
/* ===================== date utilities ===================== */
const DAY = 86400000;
const iso = d => { const x = new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
const parse = s => { if (!s) return null; if (s instanceof Date) return s; const [y,m,d] = s.split('-').map(Number); return new Date(y, m-1, d); };
const addDays = (d, n) => { const x = new Date(parse(d)); x.setDate(x.getDate()+n); return x; };
const dayDiff = (a, b) => Math.round((parse(b) - parse(a)) / DAY);
const fmt = s => { const d = parse(s); return d ? `${d.getMonth()+1}/${d.getDate()}` : '—'; };
const fmtL = s => { const d = parse(s); return d ? d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}) : '—'; };
const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const nowStamp = () => new Date().toLocaleString(undefined,{month:'numeric',day:'numeric',hour:'numeric',minute:'2-digit'});

let holidaySet = new Set();
function isWork(dateStr, weekendOk=false){ const d = parse(dateStr); if (holidaySet.has(dateStr)) return false; if (weekendOk) return d.getDay() !== 0; /* Saturday allowed, Sunday never */ return d.getDay() >= 1 && d.getDay() <= 5; }
function nextWork(dateStr, weekendOk=false){ let s = dateStr; while(!isWork(s, weekendOk)) s = iso(addDays(s,1)); return s; }
function prevWork(dateStr, weekendOk=false){ let s = dateStr; while(!isWork(s, weekendOk)) s = iso(addDays(s,-1)); return s; }
function addWork(dateStr, n, weekendOk=false){ let s = dateStr, step = n > 0 ? 1 : -1, left = Math.abs(n); while(left > 0){ s = iso(addDays(s, step)); if (isWork(s, weekendOk)) left--; } return s; }
function workdays(a, b, weekendOk=false){ if (!a||!b) return 0; if (parse(a) > parse(b)) return -workdays(b, a, weekendOk); let n=0, s=a; const end = parse(b); while(parse(s) <= end){ if (isWork(s, weekendOk)) n++; s = iso(addDays(s,1)); } return n; }
const signedWork = (from, to) => parse(to) >= parse(from) ? workdays(from, to) - 1 : -(workdays(to, from) - 1);

