  const live = c.invoices.filter(x=>x.status!=='draft'&&x.status!=='void'); const invoiced = live.reduce((a,x)=>a+docTotal(x).total,0); const retReleased = live.filter(x=>x.retainageRelease).reduce((a,x)=>a+docTotal(x).total,0); const retHeld = Math.max(0, r2(live.reduce((a,x)=>a+docTotal(x).ret,0) - retReleased));
  const paid = c.payments.filter(x=>!x.unapplied).reduce((a,x)=>a+(+x.amount||0),0); const credits = r2(c.payments.filter(x=>x.unapplied).reduce((a,x)=>a+(+x.amount||0),0)); const revised = (+c.contract||0) + approvedCO;
