  applyHolidaysFrom(tpl.project.holidays);
  tpl.tasks.forEach(t => { const d = workdays(t.start, t.end, t.weekendOk); let ns = sh(t.start); if (parse(ns) < parse(start)) ns = start; t.start = nextWork(ns, t.weekendOk); t.end = t.type==='milestone' ? t.start : addWork(t.start, Math.max(0,d-1), t.weekendOk); t.status='planned'; t.actualStart=''; t.actualEnd=''; t.notes = t.notes.replace(/\b\d{1,2}\/\d{1,2}\b/g,'').replace(/\s{2,}/g,' ').trim(); });
  tpl.materials.forEach(m => { m.status = m.status==='needs-decision' ? 'needs-decision' : 'not-ordered'; m.eta=''; m.po=''; });
