  const finish = e => { clearTimeout(longPress); svg._lp = null; svg.style.touchAction = ''; if (!drag) return; svg._suppress = true; setTimeout(() => svg._suppress = false, 300); const t = drag.t, moved = drag.moved, was = {start:drag.start, end:drag.end}; drag = null; if (!moved){ openEditor('task', t.id); return; }
    const pushed = []; if (!$('#opt-push') || $('#opt-push').checked) pushDependents(t.id, pushed);
    recordMove(t, was, 'drag'); log(`${t.name}: ${fmt(was.start)}–${fmt(was.end)} → ${fmt(t.start)}–${fmt(t.end)}${pushed.length ? `; pushed ${pushed.join(', ')}` : ''}`);
    save(); render(); toast(`${t.name}: ${fmt(t.start)} – ${fmt(t.end)}${pushed.length ? ` · pushed ${pushed.length} dependent${pushed.length>1?'s':''}` : ''}`); };
  svg.addEventListener('pointerup', finish); svg.addEventListener('pointercancel', finish);
  svg.addEventListener('click', e => { if (drag || svg._suppress) return; const el = e.target.closest('[data-edit]'); if (el){ const [k,id] = el.dataset.edit.split(':'); openEditor(k,id); return; } const bar = e.target.closest('.bar,.ms'); if (bar) openEditor('task', bar.dataset.id); });
  wrap.querySelector('.labels svg').addEventListener('click', e => { const el = e.target.closest('[data-edit]'); if (el){ const [k,id] = el.dataset.edit.split(':'); openEditor(k,id); } });
