    if (c.kind === 'action'){ if (c.op === 'add'){ const a = Object.assign({id:uid('a'), title:'Untitled', assignee:'', due:'', priority:'med', status:'todo', link:null, notes:'', source:c._meetingId?{meetingId:c._meetingId}:null, createdAt:today(), completedAt:''}, pickKeys(c, ['title','assignee','due','priority','notes','link'])); if (a.due && !isWork(a.due)) a.due = nextWork(a.due); S.actions.push(a); log(`Task for ${a.assignee||'team'}: ${a.title}${a.due?` (due ${fmt(a.due)})`:''}`, src, by); n++; } else { const a = S.actions.find(x=>x.id===c.id); if (!a) continue; if (undo) undo.push({kind:'action', id:a.id, before:JSON.parse(JSON.stringify(a))}); Object.assign(a, pickKeys(c, ['title','assignee','due','priority','status','notes'])); if (a.status==='done' && !a.completedAt) a.completedAt = today(); n++; } continue; }
