  if (c.kind === 'decision'){ const keys = ['name','owner','kind','ref','status','due','notes']; if (c.op === 'add'){ const d = Object.assign({id:uid('d'), name:'Untitled', owner:'Client', kind:'task', ref:'', status:'open', due:'', notes:''}, pickKeys(c, keys)); S.decisions.push(d); log(`Added decision: ${d.name}`, src, by); return true; } const d = S.decisions.find(x=>x.id===c.id); if (!d) return false; snap('decision', d); Object.assign(d, pickKeys(c, keys)); if (d.status==='made' && d.kind==='mat'){ const m = mat(d.ref); if (m && m.status==='needs-decision'){ snap('material', m); m.status='not-ordered'; } } log(`Decision ${d.name} → ${d.status}`, src, by); return true; }
  if (c.kind === 'inspection'){ const keys = ['name','agency','gates','after','status','date','permit','notes']; if (c.op === 'add'){ const i = Object.assign({id:uid('i'), name:'Untitled', agency:'DOB', gates:null, after:null, status:'not-scheduled', date:'', permit:'', notes:''}, pickKeys(c, keys)); S.inspections.push(i); log(`Added inspection ${i.name}`, src, by); return true; } const i = S.inspections.find(x=>x.id===c.id); if (!i) return false; snap('inspection', i); Object.assign(i, pickKeys(c, keys)); log(`Inspection ${i.name} → ${i.status}${i.date?` ${fmt(i.date)}`:''}`, src, by); return true; }
