async function writeBrief(){
  const el = $('#ai-out'); el.textContent = 'Reading the project…';
  const r = await ai(`You are the project manager's chief of staff for a residential construction job. Today is ${today()}. Using ONLY the JSON below, write a daily brief in plain text (no markdown, no asterisks; short paragraphs and simple dashes). Sections: Where we stand (projected completion vs target, critical path this week). Do today (max 6, most important first — orders, inspections to request, decisions to get from the client, calls — each with the date that makes it urgent). Watch this week. What changed since yesterday and who approved it (from recentChanges; one line each; say "nothing" if none). Chances to finish earlier (concrete; say "none yet" if none). Under 320 words.\n\n${JSON.stringify(projectJSON())}`);
  el.textContent = r.startsWith('__ERR') ? ruleBrief() : r; if (view==='dash') $('#brief').textContent = el.textContent;
}
async function writeClient(){
  const el = $('#ai-out'); el.textContent = 'Drafting…'; const tone = $('#ai-tone').value;
  const r = await ai(`Write a client update email for a residential renovation (${S.project.name}). Today is ${today()}. Tone: ${tone}. Use ONLY the JSON — it already excludes anything the client should not see. Plain text, no markdown. Include: a short progress summary; what happens over the next two weeks; decisions we need from the client, each with the date we need it by and what it holds up; any change to the completion date and why; a closing line. Under 250 words${tone.startsWith('Brief')?', or under 80 words as a text message':''}.\n\n${JSON.stringify(clientJSON())}`);
  el.textContent = r.startsWith('__ERR') ? 'The assistant can\'t be reached from this environment. Open the Decisions tab — the list with due dates is the core of the client email.' : r; $('#ai-copy').style.display = r.startsWith('__ERR') ? 'none' : '';
}
function ruleBrief(){
  const {cpm, projEnd} = computeCPM(); const att = attention(); const {out} = opportunities(); const sc = scDate(cpm, projEnd);
  const lines = [`Where we stand: substantial completion projected ${fmtL(sc)}${S.project.target ? ` against a ${fmt(S.project.target)} target` : ''}.`];
  const crit = S.tasks.filter(t => cpm[t.id].critical && t.status!=='done').slice(0,3).map(t=>`${t.name} (${fmt(t.start)}–${fmt(t.end)})`); if (crit.length) lines.push(`Critical path next: ${crit.join('; ')}.`);
  lines.push('', 'Do today:'); att.slice(0,6).forEach(a => lines.push(`- ${a.t} — ${a.act}`)); if (!att.length) lines.push('- Nothing urgent.');
  lines.push('', 'Chances to finish earlier:'); const pulls = out.filter(o=>o.kind==='pull'); (pulls.length ? pulls : [{txt:'none yet — when a predecessor finishes early it will show here.'}]).forEach(o => lines.push(`- ${o.txt}`));
  return lines.join('\n');
}


/* ===================== field issues & plan updates ===================== */
let issFilter = 'open';
function renderIssues(){
  const rows = S.issues.filter(i => issFilter==='all' || i.status==='open').map(i => { const st = issueState(i), due = issueDue(i), t = i.taskId?task(i.taskId):null; return {id:i.id, data:{i, st, due, t}, sev:st.sev, edit:'iss:'+i.id, title:st.msg, search:i.notes}; });
  const cols = [
    {key:'title', label:'Item', cls:'name', w:'34%', get:d => d.i.title},
    {key:'type', label:'Type', w:'150px', get:d => ISSUE_TYPES[d.i.type]||d.i.type},
    {key:'owner', label:'Owner', w:'150px', get:d => d.i.owner},
    {key:'task', label:'Affects', w:'24%', get:d => d.t ? `${d.t.name} · ${fmt(d.t.start)}` : '—'},
    {key:'due', label:'Due', type:'date', w:'84px'},
    {key:'status', label:'Status', type:'status', w:'100px', get:d => ({text:d.i.status, cls: d.i.status==='open' ? (d.st.sev===3?'bad':d.st.sev===2?'warn':'neutral') : d.i.status, sort:d.st.sev})},
    {key:'a', label:'', w:'110px', get:d => ({text:'', html: d.i.status==='open'?`<button class="btn sm act" data-answered="${d.i.id}">Answered</button>`:d.i.status==='answered'?`<button class="btn sm act" data-closed="${d.i.id}">Field has it</button>`:''})},
  ];
  $('#iss-table').innerHTML = grid({id:'issues', cols, rows, defaultSort:'due', empty: issFilter==='open' ? 'No open field items.' : 'No field items recorded.'});
}
/* ===================== inbox: parsing ===================== */
const CATS = {quote:'Vendor quote', decision:'Client decision', field:'Field request', plan:'Plan update / RFI', delivery:'Delivery', inspection:'Inspection / permit', schedule:'Schedule change', coordination:'Sub coordination', expense:'Expense / receipt', other:'Other'};
function parseMessages(text, fromDefault, src){
  text = text.replace(/\r/g,'').trim(); if (!text) return [];
  const wa = /^\[?(\d{1,2}\/\d{1,2}\/\d{2,4}),? (\d{1,2}:\d{2}(?::\d{2})?\s?(?:AM|PM|am|pm)?)\]?\s?[-–]?\s?([^:]{1,40}):\s([\s\S]*)$/;
  const lines = text.split('\n');
  const isWA = src==='whatsapp' || (src==='auto' && lines.filter(l => wa.test(l)).length >= 2);
  if (isWA){ const out = []; for (const l of lines){ const m = l.match(wa); if (m){ out.push({date:m[1], time:m[2], from:m[3].trim(), text:m[4].trim(), source:'whatsapp'}); } else if (out.length && l.trim()) out[out.length-1].text += '\n' + l; } return out.filter(m => m.text && !/^<Media omitted>$/i.test(m.text)); }
  const isEmail = src==='email' || (src==='auto' && /^(From|Subject|Date):/im.test(text));
  if (isEmail){ const parts = text.split(/\n(?=From:\s)/i).filter(p => p.trim()); return parts.map(p => { const g = k => (p.match(new RegExp('^'+k+':\\s*(.*)$','im'))||[])[1]||''; const body = p.replace(/^(From|To|Cc|Subject|Date|Sent):.*$/gim,'').trim(); return {date:g('Date')||g('Sent'), from:g('From')||fromDefault, subject:g('Subject'), text:body, source:'email'}; }); }
  return [{date:'', from:fromDefault||'', text, source: src==='notes' ? 'notes' : 'paste'}];
}
function addMessages(msgs){
  const now = new Date().toISOString(); let n = 0;
  for (const m of msgs){ if (!m.text || m.text.length < 3) continue; S.comms.unshift({id:uid('c'), receivedAt:now, source:m.source, from:m.from||'', subject:m.subject||'', date:m.date||'', time:m.time||'', text:m.text, category:'', confidence:0, status:'new', summary:'', proposal:null, undo:null}); n++; }
  if (n) log(`${n} message${n>1?'s':''} added to the Inbox`, 'import'); save(); render(); toast(n ? `Added ${n} message${n>1?'s':''}` : 'Nothing to add'); return n;
}
function commLabel(c){ return `${c.source==='chat'?'💬 ':c.source==='email'?'✉ ':''}${c.from ? esc(c.from) : (c.source==='notes'?'Meeting notes':'Pasted')}${c.subject?` · ${esc(c.subject)}`:''}${c.date?` · ${esc(c.date)}${c.time?' '+esc(c.time):''}`:''}${c.routeWhy?` <span class="muted">· routed by ${esc(c.routeWhy)}</span>`:''}${(c.attachments||[]).length?` · <svg class="bp-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21.4 11.05l-9.2 9.2a6 6 0 0 1-8.5-8.5l9.2-9.2a4 4 0 0 1 5.7 5.7l-9.2 9.2a2 2 0 0 1-2.8-2.8l8.5-8.5"/></svg> ${c.attachments.length}`:''}`; }
function renderInbox(){
  const list = $('#inbox-list'); if (!S.comms.length){ list.innerHTML = '<div class="empty">The Inbox is empty. Paste a text thread or forward an email on the right — the assistant will sort it into decisions, orders, field requests and schedule changes.</div>'; return; }
  const order = {new:0, proposed:1, auto:2, applied:3, ignored:4};
  list.innerHTML = [...S.comms].sort((a,b) => (order[a.status]-order[b.status]) || (b.receivedAt.localeCompare(a.receivedAt))).map(c => {
    const props = c.proposal||[]; const on = props.filter(p=>p._on!==false);
    return `<div class="msg ${c.status}" data-cid="${c.id}"><div class="top"><b>${commLabel(c)}</b>${c.category?`<span class="cat ${c.category}">${CATS[c.category]||c.category}</span>`:''}${c.confidence?`<span class="muted">${Math.round(c.confidence*100)}% sure</span>`:''}<span class="grow"></span><span class="pill ${c.status==='new'?'blue':c.status==='applied'?'green':c.status==='auto'?'amber':c.status==='proposed'?'orange':'grey'}">${c.status==='auto'?'applied automatically':c.status}</span></div>
      <div class="body ${c.text.length<300?'open':''}" data-expand>${esc(c.text)}</div>${c.text.length>=300?`<a href="#" class="small" data-expand-link>Show full message</a>`:''}
      ${c.summary?`<div class="sum">${esc(c.summary)}</div>`:''}
      ${c.status==='proposed' && props.length ? `<div style="margin:6px 0">${props.map((p,i) => `<div class="prop ${p._on===false?'off':''}"><input type="checkbox" ${p._on===false?'':'checked'} data-ptog="${c.id}:${i}"><div><div class="k">${p.op==='add'?'Add':'Update'} ${p.kind}: ${esc(propName(p))}${p.lowRisk?' <span class="pill green" style="font-weight:500">low risk</span>':''}</div><div class="diff">${esc(propDiff(p))}</div><div class="why">${esc(p.reason||'')}</div></div></div>`).join('')}</div>` : ''}
      ${c.status==='proposed' && !props.length ? `<div class="small muted">Nothing to update from this message.</div>` : ''}
      ${(c.status==='applied'||c.status==='auto') && c.appliedSummary ? `<div class="small muted">${esc(c.appliedSummary)}</div>` : ''}
      <div class="acts">${c.status==='new'?`<button class="btn sm primary" data-review="${c.id}">Review</button>`:''}${c.status==='proposed'&&props.length?`<button class="btn sm primary" data-applymsg="${c.id}">Apply ${on.length} change${on.length===1?'':'s'}</button>`:''}${c.status==='auto'?`<button class="btn sm" data-undo="${c.id}">Undo</button><button class="btn sm" data-ack="${c.id}">Looks right</button>`:''}${c.status!=='ignored'&&c.status!=='applied'&&c.status!=='auto'?`<button class="btn sm" data-ignore="${c.id}">Ignore</button>`:''}<button class="btn sm ghost" data-delmsg="${c.id}">Delete</button></div></div>`; }).join('');
}
function propName(c){ if (c.kind==='request') return `${c.qty||1} ${c.unit||'ea'} ${c.what||''}`; if (c.kind==='po'){ const po = DB.pos.find(p=>p.id===c.id); return po ? `${po.number} ${po.vendor}` : (c.vendor||'new PO'); } if (c.kind==='permit'){ return S.permits.find(p=>p.id===c.id)?.name||c.name||''; } if (c.kind==='transaction') return c.desc||c.vendor||'transaction'; if (c.kind==='action') return c.title||''; return c.kind==='task' ? (task(c.id)?.name||c.name||'') : c.kind==='material' ? (mat(c.id)?.name||c.name||'') : c.kind==='decision' ? (S.decisions.find(x=>x.id===c.id)?.name||c.name||'') : c.kind==='issue' ? (S.issues.find(x=>x.id===c.id)?.title||c.title||'') : (S.inspections.find(x=>x.id===c.id)?.name||c.name||''); }
function propDiff(c){ if (c.kind==='request') return `needed ${c.neededBy?fmt(c.neededBy):'soon'}${c.urgency==='urgent'?' · URGENT':''}`; if (c.kind==='po' && c._receive){ const po = DB.pos.find(p=>p.id===c.id); return (c.lines||[]).map(l => { const pl = po?.lines.find(x=>x.id===l.id); return `${pl?pl.item:(l.item||'line')}: received ${l.received}${pl?` of ${pl.qty} ${pl.unit}`:''}`; }).join(' · ') || 'receive'; } if (c.kind==='po' && c.op==='add') return `${(c.lines||[]).length} line${(c.lines||[]).length===1?'':'s'} · ${money((c.lines||[]).reduce((a,l)=>a+(+l.qty||0)*(+l.price||0),0))}`; if (c.kind==='transaction') return `${c.date||''} ${money(c.amt||0)} · ${catName(c.cat||'')}`; if (c.kind==='permit'){ const p = S.permits.find(x=>x.id===c.id); return ['number','expires','issued','status'].filter(k=>c[k]!=null).map(k=>`${k}: ${p?(p[k]||'—'):'—'} → ${c[k]}`).join(' · '); } const cur = c.kind==='task' ? task(c.id) : c.kind==='material' ? mat(c.id) : c.kind==='decision' ? S.decisions.find(x=>x.id===c.id) : c.kind==='issue' ? S.issues.find(x=>x.id===c.id) : S.inspections.find(x=>x.id===c.id); const skip = ['kind','op','reason','_i','_on','id','lowRisk','_commId']; const f = v => Array.isArray(v)?v.join(', '):(v??'—'); if (c.op==='add') return Object.entries(c).filter(([k]) => !skip.includes(k)).map(([k,v]) => `${k}: ${f(v)}`).join(' · '); if (!cur) return 'Item not found — will be skipped'; return Object.entries(c).filter(([k]) => !skip.includes(k) && f(cur[k]) !== f(c[k])).map(([k,v]) => `${k}: ${f(cur[k])} → ${f(v)}`).join(' · ') || 'No change'; }
const LOW_RISK_OK = c => c.op==='update' && ((c.kind==='material' && Object.keys(c).every(k => ['kind','op','id','reason','lowRisk','_commId','eta','status','vendor','po','cost','lead','qty'].includes(k)) && (!c.status || ['ordered','shipped','on-site','quoted'].includes(c.status))) || (c.kind==='inspection' && Object.keys(c).every(k => ['kind','op','id','reason','lowRisk','_commId','date','status','permit'].includes(k))) || (c.kind==='decision' && c.status==='made'));

async function reviewMessages(ids){
  const msgs = ids.map(id => S.comms.find(c=>c.id===id)).filter(Boolean); if (!msgs.length) return;
  msgs.forEach(m => { m.status='reviewing'; }); renderInbox(); toast(`Reading ${msgs.length} message${msgs.length>1?'s':''}…`);
  const prompt = `You are the project coordinator's assistant on a residential design-build job. Today is ${today()}. Below is the project as JSON (ids are stable — always use them), then a batch of messages (texts, WhatsApp, emails, notes) about this project.
For EACH message: classify it, summarize it in one sentence, and extract concrete updates to the project.
Categories: quote (vendor pricing/lead time), decision (client or designer selection/approval), field (crew asking for materials, tools, or help), plan (plan inconsistency, RFI, or a plan revision from architect/engineer/designer), delivery (material arrived or shipping update), inspection (permit/inspection scheduling or results), schedule (dates changing, task started/finished), coordination (sub scheduling), expense (a receipt, a purchase, or a payment made for the job), other.
Changes use these kinds/fields: "task" (name, start, end, status[planned|in-progress|done], owner, deps, notes), "material" (name, taskId, status[${MAT_STATUS.join('|')}], lead, eta, vendor, po, qty, cost, notes), "decision" (name, owner[${DEC_OWNERS.join('|')}], kind[mat|task], ref, status[open|made]), "inspection" (name, agency[DOB|LPC|Special|Other], gates, after, status[not-scheduled|scheduled|passed|failed], date), "issue" (title, type[rfi|plan-update|field-request|coordination], owner, taskId, due, status[open|answered|closed], notes), "transaction" (op add only: date, desc, amt negative for spend, vendor, cat[materials|subs|labor|equipment|disposal|permits|design], code[01-14]) for receipts and purchases mentioned in messages, "po" (op add only: vendor, expected, notes, lines:[{item, desc, qty, unit, price, line}]) when a vendor invoice, quote acceptance or order confirmation lists items and prices, "action" (op add: title, assignee, due, priority[high|med|low], notes) for a to-do someone commits to, "request" (op add: what, qty, unit, neededBy, taskId, urgency[normal|urgent], note) when the field asks for material, tools or a dumpster.
Rules: op is "update" (id + only changed fields) or "add" (all needed fields). Prefer updating an existing item over adding a duplicate — match by meaning (a text about "tile for the master bath" is material m8 if that exists). A vendor quote updates the material's vendor, cost, lead and sets status "quoted". "X delivered/arrived" sets status "on-site". A field request for materials not in the list is an "add material" tied to the task needing it. A plan question or revision is an "issue". Do not move dependents — the software does that. Mark "lowRisk": true only for: material eta/status/vendor/cost/lead updates, inspection date/status updates, decision status made. Everything that changes a task date, adds a task, or adds scope is lowRisk:false. confidence is 0–1: how sure you are the message is about this project and you read it right.
Keep the reply under 900 tokens (short summaries and reasons). Reply ONLY with JSON: {"messages":[{"id":"<message id>","category":"quote","confidence":0.9,"summary":"...","changes":[{"kind":"material","op":"update","id":"m8","status":"quoted","cost":"4,250","lead":10,"vendor":"Nemo Tile","lowRisk":true,"reason":"..."}]}]}

PROJECT:
${JSON.stringify(projectJSON())}

MESSAGES:
${JSON.stringify(msgs.map(m => ({id:m.id, from:m.from, date:m.date, subject:m.subject, source:m.source, text:m.text.slice(0,6000)})))}`;
  const r = await ai(prompt, 4000);
  if (r.startsWith('__ERR')){ msgs.forEach(m => m.status='new'); render(); toast('Assistant unavailable here — messages kept as new'); $('#inbox-list').insertAdjacentHTML('afterbegin', `<div class="note warn" style="margin-bottom:10px">The assistant can't be reached from this environment (${esc(r.slice(6))}). Messages stay in the Inbox; you can still act on them by hand.</div>`); return; }
  const j = safeJSON(r); if (!j){ msgs.forEach(m => m.status='new'); render(); toast('Could not read the assistant reply'); return; }
  let autoN = 0;
  for (const m of msgs){
    const res = (j.messages||[]).find(x => x.id === m.id); if (!res){ m.status='new'; continue; }
    m.category = res.category||'other'; m.confidence = +res.confidence||0; m.summary = res.summary||''; m.proposal = (res.changes||[]).map(c => Object.assign({_on:true, _commId:m.id}, c));
    m.status = 'proposed';
    if (S.project.auto === 'low' && m.confidence >= 0.8 && m.proposal.length && m.proposal.every(c => c.lowRisk && LOW_RISK_OK(c))){
      const undo = []; const res2 = applyChanges(m.proposal, 'auto', 'assistant', undo); m.undo = undo; m.status = 'auto'; m.appliedSummary = `${res2.n} update${res2.n===1?'':'s'} applied automatically (${Math.round(m.confidence*100)}% confidence). Review and undo if wrong.`; autoN += res2.n;
    }
  }
  save(); render(); toast(autoN ? `Reviewed ${msgs.length} — ${autoN} low-risk update${autoN>1?'s':''} applied automatically` : `Reviewed ${msgs.length} message${msgs.length>1?'s':''}`);
}
const isScheduleChange = c => c.kind==='task' && (c.op==='add' || c.start || c.end || c.deps);
function applyMessage(id){
  const m = S.comms.find(c=>c.id===id); if (!m || !m.proposal) return; let on = m.proposal.filter(p=>p._on!==false);
  if (!canApproveSchedule()){ const held = on.filter(isScheduleChange); if (held.length){ on = on.filter(c => !isScheduleChange(c)); held.forEach(c => c._on = false); toast(`${held.length} schedule change${held.length>1?'s':''} left for the PM to approve`); } }
  const res = applyChanges(on, 'assistant'); m.status = 'applied'; m.appliedSummary = `${res.n} change${res.n===1?'':'s'} applied${res.pushed.length?`; pushed ${res.pushed.length} dependent${res.pushed.length>1?'s':''}`:''}${S.project.userName?` · approved by ${S.project.userName}`:''}.`;
  save(); render(); toast(`Applied ${res.n} change${res.n===1?'':'s'}`);
}
function undoMessage(id){
  const m = S.comms.find(c=>c.id===id); if (!m || !m.undo) return;
  for (const u of m.undo.reverse()){ const coll = u.kind==='task'?S.tasks:u.kind==='material'?S.materials:u.kind==='decision'?S.decisions:u.kind==='issue'?S.issues:S.inspections; const i = coll.findIndex(x=>x.id===u.id); if (i>=0) coll[i] = u.before; }
  m.undo = null; m.status = 'proposed'; log(`Undid automatic updates from message (${m.from||m.source})`); save(); render(); toast('Undone — the proposal is back for review');
}

/* ===================== CSV import for materials ===================== */
function parseCSV(text){
  const rows = []; let row = [], cur = '', q = false; text = text.replace(/\r/g,'');
  for (let i=0;i<text.length;i++){ const ch = text[i]; if (q){ if (ch==='"'){ if (text[i+1]==='"'){ cur+='"'; i++; } else q=false; } else cur+=ch; } else { if (ch==='"' && cur==='') q=true; else if (ch===','||ch==='\t'){ row.push(cur); cur=''; } else if (ch==='\n'){ row.push(cur); rows.push(row); row=[]; cur=''; } else cur+=ch; } }
  if (cur.length || row.length){ row.push(cur); rows.push(row); }
  return rows.filter(r => r.some(c => c.trim()));
}
const MAT_FIELDS = {name:'Material name', cat:'Category (rough/finish)', taskName:'For task (name)', when:'Needed at (start/end)', lead:'Lead time (working days)', status:'Status', eta:'ETA', vendor:'Vendor', po:'PO #', qty:'Quantity', cost:'Cost', deliverTo:'Deliver to', notes:'Notes', skip:'— skip —'};
const GUESS = {name:/^(material|item|product|description|name|finish)/i, cat:/^(cat|type|rough|phase)/i, taskName:/^(task|for|phase|location|room|area|install)/i, when:/^(when|needed at)/i, lead:/^(lead|lead ?time|weeks|days)/i, status:/^(status|state)/i, eta:/^(eta|deliver|arrival|due)/i, vendor:/^(vendor|supplier|source|manufacturer|mfr)/i, po:/^(po|purchase)/i, qty:/^(qty|quant|amount|sf|lf|count)/i, cost:/^(cost|price|total|budget)/i, deliverTo:/^(deliver ?to|ship ?to)/i, notes:/^(note|comment|remark|spec)/i};
function matchTask(name){ if (!name) return ''; const n = name.toLowerCase(); let best = null, score = 0; for (const t of S.tasks){ const tn = t.name.toLowerCase(); if (tn === n) return t.id; const toks = n.split(/[^a-z0-9]+/).filter(x=>x.length>2); const hit = toks.filter(x => tn.includes(x)).length; const sc = hit / Math.max(1, toks.length) + (tn.includes(n)||n.includes(tn) ? 1 : 0); if (sc > score){ score = sc; best = t.id; } } return score >= 0.5 ? best : ''; }
function importMaterialsDialog(){
  editing = {kind:'matimport'}; $('#scrim').classList.add('on'); $('#drawer').classList.add('on'); $('#ai').classList.remove('on');
  $('#d-title').textContent = 'Import materials from CSV'; $('#d-delete').style.display = 'none'; $('#d-save').textContent = 'Import'; $('#d-save').disabled = true;
  $('#d-body').innerHTML = `<p class="small" style="margin:0 0 10px;color:var(--ink-2)">Upload the finish schedule or procurement list. Columns are matched to fields automatically; adjust the mapping, check the preview, import. Rows whose task can't be matched are imported unlinked so you can assign them.</p>
    <div class="row" style="margin-bottom:12px"><label class="btn primary">Choose CSV<input type="file" id="ci-file" accept=".csv,.tsv,.txt" hidden></label><span class="small muted" id="ci-status"></span></div>
    <div id="ci-map"></div>`;
  let rows = null, headers = null, mapping = {};
  $('#ci-file').addEventListener('change', async e => { const f = e.target.files[0]; if (!f) return; rows = parseCSV(await f.text()); if (rows.length < 2){ $('#ci-status').textContent = 'Need a header row and at least one data row.'; return; } headers = rows[0].map(h => h.trim()); rows = rows.slice(1);
    mapping = {}; headers.forEach((h,i) => { const k = Object.keys(GUESS).find(k => GUESS[k].test(h) && !Object.values(mapping).includes(k)); mapping[i] = k || 'skip'; }); if (!Object.values(mapping).includes('name')){ const i = headers.findIndex((h,i) => mapping[i]==='skip'); if (i>=0) mapping[i]='name'; }
    $('#ci-status').textContent = `${rows.length} rows · ${headers.length} columns`; drawMap(); });
  const drawMap = () => { const linked = rows.filter(r => { const ti = Object.keys(mapping).find(k=>mapping[k]==='taskName'); return ti!==undefined && matchTask(r[ti]); }).length;
    $('#ci-map').innerHTML = `<div class="f"><label>Column mapping</label><div class="map">${headers.map((h,i) => `<div><b>${esc(h)}</b><div class="small muted">e.g. ${esc((rows[0][i]||'').slice(0,28))}</div></div><select data-col="${i}">${Object.entries(MAT_FIELDS).map(([k,v]) => `<option value="${k}" ${mapping[i]===k?'selected':''}>${v}</option>`).join('')}</select>`).join('')}</div></div>
      <div class="f"><label>Default category for rows without one</label><select id="ci-cat"><option value="finish">Finish</option><option value="rough">Rough</option></select></div>
      <div class="f"><label>Default lead time when blank (working days)</label><input type="number" id="ci-lead" value="10"></div>
      <label class="chk" style="margin-bottom:10px"><input type="checkbox" id="ci-update" checked> Update existing materials with the same name instead of adding duplicates</label>
      <div class="note">${rows.length} rows · ${linked} matched to a task by name${Object.values(mapping).includes('taskName')?'':' (no task column mapped — all rows import unlinked)'}.</div>
      <div class="prev" style="margin-top:10px"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr>${headers.map((_,i)=>`<td>${esc((r[i]||'').slice(0,30))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
    $('#ci-map').querySelectorAll('select[data-col]').forEach(sel => sel.addEventListener('change', e => { mapping[+e.target.dataset.col] = e.target.value; drawMap(); })); $('#d-save').disabled = !Object.values(mapping).includes('name'); };
  $('#d-save').onclick = () => { if (!rows) return; const col = k => Object.keys(mapping).find(x=>mapping[x]===k); const get = (r,k) => { const c = col(k); return c===undefined ? '' : (r[c]||'').trim(); }; const upd = $('#ci-update').checked; const defCat = $('#ci-cat').value, defLead = +$('#ci-lead').value||0; let added=0, updated=0, unlinked=0;
    for (const r of rows){ const name = get(r,'name'); if (!name) continue; const taskId = matchTask(get(r,'taskName')); if (!taskId) unlinked++; const st = (get(r,'status')||'').toLowerCase().replace(/\s+/g,'-'); const lead = parseInt(get(r,'lead')); const leadWd = isNaN(lead) ? defLead : (/week/i.test(headers[col('lead')]||'') ? lead*5 : lead);
      const rec = {name, cat: /rough/i.test(get(r,'cat')) ? 'rough' : /finish/i.test(get(r,'cat')) ? 'finish' : defCat, taskId, when: /end/i.test(get(r,'when')) ? 'end' : 'start', lead: leadWd, status: MAT_STATUS.includes(st) ? st : (/site|deliver|received/.test(st) ? 'on-site' : /order/.test(st) ? 'ordered' : /quot/.test(st) ? 'quoted' : /ship/.test(st) ? 'shipped' : /select|decid|tbd|pending/.test(st) ? 'needs-decision' : 'not-ordered'), eta: normDate(get(r,'eta')), vendor:get(r,'vendor'), po:get(r,'po'), qty:get(r,'qty'), cost:get(r,'cost').replace(/[$]/g,''), deliverTo:get(r,'deliverTo')||'Site', notes:get(r,'notes')};
      const ex = upd ? S.materials.find(m => m.name.toLowerCase() === name.toLowerCase()) : null; if (ex){ Object.keys(rec).forEach(k => { if (rec[k] !== '' && !(k==='taskId' && !rec[k])) ex[k] = rec[k]; }); updated++; } else { S.materials.push(Object.assign({id:uid('m')}, rec)); added++; } }
    log(`Imported materials from CSV: ${added} added, ${updated} updated${unlinked?`, ${unlinked} not matched to a task`:''}`, 'import'); closeEditor(); $('#d-save').textContent='Save'; $('#d-save').disabled=false; $('#d-save').onclick = saveEditor; matFilter='all'; save(); setView('mat'); toast(`Imported ${added+updated} materials${unlinked?` · ${unlinked} need a task`:''}`); };
}
function normDate(v){ if (!v) return ''; if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v; const m = v.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/); if (m){ let y = m[3] ? +m[3] : new Date().getFullYear(); if (y < 100) y += 2000; return `${y}-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`; } const d = new Date(v); return isNaN(d) ? '' : iso(d); }

/* ===================== field item editor ===================== */
function openIssueEditor(id){
  editing = {kind:'iss', id}; $('#scrim').classList.add('on'); $('#drawer').classList.add('on'); $('#ai').classList.remove('on');
  const it = id ? S.issues.find(x=>x.id===id) : {title:'', type:'rfi', status:'open', owner:'Architect / designer', taskId:'', due:'', notes:'', commId:''};
  $('#d-title').textContent = id ? 'Edit field item' : 'New field item'; $('#d-delete').style.display = id ? '' : 'none';
  $('#d-body').innerHTML = `
    <div class="f"><label>What's the question, request or change?</label><input id="e-name" value="${esc(it.title)}"></div>
    <div class="f2"><div class="f"><label>Type</label><select id="e-type">${Object.entries(ISSUE_TYPES).map(([k,v]) => `<option value="${k}" ${it.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="f"><label>Who owes the answer</label><select id="e-owner">${[...DEC_OWNERS,'Crew / foreman','Subcontractor'].map(o => `<option ${it.owner===o?'selected':''}>${o}</option>`).join('')}</select></div></div>
    <div class="f"><label>Affects task</label><select id="e-task"><option value="">— none —</option>${S.tasks.map(t => `<option value="${t.id}" ${it.taskId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><span class="hint">Due = task start − ${S.project.decBuf} working days unless you set a date.</span></div>
    <div class="f2"><div class="f"><label>Due (override)</label><input type="date" id="e-due" value="${it.due||''}"></div><div class="f"><label>Status</label><select id="e-status"><option value="open" ${it.status==='open'?'selected':''}>Open</option><option value="answered" ${it.status==='answered'?'selected':''}>Answered</option><option value="closed" ${it.status==='closed'?'selected':''}>Closed — field has it</option></select></div></div>
    <div class="f"><label>Notes / answer</label><textarea id="e-notes">${esc(it.notes)}</textarea></div>
    ${id ? `<div class="note">${esc(issueState(it).msg)}</div>` : ''}`;
  editing.collect = () => ({id: id||uid('is'), title:$('#e-name').value.trim()||'Untitled', type:$('#e-type').value, owner:$('#e-owner').value, taskId:$('#e-task').value, due:$('#e-due').value, status:$('#e-status').value, notes:$('#e-notes').value, commId:it.commId||''});
  setTimeout(() => $('#e-name').focus(), 50);
}


/* ===================== client view ===================== */
function renderClient(cpm, projEnd){
  const td = today(); const cl0 = clientOf(); const sibs = cl0 ? DB.projects.filter(p=>p.clientId===cl0.id) : [S];
  const shc = siteHours(); $('#cl-switch').innerHTML = (sibs.length > 1 ? `<span class="small muted">Your projects:</span><div class="seg">${sibs.map(p => `<button class="${p.id===S.id?'on':''}" data-open="${p.id}">${esc(p.project.name)}</button>`).join('')}</div>` : `<h2 style="margin:0">${esc(S.project.name)}</h2><span class="small muted">${esc(S.project.addr||'')}</span>`) + `<span class="small muted" style="margin-left:auto">Work hours on site: ${shc.days.map(d=>DOW[d]).join(' ')} ${shc.start}–${shc.end}</span>`; const sc = scDate(cpm, projEnd); const done = S.tasks.filter(t=>t.status==='done').length; const pct = S.tasks.length ? Math.round(done/S.tasks.length*100) : 0;
  const decs = S.decisions.filter(d => d.owner==='Client' && d.status==='open').map(d => ({d, due:decDue(d), st:decState(d)})).sort((a,b)=>(parse(a.due)||0)-(parse(b.due)||0));
  $('#cl-kpis').innerHTML = `<div class="kpi good"><b>${pct}%</b><span>of the work complete</span></div><div class="kpi blue"><b>${fmtL(sc)}</b><span>expected substantial completion</span></div><div class="kpi ${decs.some(x=>x.st.sev>=2)?'warn':''}"><b>${decs.length}</b><span>decision${decs.length===1?'':'s'} we need from you</span></div><div class="kpi"><b>${S.tasks.filter(t=>t.status==='in-progress').length}</b><span>activities underway this week</span></div>`;
  $('#cl-decs').innerHTML = decs.length ? decs.map(({d,due,st}) => `<div class="attn-item sev${Math.min(2,st.sev)}" style="margin-bottom:8px"><div class="when">${fmt(due)}</div><div><div class="t">${esc(d.name)}</div><div class="why">${d.kind==='mat' ? `Needed so we can order: ${esc(mat(d.ref)?.name||'')}` : `Needed before: ${esc(task(d.ref)?.name||'')}`}</div>${d.notes?`<div class="why">${esc(d.notes)}</div>`:''}</div><div><span class="pill ${st.sev>=2?'orange':'blue'}">${st.sev>=2?'Needed now':'Upcoming'}</span></div></div>`).join('') : '<div class="muted small">Nothing outstanding — thank you.</div>';
  const up = S.tasks.filter(t => t.status!=='done' && parse(t.end) >= parse(td)).sort((a,b)=>parse(a.start)-parse(b.start)).slice(0,8);
  $('#cl-next').innerHTML = up.map(t => `<div class="chg"><span>${fmt(t.start)}–${fmt(t.end)}</span>${esc(t.name)}${t.type==='milestone'?' <span class="pill blue">milestone</span>':''}</div>`).join('') || '<div class="muted">Schedule coming soon.</div>';
  const cl = clientOf(); if (cl){ const f = clientFin(cl); $('#cl-account').innerHTML = `<div class="fin" style="grid-template-columns:1fr 1fr;margin-bottom:8px"><div><span class="muted">Contract incl. approved changes</span><br><b>${money(f.revised)}</b></div><div><span class="muted">Paid to date</span><br><b>${money(f.paid)}</b></div></div>${f.open.length ? `<div style="margin-top:6px"><b>Open invoices</b>${f.open.map(o => `<div class="chg"><span>${o.x.number}</span>${esc(o.x.desc||'')} — ${money(o.bal)} due ${fmt(o.x.due)}${o.age>0?` <span class="age late">${o.age}d overdue</span>`:''}</div>`).join('')}</div>` : '<div class="muted">No open invoices.</div>'}${cl.changeOrders.filter(x=>x.status==='sent').length ? `<div style="margin-top:8px"><b>Change orders awaiting your signature</b>${cl.changeOrders.filter(x=>x.status==='sent').map(x => `<div class="chg"><span>${esc(x.number)}</span>${esc(x.title)} — ${money(docTotal(x).total)}</div>`).join('')}</div>` : ''}`; } else $('#cl-account').innerHTML = '<div class="muted">Account details will appear here.</div>';
  const shared = S.files.filter(f => f.shareClient); if (shared.length) $('#cl-account').insertAdjacentHTML('beforeend', `<div style="margin-top:10px"><b>Shared documents</b>${shared.map(f => `<div class="chg"><span>${fmt(f.date)}</span><a href="#" data-go="file:${f.id}">${esc(f.name)}</a></div>`).join('')}</div>`);
  const dn = S.tasks.filter(t => t.status==='done').sort((a,b)=>parse(b.actualEnd||b.end)-parse(a.actualEnd||a.end)).slice(0,8);
  $('#cl-done').innerHTML = dn.map(t => `<div class="chg"><span>${fmt(t.actualEnd||t.end)}</span>${esc(t.name)}</div>`).join('') || '<div class="muted">Work is just getting started.</div>';
}
function clientJSON(){ // what the client is allowed to see — no costs, vendors, crew names, internal notes, comms
  const {cpm, projEnd} = computeCPM();
  return { today: today(), project: S.project.name, target: S.project.target, projectedCompletion: scDate(cpm, projEnd),
    tasks: S.tasks.map(t => ({name:t.name, start:t.start, end:t.end, status:t.status, type:t.type})),
    decisionsNeededFromClient: S.decisions.filter(d => d.owner==='Client' && d.status==='open').map(d => ({name:d.name, due:decDue(d), holdsUp: d.kind==='mat' ? (mat(d.ref)?.name||'') : (task(d.ref)?.name||'')})),
    milestones: S.tasks.filter(t=>t.type==='milestone').map(t => ({name:t.name, date:t.start})),
    recentlyCompleted: S.tasks.filter(t=>t.status==='done').map(t => ({name:t.name, finished:t.actualEnd||t.end})),
    account: (() => { const c = clientOf(); if (!c) return undefined; const f = clientFin(c); return {openInvoices: f.open.map(o => ({number:o.x.number, amount:o.bal, due:o.x.due, overdueDays:Math.max(0,o.age)})), changeOrdersAwaitingSignature: c.changeOrders.filter(x=>x.status==='sent').map(x => ({number:x.number, title:x.title, amount:docTotal(x).total}))}; })() };
}
function crewJSON(){ const j = projectJSON(); delete j.attention; j.materials = j.materials.map(m => ({name:m.name, taskId:m.taskId, status:m.status, needBy:m.needBy, eta:m.eta})); j.decisions = undefined; j.recentChanges = undefined; return j; }
