  if (a==='send'){ if (!d.lines.length || !docTotal(d).total){ if (!confirm('This document has no amount. Send anyway?')) return; } d.status = 'sent'; docMark(d); if (k==='invoice' && !d.due) d.due = iso(addDays(d.date, 15)); act(`${d.number} sent — ${money(docTotal(d).total)}`); toast(`${d.number} marked sent`); }
