  if (a==='expire'){ d.status = 'expired'; }
  if (a==='convert' || a==='approveconvert'){ const t = docTotal(d); if (a==='convert' && !confirm(`Convert ${d.number}: set the base contract to ${money(t.total)} and build the schedule of values from its ${d.lines.length} lines?${c.contract?' This replaces the current contract and SOV base.':''}`)) return; c.contract = t.total; c.contractNet = r2(t.sub - t.disc); c.contractDate = today(); c.sov = c.sov.filter(v => v.source!=='Contract'); if (d.template==='construction') ctNumber(d); d.lines.slice().reverse().forEach((l,i) => c.sov.unshift({id:uid('sv'), taxable:!!l.taxable, desc:(l.num?l.num+'. ':'')+(l.item||l.desc), scheduled:r2(lineAmount(l,d) * (t.sub ? (t.sub - t.disc + t.tax)/t.sub : 1)), source:'Contract', order:i, lineRef:`estimate:${d.id}:${l.id}`})); c.sov.forEach((v,i)=>v.order=i); d.status = 'converted'; act(`${d.number} converted — contract ${money(t.total)}, ${d.lines.length} SOV lines`); docMark(d);
    if (!d.projectId && confirm('Create a project for this contract now?')){ const p = projectFromTemplate(d.title||c.name, c.propertyAddr||'', nextWork(today()), ''); p.clientId = c.id; DB.projects.push(p); d.projectId = p.id; } toast('Contract and schedule of values set'); }
  if (a==='revise'){ const n = newDoc(c, 'estimate', {fields:{title:d.title, projectId:d.projectId, memo:d.memo, terms:d.terms, taxRate:d.taxRate, discount:{...d.discount}, lines:d.lines.map(l=>({...l, id:uid('l')})), revisionOf:d.number}}); docOpen = {kind:'estimate', id:n.id}; toast(`Revision ${n.number} created`); }
  if (a==='dup'){ const n = newDoc(c, k, {mode:d.mode, fields:{title:d.title, projectId:d.projectId, memo:d.memo, terms:d.terms, taxRate:d.taxRate, retainagePct:d.retainagePct, discount:{...d.discount}, lines: d.mode==='sov' ? undefined : d.lines.map(l=>({...l, id:uid('l')}))}}); docOpen = {kind:k, id:n.id}; toast(`${n.number} created`); }
  if (a==='void'){ const pays = c.payments.filter(py => py.invoiceId===d.id && !py.unapplied); const reason = prompt(`Void ${d.number}?${pays.length?` ${pays.length} payment${pays.length>1?'s':''} (${money(pays.reduce((a,py)=>a+(+py.amount||0),0))}) will become unapplied credit on the account.`:''} Reason:`); if (reason===null) return; if (!reason.trim()){ toast('A reason is required to void'); return; } docAudit(c, d, 'void', reason); pays.forEach(py => { py.unapplied = true; py.voidedInvoice = d.number; }); d.status = 'void'; d.voidReason = reason; act(`${d.number} voided — ${reason}${pays.length?` · ${pays.length} payment(s) now unapplied credit`:''}`); }
