/* ===================== job costing ===================== */
function jobCost(p){ const J = jobFin(p);
  const rows = J.byCode.filter(r => r.budget || r.committed || r.actual).map(r => ({...r, remaining:r2(r.budget - r.actual), pct: r.budget ? Math.min(999, Math.round(r.actual/r.budget*100)) : (r.actual?100:0)}));
  const tot = {budget:J.budget, committed:J.committed, actual:J.actual};
  return {J, rows, tot, contract:J.contract, billed:J.billed, collected:J.collected, pctComplete:J.pct, earned:J.earned, overUnder:J.overUnder, margin:J.plannedGP, marginPct: J.contract ? J.plannedGP/J.contract : 0, eac:J.eac, estGP:J.estGP, accrued:J.accrued, unassigned: DB.txns.filter(t => isJobCat(t.cat) && !t.projectId).length};
}
