    <div class="f2"><div class="f"><label>Payment method</label><select id="e-method" ${ro?'disabled':''}>${['ACH','Check','Card','Wire','Zelle'].map(m=>`<option ${b.payMethod===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="f"><label>Invoice document</label><select id="e-file"><option value="">— attach from Documents —</option>${S.files.filter(f=>['receipt','other','ticket'].includes(f.cat)).map(f=>`<option value="${f.id}" ${b.fileId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div></div>
