function renderBillLinesInline(b){ const tb = document.querySelector('#d-body table.lines tbody'); if (!tb) return; const l = b.lines[b.lines.length-1]; tb.insertAdjacentHTML('beforeend', `<tr data-bl="${l.id}"><td><input data-f="desc" value=""></td><td><input class="num" type="number" step="0.01" data-f="amount" value="0"></td><td><span class="rm" data-rmbl="${l.id}">✕</span></td></tr>`); tb.lastElementChild.querySelector('[data-rmbl]').addEventListener('click', e => e.target.closest('tr').remove()); }
function saveBill(){
  const o = editing.collect(); const id = editing.id; if (!o.vendor){ toast('Vendor is required'); return; }
  if (id){ const b = DB.bills.find(x=>x.id===id); if (['draft','submitted'].includes(b.status)){ const before = JSON.parse(JSON.stringify(b)); Object.assign(b, o); audit('bill', b.id, 'edited', before, b); } else { b.notes = o.notes; b.fileId = o.fileId; } }
  else { const b = Object.assign({id:uid('bill'), status:'draft', approvals:[], createdBy:S.project.userName||'', createdAt:new Date().toISOString()}, o); DB.bills.push(b); audit('bill', b.id, 'created', null, b); log(`Bill entered: ${b.vendor} ${b.number||''} ${money(billTotal(b))}`); }
  closeEditor(); save(); render();
}
function billAction(b, a){
  const by = S.project.userName || role(); const stamp = {t:nowStamp(), ts:new Date().toISOString(), by, role:role()};
  if (a==='submit'){ Object.assign(b, editing.collect()); if (!billTotal(b)){ toast('Add at least one line with an amount'); return; } b.status = needsOwner(billTotal(b)) ? 'submitted' : 'submitted'; b.approvals.push({...stamp, action:'submitted'}); audit('bill', b.id, 'submitted', null, {status:b.status}); }
  if (a==='pmok'){ if (b.createdBy && b.createdBy.toLowerCase()===by.toLowerCase() && !isOwner()){ toast('Separation of duties: the person who entered the bill cannot approve it'); return; } b.status = needsOwner(billTotal(b)) ? 'pm-approved' : 'approved'; b.approvals.push({...stamp, action: b.status==='approved' ? 'approved (PM, under Owner threshold)' : 'recommended by PM'}); audit('bill', b.id, a, null, {status:b.status}); }
  if (a==='approve'){ const vb = DB.vendors.find(x=>x.name.toLowerCase()===b.vendor.toLowerCase()); if (vb?.bankPending){ toast('This vendor has a bank change awaiting your verification — resolve it under Vendors first'); return; } if (!canApprove(b)){ toast(isOwner() ? 'Separation of duties: you entered this bill; a second person must approve it' : 'Only the Owner can approve payments'); return; } const fl = billFlags(b); if (fl.length && !confirm(`This bill has control flags:\n\n${fl.join('\n')}\n\nApprove anyway?`)) return; b.status = 'approved'; b.approvedAt = today(); b.approvals.push({...stamp, action:'approved for payment by Owner', note: fl.length ? `override: ${fl.join('; ')}` : ''}); audit('bill', b.id, 'approved', null, {status:'approved', flags:fl}); log(`Bill approved: ${b.vendor} ${money(billTotal(b))}`); }
  if (a==='reject'){ const why = prompt('Reason for rejection'); if (why===null) return; b.status = 'rejected'; b.approvals.push({...stamp, action:'rejected', note:why}); audit('bill', b.id, 'rejected', null, {note:why}); }
  if (a==='paid'){ b.status = 'paid'; b.paidAt = today(); b.approvals.push({...stamp, action:`payment released (${b.payMethod})`}); audit('bill', b.id, 'paid', null, {paidAt:b.paidAt}); log(`Payment released: ${b.vendor} ${money(billTotal(b))} (${b.payMethod})`); }
  if (a==='void'){ if (!confirm('Void this bill?')) return; b.status = 'void'; b.approvals.push({...stamp, action:'voided'}); audit('bill', b.id, 'void'); }
  if (a==='clear'){ b.status = b.paidAt ? 'verified' : 'approved'; b.approvals.push({...stamp, action:'exception cleared by Owner'}); audit('bill', b.id, 'exception-cleared'); }
  closeEditor(); save(); render(); toast(`${b.vendor}: ${billState(b).text}`);
}
// ---- payroll runs ----
