  editing = {kind:'payroll', id}; $('#scrim').classList.add('on'); $('#drawer').classList.add('on'); $('#ai').classList.remove('on'); $('#d-title').textContent = id ? `Payroll · ${r.period}` : 'New payroll run'; $('#d-delete').style.display = (id && r.status==='draft') ? '' : 'none';
