function notify(title, body){ try { if ('Notification' in window && Notification.permission==='granted') new Notification(title, {body}); } catch(e){} toast(title); }
function askNotify(){ try { if ('Notification' in window && Notification.permission==='default') Notification.requestPermission(); } catch(e){} }
async function clockEvent(kind){
  const emp = myEmp(); if (!emp){ toast('Your user is not linked to an employee record'); return; }
  toast('Getting your location…'); const g = await getGeo(); const site = S.project.geo; const geo = g ? {lat:g.lat, lng:g.lng, acc:g.acc, dist: site ? distM(g, site) : null} : null; const now = new Date(); const ts = new Date(now.getTime() - now.getTimezoneOffset()*60000).toISOString().slice(0,19);
  if (kind==='in'){ if (DB.time.find(t=>t.empId===emp.id && !t.out)){ toast('Already clocked in'); return; } DB.time.push({id:uid('te'), empId:emp.id, date:today(), in:ts, out:'', breakMin:0, projectId:S.id, code:$('#clock-code')?.value||'', notes:'', status:'open', approvedBy:'', geoIn:geo, geoOut:null, source:'phone', work:[]}); audit('time', emp.id, 'clock-in', null, {geo}); log(`${emp.name} clocked in${geo?.dist!=null?` (${geo.dist} m from site)`:''}`); }
  else { const e = DB.time.find(t=>t.empId===emp.id && !t.out); if (!e){ toast('Not clocked in'); return; } e.out = ts; e.geoOut = geo; e.work = e.work||[]; if (!e.work.length) e.work.push({projectId:e.projectId, code:e.code||'', hours:0, note:''}); e.status = Math.abs(workHours(e)-hoursOf(e))<=0.26 && workHours(e) ? 'submitted' : 'open'; if (hoursOf(e) >= 6 && !e.breakMin) e.breakMin = 30; audit('time', e.id, 'clock-out', null, {geo, hours:hoursOf(e)}); log(`${emp.name} clocked out — ${hoursOf(e).toFixed(1)} h`); }
  save(); render(); toast(kind==='in' ? 'Clocked in' : 'Clocked out — now log what you worked on');
}
