  '11': {n:'Finish carpentry & doors', items:[['Base molding (per profile)','lf',120],['Casing (per profile)','lf',160],['Door jambs / prehung doors','ea',4],['Shims','bundle',2],['Finish nails 15/16 ga','box',2],['Wood glue','ea',1],['Wood filler','ea',1],['Door hardware (hinges, stops)','set',4]]},
