const MB_SIDE = [['overview','Overview'],['activity','Activity'],['listing','Listing & price'],['uw','Underwriting'],['gov','Property & government'],['watch','Watch & revisit']];
let mbPropId = null, mbBoardMode = 'board', mbQuery = '', mbChip = 'active', mbActFilter = 'all', mbBrokerFilter = '';
const MB_ICON = {dash:'<svg viewBox="0 0 24 24"><path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg>', deals:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="10" rx="1"/><rect x="17" y="4" width="4" height="13" rx="1"/></svg>', watch:'<svg viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>', props:'<svg viewBox="0 0 24 24"><path d="M4 21V8l8-5 8 5v13"/><path d="M9 21v-6h6v6"/></svg>', brokers:'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><circle cx="17" cy="9" r="2.5"/><path d="M15.5 14.5a5 5 0 0 1 6 5"/></svg>', plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>'};

function setWorkspace(ws){ DB.workspace = ws; document.body.classList.toggle('ws-mb', ws==='mb'); if (ws==='mb'){ if (!MB_VIEWS.includes(view)) view = 'mbdash'; } else if (MB_VIEWS.includes(view)) view = ROLE_VIEWS[role()].find(v => !MB_VIEWS.includes(v)) || 'dash'; save(); render(); }
function mbTop(){ window.scrollTo(0,0); document.querySelector('.main')?.scrollTo?.(0,0); }
function mbOpen(id, tab){ mbDealId = id; if (tab) mbTab = tab; view = 'mbdeal'; render(); mbTop(); }
function renderMBShell(){ const has = mbAccess(); const sw = $('#ws'); const who = $('#whoami'); if (who){ const u = currentUser(); who.innerHTML = u ? `<div>Signed in as <b>${esc(u.name)}</b><div style="opacity:.7">${esc(ROLE_NAMES[u.role]||u.role)}${u.mb&&u.role!=='owner'?' · Mercer &amp; Bond':''}</div></div><button class="btn sm" id="switch-user" style="margin-top:6px">Switch user</button>` : ''; $('#switch-user')?.addEventListener('click', () => signOut()); } if (sw){ sw.style.display = (has && !String(role()).startsWith('mb_')) ? '' : 'none'; sw.querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.ws===(DB.workspace||'sd'))); } if (!has && DB.workspace==='mb'){ DB.workspace = 'sd'; } document.body.classList.toggle('ws-mb', DB.workspace==='mb' && has); document.querySelectorAll('#nav-mb button[data-v]').forEach(b => b.classList.toggle('on', b.dataset.v===view || (view==='mbdeal' && b.dataset.v==='mbdeals') || (view==='mbprop' && b.dataset.v==='mbprops') || (view==='mbownp' && b.dataset.v==='mbown'))); const n = { mbdash: DB.deals.filter(d => (mbReason(d)?.rank??9) <= 1).length, mbdeals: DB.deals.filter(d => MB_ACTIVE.includes(d.status)).length, mbwatch: DB.deals.filter(d => d.status==='reactivated').length }; Object.entries(n).forEach(([k,v]) => { const el = $('#n-'+k); if (el) el.textContent = v || ''; }); }

/* ---------- small UI helpers ---------- */
function mbModal(title, body, opts={}){ mbCloseModal(); const m = document.createElement('div'); m.className = 'mbm'; m.id = 'mbm'; m.innerHTML = `<div class="mbm-box" role="dialog" aria-label="${esc(title)}"><div class="mbm-hd"><h3>${title}</h3><button class="mbm-x" aria-label="Close">✕</button></div><div class="mbm-bd">${body}</div><div class="mbm-ft"><button class="btn" id="mbm-cancel">Cancel</button>${opts.submit!==null?`<button class="btn primary" id="mbm-ok">${opts.submit||'Save'}</button>`:''}</div></div>`; document.body.appendChild(m); const close = () => mbCloseModal(); m.querySelector('.mbm-x').onclick = close; $('#mbm-cancel').onclick = close; m.addEventListener('click', e => { if (e.target===m) close(); }); const ok = $('#mbm-ok'); if (ok) ok.onclick = () => { const f = {}; m.querySelectorAll('[data-f]').forEach(i => f[i.dataset.f] = i.type==='checkbox' ? i.checked : i.value.trim()); const r = opts.onSubmit && opts.onSubmit(f); if (r!==false) close(); }; m.addEventListener('keydown', e => { if (e.key==='Escape') close(); if (e.key==='Enter' && e.target.tagName!=='TEXTAREA' && ok) ok.click(); }); const first = m.querySelector('input,textarea,select'); if (first) setTimeout(() => first.focus(), 30); return m; }
function mbCloseModal(){ const m = $('#mbm'); if (m) m.remove(); }
const mbF = (label, inner) => `<div class="f"><label>${label}</label>${inner}</div>`;
const mbIn = (f, v='', ph='', type='text') => `<input data-f="${f}" type="${type}" value="${esc(v)}" placeholder="${esc(ph)}">`;
const mbSel = (f, opts, v) => `<select data-f="${f}">${opts.map(o => Array.isArray(o) ? `<option value="${esc(o[0])}" ${o[0]===v?'selected':''}>${esc(o[1])}</option>` : `<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
const mbNextFields = d => `<div class="mb-nextbox"><div class="small" style="font-weight:600;margin-bottom:6px">What's next?</div><div class="grid2">${mbF('Next action', mbIn('next', d.nextAction, 'e.g. Call broker about access'))}${mbF('Waiting for', mbIn('waiting', d.waitingFor, 'e.g. Setup sheet'))}${mbF('Follow up on', mbIn('follow', d.followUpAt||'', '', 'date'))}</div></div>`;
function mbApplyNext(d, f){ if (f.next!==undefined) d.nextAction = f.next; if (f.waiting!==undefined) d.waitingFor = f.waiting; if (f.follow!==undefined) d.followUpAt = f.follow; }
const mbTW = html => `<div class="tw">${html}</div>`;
const mbStatusCls = d => { const st = d.status, f = mbFollow(d); return st==='acquired'?'ok':['watch','passed','closed'].includes(st)?'neutral':['responded','reactivated','new'].includes(st)?'info':st==='waiting'?(f?f.cls:'info'):'warn'; };
const mbRelDate = s => { if (!s) return ''; const n = Math.round((parse(s) - parse(mbToday()))/86400000); return n===0?'today':n===1?'tomorrow':n===-1?'yesterday':n<0?`${-n} d overdue`:`in ${n} d`; };

/* why a deal needs attention — one reason, ranked (0 = act now) */
function mbReason(d){ const f = mbFollow(d); const recent = new Date(Date.now()-14*86400000).toISOString(); const p = mbProp(d); const act = MB_ACTIVE.includes(d.status);
  if (act && mbAtRisk(d)) return {rank:0, cls:'bad', label:'No next action'};
  if (f && f.sev>=3) return {rank:0, cls:'bad', label:'Broker unresponsive · '+f.label.toLowerCase()};
  if (act && d.followUpAt && d.followUpAt < mbToday()) return {rank:0, cls:'bad', label:'Follow-up '+mbRelDate(d.followUpAt)};
  if (d.status==='responded') return {rank:1, cls:'info', label:'Broker responded'};
  if (d.status==='reactivated') return {rank:1, cls:'info', label:'Reactivated — review what changed'};
  if (f && f.sev>=1) return {rank:1, cls:'warn', label:f.label};
  if (act && d.followUpAt===mbToday()) return {rank:1, cls:'warn', label:'Follow-up today'};
  if (['new','review'].includes(d.status)) return {rank:2, cls:'info', label:'Needs initial screen'};
  if ((act||d.status==='watch') && p.govEvents.some(g => g.t > recent && g.kind!=='check')) return {rank:2, cls:'bad', label:'Government record changed'};
  if (act && d.listings.some(l => l.priceHistory.some(x => x.type==='Price reduction' && x.at > recent))) return {rank:2, cls:'ok', label:'Price reduced'};
  if ((act||d.status==='watch') && mbConflicts(p).length) return {rank:3, cls:'warn', label:`${mbConflicts(p).length} data conflict${mbConflicts(p).length>1?'s':''}`};
  if (act && d.reviewAt && d.reviewAt <= mbToday()) return {rank:1, cls:'warn', label:'Scheduled review due'};
  if (act && d.followUpAt) return {rank:4, cls:'neutral', label:'Follow-up '+mbRelDate(d.followUpAt)};
  return null; }

/* ---------- capture (new deal) ---------- */
function mbCaptureModal(prefill=''){ mbModal('New deal', `<p class="small muted" style="margin:0 0 8px">A listing link, an address, or one line of notes is enough. The property record, deal and listing episode are created and de-duplicated automatically.</p>${mbF('Listing URL, address or note', `<input data-f="text" id="mb-cap" value="${esc(prefill)}" placeholder="e.g. 166 Carlton Ave — broker Michael called, asking 8.9, possible conversion">`)}<div id="mb-cap-out"></div><details style="margin-top:10px"><summary class="small" style="cursor:pointer;color:var(--ink-3)">Paste a broker email instead</summary><textarea id="mb-email" data-f="email" style="width:100%;height:120px;margin-top:6px;font-size:13px" placeholder="Paste the email including the sender's signature…"></textarea><div class="row" style="margin-top:6px;gap:8px;align-items:center"><button class="btn sm" id="mb-email-go" type="button">Read email</button><span class="small muted">Extracts address, broker, price, link, deadlines; matches an existing deal or proposes a new one.</span></div><div id="mb-email-out"></div></details>`, {submit:'Save deal', onSubmit: f => { const t = f.text; if (!t) return false; const x = mbExtract(t); if (!x.address && !x.url){ $('#mb-cap-out').innerHTML = `<div class="small" style="color:var(--warn);margin-top:6px">No address or listing link found. Add the street address, e.g. "${esc(t.slice(0,30))} — 166 Carlton Ave".</div>`; return false; } const r = mbCreateDeal(x); toast(r.merged ? `Added to existing deal ${r.deal.number}` : `Deal ${r.deal.number} created — ${r.property.address}`); mbOpen(r.deal.id, 'overview'); }});
  $('#mb-email-go').onclick = () => { const t = $('#mb-email').value.trim(); if (!t) return; const x = mbExtract(t); x.source = 'email'; const prop = mbFindProperty({address:x.address, listingId:x.listingId}); const match = prop ? mbActiveDeal(prop.id) : (x.brokerEmail ? DB.deals.find(d => d.broker.email && d.broker.email.toLowerCase()===x.brokerEmail.toLowerCase() && (MB_ACTIVE.includes(d.status)||d.status==='watch')) : null);
    $('#mb-email-out').innerHTML = `<div class="card" style="margin-top:8px;background:var(--paper-2)"><b>Extracted</b>${mbTW(`<table class="t" style="margin-top:6px"><tbody>${[['Address', x.address||'<span class="muted">not found</span>'],['Asking', x.ask?mbMM(x.ask):'—'],['Broker', [x.broker, x.brokerage].filter(Boolean).join(' · ')||'—'],['Email / phone', [x.brokerEmail, x.brokerPhone].filter(Boolean).join(' · ')||'—'],['Listing', x.url||'—'],['Deadlines', x.deadlines.join('; ')||'—'],['Attachments', x.attachments.join('; ')||'—']].map(([k,v])=>`<tr><td class="dim" style="width:120px">${k}</td><td>${v}</td></tr>`).join('')}</tbody></table>`)}<div class="row" style="margin-top:8px;gap:8px;flex-wrap:wrap">${match ? `<button class="btn primary sm" id="mb-email-attach" type="button">Attach to ${match.number} · ${esc(mbProp(match).address)}</button>` : ''}${x.address||x.url ? `<button class="btn sm ${match?'':'primary'}" id="mb-email-new" type="button">${match?'Create a separate deal':'Create deal'}</button>`:'<span class="small muted">Add an address to create a deal.</span>'}</div></div>`;
    $('#mb-email-attach')?.addEventListener('click', () => { const d = match; mbAddActivity(d, 'email', `Broker email: ${x.note}`, 'in'); if (x.ask && x.ask!==mbAsk(d)) mbPriceChange(d, x.ask, 'Broker email'); if (x.attachments.length){ mbAddActivity(d, 'doc', x.attachments[0]); mbAddDoc(d, x.attachments[0], 'Attachment'); } if (x.deadlines.length) d.deadlines = [...new Set([...(d.deadlines||[]), ...x.deadlines])]; if (d.status==='waiting'){ mbSetStatus(d, 'responded', 'broker replied'); d.waitingFor = ''; d.nextAction = 'Review broker reply' + (x.attachments.length ? ' — read the setup sheet, start quick screen' : ''); d.followUpAt = mbToday(); } save(); mbCloseModal(); toast('Attached to '+d.number); mbOpen(d.id,'overview'); });
    $('#mb-email-new')?.addEventListener('click', () => { const r = mbCreateDeal(x); mbCloseModal(); toast(`Deal ${r.deal.number} created`); mbOpen(r.deal.id,'overview'); }); }; }
function mbAddDoc(d, name, kind, note){ d.docs = d.docs||[]; d.docs.push({id:uid('dc'), name, kind:kind||'Document', date:mbToday(), note:note||'', by:mbBy()}); }

/* ---------- shared row / card ---------- */
function mbDealRow(d){ const prop = mbProp(d); const r = mbReason(d); const orig = mbOriginalAsk(d), ask = mbAsk(d); return `<tr class="click" data-mbopen="${d.id}"><td class="name"><b>${esc(prop.address)}</b><div class="sub" style="margin-left:0">${esc(prop.neighborhood||prop.borough||'')} · ${d.number}</div></td><td><span class="pill ${mbStatusCls(d)}">${MB_STATUS[d.status]}</span></td><td>${r?`<span class="mb-why ${r.cls}">${r.label}</span>`:'<span class="muted">—</span>'}</td><td class="money">${mbMM(ask)}${orig&&orig!==ask?`<div class="small muted">was ${mbMM(orig)}</div>`:''}</td><td class="num">${mbDOM(d)} / ${mbCDOM(d)}</td><td>${esc(d.broker.name||'—')}</td><td class="mb-next">${esc(d.nextAction||d.waitingFor||(d.reviewAt?'review '+fmtL(d.reviewAt):''))||'<span class="muted">—</span>'}${d.followUpAt?`<div class="small muted">${mbRelDate(d.followUpAt)}</div>`:''}</td></tr>`; }
const mbTable = rows => mbTW(`<table class="t mb-t"><thead><tr><th>Property</th><th>Stage</th><th>Attention</th><th style="text-align:right">Ask</th><th style="text-align:right">DOM / CDOM</th><th>Broker</th><th>Next step</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="7" class="muted">Nothing here.</td></tr>'}</tbody></table>`);
function mbCard(d){ const p = mbProp(d); const r = mbReason(d); const orig = mbOriginalAsk(d), ask = mbAsk(d); return `<div class="mb-card" data-mbopen="${d.id}"><div class="mb-card-addr">${esc(p.address)}</div><div class="small muted">${esc(p.neighborhood||p.borough||'')}${d.broker.name?' · '+esc(d.broker.name):''}</div><div class="mb-card-num"><b>${mbMM(ask)}</b>${orig&&orig!==ask?`<span class="small" style="color:var(--ok)">−${((orig-ask)/orig*100).toFixed(0)}%</span>`:''}<span class="small muted">${mbCDOM(d)} d</span></div>${r?`<div class="mb-why ${r.cls}">${r.label}</div>`:''}${d.nextAction||d.waitingFor?`<div class="small mb-card-next">${esc(d.nextAction||('Waiting: '+d.waitingFor))}</div>`:''}</div>`; }

function renderMB(){
  renderMBShell(); if (!mbAccess()) return; mbEvalAllWatch();
  if (view==='mbdash') renderMBDash(); if (view==='mbdeals') renderMBDeals(); if (view==='mbwatch') renderMBWatch(); if (view==='mbprops') renderMBProps(); if (view==='mbbrokers') renderMBBrokers(); if (view==='mbdeal') renderMBDeal(); if (view==='mbprop') renderMBProp();
  document.querySelectorAll('[data-mbopen]').forEach(el => el.addEventListener('click', e => { if (e.target.closest('button,a,select,input')) return; mbOpen(el.dataset.mbopen, el.dataset.mbtab||undefined); }));
  const nb = $('#mb-new'); if (nb) nb.onclick = () => mbCaptureModal();
}

/* ---------- Today ---------- */
function renderMBDash(){
  const deals = DB.deals, active = deals.filter(d => MB_ACTIVE.includes(d.status)); const recent = new Date(Date.now()-14*86400000).toISOString();
  const work = deals.map(d => ({d, r:mbReason(d)})).filter(x => x.r && x.r.rank<=3).sort((a,b) => a.r.rank-b.r.rank || (a.d.followUpAt||'9').localeCompare(b.d.followUpAt||'9') || (b.d.lastActivityAt||'').localeCompare(a.d.lastActivityAt||''));
  const later = deals.map(d => ({d, r:mbReason(d)})).filter(x => x.r && x.r.rank===4).sort((a,b) => (a.d.followUpAt||'9').localeCompare(b.d.followUpAt||'9'));
  const overdue = deals.filter(d => (mbReason(d)?.rank??9)===0).length;
  const stats = [['Active deals', active.length, mbMM(active.reduce((s,d)=>s+mbAsk(d),0))+' total ask', 'mbdeals'], ['Act now', overdue, 'overdue or forgotten', 'mbdash', overdue?'bad':''], ['Waiting on brokers', deals.filter(d=>d.status==='waiting').length, 'inquiries out', 'mbdeals'], ['Watching', deals.filter(d=>d.status==='watch').length, `${deals.filter(d=>d.status==='reactivated').length} reactivated`, 'mbwatch'], ['Properties', DB.properties.length, 'in memory', 'mbprops']];
  const signals = []; deals.forEach(d => { const p = mbProp(d); if (!(MB_ACTIVE.includes(d.status)||d.status==='watch')) return; d.listings.forEach(l => l.priceHistory.filter(x => x.type==='Price reduction' && x.at > recent).forEach(x => signals.push({t:x.at, cls:'ok', text:`${p.address}: reduced ${mbMM(x.prev)} → ${mbMM(x.next)}`, id:d.id, tab:'listing'}))); p.govEvents.filter(g => g.t > recent && g.kind!=='check').forEach(g => signals.push({t:g.t, cls:'bad', text:`${p.address}: ${g.text}`, id:d.id, tab:'gov'})); d.reactivations.filter(r => r.at > recent).forEach(r => signals.push({t:r.at, cls:'info', text:`${p.address}: reactivated — ${r.triggers.join('; ')}`, id:d.id, tab:'watch'})); }); signals.sort((a,b)=>b.t.localeCompare(a.t));
  const feed = deals.flatMap(d => d.activities.map(a => ({a, d}))).sort((a,b)=>b.a.t.localeCompare(a.a.t)).slice(0,8);
  const row = ({d, r}) => { const p = mbProp(d); return `<div class="mb-work" data-mbopen="${d.id}"><div class="mb-work-main"><div><b>${esc(p.address)}</b> <span class="small muted">${esc(p.neighborhood||p.borough||'')} · ${MB_STATUS[d.status]}${d.broker.name?' · '+esc(d.broker.name):''}</span></div><div class="mb-work-next">${esc(d.nextAction||(d.waitingFor?'Waiting for '+d.waitingFor:'')||'')||'<span style="color:var(--bad)">Set a next action</span>'}</div></div><span class="mb-why ${r.cls}">${r.label}</span><div class="mb-work-ask">${mbMM(mbAsk(d))}</div><button class="btn sm" data-mblog="${d.id}">Log</button></div>`; };
  $('#mb-today').innerHTML = `<div class="mb-stats">${stats.map(([k,v,s,go,cls]) => `<button class="mb-stat ${cls||''}" data-mbgo="${go}"><span>${k}</span><b>${v}</b><i>${s}</i></button>`).join('')}</div>
    <div class="mb-capbar"><input id="mb-cap-inline" placeholder="Add a deal — paste a listing link, an address, or a note and press Enter"><button class="btn primary" id="mb-cap-go">Add</button></div>
    <div class="mb-two"><div>
      <div class="card mb-list"><div class="mb-list-hd"><h3>Needs attention</h3><span class="small muted">${work.length} deal${work.length===1?'':'s'} · most urgent first</span></div>${work.map(row).join('')||'<div class="muted small" style="padding:10px 0">Nothing needs attention. Every active deal has a next step and nothing is overdue.</div>'}</div>
      ${later.length?`<div class="card mb-list" style="margin-top:12px"><div class="mb-list-hd"><h3>Coming up</h3><span class="small muted">scheduled follow-ups</span></div>${later.map(row).join('')}</div>`:''}
    </div><div>
      <div class="card"><h3>Market & record signals <span class="small muted">14 days</span></h3>${signals.slice(0,8).map(s => `<div class="logline click" data-mbopen="${s.id}" data-mbtab="${s.tab}"><span>${fmtL(s.t.slice(0,10))}</span><span class="mb-dot ${s.cls}"></span>${esc(s.text)}</div>`).join('')||'<div class="muted small">No price changes, government record changes or reactivations in the last two weeks.</div>'}</div>
      <div class="card" style="margin-top:12px"><h3>Recent activity</h3>${feed.map(({a,d}) => `<div class="logline click" data-mbopen="${d.id}" data-mbtab="activity"><span>${fmtL(a.t.slice(0,10))}</span><span class="mb-dot ${a.dir==='in'?'info':a.dir==='out'?'neutral':a.kind==='gov'?'bad':'neutral'}"></span><span><b>${esc(mbProp(d).address)}</b> — ${esc(a.text)}</span></div>`).join('')||'<div class="muted small">No activity yet.</div>'}</div>
    </div></div>`;
  document.querySelectorAll('[data-mbgo]').forEach(b => b.onclick = () => { view = b.dataset.mbgo; if (view==='mbdeals') mbChip = 'active'; render(); });
  const go = () => { const t = $('#mb-cap-inline').value.trim(); if (!t) { mbCaptureModal(); return; } const x = mbExtract(t); if (!x.address && !x.url){ mbCaptureModal(t); return; } const r = mbCreateDeal(x); toast(r.merged ? `Added to existing deal ${r.deal.number}` : `Deal ${r.deal.number} created — ${r.property.address}`); mbOpen(r.deal.id, 'overview'); };
  $('#mb-cap-go').onclick = go; $('#mb-cap-inline').addEventListener('keydown', e => { if (e.key==='Enter') go(); });
  document.querySelectorAll('[data-mblog]').forEach(b => b.onclick = e => { e.stopPropagation(); mbLogModal(DB.deals.find(d=>d.id===b.dataset.mblog)); });
}

/* ---------- Deals ---------- */
function renderMBDeals(){ const chips = {active:['Active', d => MB_ACTIVE.includes(d.status)], attention:['Needs attention', d => (mbReason(d)?.rank??9)<=1], waiting:['Waiting on broker', d => d.status==='waiting'], serious:['Underwriting & beyond', d => ['underwriting','diligence','offer','negotiating','contract'].includes(d.status)], reductions:['Price cuts', d => d.listings.some(l => l.priceHistory.some(p => p.type==='Price reduction'))], historic:['Historic / HTC', d => !!mbFactValue(mbProp(d),'landmark')], manhattan:['Manhattan', d => /manhattan/i.test(mbProp(d).borough)], brooklyn:['Brooklyn', d => /brooklyn/i.test(mbProp(d).borough)], watch:['Watch & passed', d => ['watch','passed','reactivated'].includes(d.status)], done:['Acquired & closed', d => ['acquired','closed'].includes(d.status)], all:['Everything', () => true]};
  if (!chips[mbChip]) mbChip = 'active'; const q = mbQuery.toLowerCase();
  const list = DB.deals.filter(chips[mbChip][1]).filter(d => !mbBrokerFilter || d.broker.name===mbBrokerFilter || d.listings.some(e => e.brokerName===mbBrokerFilter)).filter(d => !q || [mbProp(d).address, mbProp(d).neighborhood, mbProp(d).borough, d.broker.name, d.broker.brokerage, d.number, d.nextAction, d.thesis].join(' ').toLowerCase().includes(q)).sort((a,b) => (b.lastActivityAt||'').localeCompare(a.lastActivityAt||''));
  const cols = MB_STAGES.map(([name, sts]) => [name, list.filter(d => sts.includes(d.status))]).concat([['Watch / passed', list.filter(d => ['watch','passed','reactivated'].includes(d.status))],['Acquired / closed', list.filter(d => ['acquired','closed'].includes(d.status))]]).filter(([n,l]) => l.length || MB_STAGES.some(s=>s[0]===n));
  { const ld = document.getElementById('mb-deals-lead'); if (ld){ const A = DB.deals.filter(d => MB_ACTIVE.includes(d.status)); const w = A.filter(d => d.status==='waiting').length; const ser = A.filter(d => ['underwriting','diligence','offer','negotiating','contract'].includes(d.status)).length; ld.textContent = A.length ? `${A.length} active · ${w} waiting on a broker · ${ser} in underwriting or beyond · ${mbMM(A.reduce((s,d)=>s+mbAsk(d),0))} asking in total` : 'No active deals. Paste a listing on Today to start one.'; } }
  $('#mb-deals').innerHTML = `<div class="mb-toolbar"><div class="chips">${Object.entries(chips).map(([k,[l]]) => `<button class="chip ${mbChip===k?'on':''}" data-chip="${k}">${l}</button>`).join('')}${mbBrokerFilter?`<button class="chip on" id="mb-clearbroker">Broker: ${esc(mbBrokerFilter)} ✕</button>`:''}</div><div class="row" style="gap:8px;align-items:center"><input id="mb-q" class="mb-search" placeholder="Search address, broker, note…" value="${esc(mbQuery)}"><div class="seg"><button class="${mbBoardMode==='board'?'on':''}" data-mode="board">Board</button><button class="${mbBoardMode==='list'?'on':''}" data-mode="list">List</button></div></div></div>
    ${mbBoardMode==='board' ? `<div class="mb-board">${cols.map(([name, l]) => `<div class="mb-col ${l.length?'':'empty'}"><div class="mb-col-hd">${name} <span>${l.length}</span></div>${l.map(mbCard).join('')||'<div class="mb-col-empty">—</div>'}</div>`).join('')}</div>` : mbTable(list.map(mbDealRow))}
    <div class="small muted" style="margin-top:10px">${list.length} deal${list.length===1?'':'s'} · stages: ${Object.entries(MB_STATUS).map(([k,l]) => { const n = DB.deals.filter(d=>d.status===k).length; return n ? `${l} ${n}` : ''; }).filter(Boolean).join(' · ')}</div>`;
  document.querySelectorAll('[data-chip]').forEach(b => b.onclick = () => { mbChip = b.dataset.chip; render(); });
  document.querySelectorAll('[data-mode]').forEach(b => b.onclick = () => { mbBoardMode = b.dataset.mode; render(); });
  $('#mb-clearbroker')?.addEventListener('click', () => { mbBrokerFilter = ''; render(); });
  const qi = $('#mb-q'); qi.addEventListener('input', () => { mbQuery = qi.value; const pos = qi.selectionStart; render(); const n = $('#mb-q'); n.focus(); n.setSelectionRange(pos,pos); }); }

/* ---------- Watchlist ---------- */
function renderMBWatch(){ const w = DB.deals.filter(d => d.status==='watch'); const r = DB.deals.filter(d => d.status==='reactivated');
  $('#mb-watch').innerHTML = `${r.length?`<div class="card" style="margin-bottom:12px;border-color:var(--accent)"><div class="mb-list-hd"><h3>Reactivated — review what changed</h3><span class="small muted">a trigger you set was reached</span></div>${mbTable(r.map(mbDealRow))}</div>`:''}<div class="card"><div class="mb-list-hd"><h3>Watching</h3><span class="small muted">passed for now; monitored for the triggers you defined</span><button class="btn sm" id="mb-eval" style="margin-left:auto">Check triggers now</button></div>${mbTW(`<table class="t"><thead><tr><th>Property</th><th>Passed because</th><th style="text-align:right">Ask then → now</th><th>Triggers</th><th>Review</th></tr></thead><tbody>${w.map(d => { const p = mbProp(d); return `<tr class="click" data-mbopen="${d.id}" data-mbtab="watch"><td class="name"><b>${esc(p.address)}</b><div class="sub" style="margin-left:0">${esc(p.neighborhood||p.borough||'')}</div></td><td>${esc(d.passReason)}${d.passNote?`<div class="small muted">${esc(d.passNote)}</div>`:''}</td><td class="money">${d.passedSnapshot?mbMM(d.passedSnapshot.ask):'—'} → ${mbMM(mbAsk(d))}</td><td>${d.triggers.filter(t=>t.active).map(t => `<span class="pill ${mbTriggerHit(d,t)?'ok':'neutral'}" title="${mbTriggerHit(d,t)?'condition met':'not yet'}">${MB_TRIGGER_TYPES[t.type]}${['relist','broker','historic'].includes(t.type)?'':' '+(t.type==='price'?mbMM(+t.value):t.type==='psf'?mbM(+t.value):t.value)}</span>`).join(' ')} <span class="small muted">${d.triggerLogic}</span></td><td>${d.reviewAt?fmtL(d.reviewAt):'—'}</td></tr>`; }).join('') || '<tr><td colspan="5" class="muted">No watched deals.</td></tr>'}</tbody></table>`)}</div>`;
  $('#mb-eval').onclick = () => { const n = mbEvalAllWatch(); toast(n ? `${n} deal${n>1?'s':''} reactivated` : 'No triggers reached'); render(); }; }

/* ---------- Properties ---------- */
function renderMBProps(){ $('#mb-props').innerHTML = mbTW(`<table class="t"><thead><tr><th>Property</th><th>Zoning</th><th style="text-align:right">Existing / max SF</th><th>Last sale</th><th>Deals</th><th>Flags</th><th></th></tr></thead><tbody>${DB.properties.map(p => { const ds = DB.deals.filter(d=>d.propertyId===p.id).sort((a,b)=>(b.lastActivityAt||'').localeCompare(a.lastActivityAt||'')); const last = p.saleHistory[p.saleHistory.length-1]; const open = p.violations.filter(v=>!['Dismissed','Closed','Certified'].includes(v.normalizedStatus)).length; const d0 = ds[0]; return `<tr class="click" data-mbprop="${p.id}"><td class="name"><b>${esc(p.address)}</b><div class="sub" style="margin-left:0">${esc([p.neighborhood,p.borough].filter(Boolean).join(', '))}${p.bbl?' · BBL '+esc(p.bbl):''}${p.ownedBy?' · <b>owned</b>':''}</div></td><td>${esc(mbFactValue(p,'zoning')?.normalized||'—')}</td><td class="num">${mbNum(p,'buildingSF')?mbNum(p,'buildingSF').toLocaleString():'—'} / ${mbNum(p,'buildableSF')?mbNum(p,'buildableSF').toLocaleString():'—'}</td><td>${last?`${mbMM(last.price)} · ${fmt(last.date)}`:'—'}</td><td>${ds.map(d=>`<span class="pill ${MB_ACTIVE.includes(d.status)?'info':'neutral'}" data-mbopen="${d.id}" style="cursor:pointer">${d.number} ${MB_STATUS[d.status]}</span>`).join(' ')||'—'}</td><td class="mb-flags">${[open?`<span class="pill bad">${open} open violation${open>1?'s':''}</span>`:'', mbConflicts(p).length?`<span class="pill warn">${mbConflicts(p).length} conflict${mbConflicts(p).length>1?'s':''}</span>`:'', mbFactValue(p,'landmark')?'<span class="pill neutral">Historic</span>':''].filter(Boolean).join(' ')}</td><td>${mbCanEdit()&&!mbActiveDeal(p.id)?`<button class="btn sm" data-mbnewdeal="${esc(p.address)}">New deal</button>`:''}</td></tr>`; }).join('') || '<tr><td colspan="7" class="muted">No properties yet.</td></tr>'}</tbody></table>`);
  document.querySelectorAll('[data-mbnewdeal]').forEach(b => b.onclick = () => mbCaptureModal(b.dataset.mbnewdeal)); document.querySelectorAll('[data-mbprop]').forEach(tr => tr.addEventListener('click', e => { if (e.target.closest('button,a,[data-mbopen]')) return; mbOpenProp(tr.dataset.mbprop); })); }

/* ---------- Brokers ---------- */
function renderMBBrokers(){ const map = {}; DB.deals.forEach(d => { const seen = new Set(); [d.broker, ...d.listings.map(e => ({name:e.brokerName, brokerage:e.brokerage, email:'', phone:''}))].forEach(bk => { const n = bk && bk.name; if (!n || seen.has(n)) return; seen.add(n); const b = map[n] = map[n] || {name:n, brokerage:bk.brokerage, email:bk.email, phone:bk.phone, deals:[], last:''}; b.deals.push(d); if (!b.brokerage && bk.brokerage) b.brokerage = bk.brokerage; if (!b.email && bk.email) b.email = bk.email; if (!b.phone && bk.phone) b.phone = bk.phone; }); const n = d.broker.name; if (!n) return; const b = map[n]; if (!b.brokerage && d.broker.brokerage) b.brokerage = d.broker.brokerage; if (!b.email && d.broker.email) b.email = d.broker.email; if (!b.phone && d.broker.phone) b.phone = d.broker.phone; d.activities.filter(a=>a.dir).forEach(a => { if (a.t > b.last) b.last = a.t; }); });
  const bs = Object.values(map).sort((a,b) => b.deals.length - a.deals.length || a.name.localeCompare(b.name));
  $('#mb-brokers').innerHTML = mbTW(`<table class="t"><thead><tr><th>Broker</th><th>Contact</th><th style="text-align:right">Deals</th><th>Waiting on them</th><th>Last contact</th><th>Responsiveness</th></tr></thead><tbody>${bs.map(b => { const waiting = b.deals.filter(d => d.status==='waiting'); const replies = b.deals.flatMap(d=>d.activities).filter(a=>a.dir==='in').length, outs = b.deals.flatMap(d=>d.activities).filter(a=>a.dir==='out').length; const stale = waiting.filter(d => (mbFollow(d)?.sev||0)>=3).length; return `<tr class="click" data-mbbroker="${esc(b.name)}"><td class="name"><b>${esc(b.name)}</b><div class="sub" style="margin-left:0">${esc(b.brokerage||'')}</div></td><td class="small">${esc(b.email||'')}${b.email&&b.phone?'<br>':''}${esc(b.phone||'')}</td><td class="num">${b.deals.length}</td><td>${waiting.length?`<span class="pill ${stale?'bad':'warn'}">${waiting.length}${stale?' · '+stale+' stale':''}</span>`:'—'}</td><td>${b.last?fmtL(b.last.slice(0,10)):'—'}</td><td class="small muted">${outs?`${replies} repl${replies===1?'y':'ies'} to ${outs} inquir${outs===1?'y':'ies'}`:'—'}</td></tr>`; }).join('')||'<tr><td colspan="6" class="muted">No brokers yet — they appear as deals are created.</td></tr>'}</tbody></table>`);
  document.querySelectorAll('[data-mbbroker]').forEach(tr => tr.onclick = () => { mbBrokerFilter = tr.dataset.mbbroker; mbChip = 'all'; mbBoardMode = 'list'; view = 'mbdeals'; render(); }); }

/* ---------- deal page ---------- */
function mbStepper(d){ const st = d.status; const inStage = MB_STAGES.findIndex(([,s]) => s.includes(st)); const term = !MB_ACTIVE.includes(st); return `<div class="mb-steps">${MB_STAGES.map(([n,s],i) => `<div class="mb-step ${!term&&i<inStage?'done':''} ${!term&&i===inStage?'cur':''}"><i></i><span>${n}${!term&&i===inStage?': '+MB_STATUS[st]:''}</span></div>`).join('')}<div class="mb-step ${term?'cur':''} ${st==='acquired'?'ok':''}"><i></i><span>${term?MB_STATUS[st]:'Acquired'}</span></div></div>`; }
function mbKeyFacts(d, p){ const ask = mbAsk(d), orig = mbOriginalAsk(d), bld = mbNum(p,'buildingSF'), bsf = mbNum(p,'practicalSF')||mbNum(p,'buildableSF'); const last = p.saleHistory[p.saleHistory.length-1]; const sc = Object.values(d.score); const avg = sc.length ? (sc.reduce((s,v)=>s+v,0)/sc.length).toFixed(1) : null;
  const cells = [['Asking', mbMM(ask), orig&&orig!==ask?`was ${mbMM(orig)} · <span style="color:var(--ok)">−${((orig-ask)/orig*100).toFixed(1)}%</span>`:'no change'], ['$ / existing SF', bld?mbM(ask/bld):'—', bld?bld.toLocaleString()+' SF':'size unknown'], ['$ / buildable SF', bsf?mbM(ask/bsf):'—', bsf?bsf.toLocaleString()+' SF':'—'], ['Days on market', `${mbDOM(d)}`, `${mbCDOM(d)} cumulative`], ['Last sale', last?mbMM(last.price):'—', last?fmt(last.date):'none recorded'], ['Score', avg??'—', avg?'/ 10':'not scored']];
  return `<div class="mb-kf">${cells.map(([k,v,s]) => `<div><span>${k}</span><b>${v}</b><i>${s}</i></div>`).join('')}</div>`; }
function mbFlags(d, p){ const red = p.violations.filter(v => v.severity==='RED' && !['Dismissed','Closed','Certified'].includes(v.normalizedStatus)).length; const conf = mbConflicts(p).length; const f = []; if (red) f.push(['bad', `${red} RED violation${red>1?'s':''}`, 'gov']); if (conf) f.push(['warn', `${conf} data conflict${conf>1?'s':''}`, 'gov']); if (p.permits.filter(x=>!['Signed off','Letter of Completion','Withdrawn','Expired'].includes(x.status)).length) f.push(['info','open DOB job','gov']); if (mbFactValue(p,'landmark')) f.push(['neutral','historic','gov']); if (DB.deals.filter(z=>z.propertyId===p.id && z.id!==d.id).length) f.push(['neutral','evaluated before','overview']); if (d.reactivations.length) f.push(['info',`reactivated ×${d.reactivations.length}`,'watch']); if (d.deadlines?.length) f.push(['warn','deadline: '+d.deadlines[0],'overview']); return f.length ? `<div class="mb-flags">${f.map(([c,t,tab]) => `<button class="pill ${c}" data-mbtabgo="${tab}">${esc(t)}</button>`).join('')}</div>` : ''; }

function renderMBDeal(){ const d = DB.deals.find(x => x.id===mbDealId) || DB.deals[0]; if (!d){ $('#mb-deal').innerHTML = '<div class="card muted">No deal selected.</div>'; return; } mbDealId = d.id; const p = mbProp(d); const ed = mbCanEdit(); if (!MB_SIDE.some(s=>s[0]===mbTab)) mbTab = 'overview';
  const r = mbReason(d); const assignees = DB.users.filter(u => u.role==='owner' || String(u.role).startsWith('mb_'));
  let body = ''; if (mbTab==='overview') body = mbOverview(d, p, ed); if (mbTab==='activity') body = mbActivity(d, p, ed); if (mbTab==='listing') body = mbListingTab(d, p, ed); if (mbTab==='uw') body = mbUWTab(d, p, ed); if (mbTab==='watch') body = mbWatchTab(d, p, ed); if (mbTab==='gov') body = mbGovTab(d, p, ed);
  $('#mb-deal').innerHTML = `<div class="mb-dh"><div class="mb-dh-l"><a href="#" id="mb-back" class="mb-back">← Deals</a><h2>${esc(p.address)}${p.needsAddress?' <span class="pill warn">address needed</span>':''}</h2><div class="small muted">${esc([p.neighborhood,p.borough].filter(Boolean).join(', '))} · ${d.number}${d.broker.name?` · ${esc(d.broker.name)}${d.broker.brokerage?', '+esc(d.broker.brokerage):''}`:''} · <a href="#" id="mb-proplink">Property record</a></div>${r?`<div class="mb-why ${r.cls}" style="margin-top:6px">${r.label}</div>`:''}</div>
    <div class="mb-dh-r">${ed?`<button class="btn primary" id="mb-log">Log activity</button><select id="mb-status" class="btn" title="Move stage">${Object.entries(MB_STATUS).map(([k,l]) => `<option value="${k}" ${d.status===k?'selected':''}>${l}</option>`).join('')}</select><select id="mb-assign" class="btn" title="Assigned to"><option value="">Unassigned</option>${assignees.map(u => `<option ${d.assignedTo===u.name?'selected':''}>${esc(u.name)}</option>`).join('')}</select>${!['acquired','closed'].includes(d.status)?`<button class="btn" id="mb-passbtn">${['watch','passed'].includes(d.status)?'Decision…':'Pass / watch…'}</button>`:''}`:''}</div></div>
    ${mbStepper(d)}${mbKeyFacts(d, p)}${mbFlags(d, p)}
    <div class="mb-body"><nav class="mb-side">${MB_SIDE.map(([k,l]) => `<button class="${mbTab===k?'on':''}" data-mbtab="${k}">${l}${k==='activity'?` <span class="n">${d.activities.length||''}</span>`:''}${k==='gov'&&mbConflicts(p).length?` <span class="n warn">${mbConflicts(p).length}</span>`:''}</button>`).join('')}</nav><div class="mb-main">${body}</div></div>`;
  $('#mb-back').onclick = e => { e.preventDefault(); view = 'mbdeals'; render(); };
  document.querySelectorAll('[data-mbtab]').forEach(b => b.onclick = () => { mbTab = b.dataset.mbtab; render(); });
  document.querySelectorAll('[data-mbtabgo]').forEach(b => b.onclick = () => { mbTab = b.dataset.mbtabgo; render(); });
  $('#mb-log')?.addEventListener('click', () => mbLogModal(d));
  $('#mb-proplink')?.addEventListener('click', e => { e.preventDefault(); mbOpenProp(p.id); });
  $('#mb-passbtn')?.addEventListener('click', () => { mbTab = 'watch'; render(); });
  $('#mb-assign')?.addEventListener('change', e => { d.assignedTo = e.target.value; save(); toast(d.assignedTo ? 'Assigned to '+d.assignedTo : 'Unassigned'); });
  $('#mb-status')?.addEventListener('change', e => { const to = e.target.value; if (to==='acquired'){ if (!confirm('Mark this deal Acquired? Property ownership will be updated and the deal closed with full history.')) { render(); return; } mbAcquire(d); } else if (to==='passed' || to==='watch'){ mbTab = 'watch'; render(); toast('Pass from the Watch & revisit section — a reason is required'); return; } else if (to==='waiting'){ mbSetStatus(d, to, 'manual'); if (!d.lastOutboundAt) d.lastOutboundAt = mbNow(); d.waitingFor = d.waitingFor||'Broker reply'; } else { mbSetStatus(d, to, 'manual'); if (['underwriting','diligence','offer','negotiating','contract'].includes(to) && !d.nextAction) d.nextAction = `${MB_STATUS[to]} — set next step`; } save(); render(); });
  mbWireDealTab(d, p, ed);
}

/* log activity — one modal, always ends with "what's next" */
function mbLogModal(d){ if (!d) return; const kinds = [['inquiry','Inquiry sent to broker'],['call','Call'],['reply','Broker replied'],['note','Note'],['doc','Document received'],['meeting','Site visit / meeting']];
  mbModal(`Log activity — ${esc(mbProp(d).address)}`, `${mbF('What happened', mbSel('kind', kinds, 'note'))}${mbF('Details', `<textarea data-f="text" style="height:72px" placeholder="e.g. Asked for setup sheet, rent roll and access Thursday"></textarea>`)}${mbNextFields(d)}`, {submit:'Save', onSubmit: f => { const t = f.text; if (!t) { toast('Add a line of detail'); return false; }
    if (f.kind==='inquiry'){ mbAddActivity(d, 'email', `Inquiry sent to ${d.broker.name||'broker'}: ${t}`, 'out'); if (!f.waiting) f.waiting = `Broker reply — ${t}`; if (!f.follow) f.follow = addWork(mbToday(),2); if (!f.next) f.next = ''; mbSetStatus(d, 'waiting', 'inquiry sent'); }
    if (f.kind==='call') mbAddActivity(d, 'call', t, /left (a )?(vm|voicemail|message)/i.test(t)?'out':'');
    if (f.kind==='reply'){ mbAddActivity(d, 'email', `Broker replied: ${t}`, 'in'); if (/setup|OM|offering|rent roll/i.test(t)){ mbAddActivity(d, 'doc', 'Setup sheet / OM received — start quick screen'); mbAddDoc(d, 'Setup sheet / OM', 'Setup sheet', t); } if (['waiting','contact'].includes(d.status)) mbSetStatus(d, 'responded', 'broker replied'); d.waitingFor = f.waiting||''; if (!f.next) f.next = 'Review broker reply'; if (!f.follow) f.follow = mbToday(); }
    if (f.kind==='note') mbAddActivity(d, 'note', t);
    if (f.kind==='doc'){ mbAddActivity(d, 'doc', t); mbAddDoc(d, t.split(/[—:-]/)[0].trim().slice(0,60)||'Document', 'Document', t); }
    if (f.kind==='meeting') mbAddActivity(d, 'meeting', t);
    mbApplyNext(d, f); d.lastActivityAt = mbNow(); save(); render(); toast('Logged'); }}); }

function mbOverview(d, p, ed){ const acts = d.activities.slice().sort((a,b)=>b.t.localeCompare(a.t)).slice(0,5); const others = DB.deals.filter(z=>z.propertyId===p.id && z.id!==d.id); const dis = ed?'':'disabled'; const docs = d.docs||[];
  const facts = [['Zoning','zoning'],['FAR','far'],['Lot SF','lotSF'],['Existing SF','buildingSF'],['Max buildable','buildableSF'],['Units','units'],['Legal use','legalUse'],['Historic','landmark'],['HTC','htc'],['Owner','owner'],['Annual tax','annualTax']];
  return `<div class="mb-two">
    <div>
      ${others.length?`<div class="card note" style="margin-bottom:12px"><b>Evaluated before.</b> ${others.map(z=>`<a href="#" data-mbopen="${z.id}">${z.number} · ${MB_STATUS[z.status]}${z.passReason?' · '+esc(z.passReason):''}</a>`).join(' · ')} — prior underwriting, broker history and research are preserved.</div>`:''}
      <div class="card"><div class="mb-list-hd"><h3>Next step</h3><span class="small muted">saves as you type</span></div><div class="grid2"><div class="f"><label>Next action</label><input id="mb-next" value="${esc(d.nextAction)}" ${dis} placeholder="What has to happen next?"></div><div class="f"><label>Waiting for</label><input id="mb-waiting" value="${esc(d.waitingFor)}" ${dis} placeholder="e.g. Setup sheet from broker"></div><div class="f"><label>Follow up on</label><input type="date" id="mb-follow" value="${d.followUpAt||''}" ${dis}></div><div class="f"><label>Scheduled review</label><input type="date" id="mb-review" value="${d.reviewAt||''}" ${dis}></div></div>${mbAtRisk(d)?'<div class="small" style="color:var(--bad);margin-top:6px">Without a next action, waiting condition or review date this deal is flagged as at risk of being forgotten.</div>':''}</div>
      <div class="card" style="margin-top:12px"><div class="mb-list-hd"><h3>Thesis</h3></div><textarea id="mb-thesis" ${dis} style="height:70px;width:100%" placeholder="Why this deal — strategy, angle, what would make it work">${esc(d.thesis)}</textarea></div>
      <div class="card" style="margin-top:12px"><div class="mb-list-hd"><h3>Recent activity</h3><button class="btn sm" data-mbtab="activity" style="margin-left:auto">All activity</button></div>${acts.map(a => `<div class="logline"><span>${fmtL(a.t.slice(0,10))}</span><span class="mb-dot ${a.dir==='in'?'info':a.dir==='out'?'neutral':a.kind==='gov'?'bad':'neutral'}"></span><span>${esc(a.text)} <span class="muted">— ${esc(a.by)}</span></span></div>`).join('')||'<div class="muted small">Nothing logged yet.</div>'}</div>
      <div class="card" style="margin-top:12px"><div class="mb-list-hd"><h3>Documents</h3><span class="small muted">setup sheets, OMs, rent rolls, surveys</span>${ed?`<button class="btn sm" id="mb-doc-add" style="margin-left:auto">Add</button>`:''}</div>${docs.length?mbTW(`<table class="t"><tbody>${docs.slice().reverse().map(x => `<tr><td><b>${esc(x.name)}</b>${x.note?`<div class="small muted">${esc(x.note)}</div>`:''}</td><td class="dim">${esc(x.kind)}</td><td class="dim">${fmtL(x.date)}</td><td class="dim">${esc(x.by||'')}</td>${ed?`<td><span class="rm" data-mbdocdel="${x.id}">✕</span></td>`:''}</tr>`).join('')}</tbody></table>`):'<div class="muted small">No documents recorded. Files themselves live in Documents once hosted; here you track what was received and when.</div>'}</div>
    </div>
    <div>
      <div class="card"><div class="mb-list-hd"><h3>Broker</h3>${ed?`<button class="btn sm" id="mb-broker-edit" style="margin-left:auto">${d.broker.name?'Edit':'Add'}</button>`:''}</div>${d.broker.name?`<div><b>${esc(d.broker.name)}</b>${d.broker.brokerage?`<div class="small muted">${esc(d.broker.brokerage)}</div>`:''}${d.broker.email?`<div class="small"><a href="mailto:${esc(d.broker.email)}">${esc(d.broker.email)}</a></div>`:''}${d.broker.phone?`<div class="small"><a href="tel:${esc(d.broker.phone)}">${esc(d.broker.phone)}</a></div>`:''}</div>`:'<div class="muted small">No broker on this deal.</div>'}${d.lastOutboundAt?`<div class="small muted" style="margin-top:6px">Last inquiry ${fmtL(d.lastOutboundAt.slice(0,10))}</div>`:''}${d.deadlines?.length?`<div class="small" style="color:var(--warn);margin-top:6px">Deadlines: ${d.deadlines.map(esc).join('; ')}</div>`:''}</div>
      <div class="card" style="margin-top:12px"><div class="mb-list-hd"><h3>Property</h3><button class="btn sm" data-mbtab="gov" style="margin-left:auto">Records</button></div>${mbTW(`<table class="t mb-facts"><tbody>${facts.map(([k,t]) => { const f = mbFactValue(p,t); return `<tr><td class="dim">${k}</td><td>${f ? `${esc(f.normalized)} <span class="mb-prov ${MB_AUTH[f.authority][1]}" title="${MB_AUTH[f.authority][0]}${f.agency?' · '+esc(f.agency):''}"></span>` : '<span class="muted">—</span>'}</td></tr>`; }).join('')}</tbody></table>`)}<div class="small muted" style="margin-top:6px"><span class="mb-prov ok"></span> official record &nbsp;<span class="mb-prov warn"></span> broker / listing &nbsp;<span class="mb-prov neutral"></span> assumption</div>${mbConflicts(p).length?`<div class="small" style="margin-top:6px;color:var(--warn)">${mbConflicts(p).map(c => `<b>${MB_FACT_TYPES[c.type]||c.type}</b>: ${c.facts.map(f => esc(f.normalized)+' ('+MB_AUTH[f.authority][0].toLowerCase()+')').join(' vs ')}`).join('<br>')}</div>`:''}</div>
      <div class="card" style="margin-top:12px"><div class="mb-list-hd"><h3>Score</h3><span class="small muted">guides priority, not the decision</span></div>${['location','basis','upside','htc','zoning','marketability','complexity','financing','risk'].map(k => `<div class="mb-score"><span>${k}</span><input type="range" min="1" max="10" value="${d.score[k]||5}" data-mbscore="${k}" ${dis}><b>${d.score[k]||5}</b></div>`).join('')}</div>
    </div></div>`; }

function mbActivity(d, p, ed){ const ev = []; d.activities.forEach(a => ev.push({t:a.t, kind:a.dir==='in'?'inbound':a.dir==='out'?'outbound':a.kind, group:a.dir||a.kind==='gov'?'broker':'notes', text:a.text, by:a.by})); d.statusHistory.forEach(s => ev.push({t:s.at, kind:'stage', group:'stage', text:`${MB_STATUS[s.from]||s.from} → ${MB_STATUS[s.to]||s.to}${s.why?' — '+s.why:''}`, by:s.by})); d.listings.forEach(e => e.priceHistory.forEach(x => ev.push({t:x.at, kind:'price', group:'price', text:`${x.type}: ${x.prev?mbMM(x.prev)+' → ':''}${x.next?mbMM(x.next):'removed'} (${x.source})`, by:'System'}))); p.govEvents.forEach(g => ev.push({t:g.t, kind:'government', group:'gov', text:g.text, by:'System'})); d.scenarios.forEach(s => ev.push({t:s.at, kind:'underwriting', group:'uw', text:`${s.name}: price ${mbMM(s.inputs.price)}, IRR ${(mbCalc(s.inputs).irr*100).toFixed(0)}%`, by:s.by})); d.reactivations.forEach(r => ev.push({t:r.at, kind:'reactivated', group:'stage', text:`Triggers met: ${r.triggers.join('; ')}`, by:'System'})); ev.sort((a,b)=>b.t.localeCompare(a.t));
  const groups = [['all','All'],['broker','Broker'],['notes','Notes'],['price','Price'],['gov','Government'],['uw','Underwriting'],['stage','Stage']]; const list = ev.filter(e => mbActFilter==='all' || e.group===mbActFilter || (mbActFilter==='broker' && ['inbound','outbound','call','email','meeting'].includes(e.kind)));
  const cls = k => ({inbound:'info', outbound:'neutral', price:'ok', government:'bad', stage:'neutral', decision:'warn', underwriting:'info', reactivated:'info', gov:'bad'})[k]||'neutral';
  return `<div class="card"><div class="mb-list-hd"><h3>Activity</h3><div class="chips" style="margin-left:auto">${groups.map(([k,l]) => `<button class="chip ${mbActFilter===k?'on':''}" data-actf="${k}">${l}</button>`).join('')}</div></div>${list.map(e => `<div class="logline"><span>${fmtL(e.t.slice(0,10))}</span><span class="pill ${cls(e.kind)}" style="margin-right:6px">${e.kind}</span><span>${esc(e.text)} <span class="muted">— ${esc(e.by)}</span></span></div>`).join('')||'<div class="muted small">Nothing yet.</div>'}</div>`; }

function mbListingTab(d, p, ed){ return `<div class="mb-two"><div>${d.listings.slice().reverse().map((e, i) => `<div class="card" style="margin-bottom:12px"><div class="mb-list-hd"><h3>${MB_SOURCES[e.source]||e.source}${e.brokerage?' · '+esc(e.brokerage):''}${e.brokerName?' · '+esc(e.brokerName):''}</h3><span class="pill ${e.status==='active'?'ok':'neutral'}">${e.status}</span><span class="small muted" style="margin-left:auto">listed ${fmt(e.listingDate)}${e.offMarketDate?' · removed '+fmt(e.offMarketDate):''} · ${mbDays(e.listingDate, e.offMarketDate||e.soldDate||mbToday())} days</span></div>${e.url?`<div class="small" style="margin-bottom:6px"><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.url)}</a>${e.listingId?' · id '+esc(e.listingId):''}</div>`:''}${mbTW(`<table class="t"><thead><tr><th>Date</th><th>Event</th><th style="text-align:right">Price</th><th style="text-align:right">Change</th><th>Source</th></tr></thead><tbody>${e.priceHistory.map(x => `<tr><td>${fmt(x.date)}</td><td>${x.type}</td><td class="money">${x.next?mbMM(x.next):'—'}</td><td class="money" style="color:${x.prev&&x.next<x.prev?'var(--ok)':x.prev&&x.next>x.prev?'var(--bad)':'inherit'}">${x.prev&&x.next?`${x.next-x.prev<0?'−':'+'}${mbMM(Math.abs(x.next-x.prev))} · ${((x.next-x.prev)/x.prev*100).toFixed(1)}%`:'—'}</td><td class="dim">${esc(x.source)}</td></tr>`).join('')}</tbody></table>`)}${i===0 && ed && e.status==='active' ? `<div class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap"><input id="mb-newprice" class="btn" style="width:150px;text-align:left" placeholder="New asking, e.g. 7.2M"><button class="btn sm" id="mb-price-go">Record price change</button><button class="btn sm" id="mb-removed">Listing removed</button><button class="btn sm" id="mb-relist">Relisted…</button><button class="btn sm" id="mb-sold">Sold…</button></div>`:''}</div>`).join('')}<div class="small muted">Asking price only changes through a price event. Relisting starts a new episode on the same property; cumulative DOM keeps every marketing period.</div></div>
  <div><div class="card" style="margin-bottom:12px"><h3>Days on market</h3>${mbTW(`<table class="t"><tbody><tr><td class="dim">Source DOM</td><td>${mbCurrentEpisode(d)?.sourceDom ?? '<span class="muted">not reported</span>'}</td></tr><tr><td class="dim">Calculated DOM</td><td>${mbDOM(d)} days</td></tr><tr><td class="dim">Cumulative DOM</td><td>${mbCDOM(d)} days across ${DB.deals.filter(z=>z.propertyId===p.id).flatMap(z=>z.listings).length} episode(s)</td></tr></tbody></table>`)}</div><div class="card"><h3>Sale history</h3>${mbTW(`<table class="t"><thead><tr><th>Date</th><th style="text-align:right">Price</th><th>Parties</th><th>Source</th></tr></thead><tbody>${p.saleHistory.map(s => `<tr><td>${fmt(s.date)}</td><td class="money">${mbMM(s.price)}</td><td class="small">${esc(s.seller)} → ${esc(s.buyer)}${s.armsLength===false?' <span class="pill warn">possibly not arm\'s-length</span>':''}</td><td class="dim">${esc(s.source||'')}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No recorded transfers entered.</td></tr>'}</tbody></table>`)}${ed?`<div class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap"><input type="date" id="mb-sale-date" class="btn"><input id="mb-sale-price" class="btn" style="width:120px" placeholder="Price"><input id="mb-sale-parties" class="btn" style="flex:1" placeholder="Seller → Buyer"><label class="small"><input type="checkbox" id="mb-sale-nal"> not arm's-length</label><button class="btn sm" id="mb-sale-add">Add (ACRIS)</button></div>`:''}</div></div></div>`; }

function mbUWTab(d, p, ed){ const s = d.scenarios[d.scenarios.length-1]; const inputs = s ? s.inputs : mbScenarioDefaults(d); const r = mbCalc(inputs); const rows = [['price','Purchase price ($)'],['closingPct','Closing costs (%)'],['devSF','Development area (SF)'],['hardPerSF','Hard cost ($/SF)'],['softPct','Soft cost (% of hard)'],['ltc','Loan-to-cost (%)'],['ratePct','Interest rate (%)'],['months','Hold (months)'],['exitPerSF','Exit value ($/SF)']];
  const bld = mbNum(p,'buildingSF'), max = mbNum(p,'buildableSF'), prac = mbNum(p,'practicalSF');
  return `<div class="grid3"><div><div class="card" style="margin-bottom:12px"><div class="hd" style="display:flex;align-items:baseline;gap:8px"><h3 style="margin:0">Level 1 — Quick screen</h3><span class="small muted">${s?`${esc(s.name)} · ${fmtL(s.at.slice(0,10))} · ${esc(s.by)}`:'no scenario yet'}</span>${ed?`<button class="btn sm" id="mb-uw-new" style="margin-left:auto">New scenario at current ask</button>`:''}</div><div class="grid2"><div><div class="f"><label>Strategy</label><input id="uw-strategy" value="${esc(inputs.strategy||'')}" ${ed?'':'disabled'} placeholder="Residential conversion, mixed-use, vertical enlargement, HTC rehab…"></div>${rows.map(([k,l]) => `<div class="f" style="display:grid;grid-template-columns:1fr 130px;align-items:center;gap:8px"><label style="margin:0">${l}</label><input type="number" data-uw="${k}" value="${inputs[k]}" ${ed?'':'disabled'} step="${['closingPct','softPct','ltc','ratePct'].includes(k)?'0.5':'1'}"></div>`).join('')}${ed?`<button class="btn sm primary" id="mb-uw-save">Recalculate & save</button>`:''}</div><div><table class="t"><tbody>${[['Purchase + closing', mbM((+inputs.price||0)+r.closing)],['Hard cost', mbM(r.hard)],['Soft cost', mbM(r.soft)],['Loan', `${mbM(r.loan)} <span class="small muted">${inputs.ltc}% LTC</span>`],['Interest / carry', mbM(r.interest)],['Total cost', `<b>${mbM(r.total)}</b>`],['Equity required', mbM(r.equity)],['Exit value', `<b>${mbM(r.exit)}</b>`],['Profit', `<b style="color:${r.profit>=0?'var(--ok)':'var(--bad)'}">${mbM(r.profit)}</b>`],['Margin on exit', `${(r.margin*100).toFixed(1)}%`],['Projected IRR (equity)', r.irr>=0 ? `<b>${(r.irr*100).toFixed(1)}%</b>` : '<span class="pill bad">negative</span>']].map(([k,v]) => `<tr><td class="dim">${k}</td><td class="money">${v}</td></tr>`).join('')}</tbody></table><div class="small muted" style="margin-top:6px">Quick screen decides whether to spend more time. Level 2 (detailed) and Level 3 (investment committee) are Phase 2.</div></div></div></div>
  ${d.scenarios.length>1?`<div class="card"><h3>Prior scenarios</h3><table class="t"><thead><tr><th>Scenario</th><th style="text-align:right">Price</th><th style="text-align:right">Total cost</th><th style="text-align:right">Exit</th><th style="text-align:right">Profit</th><th style="text-align:right">IRR</th></tr></thead><tbody>${d.scenarios.slice().reverse().map(x => { const q = mbCalc(x.inputs); return `<tr><td>${esc(x.name)}<div class="sub" style="margin-left:0">${fmtL(x.at.slice(0,10))} · ${esc(x.by)}</div></td><td class="money">${mbMM(x.inputs.price)}</td><td class="money">${mbMM(q.total)}</td><td class="money">${mbMM(q.exit)}</td><td class="money">${mbMM(q.profit)}</td><td class="money">${q.irr>=0?(q.irr*100).toFixed(1)+'%':'neg'}</td></tr>`; }).join('')}</tbody></table><div class="small muted">History is never overwritten — each recalculation is a new scenario.</div></div>`:''}</div>
  <div><div class="card"><h3>Development potential</h3><table class="t"><tbody><tr><td class="dim">Existing built area</td><td>${bld?bld.toLocaleString()+' SF':'—'} ${mbFactValue(p,'buildingSF')?`<span class="pill ${MB_AUTH[mbFactValue(p,'buildingSF').authority][1]}">${MB_AUTH[mbFactValue(p,'buildingSF').authority][0]}</span>`:''}</td></tr><tr><td class="dim">Max theoretical floor area</td><td>${max?max.toLocaleString()+' SF':'—'} <span class="pill info">ERP calculated</span></td></tr><tr><td class="dim">Apparent unused rights</td><td>${max&&bld?Math.max(0,max-bld).toLocaleString()+' SF':'—'}</td></tr><tr><td class="dim">Practical buildable</td><td>${ed?`<input type="number" id="mb-prac" value="${prac||''}" placeholder="architect / user" style="width:120px"> SF`:(prac?prac.toLocaleString()+' SF':'—')} <span class="pill neutral">professional assumption</span></td></tr></tbody></table><div class="small muted" style="margin-top:6px">Official zoning facts, ERP calculations and professional assumptions are always labelled differently.</div></div></div></div>`; }

function mbWatchTab(d, p, ed){ const snap = d.passedSnapshot; const now = mbSnapshot(d); const last = d.reactivations[d.reactivations.length-1];
  const changed = snap ? [['Asking price', mbMM(snap.ask), mbMM(now.ask), snap.ask&&now.ask?mbM(now.ask-snap.ask):'—'],['Price / existing SF', snap.psfExisting?mbM(snap.psfExisting):'—', now.psfExisting?mbM(now.psfExisting):'—', snap.psfExisting&&now.psfExisting?((now.psfExisting-snap.psfExisting)/snap.psfExisting*100).toFixed(1)+'%':'—'],['Price / buildable SF', snap.psfBuildable?mbM(snap.psfBuildable):'—', now.psfBuildable?mbM(now.psfBuildable):'—', snap.psfBuildable&&now.psfBuildable?((now.psfBuildable-snap.psfBuildable)/snap.psfBuildable*100).toFixed(1)+'%':'—'],['Cumulative DOM', snap.dom+' d', now.dom+' d', '+'+(now.dom-snap.dom)+' d'],['Construction estimate', snap.construction?mbMM(snap.construction):'—', now.construction?mbMM(now.construction):'—', snap.construction&&now.construction?mbM(now.construction-snap.construction):'—'],['Projected exit', snap.exit?mbMM(snap.exit):'—', now.exit?mbMM(now.exit):'—', snap.exit&&now.exit?mbM(now.exit-snap.exit):'—'],['Projected IRR', snap.irr!=null?(snap.irr*100).toFixed(0)+'%':'—', now.irr!=null?(now.irr*100).toFixed(0)+'%':'—', snap.irr!=null&&now.irr!=null?((now.irr-snap.irr)*100).toFixed(0)+' pts':'—']] : [];
  return `<div class="grid3"><div>${snap?`<div class="card" style="margin-bottom:12px"><h3>What changed since we passed? <span class="small muted">passed ${fmtL(snap.date)} — ${esc(d.passReason)}</span></h3><table class="t"><thead><tr><th>Metric</th><th style="text-align:right">When passed</th><th style="text-align:right">Today</th><th style="text-align:right">Change</th></tr></thead><tbody>${changed.map(r => `<tr><td>${r[0]}</td><td class="money">${r[1]}</td><td class="money">${r[2]}</td><td class="money">${r[3]}</td></tr>`).join('')}</tbody></table>${last?`<div class="small" style="margin-top:6px;color:var(--accent)">Reactivated ${fmtL(last.at.slice(0,10))} — ${last.triggers.map(esc).join('; ')}</div>`:''}</div>`:''}
    <div class="card"><h3>Revisit triggers <span class="small muted">the deal reactivates when ${d.triggerLogic==='ALL'?'ALL':'ANY'} active trigger${d.triggerLogic==='ALL'?'s are':' is'} met</span></h3>${ed?`<div class="row" style="gap:6px;align-items:center;margin-bottom:8px"><span class="small">Logic</span><select id="mb-logic" class="btn sm"><option value="ANY" ${d.triggerLogic==='ANY'?'selected':''}>ANY</option><option value="ALL" ${d.triggerLogic==='ALL'?'selected':''}>ALL</option></select></div>`:''}<table class="t"><tbody>${d.triggers.map(t => `<tr><td><label><input type="checkbox" data-mbtg-active="${t.id}" ${t.active?'checked':''} ${ed?'':'disabled'}> ${MB_TRIGGER_TYPES[t.type]}</label></td><td>${['relist','broker','historic'].includes(t.type)?'<span class="muted">event</span>':(t.type==='date'?fmtL(t.value):t.type==='price'?mbMM(+t.value):t.type==='psf'?mbM(+t.value):t.value)}</td><td>${mbTriggerHit(d,t)?'<span class="pill ok">condition met</span>':'<span class="pill neutral">not yet</span>'}${t.triggeredAt?`<div class="small muted">fired ${fmtL(t.triggeredAt.slice(0,10))}</div>`:''}</td><td>${ed?`<span class="rm" data-mbtg-del="${t.id}">✕</span>`:''}</td></tr>`).join('')||'<tr><td class="muted" colspan="4">No triggers defined.</td></tr>'}</tbody></table>${ed?`<div class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap"><select id="mb-tg-type" class="btn sm">${Object.entries(MB_TRIGGER_TYPES).map(([k,l]) => `<option value="${k}">${l}</option>`).join('')}</select><input id="mb-tg-val" class="btn sm" style="width:140px" placeholder="value, e.g. 7000000"><button class="btn sm" id="mb-tg-add">Add trigger</button></div>`:''}</div></div>
  <div><div class="card" style="margin-bottom:12px"><h3>${d.status==='watch'||d.status==='passed'?'Decision':'Pass on this deal'}</h3>${d.passReason?`<div class="small" style="margin-bottom:6px"><b>${esc(d.passReason)}</b>${d.passNote?' — '+esc(d.passNote):''}</div>`:''}${ed && !['acquired','closed'].includes(d.status) ? `<div class="f"><label>Pass reason (required)</label><select id="mb-pass-reason" class="btn">${MB_PASS_REASONS.map(r => `<option ${d.passReason===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="f"><label>Note</label><input id="mb-pass-note" value="${esc(d.passNote)}" placeholder="e.g. seller anchored at $8M; our number is ≤ $7M"></div><label class="small" style="display:block;margin:6px 0"><input type="checkbox" id="mb-pass-monitor" checked> Keep monitoring (Watch) — reactivate when triggers are met</label><div class="row" style="gap:6px"><button class="btn sm primary" id="mb-pass-go">${d.status==='watch'?'Update':'Pass'}</button>${d.status==='watch'||d.status==='passed'||d.status==='reactivated'?`<button class="btn sm" id="mb-resume">Resume pursuing</button>`:''}${d.status==='watch'?`<button class="btn sm" id="mb-close">Close (stop monitoring)</button>`:''}</div>`:''}</div>
  <div class="card"><h3>Deal memory</h3><p class="small muted" style="margin:0">Preserved when this property resurfaces: prior underwriting (${d.scenarios.length}), offers, broker communications (${d.activities.filter(a=>a.dir).length}), setup sheets, zoning/HTC research, DOB/LPC research (${p.permits.length} jobs, ${p.violations.length} violations), price events (${d.listings.reduce((s,e)=>s+e.priceHistory.length,0)}), sale history (${p.saleHistory.length}), reasons for passing, thesis, decisions.</p></div></div></div>`; }

function mbGovTab(d, p, ed){ const openV = p.violations.filter(v => !['Dismissed','Closed','Certified'].includes(v.normalizedStatus)); const badge = f => `<span class="pill ${MB_AUTH[f.authority][1]}" title="${esc([f.agency,f.dataset,f.recordId].filter(Boolean).join(' · '))}">${MB_AUTH[f.authority][0]}</span>`;
  const secs = MB_GOV_SECTIONS.map(([k, name, types]) => { const fs = p.facts.filter(f => types.includes(f.type) && !f.superseded); const last = fs.map(f=>f.retrievedAt).sort().pop(); return `<div class="card" style="margin-bottom:10px"><div class="hd" style="display:flex;align-items:baseline;gap:8px"><h3 style="margin:0;font-size:13.5px">${name}</h3><span class="small muted">last checked ${last?fmt(last):'never'}</span>${ed?`<button class="btn sm" data-mbrefresh="${k}" style="margin-left:auto">Refresh now</button>`:''}</div>${fs.length?`<table class="t"><tbody>${types.filter(t => fs.some(f=>f.type===t)).map(t => { const all = fs.filter(f=>f.type===t); const disp = mbFactValue(p, t); return `<tr><td class="dim" style="width:200px">${MB_FACT_TYPES[t]||t}</td><td>${all.sort((a,b)=>MB_AUTH_RANK[a.authority]-MB_AUTH_RANK[b.authority]).map(f => `<div style="${f===disp?'':'opacity:.7'}">${esc(f.normalized)} ${badge(f)}${f===disp && all.length>1?' <span class="small muted">display value</span>':''}${f.note?` <span class="small muted">${esc(f.note)}</span>`:''}${f.url?` <a class="small" href="${esc(f.url)}" target="_blank" rel="noopener">source</a>`:''}${f.agency?` <span class="small muted">${esc(f.agency)} · ${fmt(f.retrievedAt)}</span>`:''}</div>`).join('')}</td></tr>`; }).join('')}</tbody></table>`:'<div class="small muted">No record retrieved. The check is recorded as not run — never substituted with third-party data.</div>'}</div>`; }).join('');
  return `<div class="grid3"><div>${mbConflicts(p).length?`<div class="card" style="margin-bottom:10px;border-color:var(--warn)"><h3>Data conflicts <span class="small muted">official vs broker / listing</span></h3>${mbConflicts(p).map(c => { const g = c.facts.find(f=>f.authority==='gov'); const b = c.facts.find(f=>f.authority!=='gov'); return `<div class="small" style="margin-bottom:4px"><b>${MB_FACT_TYPES[c.type]||c.type}</b>: ${c.facts.map(f => `${badge(f)} ${esc(f.normalized)}`).join(' vs ')}${(()=>{ if(!g||!b) return ''; const gv=parseFloat(String(g.normalized).replace(/[^\d.]/g,'')), bv=parseFloat(String(b.normalized).replace(/[^\d.]/g,'')); if(isNaN(gv)||isNaN(bv)) return ''; const diff=Math.abs(gv-bv); return ` — difference ${['annualTax','assessed'].includes(c.type)?mbM(diff):diff.toLocaleString()}${['lotSF','buildingSF','buildableSF','practicalSF'].includes(c.type)?' SF':''} (${(diff/gv*100).toFixed(1)}%)`; })()}</div>`; }).join('')}</div>`:''}${secs}
    <div class="card" style="margin-bottom:10px"><div class="hd" style="display:flex;align-items:baseline;gap:8px"><h3 style="margin:0">DOB jobs & permits</h3><span class="small muted">${p.permits.length} filing(s)</span></div>${p.permits.map(x => `<div style="border-top:1px solid var(--rule-2);padding:8px 0"><div class="row" style="gap:8px;align-items:center;flex-wrap:wrap"><b>${esc(x.agency)} ${esc(x.job)}</b><span class="pill info">${esc(x.status)}</span><span class="small muted">${esc(x.type)}${x.workType?' · '+esc(x.workType):''} · filed ${fmt(x.filedDate)}${x.issuedDate?' · issued '+fmt(x.issuedDate):''}${x.expirationDate?' · expires '+fmt(x.expirationDate):''} · ${mbDays(x.filedDate)} days since filing</span></div><div class="small" style="margin-top:4px"><span class="pill ok">Official</span> ${esc(x.officialDesc||'—')}</div><div class="small muted" style="margin-top:2px"><span class="pill neutral">Interpretation</span> ${esc(x.plainEnglish)}</div><div class="small muted">Applicant ${esc(x.applicant||'—')} · owner on filing ${esc(x.ownerOnFiling||'—')}${x.source?' · '+esc(x.source):''} · checked ${fmt(x.lastChecked)}</div></div>`).join('')||'<div class="small muted">No jobs recorded.</div>'}${ed?`<details style="margin-top:8px"><summary class="small" style="cursor:pointer">Record a DOB filing from the official record</summary><div class="grid2" style="margin-top:6px"><input id="pm-job" class="btn" placeholder="Job / application number"><select id="pm-status" class="btn">${MB_PERMIT_STATUS.map(s=>`<option>${s}</option>`).join('')}</select><input id="pm-type" class="btn" placeholder="Filing type (Alt-1, Alt-2, NB, DM…)"><input id="pm-work" class="btn" placeholder="Work type"><input id="pm-date" type="date" class="btn" value="${mbToday()}"><input id="pm-applicant" class="btn" placeholder="Applicant"></div><textarea id="pm-desc" class="btn" style="width:100%;height:56px;text-align:left;margin-top:6px" placeholder="Official job description — paste from DOB"></textarea><input id="pm-plain" class="btn" style="width:100%;text-align:left;margin-top:6px" placeholder="Plain-English interpretation (optional; labelled as interpretation)"><button class="btn sm" id="pm-add" style="margin-top:6px">Add filing</button></details>`:''}</div>
    <div class="card"><div class="hd" style="display:flex;align-items:baseline;gap:8px"><h3 style="margin:0">Violations & enforcement</h3><span class="small muted">${openV.length} open · ${p.violations.length-openV.length} resolved / historical</span></div>${p.violations.slice().sort((a,b)=>(a.severity==='RED'?0:a.severity==='YELLOW'?1:2)-(b.severity==='RED'?0:b.severity==='YELLOW'?1:2)).map(v => `<div style="border-top:1px solid var(--rule-2);padding:8px 0"><div class="row" style="gap:8px;align-items:center;flex-wrap:wrap"><span class="pill ${v.severity==='RED'?'bad':v.severity==='YELLOW'?'warn':'ok'}">${v.severity}</span><b>${esc(v.agency)} ${esc(v.number)}</b><span class="pill ${['Dismissed','Closed','Certified'].includes(v.normalizedStatus)?'neutral':'warn'}">${esc(v.normalizedStatus)}</span><span class="small muted">official status “${esc(v.officialStatus||'—')}” · ${esc(v.type||'')} · issued ${fmt(v.issueDate)}${v.hearingDate?' · hearing '+fmt(v.hearingDate):''}${v.penalty?' · penalty '+mbM(v.penalty):''}${v.due?' · due '+mbM(v.due):''}</span></div><div class="small" style="margin-top:4px"><span class="pill ok">Official</span> ${esc(v.officialDesc||'—')}</div><div class="small muted" style="margin-top:2px"><span class="pill neutral">Interpretation</span> ${esc(v.plainEnglish)}</div><div class="small muted">Severity: ${esc(v.severityReason)}${v.relatedJob?` · related job ${esc(v.relatedJob)} <span class="pill neutral">system-matched likely relationship</span>`:''}${v.source?' · '+esc(v.source):''} · checked ${fmt(v.lastChecked)}</div></div>`).join('')||'<div class="small muted">No violations recorded.</div>'}${ed?`<details style="margin-top:8px"><summary class="small" style="cursor:pointer">Record a violation from the official record</summary><div class="grid2" style="margin-top:6px"><select id="vi-agency" class="btn"><option>DOB</option><option>OATH/ECB</option><option>HPD</option><option>FDNY</option><option>DEP</option></select><input id="vi-num" class="btn" placeholder="Agency violation number"><input id="vi-type" class="btn" placeholder="Type / class"><select id="vi-status" class="btn">${MB_VIOL_STATUS.map(s=>`<option>${s}</option>`).join('')}</select><input id="vi-date" type="date" class="btn" value="${mbToday()}"><input id="vi-penalty" class="btn" type="number" placeholder="Penalty / amount due"></div><textarea id="vi-desc" class="btn" style="width:100%;height:56px;text-align:left;margin-top:6px" placeholder="Official description — paste from the agency record"></textarea><input id="vi-official" class="btn" style="width:100%;text-align:left;margin-top:6px" placeholder="Agency's own status wording (e.g. ACTIVE, RESOLVE)"><input id="vi-plain" class="btn" style="width:100%;text-align:left;margin-top:6px" placeholder="Plain-English interpretation (optional)"><button class="btn sm" id="vi-add" style="margin-top:6px">Add violation</button></details>`:''}<div class="small muted" style="margin-top:8px">Internal severity (RED / YELLOW / GREEN) never replaces the agency's classification and always explains why it was assigned.</div></div></div>
  <div>${ed?`<div class="card" style="margin-bottom:10px"><h3>Add a fact with provenance</h3><div class="f"><label>Field</label><select id="ft-type" class="btn">${Object.entries(MB_FACT_TYPES).map(([k,l]) => `<option value="${k}">${l}</option>`).join('')}</select></div><div class="f"><label>Value as the source states it</label><input id="ft-raw" class="btn" style="width:100%;text-align:left" placeholder="e.g. R6B, 4,850, 3-family"></div><div class="f"><label>Source authority</label><select id="ft-auth" class="btn">${Object.entries(MB_AUTH).filter(([k])=>k!=='erp').map(([k,[l]]) => `<option value="${k}">${l}</option>`).join('')}</select></div><div class="f"><label>Agency / system / dataset</label><input id="ft-agency" class="btn" style="width:100%;text-align:left" placeholder="e.g. NYC DOB · Certificate of Occupancy"></div><div class="f"><label>Record id / URL</label><input id="ft-url" class="btn" style="width:100%;text-align:left" placeholder="optional"></div><button class="btn sm primary" id="ft-add">Add fact</button><div class="small muted" style="margin-top:6px">Each fact keeps agency, dataset, record id, URL, retrieved date, raw value, normalized value, verification and interpretation status. Conflicts are created automatically when sources disagree.</div></div>
  <div class="card" style="margin-bottom:10px"><h3>Record a government change</h3><div class="f"><select id="ge-kind" class="btn" style="width:100%"><option value="permit">New DOB application filed</option><option value="permit">Permit issued / expired</option><option value="permit">Job signed off / Letter of Completion</option><option value="violation">New DOB / OATH / HPD violation</option><option value="violation">Violation resolved / judgment changed</option><option value="order">Stop work or vacate order</option><option value="co">Certificate of Occupancy changed</option><option value="transfer">New recorded transfer</option><option value="historic">Landmark / historic status change</option></select></div><input id="ge-text" class="btn" style="width:100%;text-align:left" placeholder="What the official record now says"><button class="btn sm" id="ge-add" style="margin-top:6px">Record change</button><div class="small muted" style="margin-top:6px">Becomes a Deal Timeline event and an alert on the dashboard; old and new values are preserved.</div></div>`:''}
  <div class="card"><h3>Regulatory snapshot</h3><table class="t"><tbody>${[['Legal use', mbFactValue(p,'legalUse')?.normalized||'—'],['Listing / broker use', p.facts.find(f=>f.type==='units'&&['broker','listing'].includes(f.authority))?p.facts.find(f=>f.type==='units'&&['broker','listing'].includes(f.authority)).normalized+'-family (broker)':'—'],['Conflicts', mbConflicts(p).length],['Zoning', mbFactValue(p,'zoning')?.normalized||'—'],['Historic', mbFactValue(p,'landmark')?.normalized||'—'],['HTC screening', mbFactValue(p,'htc')?.normalized||'Needs review'],['Open violations', `${openV.length}${openV.some(v=>v.severity==='RED')?' <span class="pill bad">RED</span>':''}`],['Open DOB jobs', p.permits.filter(x=>!['Signed off','Letter of Completion','Withdrawn','Expired','Disapproved'].includes(x.status)).length],['Stop work / vacate', p.govEvents.some(g=>g.kind==='order')?'<span class="pill bad">yes</span>':'none recorded'],['Annual property tax', mbFactValue(p,'annualTax')?.normalized||'—']].map(([k,v]) => `<tr><td class="dim">${k}</td><td>${v}</td></tr>`).join('')}</tbody></table><div class="small muted" style="margin-top:6px">HTC is shown as Likely / Potential / Unlikely / Needs review — never “eligible” from automated screening alone.</div></div></div></div>`; }


/* ---------- property record page ---------- */
function mbOpenProp(id){ mbPropId = id; view = 'mbprop'; render(); mbTop(); }
function renderMBProp(){ const p = DB.properties.find(x => x.id===mbPropId) || DB.properties[0]; if (!p){ $('#mb-prop').innerHTML = '<div class="card muted">No property selected.</div>'; return; } mbPropId = p.id; const ed = mbCanEdit();
  const ds = DB.deals.filter(d => d.propertyId===p.id).sort((a,b)=>(b.lastActivityAt||'').localeCompare(a.lastActivityAt||'')); const d0 = ds[0] || {id:'', status:'', docs:[], score:{}, broker:{}, triggers:[], scenarios:[], activities:[], listings:[], reactivations:[], statusHistory:[]};
  const last = p.saleHistory[p.saleHistory.length-1]; const openV = p.violations.filter(v => !['Dismissed','Closed','Certified'].includes(v.normalizedStatus)); const openJ = p.permits.filter(x => !['Signed off','Letter of Completion','Withdrawn','Expired','Disapproved'].includes(x.status)).length; const conf = mbConflicts(p).length;
  const fv = t => mbFactValue(p,t)?.normalized || '—';
  const cells = [['Zoning', fv('zoning'), fv('far')!=='—'?'FAR '+fv('far'):''], ['Lot / existing SF', `${mbNum(p,'lotSF')?mbNum(p,'lotSF').toLocaleString():'—'} / ${mbNum(p,'buildingSF')?mbNum(p,'buildingSF').toLocaleString():'—'}`, mbNum(p,'buildableSF')?'max '+mbNum(p,'buildableSF').toLocaleString()+' SF':''], ['Units / legal use', fv('units'), fv('legalUse')], ['Historic', fv('landmark'), 'HTC: '+fv('htc')], ['Last sale', last?mbMM(last.price):'—', last?fmt(last.date):'none recorded'], ['Annual tax', fv('annualTax'), fv('owner')!=='—'?'owner '+fv('owner'):'']];
  const flags = []; if (openV.some(v=>v.severity==='RED')) flags.push(['bad', `${openV.filter(v=>v.severity==='RED').length} RED violation${openV.filter(v=>v.severity==='RED').length>1?'s':''}`]); else if (openV.length) flags.push(['warn', `${openV.length} open violation${openV.length>1?'s':''}`]); if (conf) flags.push(['warn', `${conf} data conflict${conf>1?'s':''}`]); if (openJ) flags.push(['info','open DOB job']); if (p.ownedBy) flags.push(['ok','owned by '+p.ownedBy]); if (p.govEvents.some(g=>g.kind==='order')) flags.push(['bad','stop work / vacate order']);
  const dealRow = d => `<tr class="click" data-mbopen="${d.id}"><td><b>${d.number}</b></td><td><span class="pill ${mbStatusCls(d)}">${MB_STATUS[d.status]}</span></td><td class="money">${mbMM(mbAsk(d))}</td><td>${esc(d.broker.name||'—')}</td><td class="small">${esc(d.passReason||d.nextAction||d.waitingFor||'')}</td><td class="dim">${d.lastActivityAt?fmtL(d.lastActivityAt.slice(0,10)):'—'}</td></tr>`;
  $('#mb-prop').innerHTML = `<div class="mb-dh"><div class="mb-dh-l"><a href="#" id="mb-back" class="mb-back">← Properties</a><h2>${esc(p.address)}</h2><div class="small muted">${esc([p.neighborhood,p.borough].filter(Boolean).join(', '))}${p.bbl?' · BBL '+esc(p.bbl):''}${p.bin?' · BIN '+esc(p.bin):''}${p.aliases?.length?' · also '+p.aliases.map(esc).join(', '):''}</div></div><div class="mb-dh-r">${ed && !mbActiveDeal(p.id)?`<button class="btn primary" id="mb-prop-newdeal">New deal on this property</button>`:''}${ds[0]?`<button class="btn" data-mbopen="${ds[0].id}">Open ${ds[0].number}</button>`:''}</div></div>
    <div class="mb-kf">${cells.map(([k,v,s]) => `<div><span>${k}</span><b>${v}</b><i>${s||'&nbsp;'}</i></div>`).join('')}</div>${flags.length?`<div class="mb-flags">${flags.map(([c,t]) => `<span class="pill ${c}">${t}</span>`).join('')}</div>`:''}
    <div class="card" style="margin-bottom:12px"><div class="mb-list-hd"><h3>Deals on this property</h3><span class="small muted">${ds.length?'every evaluation is kept — underwriting, broker history, pass reasons':'never evaluated'}</span></div>${ds.length?mbTW(`<table class="t"><thead><tr><th>Deal</th><th>Stage</th><th style="text-align:right">Ask</th><th>Broker</th><th>Reason / next</th><th>Last activity</th></tr></thead><tbody>${ds.map(dealRow).join('')}</tbody></table>`):''}</div>
    ${mbGovTab(d0, p, ed)}`;
  $('#mb-back').onclick = e => { e.preventDefault(); view = 'mbprops'; render(); };
  $('#mb-prop-newdeal')?.addEventListener('click', () => mbCaptureModal(p.address));
  mbWireDealTab(d0, p, ed); }

/* ---------- mobile estimate editor (construction template) ---------- */
const ctIsMobile = () => window.innerWidth <= 760;
let ctOrganize = false, ctSheetLine = null;
const ctFirstLine = s => (String(s||'').split('\n').map(x=>x.trim()).filter(Boolean)[0]||'');
function ctMobileList(c, d, editable, kind){ ctNumber(d); const t = docTotal(d); const budget = ctBudget(d);
  const rows = ctOrdered(d).map(l => { const amt = lineAmount(l,d); const n = (l.items||[]).length; return `<div class="ct-m-row ${l.parent?'child':''}" data-ctopen="${l.id}"><span class="ct-m-num">${l.num}</span><div class="ct-m-main"><div class="ct-m-name">${esc(l.item)||'<span class="muted">Untitled line</span>'}</div><div class="ct-m-sub">${esc(ctFirstLine(l.desc))||'<span class="muted">No scope yet</span>'}</div>${n||l.vendor?`<div class="ct-m-meta">${n?`${n} item${n>1?'s':''}`:''}${n&&l.vendor?' · ':''}${esc(l.vendor||'')}</div>`:''}</div><div class="ct-m-amt"><b>${money(amt)}</b>${(+l.qty||1)!==1?`<span>${l.qty} × ${money(l.rate)}</span>`:''}</div>${ctOrganize&&editable?`<div class="ct-m-tools"><button data-ctmove="${l.id}:-1" aria-label="Move up">↑</button><button data-ctmove="${l.id}:1" aria-label="Move down">↓</button><button data-ctrm="${l.id}" aria-label="Remove">✕</button></div>`:'<span class="ct-m-chev">›</span>'}</div>`; }).join('');
  return `<div class="ct ct-m"><div class="ct-m-hd"><span>${d.lines.length} line${d.lines.length===1?'':'s'}</span>${editable?`<button class="ct-m-org ${ctOrganize?'on':''}" data-ctorg>${ctOrganize?'Done organizing':'Organize'}</button>`:''}</div>${rows||'<div class="muted small" style="padding:14px 4px">No lines yet. Add the first one below.</div>'}${editable?`<button class="ct-m-add" data-ctadd>+ Add line item</button>`:''}<div class="small muted" style="margin:6px 4px 0">Budget ${money(budget)} · margin ${t.sub?Math.round((t.sub-budget)/t.sub*100):0}% <span class="muted">(internal)</span></div></div>`; }

function ctLineSheet(c, d, l, editable){ ctSheetLine = l.id; const ro = editable ? '' : 'readonly'; const dis = editable ? '' : 'disabled'; const codes = COST_CODES.map(x => `<option value="${x[0]}" ${l.code===x[0]?'selected':''}>${x[0]} ${esc(x[1])}</option>`).join(''); const n = (l.items||[]).length;
  const sib = d.lines.filter(x => (x.parent||'')===(l.parent||'')); const idx = sib.indexOf(l); const prevTop = !l.parent && idx>0 ? sib[idx-1] : null;
  let s = document.getElementById('ct-sheet'); if (!s){ s = document.createElement('div'); s.id = 'ct-sheet'; s.className = 'ct-sheet'; document.body.appendChild(s); }
  const paint = () => { const amt = lineAmount(l,d); const cost = +l.cost||0; const m = amt && cost ? Math.round((amt-cost)/amt*100) : null;
    s.innerHTML = `<div class="ct-sheet-bar"><button class="ct-sheet-back" data-cts="done">‹ Estimate</button><b>Line ${l.num}</b><button class="ct-sheet-done" data-cts="done">Done</button></div>
      <div class="ct-sheet-body">
        <label class="ct-f"><span>Item</span><input data-csf="item" value="${esc(l.item)}" placeholder="e.g. ROUGH PLUMBING" ${ro} autocapitalize="characters"></label>
        <label class="ct-f"><span>Scope of work <i>prints on the estimate</i></span><textarea data-csf="desc" placeholder="One item per line…" ${ro}>${esc(l.desc||'')}</textarea></label>
        <div class="ct-f3"><label class="ct-f"><span>Quantity</span><input data-csf="qty" type="number" inputmode="decimal" step="any" value="${l.qty}" ${ro}></label><label class="ct-f"><span>Unit</span><input data-csf="unit" value="${esc(l.unit||'')}" placeholder="ls" ${ro}></label><label class="ct-f"><span>Rate</span><input data-csf="rate" type="number" inputmode="decimal" step="0.01" value="${Number.isInteger(+l.rate)?l.rate:(+l.rate).toFixed(2)}" ${ro}></label></div>
        <div class="ct-sheet-total"><span>Line total</span><b>${money(amt)}</b></div>
        <label class="ct-row-toggle"><span>Taxable</span><input type="checkbox" data-csf="taxable" ${l.taxable?'checked':''} ${dis}></label>
        <button class="ct-sheet-btn" data-cts="items"><span>Item list <i>materials & sub-items behind this line</i></span><b>${n||''} ›</b></button>
        <details class="ct-sheet-int" ${l.cost||l.vendor?'open':''}><summary>Internal <i>never printed</i></summary>
          <div class="ct-f3"><label class="ct-f"><span>Budget cost</span><input data-csf="cost" type="number" inputmode="decimal" step="any" value="${l.cost||''}" placeholder="0"></label><label class="ct-f"><span>Margin</span><input value="${m!=null?m+'%':'—'}" readonly class="${m!=null && m<(DB.company.minMargin||20)?'bad':''}"></label><label class="ct-f"><span>Code</span><select data-csf="code"><option value="">—</option>${codes}</select></label></div>
          <label class="ct-f"><span>Vendor / sub</span><input data-csf="vendor" value="${esc(l.vendor||'')}" list="ct-vendors" placeholder="who does it"></label>${(() => { const f = d.status!=='draft' ? lineFin(ctKey(d,l)) : null; return f ? `<div class="ct-fin-m"><div><span>Billed</span><b>${f.billedPct}%</b></div><div><span>Committed</span><b>${money(f.committed)}</b></div><div><span>Actual</span><b>${money(f.actual)}</b></div><div><span>Margin</span><b>${f.marginPct}%</b></div></div><button class="ct-sheet-btn" data-cts="fin"><span>Financial thread <i>invoices, POs, bills on this line</i></span><b>›</b></button>` : ''; })()}${d.status!=='draft'?`<button class="ct-sheet-btn" data-cts="po"><span>Create purchase order <i>for this line</i></span><b>+</b></button>`:''}</details>
        ${editable?`<div class="ct-sheet-pos"><button data-cts="up" ${idx>0?'':'disabled'}>↑ Move up</button><button data-cts="down" ${idx<sib.length-1?'':'disabled'}>↓ Move down</button>${l.parent?`<button data-cts="promote">Make top-level</button>`:(prevTop?`<button data-cts="demote">Make sub-item of ${prevTop.num}</button>`:'')}</div><button class="ct-sheet-del" data-cts="del">Remove line</button>`:''}
      </div>`;
    s.querySelectorAll('[data-csf]').forEach(inp => inp.addEventListener('change', () => { const f = inp.dataset.csf; if (f==='taxable') l.taxable = inp.checked; else if (['qty','rate','cost'].includes(f)) l[f] = +inp.value||0; else l[f] = inp.value; if (f==='item' && !l.code) l.code = ctCode(l); save(); if (f!=='desc' && f!=='item' && f!=='vendor') paint(); }));
    const ta = s.querySelector('textarea'); const grow = () => { ta.style.height = 'auto'; ta.style.height = Math.max(96, ta.scrollHeight+4) + 'px'; }; grow(); ta.addEventListener('input', grow);
    s.querySelectorAll('[data-cts]').forEach(b => b.onclick = () => { const a = b.dataset.cts;
      if (a==='done'){ ctCloseSheet(); save(); render(); return; }
      if (a==='items'){ ctItemsModal(c, d, l, editable); return; }
      if (a==='fin'){ finLineModal(ctKey(d,l)); return; }
      if (a==='po'){ ctCloseSheet(); save(); ctPOPicker(d.projectId||S.id, d.id, ctKey(d,l)); return; }
      if (a==='del'){ if ((l.item||l.desc||l.rate) && !confirm(`Remove line ${l.num}. ${l.item||''}?`)) return; d.lines = d.lines.filter(x => x.id!==l.id && x.parent!==l.id); ctCloseSheet(); save(); render(); return; }
      if (a==='up' || a==='down'){ const j = idx + (a==='up'?-1:1); if (j<0||j>=sib.length) return; const other = sib[j]; const ai = d.lines.indexOf(l), bi = d.lines.indexOf(other); d.lines[ai] = other; d.lines[bi] = l; }
      if (a==='promote'){ l.parent = ''; } if (a==='demote' && prevTop){ l.parent = prevTop.id; d.lines = d.lines.filter(x => x!==l); const kids = d.lines.filter(x => x.parent===prevTop.id); const at = kids.length ? d.lines.indexOf(kids[kids.length-1])+1 : d.lines.indexOf(prevTop)+1; d.lines.splice(at, 0, l); }
      save(); ctNumber(d); ctLineSheet(c, d, l, editable); }); };
  paint(); document.body.classList.add('ct-sheet-open'); if (!l.item) setTimeout(() => s.querySelector('[data-csf=item]')?.focus(), 60); }
function ctCloseSheet(){ const s = document.getElementById('ct-sheet'); if (s) s.remove(); document.body.classList.remove('ct-sheet-open'); ctSheetLine = null; }
function ctWireMobile(c, d, root, editable){ const rerender = () => render();
  root.querySelectorAll('[data-ctopen]').forEach(row => row.addEventListener('click', e => { if (e.target.closest('button')) return; const l = d.lines.find(x => x.id===row.dataset.ctopen); if (l) ctLineSheet(c, d, l, editable); }));
  root.querySelector('[data-ctorg]')?.addEventListener('click', () => { ctOrganize = !ctOrganize; rerender(); });
  root.querySelector('[data-ctadd]')?.addEventListener('click', () => { const l = {id:uid('l'), item:'', desc:'', qty:1, unit:'ls', rate:0, taxable:false, cost:0, vendor:'', code:'', parent:'', items:[]}; d.lines.push(l); ctNumber(d); save(); ctLineSheet(c, d, l, editable); });
  root.querySelectorAll('[data-ctrm]').forEach(b => b.onclick = () => { const l = d.lines.find(x => x.id===b.dataset.ctrm); if ((l.item||l.desc||l.rate) && !confirm(`Remove line ${l.num}. ${l.item||''}?`)) return; d.lines = d.lines.filter(x => x.id!==l.id && x.parent!==l.id); save(); rerender(); });
  root.querySelectorAll('[data-ctmove]').forEach(b => b.onclick = () => { const [id, dir] = b.dataset.ctmove.split(':'); const l = d.lines.find(x => x.id===id); const sib = d.lines.filter(x => (x.parent||'')===(l.parent||'')); const i = sib.indexOf(l); const j = i + (+dir); if (j<0 || j>=sib.length) return; const other = sib[j]; const a = d.lines.indexOf(l), bI = d.lines.indexOf(other); d.lines[a] = other; d.lines[bI] = l; save(); rerender(); }); }

/* ---------- wiring inside the deal page ---------- */
function mbWireDealTab(d, p, ed){
  const auto = (id, key, isDate) => { const el = $(id); if (!el) return; el.addEventListener('change', () => { const v = el.value.trim(); if (d[key]===v) return; if (key==='nextAction'||key==='waitingFor') audit('deal', d.id, key, d[key], v); d[key] = v; d.lastActivityAt = mbNow(); save(); if (view==='mbdeal') { const r = mbReason(d); const hd = document.querySelector('.mb-dh-l .mb-why'); if (hd) hd.remove(); } toast('Saved'); }); };
  auto('#mb-next','nextAction'); auto('#mb-waiting','waitingFor'); auto('#mb-follow','followUpAt'); auto('#mb-review','reviewAt'); auto('#mb-thesis','thesis');
  $('#mb-broker-edit')?.addEventListener('click', () => mbModal('Broker', `${mbF('Name', mbIn('name', d.broker.name))}${mbF('Brokerage', mbIn('brokerage', d.broker.brokerage))}<div class="grid2">${mbF('Email', mbIn('email', d.broker.email, '', 'email'))}${mbF('Phone', mbIn('phone', d.broker.phone, '', 'tel'))}</div>`, {onSubmit: f => { audit('deal', d.id, 'broker', d.broker.name, f.name); d.broker = {name:f.name, brokerage:f.brokerage, email:f.email, phone:f.phone}; save(); render(); }}));
  $('#mb-doc-add')?.addEventListener('click', () => mbModal('Document received', `${mbF('Name', mbIn('name', '', 'e.g. Setup sheet, Rent roll, Survey'))}${mbF('Type', mbSel('kind', ['Setup sheet','Offering memorandum','Rent roll','Survey','Title / ACRIS','Drawings','Photos','Other']))}${mbF('Note', mbIn('note', '', 'optional'))}`, {onSubmit: f => { if (!f.name) return false; mbAddDoc(d, f.name, f.kind, f.note); mbAddActivity(d, 'doc', `${f.kind}: ${f.name}`); save(); render(); }}));
  document.querySelectorAll('[data-mbdocdel]').forEach(x => x.onclick = () => { d.docs = (d.docs||[]).filter(z => z.id!==x.dataset.mbdocdel); save(); render(); });
  document.querySelectorAll('[data-actf]').forEach(b => b.onclick = () => { mbActFilter = b.dataset.actf; render(); });
  document.querySelectorAll('[data-mbscore]').forEach(r => r.addEventListener('change', () => { d.score[r.dataset.mbscore] = +r.value; save(); render(); }));
  $('#mb-price-go')?.addEventListener('click', () => { const v = mbParseMoney($('#mb-newprice').value); if (!v) return; mbPriceChange(d, v, 'Manual'); save(); render(); toast(`Price event recorded — now ${mbMM(v)}`); });
  $('#mb-removed')?.addEventListener('click', () => { const e = mbCurrentEpisode(d); e.status='removed'; e.offMarketDate = mbToday(); e.priceHistory.push({id:uid('pe'), date:mbToday(), prev:e.currentAsk, next:0, type:'Asking price removed', source:'Manual', at:mbNow()}); mbAddActivity(d, 'listing', 'Listing removed from market'); d._relisted = true; mbEvalTriggers(d); save(); render(); });
  $('#mb-relist')?.addEventListener('click', () => mbModal('Relisted', `<div class="grid2">${mbF('New brokerage', mbIn('brokerage'))}${mbF('Broker', mbIn('broker'))}${mbF('Relisting price', mbIn('ask', '', 'e.g. 8.5M'))}${mbF('Source', mbSel('source', Object.entries(MB_SOURCES).map(([k,l])=>[k,l]), 'streeteasy'))}</div>`, {onSubmit: f => { mbRelist(d, {broker:f.broker, brokerage:f.brokerage, ask:mbParseMoney(f.ask), source:MB_SOURCES[f.source]?f.source:'manual'}); save(); render(); }}));
  $('#mb-sold')?.addEventListener('click', () => mbModal('Sold to another buyer', mbF('Sold price (per listing — verify in ACRIS)', mbIn('price', '', 'e.g. 7.9M')), {onSubmit: f => { const pr = mbParseMoney(f.price); if (!pr) return false; const e = mbCurrentEpisode(d); e.status='sold'; e.soldDate = mbToday(); e.soldPrice = pr; e.priceHistory.push({id:uid('pe'), date:mbToday(), prev:e.currentAsk, next:pr, type:'Sold', source:'Manual', at:mbNow()}); p.saleHistory.push({date:mbToday(), price:pr, buyer:'(pending ACRIS)', seller:mbFactValue(p,'owner')?.normalized||'', deed:'', armsLength:true, source:'Listing — verify in ACRIS'}); mbAddActivity(d, 'listing', `Sold at ${mbMM(pr)} per listing — verify recorded consideration in ACRIS.`); if (MB_ACTIVE.includes(d.status)||d.status==='watch') { mbSetStatus(d, 'closed', 'sold to another buyer'); d.nextAction=''; d.waitingFor=''; } save(); render(); }}));
  $('#mb-sale-add')?.addEventListener('click', () => { const pr = mbParseMoney($('#mb-sale-price').value); const dt = $('#mb-sale-date').value; if (!pr||!dt) return; const parts = ($('#mb-sale-parties').value||'').split('→'); p.saleHistory.push({date:dt, price:pr, seller:(parts[0]||'').trim(), buyer:(parts[1]||'').trim(), deed:'', armsLength:!$('#mb-sale-nal').checked, source:'NYC ACRIS (entered)'}); p.saleHistory.sort((a,b)=>a.date.localeCompare(b.date)); audit('property', p.id, 'sale history', '', `${dt} ${pr}`); save(); render(); });
  $('#mb-uw-new')?.addEventListener('click', () => { const last = d.scenarios[d.scenarios.length-1]; mbAddScenario(d, Object.assign({}, last?last.inputs:{}, {price:mbAsk(d)}), `Quick screen (${fmtL(mbToday())})`); if (MB_ACTIVE.includes(d.status) && ['review','responded','contact'].includes(d.status)) mbSetStatus(d, 'underwriting', 'scenario started'); save(); render(); });
  $('#mb-uw-save')?.addEventListener('click', () => { const inputs = Object.assign({}, (d.scenarios[d.scenarios.length-1]||{inputs:mbScenarioDefaults(d)}).inputs); document.querySelectorAll('[data-uw]').forEach(i => inputs[i.dataset.uw] = +i.value||0); inputs.strategy = $('#uw-strategy').value; const s = mbAddScenario(d, inputs, `${inputs.strategy||'Quick screen'} (${fmtL(mbToday())})`); if (['review','responded','contact','new'].includes(d.status)) mbSetStatus(d, 'underwriting', 'quick screen'); if (!d.nextAction) d.nextAction = 'Decide: pursue, pass, or watch'; save(); render(); toast(`Scenario saved — IRR ${(mbCalc(s.inputs).irr*100).toFixed(1)}%`); });
  $('#mb-prac')?.addEventListener('change', e => { const v = +e.target.value||0; p.facts.filter(f=>f.type==='practicalSF').forEach(f=>f.superseded=true); if (v) mbAddFact(p, {type:'practicalSF', raw:String(v), authority:'human', agency:'Architect / user assumption'}); save(); render(); });
  $('#mb-logic')?.addEventListener('change', e => { d.triggerLogic = e.target.value; save(); render(); });
  document.querySelectorAll('[data-mbtg-active]').forEach(c => c.addEventListener('change', () => { const t = d.triggers.find(x=>x.id===c.dataset.mbtgActive); t.active = c.checked; save(); render(); }));
  document.querySelectorAll('[data-mbtg-del]').forEach(x => x.addEventListener('click', () => { d.triggers = d.triggers.filter(t=>t.id!==x.dataset.mbtgDel); save(); render(); }));
  $('#mb-tg-add')?.addEventListener('click', () => { const type = $('#mb-tg-type').value; let value = $('#mb-tg-val').value.trim(); if (['price','psf'].includes(type)) value = mbParseMoney(value); else if (['dom','reduction'].includes(type)) value = parseFloat(value)||0; if (!['relist','broker','historic'].includes(type) && !value) { toast('Enter a value'); return; } d.triggers.push({id:uid('tg'), type, value, active:true}); audit('deal', d.id, 'trigger added', '', `${type} ${value}`); save(); render(); });
  $('#mb-pass-go')?.addEventListener('click', () => { const reason = $('#mb-pass-reason').value; const note = $('#mb-pass-note').value.trim(); const mon = $('#mb-pass-monitor').checked; if (mon && !d.triggers.filter(t=>t.active).length){ if (!confirm('No revisit triggers are defined. Watch with only a scheduled review date?')) return; } mbPass(d, reason, note, mon); save(); render(); toast(mon ? 'On the watchlist' : 'Passed'); });
  $('#mb-resume')?.addEventListener('click', () => { mbSetStatus(d, 'underwriting', 'resumed'); d.nextAction = 'Resume underwriting at current ask'; d.followUpAt = mbToday(); save(); render(); });
  $('#mb-close')?.addEventListener('click', () => { if (!confirm('Stop monitoring this deal? History is kept.')) return; mbSetStatus(d, 'closed', 'monitoring stopped'); save(); render(); });
  document.querySelectorAll('[data-mbrefresh]').forEach(b => b.onclick = () => { const types = MB_GOV_SECTIONS.find(s=>s[0]===b.dataset.mbrefresh)[2]; p.facts.filter(f => types.includes(f.type) && f.authority==='gov').forEach(f => f.retrievedAt = mbToday()); p.govEvents.push({id:uid('ge'), t:mbNow(), date:mbToday(), kind:'check', text:`${MB_GOV_SECTIONS.find(s=>s[0]===b.dataset.mbrefresh)[1]} check recorded — connector not available in this prototype; official-source lookup queued, no third-party data substituted.`}); save(); render(); toast('Check recorded'); });
  $('#ft-add')?.addEventListener('click', () => { const raw = $('#ft-raw').value.trim(); if (!raw) return; mbAddFact(p, {type:$('#ft-type').value, raw, authority:$('#ft-auth').value, agency:$('#ft-agency').value.trim(), url:$('#ft-url').value.trim()}); if ($('#ft-type').value==='landmark' || $('#ft-type').value==='htc'){ DB.deals.filter(z=>z.propertyId===p.id&&z.status==='watch').forEach(z => { z._historicInfo = true; mbEvalTriggers(z); }); } save(); render(); toast('Fact added with provenance'); });
  $('#ge-add')?.addEventListener('click', () => { const t = $('#ge-text').value.trim(); if (!t) return; mbGovChange(p, $('#ge-kind').value, t); save(); render(); toast('Government change recorded'); });
  $('#pm-add')?.addEventListener('click', () => { mbAddPermit(p, {job:$('#pm-job').value.trim(), status:$('#pm-status').value, type:$('#pm-type').value.trim()||'Alteration', workType:$('#pm-work').value.trim(), filedDate:$('#pm-date').value||mbToday(), applicant:$('#pm-applicant').value.trim(), officialDesc:$('#pm-desc').value.trim(), plainEnglish:$('#pm-plain').value.trim(), source:'Entered from official record'}); DB.deals.filter(z=>z.propertyId===p.id&&(MB_ACTIVE.includes(z.status)||z.status==='watch')).forEach(z => mbAddActivity(z, 'gov', `New DOB filing ${$('#pm-job').value.trim()} recorded`)); save(); render(); });
  $('#vi-add')?.addEventListener('click', () => { const desc = $('#vi-desc').value.trim(); const st = $('#vi-status').value; const sev = mbSeverity(desc, st); mbAddViolation(p, {agency:$('#vi-agency').value, number:$('#vi-num').value.trim(), type:$('#vi-type').value.trim(), normalizedStatus:st, officialStatus:$('#vi-official').value.trim(), issueDate:$('#vi-date').value||mbToday(), penalty:+$('#vi-penalty').value||0, due:+$('#vi-penalty').value||0, officialDesc:desc, plainEnglish:$('#vi-plain').value.trim(), severity:sev, source:'Entered from official record'}); save(); render(); });
  if (d.status==='acquired' && !d.sdProjectId && mbCanEdit()){ const c = document.createElement('div'); c.className = 'card'; c.style.marginTop = '12px'; c.innerHTML = `<h3>Convert to owned project</h3><p class="small muted" style="margin:0 0 8px">Ownership is updated on the Property. Optionally create a SmartDesign project that references the Property — facts, drawings, surveys and diligence documents carry over; acquisition economics, offers and broker intelligence stay in Mercer & Bond.</p><button class="btn primary sm" id="mb-sdproj">Create SmartDesign project</button>`; $('#mb-deal').appendChild(c); $('#mb-sdproj').onclick = () => { const pr = mbCreateSDProject(d); save(); toast(`SmartDesign project created: ${pr.project.name}`); render(); }; }
}


const CT_SEED = [{"num": "1", "name": "GENERAL CONDITIONS (ALL LEVELS)", "rate": 31072.8, "qty": 1.0, "scope": "- Maintain all required GC, plumbing, and electrical licenses, certifications, and insurance\n- Interior protection: ZipWall containment, plastic protection, vent protection\n- Daily cleanup of common areas and work zones\n- Walk-up logistics, staging, and material handling\n- Continuous debris management throughout construction", "cost": 22372.42, "unit": "ls"}, {"num": "2", "name": "DEMOLITION", "rate": 42152.25, "qty": 1.0, "scope": "Garden Level (Basement / Garden Unit)\n- Remove Damage around Windows\n- Remove existing base molding in all affected areas\n- Remove existing radiators scheduled for replacement\n\nParlor Floor\n- Selective demolition of kitchen and powder room finishes\n- Remove existing flooring and base molding at living room, dining room, and hallway\n- Remove existing radiators scheduled for replacement\n\nSecond Floor\n- Full demolition of bathroom, including fixtures, wall and floor tile, backer board, and substrates\n- Remove existing flooring and base molding at bedroom, office, family room/den, and hallway\n- Demolish laundry room tile flooring\n- Selective demolition of closet and laundry room partitions per reconfiguration plans\n- Remove existing radiators scheduled for replacement\n- Remove existing stair treads serving second and third floors\n- Remove existing stair carpet, padding, tack strips, and fasteners at stair runs serving second\nand third floors\n\nClarifications / Exclusions\n**joist repair, or structural remediation excluded pending exposure and field verification (TBD)", "vendor": "Angel — crew", "cost": 30500, "unit": "ls"}, {"num": "2-1", "name": "DEBRIS REMOVAL & DEMOLITION HAULING", "rate": 13898.85, "qty": 1.0, "scope": "Scope of Work:\nOngoing removal, hauling, and disposal of demolition debris generated by the work described\nabove.\n\n- Provide labor, protection, and logistics for continuous debris removal from Garden, Parlor,\nSecond, and Third Floors\n- Load, transport, and legally dispose of demolition debris off-site\n- Maintain clean and safe work areas throughout demolition phase\n- Coordinate hauling access and timing per building requirements", "cost": 10007.17, "unit": "ls"}, {"num": "3", "name": "FRAMING & PARTITIONS", "rate": 27310.21, "qty": 1.0, "scope": "Scope of Work:\n- Construct new non-load-bearing partition walls per construction plans at Garden, Parlor,\nSecond, and Third Floors; includes metal or wood studs, top and bottom plates/tracks, rough\nopenings (backing and blocking for fixtures, millwork, and accessories)\n- coordination with plumbing and electrical rough-ins\n\nPrimary Areas:\n- Garden Level: Localized framing and returns around framing\n- Parlor Floor: Framing adjustments at modified openings and localized wall returns at kitchen\nand powder room transitions\n- Second Floor: New partition walls at laundry room enclosure, closet reconfigurations, hallway\nadjustments, and localized bathroom framing and rough openings\n- Third Floor: Localized partition framing and returns around windows", "vendor": "Angel — crew", "cost": 19800, "unit": "ls"}, {"num": "4", "name": "ROUGH PLUMBING", "rate": 32827.5, "qty": 1.0, "scope": "Parlor Floor (Kitchen + Powder Room)\n- Kitchen rough-in: Hot/cold supplies and waste/vent rough-in for sink; dishwasher rough-in\nincluding valve and drain connection; coordinate with cabinet/appliance plan.\n- Powder room rough-in: Rough-in for toilet (cold supply + waste) and lavatory (hot/cold +\nwaste/vent), including shutoff valves at rough stage where feasible.\n\nSecond Floor (Bathroom + Laundry)\n- Bathroom rough-in: Rough-in for toilet, lavatory, and tub/shower including hot/cold supplies,\nwaste/overflow, shower valve rough-in, and vent connections; coordinate exact valve height/centerlines\nwith tile and waterproofing scope.\n- Laundry rough-in: Install washer box (hot/cold supplies) and standpipe drain with venting;\ncoordinate location with laundry millwork and appliance clearances.", "vendor": "Alberto M Plumbing", "cost": 24500, "unit": "ls"}, {"num": "5", "name": "ELECTRICAL – ROUGH-IN", "rate": 415.0, "qty": 165.0, "scope": "Scope of Work:\n- Provide rough wiring, boxes, supports, and switch legs for all lighting, switching, and receptacle\nlocations shown per RCP-101 & RCP-102\n- Coordinate work with framing, millwork, plumbing, and ceiling layouts\n\n- Final fixtures, devices, and trim-out excluded and carried under Finish Electrical\n\nGarden Level / Basement Unit\n- Kitchen: 2 duplex receptacles, 2 single-pole switches, 1 pendant light rough-in\n- Hallway: 1 single-pole switch, 1 pendant light rough-in, 1 Hardwired Smoke Alarm\n- Rec Room: 1 Hardwired Smoke Alarm\n- Bedroom: 1 Hardwired Smoke Alarm\n\nParlor Floor\n- Kitchen: 7 duplex receptacles, 4 single-pole switches, 1 pendant light rough-in, 2 wall-mounted\nsconces, 4 recessed lights\n- Powder Room: 1 single-pole switch, 1 wall-mounted sconce\n- Dining Room:1 Hardwired Smoke Alarm, 2 duplex receptacles, 6 single-pole switches, 2 wall-mounted\nsconces, 1 pendant light rough-in, 5 recessed lights\n- Living Room:1 Hardwired Smoke Alarm, 2 single-pole switches, 6 recessed lights, 1 pendant\nlight rough-in\n- Vestibule: 1 pendant light rough-in, 1 single-pole switch\n- Stairs / Hallway:1 Hardwired Smoke Alarm, 3 single-pole switches, 1 pendant light rough-in,\n2 wall-mounted sconces\n\nSecond Floor\n- Bathroom: 2 single-pole switches, 2 wall-mounted sconces, 1 recessed light\n- Bedroom: 1 Hardwired Smoke Alarm, 6 duplex receptacles 2 single-pole switches, 1 pendant\nlight rough-in, 8 recessed lights\n- Closets: 2 single-pole switches, 2 wall-mounted sconces\n- Hallway: 1 Hardwired Smoke Alarm, 3 single-pole switches, 4 pendant light rough-ins\n- Laundry Room: 6 duplex receptacles 1 single-pole switch, 2 recessed lights\n- Family Room / Den: 1 Hardwired Smoke Alarm, 3 duplex receptacles 2 single-pole switches,\n1 pendant light rough-in, 6 recessed lights\n- Office: 1 duplex receptacles, 1quad, 1 single-pole switch, 2 recessed lights, 1 wall-mounted\nsconce\n\nThird Floor\n- Primary Bathroom: 2 duplex receptacles, 3 single-pole switches, 4 wall-mounted sconces, 5\nrecessed lights\n- Primary Bedroom:1 Hardwired Smoke Alarm, 2 single-pole switches, 6 recessed lights, 1 pendant\nlight rough-in\n- Stairs: 1 single-pole switch\n- Hallway: 1 Hardwired Smoke Alarm\n\nPrimary Bedroom, Closet, and Hallway\n- Budget 10 additional Electrical Points", "vendor": "Satish Electric", "cost": 49800, "unit": "ea"}, {"num": "6", "name": "DRYWALL & TAPING (ALL LEVELS)", "rate": 27034.22, "qty": 2.0, "scope": "- Sheetrock Installation and Cement/green boards at all wet areas\n- Drywall installation and patching at impacted areas\n- Tape, mud, and sand for finish readiness", "cost": 38929.28, "unit": "ea"}, {"num": "7", "name": "WATERPROOFING", "rate": 10600.0, "qty": 1.0, "scope": "- Apply liquid-waterproofing with reinforcing mesh at seams, corners, penetrations, and transitions;\napply throughout third floor primary bath and second floor bath wet areas", "cost": 7632.0, "unit": "ls"}, {"num": "8", "name": "TILE INSTALLATION", "rate": 32084.0, "qty": 1.0, "scope": "Vestibule Tile\n\nParlor Floor\n- Kitchen floor tile\n- Powder room tile\n\nSecond Floor\n- Bathroom wall and floor tile\n- Laundry room floor tile", "vendor": "Angel — crew", "cost": 21000, "items": [{"name": "Thinset — large format, white", "qty": 28, "unit": "bag", "cost": 32, "vendor": "Nemo Tile"}, {"name": "Schluter Kerdi membrane 108 sf roll", "qty": 4, "unit": "roll", "cost": 185, "vendor": "Nemo Tile"}, {"name": "Grout — Prism, per color", "qty": 9, "unit": "box", "cost": 41, "vendor": "Nemo Tile"}, {"name": "Leveling clips & wedges", "qty": 3, "unit": "box", "cost": 38, "vendor": "Home Depot"}], "unit": "ls"}, {"num": "9", "name": "SUBFLOOR / FLOOR LEVELING", "rate": 14200.0, "qty": 2.0, "scope": "Inspect exposed subfloor conditions following demolition; perform localized subfloor repairs,\nreinforcement, and floor leveling as required to receive new flooring; excludes full structural\njoist replacement unless noted as an allowance", "cost": 20448.0, "unit": "ea"}, {"num": "10", "name": "FLOORING INSTALL – HARDWOOD & ENGINEEREED", "rate": 14.5, "qty": 1890.0, "scope": "Parlor Floor, Second Floor & Limited Third Floor (Hardwood Flooring):\n\n- Scope of Work\nInstall solid hardwood flooring in areas shown on plans (Parlor Floor, Second Floor, limited\nThird Floor areas); includes layout, fastening, underlayment as required, transitions, and integration\nwith existing conditions.\n\nInstallation Method\nNail-down over approved wood subfloor", "vendor": "Tino", "cost": 17600, "items": [{"name": "Rosin paper & fasteners", "qty": 1, "unit": "ls", "cost": 420, "vendor": "Home Depot"}, {"name": "Flooring cleats 1-3/4\"", "qty": 6, "unit": "box", "cost": 54, "vendor": "Home Depot"}], "unit": "sf"}, {"num": "11", "name": "BASE MOLDING & TRIMS (ALL LEVELS)", "rate": 32261.0, "qty": 1.0, "scope": "BASE MOLDING / TRIM\n- Remove and replace base molding at all areas where flooring is replaced\n- Includes cutting, fitting, caulking, patching, and preparation for paint\n\nDOOR CASING / TRIM\n- Remove, repair, and replace door casing trim at doors impacted by flooring replacement, wall\ndemolition, new partitions, and finish work\n- Includes patching, caulking, and preparation for paint", "cost": 23227.92, "unit": "ls"}, {"num": "12", "name": "MILLWORK", "rate": 14400.0, "qty": 1.0, "scope": "Garden level/ Parlor Level/ Second Floor:\n- Coordination and Management of custom millwork at garden, parlor, and second floor levels\nin accordance with approved millwork drawings and construction plans, including all cabinetry,\npanels, built-ins, hardware, and field coordination as shown on plans approved by client", "vendor": "Carlos Millwork", "cost": 10800, "unit": "ls"}, {"num": "13", "name": "COUNTERTOPS / STONE", "rate": 3900.0, "qty": 1.0, "scope": "Coordination and management of stone countertops at:\n- Parlor kitchen\n- Second floor laundry", "cost": 2808.0, "unit": "ls"}, {"num": "14", "name": "FINISH PLUMBING", "rate": 4500.0, "qty": 1.0, "scope": "Parlor Floor\n- Powder room fixtures\n- Parlor Kitchen\n\nSecond Floor\n- Bathroom fixtures", "cost": 3240.0, "unit": "ls"}, {"num": "15", "name": "APPLIANCE INSTALLATION", "rate": 2025.0, "qty": 2.0, "scope": "Parlor kitchen:\n- Refrigerator, range, dishwasher\n- Includes setting, leveling, alignment with millwork, and connection to existing gas/electric,\nwater, and drain points; refrigerator water line and dishwasher installation kit included; test\nfor basic operation\n\nSecond floor laundry:\n- washer and dryer\n- Includes setting, leveling, connection to hot/cold water, drain, and vent or electrical/gas\nconnection as applicable; test for basic operation", "cost": 2916.0, "unit": "ea"}, {"num": "16", "name": "RESTORATION – STAIR SPINDLES / BALUSTERS / RAILINGS", "rate": 18994.0, "qty": 1.0, "scope": "- Scope of Work\nRestore existing stair components throughout all stair runs, including repair, replacement,\nand refinishing of damaged or affected wood spindles, balusters, and railings; work to match\nexisting profiles and finishes where possible", "cost": 13675.68, "unit": "ls"}, {"num": "17", "name": "STAIRS – REPLACE STAIR THREADS & CARPET", "rate": 14482.0, "qty": 2.0, "scope": "THROUGHOUT\n- Remove existing stair carpet and padding; remove and replace stair treads at second and third\nfloors\n***risers to be replaced as required based on field conditions - price TBD\n\n**Carpet Runner for Stairs not included", "cost": 20854.08, "unit": "ea"}, {"num": "18", "name": "RESTORATION (PARLOR LEVEL) - ENTRY & VESTIBULE", "rate": 18926.0, "qty": 1.0, "scope": "DOORS\n- Restore existing parlor entry door and vestibule door, including: paint stripping, wood filler\nrepairs, sanding, priming, and painting\n*** Existing hardware to remain unless otherwise directed", "cost": 13626.72, "unit": "ls"}, {"num": "19", "name": "WINDOWS – FRONT FAÇADE INSTALL", "rate": 2500.0, "qty": 15.0, "scope": "Front facade:\nReplace all front façade windows\n- Reframe Windows as needed\n- Patch and paint at window perimeters\n\nRear facade:\n- Remove and replace rear façade windows as indicated on approved drawings, including coordination\nwith masonry/stucco repairs and lintel work where applicable.\n- Reframe as needed\n- Patch and paint at window perimeters", "vendor": "Window Works", "cost": 27000, "items": [{"name": "Double-hung wood windows, LPC profile", "qty": 15, "unit": "ea", "cost": 1450, "vendor": "Window Works"}, {"name": "Brick mold & sill stock", "qty": 15, "unit": "set", "cost": 120, "vendor": "Window Works"}, {"name": "Low-expansion foam & flashing tape", "qty": 1, "unit": "ls", "cost": 380, "vendor": "Home Depot"}], "unit": "ea"}, {"num": "20", "name": "PATCH, REPAIR & SURFACE PREP", "rate": 27778.42, "qty": 1.0, "scope": "- Garden Level: Patch and repair walls, ceilings, and trim at entry foyer, bedroom, recreation\nroom, closets, hallway, and kitchen areas impacted by flooring removal, kitchen work, radiator\nreplacement, plumbing, electrical, and millwork installation\n\n- Parlor Floor: Patch and repair walls, ceilings, and trim at kitchen, powder room, living room,\ndining room, hallway, and entry/vestibule areas impacted by demolition, flooring replacement,\nmillwork installation, window replacement, plumbing, electrical, and door restoration\n\n- Second Floor: Patch and repair walls, ceilings, and trim at bathroom, laundry room, bedroom,\noffice, family room/den, hallway, stair area, and panel relocation areas impacted by demolition,\nnew partitions, plumbing, electrical, flooring, stair work, and millwork installation\n\n- Third Floor: Patch and repair walls, ceilings, and trim at primary bathroom, hallway, stair\narea, and window locations impacted by demolition, waterproofing, plumbing, electrical, flooring,\nstair work, and window replacement\n\nIncludes plaster and drywall patching, surface preparation, and blending for finish readiness\nprior to painting", "vendor": "Angel — crew", "cost": 20400, "unit": "ls"}, {"num": "21", "name": "PAINTING", "rate": 32872.32, "qty": 1.0, "scope": "- Prime and paint (Parlor & 2nd Floors)\n- Paint new base molding, window trim, and restored doors", "vendor": "Painting sub", "cost": 24500, "unit": "ls"}, {"num": "22", "name": "PERMITS & DOB", "rate": 3500.0, "qty": 3.0, "scope": "- Construction\n- Plumbing permit\n- Electrical permit\n\n- Inspections and sign-offs", "cost": 7560.0, "unit": "ea"}, {"num": "23", "name": "FINAL CLEANING Optional*", "rate": 0.0, "qty": 30.0, "scope": "OPTIONAL\n- Post-construction deep clean\nn- 3-4 Cleaner for 6-8 hours @ $64 per hour", "unit": "ls"}, {"num": "24", "name": "SCAFFOLDING (FRONT + REAR FAÇADES)", "rate": 18994.15, "qty": 1.0, "scope": "Provide, install, maintain, and remove scaffolding required for front façade window replacement\nand rear façade access for approximately four (4) window locations, replacement, and exterior\nwork in compliance with DOB and site safety requirements.", "vendor": "Safway Scaffold", "cost": 14200, "unit": "ls"}, {"num": "25", "name": "INTERIOR DOORS", "rate": 1105.0, "qty": 7.0, "scope": "Scope of Work\n- Remove and install new interior door slabs where indicated on construction plans\n- Includes fitting, rehanging, alignment, and coordination with new flooring, base molding,\nand door casing\n- Transfer and reinstall existing hardware unless otherwise noted\n\nQuantity / Locations (per plans)\n- Second Floor: new interior door slabs at closet locations (RM 205, RM 206)\n\nINTERIOR DOORS TO REMAIN:\n- Remove and reinstall doors as required to accommodate flooring replacement, base molding,\ndoor casing, framing, or adjacent work\n- Adjust, rehang, and align doors impacted by changes in finished floor elevation or wall conditions\n- Reinstall existing hardware and verify proper operation at completion", "vendor": "Carlos Millwork", "cost": 5200, "items": [{"name": "Solid-core 2-panel door slabs", "qty": 7, "unit": "ea", "cost": 310, "vendor": "Brooklyn Door Supply"}, {"name": "Hinges & latch sets", "qty": 7, "unit": "set", "cost": 62, "vendor": "Brooklyn Door Supply"}], "unit": "ea"}, {"num": "26", "name": "BLOCKING - FIXTURES, ACCESSORIES & MILLWORK", "rate": 7200.0, "qty": 1.0, "scope": "SUPPORT\nScope of Work:\nProvide wood blocking/backing at all locations required to support wall-mounted fixtures, accessories,\nand millwork per construction and millwork plans\n\n- Parlor Floor: Blocking at kitchen millwork locations (uppers, panels, shelving) and powder\nroom accessory locations as required\n- Second Floor: Blocking at bathroom accessories and medicine cabinet/mirror, laundry millwork\nsupports, and family room built-in installation supports; provide backing at wall-mounted accessories\nand heavy mount points", "cost": 5184.0, "unit": "ls"}, {"num": "27", "name": "PORTAL OPENINGS – FRAMED INSET RETURNS", "rate": 8226.3, "qty": 3.0, "scope": "Scope of Work:\n- Build new “portal” openings where indicated on construction plans, including framing\nof the opening, creating an inset/return (reveal) at jambs and head, and preparing substrates\nfor finish work\n\n- Parlor Floor: Portal opening work at the primary interior opening(s) between main living areas\n(living room/dining circulation zone) as indicated on plan; includes jamb/head inset returns\nand alignment to adjacent wall finishes\n- Second Floor: Portal opening work at revised hallway/closet/laundry transition opening(s)\nwhere openings are newly framed or modified per plan; includes inset returns as required for\nclean finish and alignment with door casing/trim\n**Includes layout verification, non-structural framing, blocking as needed, drywall, corner\nbead, tape/mud prep, and coordination with adjacent trim and pain", "cost": 17768.81, "unit": "ea"}, {"num": "28", "name": "SOFFIT – PARLOR LEVEL", "rate": 2450.0, "qty": 1.0, "scope": "Scope of Work:\n- Frame new soffit (non-structural) including blocking as required, install drywall, corner\nbead, tape/mud/sand; prep for paint; coordinate with millwork crown/trim alignment and any adjacent\nelectrical/lighting conflicts.\n- Approx. Size (Allowance): ~8 LF run × ~18\" width (drop/height TBD based on millwork + field\nconditions)", "cost": 1764.0, "unit": "ls"}, {"num": "29", "name": "INSULATION", "rate": 13370.34, "qty": 1.0, "scope": "Scope of Work:\nFurnish and install insulation at all areas opened during demolition and construction, as required\nby code and per construction plans\n\n- Install insulation at exposed exterior walls on theParlor, Second, floor where walls are opened\nfor new work, framing, or window replacement\n- Insulate and air-seal around new window perimeters, including shims, gaps, and penetrations.\n\n**Spray foam insulation excluded unless specifically noted and approved", "cost": 9626.64, "unit": "ls"}, {"num": "30", "name": "FIREPLACE – RESTORATION / HEARTH WORK (PARLOR", "rate": 4500.0, "qty": 1.0, "scope": "FLOOR)\nScope of Work:\n- Protect existing fireplace surrounds, mantels, and adjacent finishes throughout construction\n- Dining Room: Carefully remove existing hearth stone and install new hearth stone per approved\ndesign\n- set/level, grout/caulk as required, and finish edges cleanly\n- patch/repair adjacent plaster/drywall and floor transitions impacted by hearth work and flooring\nreplacement.", "cost": 3240.0, "unit": "ls"}, {"num": "31", "name": "ELECTRICAL – PANEL RELOCATION & ASSOCIATED WORK", "rate": 8927.64, "qty": 1.0, "scope": "Second Floor – Hallway: Electrical panel to be relocated\n- Work coordinated across Second and Third Floors as required to reconnect affected circuits\n- Safely disconnect, relocate, and reinstall existing electrical panel at new approved location\nper plans\n- Extend, reroute, and reconnect existing branch circuits as required to accommodate panel\nrelocation\n- Provide new breakers, grounding, bonding, and labeling as required for code compliance\n- Patch and repair walls/ceilings impacted by panel relocation and conduit routing (patch/repair\nonly", "cost": 6427.9, "unit": "ls"}, {"num": "32", "name": "ELECTRICAL – FINISH (DEVICES & TRIM-OUT) (ALL LEVELS)", "rate": 150.0, "qty": 165.0, "scope": "Provide and install all finish electrical devices and trim-out, including: switches, receptacles,\nplates, dimmers as specified, GFCI/AFCI devices as required, smoke/CO devices final installation/connection,\nlight fixture installation (pendants/sconces/recessed trims), testing, labeling, and final punch\ncorrections. Coordinate with millwork, tile, paint, and final ceiling conditions.\n\nDevices\n-Install 29 duplex receptacles\n-Install 1 quad receptacle\n-Install 35 single-pole switches\n-Install and connect 9 hardwired smoke/CO alarms\n-Install all device plates and cover plates\n\nLighting Fixtures\nInstall and connect:\n-44 recessed light trims\n-15 wall-mounted sconces\n-9 pendant fixtures\n** optional closet lighting for $2500.\n\nPrimary Bedroom, Closet, and Hallway\n- Budget 10 Electrical Points\n\nIncludes final wiring terminations, fixture mounting, alignment, and testing.", "cost": 17820.0, "unit": "ea"}, {"num": "16-2", "name": "RESTORATION – INTERIOR WOODWORK", "rate": 14275.0, "qty": 1.0, "scope": "(ALLOWANCE)\nProvide selective restoration of existing architectural elements as directed, including paint\nstripping, substrate prep, wood repairs/filling, patching, sanding, and refinishing/painting\nto match existing. Scope includes repair/restore of existing windows and doors casings identified\non drawings as “repair/restore,” plus localized restoration of existing interior wood elements\n(trim/panels) where damaged or impacted by adjacent construction. Include protection/containment,\ndust control, and proper disposal of removed coatings.\n\nClarification: Excludes stair spindles/balusters/railings (Item 16) and parlor entry/vestibule\n\ndoors (Item 18).", "cost": 10278.0, "unit": "ls"}, {"num": "34", "name": "Radiators – Furnish & Install", "rate": 2300.0, "qty": 8.0, "scope": "Furnish and install new radiators at locations shown, including valves/unions, setting, leveling,\nbleed/startup, and protection.\n- Radiator rough piping: Run/modify hydronic supply/return piping and install isolation valves/unions\nas required for new radiator location(s)\n\nGarden Level: 2 units\nParlor Level: 4 units\n2nd Floor: 2 units", "vendor": "Alberto M Plumbing", "cost": 13600, "items": [{"name": "Cast-iron radiators, 6-section", "qty": 8, "unit": "ea", "cost": 890, "vendor": "Radiator Supply Co"}, {"name": "Valves & traps", "qty": 8, "unit": "set", "cost": 95, "vendor": "Radiator Supply Co"}], "unit": "ea"}, {"num": "35", "name": "WATER DAMAGE REPAIR – GARDEN BEDROOM", "rate": 0.0, "qty": 1.0, "scope": "(ALLOWANCE)\nInvestigate and repair water-damaged finishes/substrates at garden level bedroom as required,\nincluding removal of compromised material, drying/dehumidification as needed, patching/replacement\nof damaged drywall/plaster/trim, substrate prep, and restoration to paint-ready condition. Source/active\nleak remediation excluded unless specifically identified.\n\nPrice TBD*", "unit": "ls"}, {"num": "36", "name": "Crown Molding Installation - Labor", "rate": 9322.0, "qty": 1.0, "scope": "Provide and install approximately 178 linear feet of crown molding in selective areas as indicated\non the plans (final extents to be field verified). Scope includes layout, cutting, fitting,\nfastening, jointing, and caulking to achieve a clean, continuous installation. Includes preparation\nto a paint-ready condition.", "cost": 6711.84, "unit": "ls"}, {"num": "37", "name": "Interior Window Sill Replacement / Patch (Allowance –", "rate": 750.0, "qty": 15.0, "scope": "TBD)\nProvide repair and/or replacement of simple interior window sills (non-decorative) at approximately\n15 window openings ± following window installation, including removal of damaged sections as\nrequired, installation of new sill material to match existing profile, fastening, sealing, and\npreparation to paint-ready condition.\n** Final budget to be determined pending field verification and final window count.", "cost": 8100.0, "unit": "ea"}, {"num": "38", "name": "Rear Façade – Lintel Installation & Opening Modification", "rate": 1089.0, "qty": 2.0, "scope": "(Parlor Level)\nProvide labor to enlarge existing rear façade opening at Parlor Level to accommodate new window\ninstallation, including selective demolition of brick and stucco, installation of new steel\nlintel as required, modification of masonry opening, brick infill and patching, and stucco repair\nto match existing. Field verification required prior to execution", "cost": 1568.16, "unit": "ea"}, {"num": "39", "name": "Stair Modification – Remove & Reposition", "rate": 2727.0, "qty": 1.0, "scope": "Provide labor and materials to remove and reposition two (2) existing stair steps as indicated\non plans to accommodate revised layout at the office/den level. Includes selective demolition,\nframing adjustment as required, tread/riser reinstallation or replacement, and preparation to\nreceive finish flooring. Field verify prior to execution", "cost": 1963.44, "unit": "ls"}, {"num": "40", "name": "Closet Shelf & Rod Installation (Per Closet)", "rate": 846.73, "qty": 3.0, "scope": "Provide and install one (1) fixed shelf and one (1) hanging rod per closet as indicated on plans,\nincluding supports, hardware, fastening, and preparation to paint-ready condition. Field verify\ndimensions prior to installation.", "cost": 1828.94, "unit": "ea"}, {"num": "41", "name": "Hauling & Dumping Throughout", "rate": 1867.8, "qty": 12.0, "scope": "Hauling & Dumping Throughout the Entire Project", "cost": 16137.79, "unit": "ea"}, {"num": "42", "name": "Concrete", "rate": 1900.0, "qty": 5.0, "scope": "Apply Self Level Cement or Cement Boards to Kitchen, Bathrooms (2), Laundry, Vestibule.\n\nApply Concrete w/4-degree pitch towards drain in showers.", "cost": 6840.0, "unit": "ea"}, {"num": "43", "name": "Misc. Installation", "rate": 9500.0, "qty": 1.0, "scope": "- Bathroom & Kitchen Accessories\n- Access Panels\n- Vent Grills\n- Door Stops\n- Plus all other misc installation items", "cost": 6840.0, "unit": "ls"}, {"num": "44", "name": "Kitchen Structure Budget***", "rate": 7500.0, "qty": 1.0, "scope": "Garden Bathroom - make sure that's included\nStructure Removal in the Kitchen.\n\n\n\n\n\n\n\n\n\ndocument.", "cost": 5400.0, "unit": "ls"}];
/* ===================== FINANCIAL THREAD — one line, every document ===================== */
/* Every estimate / change-order line has a key `estimate:<doc>:<line>` or `co:<doc>:<line>`. SOV rows, invoices, POs, vendor bills and bank transactions all carry that key, so each line can answer: contract, billed, collected, budget, committed, actual, margin. */
const finClientOfDoc = doc => DB.clients.find(c => c.estimates.includes(doc) || c.changeOrders.includes(doc) || c.invoices.includes(doc));
function invoicePaid(c, inv){ return c.payments.filter(p => p.invoiceId===inv.id).reduce((a,p)=>a+(+p.amount||0),0); }
function lineFin(key){ const ref = findLine(key); if (!ref) return null; const {doc, line, client:c} = ref; const price = lineAmount(line, doc); const isCO = key.startsWith('co:');
  const own = c.sov.find(v => v.lineRef===key) || (isCO ? c.sov.find(v => v.coId===doc.id) : null); const lump = !own && !isCO && doc.status==='converted' ? c.sov.find(v => v.source==='Contract' && !v.lineRef) : null; const sv = own || lump; const share = sv && (isCO || lump) ? ((isCO ? docTotal(doc).sub : +sv.scheduled) ? price/(isCO ? docTotal(doc).sub : +sv.scheduled) : 0) : 1;
  const live = c.invoices.filter(i => i.mode==='sov' && i.status!=='void' && i.status!=='draft'); const drafts = c.invoices.filter(i => i.mode==='sov' && i.status==='draft');
  const billedPct = sv ? live.flatMap(i=>i.lines).filter(l=>l.sovId===sv.id).reduce((a,l)=>a+(+l.pct||0),0) : 0; const draftPct = sv ? drafts.flatMap(i=>i.lines).filter(l=>l.sovId===sv.id).reduce((a,l)=>a+(+l.pct||0),0) : 0;
  const depositPct = sv ? live.filter(i=>i.depositOf).flatMap(i=>i.lines).filter(l=>l.sovId===sv.id).reduce((a,l)=>a+(+l.pct||0),0) : 0;
  const billed = r2(price * billedPct/100); let collected = 0, retained = 0; if (sv) live.forEach(i => { const t = docTotal(i); const paid = invoicePaid(c, i); const ratio = t.total ? Math.min(1, paid/t.total) : 0; i.lines.filter(l=>l.sovId===sv.id).forEach(l => { const amt = lineAmount(l, i) * share; retained += amt * ((+i.retainagePct||0)/100); collected += (amt - amt*((+i.retainagePct||0)/100)) * ratio; }); });
  const pos = DB.pos.filter(po => !['cancelled','draft'].includes(po.status) && po.lines.some(l => l.line===key)); const poGross = r2(pos.reduce((a,po) => a + po.lines.filter(l=>l.line===key).reduce((b,l)=>b+(+l.qty||0)*(+l.price||0),0), 0)); const poBilled = r2(DB.bills.filter(b => b.status!=='void' && b.status!=='rejected' && pos.some(po=>po.id===b.poId) && (b.line===key || !b.line)).reduce((a,b)=>a+billTotal(b),0)); const committed = Math.max(0, r2(poGross - poBilled)); const draftPOs = DB.pos.filter(po => po.status==='draft' && po.lines.some(l => l.line===key));
  const bills = DB.bills.filter(b => b.line===key && b.status!=='void' && b.status!=='rejected'); const billsAmt = r2(bills.reduce((a,b)=>a+billTotal(b),0)); const viaBill = t => !!t.billId || bills.some(b => (b.status==='paid' && (b.vendor||'').toLowerCase()===(t.vendor||'').toLowerCase() && Math.abs(billTotal(b) + t.amt) < 1) || (b.poId && (DB.pos.find(p=>p.id===b.poId)?.matchedTxns||[]).includes(t.id))); const txns = DB.txns.filter(t => t.line===key && !viaBill(t)); const txnAmt = r2(txns.reduce((a,t)=>a - t.amt, 0));
  const actual = r2(billsAmt + txnAmt); const budget = +line.cost||0; const projCost = Math.max(budget, actual, committed); const invoiced = live.filter(i => sv && i.lines.some(l=>l.sovId===sv.id)).map(i => i.number);
  return {key, doc, line, client:c, price, sv, billedPct:r2(billedPct), draftPct:r2(draftPct), depositPct:r2(depositPct), billed, collected:r2(collected), retained:r2(retained), outstanding:r2(billed - collected - retained), committed, draftPOs, pos, bills, billsAmt, txnAmt, actual, budget, projCost, margin:r2(price - projCost), marginPct: price ? Math.round((price-projCost)/price*100) : 0, invoices:invoiced, overCommit: budget && committed > budget, flags:(() => { const f = []; if (budget && actual > budget*(1+(DB.company.costVar||10)/100)) f.push('over budget'); if (budget && committed > budget) f.push('over-committed'); if (price && (price-projCost)/price*100 < (DB.company.minMargin||20)) f.push('thin margin'); if (billedPct - depositPct > 0 && budget && actual/budget < (billedPct-depositPct)/100 - 0.35) f.push('billed ahead of cost'); return f; })()}; }
const finShort = f => f ? `Billed ${f.billedPct}%${f.depositPct?` (${f.depositPct}% dep.)`:''} · PO ${money(f.committed)}${f.draftPOs.length?` +${f.draftPOs.length} draft`:''} · Actual ${money(f.actual)} · Margin ${f.marginPct}%` : '';

/* Client › By line — the hub: contract → billed → collected · budget → committed → actual, per line */
function renderFinLines(c){ const keys = []; c.estimates.filter(e => ['approved','converted'].includes(e.status)).forEach(e => { if (e.template==='construction') ctNumber(e); e.lines.forEach(l => keys.push(`estimate:${e.id}:${l.id}`)); }); c.changeOrders.filter(x => ['approved','billed'].includes(x.status)).forEach(x => x.lines.forEach(l => keys.push(`co:${x.id}:${l.id}`)));
  const rows = keys.map(lineFin).filter(Boolean); if (!rows.length) return '<div class="muted small">No approved estimate yet. Approve one and every line appears here with its billing, purchasing and cost.</div>';
  const T = rows.reduce((a,r) => { ['price','billed','collected','retained','budget','committed','actual','projCost'].forEach(k => a[k]=(a[k]||0)+r[k]); return a; }, {});
  const cell = (v, cls='') => `<td class="money ${cls}">${v?money(v):'<span class="muted">—</span>'}</td>`;
  return `<div class="row" style="gap:14px;flex-wrap:wrap;margin-bottom:10px;font-size:12.5px"><span>Contract <b>${money(T.price)}</b></span><span>Billed <b>${money(T.billed)}</b> (${T.price?Math.round(T.billed/T.price*100):0}%)</span><span>Collected <b>${money(T.collected)}</b></span><span>Retainage held <b>${money(T.retained)}</b></span><span>Client funds held <b>${money(clientFundsSummary().rows.filter(r=>r.c===c).reduce((a,r)=>a+r.reserved,0))}</b></span><span class="grow"></span><span>Budget <b>${money(T.budget)}</b></span><span>Committed <b>${money(T.committed)}</b></span><span>Actual <b>${money(T.actual)}</b></span><span>Projected margin <b style="color:${T.price-T.projCost>=0?'var(--ok)':'var(--bad)'}">${money(T.price-T.projCost)} · ${T.price?Math.round((T.price-T.projCost)/T.price*100):0}%</b></span></div>
  <div class="tw"><table class="t finl"><thead><tr><th>Line</th><th class="money">Contract</th><th class="money">Billed</th><th class="money">Collected</th><th class="money">Budget</th><th class="money">Committed</th><th class="money">Actual</th><th class="money">Margin</th><th></th></tr></thead><tbody>${rows.map(r => `<tr class="click" data-finline="${r.key}"><td><b>${r.line.num?r.line.num+'. ':''}${esc(r.line.item||r.line.desc||'')}</b><div class="small muted">${r.doc.number}${r.invoices.length?' · '+r.invoices.join(', '):''}${r.pos.length?' · '+r.pos.map(p=>p.number).join(', '):''}</div></td>${cell(r.price)}<td class="money">${r.billed?money(r.billed):'<span class="muted">—</span>'}<div class="small muted">${r.billedPct}%${r.draftPct?` +${r.draftPct}% draft`:''}</div></td>${cell(r.collected)}${cell(r.budget)}<td class="money ${r.overCommit?'bad':''}">${r.committed?money(r.committed):'<span class="muted">—</span>'}${r.draftPOs.length?`<div class="small muted">+${r.draftPOs.length} draft PO</div>`:''}</td><td class="money">${r.actual?money(r.actual):'<span class="muted">—</span>'}${r.actual?`<div class="small muted">${r.bills.length} bill${r.bills.length===1?'':'s'}${r.txnAmt?' · bank':''}</div>`:''}</td><td class="money" style="color:${r.margin>=0?'inherit':'var(--bad)'}">${money(r.margin)}<div class="small muted">${r.marginPct}%</div></td><td>${r.flags.map(f=>`<span class="pill ${f==='thin margin'||f==='over budget'||f==='over-committed'?'bad':'warn'}">${f}</span>`).join(' ')}</td></tr>`).join('')}<tr style="font-weight:600"><td>Total</td>${cell(T.price)}${cell(T.billed)}${cell(T.collected)}${cell(T.budget)}${cell(T.committed)}${cell(T.actual)}<td class="money">${money(T.price-T.projCost)}</td><td></td></tr></tbody></table></div>
  <p class="small muted" style="margin-top:8px">Billed = progress invoices sent (deposit included, shown separately). Collected = payments applied, pro-rated by line, net of retainage. Committed = issued purchase orders. Actual = vendor bills entered plus bank transactions not tied to a bill. Margin = contract − the larger of budget, committed and actual.</p>`; }

/* line detail popover: every document that touches this line */
function finLineModal(key){ const f = lineFin(key); if (!f) return; const c = f.client; const inv = c.invoices.filter(i => i.mode==='sov' && f.sv && i.lines.some(l=>l.sovId===f.sv.id) && i.status!=='void');
  const list = (title, items) => `<div style="margin-bottom:10px"><b>${title}</b>${items.length?`<table class="t" style="margin-top:4px"><tbody>${items.join('')}</tbody></table>`:'<div class="small muted">None</div>'}</div>`;
  mbModal(`${f.line.num?f.line.num+'. ':''}${esc(f.line.item||'')}`, `<div class="row" style="gap:12px;flex-wrap:wrap;font-size:12.5px;margin-bottom:10px"><span>Contract <b>${money(f.price)}</b></span><span>Billed <b>${money(f.billed)}</b> (${f.billedPct}%)</span><span>Collected <b>${money(f.collected)}</b></span><span>Budget <b>${money(f.budget)}</b></span><span>Committed <b>${money(f.committed)}</b></span><span>Actual <b>${money(f.actual)}</b></span></div>
    ${list('Invoices', inv.map(i => { const l = i.lines.find(x=>x.sovId===f.sv.id); return `<tr><td>${esc(i.number)} · ${esc(i.title)}</td><td class="dim">${fmtL(i.date)}</td><td>${invoiceStatus(c,i)}</td><td class="money">${l.pct}% · ${money(lineAmount(l,i))}</td></tr>`; }))}
    ${list('Purchase orders', [...f.pos, ...f.draftPOs].map(po => `<tr class="click" data-finpo="${po.id}"><td>${esc(po.number)} · ${esc(po.vendor)}</td><td>${po.status}</td><td class="money">${money(po.lines.filter(l=>l.line===key).reduce((a,l)=>a+(+l.qty||0)*(+l.price||0),0))}</td></tr>`))}
    ${list('Vendor bills', f.bills.map(b => `<tr><td>${esc(b.vendor)} · ${esc(b.number)}</td><td class="dim">${fmtL(b.date)}</td><td>${b.status}</td><td class="money">${money(billTotal(b))}</td></tr>`))}
    ${f.txnAmt?list('Bank transactions (no bill)', DB.txns.filter(t => t.line===key && !t.billId && !f.bills.some(b => b.poId && (DB.pos.find(p=>p.id===b.poId)?.matchedTxns||[]).includes(t.id))).map(t => `<tr><td>${esc(t.desc)}</td><td class="dim">${fmtL(t.date)}</td><td class="money">${money(-t.amt)}</td></tr>`)):''}
    <div class="row" style="gap:8px"><button class="btn sm" type="button" id="fin-po">Create purchase order for this line</button></div>`, {submit:null});
  document.querySelectorAll('[data-finpo]').forEach(tr => tr.onclick = () => { mbCloseModal(); poOpen = tr.dataset.finpo; view = 'po'; render(); });
  $('#fin-po')?.addEventListener('click', () => { mbCloseModal(); ctPOPicker(f.doc.projectId||S.id, f.doc.id, key); }); }

/* retainage release + invoice from an items-mode estimate (full or selected lines) */
function billRetainage(c){ const f = clientFin(c); if (!f.retHeld) { toast('No retainage is being held'); return; } const inv = newDoc(c, 'invoice', {mode:'items'}); inv.title = 'Retainage release'; inv.terms = 'Due on receipt'; inv.lines = [{id:uid('l'), item:'Release of retainage held', desc:`Retainage withheld on ${c.invoices.filter(i=>docTotal(i).ret&&i.status!=='void').map(i=>i.number).join(', ')}`, qty:1, unit:'ls', rate:f.retHeld, taxable:false}]; inv.retainageRelease = true; docMark(inv); c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} retainage release — ${money(f.retHeld)}`}); docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }
function invoiceFromEstimate(c, d){ if (d.template==='construction') ctNumber(d); const already = {}; c.invoices.filter(i => i.mode==='items' && i.status!=='void').forEach(i => i.lines.forEach(l => { if (l.fromLine) already[l.fromLine] = (already[l.fromLine]||0) + (+l.pct||100); }));
  const rows = d.lines.map(l => ({l, key:ctKey(d,l), done:already[`${d.type==='co'?'co':d.type}:${d.id}:${l.id}`]||0}));
  const body = () => `<div class="row" style="gap:10px;align-items:center;margin-bottom:8px"><label class="small"><input type="checkbox" id="ife-all" checked> All lines</label><label class="small">Bill <input id="ife-pct" type="number" min="1" max="100" value="100" style="width:60px;display:inline-block;height:28px"> % of each selected line</label><span class="small muted">— e.g. 50% deposit now, 50% at delivery</span></div><div class="tw" style="max-height:50vh;overflow:auto"><table class="t"><thead><tr><th></th><th>Line</th><th class="money">Amount</th><th>Billed before</th></tr></thead><tbody>${rows.map((r,i) => `<tr><td><input type="checkbox" data-ife="${i}" ${r.done>=100?'':'checked'}></td><td>${r.l.num?r.l.num+'. ':''}${esc(r.l.item||r.l.desc||'')}</td><td class="money">${money(lineAmount(r.l,d))}</td><td class="dim">${r.done?r.done+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`;
  const m = mbModal(`Invoice from ${d.number}`, body(), {submit:'Create invoice', onSubmit: () => { const pct = Math.max(1, Math.min(100, +$('#ife-pct').value||100)); const picks = [...m.querySelectorAll('[data-ife]:checked')].map(cb => rows[+cb.dataset.ife]); if (!picks.length){ toast('Select at least one line'); return false; }
      const inv = newDoc(c, 'invoice', {mode:'items'}); inv.template = d.template; inv.title = pct===100 ? `Invoice — ${d.title||d.number}` : `${pct}% — ${d.title||d.number}`; inv.fromDoc = d.id; inv.taxRate = d.taxRate; inv.lines = picks.map(r => ({id:uid('l'), item:r.l.item, desc:(pct===100?'':`${pct}% of line · `)+ctFirstLine(r.l.desc), qty:pct===100 ? r.l.qty : 1, unit:pct===100 ? r.l.unit : 'ls', rate:pct===100 ? r.l.rate : r2(lineAmount(r.l,d)*pct/100), taxable:r.l.taxable, fromLine:r.key, pct})); docMark(inv);
      c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} created from ${d.number} — ${money(docTotal(inv).total)}`}); if (d.status==='approved') d.status = 'converted'; docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }});
  $('#ife-all').addEventListener('change', e => m.querySelectorAll('[data-ife]').forEach(cb => cb.checked = e.target.checked)); }

/* ===================== REPORTS — project profitability, portfolio, client statement, custom ===================== */
let repTab = 'dash', repProj = '', repFrom = '', repTo = '', repClient = '', repDef = {ds:'lines', group:'', proj:'', from:'', to:'', q:''};
const inRange = (dt) => (!repFrom || (dt||'') >= repFrom) && (!repTo || (dt||'') <= repTo);
const laborRate = emp => emp ? (+emp.rate||0) * (1 + (+emp.burden||0)/100) : 0;
function projectLabor(p){ const rows = {}; DB.time.filter(e => e.projectId===p.id && e.status!=='rejected' && inRange(e.date)).forEach(e => { const emp = DB.employees.find(x=>x.id===e.empId); const h = hoursOf(e); const r = rows[e.empId] = rows[e.empId]||{emp:emp?.name||e.empId, hours:0, cost:0, byCode:{}}; r.hours += h; r.cost += h*laborRate(emp); const code = e.code||'99'; r.byCode[code] = (r.byCode[code]||0) + h*laborRate(emp); }); const list = Object.values(rows); return {list, hours:r2(list.reduce((a,r)=>a+r.hours,0)), cost:r2(list.reduce((a,r)=>a+r.cost,0)), byCode:list.reduce((a,r) => { Object.entries(r.byCode).forEach(([c,v]) => a[c]=(a[c]||0)+v); return a; }, {})}; }
function projectProfit(p){ const J = jobFin(p, [repFrom||'', repTo||today()]); const c = J.c; const keys = []; if (c){ c.estimates.filter(e => ['approved','converted'].includes(e.status) && (!e.projectId || e.projectId===p.id)).forEach(e => { if (e.template==='construction') ctNumber(e); e.lines.forEach(l => keys.push(`estimate:${e.id}:${l.id}`)); }); c.changeOrders.filter(x => ['approved','billed'].includes(x.status) && (!x.projectId || x.projectId===p.id)).forEach(x => x.lines.forEach(l => keys.push(`co:${x.id}:${l.id}`))); }
  const lines = keys.map(lineFin).filter(Boolean); const labor = {list:J.laborByEmp, hours:J.hours, cost:J.laborCost};
  return {p, c, J, lines, contract:J.contract, budget:J.budget, committed:J.committed, direct:J.billsAmt, unlinked:J.txnAmt, accrued:J.accrued, labor, actual:J.actual, projCost:J.eac, margin:J.estGP, marginPct:Math.round(J.estGPPct), plannedMargin:J.plannedGP, billedGross:J.billed, invoicedNet:r2(J.billed + J.taxBilled - J.retHeld), retHeld:J.retHeld, collected:J.collected, outstanding:J.outstanding, earned:J.earned, overUnder:J.overUnder, pctComplete:J.pct, backlog:J.backlog, invs:J.invs, pays:J.pays, defs:J.defs, byCode:J.byCode.map(b => ({...b, actual:r2(b.bills + b.bank)}))}; }

const repMoney = v => v ? money(v) : '<span class="muted">—</span>';
function renderReports(){ const projs = DB.projects; if (!repProj || !projs.some(p=>p.id===repProj)) repProj = S?.id || projs[0]?.id || '';
  const tabs = [['dash','Dashboard'],['flash','Weekly flash'],['company','Company'],['financials','Financial statements'],['wip','WIP schedule'],['budget','Budget vs actual'],['funds','Client funds'],['analyst','Analyst'],['pack','Monthly pack'],['profit','Project profitability'],['portfolio','Portfolio'],['statement','Client statement'],['searches','Saved searches'],['custom','Custom report']];
  const bar = repBarV2(projs);
  let body = ''; if (repTab==='flash') body = repFlash(); if (repTab==='financials') body = repFinancials(); if (repTab==='wip') body = repWIP(); if (repTab==='budget') body = repBudget(); if (repTab==='pack') body = repPack(); if (repTab==='funds') body = repFunds(); if (repTab==='searches') body = repSearches(); if (repTab==='dash') body = repDashboard(); if (repTab==='company') body = repCompany(); if (repTab==='analyst') body = repAnalyst(); if (repTab==='profit') body = repProfit(); if (repTab==='portfolio') body = repPortfolio(); if (repTab==='statement') body = repStatement(); if (repTab==='custom') body = repCustom();
  $('#rep-body').innerHTML = bar + `<div id="rep-print-area">${body}</div>`;
  document.querySelectorAll('[data-reptab]').forEach(b => b.onclick = () => { repTab = b.dataset.reptab; render(); });
  $('#rep-proj')?.addEventListener('change', e => { repProj = e.target.value; render(); }); $('#rep-client')?.addEventListener('change', e => { repClient = e.target.value; render(); });
  $('#rep-from')?.addEventListener('change', e => { repFrom = e.target.value; render(); }); $('#rep-to')?.addEventListener('change', e => { repTo = e.target.value; render(); });
  $('#rep-print').onclick = () => { document.body.classList.add('rep-printing'); setTimeout(() => { window.print(); document.body.classList.remove('rep-printing'); }, 50); };
  document.querySelectorAll('[data-repproj]').forEach(tr => tr.onclick = () => { repProj = tr.dataset.repproj; repTab = 'profit'; render(); });
  document.querySelectorAll('[data-fundpo]').forEach(b => b.onclick = e => { e.stopPropagation(); const f = lineFin(b.dataset.fundpo); if (f) ctPOPicker(f.doc.projectId||S.id, f.doc.id, b.dataset.fundpo); });
  document.querySelectorAll('[data-ent]').forEach(b => b.onclick = () => { repEntity = b.dataset.ent; render(); }); document.querySelectorAll('[data-fsdrill]').forEach(tr => tr.onclick = () => fsDrill(tr.dataset.fsdrill)); $('#bud-year')?.addEventListener('change', e => { budgetYear = e.target.value; render(); }); $('#bud-seed')?.addEventListener('click', () => { if (!confirm('Fill this year\'s budget from last year\'s actuals plus 5%? Existing values are replaced.')) return; budgetSeedFromActuals(budgetYear); save(); render(); }); $('#bud-edit')?.addEventListener('click', () => budgetEditor(budgetYear)); if (repTab==='searches') wireSearches($('#rep-body'));
  document.querySelectorAll('[data-dashp]').forEach(b => b.onclick = () => { dashPeriod = b.dataset.dashp; render(); }); dashWire($('#rep-body'));
  document.querySelectorAll('[data-cfop]').forEach(b => b.onclick = () => { cfoPeriod = b.dataset.cfop; render(); }); document.querySelectorAll('[data-anasev]').forEach(b => b.onclick = () => { anaSev = b.dataset.anasev; render(); }); document.querySelectorAll('[data-anago]').forEach(el => el.onclick = () => anaGo(JSON.parse(el.dataset.anago))); $('#ana-ai')?.addEventListener('click', anaAskAI);
  repWireCustom(); }

function repProfit(){ const p = DB.projects.find(x=>x.id===repProj); if (!p) return '<div class="card muted">No project.</div>'; const r = projectProfit(p); const c = r.c; const range = repFrom||repTo ? ` · ${repFrom||'start'} → ${repTo||'today'}` : ' · to date';
  const kpi = (label, v, sub, cls='') => `<div class="kpi ${cls}"><b>${typeof v==='number'?money(v):v}</b><span>${label}${sub?` · ${sub}`:''}</span></div>`;
  return `<div class="rep-head"><div><h2 style="margin:0">${esc(p.project.name)}</h2><div class="small muted">${esc(c?.name||'')}${p.project.address?' · '+esc(p.project.address):''}${range} · prepared ${fmtL(today())}</div></div></div>
    <h3 class="rep-h">Revenue</h3><div class="fin rep-kpis">${kpi('Contract incl. approved COs', r.contract)}${kpi('Billed', r.billedGross, `${r.contract?Math.round(r.billedGross/r.contract*100):0}% of contract`)}${kpi('Collected', r.collected, '', 'good')}${kpi('Outstanding', r.outstanding, `${money(r.retHeld)} retainage held`, r.outstanding>0?'warn':'')}${kpi('Earned (cost-to-cost)', r.earned, r.overUnder>=0?`over-billed ${money(r.overUnder)}`:`under-billed ${money(-r.overUnder)}`)}</div>
    <h3 class="rep-h">Cost & margin</h3><div class="fin rep-kpis">${kpi('Budget (estimate cost)', r.budget, `planned margin ${money(r.plannedMargin)} · ${r.contract?Math.round(r.plannedMargin/r.contract*100):0}%`)}${kpi('Committed (POs)', r.committed)}${kpi('Actual to date', r.actual, `bills & bank ${money(r.direct+r.unlinked)} · labor ${money(r.labor.cost)}`)}${kpi('Projected cost', r.projCost, `${Math.round(r.pctComplete*100)}% complete by cost`)}${kpi('Projected margin', `${money(r.margin)} · ${r.marginPct}%`, '', r.margin < r.plannedMargin*0.8 ? 'warn' : 'good')}</div>
    <h3 class="rep-h">By cost code</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Code</th><th class="money">Contract</th><th class="money">Budget</th><th class="money">Committed</th><th class="money">Bills & bank</th><th class="money">Labor</th><th class="money">Actual</th><th class="money">Remaining</th><th style="width:120px">Spent</th></tr></thead><tbody>${r.byCode.map(b => { const act = b.actual + b.labor; const pct = b.budget ? Math.round(act/b.budget*100) : (act?100:0); return `<tr><td><b>${b.code}</b> ${esc(b.name)}</td>${[b.contract,b.budget,b.committed,b.actual,b.labor,act,b.budget-act].map(v=>`<td class="money ${v<0?'bad':''}">${repMoney(v)}</td>`).join('')}<td><div class="rep-bar-wrap"><i style="width:${Math.min(100,pct)}%;background:${pct>100?'var(--bad)':pct>85?'var(--warn)':'var(--ok)'}"></i></div><span class="small muted">${pct}%</span></td></tr>`; }).join('')||'<tr><td colspan="9" class="muted">No approved estimate lines for this project.</td></tr>'}${r.unlinked?`<tr><td class="muted">Unlinked job cost (no line)</td><td></td><td></td><td></td><td class="money">${money(r.unlinked)}</td><td></td><td class="money">${money(r.unlinked)}</td><td></td><td></td></tr>`:''}<tr style="font-weight:600"><td>Total</td><td class="money">${money(r.contract)}</td><td class="money">${money(r.budget)}</td><td class="money">${money(r.committed)}</td><td class="money">${money(r.direct+r.unlinked)}</td><td class="money">${money(r.labor.cost)}</td><td class="money">${money(r.actual)}</td><td class="money">${money(r.budget-r.actual)}</td><td></td></tr></tbody></table></div>
    <h3 class="rep-h">By line</h3>${c ? renderFinLines(c) : ''}
    <div class="grid2" style="margin-top:14px"><div><h3 class="rep-h">Invoices & payments</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Invoice</th><th>Date</th><th class="money">Amount</th><th class="money">Paid</th><th>Status</th></tr></thead><tbody>${r.invs.map(i => `<tr><td>${esc(i.number)} · ${esc(i.title)}</td><td class="dim">${fmt(i.date)}</td><td class="money">${money(docTotal(i).total)}</td><td class="money">${money(invoicePaid(c,i))}</td><td>${invoiceStatus(c,i)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">None in range.</td></tr>'}</tbody></table></div></div>
    <div><h3 class="rep-h">Labor</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Employee</th><th class="money">Hours</th><th class="money">Burdened cost</th></tr></thead><tbody>${r.labor.list.map(x => `<tr><td>${esc(x.emp)}</td><td class="money">${r2(x.hours)}</td><td class="money">${money(x.cost)}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">No approved time in range.</td></tr>'}${r.labor.list.length?`<tr style="font-weight:600"><td>Total</td><td class="money">${r.labor.hours}</td><td class="money">${money(r.labor.cost)}</td></tr>`:''}</tbody></table></div><p class="small muted">Labor = clocked hours × rate × (1 + burden). Payroll bank transactions are excluded from actual to avoid double counting.</p></div></div>`; }

function repPortfolio(){ const rows = DB.projects.map(p => ({p, r:projectProfit(p)})); const T = rows.reduce((a,{r}) => { ['contract','billedGross','collected','outstanding','budget','committed','actual','projCost','margin'].forEach(k => a[k]=(a[k]||0)+r[k]); return a; }, {});
  return `<div class="rep-head"><h2 style="margin:0">Portfolio profitability</h2><div class="small muted">${DB.projects.length} project${DB.projects.length===1?'':'s'} · prepared ${fmtL(today())}</div></div><div class="fin rep-kpis"><div class="kpi"><b>${money(T.contract)}</b><span>contracts</span></div><div class="kpi"><b>${money(T.billedGross)}</b><span>billed</span></div><div class="kpi good"><b>${money(T.collected)}</b><span>collected</span></div><div class="kpi ${T.outstanding>0?'warn':''}"><b>${money(T.outstanding)}</b><span>outstanding</span></div><div class="kpi ${T.margin>=0?'good':'warn'}"><b>${money(T.margin)} · ${T.contract?Math.round(T.margin/T.contract*100):0}%</b><span>projected margin</span></div></div>
    <div class="tw"><table class="t rep-t"><thead><tr><th>Project</th><th>Client</th><th class="money">Contract</th><th class="money">Billed</th><th class="money">Collected</th><th class="money">Outstanding</th><th class="money">Budget</th><th class="money">Committed</th><th class="money">Actual</th><th class="money">Proj. cost</th><th class="money">Margin</th><th>Complete</th></tr></thead><tbody>${rows.map(({p,r}) => `<tr class="click" data-repproj="${p.id}"><td><b>${esc(p.project.name)}</b></td><td>${esc(r.c?.name||'')}</td><td class="money">${repMoney(r.contract)}</td><td class="money">${repMoney(r.billedGross)}</td><td class="money">${repMoney(r.collected)}</td><td class="money">${repMoney(r.outstanding)}</td><td class="money">${repMoney(r.budget)}</td><td class="money">${repMoney(r.committed)}</td><td class="money">${repMoney(r.actual)}</td><td class="money">${repMoney(r.projCost)}</td><td class="money" style="color:${r.margin>=0?'inherit':'var(--bad)'}">${money(r.margin)}<div class="small muted">${r.marginPct}%</div></td><td>${Math.round(r.pctComplete*100)}%</td></tr>`).join('')}<tr style="font-weight:600"><td>Total</td><td></td>${['contract','billedGross','collected','outstanding','budget','committed','actual','projCost','margin'].map(k=>`<td class="money">${money(T[k])}</td>`).join('')}<td></td></tr></tbody></table></div>`; }

function repStatement(){ const c = DB.clients.find(x => x.id===(repClient||DB.clients[0]?.id)); if (!c) return '<div class="card muted">No client.</div>'; repClient = c.id; const f = clientFin(c); const invs = c.invoices.filter(i => i.status!=='void' && i.status!=='draft' && inRange(i.date)).sort((a,b)=>a.date.localeCompare(b.date)); const cos = c.changeOrders.filter(x => ['approved','billed'].includes(x.status)); const pays = c.payments.filter(py => inRange(py.date)).sort((a,b)=>a.date.localeCompare(b.date)); let bal = 0;
  return `<div class="rep-head"><div><h2 style="margin:0">Account statement</h2><div class="small muted">${esc(DB.company.name||'SmartDesign')} · prepared ${fmtL(today())}${repFrom||repTo?` · ${repFrom||'start'} → ${repTo||'today'}`:''}</div></div><div style="text-align:right"><div class="small muted">Balance due</div><div style="font-size:24px;font-weight:700">${money(f.outstanding)}</div></div></div>
    <div class="grid2" style="margin-bottom:12px"><div><div class="small muted">Prepared for</div><b>${esc(c.name)}</b><div class="small">${esc(c.billingAddr||'')}</div></div><div><div class="small muted">Contract summary</div><table class="t rep-t"><tbody><tr><td>Base contract${c.contractDate?` (${fmt(c.contractDate)})`:''}</td><td class="money">${money(c.contract)}</td></tr>${cos.map(x=>`<tr><td>${esc(x.number)} · ${esc(x.title)}</td><td class="money">${money(docTotal(x).total)}</td></tr>`).join('')}<tr style="font-weight:600"><td>Revised contract</td><td class="money">${money(f.revised)}</td></tr><tr><td>Invoiced to date (net of retainage)</td><td class="money">${money(f.invoiced)}</td></tr><tr><td>Retainage held</td><td class="money">${money(f.retHeld)}</td></tr><tr><td>Payments received</td><td class="money">${money(f.paid)}</td></tr><tr><td>Remaining to bill</td><td class="money">${money(f.remaining)}</td></tr></tbody></table></div></div>
    <h3 class="rep-h">Activity</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Date</th><th>Document</th><th class="money">Charges</th><th class="money">Payments</th><th class="money">Balance</th></tr></thead><tbody>${[...invs.map(i=>({d:i.date, k:'inv', x:i})), ...pays.map(py=>({d:py.date, k:'pay', x:py}))].sort((a,b)=>a.d.localeCompare(b.d)).map(e => { if (e.k==='inv'){ bal += docTotal(e.x).total; return `<tr><td class="dim">${fmt(e.d)}</td><td>${esc(e.x.number)} · ${esc(e.x.title)}${e.x.due?` <span class="small muted">due ${fmt(e.x.due)}</span>`:''}</td><td class="money">${money(docTotal(e.x).total)}</td><td></td><td class="money">${money(bal)}</td></tr>`; } bal -= +e.x.amount||0; const inv = c.invoices.find(i=>i.id===e.x.invoiceId); return `<tr><td class="dim">${fmt(e.d)}</td><td>Payment${e.x.method?' · '+esc(e.x.method):''}${inv?` <span class="small muted">applied to ${esc(inv.number)}</span>`:''}</td><td></td><td class="money">${money(e.x.amount)}</td><td class="money">${money(bal)}</td></tr>`; }).join('')||'<tr><td colspan="5" class="muted">No activity in range.</td></tr>'}</tbody></table></div>
    ${f.open.length?`<h3 class="rep-h">Open invoices</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Invoice</th><th>Due</th><th class="money">Balance</th><th>Age</th></tr></thead><tbody>${f.open.map(o=>`<tr><td>${esc(o.x.number)} · ${esc(o.x.title)}</td><td class="dim">${fmt(o.x.due)}</td><td class="money">${money(o.bal)}</td><td>${o.age>0?`<span class="pill bad">${o.age} days overdue</span>`:'current'}</td></tr>`).join('')}</tbody></table></div>`:''}
    <p class="small muted" style="margin-top:12px">${esc(DB.company.tc||'')}</p>`; }

/* custom report: pick a dataset, filter, group, sum */
const REP_DS = {
  lines:{n:'Estimate / CO lines', rows:() => DB.clients.flatMap(c => [...c.estimates.filter(e=>['approved','converted'].includes(e.status)).flatMap(e => e.lines.map(l => `estimate:${e.id}:${l.id}`)), ...c.changeOrders.filter(x=>['approved','billed'].includes(x.status)).flatMap(x => x.lines.map(l => `co:${x.id}:${l.id}`))]).map(lineFin).filter(Boolean).map(f => ({project:DB.projects.find(p=>p.id===f.doc.projectId)?.project.name||'', client:f.client.name, doc:f.doc.number, code:f.line.code||codeForLine(f.line), vendor:f.line.vendor||'', line:(f.line.num?f.line.num+'. ':'')+(f.line.item||''), contract:f.price, billed:f.billed, collected:f.collected, budget:f.budget, committed:f.committed, actual:f.actual, margin:f.margin, date:f.doc.date})), dims:['project','client','doc','code','vendor'], sums:['contract','billed','collected','budget','committed','actual','margin']},
  invoices:{n:'Invoices', rows:() => DB.clients.flatMap(c => c.invoices.filter(i=>i.status!=='void').map(i => ({project:DB.projects.find(p=>p.id===i.projectId)?.project.name||'', client:c.name, number:i.number, title:i.title, status:invoiceStatus(c,i), mode:i.mode, date:i.date, due:i.due||'', total:docTotal(i).total, retainage:docTotal(i).ret, paid:invoicePaid(c,i), balance:r2(docTotal(i).total-invoicePaid(c,i))}))), dims:['project','client','status','mode'], sums:['total','retainage','paid','balance']},
  pos:{n:'Purchase orders', rows:() => DB.pos.map(po => ({project:DB.projects.find(p=>p.id===po.projectId)?.project.name||'', vendor:po.vendor, number:po.number, status:po.status, date:po.date, expected:po.expected||'', total:poTotal(po).total, paid:poPaid(po), lines:po.lines.length})), dims:['project','vendor','status'], sums:['total','paid','lines']},
  bills:{n:'Vendor bills', rows:() => DB.bills.map(b => ({project:DB.projects.find(p=>p.id===b.projectId)?.project.name||'', vendor:b.vendor, number:b.number, status:b.status, category:b.cat||'', code:b.code||'', date:b.date, due:b.due||'', total:billTotal(b)})), dims:['project','vendor','status','category','code'], sums:['total']},
  txns:{n:'Bank transactions', rows:() => DB.txns.map(t => ({project:DB.projects.find(p=>p.id===t.projectId)?.project.name||'', vendor:t.vendor||'', category:t.cat||'', code:t.code||'', status:t.status||'', date:t.date, description:t.desc, amount:-t.amt})), dims:['project','vendor','category','code','status'], sums:['amount']},
  time:{n:'Time entries', rows:() => DB.time.map(e => { const emp = DB.employees.find(x=>x.id===e.empId); const h = hoursOf(e); return {project:DB.projects.find(p=>p.id===e.projectId)?.project.name||'', employee:emp?.name||'', code:e.code||'', status:e.status, date:e.date, hours:h, cost:r2(h*laborRate(emp))}; }), dims:['project','employee','code','status'], sums:['hours','cost']},
};
function repCustom(){ const ds = REP_DS[repDef.ds]||REP_DS.lines; const rows = ds.rows().filter(r => (!repDef.proj || r.project===repDef.proj) && (!repDef.from || (r.date||'')>=repDef.from) && (!repDef.to || (r.date||'')<=repDef.to) && (!repDef.q || JSON.stringify(r).toLowerCase().includes(repDef.q.toLowerCase())));
  const cols = rows.length ? Object.keys(rows[0]) : []; let out;
  if (repDef.group && ds.dims.includes(repDef.group)){ const g = {}; rows.forEach(r => { const k = r[repDef.group]||'(none)'; const o = g[k] = g[k]||{[repDef.group]:k, count:0}; o.count++; ds.sums.forEach(s => o[s]=(o[s]||0)+(+r[s]||0)); }); out = Object.values(g).sort((a,b)=>String(a[repDef.group]).localeCompare(String(b[repDef.group]))); }
  else out = rows;
  const oc = out.length ? Object.keys(out[0]) : []; const tot = {}; ds.sums.forEach(s => tot[s] = r2(out.reduce((a,r)=>a+(+r[s]||0),0)));
  const fmtv = (k, v) => ds.sums.includes(k) ? (k==='hours'||k==='lines'||k==='count' ? r2(v) : money(v)) : esc(String(v??''));
  return `<div class="card no-print" style="margin-bottom:12px"><div class="rep-ctl"><label>Data <select id="rc-ds">${Object.entries(REP_DS).map(([k,d]) => `<option value="${k}" ${repDef.ds===k?'selected':''}>${d.n}</option>`).join('')}</select></label><label>Project <select id="rc-proj"><option value="">All</option>${DB.projects.map(p=>`<option ${repDef.proj===p.project.name?'selected':''}>${esc(p.project.name)}</option>`).join('')}</select></label><label>Group by <select id="rc-group"><option value="">— rows —</option>${ds.dims.map(d=>`<option value="${d}" ${repDef.group===d?'selected':''}>${d}</option>`).join('')}</select></label><label>From <input type="date" id="rc-from" value="${repDef.from}"></label><label>To <input type="date" id="rc-to" value="${repDef.to}"></label><label>Contains <input id="rc-q" value="${esc(repDef.q)}" placeholder="text filter"></label><button class="btn sm" id="rc-csv">Copy as CSV</button></div></div>
    <div class="rep-head"><h2 style="margin:0">${ds.n}${repDef.group?' by '+repDef.group:''}</h2><div class="small muted">${out.length} row${out.length===1?'':'s'}${repDef.proj?' · '+esc(repDef.proj):''}${repDef.from||repDef.to?` · ${repDef.from||'start'} → ${repDef.to||'today'}`:''}</div></div>
    <div class="tw"><table class="t rep-t" id="rc-table"><thead><tr>${oc.map(k=>`<th class="${ds.sums.includes(k)||k==='count'?'money':''}">${k}</th>`).join('')}</tr></thead><tbody>${out.map(r => `<tr>${oc.map(k=>`<td class="${ds.sums.includes(k)||k==='count'?'money':''}">${fmtv(k, r[k])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${Math.max(1,oc.length)}" class="muted">No rows match.</td></tr>`}${out.length?`<tr style="font-weight:600">${oc.map((k,i)=>`<td class="${ds.sums.includes(k)?'money':''}">${i===0?'Total':ds.sums.includes(k)?fmtv(k, tot[k]):''}</td>`).join('')}</tr>`:''}</tbody></table></div>`; }
function repWireCustom(){ if (repTab!=='custom') return; const set = (id, k) => $(id)?.addEventListener('change', e => { repDef[k] = e.target.value; if (k==='ds') repDef.group = ''; render(); }); set('#rc-ds','ds'); set('#rc-proj','proj'); set('#rc-group','group'); set('#rc-from','from'); set('#rc-to','to'); set('#rc-q','q');
  $('#rc-csv')?.addEventListener('click', () => { const rows = [...document.querySelectorAll('#rc-table tr')].map(tr => [...tr.children].map(td => '"'+td.textContent.replace(/"/g,'""')+'"').join(',')).join('\n'); (navigator.clipboard?.writeText(rows) || Promise.reject()).then(() => toast('Copied — paste into Excel or Sheets'), () => { const ta = document.createElement('textarea'); ta.value = rows; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); toast('Copied'); }); }); }

/* ===================== COMPANY (CEO view) + ANALYST (anomaly engine) ===================== */
let cfoPeriod = 'ytd', anaSev = 'all';
const catType = id => CATEGORIES.find(c=>c.id===id)?.type || 'non';
const cfoCatName = id => CATEGORIES.find(c=>c.id===id)?.n || id || 'Uncategorized';
function cfoRange(){ const t = today(); const y = t.slice(0,4), m = t.slice(5,7); const q = Math.floor((+m-1)/3); if (cfoPeriod==='month') return [`${y}-${m}-01`, t]; if (cfoPeriod==='quarter') return [`${y}-${String(q*3+1).padStart(2,'0')}-01`, t]; if (cfoPeriod==='ytd') return [`${y}-01-01`, t]; if (cfoPeriod==='custom') return [repFrom||'', repTo||t]; return ['', t]; }
const within = (d, [a,b]) => (!a || (d||'')>=a) && (!b || (d||'')<=b);
/* accrual-leaning company ledger: bills entered + bank transactions not tied to a bill + payroll runs */
function ledger(range){ const rows = []; DB.bills.filter(b => BILL_COSTED.includes(b.status) && within(b.date, range)).forEach(b => rows.push({date:b.date, kind:'bill', cat:b.cat||'uncat', vendor:b.vendor, desc:`${b.vendor} · ${b.number}`, amt:billTotal(b), projectId:b.projectId||'', ref:b}));
  const viaBill = t => !!t.billId || DB.bills.some(b => b.poId && (DB.pos.find(p=>p.id===b.poId)?.matchedTxns||[]).includes(t.id)) || DB.bills.some(b => b.status==='paid' && (b.vendor||'').toLowerCase()===(t.vendor||'').toLowerCase() && Math.abs(billTotal(b)+t.amt)<1);
  DB.txns.filter(t => within(t.date, range) && t.cat!=='transfer' && t.cat!=='labor' && !viaBill(t)).forEach(t => rows.push({date:t.date, kind:'txn', cat:t.cat||'uncat', vendor:t.vendor||'', desc:t.desc, amt:t.amt>0 ? t.amt : -t.amt, income:t.amt>0 && catType(t.cat)==='inc', projectId:t.projectId||'', ref:t}));
  DB.payroll.filter(p => within(p.payDate, range)).forEach(p => { (p.alloc||[{projectId:'',pct:100}]).forEach(a => rows.push({date:p.payDate, kind:'payroll', cat: a.projectId ? 'labor' : 'payroll_oh', vendor:'Payroll', desc:`Payroll ${p.period}${a.projectId?' · '+(DB.projects.find(x=>x.id===a.projectId)?.project.name||''):' · overhead'}`, amt:r2((+p.total||0)*(+a.pct||0)/100), projectId:a.projectId||'', ref:p})); });
  return rows; }
function wipAdjustment(range, projs){ const P = DB.projects.filter(p => !projs || projs.includes(p.id)); const at = end => P.reduce((a,p) => { const J = jobFin(p, ['', end]); return a + (J.contract ? J.earned - J.billed : 0); }, 0); const before = range[0] ? iso(addDays(range[0], -1)) : ''; return r2(at(range[1]||today()) - (before ? at(before) : 0)); }
function companyPL(range){ const L = ledger(range); const invoiced = r2(DB.clients.flatMap(c=>c.invoices).filter(i => !['void','draft'].includes(i.status) && !i.retainageRelease && within(i.date, range)).reduce((a,i)=>a+docNet(i),0)); const wipAdj = wipAdjustment(range); const income = r2(invoiced + wipAdj); const collected = r2(DB.clients.flatMap(c=>c.payments).filter(p => !p.unapplied && within(p.date, range)).reduce((a,p)=>a+(+p.amount||0),0)); const accrued = r2(DB.bills.filter(b => BILL_ACCRUED.includes(b.status)).reduce((a,b)=>a+billTotal(b),0));
  const cogs = {}, oh = {}, non = {}; L.forEach(r => { if (r.income) return; const t = r.cat==='payroll_oh' ? 'oh' : catType(r.cat); const bucket = t==='cogs' ? cogs : t==='oh' ? oh : non; const k = r.cat==='payroll_oh' ? 'Payroll — office & overhead' : cfoCatName(r.cat); bucket[k] = (bucket[k]||0) + r.amt; });
  const sum = o => r2(Object.values(o).reduce((a,v)=>a+v,0)); const cogsT = sum(cogs), ohT = sum(oh); const gross = r2(income - cogsT); const net = r2(gross - ohT);
  const payroll = r2(DB.payroll.filter(p => within(p.payDate, range)).reduce((a,p)=>a+(+p.total||0),0)); const payrollOH = r2(oh['Payroll — office & overhead']||0);
  return {range, income, invoiced, wipAdj, accrued, collected, cogs, cogsT, oh, ohT, non, nonT:sum(non), gross, grossPct: income?Math.round(gross/income*100):0, net, netPct: income?Math.round(net/income*100):0, payroll, payrollOH, payrollJob:r2(payroll-payrollOH), L}; }
function monthKeys(n){ const out = []; const t = new Date(today()+'T00:00:00'); for (let i=n-1;i>=0;i--){ const d = new Date(t.getFullYear(), t.getMonth()-i, 1); out.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); } return out; }
function companyBalance(){ const cash = r2(DB.accounts.filter(a=>a.type==='bank').reduce((a,x)=>a+(+x.balance||0),0)); const cards = r2(DB.accounts.filter(a=>a.type==='card').reduce((a,x)=>a+(+x.balance||0),0)); const ar = DB.clients.map(clientFin); const arOut = r2(ar.reduce((a,f)=>a+f.outstanding,0)), arOver = r2(ar.reduce((a,f)=>a+f.overdue,0)), ret = r2(ar.reduce((a,f)=>a+f.retHeld,0)); const openBills = DB.bills.filter(b => !['paid','void','rejected'].includes(b.status)); const ap = r2(openBills.reduce((a,b)=>a+billTotal(b),0)); const apOver = r2(openBills.filter(b => b.due && parse(b.due) < parse(today())).reduce((a,b)=>a+billTotal(b),0)); const openPO = r2(DB.pos.filter(po => ['issued','partial'].includes(po.status)).reduce((a,po)=>a+Math.max(0,poTotal(po).total-poPaid(po)),0));
  const projs = DB.projects.map(projectProfit); const backlog = r2(projs.reduce((a,r)=>a+Math.max(0, r.contract - r.billedGross),0)); const wip = r2(projs.reduce((a,r)=>a+r.overUnder,0)); const burn = (() => { const m = monthKeys(3); const L = ledger([m[0]+'-01', today()]); const out = L.filter(r=>!r.income).reduce((a,r)=>a+r.amt,0); const inn = DB.clients.flatMap(c=>c.payments).filter(p => within(p.date, [m[0]+'-01', today()])).reduce((a,p)=>a+(+p.amount||0),0); return r2(Math.max(0, out-inn)/3); })();
  return {cash, cards, arOut, arOver, ret, ap, apOver, openPO, backlog, wip, burn, runway: burn ? r2((cash + cards)/burn) : null}; }
const runwayText = B => B.runway==null ? 'cash-flow positive over the last 3 months' : `${Math.round(B.runway)} months of runway at ${money(B.burn)}/mo net burn`;

function repCompany(){ const range = cfoRange(); const P = companyPL(range); const B = companyBalance(); const months = monthKeys(6); const trend = months.map(k => { const pl = companyPL([k+'-01', k+'-31']); return {k, ...pl}; });
  const kpi = (l, v, s, cls='') => `<div class="kpi ${cls}"><b>${typeof v==='number'?money(v):v}</b><span>${l}${s?' · '+s:''}</span></div>`; const label = {month:'This month', quarter:'This quarter', ytd:'Year to date', all:'All time', custom:`${repFrom||'start'} → ${repTo||'today'}`}[cfoPeriod];
  const catRows = (o, tot) => Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([k,v]) => `<tr><td>${esc(k)}</td><td class="money">${money(v)}</td><td class="dim">${P.income?Math.round(v/P.income*100):0}% of income</td><td style="width:120px"><div class="rep-bar-wrap"><i style="width:${tot?Math.round(v/tot*100):0}%;background:var(--ink-4)"></i></div></td></tr>`).join('') || '<tr><td colspan="4" class="muted">Nothing in this period.</td></tr>';
  return `<div class="rep-head"><div><h2 style="margin:0">Company</h2><div class="small muted">${label} · income = invoices issued (accrual) · costs = bills entered, bank items without a bill, payroll runs</div></div><div class="seg no-print">${['month','quarter','ytd','all'].map(k=>`<button class="${cfoPeriod===k?'on':''}" data-cfop="${k}">${{month:'Month',quarter:'Quarter',ytd:'YTD',all:'All'}[k]}</button>`).join('')}</div></div>
    <h3 class="rep-h">Profit & loss — ${label}</h3><div class="fin rep-kpis">${kpi('Revenue (earned)', P.income, `${money(P.collected)} collected`)}${kpi('Job cost (COGS)', P.cogsT, `${P.income?Math.round(P.cogsT/P.income*100):0}% of income`)}${kpi('Gross profit', P.gross, `${P.grossPct}%`, P.grossPct<25?'warn':'good')}${kpi('Overhead', P.ohT, `${P.income?Math.round(P.ohT/P.income*100):0}% of income`)}${kpi('Net profit', P.net, `${P.netPct}%`, P.net<0?'warn':'good')}</div>
    <div class="fin rep-kpis">${kpi('Payroll (all)', P.payroll, `${money(P.payrollJob)} on jobs · ${money(P.payrollOH)} overhead`)}${kpi('Cash in bank', B.cash, `available ${money(B.available)} · client funds held ${money(B.clientFunds)}`, B.available<0?'warn':'good')}${kpi('Receivables', B.arOut, `${money(B.arOver)} overdue · ${money(B.ret)} retainage`, B.arOver?'warn':'')}${kpi('Payables', B.ap, `${money(B.apOver)} overdue · ${money(B.openPO)} open POs`)}${kpi('Backlog', B.backlog, runwayText(B))}</div>
    <div class="grid2"><div><h3 class="rep-h">Job cost by category</h3><div class="tw"><table class="t rep-t"><tbody>${catRows(P.cogs, P.cogsT)}<tr style="font-weight:600"><td>Total job cost</td><td class="money">${money(P.cogsT)}</td><td></td><td></td></tr></tbody></table></div></div>
    <div><h3 class="rep-h">Overhead by category</h3><div class="tw"><table class="t rep-t"><tbody>${catRows(P.oh, P.ohT)}<tr style="font-weight:600"><td>Total overhead</td><td class="money">${money(P.ohT)}</td><td></td><td></td></tr></tbody></table></div>${P.nonT?`<p class="small muted">Excluded from P&L: ${Object.entries(P.non).map(([k,v])=>`${esc(k)} ${money(v)}`).join(' · ')} (transfers, owner draws, loans, uncategorized).</p>`:''}</div></div>
    <h3 class="rep-h">Six-month trend</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Month</th><th class="money">Income</th><th class="money">Job cost</th><th class="money">Gross</th><th class="money">Overhead</th><th class="money">Net</th><th>Net %</th></tr></thead><tbody>${trend.map(t => `<tr><td>${t.k}</td><td class="money">${repMoney(t.income)}</td><td class="money">${repMoney(t.cogsT)}</td><td class="money">${repMoney(t.gross)}</td><td class="money">${repMoney(t.ohT)}</td><td class="money" style="color:${t.net<0?'var(--bad)':'inherit'}">${repMoney(t.net)}</td><td>${t.income?t.netPct+'%':''}</td></tr>`).join('')}</tbody></table></div>
    <h3 class="rep-h">Projects</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Project</th><th class="money">Contract</th><th class="money">Billed</th><th class="money">Collected</th><th class="money">Actual cost</th><th class="money">Proj. margin</th><th>WIP</th></tr></thead><tbody>${DB.projects.map(p => { const r = projectProfit(p); return `<tr class="click" data-repproj="${p.id}"><td><b>${esc(p.project.name)}</b></td><td class="money">${money(r.contract)}</td><td class="money">${money(r.billedGross)}</td><td class="money">${money(r.collected)}</td><td class="money">${money(r.actual)}</td><td class="money">${money(r.margin)} <span class="small muted">${r.marginPct}%</span></td><td class="small">${r.overUnder>=0?`over-billed ${money(r.overUnder)}`:`under-billed ${money(-r.overUnder)}`}</td></tr>`; }).join('')}</tbody></table></div>`; }

/* ---------- analyst: rules over the live data ---------- */
function analystFindings(){ const F = []; const add = (sev, area, title, detail, amount, go) => F.push({sev, area, title, detail, amount:amount||0, go}); const t0 = today(); const days = (a,b) => Math.round((parse(b)-parse(a))/86400000);
  // 1 duplicate charges / bills
  const spend = DB.txns.filter(t => t.amt < 0 && t.cat!=='transfer'); spend.forEach((a,i) => spend.slice(i+1).forEach(b => { if (Math.abs(a.amt-b.amt)<0.01 && (a.vendor||a.desc.slice(0,12)).toLowerCase()===(b.vendor||b.desc.slice(0,12)).toLowerCase() && Math.abs(days(a.date,b.date))<=3) add('high','Banking','Possible duplicate charge', `${a.vendor||a.desc} — ${money(-a.amt)} on ${fmt(a.date)} and again ${fmt(b.date)}`, -a.amt, {view:'bank'}); }));
  DB.bills.forEach((a,i) => DB.bills.slice(i+1).forEach(b => { if (a.vendor===b.vendor && (a.number && a.number===b.number || (Math.abs(billTotal(a)-billTotal(b))<0.01 && Math.abs(days(a.date,b.date))<=7))) add('high','Bills','Possible duplicate vendor bill', `${a.vendor} ${a.number} and ${b.number} — ${money(billTotal(a))}`, billTotal(a), {view:'ap'}); }));
  // 2 bill vs PO variance
  DB.bills.filter(b => b.poId).forEach(b => { const po = DB.pos.find(p=>p.id===b.poId); if (!po) return; const billed = DB.bills.filter(x=>x.poId===po.id && x.status!=='void').reduce((a,x)=>a+billTotal(x),0); const tot = poTotal(po).total; const tol = (+DB.company.matchTol||3)/100; if (tot && billed > tot*(1+tol)) add('high','Purchasing','Vendor billed more than the PO', `${po.number} ${po.vendor}: PO ${money(tot)}, billed ${money(billed)} (+${Math.round((billed/tot-1)*100)}%)`, billed-tot, {view:'po', id:po.id}); });
  // 3 uncoded job cost
  const uncoded = DB.txns.filter(t => t.amt<0 && isJobCat(t.cat) && !t.projectId); if (uncoded.length) add('med','Banking','Job cost with no project', `${uncoded.length} transaction${uncoded.length>1?'s':''} totalling ${money(-uncoded.reduce((a,t)=>a+t.amt,0))} are coded as job cost but not assigned to a project — they are missing from every job's margin`, -uncoded.reduce((a,t)=>a+t.amt,0), {view:'bank'});
  const uncat = DB.txns.filter(t => t.amt<0 && (!t.cat || t.cat==='uncat')); if (uncat.length) add('med','Banking','Uncategorized spending', `${uncat.length} transaction${uncat.length>1?'s':''} · ${money(-uncat.reduce((a,t)=>a+t.amt,0))} not in the P&L until categorized`, -uncat.reduce((a,t)=>a+t.amt,0), {view:'bank'});
  const noline = DB.bills.filter(b => b.projectId && !b.line && b.status!=='void'); if (noline.length) add('low','Bills','Bills not tied to an estimate line', `${noline.length} bill${noline.length>1?'s':''} · ${money(noline.reduce((a,b)=>a+billTotal(b),0))} hit the project but no line — line margins understate cost`, 0, {view:'ap'});
  // 4 vendor spikes and new vendors
  const byV = {}; spend.forEach(t => { const v = (t.vendor||'').trim(); if (!v) return; (byV[v] = byV[v]||[]).push(t); }); const m = monthKeys(6); const cur = m[m.length-1];
  Object.entries(byV).forEach(([v, ts]) => { const curAmt = -ts.filter(t=>t.date.startsWith(cur)).reduce((a,t)=>a+t.amt,0); const prior = m.slice(0,-1).map(k => -ts.filter(t=>t.date.startsWith(k)).reduce((a,t)=>a+t.amt,0)); const avg = prior.reduce((a,b)=>a+b,0)/Math.max(1,prior.filter(x=>x>0).length); if (avg>0 && curAmt > avg*2 && curAmt > 1500) add('med','Vendors','Vendor spend spike', `${v}: ${money(curAmt)} this month vs ${money(avg)} average — ${Math.round(curAmt/avg*10)/10}× normal`, curAmt-avg, {view:'vendors'}); if (ts.length===1 && -ts[0].amt > 5000 && !DB.pos.some(po=>po.vendor.toLowerCase()===v.toLowerCase()) && !DB.bills.some(b=>b.vendor.toLowerCase()===v.toLowerCase())) add('med','Vendors','Large payment to a vendor with no PO or bill', `${v}: ${money(-ts[0].amt)} on ${fmt(ts[0].date)} — nothing approved on file`, -ts[0].amt, {view:'bank'}); });
  // 5 recurring charges (subscriptions)
  Object.entries(byV).forEach(([v, ts]) => { const monthsHit = new Set(ts.map(t=>t.date.slice(0,7))); if (monthsHit.size>=3 && ts.every(t => catType(t.cat)==='oh' || t.cat==='uncat')){ const sorted = ts.slice().sort((a,b)=>a.date.localeCompare(b.date)); const first = -sorted[0].amt, last = -sorted[sorted.length-1].amt; const yearly = last*12; add(last > first*1.15 ? 'med' : 'low','Overhead','Recurring charge', `${v} every month — ${money(last)}/mo (${money(yearly)}/yr)${last>first*1.15?` · up ${Math.round((last/first-1)*100)}% since ${fmt(sorted[0].date)}`:''}${!ts[0].projectId?' · not tied to a project — review if still needed':''}`, yearly, {view:'bank'}); } });
  // 6 overhead growth
  const early = +today().slice(8,10) < 10; const nowM = early ? m[m.length-2] : cur, prevM = early ? m[m.length-3] : m[m.length-2]; const ohNow = companyPL([nowM+'-01', nowM+'-31']), ohPrev = companyPL([prevM+'-01', prevM+'-31']); Object.entries(ohNow.oh).forEach(([k,v]) => { const p = ohPrev.oh[k]||0; if (p && v > p*1.25 && v-p > 500) add('med','Overhead','Overhead category growing', `${k}: ${money(v)} in ${nowM} vs ${money(p)} in ${prevM} (+${Math.round((v/p-1)*100)}%)`, v-p, {view:'reports'}); }); if (ohNow.income && ohNow.ohT/ohNow.income > 0.25) add('med','Overhead','Overhead above 25% of income', `${money(ohNow.ohT)} overhead on ${money(ohNow.income)} income in ${nowM} (${Math.round(ohNow.ohT/ohNow.income*100)}%)`, 0, {view:'reports'});
  // 7 project margin
  DB.projects.forEach(p => { const r = projectProfit(p); if (!r.contract) return; const planned = r.contract ? r.plannedMargin/r.contract*100 : 0; if (r.marginPct < planned - 5) add('high','Projects', `Margin erosion — ${p.project.name}`, `projected ${r.marginPct}% vs ${Math.round(planned)}% planned · projected cost ${money(r.projCost)} against budget ${money(r.budget)}`, r.plannedMargin - r.margin, {view:'reports', proj:p.id}); r.byCode.forEach(b => { const act = b.actual+b.labor; if (b.budget && act > b.budget*1.1) add('med','Projects', `${p.project.name}: ${b.code} ${b.name} over budget`, `${money(act)} spent vs ${money(b.budget)} budget (${Math.round(act/b.budget*100)}%)`, act-b.budget, {view:'reports', proj:p.id}); }); r.lines.filter(l => l.overCommit).forEach(l => add('med','Purchasing', `Over-committed line — ${l.line.item}`, `POs ${money(l.committed)} exceed budget ${money(l.budget)} on ${p.project.name}`, l.committed-l.budget, {view:'clients', client:r.c?.id}));
    if (r.overUnder < -5000) add('med','Billing', `Under-billed — ${p.project.name}`, `earned ${money(r.earned)} on cost-to-cost but billed ${money(r.billedGross)} — ${money(-r.overUnder)} of work done and not invoiced`, -r.overUnder, {view:'clients', client:r.c?.id});
    if (r.pctComplete >= 0.95 && r.retHeld > 0) add('low','Billing', `Retainage not released — ${p.project.name}`, `${money(r.retHeld)} held with the job ${Math.round(r.pctComplete*100)}% complete`, r.retHeld, {view:'clients', client:r.c?.id}); });
  // 8 billing hygiene
  DB.clients.forEach(c => { const f = clientFin(c); f.open.filter(o => o.age > 30).forEach(o => add(o.age>60?'high':'med','Receivables', `${c.name}: ${o.x.number} ${o.age} days overdue`, `${money(o.bal)} outstanding since ${fmt(o.x.due)}${o.age>60?' — escalate; stop new work until resolved':''}`, o.bal, {view:'clients', client:c.id}));
    c.changeOrders.filter(x => x.status==='approved').forEach(x => { const ageD = x.approvedOn ? days(x.approvedOn, t0) : 0; if (ageD > 14) add('med','Billing', `${c.name}: ${x.number} approved ${ageD} days ago, not billed`, `${money(docTotal(x).total)} approved change order waiting for the next progress invoice`, docTotal(x).total, {view:'clients', client:c.id}); });
    c.estimates.filter(e => e.template==='construction' && e.status==='converted' && !c.invoices.some(i => i.depositOf===e.id && i.status!=='void')).forEach(e => add('high','Billing', `${c.name}: no deposit invoiced on ${e.number}`, `contract ${money(docTotal(e).total)} converted, deposit never billed`, docTotal(e).total, {view:'clients', client:c.id}));
    c.invoices.filter(i => i.status==='draft' && days(i.date, t0) > 7).forEach(i => add('low','Billing', `${c.name}: ${i.number} sitting in draft ${days(i.date,t0)} days`, `${money(docTotal(i).total)} not yet sent`, docTotal(i).total, {view:'clients', client:c.id}));
    c.estimates.filter(e => e.status==='sent' && e.validUntil && parse(e.validUntil) < parse(t0)).forEach(e => add('low','Sales', `${c.name}: ${e.number} expired without a decision`, `${money(docTotal(e).total)} proposal sent ${fmt(e.date)}, valid until ${fmt(e.validUntil)} — follow up or expire it`, 0, {view:'clients', client:c.id})); });
  // 9 labor & payroll
  const byEmpWeek = {}; DB.time.forEach(e => { const h = hoursOf(e); if (!h) return; const wk = (() => { const d = parse(e.date); const s = new Date(d); s.setDate(d.getDate()-d.getDay()); return iso(s); })(); const k = e.empId+'|'+wk; byEmpWeek[k] = (byEmpWeek[k]||0)+h; if (!e.projectId) add('low','Labor','Hours with no project', `${DB.employees.find(x=>x.id===e.empId)?.name||e.empId} · ${h} h on ${fmt(e.date)} not charged to a job`, h*laborRate(DB.employees.find(x=>x.id===e.empId)), {view:'time'}); if (h > 12) add('med','Labor','Time entry over 12 hours', `${DB.employees.find(x=>x.id===e.empId)?.name||e.empId} · ${h} h on ${fmt(e.date)} — likely a missed clock-out`, 0, {view:'time'}); });
  Object.entries(byEmpWeek).forEach(([k,h]) => { if (h > 45){ const [id, wk] = k.split('|'); add('med','Labor','Overtime', `${DB.employees.find(x=>x.id===id)?.name||id} · ${r2(h)} h week of ${fmt(wk)}`, 0, {view:'time'}); } });
  DB.payroll.forEach(p => { const ohPct = (p.alloc||[]).filter(a=>!a.projectId).reduce((a,x)=>a+(+x.pct||0),0); if (ohPct > 35) add('med','Payroll', `Payroll ${p.period}: ${ohPct}% to overhead`, `${money((+p.total||0)*ohPct/100)} of ${money(p.total)} not charged to any job — check the allocation`, (+p.total||0)*ohPct/100, {view:'ap'}); });
  const hrsTot = DB.time.reduce((a,e)=>a+hoursOf(e)*laborRate(DB.employees.find(x=>x.id===e.empId)),0); const payTot = DB.payroll.reduce((a,p)=>a+(+p.gross||0),0); if (payTot && hrsTot && Math.abs(payTot-hrsTot)/payTot > 0.25) add('med','Payroll','Payroll does not match clocked hours', `payroll gross ${money(payTot)} vs ${money(hrsTot)} of clocked time at burdened rates — ${payTot>hrsTot?'hours are under-recorded or payroll includes unclocked staff':'clocked time exceeds what was paid'}`, Math.abs(payTot-hrsTot), {view:'time'});
  // 10 purchasing hygiene
  DB.pos.forEach(po => { if (po.status==='draft' && days(po.date,t0) > 7) add('low','Purchasing', `${po.number} draft for ${days(po.date,t0)} days`, `${po.vendor} · ${money(poTotal(po).total)} not issued`, 0, {view:'po', id:po.id}); if (['issued','partial'].includes(po.status) && !po.expected) add('low','Purchasing', `${po.number} has no expected delivery date`, `${po.vendor} · ${money(poTotal(po).total)} — the schedule cannot see it`, 0, {view:'po', id:po.id}); if (po.status==='received' && !DB.bills.some(b=>b.poId===po.id) && days(po.date,t0) > 14) add('low','Purchasing', `${po.number} received, no vendor bill`, `${po.vendor} · ${money(poTotal(po).total)} — accrue it or chase the invoice`, poTotal(po).total, {view:'po', id:po.id}); });
  // 10b client funds
  { const F = clientFundsSummary(); F.rows.filter(r => r.reserved > 1000 && r.daysHeld > 45).forEach(r => add('med','Cash', `Client money idle — ${r.line.item}`, `${money(r.reserved)} collected ${r.daysHeld} days ago for ${r.p?.project.name||''} and not yet spent — order it or refund it`, r.reserved, {view:'reports', tab:'funds'})); F.rows.filter(r => r.floated > 1000).forEach(r => add('med','Billing', `Floating client purchases — ${r.line.item}`, `${money(r.floated)} spent on ${r.p?.project.name||''} beyond what the client has paid for that line — bill it`, r.floated, {view:'reports', tab:'funds'})); const B2 = companyBalance(); if (B2.available < 0) add('high','Cash','Available cash is negative', `${money(B2.cash)} in the bank but ${money(B2.clientFunds)} of it belongs to client purchases still to be made`, -B2.available, {view:'reports', tab:'funds'}); }
  // 11 cash coverage
  const B = companyBalance(); if (B.runway!=null && B.runway < 3) add('high','Cash','Cash runway under 3 months', `${money(B.cash+B.cards)} net cash against ${money(B.burn)}/month net burn (spend minus collections)`, 0, {view:'bank'}); if (B.apOver > 0) add('med','Payables', `${money(B.apOver)} of vendor bills past due`, `late vendors slow the job and cost goodwill`, B.apOver, {view:'ap'}); if (B.arOut > 0 && B.ap > 0 && B.arOver > B.cash*0.5) add('med','Cash','Overdue receivables are large relative to cash', `${money(B.arOver)} overdue vs ${money(B.cash)} in bank`, 0, {view:'clients'});
  const rank = {high:0, med:1, low:2}; return F.sort((a,b) => rank[a.sev]-rank[b.sev] || b.amount-a.amount); }

function repAnalyst(){ const F = analystFindings(); const list = F.filter(f => anaSev==='all' || f.sev===anaSev); const n = s => F.filter(f=>f.sev===s).length; const P = companyPL(cfoRange()); const B = companyBalance();
  const areas = [...new Set(list.map(f=>f.area))];
  const brief = `${DB.company.name||'The company'} has ${money(P.income)} invoiced ${({month:'this month',quarter:'this quarter',ytd:'year to date',all:'to date',custom:'in the period'})[cfoPeriod]} at a ${P.grossPct}% gross and ${P.netPct}% net margin, ${money(B.cash)} in the bank, ${money(B.arOut)} receivable (${money(B.arOver)} overdue) and ${money(B.ap)} payable. ${n('high')?`${n('high')} item${n('high')>1?'s':''} need${n('high')>1?'':'s'} a decision today: ${F.filter(f=>f.sev==='high').slice(0,3).map(f=>f.title.toLowerCase()).join('; ')}.`:'Nothing urgent.'} ${n('med')?`${n('med')} worth a look this week, mostly ${(() => { const c = {}; F.filter(f=>f.sev==='med').forEach(f=>c[f.area]=(c[f.area]||0)+1); return Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0].toLowerCase()).join(' and '); })()}.`:''} Recoverable or avoidable money identified: ${money(F.filter(f=>['Possible duplicate charge','Possible duplicate vendor bill','Vendor billed more than the PO','Recurring charge'].includes(f.title)).reduce((a,f)=>a+f.amount,0))}.`;
  return `<div class="rep-head"><div><h2 style="margin:0">Analyst</h2><div class="small muted">Reviews every transaction, bill, PO, invoice, time entry and payroll run for anomalies, patterns and money left on the table. Rules run locally; the AI review adds judgment on top.</div></div><div class="row no-print" style="gap:6px"><button class="btn primary" id="ana-ai">Ask AI to review</button></div></div>
    <div class="card ana-brief"><b>Brief</b><p style="margin:6px 0 0">${brief}</p><div id="ana-ai-out"></div></div>
    <div class="row no-print" style="gap:6px;margin:12px 0 8px;flex-wrap:wrap"><div class="chips">${[['all',`All ${F.length}`],['high',`Act now ${n('high')}`],['med',`This week ${n('med')}`],['low',`Housekeeping ${n('low')}`]].map(([k,l])=>`<button class="chip ${anaSev===k?'on':''}" data-anasev="${k}">${l}</button>`).join('')}</div><span class="grow"></span><span class="small muted">${areas.join(' · ')}</span></div>
    ${list.map(f => `<div class="ana ${f.sev}" ${f.go?`data-anago='${esc(JSON.stringify(f.go))}'`:''}><span class="ana-sev">${{high:'Act now',med:'This week',low:'Housekeeping'}[f.sev]}</span><div class="ana-main"><div class="ana-title">${esc(f.title)}</div><div class="ana-detail">${f.detail}</div></div><div class="ana-side"><span class="small muted">${f.area}</span>${f.amount?`<b>${money(f.amount)}</b>`:''}</div></div>`).join('') || '<div class="card muted">No findings at this level.</div>'}`; }
function anaGo(go){ if (!go) return; if (go.view==='reports'){ repTab = 'profit'; if (go.proj) repProj = go.proj; render(); return; } if (go.view==='clients'){ if (go.client){ clientOpen = go.client; clientTab = 'fin'; finTab = 'invoices'; docOpen = null; } view = 'clients'; render(); return; } if (go.view==='po' && go.id){ poOpen = go.id; } view = go.view; render(); }
async function anaAskAI(){ const out = $('#ana-ai-out'); out.innerHTML = '<div class="small muted" style="margin-top:8px">Reviewing…</div>'; const F = analystFindings().slice(0,25); const P = companyPL(cfoRange()); const B = companyBalance(); const projs = DB.projects.map(p => { const r = projectProfit(p); return {name:p.project.name, contract:r.contract, billed:r.billedGross, collected:r.collected, budget:r.budget, committed:r.committed, actual:r.actual, margin:r.margin, marginPct:r.marginPct, overUnder:r.overUnder}; });
  const prompt = `You are the CFO's analyst for a NYC design-build contractor. Review this data and write a sharp 8–12 line memo for the CEO: what is off, what pattern you see across items, which three actions recover or protect the most money, and one question the numbers cannot answer. Be concrete with names and amounts. No preamble.\n\nP&L (${cfoPeriod}): ${JSON.stringify({income:P.income, collected:P.collected, cogs:P.cogs, overhead:P.oh, gross:P.gross, net:P.net, payroll:P.payroll, payrollOverhead:P.payrollOH})}\nBalance: ${JSON.stringify(B)}\nProjects: ${JSON.stringify(projs)}\nRule findings: ${JSON.stringify(F.map(f => ({sev:f.sev, area:f.area, title:f.title, detail:f.detail.replace(/<[^>]+>/g,''), amount:f.amount})))}`;
  try { const txt = await withTimeout(ai(prompt, 900), 60000, 'AI review'); out.innerHTML = `<div class="ana-memo">${esc(txt||'').replace(/\n/g,'<br>')}</div>`; } catch(e){ out.innerHTML = `<div class="small" style="color:var(--warn);margin-top:8px">AI review unavailable here (${esc(e.message||'no connection')}). The rule findings below stand on their own.</div>`; } }

/* ===================== CEO DASHBOARD — charts + tables ===================== */
const VZ = {c1:'#2a78d6', c2:'#eb6834', c3:'#1baf7a', c4:'#4a3aa7', good:'#0ca30c', bad:'#e34948', grid:'#E2E5EA', ink:'#4B5563', muted:'#7B8494'};
let dashPeriod = '6m', dashTables = {};
const kfmt = v => (v<0?'−':'') + (Math.abs(v) >= 1e6 ? '$'+(Math.abs(v)/1e6).toFixed(1)+'M' : Math.abs(v) >= 1000 ? '$'+Math.round(Math.abs(v)/1000)+'k' : '$'+Math.round(Math.abs(v)));
function dashRange(){ const t = today(); const d = new Date(t+'T00:00:00'); const y = d.getFullYear(), m = d.getMonth(); const ym = (yy, mm) => `${yy}-${String(mm+1).padStart(2,'0')}`; const start = (yy, mm) => { const x = new Date(yy, mm, 1); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-01`; };
  if (dashPeriod==='month') return {from:start(y,m), to:t, buckets:'week', label:'This month'}; if (dashPeriod==='quarter') return {from:start(y, Math.floor(m/3)*3), to:t, buckets:'month', label:'This quarter'}; if (dashPeriod==='6m') return {from:start(y, m-5), to:t, buckets:'month', label:'Last 6 months'}; if (dashPeriod==='year') return {from:`${y}-01-01`, to:t, buckets:'month', label:'Year to date'}; const all = [...DB.txns.map(t=>t.date), ...DB.clients.flatMap(c=>c.invoices.map(i=>i.date))].filter(Boolean).sort(); return {from:all[0]||`${y}-01-01`, to:t, buckets:'quarter', label:'All time'}; }
function dashBuckets(R){ const out = []; if (R.buckets==='week'){ let d = new Date(R.from+'T00:00:00'); while (iso(d) <= R.to){ const e = new Date(d); e.setDate(d.getDate()+6); out.push({k:`wk ${d.getMonth()+1}/${d.getDate()}`, from:iso(d), to:iso(e) < R.to ? iso(e) : R.to}); d.setDate(d.getDate()+7); } return out; }
  if (R.buckets==='quarter'){ let d = new Date(R.from.slice(0,4), Math.floor((+R.from.slice(5,7)-1)/3)*3, 1); while (iso(d) <= R.to){ const e = new Date(d.getFullYear(), d.getMonth()+3, 0); out.push({k:`Q${Math.floor(d.getMonth()/3)+1} ${String(d.getFullYear()).slice(2)}`, from:iso(d), to:iso(e)}); d = new Date(d.getFullYear(), d.getMonth()+3, 1); } return out; }
  let d = new Date(R.from.slice(0,4), +R.from.slice(5,7)-1, 1); while (iso(d) <= R.to){ const e = new Date(d.getFullYear(), d.getMonth()+1, 0); out.push({k:d.toLocaleDateString(undefined,{month:'short'})+(d.getMonth()===0||out.length===0?' '+String(d.getFullYear()).slice(2):''), from:iso(d), to:iso(e)}); d = new Date(d.getFullYear(), d.getMonth()+1, 1); } return out; }
function dashPrior(R){ const a = new Date(R.from+'T00:00:00'), b = new Date(R.to+'T00:00:00'); const len = Math.round((b-a)/86400000)+1; const pb = new Date(a); pb.setDate(a.getDate()-1); const pa = new Date(pb); pa.setDate(pb.getDate()-len+1); return [iso(pa), iso(pb)]; }

/* --- chart primitives (inline SVG, hover layer, table twin) --- */
function svgBars(id, buckets, series, opts={}){ const W = opts.w||720, H = opts.h||240, padL = 52, padR = 12, padT = 14, padB = 28; const iw = W-padL-padR, ih = H-padT-padB; const n = buckets.length; const stackMax = Math.max(1, ...buckets.map((b,i) => { const g = {}; series.filter(s=>!s.line).forEach(s => { const k = s.group||s.key; g[k] = (g[k]||0) + Math.max(0, s.data[i]||0); }); return Math.max(0, ...Object.values(g)); })); const lineMax = Math.max(0, ...series.filter(s=>s.line).flatMap(s=>s.data.map(v=>Math.abs(v)))); const max = Math.max(stackMax, lineMax) * 1.08; const lineMin = Math.min(0, ...series.filter(s=>s.line).flatMap(s=>s.data)); const min = lineMin < 0 ? lineMin*1.08 : 0;
  const y = v => padT + ih - (v - min)/(max - min) * ih; const y0 = y(0); const groups = [...new Set(series.filter(s=>!s.line).map(s=>s.group||s.key))]; const bw = iw/n; const gw = Math.min(28, (bw*0.7)/Math.max(1,groups.length)); const ticks = 4; const tickVals = Array.from({length:ticks+1}, (_,i) => min + (max-min)*i/ticks);
  let g = tickVals.map(v => `<line x1="${padL}" x2="${W-padR}" y1="${y(v)}" y2="${y(v)}" stroke="${VZ.grid}" stroke-width="1"/><text x="${padL-6}" y="${y(v)+4}" text-anchor="end" font-size="10.5" fill="${VZ.muted}">${kfmt(v)}</text>`).join('');
  buckets.forEach((b,i) => { const cx = padL + bw*i + bw/2; g += `<text x="${cx}" y="${H-8}" text-anchor="middle" font-size="10.5" fill="${VZ.ink}">${esc(b.k)}</text>`; groups.forEach((grp, gi) => { const x = cx - (groups.length*gw + (groups.length-1)*4)/2 + gi*(gw+4); let acc = 0; series.filter(s=>!s.line && (s.group||s.key)===grp).forEach(s => { const v = Math.max(0, s.data[i]||0); if (!v) return; const top = y(acc+v), bot = y(acc); const h = Math.max(0, bot-top-(acc?2:0)); g += `<rect x="${x}" y="${top}" width="${gw}" height="${h}" rx="${acc?0:3}" fill="${s.color}" data-vz="${i}"/>`; acc += v; }); }); });
  series.filter(s=>s.line).forEach(s => { const pts = buckets.map((b,i) => `${padL + bw*i + bw/2},${y(s.data[i]||0)}`); g += `<polyline points="${pts.join(' ')}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linejoin="round"/>` + buckets.map((b,i) => `<circle cx="${padL + bw*i + bw/2}" cy="${y(s.data[i]||0)}" r="4" fill="${s.color}" stroke="#fff" stroke-width="2"/>`).join(''); });
  g += `<line x1="${padL}" x2="${W-padR}" y1="${y0}" y2="${y0}" stroke="${VZ.ink}" stroke-width="1"/>`; g += buckets.map((b,i) => `<rect class="vz-hit" x="${padL + bw*i}" y="${padT}" width="${bw}" height="${ih}" fill="transparent" data-vzhit="${i}"/>`).join('');
  const legend = `<div class="vz-legend">${series.map(s => `<span><i style="background:${s.color};${s.line?'height:2px;width:14px;border-radius:1px':''}"></i>${esc(s.name)}</span>`).join('')}</div>`;
  const table = `<div class="tw"><table class="t rep-t vz-table"><thead><tr><th></th>${buckets.map(b=>`<th class="money">${esc(b.k)}</th>`).join('')}</tr></thead><tbody>${series.map(s => `<tr><td>${esc(s.name)}</td>${s.data.map(v=>`<td class="money">${money(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  return `<div class="vz" id="${id}" data-vzb='${esc(JSON.stringify({buckets:buckets.map(b=>b.k), series:series.map(s=>({name:s.name, data:s.data, color:s.color}))}))}'><div class="vz-hd">${legend}<button class="vz-toggle" data-vztoggle="${id}">${dashTables[id]?'Chart':'Table'}</button></div>${dashTables[id] ? table : `<svg viewBox="0 0 ${W} ${H}" class="vz-svg">${g}</svg><div class="vz-tip" hidden></div>`}</div>`; }
function svgHBars(id, rows, opts={}){ const max = Math.max(1, ...rows.map(r=>Math.abs(r.v))); const color = opts.color||VZ.c1; const table = `<div class="tw"><table class="t rep-t"><tbody>${rows.map(r=>`<tr><td>${esc(r.k)}</td><td class="money">${money(r.v)}</td>${r.sub!==undefined?`<td class="dim">${esc(r.sub)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;
  return `<div class="vz" id="${id}"><div class="vz-hd"><span class="small muted">${esc(opts.note||'')}</span><button class="vz-toggle" data-vztoggle="${id}">${dashTables[id]?'Chart':'Table'}</button></div>${dashTables[id] ? table : `<div class="vz-h">${rows.map(r => `<div class="vz-hrow" title="${esc(r.k)} · ${money(r.v)}"><span class="vz-hk">${esc(r.k)}</span><span class="vz-hbar"><i style="width:${Math.round(Math.abs(r.v)/max*100)}%;background:${r.color||color}"></i></span><span class="vz-hv">${money(r.v)}${r.sub!==undefined?` <span class="muted">${esc(r.sub)}</span>`:''}</span></div>`).join('')||'<div class="muted small">Nothing in this period.</div>'}</div>`}</div>`; }
function dashWire(root){ root.querySelectorAll('[data-vztoggle]').forEach(b => b.onclick = () => { dashTables[b.dataset.vztoggle] = !dashTables[b.dataset.vztoggle]; render(); });
  root.querySelectorAll('.vz[data-vzb]').forEach(vz => { const data = JSON.parse(vz.dataset.vzb); const tip = vz.querySelector('.vz-tip'); if (!tip) return; vz.querySelectorAll('[data-vzhit]').forEach(hit => { hit.addEventListener('mousemove', e => { const i = +hit.dataset.vzhit; tip.hidden = false; tip.innerHTML = `<b>${esc(data.buckets[i])}</b>${data.series.map(s => `<div><i style="background:${s.color}"></i>${esc(s.name)} <b>${money(s.data[i])}</b></div>`).join('')}`; const r = vz.getBoundingClientRect(); tip.style.left = Math.min(r.width-170, e.clientX - r.left + 12) + 'px'; tip.style.top = (e.clientY - r.top - 10) + 'px'; }); hit.addEventListener('mouseleave', () => { tip.hidden = true; }); }); }); }

/* --- data --- */
function dashData(){ const R = dashRange(); const B = dashBuckets(R); const rng = [R.from, R.to]; const P = companyPL(rng); const prior = companyPL(dashPrior(R)); const bal = companyBalance();
  const per = B.map(b => { const pl = companyPL([b.from, b.to]); const paid = DB.clients.flatMap(c=>c.payments).filter(p => within(p.date, [b.from, b.to])).reduce((a,p)=>a+(+p.amount||0),0); const out = pl.L.filter(r=>!r.income).reduce((a,r)=>a+r.amt,0); return {k:b.k, income:pl.income, cogs:pl.cogsT, oh:pl.ohT, net:pl.net, collected:paid, paidOut:out}; });
  const incomeBy = {}; DB.clients.forEach(c => c.invoices.filter(i => !['void','draft'].includes(i.status) && within(i.date, rng)).forEach(i => { const k = (DB.projects.find(p=>p.id===i.projectId)?.project.name) || c.name; incomeBy[k] = (incomeBy[k]||0) + docTotal(i).total + docTotal(i).ret; }));
  const expBy = {}; P.L.filter(r=>!r.income && (catType(r.cat)==='cogs' || catType(r.cat)==='oh' || r.cat==='payroll_oh')).forEach(r => { const k = r.cat==='payroll_oh' ? 'Payroll — overhead' : cfoCatName(r.cat); expBy[k] = (expBy[k]||0) + r.amt; });
  const vendBy = {}; P.L.filter(r=>!r.income && r.vendor && r.kind!=='payroll').forEach(r => { vendBy[r.vendor] = (vendBy[r.vendor]||0) + r.amt; });
  const top = (o, n=8) => Object.entries(o).sort((a,b)=>b[1]-a[1]).slice(0,n).map(([k,v]) => ({k, v}));
  const invs = DB.clients.flatMap(c => c.invoices.filter(i => i.status!=='void' && within(i.date, rng)).map(i => ({c, i, st:invoiceStatus(c,i), total:docTotal(i).total, paid:invoicePaid(c,i)}))); const invBy = {}; invs.forEach(x => { const b = invBy[x.st] = invBy[x.st]||{n:0, amt:0, bal:0}; b.n++; b.amt += x.total; b.bal += x.total - x.paid; });
  const aging = DB.clients.reduce((a,c) => { const f = clientFin(c); Object.keys(f.buckets).forEach(k => a[k] = (a[k]||0) + f.buckets[k]); return a; }, {});
  return {R, B, P, prior, bal, per, topIncome:top(incomeBy), topExp:top(expBy), topVend:top(vendBy), invs, invBy, aging, projects:DB.projects.map(p => ({p, r:projectProfit(p)}))}; }

function repDashboard(){ const D = dashData(); const {P, prior, bal, per} = D; const delta = (a, b) => b ? `<i class="${a>=b?'up':'down'}">${a>=b?'▲':'▼'} ${Math.abs(Math.round((a-b)/Math.abs(b)*100))}%</i> vs prior` : ''; const tile = (l, v, sub, cls='') => `<div class="dtile ${cls}"><span>${l}</span><b>${money(v)}</b><small>${sub||''}</small></div>`;
  const pl = svgBars('vz-pl', D.B, [{key:'income', name:'Income', color:VZ.c1, data:per.map(x=>x.income)}, {key:'cogs', group:'exp', name:'Job cost', color:VZ.c2, data:per.map(x=>x.cogs)}, {key:'oh', group:'exp', name:'Overhead', color:VZ.c3, data:per.map(x=>x.oh)}, {key:'net', name:'Net profit', color:VZ.c4, line:true, data:per.map(x=>x.net)}]);
  const cash = svgBars('vz-cash', D.B, [{key:'in', name:'Collected', color:VZ.c1, data:per.map(x=>x.collected)}, {key:'out', name:'Paid out', color:VZ.c2, data:per.map(x=>x.paidOut)}, {key:'netc', name:'Net cash', color:VZ.c4, line:true, data:per.map(x=>r2(x.collected-x.paidOut))}], {h:200});
  const expenses = P.cogsT + P.ohT, expensesPrior = prior.cogsT + prior.ohT;
  return `<div class="rep-head"><div><h2 style="margin:0">CEO dashboard</h2><div class="small muted">${D.R.label} · ${fmtL(D.R.from)} → ${fmtL(D.R.to)} · accrual: invoices issued vs bills, bank items without a bill, payroll</div></div><div class="seg no-print">${[['month','Month'],['quarter','Quarter'],['6m','6 months'],['year','Year'],['all','All']].map(([k,l])=>`<button class="${dashPeriod===k?'on':''}" data-dashp="${k}">${l}</button>`).join('')}</div></div>
    <div class="dtiles">${tile('Income', P.income, delta(P.income, prior.income))}${tile('Expenses', expenses, delta(expenses, expensesPrior), 'exp')}${tile('Net profit', P.net, `${P.netPct}% margin · ${delta(P.net, prior.net)}`, P.net>=0?'good':'bad')}${tile('Cash', bal.cash, `available ${money(bal.available)} after ${money(bal.clientFunds)} client funds`, bal.available<0?'bad':'')}${tile('Receivables', bal.arOut, `${money(bal.arOver)} overdue`, bal.arOver?'warn':'')}${tile('Payables', bal.ap, `${money(bal.apOver)} overdue`)}</div>
    <div class="dgrid"><div class="card dcard wide"><h3>Profit & loss by ${D.R.buckets}</h3>${pl}</div>
      <div class="card dcard"><h3>Income vs expense</h3><div class="tw"><table class="t rep-t"><thead><tr><th></th><th class="money">${esc(D.R.label)}</th><th class="money">Prior</th><th class="money">Change</th></tr></thead><tbody>${[['Income',P.income,prior.income],['Job cost',P.cogsT,prior.cogsT],['Gross profit',P.gross,prior.gross],['Overhead',P.ohT,prior.ohT],['Net profit',P.net,prior.net],['Collected (cash)',P.collected,prior.collected]].map(([k,a,b]) => `<tr ${k.includes('profit')?'style="font-weight:600"':''}><td>${k}</td><td class="money">${money(a)}</td><td class="money">${money(b)}</td><td class="money" style="color:${a-b>=0?'var(--ok)':'var(--bad)'}">${b?((a-b>=0?'+':'−')+money(Math.abs(a-b))+' · '+Math.round((a-b)/Math.abs(b)*100)+'%'):'—'}</td></tr>`).join('')}</tbody></table></div><div class="small muted" style="margin-top:6px">Gross margin ${P.grossPct}% · net margin ${P.netPct}% · overhead ${P.income?Math.round(P.ohT/P.income*100):0}% of income</div></div>
      <div class="card dcard"><h3>Top income sources</h3>${svgHBars('vz-inc', D.topIncome, {note:'invoiced, by project'})}</div>
      <div class="card dcard"><h3>Top expense categories</h3>${svgHBars('vz-exp', D.topExp, {color:VZ.c2, note:'bills, bank and payroll'})}</div>
      <div class="card dcard"><h3>Top vendors</h3>${svgHBars('vz-vend', D.topVend, {color:VZ.c2, note:'paid or billed'})}</div>
      <div class="card dcard wide"><h3>Cash flow by ${D.R.buckets}</h3>${cash}</div>
      <div class="card dcard"><h3>Invoices in period</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Status</th><th class="money">#</th><th class="money">Amount</th><th class="money">Open</th></tr></thead><tbody>${Object.entries(D.invBy).map(([k,v]) => `<tr><td><span class="pill ${k==='paid'?'ok':k==='overdue'?'bad':'info'}">${k}</span></td><td class="money">${v.n}</td><td class="money">${money(v.amt)}</td><td class="money">${money(v.bal)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">None.</td></tr>'}</tbody></table></div><h3 style="margin-top:12px">Receivables ageing</h3>${svgHBars('vz-age', [['Current','current'],['1–30','d30'],['31–60','d60'],['60+','d90']].map(([k,f]) => ({k, v:D.aging[f]||0, color: f==='current'?VZ.c1:f==='d30'?VZ.c3:f==='d60'?VZ.c2:VZ.bad})), {note:'open balances'})}</div>
      <div class="card dcard wide"><h3>By project</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Project</th><th>Client</th><th class="money">Contract</th><th class="money">Billed</th><th class="money">Collected</th><th class="money">Cost to date</th><th class="money">Proj. margin</th><th style="width:140px">Billed / complete</th></tr></thead><tbody>${D.projects.map(({p,r}) => `<tr class="click" data-repproj="${p.id}"><td><b>${esc(p.project.name)}</b></td><td>${esc(r.c?.name||'')}</td><td class="money">${money(r.contract)}</td><td class="money">${money(r.billedGross)}</td><td class="money">${money(r.collected)}</td><td class="money">${money(r.actual)}</td><td class="money" style="color:${r.margin>=0?'inherit':'var(--bad)'}">${money(r.margin)} <span class="small muted">${r.marginPct}%</span></td><td><div class="vz-dual"><i style="width:${r.contract?Math.min(100,Math.round(r.billedGross/r.contract*100)):0}%;background:${VZ.c1}"></i><i style="width:${Math.round(r.pctComplete*100)}%;background:${VZ.c2}"></i></div><span class="small muted">${r.contract?Math.round(r.billedGross/r.contract*100):0}% billed · ${Math.round(r.pctComplete*100)}% complete</span></td></tr>`).join('')}</tbody></table></div></div>
      <div class="card dcard wide"><h3>Invoice register</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Invoice</th><th>Client</th><th>Date</th><th>Due</th><th class="money">Amount</th><th class="money">Paid</th><th class="money">Balance</th><th>Status</th></tr></thead><tbody>${D.invs.sort((a,b)=>b.i.date.localeCompare(a.i.date)).map(x => `<tr><td>${esc(x.i.number)} · ${esc(x.i.title)}</td><td>${esc(x.c.name)}</td><td class="dim">${fmt(x.i.date)}</td><td class="dim">${x.i.due?fmt(x.i.due):'—'}</td><td class="money">${money(x.total)}</td><td class="money">${money(x.paid)}</td><td class="money">${money(x.total-x.paid)}</td><td><span class="pill ${x.st==='paid'?'ok':x.st==='overdue'?'bad':x.st==='draft'?'neutral':'info'}">${x.st}</span></td></tr>`).join('')||'<tr><td colspan="8" class="muted">No invoices in period.</td></tr>'}</tbody></table></div></div>
    </div>`; }

/* ===================== HOME — role-based dashboards from portlets (KPIs · meters · trends · scorecards · reminders · saved searches) ===================== */
let homeEdit = false;
const KPI_RANGES = { tm:'This month', lm:'Last month', tq:'This quarter', lq:'Last quarter', ty:'This year', ly:'Last year', l30:'Last 30 days', l90:'Last 90 days', all:'All time' };
const KPI_COMPARE = { prev:'Previous period', yoy:'Same period last year', none:'No comparison' };
function kpiRange(key){ const t = today(); const d = new Date(t+'T00:00:00'); const y = d.getFullYear(), m = d.getMonth(); const S = (yy,mm,dd=1) => { const x = new Date(yy,mm,dd); return iso(x); }; const E = (yy,mm) => iso(new Date(yy,mm+1,0));
  switch(key){ case 'tm': return [S(y,m), t]; case 'lm': return [S(y,m-1), E(y,m-1)]; case 'tq': return [S(y,Math.floor(m/3)*3), t]; case 'lq': { const q = Math.floor(m/3)*3-3; return [S(y,q), E(y,q+2)]; } case 'ty': return [`${y}-01-01`, t]; case 'ly': return [`${y-1}-01-01`, `${y-1}-12-31`]; case 'l30': return [iso(addDays(t,-29)), t]; case 'l90': return [iso(addDays(t,-89)), t]; default: return ['', t]; } }
function kpiCompareRange(key, cmp){ if (cmp==='none' || key==='all') return null; if (cmp==='prev'){ const full = {tm:'lm', tq:'lq', ty:'ly'}[key]; if (full) return kpiRange(full); const t = new Date(today()+'T00:00:00'); const S = (yy,mm) => iso(new Date(yy,mm,1)), E = (yy,mm) => iso(new Date(yy,mm+1,0)); const y = t.getFullYear(), m = t.getMonth(); if (key==='lm') return [S(y,m-2), E(y,m-2)]; if (key==='lq'){ const q = Math.floor(m/3)*3-6; return [S(y,q), E(y,q+2)]; } if (key==='ly') return [`${y-2}-01-01`, `${y-2}-12-31`]; } const [a,b] = kpiRange(key); if (cmp==='yoy'){ const s = x => { const d = new Date(x+'T00:00:00'); d.setFullYear(d.getFullYear()-1); return iso(d); }; return [s(a), s(b)]; } const da = new Date(a+'T00:00:00'), db = new Date(b+'T00:00:00'); const len = Math.round((db-da)/86400000)+1; const pb = new Date(da); pb.setDate(da.getDate()-1); const pa = new Date(pb); pa.setDate(pb.getDate()-len+1); return [iso(pa), iso(pb)]; }

/* KPI library: fn(range) → value. fmt: money | pct | int | days. good: 'up' | 'down'. go: drill-down view. */
const inR = (d, R) => within(d, R);
const invAll = () => DB.clients.flatMap(c => c.invoices.filter(i => !['void','draft'].includes(i.status)).map(i => ({c, i})));
const KPIS = {
  income:{n:'Income (invoiced)', g:'Financial', fmt:'money', good:'up', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).income},
  collected:{n:'Sales (cash basis)', g:'Financial', fmt:'money', good:'up', go:{view:'clients'}, fn:R => companyPL(R).collected},
  cogs:{n:'COGS (job cost)', g:'Financial', fmt:'money', good:'down', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).cogsT},
  opex:{n:'Operating expenses', g:'Financial', fmt:'money', good:'down', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).ohT},
  expenses:{n:'Expenses (all)', g:'Financial', fmt:'money', good:'down', go:{view:'reports', tab:'company'}, fn:R => { const p = companyPL(R); return r2(p.cogsT+p.ohT); }},
  gross:{n:'Gross profit', g:'Financial', fmt:'money', good:'up', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).gross},
  profit:{n:'Profit', g:'Financial', fmt:'money', good:'up', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).net},
  grossPct:{n:'Gross profit %', g:'Ratios', fmt:'pct', good:'up', go:{view:'reports', tab:'company'}, fn:R => { const p = companyPL(R); return p.income ? r2(p.gross/p.income*100) : 0; }},
  netPct:{n:'Net profit %', g:'Ratios', fmt:'pct', good:'up', go:{view:'reports', tab:'company'}, fn:R => companyPL(R).netPct},
  ohRatio:{n:'Overhead % of income', g:'Ratios', fmt:'pct', good:'down', go:{view:'reports', tab:'company'}, fn:R => { const p = companyPL(R); return p.income ? r2(p.ohT/p.income*100) : 0; }},
  payroll:{n:'Payroll', g:'Financial', fmt:'money', good:'down', go:{view:'ap'}, fn:R => companyPL(R).payroll},
  bank:{n:'Bank balance', g:'Cash', fmt:'money', good:'up', go:{view:'bank'}, fn:() => companyBalance().cash},
  cards:{n:'Credit card balance', g:'Cash', fmt:'money', good:'up', go:{view:'bank'}, fn:() => companyBalance().cards},
  netCash:{n:'Net cash flow', g:'Cash', fmt:'money', good:'up', go:{view:'bank'}, fn:R => { const inn = DB.clients.flatMap(c=>c.payments).filter(p => inR(p.date,R)).reduce((a,p)=>a+(+p.amount||0),0); const out = ledger(R).filter(r=>!r.income).reduce((a,r)=>a+r.amt,0); return r2(inn-out); }},
  ar:{n:'Receivables', g:'AR / AP', fmt:'money', good:'down', go:{view:'clients'}, fn:() => companyBalance().arOut},
  arOver:{n:'Overdue receivables', g:'AR / AP', fmt:'money', good:'down', go:{view:'clients'}, fn:() => companyBalance().arOver},
  retain:{n:'Retainage held', g:'AR / AP', fmt:'money', good:'down', go:{view:'clients'}, fn:() => companyBalance().ret},
  ap:{n:'Payables', g:'AR / AP', fmt:'money', good:'down', go:{view:'ap'}, fn:() => companyBalance().ap},
  apOver:{n:'Overdue payables', g:'AR / AP', fmt:'money', good:'down', go:{view:'ap'}, fn:() => companyBalance().apOver},
  dso:{n:'Days sales outstanding', g:'Ratios', fmt:'days', good:'down', go:{view:'clients'}, fn:R => { const paid = DB.clients.flatMap(c => c.payments.map(p => ({p, i:c.invoices.find(x=>x.id===p.invoiceId)}))).filter(x => x.i && inR(x.p.date,R)); if (!paid.length) return 0; return Math.round(paid.reduce((a,x)=>a+Math.max(0,(parse(x.p.date)-parse(x.i.date))/86400000),0)/paid.length); }},
  backlog:{n:'Backlog (contract − billed)', g:'Projects', fmt:'money', good:'up', go:{view:'reports', tab:'portfolio'}, fn:() => companyBalance().backlog},
  wip:{n:'Over / (under) billing', g:'Projects', fmt:'money', good:'flat', go:{view:'reports', tab:'portfolio'}, fn:() => companyBalance().wip},
  openProjects:{n:'Open projects', g:'Projects', fmt:'int', good:'up', go:{view:'port'}, fn:() => DB.projects.length},
  projMargin:{n:'Projected project margin %', g:'Projects', fmt:'pct', good:'up', go:{view:'reports', tab:'portfolio'}, fn:() => { const rs = DB.projects.map(projectProfit); const c = rs.reduce((a,r)=>a+r.contract,0); return c ? Math.round(rs.reduce((a,r)=>a+r.margin,0)/c*100) : 0; }},
  cosApproved:{n:'Change orders approved', g:'Projects', fmt:'money', good:'up', go:{view:'clients'}, fn:R => DB.clients.flatMap(c=>c.changeOrders).filter(x => ['approved','billed'].includes(x.status) && inR(x.approvedOn||x.date,R)).reduce((a,x)=>a+docTotal(x).total,0)},
  committed:{n:'Open purchase orders', g:'Purchasing', fmt:'money', good:'flat', go:{view:'po'}, fn:() => companyBalance().openPO},
  billsPending:{n:'Bills awaiting approval', g:'Purchasing', fmt:'int', good:'down', go:{view:'ap'}, fn:() => DB.bills.filter(b => ['submitted','pm-approved'].includes(b.status)).length},
  estOpen:{n:'Open estimates ($)', g:'Sales', fmt:'money', good:'up', go:{view:'clients'}, fn:() => DB.clients.flatMap(c=>c.estimates).filter(e => e.status==='sent').reduce((a,e)=>a+docTotal(e).total,0)},
  estOpenN:{n:'Open estimates (#)', g:'Sales', fmt:'int', good:'up', go:{view:'clients'}, fn:() => DB.clients.flatMap(c=>c.estimates).filter(e => e.status==='sent').length},
  estWon:{n:'Estimates won ($)', g:'Sales', fmt:'money', good:'up', go:{view:'clients'}, fn:R => DB.clients.flatMap(c=>c.estimates).filter(e => ['approved','converted'].includes(e.status) && inR(e.approvedOn||e.date,R)).reduce((a,e)=>a+docTotal(e).total,0)},
  estLost:{n:'Estimates lost / expired', g:'Sales', fmt:'int', good:'down', go:{view:'clients'}, fn:R => DB.clients.flatMap(c=>c.estimates).filter(e => ['rejected','expired'].includes(e.status) && inR(e.date,R)).length},
  winRate:{n:'Win rate %', g:'Sales', fmt:'pct', good:'up', go:{view:'clients'}, fn:R => { const es = DB.clients.flatMap(c=>c.estimates).filter(e => ['approved','converted','rejected','expired'].includes(e.status) && inR(e.date,R)); return es.length ? Math.round(es.filter(e=>['approved','converted'].includes(e.status)).length/es.length*100) : 0; }},
  newClients:{n:'New clients', g:'Sales', fmt:'int', good:'up', go:{view:'clients'}, fn:R => DB.clients.filter(c => inR(c.createdAt,R)).length},
  pipeline:{n:'M&B pipeline (active asks)', g:'Acquisitions', fmt:'money', good:'up', go:{view:'mbdeals'}, fn:() => (DB.deals||[]).filter(d => MB_ACTIVE.includes(d.status)).reduce((a,d)=>a+mbAsk(d),0)},
  hours:{n:'Hours clocked', g:'Labor', fmt:'num', good:'flat', go:{view:'time'}, fn:R => r2(DB.time.filter(e => inR(e.date,R)).reduce((a,e)=>a+hoursOf(e),0))},
  laborCost:{n:'Labor cost (burdened)', g:'Labor', fmt:'money', good:'down', go:{view:'time'}, fn:R => r2(DB.time.filter(e => inR(e.date,R)).reduce((a,e)=>a+hoursOf(e)*laborRate(DB.employees.find(x=>x.id===e.empId)),0))},
  employees:{n:'Employees', g:'Labor', fmt:'int', good:'flat', go:{view:'time'}, fn:() => DB.employees.filter(e => e.active!==false).length},
  uncat:{n:'Uncategorized transactions', g:'Hygiene', fmt:'int', good:'down', go:{view:'bank'}, fn:() => DB.txns.filter(t => !t.cat || t.cat==='uncat' || t.status==='new').length},
  actNow:{n:'Analyst: act now', g:'Hygiene', fmt:'int', good:'down', go:{view:'reports', tab:'analyst'}, fn:() => analystFindings().filter(f=>f.sev==='high').length},
};
const kpiFmt = (k, v) => { const f = KPIS[k]?.fmt; if (v==null || isNaN(v)) return '—'; if (f==='money') return money(v); if (f==='pct') return r2(v)+'%'; if (f==='days') return Math.round(v)+' d'; return (+v).toLocaleString(); };
function kpiEval(k, range, cmp){ const K = KPIS[k]; if (!K) return null; const R = kpiRange(range); const cur = K.fn(R); const CR = kpiCompareRange(range, cmp); const prev = CR ? K.fn(CR) : null; const change = prev!=null && prev!==0 ? r2((cur-prev)/Math.abs(prev)*100) : null; const dir = prev==null ? '' : cur>prev ? 'up' : cur<prev ? 'down' : ''; const good = !dir ? '' : K.good==='flat' ? 'neutral' : (dir===K.good ? 'good' : 'bad'); return {k, K, cur, prev, change, dir, good, R, CR}; }
function kpiGo(k){ const go = KPIS[k]?.go; if (!go) return; if (go.view==='reports'){ repTab = go.tab||'dash'; if (go.search) ssOpen = go.search; } if (go.view==='mbdeals' && DB.workspace!=='mb'){ setWorkspace('mb'); } view = go.view; render(); }

/* ---------- portlet catalogue and role defaults ---------- */
const PORTLETS = { kpi:'Key performance indicators', meter:'KPI meter', trend:'Trend graph', scorecard:'KPI scorecard', reminders:'Reminders', search:'Saved report (list)', snapshot:'Report snapshot (chart)', chart:'P&L chart', shortcuts:'Shortcuts', analyst:'Analyst brief' };
const SCORECARDS = {
  exec:{n:'Executive financials', rows:['income','cogs','gross','opex','profit', {f:'grossPct', n:'Gross profit %'}, {f:'netPct', n:'Net profit %'}]},
  ratios:{n:'Financial ratios', rows:[{f:'grossPct'},{f:'netPct'},{f:'ohRatio'},'dso',{f:'projMargin'}]},
  billing:{n:'Billing & collections', rows:['income','collected','ar','arOver','retain','dso','wip']},
  cash:{n:'Cash position', rows:['bank','clientFunds','availableCash','floated','netCash','ar','ap']},
  projects:{n:'Projects & backlog', rows:['openProjects','backlog','cosApproved','committed',{f:'projMargin'},'wip']},
  sales:{n:'Sales', rows:['estOpenN','estOpen','estWon','estLost',{f:'winRate'},'newClients']},
  labor:{n:'Labor', rows:['employees','hours','laborCost','payroll']},
};
const ROLE_HOME = {
  owner:{layout:3, portlets:[{type:'kpi', cfg:{kpis:['income','profit','netPct','availableCash','clientFunds','ar','arOver','ap','backlog'], range:'tm', cmp:'prev', hl:{netPct:{op:'<',v:15}, arOver:{op:'>',v:0}}}}, {type:'reminders'}, {type:'meter', cfg:{k:'grossPct', range:'tq', min:0, max:60, low:25, high:40}}, {type:'chart', cfg:{period:'6m'}}, {type:'scorecard', cfg:{preset:'exec', cols:'m3'}}, {type:'scorecard', cfg:{preset:'construction', cols:'m3'}}, {type:'analyst'}, {type:'trend', cfg:{kpis:['income','expenses','profit'], months:6}}, {type:'snapshot', cfg:{ds:'bills', group:'vendor', title:'Bills by vendor'}}, {type:'shortcuts'}]},
  pm:{layout:2, portlets:[{type:'kpi', cfg:{kpis:['backlog','wip','committed','billsPending','hours','cosApproved'], range:'tm', cmp:'prev', hl:{}}}, {type:'reminders'}, {type:'scorecard', cfg:{preset:'projects', cols:'m3'}}, {type:'search', cfg:{ds:'pos', group:'', title:'Purchase orders'}}, {type:'shortcuts'}]},
  coord:{layout:2, portlets:[{type:'reminders'}, {type:'kpi', cfg:{kpis:['committed','billsPending','apOver','hours'], range:'tm', cmp:'prev', hl:{}}}, {type:'search', cfg:{ds:'pos', group:'vendor', title:'Open POs by vendor'}}, {type:'shortcuts'}]},
};
function homeDef(){ DB.dashboards = DB.dashboards||{}; const r = role(); if (!DB.dashboards[r]){ const base = ROLE_HOME[r] || ROLE_HOME.pm; DB.dashboards[r] = JSON.parse(JSON.stringify(base)); DB.dashboards[r].portlets.forEach(p => { p.id = uid('pt'); p.cfg = p.cfg||{}; }); } return DB.dashboards[r]; }

/* ---------- reminders: what needs action, by count, each a link ---------- */
function reminders(){ const out = []; const t = today(); const B = companyBalance(); const push = (n, label, go, sev='') => { if (n) out.push({n, label, go, sev}); }; searchReminders().forEach(r => out.push(r));
  const over = DB.clients.flatMap(c => clientFin(c).open.filter(o => o.age>0)); push(over.length, 'overdue invoices · '+money(over.reduce((a,o)=>a+o.bal,0)), {view:'clients'}, 'bad');
  push(DB.clients.flatMap(c=>c.invoices).filter(i => i.status==='draft').length, 'invoices in draft', {view:'clients'});
  push(DB.clients.flatMap(c=>c.estimates).filter(e => e.status==='sent').length, 'estimates awaiting client decision', {view:'clients'});
  push(DB.clients.flatMap(c=>c.estimates).filter(e => e.status==='sent' && e.validUntil && parse(e.validUntil) < parse(t)).length, 'estimates expired', {view:'clients'}, 'warn');
  push(DB.clients.flatMap(c=>c.changeOrders).filter(x => x.status==='sent').length, 'change orders awaiting signature', {view:'clients'});
  push(DB.clients.flatMap(c=>c.changeOrders).filter(x => x.status==='approved').length, 'approved change orders to bill', {view:'clients'});
  push(DB.bills.filter(b => ['submitted','pm-approved'].includes(b.status)).length, 'vendor bills to approve', {view:'ap'}, 'warn');
  push(DB.bills.filter(b => !['paid','void','rejected'].includes(b.status) && b.due && parse(b.due) < parse(t)).length, 'vendor bills past due · '+money(B.apOver), {view:'ap'}, 'bad');
  push(DB.pos.filter(po => po.status==='draft').length, 'draft purchase orders', {view:'po'});
  push(DB.pos.filter(po => ['issued','partial'].includes(po.status) && po.expected && parse(po.expected) < parse(t)).length, 'purchase orders past expected delivery', {view:'po'}, 'warn');
  push(DB.txns.filter(t => !t.cat || t.cat==='uncat' || t.status==='new').length, 'bank transactions to categorize', {view:'bank'});
  push(DB.time.filter(e => e.status==='open' && e.date < t).length, 'time entries still open', {view:'time'}, 'warn');
  push(DB.time.filter(e => e.status==='submitted').length, 'time sheets to approve', {view:'time'});
  push((DB.deals||[]).filter(d => (mbReason(d)?.rank??9) <= 1).length, 'M&B deals needing attention', {view:'mbdash', ws:'mb'});
  push(analystFindings().filter(f=>f.sev==='high').length, 'analyst items to act on now', {view:'reports', tab:'analyst'}, 'bad');
  return out; }

/* ---------- render ---------- */
function renderHome(){ Object.keys(KPIS).filter(k=>k.startsWith('ss:')).forEach(k => delete KPIS[k]); Object.assign(KPIS, customKPIs()); const H = homeDef(); const root = homeRoot(); const cols = H.layout||2; const lock = (DB.published||{})[role()]?.lock||'unlocked'; if (lock==='locked') homeEdit = false;
  root.innerHTML = `<div class="home-bar no-print"><div><h2 style="margin:0">${esc(currentUser()?.name||'')}${currentUser()?', ':''}${fmtL(today())}</h2><div class="small muted">${esc(ROLE_NAMES[role()]||role())} dashboard · ${H.portlets.length} portlets</div></div><span class="grow"></span>${homeEdit?`<select id="home-layout" class="btn">${[1,2,3].map(n=>`<option value="${n}" ${cols===n?'selected':''}>${n} column${n>1?'s':''}</option>`).join('')}</select><select id="home-add" class="btn"><option value="">Add portlet…</option>${Object.entries(PORTLETS).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><button class="btn" id="home-reset">Reset to role default</button>`:''}${role()==='owner'?`<button class="btn" id="home-publish">Publish to roles…</button>`:''}${lock==='locked'?`<span class="small muted">Dashboard published and locked by ${esc((DB.published||{})[role()]?.by||'owner')}</span>`:`<button class="btn ${homeEdit?'primary':''}" id="home-edit">${homeEdit?'Done':'Personalize'}</button>`}</div>
    <div class="home-grid cols-${cols}">${H.portlets.map((p,i) => `<div class="portlet ${p.type==='chart'||p.type==='scorecard'||p.type==='trend'?'wide':''}" data-pt="${p.id}"><div class="portlet-hd"><b>${esc(p.cfg?.title || (p.type==='scorecard' ? (SCORECARDS[p.cfg?.preset]?.n||'Scorecard') : PORTLETS[p.type]))}</b>${homeEdit?`<span class="portlet-tools"><button data-ptsetup="${p.id}" title="Set up">Set up</button><button data-ptmove="${p.id}:-1">↑</button><button data-ptmove="${p.id}:1">↓</button>${lock==='addmove'?'':`<button data-ptrm="${p.id}">✕</button>`}</span>`:(p.type==='kpi'||p.type==='trend'||p.type==='scorecard'||p.type==='meter'?`<span class="small muted">${KPI_RANGES[p.cfg?.range]||''}</span>`:'')}</div><div class="portlet-bd">${renderPortlet(p)}</div></div>`).join('')}</div>`;
  $('#home-edit')?.addEventListener('click', () => { homeEdit = !homeEdit; render(); }); $('#home-publish')?.addEventListener('click', publishDashboard);
  $('#home-layout')?.addEventListener('change', e => { H.layout = +e.target.value; save(); render(); });
  $('#home-add')?.addEventListener('change', e => { const type = e.target.value; if (!type) return; const cfg = type==='kpi' ? {kpis:['income','profit','ar'], range:'tm', cmp:'prev', hl:{}} : type==='meter' ? {k:'grossPct', range:'tq', min:0, max:60, low:25, high:40} : type==='trend' ? {kpis:['income','profit'], months:6} : type==='scorecard' ? {preset:'exec', cols:'m3'} : type==='chart' ? {period:'6m'} : (type==='search'||type==='snapshot') ? {ds:'invoices', group:'status', title:''} : {}; H.portlets.push({id:uid('pt'), type, cfg}); save(); render(); });
  $('#home-reset')?.addEventListener('click', () => { if (!confirm('Reset this dashboard to the role default?')) return; delete DB.dashboards[role()]; save(); render(); });
  root.querySelectorAll('[data-ptmove]').forEach(b => b.onclick = () => { const [id, dir] = b.dataset.ptmove.split(':'); const i = H.portlets.findIndex(p=>p.id===id); const j = i + (+dir); if (j<0||j>=H.portlets.length) return; [H.portlets[i], H.portlets[j]] = [H.portlets[j], H.portlets[i]]; save(); render(); });
  root.querySelectorAll('[data-ptrm]').forEach(b => b.onclick = () => { H.portlets = H.portlets.filter(p=>p.id!==b.dataset.ptrm); save(); render(); });
  root.querySelectorAll('[data-ptsetup]').forEach(b => b.onclick = () => portletSetup(H.portlets.find(p=>p.id===b.dataset.ptsetup)));
  root.querySelectorAll('[data-kpigo]').forEach(el => el.onclick = () => kpiGo(el.dataset.kpigo));
  root.querySelectorAll('[data-remgo]').forEach(el => el.onclick = () => { const go = JSON.parse(el.dataset.remgo); if (go.ws==='mb') setWorkspace('mb'); if (go.tab) repTab = go.tab; if (go.search) ssOpen = go.search; if (go.po){ const po = DB.pos.find(x=>x.id===go.po); if (po && po.projectId) setCurrent(po.projectId); poOpen = go.po; } view = go.view; render(); window.scrollTo(0,0); });
  root.querySelectorAll('[data-shortcut]').forEach(el => el.onclick = () => { const [v, tab] = el.dataset.shortcut.split(':'); if (tab) repTab = tab; view = v; render(); });
  dashWire(root); }

function renderPortlet(p){ const c = p.cfg||{};
  if (p.type==='kpi'){ const rows = (c.kpis||[]).map(k => kpiEval(k, c.range||'tm', c.cmp||'prev')).filter(Boolean); const hl = (e) => { const h = c.hl?.[e.k]; if (!h) return ''; const hit = h.op==='>' ? e.cur > +h.v : e.cur < +h.v; return hit ? 'hl' : ''; };
    return `<div class="kpi-head">${rows.slice(0,4).map(e => `<div class="kpi-h ${hl(e)}" data-kpigo="${e.k}"><span>${esc(e.K.n)}</span><b>${kpiFmt(e.k, e.cur)}</b>${e.change!=null?`<i class="${e.good}">${e.dir==='up'?'▲':'▼'} ${Math.abs(e.change)}%</i>`:''}</div>`).join('')}</div>${rows.length>4?`<table class="t kpi-t"><thead><tr><th>Indicator</th><th class="money">${KPI_RANGES[c.range||'tm']}</th><th class="money">${c.cmp==='none'?'':KPI_COMPARE[c.cmp||'prev']}</th><th class="money">Change</th></tr></thead><tbody>${rows.slice(4).map(e => `<tr class="click ${hl(e)}" data-kpigo="${e.k}"><td>${esc(e.K.n)}</td><td class="money"><b>${kpiFmt(e.k, e.cur)}</b></td><td class="money dim">${e.prev!=null?kpiFmt(e.k, e.prev):'—'}</td><td class="money"><i class="chg ${e.good}">${e.change!=null?`${e.dir==='up'?'▲':'▼'} ${Math.abs(e.change)}%`:'—'}</i></td></tr>`).join('')}</tbody></table>`:''}`; }
  if (p.type==='meter'){ const e = kpiEval(c.k||'grossPct', c.range||'tq', 'none'); if (!e) return ''; const min = +c.min||0, max = +c.max||100, lo = +c.low||0, hi = +c.high||0; const v = Math.max(min, Math.min(max, e.cur)); const ang = (v-min)/(max-min)*180; const zone = e.cur < lo ? 'bad' : e.cur < hi ? 'warn' : 'ok'; const arc = (a0, a1, col) => { const r = 70, cx = 90, cy = 84; const P = a => [cx + r*Math.cos(Math.PI*(1 - a/180)), cy - r*Math.sin(Math.PI*(1 - a/180))]; const [x0,y0] = P(a0), [x1,y1] = P(a1); return `<path d="M${x0} ${y0} A${r} ${r} 0 ${a1-a0>180?1:0} 1 ${x1} ${y1}" fill="none" stroke="${col}" stroke-width="14" stroke-linecap="butt"/>`; }; const t = x => (x-min)/(max-min)*180; const nx = 90 + 62*Math.cos(Math.PI*(1-ang/180)), ny = 84 - 62*Math.sin(Math.PI*(1-ang/180));
    return `<div class="meter" data-kpigo="${e.k}"><svg viewBox="0 0 180 100">${arc(0, t(lo), '#FBECEA')}${arc(t(lo), t(hi), '#FFF3E0')}${arc(t(hi), 180, '#E6F4EC')}<line x1="90" y1="84" x2="${nx}" y2="${ny}" stroke="var(--ink)" stroke-width="3" stroke-linecap="round"/><circle cx="90" cy="84" r="5" fill="var(--ink)"/><text x="12" y="98" font-size="9" fill="#7B8494">${kpiFmt(e.k,min)}</text><text x="168" y="98" font-size="9" fill="#7B8494" text-anchor="end">${kpiFmt(e.k,max)}</text></svg><div class="meter-v ${zone}"><b>${kpiFmt(e.k, e.cur)}</b><span>${esc(e.K.n)} · ${KPI_RANGES[c.range||'tq']}</span><span class="small">target ${kpiFmt(e.k,hi)} · floor ${kpiFmt(e.k,lo)}</span></div></div>`; }
  if (p.type==='trend'){ const n = +c.months||6; const months = monthKeys(n); const buckets = months.map(k => ({k:k.slice(5)+'/'+k.slice(2,4), from:k+'-01', to:k+'-31'})); const cols = [VZ.c1, VZ.c2, VZ.c4]; const series = (c.kpis||[]).slice(0,3).map((k,i) => ({key:k, name:KPIS[k]?.n||k, color:cols[i], line:i>0, data:buckets.map(b => +KPIS[k].fn([b.from,b.to])||0)})); return svgBars('vz-'+p.id, buckets, series, {h:200}); }
  if (p.type==='scorecard'){ const sc = SCORECARDS[c.preset]||SCORECARDS.exec; const colsDef = c.cols==='q3' ? (() => { const t = new Date(today()+'T00:00:00'); return [2,1,0].map(i => { const q = Math.floor(t.getMonth()/3)-i; const y = t.getFullYear() + Math.floor(q/3); const qq = ((q%4)+4)%4; return {k:`Q${qq+1} ${String(y).slice(2)}`, R:[iso(new Date(y,qq*3,1)), iso(new Date(y,qq*3+3,0))]}; }); })() : monthKeys(3).map(k => ({k, R:[k+'-01', k+'-31']})); const vals = {};
    const rowV = (r) => { const key = typeof r==='string' ? r : r.f; return colsDef.map(cd => { const v = KPIS[key].fn(cd.R); return v; }); };
    return `<div class="tw"><table class="t sc"><thead><tr><th>KPI</th>${colsDef.map(cd=>`<th class="money">${cd.k}</th>`).join('')}<th class="money">Change</th><th>Benchmark</th></tr></thead><tbody>${sc.rows.map(r => { const key = typeof r==='string' ? r : r.f; const label = (typeof r==='object' && r.n) || KPIS[key]?.n || key; const v = rowV(r); const a = v[v.length-2], b = v[v.length-1]; const ch = a ? r2((b-a)/Math.abs(a)*100) : null; const K = KPIS[key]; const good = ch==null ? '' : K.good==='flat' ? 'neutral' : ((ch>0?'up':'down')===K.good ? 'good' : 'bad'); return `<tr class="click ${typeof r==='object'?'formula':''}" data-kpigo="${key}"><td>${esc(label)}${typeof r==='object'?' <span class="small muted">ƒ</span>':''}</td>${v.map(x=>`<td class="money">${kpiFmt(key,x)}</td>`).join('')}<td class="money"><i class="chg ${good}">${ch!=null?`${ch>0?'▲':ch<0?'▼':''} ${Math.abs(ch)}%`:'—'}</i></td><td class="small muted">${esc(K?.bench||'')}</td></tr>`; }).join('')}</tbody></table></div>`; }
  if (p.type==='reminders'){ const rs = reminders(); return `<div class="rem">${rs.map(r => `<div class="rem-row ${r.sev}" data-remgo='${esc(JSON.stringify(r.go))}'><b>${r.n}</b><span>${esc(r.label)}</span></div>`).join('')||'<div class="muted small">Nothing waiting on you.</div>'}</div>`; }
  if (p.type==='search' || p.type==='snapshot'){ const ds = REP_DS[c.ds]||REP_DS.invoices; let rows = ds.rows(); if (c.proj) rows = rows.filter(r => r.project===c.proj); const sums = ds.sums; let out; if (c.group && ds.dims.includes(c.group)){ const g = {}; rows.forEach(r => { const k = r[c.group]||'(none)'; const o = g[k] = g[k]||{[c.group]:k, count:0}; o.count++; sums.forEach(s => o[s]=(o[s]||0)+(+r[s]||0)); }); out = Object.values(g).sort((a,b)=>(b[sums[0]]||0)-(a[sums[0]]||0)); } else out = rows.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))); out = out.slice(0, p.type==='snapshot' ? 8 : 10);
    if (p.type==='snapshot'){ const key = c.group||ds.dims[0]; const s = sums[0]; return svgHBars('vz-'+p.id, out.map(r => ({k:String(r[key]||r[ds.dims[0]]||''), v:+r[s]||0})), {note:`${ds.n} · ${s}`}); }
    const oc = out.length ? Object.keys(out[0]).slice(0,5) : []; return `<div class="tw"><table class="t"><thead><tr>${oc.map(k=>`<th class="${sums.includes(k)||k==='count'?'money':''}">${k}</th>`).join('')}</tr></thead><tbody>${out.map(r => `<tr>${oc.map(k=>`<td class="${sums.includes(k)||k==='count'?'money':''}">${sums.includes(k)?(k==='hours'||k==='lines'?r2(r[k]):money(r[k])):esc(String(r[k]??''))}</td>`).join('')}</tr>`).join('')||'<tr><td class="muted">No rows.</td></tr>'}</tbody></table></div><div class="small muted" style="margin-top:4px"><a href="#" data-shortcut="reports:custom">Open in Custom report</a></div>`; }
  if (p.type==='chart'){ const keep = dashPeriod; dashPeriod = c.period||'6m'; const D = dashData(); dashPeriod = keep; return svgBars('vz-'+p.id, D.B, [{key:'income', name:'Income', color:VZ.c1, data:D.per.map(x=>x.income)}, {key:'cogs', group:'exp', name:'Job cost', color:VZ.c2, data:D.per.map(x=>x.cogs)}, {key:'oh', group:'exp', name:'Overhead', color:VZ.c3, data:D.per.map(x=>x.oh)}, {key:'net', name:'Net profit', color:VZ.c4, line:true, data:D.per.map(x=>x.net)}], {h:220}); }
  if (p.type==='analyst'){ const F = analystFindings().slice(0,5); return `<div class="rem">${F.map(f => `<div class="rem-row ${f.sev==='high'?'bad':f.sev==='med'?'warn':''}" data-remgo='{"view":"reports","tab":"analyst"}'><b>${f.amount?money(f.amount):'·'}</b><span><b>${esc(f.title)}</b><br><span class="small muted">${f.detail}</span></span></div>`).join('')||'<div class="muted small">No findings.</div>'}</div>`; }
  if (p.type==='shortcuts'){ const items = [['reports:funds','Client funds'],['reports:flash','Weekly flash'],['reports:dash','CEO dashboard'],['reports:financials','Financial statements'],['reports:wip','WIP schedule'],['reports:budget','Budget vs actual'],['reports:pack','Monthly pack'],['reports:searches','Saved searches'],['reports:company','Company P&L'],['reports:analyst','Analyst'],['reports:profit','Project profitability'],['reports:statement','Client statement'],['reports:custom','Custom report'],['clients','Clients & billing'],['po','Purchasing'],['ap','Bills & payroll'],['bank','Banking'],['costs','Costs'],['time','Time & crew']].filter(([k]) => ROLE_VIEWS[role()].includes(k.split(':')[0])); return `<div class="shortcuts">${items.map(([k,l]) => `<button data-shortcut="${k}">${l}</button>`).join('')}</div>`; }
  return ''; }

function portletSetup(p){ if (!p) return; const c = p.cfg = p.cfg||{}; const kpiOpts = (sel=[]) => Object.entries(KPIS).map(([k,K]) => `<label class="chk"><input type="checkbox" data-f="k:${k}" ${sel.includes(k)?'checked':''}> ${esc(K.n)} <span class="small muted">${K.g}</span></label>`).join(''); const rangeSel = (f, v) => mbSel(f, Object.entries(KPI_RANGES), v||'tm'); const kpiSingle = (f, v) => mbSel(f, Object.entries(KPIS).map(([k,K])=>[k,K.n]), v);
  let body = mbF('Title (optional)', mbIn('title', c.title||'', PORTLETS[p.type]));
  if (p.type==='kpi') body += `<div class="grid2">${mbF('Range', rangeSel('range', c.range))}${mbF('Compare to', mbSel('cmp', Object.entries(KPI_COMPARE), c.cmp||'prev'))}</div><div class="f"><label>Indicators <span class="small muted">first four are headlines</span></label><div class="kpi-pick">${kpiOpts(c.kpis)}</div></div><div class="f"><label>Highlight when</label><div class="grid2">${mbF('Indicator', kpiSingle('hlk', Object.keys(c.hl||{})[0]||''))}<div class="f"><label>Condition</label><div class="row" style="gap:6px">${mbSel('hlop', [['<','below'],['>','above']], (Object.values(c.hl||{})[0]||{}).op||'<')}${mbIn('hlv', (Object.values(c.hl||{})[0]||{}).v??'', 'value', 'number')}</div></div></div></div>`;
  if (p.type==='meter') body += `${mbF('Indicator', kpiSingle('k', c.k||'grossPct'))}${mbF('Range', rangeSel('range', c.range||'tq'))}<div class="grid2">${mbF('Scale from', mbIn('min', c.min??0, '', 'number'))}${mbF('Scale to', mbIn('max', c.max??100, '', 'number'))}${mbF('Red below', mbIn('low', c.low??0, '', 'number'))}${mbF('Green above (target)', mbIn('high', c.high??0, '', 'number'))}</div>`;
  if (p.type==='trend') body += `${mbF('Months', mbSel('months', [['3','3'],['6','6'],['12','12']], String(c.months||6)))}<div class="f"><label>Indicators <span class="small muted">up to three — first as bars, others as lines</span></label><div class="kpi-pick">${kpiOpts(c.kpis)}</div></div>`;
  if (p.type==='scorecard') body += `${mbF('Scorecard', mbSel('preset', Object.entries(SCORECARDS).map(([k,s])=>[k,s.n]), c.preset||'exec'))}${mbF('Columns', mbSel('cols', [['m3','Last 3 months'],['q3','Last 3 quarters']], c.cols||'m3'))}`;
  if (p.type==='chart') body += mbF('Period', mbSel('period', [['month','Month'],['quarter','Quarter'],['6m','6 months'],['year','Year'],['all','All']], c.period||'6m'));
  if (p.type==='search' || p.type==='snapshot') body += `${mbF('Data', mbSel('ds', Object.entries(REP_DS).map(([k,d])=>[k,d.n]), c.ds||'invoices'))}${mbF('Group by (optional)', mbIn('group', c.group||'', 'e.g. vendor, status, project, code'))}${mbF('Project (optional, exact name)', mbIn('proj', c.proj||''))}`;
  mbModal(`Set up — ${PORTLETS[p.type]}`, body, {onSubmit: f => { c.title = f.title||''; if (p.type==='kpi'){ c.range = f.range; c.cmp = f.cmp; c.kpis = Object.keys(f).filter(k=>k.startsWith('k:') && f[k]).map(k=>k.slice(2)); c.hl = f.hlk && f.hlv!=='' ? {[f.hlk]:{op:f.hlop, v:+f.hlv}} : {}; } if (p.type==='meter'){ c.k = f.k; c.range = f.range; c.min = +f.min; c.max = +f.max; c.low = +f.low; c.high = +f.high; } if (p.type==='trend'){ c.months = +f.months; c.kpis = Object.keys(f).filter(k=>k.startsWith('k:') && f[k]).map(k=>k.slice(2)).slice(0,3); } if (p.type==='scorecard'){ c.preset = f.preset; c.cols = f.cols; } if (p.type==='chart') c.period = f.period; if (p.type==='search'||p.type==='snapshot'){ c.ds = f.ds; c.group = f.group.trim(); c.proj = f.proj.trim(); } save(); render(); }}); }

/* ===================== CONSTRUCTION FINANCE — entity context · WIP schedule · profit fade · backlog · budgets · financial statements · management pack · weekly flash ===================== */
let repEntity = '', repCol = 'time', budgetYear = '';
const entName = id => (DB.entities||[]).find(e=>e.id===id)?.name || 'Consolidated';
function entityOfTxn(t){ return DB.accounts.find(a=>a.id===t.acct)?.entityId || 'ent1'; }
function entityOfTime(e){ return DB.employees.find(x=>x.id===e.empId)?.entityId || 'ent1'; }
function entityOfProject(p){ return p.entityId || 'ent1'; }
/* entity-scoped ledger: wraps the company ledger so every report can be run per subsidiary or consolidated */
const ledgerBase = ledger;
ledger = function(range){ const rows = ledgerBase(range); if (!repEntity) return rows; return rows.filter(r => r.kind==='bill' ? (r.ref.entityId||'ent1')===repEntity : r.kind==='payroll' ? (r.ref.entityId||'ent1')===repEntity : entityOfTxn(r.ref)===repEntity); };
const companyPLBase = companyPL;
companyPL = function(range){ const P = companyPLBase(range); if (!repEntity) return P; const projs = DB.projects.filter(p => entityOfProject(p)===repEntity).map(p=>p.id); P.invoiced = r2(DB.clients.flatMap(c=>c.invoices).filter(i => !['void','draft'].includes(i.status) && !i.retainageRelease && within(i.date, range) && projs.includes(i.projectId)).reduce((a,i)=>a+docNet(i),0)); P.wipAdj = wipAdjustment(range, projs); P.income = r2(P.invoiced + P.wipAdj); P.collected = r2(DB.clients.flatMap(c=>c.payments.map(p=>({p, i:c.invoices.find(x=>x.id===p.invoiceId)}))).filter(x => !x.p.unapplied && within(x.p.date, range) && x.i && projs.includes(x.i.projectId)).reduce((a,x)=>a+(+x.p.amount||0),0)); P.gross = r2(P.income - P.cogsT); P.net = r2(P.gross - P.ohT); P.grossPct = P.income?Math.round(P.gross/P.income*100):0; P.netPct = P.income?Math.round(P.net/P.income*100):0; P.payroll = r2(DB.payroll.filter(p => within(p.payDate, range) && (p.entityId||'ent1')===repEntity).reduce((a,p)=>a+(+p.total||0),0)); return P; };
function entityBar(){ return `<div class="ent-bar no-print"><span class="small muted">Entity</span><div class="seg">${[['','Consolidated'], ...(DB.entities||[]).map(e=>[e.id, e.name.replace(/ LLC$/,'')])].map(([k,l]) => `<button class="${repEntity===k?'on':''}" data-ent="${k}">${esc(l)}</button>`).join('')}</div></div>`; }

/* ---------- WIP schedule (CFMA layout) ---------- */
function wipRow(p){ const J = jobFin(p); const c = J.c;
  return {p, c, J, orig:J.base, cos:J.coAmt, pending:J.pendingCO, contract:J.contract, eac:J.eac, estGP:J.estGP, gpPct:J.estGPPct, costToDate:J.actual, pct:J.pct, earned:J.earned, billed:J.billed, over:J.over, under:J.under, ctc:r2(J.eac-J.actual), gpToDate:r2(J.earned-J.actual), retain:J.retHeld, bidGP:J.plannedGP, bidGPPct:J.plannedGPPct, backlog:J.backlog, backlogGP:J.backlogGP}; }
function wipSnapshot(){ DB.wipHistory = DB.wipHistory||[]; const m = today().slice(0,7); DB.projects.forEach(p => { const w = wipRow(p); const ex = DB.wipHistory.find(h => h.month===m && h.projectId===p.id); const rec = {month:m, projectId:p.id, contract:w.contract, eac:w.eac, estGP:w.estGP, gpPct:w.gpPct, pct:r2(w.pct*100), earned:w.earned, billed:w.billed}; if (ex) Object.assign(ex, rec); else DB.wipHistory.push(rec); }); }
function fadeFor(p, w){ const hist = (DB.wipHistory||[]).filter(h => h.projectId===p.id && h.month < today().slice(0,7)).sort((a,b)=>a.month.localeCompare(b.month)); const prior = hist[hist.length-1]; return {prior, fadePts: prior ? r2(w.gpPct - prior.gpPct) : null, fadeAmt: prior ? r2(w.estGP - prior.estGP) : null, vsBidPts: r2(w.gpPct - w.bidGPPct), vsBidAmt: r2(w.estGP - w.bidGP)}; }
function repWIP(){ wipSnapshot(); const rows = DB.projects.filter(p => !repEntity || entityOfProject(p)===repEntity).map(p => ({w:wipRow(p), f:fadeFor(p, wipRow(p))})).filter(x => x.w.contract); const T = rows.reduce((a,{w}) => { ['contract','eac','estGP','costToDate','earned','billed','over','under','ctc','gpToDate','retain','backlog','backlogGP','pending'].forEach(k => a[k]=(a[k]||0)+w[k]); return a; }, {}); const P = companyPL(kpiRange('ty')); const B = companyBalance(); const avgRev = (() => { const m = monthKeys(6); const inc = companyPL([m[0]+'-01', today()]).income; return inc/6; })();
  const M = v => v ? money(v) : '<span class="muted">—</span>';
  return `<div class="rep-head"><div><h2 style="margin:0">Work-in-progress schedule</h2><div class="small muted">Cost-to-cost percentage of completion · ${entName(repEntity)} · as of ${fmtL(today())}</div></div></div>${entityBar()}
    <div class="fin rep-kpis"><div class="kpi"><b>${money(T.contract)}</b><span>revised contracts · ${money(T.pending)} pending COs (memo)</span></div><div class="kpi"><b>${money(T.estGP)} · ${T.contract?r2(T.estGP/T.contract*100):0}%</b><span>estimated gross profit at completion</span></div><div class="kpi ${T.over>T.contract*0.1?'warn':''}"><b>${money(T.over)}</b><span>billings in excess of earnings (liability)${B.cash&&T.over?` · cash-to-overbillings ${r2(B.cash/T.over)}`:''}</span></div><div class="kpi ${T.under>0?'warn':''}"><b>${money(T.under)}</b><span>earnings in excess of billings (asset) · unbilled work</span></div><div class="kpi"><b>${money(T.backlog)}</b><span>backlog · ${money(T.backlogGP)} backlog GP · ${avgRev?r2(T.backlog/avgRev):'—'} months at recent run-rate</span></div></div>
    <div class="tw"><table class="t rep-t wip"><thead><tr><th>Job</th><th class="money">Original</th><th class="money">Appr. COs</th><th class="money">Revised contract</th><th class="money">Est. total cost</th><th class="money">Est. GP</th><th class="money">GP %</th><th class="money">Cost to date</th><th class="money">% complete</th><th class="money">Earned revenue</th><th class="money">Billed to date</th><th class="money">Over-billed</th><th class="money">Under-billed</th><th class="money">Cost to complete</th><th class="money">Retainage rec.</th><th class="money">Fade vs prior</th><th class="money">Fade vs bid</th></tr></thead><tbody>${rows.map(({w,f}) => `<tr class="click" data-repproj="${w.p.id}"><td><b>${esc(w.p.project.name)}</b><div class="small muted">${esc(w.c?.name||'')}${w.pending?` · pending COs ${money(w.pending)}`:''}</div></td><td class="money">${M(w.orig)}</td><td class="money">${M(w.cos)}</td><td class="money">${money(w.contract)}</td><td class="money">${money(w.eac)}</td><td class="money">${money(w.estGP)}</td><td class="money">${w.gpPct}%</td><td class="money">${money(w.costToDate)}</td><td class="money">${Math.round(w.pct*100)}%</td><td class="money">${money(w.earned)}</td><td class="money">${money(w.billed)}</td><td class="money ${w.over?'warn':''}">${M(w.over)}</td><td class="money ${w.under?'warn':''}">${M(w.under)}</td><td class="money">${money(w.ctc)}</td><td class="money">${M(w.retain)}</td><td class="money" style="color:${f.fadePts==null?'inherit':f.fadePts<0?'var(--bad)':'var(--ok)'}">${f.fadePts==null?'<span class="muted">first month</span>':`${f.fadePts>0?'+':''}${f.fadePts} pts<div class="small">${money(f.fadeAmt)}</div>`}</td><td class="money" style="color:${f.vsBidPts<0?'var(--bad)':'var(--ok)'}">${f.vsBidPts>0?'+':''}${f.vsBidPts} pts<div class="small">${money(f.vsBidAmt)}</div></td></tr>`).join('')||'<tr><td colspan="17" class="muted">No contracts.</td></tr>'}<tr style="font-weight:600"><td>Total</td><td class="money">${money(rows.reduce((a,{w})=>a+w.orig,0))}</td><td class="money">${money(rows.reduce((a,{w})=>a+w.cos,0))}</td><td class="money">${money(T.contract)}</td><td class="money">${money(T.eac)}</td><td class="money">${money(T.estGP)}</td><td class="money">${T.contract?r2(T.estGP/T.contract*100):0}%</td><td class="money">${money(T.costToDate)}</td><td class="money">${T.eac?Math.round(T.costToDate/T.eac*100):0}%</td><td class="money">${money(T.earned)}</td><td class="money">${money(T.billed)}</td><td class="money">${money(T.over)}</td><td class="money">${money(T.under)}</td><td class="money">${money(T.ctc)}</td><td class="money">${money(T.retain)}</td><td></td><td></td></tr></tbody></table></div>
    <p class="small muted" style="margin-top:8px">Revised contract = base contract + approved change orders (pending COs shown as memo only). Estimated total cost = actual + the PM's cost-to-complete review when one exists; otherwise the greater of estimate budget and actual + open POs. % complete = cost to date ÷ estimated total cost. Earned = contract × % complete. Over/under = billed − earned. Fade compares GP% to the prior month-end snapshot (snapshots are captured automatically each month this report is opened) and to the original bid margin.</p>
    <h3 class="rep-h">Backlog by job</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Job</th><th class="money">Contract</th><th class="money">Earned</th><th class="money">Backlog</th><th class="money">Backlog GP</th><th class="money">% complete</th><th>Remaining</th></tr></thead><tbody>${rows.map(({w}) => `<tr><td>${esc(w.p.project.name)}</td><td class="money">${money(w.contract)}</td><td class="money">${money(w.earned)}</td><td class="money">${money(w.backlog)}</td><td class="money">${money(w.backlogGP)}</td><td class="money">${Math.round(w.pct*100)}%</td><td><div class="rep-bar-wrap"><i style="width:${Math.round((1-w.pct)*100)}%;background:var(--accent)"></i></div></td></tr>`).join('')}</tbody></table></div><p class="small muted">CFMA rule of thumb: backlog gross profit should cover at least half of annual overhead — this year's overhead to date is ${money(P.ohT)}${P.ohT?` (${Math.round(T.backlogGP/P.ohT*100)}% covered)`:''}.</p>`; }

/* ---------- budgets (native-style: category × month) and budget vs actual ---------- */
function budgetCats(){ return [{id:'income', n:'Revenue (earned)', type:'inc'}, ...CATEGORIES.filter(c => c.type==='cogs' || c.type==='oh'), {id:'payroll_oh', n:'Payroll — office & overhead', type:'oh'}]; }
function budgetFor(year){ DB.budgets = DB.budgets||{}; if (!DB.budgets[year]){ const b = {}; budgetCats().forEach(c => b[c.id] = Array(12).fill(0)); DB.budgets[year] = b; } budgetCats().forEach(c => { if (!DB.budgets[year][c.id]) DB.budgets[year][c.id] = Array(12).fill(0); }); return DB.budgets[year]; }
function budgetSeedFromActuals(year){ const b = budgetFor(year); const prev = String(+year-1); budgetCats().forEach(c => { for (let m=0;m<12;m++){ const R = [`${prev}-${String(m+1).padStart(2,'0')}-01`, iso(new Date(+prev, m+1, 0))]; const P = companyPL(R); const v = c.id==='income' ? P.income : c.id==='payroll_oh' ? P.payrollOH : (c.type==='cogs' ? P.cogs : P.oh)[c.n]||0; b[c.id][m] = r2(v*1.05); } }); }
function actualsByCat(year){ const out = {}; budgetCats().forEach(c => out[c.id] = Array(12).fill(0)); for (let m=0;m<12;m++){ const R = [`${year}-${String(m+1).padStart(2,'0')}-01`, iso(new Date(+year, m+1, 0))]; if (R[0] > today()) break; const P = companyPL(R); out.income[m] = P.income; out.payroll_oh[m] = P.payrollOH; CATEGORIES.forEach(c => { if (c.type==='cogs') out[c.id][m] = P.cogs[c.n]||0; if (c.type==='oh') out[c.id][m] = P.oh[c.n]||0; }); } return out; }
function repBudget(){ const year = budgetYear || today().slice(0,4); budgetYear = year; const b = budgetFor(year); const A = actualsByCat(year); const cats = budgetCats(); const mNow = +today().slice(5,7); const ytd = arr => arr.slice(0, mNow).reduce((a,v)=>a+v,0); const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const line = (c, cls='') => { const bud = ytd(b[c.id]), act = ytd(A[c.id]); const varr = c.type==='inc' ? act-bud : bud-act; return `<tr class="${cls}"><td>${esc(c.n)}</td><td class="money">${money(act)}</td><td class="money">${money(bud)}</td><td class="money" style="color:${varr>=0?'var(--ok)':'var(--bad)'}">${money(varr)}</td><td class="money">${bud?Math.round(act/bud*100):'—'}${bud?'%':''}</td><td class="money">${money(b[c.id].reduce((a,v)=>a+v,0))}</td></tr>`; };
  const sum = (ids, arr) => ids.reduce((a,id)=>a+ytd(arr[id]),0); const cogsIds = cats.filter(c=>c.type==='cogs').map(c=>c.id), ohIds = cats.filter(c=>c.type==='oh').map(c=>c.id); const gpA = ytd(A.income)-sum(cogsIds,A), gpB = ytd(b.income)-sum(cogsIds,b); const netA = gpA - sum(ohIds,A), netB = gpB - sum(ohIds,b);
  return `<div class="rep-head"><div><h2 style="margin:0">Budget vs actual</h2><div class="small muted">${year} year to date through ${months[mNow-1]} · ${entName(repEntity)}</div></div><div class="row no-print" style="gap:6px"><select id="bud-year" class="btn">${[+year-1, +year, +year+1].map(y=>`<option ${String(y)===year?'selected':''}>${y}</option>`).join('')}</select><button class="btn" id="bud-seed">Seed from last year +5%</button><button class="btn" id="bud-edit">Edit budget</button></div></div>${entityBar()}
    <div class="tw"><table class="t rep-t"><thead><tr><th></th><th class="money">Actual YTD</th><th class="money">Budget YTD</th><th class="money">Variance</th><th class="money">% of budget</th><th class="money">Annual budget</th></tr></thead><tbody>${line(cats[0])}<tr class="sec"><td colspan="6">Job cost</td></tr>${cats.filter(c=>c.type==='cogs').map(c=>line(c)).join('')}<tr style="font-weight:600"><td>Gross profit</td><td class="money">${money(gpA)}</td><td class="money">${money(gpB)}</td><td class="money" style="color:${gpA-gpB>=0?'var(--ok)':'var(--bad)'}">${money(gpA-gpB)}</td><td class="money">${gpB?Math.round(gpA/gpB*100)+'%':'—'}</td><td></td></tr><tr class="sec"><td colspan="6">Overhead</td></tr>${cats.filter(c=>c.type==='oh').map(c=>line(c)).join('')}<tr style="font-weight:700"><td>Net profit</td><td class="money">${money(netA)}</td><td class="money">${money(netB)}</td><td class="money" style="color:${netA-netB>=0?'var(--ok)':'var(--bad)'}">${money(netA-netB)}</td><td class="money">${netB?Math.round(netA/netB*100)+'%':'—'}</td><td></td></tr></tbody></table></div>
    <div id="bud-grid"></div>`; }
function budgetEditor(year){ const b = budgetFor(year); const cats = budgetCats(); const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']; $('#bud-grid').innerHTML = `<h3 class="rep-h">Budget ${year} — by month <span class="small muted">type a value, or a value in Jan then "Fill →" to copy across</span></h3><div class="tw"><table class="t bud"><thead><tr><th>Category</th>${months.map(m=>`<th class="money">${m}</th>`).join('')}<th class="money">Year</th><th></th></tr></thead><tbody>${cats.map(c => `<tr data-bc="${c.id}"><td>${esc(c.n)}</td>${b[c.id].map((v,m)=>`<td><input type="number" data-bm="${m}" value="${v||''}"></td>`).join('')}<td class="money" data-bsum>${money(b[c.id].reduce((a,v)=>a+v,0))}</td><td><button class="btn sm" data-bfill title="Copy January across">Fill →</button></td></tr>`).join('')}</tbody></table></div>`;
  document.querySelectorAll('[data-bc]').forEach(tr => { const id = tr.dataset.bc; tr.querySelectorAll('[data-bm]').forEach(inp => inp.addEventListener('change', () => { b[id][+inp.dataset.bm] = +inp.value||0; tr.querySelector('[data-bsum]').textContent = money(b[id].reduce((a,v)=>a+v,0)); save(); })); tr.querySelector('[data-bfill]').onclick = () => { const v = b[id][0]; b[id] = Array(12).fill(v); save(); budgetEditor(year); }; }); }

/* ---------- financial statements (income statement · balance sheet · cash flow) with comparative columns and drill-down ---------- */
function repFinancials(){ const range = cfoRange(); const P = companyPL(range); const prior = companyPL((repPriorRange()||['',''])); const year = range[0].slice(0,4)||today().slice(0,4); const b = budgetFor(year); const mA = range[0] ? +range[0].slice(5,7)-1 : 0, mB = +range[1].slice(5,7)-1; const bud = id => (b[id]||[]).slice(mA, mB+1).reduce((a,v)=>a+v,0); const B = companyBalance(); const wip = DB.projects.map(wipRow); const over = wip.reduce((a,w)=>a+w.over,0), under = wip.reduce((a,w)=>a+w.under,0);
  const pct = v => P.income ? Math.round(v/P.income*100)+'%' : '—'; const budRow = (id) => cfoPeriod==='all' ? 0 : bud(id);
  const row = (label, cur, prev, budget, cls='', drill='') => `<tr class="${cls} ${drill?'click':''}" ${drill?`data-fsdrill="${drill}"`:''}><td>${label}</td><td class="money">${money(cur)}</td><td class="money">${pct(cur)}</td><td class="money dim">${money(prev)}</td><td class="money" style="color:${cur-prev>=0?'var(--ok)':'var(--bad)'}">${prev?Math.round((cur-prev)/Math.abs(prev)*100)+'%':'—'}</td><td class="money dim">${budget?money(budget):'—'}</td><td class="money" style="color:${budget?((cls.includes('inc')?cur-budget:budget-cur)>=0?'var(--ok)':'var(--bad)'):'inherit'}">${budget?money(cur-budget):'—'}</td></tr>`;
  const catRows = (o, po, type) => Object.keys(Object.assign({}, po, o)).sort().map(k => { const cat = CATEGORIES.find(c=>c.n===k) || (k==='Payroll — office & overhead' ? {id:'payroll_oh'} : null); return row(k, o[k]||0, po[k]||0, cat ? budRow(cat.id) : 0, '', cat ? `cat:${cat.id}` : ''); }).join('');
  const labelP = {month:'This month', quarter:'This quarter', ytd:'Year to date', all:'All time'}[cfoPeriod]||'Year to date';
  const IS = `<h3 class="rep-h">Income statement — ${labelP}</h3><div class="tw"><table class="t rep-t fs"><thead><tr><th></th><th class="money">${labelP}</th><th class="money">% of income</th><th class="money">Prior period</th><th class="money">Change</th><th class="money">Budget</th><th class="money">Var. to budget</th></tr></thead><tbody><tr class="sec"><td colspan="7">Income</td></tr>${row('Revenue (earned)', P.income, prior.income, budRow('income'), 'inc', 'income')}<tr class="sec"><td colspan="7">Cost of revenue</td></tr>${catRows(P.cogs, prior.cogs, 'cogs')}${row('Total job cost', P.cogsT, prior.cogsT, CATEGORIES.filter(c=>c.type==='cogs').reduce((a,c)=>a+budRow(c.id),0), 'tot')}${row('Gross profit', P.gross, prior.gross, budRow('income') - CATEGORIES.filter(c=>c.type==='cogs').reduce((a,c)=>a+budRow(c.id),0), 'tot inc')}<tr class="sec"><td colspan="7">Operating expenses</td></tr>${catRows(P.oh, prior.oh, 'oh')}${row('Total operating expenses', P.ohT, prior.ohT, CATEGORIES.filter(c=>c.type==='oh').reduce((a,c)=>a+budRow(c.id),0)+budRow('payroll_oh'), 'tot')}${row('Operating profit', P.opProfit??P.net, prior.opProfit??prior.net, budRow('income') - CATEGORIES.filter(c=>c.type!=='inc'&&c.type!=='non').reduce((a,c)=>a+budRow(c.id),0)-budRow('payroll_oh'), 'tot inc')}${P.propertyNOI!=null&&!repEntity?row('Owned property — net operating income', P.propertyNOI, prior.propertyNOI||0, 0, ''):''}${row('Net profit', P.net, prior.net, budRow('income') - CATEGORIES.filter(c=>c.type!=='inc'&&c.type!=='non').reduce((a,c)=>a+budRow(c.id),0)-budRow('payroll_oh'), 'grand inc')}</tbody></table></div><p class="small muted">Revenue is earned (billed ± WIP adjustment). Job cost includes ${money(P.accruedCost||0)} of bills awaiting approval — approval gates payment, not recognition. Bank items already matched to a bill are not counted twice. Rows drill to the transactions behind them. Excluded: ${Object.entries(P.non).map(([k,v])=>`${esc(k)} ${money(v)}`).join(' · ')||'nothing'}.</p>`;
  const bsRow = (l, v, cls='') => `<tr class="${cls}"><td>${l}</td><td class="money">${money(v)}</td></tr>`; const curAssets = B.cash + (B.undeposited||0) + B.arOut + B.ret + under - (B.credits||0); const curLiab = -B.cards + B.ap + (B.apRet||0) + (B.payrollAccrued||0) + over; const BS = `<h3 class="rep-h">Balance sheet (working capital view) — as of ${fmtL(today())}</h3><div class="grid2"><div class="tw"><table class="t rep-t fs"><tbody><tr class="sec"><td colspan="2">Current assets</td></tr>${bsRow('Cash in bank', B.cash)}${bsRow('Accounts receivable', B.arOut)}${B.undeposited?bsRow('Receipts not yet deposited', B.undeposited):''}${B.credits?bsRow('Less credits on account', -B.credits):''}${bsRow('Retainage receivable', B.ret)}${bsRow('Costs & estimated earnings in excess of billings (under-billings)', under)}${bsRow('Total current assets', curAssets, 'tot')}</tbody></table></div><div class="tw"><table class="t rep-t fs"><tbody><tr class="sec"><td colspan="2">Current liabilities</td></tr>${bsRow('Credit cards', -B.cards)}${bsRow('Accounts payable', B.ap)}${bsRow('Billings in excess of costs & estimated earnings (over-billings)', over)}${bsRow('Billings in excess of earned — of which held for purchases (memo)', B.clientFunds, 'dim')}${B.apRet?bsRow('Retainage payable to subs', B.apRet):''}${B.payrollAccrued?bsRow('Payroll due', B.payrollAccrued):''}${bsRow('Total current liabilities', curLiab, 'tot')}${bsRow('Working capital', curAssets - curLiab, 'grand')}<tr><td>Current ratio</td><td class="money">${curLiab?r2(curAssets/curLiab):'—'} <span class="small muted">benchmark 1.5–2.0</span></td></tr><tr><td>Cash-to-overbillings</td><td class="money">${over?r2(B.cash/over):'—'} <span class="small muted">keep above 1.0</span></td></tr></tbody></table></div></div><p class="small muted">Fixed assets, loans, equity and tax balances live in the accounting system; this view covers the working-capital accounts the ERP controls.</p>`;
  const months = monthKeys(6); const CF = `<h3 class="rep-h">Cash flow — last six months</h3><div class="tw"><table class="t rep-t fs"><thead><tr><th></th>${months.map(m=>`<th class="money">${m}</th>`).join('')}<th class="money">Total</th></tr></thead><tbody>${(() => { const rows = {'Collected from clients':[], 'Paid: materials & subs':[], 'Paid: payroll':[], 'Paid: overhead':[]}; months.forEach(m => { const R = [m+'-01', m+'-31']; const L = ledger(R).filter(r=>!r.income); rows['Collected from clients'].push(DB.clients.flatMap(c=>c.payments).filter(p=>within(p.date,R)).reduce((a,p)=>a+(+p.amount||0),0)); rows['Paid: materials & subs'].push(L.filter(r=>catType(r.cat)==='cogs' && r.kind!=='payroll').reduce((a,r)=>a+r.amt,0)); rows['Paid: payroll'].push(L.filter(r=>r.kind==='payroll').reduce((a,r)=>a+r.amt,0)); rows['Paid: overhead'].push(L.filter(r=>catType(r.cat)==='oh' && r.kind!=='payroll').reduce((a,r)=>a+r.amt,0)); }); const net = months.map((m,i) => rows['Collected from clients'][i] - rows['Paid: materials & subs'][i] - rows['Paid: payroll'][i] - rows['Paid: overhead'][i]); return Object.entries(rows).map(([k,v]) => `<tr><td>${k}</td>${v.map(x=>`<td class="money">${x?money(x):'—'}</td>`).join('')}<td class="money">${money(v.reduce((a,x)=>a+x,0))}</td></tr>`).join('') + `<tr class="grand"><td>Net cash flow</td>${net.map(x=>`<td class="money" style="color:${x<0?'var(--bad)':'inherit'}">${money(x)}</td>`).join('')}<td class="money">${money(net.reduce((a,x)=>a+x,0))}</td></tr>`; })()}</tbody></table></div>`;
  return `<div class="rep-head"><div><h2 style="margin:0">Financial statements</h2><div class="small muted">${entName(repEntity)} · comparative columns, budget variance, drill-down</div></div><div class="seg no-print">${['month','quarter','ytd','all'].map(k=>`<button class="${cfoPeriod===k?'on':''}" data-cfop="${k}">${{month:'Month',quarter:'Quarter',ytd:'YTD',all:'All'}[k]}</button>`).join('')}</div></div>${entityBar()}${IS}${BS}${CF}`; }
function fsDrill(key){ const range = kpiRange(({month:'tm',quarter:'tq',ytd:'ty',all:'all'})[cfoPeriod]||'ty'); let rows = []; if (key==='income'){ rows = DB.clients.flatMap(c => c.invoices.filter(i => !['void','draft'].includes(i.status) && within(i.date, range)).map(i => ({date:i.date, desc:`${i.number} · ${i.title}`, who:c.name, amt:docTotal(i).total+docTotal(i).ret}))); } else { const id = key.slice(4); rows = ledger(range).filter(r => !r.income && (r.cat===id || (id==='payroll_oh' && r.cat==='payroll_oh'))).map(r => ({date:r.date, desc:r.desc, who:r.vendor, amt:r.amt, kind:r.kind})); } rows.sort((a,b)=>b.date.localeCompare(a.date));
  mbModal(`Transactions — ${key==='income'?'Contract revenue':cfoCatName(key.slice(4))}`, `<div class="tw" style="max-height:60vh;overflow:auto"><table class="t"><thead><tr><th>Date</th><th>Description</th><th>Party</th><th>Source</th><th class="money">Amount</th></tr></thead><tbody>${rows.map(r => `<tr><td class="dim">${fmt(r.date)}</td><td>${esc(r.desc)}</td><td>${esc(r.who||'')}</td><td class="dim">${r.kind||'invoice'}</td><td class="money">${money(r.amt)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Nothing in this period.</td></tr>'}<tr style="font-weight:600"><td colspan="4">Total · ${rows.length} item${rows.length===1?'':'s'}</td><td class="money">${money(rows.reduce((a,r)=>a+r.amt,0))}</td></tr></tbody></table></div>`, {submit:null}); }

/* ---------- monthly management pack + weekly CEO flash ---------- */
function repPack(){ const keepP = cfoPeriod; cfoPeriod = 'month'; const P = companyPL(kpiRange('tm')); const Pl = companyPL(kpiRange('lm')); const Y = companyPL(kpiRange('ty')); const B = companyBalance(); const wip = DB.projects.map(p => ({w:wipRow(p), f:fadeFor(p, wipRow(p))})).filter(x=>x.w.contract); const F = analystFindings(); const year = today().slice(0,4); const b = budgetFor(year); const m = +today().slice(5,7)-1; const bud = id => (b[id]||[])[m]||0; const budY = id => (b[id]||[]).slice(0,m+1).reduce((a,v)=>a+v,0);
  const cos = DB.clients.flatMap(c => c.changeOrders.map(x => ({c, x}))); const lab = DB.projects.map(p => ({p, l:projectLabor(p)}));
  const html = `<div class="rep-head"><div><h2 style="margin:0">Monthly management report</h2><div class="small muted">${new Date(today()+'T00:00:00').toLocaleDateString(undefined,{month:'long',year:'numeric'})} · ${entName(repEntity)} · prepared ${fmtL(today())}</div></div></div>${entityBar()}
    <h3 class="rep-h">1 · Executive summary</h3><div class="fin rep-kpis"><div class="kpi"><b>${money(P.income)}</b><span>income this month · ${Pl.income?Math.round((P.income-Pl.income)/Pl.income*100)+'% vs last month':''} · budget ${money(bud('income'))}</span></div><div class="kpi ${P.grossPct<25?'warn':'good'}"><b>${P.grossPct}%</b><span>gross margin · YTD ${Y.grossPct}%</span></div><div class="kpi ${P.net<0?'warn':'good'}"><b>${money(P.net)}</b><span>net profit · YTD ${money(Y.net)} (${Y.netPct}%)</span></div><div class="kpi"><b>${money(B.cash)}</b><span>cash · AR ${money(B.arOut)} · AP ${money(B.ap)}</span></div><div class="kpi"><b>${money(B.backlog)}</b><span>backlog · ${F.filter(f=>f.sev==='high').length} items to act on</span></div></div>
    <h3 class="rep-h">2 · P&L vs budget (YTD)</h3><div class="tw"><table class="t rep-t"><thead><tr><th></th><th class="money">Month</th><th class="money">Budget</th><th class="money">YTD</th><th class="money">YTD budget</th><th class="money">Variance</th></tr></thead><tbody>${[['Income',P.income,bud('income'),Y.income,budY('income'),true],['Job cost',P.cogsT,CATEGORIES.filter(c=>c.type==='cogs').reduce((a,c)=>a+bud(c.id),0),Y.cogsT,CATEGORIES.filter(c=>c.type==='cogs').reduce((a,c)=>a+budY(c.id),0),false],['Gross profit',P.gross,0,Y.gross,0,true],['Overhead',P.ohT,CATEGORIES.filter(c=>c.type==='oh').reduce((a,c)=>a+bud(c.id),0)+bud('payroll_oh'),Y.ohT,CATEGORIES.filter(c=>c.type==='oh').reduce((a,c)=>a+budY(c.id),0)+budY('payroll_oh'),false],['Net profit',P.net,0,Y.net,0,true]].map(([k,a,bb,y,yb,inc]) => `<tr ${k.includes('profit')?'style="font-weight:600"':''}><td>${k}</td><td class="money">${money(a)}</td><td class="money dim">${bb?money(bb):'—'}</td><td class="money">${money(y)}</td><td class="money dim">${yb?money(yb):'—'}</td><td class="money" style="color:${yb?((inc?y-yb:yb-y)>=0?'var(--ok)':'var(--bad)'):'inherit'}">${yb?money(y-yb):'—'}</td></tr>`).join('')}</tbody></table></div>
    <h3 class="rep-h">3 · WIP & profit fade</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Job</th><th class="money">Contract</th><th class="money">% complete</th><th class="money">Est. GP %</th><th class="money">Bid GP %</th><th class="money">Fade vs prior</th><th class="money">Over / (under) billed</th><th class="money">Cost to complete</th></tr></thead><tbody>${wip.map(({w,f}) => `<tr><td>${esc(w.p.project.name)}</td><td class="money">${money(w.contract)}</td><td class="money">${Math.round(w.pct*100)}%</td><td class="money">${w.gpPct}%</td><td class="money">${w.bidGPPct}%</td><td class="money" style="color:${f.fadePts<0?'var(--bad)':'inherit'}">${f.fadePts==null?'—':(f.fadePts>0?'+':'')+f.fadePts+' pts'}</td><td class="money">${w.over?money(w.over):w.under?'('+money(w.under)+')':'—'}</td><td class="money">${money(w.ctc)}</td></tr>`).join('')}</tbody></table></div>
    <h3 class="rep-h">4 · Change orders</h3><div class="tw"><table class="t rep-t"><thead><tr><th>CO</th><th>Client</th><th>Status</th><th class="money">Amount</th><th>Days open</th></tr></thead><tbody>${cos.map(({c,x}) => `<tr><td>${esc(x.number)} · ${esc(x.title)}</td><td>${esc(c.name)}</td><td><span class="pill ${x.status==='approved'||x.status==='billed'?'ok':x.status==='sent'?'warn':'neutral'}">${x.status}</span></td><td class="money">${money(docTotal(x).total)}</td><td>${x.status==='sent'?Math.round((parse(today())-parse(x.date))/86400000):''}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">None.</td></tr>'}</tbody></table></div>
    <h3 class="rep-h">5 · Labor</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Project</th><th class="money">Hours (month)</th><th class="money">Burdened cost</th><th class="money">Labor % of income</th></tr></thead><tbody>${lab.map(({p,l}) => `<tr><td>${esc(p.project.name)}</td><td class="money">${l.hours}</td><td class="money">${money(l.cost)}</td><td class="money">${P.income?Math.round(l.cost/P.income*100)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>
    <h3 class="rep-h">6 · Receivables & payables</h3>${(() => { const ag = DB.clients.reduce((a,c) => { const f = clientFin(c); Object.keys(f.buckets).forEach(k => a[k]=(a[k]||0)+f.buckets[k]); return a; }, {}); const ap = DB.bills.filter(b => !['paid','void','rejected'].includes(b.status)); const apB = {current:0,d30:0,d60:0,d90:0}; ap.forEach(b => { const age = b.due ? Math.round((parse(today())-parse(b.due))/86400000) : 0; const v = billTotal(b); if (age<=0) apB.current+=v; else if (age<=30) apB.d30+=v; else if (age<=60) apB.d60+=v; else apB.d90+=v; }); return `<div class="tw"><table class="t rep-t"><thead><tr><th></th><th class="money">Current</th><th class="money">1–30</th><th class="money">31–60</th><th class="money">60+</th><th class="money">Total</th></tr></thead><tbody><tr><td>Receivables (retainage ${money(B.ret)} separate)</td>${['current','d30','d60','d90'].map(k=>`<td class="money">${money(ag[k]||0)}</td>`).join('')}<td class="money">${money(B.arOut)}</td></tr><tr><td>Payables</td>${['current','d30','d60','d90'].map(k=>`<td class="money">${money(apB[k])}</td>`).join('')}<td class="money">${money(B.ap)}</td></tr></tbody></table></div>`; })()}
    <h3 class="rep-h">7 · Overhead by category (month)</h3><div class="tw"><table class="t rep-t"><tbody>${Object.entries(P.oh).sort((a,b)=>b[1]-a[1]).map(([k,v]) => `<tr><td>${esc(k)}</td><td class="money">${money(v)}</td><td class="dim">${P.income?Math.round(v/P.income*100):0}% of income</td></tr>`).join('')||'<tr><td class="muted">None.</td></tr>'}</tbody></table></div>
    <h3 class="rep-h">8 · Analyst — items requiring a decision</h3>${F.filter(f=>f.sev!=='low').slice(0,10).map(f => `<div class="ana ${f.sev}"><span class="ana-sev">${{high:'Act now',med:'This week'}[f.sev]}</span><div class="ana-main"><div class="ana-title">${esc(f.title)}</div><div class="ana-detail">${f.detail}</div></div><div class="ana-side">${f.amount?`<b>${money(f.amount)}</b>`:''}</div></div>`).join('')||'<div class="muted small">Nothing outstanding.</div>'}`;
  cfoPeriod = keepP; return html; }
function repFlash(){ const B = companyBalance(); const wk = kpiRange('l30'); const wk7 = [iso(addDays(today(),-6)), today()]; const coll = DB.clients.flatMap(c=>c.payments).filter(p=>within(p.date,wk7)).reduce((a,p)=>a+(+p.amount||0),0); const billed = DB.clients.flatMap(c=>c.invoices).filter(i=>!['void','draft'].includes(i.status)&&within(i.date,wk7)).reduce((a,i)=>a+docTotal(i).total,0); const hrs = DB.time.filter(e=>within(e.date,wk7)).reduce((a,e)=>a+hoursOf(e),0); const wip = DB.projects.map(p=>({w:wipRow(p), f:fadeFor(p, wipRow(p))})).filter(x=>x.w.contract); const fade = wip.filter(x => x.f.fadePts!=null && x.f.fadePts < -2); const pend = DB.clients.flatMap(c=>c.changeOrders.filter(x=>x.status==='sent').map(x=>({c,x,days:Math.round((parse(today())-parse(x.date))/86400000)}))); const over60 = DB.clients.flatMap(c=>clientFin(c).open.filter(o=>o.age>60)); const bids = DB.clients.flatMap(c=>c.estimates.filter(e=>e.status==='sent')); const wins = DB.clients.flatMap(c=>c.estimates.filter(e=>['approved','converted'].includes(e.status)&&within(e.approvedOn||e.date,wk))); const F = analystFindings().filter(f=>f.sev==='high'); const ctcFlags = wip.filter(x => x.w.ctc > x.w.contract - x.w.billed).slice(0,5);
  const li = (k, v, sub='') => `<div class="flash-row"><span>${k}</span><b>${v}</b><i>${sub}</i></div>`;
  return `<div class="rep-head"><div><h2 style="margin:0">CEO weekly flash</h2><div class="small muted">Week ending ${fmtL(today())} · ${entName(repEntity)}</div></div></div>${entityBar()}<div class="flash">
    <div class="card"><h3>Cash & collections</h3>${li('Cash today', money(B.cash), `available ${money(B.available)} after ${money(B.clientFunds)} client funds held`)}${li('Collected this week', money(coll))}${li('Billed this week', money(billed))}${li('AR over 60 days', money(over60.reduce((a,o)=>a+o.bal,0)), over60.map(o=>o.x.number).join(', '))}${li('Payables past due', money(B.apOver))}${li('Runway', runwayText(B))}</div>
    <div class="card"><h3>Jobs</h3>${li('Backlog', money(B.backlog), `${wip.length} active contract${wip.length===1?'':'s'}`)}${li('GP fade > 2 pts', fade.length ? fade.map(x=>`${x.w.p.project.name} ${x.f.fadePts} pts`).join('; ') : 'none')}${li('Over / under billed', `${money(wip.reduce((a,x)=>a+x.w.over,0))} / ${money(wip.reduce((a,x)=>a+x.w.under,0))}`)}${li('Pending COs', `${pend.length} · ${money(pend.reduce((a,x)=>a+docTotal(x.x).total,0))}`, pend.filter(x=>x.days>14).length?`${pend.filter(x=>x.days>14).length} older than 14 days`:'')}${li('Cost-to-complete flags', ctcFlags.length ? ctcFlags.map(x=>x.w.p.project.name).join('; ') : 'none', 'cost to complete exceeds remaining billing')}</div>
    <div class="card"><h3>People & sales</h3>${li('Hours this week', r2(hrs))}${li('Proposals out', `${bids.length} · ${money(bids.reduce((a,e)=>a+docTotal(e).total,0))}`)}${li('Won last 30 days', `${wins.length} · ${money(wins.reduce((a,e)=>a+docTotal(e).total,0))}`)}${li('Bills to approve', DB.bills.filter(b=>['submitted','pm-approved'].includes(b.status)).length)}${li('Act now', F.length ? F.map(f=>f.title).join('; ') : 'nothing urgent')}</div></div>`; }

/* ===================== SAVED SEARCHES — criteria · summary types · highlighting · audience · custom KPIs · reminders · publish dashboards ===================== */
const SEARCH_OPS = {eq:'is', ne:'is not', contains:'contains', gt:'greater than', lt:'less than', gte:'at least', lte:'at most', empty:'is empty', notempty:'is not empty'};
const SUMMARY_TYPES = {sum:'Sum', count:'Count', avg:'Average', min:'Minimum', max:'Maximum'};
function searchList(){ DB.searches = DB.searches||[]; return DB.searches; }
function searchRun(s){ const ds = REP_DS[s.ds]||REP_DS.invoices; let rows = ds.rows(); const test = (r, c) => { const v = r[c.field]; const val = c.value; switch(c.op){ case 'eq': return String(v??'').toLowerCase()===String(val).toLowerCase() || (+v===+val && val!==''); case 'ne': return String(v??'').toLowerCase()!==String(val).toLowerCase(); case 'contains': return String(v??'').toLowerCase().includes(String(val).toLowerCase()); case 'gt': return +v > +val; case 'lt': return +v < +val; case 'gte': return +v >= +val; case 'lte': return +v <= +val; case 'empty': return v==null || v===''; case 'notempty': return v!=null && v!==''; } return true; };
  (s.criteria||[]).forEach(c => { if (c.field && c.op) rows = rows.filter(r => test(r, c)); }); if (s.from) rows = rows.filter(r => (r.date||'') >= s.from); if (s.to) rows = rows.filter(r => (r.date||'') <= s.to);
  let out = rows; if (s.group && ds.dims.includes(s.group)){ const g = {}; rows.forEach(r => { const k = r[s.group]||'(none)'; const o = g[k] = g[k]||{[s.group]:k, count:0, _rows:[]}; o.count++; o._rows.push(r); }); out = Object.values(g).map(o => { const res = {[s.group]:o[s.group], count:o.count}; ds.sums.forEach(f => { const vals = o._rows.map(r=>+r[f]||0); const st = (s.summary||{})[f]||'sum'; res[f] = st==='sum' ? r2(vals.reduce((a,v)=>a+v,0)) : st==='avg' ? r2(vals.reduce((a,v)=>a+v,0)/Math.max(1,vals.length)) : st==='min' ? Math.min(...vals) : st==='max' ? Math.max(...vals) : vals.length; }); return res; }).sort((a,b)=>(b[ds.sums[0]]||0)-(a[ds.sums[0]]||0)); }
  else out = rows.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
  return {ds, rows:out, cols: out.length ? Object.keys(out[0]) : []}; }
function searchHighlight(s, r){ const h = s.highlight; if (!h || !h.field) return ''; const v = r[h.field]; const hit = h.op==='gt' ? +v > +h.value : h.op==='lt' ? +v < +h.value : h.op==='eq' ? String(v??'').toLowerCase()===String(h.value).toLowerCase() : h.op==='contains' ? String(v??'').toLowerCase().includes(String(h.value).toLowerCase()) : false; return hit ? `style="background:${h.color||'#FFF3E0'}"` : ''; }
function searchTotal(s, field){ const R = searchRun(s); if (!field || field==='count') return R.rows.length; return r2(R.rows.reduce((a,r)=>a+(+r[field]||0),0)); }
function searchTable(s, limit){ const R = searchRun(s); const rows = limit ? R.rows.slice(0, limit) : R.rows; const sums = R.ds.sums; const fmtv = (k, v) => sums.includes(k) ? (k==='hours'||k==='lines'?r2(v):money(v)) : k==='count' ? v : esc(String(v??'')); const tot = {}; sums.forEach(f => tot[f] = r2(rows.reduce((a,r)=>a+(+r[f]||0),0)));
  return `<div class="tw"><table class="t rep-t" id="ss-table"><thead><tr>${R.cols.map(k=>`<th class="${sums.includes(k)||k==='count'?'money':''}">${k}${s.group&&s.summary?.[k]?` <span class="small muted">${SUMMARY_TYPES[s.summary[k]]}</span>`:''}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr ${searchHighlight(s, r)}>${R.cols.map(k=>`<td class="${sums.includes(k)||k==='count'?'money':''}">${fmtv(k, r[k])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${Math.max(1,R.cols.length)}" class="muted">No rows match.</td></tr>`}${rows.length?`<tr style="font-weight:600">${R.cols.map((k,i)=>`<td class="${sums.includes(k)?'money':''}">${i===0?`Total · ${R.rows.length}`:sums.includes(k)?fmtv(k, tot[k]):''}</td>`).join('')}</tr>`:''}</tbody></table></div>`; }

/* Reports › Saved searches (replaces the simple custom report) */
let ssOpen = null;
function repSearches(){ const list = searchList(); const s = ssOpen ? list.find(x=>x.id===ssOpen) : null; if (!s) return `<div class="rep-head"><div><h2 style="margin:0">Saved searches</h2><div class="small muted">Any dataset, any criteria, summarized and highlighted — then used as a list, a chart, a KPI or a reminder on any dashboard.</div></div><button class="btn primary no-print" id="ss-new">New search</button></div>
    <div class="tw"><table class="t rep-t"><thead><tr><th>Search</th><th>Data</th><th>Group by</th><th>Criteria</th><th>Audience</th><th>Used as</th><th class="money">Rows</th></tr></thead><tbody>${list.map(x => `<tr class="click" data-ssopen="${x.id}"><td><b>${esc(x.name)}</b></td><td>${REP_DS[x.ds]?.n||x.ds}</td><td>${esc(x.group||'—')}</td><td class="small">${(x.criteria||[]).filter(c=>c.field).map(c=>`${c.field} ${SEARCH_OPS[c.op]} ${esc(String(c.value??''))}`).join(' and ')||'—'}</td><td class="small">${(x.audience||['all']).join(', ')}</td><td class="small">${[x.kpi?'KPI':'', x.reminder?'Reminder':''].filter(Boolean).join(' · ')||'—'}</td><td class="money">${searchRun(x).rows.length}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">No saved searches yet. Start from a dataset, add criteria, group and summarize, then save.</td></tr>'}</tbody></table></div>`;
  const ds = REP_DS[s.ds]||REP_DS.invoices; const sample = ds.rows()[0]||{}; const fields = Object.keys(sample); const crit = (s.criteria||[]).concat([{field:'', op:'eq', value:''}]);
  return `<div class="rep-head"><div><a href="#" id="ss-back" class="mb-back">← Saved searches</a><h2 style="margin:2px 0 0">${esc(s.name)}</h2><div class="small muted">${ds.n}${s.group?' by '+s.group:''} · ${searchRun(s).rows.length} rows</div></div><div class="row no-print" style="gap:6px"><button class="btn" id="ss-csv">Copy as CSV</button><button class="btn danger" id="ss-del">Delete</button></div></div>
    <div class="card no-print" style="margin-bottom:12px"><div class="rep-ctl"><label>Name <input id="ss-name" value="${esc(s.name)}"></label><label>Data <select id="ss-ds">${Object.entries(REP_DS).map(([k,d])=>`<option value="${k}" ${s.ds===k?'selected':''}>${d.n}</option>`).join('')}</select></label><label>Group by <select id="ss-group"><option value="">— rows —</option>${ds.dims.map(d=>`<option value="${d}" ${s.group===d?'selected':''}>${d}</option>`).join('')}</select></label><label>From <input type="date" id="ss-from" value="${s.from||''}"></label><label>To <input type="date" id="ss-to" value="${s.to||''}"></label></div>
      <div style="margin-top:10px"><div class="small" style="font-weight:600;margin-bottom:4px">Criteria</div>${crit.map((c,i) => `<div class="row ss-crit" style="gap:6px;margin-bottom:4px;flex-wrap:wrap" data-ci="${i}"><select data-cf="field"><option value="">— field —</option>${fields.map(f=>`<option ${c.field===f?'selected':''}>${f}</option>`).join('')}</select><select data-cf="op">${Object.entries(SEARCH_OPS).map(([k,l])=>`<option value="${k}" ${c.op===k?'selected':''}>${l}</option>`).join('')}</select><input data-cf="value" value="${esc(String(c.value??''))}" placeholder="value" style="width:160px">${i<crit.length-1?`<button class="btn sm" data-crm="${i}">✕</button>`:''}</div>`).join('')}</div>
      ${s.group?`<div style="margin-top:8px"><div class="small" style="font-weight:600;margin-bottom:4px">Summary types</div><div class="row" style="gap:10px;flex-wrap:wrap">${ds.sums.map(f => `<label class="small">${f} <select data-sum="${f}">${Object.entries(SUMMARY_TYPES).map(([k,l])=>`<option value="${k}" ${(s.summary?.[f]||'sum')===k?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div></div>`:''}
      <div style="margin-top:8px"><div class="small" style="font-weight:600;margin-bottom:4px">Highlight rows when</div><div class="row" style="gap:6px;flex-wrap:wrap"><select id="ss-hf"><option value="">— field —</option>${(s.group?[s.group,'count',...ds.sums]:fields).map(f=>`<option ${s.highlight?.field===f?'selected':''}>${f}</option>`).join('')}</select><select id="ss-hop">${['gt','lt','eq','contains'].map(k=>`<option value="${k}" ${s.highlight?.op===k?'selected':''}>${SEARCH_OPS[k]}</option>`).join('')}</select><input id="ss-hv" value="${esc(String(s.highlight?.value??''))}" placeholder="value" style="width:120px"><input type="color" id="ss-hc" value="${s.highlight?.color||'#FFF3E0'}" style="width:44px;height:30px;padding:2px"></div></div>
      <div style="margin-top:10px" class="row" style="gap:14px;flex-wrap:wrap"><label class="small"><input type="checkbox" id="ss-kpi" ${s.kpi?'checked':''}> Available as KPI <select id="ss-kpif" style="height:26px"><option value="count" ${s.kpiField==='count'?'selected':''}>count</option>${ds.sums.map(f=>`<option ${s.kpiField===f?'selected':''}>${f}</option>`).join('')}</select> <span class="muted">date-filtered by the KPI range</span></label><label class="small"><input type="checkbox" id="ss-rem" ${s.reminder?'checked':''}> Available for reminders <span class="muted">count, highlighted when above</span> <input id="ss-remt" type="number" value="${s.reminderThreshold??0}" style="width:70px;height:26px"></label><label class="small">Audience <select id="ss-aud" multiple style="height:60px">${['all','owner','pm','coord'].map(r=>`<option ${(s.audience||['all']).includes(r)?'selected':''}>${r}</option>`).join('')}</select></label></div></div>
    ${searchTable(s)}`; }
function wireSearches(root){ $('#ss-new')?.addEventListener('click', () => { const s = {id:uid('ss'), name:'New search', ds:'invoices', group:'', criteria:[], summary:{}, highlight:null, audience:['all'], kpi:false, kpiField:'count', reminder:false, reminderThreshold:0, createdBy:DB.me||''}; searchList().push(s); ssOpen = s.id; save(); render(); });
  root.querySelectorAll('[data-ssopen]').forEach(tr => tr.onclick = () => { ssOpen = tr.dataset.ssopen; render(); }); $('#ss-back')?.addEventListener('click', e => { e.preventDefault(); ssOpen = null; render(); });
  const s = searchList().find(x=>x.id===ssOpen); if (!s) return; const upd = () => { save(); render(); };
  $('#ss-name').addEventListener('change', e => { s.name = e.target.value.trim()||s.name; upd(); }); $('#ss-ds').addEventListener('change', e => { s.ds = e.target.value; s.group = ''; s.criteria = []; s.summary = {}; s.highlight = null; upd(); }); $('#ss-group').addEventListener('change', e => { s.group = e.target.value; upd(); }); $('#ss-from').addEventListener('change', e => { s.from = e.target.value; upd(); }); $('#ss-to').addEventListener('change', e => { s.to = e.target.value; upd(); });
  root.querySelectorAll('.ss-crit').forEach(row => row.querySelectorAll('[data-cf]').forEach(inp => inp.addEventListener('change', () => { const i = +row.dataset.ci; s.criteria = s.criteria||[]; const c = s.criteria[i] = s.criteria[i]||{field:'', op:'eq', value:''}; c[inp.dataset.cf] = inp.value; s.criteria = s.criteria.filter(x => x.field); upd(); }))); root.querySelectorAll('[data-crm]').forEach(b => b.onclick = () => { s.criteria.splice(+b.dataset.crm, 1); upd(); });
  root.querySelectorAll('[data-sum]').forEach(sel => sel.addEventListener('change', () => { s.summary = s.summary||{}; s.summary[sel.dataset.sum] = sel.value; upd(); }));
  const hl = () => { const f = $('#ss-hf').value; s.highlight = f ? {field:f, op:$('#ss-hop').value, value:$('#ss-hv').value, color:$('#ss-hc').value} : null; upd(); }; ['#ss-hf','#ss-hop','#ss-hv','#ss-hc'].forEach(id => $(id).addEventListener('change', hl));
  $('#ss-kpi').addEventListener('change', e => { s.kpi = e.target.checked; upd(); }); $('#ss-kpif').addEventListener('change', e => { s.kpiField = e.target.value; upd(); }); $('#ss-rem').addEventListener('change', e => { s.reminder = e.target.checked; upd(); }); $('#ss-remt').addEventListener('change', e => { s.reminderThreshold = +e.target.value||0; upd(); }); $('#ss-aud').addEventListener('change', e => { s.audience = [...e.target.selectedOptions].map(o=>o.value); if (!s.audience.length) s.audience = ['all']; upd(); });
  $('#ss-del').onclick = () => { if (!confirm(`Delete search "${s.name}"?`)) return; DB.searches = searchList().filter(x=>x.id!==s.id); ssOpen = null; upd(); };
  $('#ss-csv').onclick = () => { const rows = [...document.querySelectorAll('#ss-table tr')].map(tr => [...tr.children].map(td => '"'+td.textContent.replace(/"/g,'""')+'"').join(',')).join('\n'); (navigator.clipboard?.writeText(rows)||Promise.reject()).then(() => toast('Copied'), () => toast('Copy blocked here — select the table and copy')); }; }
/* custom KPIs and reminders sourced from saved searches (merged into the KPI library at read time) */
function customKPIs(){ const out = {}; searchList().filter(s => s.kpi && (s.audience||['all']).some(a => a==='all' || a===role())).forEach(s => { out['ss:'+s.id] = {n:s.name, g:'Saved searches', fmt: s.kpiField==='count' ? 'int' : (['hours','lines'].includes(s.kpiField) ? 'num' : 'money'), good:'flat', go:{view:'reports', tab:'searches', search:s.id}, fn:R => { const s2 = Object.assign({}, s, {from:R[0]||s.from, to:R[1]||s.to}); return searchTotal(s2, s.kpiField); }}; }); return out; }
function searchReminders(){ return searchList().filter(s => s.reminder && (s.audience||['all']).some(a => a==='all' || a===role())).map(s => { const n = searchRun(s).rows.length; return {n, label:s.name, go:{view:'reports', tab:'searches', search:s.id}, sev: n > (s.reminderThreshold||0) ? 'warn' : ''}; }).filter(r => r.n); }

/* publish a dashboard to roles (NetSuite "Publish Dashboard": new users only / override; locked / add-move / unlocked) */
function publishDashboard(){ const H = homeDef(); mbModal('Publish this dashboard', `<p class="small muted" style="margin:0 0 8px">Copies your current layout and portlets as the dashboard for the roles you pick.</p><div class="f"><label>Roles</label>${['owner','pm','coord'].map(r => `<label class="chk"><input type="checkbox" data-f="r:${r}" ${r!==role()?'checked':''}> ${ROLE_NAMES[r]||r}</label>`).join('')}</div>${mbF('Apply to', mbSel('mode', [['new','New users only (keep existing personalization)'],['override','Override existing users\' dashboards']], 'override'))}${mbF('Lock mode', mbSel('lock', [['unlocked','Unlocked — users can personalize'],['addmove','Add / move content only'],['locked','Locked — no personalization']], 'unlocked'))}`, {submit:'Publish', onSubmit: f => { const roles = Object.keys(f).filter(k=>k.startsWith('r:') && f[k]).map(k=>k.slice(2)); if (!roles.length) return false; DB.published = DB.published||{}; roles.forEach(r => { DB.published[r] = {layout:H.layout, portlets:JSON.parse(JSON.stringify(H.portlets)).map(p => ({...p, id:uid('pt')})), lock:f.lock, by:DB.me||'', at:today()}; if (f.mode==='override' || !DB.dashboards[r]) DB.dashboards[r] = JSON.parse(JSON.stringify(DB.published[r])); }); save(); toast(`Published to ${roles.map(r=>ROLE_NAMES[r]||r).join(', ')}`); }}); }

/* ---- construction & design-firm ratios with benchmarks (sources: CFMA benchmarker, Deltek Clarity, NAHB, JMCO) ---- */
Object.assign(KPIS, {
  backlogMonths:{n:'Months of backlog', g:'Projects', fmt:'num', good:'up', bench:'6–12 months', go:{view:'reports', tab:'wip'}, fn:() => { const m = monthKeys(6); const inc = companyPL([m[0]+'-01', today()]).income/6; return inc ? r2(companyBalance().backlog/inc) : 0; }},
  backlogGP:{n:'Backlog gross profit', g:'Projects', fmt:'money', good:'up', bench:'> 50% of annual overhead', go:{view:'reports', tab:'wip'}, fn:() => r2(DB.projects.map(wipRow).reduce((a,w)=>a+w.backlogGP,0))},
  overBill:{n:'Over-billings (liability)', g:'Projects', fmt:'money', good:'flat', bench:'< 5% of contracts', go:{view:'reports', tab:'wip'}, fn:() => r2(DB.projects.map(wipRow).reduce((a,w)=>a+w.over,0))},
  underBill:{n:'Under-billings (unbilled work)', g:'Projects', fmt:'money', good:'down', bench:'near zero', go:{view:'reports', tab:'wip'}, fn:() => r2(DB.projects.map(wipRow).reduce((a,w)=>a+w.under,0))},
  fade:{n:'GP fade vs bid (pts, contract-weighted)', g:'Projects', fmt:'num', good:'up', bench:'≥ 0', go:{view:'reports', tab:'wip'}, fn:() => { const ws = DB.projects.map(wipRow).filter(w=>w.contract); const c = ws.reduce((a,w)=>a+w.contract,0); return c ? r2(ws.reduce((a,w)=>a+(w.gpPct-w.bidGPPct)*w.contract,0)/c) : 0; }},
  coRate:{n:'Change-order rate', g:'Projects', fmt:'pct', good:'flat', bench:'3–5% of contract', go:{view:'clients'}, fn:() => { const ws = DB.projects.map(wipRow); const o = ws.reduce((a,w)=>a+w.orig,0); return o ? r2(ws.reduce((a,w)=>a+w.cos,0)/o*100) : 0; }},
  cashToOver:{n:'Cash-to-overbillings', g:'Ratios', fmt:'num', good:'up', bench:'> 1.0', go:{view:'reports', tab:'financials'}, fn:() => { const o = DB.projects.map(wipRow).reduce((a,w)=>a+w.over,0); return o ? r2(companyBalance().cash/o) : 0; }},
  currentRatio:{n:'Current ratio (working capital view)', g:'Ratios', fmt:'num', good:'up', bench:'1.5–2.0', go:{view:'reports', tab:'financials'}, fn:() => { const B = companyBalance(); const ws = DB.projects.map(wipRow); const ca = B.cash + B.arOut + ws.reduce((a,w)=>a+w.under,0); const cl = -B.cards + B.ap + ws.reduce((a,w)=>a+w.over,0); return cl ? r2(ca/cl) : 0; }},
  dpo:{n:'Days payables outstanding', g:'Ratios', fmt:'days', good:'flat', bench:'30–45 days', go:{view:'ap'}, fn:R => { const paid = DB.bills.filter(b => b.status==='paid' && b.paidOn && within(b.paidOn, R)); if (!paid.length) return 0; return Math.round(paid.reduce((a,b)=>a+Math.max(0,(parse(b.paidOn)-parse(b.date))/86400000),0)/paid.length); }},
  overheadRate:{n:'Overhead rate (overhead ÷ direct labor)', g:'Ratios', fmt:'pct', good:'down', bench:'130–160% (design firms)', go:{view:'reports', tab:'company'}, fn:R => { const P = companyPL(R); const lab = KPIS.laborCost.fn(R); return lab ? Math.round(P.ohT/lab*100) : 0; }},
  breakEven:{n:'Break-even revenue (month)', g:'Ratios', fmt:'money', good:'down', bench:'below actual income', go:{view:'reports', tab:'company'}, fn:R => { const P = companyPL(R); return P.grossPct ? r2(P.ohT/(P.grossPct/100)) : 0; }},
  laborPct:{n:'Direct labor % of income', g:'Labor', fmt:'pct', good:'down', bench:'18–25% GC · 30–40% MEP', go:{view:'time'}, fn:R => { const P = companyPL(R); const lab = KPIS.laborCost.fn(R); return P.income ? Math.round(lab/P.income*100) : 0; }},
  utilization:{n:'Utilization (project hours ÷ all hours)', g:'Labor', fmt:'pct', good:'up', bench:'60–65%', go:{view:'time'}, fn:R => { const es = DB.time.filter(e => within(e.date,R)); const all = es.reduce((a,e)=>a+hoursOf(e),0); const proj = es.filter(e=>e.projectId).reduce((a,e)=>a+hoursOf(e),0); return all ? Math.round(proj/all*100) : 0; }},
  netMultiplier:{n:'Net multiplier (income ÷ direct labor)', g:'Ratios', fmt:'num', good:'up', bench:'~3.0 (design)', go:{view:'reports', tab:'company'}, fn:R => { const P = companyPL(R); const lab = KPIS.laborCost.fn(R); return lab ? r2(P.income/lab) : 0; }},
  effRate:{n:'Effective hourly rate', g:'Labor', fmt:'money', good:'up', bench:'above standard rate', go:{view:'time'}, fn:R => { const P = companyPL(R); const h = KPIS.hours.fn(R); return h ? r2(P.income/h) : 0; }},
  revPerEmp:{n:'Income per employee (annualized)', g:'Ratios', fmt:'money', good:'up', bench:'$165k+ net rev / employee (design)', go:{view:'time'}, fn:() => { const n = KPIS.employees.fn(); const m = monthKeys(6); const inc = companyPL([m[0]+'-01', today()]).income*2; return n ? r2(inc/n) : 0; }},
  budgetVar:{n:'Income vs budget (YTD)', g:'Financial', fmt:'money', good:'up', bench:'≥ 0', go:{view:'reports', tab:'budget'}, fn:() => { const y = today().slice(0,4); const b = budgetFor(y); const m = +today().slice(5,7); const bud = b.income.slice(0,m).reduce((a,v)=>a+v,0); return r2(companyPL(kpiRange('ty')).income - bud); }},
  clientFunds:{n:'Client funds held for purchases', g:'Cash', fmt:'money', good:'down', bench:'spend or refund within 45 days', go:{view:'reports', tab:'funds'}, fn:() => companyBalance().clientFunds},
  availableCash:{n:'Available cash (bank − client funds)', g:'Cash', fmt:'money', good:'up', bench:'> 2 months overhead', go:{view:'reports', tab:'funds'}, fn:() => companyBalance().available},
  floated:{n:'Client purchases floated by us', g:'Cash', fmt:'money', good:'down', bench:'0 — bill before buying', go:{view:'reports', tab:'funds'}, fn:() => companyBalance().floated},
  arDays:{n:'AR > 60 days', g:'AR / AP', fmt:'money', good:'down', bench:'0', go:{view:'clients'}, fn:() => r2(DB.clients.flatMap(c=>clientFin(c).open.filter(o=>o.age>60)).reduce((a,o)=>a+o.bal,0))},
});
KPIS.grossPct.bench = '25–35% remodel · 12–20% GC'; KPIS.netPct.bench = '5–8% typical · 14% best'; KPIS.ohRatio.bench = '8–12%'; KPIS.dso.bench = '< 45 days (CFMA 58)'; KPIS.winRate.bench = '25–40% negotiated'; KPIS.projMargin.bench = '≥ bid margin';
Object.assign(SCORECARDS, {
  construction:{n:'Construction health (CFMA)', rows:['backlog','backlogMonths','backlogGP','overBill','underBill','fade','coRate','cashToOver','currentRatio','dso','dpo']},
  design:{n:'Design studio', rows:['utilization','netMultiplier','overheadRate','breakEven','effRate','revPerEmp','laborPct']},
  budget:{n:'Budget performance', rows:['income','budgetVar','gross','opex','profit']},
});
SCORECARDS.ratios.rows = [{f:'grossPct'},{f:'netPct'},{f:'ohRatio'},'dso','dpo','currentRatio','cashToOver',{f:'projMargin'}];

/* ===================== CLIENT FUNDS — money collected for purchases that has not been spent yet ===================== */
/* Rule: for every contract line, cash the client has paid toward that line (collected) that exceeds what has actually been spent on it (actual cost) is still the client's money as long as there is budget left to buy. Reserved = max(0, min(collected − actual, budget − actual)). Bank balance − reserved = cash that is really ours to use. */
function clientFundsLedger(){ const rows = []; DB.clients.forEach(c => { [...c.estimates.filter(e => ['approved','converted'].includes(e.status)), ...c.changeOrders.filter(x => ['approved','billed'].includes(x.status))].forEach(doc => { if (doc.template==='construction') ctNumber(doc); doc.lines.forEach(l => { const key = ctKey(doc, l); const f = lineFin(key); if (!f) return;
    // collected against this line: SOV invoices (pro-rated) + items-mode invoices billed from the line (fromLine)
    let collected = f.collected;
    const budget = +l.cost||0; const actual = f.actual; const committed = f.committed; const paidOut = actual; const remainingToBuy = Math.max(0, r2(budget - actual - committed)); const reserved = Math.max(0, r2(Math.min(collected - paidOut, budget - paidOut))); const floated = Math.max(0, r2(paidOut - collected));
    const kind = (l.items||[]).length || /material|millwork|tile|fixture|appliance|window|door|stone|flooring|lighting|hardware|cabinet/i.test(l.item||'') ? 'materials' : (l.vendor ? 'subs' : 'labor');
    const p = DB.projects.find(x => x.id===doc.projectId); const oldest = (() => { const inv = c.invoices.filter(i => !['void','draft'].includes(i.status) && ((i.mode==='sov' && f.sv && i.lines.some(x=>x.sovId===f.sv.id)) || i.lines.some(x=>x.fromLine===key))); const pays = c.payments.filter(py => inv.some(i=>i.id===py.invoiceId)).map(py=>py.date).sort(); return pays[0]||''; })();
    const laborAdvance = kind==='labor' ? reserved : 0; if (collected || budget) rows.push({key, c, p, doc, line:l, kind, budget, collected:r2(collected), actual, committed, remainingToBuy:kind==='labor'?0:remainingToBuy, reserved:kind==='labor'?0:reserved, laborAdvance, floated, daysHeld: oldest && reserved ? Math.round((parse(today())-parse(oldest))/86400000) : 0}); }); }); }); return rows; }
function clientFundsSummary(){ const rows = clientFundsLedger(); const S = {reserved:0, materials:0, subs:0, labor:0, floated:0, toBuy:0, collected:0}; rows.forEach(r => { S.reserved += r.reserved; S[r.kind] += r.kind==='labor' ? r.laborAdvance : r.reserved; S.floated += r.floated; S.toBuy += r.remainingToBuy; S.collected += r.collected; }); Object.keys(S).forEach(k => S[k] = r2(S[k])); S.rows = rows; return S; }
const companyBalanceBase2 = companyBalance;
companyBalance = function(){ const B = companyBalanceBase2(); const F = clientFundsSummary(); B.clientFunds = F.reserved; B.clientFundsMaterials = F.materials; B.floated = F.floated; B.available = r2(B.cash - F.reserved); return B; };

function repFunds(){ const F = clientFundsSummary(); const B = companyBalance(); const rows = F.rows.filter(r => r.reserved || r.remainingToBuy || r.floated).sort((a,b) => b.reserved - a.reserved); const byProj = {}; rows.forEach(r => { const k = r.p?.project.name||r.c.name; const o = byProj[k] = byProj[k]||{k, reserved:0, toBuy:0, floated:0, collected:0}; o.reserved += r.reserved; o.toBuy += r.remainingToBuy; o.floated += r.floated; o.collected += r.collected; });
  return `<div class="rep-head"><div><h2 style="margin:0">Client funds & purchasing obligations</h2><div class="small muted">Cash collected for lines that still have purchasing left is the client's money until it is spent. Bank balance less those funds is what the company can actually use.</div></div></div>
    <div class="fin rep-kpis"><div class="kpi"><b>${money(B.cash)}</b><span>bank balance</span></div><div class="kpi warn"><b>− ${money(F.reserved)}</b><span>client funds held for purchases · materials ${money(F.materials)} · subs ${money(F.subs)}${F.labor?` · (labor billed ahead of work ${money(F.labor)} — ours, not reserved)`:''}</span></div><div class="kpi ${B.available<0?'warn':'good'}"><b>${money(B.available)}</b><span>available cash (ours)</span></div><div class="kpi"><b>${money(F.toBuy)}</b><span>still to purchase against budgets (net of open POs)</span></div><div class="kpi ${F.floated?'warn':''}"><b>${money(F.floated)}</b><span>spent ahead of collections — we are floating client purchases</span></div></div>
    <h3 class="rep-h">By project</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Project</th><th class="money">Collected on lines</th><th class="money">Client funds held</th><th class="money">Still to purchase</th><th class="money">Floated by us</th></tr></thead><tbody>${Object.values(byProj).map(o => `<tr><td><b>${esc(o.k)}</b></td><td class="money">${money(o.collected)}</td><td class="money">${money(o.reserved)}</td><td class="money">${money(o.toBuy)}</td><td class="money ${o.floated?'warn':''}">${o.floated?money(o.floated):'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Nothing collected yet.</td></tr>'}</tbody></table></div>
    <h3 class="rep-h">By line — where the money sits</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Line</th><th>Type</th><th class="money">Budget</th><th class="money">Collected</th><th class="money">Spent</th><th class="money">On open POs</th><th class="money">Still to buy</th><th class="money">Client funds held</th><th>Held since</th><th></th></tr></thead><tbody>${rows.map(r => `<tr class="click" data-finline="${r.key}"><td><b>${r.line.num?r.line.num+'. ':''}${esc(r.line.item||'')}</b><div class="small muted">${esc(r.p?.project.name||'')} · ${esc(r.doc.number)}</div></td><td><span class="pill ${r.kind==='materials'?'info':r.kind==='subs'?'neutral':'neutral'}">${r.kind}</span></td><td class="money">${money(r.budget)}</td><td class="money">${money(r.collected)}</td><td class="money">${money(r.actual)}</td><td class="money">${r.committed?money(r.committed):'—'}</td><td class="money">${r.remainingToBuy?money(r.remainingToBuy):'—'}</td><td class="money" style="font-weight:600">${r.reserved?money(r.reserved):'—'}</td><td class="small ${r.daysHeld>45?'warn':''}">${r.daysHeld?r.daysHeld+' d':'—'}</td><td>${r.remainingToBuy && mbCanEdit()?`<button class="btn sm" data-fundpo="${r.key}">Buy</button>`:''}</td></tr>`).join('')||'<tr><td colspan="10" class="muted">No lines with purchasing remaining.</td></tr>'}</tbody></table></div>
    <p class="small muted" style="margin-top:8px">Client funds held on a line = the smaller of (collected − spent) and (budget − spent), never below zero. Open purchase orders do not release funds — the cash leaves when the bill is paid. "Floated by us" is spend on a line beyond what the client has paid for it. Lines are typed as materials when they carry an item list or a materials name, subs when a vendor is assigned, otherwise labor.</p>`; }

/* ===================== JOB METRICS ENGINE — the one place every number comes from ===================== */
/* Definitions (printed wherever the numbers appear):
   billed        = non-void, non-draft invoices on the job: subtotal − discount (ex sales tax, before retainage); retainage-release invoices excluded
   retainage rec = Σ retainage withheld on billed invoices − Σ retainage released
   collected     = payments applied to those invoices (payments on voided invoices become unapplied credits)
   contract      = base contract (ex tax) + approved change orders (ex tax)
   budget        = Σ estimate line cost of the converted estimate + Σ approved change-order line cost
   actual        = approved/paid vendor bills + bank items not tied to a bill + clocked hours × burdened rate
   accrued       = submitted / PM-approved bills not yet approved (shown, not costed)
   committed     = issued/partial/received PO lines − bills received against those POs
   EAC           = greater of budget, actual + committed, and the PM cost-to-complete review if one exists
   % complete    = actual ÷ EAC (cost-to-cost)   earned = contract × % complete   over/(under) = billed − earned   backlog = contract − earned */
const BILL_COSTED = ['approved','paid','verified'], BILL_ACCRUED = ['submitted','pm-approved'];
let docNet = d => { const t = docTotal(d); return r2(t.sub - t.disc); };
function txnViaBill(t, bills){ return !!t.billId || bills.some(b => (b.status==='paid' && (b.vendor||'').toLowerCase()===(t.vendor||'').toLowerCase() && Math.abs(billTotal(b)+t.amt)<1) || (b.poId && (DB.pos.find(p=>p.id===b.poId)?.matchedTxns||[]).includes(t.id))); }
function jobFin(p, range){ const c = DB.clients.find(x => x.id===p.clientId); const R = range || ['', today()]; const inRng = d => within(d, R); const onJob = i => i.projectId===p.id || (!i.projectId && c && DB.projects.filter(x=>x.clientId===c.id).length===1);
  const invs = c ? c.invoices.filter(i => !['void','draft'].includes(i.status) && onJob(i) && inRng(i.date)) : []; const billedInvs = invs.filter(i => !i.retainageRelease); const releases = invs.filter(i => i.retainageRelease);
  const billed = r2(billedInvs.reduce((a,i)=>a+docNet(i),0)); const taxBilled = r2(billedInvs.reduce((a,i)=>a+docTotal(i).tax,0)); const retWithheld = r2(billedInvs.reduce((a,i)=>a+docTotal(i).ret,0)); const retReleased = r2(releases.reduce((a,i)=>a+docNet(i),0)); const retHeld = Math.max(0, r2(retWithheld - retReleased));
  const pays = c ? c.payments.filter(py => !py.unapplied && invs.some(i=>i.id===py.invoiceId) && inRng(py.date)) : []; const collected = r2(pays.reduce((a,py)=>a+(+py.amount||0),0)); const credits = c ? r2(c.payments.filter(py => py.unapplied).reduce((a,py)=>a+(+py.amount||0),0)) : 0;
  const est = c ? c.estimates.find(e => e.status==='converted' && (e.projectId===p.id || (!e.projectId && onJob({})))) || c.estimates.find(e => ['approved','converted'].includes(e.status) && e.projectId===p.id) : null; const cos = c ? c.changeOrders.filter(x => ['approved','billed'].includes(x.status) && (x.projectId===p.id || !x.projectId)) : []; const pendingCOs = c ? c.changeOrders.filter(x => x.status==='sent' && (x.projectId===p.id || !x.projectId)) : [];
  const base = c ? (c.contractNet!=null ? +c.contractNet : (+c.contract||0)) : 0; const coAmt = r2(cos.reduce((a,x)=>a+docNet(x),0)); const contract = r2((est && !c.contract ? docNet(est) : base) + coAmt); const pendingCO = r2(pendingCOs.reduce((a,x)=>a+docNet(x),0));
  const budgetLines = [...(est ? est.lines.map(l => ({l, doc:est})) : []), ...cos.flatMap(x => x.lines.map(l => ({l, doc:x})))]; const budget = r2(budgetLines.reduce((a,{l,doc})=>a+lineBudget(l,doc).budget,0));
  const bills = DB.bills.filter(b => b.projectId===p.id); const costedBills = bills.filter(b => BILL_COSTED.includes(b.status) && inRng(b.date)); const accruedBills = bills.filter(b => BILL_ACCRUED.includes(b.status)); const billsAmt = r2(costedBills.reduce((a,b)=>a+billTotal(b),0)); const accrued = r2(accruedBills.reduce((a,b)=>a+billTotal(b),0));
  const txns = DB.txns.filter(t => t.projectId===p.id && t.amt<0 && isJobCat(t.cat) && t.cat!=='labor' && inRng(t.date) && !txnViaBill(t, bills)); const txnAmt = r2(txns.reduce((a,t)=>a - t.amt, 0));
  const time = DB.time.filter(e => e.projectId===p.id && e.status!=='rejected' && inRng(e.date)); const laborByEmp = {}; let laborCost = 0, hours = 0; const laborByCode = {}; const trueUp = payrollTrueUp(); time.forEach(e => { const emp = DB.employees.find(x=>x.id===e.empId); const h = hoursOf(e); const cost = h*laborRate(emp)*trueUp(e, emp); hours += h; laborCost += cost; const k = e.empId; (laborByEmp[k] = laborByEmp[k]||{emp:emp?.name||k, hours:0, cost:0, entityId:emp?.entityId||'ent1'}).hours += h; laborByEmp[k].cost += cost; const code = e.code||'99'; laborByCode[code] = (laborByCode[code]||0)+cost; }); laborCost = r2(laborCost); hours = r2(hours);
  const actual = r2(billsAmt + txnAmt + laborCost);
  const pos = DB.pos.filter(po => po.projectId===p.id && ['issued','partial','received'].includes(po.status)); const poGross = r2(pos.reduce((a,po)=>a+poTotal(po).sub,0)); const poBilled = r2(bills.filter(b => b.status!=='void' && b.status!=='rejected' && pos.some(po=>po.id===b.poId)).reduce((a,b)=>a+billTotal(b),0)); const committed = Math.max(0, r2(poGross - poBilled));
  const ctc = +(p.ctc||0); const eac = r2(p.ctcReviewed ? Math.max(actual + committed, actual + ctc) : Math.max(budget, actual + committed)); const pct = eac ? Math.min(1, actual/eac) : 0; const earned = r2(contract*pct); const overUnder = r2(billed - earned); const backlog = r2(Math.max(0, contract - earned)); const estGP = r2(contract - eac); const plannedGP = r2(contract - budget);
  const byCode = {}; const bump = (code, k, v) => { const b = byCode[code] = byCode[code]||{code, name:(COST_CODES.find(x=>x[0]===code)||[code,'Other'])[1], contract:0, budget:0, committed:0, bills:0, bank:0, labor:0, actual:0}; b[k] += v; };
  budgetLines.forEach(({l, doc}) => { const code = lineCode(l, doc); bump(code, 'budget', lineBudget(l,doc).budget); bump(code, 'contract', lineAmount(l, doc)); }); costedBills.forEach(b => bump(b.code||(b.line?(findLine(b.line)?.line.code||codeForLine(findLine(b.line)?.line||{})):'99'), 'bills', billTotal(b))); txns.forEach(t => bump(t.code||'99', 'bank', -t.amt)); Object.entries(laborByCode).forEach(([code,v]) => bump(code, 'labor', v)); pos.forEach(po => { const tot = poTotal(po).sub; const open = Math.max(0, tot - bills.filter(b => b.poId===po.id && b.status!=='void').reduce((a,b)=>a+billTotal(b),0)); po.lines.forEach(l => { const ref = l.line ? findLine(l.line) : null; const code = l.code || (ref ? (ref.line.code||codeForLine(ref.line)) : '99'); bump(code, 'committed', tot ? open*((+l.qty||0)*(+l.price||0))/tot : 0); }); }); Object.values(byCode).forEach(b => { b.actual = r2(b.bills + b.bank + b.labor); ['contract','budget','committed','bills','bank','labor'].forEach(k => b[k] = r2(b[k])); });
  return {p, c, est, invs, billedInvs, releases, pays, billed, taxBilled, retHeld, retWithheld, retReleased, collected, credits, outstanding:r2(billed + taxBilled - collected - retHeld), contract, base:r2(contract - coAmt), coAmt, pendingCO, budget, plannedGP, plannedGPPct: contract?r2(plannedGP/contract*100):0, billsAmt, accrued, accruedBills, txnAmt, laborCost, hours, laborByEmp:Object.values(laborByEmp), actual, committed, ctc, eac, estGP, estGPPct: contract?r2(estGP/contract*100):0, pct, earned, overUnder, over:Math.max(0,overUnder), under:Math.max(0,-overUnder), backlog, backlogGP:r2(estGP*(1-pct)), byCode:Object.values(byCode).sort((a,b)=>a.code.localeCompare(b.code)), defs:'billed = invoices ex tax before retainage · actual = approved bills + bank items without a bill + burdened labor · committed = open POs net of bills · % complete = actual ÷ estimated total cost'}; }
/* payroll true-up: for dates covered by a paid payroll run, clocked cost is scaled so the job carries actual payroll (run total ÷ clocked burdened cost of that entity's people in the period); until the run posts the burdened-rate estimate stands */
function payrollTrueUp(){ const runs = DB.payroll.filter(r => ['paid','verified'].includes(r.status) && r.from && r.to && r.total); const factors = runs.map(r => { const ent = r.entityId||'ent1'; const est = DB.time.filter(e => e.status!=='rejected' && e.date>=r.from && e.date<=r.to && entOfEmpId(e.empId)===ent).reduce((a,e)=>a+hoursOf(e)*laborRate(DB.employees.find(x=>x.id===e.empId)),0); const jobPct = (r.alloc||[]).length ? (r.alloc||[]).filter(x=>x.projectId).reduce((a,x)=>a+(+x.pct||0),0)/100 : 1; return {r, ent, f: est ? Math.min(3, (+r.total||0)*jobPct/est) : 1}; }); return (e, emp) => { const ent = emp?.entityId||'ent1'; const m = factors.find(x => x.ent===ent && e.date>=x.r.from && e.date<=x.r.to); return m ? m.f : 1; }; }
const entOfEmpId = id => DB.employees.find(x=>x.id===id)?.entityId || 'ent1';
const JOBFIN_NOTE = 'One engine feeds every screen: billed = invoices ex tax, before retainage; actual = approved bills + bank items without a bill + clocked labor at burdened rates (trued up to actual payroll once a run is paid); committed = open POs net of bills; % complete = actual ÷ estimated total cost (cost-to-cost).';

/* ===================== HOME v2 — Needs me · Cash · Jobs · This month vs last ===================== */
Object.assign(PORTLETS, {needsme:'Needs me', cashblock:'Cash', jobcards:'Jobs', monthcompare:'This month vs last'});
function needsMe(){ const out = []; const rank = s => s==='bad'||s==='high' ? 0 : s==='bill' ? 0.5 : s==='warn'||s==='med' ? 1 : 2;
  reminders().filter(r => !/analyst items/.test(r.label)).forEach(r => out.push({sev:r.sev==='bad'?'bad':r.sev==='warn'?'warn':r.sev==='bill'?'bill':'', n:r.n, title:r.label, detail:'', go:r.go, action:r.sev==='bill'?'Draft invoice':'Open'}));
  analystFindings().filter(f => f.sev==='high' || f.sev==='med').forEach(f => out.push({sev:f.sev==='high'?'bad':'warn', n:f.amount?money(f.amount):'', title:f.title, detail:f.detail, go:f.go||{view:'reports', tab:'analyst'}, action:'Review'}));
  return out.sort((a,b) => rank(a.sev)-rank(b.sev)); }
let needsAll = false;
function ptNeedsMe(){ const rows = needsMe(); const show = needsAll ? rows : rows.slice(0, 8); const urgent = rows.filter(r=>r.sev==='bad').length;
  return `<div class="nm-sum small muted">${rows.length ? `${rows.length} item${rows.length>1?'s':''} · ${urgent} need${urgent===1?'s':''} action now` : 'Nothing waiting on you.'}</div><div class="rem nm">${show.map(r => `<div class="rem-row ${r.sev}" data-remgo='${esc(JSON.stringify(r.go))}'><b>${esc(String(r.n||'·'))}</b><span><b>${esc(r.title)}</b>${r.detail?`<br><span class="small muted">${r.detail}</span>`:''}</span><em class="nm-act">${r.action} ›</em></div>`).join('')}</div>${rows.length>8?`<button class="btn sm" data-nmall>${needsAll?'Show fewer':`Show all ${rows.length}`}</button>`:''}`; }
function ptCash(){ const B = companyBalance(); const F = cashForecast(); const lowWk = F.weeks.reduce((a,w) => w.balance < a.balance ? w : a, F.weeks[0]); const P = companyPL(kpiRange('tm')); const burn = r2(P.cogsT + P.ohT);
  return `<div class="cashb"><div class="cash-row"><span>In the bank</span><b>${money(B.cash)}</b></div><div class="cash-row dim"><span>− client funds held for purchases</span><b>${money(B.clientFunds)}</b></div><div class="cash-row big ${B.available<0?'bad':''}"><span>Available (ours)</span><b>${money(B.available)}</b></div>
    <div class="cash-grid"><div><span>Owed to us</span><b>${money(B.arOut)}</b><i class="${B.arOver?'bad':''}">${B.arOver?money(B.arOver)+' overdue':'nothing overdue'}</i></div><div><span>We owe</span><b>${money(B.ap)}</b><i class="${B.apOver?'bad':''}">${B.apOver?money(B.apOver)+' past due':'nothing past due'}</i></div><div><span>13-week low</span><b class="${F.low<0?'bad':F.low<burn?'warn':''}">${money(F.low)}</b><i>week of ${fmt(lowWk.start)}</i></div><div><span>Spend this month</span><b>${money(burn)}</b><i>${B.available && burn ? (B.available/burn).toFixed(1)+' months of spend available' : ''}</i></div></div>
    <div class="small muted">Available = bank balance less money clients have paid for purchases not yet made. 13-week low comes from open invoices, bills, POs, payroll cadence and recurring overhead.</div></div>`; }
function ptJobs(){ const rows = DB.projects.map(p => { const J = jobFin(p); const h = projectHealth(p); return {p, J, h}; }).filter(x => x.J.contract || x.p.tasks.length).sort((a,b) => (a.h.health?.score??50) - (b.h.health?.score??50));
  return `<div class="jobcards">${rows.map(({p, J, h}) => { const billedPct = J.contract ? Math.round(J.billed/J.contract*100) : 0; const compPct = Math.round(J.pct*100); const ahead = billedPct - compPct; const gpFade = J.plannedGPPct ? r2(J.estGPPct - J.plannedGPPct) : 0; const flags = []; if (h.late>0) flags.push(`<i class="bad">${h.late}d late</i>`); if (ahead>15) flags.push(`<i class="warn">billed ${ahead} pts ahead of work</i>`); if (ahead<-15) flags.push(`<i class="warn">${-ahead} pts under-billed</i>`); if (gpFade<-3) flags.push(`<i class="bad">margin fading ${Math.abs(gpFade)} pts</i>`); if (J.accrued) flags.push(`<i>${money(J.accrued)} bills to approve</i>`); if (h.urgent) flags.push(`<i class="bad">${h.urgent} urgent</i>`);
    return `<div class="jobcard" data-jobgo="${p.id}"><div class="jc-top"><b>${esc(p.project.name)}</b><span class="small muted">${h.sc?'finish '+fmt(h.sc):''}</span></div><div class="jc-bars"><div class="jc-bar"><span>Work ${compPct}%</span><div class="bar2"><i style="width:${compPct}%"></i></div></div><div class="jc-bar"><span>Billed ${billedPct}%</span><div class="bar2"><i style="width:${Math.min(100,billedPct)}%;background:var(--c2,#4a6fa5)"></i></div></div></div><div class="jc-nums"><span>${money(J.contract)} contract</span><span>GP ${J.estGPPct}%${J.plannedGPPct?` <span class="muted">(bid ${J.plannedGPPct}%)</span>`:''}</span><span>${money(J.backlog)} left to earn</span></div>${flags.length?`<div class="jc-flags">${flags.join('')}</div>`:'<div class="jc-flags"><i class="ok">on track</i></div>'}</div>`; }).join('')||'<div class="muted small">No jobs yet.</div>'}</div>`; }
function ptMonthCompare(){ const m = monthKeys(2); const R1 = [m[1]+'-01', today()], R0 = [m[0]+'-01', m[0]+'-31']; const P1 = companyPL(R1), P0 = companyPL(R0); const rows = [['Revenue (earned)', P1.income, P0.income, true], ['Costs', P1.cogsT, P0.cogsT, false], ['Overhead', P1.ohT, P0.ohT, false], ['Net profit', P1.net, P0.net, true], ['Collected', P1.collected, P0.collected, true], ['Billed', P1.invoiced, P0.invoiced, true]];
  return `<table class="t kpi-t"><thead><tr><th></th><th class="money">${monthLabel(m[1])}</th><th class="money">${monthLabel(m[0])}</th><th class="money">Change</th></tr></thead><tbody>${rows.map(([n,a,b,upGood]) => { const ch = b ? Math.round((a-b)/Math.abs(b)*100) : null; const good = ch==null ? '' : ((ch>=0)===upGood ? 'good' : 'bad'); return `<tr><td>${n}</td><td class="money"><b>${money(a)}</b></td><td class="money dim">${money(b)}</td><td class="money"><i class="chg ${good}">${ch==null?'—':(ch>=0?'▲':'▼')+' '+Math.abs(ch)+'%'}</i></td></tr>`; }).join('')}</tbody></table><div class="small muted" style="margin-top:6px">Month to date against the full previous month. Revenue is earned (billed ± work-in-progress adjustment), not invoices issued.</div>`; }
function monthLabel(k){ const [y,mo] = k.split('-'); return new Date(+y, +mo-1, 1).toLocaleString('en-US', {month:'short', year:'2-digit'}); }
const renderPortletBase = renderPortlet;
renderPortlet = function(p){ if (p.type==='needsme') return ptNeedsMe(); if (p.type==='cashblock') return ptCash(); if (p.type==='jobcards') return ptJobs(); if (p.type==='monthcompare') return ptMonthCompare(); return renderPortletBase(p); };
ROLE_HOME.owner = {layout:2, portlets:[{type:'needsme'}, {type:'cashblock'}, {type:'jobcards'}, {type:'monthcompare'}, {type:'chart', cfg:{period:'6m'}}, {type:'shortcuts'}]};
ROLE_HOME.pm = {layout:2, portlets:[{type:'needsme'}, {type:'jobcards'}, {type:'kpi', cfg:{kpis:['backlog','committed','billsPending','hours','cosApproved'], range:'tm', cmp:'prev', hl:{}}}, {type:'shortcuts'}]};
ROLE_HOME.coord = {layout:2, portlets:[{type:'needsme'}, {type:'jobcards'}, {type:'search', cfg:{ds:'pos', group:'vendor', title:'Open POs by vendor'}}, {type:'shortcuts'}]};
const renderHomeBase = renderHome;
renderHome = function(){ renderHomeBase(); const root = homeRoot(); root.querySelectorAll('[data-jobgo]').forEach(el => el.onclick = () => { setCurrent(el.dataset.jobgo); view = 'costs'; render(); }); root.querySelector('[data-nmall]')?.addEventListener('click', () => { needsAll = !needsAll; render(); });
  root.querySelectorAll('.portlet').forEach(el => { const t = homeDef().portlets.find(p => p.id===el.dataset.pt)?.type; if (t==='jobcards' || t==='needsme') el.classList.add('wide'); }); };
const homeDefBase = homeDef;
homeDef = function(){ const r = role(); DB.dashboards = DB.dashboards||{}; if (DB.dashboards[r] && !(DB.dashboards[r].v>=2) && (DB.published||{})[r]?.lock!=='locked') delete DB.dashboards[r]; const H = homeDefBase(); if (!(H.v>=2)) H.v = 2; return H; };

/* ===================== NAVIGATION v2 — 7 rail groups + sub-tabs; Reports in 5 groups ===================== */
const NAV_GROUPS = [
  {id:'home', n:'Brief', views:['home']},
  {id:'jobs', n:'Projects', views:['port','dash','sched','tasks','mat','dec','insp','field','files','costs','inbox','chat','proj'], proj:true},
  {id:'clients', n:'Clients & billing', views:['clients','client']},
  {id:'buy', n:'Purchasing', views:['po','vendors','inv']},
  {id:'money', n:'Accounting', views:['bank','ap','verify']},
  {id:'people', n:'People & time', views:['time','req','route']},
  {id:'reports', n:'Reports', views:['reports']},
];
const NAV_LABELS = {port:'All projects', dash:'Today', sched:'Schedule', tasks:'Tasks', mat:'Materials', dec:'Decisions', insp:'Permits', field:'Field', files:'Documents', costs:'Costs', inbox:'Inbox', chat:'Chat', proj:'Settings', clients:'Clients', client:'Project overview', po:'Purchase orders', vendors:'Vendors', inv:'Inventory & tools', bank:'Banking', ap:'Bills & payroll', verify:'Verification', time:'Time & crew', req:'Requests', route:'Route', reports:'Reports', home:'Brief'};
const NAV_ICON = {home:'<path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>', jobs:'<path d="M4 21V8l8-5 8 5v13"/><path d="M9 21v-6h6v6"/>', clients:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><path d="M16 4h5v5M21 4l-6 6"/>', buy:'<path d="M3 4h2l2.5 11h11L21 7H6.5"/><circle cx="9" cy="19" r="1.5"/><circle cx="17" cy="19" r="1.5"/>', money:'<rect x="3" y="6" width="18" height="12" rx="2"/><circle cx="12" cy="12" r="2.5"/>', people:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>', reports:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>'};
let navLast = {};
function navGroupOf(v){ return NAV_GROUPS.find(g => g.views.includes(v)); }
function renderNav(){ const nav = $('#nav'); if (!nav) return; const r = role(); const allowed = ROLE_VIEWS[r]||[]; const badge = v => { const el = document.getElementById('n-'+v); const n = el ? parseInt(el.textContent) : 0; return isNaN(n) ? 0 : n; };
  if (!nav._legacy){ nav._legacy = document.createElement('div'); nav._legacy.id = 'nav-legacy'; nav._legacy.style.display = 'none'; [...nav.querySelectorAll('button[data-v]')].forEach(b => nav._legacy.appendChild(b)); nav._projsel = nav.querySelector('.projsel'); nav.innerHTML = ''; nav.appendChild(nav._legacy); nav._wrap = document.createElement('div'); nav._wrap.id = 'nav-groups'; nav.appendChild(nav._wrap); }
  const cur = navGroupOf(view); if (cur) navLast[cur.id] = view;
  nav._wrap.innerHTML = NAV_GROUPS.map(g => { const vs = g.views.filter(v => allowed.includes(v)); if (!vs.length) return ''; const target = vs.includes(navLast[g.id]) ? navLast[g.id] : vs[0]; const n = vs.reduce((a,v)=>a+badge(v),0); return `<button data-grp="${g.id}" data-v="${target}" class="${cur&&cur.id===g.id?'on':''}"><svg viewBox="0 0 24 24">${NAV_ICON[g.id]}</svg>${g.n}<span class="n">${n||''}</span></button>`; }).join('');
  nav._wrap.querySelectorAll('button[data-grp]').forEach(b => b.onclick = () => setView(b.dataset.v));
  // sub-tabs under the top bar
  let sub = $('#subnav'); if (!sub){ sub = document.createElement('div'); sub.id = 'subnav'; sub.className = 'subnav no-print'; document.querySelector('header.topbar')?.after(sub); }
  if (nav._projsel){ nav.appendChild(nav._projsel); nav._projsel.hidden = true; } const g = cur; const vs = g ? g.views.filter(v => allowed.includes(v)) : []; const isMB = typeof MB_VIEWS!=='undefined' && MB_VIEWS.includes(view);
  if (!g || vs.length<2 || isMB){ sub.innerHTML = ''; sub.hidden = true; if (nav._projsel) nav._projsel.hidden = true; }
  else { sub.hidden = false; sub.innerHTML = `${g.proj?`<span class="sub-proj"></span>`:''}<div class="sub-tabs">${vs.map(v => `<button data-sub="${v}" class="${v===view?'on':''}">${NAV_LABELS[v]||v}${badge(v)?`<span class="n">${badge(v)}</span>`:''}</button>`).join('')}</div>`; sub.querySelectorAll('[data-sub]').forEach(b => b.onclick = () => setView(b.dataset.sub)); if (nav._projsel){ nav._projsel.hidden = !g.proj; if (g.proj){ sub.querySelector('.sub-proj').appendChild(nav._projsel); nav._projsel.hidden = false; } }
    const on = sub.querySelector('[data-sub].on'); if (on) on.scrollIntoView({block:'nearest', inline:'nearest'}); }
}
const renderBaseNav = render;
render = function(){ renderBaseNav(); renderNav(); };
/* Reports: 5 groups */
const REP_GROUPS = [
  {id:'fin', n:'Financials', tabs:[['dash','Dashboard'],['company','P&L detail'],['financials','Statements'],['budget','Budget vs actual'],['pack','Monthly pack']]},
  {id:'jobs', n:'Projects', tabs:[['portfolio','All projects'],['profit','Project profitability'],['wip','WIP schedule']]},
  {id:'cash', n:'Cash & receivables', tabs:[['funds','Client funds'],['statement','Client statement']]},
  {id:'review', n:'Review', tabs:[['analyst','Analyst'],['flash','Weekly flash']]},
  {id:'build', n:'Build a report', tabs:[['searches','Saved searches'],['custom','Custom report']]},
];
const REP_DEFS = {dash:'Earned revenue, cost and profit for the period, with comparisons.', company:'Income statement by category with drill-down to every transaction.', financials:'Income statement, balance sheet and cash flow by entity, consolidated or separate.', budget:'Annual budget against actuals by month.', pack:'The month-end package: statements, WIP, ratios and analyst notes on one printable page.', portfolio:'Every job side by side: contract, cost, billed, % complete, margin.', profit:'One job in depth: cost codes, lines, labor, billing and collections.', wip:'Work-in-progress schedule: earned vs billed, over/under billings, backlog and margin fade.', funds:'Cash clients have paid for purchases not yet made, and what the company can actually use.', statement:'Statement of account for one client.', analyst:'Anomalies, patterns and things that look off, ranked by what to act on first.', flash:'One-page weekly summary for the leadership meeting.', searches:'Saved lists and summaries you can pin to Home.', custom:'Build any table from any dataset in the system.'};
function repBarV2(projs){ const g = REP_GROUPS.find(x => x.tabs.some(t => t[0]===repTab)) || REP_GROUPS[0];
  return `<div class="rep-bar no-print rep-groups"><div class="ctabs" style="margin:0">${REP_GROUPS.map(x => `<button class="${x.id===g.id?'on':''}" data-reptab="${x.tabs[0][0]}">${x.n}</button>`).join('')}</div></div>
    <div class="rep-bar no-print rep-sub"><div class="sub-tabs">${g.tabs.map(([k,l]) => `<button class="${repTab===k?'on':''}" data-reptab="${k}">${l}</button>`).join('')}</div><span class="grow"></span>${repTab==='profit'?`<select id="rep-proj" class="btn">${projs.map(p=>`<option value="${p.id}" ${repProj===p.id?'selected':''}>${esc(p.project.name)}</option>`).join('')}</select>`:''}${repTab==='statement'?`<select id="rep-client" class="btn">${DB.clients.map(c=>`<option value="${c.id}" ${(repClient||DB.clients[0]?.id)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}${['profit','portfolio','statement'].includes(repTab)?`<label class="small">From <input type="date" id="rep-from" value="${repFrom}"></label><label class="small">To <input type="date" id="rep-to" value="${repTo}"></label>`:''}<button class="btn" id="rep-print">Print / PDF</button></div>
    <div class="small muted rep-def no-print">${REP_DEFS[repTab]||''}</div>`; }

/* ===================== INTERCOMPANY — subsidiaries as profit centers ===================== */
/* SD Plumbing / SD Electric crews clock time on SmartDesign jobs. Their hours are billed to SmartDesign Group as an intercompany bill (hours × burdened rate × (1 + markup)).
   Job cost sees the IC bill (like any sub); the clocked hours behind it are no longer costed separately, so labor is costed once.
   Entity view: the bill is cost to SmartDesign and revenue to the subsidiary. Consolidated view: the bill is eliminated and only the subsidiary's real payroll/labor cost remains. */
const entMarkup = e => (e && e.icMarkup!=null) ? +e.icMarkup : 15;
const entOfEmp = emp => emp?.entityId || 'ent1';
function icUnbilled(){ const out = {}; DB.time.filter(e => e.status!=='rejected' && !e.icBillId && e.projectId).forEach(e => { const emp = DB.employees.find(x=>x.id===e.empId); const ent = entOfEmp(emp); if (ent==='ent1') return; const p = DB.projects.find(x=>x.id===e.projectId); if (!p || entityOfProject(p)===ent) return; const h = hoursOf(e); if (!h) return; const k = ent+'|'+e.projectId; const o = out[k] = out[k]||{ent, entity:DB.entities.find(x=>x.id===ent), p, hours:0, cost:0, entries:[], byCode:{}}; o.hours += h; o.cost += h*laborRate(emp); o.entries.push(e); const c = e.code||'99'; o.byCode[c] = (o.byCode[c]||0) + h*laborRate(emp); }); Object.values(out).forEach(o => { o.hours = r2(o.hours); o.cost = r2(o.cost); o.amount = r2(o.cost*(1+entMarkup(o.entity)/100)); }); return Object.values(out).filter(o => o.amount>0); }
function icCreateBills(){ const groups = icUnbilled(); if (!groups.length){ toast('No unbilled subsidiary hours'); return 0; } const t = today(); const m = t.slice(0,7); groups.forEach(o => { const n = (DB.bills.filter(b=>b.ic).length+1); const b = {id:uid('b'), number:`IC-${m.replace('-','')}-${String(n).padStart(2,'0')}`, vendor:o.entity.name, date:t, due:iso(addDays(t, 30)), entityId:entityOfProject(o.p), projectId:o.p.id, cat:'subs', code:Object.entries(o.byCode).sort((a,b)=>b[1]-a[1])[0]?.[0]||'99', ic:{from:o.ent, to:entityOfProject(o.p), hours:o.hours, cost:o.cost, markup:entMarkup(o.entity)}, lines:Object.entries(o.byCode).map(([code,c]) => ({id:uid('bl'), desc:`${o.entity.name.replace(/ LLC$/,'')} labor — ${(COST_CODES.find(x=>x[0]===code)||[code,'Other'])[1]} · ${r2(c/ (o.cost||1) * o.hours)} h`, amount:r2(c*(1+entMarkup(o.entity)/100))})), payMethod:'Intercompany', status:'approved', approvals:[{t:nowStamp(), by:S.project.userName||'', role:role(), action:'intercompany bill generated from approved hours'}], notes:`${o.hours} h × burdened rate + ${entMarkup(o.entity)}% = ${money(o.amount)}`}; DB.bills.push(b); o.entries.forEach(e => e.icBillId = b.id); try { audit('bill', b.id, 'intercompany', '', 'approved', `${b.number} ${o.entity.name} → ${o.p.project.name} ${money(o.amount)}`); } catch(err){} }); save(); toast(`${groups.length} intercompany bill${groups.length>1?'s':''} created`); return groups.length; }
/* labor costed once: clocked entries already carried by an IC bill drop out of the engine's labor line */
const jobFinBase = jobFin;
jobFin = function(p, range){ const hidden = new Set(DB.time.filter(e => e.icBillId).map(e => e.id)); if (!hidden.size) return jobFinBase(p, range); const keep = DB.time; DB.time = keep.filter(e => !hidden.has(e.id)); try { const J = jobFinBase(p, range); J.icBills = DB.bills.filter(b => b.ic && b.projectId===p.id && BILL_COSTED.includes(b.status)).reduce((a,b)=>a+billTotal(b),0); J.defs += ' · subsidiary crews are costed through intercompany bills, not clocked hours'; return J; } finally { DB.time = keep; } };
/* ledger: consolidated view eliminates IC bills; an entity view shows them as cost (to) — IC revenue (from) is added in companyPL */
const ledgerBase2 = ledger;
ledger = function(range){ const rows = ledgerBase2(range); return repEntity ? rows : rows.filter(r => !(r.kind==='bill' && r.ref.ic)); };
function icRevenue(range, ent){ return r2(DB.bills.filter(b => b.ic && b.ic.from===ent && BILL_COSTED.includes(b.status) && within(b.date, range)).reduce((a,b)=>a+billTotal(b),0)); }
function icCost(range, ent){ return r2(DB.bills.filter(b => b.ic && b.ic.to===ent && BILL_COSTED.includes(b.status) && within(b.date, range)).reduce((a,b)=>a+billTotal(b),0)); }
const companyPLBase3 = companyPL;
companyPL = function(range){ const P = companyPLBase3(range); P.icRevenue = repEntity ? icRevenue(range, repEntity) : 0; P.icCost = repEntity ? icCost(range, repEntity) : 0; P.icEliminated = repEntity ? 0 : r2(DB.bills.filter(b => b.ic && BILL_COSTED.includes(b.status) && within(b.date, range)).reduce((a,b)=>a+billTotal(b),0)); if (P.icRevenue){ P.income = r2(P.income + P.icRevenue); P.gross = r2(P.income - P.cogsT); P.net = r2(P.gross - P.ohT); P.grossPct = P.income?Math.round(P.gross/P.income*100):0; P.netPct = P.income?Math.round(P.net/P.income*100):0; } return P; };
/* entities side by side */
function entityPL(range){ const keep = repEntity; const cols = []; try { DB.entities.forEach(e => { repEntity = e.id; cols.push({e, P:companyPL(range)}); }); repEntity = ''; const C = companyPL(range); const elim = r2(cols.reduce((a,c)=>a+c.P.icRevenue,0)); return {cols, C, elim}; } finally { repEntity = keep; } }
function repEntities(){ const range = cfoRange(); const {cols, C, elim} = entityPL(range); const un = icUnbilled(); const icBills = DB.bills.filter(b => b.ic).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);
  const line = (label, f, cls='') => `<tr class="${cls}"><td>${label}</td>${cols.map(c => `<td class="money">${money(f(c.P))}</td>`).join('')}<td class="money dim">${label==='Income'||label==='Job cost'?'− '+money(elim):'—'}</td><td class="money"><b>${money(f(C))}</b></td></tr>`;
  return `<h3 class="rep-h">Entities side by side — ${({month:'This month', quarter:'This quarter', ytd:'Year to date', all:'All time'})[cfoPeriod]||'Year to date'}</h3><div class="tw"><table class="t rep-t fs"><thead><tr><th></th>${cols.map(c=>`<th class="money">${esc(c.e.name.replace(/ LLC$/,''))}</th>`).join('')}<th class="money">Eliminations</th><th class="money">Consolidated</th></tr></thead><tbody>
    ${line('Income', P=>P.income, 'inc')}${line('of which intercompany', P=>P.icRevenue, 'dim')}${line('Job cost', P=>P.cogsT)}${line('of which intercompany', P=>P.icCost, 'dim')}${line('Gross profit', P=>P.gross, 'tot')}${line('Overhead', P=>P.ohT)}${line('Net profit', P=>P.net, 'tot inc')}<tr class="dim"><td>Net margin</td>${cols.map(c=>`<td class="money">${c.P.netPct}%</td>`).join('')}<td></td><td class="money">${C.netPct}%</td></tr></tbody></table></div>
    <p class="small muted">Subsidiary crews bill their hours to SmartDesign Group as intercompany bills (burdened rate + markup). Each entity is a profit center on its own column; eliminations remove the intercompany amounts so the consolidated column counts the work once.</p>
    <div class="grid2" style="margin-top:12px"><div class="card"><h3 class="rep-h" style="margin-top:0">Subsidiary hours not yet billed</h3>${un.length?`<table class="t"><thead><tr><th>From</th><th>Job</th><th class="money">Hours</th><th class="money">Cost</th><th class="money">Bill (+markup)</th></tr></thead><tbody>${un.map(o=>`<tr><td>${esc(o.entity.name.replace(/ LLC$/,''))}</td><td>${esc(o.p.project.name)}</td><td class="money">${o.hours}</td><td class="money">${money(o.cost)}</td><td class="money"><b>${money(o.amount)}</b></td></tr>`).join('')}</tbody></table>${role()==='owner'||role()==='pm'?`<button class="btn primary" id="ic-create" style="margin-top:8px">Create intercompany bills</button>`:''}`:'<div class="muted small">All subsidiary hours are billed.</div>'}<div class="small muted" style="margin-top:8px">Markup per entity: ${DB.entities.filter(e=>e.id!=='ent1').map(e=>`${esc(e.name.replace(/ LLC$/,''))} ${entMarkup(e)}%`).join(' · ')} <a href="#" id="ic-markup">change</a></div></div>
    <div class="card"><h3 class="rep-h" style="margin-top:0">Intercompany bills</h3>${icBills.length?`<table class="t"><thead><tr><th>Bill</th><th>From → to</th><th>Job</th><th class="money">Hours</th><th class="money">Amount</th><th>Status</th></tr></thead><tbody>${icBills.map(b=>`<tr><td style="white-space:nowrap">${esc(b.number)}<div class="small muted">${fmt(b.date)}</div></td><td>${esc(entName(b.ic.from).replace(/ LLC$/,""))} → ${esc(entName(b.ic.to).replace(/ LLC$/,""))}</td><td>${esc(DB.projects.find(p=>p.id===b.projectId)?.project.name||'')}</td><td class="money">${b.ic.hours}</td><td class="money">${money(billTotal(b))}</td><td><span class="pill ${billState(b).cls}">${b.status==="approved"?"Approved":billState(b).text}</span></td></tr>`).join('')}</tbody></table>`:'<div class="muted small">None yet.</div>'}</div></div>`; }
function icWire(){ $('#ic-create')?.addEventListener('click', () => { const n = icUnbilled(); if (!confirm(`Create ${n.length} intercompany bill${n.length>1?'s':''} totalling ${money(n.reduce((a,o)=>a+o.amount,0))}? Clocked hours behind them stop being costed separately.`)) return; icCreateBills(); render(); });
  $('#ic-markup')?.addEventListener('click', e => { e.preventDefault(); mbModal('Intercompany markup', `<p class="small muted">Applied on top of burdened labor cost when a subsidiary bills SmartDesign Group.</p>${DB.entities.filter(x=>x.id!=='ent1').map(x=>`<label class="f"><span>${esc(x.name)}</span><input type="number" step="1" min="0" data-icm="${x.id}" value="${entMarkup(x)}"> %</label>`).join('')}`, {submit:'Save', onSubmit:()=>{ document.querySelectorAll('[data-icm]').forEach(i => { const en = DB.entities.find(x=>x.id===i.dataset.icm); if (en) en.icMarkup = +i.value||0; }); save(); render(); }}); }); }
const repFinancialsBase = repFinancials;
repFinancials = function(){ return repFinancialsBase() + tieOutHtml(cfoRange()) + repEntities(); };
const renderReportsBase = renderReports;
renderReports = function(){ renderReportsBase(); icWire(); };
const remindersBase = reminders;
reminders = function(){ const out = remindersBase(); const un = icUnbilled(); const h = r2(un.reduce((a,o)=>a+o.hours,0)); if (h) out.push({n:h, label:'subsidiary hours to bill intercompany · '+money(un.reduce((a,o)=>a+o.amount,0)), go:{view:'reports', tab:'financials'}, sev:''}); return out; };

/* ===================== COST TO COMPLETE + MONTH-END CLOSE ===================== */
/* PM cost-to-complete review: per cost code, the PM states what it will still cost to finish. Estimated total cost = actual + cost to complete (never below actual + open POs). Without a review, EAC = greater of budget and actual + committed. */
function ctcReview(p){ const J = jobFin(p); const rows = J.byCode.filter(r => r.budget || r.actual || r.committed); const cur = p.ctcByCode||{}; const rem = r => Math.max(0, r2(r.budget - r.actual - r.committed));
  mbModal(`Cost to complete — ${esc(p.project.name)}`, `<p class="small muted">For each cost code, what will it still cost to finish (beyond bills already in and open POs)? Defaults to budget remaining. ${p.ctcReviewed?`Last reviewed ${fmt(p.ctcReviewed)} by ${esc(p.ctcBy||'')}.`:''}</p>
    <div class="tw"><table class="t"><thead><tr><th>Code</th><th class="money">Budget</th><th class="money">Actual</th><th class="money">Open POs</th><th class="money">Budget left</th><th class="money" style="width:130px">Cost to complete</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r.code} ${esc(r.name)}</td><td class="money">${money(r.budget)}</td><td class="money">${money(r.actual)}</td><td class="money">${r.committed?money(r.committed):'—'}</td><td class="money">${money(rem(r))}</td><td class="money"><input type="number" step="1" min="0" data-ctc="${r.code}" value="${cur[r.code]!=null?cur[r.code]:rem(r)}" style="width:110px;text-align:right"></td></tr>`).join('')}</tbody><tfoot><tr style="font-weight:600"><td>Estimated total cost</td><td class="money">${money(J.budget)}</td><td class="money">${money(J.actual)}</td><td class="money">${money(J.committed)}</td><td></td><td class="money" id="ctc-eac">${money(J.eac)}</td></tr></tfoot></table></div><div class="small muted" id="ctc-note" style="margin-top:6px"></div>`,
    {submit:'Save review', onSubmit:()=>{ const o = {}; document.querySelectorAll('[data-ctc]').forEach(i => o[i.dataset.ctc] = +i.value||0); p.ctcByCode = o; p.ctc = r2(Object.values(o).reduce((a,v)=>a+v,0)); p.ctcReviewed = today(); p.ctcBy = S.project.userName||''; try { audit('project', p.id, 'ctc-review', '', String(p.ctc), `${p.project.name} cost to complete ${money(p.ctc)}`); } catch(e){} save(); render(); toast('Cost to complete saved'); }});
  const upd = () => { let s = 0; document.querySelectorAll('[data-ctc]').forEach(i => s += +i.value||0); const eac = Math.max(J.actual + J.committed, J.actual + s); $('#ctc-eac').textContent = money(eac); $('#ctc-note').textContent = `Estimated total cost ${money(eac)} · estimated gross profit ${money(J.contract - eac)} (${J.contract?Math.round((J.contract-eac)/J.contract*100):0}%) · bid margin ${J.plannedGPPct}%`; }; document.querySelectorAll('[data-ctc]').forEach(i => i.addEventListener('input', upd)); upd(); }
const renderCostsBase = renderCosts;
renderCosts = function(){ renderCostsBase(); const acts = document.querySelector('#v-costs .acts'); if (acts && !acts.querySelector('#btn-ctc')){ const b = document.createElement('button'); b.className = 'btn'; b.id = 'btn-ctc'; acts.appendChild(b); } const b = $('#btn-ctc'); if (b){ b.textContent = S.ctcReviewed ? `Cost to complete · reviewed ${fmt(S.ctcReviewed)}` : 'Review cost to complete'; b.onclick = () => ctcReview(S); } };

/* Month-end close: a checklist, then the month locks. The WIP snapshot for a locked month is frozen (fade is measured against it) and documents dated inside it ask for a reason before they change. */
function lockedThrough(){ return (DB.periods||{}).lockedThrough || ''; }
function isLocked(date){ const l = lockedThrough(); return !!(l && date && date.slice(0,7) <= l); }
function closeChecklist(month){ const R = [month+'-01', month+'-31']; const items = [];
  const add = (label, n, go) => items.push({label, n, go, ok:!n});
  add('Vendor bills awaiting approval', DB.bills.filter(b => BILL_ACCRUED.includes(b.status) && within(b.date, R)).length, {view:'ap'});
  add('Bank transactions not categorized', DB.txns.filter(t => within(t.date, R) && (!t.cat || t.cat==='uncat' || t.status==='new')).length, {view:'bank'});
  add('Job-cost transactions with no project', DB.txns.filter(t => within(t.date, R) && isJobCat(t.cat) && !t.projectId).length, {view:'bank'});
  add('Time entries not approved', DB.time.filter(e => within(e.date, R) && ['open','submitted'].includes(e.status)).length, {view:'time'});
  add('Subsidiary hours not billed intercompany', icUnbilled().filter(o => o.entries.some(e => within(e.date, R))).length, {view:'reports', tab:'financials'});
  add('Draft invoices dated in the month', DB.clients.flatMap(c=>c.invoices).filter(i => i.status==='draft' && within(i.date, R)).length, {view:'clients'});
  add('Jobs without a cost-to-complete review this month', DB.projects.filter(p => jobFin(p).contract && !(p.ctcReviewed && p.ctcReviewed.slice(0,7) >= month)).length, {view:'costs'});
  return items; }
function closeMonthDialog(){ const l = lockedThrough(); const t = today(); const prev = (() => { const d = new Date(t.slice(0,4), +t.slice(5,7)-2, 1); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; })(); const month = l ? (() => { const d = new Date(l.slice(0,4), +l.slice(5,7), 1); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; })() : prev; if (month >= t.slice(0,7)){ toast('The current month cannot be closed yet'); return; }
  const items = closeChecklist(month); const open = items.filter(i=>!i.ok).length; const label = new Date(month+'-01T00:00:00').toLocaleString('en-US', {month:'long', year:'numeric'});
  mbModal(`Close ${label}`, `<p class="small muted">Closing freezes the WIP snapshot for ${label} and locks its documents. Everything below should be at zero first.</p><div class="rem">${items.map(i => `<div class="rem-row ${i.ok?'':'warn'}" data-remgo='${esc(JSON.stringify(i.go))}'><b>${i.ok?'✓':i.n}</b><span>${i.label}</span></div>`).join('')}</div>${open?`<div class="note warn" style="margin-top:8px">${open} item${open>1?'s':''} still open. You can close anyway — the reason is recorded.</div>`:''}`,
    {submit:`Close ${label}`, onSubmit:()=>{ let reason = ''; if (open){ reason = prompt(`${open} checklist item(s) are still open. Reason for closing anyway:`); if (reason===null) return; if (!reason.trim()){ toast('A reason is required'); return; } } DB.periods = DB.periods||{}; DB.periods.lockedThrough = month; DB.periods.closes = DB.periods.closes||[]; DB.periods.closes.push({month, t:nowStamp(), by:S.project.userName||'', open, reason}); wipSnapshotFor(month); try { audit('period', month, 'close', '', month, reason||'clean close'); } catch(e){} save(); render(); toast(`${label} closed`); }});
  document.querySelectorAll('#mbm [data-remgo]').forEach(el => el.onclick = () => { const go = JSON.parse(el.dataset.remgo); mbCloseModal(); if (go.tab) repTab = go.tab; view = go.view; render(); }); }
function reopenMonth(){ const l = lockedThrough(); if (!l) return; const reason = prompt(`Reopen ${l}? Reason:`); if (!reason) return; const closes = (DB.periods.closes||[]).map(x=>x.month).filter(m => m < l).sort(); DB.periods.lockedThrough = closes.pop() || ''; try { audit('period', l, 'reopen', l, DB.periods.lockedThrough, reason); } catch(e){} save(); render(); }
function wipSnapshotFor(month){ DB.wipHistory = DB.wipHistory||[]; const end = month+'-31'; DB.projects.forEach(p => { const J = jobFin(p, ['', end]); const rec = {month, projectId:p.id, contract:J.contract, eac:J.eac, estGP:J.estGP, gpPct:J.estGPPct, pct:r2(J.pct*100), earned:J.earned, billed:J.billed, frozen:true}; const ex = DB.wipHistory.find(h => h.month===month && h.projectId===p.id); if (ex) Object.assign(ex, rec); else DB.wipHistory.push(rec); }); }
const wipSnapshotBase = wipSnapshot;
wipSnapshot = function(){ const m = today().slice(0,7); if (isLocked(m+'-01')) return; DB.wipHistory = DB.wipHistory||[]; const keep = DB.wipHistory.filter(h => h.frozen); wipSnapshotBase(); DB.wipHistory = DB.wipHistory.filter(h => !(h.frozen===undefined && keep.some(k => k.month===h.month && k.projectId===h.projectId))).concat(keep.filter(k => !DB.wipHistory.some(h => h.month===k.month && h.projectId===k.projectId && h.frozen))); };
const repWIPBase = repWIP;
repWIP = function(){ const l = lockedThrough(); const bar = `<div class="close-bar no-print"><span class="small muted">${l?`Books closed through ${new Date(l+'-01T00:00:00').toLocaleString('en-US',{month:'long',year:'numeric'})} · WIP snapshots frozen`:'No month closed yet'}</span><span class="grow"></span>${role()==='owner'?`<button class="btn" id="close-month">Close month…</button>${l?`<button class="btn sm" id="reopen-month">Reopen</button>`:''}`:''}</div>`; return bar + repWIPBase(); };
const renderReportsBase2 = renderReports;
renderReports = function(){ renderReportsBase2(); $('#close-month')?.addEventListener('click', closeMonthDialog); $('#reopen-month')?.addEventListener('click', reopenMonth); };
/* documents dated inside a closed month */
const docActionBase = docAction;
docAction = async function(c, d, a){ if (['send','approve','approveconvert','void','del','convert'].includes(a) && isLocked(d.date)){ const reason = prompt(`${d.number} is dated in a closed month (${d.date}). Reason for changing it:`); if (!reason) return; try { audit(d.type, d.id, 'locked-period-change', d.status, a, reason); } catch(e){} } return docActionBase(c, d, a); };

/* ===================== DESIGN ESTIMATE / BILLING TEMPLATE + STUDIO KPIs ===================== */
/* A design proposal is a set of phases. Each phase is either hourly (est. hours × studio rate) or fixed fee. Billing: a retainer at signing that is applied against later invoices,
   then progress invoices either by milestone (e.g. 50% at signing / 40% at filing / 10% at sign-off, as % of every phase) or by hours (approved design hours × each person's bill rate).
   Studio KPIs: hours vs estimate per phase, realization (fees billed ÷ hours × bill rate), utilization (billable hours ÷ available hours) per designer. */
const DESIGN_PHASES = [['Schematic design', 40], ['Design development', 60], ['Construction documents', 80], ['Filing & permits', 24], ['Construction administration', 40]];
const DESIGN_MILESTONES = [{label:'At signing', pct:50}, {label:'At filing / submission', pct:40}, {label:'At sign-off', pct:10}];
const designRate = () => +(DB.company.designRate||175);
const isDesignStaff = emp => !!(emp && (+emp.billRate||0) > 0);
function designInit(){ DB.company.designRate = DB.company.designRate||175; if (!DB.employees.some(e=>e.id==='em6')) DB.employees.push({id:'em6', name:'Maya', role:'Architect', rate:55, burden:20, billRate:175, entityId:'ent1', active:true}, {id:'em7', name:'Maja', role:'Designer', rate:40, burden:20, billRate:140, entityId:'ent1', active:true});
  if (DB.__designSeeded || !DB.projects.some(p=>p.id==='p121')) return; DB.__designSeeded = true;
  const p = projectFromTemplate('45 Cranberry St — design', '45 Cranberry St, Brooklyn Heights', '2026-08-03', ''); p.id = 'p45'; p.entityId = 'ent1'; p.materials = []; p.decisions = p.decisions.filter(d => d.kind!=='mat'); DB.projects.push(p);
  const c = {id:'cl45', name:'Rivera family', company:'', type:'Residential owner', contacts:[{id:'ct45', name:'Elena Rivera', email:'elena.rivera@example.com', phone:'(646) 555-0188', role:'Owner', primary:true}], propertyAddr:'45 Cranberry St, Brooklyn Heights', billingAddr:'', prefComm:'email', notes:'Landmark townhouse — full design through LPC approval.', estimates:[], changeOrders:[], invoices:[], sov:[], payments:[], docs:[], activity:[], contract:0}; migrateClientDocs(c); DB.clients.push(c); p.clientId = c.id;
  const lines = DESIGN_PHASES.map(([n,h]) => ({id:uid('l'), item:n, desc:'', qty:h, unit:'hr', rate:designRate(), taxable:false, cost:r2(h*66), code:'01'}));
  const est = {id:'esD45', type:'estimate', number:'EST-2026-D45', title:'Design services — 45 Cranberry St', date:'2026-07-20', validUntil:'2026-08-19', status:'converted', approvedOn:'2026-07-28', projectId:p.id, template:'design', billing:'milestones', milestones:JSON.parse(JSON.stringify(DESIGN_MILESTONES)), retainer:5000, lines, discount:{type:'pct',value:0}, taxRate:0, terms:'Retainer due at signing; progress invoices net 15', memo:'Fees by phase at the studio rate. Filing fees and expediting billed at cost.', internal:''};
  c.estimates.push(est); docMark(est); const t = docTotal(est); c.contract = t.total; c.contractNet = r2(t.sub - t.disc); c.contractDate = '2026-07-28'; c.sov = lines.map((l,i) => ({id:uid('sv'), taxable:false, desc:l.item, scheduled:lineAmount(l, est), source:'Contract', order:i, lineRef:`estimate:${est.id}:${l.id}`}));
  const ret = {id:'inD45r', type:'invoice', mode:'items', number:'INV-2026-D45-R', title:'Design retainer', date:'2026-07-28', due:'2026-07-28', status:'paid', projectId:p.id, template:'design', retainerOf:est.id, lines:[{id:uid('l'), item:'Design retainer', desc:'Applied against progress invoices', qty:1, unit:'ls', rate:5000, taxable:false}], discount:{type:'pct',value:0}, taxRate:0, retainagePct:0, terms:'Due on receipt', memo:''}; c.invoices.push(ret); docMark(ret); c.payments.push({id:uid('py'), invoiceId:ret.id, date:'2026-07-30', amount:5000, method:'ACH', ref:'Retainer'});
  const mk = (id, em, date, h, code, note) => ({id, empId:em, date, in:`${date}T09:00:00`, out:`${date}T${String(9+Math.floor(h)).padStart(2,'0')}:${h%1?'30':'00'}:00`, breakMin:0, projectId:p.id, code, notes:note||'', status:'approved', approvedBy:'Alan', source:'seed', phase:0});
  [['2026-08-04',7,'Maya'],['2026-08-05',6.5,'Maya'],['2026-08-06',8,'Maya'],['2026-08-11',7,'Maya'],['2026-08-12',5,'Maya'],['2026-08-18',8,'Maya'],['2026-08-19',6,'Maya'],['2026-08-25',7.5,'Maya'],['2026-09-01',7,'Maya'],['2026-09-02',6,'Maya'],['2026-08-05',8,'Maja'],['2026-08-06',8,'Maja'],['2026-08-12',7,'Maja'],['2026-08-13',8,'Maja'],['2026-08-20',6,'Maja'],['2026-08-27',8,'Maja'],['2026-09-02',8,'Maja']].forEach(([d,h,who],i) => DB.time.push(mk('teD'+i, who==='Maya'?'em6':'em7', d, h, '01', 'Schematic design')));
  const m0 = {id:'inD45m1', type:'invoice', mode:'items', number:'INV-2026-D45-1', title:'At signing — 50% of design fee', date:'2026-08-03', due:'2026-08-18', status:'paid', projectId:p.id, template:'design', fromDoc:est.id, milestone:0, lines:lines.map(l => ({id:uid('l'), item:l.item, desc:'50% of phase', qty:1, unit:'ls', rate:r2(lineAmount(l, est)*0.5), taxable:false, fromLine:`estimate:${est.id}:${l.id}`, pct:50})), discount:{type:'pct',value:0}, taxRate:0, retainagePct:0, terms:'Net 15', memo:''}; applyRetainer(c, est, m0); c.invoices.push(m0); docMark(m0); est.milestonesBilled = [0]; c.payments.push({id:uid('py'), invoiceId:m0.id, date:'2026-08-14', amount:docTotal(m0).total, method:'ACH', ref:'INV-2026-D45-1'}); docMark(est);
  p.permits.push({id:uid('pm'), name:'LPC Certificate of Appropriateness — filed', agency:'LPC', number:'LPC-26-08812', issued:'2026-08-28', expires:'', status:'active'});
  c.activity.push({t:nowStamp(), by:'', text:'EST-2026-D45 design proposal approved · retainer INV-2026-D45-R paid · INV-2026-D45-1 (at signing) paid'}); }
function retainerBalance(c, estId){ const paid = c.invoices.filter(i => i.retainerOf===estId && i.status!=='void').reduce((a,i)=>a+invoicePaid(c, i),0); const applied = c.invoices.filter(i => i.fromDoc===estId && i.status!=='void').reduce((a,i)=>a+(+i.retainerApplied||0),0); return r2(paid - applied); }
function designHoursUnbilled(c, d){ const p = DB.projects.find(x=>x.id===d.projectId); if (!p) return []; return DB.time.filter(e => e.projectId===p.id && e.status==='approved' && !e.invoiceId && isDesignStaff(DB.employees.find(x=>x.id===e.empId))); }
function applyRetainer(c, d, inv){ const bal = retainerBalance(c, d.id); if (bal<=0) return; const sub = docTotal(inv).sub; const use = Math.min(bal, sub); if (use<=0) return; inv.lines.push({id:uid('l'), item:'Less retainer applied', desc:`Retainer on account ${money(bal)}`, qty:1, unit:'ls', rate:-use, taxable:false, retainerLine:true}); inv.retainerApplied = use; }
function designRetainerInvoice(c, d){ const amt = +prompt('Retainer amount', d.retainer||5000); if (!amt) return; const inv = newDoc(c, 'invoice', {mode:'items'}); inv.template = 'design'; inv.title = 'Design retainer'; inv.terms = 'Due on receipt'; inv.retainerOf = d.id; inv.lines = [{id:uid('l'), item:'Design retainer', desc:'Applied against progress invoices', qty:1, unit:'ls', rate:amt, taxable:false}]; d.retainer = amt; docMark(inv); c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} retainer — ${money(amt)}`}); docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }
function designMilestoneInvoice(c, d){ const ms = d.milestones||DESIGN_MILESTONES; const done = d.milestonesBilled||[]; const total = docNet(d);
  const m = mbModal(`Bill a milestone — ${esc(d.number)}`, `<p class="small muted">Each milestone bills its percentage of every phase. Retainer on account ${money(retainerBalance(c, d.id))} is applied automatically.</p><div class="rem">${ms.map((x,i) => `<label class="rem-row ${done.includes(i)?'dim':''}" style="cursor:pointer"><input type="radio" name="dms" value="${i}" ${done.includes(i)?'disabled':(!done.length&&i===0)||done.length===i?'checked':''}> <b>${x.pct}%</b><span>${esc(x.label)} · ${money(total*x.pct/100)}${done.includes(i)?' · billed':''}</span></label>`).join('')}</div><div class="small muted" style="margin-top:8px">Billed so far ${done.reduce((a,i)=>a+(ms[i]?.pct||0),0)}% of ${money(total)}. <a href="#" id="dms-edit">Edit milestones</a></div>`,
    {submit:'Create invoice', onSubmit:()=>{ const i = +(m.querySelector('[name=dms]:checked')?.value ?? -1); if (i<0){ toast('Pick a milestone'); return false; } const x = ms[i]; const inv = newDoc(c, 'invoice', {mode:'items'}); inv.template = 'design'; inv.title = `${x.label} — ${x.pct}% of design fee`; inv.fromDoc = d.id; inv.milestone = i; inv.lines = d.lines.map(l => ({id:uid('l'), item:l.item, desc:`${x.pct}% of phase`, qty:1, unit:'ls', rate:r2(lineAmount(l,d)*x.pct/100), taxable:false, fromLine:`estimate:${d.id}:${l.id}`, pct:x.pct})); applyRetainer(c, d, inv); docMark(inv); d.milestonesBilled = [...done, i]; c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} — ${x.label} ${x.pct}% · ${money(docTotal(inv).total)}`}); docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }});
  m.querySelector('#dms-edit')?.addEventListener('click', e => { e.preventDefault(); const txt = prompt('Milestones as label:percent, one per line', ms.map(x=>`${x.label}:${x.pct}`).join('\n')); if (txt===null) return; const next = txt.split('\n').map(s => s.split(':')).filter(a => a.length===2 && +a[1]).map(a => ({label:a[0].trim(), pct:+a[1]})); if (next.reduce((a,x)=>a+x.pct,0)!==100){ toast('Milestones must total 100%'); return; } d.milestones = next; save(); mbCloseModal(); designMilestoneInvoice(c, d); }); }
function designHoursInvoice(c, d){ const ents = designHoursUnbilled(c, d); if (!ents.length){ toast('No approved, unbilled design hours on this project'); return; } const by = {}; ents.forEach(e => { const emp = DB.employees.find(x=>x.id===e.empId); const o = by[e.empId] = by[e.empId]||{emp, hours:0, ids:[], from:e.date, to:e.date}; o.hours += hoursOf(e); o.ids.push(e.id); if (e.date<o.from) o.from = e.date; if (e.date>o.to) o.to = e.date; }); const rows = Object.values(by);
  const m = mbModal(`Bill design hours — ${esc(d.number)}`, `<p class="small muted">Approved hours on ${esc(DB.projects.find(p=>p.id===d.projectId)?.project.name||'')} not yet invoiced, at each person's bill rate. Retainer on account ${money(retainerBalance(c, d.id))} is applied automatically.</p><table class="t"><thead><tr><th></th><th>Person</th><th>Dates</th><th class="money">Hours</th><th class="money">Rate</th><th class="money">Amount</th></tr></thead><tbody>${rows.map((r,i) => `<tr><td><input type="checkbox" data-dh="${i}" checked></td><td>${esc(r.emp.name)}<div class="small muted">${esc(r.emp.role||'')}</div></td><td class="small">${fmt(r.from)} – ${fmt(r.to)}</td><td class="money">${r2(r.hours)}</td><td class="money">${money(laborBillRate(r.emp))}</td><td class="money"><b>${money(r.hours*laborBillRate(r.emp))}</b></td></tr>`).join('')}</tbody></table>`,
    {submit:'Create invoice', onSubmit:()=>{ const picks = [...m.querySelectorAll('[data-dh]:checked')].map(cb => rows[+cb.dataset.dh]); if (!picks.length){ toast('Select at least one person'); return false; } const inv = newDoc(c, 'invoice', {mode:'items'}); inv.template = 'design'; inv.title = `Design services — hours through ${fmt(today())}`; inv.fromDoc = d.id; inv.hoursBilled = true; inv.lines = picks.map(r => ({id:uid('l'), item:`${r.emp.name} — ${r.emp.role||'design'}`, desc:`${fmt(r.from)} – ${fmt(r.to)}`, qty:r2(r.hours), unit:'hr', rate:laborBillRate(r.emp), taxable:false, timeIds:r.ids, fromLine:`estimate:${d.id}:${d.lines[0]?.id}`})); applyRetainer(c, d, inv); docMark(inv); picks.forEach(r => r.ids.forEach(id => { const e = DB.time.find(x=>x.id===id); if (e) e.invoiceId = inv.id; })); c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} — ${r2(picks.reduce((a,r)=>a+r.hours,0))} design hours · ${money(docTotal(inv).total)}`}); docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }}); }
/* estimate + actions */
const newDocBase = newDoc;
newDoc = function(c, kind, opts={}){ const d = newDocBase(c, kind, opts); if (kind==='estimate' && opts.template==='design'){ d.title = 'Design proposal'; d.terms = 'Retainer due at signing; progress invoices net 15'; d.billing = 'milestones'; d.milestones = JSON.parse(JSON.stringify(DESIGN_MILESTONES)); d.retainer = 5000; d.lines = DESIGN_PHASES.map(([n,h]) => ({id:uid('l'), item:n, desc:'', qty:h, unit:'hr', rate:designRate(), taxable:false, cost:r2(h*66), code:'01'})); docMark(d); } return d; };
const docActionsBase = docActions;
docActions = function(c, d, st){ let h = docActionsBase(c, d, st); if (d.type==='estimate' && d.template==='design' && ['approved','converted'].includes(d.status)){ const B = (a, l, cls='') => `<button class="btn sm ${cls}" data-docact="${a}">${l}</button>`; const hasRet = c.invoices.some(i => i.retainerOf===d.id && i.status!=='void'); const extra = (hasRet ? '' : B('dretainer', 'Retainer invoice', 'primary')) + B('dmilestone', 'Bill milestone…', hasRet?'primary':'') + B('dhours', `Bill design hours…${designHoursUnbilled(c,d).length?` (${r2(designHoursUnbilled(c,d).reduce((a,e)=>a+hoursOf(e),0))} h)`:''}`); h = h.replace(/<button class="btn sm primary" data-docact="invoice">[^<]*<\/button>/, '') + extra; } return h; };
const docActionBase2 = docAction;
docAction = async function(c, d, a){ if (d.type==='estimate' && d.template==='design'){ if (a==='approve') a = 'approveconvert'; if (a==='dretainer'){ designRetainerInvoice(c, d); return; } if (a==='dmilestone'){ designMilestoneInvoice(c, d); return; } if (a==='dhours'){ designHoursInvoice(c, d); return; } } return docActionBase2(c, d, a); };
/* design estimate header strip: billing method + retainer + milestone progress */
function designStrip(c, d){ if (d.type!=='estimate' || d.template!=='design') return ''; const ms = d.milestones||DESIGN_MILESTONES; const done = d.milestonesBilled||[]; const hrs = DB.time.filter(e => e.projectId===d.projectId && e.status!=='rejected' && isDesignStaff(DB.employees.find(x=>x.id===e.empId))); const h = r2(hrs.reduce((a,e)=>a+hoursOf(e),0)); const estH = d.lines.filter(l=>l.unit==='hr').reduce((a,l)=>a+(+l.qty||0),0); const bal = retainerBalance(c, d.id);
  return `<div class="dstrip"><div><span>Billing</span><b>${d.billing==='hours'?'By hours':'By milestone'}</b><i>${d.billing==='hours'?'approved design hours × bill rate':ms.map((x,i)=>`<em class="${done.includes(i)?'done':''}">${x.pct}% ${esc(x.label)}</em>`).join(' → ')}</i></div><div><span>Retainer</span><b>${money(d.retainer||0)}</b><i>${bal>0?`${money(bal)} on account`:c.invoices.some(i=>i.retainerOf===d.id)?'fully applied':'not invoiced yet'}</i></div><div><span>Design hours</span><b>${h} / ${estH} h</b><i>${estH?Math.round(h/estH*100):0}% of estimate used</i></div><div><span>Fee billed</span><b>${money(designBilled(c, d))}</b><i>of ${money(docNet(d))} fee</i></div>${mbCanEdit()&&['draft','sent'].includes(d.status)?`<div><span>Method</span><select data-dbilling class="btn sm"><option value="milestones" ${d.billing!=='hours'?'selected':''}>Milestones</option><option value="hours" ${d.billing==='hours'?'selected':''}>Hours</option></select></div>`:''}</div>`; }
function designBilled(c, d){ return r2(c.invoices.filter(i => i.fromDoc===d.id && !['void','draft'].includes(i.status)).reduce((a,i)=>a+docTotal(i).sub + (+i.retainerApplied||0),0)); }
/* studio report */
function repStudio(){ const R = [repFrom||'', repTo||today()]; const jobs = []; DB.clients.forEach(c => c.estimates.filter(e => e.template==='design' && ['approved','converted'].includes(e.status)).forEach(d => { const p = DB.projects.find(x=>x.id===d.projectId); const ents = DB.time.filter(e => e.projectId===d.projectId && e.status!=='rejected' && isDesignStaff(DB.employees.find(x=>x.id===e.empId))); const hours = r2(ents.reduce((a,e)=>a+hoursOf(e),0)); const stdValue = r2(ents.reduce((a,e)=>a+hoursOf(e)*(laborBillRate(DB.employees.find(x=>x.id===e.empId))),0)); const cost = r2(ents.reduce((a,e)=>a+hoursOf(e)*laborRate(DB.employees.find(x=>x.id===e.empId)),0)); const estH = d.lines.filter(l=>l.unit==='hr').reduce((a,l)=>a+(+l.qty||0),0); const fee = docNet(d); const billed = designBilled(c, d); const earned = estH ? r2(fee*Math.min(1, hours/estH)) : billed; jobs.push({c, d, p, fee, estH, hours, stdValue, cost, billed, earned, realization: stdValue ? Math.round(billed/stdValue*100) : null, retainer:retainerBalance(c, d.id), unbilledH: r2(designHoursUnbilled(c, d).reduce((a,e)=>a+hoursOf(e),0))}); }));
  const staff = DB.employees.filter(isDesignStaff); const m = today().slice(0,7); const R1 = [m+'-01', today()]; const wd = (() => { let n = 0; for (let d = parse(R1[0]); d <= parse(R1[1]); d = addDays(d, 1)) if (d.getDay()>0 && d.getDay()<6) n++; return n; })(); const util = staff.map(emp => { const es = DB.time.filter(e => e.empId===emp.id && e.status!=='rejected' && within(e.date, R1)); const billable = r2(es.filter(e=>e.projectId).reduce((a,e)=>a+hoursOf(e),0)); const all = r2(es.reduce((a,e)=>a+hoursOf(e),0)); const avail = wd*8; const billedH = r2(es.filter(e=>e.invoiceId).reduce((a,e)=>a+hoursOf(e),0)); return {emp, billable, all, avail, util: avail?Math.round(billable/avail*100):0, billedH, value:r2(billable*emp.billRate)}; });
  const T = jobs.reduce((a,j) => { ['fee','hours','estH','billed','earned','stdValue','cost','retainer'].forEach(k => a[k]=(a[k]||0)+j[k]); return a; }, {}); const M = v => v ? money(v) : '<span class="muted">—</span>';
  return `<div class="rep-head"><div><h2 style="margin:0">Studio — design fees, hours and utilization</h2><div class="small muted">Design proposals and the hours behind them · month-to-date utilization</div></div></div>
    <div class="fin rep-kpis"><div class="kpi"><b>${money(T.fee||0)}</b><span>design fees under contract</span></div><div class="kpi"><b>${money(T.billed||0)}</b><span>billed · ${money(T.earned||0)} earned by hours</span></div><div class="kpi ${T.stdValue && T.billed/T.stdValue<0.85?'warn':''}"><b>${T.stdValue?Math.round(T.billed/T.stdValue*100)+'%':'—'}</b><span>realization · fees billed ÷ hours at bill rates (${money(T.stdValue||0)})</span></div><div class="kpi"><b>${util.length?Math.round(util.reduce((a,u)=>a+u.util,0)/util.length)+'%':'—'}</b><span>studio utilization this month · target 65–75%</span></div><div class="kpi"><b>${money(T.retainer||0)}</b><span>retainers on account (client money until applied)</span></div></div>
    <h3 class="rep-h">By proposal</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Proposal</th><th>Billing</th><th class="money">Fee</th><th class="money">Hours (est.)</th><th class="money">Hours used</th><th class="money">Hours value</th><th class="money">Labor cost</th><th class="money">Billed</th><th class="money">Earned by hours</th><th class="money">Realization</th><th class="money">Retainer</th><th class="money">Unbilled h</th></tr></thead><tbody>${jobs.map(j => `<tr><td><b>${esc(j.d.title||j.d.number)}</b><div class="small muted">${esc(j.c.name)} · ${esc(j.p?.project.name||'')}</div></td><td>${j.d.billing==='hours'?'hours':'milestones'}</td><td class="money">${money(j.fee)}</td><td class="money">${j.estH}</td><td class="money ${j.estH&&j.hours>j.estH?'bad':''}">${j.hours}</td><td class="money">${M(j.stdValue)}</td><td class="money">${M(j.cost)}</td><td class="money">${M(j.billed)}</td><td class="money">${M(j.earned)}</td><td class="money ${j.realization!=null&&j.realization<85?'bad':''}">${j.realization!=null?j.realization+'%':'—'}</td><td class="money">${M(j.retainer)}</td><td class="money">${j.unbilledH||'—'}</td></tr>`).join('')||'<tr><td colspan="12" class="muted">No design proposals yet.</td></tr>'}</tbody></table></div>
    <h3 class="rep-h">Utilization — ${monthLabel(m)} to date (${wd} working days)</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Person</th><th class="money">Bill rate</th><th class="money">Available h</th><th class="money">Billable h</th><th class="money">Utilization</th><th class="money">Invoiced h</th><th class="money">Value at rate</th></tr></thead><tbody>${util.map(u => `<tr><td><b>${esc(u.emp.name)}</b> <span class="small muted">${esc(u.emp.role||'')}</span></td><td class="money">${money(+u.emp.billRate)}</td><td class="money">${u.avail}</td><td class="money">${u.billable}</td><td class="money"><div class="bar2" style="display:inline-block;width:80px;vertical-align:middle;margin-right:6px"><i style="width:${Math.min(100,u.util)}%;${u.util<50?'background:var(--bad)':u.util<65?'background:var(--warn,#B26A00)':''}"></i></div>${u.util}%</td><td class="money">${u.billedH}</td><td class="money">${money(u.value)}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">No design staff (set a bill rate on an employee).</td></tr>'}</tbody></table></div>
    <p class="small muted">Realization = fees billed ÷ (hours worked × bill rate); under 85% means hours are being written off. Utilization = hours clocked to projects ÷ 8 h × working days so far this month. Earned by hours = fee × hours used ÷ hours estimated, capped at the fee.</p>`; }
REP_GROUPS.find(g=>g.id==='jobs').tabs.push(['studio','Studio']); REP_DEFS.studio = 'Design fees, hours against estimate, realization and designer utilization.';
const renderReportsBase3 = renderReports;
renderReports = function(){ if (repTab==='studio'){ renderReportsBase3(); $('#rep-print-area').innerHTML = repStudio(); return; } renderReportsBase3(); };
document.addEventListener('change', e => { const s = e.target.closest && e.target.closest('[data-dbilling]'); if (!s || !docOpen) return; const c = DB.clients.find(x=>x.id===clientOpen); const d = c && findDoc(c, docOpen.kind, docOpen.id); if (!d) return; d.billing = s.value; save(); render(); });

/* ===================== FINISH MATERIALS TEMPLATE ===================== */
/* One line per item (tile, millwork, fixtures…), taxable, with vendor and lead time. Billed in full or split (e.g. millwork 50% on order / 50% at delivery) through "Invoice from this estimate…" — each line remembers how much of it has been billed. POs come from the same lines by vendor. Money collected but not yet spent shows as client funds. */
const newDocBase2 = newDoc;
newDoc = function(c, kind, opts={}){ const d = newDocBase2(c, kind, opts); if (kind==='estimate' && opts.template==='materials'){ d.title = 'Finish materials'; d.terms = 'Due on receipt; split items balance due at delivery'; d.taxRate = +DB.company.tax||0; d.lines = [{id:uid('l'), item:'', desc:'', qty:1, unit:'ea', rate:0, taxable:true, cost:0, vendor:'', leadWeeks:''}]; docMark(d); } return d; };
function materialsStrip(c, d){ if (d.type!=='estimate' || d.template!=='materials' || !d.lines.length) return ''; const rows = d.lines.map(l => { const f = lineFin(`estimate:${d.id}:${l.id}`); return f || {price:lineAmount(l,d), billed:0, collected:0, committed:0, actual:0, billedPct:0}; }); const S1 = k => r2(rows.reduce((a,r)=>a+(r[k]||0),0)); const pos = DB.pos.filter(po => po.lines.some(pl => (pl.line||'').startsWith(`estimate:${d.id}:`))); const funds = clientFundsLedger().filter(r => r.doc.id===d.id); const held = r2(funds.reduce((a,r)=>a+r.reserved,0));
  return `<div class="dstrip"><div><span>Billed</span><b>${money(S1('billed'))}</b><i>of ${money(S1('price'))} · ${rows.filter(r=>r.billedPct>=100).length}/${rows.length} lines in full</i></div><div><span>Collected</span><b>${money(S1('collected'))}</b><i>${held?`${money(held)} held for purchases`:'nothing held'}</i></div><div><span>Purchase orders</span><b>${pos.length}</b><i>${money(S1('committed'))} open · ${money(S1('actual'))} spent</i></div><div><span>Vendors</span><b>${[...new Set(d.lines.map(l=>l.vendor).filter(Boolean))].length}</b><i>${[...new Set(d.lines.map(l=>l.vendor).filter(Boolean))].slice(0,3).map(esc).join(', ')||'assign vendors on lines for POs'}</i></div></div>`; }
const docActionBase3 = docAction;
docAction = async function(c, d, a){ if (d.type==='estimate' && d.template==='materials' && a==='approve') a = 'approveconvert'; return docActionBase3(c, d, a); };

/* items-mode invoices billed from a line (fromLine) count toward that line's billed / collected — e.g. finish materials 50% on order, 50% at delivery */
const lineFinBase = lineFin;
lineFin = function(key){ const f = lineFinBase(key); if (!f) return f; const c = f.client || f.c || findLine(key)?.client; if (!c) return f; let billed = 0, collected = 0, pct = 0; const nums = []; c.invoices.filter(i => i.mode!=='sov' && !['void','draft'].includes(i.status)).forEach(i => { const t = docTotal(i); const paid = invoicePaid(c, i); const ratio = t.total ? Math.min(1, paid/t.total) : 0; i.lines.filter(x => x.fromLine===key && !x.retainerLine).forEach(x => { const amt = lineAmount(x, i); billed += amt; collected += amt*ratio; pct += x.pct ? +x.pct : (f.price ? amt/f.price*100 : 0); if (!nums.includes(i.number)) nums.push(i.number); }); }); if (billed){ f.billed = r2(f.billed + billed); f.collected = r2(f.collected + collected); f.billedPct = r2(f.billedPct + pct); f.invoiced = [...(f.invoiced||[]), ...nums]; f.outstanding = r2(f.billed - f.collected - (f.retained||0)); } return f; };

/* ===================== CREDITS ON ACCOUNT + QUICKBOOKS EXPORT ===================== */
function applyCredits(c, inv){ const bal = clientFin(c).open.find(o => o.x.id===inv.id)?.bal || 0; if (bal<=0){ toast('Nothing outstanding on this invoice'); return; } let left = bal, used = 0; c.payments.filter(py => py.unapplied).forEach(py => { if (left<=0) return; const amt = +py.amount||0; if (amt <= left){ py.unapplied = false; py.invoiceId = inv.id; py.appliedFrom = py.voidedInvoice||''; left -= amt; used += amt; } else { py.amount = r2(amt - left); c.payments.push({id:uid('py'), invoiceId:inv.id, date:today(), amount:left, method:py.method||'Credit', ref:`Credit from ${py.voidedInvoice||'account'}`, appliedFrom:py.voidedInvoice||''}); used += left; left = 0; } }); if (!used){ toast('No credit on account'); return; } if (left<=0.005) inv.status = 'paid'; c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${money(used)} credit on account applied to ${inv.number}`}); try { audit('invoice', inv.id, 'apply-credit', '', String(used), `${inv.number} credit applied ${money(used)}`); } catch(e){} save(); render(); toast(`${money(used)} credit applied`); }
const docActionsBase2 = docActions;
docActions = function(c, d, st){ let h = docActionsBase2(c, d, st); if (d.type==='invoice' && !['void','draft','paid'].includes(d.status)){ const cr = clientFin(c).credits; if (cr>0) h += `<button class="btn sm primary" data-docact="applycredit">Apply credit on account (${money(cr)})</button>`; } return h; };
const docActionBase4 = docAction;
docAction = async function(c, d, a){ if (a==='applycredit'){ applyCredits(c, d); return; } return docActionBase4(c, d, a); };
/* QuickBooks Online export — CSVs that map onto QBO import formats. Customers ↔ clients, Items ↔ estimate lines, Invoices, Bills (vendor + job as Class), and a journal entry for the period's WIP adjustment and intercompany eliminations. */
function qboRows(kind, range){ const R = range; const q = s => `"${String(s??'').replace(/"/g,'""')}"`; const out = [];
  if (kind==='customers'){ out.push(['Name','Company','Email','Phone','Billing Address']); DB.clients.forEach(c => out.push([c.name, c.company||'', c.contacts?.[0]?.email||'', c.contacts?.[0]?.phone||'', c.billingAddr||c.propertyAddr||''])); }
  if (kind==='invoices'){ out.push(['*InvoiceNo','*Customer','*InvoiceDate','*DueDate','Terms','Item(Product/Service)','ItemDescription','ItemQuantity','ItemRate','*ItemAmount','ItemTaxCode','Class','Memo']); DB.clients.forEach(c => c.invoices.filter(i => !['void','draft'].includes(i.status) && within(i.date, R)).forEach(i => { const job = DB.projects.find(p=>p.id===i.projectId)?.project.name||''; i.lines.forEach(l => out.push([i.number, c.name, i.date, i.due||i.date, i.terms||'', i.retainerOf?'Design retainer':l.item||'Progress billing', l.desc||'', i.mode==='sov'?1:(+l.qty||1), i.mode==='sov'?lineAmount(l,i):(+l.rate||0), lineAmount(l,i), l.taxable?'TAX':'NON', job, i.title||''])); const t = docTotal(i); if (t.ret) out.push([i.number, c.name, i.date, i.due||i.date, i.terms||'', 'Retainage withheld', `${i.retainagePct}% retainage`, 1, -t.ret, -t.ret, 'NON', job, '']); })); }
  if (kind==='bills'){ out.push(['*BillNo','*Vendor','*BillDate','*DueDate','Terms','*Account','LineDescription','*LineAmount','Class','Memo']); DB.bills.filter(b => BILL_COSTED.includes(b.status) && within(b.date, R)).forEach(b => { const job = DB.projects.find(p=>p.id===b.projectId)?.project.name||''; const acct = b.ic ? 'Intercompany labor' : (CATEGORIES.find(x=>x.id===b.cat)?.n||'Job cost'); (b.lines||[]).forEach(l => out.push([b.number, b.vendor, b.date, b.due||b.date, '', acct, l.desc||'', +l.amount||0, job, b.notes||''])); }); }
  if (kind==='journal'){ out.push(['*JournalNo','*JournalDate','*AccountName','Debits','Credits','Description','Name','Class']); const end = R[1]||today(); const jn = 'WIP-'+end.replace(/-/g,''); DB.projects.forEach(p => { const J = jobFin(p, ['', end]); if (!J.contract) return; const ou = J.overUnder; if (Math.abs(ou) < 0.5) return; const job = p.project.name; if (ou > 0){ out.push([jn, end, 'Contract revenue', ou, '', 'Billings in excess of costs and estimated earnings', '', job]); out.push([jn, end, 'Billings in excess of earnings (liability)', '', ou, 'Over-billing at '+end, '', job]); } else { out.push([jn, end, 'Costs and estimated earnings in excess of billings (asset)', -ou, '', 'Under-billing at '+end, '', job]); out.push([jn, end, 'Contract revenue', '', -ou, 'Earned not yet billed', '', job]); } }); const ic = DB.bills.filter(b => b.ic && BILL_COSTED.includes(b.status) && within(b.date, R)).reduce((a,b)=>a+billTotal(b),0); if (ic){ out.push(['IC-'+end.replace(/-/g,''), end, 'Intercompany revenue', ic, '', 'Eliminate intercompany labor billed by subsidiaries', '', 'Consolidation']); out.push(['IC-'+end.replace(/-/g,''), end, 'Intercompany labor', '', ic, 'Eliminate intercompany labor cost', '', 'Consolidation']); } }
  return out; }
function qboCSV(rows){ return rows.map(r => r.map(v => typeof v==='number' ? v : `"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'); }
let qboKind = 'invoices';
function repQBO(){ const R = [repFrom||monthKeys(1)[0]+'-01', repTo||today()]; const kinds = [['customers','Customers'],['invoices','Invoices'],['bills','Bills'],['journal','Journal — WIP & eliminations']]; const rows = qboRows(qboKind, R); const head = rows[0]||[]; const body = rows.slice(1);
  return `<div class="rep-head"><div><h2 style="margin:0">QuickBooks Online export</h2><div class="small muted">Files in QBO's import layout · ${fmt(R[0])} – ${fmt(R[1])} · jobs go to Class, entities are separate company files</div></div></div>
    <div class="row no-print" style="gap:8px;align-items:center;margin-bottom:10px"><div class="seg sm">${kinds.map(([k,l]) => `<button class="${qboKind===k?'on':''}" data-qbo="${k}">${l}</button>`).join('')}</div><span class="grow"></span><label class="small">From <input type="date" id="rep-from" value="${repFrom}"></label><label class="small">To <input type="date" id="rep-to" value="${repTo}"></label><button class="btn primary" id="qbo-dl">Download CSV (${body.length} rows)</button></div>
    <div class="tw"><table class="t rep-t"><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.slice(0,60).map(r => `<tr>${r.map(v => `<td class="${typeof v==='number'?'money':''}">${typeof v==='number'?money(v):esc(String(v))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${head.length||1}" class="muted">Nothing in this period.</td></tr>`}</tbody></table></div>${body.length>60?`<div class="small muted">Showing 60 of ${body.length} rows — the download has all of them.</div>`:''}
    <p class="small muted">Mapping: client → Customer · estimate line → Item (product/service) · invoice line → Invoice line with Class = job · retainage → negative "Retainage withheld" line · bill → Bill with Account = category and Class = job · intercompany bills → "Intercompany labor" account · month-end journal books over/under billings per job and eliminates intercompany. Design retainers export as a "Design retainer" item (liability until applied).</p>`; }
REP_GROUPS.find(g=>g.id==='build').tabs.push(['qbo','QuickBooks export']); REP_DEFS.qbo = 'CSV files in QuickBooks Online import layout: customers, invoices, bills, and the month-end journal.';
const renderReportsBase4 = renderReports;
renderReports = function(){ renderReportsBase4(); if (repTab!=='qbo') return; $('#rep-print-area').innerHTML = repQBO(); document.querySelectorAll('[data-qbo]').forEach(b => b.onclick = () => { qboKind = b.dataset.qbo; render(); }); $('#rep-from')?.addEventListener('change', e => { repFrom = e.target.value; render(); }); $('#rep-to')?.addEventListener('change', e => { repTo = e.target.value; render(); });
  $('#qbo-dl')?.addEventListener('click', () => { const R = [repFrom||monthKeys(1)[0]+'-01', repTo||today()]; const csv = qboCSV(qboRows(qboKind, R)); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv],{type:'text/csv'})); a.download = `qbo_${qboKind}_${R[0]}_${R[1]}.csv`; a.click(); toast('CSV ready'); }); };

/* ===================== OWNED PROPERTIES — Property → Unit → Lease → Tenant → Loan · rent roll · NOI / DSCR · capex as SmartDesign jobs · HTC ===================== */
MB_VIEWS.push('mbown', 'mbownp');
let mbOwnId = '', ownTab = 'overview';
const ownedProps = () => DB.properties.filter(p => p.owned);
const monthsBetween = (a, b) => { const A = parse(a), B = parse(b); return (B.getFullYear()-A.getFullYear())*12 + (B.getMonth()-A.getMonth()); };
function loanCalc(L, asOf){ if (!L || !L.principal) return {payment:0, balance:0, interestM:0, principalM:0, monthsLeft:0}; const r = (+L.rate||0)/100/12, n = +L.termMonths||360; const pmt = r ? L.principal*r/(1-Math.pow(1+r,-n)) : L.principal/n; const k = Math.max(0, Math.min(n, monthsBetween(L.start||asOf, asOf||today()))); const io = +L.ioMonths||0; let bal = +L.principal; for (let i=0;i<k;i++){ if (i<io) continue; bal -= (pmt - bal*r); } const interestM = bal*r; return {payment: k<io ? bal*r : pmt, balance:r2(Math.max(0,bal)), interestM:r2(interestM), principalM:r2(k<io?0:pmt-interestM), monthsLeft:n-k, maturity: L.maturity || (L.start ? iso(new Date(new Date(L.start+'T00:00:00').setMonth(new Date(L.start+'T00:00:00').getMonth()+n))) : '')}; }
function rentRoll(p){ const O = p.owned; const units = (O.units||[]).map(u => { const L = u.lease; const active = L && L.status!=='ended' && (!L.end || L.end >= today()); const rent = active ? +L.rent||0 : 0; const daysToEnd = active && L.end ? Math.round((parse(L.end)-parse(today()))/86400000) : null; return {u, L, active, rent, market:+u.market||rent, daysToEnd}; }); const scheduled = r2(units.reduce((a,x)=>a+x.rent,0)); const potential = r2(units.reduce((a,x)=>a+(x.active?x.rent:x.market),0)); const occ = units.length ? units.filter(x=>x.active).length/units.length : 0; return {units, scheduled, potential, occ, vacant:units.filter(x=>!x.active)}; }
function rentCollected(p, month){ return r2((p.owned.rentLedger||[]).filter(r => r.month===month && r.paid).reduce((a,r)=>a+(+r.amount||0),0)); }
function rentDue(p, month){ const RR = rentRoll(p); return r2(RR.units.filter(x=>x.active).reduce((a,x)=>a+x.rent,0)); }
function delinquent(p){ const m = today().slice(0,7); const RR = rentRoll(p); return RR.units.filter(x => x.active && !(p.owned.rentLedger||[]).some(r => r.unitId===x.u.id && r.month===m && r.paid)); }
function propertyFin(p){ const O = p.owned; const RR = rentRoll(p); const opexM = r2((O.opex||[]).reduce((a,o)=>a + (o.pct ? RR.scheduled*(+o.pct)/100 : +o.monthly||0), 0)); const vacancyM = r2(RR.potential - RR.scheduled); const egi = RR.scheduled; const noiM = r2(egi - opexM); const Lc = loanCalc(O.loan, today()); const dsM = r2(Lc.payment); const cfM = r2(noiM - dsM); const capex = DB.projects.filter(x => x.propertyId===p.id); const capexCost = r2(capex.reduce((a,x)=>a+jobFin(x).billed,0)); const basis = r2((+O.basis||0) + capexCost); const value = +O.value || (O.capRate && noiM ? r2(noiM*12/(+O.capRate/100)) : basis); const m = today().slice(0,7); const collected = rentCollected(p, m); const due = rentDue(p, m);
  return {RR, opexM, vacancyM, egi, noiM, noiA:r2(noiM*12), dsM, dsA:r2(dsM*12), cfM, cfA:r2(cfM*12), dscr: dsM ? r2(noiM/dsM) : null, Lc, capex, capexCost, basis, value, ltv: value ? r2(Lc.balance/value*100) : null, capRate: basis ? r2(noiM*12/basis*100) : null, collected, due, delinquent:delinquent(p), htc:O.htc||null, htcDays: O.htc?.complianceEnd ? Math.round((parse(O.htc.complianceEnd)-parse(today()))/86400000) : null, loanDays: Lc.maturity ? Math.round((parse(Lc.maturity)-parse(today()))/86400000) : null}; }
function propertyPL(p, range){ const months = []; const acq = (p.owned.acquired||'').slice(0,7); let a = (range[0]||acq||today()).slice(0,7); if (acq && a < acq) a = acq; const b = (range[1]||today()).slice(0,7); let cur = a; while (cur <= b && months.length < 240){ months.push(cur); const d = new Date(cur+'-01T00:00:00'); d.setMonth(d.getMonth()+1); cur = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; } const F = propertyFin(p); const income = r2(months.reduce((a,m)=>a+rentCollected(p, m),0)); const full = months.filter(m => m < today().slice(0,7)).length + (months.includes(today().slice(0,7)) ? 1 : 0); const opex = r2(F.opexM*full); const interest = r2(F.Lc.interestM*full); return {income, opex, interest, net:r2(income - opex - interest), months:full}; }
const propEntity = p => (DB.entities||[]).find(e => e.propertyId===p.id);
function ownInit(){ if (DB.__ownSeeded) return; DB.__ownSeeded = true; const p = mbNewProperty('206 Lenox Ave', {borough:'Manhattan', neighborhood:'Harlem', aliases:['206 Lenox']}); DB.entities.push({id:'ent_206', name:'206 Lenox LLC', ein:'', type:'property', propertyId:p.id});
  p.owned = {entityId:'ent_206', acquired:'2025-05-01', basis:2400000, value:0, capRate:5.5, units:[{id:'u1', name:'Garden', sf:1100, beds:2, market:3400, lease:{tenant:'J. Morales', start:'2025-09-01', end:'2026-11-30', rent:3300, deposit:3300, status:'active'}}, {id:'u2', name:'Parlor', sf:1250, beds:2, market:3900, lease:{tenant:'A. & K. Chen', start:'2026-02-01', end:'2027-01-31', rent:3850, deposit:3850, status:'active'}}, {id:'u3', name:'3rd floor', sf:1000, beds:1, market:3200, lease:null}, {id:'u4', name:'Retail', sf:900, beds:0, market:6500, lease:{tenant:'Lenox Coffee Co.', start:'2025-11-01', end:'2030-10-31', rent:6200, deposit:12400, status:'active'}}], loan:{lender:'Community Bank', principal:1150000, rate:6.25, termMonths:360, ioMonths:0, start:'2025-06-01'}, opex:[{cat:'Property taxes', monthly:2450},{cat:'Insurance', monthly:610},{cat:'Utilities (common)', monthly:380},{cat:'Repairs & maintenance', monthly:450},{cat:'Management', pct:5}], htc:{placedInService:'2025-05-01', complianceEnd:'2030-05-01', credit:480000, qre:2400000}, rentLedger:[]};
  const t0 = (typeof S!=='undefined' && S && S.project) ? today() : (DB.projects[0]?.project?.today || iso(new Date())); const m0 = t0.slice(0,7); const prev = k => { const d = new Date(m0+'-01T00:00:00'); d.setMonth(d.getMonth()-k); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`; }; const ms = []; for (let k=16;k>=0;k--) ms.push(prev(k)); ms.forEach((m, i) => p.owned.units.forEach(u => { if (!u.lease) return; if (m===m0 && u.id==='u4') return; if (m < u.lease.start.slice(0,7)) return; p.owned.rentLedger.push({id:uid('rl'), unitId:u.id, month:m, amount:u.lease.rent, paid:true, date:m+'-03'}); }));
  const cl = {id:'cl206', name:'206 Lenox LLC', company:'206 Lenox LLC', type:'Owned property (M&B)', contacts:[], propertyAddr:'206 Lenox Ave', billingAddr:'', prefComm:'email', notes:'Intercompany — capex on an owned property.', estimates:[], changeOrders:[], invoices:[], sov:[], payments:[], docs:[], activity:[], contract:0, entityId:'ent_206'}; migrateClientDocs(cl); DB.clients.push(cl);
  const pj = projectFromTemplate('206 Lenox — 3rd floor turnover', '206 Lenox Ave', t0, ''); pj.id = 'p206'; pj.clientId = cl.id; pj.propertyId = p.id; pj.entityId = 'ent1'; pj.materials = pj.materials.slice(0, 5); DB.projects.push(pj); }
/* P&L: a property LLC is its own profit center; consolidated adds them */
const companyPLBase4 = companyPL;
companyPL = function(range){ const P = companyPLBase4(range); const props = ownedProps().filter(p => !repEntity || propEntity(p)?.id===repEntity); if (!props.length) return P; const R = props.map(p => propertyPL(p, range)); const inc = r2(R.reduce((a,x)=>a+x.income,0)), opex = r2(R.reduce((a,x)=>a+x.opex,0)), int = r2(R.reduce((a,x)=>a+x.interest,0)); P.rent = inc; P.income = r2(P.income + inc); if (opex) P.oh['Property operating'] = (P.oh['Property operating']||0) + opex; if (int) P.oh['Mortgage interest'] = (P.oh['Mortgage interest']||0) + int; P.ohT = r2(P.ohT + opex + int); P.gross = r2(P.income - P.cogsT); P.net = r2(P.gross - P.ohT); P.grossPct = P.income?Math.round(P.gross/P.income*100):0; P.netPct = P.income?Math.round(P.net/P.income*100):0; return P; };
/* reminders */
const remindersBase2 = reminders;
reminders = function(){ const out = remindersBase2(); ownedProps().forEach(p => { const F = propertyFin(p); const go = {view:'mbownp', ws:'mb', own:p.id}; const a = p.address; if (F.RR.vacant.length) out.push({n:F.RR.vacant.length, label:`vacant unit${F.RR.vacant.length>1?'s':''} at ${a} · ${money(F.vacancyM)}/mo`, go, sev:'warn'}); if (F.delinquent.length) out.push({n:F.delinquent.length, label:`rent not received this month at ${a} · ${money(F.delinquent.reduce((s,x)=>s+x.rent,0))}`, go, sev:'bad'}); F.RR.units.filter(x => x.daysToEnd!=null && x.daysToEnd <= 90).forEach(x => out.push({n:x.daysToEnd, label:`days until ${x.u.name} lease ends at ${a} (${esc(x.L.tenant)})`, go, sev:'warn'})); if (F.dscr!=null && F.dscr < 1.2) out.push({n:F.dscr, label:`DSCR below 1.20 at ${a}`, go, sev:'bad'}); if (F.loanDays!=null && F.loanDays < 365) out.push({n:Math.round(F.loanDays/30), label:`months to loan maturity at ${a}`, go, sev:'warn'}); if (F.htcDays!=null && F.htcDays < 365) out.push({n:Math.round(F.htcDays/30), label:`months left in HTC compliance period at ${a}`, go, sev:'warn'}); }); return out; };
/* views */
function ownOpen(id, tab){ mbOwnId = id; if (tab) ownTab = tab; view = 'mbownp'; render(); mbTop(); }
function renderMBOwn(){ const rows = ownedProps().map(p => ({p, F:propertyFin(p)})); const T = rows.reduce((a,{F}) => { a.units += F.RR.units.length; a.occ += F.RR.units.filter(x=>x.active).length; a.rent += F.RR.scheduled; a.noi += F.noiA; a.ds += F.dsA; a.debt += F.Lc.balance; a.value += F.value; a.cf += F.cfA; return a; }, {units:0, occ:0, rent:0, noi:0, ds:0, debt:0, value:0, cf:0});
  $('#mb-own').innerHTML = `<div class="fin rep-kpis"><div class="kpi"><b>${rows.length}</b><span>properties · ${T.units} units · ${T.units?Math.round(T.occ/T.units*100):0}% occupied</span></div><div class="kpi"><b>${money(T.rent)}</b><span>monthly rent in place</span></div><div class="kpi"><b>${money(T.noi)}</b><span>annual NOI · ${T.ds?(T.noi/T.ds).toFixed(2):'—'}× portfolio DSCR</span></div><div class="kpi ${T.cf<0?'warn':''}"><b>${money(T.cf)}</b><span>annual cash flow after debt service</span></div><div class="kpi"><b>${money(T.value - T.debt)}</b><span>equity · ${money(T.value)} value less ${money(T.debt)} debt</span></div></div>
    <div class="jobcards">${rows.map(({p, F}) => { const flags = []; if (F.RR.vacant.length) flags.push(`<i class="warn">${F.RR.vacant.length} vacant</i>`); if (F.delinquent.length) flags.push(`<i class="bad">${F.delinquent.length} rent unpaid</i>`); if (F.dscr!=null && F.dscr<1.2) flags.push(`<i class="bad">DSCR ${F.dscr}</i>`); if (F.loanDays!=null && F.loanDays<365) flags.push(`<i class="warn">loan matures ${fmt(F.Lc.maturity)}</i>`); if (F.htcDays!=null && F.htcDays<365) flags.push(`<i class="warn">HTC compliance ends ${fmt(F.htc.complianceEnd)}</i>`); if (F.capex.length) flags.push(`<i>${F.capex.length} capex job${F.capex.length>1?'s':''}</i>`);
      return `<div class="jobcard" data-own="${p.id}"><div class="jc-top"><b>${esc(p.address)}</b><span class="small muted">${esc(propEntity(p)?.name||'')}</span></div><div class="jc-bars"><div class="jc-bar"><span>Occupancy ${Math.round(F.RR.occ*100)}%</span><div class="bar2"><i style="width:${Math.round(F.RR.occ*100)}%"></i></div></div><div class="jc-bar"><span>Rent collected ${F.due?Math.round(F.collected/F.due*100):0}%</span><div class="bar2"><i style="width:${F.due?Math.min(100,Math.round(F.collected/F.due*100)):0}%;background:var(--c2,#4a6fa5)"></i></div></div></div><div class="jc-nums"><span>${money(F.RR.scheduled)}/mo rent</span><span>NOI ${money(F.noiA)}/yr</span><span>DSCR ${F.dscr??'—'}</span><span>cap ${F.capRate??'—'}% on basis</span></div><div class="jc-flags">${flags.join('')||'<i class="ok">stable</i>'}</div></div>`; }).join('')||'<div class="muted">No owned properties yet. Mark a property as owned from its record.</div>'}</div>
    <p class="small muted" style="margin-top:10px">NOI = rent in place − operating expenses (management as % of rent). DSCR = NOI ÷ debt service. Cap rate on basis = annual NOI ÷ (purchase basis + capital improvements billed by SmartDesign). Equity = value (stated, or NOI capitalized at the target cap rate) − loan balance.</p>`;
  document.querySelectorAll('[data-own]').forEach(el => el.onclick = () => ownOpen(el.dataset.own)); }
function renderMBOwnP(){ const p = DB.properties.find(x=>x.id===mbOwnId) || ownedProps()[0]; if (!p){ $('#mb-ownp').innerHTML = '<div class="card muted">No property.</div>'; return; } mbOwnId = p.id; const O = p.owned; const F = propertyFin(p); const ed = mbCanEdit(); const M = v => v!=null ? money(v) : '—';
  const tabs = [['overview','Overview'],['rent','Rent roll'],['loan','Loan & HTC'],['fin','Financials'],['capex','Capex']];
  const head = `<div class="row" style="align-items:flex-start;gap:12px;margin-bottom:10px"><div><a href="#" id="own-back" class="small">‹ Portfolio</a><h2 style="margin:4px 0 0">${esc(p.address)}</h2><div class="small muted">${esc(propEntity(p)?.name||'')} · acquired ${fmt(O.acquired)} · ${F.RR.units.length} units · <a href="#" id="own-prop-rec">property record</a></div></div><span class="grow"></span>${ed?`<button class="btn" id="own-edit">Edit property</button>`:''}</div>
    <div class="fin rep-kpis"><div class="kpi"><b>${money(F.RR.scheduled)}</b><span>rent in place / mo · ${Math.round(F.RR.occ*100)}% occupied${F.vacancyM?` · ${money(F.vacancyM)} vacancy loss`:''}</span></div><div class="kpi"><b>${money(F.noiM)}</b><span>NOI / mo · ${money(F.noiA)} / yr</span></div><div class="kpi ${F.dscr!=null&&F.dscr<1.2?'warn':''}"><b>${F.dscr??'—'}×</b><span>DSCR · debt service ${money(F.dsM)}/mo</span></div><div class="kpi ${F.cfM<0?'warn':'good'}"><b>${money(F.cfM)}</b><span>cash flow / mo after debt</span></div><div class="kpi"><b>${money(F.value - F.Lc.balance)}</b><span>equity · value ${money(F.value)} · LTV ${F.ltv??'—'}%</span></div></div>
    <div class="ctabs">${tabs.map(([k,l]) => `<button class="${ownTab===k?'on':''}" data-owntab="${k}">${l}</button>`).join('')}</div>`;
  let body = '';
  if (ownTab==='overview') body = `<div class="grid2"><div class="card"><h3>Needs attention</h3><div class="rem">${[...F.RR.vacant.map(x=>`<div class="rem-row warn"><b>·</b><span>${esc(x.u.name)} vacant — market ${money(x.market)}/mo</span></div>`), ...F.delinquent.map(x=>`<div class="rem-row bad"><b>${money(x.rent)}</b><span>${esc(x.u.name)} · ${esc(x.L.tenant)} — rent not received this month</span></div>`), ...F.RR.units.filter(x=>x.daysToEnd!=null&&x.daysToEnd<=90).map(x=>`<div class="rem-row warn"><b>${x.daysToEnd} d</b><span>${esc(x.u.name)} lease ends ${fmt(x.L.end)} — renew or list</span></div>`), F.dscr!=null&&F.dscr<1.2?`<div class="rem-row bad"><b>${F.dscr}</b><span>DSCR under lender covenant 1.20</span></div>`:'', F.loanDays!=null&&F.loanDays<365?`<div class="rem-row warn"><b>${Math.round(F.loanDays/30)} mo</b><span>loan matures ${fmt(F.Lc.maturity)} — start refinance</span></div>`:'', F.htcDays!=null&&F.htcDays<365?`<div class="rem-row warn"><b>${Math.round(F.htcDays/30)} mo</b><span>HTC recapture period ends ${fmt(F.htc.complianceEnd)} — no sale or disqualifying change before then</span></div>`:''].filter(Boolean).join('')||'<div class="muted small">Nothing outstanding.</div>'}</div></div>
    <div class="card"><h3>Monthly picture</h3>${[['Rent in place', F.RR.scheduled], ['Vacancy loss', -F.vacancyM], ['Operating expenses', -F.opexM], ['Net operating income', F.noiM, true], ['Debt service', -F.dsM], ['Cash flow', F.cfM, true]].map(([l,v,b]) => `<div class="chg" ${b?'style="font-weight:600"':''}><span>${l}</span>${money(v)}</div>`).join('')}<div class="small muted" style="margin-top:8px">Cap rate on basis ${F.capRate??'—'}% · basis ${money(F.basis)} (purchase ${money(O.basis)} + capex ${money(F.capexCost)})</div></div></div>`;
  if (ownTab==='rent'){ const m = today().slice(0,7); body = `<div class="row" style="margin-bottom:8px;align-items:center"><span class="small muted">${monthLabel(m)}: ${money(F.collected)} received of ${money(F.due)} due</span><span class="grow"></span>${ed?`<button class="btn sm" id="own-unit-add">Add unit</button>`:''}</div><div class="tw"><table class="t rep-t"><thead><tr><th>Unit</th><th class="money">SF</th><th>Tenant</th><th>Lease</th><th class="money">Rent / mo</th><th class="money">Market</th><th class="money">Deposit</th><th>This month</th><th></th></tr></thead><tbody>${F.RR.units.map(x => { const paid = (O.rentLedger||[]).find(r => r.unitId===x.u.id && r.month===m && r.paid); return `<tr><td><b>${esc(x.u.name)}</b><div class="small muted">${x.u.beds?x.u.beds+' bd':'commercial'}</div></td><td class="money">${x.u.sf||'—'}</td><td>${x.active?esc(x.L.tenant):'<span class="pill warn">vacant</span>'}</td><td class="small">${x.active?`${fmt(x.L.start)} – ${fmt(x.L.end)}${x.daysToEnd!=null&&x.daysToEnd<=90?` <span class="pill warn">${x.daysToEnd} d</span>`:''}`:'—'}</td><td class="money">${x.active?money(x.rent):'—'}</td><td class="money dim">${money(x.market)}</td><td class="money dim">${x.active?money(+x.L.deposit||0):'—'}</td><td>${x.active?(paid?`<span class="pill ok">paid ${fmt(paid.date)}</span>`:`<span class="pill bad">not received</span>`):''}</td><td>${ed?(x.active?(paid?'':`<button class="btn sm" data-rent="${x.u.id}">Record rent</button>`)+` <button class="btn sm" data-lease="${x.u.id}">Lease</button>`:`<button class="btn sm primary" data-lease="${x.u.id}">New lease</button>`):''}</td></tr>`; }).join('')}</tbody><tfoot><tr style="font-weight:600"><td>Total</td><td></td><td></td><td></td><td class="money">${money(F.RR.scheduled)}</td><td class="money">${money(F.RR.potential)}</td><td></td><td></td><td></td></tr></tfoot></table></div>
    <h3 class="rep-h">Rent ledger</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Month</th><th>Unit</th><th class="money">Amount</th><th>Received</th></tr></thead><tbody>${(O.rentLedger||[]).slice().sort((a,b)=>b.month.localeCompare(a.month)).slice(0,24).map(r => `<tr><td>${monthLabel(r.month)}</td><td>${esc(O.units.find(u=>u.id===r.unitId)?.name||r.unitId)}</td><td class="money">${money(r.amount)}</td><td class="small">${r.paid?fmt(r.date):'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No rent recorded yet.</td></tr>'}</tbody></table></div>`; }
  if (ownTab==='loan'){ const L = O.loan||{}; const Lc = F.Lc; body = `<div class="grid2"><div class="card"><h3>Loan</h3>${L.principal?`${[['Lender', L.lender], ['Original principal', money(L.principal)], ['Rate', L.rate+'%'], ['Term', (L.termMonths/12)+' years'+(L.ioMonths?` · ${L.ioMonths} mo interest-only`:'')], ['Start', fmt(L.start)], ['Maturity', fmt(Lc.maturity)], ['Monthly payment', money(Lc.payment)], ['Current balance', money(Lc.balance)], ['This month interest / principal', `${money(Lc.interestM)} / ${money(Lc.principalM)}`], ['Months left', Lc.monthsLeft], ['DSCR', (F.dscr??'—')+'×'], ['LTV', (F.ltv??'—')+'%']].map(([l,v]) => `<div class="chg"><span>${l}</span>${v}</div>`).join('')}`:'<div class="muted small">No loan on this property.</div>'}${ed?`<button class="btn sm" id="own-loan" style="margin-top:8px">${L.principal?'Edit loan':'Add loan'}</button>`:''}</div>
    <div class="card"><h3>Historic Tax Credit</h3>${O.htc?`${[['Placed in service', fmt(O.htc.placedInService)], ['Qualified rehabilitation expenditures', money(O.htc.qre)], ['Credit', money(O.htc.credit)+(O.htc.qre?` (${Math.round(O.htc.credit/O.htc.qre*100)}%)`:'')], ['Compliance / recapture period ends', fmt(O.htc.complianceEnd)+(F.htcDays!=null?` · ${Math.max(0,Math.round(F.htcDays/30))} months left`:'')]].map(([l,v]) => `<div class="chg"><span>${l}</span>${v}</div>`).join('')}<p class="small muted" style="margin-top:8px">During the five-year recapture period a sale, a change of use, or a disqualifying alteration claws back 20% of the credit per year remaining. Capex on this property should be reviewed against the Secretary of the Interior's Standards before it starts.</p>`:'<div class="muted small">No HTC on this property.</div>'}${ed?`<button class="btn sm" id="own-htc" style="margin-top:8px">${O.htc?'Edit':'Add HTC'}</button>`:''}</div></div>`; }
  if (ownTab==='fin'){ const months = monthKeys(6); const rows = months.map(m => { const R = [m+'-01', m+'-31']; const coll = rentCollected(p, m); const due = m <= today().slice(0,7) ? rentDue(p, m) : 0; return {m, due, coll, opex:F.opexM, int:F.Lc.interestM, prin:F.Lc.principalM, noi:r2(coll - F.opexM), cf:r2(coll - F.opexM - F.Lc.payment)}; }); const T = rows.reduce((a,r) => { Object.keys(r).forEach(k => { if (k!=='m') a[k]=(a[k]||0)+r[k]; }); return a; }, {});
    body = `<div class="tw"><table class="t rep-t"><thead><tr><th></th>${months.map(m=>`<th class="money">${monthLabel(m)}</th>`).join('')}<th class="money">Total</th></tr></thead><tbody>${[['Rent due','due'],['Rent collected','coll'],['Operating expenses','opex'],['NOI (cash)','noi',true],['Interest','int'],['Principal','prin'],['Cash flow after debt','cf',true]].map(([l,k,b]) => `<tr ${b?'style="font-weight:600"':''}><td>${l}</td>${rows.map(r=>`<td class="money ${(k==='cf'&&r.cf<0)?'bad':''}">${money(r[k])}</td>`).join('')}<td class="money">${money(T[k])}</td></tr>`).join('')}</tbody></table></div>
    <h3 class="rep-h">Operating expenses (monthly)</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Category</th><th class="money">Per month</th><th class="money">Per year</th><th class="money">% of rent</th></tr></thead><tbody>${(O.opex||[]).map(o => { const v = o.pct ? F.RR.scheduled*o.pct/100 : +o.monthly||0; return `<tr><td>${esc(o.cat)}${o.pct?` <span class="small muted">(${o.pct}% of rent)</span>`:''}</td><td class="money">${money(v)}</td><td class="money">${money(v*12)}</td><td class="money">${F.RR.scheduled?Math.round(v/F.RR.scheduled*100):0}%</td></tr>`; }).join('')}<tr style="font-weight:600"><td>Total</td><td class="money">${money(F.opexM)}</td><td class="money">${money(F.opexM*12)}</td><td class="money">${F.RR.scheduled?Math.round(F.opexM/F.RR.scheduled*100):0}%</td></tr></tbody></table></div>${ed?`<button class="btn sm" id="own-opex" style="margin-top:8px">Edit expenses</button>`:''}
    <p class="small muted" style="margin-top:8px">This property is its own entity (${esc(propEntity(p)?.name||'')}) on the financial statements: rent collected is its income, operating expenses and mortgage interest its overhead; principal is a balance-sheet payment. Capital improvements done by SmartDesign are billed intercompany and added to basis, not expensed.</p>`; }
  if (ownTab==='capex') body = `<div class="row" style="margin-bottom:8px;align-items:center"><span class="small muted">Capital work is run as a SmartDesign job for ${esc(propEntity(p)?.name||'the LLC')} — estimated, scheduled, purchased and billed like any client job, and it adds to the property's basis.</span><span class="grow"></span>${ed?`<button class="btn sm primary" id="own-capex">New capex job</button>`:''}</div><div class="tw"><table class="t rep-t"><thead><tr><th>Job</th><th class="money">Contract</th><th class="money">Cost to date</th><th class="money">% complete</th><th class="money">Billed to LLC</th><th>Finish</th><th></th></tr></thead><tbody>${F.capex.map(x => { const J = jobFin(x); const h = projectHealth(x); return `<tr><td><b>${esc(x.project.name)}</b></td><td class="money">${M(J.contract)}</td><td class="money">${M(J.actual)}</td><td class="money">${Math.round(J.pct*100)}%</td><td class="money">${M(J.billed)}</td><td class="small">${h.sc?fmt(h.sc):'—'}</td><td><button class="btn sm" data-capexgo="${x.id}">Open job</button></td></tr>`; }).join('')||'<tr><td colspan="7" class="muted">No capex jobs yet.</td></tr>'}</tbody></table></div>`;
  $('#mb-ownp').innerHTML = head + body;
  $('#own-back').onclick = e => { e.preventDefault(); view = 'mbown'; render(); }; $('#own-prop-rec').onclick = e => { e.preventDefault(); mbOpenProp(p.id); };
  document.querySelectorAll('[data-owntab]').forEach(b => b.onclick = () => { ownTab = b.dataset.owntab; render(); });
  document.querySelectorAll('[data-rent]').forEach(b => b.onclick = () => { const u = O.units.find(x=>x.id===b.dataset.rent); const m = today().slice(0,7); (O.rentLedger = O.rentLedger||[]).push({id:uid('rl'), unitId:u.id, month:m, amount:+u.lease.rent, paid:true, date:today()}); audit('property', p.id, 'rent', '', String(u.lease.rent), `${p.address} ${u.name} rent ${monthLabel(m)}`); save(); render(); toast(`${money(u.lease.rent)} recorded for ${u.name}`); });
  document.querySelectorAll('[data-lease]').forEach(b => b.onclick = () => { const u = O.units.find(x=>x.id===b.dataset.lease); const L = u.lease||{tenant:'', start:today(), end:iso(addDays(today(), 365)), rent:u.market||0, deposit:u.market||0, status:'active'}; mbModal(`${u.lease?'Lease':'New lease'} — ${esc(u.name)}`, `<label class="f"><span>Tenant</span><input data-lf="tenant" value="${esc(L.tenant)}"></label><div class="f2"><label class="f"><span>Start</span><input type="date" data-lf="start" value="${L.start}"></label><label class="f"><span>End</span><input type="date" data-lf="end" value="${L.end}"></label></div><div class="f2"><label class="f"><span>Rent / mo</span><input type="number" data-lf="rent" value="${L.rent}"></label><label class="f"><span>Deposit</span><input type="number" data-lf="deposit" value="${L.deposit}"></label></div>${u.lease?`<label class="small"><input type="checkbox" id="lf-end"> Mark lease ended (unit becomes vacant)</label>`:''}`, {submit:'Save', onSubmit:()=>{ const o = {}; document.querySelectorAll('[data-lf]').forEach(i => o[i.dataset.lf] = i.type==='number' ? +i.value : i.value); if ($('#lf-end')?.checked){ u.lease = null; } else u.lease = Object.assign({status:'active'}, o); audit('property', p.id, 'lease', '', u.lease?u.lease.tenant:'ended', `${p.address} ${u.name}`); save(); render(); }}); });
  $('#own-unit-add')?.addEventListener('click', () => { const name = prompt('Unit name'); if (!name) return; O.units.push({id:uid('u'), name, sf:0, beds:0, market:0, lease:null}); save(); render(); });
  $('#own-loan')?.addEventListener('click', () => { const L = O.loan||{lender:'', principal:0, rate:6.5, termMonths:360, ioMonths:0, start:today()}; mbModal('Loan', `<label class="f"><span>Lender</span><input data-ln="lender" value="${esc(L.lender||'')}"></label><div class="f2"><label class="f"><span>Principal</span><input type="number" data-ln="principal" value="${L.principal}"></label><label class="f"><span>Rate %</span><input type="number" step="0.01" data-ln="rate" value="${L.rate}"></label></div><div class="f2"><label class="f"><span>Term (months)</span><input type="number" data-ln="termMonths" value="${L.termMonths}"></label><label class="f"><span>Interest-only months</span><input type="number" data-ln="ioMonths" value="${L.ioMonths||0}"></label></div><label class="f"><span>First payment</span><input type="date" data-ln="start" value="${L.start}"></label>`, {submit:'Save', onSubmit:()=>{ const o = {}; document.querySelectorAll('[data-ln]').forEach(i => o[i.dataset.ln] = i.type==='number' ? +i.value : i.value); O.loan = o; save(); render(); }}); });
  $('#own-htc')?.addEventListener('click', () => { const H = O.htc||{placedInService:today(), complianceEnd:iso(addDays(today(), 365*5)), qre:0, credit:0}; mbModal('Historic Tax Credit', `<div class="f2"><label class="f"><span>Placed in service</span><input type="date" data-ht="placedInService" value="${H.placedInService}"></label><label class="f"><span>Compliance period ends</span><input type="date" data-ht="complianceEnd" value="${H.complianceEnd}"></label></div><div class="f2"><label class="f"><span>QRE</span><input type="number" data-ht="qre" value="${H.qre}"></label><label class="f"><span>Credit</span><input type="number" data-ht="credit" value="${H.credit}"></label></div>`, {submit:'Save', onSubmit:()=>{ const o = {}; document.querySelectorAll('[data-ht]').forEach(i => o[i.dataset.ht] = i.type==='number' ? +i.value : i.value); O.htc = o; save(); render(); }}); });
  $('#own-opex')?.addEventListener('click', () => { const txt = prompt('Expenses as category:monthly (or category:pct%), one per line', (O.opex||[]).map(o => `${o.cat}:${o.pct?o.pct+'%':o.monthly}`).join('\n')); if (txt===null) return; O.opex = txt.split('\n').map(s => { const i = s.lastIndexOf(':'); if (i<0) return null; const cat = s.slice(0,i).trim(), v = s.slice(i+1).trim(); return v.endsWith('%') ? {cat, pct:+v.slice(0,-1)} : {cat, monthly:+v||0}; }).filter(Boolean); save(); render(); });
  $('#own-edit')?.addEventListener('click', () => { mbModal('Property', `<div class="f2"><label class="f"><span>Acquired</span><input type="date" data-pe="acquired" value="${O.acquired||''}"></label><label class="f"><span>Purchase basis</span><input type="number" data-pe="basis" value="${O.basis||0}"></label></div><div class="f2"><label class="f"><span>Value (blank = NOI ÷ cap rate)</span><input type="number" data-pe="value" value="${O.value||''}"></label><label class="f"><span>Target cap rate %</span><input type="number" step="0.1" data-pe="capRate" value="${O.capRate||''}"></label></div>`, {submit:'Save', onSubmit:()=>{ document.querySelectorAll('[data-pe]').forEach(i => O[i.dataset.pe] = i.type==='number' ? +i.value : i.value); save(); render(); }}); });
  $('#own-capex')?.addEventListener('click', () => { const name = prompt('Capex job name', `${p.address} — `); if (!name) return; let cl = DB.clients.find(c => c.entityId===propEntity(p)?.id); if (!cl){ cl = {id:uid('cl'), name:propEntity(p)?.name||p.address, company:propEntity(p)?.name||'', type:'Owned property (M&B)', contacts:[], propertyAddr:p.address, billingAddr:'', prefComm:'email', notes:'', estimates:[], changeOrders:[], invoices:[], sov:[], payments:[], docs:[], activity:[], contract:0, entityId:propEntity(p)?.id||''}; migrateClientDocs(cl); DB.clients.push(cl); } const pj = projectFromTemplate(name, p.address, nextWork(today()), ''); pj.clientId = cl.id; pj.propertyId = p.id; DB.projects.push(pj); audit('property', p.id, 'capex', '', pj.id, name); save(); render(); toast('Capex job created — estimate it under Clients & billing'); });
  document.querySelectorAll('[data-capexgo]').forEach(b => b.onclick = () => { setCurrent(b.dataset.capexgo); setWorkspace('sd'); view = 'costs'; render(); }); }
const renderMBBase = renderMB;
renderMB = function(){ renderMBBase(); if (!mbAccess()) return; if (view==='mbown') renderMBOwn(); if (view==='mbownp') renderMBOwnP(); };
/* mark a property as owned from its record */
const renderMBPropBase = renderMBProp;
renderMBProp = function(){ renderMBPropBase(); const p = DB.properties.find(x => x.id===mbPropId); const host = $('#mb-prop'); if (!p || !host || !mbCanEdit()) return; const bar = document.createElement('div'); bar.className = 'note'; bar.style.margin = '0 0 10px'; bar.innerHTML = p.owned ? `This property is owned (${esc(propEntity(p)?.name||'')}). <a href="#" id="own-go">Open the ownership page</a>` : `Acquired this one? <a href="#" id="own-mark">Mark as owned</a> to start the rent roll, loan and capex.`; host.prepend(bar); $('#own-go')?.addEventListener('click', e => { e.preventDefault(); ownOpen(p.id, 'overview'); }); $('#own-mark')?.addEventListener('click', e => { e.preventDefault(); const ent = prompt('Owning entity (LLC) name', `${p.address} LLC`); if (!ent) return; const id = uid('ent'); DB.entities.push({id, name:ent, ein:'', type:'property', propertyId:p.id}); p.owned = {entityId:id, acquired:today(), basis:0, value:0, capRate:5.5, units:[], loan:null, opex:[], htc:null, rentLedger:[]}; audit('property', p.id, 'owned', '', ent); save(); ownOpen(p.id, 'overview'); }); };
/* reminders that point at a property page */
document.addEventListener('click', e => { const el = e.target.closest('[data-remgo]'); if (!el) return; try { const go = JSON.parse(el.dataset.remgo); if (go.own){ mbOwnId = go.own; ownTab = 'overview'; } } catch(err){} }, true);

/* ===================== EVENTS — every dollar as one row with its dimensions (entity · job · cost code · property · unit · vendor · customer · period) ===================== */
/* Any report is a filter over this one table. Built on demand from the documents that already exist; nothing is entered twice. */
function eventRows(){ const out = []; const jobName = id => DB.projects.find(p=>p.id===id)?.project.name||''; const jobEnt = id => { const p = DB.projects.find(x=>x.id===id); return p ? entName(entityOfProject(p)) : ''; }; const propOf = id => { const p = DB.projects.find(x=>x.id===id); return p?.propertyId ? (DB.properties.find(x=>x.id===p.propertyId)?.address||'') : ''; };
  const push = (o) => out.push(Object.assign({period:(o.date||'').slice(0,7), entity:'', job:'', code:'', property:'', unit:'', vendor:'', customer:'', ref:'', memo:''}, o));
  DB.clients.forEach(c => { c.invoices.filter(i => !['void','draft'].includes(i.status)).forEach(i => { i.lines.forEach(l => push({date:i.date, kind: i.retainerOf ? 'Retainer' : l.retainerLine ? 'Retainer applied' : 'Invoice line', side:'Revenue', entity:jobEnt(i.projectId)||entName('ent1'), job:jobName(i.projectId), code:(i.mode==='sov' ? (c.sov.find(v=>v.id===l.sovId)?.lineRef && findLine(c.sov.find(v=>v.id===l.sovId).lineRef)?.line.code) : (l.fromLine && findLine(l.fromLine)?.line.code)) || '', property:propOf(i.projectId), customer:c.name, ref:i.number, memo:l.item||l.desc||'', amount:lineAmount(l, i)})); const t = docTotal(i); if (t.ret) push({date:i.date, kind:'Retainage withheld', side:'Revenue', entity:jobEnt(i.projectId), job:jobName(i.projectId), customer:c.name, ref:i.number, amount:-t.ret}); });
    c.payments.forEach(py => { const inv = c.invoices.find(i=>i.id===py.invoiceId); push({date:py.date, kind: py.unapplied ? 'Credit on account' : 'Payment', side:'Cash in', entity:jobEnt(inv?.projectId)||entName('ent1'), job:jobName(inv?.projectId), property:propOf(inv?.projectId), customer:c.name, ref:inv?.number||'', memo:py.ref||py.method||'', amount:+py.amount||0}); }); });
  DB.bills.filter(b => BILL_COSTED.includes(b.status)).forEach(b => (b.lines||[]).forEach(l => push({date:b.date, kind: b.ic ? 'Intercompany bill' : 'Bill line', side:'Cost', entity:entName(b.entityId||'ent1'), job:jobName(b.projectId), code:b.code||'', property:propOf(b.projectId), vendor:b.vendor, ref:b.number, memo:l.desc||'', amount:+l.amount||0})));
  DB.txns.filter(t => t.amt<0 && !txnViaBill(t, DB.bills)).forEach(t => push({date:t.date, kind:'Bank', side: isJobCat(t.cat) ? 'Cost' : 'Overhead', entity:entName((typeof entityOfTxn==='function' ? entityOfTxn(t) : null)||'ent1'), job:jobName(t.projectId), code:t.code||'', property:propOf(t.projectId), vendor:t.vendor||'', ref:t.desc||'', memo:cfoCatName(t.cat), amount:-t.amt}));
  DB.time.filter(e => e.status!=='rejected' && !e.icBillId).forEach(e => { const emp = DB.employees.find(x=>x.id===e.empId); push({date:e.date, kind:'Labor (clocked)', side:'Cost', entity:entName(emp?.entityId||'ent1'), job:jobName(e.projectId), code:e.code||'', property:propOf(e.projectId), vendor:emp?.name||e.empId, ref:hoursOf(e)+' h', memo:e.notes||'', amount:r2(hoursOf(e)*laborRate(emp))}); });
  DB.payroll.filter(r => ['paid','verified'].includes(r.status)).forEach(r => push({date:r.payDate, kind:'Payroll', side:'Cost', entity:entName(r.entityId||'ent1'), ref:r.period, memo:`${r.employees} employees`, amount:+r.total||0}));
  (typeof ownedProps==='function' ? ownedProps() : []).forEach(p => { const en = propEntity(p)?.name||''; (p.owned.rentLedger||[]).filter(r=>r.paid).forEach(r => push({date:r.date||r.month+'-01', kind:'Rent', side:'Revenue', entity:en, property:p.address, unit:p.owned.units.find(u=>u.id===r.unitId)?.name||'', customer:p.owned.units.find(u=>u.id===r.unitId)?.lease?.tenant||'', ref:r.month, amount:+r.amount||0})); });
  return out.sort((a,b) => (b.date||'').localeCompare(a.date||'')); }
REP_DS.events = {n:'Every dollar (events)', rows:eventRows, dims:['kind','side','entity','job','code','property','unit','vendor','customer','period'], sums:['amount']};

/* ===================== WORK DRIVES MONEY — billing suggested by the work, and a cost library built from your own history ===================== */
/* Billing suggestions: construction jobs whose work is ahead of billing get a progress invoice pre-filled from cost-to-cost % per SOV line; design jobs with banked hours or a reached milestone; finish-material lines whose PO has been received and still have a balance to bill. Each suggestion is one click to a draft invoice — a person still reviews and sends it. */
function lineCompletePct(c, v){ if (!v.lineRef) return null; const f = lineFin(v.lineRef); if (!f) return null; const budget = f.budget||0; if (!budget) return null; return Math.min(100, Math.round(f.actual/budget*100)); }
function progressPrefill(c, inv, pctJob){ inv.lines.forEach(l => { const v = c.sov.find(x=>x.id===l.sovId); const done = v ? lineCompletePct(c, v) : null; const target = done!=null ? done : Math.round(pctJob*100); l.pct = Math.max(0, r2(target - (+l.prevPct||0))); l.suggested = true; }); inv.title = `Progress billing — work through ${fmtL(today())}`; inv.memo = (inv.memo?inv.memo+'\n':'') + 'Percentages pre-filled from cost to date against each line\'s budget. Adjust before sending.'; }
const ctProgressInvoiceBase = ctProgressInvoice;
ctProgressInvoice = function(c, d){ const inv = ctProgressInvoiceBase(c, d); const p = DB.projects.find(x=>x.id===(d.projectId||inv.projectId)); if (p) progressPrefill(c, inv, jobFin(p).pct); return inv; };
function billingSuggestions(){ const out = []; const t = today();
  DB.clients.forEach(c => { c.estimates.filter(e => e.status==='converted').forEach(d => { const p = DB.projects.find(x=>x.id===d.projectId); if (!p) return; const J = jobFin(p); const openDraft = c.invoices.some(i => i.status==='draft' && (i.mode==='sov' || i.fromDoc===d.id)); if (openDraft) return;
      if (d.template==='construction' || !d.template){ const compPct = Math.round(J.pct*100); const billedPct = J.contract ? Math.round(J.billed/J.contract*100) : 0; const gap = compPct - billedPct; const amt = r2(J.contract*Math.max(0,gap)/100); if (gap >= 10 && amt >= 2500) out.push({kind:'progress', c, d, p, amount:amt, title:`${p.project.name}: ${compPct}% complete, ${billedPct}% billed — draft the progress invoice (${money(amt)})`, act:'progress'}); }
      if (d.template==='design'){ const un = designHoursUnbilled(c, d); const h = r2(un.reduce((a,e)=>a+hoursOf(e),0)); if (d.billing==='hours' && h >= 8) out.push({kind:'dhours', c, d, p, amount:r2(un.reduce((a,e)=>a+hoursOf(e)*(laborBillRate(DB.employees.find(x=>x.id===e.empId))),0)), title:`${p.project.name}: ${h} design hours banked — bill them`, act:'dhours'});
        if (d.billing!=='hours'){ const ms = d.milestones||DESIGN_MILESTONES; const done = d.milestonesBilled||[]; const filed = p.permits.some(x => x.number || ['active','renewed'].includes(x.status)); const estH = d.lines.filter(l=>l.unit==='hr').reduce((a,l)=>a+(+l.qty||0),0); const hrs = DB.time.filter(e => e.projectId===p.id && e.status!=='rejected' && isDesignStaff(DB.employees.find(x=>x.id===e.empId))).reduce((a,e)=>a+hoursOf(e),0); const next = ms.findIndex((x,i)=>!done.includes(i)); const reached = next===0 || (next===1 && (filed || (estH && hrs/estH >= 0.5))) || (next===2 && estH && hrs/estH >= 0.95); if (next>=0 && reached) out.push({kind:'dmilestone', c, d, p, amount:r2(docNet(d)*ms[next].pct/100), title:`${p.project.name}: "${ms[next].label}" reached — bill ${ms[next].pct}% of the design fee (${money(docNet(d)*ms[next].pct/100)})`, act:'dmilestone'}); } }
      if (d.template==='materials'){ const lines = d.lines.filter(l => { const key = `estimate:${d.id}:${l.id}`; const f = lineFin(key); if (!f || f.billedPct >= 100) return false; return DB.pos.some(po => ['received','partial'].includes(po.status) && po.lines.some(pl => pl.line===key)); }); if (lines.length){ const amt = r2(lines.reduce((a,l)=>{ const f = lineFin(`estimate:${d.id}:${l.id}`); return a + lineAmount(l,d)*(100-f.billedPct)/100; },0)); out.push({kind:'materials', c, d, p, amount:amt, title:`${p.project.name}: ${lines.length} material line${lines.length>1?'s':''} received with a balance to bill (${money(amt)})`, act:'invoice'}); } } }); });
  return out.sort((a,b)=>b.amount-a.amount); }
const remindersBase3 = reminders;
reminders = function(){ const out = remindersBase3(); billingSuggestions().forEach(s => out.unshift({n:money(s.amount), label:s.title, go:{view:'clients', bill:{clientId:s.c.id, docId:s.d.id, act:s.act}}, sev:'bill'})); return out; };
document.addEventListener('click', e => { const el = e.target.closest('[data-remgo]'); if (!el) return; let go; try { go = JSON.parse(el.dataset.remgo); } catch(err){ return; } if (!go.bill) return; const {clientId, docId, act} = go.bill; setWorkspace('sd'); clientOpen = clientId; clientTab = 'fin'; finTab = 'estimates'; docOpen = {kind:'estimate', id:docId}; setTimeout(() => { const c = DB.clients.find(x=>x.id===clientId); const d = c && findDoc(c, 'estimate', docId); if (c && d) Promise.resolve(docAction(c, d, act)).then(() => { save(); render(); }); }, 80); }, true);
/* job cards: a Bill now button when the work is ahead of billing */
const ptJobsBase = ptJobs;
ptJobs = function(){ let h = ptJobsBase(); const S1 = billingSuggestions(); S1.forEach(s => { const marker = `data-jobgo="${s.p.id}"`; if (h.includes(marker)) h = h.replace(`<div class="jobcard" ${marker}>`, `<div class="jobcard" ${marker}><button class="btn sm primary jc-bill" data-billnow="${s.c.id}:${s.d.id}:${s.act}">Bill ${money(s.amount)}</button>`); }); return h; };
const renderHomeBase2 = renderHome;
renderHome = function(){ renderHomeBase2(); document.querySelectorAll('[data-billnow]').forEach(b => b.onclick = e => { e.stopPropagation(); const [clientId, docId, act] = b.dataset.billnow.split(':'); clientOpen = clientId; clientTab = 'fin'; finTab = 'estimates'; docOpen = {kind:'estimate', id:docId}; view = 'clients'; render(); setTimeout(() => { const c = DB.clients.find(x=>x.id===clientId); const d = c && findDoc(c, 'estimate', docId); if (c && d) Promise.resolve(docAction(c, d, act)).then(() => { save(); render(); }); }, 80); }); };
/* schedule → materials → PO: mark a PO received from the phone, materials on the schedule follow */
/* (PO receiving lives in Purchasing; here we only make sure a received PO on a material line can trigger the balance invoice above.) */

/* ===================== COST LIBRARY — what things really cost, from your own estimates, POs and bills ===================== */
const normItem = s => (s||'').toLowerCase().replace(/\(.*?\)/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
function costLibrary(){ const lib = {}; const get = name => { const k = normItem(name); if (!k) return null; return lib[k] = lib[k]||{key:k, name:name.trim(), est:[], pos:[], bills:[], actual:[]}; };
  DB.clients.forEach(c => [...c.estimates, ...c.changeOrders].forEach(d => { if (['rejected','expired'].includes(d.status)) return; if (d.template==='construction') ctNumber(d); d.lines.forEach(l => { const o = get(l.item); if (!o) return; const qty = +l.qty||1; o.est.push({date:d.date, job:DB.projects.find(p=>p.id===d.projectId)?.project.name||c.name, doc:d.number, qty, unit:l.unit||'ls', price:r2(lineAmount(l,d)/qty), cost:l.cost?r2((+l.cost)/qty):null, vendor:l.vendor||'', status:d.status}); if (['approved','converted','billed'].includes(d.status) && l.cost){ const f = lineFin(ctKey(d,l)); if (f && f.actual) o.actual.push({date:d.date, job:DB.projects.find(p=>p.id===d.projectId)?.project.name||c.name, budget:+l.cost, actual:f.actual, done:f.billedPct>=100 || DB.projects.find(p=>p.id===d.projectId)?.project.status==='complete'}); } (l.items||[]).forEach(it => { const oi = get(it.name||it.item); if (oi && (it.price||it.cost)) oi.est.push({date:d.date, job:'', doc:d.number, qty:+it.qty||1, unit:it.unit||'ea', price:+it.price||+it.cost||0, cost:+it.cost||null, vendor:it.vendor||l.vendor||'', status:d.status}); }); }); }));
  DB.pos.filter(po => !['cancelled','draft'].includes(po.status)).forEach(po => po.lines.forEach(l => { const o = get(l.item||(l.line && findLine(l.line)?.line.item)||l.desc||''); if (!o) return; o.pos.push({date:po.date||po.created||'', vendor:po.vendor, qty:+l.qty||1, unit:l.unit||'ea', price:+l.price||0, po:po.number||po.id, status:po.status}); }));
  DB.bills.filter(b => BILL_COSTED.includes(b.status) && !b.ic).forEach(b => (b.lines||[]).forEach(l => { const o = get(l.desc||''); if (!o) return; o.bills.push({date:b.date, vendor:b.vendor, amount:+l.amount||0, bill:b.number}); }));
  Object.values(lib).forEach(o => { const est = o.est.filter(x=>x.price>0); o.n = est.length; o.avgPrice = est.length ? r2(est.reduce((a,x)=>a+x.price,0)/est.length) : 0; const costs = est.filter(x=>x.cost); o.avgCost = costs.length ? r2(costs.reduce((a,x)=>a+x.cost,0)/costs.length) : 0; o.lastPO = o.pos.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]||null; o.byVendor = {}; o.pos.forEach(x => { const v = o.byVendor[x.vendor] = o.byVendor[x.vendor]||{vendor:x.vendor, n:0, last:null, prices:[]}; v.n++; v.prices.push(x.price); if (!v.last || (x.date||'') > (v.last.date||'')) v.last = x; }); const act = o.actual; o.actualVsEst = act.length ? r2((act.reduce((a,x)=>a+x.actual,0) / act.reduce((a,x)=>a+x.budget,0) - 1)*100) : null; o.unit = est[0]?.unit || o.lastPO?.unit || ''; });
  return Object.values(lib).filter(o => o.n || o.pos.length).sort((a,b) => b.n - a.n || a.name.localeCompare(b.name)); }
function libLookup(name){ const k = normItem(name); if (!k || k.length < 3) return []; const L = costLibrary(); return L.filter(o => o.key===k || o.key.includes(k) || k.includes(o.key)).slice(0, 5); }
function libHint(o){ const parts = []; if (o.n) parts.push(`estimated ${o.n}× · avg ${money(o.avgPrice)}/${o.unit||'ea'}${o.avgCost?` · cost ${money(o.avgCost)}`:''}`); if (o.lastPO) parts.push(`last PO ${money(o.lastPO.price)}/${o.lastPO.unit} from ${esc(o.lastPO.vendor)} ${o.lastPO.date?fmt(o.lastPO.date):''}`); if (o.actualVsEst!=null) parts.push(`<b class="${o.actualVsEst>5?'bad':o.actualVsEst<-5?'ok':''}">actual ${o.actualVsEst>=0?'+':''}${o.actualVsEst}% vs estimate</b>`); return parts.join(' · '); }
let libPop = null;
function libShow(input){ const val = input.value; const hits = libLookup(val); libHide(); if (!hits.length) return; const pop = document.createElement('div'); pop.className = 'lib-pop'; pop.innerHTML = `<div class="lib-h">From your history</div>${hits.map((o,i) => `<div class="lib-row" data-libi="${i}"><b>${esc(o.name)}</b><span>${libHint(o)}</span></div>`).join('')}`; document.body.appendChild(pop); const r = input.getBoundingClientRect(); pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - 380)) + 'px'; pop.style.top = (r.bottom + window.scrollY + 4) + 'px'; libPop = pop;
  pop.querySelectorAll('[data-libi]').forEach(row => row.onmousedown = e => { e.preventDefault(); const o = hits[+row.dataset.libi]; libApply(input, o); libHide(); }); }
function libHide(){ if (libPop){ libPop.remove(); libPop = null; } }
function libApply(input, o){ const row = input.closest('tr, .ctm-line, .cs-line, .ctm-sheet, form') || input.parentElement; const price = o.avgPrice || o.lastPO?.price || 0; const cost = o.avgCost || o.lastPO?.price || 0; const vend = o.lastPO?.vendor || Object.values(o.byVendor)[0]?.vendor || o.est.find(x=>x.vendor)?.vendor || ''; const plan = [['[data-ctf="unit"],[data-f="unit"],[data-csf="unit"]', o.unit, true], ['[data-ctf="rate"],[data-f="rate"],[data-csf="rate"]', price, false], ['[data-ctf="cost"],[data-f="cost"],[data-csf="cost"]', cost, false], ['[data-ctf="vendor"],[data-f="vendor"],[data-csf="vendor"]', vend, true]]; const els = []; plan.forEach(([sel, v, txt]) => { const el = row && row.querySelector(sel); if (!el || !v) return; if (txt ? el.value : +el.value) return; el.value = v; els.push(el); }); input.value = o.name; els.push(input); els.forEach(el => { el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); }); toast(`Filled from history: ${money(price)}${o.unit?'/'+o.unit:''}`); }
document.addEventListener('input', e => { const t = e.target; if (t.matches && t.matches('[data-ctf="item"],[data-f="item"],[data-csf="item"]') && !t.readOnly) libShow(t); });
document.addEventListener('focusin', e => { const t = e.target; if (t.matches && t.matches('[data-ctf="item"],[data-f="item"],[data-csf="item"]') && !t.readOnly && t.value.length>=3) libShow(t); });
document.addEventListener('focusout', e => { if (e.target.matches && e.target.matches('[data-ctf="item"],[data-f="item"],[data-csf="item"]')) setTimeout(libHide, 150); });
/* report */
function repLibrary(){ const L = costLibrary(); const q = (repDef.q||'').toLowerCase(); const rows = L.filter(o => !q || o.key.includes(q)); const off = rows.filter(o => o.actualVsEst!=null && Math.abs(o.actualVsEst) > 10);
  return `<div class="rep-head"><div><h2 style="margin:0">Cost library</h2><div class="small muted">${L.length} items learned from ${DB.clients.reduce((a,c)=>a+c.estimates.length+c.changeOrders.length,0)} estimates, ${DB.pos.length} purchase orders and ${DB.bills.length} bills. Type an item name on any estimate line and the history appears.</div></div></div>
    <div class="fin rep-kpis"><div class="kpi"><b>${L.length}</b><span>items with history</span></div><div class="kpi"><b>${L.filter(o=>o.pos.length).length}</b><span>with real vendor prices</span></div><div class="kpi ${off.length?'warn':''}"><b>${off.length}</b><span>items where actual cost differs from estimate by more than 10%</span></div></div>
    <div class="row no-print" style="margin:8px 0"><input id="lib-q" placeholder="Filter items…" value="${esc(repDef.q||'')}" style="max-width:280px"></div>
    <div class="tw"><table class="t rep-t"><thead><tr><th>Item</th><th class="money">Times estimated</th><th class="money">Avg price</th><th class="money">Avg cost</th><th class="money">Margin</th><th>Last PO</th><th>Vendors</th><th class="money">Actual vs est.</th></tr></thead><tbody>${rows.slice(0,150).map(o => `<tr><td><b>${esc(o.name)}</b>${o.unit?` <span class="small muted">/ ${esc(o.unit)}</span>`:''}</td><td class="money">${o.n||'—'}</td><td class="money">${o.avgPrice?money(o.avgPrice):'—'}</td><td class="money">${o.avgCost?money(o.avgCost):'—'}</td><td class="money">${o.avgPrice&&o.avgCost?Math.round((1-o.avgCost/o.avgPrice)*100)+'%':'—'}</td><td class="small">${o.lastPO?`${money(o.lastPO.price)}/${esc(o.lastPO.unit)} · ${esc(o.lastPO.vendor)}${o.lastPO.date?' · '+fmt(o.lastPO.date):''}`:'—'}</td><td class="small">${Object.values(o.byVendor).map(v=>`${esc(v.vendor)} (${v.n})`).join(', ')||'—'}</td><td class="money ${o.actualVsEst!=null?(o.actualVsEst>10?'bad':o.actualVsEst<-10?'ok':''):''}">${o.actualVsEst!=null?(o.actualVsEst>=0?'+':'')+o.actualVsEst+'%':'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">Nothing yet.</td></tr>'}</tbody></table></div>
    <p class="small muted">Avg price and cost are per unit across your estimates and change orders; last PO is what you actually paid a vendor; actual vs estimate compares approved bills and bank items on the line to its budgeted cost on converted jobs. Items are matched by name, so keep names consistent.</p>`; }
REP_GROUPS.find(g=>g.id==='jobs').tabs.push(['library','Cost library']); REP_DEFS.library = 'What things really cost: your own estimate, PO and bill history per item.';
const renderReportsBase5 = renderReports;
renderReports = function(){ renderReportsBase5(); if (repTab!=='library') return; $('#rep-print-area').innerHTML = repLibrary(); const q = $('#lib-q'); if (q) q.oninput = () => { repDef.q = q.value; $('#rep-print-area').innerHTML = repLibrary(); const q2 = $('#lib-q'); q2.focus(); q2.setSelectionRange(q2.value.length, q2.value.length); q2.oninput = q.oninput; }; };
REP_DS.library = {n:'Cost library', rows:() => costLibrary().map(o => ({item:o.name, unit:o.unit, timesEstimated:o.n, avgPrice:o.avgPrice, avgCost:o.avgCost, lastVendor:o.lastPO?.vendor||'', lastPOPrice:o.lastPO?.price||0, actualVsEstPct:o.actualVsEst??0})), dims:['item','unit','lastVendor'], sums:['timesEstimated','avgPrice','avgCost','lastPOPrice']};

/* ===================== SUBCONTRACTOR COMPLIANCE + AP RETAINAGE + FIELD RECEIVING ===================== */
/* Compliance is checked where money moves: a bill cannot be approved for a sub whose insurance has lapsed, whose W-9 is missing, or whose last payment has no lien waiver on file — the Owner can override with a reason, and it is audited.
   Retainage on subs: a vendor can carry a retainage %, every bill from that vendor holds it back (bill total = lines − retainage) until a release bill is created.
   Receiving: deliveries are checked in from the phone, line by line; materials on the schedule follow; a PO fully received on a material line lets the balance invoice be suggested. */
const isSub = v => !!(v && (v.retainagePct>0 || /sub|plumb|electric|hvac|mason|roof|carpent|millwork|painter|flooring|demo|framing/i.test(v.trade||'')));
const subBill = b => b.cat==='subs' || +b.retainagePct>0;
const vendorOfBill = b => DB.vendors.find(x => x.name.toLowerCase()===(b.vendor||'').toLowerCase());
function waiverNeeded(b){ const v = vendorOfBill(b); if (!v || !isSub(v)) return null; if (!subBill(b)) return null; const prior = DB.bills.filter(x => x.id!==b.id && x.vendor.toLowerCase()===b.vendor.toLowerCase() && x.projectId===b.projectId && ['paid','verified'].includes(x.status) && subBill(x) && !x.retainageRelease && !x.ic); const missing = prior.filter(x => !x.waiver || x.waiver.type!=='unconditional'); return missing.length ? missing : null; }
function complianceIssues(b){ const v = vendorOfBill(b); const out = []; if (!v) return out; const td = today(); if (v.insuranceExp && parse(v.insuranceExp) < parse(td)) out.push({lvl:'block', m:`Insurance (COI) expired ${fmt(v.insuranceExp)}`}); else if (!v.insuranceExp && isSub(v)) out.push({lvl:'warn', m:'No certificate of insurance on file'}); if (!v.w9) out.push({lvl: billTotal(b) >= 600 ? 'block' : 'warn', m:'No W-9 on file (needed for 1099)'}); if (v.licenseExp && parse(v.licenseExp) < parse(td)) out.push({lvl:'block', m:`License expired ${fmt(v.licenseExp)}`}); const w = waiverNeeded(b); if (w) out.push({lvl:'block', m:`No unconditional lien waiver for prior payment${w.length>1?'s':''} ${w.map(x=>x.number).join(', ')}`}); return out; }
/* retainage on sub bills: total net of retainage */
const billTotalBase = billTotal;
billTotal = function(b){ const gross = billTotalBase(b); const pct = +b.retainagePct||0; return pct && !b.retainageRelease ? r2(gross*(1-pct/100)) : gross; };
const billGross = b => billTotalBase(b);
function apRetainage(vendorName, projectId){ const n = (vendorName||'').toLowerCase(); const held = DB.bills.filter(b => b.vendor.toLowerCase()===n && (!projectId || b.projectId===projectId) && !['void','rejected','draft'].includes(b.status) && +b.retainagePct && !b.retainageRelease).reduce((a,b)=>a + billGross(b)*(+b.retainagePct/100), 0); const released = DB.bills.filter(b => b.vendor.toLowerCase()===n && (!projectId || b.projectId===projectId) && !['void','rejected'].includes(b.status) && b.retainageRelease).reduce((a,b)=>a+billGross(b),0); return r2(held - released); }
function releaseRetainage(v, projectId){ const amt = apRetainage(v.name, projectId); if (amt<=0){ toast('No retainage held for this vendor'); return; } if (!confirm(`Create a bill releasing ${money(amt)} retainage to ${v.name}? It goes through normal approval.`)) return; const b = {id:uid('b'), number:`RET-${v.name.split(' ')[0].toUpperCase().slice(0,6)}-${today().replace(/-/g,'').slice(2)}`, vendor:v.name, date:today(), due:iso(addDays(today(), 30)), entityId:'ent1', projectId:projectId||'', cat:'subs', code:'', lines:[{id:uid('bl'), desc:'Release of retainage held', amount:amt}], payMethod:v.payMethod||'ACH', status:'submitted', retainageRelease:true, approvals:[{t:nowStamp(), by:S.project.userName||'', role:role(), action:'submitted (retainage release)'}], notes:'Retainage release — requires final unconditional lien waiver.'}; DB.bills.push(b); audit('bill', b.id, 'retainage-release', '', String(amt), `${v.name} ${money(amt)}`); save(); render(); toast(`${b.number} submitted for approval`); }
/* bill approval / payment gates */
const billActionBase = billAction;
billAction = function(b, a){ if (a==='approve'){ const iss = complianceIssues(b); const blocks = iss.filter(x=>x.lvl==='block'); if (blocks.length){ if (!isOwner()){ toast('Blocked: ' + blocks.map(x=>x.m).join(' · ')); return; } const why = prompt(`Compliance blocks on ${b.vendor}:\n\n${blocks.map(x=>'• '+x.m).join('\n')}\n\nOwner override — reason (leave blank to cancel):`); if (!why) return; b.approvals = b.approvals||[]; b.approvals.push({t:nowStamp(), ts:new Date().toISOString(), by:S.project.userName||role(), role:role(), action:'compliance override', note:why}); audit('bill', b.id, 'compliance-override', '', blocks.map(x=>x.m).join('; '), why); } }
  if (a==='paid'){ const v = vendorOfBill(b); if (v && isSub(v) && subBill(b) && !b.retainageRelease && !b.ic && !(b.waiver && b.waiver.type)){ const ok = confirm(`Record a conditional lien waiver from ${b.vendor} for this payment?\n\nOK = waiver received · Cancel = release without it (will be flagged until the unconditional waiver arrives)`); if (ok) b.waiver = {type:'conditional', received:today(), by:S.project.userName||''}; } }
  return billActionBase(b, a); };
/* receiving from the phone (crew / coordinator / PM) */
ROLE_VIEWS.crew.push('recv'); ROLE_VIEWS.coord.push('recv'); ROLE_VIEWS.pm.push('recv'); ROLE_VIEWS.owner.push('recv');
NAV_GROUPS.find(g=>g.id==='jobs').views.push('recv'); NAV_LABELS.recv = 'Deliveries';
function renderRecv(){ const root = $('#recv-body'); if (!root) return; const pos = DB.pos.filter(po => po.projectId===S.id && ['issued','partial'].includes(po.status)).sort((a,b)=>(a.expected||'').localeCompare(b.expected||''));
  root.innerHTML = `<div class="ph"><div><h2>Deliveries</h2><p class="lead">Check in what arrived, line by line. Materials on the schedule update themselves.</p></div></div>${pos.map(po => { const tot = po.lines.reduce((a,l)=>a+(+l.qty||0),0), got = po.lines.reduce((a,l)=>a+(+l.received||0),0); const late = po.expected && parse(po.expected) < parse(today()); return `<div class="card recv-po"><div class="row" style="align-items:baseline"><b>${esc(po.vendor)}</b><span class="small muted">${esc(po.number)} · expected ${po.expected?fmt(po.expected):'—'}${late?' <span class="pill bad">late</span>':''}</span><span class="grow"></span><span class="small">${got}/${tot} received</span></div>
    ${po.lines.map(l => { const left = Math.max(0, (+l.qty||0) - (+l.received||0)); return `<div class="recv-line ${left?'':'done'}"><div class="recv-item"><b>${esc(l.item||l.desc||'')}</b><span class="small muted">${l.qty} ${esc(l.unit||'')} ordered · ${l.received||0} received</span></div>${left?`<div class="recv-ctl"><input type="number" inputmode="decimal" min="0" max="${left}" step="any" value="${left}" data-rq="${po.id}:${l.id}"><button class="btn sm primary" data-rin="${po.id}:${l.id}">Received</button></div>`:'<span class="pill ok">complete</span>'}</div>`; }).join('')}
    <div class="row" style="margin-top:8px;gap:6px"><button class="btn sm" data-rall="${po.id}">Everything arrived</button><button class="btn sm" data-rissue="${po.id}">Report a problem</button></div></div>`; }).join('')||'<div class="card muted">Nothing on order for this job.</div>'}`;
  const receive = (po, l, qty, note) => { l.received = r2((+l.received||0) + qty); const m = l.materialId && mat(l.materialId); if (m && l.received >= l.qty - 0.001){ m.status = 'on-site'; m.onSiteDate = m.onSiteDate||today(); } const full = po.lines.every(x => (+x.received||0) >= (+x.qty||0) - 0.001); po.status = full ? 'received' : 'partial'; if (full) po.receivedOn = today(); (po.receipts = po.receipts||[]).push({t:nowStamp(), by:S.project.userName||role(), lineId:l.id, qty, note:note||''}); audit('po', po.id, 'received', '', `${l.item||l.desc}: ${qty}`, note||''); log(`${po.number}: received ${qty} ${l.unit||''} ${l.item||l.desc||''}${note?' — '+note:''}`); };
  root.querySelectorAll('[data-rin]').forEach(b => b.onclick = () => { const [pid, lid] = b.dataset.rin.split(':'); const po = DB.pos.find(x=>x.id===pid); const l = po.lines.find(x=>x.id===lid); const qty = +root.querySelector(`[data-rq="${pid}:${lid}"]`).value||0; if (qty<=0) return; receive(po, l, qty); save(); render(); toast(`${qty} ${l.unit||''} ${l.item||''} checked in`); });
  root.querySelectorAll('[data-rall]').forEach(b => b.onclick = () => { const po = DB.pos.find(x=>x.id===b.dataset.rall); po.lines.forEach(l => { const left = (+l.qty||0) - (+l.received||0); if (left>0) receive(po, l, left); }); save(); render(); toast(`${po.number} received in full`); });
  root.querySelectorAll('[data-rissue]').forEach(b => b.onclick = () => { const po = DB.pos.find(x=>x.id===b.dataset.rissue); const note = prompt('What is wrong with this delivery? (damaged, short, wrong item…)'); if (!note) return; (po.issues = po.issues||[]).push({t:nowStamp(), by:S.project.userName||role(), note}); po.flag = note; audit('po', po.id, 'delivery-issue', '', note); log(`${po.number}: delivery problem — ${note}`); save(); render(); toast('Reported to purchasing'); }); }
const renderBaseRecv = render;
render = function(){ renderBaseRecv(); if (view==='recv') renderRecv(); };
/* vendor record: compliance + retainage */
const openVendorBase = openVendor;
openVendor = function(id){ openVendorBase(id); const v = DB.vendors.find(x=>x.id===id) || {}; const body = $('#d-body'); if (!body) return; const held = id ? apRetainage(v.name) : 0; const div = document.createElement('div'); div.className = 'card'; div.style.margin = '0 0 10px'; div.innerHTML = `<h4>Subcontractor terms</h4><div class="f2"><div class="f"><label>Retainage held on bills %</label><input type="number" id="e-vret" min="0" max="20" step="1" value="${v.retainagePct||0}"></div><div class="f"><label>Lien waivers</label><div class="small" style="padding-top:8px">${id?`${DB.bills.filter(b=>b.vendor===v.name&&['paid','verified'].includes(b.status)&&!b.ic).length} payments · ${DB.bills.filter(b=>b.vendor===v.name&&['paid','verified'].includes(b.status)&&!b.ic&&!(b.waiver&&b.waiver.type==='unconditional')).length} without unconditional waiver`:'—'}</div></div></div>${held?`<div class="row" style="align-items:center"><span class="small">Retainage held ${money(held)}</span><span class="grow"></span><button class="btn sm" id="e-vrelease">Release retainage…</button></div>`:''}`; const bank = [...body.querySelectorAll('.card')].find(c => /Banking/.test(c.textContent)); if (bank) bank.before(div); else body.appendChild(div); const base = editing.collect; editing.collect = () => Object.assign(base(), {retainagePct:+$('#e-vret').value||0}); $('#e-vrelease')?.addEventListener('click', () => { closeEditor(); releaseRetainage(v); }); };
/* new bills for a sub carry the vendor's retainage; the bill editor shows it */
const billFlagsBase = billFlags;
billFlags = function(b){ const f = billFlagsBase(b); complianceIssues(b).forEach(x => { if (!f.some(y => y===x.m)) f.push(x.m); }); if (+b.retainagePct) f.push(`Retainage ${b.retainagePct}% held — net ${money(billTotal(b))} of ${money(billGross(b))}`); return f.filter(x => !/Vendor insurance expired/.test(x) || !f.some(y => /COI/.test(y))); };
document.addEventListener('change', e => { if (e.target.id!=='e-vendor' && !(e.target.matches && e.target.matches('#e-vendor, [list="vendors"]'))) return; const v = DB.vendors.find(x=>x.name.toLowerCase()===e.target.value.trim().toLowerCase()); if (v && editing?.kind==='bill'){ const b = DB.bills.find(x=>x.id===editing.id); if (b && b.retainagePct==null && v.retainagePct) { b.retainagePct = v.retainagePct; toast(`${v.retainagePct}% retainage will be held on this bill`); } } });
/* waiver capture on a paid bill (Bills & payroll grid row action) */
function recordWaiver(b){ mbModal(`Lien waiver — ${esc(b.vendor)} ${esc(b.number||'')}`, `<p class="small muted">Payment of ${money(billTotal(b))} on ${fmt(b.paidAt||b.date)}. Record the waiver received from the sub.</p><label class="f"><span>Type</span><select id="wv-type"><option value="conditional" ${b.waiver?.type==='conditional'?'selected':''}>Conditional (given with the check)</option><option value="unconditional" ${b.waiver?.type==='unconditional'?'selected':''}>Unconditional (after the check clears)</option></select></label><label class="f"><span>Received</span><input type="date" id="wv-date" value="${b.waiver?.received||today()}"></label><label class="f"><span>Note / file reference</span><input id="wv-note" value="${esc(b.waiver?.note||'')}"></label>`, {submit:'Save waiver', onSubmit:()=>{ b.waiver = {type:$('#wv-type').value, received:$('#wv-date').value, note:$('#wv-note').value, by:S.project.userName||''}; audit('bill', b.id, 'waiver', '', b.waiver.type, b.waiver.note); save(); render(); toast('Waiver recorded'); }}); }
/* reminders: compliance that needs the office */
const remindersBase4 = reminders;
reminders = function(){ const out = remindersBase4(); const td = today(); const soon = DB.vendors.filter(v => v.insuranceExp && dayDiff(td, v.insuranceExp) <= 30 && dayDiff(td, v.insuranceExp) >= 0 && DB.pos.some(po => po.vendor===v.name && ['issued','partial'].includes(po.status))); if (soon.length) out.push({n:soon.length, label:`active vendor${soon.length>1?'s':''} with insurance expiring within 30 days — request a new COI`, go:{view:'vendors'}, sev:'warn'}); const nw = DB.bills.filter(b => ['paid','verified'].includes(b.status) && !b.ic && !b.retainageRelease && subBill(b) && isSub(vendorOfBill(b)) && !(b.waiver && b.waiver.type==='unconditional') && dayDiff(b.paidAt||b.date, td) > 10); if (nw.length) out.push({n:nw.length, label:`sub payment${nw.length>1?'s':''} over 10 days old without an unconditional lien waiver · ${money(nw.reduce((a,b)=>a+billTotal(b),0))}`, go:{view:'ap'}, sev:'warn'}); const ret = DB.vendors.map(v => ({v, held:apRetainage(v.name)})).filter(x => x.held>0); if (ret.length) out.push({n:ret.length, label:`sub${ret.length>1?'s':''} with retainage held · ${money(ret.reduce((a,x)=>a+x.held,0))}`, go:{view:'vendors'}, sev:''}); return out; };
const openBillBase = openBill;
openBill = function(id){ openBillBase(id); const b = DB.bills.find(x=>x.id===id); const body = $('#d-body'); if (!b || !body) return; const iss = complianceIssues(b); const v = vendorOfBill(b);
  if (iss.length || +b.retainagePct){ const div = document.createElement('div'); div.className = 'note ' + (iss.some(x=>x.lvl==='block')?'warn':''); div.style.margin = '0 0 10px'; div.innerHTML = `${iss.map(x => `<div>${x.lvl==='block'?'<b>Blocks approval:</b> ':''}${x.m}</div>`).join('')}${+b.retainagePct?`<div>Retainage ${b.retainagePct}% held: pay ${money(billTotal(b))} of ${money(billGross(b))}.</div>`:''}`; body.prepend(div); }
  if (['paid','verified'].includes(b.status) && v && isSub(v) && subBill(b) && !b.ic && !b.retainageRelease){ const wrap = body.querySelector('.docacts, .row.wrap') || body; const btn = document.createElement('button'); btn.className = 'btn sm'; btn.textContent = b.waiver ? `Lien waiver: ${b.waiver.type} (${fmt(b.waiver.received)}) — update` : 'Record lien waiver'; btn.onclick = () => recordWaiver(b); wrap.appendChild(btn); } };

/* ===================== CLIENT PORTAL — approvals with a name and a timestamp, selections, statement ===================== */
/* The client signs in as themselves and sees exactly what is waiting on them: proposals and change orders to approve, selections to make, invoices to pay. Approving records who, when and what was approved (total, lines) on the document and in the audit log; approving a construction proposal converts it exactly as it would from the office. */
const clientUserOf = () => { const u = currentUser(); return u && u.clientId ? DB.clients.find(c => c.id===u.clientId) : clientOf(); };
function docSummaryHtml(c, d){ const t = docTotal(d); if (d.template==='construction' && d.mode!=='sov') ctNumber(d); const lines = d.mode==='sov' ? d.lines.filter(l => +l.pct) : d.lines.filter(l => !l.parent);
  return `<div class="pv"><div class="pv-head"><div><div class="small muted">${{estimate:'Proposal', co:'Change order', invoice:'Invoice'}[d.type]} ${esc(d.number)} · ${fmt(d.date)}</div><h3 style="margin:2px 0">${esc(d.title||'')}</h3></div><div style="text-align:right"><div class="small muted">Total</div><b style="font-size:20px">${money(t.total)}</b></div></div>
    <table class="t pv-t"><tbody>${lines.map(l => { const subs = d.lines.filter(x => x.parent===l.id); return `<tr><td><b>${l.num?l.num+'. ':''}${esc(l.item||l.desc||'')}</b>${l.desc && l.item ? `<div class="small muted" style="white-space:pre-wrap">${esc(ctFirstLine ? ctFirstLine(l.desc) : l.desc)}</div>`:''}${subs.length?`<div class="small muted">${subs.map(s=>esc(s.item)).join(' · ')}</div>`:''}</td><td class="money">${d.mode==='sov'?`${l.pct}% · `:''}${money(d.mode==='sov' ? lineAmount(l,d) : lineAmount(l,d) + subs.reduce((a,s)=>a+lineAmount(s,d),0))}</td></tr>`; }).join('')}</tbody><tfoot>${t.disc?`<tr><td>Discount</td><td class="money">−${money(t.disc)}</td></tr>`:''}${t.tax?`<tr><td>Sales tax</td><td class="money">${money(t.tax)}</td></tr>`:''}${t.ret?`<tr><td>Retainage held</td><td class="money">−${money(t.ret)}</td></tr>`:''}<tr style="font-weight:600"><td>Total</td><td class="money">${money(t.total)}</td></tr></tfoot></table>
    ${d.memo?`<div class="small" style="margin-top:8px;white-space:pre-wrap">${esc(d.memo)}</div>`:''}${d.terms?`<div class="small muted" style="margin-top:6px"><b>Terms</b> ${esc(d.terms)}</div>`:''}${d.scheduleDays?`<div class="small muted" style="margin-top:4px">Adds ${d.scheduleDays} working day${d.scheduleDays>1?'s':''} to the schedule.</div>`:''}</div>`; }
function portalApprove(c, d){ const u = currentUser(); const t = docTotal(d); const kind = d.type==='co' ? 'change order' : 'proposal';
  mbModal(`Approve ${kind} ${esc(d.number)}`, `${docSummaryHtml(c, d)}<div class="card" style="margin-top:10px"><label class="f"><span>Type your full name to approve</span><input id="pa-name" value="${esc(u?.name||'')}" autocomplete="name"></label><label class="small"><input type="checkbox" id="pa-agree"> I approve this ${kind} for ${money(t.total)} and the terms above.${d.type==='co'?' I understand it changes the contract sum and, where noted, the schedule.':''}</label></div>`,
    {submit:`Approve ${money(t.total)}`, onSubmit:()=>{ const name = $('#pa-name').value.trim(); if (!name || !$('#pa-agree').checked){ toast('Type your name and tick the box to approve'); return false; } d.clientApproval = {name, t:nowStamp(), ts:new Date().toISOString(), total:t.total, lines:d.lines.length, via:'portal', user:u?.id||''}; try { audit(d.type, d.id, 'client-approved', d.status, 'approved', `${name} approved ${d.number} ${money(t.total)} via portal`); } catch(e){} c.activity.push({t:nowStamp(), by:name, text:`${d.number} approved by client via portal — ${money(t.total)}`}); Promise.resolve(docAction(c, d, 'approve')).then(() => { save(); render(); toast(`${d.number} approved — thank you`); }); }}); }
function portalQuestion(c, d){ const u = currentUser(); const q = prompt(`Question or change request about ${d.number}:`); if (!q) return; const p = DB.projects.find(x => x.id===d.projectId) || S; (p.comms = p.comms||[]).push({id:uid('cm'), t:nowStamp(), ts:new Date().toISOString(), from:u?.name||c.name, subject:`Re: ${d.number} ${d.title||''}`, body:q, status:'new', category:'client', source:'portal'}); c.activity.push({t:nowStamp(), by:u?.name||c.name, text:`Question on ${d.number}: ${q}`}); d.clientNote = {t:nowStamp(), by:u?.name||'', text:q}; try { audit(d.type, d.id, 'client-question', d.status, d.status, q); } catch(e){} save(); render(); toast('Sent to your project manager'); }
function portalDecide(dec){ const m = dec.kind==='mat' ? mat(dec.ref) : null; const u = currentUser(); mbModal(`Your selection — ${esc(dec.name)}`, `<p class="small muted">${m?`For: ${esc(m.name)}. `:''}Tell us what you've chosen; we record it with your name and the date and it releases the order or task it is holding.</p><label class="f"><span>Your choice</span><input id="pd-choice" placeholder="e.g. Calacatta Gold honed, 12x24"></label><label class="f"><span>Notes</span><textarea id="pd-note" rows="2"></textarea></label>`, {submit:'Confirm selection', onSubmit:()=>{ const ch = $('#pd-choice').value.trim(); if (!ch){ toast('Enter your choice'); return false; } dec.status = 'made'; dec.decision = ch; dec.decidedBy = u?.name||''; dec.decidedAt = today(); dec.notes = [dec.notes, $('#pd-note').value.trim()].filter(Boolean).join('\n'); if (m && m.status==='needs-decision') m.status = 'not-ordered'; log(`Selection by client (${u?.name||'client'}): ${dec.name} — ${ch}`); try { audit('decision', dec.id, 'client-decided', 'open', 'made', `${u?.name||''}: ${ch}`); } catch(e){} save(); render(); toast('Selection recorded'); }}); }
function portalStatement(c){ const keep = [repClient, repFrom, repTo]; repClient = c.id; repFrom = ''; repTo = ''; const html = repStatement(); [repClient, repFrom, repTo] = keep; mbModal('Your account statement', `<div class="pv">${html.replace(/<div class="rep-head">[\s\S]*?<\/div><\/div>/, '')}</div>`, {}); }
function renderPortalApprovals(){ const c = clientUserOf(); const host = $('#cl-approvals'); if (!host || !c) return; const est = c.estimates.filter(d => d.status==='sent'); const cos = c.changeOrders.filter(d => d.status==='sent'); const inv = clientFin(c).open; const decs = DB.projects.filter(p => p.clientId===c.id).flatMap(p => p.decisions.filter(d => d.owner==='Client' && d.status==='open').map(d => ({d, p}))); const n = est.length + cos.length + decs.length;
  const docRow = (d, kind) => `<div class="pa-row"><div class="pa-main"><b>${esc(d.title||d.number)}</b><div class="small muted">${kind} ${esc(d.number)} · ${fmt(d.date)}${d.validUntil?` · valid until ${fmt(d.validUntil)}`:''}${d.clientNote?` · <i>you asked: ${esc(d.clientNote.text)}</i>`:''}</div></div><b class="pa-amt">${money(docTotal(d).total)}</b><div class="pa-acts"><button class="btn sm" data-pview="${d.type}:${d.id}">View</button><button class="btn sm" data-pask="${d.type}:${d.id}">Ask</button><button class="btn sm primary" data-papprove="${d.type}:${d.id}">Approve</button></div></div>`;
  host.innerHTML = `<div class="card" style="margin-bottom:14px"><div class="row" style="align-items:baseline"><h3 style="margin:0">Waiting on you</h3><span class="small muted" style="margin-left:8px">${n?`${n} item${n>1?'s':''}`:'nothing right now'}</span></div>
    ${est.map(d => docRow(d, 'Proposal')).join('')}${cos.map(d => docRow(d, 'Change order')).join('')}
    ${decs.map(({d,p}) => { const due = decDue(d); const st = decState(d); return `<div class="pa-row"><div class="pa-main"><b>${esc(d.name)}</b><div class="small muted">Selection · ${esc(p.project.name)}${due?` · needed by ${fmt(due)}`:''}${st.sev>=2?' <span class="pill warn">holding the schedule</span>':''}</div></div><div class="pa-acts"><button class="btn sm primary" data-pdecide="${p.id}:${d.id}">Make selection</button></div></div>`; }).join('')}
    ${inv.length?`<div class="small muted" style="margin-top:10px;text-transform:uppercase;letter-spacing:.04em">Invoices</div>${inv.map(o => `<div class="pa-row"><div class="pa-main"><b>${esc(o.x.title||o.x.number)}</b><div class="small muted">${esc(o.x.number)} · due ${o.x.due?fmt(o.x.due):'on receipt'}${o.age>0?` · <span class="bad">${o.age} days past due</span>`:''}</div></div><b class="pa-amt">${money(o.bal)}</b><div class="pa-acts"><button class="btn sm" data-pview="invoice:${o.x.id}">View</button></div></div>`).join('')}`:''}
    <div class="row" style="margin-top:10px;gap:6px"><button class="btn sm" id="p-statement">Account statement</button>${[...c.estimates, ...c.changeOrders].filter(d=>d.clientApproval).length?`<span class="small muted">You have approved ${[...c.estimates, ...c.changeOrders].filter(d=>d.clientApproval).length} document${[...c.estimates, ...c.changeOrders].filter(d=>d.clientApproval).length>1?'s':''} — each is recorded with your name and time.</span>`:''}</div></div>`;
  const find = s => { const [k, id] = s.split(':'); return [k, findDoc(c, k, id)]; };
  host.querySelectorAll('[data-pview]').forEach(b => b.onclick = () => { const [k, d] = find(b.dataset.pview); if (d) mbModal(`${{estimate:'Proposal', co:'Change order', invoice:'Invoice'}[k]} ${esc(d.number)}`, docSummaryHtml(c, d), {}); });
  host.querySelectorAll('[data-pask]').forEach(b => b.onclick = () => { const [, d] = find(b.dataset.pask); if (d) portalQuestion(c, d); });
  host.querySelectorAll('[data-papprove]').forEach(b => b.onclick = () => { const [, d] = find(b.dataset.papprove); if (d) portalApprove(c, d); });
  host.querySelectorAll('[data-pdecide]').forEach(b => b.onclick = () => { const [pid, did] = b.dataset.pdecide.split(':'); const p = DB.projects.find(x=>x.id===pid); const dec = p?.decisions.find(x=>x.id===did); if (dec){ if (S.id!==p.id) setCurrent(p.id); portalDecide(dec); } });
  $('#p-statement')?.addEventListener('click', () => portalStatement(c)); }
const renderClientBase = renderClient;
renderClient = function(cpm, projEnd){ renderClientBase(cpm, projEnd); renderPortalApprovals(); };
/* office side: approval record on the document + statement button on the client record */
const docActionsBase3 = docActions;
docActions = function(c, d, st){ let h = docActionsBase3(c, d, st); if (d.clientApproval) h = `<span class="pill ok" title="${esc(d.clientApproval.ts||'')}">Approved by ${esc(d.clientApproval.name)} · ${esc(d.clientApproval.t)} · ${money(d.clientApproval.total)}</span> ` + h; if (d.clientNote && ['sent'].includes(d.status)) h = `<span class="pill warn">Client asked: ${esc(d.clientNote.text.slice(0,60))}</span> ` + h; return h; };
const renderFinTabBase = renderFinTab;
renderFinTab = function(c, f, projs){ const h = renderFinTabBase(c, f, projs); return h.replace(/(<button class="btn primary" data-newdoc="estimate:construction">)/, `<button class="btn" data-cstatement="${c.id}">Statement</button>$1`); };
document.addEventListener('click', e => { const b = e.target.closest('[data-cstatement]'); if (!b) return; const c = DB.clients.find(x=>x.id===b.dataset.cstatement); if (!c) return; const keep = [repClient]; repClient = c.id; const html = repStatement(); repClient = keep[0]; mbModal(`Statement — ${esc(c.name)}`, `<div class="pv">${html}</div><div class="row" style="margin-top:8px"><span class="grow"></span><button class="btn" id="cs-print">Print / PDF</button></div>`, {}); $('#cs-print')?.addEventListener('click', () => { repClient = c.id; repTab = 'statement'; view = 'reports'; mbCloseModal(); render(); setTimeout(() => $('#rep-print')?.click(), 100); }); });
/* the office sees what the client is sitting on */
const remindersBase5 = reminders;
reminders = function(){ const out = remindersBase5(); const td = today(); const waiting = DB.clients.flatMap(c => [...c.estimates, ...c.changeOrders].filter(d => d.status==='sent' && dayDiff(d.date, td) > 7).map(d => ({c, d}))); if (waiting.length) out.push({n:waiting.length, label:`proposal${waiting.length>1?'s':''} / change order${waiting.length>1?'s':''} with the client for more than a week · ${money(waiting.reduce((a,x)=>a+docTotal(x.d).total,0))} — nudge`, go:{view:'clients'}, sev:'warn'}); const asked = DB.clients.flatMap(c => [...c.estimates, ...c.changeOrders].filter(d => d.status==='sent' && d.clientNote)); if (asked.length) out.push({n:asked.length, label:`client question${asked.length>1?'s':''} on open proposals — answer them`, go:{view:'clients'}, sev:'bad'}); return out; };

/* ===================== DESIGN CHANGE ORDERS + STUDIO RATE SCHEDULE ===================== */
/* A design change order adds phases or hours to a design proposal (extra revisions, an added filing). It is approved like any CO, joins the fee, and is billed through the same milestones/hours. Rate schedule: one studio rate per staff level, used when a design line or an employee has none of its own. */
const rateSchedule = () => (DB.company.rateSchedule = DB.company.rateSchedule || [{level:'Principal', rate:225}, {level:'Architect', rate:175}, {level:'Designer', rate:140}, {level:'Drafter', rate:95}]);
function levelRate(level){ const s = rateSchedule().find(x => x.level.toLowerCase()===(level||'').toLowerCase()); return s ? +s.rate : designRate(); }
const laborBillRate = emp => +emp?.billRate || levelRate(emp?.role) || 0;
const docActionsBase4 = docActions;
docActions = function(c, d, st){ let h = docActionsBase4(c, d, st); if (d.type==='estimate' && d.template==='design' && ['approved','converted'].includes(d.status) && mbCanEdit()) h += `<button class="btn sm" data-docact="dco">Design change order…</button>`; return h; };
const docActionBase5 = docAction;
docAction = async function(c, d, a){ if (a==='dco' && d.template==='design'){ const co = newDoc(c, 'co', {}); co.title = `Additional design services — ${d.title||d.number}`; co.template = 'design'; co.designOf = d.id; co.projectId = d.projectId; co.lines = [{id:uid('l'), item:'Additional revisions', desc:'', qty:8, unit:'hr', rate:designRate(), taxable:false, cost:r2(8*66), code:'01'}]; docMark(co); docOpen = {kind:'co', id:co.id}; finTab = 'co'; save(); render(); toast('Design change order drafted — set the hours or fee, then send'); return; } return docActionBase5(c, d, a); };
/* rate schedule editor on the Studio report */
const repStudioBase = repStudio;
repStudio = function(){ return repStudioBase() + `<h3 class="rep-h">Studio rate schedule</h3><div class="tw"><table class="t rep-t" style="max-width:420px"><thead><tr><th>Level</th><th class="money">Bill rate / h</th><th class="money">People</th></tr></thead><tbody>${rateSchedule().map(s => `<tr><td>${esc(s.level)}</td><td class="money">${money(s.rate)}</td><td class="money">${DB.employees.filter(e => (e.role||'').toLowerCase()===s.level.toLowerCase()).length||'—'}</td></tr>`).join('')}</tbody></table></div>${role()==='owner'?`<button class="btn sm" id="rs-edit" style="margin-top:6px">Edit rate schedule</button>`:''}<p class="small muted">An employee's own bill rate wins; otherwise the rate for their level applies. Design proposals default to the studio rate (${money(designRate())}).</p>`; };
const renderReportsBase6 = renderReports;
renderReports = function(){ renderReportsBase6(); $('#rs-edit')?.addEventListener('click', () => { const txt = prompt('Levels as level:rate, one per line', rateSchedule().map(s=>`${s.level}:${s.rate}`).join('\n')); if (txt===null) return; DB.company.rateSchedule = txt.split('\n').map(s => { const i = s.lastIndexOf(':'); return i>0 ? {level:s.slice(0,i).trim(), rate:+s.slice(i+1)||0} : null; }).filter(x => x && x.level); save(); render(); }); };

/* ===================== FINANCIAL CORRECTIONS (panel round 2) — one truth for cash, AP, cost incurred, backlog, revenue ===================== */
/* 1. A bank/card debit that matches a bill IS the payment: bill.txnId ↔ txn.billId, paidAt = bank date. AP = bills not yet paid. A bill paid before approval is an exception, not a payable.
   2. Cost incurred = every bill entered (approved or awaiting approval) + bank items without a bill + labor. Approval gates payment, not recognition. "Of which awaiting approval" is printed wherever cost prints.
   3. Cash on the books = opening balance + register. Balance sheet: AR = open invoices (retainage receivable separate), AP retainage payable, accrued payroll, credits on account, over-billings; client funds is a memo.
   4. One vocabulary: Revenue (earned) · Billed to date · Backlog = contract − earned · Unbilled contract = contract − billed.
   5. Owned property is its own line below operating profit, never inside GC overhead. */
function billMatchTxn(b){ if (b.txnId) return DB.txns.find(t => t.id===b.txnId) || null; const n = (b.vendor||'').toLowerCase(); const gross = billGross(b), net = billTotal(b); const po = b.poId ? DB.pos.find(p=>p.id===b.poId) : null;
  return DB.txns.find(t => t.amt < 0 && !t.billId && (t.billId!==b.id) && (((t.vendor||'').toLowerCase()===n || (t.desc||'').toLowerCase().includes(n.split(' ')[0]) && n.split(' ')[0].length>3) && (Math.abs(-t.amt - net) <= Math.max(1, net*0.02) || Math.abs(-t.amt - gross) <= Math.max(1, gross*0.02)) && Math.abs(dayDiff(b.date, t.date)) <= 45) || (po && (po.matchedTxns||[]).includes(t.id) && Math.abs(-t.amt - net) <= Math.max(1, net*0.05))) || null; }
function linkBankToBills(){ let n = 0; DB.bills.filter(b => !['void','rejected','draft'].includes(b.status) && !b.txnId && !b.ic).forEach(b => { const t = billMatchTxn(b); if (!t) return; b.txnId = t.id; t.billId = b.id; if (!b.paidAt) b.paidAt = t.date; if (!['paid','verified'].includes(b.status)){ b.paidBeforeApproval = true; } else if (b.status==='paid') b.status = 'verified'; n++; }); return n; }
const billIsPaid = b => !!(b.paidAt || b.txnId || ['paid','verified'].includes(b.status));
const verifyAllBase = verifyAll;
verifyAll = function(){ linkBankToBills(); return verifyAllBase(); };
/* accounts: opening balance so cash on the books = opening + register */
function acctRegister(a){ return r2(DB.txns.filter(t => t.acct===a.id).reduce((s,t)=>s+t.amt,0)); }
function acctBook(a){ if (a.opening==null) a.opening = r2((+a.balance||0) - acctRegister(a)); return r2(a.opening + acctRegister(a)); }
function undepositedReceipts(){ const out = []; DB.clients.forEach(c => c.payments.filter(py => !py.unapplied && (+py.amount||0) > 0).forEach(py => { const hit = DB.txns.find(t => t.amt > 0 && Math.abs(t.amt - py.amount) <= 1 && Math.abs(dayDiff(py.date, t.date)) <= 10); if (!hit) out.push({c, py}); })); return out; }
function accruedPayroll(){ return r2(DB.payroll.filter(r => r.payDate && r.payDate <= today() && !['paid','verified','void'].includes(r.status) && r.total).reduce((a,r)=>a+(+r.total||0),0)); }
const companyBalanceBase3 = companyBalance;
companyBalance = function(){ linkBankToBills(); const B = companyBalanceBase3(); const td = today(); B.cash = r2(DB.accounts.filter(a=>a.type==='bank').reduce((s,a)=>s+acctBook(a),0)); const openBills = DB.bills.filter(b => !['void','rejected','draft'].includes(b.status) && !billIsPaid(b)); B.ap = r2(openBills.reduce((a,b)=>a+billTotal(b),0)); B.apOver = r2(openBills.filter(b => b.due && parse(b.due) < parse(td)).reduce((a,b)=>a+billTotal(b),0)); B.apAccrued = r2(openBills.filter(b => BILL_ACCRUED.includes(b.status)).reduce((a,b)=>a+billTotal(b),0)); B.apRet = r2(DB.vendors.reduce((a,v)=>a+apRetainage(v.name),0)); B.payrollAccrued = accruedPayroll(); B.undeposited = r2(undepositedReceipts().reduce((a,x)=>a+(+x.py.amount||0),0)); B.credits = r2(DB.clients.reduce((a,c)=>a+clientFin(c).credits,0)); const W = DB.projects.map(wipRow); B.over = r2(W.reduce((a,w)=>a+w.over,0)); B.under = r2(W.reduce((a,w)=>a+w.under,0)); B.cashToday = r2(B.cash - (-B.cards) - B.ap - B.payrollAccrued); B.trulyOurs = r2(B.cashToday - B.over); B.available = r2(B.cash - B.clientFunds); B.paidBeforeApproval = DB.bills.filter(b => b.paidBeforeApproval && !['paid','verified','void'].includes(b.status)); return B; };
/* engine: cost incurred includes bills awaiting approval */
const jobFinBase2 = jobFin;
jobFin = function(p, range){ const J = jobFinBase2(p, range); const R = range || ['', today()]; const acc = DB.bills.filter(b => b.projectId===p.id && BILL_ACCRUED.includes(b.status) && within(b.date, R)); const accrued = r2(acc.reduce((a,b)=>a+billTotal(b),0)); if (!accrued) { J.actualCosted = J.actual; return J; }
  J.actualCosted = J.actual; J.accrued = accrued; J.actual = r2(J.actual + accrued); J.billsAmt = r2(J.billsAmt + accrued); acc.forEach(b => { const code = b.code || '99'; let row = J.byCode.find(x => x.code===code); if (!row){ row = {code, name:(COST_CODES.find(x=>x[0]===code)||[code,'Other'])[1], contract:0, budget:0, committed:0, bills:0, bank:0, labor:0, actual:0}; J.byCode.push(row); } row.bills = r2(row.bills + billTotal(b)); row.actual = r2(row.actual + billTotal(b)); }); J.byCode.sort((a,b)=>a.code.localeCompare(b.code));
  const ctc = +(p.ctc||0); J.eac = r2(p.ctcReviewed ? Math.max(J.actual + J.committed, J.actual + ctc) : Math.max(J.budget, J.actual + J.committed)); J.pct = J.eac ? Math.min(1, J.actual/J.eac) : 0; J.earned = r2(J.contract*J.pct); J.overUnder = r2(J.billed - J.earned); J.over = Math.max(0, J.overUnder); J.under = Math.max(0, -J.overUnder); J.backlog = r2(Math.max(0, J.contract - J.earned)); J.estGP = r2(J.contract - J.eac); J.estGPPct = J.contract ? r2(J.estGP/J.contract*100) : 0; J.backlogGP = r2(J.estGP*(1-J.pct)); J.defs = J.defs.replace('actual = approved bills', 'actual = all bills entered (approved or awaiting approval)'); return J; };
/* P&L: bills awaiting approval are cost; payroll recognised by pay date once approved; a bill paid by bank is never also a bank item */
const ledgerBase3 = ledger;
ledger = function(range){ const rows = ledgerBase3(range); DB.bills.filter(b => BILL_ACCRUED.includes(b.status) && within(b.date, range) && !(repEntity && (b.entityId||'ent1')!==repEntity)).forEach(b => rows.push({date:b.date, kind:'bill', cat:b.cat||'uncat', vendor:b.vendor, desc:`${b.vendor} · ${b.number} (awaiting approval)`, amt:billTotal(b), projectId:b.projectId||'', ref:b, unapproved:true})); return rows.filter(r => !(r.kind==='txn' && r.ref && r.ref.billId)); };
/* revenue and backlog vocabulary */
KPIS.income.n = 'Revenue (earned)'; KPIS.backlog = {n:'Backlog (contract − earned)', g:'Projects', fmt:'money', good:'up', go:{view:'reports', tab:'wip'}, fn:() => r2(DB.projects.reduce((a,p)=>a+jobFin(p).backlog,0))}; KPIS.unbilled = {n:'Unbilled contract (contract − billed)', g:'Projects', fmt:'money', good:'up', go:{view:'reports', tab:'portfolio'}, fn:() => r2(DB.projects.reduce((a,p)=>{ const J = jobFin(p); return a + Math.max(0, J.contract - J.billed); },0))};
const METRIC_DEFS = {income:'Revenue (earned) = invoices issued ex tax ± the change in over/under-billing (earned = contract × % complete, cost-to-cost).', billed:'Billed to date = invoices issued ex tax, before retainage.', backlog:'Backlog = contract − earned revenue: work still to be performed.', unbilled:'Unbilled contract = contract − billed: contract value not yet invoiced (differs from backlog by over/under-billing).', actual:'Cost incurred = all bills entered (approved or awaiting approval) + bank items without a bill + labor at burdened rates.', cashToday:'Cash today = bank (book) − credit cards − unpaid bills − payroll due.', trulyOurs:'Truly ours = cash today − billings in excess of earned (client money for work not yet done).', safe:'Safe to spend = the lower of truly ours and the 13-week forecast low.'};
/* owned property below operating profit */
const companyPLBase5 = companyPL;
companyPL = function(range){ const P = companyPLBase5(range); if (P.rent==null) return P; const opex = P.oh['Property operating']||0, int = P.oh['Mortgage interest']||0; P.propertyNOI = r2(P.rent - opex - int); P.income = r2(P.income - P.rent); delete P.oh['Property operating']; delete P.oh['Mortgage interest']; P.ohT = r2(P.ohT - opex - int); P.gross = r2(P.income - P.cogsT); P.opProfit = r2(P.gross - P.ohT); P.net = r2(P.opProfit + P.propertyNOI); P.grossPct = P.income?Math.round(P.gross/P.income*100):0; P.netPct = P.income?Math.round(P.net/P.income*100):0; P.accruedCost = r2(P.L.filter(r=>r.unapproved).reduce((a,r)=>a+r.amt,0)); return P; };
/* tie-out: jobs + unassigned + payroll not on jobs = COGS */
function tieOut(range){ const P = companyPL(range); const jobs = r2(DB.projects.filter(p => !repEntity || entityOfProject(p)===repEntity).reduce((a,p)=>a+jobFin(p, range).actual,0)); const unassigned = r2(P.L.filter(r => !r.income && !r.projectId && r.kind!=='payroll' && catType(r.cat)==='cogs').reduce((a,r)=>a+r.amt,0)); const laborJobs = r2(DB.projects.reduce((a,p)=>a+jobFin(p, range).laborCost,0)); const payrollJobs = r2(P.L.filter(r => r.kind==='payroll' && r.projectId).reduce((a,r)=>a+r.amt,0)); const laborDiff = r2(payrollJobs - laborJobs); const ar = r2(DB.clients.reduce((a,c)=>a+clientFin(c).outstanding,0)); const B = companyBalance(); return {P, jobs, unassigned, laborDiff, cogs:P.cogsT, gap:r2(P.cogsT - jobs - unassigned - laborDiff), ar, arBS:B.arOut, invoiced:P.invoiced, wipAdj:P.wipAdj, income:P.income}; }
function tieOutHtml(range){ const T = tieOut(range); const ok = v => Math.abs(v) < 1; return `<div class="card tie"><h3 class="rep-h" style="margin-top:0">Ties</h3><table class="t rep-t"><tbody><tr><td>Revenue (earned)</td><td class="money">${money(T.income)}</td><td class="small muted">= billed ${money(T.invoiced)} ${T.wipAdj>=0?'+':'−'} WIP adjustment ${money(Math.abs(T.wipAdj))}</td><td>${ok(T.income - T.invoiced - T.wipAdj)?'<span class="pill ok">ties</span>':'<span class="pill bad">off</span>'}</td></tr><tr><td>Job cost (P&L)</td><td class="money">${money(T.cogs)}</td><td class="small muted">= jobs ${money(T.jobs)} + no project ${money(T.unassigned)} + payroll not clocked to a job ${money(T.laborDiff)}</td><td>${ok(T.gap)?'<span class="pill ok">ties</span>':`<span class="pill warn">gap ${money(T.gap)}</span>`}</td></tr><tr><td>Receivables</td><td class="money">${money(T.arBS)}</td><td class="small muted">= open invoices on client records ${money(T.ar)}</td><td>${ok(T.arBS - T.ar)?'<span class="pill ok">ties</span>':'<span class="pill bad">off</span>'}</td></tr></tbody></table><div class="small muted">${METRIC_DEFS.income} ${METRIC_DEFS.actual}</div></div>`; }

/* ===================== PROCUREMENT COCKPIT — the Buy board: everything to buy, across every job, in the order it must be ordered ===================== */
/* One row per thing still to buy: schedule materials not on site, plus contract lines with budget left and no PO. Order-by = when the task needs it − lead time.
   Red = past order-by or ETA after need-by. Amber = order within a week, no vendor, no price, waiting on a decision, ordered without an ETA. Green = ordered and arriving in time. One tap does the next thing. */
function withProject(p, fn){ const keep = S; if (p && p!==S){ S = p; applyHolidays(); } try { return fn(); } finally { if (keep!==S){ S = keep; applyHolidays(); } } }
const wd = (a, b) => { let n = 0, d = parse(a); const e = parse(b); const sign = e >= d ? 1 : -1; while ((sign>0 ? d < e : d > e)){ d = addDays(d, sign); if (d.getDay()>0 && d.getDay()<6) n += sign; } return n; };
function lineNeedBy(p, l){ const code = l.code || codeForLine(l); const trades = (COST_CODES.find(c=>c[0]===code)||[])[2]||[]; const ts = p.tasks.filter(t => trades.includes(t.trade) && t.status!=='done').sort((a,b)=>a.start.localeCompare(b.start)); return ts[0] ? {needBy:ts[0].start, task:ts[0]} : {needBy:'', task:null}; }
function buyList(scope){ const rows = []; const td = today(); const projs = DB.projects.filter(p => !scope || p.id===scope);
  projs.forEach(p => withProject(p, () => { const c = DB.clients.find(x=>x.id===p.clientId); const covered = new Set();
    p.materials.filter(m => m.status!=='on-site').forEach(m => { const {needBy, orderBy} = matDates(m); const st = matState(m); const dec = openDecisionFor('mat', m.id); const pos = DB.pos.filter(po => po.projectId===p.id && !['cancelled','draft'].includes(po.status) && po.lines.some(l => l.materialId===m.id)); const po = pos[0]; const lf = m.line ? lineFin(m.line) : null; if (m.line) covered.add(m.line); const price = +m.cost || (lf ? lf.budget : 0); const vendor = m.vendor || po?.vendor || lf?.line.vendor || ''; const ordered = ['ordered','shipped'].includes(m.status) || !!po; const eta = m.eta || po?.expected || '';
      let sev = 0, why = ''; if (!ordered){ if (dec){ sev = orderBy && orderBy < td ? 3 : 2; why = 'waiting on decision'; } else if (orderBy && orderBy < td){ sev = 3; why = `order-by ${fmt(orderBy)} passed`; } else if (orderBy && wd(td, orderBy) <= 5){ sev = 2; why = `order by ${fmt(orderBy)}`; } if (!vendor && sev < 2){ sev = 2; why = why || 'no vendor'; } if (!price && sev < 2){ sev = 2; why = why || 'no price'; } } else { if (eta && needBy && eta > needBy){ sev = 3; why = `ETA ${fmt(eta)} after need-by ${fmt(needBy)}`; } else if (!eta){ sev = 2; why = 'ordered — no ETA'; } else { sev = 0; why = `arriving ${fmt(eta)}`; } }
      rows.push({kind:'material', p, m, c, key:m.line||'', name:m.name, needBy, orderBy, lead:+m.lead||0, task:task(m.taskId), vendor, price, budget:lf?lf.budget:(+m.cost||0), held:0, po, ordered, eta, dec, sev, why, st}); });
    if (c) c.estimates.filter(e => e.status==='converted' && e.projectId===p.id).forEach(d => { if (d.template==='construction') ctNumber(d); d.lines.forEach(l => { if (l.parent) return; const key = ctKey(d, l); if (covered.has(key)) return; const f = lineFin(key); if (!f) return; const remaining = Math.max(0, r2(f.budget - f.actual - f.committed)); if (!f.budget || remaining < 1) return; const buyable = (l.items||[]).length || /material|millwork|tile|fixture|appliance|window|door|stone|floor|light|hardware|cabinet|lumber|glass|counter|vanit|radiator/i.test(l.item||''); if (!buyable) return; const {needBy, task:tk} = lineNeedBy(p, l); const orderBy = needBy ? addWork(needBy, -(l.leadWeeks ? +l.leadWeeks*5 : 5), false) : ''; const funds = clientFundsLedger().find(r => r.key===key); let sev = 0, why = ''; if (orderBy && orderBy < td){ sev = 3; why = `order-by ${fmt(orderBy)} passed`; } else if (orderBy && wd(td, orderBy) <= 5){ sev = 2; why = `order by ${fmt(orderBy)}`; } else if (!needBy){ sev = 1; why = 'no task date — link a task'; } if (!l.vendor && sev < 2){ sev = 2; why = why || 'no vendor'; }
      rows.push({kind:'line', p, c, d, l, key, name:(l.num?l.num+'. ':'')+(l.item||''), needBy, orderBy, lead:l.leadWeeks?+l.leadWeeks*5:5, task:tk, vendor:l.vendor||'', price:remaining, budget:f.budget, held:funds?funds.reserved:0, po:null, ordered:false, eta:'', dec:null, sev, why}); }); });
  }));
  return rows.sort((a,b) => (b.sev - a.sev) || ((a.orderBy||'9999') .localeCompare(b.orderBy||'9999'))); }
let buyScope = '', buyOpen = true;
function buyStrip(rows){ const td = today(); const week = rows.filter(r => !r.ordered && r.orderBy && wd(td, r.orderBy) <= 5 && r.orderBy >= td).length; const late = rows.filter(r => r.sev===3).length; const unpriced = rows.filter(r => !r.ordered && !r.price).length; const noVendor = rows.filter(r => !r.ordered && !r.vendor).length; const due = DB.pos.filter(po => ['issued','partial'].includes(po.status) && (!buyScope || po.projectId===buyScope) && po.expected && dayDiff(td, po.expected) <= 7).length; const deposits = r2(DB.pos.filter(po => ['issued','partial'].includes(po.status) && (!buyScope || po.projectId===buyScope)).reduce((a,po)=>a+poNextDue(po).amount,0)); const B = companyBalance(); const committed = r2(DB.pos.filter(po => ['issued','partial'].includes(po.status) && (!buyScope || po.projectId===buyScope)).reduce((a,po)=>a+Math.max(0, poTotal(po).total - poBilled(po)),0));
  const t = (n, l, cls) => `<div class="kpi ${n&&cls?cls:''}"><b>${typeof n==='number'&&l.startsWith('$')?money(n):n}</b><span>${l.replace(/^\$/,'')}</span></div>`;
  return `<div class="kpis buy-strip">${t(late,'late — order-by passed or ETA after need-by','warn')}${t(week,'to order this week','')}${t(unpriced,'unpriced','warn')}${t(noVendor,'no vendor','warn')}${t(due,'deliveries due within 7 days','')}${t(deposits,'$vendor deposits / balances due','')}${t(B.available,'$client funds available to buy (bank − funds held)','')}${t(committed,'$committed on open POs, not yet billed','')}</div>`; }
function renderBuyBoard(){ const host = $('#buy-board'); if (!host) return; if (poOpen){ host.innerHTML = ''; return; } const rows = buyList(buyScope); const td = today(); const shown = buyOpen ? rows : rows.filter(r => r.sev >= 2);
  host.innerHTML = `<div class="row" style="align-items:center;gap:8px;margin-bottom:6px"><h3 style="margin:0">Buy board</h3><span class="small muted">${rows.length} open · ${rows.filter(r=>r.sev===3).length} red · ${rows.filter(r=>r.sev===2).length} amber</span><span class="grow"></span><div class="seg sm"><button class="${!buyScope?'on':''}" data-buyscope="">All projects</button>${DB.projects.filter(p => p.materials.length || DB.clients.some(c=>c.estimates.some(e=>e.status==='converted'&&e.projectId===p.id))).map(p => `<button class="${buyScope===p.id?'on':''}" data-buyscope="${p.id}">${esc(p.project.name.replace(/ —.*$/,''))}</button>`).join('')}</div><button class="btn sm" id="buy-toggle">${buyOpen?'Only red & amber':'Show all'}</button></div>${buyStrip(rows)}
    <div class="tw"><table class="t buy-t"><thead><tr><th></th><th>Item</th><th>Job · task</th><th>Order by</th><th>On site by</th><th>Lead</th><th>Vendor</th><th class="money">Price / budget</th><th class="money">Client funds</th><th>Status</th><th></th></tr></thead><tbody>${shown.map((r,i) => { const act = r.ordered ? (r.eta ? `<button class="btn sm" data-buy="recv|${r.p.id}">Received</button>` : `<input type="date" data-buyeta="${r.p.id}:${r.m?.id||''}" title="Confirm ETA" style="height:30px">`) : r.dec ? `<button class="btn sm" data-buy="dec|${r.p.id}|${r.dec.id}">Get decision</button>` : `<button class="btn sm primary" data-buy="po|${r.p.id}|${r.d?r.d.id:''}|${r.key||''}|${r.m?r.m.id:''}">Create PO</button>`;
      return `<tr class="buy-row sev${r.sev}"><td><i class="rag rag${r.sev}"></i></td><td><b>${esc(r.name)}</b>${r.dec?`<div class="small muted">decision: ${esc(r.dec.name)}</div>`:''}${r.kind==='line'?'<div class="small muted">contract line, no PO yet</div>':''}</td><td class="small">${esc(r.p.project.name.replace(/ —.*$/,''))}${r.task?`<div class="muted">${esc(r.task.name)} · starts ${fmt(r.task.start)}</div>`:''}</td><td class="${r.orderBy&&r.orderBy<td&&!r.ordered?'bad':''}">${r.orderBy?fmt(r.orderBy):'—'}</td><td>${r.needBy?fmt(r.needBy):'—'}</td><td class="small">${r.lead?r.lead+' d':'—'}</td><td>${r.vendor?esc(r.vendor):'<span class="pill warn">none</span>'}</td><td class="money">${r.price?money(r.price):'<span class="pill warn">unpriced</span>'}${r.budget&&r.kind==='material'?`<div class="small muted">budget ${money(r.budget)}</div>`:''}</td><td class="money">${r.held?money(r.held):'—'}</td><td class="small ${r.sev===3?'bad':r.sev===2?'warn':''}">${r.ordered?(r.po?esc(r.po.number)+' · ':'')+esc(r.why):esc(r.why||'ready to order')}</td><td>${act}</td></tr>`; }).join('')||`<tr><td colspan="11" class="muted">${rows.length?'Nothing red or amber — everything is ordered and on time.':'Nothing to buy.'}</td></tr>`}</tbody></table></div>
    <p class="small muted">Order-by = the task's start (or end, for finish items) − lead time − the job's material buffer. Contract lines appear when budget is left and no PO exists; they date from the first open task of that trade. Client funds = money already collected for the line and not yet spent.</p>`;
  host.querySelectorAll('[data-buyscope]').forEach(b => b.onclick = () => { buyScope = b.dataset.buyscope; render(); }); $('#buy-toggle')?.addEventListener('click', () => { buyOpen = !buyOpen; render(); });
  host.querySelectorAll('[data-buy]').forEach(b => b.onclick = () => { const [k, pid, a, key, mid] = b.dataset.buy.split('|'); const p = DB.projects.find(x=>x.id===pid); if (!p) return; if (S.id!==p.id) setCurrent(p.id); if (k==='recv'){ view = 'recv'; render(); return; } if (k==='dec'){ view = 'dec'; render(); return; } if (k==='po'){ if (key) ctPOPicker(p.id, a||undefined, key); else if (mid){ openEditor('mat', mid); toast('Link an estimate line or set vendor and cost, then create the PO'); } else ctPOPicker(p.id); } });
  host.querySelectorAll('[data-buyeta]').forEach(i => i.onchange = () => { const [pid, mid] = i.dataset.buyeta.split(':'); const p = DB.projects.find(x=>x.id===pid); const m = p?.materials.find(x=>x.id===mid); if (m){ m.eta = i.value; if (m.status==='not-ordered') m.status = 'ordered'; const po = DB.pos.find(po => po.projectId===p.id && po.lines.some(l=>l.materialId===m.id)); if (po && !po.expected) po.expected = i.value; save(); render(); } }); }
/* PO money: deposit schedule, billed vs paid, next due */
function poBilled(po){ return r2(DB.bills.filter(b => b.poId===po.id && !['void','rejected'].includes(b.status)).reduce((a,b)=>a+billGross(b),0)); }
function poNextDue(po){ const tot = poTotal(po).total; const paid = poPaid(po); const s = po.schedule || (po.depositPct ? [{pct:+po.depositPct, trigger:'on order'}, {pct:100-(+po.depositPct), trigger:'on delivery'}] : null); if (!s || !tot) return {amount:Math.max(0, tot - paid), when:po.expected||'', label:'balance'}; let cum = 0; for (const step of s){ cum += tot*step.pct/100; if (paid < cum - 1){ const when = step.trigger==='on order' ? (po.date||today()) : step.trigger==='on delivery' ? (po.receivedOn || po.expected || '') : (po.receivedOn ? iso(addDays(po.receivedOn, +step.days||30)) : ''); return {amount:r2(cum - paid), when, label:`${step.pct}% ${step.trigger}${step.days?' net '+step.days:''}`}; } } return {amount:0, when:'', label:'paid'}; }
function poMoneyHtml(po){ const tot = poTotal(po).total, billed = poBilled(po), paid = poPaid(po); const nd = poNextDue(po); const s = po.schedule || (po.depositPct ? [{pct:+po.depositPct, trigger:'on order'}, {pct:100-(+po.depositPct), trigger:'on delivery'}] : [{pct:100, trigger:'on delivery'}]); const ed = po.status!=='cancelled' && !['client','crew','driver'].includes(role());
  return `<div class="card po-money"><div class="row" style="align-items:baseline"><h3 style="margin:0">Accounting</h3><span class="grow"></span>${ed?`<button class="btn sm" data-posched>Payment terms…</button>`:''}</div><div class="cash-grid" style="grid-template-columns:repeat(4,1fr)"><div><span>Ordered</span><b>${money(tot)}</b></div><div><span>Billed</span><b>${money(billed)}</b><i>${DB.bills.filter(b=>b.poId===po.id&&!['void','rejected'].includes(b.status)).map(b=>esc(b.number)).join(', ')||'no bill yet'}</i></div><div><span>Paid</span><b>${money(paid)}</b></div><div><span>Next due</span><b class="${nd.amount&&nd.when&&nd.when<today()?'bad':''}">${nd.amount?money(nd.amount):'—'}</b><i>${nd.amount?`${nd.label}${nd.when?' · '+fmt(nd.when):''}`:'nothing due'}</i></div></div><div class="small muted">Terms: ${s.map(x=>`${x.pct}% ${x.trigger}${x.days?' net '+x.days:''}`).join(' · ')}${po.needBy?` · needed on site ${fmt(po.needBy)}`:''}${billed > tot*1.02+1?` · <b class="bad">billed ${money(billed-tot)} over the PO</b>`:''}</div></div>`; }
function poTermsDialog(po){ const s = po.schedule || (po.depositPct ? [{pct:+po.depositPct, trigger:'on order'}, {pct:100-(+po.depositPct), trigger:'on delivery'}] : [{pct:100, trigger:'on delivery'}]); mbModal(`Payment terms — ${esc(po.number)}`, `<p class="small muted">When the vendor gets paid. The balance due and the cash forecast follow this.</p><div class="f2"><label class="f"><span>Deposit % on order</span><input type="number" id="pt-dep" min="0" max="100" value="${s.find(x=>x.trigger==='on order')?.pct||0}"></label><label class="f"><span>Balance</span><select id="pt-bal"><option value="on delivery" ${s.some(x=>x.trigger==='on delivery')?'selected':''}>on delivery</option><option value="net" ${s.some(x=>x.trigger==='net')?'selected':''}>net days after delivery</option></select></label></div><label class="f"><span>Net days (if net)</span><input type="number" id="pt-days" value="${s.find(x=>x.trigger==='net')?.days||30}"></label>`, {submit:'Save', onSubmit:()=>{ const dep = Math.max(0, Math.min(100, +$('#pt-dep').value||0)); const bal = $('#pt-bal').value; const days = +$('#pt-days').value||30; po.schedule = [...(dep?[{pct:dep, trigger:'on order'}]:[]), {pct:100-dep, trigger:bal, days:bal==='net'?days:0}]; po.depositPct = dep; save(); render(); }}); }
const renderPODocBase = renderPODoc;
renderPODoc = function(po){ const h = renderPODocBase(po); const need = po.needBy ? `<div class="note ${po.expected && po.expected > po.needBy ? 'warn':''}" style="margin:0 0 10px">Needed on site ${fmt(po.needBy)}${po.needTask?` for ${esc(po.needTask)}`:''}${po.expected && po.expected > po.needBy ? ` — expected ${fmt(po.expected)} is <b>after</b> the need date` : ''}</div>` : ''; return need + h + poMoneyHtml(po); };
const wirePODocBase = wirePODoc;
wirePODoc = function(po){ wirePODocBase(po); document.querySelector('[data-posched]')?.addEventListener('click', () => poTermsDialog(po)); };
const poStateBase = poState;
poState = function(po){ const st = poStateBase(po); if (po.needBy && po.expected && po.expected > po.needBy && ['issued','partial'].includes(po.status)){ st.flags.push(`expected ${fmt(po.expected)} after need-by ${fmt(po.needBy)}`); st.sev = 3; st.msg = st.msg && st.msg!=='OK' ? st.msg : 'late for the schedule'; } return st; };
/* picker → PO carries the need date; matched materials link to the PO */
const ctPOPickerBase = ctPOPicker;
ctPOPicker = function(projectId, preferId, preKey){ const before = new Set(DB.pos.map(x=>x.id)); ctPOPickerBase(projectId, preferId, preKey); const ok = document.querySelector('#mbm-ok'); if (!ok) return; ok.addEventListener('click', () => { setTimeout(() => { const p = DB.projects.find(x=>x.id===projectId) || S; DB.pos.filter(x => !before.has(x.id)).forEach(po => { let need = '', needTask = ''; po.lines.forEach(l => { const m = p.materials.find(mm => mm.line===l.line || (!mm.line && normItem(mm.name)===normItem(l.item))); if (m){ l.materialId = m.id; if (!m.line && l.line) m.line = l.line; if (!m.vendor) m.vendor = po.vendor; const {needBy} = withProject(p, () => matDates(m)); if (needBy && (!need || needBy < need)){ need = needBy; needTask = task(m.taskId)?.name || ''; } } else if (l.line){ const ref = findLine(l.line); const nb = ref ? lineNeedBy(p, ref.line) : {needBy:''}; if (nb.needBy && (!need || nb.needBy < need)){ need = nb.needBy; needTask = nb.task?.name||''; } } }); if (need){ po.needBy = need; po.needTask = needTask; if (!po.expected) po.expected = need; } const v = DB.vendors.find(x=>x.name.toLowerCase()===po.vendor.toLowerCase()); if (v && v.depositPct && !po.schedule) po.depositPct = v.depositPct; }); save(); render(); }, 50); }, {once:true}); };
/* issuing a PO marks its materials ordered */
const poActionBase = poAction;
poAction = function(po, a){ const r = poActionBase(po, a); if (a==='issue'){ const p = DB.projects.find(x=>x.id===po.projectId); if (p) po.lines.forEach(l => { const m = l.materialId && p.materials.find(mm=>mm.id===l.materialId); if (m && ['needs-decision','not-ordered','quoted'].includes(m.status)){ m.status = 'ordered'; m.po = po.number; if (po.expected) m.eta = po.expected; } }); save(); } return r; };
/* Purchasing view hosts the board */
const renderPOsBase = renderPOs;
renderPOs = function(){ renderPOsBase(); let host = $('#buy-board'); if (!host){ host = document.createElement('div'); host.id = 'buy-board'; $('#po-kpis')?.before(host); } renderBuyBoard(); const hide = !!poOpen; ['#po-kpis','#po-funds'].forEach(s => { const el = $(s); if (el) el.style.display = hide ? 'none' : ''; }); };
/* buying reaches Home */
const remindersBase6 = reminders;
reminders = function(){ const out = remindersBase6(); const rows = buyList(''); const td = today(); const late = rows.filter(r => r.sev===3 && !r.ordered); const eta = rows.filter(r => r.sev===3 && r.ordered); const week = rows.filter(r => !r.ordered && r.orderBy && r.orderBy >= td && wd(td, r.orderBy) <= 5); const blocked = rows.filter(r => r.dec && r.orderBy && wd(td, r.orderBy) <= 10); const dueSoon = DB.pos.filter(po => ['issued','partial'].includes(po.status) && po.expected && dayDiff(td, po.expected) <= 1 && dayDiff(td, po.expected) >= 0); const deposits = DB.pos.filter(po => ['issued','partial'].includes(po.status)).map(po => ({po, nd:poNextDue(po)})).filter(x => x.nd.amount && x.nd.when && dayDiff(td, x.nd.when) <= 7);
  if (late.length) out.unshift({n:late.length, label:`item${late.length>1?'s':''} past order-by, not ordered — ${late.slice(0,2).map(r=>r.name).join(', ')}${late.length>2?'…':''}`, go:{view:'po', buy:true}, sev:'bad'}); if (eta.length) out.push({n:eta.length, label:`delivery${eta.length>1?'ies':''} arriving after the schedule needs ${eta.length>1?'them':'it'}`, go:{view:'po', buy:true}, sev:'bad'}); if (week.length) out.push({n:week.length, label:`to order this week${week.reduce((a,r)=>a+r.price,0)?' · '+money(week.reduce((a,r)=>a+r.price,0)):''}`, go:{view:'po', buy:true}, sev:'warn'}); if (blocked.length) out.push({n:blocked.length, label:`order${blocked.length>1?'s':''} blocked by a client decision due within 10 days`, go:{view:'po', buy:true}, sev:'warn'}); if (dueSoon.length) out.push({n:dueSoon.length, label:`deliver${dueSoon.length>1?'ies':'y'} expected today or tomorrow`, go:{view:'recv'}, sev:''}); if (deposits.length) out.push({n:deposits.length, label:`vendor deposit${deposits.length>1?'s':''} / balance${deposits.length>1?'s':''} due within 7 days · ${money(deposits.reduce((a,x)=>a+x.nd.amount,0))}`, go:{view:'po'}, sev:'warn'}); return out; };
document.addEventListener('click', e => { const el = e.target.closest('[data-remgo]'); if (!el) return; try { const go = JSON.parse(el.dataset.remgo); if (go.buy){ buyScope = ''; buyOpen = false; poOpen = null; } } catch(err){} }, true);
const ptJobsBase2 = ptJobs;
ptJobs = function(){ let h = ptJobsBase2(); DB.projects.forEach(p => { const rows = buyList(p.id); const late = rows.filter(r=>r.sev===3).length, week = rows.filter(r=>r.sev===2).length; if (!late && !week) return; const marker = `data-jobgo="${p.id}"`; const flag = `${late?`<i class="bad">${late} buying late</i>`:''}${week?`<i class="warn">${week} to order / unpriced</i>`:''}`; h = h.replace(new RegExp(`(<div class="jobcard" ${marker}>[\\s\\S]*?<div class="jc-flags">)`), `$1${flag}`); }); return h; };
Object.assign(PORTLETS, {buyboard:'Buy board'});
const renderPortletBase2 = renderPortlet;
renderPortlet = function(p){ if (p.type==='buyboard'){ const rows = buyList('').filter(r => r.sev >= 2).slice(0, 8); return `<div class="rem">${rows.map(r => `<div class="rem-row ${r.sev===3?'bad':'warn'}" data-remgo='{"view":"po","buy":true}'><b>${r.orderBy?fmt(r.orderBy):'·'}</b><span><b>${esc(r.name)}</b><br><span class="small muted">${esc(r.p.project.name.replace(/ —.*$/,''))} · ${esc(r.why)}${r.vendor?' · '+esc(r.vendor):''}</span></span></div>`).join('')||'<div class="muted small">Nothing red or amber on the buy board.</div>'}</div>`; } return renderPortletBase2(p); };
ROLE_HOME.coord = {layout:2, portlets:[{type:'needsme'}, {type:'buyboard'}, {type:'jobcards'}, {type:'shortcuts'}]};
/* vendors: performance, not only compliance */
function vendorPerf(v){ const n = v.name.toLowerCase(); const pos = DB.pos.filter(po => po.vendor.toLowerCase()===n && !['cancelled','draft'].includes(po.status)); const done = pos.filter(po => po.receivedOn && po.expected); const onTime = done.length ? Math.round(done.filter(po => po.receivedOn <= po.expected).length/done.length*100) : null; const leads = done.map(po => dayDiff(po.date, po.receivedOn)).filter(x=>x>=0); const avgLead = leads.length ? Math.round(leads.reduce((a,b)=>a+b,0)/leads.length) : null; const billed = pos.reduce((a,po)=>a+poBilled(po),0), ordered = pos.reduce((a,po)=>a+poTotal(po).total,0); const variance = ordered && billed ? r2((billed/ordered-1)*100) : null; const open = r2(pos.filter(po=>['issued','partial'].includes(po.status)).reduce((a,po)=>a+Math.max(0,poTotal(po).total-poBilled(po)),0)); return {pos:pos.length, onTime, avgLead, variance, open, last:pos.map(po=>po.date).sort().pop()||''}; }
const renderVendorsBase = renderVendors;
renderVendors = function(){ renderVendorsBase(); const tb = document.querySelector('#vend-table table'); if (!tb) return; const hr = tb.querySelector('thead tr'); if (!hr || hr.querySelector('.vp')) return; ['Open POs','On time','Avg lead','Bill vs PO'].forEach(l => { const th = document.createElement('th'); th.className = 'vp money'; th.textContent = l; hr.appendChild(th); }); tb.querySelectorAll('tbody tr').forEach(tr => { const id = tr.dataset.id || (tr.dataset.edit||'').split(':')[1]; const v = DB.vendors.find(x=>x.id===id) || DB.vendors.find(x => tr.textContent.includes(x.name)); if (!v) return; const P = vendorPerf(v); [P.open?money(P.open):'—', P.onTime!=null?P.onTime+'%':'—', P.avgLead!=null?P.avgLead+' d':'—', P.variance!=null?(P.variance>0?'+':'')+P.variance+'%':'—'].forEach((t,i) => { const td = document.createElement('td'); td.className = 'money vp' + (i===1 && P.onTime!=null && P.onTime<80 ? ' bad' : i===3 && P.variance>5 ? ' bad' : ''); td.textContent = t; tr.appendChild(td); }); }); };
/* deliveries: every job, by urgency */
let recvAll = false;
const renderRecvBase = renderRecv;
renderRecv = function(){ if (!recvAll){ renderRecvBase(); const root = $('#recv-body'); const ph = root?.querySelector('.ph .acts') || root?.querySelector('.ph'); if (ph && !root.querySelector('#recv-all')){ const b = document.createElement('button'); b.className = 'btn sm'; b.id = 'recv-all'; b.textContent = 'All projects'; b.onclick = () => { recvAll = true; render(); }; ph.appendChild(b); } return; }
  const root = $('#recv-body'); const td = today(); const pos = DB.pos.filter(po => ['issued','partial'].includes(po.status)).map(po => ({po, p:DB.projects.find(x=>x.id===po.projectId), d:po.expected ? dayDiff(td, po.expected) : null})); const groups = [['Late', x => x.d!=null && x.d < 0], ['Today', x => x.d===0], ['Tomorrow', x => x.d===1], ['This week', x => x.d!=null && x.d > 1 && x.d <= 7], ['Later / no date', x => x.d==null || x.d > 7]];
  root.innerHTML = `<div class="ph"><div><h2>Deliveries — all projects</h2><p class="lead">What is coming, in the order it matters.</p></div><div class="acts"><button class="btn sm" id="recv-one">This job only</button></div></div>${groups.map(([g, f]) => { const list = pos.filter(f); if (!list.length) return ''; return `<h3 class="rep-h">${g} <span class="small muted">${list.length}</span></h3>${list.map(({po, p}) => `<div class="card recv-po click" data-recvgo="${po.projectId}"><div class="row" style="align-items:baseline"><b>${esc(po.vendor)}</b><span class="small muted">${esc(po.number)} · ${esc(p?.project.name||'')}${po.needBy?` · needed ${fmt(po.needBy)}`:''}</span><span class="grow"></span><span class="small ${g==='Late'?'bad':''}">${po.expected?fmt(po.expected):'no date'}</span></div><div class="small muted">${po.lines.map(l=>esc(l.item||l.desc||'')).join(', ')}</div></div>`).join('')}`; }).join('')||'<div class="card muted">Nothing on order.</div>'}`;
  $('#recv-one').onclick = () => { recvAll = false; render(); }; root.querySelectorAll('[data-recvgo]').forEach(el => el.onclick = () => { recvAll = false; setCurrent(el.dataset.recvgo); render(); }); };

/* ===================== ONE REPORT FRAME — one period, one comparison, one entity, on every tab ===================== */
const REP = {preset:'ty', from:'', to:'', compare:'prev'};
const REP_PRESETS = [['tm','This month'],['lm','Last month'],['tq','This quarter'],['ty','Year to date'],['l12','Last 12 months'],['all','All time'],['custom','Custom']];
const REP_COMPARES = [['prev','Prior period'],['ly','Same period last year'],['budget','Budget'],['none','None']];
function repRangeOf(){ const t = today(); const d = new Date(t+'T00:00:00'); const y = d.getFullYear(), m = d.getMonth(); const S1 = (yy,mm) => iso(new Date(yy,mm,1)), E1 = (yy,mm) => iso(new Date(yy,mm+1,0)); const k = REP.preset;
  if (k==='tm') return {range:[S1(y,m), t], label:'This month', buckets:'week'}; if (k==='lm') return {range:[S1(y,m-1), E1(y,m-1)], label:'Last month', buckets:'week'}; if (k==='tq') return {range:[S1(y, Math.floor(m/3)*3), t], label:'This quarter', buckets:'month'}; if (k==='ty') return {range:[`${y}-01-01`, t], label:'Year to date', buckets:'month'}; if (k==='l12') return {range:[S1(y, m-11), t], label:'Last 12 months', buckets:'month'}; if (k==='custom') return {range:[REP.from||`${y}-01-01`, REP.to||t], label:'Custom', buckets:'month'}; const all = [...DB.txns.map(x=>x.date), ...DB.clients.flatMap(c=>c.invoices.map(i=>i.date))].filter(Boolean).sort(); return {range:[all[0]||`${y}-01-01`, t], label:'All time', buckets:'quarter'}; }
function repPriorRange(){ const {range:[a, b]} = repRangeOf(); if (REP.compare==='none' || REP.compare==='budget') return null; const A = parse(a), B = parse(b); if (REP.compare==='ly'){ return [iso(new Date(A.getFullYear()-1, A.getMonth(), A.getDate())), iso(new Date(B.getFullYear()-1, B.getMonth(), B.getDate()))]; } if (REP.preset==='tm'){ const pa = new Date(A.getFullYear(), A.getMonth()-1, 1); const pb = new Date(pa.getFullYear(), pa.getMonth(), Math.min(B.getDate(), new Date(pa.getFullYear(), pa.getMonth()+1, 0).getDate())); return [iso(pa), iso(pb)]; } if (REP.preset==='ty'){ return [iso(new Date(A.getFullYear()-1, 0, 1)), iso(new Date(B.getFullYear()-1, B.getMonth(), B.getDate()))]; } const len = Math.round((B-A)/86400000)+1; const pb = addDays(A, -1), pa = addDays(pb, -(len-1)); return [iso(pa), iso(pb)]; }
function repCompareLabel(){ const P = repPriorRange(); if (!P) return REP.compare==='budget' ? 'vs budget' : ''; return `vs ${fmt(P[0])} – ${fmt(P[1])}${P[0].slice(0,4)!==today().slice(0,4)?' '+P[0].slice(0,4):''}`; }
function repSync(){ const {range} = repRangeOf(); repFrom = range[0]; repTo = range[1]; cfoPeriod = {tm:'month', tq:'quarter', ty:'ytd', all:'all'}[REP.preset] || 'custom'; dashPeriod = {tm:'month', tq:'quarter', ty:'year', all:'all'}[REP.preset] || '6m'; budgetYear = range[0].slice(0,4); }
/* the legacy range helpers now read the shared frame */
cfoRange = function(){ return repRangeOf().range; };
dashRange = function(){ const R = repRangeOf(); return {from:R.range[0], to:R.range[1], buckets:R.buckets, label:R.label}; };
dashPrior = function(R){ return repPriorRange() || [R.from, R.to]; };
kpiCompareRange = (function(base){ return function(key, cmp){ if (typeof key==='object') return repPriorRange(); return base(key, cmp); }; })(kpiCompareRange);
const repBarV2Base = repBarV2;
repBarV2 = function(projs){ const h = repBarV2Base(projs); const R = repRangeOf(); const bar = `<div class="rep-bar no-print rep-frame"><div class="seg sm">${REP_PRESETS.map(([k,l]) => `<button class="${REP.preset===k?'on':''}" data-repp="${k}">${l}</button>`).join('')}</div>${REP.preset==='custom'?`<label class="small">From <input type="date" id="repf-from" value="${REP.from}"></label><label class="small">To <input type="date" id="repf-to" value="${REP.to}"></label>`:''}<label class="small">Compare <select id="repf-cmp" class="btn sm">${REP_COMPARES.map(([k,l]) => `<option value="${k}" ${REP.compare===k?'selected':''}>${l}</option>`).join('')}</select></label>${entityBar()}</div><div class="small muted rep-line">${R.label} · ${fmtL(R.range[0])} → ${fmtL(R.range[1])}${repCompareLabel()?' · '+repCompareLabel():''} · ${entName(repEntity)}</div>`;
  return h.replace(/<button class="btn" id="rep-print">/, `</div>${bar}<div class="rep-bar no-print" style="margin-top:0"><span class="grow"></span><button class="btn" id="rep-print">`).replace(/<label class="small">From <input type="date" id="rep-from"[\s\S]*?id="rep-to" value="[^"]*"><\/label>/, ''); };
const renderReportsBase7 = renderReports;
renderReports = function(){ repSync(); renderReportsBase7(); const root = $('#rep-body'); if (!root) return; root.querySelectorAll('#rep-print-area .seg.no-print').forEach(seg => { if (seg.querySelector('[data-cfop],[data-dashp]')) seg.remove(); }); root.querySelectorAll('#rep-print-area .ent-bar').forEach(e => e.remove()); root.querySelectorAll('#rep-print-area #bud-year').forEach(e => e.remove());
  root.querySelectorAll('[data-repp]').forEach(b => b.onclick = () => { REP.preset = b.dataset.repp; if (REP.preset==='custom' && !REP.from){ const {range} = repRangeOf(); REP.from = range[0]; REP.to = range[1]; } render(); }); $('#repf-from')?.addEventListener('change', e => { REP.from = e.target.value; render(); }); $('#repf-to')?.addEventListener('change', e => { REP.to = e.target.value; render(); }); $('#repf-cmp')?.addEventListener('change', e => { REP.compare = e.target.value; render(); }); root.querySelectorAll('.rep-frame [data-ent]').forEach(b => b.onclick = () => { repEntity = b.dataset.ent; render(); }); };

/* ===================== HOME v3 — a decision sheet: Today strip · Decide / Approve / Watch · job cards that say why ===================== */
function safeToSpend(){ const B = companyBalance(); const F = cashForecast(); return {B, F, safe:r2(Math.min(B.trulyOurs, F.low)), low:F.low}; }
function biggestReceivable(){ let best = null; DB.clients.forEach(c => clientFin(c).open.forEach(o => { if (!best || o.bal > best.bal) best = {c, o, bal:o.bal}; })); return best; }
function worstJob(){ let w = null; DB.projects.forEach(p => { const J = jobFin(p); if (!J.contract) return; const h = projectHealth(p); const fade = J.plannedGPPct ? r2(J.estGPPct - J.plannedGPPct) : 0; const over = J.byCode.filter(x => x.budget && x.actual > x.budget).sort((a,b)=>(b.actual-b.budget)-(a.actual-a.budget))[0]; const score = (h.health?.score??70) - Math.max(0,-fade)*5; if (!w || score < w.score) w = {p, J, h, fade, over, score}; }); return w; }
function ptToday(){ const {B, safe, low} = safeToSpend(); const R = biggestReceivable(); const W = worstJob(); const cur = currentUser(); const phone = (c) => c?.contacts?.find(x=>x.primary)?.phone || c?.contacts?.[0]?.phone || '';
  return `<div class="today"><div class="today-c ${safe<0?'bad':safe<B.payrollAccrued?'warn':''}"><span>Safe to spend</span><b>${money(safe)}</b><i>truly ours ${money(B.trulyOurs)} · 13-week low ${money(low)}</i></div><div class="today-c"><span>Biggest receivable</span><b>${R?money(R.bal):'—'}</b><i>${R?`${esc(R.c.name)} · ${esc(R.o.x.number)} · ${R.o.age>0?`<span class="bad">${R.o.age} d overdue</span>`:'due '+fmt(R.o.x.due)}${phone(R.c)?` · <a href="tel:${esc(phone(R.c))}">call</a>`:''}`:'nothing open'}</i></div><div class="today-c ${W&&(W.fade<-1||W.h.late>0)?'warn':''}"><span>Job to watch</span><b>${W?esc(W.p.project.name.replace(/ —.*$/,'')):'—'}</b><i>${W?[W.fade<0?`GP ${W.J.estGPPct}% vs bid ${W.J.plannedGPPct}%`:'', W.over?`${esc(W.over.name)} +${money(W.over.actual-W.over.budget)}`:'', W.h.late>0?`${W.h.late} d late`:'', W.h.health?.why?.[0]?esc(W.h.health.why[0]):''].filter(Boolean).slice(0,2).join(' · ')||'on track':''}</i></div></div>`; }
function bandOf(r){ if (r.sev==='bill' || /client asked|override|analyst|margin|DSCR|over the PO|more than the PO|duplicate|before approval|floating|unsigned|awaiting client|with the client|bank change|banking changed/i.test(r.title||r.label||'')) return 'decide'; if (/approv|awaiting|draft|sheets|to bill|intercompany|waiver|release|confirm or reject/i.test(r.title||r.label||'')) return 'approve'; return 'watch'; }
const dollars = r => { const m = String(r.n||'').match(/\$([\d,]+)/) || String(r.title||'').match(/\$([\d,]+)/); return m ? +m[1].replace(/,/g,'') : 0; };
const needsMeBase = needsMe;
needsMe = function(){ const rows = needsMeBase().map(r => Object.assign(r, {band: r.go?.own ? 'watch' : bandOf(r), amt: dollars(r)})); const order = {decide:0, approve:1, watch:2}; const sevOrder = s => s==='bad'?0:s==='bill'?1:s==='warn'?2:3; return rows.sort((a,b) => order[a.band]-order[b.band] || sevOrder(a.sev)-sevOrder(b.sev) || b.amt-a.amt); };
const ptNeedsMeBase = ptNeedsMe;
ptNeedsMe = function(){ const rows = needsMe(); const mobile = window.innerWidth < 700; const cap = needsAll ? 999 : (mobile ? 6 : 12); const bands = [['decide','Decide'],['approve','Approve'],['watch','Watch']]; let shown = 0;
  return `<div class="nm-sum small muted">${rows.length ? `${rows.filter(r=>r.band==='decide').length} to decide · ${rows.filter(r=>r.band==='approve').length} to approve · ${rows.filter(r=>r.band==='watch').length} to watch` : 'Nothing waiting on you.'}</div>${bands.map(([k,l]) => { const list = rows.filter(r=>r.band===k); if (!list.length) return ''; const vis = list.slice(0, Math.max(0, cap - shown)); shown += vis.length; if (!vis.length) return `<div class="nm-band"><h4>${l} <span class="muted">${list.length}</span></h4></div>`; return `<div class="nm-band"><h4>${l} <span class="muted">${list.length}</span></h4><div class="rem nm">${vis.map(r => `<div class="rem-row ${r.sev}" data-remgo='${esc(JSON.stringify(r.go))}'><b>${esc(String(r.n||'·'))}</b><span><b>${esc(r.title)}</b>${r.detail?`<br><span class="small muted">${r.detail}</span>`:''}</span><em class="nm-act">${r.action} ›</em></div>`).join('')}</div></div>`; }).join('')}${rows.length>cap?`<button class="btn sm" data-nmall>${needsAll?'Show fewer':`Show all ${rows.length}`}</button>`:''}`; };
/* job cards say why */
const ptJobsBase3 = ptJobs;
ptJobs = function(){ let h = ptJobsBase3(); DB.projects.forEach(p => { const J = jobFin(p); if (!J.contract) return; const over = J.byCode.filter(x => x.budget && x.actual > x.budget*1.05).sort((a,b)=>(b.actual-b.budget)-(a.actual-a.budget)).slice(0,2); const c = DB.clients.find(x=>x.id===p.clientId); const ct = c?.contacts?.find(x=>x.primary)||c?.contacts?.[0]; const marker = `data-jobgo="${p.id}"`; const extra = `${over.map(o => `<i class="bad">${esc(o.name.split(',')[0])} +${money(o.actual-o.budget)}</i>`).join('')}${J.accrued?'':''}`; const who = `<div class="jc-who small muted">${p.project.pm?`PM ${esc(p.project.pm)} · `:''}${c?esc(c.name):''}${ct?.phone?` · <a href="tel:${esc(ct.phone)}" onclick="event.stopPropagation()">${esc(ct.phone)}</a>`:''}</div>`; h = h.replace(new RegExp(`(<div class="jobcard" ${marker}>[\\s\\S]*?<div class="jc-flags">)([\\s\\S]*?)(</div></div>)`), (m0, a, flags, z) => a + extra + flags.replace('<i class="ok">on track</i>', extra?'':'<i class="ok">on track</i>') + '</div>' + who + '</div>'); }); return h; };
/* cash block: one answer */
ptCash = function(){ const {B, F, safe} = safeToSpend(); const lowWk = F.weeks.reduce((a,w) => w.balance < a.balance ? w : a, F.weeks[0]);
  return `<div class="cashb"><div class="cash-row"><span>In the bank (book)</span><b>${money(B.cash)}</b></div>${B.undeposited?`<div class="cash-row dim"><span>+ receipts not yet deposited</span><b>${money(B.undeposited)}</b></div>`:''}<div class="cash-row dim"><span>− credit cards</span><b>${money(-B.cards)}</b></div><div class="cash-row dim"><span>− unpaid bills</span><b>${money(B.ap)}</b></div>${B.payrollAccrued?`<div class="cash-row dim"><span>− payroll due</span><b>${money(B.payrollAccrued)}</b></div>`:''}<div class="cash-row"><span>Cash today</span><b>${money(B.cashToday)}</b></div><div class="cash-row dim"><span>− billed ahead of work (client money for work not done)</span><b>${money(B.over)}</b></div><div class="cash-row big ${B.trulyOurs<0?'bad':''}"><span>Truly ours</span><b>${money(B.trulyOurs)}</b></div>
    <div class="cash-grid"><div><span>Safe to spend</span><b class="${safe<0?'bad':''}">${money(safe)}</b><i>lower of truly ours and the 13-week low</i></div><div><span>13-week low</span><b class="${F.low<0?'bad':''}">${money(F.low)}</b><i>week of ${fmt(lowWk.start)}</i></div><div><span>Owed to us</span><b>${money(B.arOut)}</b><i class="${B.arOver?'bad':''}">${B.arOver?money(B.arOver)+' overdue':'nothing overdue'}</i></div><div><span>Held for purchases</span><b>${money(B.clientFunds)}</b><i>of the billed-ahead amount, still to buy</i></div></div>
    <div class="small muted">${METRIC_DEFS.cashToday} ${METRIC_DEFS.trulyOurs} ${METRIC_DEFS.safe}${B.paidBeforeApproval.length?` <b class="bad">${B.paidBeforeApproval.length} bill${B.paidBeforeApproval.length>1?'s':''} paid before approval — see Money.</b>`:''}</div></div>`; };
Object.assign(PORTLETS, {today:'Today strip'});
const renderPortletBase3 = renderPortlet;
renderPortlet = function(p){ if (p.type==='today') return ptToday(); return renderPortletBase3(p); };
ROLE_HOME.owner = {layout:2, portlets:[{type:'today'}, {type:'needsme'}, {type:'cashblock'}, {type:'jobcards'}, {type:'monthcompare'}, {type:'chart', cfg:{period:'6m'}}, {type:'shortcuts'}]};
ROLE_HOME.pm = {layout:2, portlets:[{type:'needsme'}, {type:'jobcards'}, {type:'buyboard'}, {type:'kpi', cfg:{kpis:['backlog','committed','billsPending','hours','cosApproved'], range:'tm', cmp:'prev', hl:{}}}, {type:'shortcuts'}]};
const homeDefBase2 = homeDef;
homeDef = function(){ const r = role(); DB.dashboards = DB.dashboards||{}; if (DB.dashboards[r] && !(DB.dashboards[r].v>=3) && (DB.published||{})[r]?.lock!=='locked') delete DB.dashboards[r]; const H = homeDefBase2(); H.v = 3; return H; };
const renderHomeBase3 = renderHome;
renderHome = function(){ renderHomeBase3(); const root = homeRoot(); root.querySelectorAll('.portlet').forEach(el => { const t = homeDef().portlets.find(p => p.id===el.dataset.pt)?.type; if (t==='today'){ el.classList.add('wide'); if (!homeEdit) el.classList.add('today-pt'); } }); const tb = document.querySelector('.topbar .stat'); };
/* the top bar names the project it is talking about */
const renderBaseTop = render;
render = function(){ renderBaseTop(); const st = document.querySelector('.topbar .stat, .topbar .stats'); if (st && S && !MB_VIEWS.includes(view) && !['home','port','clients','reports','bank','ap','verify','vendors','inv','time','req','route','recv'].includes(view)){ if (!st.querySelector('.stat-proj')){ const s = document.createElement('div'); s.className = 'stat-proj small muted'; st.prepend(s); } st.querySelector('.stat-proj').textContent = S.project.name; } else if (st){ st.querySelector('.stat-proj')?.remove(); } };

const remindersBase7 = reminders;
reminders = function(){ const out = remindersBase7(); const pb = DB.bills.filter(b => b.paidBeforeApproval && !['paid','verified','void','rejected'].includes(b.status)); if (pb.length) out.unshift({n:money(pb.reduce((a,b)=>a+billTotal(b),0)), label:`bill${pb.length>1?'s':''} paid from the bank before approval — ${pb.map(b=>b.vendor).join(', ')}: approve as billed or dispute`, go:{view:'ap'}, sev:'bad'}); return out; };

/* ===================== BILLING (panel round 2) — pay application · one deposit model · receivables · contracts per job ===================== */
/* Pay application: every SOV invoice shows, per line, % complete to date and this-period $ (either input drives the other), and a G702-style summary: original contract, approved changes, revised contract, completed to date, retainage to date, less previous applications, less deposit applied, current payment due.
   One deposit model: a deposit is money on account (an items invoice tagged depositOf). It never marks SOV lines as billed. Each progress invoice applies part of it ("Less deposit applied"), by default the deposit's share of this period's work.
   Receivables: one screen for every open invoice across clients — aging, promise-to-pay, last contact — and payments that can cover several invoices with the remainder left on account.
   Contracts per job: converting an estimate records the contract for its project; a client with two jobs has two contracts and two schedules of values. */
function depositBalance(c, estId){ const paid = c.invoices.filter(i => i.depositOf===estId && i.mode!=='sov' && i.status!=='void').reduce((a,i)=>a+invoicePaid(c, i),0); const applied = c.invoices.filter(i => i.status!=='void' && i.mode==='sov' && (+i.depositApplied||0) && (!estId || i.depositOf===estId || !i.depositOf)).reduce((a,i)=>a+(+i.depositApplied||0),0); return r2(paid - applied); }
function depositPctOf(c, estId){ const d = estId && findDoc(c, 'estimate', estId); const dep = c.invoices.filter(i => i.depositOf===estId && i.mode!=='sov' && i.status!=='void').reduce((a,i)=>a+docTotal(i).total,0); const base = d ? docNet(d) : 0; return base ? Math.min(100, r2(dep/base*100)) : 0; }
const docTotalBase = docTotal;
docTotal = function(d){ const t = docTotalBase(d); const dep = d.type==='invoice' && d.mode==='sov' ? r2(+d.depositApplied||0) : 0; if (dep){ t.dep = dep; t.total = r2(t.total - dep); } return t; };
docNet = d => { const t = docTotal(d); return r2(t.sub - t.disc - (t.dep||0)); };
/* deposit invoice: on account, not against lines */
ctDepositInvoice = function(c, d){ const base = docNet(d); const pct = +DB.company.depositPct||30; const already = c.invoices.filter(i => i.depositOf===d.id && i.status!=='void').reduce((a,i)=>a+docTotal(i).total,0);
  mbModal(`Deposit — ${esc(d.number)}`, `<p class="small muted">A deposit is money on account. It is applied against progress invoices as work is billed, so the schedule of values only ever shows work done.${already?` Already invoiced: ${money(already)}.`:''}</p><div class="f2"><label class="f"><span>Deposit %</span><input id="dep-pct" type="number" min="0" max="100" step="1" value="${pct}"></label><label class="f"><span>Amount</span><input id="dep-amt" type="number" step="1" value="${r2(base*pct/100)}"></label></div><div class="small muted">Contract ${money(base)} · terms: due at signing.</div>`,
    {submit:'Create deposit invoice', onSubmit:()=>{ const amt = r2(+$('#dep-amt').value||0); if (amt<=0){ toast('Enter a deposit amount'); return false; } const inv = newDoc(c, 'invoice', {mode:'items'}); inv.template = 'construction'; inv.depositOf = d.id; inv.title = `Deposit — ${$('#dep-pct').value}% of contract`; inv.terms = 'Due at signing'; inv.retainagePct = 0; inv.lines = [{id:uid('l'), item:'Deposit on contract', desc:`${d.number} · applied against progress invoices`, qty:1, unit:'ls', rate:amt, taxable:false}]; docMark(inv); c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${inv.number} deposit — ${money(amt)}`}); docOpen = {kind:'invoice', id:inv.id}; finTab = 'invoices'; save(); render(); }});
  $('#dep-pct').addEventListener('input', () => { $('#dep-amt').value = r2(base*(+$('#dep-pct').value||0)/100); }); };
function applyDepositTo(c, inv){ const est = inv.depositOf ? findDoc(c, 'estimate', inv.depositOf) : c.estimates.find(e => e.status==='converted' && (!inv.projectId || e.projectId===inv.projectId)); if (!est) return; inv.depositOf = est.id; const bal = depositBalance(c, est.id); if (bal<=0){ inv.depositApplied = 0; return; } const t = docTotalBase(inv); const gross = r2(t.sub - t.disc); const pct = depositPctOf(c, est.id); inv.depositApplied = r2(Math.min(bal, gross*pct/100)); }
const ctProgressInvoiceBase2 = ctProgressInvoice;
ctProgressInvoice = function(c, d){ const inv = ctProgressInvoiceBase2(c, d); inv.depositOf = d.id; applyDepositTo(c, inv); return inv; };
/* the doc actions: deposit button no longer depends on SOV %; final invoice applies everything */
const docActionsBase5 = docActions;
docActions = function(c, d, st){ let h = docActionsBase5(c, d, st); if (d.type==='estimate' && d.template==='construction' && d.status==='converted'){ const bal = depositBalance(c, d.id); h = h.replace(/<button class="btn sm primary" data-docact="deposit">[^<]*<\/button>/, m => c.invoices.some(i=>i.depositOf===d.id && i.status!=='void') ? '' : m); if (bal) h += `<span class="pill info">Deposit on account ${money(bal)}</span>`; } return h; };
/* pay application: DOM decoration of the SOV editor + G702 block */
function payAppData(c, d){ const est = d.depositOf ? findDoc(c, 'estimate', d.depositOf) : c.estimates.find(e => e.status==='converted' && (!d.projectId || e.projectId===d.projectId)); const p = DB.projects.find(x=>x.id===d.projectId); const K = c.contracts?.[d.projectId||''] || null; const orig = K ? K.net : (est ? docNet(est) : (+c.contractNet||+c.contract||0)); const cos = c.changeOrders.filter(x => ['approved','billed'].includes(x.status) && (!x.projectId || x.projectId===d.projectId)); const coAmt = r2(cos.reduce((a,x)=>a+docNet(x),0)); const revised = r2(orig + coAmt); const prevInv = c.invoices.filter(i => i.mode==='sov' && i.id!==d.id && !['void','draft'].includes(i.status) && (!i.projectId || i.projectId===d.projectId) && i.date <= d.date); const t = docTotal(d); const thisGross = r2(t.sub - t.disc); const prevGross = r2(prevInv.reduce((a,i)=>{ const x = docTotalBase(i); return a + x.sub - x.disc; },0)); const completed = r2(prevGross + thisGross); const retPct = +d.retainagePct||0; const retToDate = r2(prevInv.reduce((a,i)=>a+docTotalBase(i).ret,0) + t.ret); const prevPaid = r2(prevInv.reduce((a,i)=>{ const x = docTotal(i); return a + x.total; },0)); const dep = t.dep||0; const due = t.total; return {orig, coAmt, revised, completed, pctComplete: revised ? r2(completed/revised*100) : 0, retToDate, thisGross, prevGross, prevPaid, dep, due, balanceToFinish:r2(revised - completed), depositBal: est ? depositBalance(c, est.id) : 0, est}; }
function payAppHtml(c, d, editable){ const A = payAppData(c, d); const row = (l, v, cls='') => `<div class="chg ${cls}"><span>${l}</span>${v}</div>`; return `<div class="card payapp"><h3 style="margin:0 0 6px">Application for payment</h3>${row('Original contract sum', money(A.orig))}${row('Net change by approved change orders', money(A.coAmt))}${row('Contract sum to date', money(A.revised), 'b')}${row(`Total completed to date (${A.pctComplete}%)`, money(A.completed))}${row(`Retainage (${+d.retainagePct||0}%) to date`, '− '+money(A.retToDate))}${row('Total earned less retainage', money(A.completed - A.retToDate))}${row('Less previous applications', '− '+money(A.prevPaid))}${A.est?`<div class="chg"><span>Less deposit applied${editable?` <span class="small muted">(on account ${money(A.depositBal + (A.dep||0))})</span>`:''}</span>${editable?`<input type="number" step="1" min="0" max="${r2(A.depositBal + (A.dep||0))}" id="pa-dep" value="${A.dep||0}" style="width:110px;text-align:right">`:'− '+money(A.dep||0)}</div>`:''}${row('Current payment due', money(A.due), 'b big')}${row('Balance to finish (incl. retainage)', money(A.balanceToFinish + A.retToDate), 'dim')}<div class="small muted">Completed to date = previous applications + this period, ex tax. Deposit applied by default = the deposit's share of this period's work; apply all of it on the final invoice.</div></div>`; }
function payAppDecorate(){ if (view!=='clients' || !docOpen || docOpen.kind!=='invoice') return; const c = DB.clients.find(x=>x.id===clientOpen); const d = c && findDoc(c, 'invoice', docOpen.id); if (!d || d.mode!=='sov') return; const root = document.querySelector('table.lines.sov'); if (!root || root.dataset.pa) return; root.dataset.pa = '1'; const editable = d.status==='draft';
  const hr = root.querySelector('thead tr'); const ths = hr.querySelectorAll('th'); const pctTh = [...ths].find(th => /This period %/.test(th.textContent)); if (pctTh){ const a = document.createElement('th'); a.style.width = '84px'; a.className = 'money'; a.textContent = '% to date'; pctTh.before(a); const b = document.createElement('th'); b.className = 'money'; b.style.width = '110px'; b.textContent = 'This period $'; pctTh.after(b); pctTh.textContent = 'This period %'; }
  root.querySelectorAll('tbody tr[data-line]').forEach(tr => { const l = d.lines.find(x=>x.id===tr.dataset.line); if (!l) return; const pctCell = tr.querySelector('td.pct'); if (!pctCell) return; const prev = +l.prevPct||0; const a = document.createElement('td'); a.className = 'pct'; a.innerHTML = `<span class="ro-cell num" data-todate-ro="${l.id}" title="Previously ${r2(prev)}% + this period ${r2(+l.pct||0)}% — enter this period; to date follows">${r2(prev + (+l.pct||0))}%</span>`; pctCell.before(a); const b = document.createElement('td'); b.className = 'pct'; b.innerHTML = `<input class="num" type="number" step="1" min="0" data-period="${l.id}" value="${r2(lineAmount(l,d))}" ${editable?'':'readonly'}>`; pctCell.after(b); });
  const totals = document.querySelector('#v-clients .totals') || root.parentElement; const pa = document.createElement('div'); pa.innerHTML = payAppHtml(c, d, editable); totals.after(pa.firstChild); $('#pa-dep')?.addEventListener('change', e => { d.depositApplied = Math.max(0, +e.target.value||0); save(); render(); }); }
document.addEventListener('change', e => { const t = e.target; if (!t.matches || !(t.matches('[data-todate]') || t.matches('[data-period]'))) return; const tr = t.closest('tr'); const pctIn = tr.querySelector('[data-f="pct"]'); if (!pctIn) return; const c = DB.clients.find(x=>x.id===clientOpen); const d = c && findDoc(c, 'invoice', docOpen.id); const l = d?.lines.find(x=>x.id===tr.dataset.line); if (!l) return; const prev = +l.prevPct||0; let pct; if (t.matches('[data-todate]')) pct = Math.max(0, r2((+t.value||0) - prev)); else pct = (+l.scheduled||0) ? Math.max(0, r2((+t.value||0)/(+l.scheduled)*100)) : 0; pct = Math.min(pct, 100 - prev); pctIn.value = pct; pctIn.dispatchEvent(new Event('change', {bubbles:true})); });
const renderBasePA = render;
render = function(){ renderBasePA(); try { payAppDecorate(); } catch(e){ console.error('payapp', e); } };
/* print: G702 block on SOV invoices */
const printDocBase = printDoc;
printDoc = function(c, d){ if (d.type==='invoice' && d.mode==='sov'){ const A = payAppData(c, d); const w0 = window.open; let html = ''; window.open = () => ({document:{write:(h)=>{ html = h; }, close(){}}}); try { printDocBase(c, d); } finally { window.open = w0; } const block = `<div class="tot" style="margin-top:14px"><span><b>Application for payment</b></span><span></span><span>Original contract sum</span><span class="r">${money(A.orig)}</span><span>Net change by change orders</span><span class="r">${money(A.coAmt)}</span><span>Contract sum to date</span><span class="r">${money(A.revised)}</span><span>Total completed to date (${A.pctComplete}%)</span><span class="r">${money(A.completed)}</span><span>Less retainage to date</span><span class="r">− ${money(A.retToDate)}</span><span>Less previous applications</span><span class="r">− ${money(A.prevPaid)}</span>${A.dep?`<span>Less deposit applied</span><span class="r">− ${money(A.dep)}</span>`:''}<span class="big">Current payment due</span><span class="r big">${money(A.due)}</span><span>Balance to finish incl. retainage</span><span class="r">${money(A.balanceToFinish + A.retToDate)}</span></div>`; html = html.replace('<div class="tot">', block + '<div class="tot">'); const w = w0.call(window, '', '_blank'); if (!w){ toast('Allow pop-ups to print'); return; } w.document.write(html); w.document.close(); return; } return printDocBase(c, d); };
/* invoice-from-estimate: default to what is left */
const invoiceFromEstimateBase = invoiceFromEstimate;
invoiceFromEstimate = function(c, d){ invoiceFromEstimateBase(c, d); const already = {}; c.invoices.filter(i => i.mode==='items' && i.status!=='void').forEach(i => i.lines.forEach(l => { if (l.fromLine) already[l.fromLine] = (already[l.fromLine]||0) + (+l.pct||100); })); const left = d.lines.map(l => 100 - (already[ctKey(d,l)]||0)).filter(x => x > 0); const def = left.length ? Math.min(100, ...left) : 100; const inp = $('#ife-pct'); if (inp){ inp.value = def; inp.max = def; } };
/* change orders: billed % derived from the SOV, not a status */
function coBilledPct(c, co){ const sv = c.sov.find(v => v.coId===co.id); if (!sv) return 0; return r2(sovBilled(c, sv.id)); }
const remindersBase8 = reminders;
reminders = function(){ const out = remindersBase8().filter(r => !/approved change orders to bill/.test(r.label)); const n = DB.clients.reduce((a,c)=>a+c.changeOrders.filter(x => x.status==='approved' && coBilledPct(c, x)===0).length,0); if (n) out.push({n, label:'approved change orders not yet on a progress invoice', go:{view:'clients'}, sev:''}); return out; };
/* contracts per job */
const migrateClientDocsBase = migrateClientDocs;
migrateClientDocs = function(c){ migrateClientDocsBase(c); c.contracts = c.contracts||{}; const first = DB.projects.find(p => p.clientId===c.id)?.id || ''; c.sov.forEach(v => { if (v.projectId==null) v.projectId = first; }); if (c.contract && !Object.keys(c.contracts).length){ const est = c.estimates.find(e => e.status==='converted'); c.contracts[est?.projectId||first] = {base:+c.contract, net:+c.contractNet||+c.contract, date:c.contractDate||'', estId:est?.id||''}; } };
function contractTotals(c){ const K = Object.values(c.contracts||{}); return {base:r2(K.reduce((a,k)=>a+(+k.base||0),0)), net:r2(K.reduce((a,k)=>a+(+k.net||0),0))}; }
const docActionBase6 = docAction;
docAction = async function(c, d, a){ if ((a==='convert' || a==='approveconvert' || (a==='approve' && ['construction','design','materials'].includes(d.template))) && d.type==='estimate'){ const pid = d.projectId||''; const live = c.invoices.some(i => i.mode==='sov' && !['void','draft'].includes(i.status) && (i.projectId||'')===pid); if (live && a==='convert' && !confirm(`${DB.projects.find(p=>p.id===pid)?.project.name||'This project'} already has a contract with progress invoices. Replace it? (Use a change order to add scope instead.)`)) return; const keepSov = c.sov.filter(v => v.source==='Contract' && (v.projectId||'')!==pid); const keepContract = c.contract; const r = await docActionBase6(c, d, a); if (d.status==='converted'){ c.sov.forEach(v => { if (v.source==='Contract' && v.projectId==null) v.projectId = pid; }); keepSov.forEach(v => { if (!c.sov.includes(v)) c.sov.push(v); }); c.sov.forEach((v,i)=>v.order=i); const t = docTotal(d); c.contracts = c.contracts||{}; c.contracts[pid] = {base:t.total, net:r2(t.sub - t.disc), date:today(), estId:d.id, retainagePct:+DB.company.ret||0}; const T = contractTotals(c); c.contract = T.base; c.contractNet = T.net; } return r; } return docActionBase6(c, d, a); };
const newDocBase3 = newDoc;
newDoc = function(c, kind, opts={}){ const d = newDocBase3(c, kind, opts); if (kind==='invoice' && opts.mode==='sov'){ const pid = d.projectId||''; d.lines = d.lines.filter(l => { const v = c.sov.find(x=>x.id===l.sovId); return !v || !v.projectId || v.projectId===pid; }); const K = c.contracts?.[pid]; if (K && K.retainagePct!=null && d.retainagePct==null) d.retainagePct = K.retainagePct; } return d; };
const jobFinBase3 = jobFin;
jobFin = function(p, range){ const J = jobFinBase3(p, range); const c = J.c; const K = c?.contracts?.[p.id]; if (K && K.net){ const coAmt = J.coAmt; J.base = r2(+K.net); J.contract = r2(J.base + coAmt); J.earned = r2(J.contract*J.pct); J.overUnder = r2(J.billed - J.earned); J.over = Math.max(0, J.overUnder); J.under = Math.max(0, -J.overUnder); J.backlog = r2(Math.max(0, J.contract - J.earned)); J.estGP = r2(J.contract - J.eac); J.estGPPct = J.contract ? r2(J.estGP/J.contract*100) : 0; J.plannedGP = r2(J.contract - J.budget); J.plannedGPPct = J.contract ? r2(J.plannedGP/J.contract*100) : 0; J.backlogGP = r2(J.estGP*(1-J.pct)); } return J; };
/* receivables */
function arRows(){ const td = today(); const rows = []; DB.clients.forEach(c => clientFin(c).open.forEach(o => { const i = o.x; const age = o.age; const bucket = age<=0 ? 'current' : age<=30 ? '1–30' : age<=60 ? '31–60' : '60+'; rows.push({c, i, bal:o.bal, age, bucket, promise:i.promise||null, contact:i.lastContact||null, p:DB.projects.find(p=>p.id===i.projectId)}); })); return rows.sort((a,b) => b.age - a.age || b.bal - a.bal); }
function repAR(){ const rows = arRows(); const B = {current:0, '1–30':0, '31–60':0, '60+':0}; rows.forEach(r => B[r.bucket] += r.bal); const tot = r2(rows.reduce((a,r)=>a+r.bal,0)); const byClient = {}; rows.forEach(r => { const o = byClient[r.c.id] = byClient[r.c.id]||{c:r.c, n:0, bal:0, over:0}; o.n++; o.bal += r.bal; if (r.age>0) o.over += r.bal; }); const promised = r2(rows.filter(r=>r.promise).reduce((a,r)=>a+r.bal,0)); const credits = r2(DB.clients.reduce((a,c)=>a+clientFin(c).credits,0));
  return `<div class="rep-head"><div><h2 style="margin:0">Receivables</h2><div class="small muted">Every open invoice, who promised what, and what to do next</div></div></div>
    <div class="fin rep-kpis"><div class="kpi"><b>${money(tot)}</b><span>open · ${rows.length} invoice${rows.length===1?'':'s'}</span></div><div class="kpi"><b>${money(B.current)}</b><span>current</span></div><div class="kpi ${B['1–30']?'warn':''}"><b>${money(B['1–30'])}</b><span>1–30 days</span></div><div class="kpi ${B['31–60']?'warn':''}"><b>${money(B['31–60'])}</b><span>31–60 days</span></div><div class="kpi ${B['60+']?'bad':''}"><b>${money(B['60+'])}</b><span>over 60 days</span></div><div class="kpi"><b>${money(promised)}</b><span>promised · ${money(credits)} credits on account</span></div></div>
    <div class="tw"><table class="t rep-t ar-t"><thead><tr><th>Client · invoice</th><th>Job</th><th>Due</th><th class="money">Balance</th><th>Age</th><th>Promise</th><th>Last contact</th><th></th></tr></thead><tbody>${rows.map(r => `<tr class="${r.age>60?'bad':''}"><td><b>${esc(r.c.name)}</b><div class="small muted">${esc(r.i.number)} · ${esc(r.i.title||'')}</div></td><td class="small">${esc(r.p?.project.name||'')}</td><td class="small">${r.i.due?fmt(r.i.due):'—'}</td><td class="money"><b>${money(r.bal)}</b></td><td><span class="pill ${r.age>60?'bad':r.age>0?'warn':'ok'}">${r.age>0?r.age+' d':'current'}</span></td><td class="small">${r.promise?`${fmt(r.promise.date)}${r.promise.note?' · '+esc(r.promise.note):''}`:'—'}</td><td class="small">${r.contact?`${fmt(r.contact.date)} · ${esc(r.contact.note||'')}`:'—'}</td><td class="ar-acts"><button class="btn sm" data-arnote="${r.c.id}:${r.i.id}">Note</button><button class="btn sm" data-arpromise="${r.c.id}:${r.i.id}">Promise</button><button class="btn sm primary" data-arpay="${r.c.id}">Record payment</button></td></tr>`).join('')||'<tr><td colspan="8" class="muted">Nothing open.</td></tr>'}</tbody></table></div>
    <h3 class="rep-h">By client</h3><div class="tw"><table class="t rep-t"><thead><tr><th>Client</th><th class="money">Open</th><th class="money">Overdue</th><th class="money">Credits</th><th></th></tr></thead><tbody>${Object.values(byClient).map(o => `<tr><td><b>${esc(o.c.name)}</b> <span class="small muted">${o.n} invoice${o.n>1?'s':''}</span></td><td class="money">${money(o.bal)}</td><td class="money ${o.over?'bad':''}">${o.over?money(o.over):'—'}</td><td class="money">${clientFin(o.c).credits?money(clientFin(o.c).credits):'—'}</td><td><button class="btn sm" data-arstmt="${o.c.id}">Statement</button></td></tr>`).join('')}</tbody></table></div>`; }
function paymentAllocate(c, presetInvoiceId){ const open = clientFin(c).open.slice().sort((a,b)=>(a.x.due||a.x.date).localeCompare(b.x.due||b.x.date)); const total = r2(open.reduce((a,o)=>a+o.bal,0));
  const m = mbModal(`Record payment — ${esc(c.name)}`, `<div class="f2"><label class="f"><span>Amount received</span><input type="number" step="0.01" id="py-amt" value="${presetInvoiceId ? (open.find(o=>o.x.id===presetInvoiceId)?.bal||total) : total}"></label><label class="f"><span>Date</span><input type="date" id="py-date" value="${today()}"></label></div><div class="f2"><label class="f"><span>Method</span><select id="py-method"><option>ACH</option><option>Check</option><option>Wire</option><option>Card</option><option>Credit on account</option></select></label><label class="f"><span>Reference</span><input id="py-ref" placeholder="check #, wire ref"></label></div>
    <table class="t"><thead><tr><th>Invoice</th><th class="money">Balance</th><th class="money" style="width:130px">Apply</th></tr></thead><tbody>${open.map(o => `<tr><td>${esc(o.x.number)} <span class="small muted">${esc(o.x.title||'')} · due ${o.x.due?fmt(o.x.due):'—'}</span></td><td class="money">${money(o.bal)}</td><td class="money"><input type="number" step="0.01" min="0" max="${o.bal}" data-pyalloc="${o.x.id}" value="0" style="width:120px;text-align:right"></td></tr>`).join('')}</tbody><tfoot><tr><td>Applied</td><td></td><td class="money" id="py-applied">$0</td></tr><tr><td>Left on account (credit)</td><td></td><td class="money" id="py-left">$0</td></tr></tfoot></table><div class="row" style="margin-top:6px;gap:6px"><button class="btn sm" id="py-auto">Apply oldest first</button></div>`,
    {submit:'Record', onSubmit:()=>{ const amt = r2(+$('#py-amt').value||0); if (amt<=0){ toast('Enter the amount'); return false; } const date = $('#py-date').value||today(); const method = $('#py-method').value, ref = $('#py-ref').value; let applied = 0; m.querySelectorAll('[data-pyalloc]').forEach(inp => { const v = r2(+inp.value||0); if (v<=0) return; applied += v; c.payments.push({id:uid('py'), invoiceId:inp.dataset.pyalloc, date, amount:v, method, ref}); const inv = findDoc(c, 'invoice', inp.dataset.pyalloc); if (inv && clientFin(c).open.find(o=>o.x.id===inv.id)?.bal <= 0.005) inv.status = 'paid'; }); const left = r2(amt - applied); if (left < -0.005){ toast('Applied more than received'); return false; } if (left > 0.005) c.payments.push({id:uid('py'), invoiceId:'', date, amount:left, method, ref, unapplied:true, voidedInvoice:'payment on account'}); c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`Payment ${money(amt)} (${method}${ref?' '+ref:''}) — applied ${money(applied)}${left>0.005?`, ${money(left)} on account`:''}`}); try { audit('payment', c.id, 'received', '', String(amt), `${c.name} ${method} ${ref}`); } catch(e){} save(); render(); toast(`${money(amt)} recorded`); }});
  const recalc = () => { const amt = r2(+$('#py-amt').value||0); let ap = 0; m.querySelectorAll('[data-pyalloc]').forEach(i => ap += r2(+i.value||0)); $('#py-applied').textContent = money(ap); $('#py-left').textContent = money(Math.max(0, amt - ap)); $('#py-left').classList.toggle('bad', ap > amt + 0.005); }; const auto = () => { let left = r2(+$('#py-amt').value||0); m.querySelectorAll('[data-pyalloc]').forEach(i => { const cap = +i.max||0; const v = Math.min(cap, Math.max(0, left)); i.value = r2(v); left = r2(left - v); }); recalc(); }; m.querySelectorAll('[data-pyalloc], #py-amt').forEach(i => i.addEventListener('input', recalc)); $('#py-auto').onclick = auto; if (presetInvoiceId){ m.querySelectorAll('[data-pyalloc]').forEach(i => { if (i.dataset.pyalloc===presetInvoiceId) i.value = i.max; }); recalc(); } else auto(); }
REP_GROUPS.find(g=>g.id==='cash').tabs.unshift(['ar','Receivables']); REP_DEFS.ar = 'Every open invoice across clients with aging, promises to pay and last contact; record payments that cover several invoices.';
const renderReportsBase8 = renderReports;
renderReports = function(){ renderReportsBase8(); if (repTab!=='ar') return; $('#rep-print-area').innerHTML = repAR(); const root = $('#rep-print-area');
  root.querySelectorAll('[data-arpay]').forEach(b => b.onclick = () => paymentAllocate(DB.clients.find(c=>c.id===b.dataset.arpay)));
  root.querySelectorAll('[data-arpromise]').forEach(b => b.onclick = () => { const [cid, iid] = b.dataset.arpromise.split(':'); const c = DB.clients.find(x=>x.id===cid); const i = findDoc(c, 'invoice', iid); mbModal(`Promise to pay — ${esc(i.number)}`, `<label class="f"><span>Expected on</span><input type="date" id="pr-date" value="${i.promise?.date||iso(addDays(today(), 7))}"></label><label class="f"><span>Note</span><input id="pr-note" value="${esc(i.promise?.note||'')}" placeholder="who said what"></label>`, {submit:'Save', onSubmit:()=>{ i.promise = {date:$('#pr-date').value, note:$('#pr-note').value, by:S.project.userName||'', t:nowStamp()}; i.lastContact = {date:today(), note:'promise: '+$('#pr-note').value}; save(); render(); }}); });
  root.querySelectorAll('[data-arnote]').forEach(b => b.onclick = () => { const [cid, iid] = b.dataset.arnote.split(':'); const c = DB.clients.find(x=>x.id===cid); const i = findDoc(c, 'invoice', iid); const note = prompt(`Last contact about ${i.number} — what happened?`, i.lastContact?.note||''); if (note===null) return; i.lastContact = {date:today(), note, by:S.project.userName||''}; c.activity.push({t:nowStamp(), by:S.project.userName||'', text:`${i.number}: ${note}`}); save(); render(); });
  root.querySelectorAll('[data-arstmt]').forEach(b => b.onclick = () => { repClient = b.dataset.arstmt; repTab = 'statement'; render(); }); };
/* the old single-invoice payment editor now opens the allocation modal; overdue reminder goes to Receivables */
const docActionBase7 = docAction;
docAction = async function(c, d, a){ if (a==='pay' && d.type==='invoice'){ paymentAllocate(c, d.id); return; } return docActionBase7(c, d, a); };
const remindersBase9 = reminders;
reminders = function(){ return remindersBase9().map(r => /overdue invoices/.test(r.label) ? Object.assign(r, {go:{view:'reports', tab:'ar'}}) : r); };
/* cash forecast: promised dates beat due dates */
const cashForecastBase = cashForecast;
cashForecast = function(){ const F = cashForecastBase(); const td = parse(today()); DB.clients.forEach(c => clientFin(c).open.forEach(o => { if (!o.x.promise?.date) return; const label = `${c.name.split(' ')[0]} ${o.x.number}`; F.weeks.forEach(w => { const k = w.items.findIndex(it => it[0]===label && it[1]>0); if (k>=0){ w.inflow -= o.bal; w.items.splice(k,1); } }); const w = F.weeks.find(x => o.x.promise.date >= x.start && o.x.promise.date <= x.end); if (w){ w.inflow += o.bal; w.items.push([label+' (promised)', o.bal]); } })); let bal = F.cash; F.weeks.forEach(w => { w.net = w.inflow - w.outflow; bal += w.net; w.balance = bal; }); F.low = Math.min(...F.weeks.map(w=>w.balance)); return F; };

/* ===================== DRILL-THROUGH THAT TIES — number → the exact rows behind it → the document ===================== */
function drillRows(key, range){ const R = range || cfoRange(); const rows = []; const proj = id => DB.projects.find(p=>p.id===id); const inEnt = pid => !repEntity || (proj(pid) ? entityOfProject(proj(pid))===repEntity : true);
  if (key==='income'){ DB.clients.forEach(c => c.invoices.filter(i => !['void','draft'].includes(i.status) && !i.retainerRelease && within(i.date, R) && inEnt(i.projectId)).forEach(i => rows.push({date:i.date, kind:'Invoice', desc:`${i.number} · ${i.title||''}`, who:c.name, amt:docNet(i), open:{type:'invoice', c, d:i}}))); DB.projects.filter(p => inEnt(p.id)).forEach(p => { const adj = wipAdjustment(R, [p.id]); if (Math.abs(adj) >= 0.5) rows.push({date:R[1]||today(), kind:'WIP adjustment', desc:`${p.project.name} · earned − billed for the period`, who:'', amt:adj, open:{type:'wip', p}}); }); }
  else if (key.startsWith('cat:')){ const id = key.slice(4); ledger(R).filter(r => !r.income && (r.cat===id || (id==='payroll_oh' && r.cat==='payroll_oh'))).forEach(r => rows.push({date:r.date, kind:r.kind==='bill' ? (r.unapproved?'Bill (awaiting approval)':'Bill') : r.kind==='payroll' ? 'Payroll' : 'Bank', desc:r.desc, who:r.vendor||'', amt:r.amt, open:r.kind==='bill' ? {type:'bill', b:r.ref} : r.kind==='payroll' ? {type:'payroll', r:r.ref} : {type:'txn', t:r.ref}})); }
  else if (key==='ar'){ DB.clients.forEach(c => clientFin(c).open.forEach(o => rows.push({date:o.x.date, kind:'Open invoice', desc:`${o.x.number} · ${o.x.title||''}`, who:c.name, amt:o.bal, open:{type:'invoice', c, d:o.x}}))); }
  else if (key==='ap'){ DB.bills.filter(b => !['void','rejected','draft'].includes(b.status) && !billIsPaid(b)).forEach(b => rows.push({date:b.date, kind:b.status, desc:`${b.number} · ${b.vendor}`, who:b.vendor, amt:billTotal(b), open:{type:'bill', b}})); }
  else if (key==='cash'){ DB.accounts.filter(a=>a.type==='bank').forEach(a => rows.push({date:today(), kind:'Account', desc:`${a.name||a.id} · opening ${money(a.opening||0)} + register ${money(acctRegister(a))}`, who:'', amt:acctBook(a), open:{type:'bank'}})); }
  else if (key==='collected'){ DB.clients.forEach(c => c.payments.filter(py => !py.unapplied && within(py.date, R)).forEach(py => { const i = c.invoices.find(x=>x.id===py.invoiceId); rows.push({date:py.date, kind:'Payment', desc:`${i?.number||''} · ${py.method||''} ${py.ref||''}`, who:c.name, amt:+py.amount||0, open: i ? {type:'invoice', c, d:i} : null}); })); }
  return rows.sort((a,b)=>(b.date||'').localeCompare(a.date||'')); }
function drillOpen(o){ mbCloseModal(); if (!o) return; if (o.type==='invoice'){ clientOpen = o.c.id; clientTab = 'fin'; finTab = 'invoices'; docOpen = {kind:'invoice', id:o.d.id}; view = 'clients'; render(); } else if (o.type==='bill'){ view = 'ap'; render(); setTimeout(() => openBill(o.b.id), 60); } else if (o.type==='txn'){ view = 'bank'; render(); } else if (o.type==='payroll'){ view = 'ap'; render(); } else if (o.type==='wip'){ setCurrent(o.p.id); view = 'costs'; render(); } else if (o.type==='prop'){ setWorkspace('mb'); mbOwnId = o.p.id; ownTab = 'fin'; view = 'mbownp'; render(); } else if (o.type==='bank'){ view = 'bank'; render(); } }
const DRILL_TITLES = {income:'Revenue (earned)', ar:'Receivables', ap:'Unpaid bills', cash:'Cash on the books', collected:'Collected'};
fsDrill = function(key, range){ const rows = drillRows(key, range); const title = DRILL_TITLES[key] || cfoCatName(key.slice(4)); const total = r2(rows.reduce((a,r)=>a+r.amt,0)); const R = range || cfoRange();
  mbModal(`${title} — ${fmt(R[0]||'')} → ${fmt(R[1]||today())}`, `<div class="small muted" style="margin-bottom:6px">${rows.length} row${rows.length===1?'':'s'} · total ${money(total)} — the same number as the one you clicked. Tap a row to open it.</div><div class="tw" style="max-height:60vh;overflow:auto"><table class="t"><thead><tr><th>Date</th><th>What</th><th>Who</th><th>Kind</th><th class="money">Amount</th></tr></thead><tbody>${rows.map((r,i) => `<tr class="${r.open?'click':''}" data-drillrow="${i}"><td class="dim">${fmt(r.date)}</td><td>${esc(r.desc)}</td><td>${esc(r.who||'')}</td><td class="dim">${esc(r.kind)}</td><td class="money ${r.amt<0?'bad':''}">${money(r.amt)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Nothing in this period.</td></tr>'}<tr style="font-weight:600"><td colspan="4">Total</td><td class="money">${money(total)}</td></tr></tbody></table></div>`, {submit:null}); document.querySelectorAll('[data-drillrow]').forEach(tr => tr.onclick = () => drillOpen(rows[+tr.dataset.drillrow].open)); };
/* every tile with a metric drills */
document.addEventListener('click', e => { const el = e.target.closest('[data-drill]'); if (!el || e.target.closest('a,button,input,select')) return; fsDrill(el.dataset.drill); });
const renderReportsBase9 = renderReports;
renderReports = function(){ renderReportsBase9(); const root = $('#rep-print-area'); if (!root) return; root.querySelectorAll('.kpi').forEach(k => { const t = k.textContent; const m = /Revenue \(earned\)/.test(t) ? 'income' : /Job cost \(COGS\)/.test(t) ? null : /receivable|owed to us/i.test(t) && !/retainage/i.test(t) ? 'ar' : /payables|unpaid bills|we owe/i.test(t) ? 'ap' : /bank balance|cash on the books/i.test(t) ? 'cash' : /collected/i.test(t) && /^\$/.test(t.trim()) && !/Revenue/.test(t) ? 'collected' : null; if (m){ k.dataset.drill = m; k.classList.add('click'); k.title = 'Click to see the rows behind this number'; } }); root.querySelectorAll('[data-fsdrill]').forEach(tr => { tr.classList.add('click'); }); };
/* analyst: one card per vendor, with the decision */
const analystFindingsBase = analystFindings;
analystFindings = function(){ const F = analystFindingsBase(); const byV = {}; const keep = []; F.forEach(f => { const m = (f.title+' '+f.detail).match(/(?:PO-\d{4}-\d+ )?([A-Z][A-Za-z&' ]+(?:Works|Tile|Millwork|Plumbing|Electric|Supply|Lumber|Glass|Stone|Inc|LLC))/); const vendor = DB.vendors.find(v => (f.title+' '+f.detail).includes(v.name)); if (!vendor){ keep.push(f); return; } (byV[vendor.name] = byV[vendor.name]||[]).push(f); }); Object.entries(byV).forEach(([name, fs]) => { if (fs.length===1){ keep.push(fs[0]); return; } const v = DB.vendors.find(x=>x.name===name); const bills = DB.bills.filter(b => b.vendor===name && !['void','rejected','paid','verified'].includes(b.status)); const pb = bills.filter(b => b.paidBeforeApproval); const sev = fs.some(f=>f.sev==='high') ? 'high' : 'med'; keep.push({sev, area:'Vendors', title:`${name}: ${fs.map(f=>f.title.replace(name,'').replace(/^[\s:—-]+|[\s:—-]+$/g,'').toLowerCase()).join(' · ')}${v?.bankPending?' · bank change unverified':''}${pb.length?' · paid before approval':''}`, detail:fs.map(f=>f.detail).join(' — '), amount:Math.max(...fs.map(f=>f.amount||0)), go:{view:'ap'}, actions:[...(bills.length?[{l:'Open bill', go:{view:'ap'}}]:[]), {l:'Vendor record', go:{view:'vendors'}}], merged:fs.length}); }); return keep.sort((a,b) => ({high:0,med:1,low:2}[a.sev]-{high:0,med:1,low:2}[b.sev]) || (b.amount||0)-(a.amount||0)); };

/* client portal: the account in one card */
const renderPortalApprovalsBase = renderPortalApprovals;
renderPortalApprovals = function(){ renderPortalApprovalsBase(); const c = clientUserOf(); const host = $('#cl-approvals'); if (!host || !c) return; const f = clientFin(c); const projs = DB.projects.filter(p => p.clientId===c.id); const J = projs.map(p => jobFin(p)); const contract = r2(J.reduce((a,x)=>a+x.contract,0)), earned = r2(J.reduce((a,x)=>a+x.earned,0)), billed = r2(J.reduce((a,x)=>a+x.billed,0)); const dep = r2(c.estimates.reduce((a,e)=>a+depositBalance(c, e.id),0)); const card = document.createElement('div'); card.className = 'card'; card.style.marginBottom = '14px'; card.innerHTML = `<h3 style="margin:0 0 6px">Your account</h3><div class="cash-grid" style="grid-template-columns:repeat(3,1fr)"><div><span>Contract</span><b>${money(contract)}</b><i>incl. approved changes</i></div><div><span>Work completed</span><b>${money(earned)}</b><i>${contract?Math.round(earned/contract*100):0}% of contract</i></div><div><span>Billed to date</span><b>${money(billed)}</b><i>${dep?`deposit on account ${money(dep)}`:'ex tax'}</i></div><div><span>Retainage held</span><b>${money(f.retHeld)}</b><i>released at completion</i></div><div><span>Paid to date</span><b>${money(f.paid)}</b><i>${f.credits?`credit on account ${money(f.credits)}`:''}</i></div><div><span>Balance due</span><b class="${f.overdue?'bad':''}">${money(f.outstanding)}</b><i>${f.overdue?money(f.overdue)+' overdue':'nothing overdue'}</i></div></div>`; host.prepend(card); };

/* ===================== PHASE 5c — report builder · budget everywhere · phone layouts · bank reconciliation · close v2 · procurement extras · vendor card · client columns ===================== */
/* ---- 1. one report builder: Saved searches with columns, row group, month columns, sort, starters ---- */
REP_GROUPS.find(g=>g.id==='build').tabs = [['searches','Report builder']]; REP_DEFS.searches = 'Build any report from any dataset: pick columns, group rows, spread by month, sort, filter, save — then pin it to Home as a list, KPI or reminder.';
Object.assign(REP_DS, {
  jobs:{n:'Jobs', rows:() => DB.projects.map(p => { const J = jobFin(p); const c = DB.clients.find(x=>x.id===p.clientId); return {job:p.project.name, client:c?.name||'', entity:entName(entityOfProject(p)), status:p.project.status||'active', date:p.project.start||'', contract:J.contract, budget:J.budget, actual:J.actual, committed:J.committed, eac:J.eac, estGP:J.estGP, estGPPct:J.estGPPct, bidGPPct:J.plannedGPPct, fadePts:r2(J.estGPPct - J.plannedGPPct), pctComplete:r2(J.pct*100), earned:J.earned, billed:J.billed, overUnder:J.overUnder, backlog:J.backlog, collected:J.collected, outstanding:J.outstanding}; }), dims:['job','client','entity','status'], sums:['contract','budget','actual','committed','eac','estGP','earned','billed','overUnder','backlog','collected','outstanding']},
  cos:{n:'Change orders', rows:() => DB.clients.flatMap(c => c.changeOrders.map(x => ({client:c.name, job:DB.projects.find(p=>p.id===x.projectId)?.project.name||'', number:x.number, title:x.title, status:x.status, date:x.date, amount:docNet(x), billedPct:coBilledPct(c, x), scheduleDays:+x.scheduleDays||0}))), dims:['client','job','status'], sums:['amount','scheduleDays']},
  payments:{n:'Payments received', rows:() => DB.clients.flatMap(c => c.payments.map(py => ({client:c.name, invoice:c.invoices.find(i=>i.id===py.invoiceId)?.number||'', date:py.date, method:py.method||'', ref:py.ref||'', unapplied:py.unapplied?'yes':'no', amount:+py.amount||0}))), dims:['client','method','unapplied'], sums:['amount']},
  payrollRuns:{n:'Payroll runs', rows:() => DB.payroll.map(r => ({period:r.period, date:r.payDate, entity:entName(r.entityId||'ent1'), status:r.status, employees:+r.employees||0, gross:+r.gross||0, taxes:+r.taxes||0, total:+r.total||0})), dims:['entity','status'], sums:['employees','gross','taxes','total']},
  clients:{n:'Clients', rows:() => DB.clients.map(c => { const f = clientFin(c); const projs = DB.projects.filter(p=>p.clientId===c.id); const J = projs.map(p=>jobFin(p)); return {client:c.name, type:c.type||'', jobs:projs.length, contract:r2(J.reduce((a,x)=>a+x.contract,0)), billed:r2(J.reduce((a,x)=>a+x.billed,0)), earned:r2(J.reduce((a,x)=>a+x.earned,0)), prepaid:r2(J.reduce((a,x)=>a+x.over,0)), paid:f.paid, outstanding:f.outstanding, overdue:f.overdue, credits:f.credits, unsigned:r2([...c.estimates, ...c.changeOrders].filter(d=>d.status==='sent').reduce((a,d)=>a+docTotal(d).total,0)), date:c.contractDate||''}; }), dims:['client','type'], sums:['jobs','contract','billed','earned','prepaid','paid','outstanding','overdue','credits','unsigned']},
  vendors:{n:'Vendors', rows:() => DB.vendors.map(v => { const P = vendorPerf(v); return {vendor:v.name, trade:v.trade||'', insuranceExp:v.insuranceExp||'', w9:v.w9?'yes':'no', retainagePct:+v.retainagePct||0, pos:P.pos, openPOs:P.open, onTimePct:P.onTime??'', avgLeadDays:P.avgLead??'', billVsPOPct:P.variance??'', paid:vendorSpend(v), retainageHeld:apRetainage(v.name), date:P.last}; }), dims:['vendor','trade','w9'], sums:['pos','openPOs','paid','retainageHeld']},
});
const monthOf = d => (d||'').slice(0,7);
const searchRunBase = searchRun;
searchRun = function(s){ const R = searchRunBase(s); const ds = R.ds; let rows = R.rows; let cols = R.cols;
  if (s.colGroup==='month' && s.group && ds.dims.includes(s.group) && ds.sums.length){ const raw = searchRunBase(Object.assign({}, s, {group:''})).rows; const f = s.valueField && ds.sums.includes(s.valueField) ? s.valueField : ds.sums[0]; const months = [...new Set(raw.map(r => monthOf(r.date)).filter(Boolean))].sort(); const g = {}; raw.forEach(r => { const k = r[s.group]||'(none)'; const o = g[k] = g[k]||{[s.group]:k, total:0}; months.forEach(m => { if (o[m]==null) o[m] = 0; }); const m = monthOf(r.date); if (m){ o[m] = r2(o[m] + (+r[f]||0)); o.total = r2(o.total + (+r[f]||0)); } }); rows = Object.values(g).sort((a,b)=>b.total-a.total); cols = [s.group, ...months, 'total']; R.pivot = {field:f, months}; }
  if (s.cols && s.cols.length && !R.pivot){ const keep = cols.filter(c => s.cols.includes(c) || c==='count' || (s.group && c===s.group)); if (keep.length) cols = keep; }
  if (s.sort && cols.includes(s.sort)){ const dir = s.sortDir==='asc' ? 1 : -1; rows = rows.slice().sort((a,b) => { const x = a[s.sort], y = b[s.sort]; if (typeof x==='number' || typeof y==='number') return ((+x||0)-(+y||0))*dir; return String(x??'').localeCompare(String(y??''))*dir; }); }
  return Object.assign(R, {rows, cols}); };
const searchTableBase = searchTable;
searchTable = function(s, limit){ const R = searchRun(s); if (!R.pivot) return searchTableBase(s, limit); const rows = limit ? R.rows.slice(0, limit) : R.rows; const tot = {}; R.cols.slice(1).forEach(c => tot[c] = r2(rows.reduce((a,r)=>a+(+r[c]||0),0))); return `<div class="tw"><table class="t rep-t" id="ss-table"><thead><tr>${R.cols.map((c,i)=>`<th class="${i?'money':''}">${i&&c!=='total'?monthLabel(c):esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr ${searchHighlight(s, r)}>${R.cols.map((c,i)=>`<td class="${i?'money':''}">${i?money(r[c]||0):esc(String(r[c]??''))}</td>`).join('')}</tr>`).join('')}${rows.length?`<tr style="font-weight:600"><td>Total</td>${R.cols.slice(1).map(c=>`<td class="money">${money(tot[c])}</td>`).join('')}</tr>`:''}</tbody></table></div><div class="small muted">${esc(R.pivot.field)} by month.</div>`; };
const repSearchesBase = repSearches;
repSearches = function(){ let h = repSearchesBase(); const s = ssOpen ? searchList().find(x=>x.id===ssOpen) : null; if (!s) return h.replace('Saved searches</h2>', 'Report builder</h2>').replace('id="ss-new">New search', 'id="ss-new">New report'); const ds = REP_DS[s.ds]||REP_DS.invoices; const sample = ds.rows()[0]||{}; const fields = Object.keys(sample); const cur = searchRun(s).cols;
  const extra = `<div style="margin-top:10px"><div class="small" style="font-weight:600;margin-bottom:4px">Columns</div><div class="row" style="gap:8px;flex-wrap:wrap">${(s.group && !s.colGroup ? [s.group,'count',...ds.sums] : fields).map(f => `<label class="small"><input type="checkbox" data-sscol="${f}" ${!s.cols||!s.cols.length||s.cols.includes(f)?'checked':''}> ${f}</label>`).join('')}</div></div><div class="row" style="margin-top:8px;gap:12px;flex-wrap:wrap"><label class="small">Spread by <select id="ss-colgroup" class="btn sm"><option value="">— none —</option><option value="month" ${s.colGroup==='month'?'selected':''}>month</option></select></label>${s.colGroup==='month'?`<label class="small">Value <select id="ss-valuef" class="btn sm">${ds.sums.map(f=>`<option ${(s.valueField||ds.sums[0])===f?'selected':''}>${f}</option>`).join('')}</select></label>`:''}<label class="small">Sort by <select id="ss-sort" class="btn sm"><option value="">— default —</option>${cur.map(c=>`<option value="${c}" ${s.sort===c?'selected':''}>${c}</option>`).join('')}</select> <select id="ss-sortdir" class="btn sm"><option value="desc" ${s.sortDir!=='asc'?'selected':''}>high → low</option><option value="asc" ${s.sortDir==='asc'?'selected':''}>low → high</option></select></label><button class="btn sm" id="ss-pin">Pin to Home</button></div>`;
  return h.replace('<div style="margin-top:8px"><div class="small" style="font-weight:600;margin-bottom:4px">Highlight rows when</div>', extra + '<div style="margin-top:8px"><div class="small" style="font-weight:600;margin-bottom:4px">Highlight rows when</div>').replace('← Saved searches', '← Report builder'); };
const wireSearchesBase = wireSearches;
wireSearches = function(root){ wireSearchesBase(root); const s = searchList().find(x=>x.id===ssOpen); if (!s) return; const upd = () => { save(); render(); }; root.querySelectorAll('[data-sscol]').forEach(cb => cb.addEventListener('change', () => { s.cols = [...root.querySelectorAll('[data-sscol]:checked')].map(x=>x.dataset.sscol); upd(); })); $('#ss-colgroup')?.addEventListener('change', e => { s.colGroup = e.target.value; upd(); }); $('#ss-valuef')?.addEventListener('change', e => { s.valueField = e.target.value; upd(); }); $('#ss-sort')?.addEventListener('change', e => { s.sort = e.target.value; upd(); }); $('#ss-sortdir')?.addEventListener('change', e => { s.sortDir = e.target.value; upd(); }); $('#ss-pin')?.addEventListener('click', () => { const H = homeDef(); H.portlets.push({id:uid('pt'), type:'search', cfg:{ds:s.ds, group:s.group, title:s.name, searchId:s.id}}); save(); toast(`"${s.name}" pinned to your Home`); }); };
function seedSearches(){ if (DB.__ssSeeded) return; DB.__ssSeeded = true; const L = searchList(); if (L.length) return; const mk = (name, ds, o={}) => L.push(Object.assign({id:uid('ss'), name, ds, group:'', criteria:[], summary:{}, highlight:null, audience:['all'], kpi:false, kpiField:'count', reminder:false, reminderThreshold:0, createdBy:'', cols:[], sort:'', sortDir:'desc'}, o));
  mk('AR aging by client', 'invoices', {group:'client', criteria:[{field:'balance', op:'gt', value:'0'}], sort:'balance'}); mk('Open POs by vendor', 'pos', {group:'vendor', criteria:[{field:'status', op:'ne', value:'closed'}]}); mk('Bills awaiting approval', 'bills', {criteria:[{field:'status', op:'contains', value:'submitted'}], sort:'total'}); mk('Uncategorized bank items', 'txns', {criteria:[{field:'category', op:'eq', value:'uncat'}], sort:'amount'}); mk('Job GP vs bid', 'jobs', {cols:['job','contract','estGPPct','bidGPPct','fadePts','pctComplete','backlog'], sort:'fadePts', sortDir:'asc', highlight:{field:'fadePts', op:'lt', value:'-1', color:'#FBECEA'}}); mk('Hours by employee', 'time', {group:'employee'}); mk('Invoices due this week', 'invoices', {criteria:[{field:'balance', op:'gt', value:'0'}], sort:'due', sortDir:'asc'}); mk('Change order log', 'cos', {sort:'date'}); mk('Revenue by job by month', 'events', {group:'job', colGroup:'month', valueField:'amount', criteria:[{field:'side', op:'eq', value:'Revenue'}]}); }
/* ---- 2. budget: seed on first use; compare=budget everywhere the frame is shown ---- */
const budgetForBase = budgetFor;
budgetFor = function(year){ const b = budgetForBase(year); const empty = !Object.values(b).some(arr => (arr||[]).some(v => v)); if (empty && !DB.__budgetAsked?.[year] && role()==='owner' && view==='reports'){ DB.__budgetAsked = DB.__budgetAsked||{}; DB.__budgetAsked[year] = true; setTimeout(() => { if (confirm(`No budget for ${year} yet. Fill it from last year's actuals plus 5% so the Budget comparison works everywhere?`)){ budgetSeedFromActuals(year); save(); render(); } }, 200); } return b; };
/* ---- 3. phone: wide tables scroll inside their frame; WIP and portfolio become cards ---- */
function wipCards(rows){ return `<div class="jobcards">${rows.map(({w,f}) => `<div class="jobcard" data-jobgo="${w.p.id}"><div class="jc-top"><b>${esc(w.p.project.name)}</b><span class="small muted">${Math.round(w.pct*100)}%</span></div><div class="jc-nums"><span>Contract ${money(w.contract)}</span><span>Est. cost ${money(w.eac)}</span><span>GP ${w.gpPct}%${f?.fadePts!=null?` (${f.fadePts>=0?'+':''}${f.fadePts} pts)`:''}</span></div><div class="jc-nums"><span>Earned ${money(w.earned)}</span><span>Billed ${money(w.billed)}</span><span class="${w.over?'warn':w.under?'bad':''}">${w.over?'Over-billed '+money(w.over):w.under?'Under-billed '+money(w.under):'Billed = earned'}</span></div><div class="jc-nums"><span>Cost to complete ${money(w.ctc)}</span><span>Backlog ${money(w.backlog)}</span></div></div>`).join('')}</div>`; }
const repWIPBase2 = repWIP;
repWIP = function(){ const h = repWIPBase2(); if (window.innerWidth >= 700) return h; const rows = DB.projects.filter(p => !repEntity || entityOfProject(p)===repEntity).map(p => ({w:wipRow(p), f:fadeFor(p, wipRow(p))})).filter(x => x.w.contract); return h.replace(/<div class="tw"><table class="t rep-t">[\s\S]*?<\/table><\/div>/, wipCards(rows)); };
/* ---- 4. bank reconciliation to a statement ---- */
let reconAcct = '';
function reconcileDialog(acct){ const a = acct || DB.accounts.find(x=>x.type==='bank'); if (!a) return; const last = a.recon || null; const cleared = DB.txns.filter(t => t.acct===a.id && t.status==='reconciled'); const uncleared = DB.txns.filter(t => t.acct===a.id && t.status!=='reconciled').sort((x,y)=>x.date.localeCompare(y.date));
  const m = mbModal(`Reconcile ${esc(a.name)}`, `<p class="small muted">Enter the statement's ending balance and date, tick what is on the statement. The difference must be zero to finish.${last?` Last reconciled ${fmt(last.date)} at ${money(last.balance)}.`:''}</p><div class="f2"><label class="f"><span>Statement date</span><input type="date" id="rc-date" value="${today()}"></label><label class="f"><span>Ending balance</span><input type="number" step="0.01" id="rc-bal" value="${acctBook(a)}"></label></div><div class="cash-grid" style="grid-template-columns:repeat(3,1fr)"><div><span>Cleared balance</span><b id="rc-cleared">—</b></div><div><span>Statement</span><b id="rc-stmt">—</b></div><div><span>Difference</span><b id="rc-diff">—</b></div></div><div class="tw" style="max-height:40vh;overflow:auto"><table class="t"><thead><tr><th></th><th>Date</th><th>Description</th><th class="money">Amount</th></tr></thead><tbody>${uncleared.map(t => `<tr><td><input type="checkbox" data-rc="${t.id}" ${t.date <= today() ? 'checked':''}></td><td class="dim">${fmt(t.date)}</td><td>${esc(t.desc)}</td><td class="money ${t.amt<0?'':'ok'}">${money(t.amt)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Everything is already reconciled.</td></tr>'}</tbody></table></div>`,
    {submit:'Finish reconciliation', onSubmit:()=>{ const stmt = +$('#rc-bal').value||0; const ids = [...m.querySelectorAll('[data-rc]:checked')].map(x=>x.dataset.rc); const clearedSum = r2((a.opening||0) + cleared.reduce((s,t)=>s+t.amt,0) + DB.txns.filter(t=>ids.includes(t.id)).reduce((s,t)=>s+t.amt,0)); if (Math.abs(clearedSum - stmt) > 0.005){ if (!confirm(`Difference ${money(stmt - clearedSum)}. Finish anyway and record the difference as an unreconciled item?`)) return false; } ids.forEach(id => { const t = DB.txns.find(x=>x.id===id); if (t){ t.status = 'reconciled'; t.reconciledOn = $('#rc-date').value; } }); a.recon = {date:$('#rc-date').value, balance:stmt, difference:r2(stmt - clearedSum), by:S.project.userName||''}; a.balance = stmt; a.asOf = $('#rc-date').value; try { audit('account', a.id, 'reconciled', '', String(stmt), `${a.name} ${a.recon.date} diff ${money(a.recon.difference)}`); } catch(e){} save(); render(); toast(`${a.name} reconciled through ${fmt(a.recon.date)}`); }});
  const upd = () => { const ids = [...m.querySelectorAll('[data-rc]:checked')].map(x=>x.dataset.rc); const clearedSum = r2((a.opening||0) + cleared.reduce((s,t)=>s+t.amt,0) + DB.txns.filter(t=>ids.includes(t.id)).reduce((s,t)=>s+t.amt,0)); const stmt = +$('#rc-bal').value||0; $('#rc-cleared').textContent = money(clearedSum); $('#rc-stmt').textContent = money(stmt); const d = $('#rc-diff'); d.textContent = money(stmt - clearedSum); d.className = Math.abs(stmt-clearedSum) < 0.005 ? 'ok' : 'bad'; }; m.querySelectorAll('[data-rc], #rc-bal').forEach(i => i.addEventListener('input', upd)); m.querySelectorAll('[data-rc]').forEach(i => i.addEventListener('change', upd)); upd(); }
const renderBankBase = renderBank;
renderBank = function(){ renderBankBase(); const acts = document.querySelector('#v-bank .acts'); if (acts && !acts.querySelector('#btn-recon')){ const b = document.createElement('button'); b.className = 'btn'; b.id = 'btn-recon'; b.textContent = 'Reconcile…'; acts.insertBefore(b, acts.firstChild); } const b = $('#btn-recon'); if (b) b.onclick = () => reconcileDialog(DB.accounts.find(a => a.id===txnAcct) || DB.accounts.find(a=>a.type==='bank')); const und = undepositedReceipts(); const host = $('#sync-status'); if (host && und.length && !host.querySelector('.undep-note')) host.innerHTML += ` <span class="bad undep-note">${und.length} client payment${und.length>1?'s':''} recorded but not seen in the bank (${money(und.reduce((a,x)=>a+(+x.py.amount||0),0))}) — deposit them or fix the record.</span>`; };
/* ---- 5. close v2: more checks, locks on bills/payroll/time, pack for a closed month ---- */
const closeChecklistBase = closeChecklist;
closeChecklist = function(month){ const items = closeChecklistBase(month); const R = [month+'-01', month+'-31']; const add = (label, n, go) => items.push({label, n, go, ok:!n}); add('Bank accounts not reconciled through month-end', DB.accounts.filter(a => a.type==='bank' && !(a.recon && a.recon.date >= R[1].slice(0,8)+'01')).length, {view:'bank'}); add('Client payments not seen in the bank', undepositedReceipts().filter(x => within(x.py.date, R)).length, {view:'bank'}); add('Bills paid from the bank before approval', DB.bills.filter(b => b.paidBeforeApproval && !['paid','verified','void','rejected'].includes(b.status)).length, {view:'ap'}); add('Payroll runs past pay date not marked paid', DB.payroll.filter(r => r.payDate && r.payDate <= R[1] && !['paid','verified','void'].includes(r.status)).length, {view:'ap'}); add('Receivables over 60 days', arRows().filter(r => r.age > 60).length, {view:'reports', tab:'ar'}); add('Credits on account not applied', DB.clients.filter(c => clientFin(c).credits > 0).length, {view:'reports', tab:'ar'}); return items; };
const saveBillBase = saveBill; saveBill = function(){ const b = editing?.id ? DB.bills.find(x=>x.id===editing.id) : null; const date = $('#e-date')?.value || b?.date; if (date && isLocked(date)){ const why = prompt(`This bill is dated in a closed month (${date}). Reason for changing it:`); if (!why) return; try { audit('bill', b?.id||'new', 'locked-period-change', '', date, why); } catch(e){} } return saveBillBase(); };
const savePayrollBase = savePayroll; savePayroll = function(){ const date = $('#e-paydate')?.value; if (date && isLocked(date)){ const why = prompt(`This payroll run is dated in a closed month (${date}). Reason:`); if (!why) return; try { audit('payroll', editing?.id||'new', 'locked-period-change', '', date, why); } catch(e){} } return savePayrollBase(); };
const saveTimeBase = saveTime; saveTime = function(){ const date = $('#e-date')?.value || $('#e-tdate')?.value; if (date && isLocked(date)){ const why = prompt(`This time entry is dated in a closed month (${date}). Reason:`); if (!why) return; try { audit('time', editing?.id||'new', 'locked-period-change', '', date, why); } catch(e){} } return saveTimeBase(); };
let packMonth = '';
const repPackBase = repPack;
repPack = function(){ const closes = (DB.periods?.closes||[]).map(x=>x.month).sort().reverse(); const cur = today().slice(0,7); const pick = `<div class="rep-bar no-print"><label class="small">Month <select id="pack-month" class="btn sm"><option value="">${monthLabel(cur)} (open)</option>${closes.map(m => `<option value="${m}" ${packMonth===m?'selected':''}>${monthLabel(m)} (closed)</option>`).join('')}</select></label>${packMonth?`<span class="small muted">Prepared from the frozen close of ${monthLabel(packMonth)}.</span>`:''}</div>`; if (!packMonth) return pick + repPackBase(); const keepT = S.project.today; const end = iso(new Date(+packMonth.slice(0,4), +packMonth.slice(5,7), 0)); S.project.today = end; let h = ''; try { h = repPackBase(); } finally { S.project.today = keepT; } return pick + h; };
const renderReportsBase10 = renderReports;
renderReports = function(){ renderReportsBase10(); $('#pack-month')?.addEventListener('change', e => { packMonth = e.target.value; render(); }); if (repTab==='searches') seedSearches(); };
/* ---- 6. procurement: buyout from a draft estimate; delivery problem sheet ---- */
const docActionsBase6 = docActions;
docActions = function(c, d, st){ let h = docActionsBase6(c, d, st); if (d.type==='estimate' && d.status==='draft' && d.lines.length && !/data-docact="pos"/.test(h) && mbCanEdit()) h += `<button class="btn sm" data-docact="pos" title="Buy out long-lead items before award; the PO cannot be issued until the estimate is approved">Purchase orders from lines… (pre-award)</button>`; return h; };
const poActionBase2 = poAction;
poAction = function(po, a){ if (a==='issue'){ const src = po.lines.map(l => l.line && findLine(l.line)).find(Boolean); const d = src?.doc; if (d && d.type==='estimate' && !['approved','converted'].includes(d.status)){ toast(`${po.number} waits for ${d.number} to be approved — it is marked pre-award`); po.preAward = true; save(); render(); return; } po.preAward = false; } return poActionBase2(po, a); };
const poStateBase2 = poState;
poState = function(po){ const st = poStateBase2(po); if (po.status==='draft'){ const src = po.lines.map(l => l.line && findLine(l.line)).find(Boolean); if (src?.doc?.type==='estimate' && !['approved','converted'].includes(src.doc.status)){ st.flags.push('awaiting award'); if (st.sev < 2) st.sev = 2; st.msg = 'awaiting award'; } } return st; };
function deliveryProblem(po, host){ const p = DB.projects.find(x=>x.id===po.projectId); mbModal(`Delivery problem — ${esc(po.number)}`, `<label class="f"><span>What happened</span><select id="dp-type"><option value="short">Short — fewer than ordered</option><option value="damaged">Damaged</option><option value="wrong">Wrong item</option><option value="backorder">Back-ordered</option></select></label><label class="f"><span>Line</span><select id="dp-line">${po.lines.map(l=>`<option value="${l.id}">${esc(l.item||l.desc||'')}</option>`).join('')}</select></label><label class="f"><span>Quantity affected</span><input type="number" step="any" id="dp-qty" value="${po.lines[0]?Math.max(0,(+po.lines[0].qty||0)-(+po.lines[0].received||0)):0}"></label><label class="f"><span>New ETA (if known)</span><input type="date" id="dp-eta"></label><label class="f"><span>Note</span><input id="dp-note" placeholder="what the driver / vendor said"></label>`, {submit:'Report', onSubmit:()=>{ const type = $('#dp-type').value, lid = $('#dp-line').value, qty = +$('#dp-qty').value||0, eta = $('#dp-eta').value, note = $('#dp-note').value; const l = po.lines.find(x=>x.id===lid); (po.issues = po.issues||[]).push({t:nowStamp(), by:S.project.userName||role(), type, lineId:lid, qty, eta, note}); if (l){ l.backordered = qty; l.issue = type; } po.flag = `${type}: ${l?.item||''} ${qty}`; if (eta) po.expected = eta; else if (type==='backorder') po.expected = ''; const m = l?.materialId && p?.materials.find(mm=>mm.id===l.materialId); if (m){ m.eta = eta || ''; if (!eta) m.status = 'ordered'; m.notes = [m.notes, `${type} on ${po.number}${note?': '+note:''}`].filter(Boolean).join('\n'); } try { audit('po', po.id, 'delivery-issue', '', type, `${qty} ${l?.item||''} ${note}`); } catch(e){} log(`${po.number}: ${type} — ${l?.item||''} × ${qty}${eta?', new ETA '+fmt(eta):', no ETA'}${note?' — '+note:''}`); save(); render(); toast('Reported to purchasing'); }}); }
const renderRecvBase2 = renderRecv;
renderRecv = function(){ renderRecvBase2(); document.querySelectorAll('[data-rissue]').forEach(b => { const po = DB.pos.find(x=>x.id===b.dataset.rissue); b.onclick = () => deliveryProblem(po); }); };
const remindersBase10 = reminders;
reminders = function(){ const out = remindersBase10(); const bo = DB.pos.filter(po => (po.issues||[]).length && ['issued','partial'].includes(po.status) && !po.expected); if (bo.length) out.push({n:bo.length, label:`delivery problem${bo.length>1?'s':''} with no new ETA — ${bo.map(po=>po.vendor).join(', ')}`, go:{view:'po'}, sev:'bad'}); const pre = DB.pos.filter(po => po.preAward); if (pre.length) out.push({n:pre.length, label:`pre-award PO${pre.length>1?'s':''} waiting for the estimate to be approved`, go:{view:'po'}, sev:'warn'}); return out; };
/* ---- 7. one vendor card in the analyst; vendor chips in the picker ---- */
analystFindings = (function(base){ return function(){ const F = base(); const byV = {}; const keep = []; F.forEach(f => { const v = DB.vendors.find(x => (f.title+' '+(f.detail||'')).includes(x.name)); if (!v){ keep.push(f); return; } (byV[v.name] = byV[v.name]||[]).push(f); }); Object.entries(byV).forEach(([name, fs]) => { const v = DB.vendors.find(x=>x.name===name); const extras = []; if (v?.bankPending) extras.push('bank change unverified'); else if (v?.bankChangedAt && dayDiff(v.bankChangedAt, today()) <= 30) extras.push(`banking changed ${fmt(v.bankChangedAt)}`); const pb = DB.bills.filter(b => b.vendor===name && b.paidBeforeApproval && !['paid','verified','void','rejected'].includes(b.status)); if (pb.length) extras.push(`paid before approval (${pb.map(b=>b.number).join(', ')})`); const iss = complianceIssues({vendor:name, projectId:'', lines:[{amount:1000}]}).filter(x=>x.lvl==='block').map(x=>x.m); if (fs.length + extras.length + iss.length <= 1){ keep.push(...fs); return; } keep.push({sev: fs.some(f=>f.sev==='high') || extras.length ? 'high' : 'med', area:'Vendors', title:`${name}: ${[...fs.map(f => f.title.replace(new RegExp(name,'g'),'').replace(/^[\s:—-]+|[\s:—-]+$/g,'')), ...extras, ...iss].join(' · ')}`, detail:`${fs.map(f=>f.detail).join(' — ')}. Decide: approve the bill as billed, dispute the difference with the vendor, or hold payment until the vendor record is clean.`, amount:Math.max(0, ...fs.map(f=>f.amount||0), ...pb.map(b=>billTotal(b))), go:{view:'ap'}, merged:fs.length + extras.length}); }); return keep.sort((a,b) => ({high:0,med:1,low:2}[a.sev]-{high:0,med:1,low:2}[b.sev]) || (b.amount||0)-(a.amount||0)); }; })(analystFindings);
/* ---- 8. clients grid: what is unsigned, prepaid, and next to bill ---- */
const renderClientsBase = renderClients;
renderClients = function(){ renderClientsBase(); if (clientOpen) return; const tb = document.querySelector('#v-clients table'); if (!tb) return; const hr = tb.querySelector('thead tr'); if (!hr || hr.querySelector('.cx')) return; ['Unsigned','Billed ahead','Next bill'].forEach(l => { const th = document.createElement('th'); th.className = 'cx money'; th.textContent = l; hr.appendChild(th); }); const sugg = billingSuggestions(); tb.querySelectorAll('tbody tr').forEach(tr => { const c = DB.clients.find(x => tr.dataset.id===x.id || (tr.dataset.edit||'').endsWith(x.id) || tr.textContent.includes(x.name)); if (!c) return; const uns = r2([...c.estimates, ...c.changeOrders].filter(d=>d.status==='sent').reduce((a,d)=>a+docTotal(d).total,0)); const over = r2(DB.projects.filter(p=>p.clientId===c.id).reduce((a,p)=>a+jobFin(p).over,0)); const nb = sugg.filter(s => s.c.id===c.id).reduce((a,s)=>a+s.amount,0); [uns?money(uns):'—', over?money(over):'—', nb?money(nb):'—'].forEach((t,i) => { const td = document.createElement('td'); td.className = 'money cx' + (i===0 && uns ? ' warn' : ''); td.textContent = t; tr.appendChild(td); }); }); };

/* ===================== MATCHING WITH HUMAN VERIFICATION — the machine proposes, a person confirms ===================== */
/* Automatic matching (bank/card charge ↔ PO, bank/card charge ↔ bill) never links on its own. It records a proposal on the transaction with its reason; the person confirms or rejects it — on the PO, on the bill, in Banking, or from Needs me. Only a confirmed match pays a PO, pays a bill, or lands on a job line. A bill someone has already marked paid is the one exception: its bank charge links when found, because the human decision was already made. */
function proposeMatch(t, o){ t.proposal = Object.assign({t:nowStamp(), by:'auto'}, o); }
const matchPOBase = matchPO;
matchPO = function(po){ const snap = {}; DB.txns.forEach(t => { snap[t.id] = {poId:t.poId, projectId:t.projectId, cat:t.cat, status:t.status, actor:t.actor, line:t.line, noPO:t.noPO}; if (!t.poId && (t.rejectedPOs||[]).includes(po.id)) t.poId = '__rejected'; }); const before = new Set(po.matchedTxns||[]); let n = 0; try { n = matchPOBase(po); } finally { DB.txns.forEach(t => { if (t.poId==='__rejected') t.poId = snap[t.id].poId; }); }
  (po.matchedTxns||[]).filter(id => !before.has(id)).forEach(id => { const t = DB.txns.find(x=>x.id===id); po.matchedTxns = po.matchedTxns.filter(x => x!==id); if (!t) return; Object.assign(t, snap[t.id]); const tot = poTotal(po).total; const pct = tot ? Math.round(-t.amt/tot*100) : 0; proposeMatch(t, {kind:'po', poId:po.id, why:`${esc(t.vendor||t.desc)} · ${money(-t.amt)} is ${pct}% of ${po.number} (${money(tot)}) within ${(DB.company.matchTol||2)}%`}); }); return n; };
function confirmMatch(t){ const P = t.proposal; if (!P) return; const by = S.project.userName||role(); if (P.kind==='po'){ const po = DB.pos.find(x=>x.id===P.poId); if (!po){ t.proposal = null; return; } po.matchedTxns = po.matchedTxns||[]; if (!po.matchedTxns.includes(t.id)) po.matchedTxns.push(t.id); t.poId = po.id; t.noPO = false; if (!t.projectId) t.projectId = po.projectId; if (!t.cat || t.cat==='uncat'){ t.cat = poCat(po); t.status = 'categorized'; } if (!t.code && po.lines[0]?.code) t.code = po.lines[0].code; if (!t.line && po.lines.length===1 && po.lines[0].line) t.line = po.lines[0].line; t.matchedBy = by; t.matchedAt = today(); audit('txn', t.id, 'match-confirmed', '', po.number, `${by}: ${P.why}`); log(`${po.number}: ${money(-t.amt)} confirmed as payment by ${by}`); }
  if (P.kind==='bill'){ const b = DB.bills.find(x=>x.id===P.billId); if (!b){ t.proposal = null; return; } b.txnId = t.id; t.billId = b.id; if (!b.paidAt) b.paidAt = t.date; if (!['paid','verified'].includes(b.status)) b.paidBeforeApproval = true; else if (b.status==='paid') b.status = 'verified'; if (!t.projectId && b.projectId) t.projectId = b.projectId; if ((!t.cat || t.cat==='uncat') && b.cat){ t.cat = b.cat; t.status = 'categorized'; } t.matchedBy = by; t.matchedAt = today(); audit('bill', b.id, 'payment-confirmed', '', t.id, `${by}: ${P.why}`); } t.proposal = null; save(); }
function rejectMatch(t){ const P = t.proposal; if (!P) return; if (P.kind==='po'){ t.rejectedPOs = [...(t.rejectedPOs||[]), P.poId]; audit('txn', t.id, 'match-rejected', '', P.poId, S.project.userName||role()); } if (P.kind==='bill'){ t.rejectedBills = [...(t.rejectedBills||[]), P.billId]; audit('txn', t.id, 'match-rejected', '', P.billId, S.project.userName||role()); } t.proposal = null; save(); }
const proposals = () => DB.txns.filter(t => t.proposal);
/* bills: propose unless the bill is already marked paid by a person */
linkBankToBills = function(){ let n = 0; DB.bills.filter(b => !['void','rejected','draft'].includes(b.status) && !b.txnId && !b.ic).forEach(b => { const t = billMatchTxn(b); if (!t || t.proposal || (t.rejectedBills||[]).includes(b.id)) return; if (['paid','verified'].includes(b.status)){ b.txnId = t.id; t.billId = b.id; if (!b.paidAt) b.paidAt = t.date; if (b.status==='paid') b.status = 'verified'; n++; } else { proposeMatch(t, {kind:'bill', billId:b.id, why:`${esc(t.vendor||t.desc)} · ${money(-t.amt)} on ${fmt(t.date)} looks like bill ${b.number} (${money(billTotal(b))}, ${b.status})`}); } }); return n; };
/* the proposal list — one card, used on Banking, on a PO, on a bill */
function proposalsHtml(list, title){ if (!list.length) return ''; return `<div class="card prop-card"><div class="row" style="align-items:baseline"><h3 style="margin:0">${title||'Matches waiting for your confirmation'}</h3><span class="small muted" style="margin-left:8px">${list.length} — nothing is linked until you say so</span></div>${list.map(t => { const P = t.proposal; const target = P.kind==='po' ? DB.pos.find(x=>x.id===P.poId) : DB.bills.find(x=>x.id===P.billId); const label = P.kind==='po' ? `${target?.number||'PO'} · ${esc(target?.vendor||'')} · ordered ${money(target?poTotal(target).total:0)}` : `Bill ${target?.number||''} · ${esc(target?.vendor||'')} · ${money(target?billTotal(target):0)} · ${target?.status||''}`; return `<div class="prop-row"><div class="prop-main"><b>${fmt(t.date)} · ${esc(t.desc)}</b> <span class="small muted">${money(-t.amt)} · ${esc(DB.accounts.find(a=>a.id===t.acct)?.name||'')}</span><div class="small">→ ${label}</div><div class="small muted">${P.why}</div></div><div class="prop-acts"><button class="btn sm primary" data-mconfirm="${t.id}">Confirm</button><button class="btn sm" data-mreject="${t.id}">Not this</button></div></div>`; }).join('')}</div>`; }
function wireProposals(root){ (root||document).querySelectorAll('[data-mconfirm]').forEach(b => b.onclick = () => { const t = DB.txns.find(x=>x.id===b.dataset.mconfirm); confirmMatch(t); render(); toast('Match confirmed'); }); (root||document).querySelectorAll('[data-mreject]').forEach(b => b.onclick = () => { const t = DB.txns.find(x=>x.id===b.dataset.mreject); rejectMatch(t); render(); toast('Kept unmatched'); }); }
const renderBankBase2 = renderBank;
renderBank = function(){ renderBankBase2(); const host = $('#txn-table'); if (!host) return; document.querySelector('#v-bank .prop-card')?.remove(); const html = proposalsHtml(proposals()); if (html){ const div = document.createElement('div'); div.innerHTML = html; host.before(div.firstChild); wireProposals($('#v-bank')); } };
const renderPODocBase2 = renderPODoc;
renderPODoc = function(po){ const list = proposals().filter(t => t.proposal.kind==='po' && t.proposal.poId===po.id); let h = renderPODocBase2(po); if (!list.length) return h;
  const card = proposalsHtml(list, 'Proposed by matching — confirm to link').replace('class="card prop-card"', 'class="prop-card" style="margin-top:8px"'); list.forEach(t => { h = h.replace(new RegExp(`<div class="chg"><span>[^<]*</span>[^<]*<b style="float:right">[^<]*</b> <a href="#" data-match="${t.id}"[^>]*>match</a></div>`), ''); });
  h = h.replace(/<div class="small" style="margin-top:8px"><b>Possible matches<\/b><\/div>/, ''); const anchor = '<div class="muted small">Nothing matched yet.</div>'; const anchor2 = 'Possible matches</b>'; if (h.includes(anchor)) return h.replace(anchor, anchor + card); const i = h.indexOf('<div class="small" style="margin-top:8px"><b>' + anchor2); if (i > -1) return h.slice(0,i) + card + h.slice(i); return h + card; };
const wirePODocBase2 = wirePODoc;
wirePODoc = function(po){ wirePODocBase2(po); wireProposals($('#po-doc')); };
const openBillBase2 = openBill;
openBill = function(id){ openBillBase2(id); const body = $('#d-body'); const list = proposals().filter(t => t.proposal.kind==='bill' && t.proposal.billId===id); if (!body || !list.length) return; const div = document.createElement('div'); div.innerHTML = proposalsHtml(list, 'Is this the payment?'); body.prepend(div.firstChild); wireProposals(body); };
/* poState: a proposed payment is not a paid PO */
const remindersBase11 = reminders;
reminders = function(){ const out = remindersBase11(); const P = proposals(); if (P.length) out.unshift({n:P.length, label:`bank/card charge${P.length>1?'s':''} matched to a PO or bill — confirm or reject · ${money(P.reduce((a,t)=>a-t.amt,0))}`, go:{view:'bank'}, sev:'warn'}); return out; };
const closeChecklistBase2 = closeChecklist;
closeChecklist = function(month){ const items = closeChecklistBase2(month); const R = [month+'-01', month+'-31']; const n = proposals().filter(t => within(t.date, R)).length; items.push({label:'Bank matches not yet confirmed by a person', n, go:{view:'bank'}, ok:!n}); return items; };
/* the machine's own categorize-and-match keeps the same rule: propose, never link */
const txnStateBase = txnState;
txnState = function(t){ if (t.proposal) return {sev:2, msg:`Proposed match → ${t.proposal.kind==='po' ? (DB.pos.find(x=>x.id===t.proposal.poId)?.number||'PO') : 'bill ' + (DB.bills.find(x=>x.id===t.proposal.billId)?.number||'')} — confirm`}; return txnStateBase(t); };

/* ===================== LINE CATEGORIES — Category › Subcategory (cost code) set once on the estimate line, inherited everywhere ===================== */
/* Design gets real cost codes; the subcategory IS the cost code, filtered by the line's main category. Budget defaults from the category's target margin when the estimator leaves cost blank; design/hourly lines carry an hours budget. */
(() => { const add = [['15','Architecture',['arch']],['16','Interior design',['int']],['17','MEP engineering',['mep']],['18','Structural engineering',['struct']],['19','Filing & expediting',['file']],['20','Testing & surveys',['test']],['21','Special inspections',['sinsp']]]; add.forEach(c => { if (!COST_CODES.some(x => x[0]===c[0])) COST_CODES.splice(COST_CODES.length-1, 0, c); }); })();
const LINE_CATS = { design:{n:'Design', codes:['15','16','17','18','19','20','21','14']}, construction:{n:'Construction', codes:['01','02','03','04','05','06','07','08','09','10','11','12','13','14']}, materials:{n:'Finish materials', codes:['04','08','09','10','11','13']} };
const CAT_ORDER = ['design','construction','materials'];
LINE_KW.unshift(['architect','15'],['schematic','15'],['design development','15'],['construction document','15'],['construction administration','15'],['interior','16'],['mep','17'],['mechanical','17'],['engineer','17'],['structur','18'],['filing','19'],['expedit','19'],['asbestos','20'],['survey','20'],['testing','20'],['special inspection','21']);
function lineCat(l, d){ if (l.cat && LINE_CATS[l.cat]) return l.cat; const t = d?.template; if (t==='design') return 'design'; if (t==='materials' || t==='finish') return 'materials'; const code = l.code || ''; if (['15','16','17','18','19','20','21'].includes(code)) return 'design'; return 'construction'; }
function lineCode(l, d){ if (l.code) return l.code; const cat = lineCat(l, d); const guess = codeForLine(l); if (LINE_CATS[cat].codes.includes(guess)) return guess; if (cat==='design') return '15'; if (cat==='materials') return '13'; return guess; }
function codeName(code){ return (COST_CODES.find(x=>x[0]===code)||[code,'Other'])[1]; }
function catLabel(l, d){ const cat = lineCat(l, d); const code = lineCode(l, d); return `${LINE_CATS[cat].n} › ${codeName(code)}`; }
function targetMarginFor(cat){ const tm = DB.company.targetMargin || {}; return +tm[cat] || (+DB.company.minMargin || 20); }
/* budget: entered cost, else price × (1 − target margin). `defaulted` tells the UI it's an assumption. */
function lineBudget(l, d){ const cost = +l.cost || 0; if (cost) return {budget:cost, defaulted:false}; const price = d ? lineAmount(l, d) : 0; return {budget: r2(price * (1 - targetMarginFor(lineCat(l, d))/100)), defaulted:true}; }
function lineHoursBudget(l){ if (+l.hoursBudget) return +l.hoursBudget; if ((l.unit||'')==='hr') return +l.qty||0; return 0; }
/* one cell: Category › Subcategory (+ hours budget for design/hourly lines). attr = 'data-ctf' (construction template) or 'data-f' (generic lines) */
function catCodeCell(l, d, attr, editable){ const cat = lineCat(l, d); const code = lineCode(l, d); const dis = editable===false ? 'disabled' : ''; const codes = LINE_CATS[cat].codes.map(c => `<option value="${c}" ${c===code?'selected':''}>${c} ${esc(codeName(c))}</option>`).join('');
  return `<select ${attr}="cat" class="cat-sel" ${dis} title="Category">${CAT_ORDER.map(k => `<option value="${k}" ${k===cat?'selected':''}>${LINE_CATS[k].n}</option>`).join('')}</select><span class="cat-sep">›</span><select ${attr}="code" class="cat-sel" ${dis} title="Subcategory = cost code">${codes}</select>${cat==='design' || (l.unit||'')==='hr' ? `<span class="cat-hrs">hrs budget <input ${attr}="hoursBudget" type="number" step="any" value="${l.hoursBudget||''}" placeholder="${(l.unit||'')==='hr' ? l.qty||'' : ''}" ${dis}></span>` : ''}`; }
/* when the category changes, the code must belong to it */
function catFix(l, d){ const cat = lineCat(l, d); if (!LINE_CATS[cat].codes.includes(l.code||'')) l.code = LINE_CATS[cat].codes.includes(codeForLine(l)) ? codeForLine(l) : LINE_CATS[cat].codes[0]; }
/* ct template: the Code select becomes Category › Subcategory */
const ctLinesHtmlBase = ctLinesHtml;
ctLinesHtml = function(c, d, editable, kind){ let h = ctLinesHtmlBase(c, d, editable, kind); ctOrdered(d).forEach(l => { const re = new RegExp(`<span>Code <select data-ctf="code">[\\s\\S]*?</select></span>`); const idx = h.indexOf(`data-ctl="${l.id}"`); if (idx<0) return; const tail = h.slice(idx); const m = tail.match(re); if (!m) return; h = h.slice(0, idx) + tail.replace(m[0], `<span class="cat-cell">${catCodeCell(l, d, 'data-ctf', editable)}</span>`); }); return h; };
const ctWireBase = ctWire;
ctWire = function(c, d, root, editable){ ctWireBase(c, d, root, editable); root.querySelectorAll('[data-ctl]').forEach(row => { const l = d.lines.find(x => x.id===row.dataset.ctl); if (!l) return; row.querySelectorAll('[data-ctf="cat"],[data-ctf="code"],[data-ctf="hoursBudget"]').forEach(inp => inp.addEventListener('change', () => { const f = inp.dataset.ctf; if (f==='hoursBudget') l.hoursBudget = +inp.value||0; else l[f] = inp.value; if (f==='cat') catFix(l, d); save(); render(); })); }); };
/* generic lines table (design, finish materials, invoices): a Category › Subcategory internal cell before Budget cost */
function catPatchLinesTable(html, d){ if (!html.includes('data-f="cost"')) return html; html = html.replace('<th class="int money" style="width:112px" title="Internal — not printed">Budget cost</th>', '<th class="int" style="width:250px" title="Internal — not printed">Category › Subcategory</th><th class="int money" style="width:112px" title="Internal — not printed">Budget cost</th>'); d.lines.forEach(l => { const marker = `data-line="${l.id}"`; const i = html.indexOf(marker); if (i<0) return; const j = html.indexOf('<td class="int"><input class="num" type="number" step="any" data-f="cost"', i); if (j<0) return; html = html.slice(0,j) + `<td class="int cat-cell">${catCodeCell(l, d, 'data-f', true)}</td>` + html.slice(j); }); return html; }
/* hook: docs render through renderDocs → docHtml; patch the built string */
const renderDocEditorBase_cat = renderDocEditor;
renderDocEditor = function(c, d){ const h = renderDocEditorBase_cat(c, d); if (!d || !d.lines) return h; return (d.template==='construction' && d.mode!=='sov') || d.mode==='sov' ? h : catPatchLinesTable(h, d); };
/* the estimator can't send with uncategorized lines: the guess is applied, and shown */
const docActionBase_cat = docAction;
docAction = async function(c, d, a){ if (a==='send' && d.type!=='invoice'){ let n = 0; d.lines.forEach(l => { if (!l.cat){ l.cat = lineCat(l, d); n++; } if (!l.code){ l.code = lineCode(l, d); n++; } }); if (n) toast(`${n} line categor${n>1?'ies':'y'} set from the item names — check them under Show internal`); } return docActionBase_cat(c, d, a); };
/* line-level P&L: budget (defaulted), hours, over-budget on committed + actual, hours over budget */
const lineFinBase_cat = lineFin;
lineFin = function(key){ const f = lineFinBase_cat(key); if (!f) return f; const {line:l, doc:d} = f; const B = lineBudget(l, d); f.budget = B.budget; f.budgetDefaulted = B.defaulted; f.cat = lineCat(l, d); f.code = lineCode(l, d); f.catLabel = catLabel(l, d); f.projCost = Math.max(f.budget, f.actual, f.committed + f.actual); f.margin = r2(f.price - f.projCost); f.marginPct = f.price ? Math.round(f.margin/f.price*100) : 0;
  const hb = lineHoursBudget(l); const hrs = r2(DB.time.filter(t => t.status!=='rejected' && ((t.line===key) || (t.work||[]).some(w => w.line===key))).reduce((a,t) => a + ((t.line===key) ? hoursOf(t) : (t.work||[]).filter(w=>w.line===key).reduce((b,w)=>b+(+w.hours||0),0)), 0) + DB.bills.filter(b => b.line===key && !['void','rejected'].includes(b.status)).reduce((a,b) => a + (b.lines||[]).reduce((s,x) => s + ((x.unit||'')==='hr' ? +x.qty||0 : 0), 0), 0));
  f.hoursBudget = hb; f.hours = hrs; const tol = 1 + (+DB.company.budgetTol ?? 5)/100; const flags = f.flags.filter(x => !['over budget','over-committed'].includes(x)); if (f.budget && f.committed + f.actual > f.budget*tol) flags.push(`committed + actual ${money(f.committed+f.actual)} over budget ${money(f.budget)}`); if (hb && hrs > hb*tol) flags.push(`${hrs} of ${hb} hours used`); else if (hb && hrs > hb*0.75) flags.push(`${Math.round(hrs/hb*100)}% of hours used`); f.flags = flags; return f; };
const lineProfitBase_cat = lineProfit;
lineProfit = function(p){ return lineProfitBase_cat(p).map(r => { const B = lineBudget(r.line, r.doc); if (B.defaulted && !r.budget){ r.budget = B.budget; r.budgetDefaulted = true; } r.cat = lineCat(r.line, r.doc); r.code = lineCode(r.line, r.doc); r.catLabel = catLabel(r.line, r.doc); return r; }); };
/* migration: existing lines get their category + code once so downstream never guesses again */
function catMigrate(){ if (DB.__catv) return; DB.clients.forEach(c => [...c.estimates, ...c.changeOrders, ...c.invoices].forEach(d => (d.lines||[]).forEach(l => { if (!l.cat) l.cat = lineCat(l, d); if (l.cat==='design' && !DESIGN_CODES.includes(l.code||'')) l.code = ''; if (!l.code) l.code = lineCode(l, d); }))); DB.time.forEach(t => { const e = DB.employees.find(x=>x.id===t.empId); if (empDept(e)==='design' && !DESIGN_CODES.includes(t.code||'')) t.code = '15'; (t.work||[]).forEach(w => { if (empDept(e)==='design' && !DESIGN_CODES.includes(w.code||'')) w.code = '15'; }); }); DB.company.targetMargin = DB.company.targetMargin || {design:35, construction:25, materials:25}; DB.company.budgetTol = DB.company.budgetTol ?? 5; DB.__catv = 1; }

/* ===================== OVERHEAD — one pool, two departments, two rates; margins gross or fully burdened ===================== */
/* Pool = everything coded overhead (bills, bank, office payroll) + hours nobody logged to a job. Each overhead category and each employee is tagged Design / Construction / Shared; Shared splits by project hours. Each department's pool ÷ its direct job cost = the rate. Burden on a line = its direct cost × the rate of its department (design codes 15–21, everything else construction). Rates are trailing 3 full months; the month to date is shown beside them so drift is visible before close. */
const DESIGN_CODES = ['15','16','17','18','19','20','21'];
const deptOfCode = code => DESIGN_CODES.includes(code) ? 'design' : 'construction';
const OH_DEPT_DEFAULT = {insurance:'construction', vehicle:'construction', office:'shared', marketing:'shared', 'payroll-oh':'shared', payroll_oh:'shared', meals:'shared', taxes:'shared'};
function ohDeptOfCat(cat){ return (DB.company.ohDept||{})[cat] || OH_DEPT_DEFAULT[cat] || 'shared'; }
function empDept(e){ if (!e) return 'construction'; if (e.dept) return e.dept; const r = (e.role||'').toLowerCase(); if (/architect|design|draft|interior/.test(r)) return 'design'; if (/coordinator|office|admin|book|account|owner|ceo|manager/.test(r)) return 'office'; return 'construction'; }
function monthsBack(n, end){ const out = []; const d = parse(end||today()); d.setDate(1); for (let i=0;i<n;i++){ d.setMonth(d.getMonth()-1); out.unshift(d.toISOString().slice(0,7)); } return out; }
const monthRange = m => [m+'-01', m+'-31'];
/* the pool for a range */
function ohPool(range, base){ const saveEnt = repEntity; const items = []; const by = {design:0, construction:0, shared:0};
  ledger(range).filter(r => !r.income && catType(r.cat)==='oh').forEach(r => { const dept = ohDeptOfCat(r.cat); by[dept] += r.amt; items.push({date:r.date, desc:r.desc, cat:r.cat, dept, amt:r.amt}); });
  DB.time.filter(t => !t.projectId && t.status!=='rejected' && within(t.date, range)).forEach(t => { const e = DB.employees.find(x=>x.id===t.empId); const h = hoursOf(t); if (!h) return; const amt = r2(h*laborRate(e)); const d0 = empDept(e); const dept = d0==='office' ? 'shared' : d0; by[dept] += amt; items.push({date:t.date, desc:`${e?.name||t.empId} · ${h} h not on a job`, cat:'unlogged', dept, amt}); });
  const hrs = {design:0, construction:0}; DB.time.filter(t => t.projectId && t.status!=='rejected' && within(t.date, range)).forEach(t => { const e = DB.employees.find(x=>x.id===t.empId); const d0 = empDept(e); if (d0==='office') return; hrs[d0] += hoursOf(t); });
  const hT = hrs.design + hrs.construction; const B = base || ohBase(range); const bT = B.design + B.construction; const dShare = (hrs.design && hrs.construction) ? hrs.design/hT : bT ? B.design/bT : 0.3; const splitBy = (hrs.design && hrs.construction) ? 'project hours' : bT ? 'direct cost' : 'default'; const shared = r2(by.shared);
  return {items, design:{own:r2(by.design), shared:r2(shared*dShare), total:r2(by.design + shared*dShare)}, construction:{own:r2(by.construction), shared:r2(shared*(1-dShare)), total:r2(by.construction + shared*(1-dShare))}, shared, sharedSplit:{design:Math.round(dShare*100), construction:Math.round((1-dShare)*100), by:splitBy}, hours:hrs, total:r2(by.design+by.construction+shared)}; }
/* direct job cost for a range, split by department of the cost code */
function ohBase(range){ const base = {design:0, construction:0}; DB.projects.forEach(p => { const J = jobFin(p, range); (J.byCode||[]).forEach(r => { base[deptOfCode(r.code)] += r.actual||0; }); }); base.design = r2(base.design); base.construction = r2(base.construction); return base; }
function ohRates(range){ const B = ohBase(range); const P = ohPool(range, B); const rate = d => B[d] ? P[d].total/B[d] : 0; return {range, pool:P, base:B, design:{pool:P.design.total, base:B.design, rate:rate('design')}, construction:{pool:P.construction.total, base:B.construction, rate:rate('construction')}}; }
let __ohCache = null;
function ohCurrent(){ const key = today()+'|'+JSON.stringify(DB.company.ohDept||{})+'|'+DB.bills.length+'|'+DB.txns.length+'|'+DB.time.length; if (__ohCache && __ohCache.key===key) return __ohCache.v; const months = monthsBack(3); let R = ohRates([months[0]+'-01', months[months.length-1]+'-31']); R.basis = `trailing 3 months (${months[0]} → ${months[months.length-1]})`; if (!R.base.design && !R.base.construction){ R = ohRates(['', today()]); R.basis = 'all time (no closed months yet)'; } const m = today().slice(0,7); R.mtd = ohRates(monthRange(m)); R.months = monthsBack(6).map(mm => { const x = ohRates(monthRange(mm)); return {m:mm, design:x.design.rate, construction:x.construction.rate, pool:x.pool.total}; }); __ohCache = {key, v:R}; return R; }
function burdenRate(code){ return ohCurrent()[deptOfCode(code)].rate; }
function burdenOf(cost, code){ return r2((+cost||0) * burdenRate(code)); }
const pct1 = x => (Math.round(x*1000)/10) + '%';
/* view state: gross or burdened, remembered */
const burdened = () => (DB.company.burdenView||'gross')==='burdened';
function burdenToggleHtml(){ return `<div class="seg sm" id="burden-seg"><button class="${burdened()?'':'on'}" data-burden="gross">Gross</button><button class="${burdened()?'on':''}" data-burden="burdened">After overhead</button></div>`; }
document.addEventListener('click', e => { const b = e.target.closest('[data-burden]'); if (!b) return; DB.company.burdenView = b.dataset.burden; save(); render(); });
/* line P&L: burden + true margin */
const lineFinBase_oh = lineFin;
lineFin = function(key){ const f = lineFinBase_oh(key); if (!f) return f; const code = f.code || lineCode(f.line, f.doc); f.burdenRate = burdenRate(code); f.burden = burdenOf(f.projCost, code); f.trueMargin = r2(f.margin - f.burden); f.trueMarginPct = f.price ? Math.round(f.trueMargin/f.price*100) : 0; return f; };
const lineProfitBase_oh = lineProfit;
lineProfit = function(p){ return lineProfitBase_oh(p).map(r => { const code = r.code || lineCode(r.line, r.doc); const projCost = Math.max(r.budget, r.actual + r.committed); r.burdenRate = burdenRate(code); r.burden = burdenOf(projCost, code); r.trueMargin = r2(r.margin - r.burden); r.trueMarginPct = r.price ? r.trueMargin/r.price*100 : 0; if (burdened() && r.price && r.trueMarginPct < 5) r.flags = [...r.flags, `${r.trueMarginPct<0?'loses money':'thin'} after overhead · ${Math.round(r.trueMarginPct)}%`]; return r; }); };
/* job P&L: burden by code */
const projectProfitBase_oh = projectProfit;
projectProfit = function(p){ const r = projectProfitBase_oh(p); const J = r.J; let burden = 0; (J.byCode||[]).forEach(c => { const proj = Math.max(c.budget||0, (c.actual||0) + (c.committed||0)); burden += burdenOf(proj, c.code); }); r.burden = r2(burden); r.trueMargin = r2(r.margin - r.burden); r.trueMarginPct = r.contract ? Math.round(r.trueMargin/r.contract*100) : 0; r.rates = ohCurrent(); return r; };
/* Line profitability table: toggle + two columns when burdened */
const renderLineProfitBase_oh = renderLineProfit;
renderLineProfit = function(){ renderLineProfitBase_oh(); const host = $('#jl-table'); if (!host) return; const bar = $('#jl-filter'); if (bar && !$('#burden-seg')){ const d = document.createElement('span'); d.innerHTML = burdenToggleHtml(); bar.after(d.firstChild); } if (!burdened()) return; const rows = lineProfit(S).filter(r => jlFilter!=='flag' || r.flags.length); const R = ohCurrent(); const tbl = host.querySelector('table'); if (!tbl) return; const th = tbl.querySelector('thead tr'); const ref = [...th.children].find(x => /Margin %/.test(x.textContent)); const h1 = document.createElement('th'); h1.className='money'; h1.textContent='Overhead'; const h2 = document.createElement('th'); h2.className='money'; h2.textContent='After overhead'; ref.after(h1, h2); [...tbl.querySelectorAll('tbody tr')].forEach((tr, i) => { const r = rows[i]; const cells = tr.children; const anchor = cells[7]; if (!anchor) return; const c1 = document.createElement('td'); c1.className='money'; const c2 = document.createElement('td'); c2.className='money'; if (r){ c1.innerHTML = `${money(r.burden)}<span class="sub" style="margin-left:4px">${pct1(r.burdenRate)}</span>`; c2.innerHTML = `${money(r.trueMargin)} · ${Math.round(r.trueMarginPct)}%`; c2.className += r.trueMarginPct < 0 ? ' flag' : ''; } else { const rowsT = lineProfit(S); c1.textContent = money(r2(rowsT.reduce((a,x)=>a+x.burden,0))); c2.textContent = money(r2(rowsT.reduce((a,x)=>a+x.trueMargin,0))); } anchor.after(c1, c2); }); const note = document.createElement('div'); note.className = 'small muted'; note.style.marginTop = '6px'; note.textContent = `Overhead rates: design ${pct1(R.design.rate)} · construction ${pct1(R.construction.rate)} of direct cost — ${R.basis}.`; host.append(note); };
/* Project profitability report: overhead is never optional here */
const repProfitBase_oh = repProfit;
repProfit = function(){ let h = repProfitBase_oh(); const p = DB.projects.find(x=>x.id===repProj); if (!p) return h; const r = projectProfit(p); const R = r.rates; const kpi = (label, v, sub, cls='') => `<div class="kpi ${cls}"><b>${typeof v==='number'?money(v):v}</b><span>${label}${sub?` · ${sub}`:''}</span></div>`; const block = `<h3 class="rep-h">After overhead</h3><div class="fin rep-kpis">${kpi('Overhead burden', r.burden, `design ${pct1(R.design.rate)} · construction ${pct1(R.construction.rate)} of projected cost`)}${kpi('Margin after overhead', `${money(r.trueMargin)} · ${r.trueMarginPct}%`, `gross ${r.marginPct}%`, r.trueMargin < 0 ? 'bad' : r.trueMarginPct < 10 ? 'warn' : 'good')}</div><div class="small muted" style="margin:-4px 0 10px">Rates are ${R.basis}; month to date: design ${pct1(R.mtd.design.rate)} · construction ${pct1(R.mtd.construction.rate)}.</div>`; const i = h.indexOf('<h3 class="rep-h">'); const j = h.indexOf('<h3 class="rep-h">', h.indexOf('Cost &amp; margin')>-1 ? h.indexOf('Cost &amp; margin') : h.indexOf('Cost & margin')); const k = j>-1 ? h.indexOf('<h3 class="rep-h">', j+10) : -1; return k>-1 ? h.slice(0,k) + block + h.slice(k) : h + block; };
/* Financials: the overhead card — pool, split, rates, trend */
function ohCardHtml(){ const R = ohCurrent(); const P = R.pool; const trend = R.months.map(m => `<tr><td class="dim">${m.m}</td><td class="money">${money(m.pool)}</td><td class="money">${pct1(m.design)}</td><td class="money">${pct1(m.construction)}</td></tr>`).join('');
  return `<div class="card oh-card"><div class="row" style="align-items:baseline"><h3 style="margin:0">Overhead rates</h3><span class="small muted" style="margin-left:8px">${R.basis}</span><span class="grow"></span><a href="#" class="small" data-ohsetup>Departments &amp; tags…</a></div>
    <div class="cash-grid" style="grid-template-columns:repeat(4,1fr)"><div><span>Design rate</span><b>${pct1(R.design.rate)}</b><i>${money(R.design.pool)} ÷ ${money(R.design.base)} direct</i></div><div><span>Construction rate</span><b>${pct1(R.construction.rate)}</b><i>${money(R.construction.pool)} ÷ ${money(R.construction.base)} direct</i></div><div><span>Overhead pool</span><b>${money(P.total)}</b><i>design ${money(P.design.own)} · construction ${money(P.construction.own)} · shared ${money(P.shared)}</i></div><div><span>Shared split</span><b>${P.sharedSplit.design}% / ${P.sharedSplit.construction}%</b><i>by ${P.sharedSplit.by} · ${r2(P.hours.design)} h design · ${r2(P.hours.construction)} h construction</i></div></div>
    <div class="small muted" style="margin:6px 0">${R.mtd.pool.total ? `Month to date: design ${pct1(R.mtd.design.rate)} · construction ${pct1(R.mtd.construction.rate)} · pool ${money(R.mtd.pool.total)}.` : 'Nothing posted to overhead yet this month.'} Rates apply to every line's projected cost when margins are shown after overhead.</div>
    <details><summary class="small">Six-month trend</summary><table class="t" style="margin-top:6px"><thead><tr><th>Month</th><th class="money">Pool</th><th class="money">Design</th><th class="money">Construction</th></tr></thead><tbody>${trend}</tbody></table></details></div>`; }
const repFinancialsBase_oh = repFinancials;
repFinancials = function(){ return repFinancialsBase_oh() + ohCardHtml(); };
function ohSetupDialog(){ const ohCats = CATEGORIES.filter(c => c.type==='oh'); const emps = DB.employees.filter(e => e.active!==false); const sel = (v, opts, attr) => `<select ${attr}>${opts.map(o => `<option value="${o}" ${o===v?'selected':''}>${o[0].toUpperCase()+o.slice(1)}</option>`).join('')}</select>`;
  mbModal('Overhead — departments', `<p class="small muted">Tag each overhead category and each person. Shared is split by project hours every month. Office staff time never lands on a job; their unlogged hours are shared overhead.</p><h4>Overhead categories</h4>${ohCats.map(c => `<div class="row" style="padding:4px 0;border-top:1px solid var(--rule)"><span class="grow">${esc(c.n)}</span>${sel(ohDeptOfCat(c.id), ['design','construction','shared'], `data-ohcat="${c.id}"`)}</div>`).join('')}<h4 style="margin-top:12px">People</h4>${emps.map(e => `<div class="row" style="padding:4px 0;border-top:1px solid var(--rule)"><span class="grow">${esc(e.name)} <span class="small muted">${esc(e.role||'')}</span></span>${sel(empDept(e), ['design','construction','office'], `data-ohemp="${e.id}"`)}</div>`).join('')}`, {submit:'Save', onSubmit:() => { DB.company.ohDept = DB.company.ohDept||{}; document.querySelectorAll('[data-ohcat]').forEach(s => DB.company.ohDept[s.dataset.ohcat] = s.value); document.querySelectorAll('[data-ohemp]').forEach(s => { const e = DB.employees.find(x=>x.id===s.dataset.ohemp); if (e) e.dept = s.value; }); __ohCache = null; save(); render(); }}); }
document.addEventListener('click', e => { const a = e.target.closest('[data-ohsetup]'); if (!a) return; e.preventDefault(); ohSetupDialog(); });
/* seed: a few months of overhead so the rates mean something */
if (!CATEGORIES.some(c=>c.id==='design-software')) CATEGORIES.splice(CATEGORIES.findIndex(c=>c.id==='office')+1, 0, {id:'design-software', n:'Design software (CAD, rendering)', type:'oh'});
OH_DEPT_DEFAULT['design-software'] = 'design';
function ohSeed(){ if (DB.__ohSeed || !DB.projects.some(p=>p.id==='p121')) return; DB.__ohSeed = 1; const A = DB.accounts.find(a=>a.type==='bank'); if (!A) return; const months = monthsBack(6); let n = 0, tot = 0; months.forEach(m => { const add = (d, desc, vendor, cat, amt) => { if (DB.txns.some(t => t.desc===desc && t.date.startsWith(m))) return; DB.txns.push({id:'toh'+m.replace('-','')+d+desc.toLowerCase().replace(/[^a-z]/g,'').slice(0,8), date:`${m}-${d}`, acct:A.id, desc, vendor, amt:-amt, cat, status:'reconciled', actor:'rule', seed:'oh'}); n++; tot += amt; }; add('01', 'RENT 148 ATLANTIC AVE', 'Atlantic Realty', 'office', 1200); add('03', 'CON EDISON', 'Con Edison', 'office', 100); add('05', 'AUTODESK AEC COLLECTION', 'Autodesk', 'design-software', 410); add('05', 'ADOBE CREATIVE CLOUD', 'Adobe', 'design-software', 90); add('05', 'ENSCAPE RENDERING', 'Enscape', 'design-software', 65); add('06', 'ANTHROPIC CLAUDE', 'Anthropic', 'office', 100); add('10', 'HARTFORD GL INSURANCE', 'Hartford', 'insurance', 300); add('12', 'GEICO COMMERCIAL AUTO', 'Geico', 'vehicle', 120); add('15', 'SHELL FUEL', 'Shell', 'vehicle', 80); }); if (A.opening!=null) A.opening = r2(A.opening + tot); /* cash stays where it was */ }

/* ===================== PURCHASE ORDER v2 — typed, entity-aware, approved by a person, every field a data point ===================== */
/* One PO document with a Type switch (materials / subcontract / equipment / service) instead of two documents. Vendor, entity, ship-to, ship-via, terms, tax, unit and cost code are dropdowns — the exact-match fields are what make bank matching, insurance/W-9 gates, 1099, committed-by-code and vendor performance work. Cost code inherits from the estimate line the PO was made from. Above the approval threshold the Owner approves before it can be issued. */
const PO_TYPES = {materials:'Materials', subcontract:'Subcontract', equipment:'Equipment / rental', service:'Service'};
const PO_TYPE_CAT = {materials:'materials', subcontract:'subs', equipment:'equipment', service:'subs'};
const SHIP_TO = {site:'Job site', shop:'Shop / office', willcall:'Will-call — we pick up', vendor:'Vendor holds', other:'Other…'};
const SHIP_VIA = {vendor:'Vendor truck', freight:'Freight / LTL', courier:'Courier', pickup:'We pick up'};
const TAX_STATUS = {taxable:'Taxable', 'exempt-ci':'Exempt — capital improvement (ST-124)', 'exempt-resale':'Exempt — resale', none:'No tax (labor / service)'};
const PO_UNITS = ['ea','sf','lf','sy','cy','ls','hr','day','wk','box','roll','sheet','set','kit','gal','ton','pallet','pair','bag'];
const TERMS_PRESETS = [['delivery','100% on delivery', {dep:0, bal:'on delivery'}], ['5050','50% deposit · 50% on delivery', {dep:50, bal:'on delivery'}], ['net30','Net 30 after delivery', {dep:0, bal:'net', days:30}], ['dep-net30','Deposit · net 30 after delivery', {dep:30, bal:'net', days:30}], ['progress','Progress billing (subcontract)', {dep:0, bal:'net', days:15}], ['custom','Custom…', null]];
const poCat = po => PO_TYPE_CAT[po.type||'materials'] || 'materials';
const poEntity = po => po.entityId || entityOfProject(DB.projects.find(p=>p.id===po.projectId)||{});

function poNeedsApproval(po){ const lim = +DB.company.poApprovalOver; return lim > 0 && poTotal(po).total > lim; }
function shipToLabel(po){ const k = po.shipTo||'site'; if (SHIP_TO[k]){ if (k==='site'){ const p = DB.projects.find(x=>x.id===po.projectId); return `Job site${p?.project.addr?' — '+p.project.addr:''}`; } if (k==='other') return po.shipToText||'Other'; return SHIP_TO[k]; } return po.shipTo; }
function poUnit(u){ const s = String(u||'').toLowerCase().trim(); const map = {sheets:'sheet', boxes:'box', rolls:'roll', sets:'set', kits:'kit', each:'ea', hrs:'hr', hours:'hr', days:'day', 'sq ft':'sf', sqft:'sf', 'lin ft':'lf', lnft:'lf', gallon:'gal', gallons:'gal', pcs:'ea', pc:'ea', '':'ea'}; return map[s] || (PO_UNITS.includes(s) ? s : s); }
function vendorRec(name){ return DB.vendors.find(v => v.name.toLowerCase()===(name||'').toLowerCase()) || null; }
function ensureVendor(name, extra={}){ if (!name) return null; let v = vendorRec(name); if (!v){ v = Object.assign({id:uid('v'), name, trade:'', insuranceExp:'', bankChangedAt:'', createdFrom:'po'}, extra); DB.vendors.push(v); } return v; }
function vendorDefaultType(v, po){ const t = (v?.trade||'').toLowerCase(); const lumpy = !po || !po.lines?.length || po.lines.every(l => ['ls','hr','day','wk',''].includes(String(l.unit||'').toLowerCase())); if (/plumb|elec|hvac|mill|carp|paint|demo|fram|mason|roof|glaz|tile/.test(t) && lumpy) return 'subcontract'; if (/rental|equip|dumpster|scaffold/.test(t)) return 'equipment'; return 'materials'; }
function vendorDefaultEntity(v, po){ const t = (v?.trade||'').toLowerCase(); const byTrade = /plumb/.test(t) ? DB.entities.find(e=>/plumb/i.test(e.name))?.id : /elec/.test(t) ? DB.entities.find(e=>/elec/i.test(e.name))?.id : null; return byTrade || poEntity(po); }
function applyTerms(po, key){ const p = TERMS_PRESETS.find(x=>x[0]===key); if (!p || !p[2]) return; const o = p[2]; po.termsPreset = key; po.depositPct = o.dep; po.schedule = [...(o.dep?[{pct:o.dep, trigger:'on order'}]:[]), {pct:100-o.dep, trigger:o.bal, days:o.bal==='net'?(o.days||30):0}]; }
function applyTax(po){ const rate = +DB.company.taxRate || 8.875; po.tax = (po.taxStatus||'none')==='taxable' ? rate : 0; }
/* migration: every existing PO gets the new fields, nothing guessed twice */
function poMigrate(){ DB.company.taxRate = DB.company.taxRate || 8.875; DB.company.poApprovalOver = DB.company.poApprovalOver ?? (DB.company.ap?.ceoAbove || 10000); DB.pos.forEach(po => { if (po.__v2) return; const v = ensureVendor(po.vendor); po.vendorId = v?.id||''; if (!po.type) po.type = vendorDefaultType(v, po); if (!po.entityId) po.entityId = vendorDefaultEntity(v, po); if (!SHIP_TO[po.shipTo||'']){ const s = (po.shipTo||'').toLowerCase(); po.shipToText = s && s!=='site' ? po.shipTo : ''; po.shipTo = !s || s==='site' ? 'site' : /shop|office/.test(s) ? 'shop' : 'other'; } if (!po.shipVia) po.shipVia = po.type==='subcontract'||po.type==='service' ? '' : 'vendor'; if (!po.taxStatus) po.taxStatus = +po.tax>0 ? 'taxable' : (po.type==='materials' ? 'exempt-ci' : 'none'); if (!po.termsPreset){ const dep = +po.depositPct||0; const net = (po.schedule||[]).find(x=>x.trigger==='net'); po.termsPreset = po.schedule||dep ? (dep===50&&!net?'5050':dep&&net?'dep-net30':!dep&&net?'net30':'custom') : 'delivery'; } if (po.retainagePct==null && po.type==='subcontract') po.retainagePct = +v?.retainagePct||0; po.receipts = po.receipts||[]; po.srcDocs = po.srcDocs || (po.notes||'').match(/From ([A-Z0-9, -]+)/)?.[1]?.split(',').map(x=>x.trim()) || []; po.lines.forEach(l => { l.unit = poUnit(l.unit); if (!l.code){ const ref = l.line ? findLine(l.line) : null; l.code = ref ? lineCode(ref.line, ref.doc) : (v?.trade ? codeForTrade(v.trade.toLowerCase().slice(0,4)) : '') || codeForLine(l); if (l.code==='99' && po.type==='subcontract' && v?.trade) l.code = (COST_CODES.find(c => c[1].toLowerCase().includes(v.trade.toLowerCase().split(' ')[0]))||['99'])[0]; } }); po.__v2 = 1; }); }
