function poLineOptions(projectId){ const out = lineOptions(projectId); const cl = DB.clients.find(c => DB.projects.find(p=>p.id===projectId)?.clientId === c.id); if (cl) cl.invoices.filter(i => i.mode!=='sov' && !['void','draft'].includes(i.status) && (!i.projectId || i.projectId===projectId)).forEach(i => i.lines.filter(l => !l.retainerLine && !l.fromLine).forEach(l => out.push({key:`invoice:${i.id}:${l.id}`, label:`${i.number} · ${l.item||l.desc}`, doc:i, line:l}))); return out; }
