  if (a==='approve'){ if (!owner){ toast('Only the Owner approves'); return; } po.status = 'draft'; po.approvedBy = by; po.approvedAt = today(); audit('po', po.id, 'approved', 'pending', 'issued', by); return poActionBase_po(po, 'issue'); }
