/* Bill this PO — the bill inherits everything; entity must match */
function billFromPO(po){ const billed = poBilled(po); const tot = poTotal(po).total; const remaining = r2(tot - billed); const v = vendorRec(po.vendor); const b = {id:uid('b'), vendor:po.vendor, number:'', date:today(), due:iso(addDays(today(), /net ?(\d+)/i.test(v?.terms||'') ? +(v.terms.match(/net ?(\d+)/i)[1]) : 30)), entityId:poEntity(po), projectId:po.projectId||'', poId:po.id, cat:poCat(po), code:po.lines[0]?.code||'', line:po.lines.length===1 ? (po.lines[0].line||'') : '', lines:po.lines.map(l => ({desc:`${l.item}${l.desc?' — '+l.desc:''}`, qty:+l.qty||1, unit:l.unit, amount:r2((+l.qty||0)*(+l.price||0)), code:l.code||'', poLineId:l.id})), payMethod:'ACH', fileId:'', notes:`From ${po.number}${remaining<tot?` · ${money(billed)} already billed`:''}`, status:'submitted', approvals:[], createdBy:S.project.userName||'', retainagePct:po.type==='subcontract' ? (+po.retainagePct||0) : 0, taxStatus:po.taxStatus||'none'}; if (po.tax){ b.lines.push({desc:`Sales tax ${po.tax}%`, qty:1, unit:'ls', amount:poTotal(po).tax, code:po.lines[0]?.code||''}); } if (po.shipping) b.lines.push({desc:'Shipping / freight', qty:1, unit:'ls', amount:+po.shipping, code:po.lines[0]?.code||''}); DB.bills.push(b); audit('bill', b.id, 'created-from-po', '', po.number, S.project.userName||role()); log(`Bill drafted from ${po.number} — ${money(billTotal(b))}`); save(); view = 'ap'; render(); setTimeout(() => openBill(b.id), 60); }
