function jvWeekAnswer(f){ const wk = iso(addDays(f.today, 7)); const L = []; const dec = f.needsMe.filter(t => /approve|decide|confirm|sign|release|review/i.test(t)); if (dec.length) L.push(`Decide or approve (${dec.length}): ${dec.slice(0,5).join('; ')}${dec.length>5?'; …':''}`); if (f.billsToApprove.length) L.push(`Bills to approve: ${f.billsToApprove.map(b=>`${b.vendor} ${money(b.amount)}`).join(', ')}`); if (f.posPending.length) L.push(`POs awaiting approval: ${f.posPending.map(p=>`${p.number} ${p.vendor} ${money(p.total)}`).join(', ')}`); const due = f.dueWithin7.reduce((a,b)=>a+b.amount,0); if (f.dueWithin7.length) L.push(`Due to vendors by ${fmt(wk)}: ${money(due)} — ${f.dueWithin7.map(b=>`${b.vendor} ${money(b.amount)} ${fmt(b.due)}`).join(', ')}`); if (f.overdue.length) L.push(`Overdue from clients: ${f.overdue.map(o=>`${o.client} ${o.invoice} ${money(o.balance)}`).join(', ')} — chase these first`); if (f.decisionsOverdue.length) L.push(`Client decisions overdue: ${f.decisionsOverdue.map(d=>`${d.name} (${d.job})`).join(', ')}`); const bad = f.jobs.filter(j => j.daysBehind>0 || j.health<70); if (bad.length) L.push(`Jobs to watch: ${bad.map(j=>`${j.name} health ${j.health}${j.daysBehind>0?`, ${j.daysBehind}d behind`:''}${j.urgent?`, ${j.urgent} late item${j.urgent===1?'':'s'}`:''}`).join('; ')}`); if (f.deliveries.length) L.push(`Deliveries: ${f.deliveries.map(d=>`${d.item} ${fmt(d.eta)} (${d.job})`).join(', ')}`); if (f.matchesToConfirm) L.push(`${f.matchesToConfirm} bank match${f.matchesToConfirm===1?'':'es'} to confirm`); if (f.proposalsOut.length) L.push(`Proposals out: ${f.proposalsOut.map(e=>`${e.number} ${money(e.total)}`).join(', ')} — follow up`); L.push(`Cash ${money(f.cash)}, safe to spend ${money(f.safeToSpend)}${f.cashLow13w<f.cash?`, 13-week low ${money(f.cashLow13w)}`:''}.`); return L.join('\n'); }
function jvLocalAnswer(q, f){ const s = q.toLowerCase(); if (/attention|focus|priorit|what should i|to do|todo|on my plate|this week|today/.test(s) && !/due|owe|cash|deliver/.test(s)) return jvWeekAnswer(f); if (/due|owe|pay/.test(s) && /week|7|seven/.test(s)) return f.dueWithin7.length ? f.dueWithin7.map(b=>`${b.vendor} ${money(b.amount)} due ${fmt(b.due)}`).join('; ') : 'Nothing due to vendors within 7 days.'; if (/cash|spend|afford/.test(s)) return `Cash ${money(f.cash)}, safe to spend ${money(f.safeToSpend)}, 13-week low ${money(f.cashLow13w)}.`; if (/job|bleed|behind|late/.test(s)) return f.jobs.map(j=>`${j.name}: health ${j.health}${j.daysBehind>0?`, ${j.daysBehind}d behind`:''}, ${j.pctComplete}% complete`).join('; '); if (/overdue|receivable|collect/.test(s)) return f.overdue.length ? f.overdue.map(o=>`${o.client} ${o.invoice} ${money(o.balance)} due ${fmt(o.due)}`).join('; ') : `No overdue receivables; ${money(f.receivables)} outstanding.`; if (/deliver|arriv/.test(s)) return f.deliveries.length ? f.deliveries.map(d=>`${d.item} ${fmt(d.eta)} (${d.job})`).join('; ') : 'No deliveries expected this week.'; return jvWeekAnswer(f); }

/* ===================== SORT ANY TABLE BY ITS COLUMNS — click a header; click again to flip; it sticks per page ===================== */
/* Every table with a header row sorts on click. Group rows (a cell spanning columns) and total rows stay where they are — rows sort within their group. Editable line-item tables (estimates, invoices, SOV) keep their own order; the data grid already sorts. */
const SORT_SKIP = 'table.lines, table.sov, #ct-itbl, table.mb-facts, table[data-nosort], table.kpi-t';
let tableSort = {}; try { tableSort = JSON.parse(localStorage.getItem('tableSort')||'{}'); } catch(e){}
function sortKeyOf(tb){ const ths = [...tb.querySelectorAll('thead th')].map(t => t.textContent.trim()).join('|'); return (typeof view!=='undefined'?view:'') + '|' + (tb.id || ths.slice(0,120)); }
function sortVal(td){ if (!td) return {n:null, s:''}; if (td.dataset.v!=null){ const n = parseFloat(td.dataset.v); return {n: isNaN(n)?null:n, s:String(td.dataset.v).toLowerCase()}; } const inp = td.querySelector('input,select'); let s = inp ? (inp.type==='checkbox' ? (inp.checked?'1':'0') : (inp.value||'')) : td.textContent; s = s.trim(); if (!s || s==='—' || s==='-') return {n:null, s:''};
  let t = s.replace(/[,$%\s]/g,''); let neg = false; if (/^\(.*\)$/.test(t)){ neg = true; t = t.slice(1,-1); } if (/^[−–-]/.test(t)){ neg = true; t = t.slice(1); } if (/^\d+(\.\d+)?[kKmM]?$/.test(t)){ let n = parseFloat(t); if (/k$/i.test(t)) n *= 1000; if (/m$/i.test(t)) n *= 1e6; return {n: neg?-n:n, s:s.toLowerCase()}; }
  const d = /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0,10) : /^(\d{1,2})\/(\d{1,2})(\/(\d{2,4}))?$/.test(s) ? (m => { const y = m[4] ? (m[4].length===2?'20'+m[4]:m[4]) : String(new Date().getFullYear()); return `${y}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`; })(s.match(/^(\d{1,2})\/(\d{1,2})(\/(\d{2,4}))?$/)) : null;
  if (d) return {n: Date.parse(d)||null, s:s.toLowerCase()}; const mo = s.match(/^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]* (\d{1,2})(,? (\d{4}))?$/i); if (mo){ const y = mo[4] || new Date().getFullYear(); return {n: Date.parse(`${mo[1].slice(0,3)} ${mo[2]}, ${y}`)||null, s:s.toLowerCase()}; }
  return {n:null, s:s.toLowerCase()}; }
function sortPinned(tr){ return [...tr.children].some(c => +c.getAttribute('colspan')>1) || /\b(tot|total|sum|foot|grp|group|sub|hd)\b/.test(tr.className); }
function applyTableSort(tb, col, dir){ const body = tb.tBodies[0]; if (!body) return; const rows = [...body.rows]; const segs = []; let cur = []; rows.forEach(r => { if (sortPinned(r)){ if (cur.length) segs.push(cur); segs.push([r]); cur = []; } else cur.push(r); }); if (cur.length) segs.push(cur);
  const cmp = (a,b) => { const A = sortVal(a.cells[col]), B = sortVal(b.cells[col]); if (!A.s && B.s) return 1; if (A.s && !B.s) return -1; let r; if (A.n!=null && B.n!=null) r = A.n - B.n; else if (A.n!=null) r = -1; else if (B.n!=null) r = 1; else r = A.s.localeCompare(B.s, undefined, {numeric:true}); return dir==='desc' ? -r : r; };
  const out = segs.flatMap(sg => sg.length>1 || !sortPinned(sg[0]) ? sg.slice().sort(cmp) : sg); out.forEach(r => body.appendChild(r));
  tb.querySelectorAll('thead th').forEach((th, i) => { th.classList.toggle('sort-asc', i===col && dir==='asc'); th.classList.toggle('sort-desc', i===col && dir==='desc'); if (tb.classList.contains('dg-t')) th.classList.remove('s','sd'); }); }
function sortableTables(){ return [...document.querySelectorAll('table:not(.no-sort)')].filter(tb => tb.querySelector('thead th') && tb.tBodies[0] && tb.tBodies[0].rows.length>1 && !tb.matches(SORT_SKIP)); }
function reapplyTableSorts(){ sortableTables().forEach(tb => { tb.classList.add('sortable'); const st = tableSort[sortKeyOf(tb)]; if (st && tb.querySelectorAll('thead th').length > st.col) applyTableSort(tb, st.col, st.dir); }); }
document.addEventListener('click', e => { const th = e.target.closest('th'); if (!th || e.target.closest('input,select,button,a,label')) return; const tb = th.closest('table'); if (!tb || !tb.classList.contains('sortable')) return; if (th.dataset.sort){ /* the grid sorts this column itself — drop any column-appended sort so the two don't fight */ delete tableSort[sortKeyOf(tb)]; try { localStorage.setItem('tableSort', JSON.stringify(tableSort)); } catch(_){} return; } const ths = [...th.parentElement.children]; const col = ths.indexOf(th); const key = sortKeyOf(tb); const prev = tableSort[key]; const dir = prev && prev.col===col ? (prev.dir==='asc' ? 'desc' : null) : 'asc';
  if (!dir){ delete tableSort[key]; tb.querySelectorAll('thead th').forEach(t => t.classList.remove('sort-asc','sort-desc')); try { localStorage.setItem('tableSort', JSON.stringify(tableSort)); } catch(_){} render(); return; }
  tableSort[key] = {col, dir}; try { localStorage.setItem('tableSort', JSON.stringify(tableSort)); } catch(_){} applyTableSort(tb, col, dir); });
const renderBase_sort = render;
render = function(){ renderBase_sort(); try { reapplyTableSorts(); } catch(e){ console.warn('sort', e); } };

/* ===================== APPEARANCE — Classic (blue) or Mono (black & white; colour only on data) ===================== */
/* Per device: whoever is signed in on this phone or laptop picks. Settings › Appearance, or the button on Home. */
function themeGet(){ const def = (typeof DB!=='undefined' && DB && DB.company && DB.company.themeDefault) || 'classic'; try { return localStorage.getItem('theme') || def; } catch(e){ return def; } }
function themeSet(t){ try { localStorage.setItem('theme', t); } catch(e){} themeApply(); render(); }
function themeApply(){ document.documentElement.classList.toggle('mono', themeGet()==='mono'); }
function themeSegHtml(){ const t = themeGet(); return `<div class="seg sm" id="theme-seg"><button class="${t==='classic'?'on':''}" data-theme="classic">Classic</button><button class="${t==='mono'?'on':''}" data-theme="mono">Mono</button></div>`; }
document.addEventListener('click', e => { const b = e.target.closest('[data-theme]'); if (!b) return; themeSet(b.dataset.theme); });
const renderBase_theme = render;
render = function(){ themeApply(); renderBase_theme();
  /* Settings › Appearance */ const anchor = $('#po-settings'); if (anchor && !$('#theme-card')){ const div = document.createElement('div'); div.className = 'card'; div.id = 'theme-card'; div.innerHTML = `<h3>Appearance</h3><div class="row" style="align-items:center;gap:10px;flex-wrap:wrap">${themeSegHtml()}<span class="small muted">${themeGet()==='mono' ? 'Mono — black, white and gray; colour is reserved for numbers, status and flags.' : 'Classic — blue accent.'} Saved on this device.</span><span class="grow"></span><label class="small" style="display:flex;gap:6px;align-items:center"><input type="checkbox" id="theme-default" ${DB.company.themeDefault==='mono'?'checked':''}> Mono is the company default for new devices</label></div>`; anchor.before(div); $('#theme-default').onchange = e => { DB.company.themeDefault = e.target.checked ? 'mono' : ''; save(); }; }
  /* Home bar */ const hb = document.querySelector('.home-bar'); if (hb && !hb.querySelector('#theme-seg')){ const s = document.createElement('span'); s.innerHTML = themeSegHtml(); s.title = 'Appearance'; hb.querySelector('#home-classic')?.before(s.firstChild); } };
themeApply();

/* ===================== STUDIO A — the design team's module: my day, project board, dimensions with provenance, drawing register, filings ===================== */
/* Principle: a dimension is a data point with a provenance (listing → field → trade → as-built) and every drawing inherits the weakest provenance under it. The designer sees one badge and one list — never a form. Gates, not nags: SD→DD, issuing a set, and fabrication POs wait for field-measured dimensions. A change lists its reach across every set, schedule, estimate line, PO and deck — the domino stopped at the first tile. */
const PROV = {listing:{rank:0, label:'listing plan', short:'Unverified', cls:'bad'}, field:{rank:1, label:'field-measured', short:'Measured', cls:'ok'}, trade:{rank:2, label:'trade-verified', short:'Trade-verified', cls:'ok'}, asbuilt:{rank:3, label:'as-built', short:'As-built', cls:'ok'}};
const SETS = {deck:'Presentation deck', sd:'Schematic', lpc:'LPC set', dob:'DOB set', cd:'CD set', ffe:'FF&E schedules', struct:'Structural (consultant)', mep:'MEP (consultant)'};
const ROOM_PHASES = [['sd','Schematic'],['dd','Design development'],['cd','Construction docs'],['done','Issued']];
const FAB_WORDS = /millwork|cabinet|kitchen|vanity|stone|counter|slab|window|door|appliance|range|tub|shower|closet|built-in|wardrobe/i;
const STD_DIMS = [['w','Width'],['d','Depth'],['h','Ceiling height']];
const fi = n => { if (n==null || n==='') return '—'; const neg = n<0; n = Math.abs(+n); const f = Math.floor(n/12), i = Math.round((n%12)*4)/4; const is = i%1 ? `${Math.floor(i)}${['','¼','½','¾'][Math.round((i%1)*4)]}` : String(i); return `${neg?'−':''}${f?f+"'-":''}${is}"`; };
function parseFI(s){ s = String(s||'').trim().replace(/[”"]/g,'"').replace(/[’']/g,"'"); if (!s) return null; let m = s.match(/^(\d+(?:\.\d+)?)\s*'\s*-?\s*(\d+(?:\.\d+)?)?\s*(?:\s(\d)\/(\d))?\s*"?$/); if (m) return +m[1]*12 + (+m[2]||0) + (m[3]?+m[3]/+m[4]:0); m = s.match(/^(\d+)\s+(\d+(?:\.\d+)?)$/); if (m) return +m[1]*12 + +m[2]; m = s.match(/^(\d+(?:\.\d+)?)\s*"?$/); if (m) return +m[1]; m = s.match(/^(\d+(?:\.\d+)?)\s*(ft|feet)$/i); if (m) return +m[1]*12; return null; }
