    St.filings.push(...[['altco','Alteration-CO — conversion',45000,['lpc','acp5','survey']], ['demo','Demolition filing',12000,['acp5','survey']], ['frame','Partition / framing filing',12000,['demo']], ['alt2','ALT-2 construction filing',15000,['lpc','frame']], ['lpc','LPC — rear windows only',27000,['survey']]].map(([key,name,fee,pre]) => ({id:'fl140'+key, projectId:p.id, key, name, fee, pre, status:'not-started', rounds:0, startedOn:'', submittedOn:'', approvedOn:'', notes:'', billed:{start:false, submit:false, approve:false}})));
