/* ---------- provenance, gates, fit checks ---------- */
const roomsOf = pid => DB.studio.rooms.filter(r => r.projectId===pid);
const sheetsOf = pid => DB.studio.sheets.filter(s => s.projectId===pid);
function roomProv(r){ return r.dims.reduce((m, d) => Math.min(m, PROV[d.src]?.rank ?? 0), 3); }
function provOfRooms(ids){ return ids.map(id => DB.studio.rooms.find(r=>r.id===id)).filter(Boolean).reduce((m,r) => Math.min(m, roomProv(r)), 3); }
const provKey = rank => Object.keys(PROV).find(k => PROV[k].rank===rank) || 'listing';
function provBadge(rank, small){ const k = provKey(rank); const P = PROV[k]; return `<span class="pill ${P.cls}" title="Weakest dimension under this: ${P.label}">${small?P.short:(rank===0?'Drawn on listing dimensions — not field-verified':`Dimensions ${P.label}`)}</span>`; }
function roomMissing(r){ return r.dims.filter(d => (PROV[d.src]?.rank??0) < 1); }
function roomGate(r, what){ const miss = roomMissing(r); return miss.length ? `${what} waits for field measurements in ${r.name}: ${miss.map(d=>d.label).join(', ')}` : ''; }
function fitCheck(r){ const walls = {}; r.fixtures.forEach(f => (walls[f.wall] = walls[f.wall]||[]).push(f)); return Object.entries(walls).map(([wk, fx]) => { const dim = r.dims.find(d=>d.key===wk); const len = dim ? +dim.value : 0; const used = fx.reduce((a,f)=>a+(+f.w||0),0); return {wall:dim?dim.label:wk, len, used, left:len-used, fx, prov:dim?.src||'listing'}; }); }
/* ---------- change records: the reach of one number ---------- */
function dimChange(room, dim, to, src, why, by, seed){ const from = dim.value; const P = DB.projects.find(x=>x.id===room.projectId); const c = P && DB.clients.find(x=>x.id===P.clientId); const affected = [];
  DB.studio.sheets.filter(s => s.projectId===room.projectId && s.rooms.includes(room.id) && s.status==='current').forEach(s => { s.stale = true; s.staleWhy = `${room.name} — ${dim.label} ${fi(from)} → ${fi(to)}`; affected.push({kind:'sheet', id:s.id, label:`${SETS[s.set]||s.set} · ${s.number} ${s.title}${s.source!=='inhouse'?' — notify consultant':''}`, done:false}); });
  const nm = room.name.toLowerCase(); if (c){ [...c.estimates, ...c.changeOrders].forEach(d => d.lines.forEach(l => { if ((l.roomId===room.id) || (l.item+' '+l.desc).toLowerCase().includes(nm)){ l.stale = true; affected.push({kind:'line', id:`${d.type}:${d.id}:${l.id}`, label:`${d.number} · ${l.item}`, done:false}); } })); }
  (DB.pos||[]).filter(po => po.projectId===room.projectId && !['closed','received'].includes(po.status)).forEach(po => { if (po.lines.some(l => (l.roomId===room.id) || (l.item||'').toLowerCase().includes(nm))){ po.stale = true; affected.push({kind:'po', id:po.id, label:`${po.number} · ${po.vendor}`, done:false}); } });
  (P?.materials||[]).forEach(m => { if (m.roomId===room.id || (m.name||'').toLowerCase().includes(nm)){ m.stale = true; affected.push({kind:'mat', id:m.id, label:`Material · ${m.name}`, done:false}); } });
  const rec = {id:uid('ch'), projectId:room.projectId, at:seed ? '2026-09-02' : today(), by:by||DB.me||'—', roomId:room.id, dimId:dim.id, label:`${room.name} — ${dim.label}`, from, to, src, why:why||'', affected, filing: DB.studio.sheets.some(s => s.projectId===room.projectId && s.rooms.includes(room.id) && ['lpc','dob'].includes(s.set) && s.status==='current')};
  DB.studio.changes.unshift(rec); dim.value = to; dim.src = src; dim.by = by||DB.me||'—'; dim.at = rec.at; if (!seed){ log(`Dimension changed: ${rec.label} ${fi(from)} → ${fi(to)} (${PROV[src].label}) — ${affected.length} item${affected.length===1?'':'s'} now stale`); } return rec; }
function dimSet(room, dim, val, src){ const rank = PROV[src].rank; const tol = +(DB.company.dimTol||0.5); if (dim.value!=null && dim.value!=='' && Math.abs(val - dim.value) > tol && rank >= 1){ return dimChange(room, dim, val, src, `${PROV[src].label}: was ${fi(dim.value)} (${PROV[dim.src]?.label||'—'})`); } dim.value = val; if (rank >= (PROV[dim.src]?.rank??0)) { dim.src = src; dim.by = DB.me||'—'; dim.at = today(); } return null; }
/* ---------- hours: phases, retainer, day sheet ---------- */
function designEst(p){ const c = DB.clients.find(x=>x.id===p.clientId); return c && c.estimates.find(e => e.template==='design' && ['converted','billed','approved'].includes(e.status)); }
function phaseHours(p){ const est = designEst(p); if (!est) return []; const emps = DB.employees.filter(isDesignStaff).map(e=>e.id); const T = DB.time.filter(t => t.projectId===p.id && emps.includes(t.empId)); return est.lines.filter(l => l.unit==='hr').map((l, i) => { const used = r2(T.filter(t => (t.phase??0)===i || (t.phaseLine===l.id)).reduce((a,t)=>a+hoursOf(t),0)); return {i, line:l, est:+l.qty||0, used, left:r2((+l.qty||0)-used), fee:lineAmount(l, est)}; }); }
function retainerLeft(p){ const est = designEst(p); if (!est || !est.retainer || est.billing!=='hours') return null; const rate = +(est.lines.find(l=>l.unit==='hr')?.rate||designRate()); const used = phaseHours(p).reduce((a,x)=>a+x.used,0); return {hours: r2(est.retainer/rate - used), dollars: r2(est.retainer - used*rate), rate, replenishAt:20}; }
const touchKey = () => `studio-touch:${DB.deviceUser||'x'}:${today()}`;
function touch(kind, id, label, projectId, minutes){ try { const L = JSON.parse(localStorage.getItem(touchKey())||'[]'); const k = `${kind}:${id}`; const ex = L.find(x=>x.k===k); if (ex){ ex.n++; ex.min = Math.max(ex.min, minutes||0); } else L.push({k, kind, id, label, projectId, n:1, min:minutes||0, at:nowStamp()}); localStorage.setItem(touchKey(), JSON.stringify(L.slice(-40))); } catch(e){} }
function touches(){ try { return JSON.parse(localStorage.getItem(touchKey())||'[]'); } catch(e){ return []; } }
function logHours(projectId, hours, phaseIdx, note, date){ const u = currentUser(); const emp = DB.employees.find(e => e.id===u?.employeeId); if (!emp){ toast('Sign in as a designer to log hours'); return null; } date = date||today(); const start = 9 + DB.time.filter(t=>t.empId===emp.id && t.date===date).reduce((a,t)=>a+hoursOf(t),0); const hh = Math.floor(start), mm = Math.round((start%1)*60); const e2 = start + hours; const e = {id:uid('te'), empId:emp.id, date, in:`${date}T${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:00`, out:`${date}T${String(Math.floor(e2)).padStart(2,'0')}:${String(Math.round((e2%1)*60)).padStart(2,'0')}:00`, breakMin:0, projectId, code:'15', notes:note||'', status:'submitted', approvedBy:'', source:'studio', phase:phaseIdx||0}; DB.time.push(e); save(); return e; }
/* ---------- views ---------- */
let sboardTab = 'rooms', sdrawSet = 'all';
function studioProjects(){ return DB.projects.filter(p => roomsOf(p.id).length || designEst(p)); }
function ensureStudioProject(){ if (!roomsOf(S.id).length && !designEst(S)){ const p = studioProjects()[0]; if (p) setCurrent(p.id); } }
function phaseStrip(p){ const ph = phaseHours(p); const R = retainerLeft(p); if (!ph.length) return `<div class="small muted">No design proposal on this job yet.</div>`; return `<div class="st-strip">${ph.map(x => { const pct = x.est ? Math.min(100, Math.round(x.used/x.est*100)) : 0; return `<div class="st-ph ${x.left<0?'over':''}" title="${esc(x.line.item)}: ${x.used} of ${x.est} hrs · ${money(x.fee)} fee"><div class="n">${esc(x.line.item.replace(/ and .*| \/ .*/,''))}</div><div class="bar"><i style="width:${pct}%"></i></div><div class="v"><b>${x.used}</b> / ${x.est} hrs${x.left<0?` · <span class="bad">${-x.left} over</span>`:''}</div></div>`; }).join('')}${R?`<div class="st-ph ret ${R.hours<=R.replenishAt?'over':''}"><div class="n">Retainer</div><div class="v"><b>${R.hours}</b> hrs left · ${money(R.dollars)}${R.hours<=R.replenishAt?' · replenish':''}</div></div>`:''}</div>`; }
function roomCard(r){ const rank = roomProv(r); const miss = roomMissing(r); const F = fitCheck(r); const tight = F.filter(f => f.left < 12); const ph = ROOM_PHASES.find(x=>x[0]===r.phase)?.[1]||'Schematic'; const sh = sheetsOf(r.projectId).filter(s => s.rooms.includes(r.id) && s.status==='current'); const stale = sh.filter(s=>s.stale).length;
  return `<div class="st-room ${rank===0?'unv':''}" data-room="${r.id}"><div class="hd"><div><b>${esc(r.name)}</b><span class="small muted"> · ${esc(r.floor)}</span></div>${provBadge(rank, true)}</div>
    <div class="dims">${r.dims.slice(0,4).map(d => `<span class="${(PROV[d.src]?.rank??0)<1?'unv':''}" title="${PROV[d.src]?.label||''} · ${esc(d.by||'')} ${d.at||''}">${esc(d.label)} <b>${fi(d.value)}</b></span>`).join('')}${r.dims.length>4?`<span class="muted">+${r.dims.length-4}</span>`:''}</div>
    ${F.length ? `<div class="fit">${F.map(f => `<span class="${f.left<0?'bad':f.left<12?'warn':'ok'}">${esc(f.wall)}: ${fi(f.used)} of ${fi(f.len)} used · <b>${fi(f.left)} left</b>${f.prov==='listing'?' (unverified)':''}</span>`).join('')}</div>` : ''}
    <div class="ft"><span class="pill neutral">${ph}</span>${stale?`<span class="pill bad">${stale} sheet${stale===1?'':'s'} stale</span>`:sh.length?`<span class="small muted">${sh.length} sheet${sh.length===1?'':'s'}</span>`:''}<span class="grow"></span><button class="btn sm" data-measure="${r.id}">${miss.length?`Measure (${miss.length})`:'Dimensions'}</button><button class="btn sm" data-timer="${r.id}">${timerOn(r.id)?'Stop timer':'Timer'}</button></div></div>`; }
function renderSBoard(){ const root = $('#sboard-body'); if (!root) return; ensureStudioProject(); const p = S; const c = DB.clients.find(x=>x.id===p.clientId); const rooms = roomsOf(p.id); const sh = sheetsOf(p.id); const stale = sh.filter(s=>s.stale && s.status==='current'); const gates = p.decisions.filter(d => d.status==='open' && d.gate); const unv = rooms.filter(r => roomProv(r)===0); const mt = DB.studio.meetings.filter(m=>m.projectId===p.id); const F = DB.studio.filings.filter(f=>f.projectId===p.id);
  root.innerHTML = `<div class="ph"><div><h2>${esc(p.project.name)}</h2><div class="small muted">${esc(p.project.addr||'')}${c?` · ${esc(c.name)}`:''}${p.project.lpc?` · ${esc(p.project.lpc)}`:''}</div></div><div class="acts"><button class="btn sm" data-addroom>+ Room</button></div></div>
    ${phaseStrip(p)}
    ${unv.length ? `<div class="note warn" style="margin:10px 0"><b>${unv.length} of ${rooms.length} rooms are drawn on listing dimensions.</b> Design development, issuing any set and millwork / stone / window / appliance orders wait for the survey. <a href="#" data-survey>Open the survey checklist ›</a></div>` : ''}
    ${gates.length ? `<div class="st-gates">${gates.map(d => `<div class="st-gate ${d.due && d.due < today() ? 'late':''}"><span class="k">Gate · ${esc(d.gate)}</span><b>${esc(d.name)}</b><span class="small muted">${esc(d.owner||'')} · due ${fmt(d.due)}</span></div>`).join('')}</div>` : ''}
    <div class="row" style="margin:12px 0 10px;align-items:center"><div class="seg sm">${[['rooms','Rooms'],['client','Client'],['meetings','Meetings'],['drawings',`Drawings${stale.length?` · ${stale.length} stale`:''}`],['filings','Filings']].map(([k,n]) => `<button class="${sboardTab===k?'on':''}" data-sbtab="${k}">${n}</button>`).join('')}</div><span class="grow"></span><a href="#" class="small" data-survey>Survey checklist ›</a></div>
    ${sboardTab==='rooms' ? `<div class="st-grid">${rooms.map(roomCard).join('') || '<div class="empty">No rooms yet — add the rooms in scope and the survey checklist writes itself.</div>'}</div>` : ''}
    ${sboardTab==='client' ? (c ? `<div class="card"><h3>${esc(c.name)}</h3>${c.contacts.map(ct => `<div class="row" style="padding:6px 0;border-top:1px solid var(--rule)"><b>${esc(ct.name)}</b><span class="pill ${ct.decides==='money'?'warn':ct.decides==='design'?'info':'neutral'}">${ct.decides==='money'?'Decides money':ct.decides==='design'?'Decides design':'Informed'}</span><span class="small muted">${esc(ct.email||'')}</span></div>`).join('')}<p class="small muted" style="margin:10px 0 0">${esc(c.notes||'')}</p></div><div class="card" style="margin-top:10px"><h3>Open decisions</h3>${p.decisions.filter(d=>d.status==='open').map(d => `<div class="row" style="padding:6px 0;border-top:1px solid var(--rule)"><span class="grow">${esc(d.name)}</span><span class="small muted">${esc(d.owner||'')} · ${fmt(d.due)}</span></div>`).join('')||'<div class="muted small">None open.</div>'}</div>` : '<div class="empty">No client linked.</div>') : ''}
    ${sboardTab==='meetings' ? `<div class="card">${mt.map(m => `<div class="row" style="padding:8px 0;border-top:1px solid var(--rule);align-items:flex-start"><div><b>${esc(m.title)}</b><div class="small muted">${fmtL(m.date)} · ${m.minutes} min · with ${esc(m.with||'')} · ${m.attendees.map(a => DB.employees.find(e=>e.id===a)?.name || DB.users.find(u=>u.id===a)?.name || a).join(', ')}</div></div><span class="grow"></span>${m.link?`<a href="${esc(m.link)}" target="_blank" class="small">Transcript ›</a>`:''}<span class="pill ${m.intake==='done'?'ok':'warn'}">${m.intake==='done'?'Decisions captured':m.intake==='proposed'?'Proposals to confirm':'Not read yet'}</span></div>`).join('')||'<div class="muted small">No meetings recorded.</div>'}</div>` : ''}
    ${sboardTab==='drawings' ? `<div class="small muted" style="margin-bottom:8px">Full register under Drawings. ${stale.length?`<b class="bad">${stale.length} current sheet${stale.length===1?'':'s'} carry a changed dimension.</b>`:'Every current sheet matches the register.'}</div>${sheetTable(sh.filter(s=>s.status==='current'))}` : ''}
    ${sboardTab==='filings' ? filingsHtml(p, F) : ''}`;
  wireSBoard(root, p); }
function wireSBoard(root, p){ root.querySelectorAll('[data-sbtab]').forEach(b => b.onclick = () => { sboardTab = b.dataset.sbtab; renderSBoard(); }); root.querySelectorAll('[data-measure]').forEach(b => b.onclick = () => roomDialog(b.dataset.measure)); root.querySelectorAll('[data-timer]').forEach(b => b.onclick = () => { timerToggle(b.dataset.timer, DB.studio.rooms.find(r=>r.id===b.dataset.timer)?.name, p.id); renderSBoard(); }); root.querySelectorAll('[data-survey]').forEach(b => b.onclick = e => { e.preventDefault(); surveyDialog(p); }); root.querySelector('[data-addroom]')?.addEventListener('click', () => mbModal('New room', `<div class="f"><label>Room</label><input data-f="name" placeholder="Kitchen"></div><div class="f"><label>Floor</label><input data-f="floor" placeholder="Parlor"></div><p class="small muted">Width, depth and ceiling height are added as unverified until measured.</p>`, {submit:'Add room', onSubmit:f => { if (!f.name) return false; DB.studio.rooms.push({id:uid('rm'), projectId:p.id, name:f.name, floor:f.floor, phase:'sd', dims:STD_DIMS.map(([k,l]) => ({id:uid('dm'), key:k, label:l, value:'', src:'listing', by:'', at:''})), fixtures:[], notes:''}); save(); renderSBoard(); }})); wireFilings(root, p); }
function roomDialog(id){ const r = DB.studio.rooms.find(x=>x.id===id); if (!r) return; touch('room', r.id, `${r.name} — dimensions`, r.projectId, 15); const F = fitCheck(r);
  const body = `<div class="small muted" style="margin-bottom:8px">Enter feet-inches (14'-6", 14 6) or inches (174). Marking a value <b>Field</b> or <b>Trade</b> records who measured it and when; a change beyond ${DB.company.dimTol||0.5}" from a measured value creates a change record listing every sheet, line and order that carries it.</div>
    <table class="t st-dims"><thead><tr><th>Dimension</th><th>Value</th><th>Source</th><th>By · when</th><th></th></tr></thead><tbody>${r.dims.map(d => `<tr data-dim="${d.id}"><td><input data-dl value="${esc(d.label)}"></td><td><input data-dv value="${d.value===''||d.value==null?'':fi(d.value)}" placeholder="—" style="width:90px"></td><td><select data-ds>${Object.entries(PROV).map(([k,P]) => `<option value="${k}" ${d.src===k?'selected':''}>${P.short}</option>`).join('')}</select></td><td class="small muted">${esc(d.by||'')}${d.at?` · ${fmt(d.at)}`:''}</td><td><span class="rm" data-rmdim="${d.id}">✕</span></td></tr>`).join('')}</tbody></table><button class="btn sm" id="st-adddim" style="margin:6px 0 12px">+ Dimension</button>
    <h4 style="margin:6px 0">Fit check — what sits on each wall</h4><div class="small muted" style="margin-bottom:6px">Fixtures and cabinetry on a wall sum against its length; what is left is the doors, the arch, the gaps.</div>
    <table class="t st-fix"><thead><tr><th>Wall</th><th>Item</th><th>Width</th><th></th></tr></thead><tbody>${r.fixtures.map((f,i) => `<tr data-fx="${i}"><td><select data-fw>${r.dims.map(d => `<option value="${d.key}" ${f.wall===d.key?'selected':''}>${esc(d.label)}</option>`).join('')}</select></td><td><input data-fn value="${esc(f.name)}"></td><td><input data-fv value="${fi(f.w)}" style="width:80px"></td><td><span class="rm" data-rmfx="${i}">✕</span></td></tr>`).join('')}</tbody></table><button class="btn sm" id="st-addfx" style="margin:6px 0">+ Item on a wall</button>
    ${F.length?`<div class="fit" style="margin-top:8px">${F.map(f => `<div class="${f.left<0?'bad':f.left<12?'warn':'ok'}"><b>${esc(f.wall)}</b>: ${f.fx.map(x=>`${esc(x.name)} ${fi(x.w)}`).join(' + ')} = ${fi(f.used)} of ${fi(f.len)} → <b>${fi(f.left)} left</b>${f.prov==='listing'?' · wall length unverified':''}</div>`).join('')}</div>`:''}
    <div class="f" style="margin-top:10px"><label>Phase</label><select data-f="phase">${ROOM_PHASES.map(([k,n]) => `<option value="${k}" ${r.phase===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="f"><label>Notes</label><textarea data-f="notes" rows="2">${esc(r.notes||'')}</textarea></div>`;
  const m = mbModal(`${r.name} · ${r.floor}`, body, {submit:'Save', onSubmit:f => { let changes = 0; m.querySelectorAll('tr[data-dim]').forEach(tr => { const d = r.dims.find(x=>x.id===tr.dataset.dim); if (!d) return; d.label = tr.querySelector('[data-dl]').value.trim()||d.label; const v = parseFI(tr.querySelector('[data-dv]').value); const src = tr.querySelector('[data-ds]').value; if (v!=null){ const rec = dimSet(r, d, v, src); if (rec) changes++; } else if (src!==d.src) d.src = src; });
    r.fixtures = [...m.querySelectorAll('tr[data-fx]')].map(tr => ({wall:tr.querySelector('[data-fw]').value, name:tr.querySelector('[data-fn]').value.trim(), w:parseFI(tr.querySelector('[data-fv]').value)||0})).filter(x=>x.name);
    if (f.phase!==r.phase && ROOM_PHASES.findIndex(x=>x[0]===f.phase) > 0 && roomMissing(r).length){ toast(roomGate(r, 'Design development')); } else r.phase = f.phase; r.notes = f.notes; save(); render(); if (changes) toast(`${changes} change record${changes===1?'':'s'} — see Drawings for what went stale`); }});
  m.querySelector('#st-adddim').onclick = () => { r.dims.push({id:uid('dm'), key:'x'+r.dims.length, label:'New dimension', value:'', src:'listing', by:'', at:''}); save(); roomDialog(id); };
  m.querySelector('#st-addfx').onclick = () => { r.fixtures.push({wall:r.dims[0]?.key||'w', name:'Item', w:24}); save(); roomDialog(id); };
  m.querySelectorAll('[data-rmdim]').forEach(x => x.onclick = () => { r.dims = r.dims.filter(d=>d.id!==x.dataset.rmdim); save(); roomDialog(id); }); m.querySelectorAll('[data-rmfx]').forEach(x => x.onclick = () => { r.fixtures.splice(+x.dataset.rmfx,1); save(); roomDialog(id); }); }
/* survey: the checklist writes itself from the rooms in scope; phone-first, one value at a time */
function surveyDialog(p){ const rooms = roomsOf(p.id); const rows = rooms.flatMap(r => r.dims.map(d => ({r, d}))); const todo = rows.filter(x => (PROV[x.d.src]?.rank??0) < 1); touch('survey', p.id, 'Survey checklist', p.id, 30);
  const m = mbModal(`Survey — ${p.project.name}`, `<div class="small muted" style="margin-bottom:8px"><b>${todo.length}</b> of ${rows.length} dimensions still from the listing plan. Type as you walk: 14'-6", 14 6, or 174. Each entry is saved as field-measured by you, today.${('webkitSpeechRecognition' in window)?' Tap the mic to say it.':''}</div><div class="st-survey">${rooms.map(r => `<div class="st-sroom"><b>${esc(r.name)}</b> <span class="small muted">${esc(r.floor)}</span>${r.dims.map(d => `<div class="row st-srow"><span class="grow ${(PROV[d.src]?.rank??0)<1?'':'muted'}">${esc(d.label)}</span><span class="small muted">${(PROV[d.src]?.rank??0)<1?`listing ${fi(d.value)}`:`${PROV[d.src].short} ${fi(d.value)}`}</span><input data-sv="${r.id}|${d.id}" placeholder="measure" inputmode="text" style="width:96px">${('webkitSpeechRecognition' in window)?`<button class="btn sm" data-mic="${r.id}|${d.id}" title="Say it">Mic</button>`:''}</div>`).join('')}</div>`).join('')}</div>`, {submit:'Save measurements', onSubmit:() => { let n = 0, ch = 0; m.querySelectorAll('[data-sv]').forEach(i => { const v = parseFI(i.value); if (v==null) return; const [rid, did] = i.dataset.sv.split('|'); const r = rooms.find(x=>x.id===rid); const d = r.dims.find(x=>x.id===did); const rec = dimSet(r, d, v, 'field'); n++; if (rec) ch++; }); if (n){ p.studioChecks = p.studioChecks||{}; if (!rooms.some(r=>roomMissing(r).length)) p.studioChecks.survey = true; save(); render(); toast(`${n} measurement${n===1?'':'s'} saved${ch?` · ${ch} change record${ch===1?'':'s'}`:''}`); } }});
  m.querySelectorAll('[data-mic]').forEach(b => b.onclick = () => { const rec = new webkitSpeechRecognition(); rec.lang = 'en-US'; rec.onresult = ev => { const t = ev.results[0][0].transcript.toLowerCase().replace(/feet|foot/,"'").replace(/inches|inch/,'"').replace(/ and /,' '); m.querySelector(`[data-sv="${b.dataset.mic}"]`).value = t; }; rec.start(); }); }
/* timers */
function timerOn(id){ try { const t = JSON.parse(localStorage.getItem('studio-timer')||'null'); return t && t.id===id ? t : null; } catch(e){ return null; } }
function timerToggle(id, label, projectId){ const t = timerOn(id); if (t){ const mins = Math.max(1, Math.round((Date.now()-t.start)/60000)); localStorage.removeItem('studio-timer'); touch('timer', id, label, projectId, mins); toast(`${mins} min on ${label} — on your day sheet`); } else { const cur = (()=>{ try { return JSON.parse(localStorage.getItem('studio-timer')||'null'); } catch(e){ return null; } })(); if (cur){ const mins = Math.max(1, Math.round((Date.now()-cur.start)/60000)); touch('timer', cur.id, cur.label, cur.projectId, mins); } localStorage.setItem('studio-timer', JSON.stringify({id, label, projectId, start:Date.now()})); toast(`Timer started — ${label}`); } }
/* ---------- drawing register ---------- */
function sheetTable(list){ if (!list.length) return '<div class="empty">No sheets yet.</div>'; return `<table class="t st-sheets"><thead><tr><th>Set</th><th>Sheet</th><th>Title</th><th>Rev</th><th>Rooms</th><th>Dimensions</th><th>Status</th><th>Issued</th><th>Source</th><th></th></tr></thead><tbody>${list.map(s => { const rk = provOfRooms(s.rooms); return `<tr class="${s.stale?'stale':''} ${s.status==='superseded'?'sup':''}"><td>${SETS[s.set]||s.set}</td><td><b>${esc(s.number)}</b></td><td>${esc(s.title)}${s.stale?`<div class="small bad">Stale — ${esc(s.staleWhy||'a dimension changed')}</div>`:''}</td><td>${esc(s.rev)}</td><td class="small">${s.rooms.map(id => DB.studio.rooms.find(r=>r.id===id)?.name).filter(Boolean).join(', ')}</td><td>${provBadge(rk, true)}</td><td>${s.status==='superseded'?'<span class="pill neutral">Superseded</span>':s.stale?'<span class="pill bad">Stale</span>':'<span class="pill ok">Current</span>'}</td><td>${s.issuedOn?fmt(s.issuedOn):'—'}</td><td class="small">${s.source==='inhouse'?'In-house':s.source==='structural'?'Structural PE':'MEP PE'}</td><td class="nowrap">${s.link?`<a href="${esc(s.link)}" target="_blank" class="small">Drive</a> `:''}${s.status!=='superseded'?`<button class="btn sm" data-rev="${s.id}">${s.stale?'Re-issue as rev':'New rev'} ${nextRev(s.rev)}</button>`:''}</td></tr>`; }).join('')}</tbody></table>`; }
const nextRev = r => { if (!r) return 'A'; if (/^[A-Z]$/.test(r)) return String.fromCharCode(r.charCodeAt(0)+1); const n = parseInt(r); return isNaN(n) ? r+'1' : String(n+1); };
function renderSDraw(){ const root = $('#sdraw-body'); if (!root) return; ensureStudioProject(); const p = S; const all = sheetsOf(p.id); const list = all.filter(s => sdrawSet==='all' || s.set===sdrawSet); const sets = [...new Set(all.map(s=>s.set))]; const ch = DB.studio.changes.filter(c=>c.projectId===p.id); const stale = all.filter(s=>s.stale && s.status==='current'); const tr = DB.studio.transmittals.filter(t=>t.projectId===p.id);
  root.innerHTML = `<div class="ph"><div><h2>Drawings — ${esc(p.project.name)}</h2><div class="small muted">Every sheet in every set, its revision, and the weakest dimension under it. Files stay in Google Drive; the register says which one is current.</div></div><div class="acts"><button class="btn sm" data-addsheet>+ Sheet</button><button class="btn sm primary" data-issue>Issue a set…</button></div></div>
    ${stale.length ? `<div class="note warn" style="margin-bottom:10px"><b>${stale.length} current sheet${stale.length===1?'':'s'} carry a changed dimension</b> — re-issue them before anyone builds or buys from them. Purchasing and the field open drawings through this register.</div>` : ''}
    <div class="seg sm" style="margin-bottom:10px"><button class="${sdrawSet==='all'?'on':''}" data-set="all">All sets</button>${sets.map(s => `<button class="${sdrawSet===s?'on':''}" data-set="${s}">${SETS[s]||s}${(n => n?` · ${n} stale`:'')(all.filter(x=>x.set===s && x.stale && x.status==='current').length)}</button>`).join('')}</div>
    ${sheetTable(list)}
    <div class="grid2" style="margin-top:14px"><div class="card"><h3>Change records</h3><div class="small muted" style="margin-bottom:6px">One number changed; this is everything that carries it. Tick each as it is re-issued or confirmed.</div>${ch.map(r => `<div class="st-change"><div class="row"><b>${esc(r.label)}</b><span class="mono">${fi(r.from)} → ${fi(r.to)}</span><span class="pill ${r.src==='trade'?'warn':'info'}">${PROV[r.src]?.short||r.src}</span><span class="grow"></span><span class="small muted">${fmt(r.at)} · ${esc(r.by)}</span></div><div class="small muted">${esc(r.why||'')}${r.filing?' · <b class="bad">a filed sheet is affected — PAA / LPC amendment?</b>':''}</div><div class="st-aff">${r.affected.map((a,i) => `<label class="${a.done?'done':''}"><input type="checkbox" data-aff="${r.id}|${i}" ${a.done?'checked':''}> ${esc(a.label)}</label>`).join('')||'<span class="small muted">Nothing else carried this value.</span>'}</div></div>`).join('')||'<div class="muted small">No changes recorded.</div>'}</div>
    <div class="card"><h3>Transmittals</h3>${tr.map(t => `<div class="row" style="padding:6px 0;border-top:1px solid var(--rule)"><b>${fmt(t.date)}</b><span class="grow">${esc(t.purpose)} → ${esc(t.to)}</span><span class="small muted">${t.sheets.length} sheet${t.sheets.length===1?'':'s'}</span></div>`).join('')||'<div class="muted small">Nothing issued yet.</div>'}</div></div>`;
  root.querySelectorAll('[data-set]').forEach(b => b.onclick = () => { sdrawSet = b.dataset.set; renderSDraw(); });
  root.querySelectorAll('[data-rev]').forEach(b => b.onclick = () => { const s = all.find(x=>x.id===b.dataset.rev); const gate = s.rooms.map(id=>DB.studio.rooms.find(r=>r.id===id)).filter(Boolean).map(r => roomGate(r, 'Re-issuing')).filter(Boolean); if (gate.length && ['lpc','dob','cd','ffe'].includes(s.set)){ toast(gate[0]); return; } const n = Object.assign({}, s, {id:uid('sh'), rev:nextRev(s.rev), stale:false, staleWhy:'', issuedOn:today(), supersedes:s.id}); s.status = 'superseded'; DB.studio.sheets.push(n); DB.studio.changes.filter(c=>c.projectId===p.id).forEach(c => c.affected.forEach(a => { if (a.kind==='sheet' && a.id===s.id) a.done = true; })); touch('sheet', n.id, `${n.number} rev ${n.rev}`, p.id, 30); save(); renderSDraw(); toast(`${n.number} rev ${n.rev} is current — rev ${s.rev} superseded`); });
  root.querySelectorAll('[data-aff]').forEach(i => i.onchange = () => { const [cid, idx] = i.dataset.aff.split('|'); const r = ch.find(x=>x.id===cid); r.affected[+idx].done = i.checked; const a = r.affected[+idx]; if (a.kind==='po'){ const po = DB.pos.find(x=>x.id===a.id); if (po) po.stale = !i.checked; } if (a.kind==='mat'){ const mt = p.materials.find(x=>x.id===a.id); if (mt) mt.stale = !i.checked; } if (a.kind==='line'){ const [k, did, lid] = a.id.split(':'); const c = DB.clients.find(x=>x.id===p.clientId); const d = c && [...c.estimates, ...c.changeOrders].find(x=>x.id===did); const l = d && d.lines.find(x=>x.id===lid); if (l) l.stale = !i.checked; } save(); renderSDraw(); });
  root.querySelector('[data-addsheet]').onclick = () => { const rooms = roomsOf(p.id); mbModal('New sheet', `<div class="f2"><div class="f"><label>Set</label><select data-f="set">${Object.entries(SETS).map(([k,n]) => `<option value="${k}">${n}</option>`).join('')}</select></div><div class="f"><label>Number</label><input data-f="number" placeholder="A-201"></div></div><div class="f"><label>Title</label><input data-f="title"></div><div class="f"><label>Rooms it depends on</label><div class="st-pick">${rooms.map(r => `<label><input type="checkbox" data-rm="${r.id}"> ${esc(r.name)}</label>`).join('')}</div></div><div class="f2"><div class="f"><label>Source</label><select data-f="source"><option value="inhouse">In-house</option><option value="structural">Structural PE</option><option value="mep">MEP PE</option></select></div><div class="f"><label>Drive link</label><input data-f="link" placeholder="https://drive.google.com/…"></div></div>`, {submit:'Add sheet', onSubmit:f => { if (!f.number) return false; const rs = [...document.querySelectorAll('#mbm [data-rm]:checked')].map(x=>x.dataset.rm); DB.studio.sheets.push({id:uid('sh'), projectId:p.id, set:f.set, number:f.number, title:f.title, rev:'A', rooms:rs, status:'current', issuedOn:'', source:f.source, link:f.link, stale:false}); save(); renderSDraw(); }}); };
  root.querySelector('[data-issue]').onclick = () => issueDialog(p); }
function issueDialog(p){ const all = sheetsOf(p.id).filter(s=>s.status==='current'); const sets = [...new Set(all.map(s=>s.set))]; if (!sets.length){ toast('Add sheets first'); return; }
  const m = mbModal('Issue a set', `<div class="f"><label>Set</label><select data-f="set">${sets.map(s => `<option value="${s}">${SETS[s]||s}</option>`).join('')}</select></div><div class="f"><label>Purpose</label><input data-f="purpose" placeholder="For LPC submission / for pricing / client deck"></div><div class="f"><label>To</label><input data-f="to" placeholder="LPC via Portico; Carlos Millwork; client"></div><div id="st-issue-check" class="small" style="margin-top:6px"></div>`, {submit:'Issue', onSubmit:f => { const list = all.filter(s=>s.set===f.set); const gates = []; list.forEach(s => s.rooms.forEach(id => { const r = DB.studio.rooms.find(x=>x.id===id); if (r && roomMissing(r).length && ['lpc','dob','cd','ffe'].includes(f.set)) gates.push(`${r.name}: ${roomMissing(r).map(d=>d.label).join(', ')}`); })); const stale = list.filter(s=>s.stale); if (stale.length){ toast(`${stale.length} sheet${stale.length===1?'':'s'} in this set are stale — re-issue them first`); return false; } if (gates.length){ toast(`Issue blocked — unverified dimensions in ${[...new Set(gates)].join(' · ')}`); return false; } const t = {id:uid('tr'), projectId:p.id, date:today(), purpose:f.purpose, to:f.to, set:f.set, sheets:list.map(s=>s.id)}; DB.studio.transmittals.push(t); list.forEach(s => { if (!s.issuedOn) s.issuedOn = today(); }); const F = DB.studio.filings.find(x => x.projectId===p.id && ((f.set==='lpc' && x.key==='lpc') || (f.set==='dob' && ['altco','alt2','demo','frame'].includes(x.key) && x.status==='in-prep'))); if (F && !F.submittedOn){ F.submittedOn = today(); F.status = 'submitted'; } touch('issue', t.id, `Issued ${SETS[f.set]}`, p.id, 45); log(`Issued ${SETS[f.set]||f.set}: ${list.length} sheets → ${f.to}`); save(); render(); toast(`${SETS[f.set]} issued — ${list.length} sheets on transmittal`); }});
  const check = () => { const set = m.querySelector('[data-f="set"]').value; const list = all.filter(s=>s.set===set); const audit = [...new Set(list.flatMap(s=>s.rooms))].map(id=>DB.studio.rooms.find(r=>r.id===id)).filter(Boolean); const unv = audit.filter(r=>roomMissing(r).length); const stale = list.filter(s=>s.stale); m.querySelector('#st-issue-check').innerHTML = `<b>Issue checklist</b><div>${list.length} sheet${list.length===1?'':'s'} · ${audit.length} room${audit.length===1?'':'s'} audited</div><div class="${stale.length?'bad':'ok'}">${stale.length?`${stale.length} stale — re-issue first`:'No stale sheets'}</div><div class="${unv.length?'bad':'ok'}">${unv.length?`Unverified dimensions: ${unv.map(r=>r.name).join(', ')}`:'All dimensions field-measured or better'}</div><div class="muted">Dimension audit: ${audit.flatMap(r=>r.dims).length} values checked against the register</div>`; }; m.querySelector('[data-f="set"]').onchange = check; check(); }
/* ---------- filings: the five fixed-fee tracks, billed 50 / 25 / 25, two comment rounds included ---------- */
const FILING_STATUS = {'not-started':['Not started','neutral'], 'in-prep':['In preparation','info'], submitted:['Submitted — in review','warn'], objections:['Objections — revising','bad'], approved:['Approved','ok']};
const PRE_LABELS = {survey:'Survey complete', acp5:'ACP-5 on file', lpc:'LPC permit issued', demo:'Demolition approved', frame:'Framing approved', zoning:'Zoning statement'};
function filingReady(p, f){ const chk = p.studioChecks||{}; const F = DB.studio.filings.filter(x=>x.projectId===p.id); return (f.pre||[]).map(k => { const other = F.find(x=>x.key===k); const ok = other ? other.status==='approved' : !!chk[k]; return {k, label:PRE_LABELS[k]||k, ok}; }); }
function filingsHtml(p, F){ const chk = p.studioChecks||{}; const rate = 200; return `<div class="card" style="margin-bottom:10px"><h3>Before anything is filed</h3><div class="st-pre">${[['survey','Existing-conditions survey complete'],['acp5','Asbestos investigation — ACP-5 on file'],['zoning','Zoning statement / objection sheet for LPC']].map(([k,n]) => `<label><input type="checkbox" data-chk="${k}" ${chk[k]?'checked':''}> ${n}</label>`).join('')}<div class="small muted">LPC track: ${esc(chk.lpcTrack||'—')}</div></div></div>
    ${F.map(f => { const [st, cls] = FILING_STATUS[f.status]; const pre = filingReady(p, f); const blocked = pre.filter(x=>!x.ok); const days = f.submittedOn && !f.approvedOn ? dayDiff(f.submittedOn, today()) : null; const billed = (f.billed.start?0.5:0)+(f.billed.submit?0.25:0)+(f.billed.approve?0.25:0);
      return `<div class="st-filing"><div class="row"><b>${esc(f.name)}</b><span class="pill ${cls}">${st}</span>${days!=null?`<span class="small muted">${days} day${days===1?'':'s'} in review</span>`:''}<span class="grow"></span><span class="mono">${money(f.fee)}</span><span class="small muted">billed ${Math.round(billed*100)}%</span></div>
        <div class="row small" style="gap:10px;flex-wrap:wrap;margin-top:4px">${pre.map(x => `<span class="${x.ok?'ok':'bad'}">${x.ok?'✓':'○'} ${x.label}</span>`).join('')}${f.rounds?`<span class="${f.rounds>2?'bad':'muted'}">Comment rounds: ${f.rounds} of 2 included${f.rounds>2?' — additional service at $'+rate+'/hr':''}</span>`:''}</div>
        <div class="row" style="margin-top:6px;gap:6px;flex-wrap:wrap">${f.status==='not-started'?`<button class="btn sm primary" data-fact="start|${f.id}" ${blocked.length?'disabled title="Waiting: '+blocked.map(x=>x.label).join(', ')+'"':''}>Start — bill 50%</button>`:''}${f.status==='in-prep'?`<button class="btn sm primary" data-fact="submit|${f.id}">Submitted — bill 25%</button>`:''}${['submitted','objections'].includes(f.status)?`<button class="btn sm" data-fact="round|${f.id}">Objections received</button><button class="btn sm primary" data-fact="approve|${f.id}">Approved — bill 25%</button>`:''}${f.status==='objections'?`<button class="btn sm" data-fact="resubmit|${f.id}">Resubmitted</button>`:''}<span class="small muted">${f.startedOn?`started ${fmt(f.startedOn)}`:''}${f.submittedOn?` · submitted ${fmt(f.submittedOn)}`:''}${f.approvedOn?` · approved ${fmt(f.approvedOn)}`:''}</span></div></div>`; }).join('')||'<div class="empty">No fixed-fee filings on this proposal.</div>'}`; }
function filingInvoice(p, f, pct, label){ const c = DB.clients.find(x=>x.id===p.clientId); if (!c) return; const inv = newDoc(c, 'invoice'); inv.mode = 'items'; inv.title = `${f.name} — ${label}`; inv.projectId = p.id; inv.template = 'design'; inv.lines = [{id:uid('l'), item:`${f.name} — ${label} (${Math.round(pct*100)}% of ${money(f.fee)})`, desc:'Fixed filing fee per agreement §5.B', qty:1, unit:'ls', rate:r2(f.fee*pct), taxable:false, code:'18', filing:f.key}]; inv.status = 'draft'; docMark(inv); return inv; }
function wireFilings(root, p){ root.querySelectorAll('[data-chk]').forEach(i => i.onchange = () => { p.studioChecks = p.studioChecks||{}; p.studioChecks[i.dataset.chk] = i.checked; save(); render(); }); root.querySelectorAll('[data-fact]').forEach(b => b.onclick = () => { const [a, id] = b.dataset.fact.split('|'); const f = DB.studio.filings.find(x=>x.id===id); let inv = null; if (a==='start'){ f.status = 'in-prep'; f.startedOn = today(); f.billed.start = true; inv = filingInvoice(p, f, .5, '50% at start'); } if (a==='submit'){ f.status = 'submitted'; f.submittedOn = today(); f.billed.submit = true; inv = filingInvoice(p, f, .25, '25% at submission'); } if (a==='round'){ f.rounds++; f.status = 'objections'; if (f.rounds>2) toast(`Round ${f.rounds} — beyond the two included; bill additional services hourly`); } if (a==='resubmit'){ f.status = 'submitted'; } if (a==='approve'){ f.status = 'approved'; f.approvedOn = today(); f.billed.approve = true; inv = filingInvoice(p, f, .25, '25% at approval'); } touch('filing', f.id, f.name, p.id, 20); log(`${f.name}: ${FILING_STATUS[f.status][0]}`); save(); render(); if (inv) toast(`${inv.number} drafted — ${money(docTotal(inv).total)} · Clients & billing`); }); }
function renderSFile(){ const root = $('#sfile-body'); if (!root) return; ensureStudioProject(); const p = S; const F = DB.studio.filings.filter(f=>f.projectId===p.id); root.innerHTML = `<div class="ph"><div><h2>Filings — ${esc(p.project.name)}</h2><div class="small muted">Fixed-fee tracks from the proposal. Predecessors follow the NYC sequence: LPC before DOB, ACP-5 before plan approval, survey before anything. Each milestone drafts its invoice.</div></div></div>${filingsHtml(p, F)}`; wireFilings(root, p); }
/* ---------- my day ---------- */
function renderSDay(){ const root = $('#sday-body'); if (!root) return; ensureStudioProject(); const u = currentUser(); const emp = DB.employees.find(e=>e.id===u?.employeeId); const td = today(); const mine = p => !emp || p.tasks.some(t => t.assignee===emp.name) || roomsOf(p.id).length; const projs = studioProjects().filter(mine);
  const T = touches(); const tm = timerOn(null) || (()=>{ try { return JSON.parse(localStorage.getItem('studio-timer')||'null'); } catch(e){ return null; } })(); const logged = emp ? r2(DB.time.filter(t=>t.empId===emp.id && t.date===td).reduce((a,t)=>a+hoursOf(t),0)) : 0; const yday = iso(addDays(td,-1)); const yLogged = emp ? r2(DB.time.filter(t=>t.empId===emp.id && t.date===yday).reduce((a,t)=>a+hoursOf(t),0)) : 0;
  const mtgs = DB.studio.meetings.filter(m => (!emp || m.attendees.includes(emp.id)) && [td, yday].includes(m.date) && !DB.time.some(t => t.meetingId===m.id && t.empId===emp?.id));
  const due = projs.flatMap(p => p.tasks.filter(t => t.status!=='done' && (t.track||'')==='design' && (!emp || t.assignee===emp.name) && t.end && dayDiff(td, t.end) <= 7).map(t => ({p, t})));
  const dec = projs.flatMap(p => p.decisions.filter(d => d.status==='open').map(d => ({p, d}))).sort((a,b) => (a.d.due||'').localeCompare(b.d.due||''));
  const stale = projs.flatMap(p => sheetsOf(p.id).filter(s=>s.stale && s.status==='current').map(s => ({p, s})));
  const unv = projs.map(p => ({p, n:roomsOf(p.id).filter(r=>roomProv(r)===0).length})).filter(x=>x.n);
  root.innerHTML = `<div class="ph"><div><h2>${u?`${esc(u.name.split(' ')[0])}, `:''}${fmtL(td)}</h2><div class="small muted">${projs.length} project${projs.length===1?'':'s'} · ${logged} hrs logged today${yLogged?'':' · <b class="bad">nothing logged yesterday</b>'}</div></div><div class="acts">${tm?`<button class="btn sm" data-stoptimer>Stop timer · ${esc(tm.label)}</button>`:''}</div></div>
    <div class="grid2">
      <div>
        <div class="card"><h3>Today</h3>${due.map(({p,t}) => `<div class="st-item"><span class="k">${dayDiff(td,t.end)<0?'Late':dayDiff(td,t.end)===0?'Due today':`Due ${fmt(t.end)}`}</span><b>${esc(t.name)}</b><span class="small muted">${esc(p.project.name)}${t.hours?` · est. ${t.hours} hrs`:''}</span></div>`).join('')||'<div class="muted small">Nothing due this week.</div>'}</div>
        <div class="card" style="margin-top:10px"><h3>Waiting on a decision</h3>${dec.slice(0,6).map(({p,d}) => `<div class="st-item ${d.due && d.due<td?'late':''}"><span class="k">${d.gate?`Gate · ${esc(d.gate)}`:'Decision'} · ${fmt(d.due)}</span><b>${esc(d.name)}</b><span class="small muted">${esc(d.owner||'')} · ${esc(p.project.name)}</span></div>`).join('')||'<div class="muted small">Nothing open.</div>'}</div>
        ${stale.length||unv.length ? `<div class="card" style="margin-top:10px"><h3>Drawings</h3>${stale.map(({p,s}) => `<div class="st-item late"><span class="k">Re-issue · ${esc(p.project.name)}</span><b>${esc(s.number)} ${esc(s.title)}</b><span class="small muted">${esc(s.staleWhy||'')}</span></div>`).join('')}${unv.map(({p,n}) => `<div class="st-item"><span class="k">Survey · ${esc(p.project.name)}</span><b>${n} room${n===1?'':'s'} still on listing dimensions</b><span class="small muted">DD, set issue and fabrication orders wait for it</span></div>`).join('')}</div>` : ''}
      </div>
      <div>
        <div class="card st-day"><h3>Day sheet <span class="small muted">— what you touched; tap to make it hours</span></h3>
          ${mtgs.map(m => `<button class="st-chip" data-mtg="${m.id}"><span class="k">Meeting · ${m.date===td?'today':'yesterday'} · ${Math.round(m.minutes/60*4)/4} hrs</span><b>${esc(m.title)}</b><span class="small muted">${esc(DB.projects.find(p=>p.id===m.projectId)?.project.name||'')}</span></button>`).join('')}
          ${T.slice().reverse().map(t => `<button class="st-chip" data-touch="${t.k}"><span class="k">${t.kind==='timer'?'Timer':t.kind==='room'?'Dimensions':t.kind==='sheet'?'Drawing':t.kind==='issue'?'Issued':t.kind==='survey'?'Survey':t.kind==='filing'?'Filing':'Worked on'} · ${t.min?`${Math.max(.25, Math.round(t.min/15)/4)} hrs`:'set hours'}</span><b>${esc(t.label)}</b><span class="small muted">${esc(DB.projects.find(p=>p.id===t.projectId)?.project.name||'')}</span></button>`).join('')}
          ${!mtgs.length && !T.length ? '<div class="muted small">Open a room, a drawing or a meeting and it lands here. Or add hours directly.</div>' : ''}
          <div class="row" style="margin-top:8px;gap:6px;flex-wrap:wrap"><select id="st-addp">${projs.map(p => `<option value="${p.id}">${esc(p.project.name)}</option>`).join('')}</select><input id="st-addh" type="number" step="0.25" placeholder="hrs" style="width:70px"><input id="st-addn" placeholder="what" style="flex:1;min-width:120px"><button class="btn sm" id="st-addgo">Log</button></div>
          <div class="small muted" style="margin-top:8px">Hours left this phase are on each project's board. Entries go to your manager for approval.</div></div>
        <div class="card" style="margin-top:10px"><h3>Projects</h3>${projs.map(p => { const ph = phaseHours(p); const R = retainerLeft(p); const cur = ph.find(x=>x.left>0 && x.used>0) || ph[0]; return `<div class="st-item" data-goproj="${p.id}" style="cursor:pointer"><span class="k">${cur?`${esc(cur.line.item.split(' and ')[0])} · ${cur.left} hrs left`:'No proposal'}${R?` · retainer ${R.hours} hrs`:''}</span><b>${esc(p.project.name)}</b><span class="small muted">${roomsOf(p.id).length} rooms · ${sheetsOf(p.id).filter(s=>s.status==='current').length} current sheets · ${roomsOf(p.id).filter(r=>roomProv(r)===0).length} unverified</span></div>`; }).join('')}</div>
      </div></div>`;
  const doLog = (projectId, hours, note, extra) => { const ph = phaseHours(DB.projects.find(p=>p.id===projectId)); const idx = Math.max(0, ph.findIndex(x=>x.left>0 && x.used>0)); const e = logHours(projectId, hours, idx, note, extra?.date); if (e){ Object.assign(e, extra||{}); save(); toast(`${hours} hrs logged — ${note}`); } };
  root.querySelectorAll('[data-mtg]').forEach(b => b.onclick = () => { const m = DB.studio.meetings.find(x=>x.id===b.dataset.mtg); doLog(m.projectId, Math.round(m.minutes/60*4)/4, m.title, {meetingId:m.id, date:m.date}); renderSDay(); });
  root.querySelectorAll('[data-touch]').forEach(b => b.onclick = () => { const t = T.find(x=>x.k===b.dataset.touch); const def = t.min ? Math.max(.25, Math.round(t.min/15)/4) : 1; const h = prompt(`Hours on "${t.label}"?`, def); if (h==null || !+h) return; doLog(t.projectId, +h, t.label); try { localStorage.setItem(touchKey(), JSON.stringify(T.filter(x=>x.k!==t.k))); } catch(e){} renderSDay(); });
  root.querySelector('#st-addgo')?.addEventListener('click', () => { const h = +$('#st-addh').value; if (!h) return; doLog($('#st-addp').value, h, $('#st-addn').value||'Design'); renderSDay(); });
  root.querySelector('[data-stoptimer]')?.addEventListener('click', () => { timerToggle(tm.id, tm.label, tm.projectId); renderSDay(); });
  root.querySelectorAll('[data-goproj]').forEach(el => el.onclick = () => { setCurrent(el.dataset.goproj); setView('sboard'); }); }
/* ---------- studio: the director's screen ---------- */
function renderStudio(){ const root = $('#studio-body'); if (!root) return; ensureStudioProject(); const td = today(); const projs = studioProjects(); const designers = DB.employees.filter(isDesignStaff);
  const rows = projs.map(p => { const ph = phaseHours(p); const R = retainerLeft(p); const est = ph.reduce((a,x)=>a+x.est,0), used = ph.reduce((a,x)=>a+x.used,0); const F = DB.studio.filings.filter(f=>f.projectId===p.id); const inRev = F.filter(f=>f.status==='submitted').map(f => `${f.name.split(' — ')[0]} ${dayDiff(f.submittedOn, td)}d`); const unv = roomsOf(p.id).filter(r=>roomProv(r)===0).length; const stale = sheetsOf(p.id).filter(s=>s.stale && s.status==='current').length; const gates = p.decisions.filter(d=>d.status==='open' && d.gate); const late = p.decisions.filter(d=>d.status==='open' && d.due && d.due<td).length; const c = DB.clients.find(x=>x.id===p.clientId); const cur = ph.find(x=>x.left>0 && x.used>0) || ph[0]; return {p, c, est, used, R, cur, inRev, unv, stale, gates, late, F}; });
  const unlogged = designers.map(e => { const days = [1,2,3,4,5].map(n => iso(addDays(td,-n))).filter(d => ![0,6].includes(parse(d).getDay())); const missing = days.filter(d => !DB.time.some(t=>t.empId===e.id && t.date===d)); return {e, missing}; }).filter(x=>x.missing.length);
  root.innerHTML = `<div class="ph"><div><h2>Studio</h2><div class="small muted">Every design project on one screen: hours against the proposal, retainers, filings in review, surveys outstanding, sheets to re-issue, gates.</div></div></div>
    <div class="kpis"><div class="kpi"><b>${projs.length}</b><span>design projects</span></div><div class="kpi ${rows.some(r=>r.unv)?'warn':''}"><b>${rows.reduce((a,r)=>a+r.unv,0)}</b><span>rooms on listing dimensions</span></div><div class="kpi ${rows.some(r=>r.stale)?'warn':''}"><b>${rows.reduce((a,r)=>a+r.stale,0)}</b><span>sheets to re-issue</span></div><div class="kpi ${unlogged.length?'warn':''}"><b>${unlogged.reduce((a,x)=>a+x.missing.length,0)}</b><span>designer-days without hours (5 days)</span></div></div>
    <div class="tw"><table class="t"><thead><tr><th>Project</th><th>Client</th><th>Phase</th><th class="money">Hours</th><th class="money">Retainer</th><th>Filings</th><th>Survey</th><th>Drawings</th><th>Gates</th></tr></thead><tbody>${rows.map(r => `<tr data-goproj="${r.p.id}" style="cursor:pointer"><td><b>${esc(r.p.project.name)}</b></td><td>${esc(r.c?.name||'—')}</td><td>${r.cur?esc(r.cur.line.item.split(' and ')[0]):'—'}</td><td class="money ${r.used>r.est?'bad':''}">${r.used} / ${r.est}</td><td class="money ${r.R&&r.R.hours<=20?'bad':''}">${r.R?`${r.R.hours} hrs`:'—'}</td><td class="small">${r.inRev.join(', ')||(r.F.length?`${r.F.filter(f=>f.status==='approved').length} of ${r.F.length} approved`:'—')}</td><td>${r.unv?`<span class="pill bad">${r.unv} unverified</span>`:'<span class="pill ok">Measured</span>'}</td><td>${r.stale?`<span class="pill bad">${r.stale} stale</span>`:`${sheetsOf(r.p.id).filter(s=>s.status==='current').length} current`}</td><td>${r.gates.length?`<span class="pill ${r.late?'bad':'warn'}">${r.gates.length} open${r.late?` · ${r.late} late`:''}</span>`:'—'}</td></tr>`).join('')}</tbody></table></div>
    <div class="grid2" style="margin-top:14px"><div class="card"><h3>Hours not logged</h3>${unlogged.map(x => `<div class="row" style="padding:6px 0;border-top:1px solid var(--rule)"><b>${esc(x.e.name)}</b><span class="small muted">${x.missing.map(fmt).join(', ')}</span></div>`).join('')||'<div class="muted small">Everyone is current.</div>'}</div>
    <div class="card"><h3>Who is on what</h3>${designers.map(e => { const T = DB.time.filter(t=>t.empId===e.id && dayDiff(t.date, td) <= 14 && dayDiff(t.date, td) >= 0); const by = {}; T.forEach(t => by[t.projectId] = (by[t.projectId]||0) + hoursOf(t)); const next = projs.flatMap(p => p.tasks.filter(t => t.assignee===e.name && t.status!=='done' && t.end >= td).map(t => ({p,t}))); return `<div style="padding:6px 0;border-top:1px solid var(--rule)"><b>${esc(e.name)}</b> <span class="small muted">${esc(e.role)} · $${e.billRate}/hr</span><div class="small">${Object.entries(by).map(([pid,h]) => `${esc(DB.projects.find(p=>p.id===pid)?.project.name||'')} ${r2(h)} hrs`).join(' · ')||'no hours in 14 days'}</div>${next.length?`<div class="small muted">Next: ${next.slice(0,3).map(x=>`${esc(x.t.name)} (${fmt(x.t.end)})`).join(' · ')}</div>`:''}</div>`; }).join('')}</div></div>`;
  root.querySelectorAll('[data-goproj]').forEach(el => el.onclick = () => { setCurrent(el.dataset.goproj); setView('sboard'); }); }
/* ---------- fabrication gate on purchase orders ---------- */
function poFabGate(po){ const p = DB.projects.find(x=>x.id===po.projectId); if (!p) return ''; const rooms = roomsOf(p.id); if (!rooms.length) return ''; const hit = po.lines.filter(l => FAB_WORDS.test(l.item||'') || FAB_WORDS.test(poCat?.(po)||'')); if (!hit.length) return ''; const rs = rooms.filter(r => hit.some(l => l.roomId===r.id || (l.item||'').toLowerCase().includes(r.name.toLowerCase()))); const unv = rs.filter(r => roomMissing(r).length); if (unv.length) return `Fabrication order waits for field measurements: ${unv.map(r => `${r.name} (${roomMissing(r).map(d=>d.label).join(', ')})`).join('; ')}`; if (rs.length && !po.tradeVerified) return `Second measurement first: confirm the fabricator's own field measurements for ${rs.map(r=>r.name).join(', ')} on the PO before it issues`; return ''; }
if (typeof poAction==='function'){ const poActionBase_st = poAction; poAction = function(po, a){ if (['issue','approve','submit'].includes(a)){ const g = poFabGate(po); if (g){ toast(g); return; } if (po.stale){ toast(`${po.number} carries a changed dimension — check the lines against the re-issued drawings first`); return; } } return poActionBase_st(po, a); }; }
if (typeof renderPODoc==='function'){ const renderPODocBase_st = renderPODoc; renderPODoc = function(po){ const h = renderPODocBase_st(po); const g = poFabGate(po); if (!g && !po.stale) return h; return `<div class="note ${po.stale?'bad':'warn'}" style="margin-bottom:10px"><b>${po.stale?'A dimension on this order changed.':'Measurement gate.'}</b> ${esc(g||'Re-check the lines against the re-issued drawings, then clear the change record under Drawings.')}${!po.stale && /Second measurement/.test(g)?` <label style="margin-left:8px"><input type="checkbox" data-tradeok="${po.id}"> Fabricator's field measurements received and entered</label>`:''}</div>` + h; }; document.addEventListener('change', e => { const cb = e.target.closest('[data-tradeok]'); if (!cb) return; const po = DB.pos.find(x=>x.id===cb.dataset.tradeok); if (po){ po.tradeVerified = cb.checked; save(); toast(cb.checked ? 'Enter the fabricator\'s numbers on the room — a mismatch beyond tolerance makes a change record' : 'Gate back on'); } }); }
/* ---------- reminders / nav / render ---------- */
const remindersBase_st = reminders;
reminders = function(){ const out = remindersBase_st(); const td = today(); const projs = studioProjects(); const unv = projs.reduce((a,p)=>a+roomsOf(p.id).filter(r=>roomProv(r)===0 && sheetsOf(p.id).some(s=>s.rooms.includes(r.id))).length,0); if (unv) out.push({n:unv, label:'rooms drawn on listing dimensions — survey before design development', go:{view:'sboard'}, sev:'warn'}); const stale = projs.reduce((a,p)=>a+sheetsOf(p.id).filter(s=>s.stale && s.status==='current').length,0); if (stale) out.push({n:stale, label:'drawings carry a changed dimension — re-issue before anyone builds from them', go:{view:'sdraw'}, sev:'bad'}); const rev = DB.studio.filings.filter(f=>f.status==='submitted'); if (rev.length) out.push({n:rev.length, label:'filings in agency review', go:{view:'sfile'}, sev:''}); const R = projs.map(p=>({p, R:retainerLeft(p)})).filter(x=>x.R && x.R.hours<=x.R.replenishAt); if (R.length) out.push({n:R.length, label:`design retainer${R.length===1?'':'s'} at replenishment point · ${R.map(x=>x.p.project.name).join(', ')}`, go:{view:'studio'}, sev:'warn'}); if (['designer','design_mgr'].includes(role())){ const u = currentUser(); const emp = DB.employees.find(e=>e.id===u?.employeeId); const y = iso(addDays(td,-1)); if (emp && ![0,6].includes(parse(y).getDay()) && !DB.time.some(t=>t.empId===emp.id && t.date===y)) out.push({n:1, label:'day without hours — yesterday. Your day sheet remembers what you touched', go:{view:'sday'}, sev:'warn'}); } return out; };
NAV_GROUPS.splice(2, 0, {id:'studio', n:'Studio', views:['sday','sboard','sdraw','sfile','studio'], proj:true});
Object.assign(NAV_LABELS, {sday:'My day', sboard:'Project', sdraw:'Drawings', sfile:'Filings', studio:'Studio'});
NAV_ICON.studio = '<path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>';
const renderBase_st = render;
render = function(){ renderBase_st(); /* My day and Studio span every project — the project switcher only belongs on the project tabs */ const sp = document.querySelector('#subnav .sub-proj'); if (sp){ const cross = ['sday','studio','port'].includes(view); sp.style.display = cross ? 'none' : ''; /* the switcher sits between the cross-project tab and the tabs it scopes */ const tabs = sp.parentElement?.querySelector('.sub-tabs'); const first = tabs?.querySelector('[data-sub]'); if (tabs && first && ['port','sday'].includes(first.dataset.sub) && !tabs.dataset.split){ tabs.dataset.split = '1'; const cut = tabs.querySelector('[data-sub="port"], [data-sub="sday"]'); if (cut){ const left = document.createElement('div'); left.className = 'sub-tabs sub-cross'; left.appendChild(cut); tabs.before(left); left.after(sp); } } } if (view==='sday') renderSDay(); if (view==='sboard') renderSBoard(); if (view==='sdraw') renderSDraw(); if (view==='sfile') renderSFile(); if (view==='studio') renderStudio(); };

/* ===================== STUDIO B — the record the meeting didn't have: intake, promises, explorations, preferences, FF&E, the client's page ===================== */
/* A recorded meeting becomes proposals — decisions, open questions, promises in both directions, preferences, selections, site notes — and a person confirms each one. Nothing is committed by the machine. Confirmed items get an owner and a date and show up where each person looks: the designer's day, the director's screen, the client's page. */
const INTAKE_KINDS = {decision:'Decisions made', question:'Open questions', promise:'Promises', pref:'Preferences', ffe:'Selections (FF&E)', site:'Site & measurement notes'};
const FFE_STATUS = ['proposed','client approved','ordered','delivered','installed'];
function studio2Init(){ const St = DB.studio; St.promises = St.promises||[]; St.prefs = St.prefs||{}; St.ffe = St.ffe||[]; St.intake = St.intake||{}; St.precedents = St.precedents||[];
  if (!DB.users.some(u=>u.id==='u_cambri')) DB.users.push({id:'u_cambri', name:'Cambri Jessop', role:'client', contact:'cambri@example.com', clientId:'cl140'});
  if (!DB.__studio2Seed && DB.studio.meetings.some(m=>m.id==='mt140a')) studio2Seed(); }
function studio2Seed(){ DB.__studio2Seed = 1; const St = DB.studio; const pid = 'p140'; const rm = n => St.rooms.find(r => r.projectId===pid && r.name===n)?.id || '';
  const I = (kind, text, o) => Object.assign({id:uid('ik'), kind, text, room:'', owner:'', dir:'', due:'', gate:'', status:'proposed'}, o||{});
  St.intake['mt140a'] = {meetingId:'mt140a', at:'2026-09-05', by:'assistant', items:[
    I('decision','Bed goes in the existing arch niche, across from the fireplace', {room:rm('Primary bedroom'), owner:'Cambri Jessop'}),
    I('decision','Closet bigger than the bathroom; toilet in its own compartment tucked behind the closet', {room:rm('Dressing room'), owner:'Cambri Jessop'}),
    I('decision','Single sink with a longer counter instead of a double vanity; no makeup counter', {room:rm('Primary bath'), owner:'Cambri Jessop'}),
    I('decision','Hall bath is a full bath with shower and a pocket door — not a powder room', {room:rm('Hall bath'), owner:'Cambri Jessop'}),
    I('decision','No recessed can lighting anywhere — central fixtures and sconces', {owner:'Cambri Jessop'}),
    I('decision','Keep the 66" room as a small study; two guest bedrooms share one bath', {room:rm('Study'), owner:'Cambri Jessop'}),
    I('decision','Laundry: centered door with two pocket doors, counters both sides, sink at back, W/D under counter, drying rail above', {room:rm('Laundry'), owner:'Cambri Jessop'}),
    I('decision','Roof deck is phase 2 — draw the stair now so structure and HVAC allow it later', {owner:'Jaleena Jessop', gate:'Framing'}),
    I('decision','Garden level is a rental unit (1 bed / 1 bath) with its own laundry closet — invest less there', {room:rm('Rental unit'), owner:'Cambri Jessop'}),
    I('decision','Rear "micro mud room" comes out (not original, not worth bringing to code)', {owner:'Alan'}),
    I('question','Island: large island with sink as drawn, offset island near the range, or antique island with the sink under an arched rear window?', {room:rm('Kitchen'), owner:'Cambri Jessop', due:'2026-09-19'}),
    I('question','Does the kitchen fireplace work, or can it? Drives seating and island position', {room:rm('Kitchen'), owner:'SmartDesign · site check', due:'2026-09-20', gate:'Kitchen layout'}),
    I('question','Fridge / freezer location: panel-front in a pantry, under-counter drawers flanking the range, or drawers in the island', {room:rm('Kitchen'), owner:'Sarah Davis', due:'2026-09-19'}),
    I('question','Tub: angled in the corner vs in front of the window; red Kohler tub with brass — dimensions needed', {room:rm('Primary bath'), owner:'Sarah Davis', due:'2026-09-19'}),
    I('question','Roof-stair route: continue the existing stair, new stair from the study, or a lift — with bulkhead rules and cost', {owner:'Sarah Davis', due:'2026-11-05', gate:'Framing'}),
    I('question','Facade and windows now or later? Front windows must be double-hung per the 1940 tax photo', {owner:'Jaleena Jessop', due:'2026-09-19'}),
    I('question','Deck cover: awning, covered or greenhouse-style enclosure on the parlor deck', {room:rm('Kitchen'), owner:'Cambri Jessop'}),
    I('question','Cellar water: sump pump, French drain, replace the 200-year-old storm drain — scope and price', {owner:'Alan'}),
    I('promise','Send the presentation deck', {dir:'us', owner:'Sarah Davis', due:'2026-09-07'}),
    I('promise','Render the third kitchen option (antique island, sink under an arched window) with a light study', {dir:'us', owner:'Sarah Davis', due:'2026-09-11', hours:8}),
    I('promise','Primary bath / dressing layout options: angled tub, WC compartment, smaller vanity, longer hall bath', {dir:'us', owner:'Sarah Davis', due:'2026-09-12', hours:10}),
    I('promise','Roof-stair options with pros, cons, bulkhead and cost', {dir:'us', owner:'Sarah Davis', due:'2026-10-15', hours:30}),
    I('promise','Reference images of "whisper" micro-recessed lights', {dir:'us', owner:'Sarah Davis', due:'2026-09-09'}),
    I('promise','Price the facade and windows done now vs in two stages; quote the front door and vestibule door', {dir:'us', owner:'Alan', due:'2026-09-19'}),
    I('promise','Wiring instructions and the retainer invoice', {dir:'us', owner:'Janette', due:'2026-09-08'}),
    I('promise','Share the folder of 200+ site photos', {dir:'us', owner:'Alan', due:'2026-09-06'}),
    I('promise','Share the Pinterest board (pruned) and Mexico City kitchen photos', {dir:'client', owner:'Cambri Jessop', due:'2026-09-09'}),
    I('promise','Sign and return the acceptance form', {dir:'client', owner:'Jaleena Jessop', due:'2026-09-12'}),
    I('promise','Wire the retainer and 50% of the immediate filings', {dir:'client', owner:'Jaleena Jessop', due:'2026-09-15'}),
    I('promise','Decide lighting, outlet and sconce locations before framing', {dir:'client', owner:'Cambri Jessop', due:'2026-11-05'}),
    I('pref','Likes: steel base cabinetry with rosy marble, antique (never faux) pieces, patterned colour stone floors, curved hoods, glass showers, glass-front closet doors, brass, statement fixtures, sconces, wallpaper'),
    I('pref','Dislikes: beige palettes, faux antique, recessed cans, sink in the island, things hidden behind doors, arch-enclosed showers, black-white-red "diner" look'),
    I('pref','Rule: no recessed can lighting — "very, very hard to convince me"'),
    I('ffe','La Cornue-style freestanding gas range in the arch', {room:rm('Kitchen'), owner:'liked'}),
    I('ffe','Kohler 100th-anniversary red tub, brass fittings', {room:rm('Primary bath'), owner:'undecided'}),
    I('ffe','Two antique armoires flanking the fireplace as pantry', {room:rm('Kitchen'), owner:'liked'}),
    I('ffe','LG air-drying closet', {room:rm('Laundry'), owner:'undecided'}),
    I('ffe','Brick / stone paver floor continuing out to the deck', {room:rm('Kitchen'), owner:'liked'}),
    I('site','Plans are drawn on the realtor\'s marketing plan — "off everywhere"; survey every room before the next design round'),
    I('site','Rear wall stack-up: sink 30" + DW 24" + pull-outs + trash 24" ≈ 7\' — doors shrink to 12–18" unless the arch grows', {room:rm('Kitchen')}),
    I('site','Fireplace marble under paint — probably darker/greyer than rendered; fireplace depth vs today\'s requirements', {room:rm('Kitchen')}),
    I('site','Hall-bath shower minimum width is the pinch point for the closet run', {room:rm('Hall bath')}),
    I('site','Existing stairs likely not to code (grandfathered); a new roof stair must comply and needs a landing'),
  ]};
  const m = St.meetings.find(x=>x.id==='mt140a'); if (m) m.intake = 'proposed'; const dk = St.sheets.find(s=>s.id==='sh140d'); if (dk) dk.notes = 'Kitchen rendering: recessed can lighting in the ceiling; palettes lean beige / neutral.';
  St.precedents.push({id:'pc1', projectId:'p45', title:'45 Cranberry — kitchen with sink under the rear window', rooms:['Kitchen'], note:'Custom doors either side of a 4\'-6" arch came out at 14" — client was fine with it once we mocked the opening on site.'}, {id:'pc2', projectId:'p121', title:'121 State — parlor kitchen, steel base + stone', rooms:['Kitchen'], note:'Steel cabinetry from Hudson vendor; 12-week lead. Stone apron sink needed a reinforced base.'}); }
/* ---------- intake ---------- */
async function intakeRun(m, text){ const p = DB.projects.find(x=>x.id===m.projectId); const rooms = roomsOf(p.id).map(r=>r.name); const prompt = `You are the design studio's meeting assistant. From this meeting transcript, extract JSON only: {"items":[{"kind":"decision|question|promise|pref|ffe|site","text":"…","room":"one of: ${rooms.join(', ')} or empty","owner":"person","dir":"us|client (promises only)","due":"YYYY-MM-DD or empty","gate":"what it blocks, or empty","hours":number or 0}]}. Decisions = what the client agreed; questions = still open; promises = who owes what; pref = likes/dislikes/rules; ffe = product or material selections; site = measurements, existing conditions, things to check on site. Be faithful, no invention, ≤45 items.\n\nTRANSCRIPT:\n${text.slice(0, 60000)}`; const r = await ai(prompt, 4000); if (r.startsWith('__ERR')) return {error:r.slice(6,120)}; const j = safeJSON(r); if (!j || !j.items) return {error:'could not read the reply'}; const items = j.items.map(it => ({id:uid('ik'), kind:INTAKE_KINDS[it.kind]?it.kind:'site', text:String(it.text||'').trim(), room:roomsOf(p.id).find(r=>r.name.toLowerCase()===String(it.room||'').toLowerCase())?.id||'', owner:it.owner||'', dir:it.dir||'', due:it.due||'', gate:it.gate||'', hours:+it.hours||0, status:'proposed'})).filter(x=>x.text); DB.studio.intake[m.id] = {meetingId:m.id, at:today(), by:'assistant', items}; m.intake = 'proposed'; save(); return {n:items.length}; }
function intakeConfirm(m, it){ const p = DB.projects.find(x=>x.id===m.projectId); const St = DB.studio; const room = St.rooms.find(r=>r.id===it.room); const c = DB.clients.find(x=>x.id===p.clientId); const decider = c?.contacts.find(x=>x.decides==='design')?.name || '';
  if (it.kind==='decision'){ p.decisions.push({id:uid('dc'), name:it.text, owner:it.owner||decider, due:it.due||'', status:'made', madeOn:m.date, decidedBy:it.owner||decider, roomId:it.room, gate:it.gate, kind:'design', source:m.id}); if (room && !room.notes.includes(it.text)) room.notes = (room.notes ? room.notes+'\n' : '') + it.text; }
  if (it.kind==='question'){ const isClient = c && c.contacts.some(x => it.owner && x.name.split(' ')[0]===it.owner.split(' ')[0]); p.decisions.push({id:uid('dc'), name:it.text, who:it.owner||decider, owner: isClient || !it.owner ? 'Client' : it.owner, due:it.due||iso(addDays(m.date, 14)), status:'open', roomId:it.room, gate:it.gate, kind:'design', source:m.id}); }
  if (it.kind==='promise'){ const pr = {id:uid('pr'), projectId:p.id, text:it.text, owner:it.owner, dir:it.dir||'us', due:it.due||iso(addDays(m.date, 7)), status:'open', hours:+it.hours||0, source:m.id, madeOn:m.date}; St.promises.push(pr); if (pr.dir==='us' && pr.hours){ p.tasks.push({id:uid('tk'), name:pr.text, start:m.date, end:pr.due, dur:Math.max(1, workdays(m.date, pr.due)), deps:[], status:'planned', track:'design', assignee:pr.owner, type:'task', hours:pr.hours, exploration:true, clientApproved:false, promiseId:pr.id}); } }
  if (it.kind==='pref'){ const P = St.prefs[p.id] = St.prefs[p.id]||{likes:[], dislikes:[], rules:[]}; const t = it.text; const k = /^dislikes?:/i.test(t) ? 'dislikes' : /^rule:/i.test(t) ? 'rules' : 'likes'; const body = t.replace(/^(likes?|dislikes?|rule):\s*/i,''); (k==='rules' ? [body] : body.split(/,\s*|;\s*/)).map(x=>x.trim()).filter(Boolean).forEach(x => { if (!P[k].includes(x)) P[k].push(x); }); }
  if (it.kind==='ffe'){ St.ffe.push({id:uid('ff'), projectId:p.id, roomId:it.room, item:it.text, status:it.owner==='liked'?'proposed':'proposed', note:it.owner||'', vendor:'', price:'', lead:'', source:m.id}); }
  if (it.kind==='site'){ if (room) room.notes = (room.notes ? room.notes+'\n' : '') + it.text; else p.log.unshift({t:m.date, msg:`Site note from ${m.title}: ${it.text}`, src:'intake', ts:new Date().toISOString()}); }
  it.status = 'confirmed'; }
function intakeHtml(m){ const K = DB.studio.intake[m.id]; const p = DB.projects.find(x=>x.id===m.projectId); const rooms = roomsOf(p.id); if (!K) return `<div class="empty">No proposals yet for this meeting.</div>`; const open = K.items.filter(i=>i.status==='proposed'); const c = DB.clients.find(x=>x.id===p.clientId); const people = [...new Set([...(c?.contacts.map(x=>x.name)||[]), ...DB.employees.filter(isDesignStaff).map(e=>e.name), 'Alan', 'Janette'])];
  return `<div class="row" style="margin-bottom:8px"><div><b>${esc(m.title)}</b> <span class="small muted">${fmtL(m.date)} · ${K.items.length} proposals · ${open.length} to review</span></div><span class="grow"></span>${open.length?`<button class="btn sm primary" data-ik-all="${m.id}">Confirm all ${open.length} shown</button>`:'<span class="pill ok">All reviewed</span>'}</div><p class="small muted" style="margin:0 0 10px">The assistant read the transcript and proposed these. Edit anything, then confirm or drop each one — nothing is on the record until a person says so. Confirmed decisions land on the rooms and the client's page; promises get owners and dates; explorations with hours become tasks the client can see the cost of.</p>
    ${Object.entries(INTAKE_KINDS).map(([k, label]) => { const items = K.items.filter(i=>i.kind===k); if (!items.length) return ''; return `<div class="card" style="margin-bottom:10px"><h3>${label} <span class="small muted">${items.filter(i=>i.status==='proposed').length} open</span></h3>${items.map(it => `<div class="ik ${it.status}" data-ik="${it.id}"><div class="row" style="align-items:flex-start;gap:8px"><textarea data-ikf="text" rows="2" ${it.status!=='proposed'?'readonly':''}>${esc(it.text)}</textarea>${it.status==='proposed'?`<div class="ik-acts"><button class="btn sm primary" data-ikok="${it.id}">Confirm</button><button class="btn sm" data-ikno="${it.id}">Drop</button></div>`:`<span class="pill ${it.status==='confirmed'?'ok':'neutral'}">${it.status}</span>`}</div>${it.status==='proposed'?`<div class="row ik-meta">${['decision','question','ffe','site'].includes(k)?`<select data-ikf="room"><option value="">— room —</option>${rooms.map(r => `<option value="${r.id}" ${it.room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`:''}${['decision','question','promise'].includes(k)?`<input data-ikf="owner" list="ik-people" value="${esc(it.owner)}" placeholder="owner" style="width:150px">`:''}${k==='promise'?`<select data-ikf="dir"><option value="us" ${it.dir!=='client'?'selected':''}>We owe the client</option><option value="client" ${it.dir==='client'?'selected':''}>Client owes us</option></select><input data-ikf="hours" type="number" step="1" value="${it.hours||''}" placeholder="est. hrs" style="width:80px" title="Design exploration hours — visible to the client">`:''}${['question','promise'].includes(k)?`<input data-ikf="due" type="date" value="${it.due||''}">`:''}${['decision','question'].includes(k)?`<input data-ikf="gate" value="${esc(it.gate||'')}" placeholder="blocks… (gate)" style="width:140px">`:''}</div>`:''}</div>`).join('')}</div>`; }).join('')}<datalist id="ik-people">${people.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`; }
function wireIntake(root, m){ const K = DB.studio.intake[m.id]; if (!K) return; const read = it => { const el = root.querySelector(`[data-ik="${it.id}"]`); if (!el) return; el.querySelectorAll('[data-ikf]').forEach(i => { it[i.dataset.ikf] = i.type==='number' ? +i.value : i.value; }); }; const finish = () => { if (!K.items.some(i=>i.status==='proposed')) m.intake = 'done'; save(); render(); };
  root.querySelectorAll('[data-ikok]').forEach(b => b.onclick = () => { const it = K.items.find(x=>x.id===b.dataset.ikok); read(it); intakeConfirm(m, it); touch('intake', m.id, `Reviewed ${m.title}`, m.projectId, 5); finish(); });
  root.querySelectorAll('[data-ikno]').forEach(b => b.onclick = () => { const it = K.items.find(x=>x.id===b.dataset.ikno); it.status = 'dropped'; finish(); });
  root.querySelector('[data-ik-all]')?.addEventListener('click', () => { K.items.filter(i=>i.status==='proposed').forEach(it => { read(it); intakeConfirm(m, it); }); touch('intake', m.id, `Reviewed ${m.title}`, m.projectId, 20); finish(); toast('Confirmed — decisions on the rooms, promises dated, explorations as tasks'); }); }
function newMeetingDialog(p){ mbModal('New meeting', `<div class="f2"><div class="f"><label>Title</label><input data-f="title" placeholder="Design review — kitchen"></div><div class="f"><label>Date</label><input data-f="date" type="date" value="${today()}"></div></div><div class="f2"><div class="f"><label>With</label><input data-f="with" placeholder="Cambri & Jaleena"></div><div class="f"><label>Minutes</label><input data-f="minutes" type="number" value="60"></div></div><div class="f"><label>Transcript (paste from the recorder app) or Drive link</label><textarea data-f="text" rows="6" placeholder="Paste the transcript here — the assistant proposes decisions, questions, promises, preferences, selections and site notes for you to confirm."></textarea></div><div class="f"><label>Drive link</label><input data-f="link" placeholder="https://docs.google.com/…"></div>`, {submit:'Save & read', onSubmit:f => { if (!f.title) return false; const u = currentUser(); const emp = DB.employees.find(e=>e.id===u?.employeeId); const m = {id:uid('mt'), projectId:p.id, date:f.date, title:f.title, minutes:+f.minutes||60, attendees:[emp?.id||'u_alan'], with:f.with, link:f.link, intake:'pending'}; DB.studio.meetings.push(m); touch('meeting', m.id, m.title, p.id, m.minutes); save(); render(); if (f.text.trim().length > 200){ toast('Reading the transcript…'); intakeRun(m, f.text).then(r => { if (r.error){ toast(`Assistant couldn't read it (${r.error}) — add items by hand`); } else toast(`${r.n} proposals to review`); sboardTab = 'meetings'; render(); }); } }}); }
/* ---------- promises, explorations, preferences, FF&E ---------- */
function promisesOf(pid){ return DB.studio.promises.filter(x=>x.projectId===pid); }
function promiseRow(pr, who){ const late = pr.status==='open' && pr.due && pr.due < today(); return `<div class="st-item ${late?'late':''}"><span class="k">${pr.dir==='us'?'We owe':'Client owes'} · ${esc(pr.owner||'')} · ${late?'overdue ':'due '}${fmt(pr.due)}${pr.hours?` · est. ${pr.hours} hrs`:''}</span><div class="row" style="gap:8px"><b class="grow" style="font-weight:500">${esc(pr.text)}</b>${pr.status==='open' && who!=='client' ? `<button class="btn sm" data-prdone="${pr.id}">Done</button>` : pr.status==='done' ? `<span class="pill ok">Done ${fmt(pr.doneOn)}</span>` : ''}</div></div>`; }
function prefsHtml(pid, editable){ const P = DB.studio.prefs[pid] || {likes:[], dislikes:[], rules:[]}; const chip = (k, x, i) => `<span class="pf ${k}">${esc(x)}${editable?`<i data-pfrm="${k}|${i}" title="Remove">✕</i>`:''}</span>`; return `<div class="st-prefs">${[['rules','Hard rules'],['dislikes','Never'],['likes','Loves']].map(([k,l]) => `<div><span class="k">${l}</span><div class="pfs">${P[k].map((x,i)=>chip(k,x,i)).join('')||'<span class="small muted">—</span>'}${editable?`<input data-pfadd="${k}" placeholder="+ add" style="width:110px;height:24px;font-size:12px">`:''}</div></div>`).join('')}</div>`; }
function prefConflicts(pid, text){ const P = DB.studio.prefs[pid]; if (!P) return []; const t = (text||'').toLowerCase(); const hits = []; [...P.rules, ...P.dislikes].forEach(x => { const words = x.toLowerCase().replace(/^no\s+|^never\s+/,'').split(/[^a-z0-9]+/).filter(w => w.length > 3 && !['only','look','things','behind','doors','with','that','very','hard','convince'].includes(w)); if (words.length && words.every(w => t.includes(w))) hits.push(x); }); return [...new Set(hits)]; }
function ffeCard(f){ const r = DB.studio.rooms.find(x=>x.id===f.roomId); const i = FFE_STATUS.indexOf(f.status); return `<div class="st-ffe"><div class="hd"><b>${esc(f.item)}</b><span class="pill ${i>=1?'ok':'neutral'}">${f.status}</span></div><div class="small muted">${r?esc(r.name):'—'}${f.vendor?` · ${esc(f.vendor)}`:''}${f.price?` · ${money(+f.price)}`:''}${f.lead?` · ${esc(f.lead)} lead`:''}${f.note?` · ${esc(f.note)}`:''}</div><div class="row" style="gap:6px;margin-top:6px;flex-wrap:wrap">${i < FFE_STATUS.length-1 ? `<button class="btn sm ${i===0?'primary':''}" data-ffnext="${f.id}">${i===0?'Client approved':'→ '+FFE_STATUS[i+1]}</button>`:''}${i>=1 && !f.materialId ? `<button class="btn sm" data-ffbuy="${f.id}">Add to purchasing</button>` : f.materialId ? '<span class="small muted">On the buy board</span>' : ''}<button class="btn sm" data-ffedit="${f.id}">Edit</button></div></div>`; }
function ffeDialog(pid, id){ const f = id ? DB.studio.ffe.find(x=>x.id===id) : {roomId:'', item:'', vendor:'', price:'', lead:'', note:'', status:'proposed'}; const rooms = roomsOf(pid); mbModal(id?'Selection':'New selection', `<div class="f"><label>Item</label><input data-f="item" value="${esc(f.item)}"></div><div class="f2"><div class="f"><label>Room</label><select data-f="roomId">${rooms.map(r=>`<option value="${r.id}" ${f.roomId===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="f"><label>Status</label><select data-f="status">${FFE_STATUS.map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="f2"><div class="f"><label>Vendor</label><input data-f="vendor" value="${esc(f.vendor||'')}" list="ct-vendors-rec"></div><div class="f"><label>Price</label><input data-f="price" type="number" value="${f.price||''}"></div></div><div class="f2"><div class="f"><label>Lead time</label><input data-f="lead" value="${esc(f.lead||'')}" placeholder="12 weeks"></div><div class="f"><label>Note</label><input data-f="note" value="${esc(f.note||'')}"></div></div>`, {submit:'Save', onSubmit:v => { if (!v.item) return false; if (id) Object.assign(f, v); else DB.studio.ffe.push(Object.assign({id:uid('ff'), projectId:pid}, v)); save(); render(); }}); }
function ffeToPurchasing(f){ const p = DB.projects.find(x=>x.id===f.projectId); const r = DB.studio.rooms.find(x=>x.id===f.roomId); const wk = parseInt(f.lead)||8; const m = {id:uid('m'), name:f.item, task:'', vendor:f.vendor||'', lead:wk*5, status:'not-ordered', eta:'', notes:`FF&E selection — ${r?r.name:''}${f.note?' · '+f.note:''}`, roomId:f.roomId, ffeId:f.id, cost:+f.price||0, kind:'finish'}; p.materials.push(m); f.materialId = m.id; if (f.status==='client approved') f.status = 'client approved'; log(`FF&E to purchasing: ${f.item}${r?' ('+r.name+')':''}`); }
/* ---------- board tabs: intake in Meetings, Client, FF&E ---------- */
const renderSBoardBase_b = renderSBoard;
renderSBoard = function(){ renderSBoardBase_b(); const root = $('#sboard-body'); if (!root) return; const p = S; const c = DB.clients.find(x=>x.id===p.clientId);
  /* tabs: add FF&E */ const seg = root.querySelector('[data-sbtab]')?.parentElement; if (seg && !seg.querySelector('[data-sbtab="ffe"]')){ const n = DB.studio.ffe.filter(f=>f.projectId===p.id).length; const b = document.createElement('button'); b.dataset.sbtab = 'ffe'; b.className = sboardTab==='ffe'?'on':''; b.textContent = `FF&E${n?` · ${n}`:''}`; seg.append(b); b.onclick = () => { sboardTab = 'ffe'; renderSBoard(); }; }
  const after = seg; if (!after) return;
  if (sboardTab==='meetings'){ const card = root.querySelector('.card'); const acts = document.createElement('div'); acts.className = 'row'; acts.style.margin = '0 0 8px'; acts.innerHTML = `<span class="grow"></span><button class="btn sm primary" data-newmeeting>+ Meeting / transcript</button>`; card?.before(acts); acts.querySelector('[data-newmeeting]').onclick = () => newMeetingDialog(p); const ms = DB.studio.meetings.filter(m=>m.projectId===p.id && DB.studio.intake[m.id]); ms.forEach(m => { const d = document.createElement('div'); d.style.marginTop = '12px'; d.innerHTML = intakeHtml(m); root.append(d); wireIntake(d, m); }); }
  if (sboardTab==='client'){ const prs = promisesOf(p.id); const us = prs.filter(x=>x.dir==='us' && x.status==='open'), cl = prs.filter(x=>x.dir==='client' && x.status==='open'); const done = prs.filter(x=>x.status==='done'); const ex = p.tasks.filter(t=>t.exploration); const d = document.createElement('div'); d.innerHTML = `<div class="grid2" style="margin-top:10px"><div class="card"><h3>We owe the client <span class="small muted">${us.length}</span></h3>${us.map(x=>promiseRow(x)).join('')||'<div class="small muted">Nothing outstanding.</div>'}</div><div class="card"><h3>The client owes us <span class="small muted">${cl.length}</span></h3>${cl.map(x=>promiseRow(x)).join('')||'<div class="small muted">Nothing outstanding.</div>'}</div></div>
      <div class="card" style="margin-top:10px"><h3>Preference profile</h3><div class="small muted" style="margin-bottom:6px">Captured from meetings and the inspiration intake. Every room card carries it; the deck is checked against it before it issues.</div>${prefsHtml(p.id, true)}</div>
      <div class="card" style="margin-top:10px"><h3>Explorations <span class="small muted">— design studies with an hour cost the client can see</span></h3>${ex.map(t => `<div class="st-item"><span class="k">est. ${t.hours} hrs · ${money((t.hours||0)*(designEst(p)?.lines.find(l=>l.unit==='hr')?.rate||designRate()))} · ${esc(t.assignee||'')} · due ${fmt(t.end)}</span><div class="row" style="gap:8px"><b class="grow" style="font-weight:500">${esc(t.name)}</b><label class="small"><input type="checkbox" data-exok="${t.id}" ${t.clientApproved?'checked':''}> Client approved the hours</label></div></div>`).join('')||'<div class="small muted">None.</div>'}</div>${done.length?`<div class="card" style="margin-top:10px"><h3>Kept <span class="small muted">${done.length}</span></h3>${done.slice(0,8).map(x=>promiseRow(x)).join('')}</div>`:''}`; root.append(d);
    d.querySelectorAll('[data-prdone]').forEach(b => b.onclick = () => { const pr = DB.studio.promises.find(x=>x.id===b.dataset.prdone); pr.status = 'done'; pr.doneOn = today(); save(); renderSBoard(); }); d.querySelectorAll('[data-exok]').forEach(i => i.onchange = () => { const t = p.tasks.find(x=>x.id===i.dataset.exok); t.clientApproved = i.checked; save(); }); d.querySelectorAll('[data-pfrm]').forEach(i => i.onclick = () => { const [k, idx] = i.dataset.pfrm.split('|'); DB.studio.prefs[p.id][k].splice(+idx,1); save(); renderSBoard(); }); d.querySelectorAll('[data-pfadd]').forEach(i => i.addEventListener('keydown', e => { if (e.key!=='Enter' || !i.value.trim()) return; const P = DB.studio.prefs[p.id] = DB.studio.prefs[p.id]||{likes:[], dislikes:[], rules:[]}; P[i.dataset.pfadd].push(i.value.trim()); save(); renderSBoard(); })); }
  if (sboardTab==='ffe'){ const list = DB.studio.ffe.filter(f=>f.projectId===p.id); const d = document.createElement('div'); d.innerHTML = `<div class="row" style="margin:0 0 8px"><span class="small muted">Selections move proposed → client approved → ordered → delivered → installed. Approved selections go to the buy board as materials with their lead time; a room dimension change flags them.</span><span class="grow"></span><button class="btn sm primary" data-ffnew>+ Selection</button></div><div class="st-grid">${list.map(ffeCard).join('')||'<div class="empty">No selections yet.</div>'}</div>`; root.append(d);
    d.querySelector('[data-ffnew]').onclick = () => ffeDialog(p.id); d.querySelectorAll('[data-ffedit]').forEach(b => b.onclick = () => ffeDialog(p.id, b.dataset.ffedit)); d.querySelectorAll('[data-ffnext]').forEach(b => b.onclick = () => { const f = DB.studio.ffe.find(x=>x.id===b.dataset.ffnext); f.status = FFE_STATUS[FFE_STATUS.indexOf(f.status)+1]; if (f.status==='client approved') f.approvedOn = today(); save(); renderSBoard(); }); d.querySelectorAll('[data-ffbuy]').forEach(b => b.onclick = () => { const f = DB.studio.ffe.find(x=>x.id===b.dataset.ffbuy); ffeToPurchasing(f); save(); renderSBoard(); toast(`${f.item} is on the buy board`); }); }
  if (sboardTab==='rooms'){ const P = DB.studio.prefs[p.id]; const pcs = DB.studio.precedents.filter(x => x.projectId!==p.id); if (P || pcs.length){ const d = document.createElement('div'); d.className = 'grid2'; d.style.marginTop = '12px'; d.innerHTML = `${P?`<div class="card"><h3>Client profile</h3>${prefsHtml(p.id, false)}</div>`:''}${pcs.length?`<div class="card"><h3>Precedents <span class="small muted">— what we did last time</span></h3>${pcs.map(x => `<div class="st-item"><span class="k">${esc(DB.projects.find(q=>q.id===x.projectId)?.project.name||'')} · ${x.rooms.join(', ')}</span><b>${esc(x.title)}</b><span class="small muted">${esc(x.note)}</span></div>`).join('')}</div>`:''}`; root.append(d); } } };
/* deck check: the set can't issue with a preference conflict unresolved */
