/* ===================== STUDIO — UI pass: small confusions found by walking the screens as Sarah and as the client ===================== */
const isDesignProject = p => !!(p && designEst(p) && !p.tasks.some(t => (t.track||'build')==='build'));
/* 1. the board's tabs no longer repeat the sub-nav (Drawings, Filings live one level up) */
const renderSBoardBase_c = renderSBoard;
