renderSDay = function(){ renderSDayBase_c(); const root = $('#sday-body'); if (!root) return; const h = [...root.querySelectorAll('h3')].find(x => x.textContent.trim()==='Today'); if (h) h.textContent = 'Due this week'; root.querySelectorAll('.st-item .k').forEach(k => { k.textContent = k.textContent.replace(/^Decision · —$/, 'Decision · no date'); }); };
