/* 7. the top bar and the client's numbers were built for construction — a design-phase job says design things */
const renderBase_c = render;
render = function(){ renderBase_c(); if (!isDesignProject(S)) return; const ph = phaseHours(S); const cur = ph.find(x=>x.left>0 && x.used>0) || ph.find(x=>x.used>0) || ph[0]; const nextDue = S.tasks.filter(t => t.status!=='done' && t.end >= today()).sort((a,b)=>a.end.localeCompare(b.end))[0]; const F = DB.studio.filings.filter(f=>f.projectId===S.id); const inRev = F.filter(f=>f.status==='submitted');
  const sf = $('#st-finish'); if (sf){ sf.innerHTML = `<b>${cur ? esc(cur.line.item.split(' and ')[0].replace('Existing-conditions site survey','Survey')) : 'Design'}</b><span>current phase${cur?` · ${cur.used} of ${cur.est} hrs`:''}</span>`; sf.className = 'stat ' + (cur && cur.left < 0 ? 'warn' : 'good'); }
  const fl = $('#st-float'); if (fl){ fl.innerHTML = `<b>${nextDue ? fmtL(nextDue.end) : '—'}</b><span>${nextDue ? `next deliverable · ${esc(nextDue.name.slice(0,38))}${nextDue.name.length>38?'…':''}` : 'no deliverable dated'}${inRev.length?` · ${inRev.length} filing${inRev.length===1?'':'s'} in review`:''}</span>`; fl.className = 'stat'; }
  if (view==='client'){ const k = $('#cl-kpis'); if (k){ const decs = S.decisions.filter(d => d.owner==='Client' && d.status==='open'); const R = retainerLeft(S); const rooms = roomsOf(S.id); const unv = rooms.filter(r=>roomProv(r)===0).length; k.innerHTML = `<div class="kpi blue"><b>${cur ? esc(cur.line.item.split(' and ')[0].replace('Existing-conditions site survey','Survey')) : 'Design'}</b><span>where we are</span></div><div class="kpi ${decs.length?'warn':''}"><b>${decs.length}</b><span>decision${decs.length===1?'':'s'} we need from you</span></div><div class="kpi ${unv?'warn':'good'}"><b>${rooms.length-unv} / ${rooms.length}</b><span>rooms field-measured</span></div><div class="kpi"><b>${R ? R.hours+' hrs' : (ph.reduce((a,x)=>a+x.used,0)+' hrs')}</b><span>${R ? 'retainer remaining' : 'design hours to date'}</span></div>`; } } };
/* 8. the board's head was six boxes + a banner + two gate cards + tabs, all different shapes. Now: one "where it stands" bar and one "blocking" list. */
const renderSBoardBase_d = renderSBoard;
renderSBoard = function(){ renderSBoardBase_d(); const root = $('#sboard-body'); if (!root) return; const p = S; const strip = root.querySelector('.st-strip'); const note = root.querySelector('.note.warn'); const gates = root.querySelector('.st-gates'); if (!strip && !note && !gates) return;
  const ph = phaseHours(p); const R = retainerLeft(p); const totalEst = ph.reduce((a,x)=>a+x.est,0)||1; const rooms = roomsOf(p.id); const unv = rooms.filter(r=>roomProv(r)===0); const stale = sheetsOf(p.id).filter(s=>s.stale && s.status==='current'); const open = p.decisions.filter(d => d.status==='open' && d.gate); const td = today();
  const bar = ph.length ? `<div class="st-bar">${ph.map(x => `<div class="st-seg" title="${esc(x.line.item)}: ${x.used} of ${x.est} hrs"><i style="width:${Math.min(100, x.est ? x.used/x.est*100 : 0)}%" class="${x.left<0?'over':''}"></i></div>`).join('')}</div><div class="st-barl">${ph.map(x => `<div><span class="n">${esc(({'Existing-conditions site survey':'Survey','Schematic and conceptual design':'Schematic','Design development and material selection':'Design dev','Material and vendor pricing / quotations':'Pricing','Client meetings':'Meetings'})[x.line.item]||x.line.item.split(' and ')[0])}</span><b class="${x.left<0?'bad':''}">${x.used}</b><span class="muted">/${x.est}</span></div>`).join('')}</div>` : '<div class="small muted">No design proposal on this job yet.</div>';
  const blocks = [];
  if (unv.length) blocks.push({k:'Survey', t:`${unv.length} of ${rooms.length} rooms on listing dimensions`, s:'DD, set issue and fabrication orders wait for it', act:'<button class="btn sm primary" data-survey>Survey</button>', late:false});
  open.forEach(d => blocks.push({k:`Gate · ${d.gate}`, t:d.name, s:`${d.owner||''} · due ${fmt(d.due)}`, act:'', late: d.due && d.due < td}));
  if (stale.length) blocks.push({k:'Re-issue', t:`${stale.length} current sheet${stale.length===1?'':'s'} carry a changed dimension`, s:stale[0].staleWhy||'', act:'<button class="btn sm" data-goview="sdraw">Drawings</button>', late:true});
  const head = document.createElement('div'); head.className = 'st-head'; head.innerHTML = `<div class="card st-stand"><div class="row" style="margin-bottom:8px"><h3 style="margin:0">Where it stands</h3><span class="grow"></span>${R?`<span class="small ${R.hours<=R.replenishAt?'bad':'muted'}">Retainer <b>${R.hours} hrs</b> · ${money(R.dollars)}${R.hours<=R.replenishAt?' · replenish':''}</span>`:''}</div>${bar}</div>
    <div class="card st-block"><h3 style="margin:0 0 4px">Blocking <span class="small muted">${blocks.length||'nothing'}</span></h3>${blocks.map(b => `<div class="st-item ${b.late?'late':''}"><span class="k">${esc(b.k)}</span><div class="row" style="gap:8px;align-items:flex-start"><div class="grow"><b style="font-weight:500">${esc(b.t)}</b><span class="small muted" style="display:block">${esc(b.s)}</span></div>${b.act}</div></div>`).join('')||'<div class="small muted">Nothing is holding this project.</div>'}</div>`;
  (strip||note||gates).before(head); [strip, note, gates].forEach(el => el && el.remove());
  head.querySelector('[data-survey]')?.addEventListener('click', () => surveyDialog(p)); head.querySelector('[data-goview]')?.addEventListener('click', e => setView(e.target.dataset.goview)); };
/* 9. survey on a phone: one room at a time, Save & next */
surveyDialog = function(p, idx){ const rooms = roomsOf(p.id); if (!rooms.length){ toast('Add rooms first'); return; } idx = idx==null ? Math.max(0, rooms.findIndex(r => roomMissing(r).length)) : idx; const r = rooms[idx]; const todo = rooms.reduce((a,x)=>a+roomMissing(x).length,0); touch('survey', p.id, 'Survey checklist', p.id, 30);
  const mic = 'webkitSpeechRecognition' in window; const m = mbModal(`Survey · ${r.name} <span class="small muted">${idx+1} of ${rooms.length}</span>`, `<div class="row" style="gap:6px;flex-wrap:wrap;margin-bottom:8px">${rooms.map((x,i) => `<button class="btn sm ${i===idx?'primary':''}" data-sroom="${i}">${esc(x.name)}${roomMissing(x).length?'':' ✓'}</button>`).join('')}</div><div class="small muted" style="margin-bottom:8px">${todo} dimension${todo===1?'':'s'} still from the listing plan across the house. Type 14'-6", 14 6, or 174${mic?' — or tap Mic and say it':''}. Saved as field-measured by you, today.</div><div class="st-survey"><div class="st-sroom">${r.dims.map(d => `<div class="row st-srow"><span class="grow ${(PROV[d.src]?.rank??0)<1?'':'muted'}">${esc(d.label)}</span><span class="small muted">${(PROV[d.src]?.rank??0)<1?`listing ${fi(d.value)}`:`${PROV[d.src].short} ${fi(d.value)}`}</span><input data-sv="${r.id}|${d.id}" placeholder="measure" style="width:96px">${mic?`<button class="btn sm" data-mic="${r.id}|${d.id}">Mic</button>`:''}</div>`).join('')}</div></div>`, {submit: idx < rooms.length-1 ? 'Save & next room' : 'Save & finish', onSubmit:() => { let n = 0, ch = 0; m.querySelectorAll('[data-sv]').forEach(i => { const v = parseFI(i.value); if (v==null) return; const [rid, did] = i.dataset.sv.split('|'); const d = r.dims.find(x=>x.id===did); const rec = dimSet(r, d, v, 'field'); n++; if (rec) ch++; }); p.studioChecks = p.studioChecks||{}; if (!rooms.some(x=>roomMissing(x).length)) p.studioChecks.survey = true; save(); if (n) toast(`${r.name}: ${n} saved${ch?` · ${ch} change record${ch===1?'':'s'}`:''}`); if (idx < rooms.length-1){ setTimeout(() => surveyDialog(p, idx+1), 60); return; } render(); }});
  m.querySelectorAll('[data-sroom]').forEach(b => b.onclick = () => { mbCloseModal(); surveyDialog(p, +b.dataset.sroom); }); m.querySelector('#mbm-cancel').textContent = 'Close';
  m.querySelectorAll('[data-mic]').forEach(b => b.onclick = () => { const rec = new webkitSpeechRecognition(); rec.lang = 'en-US'; rec.onresult = ev => { const t = ev.results[0][0].transcript.toLowerCase().replace(/feet|foot/,"'").replace(/inches|inch/,'"').replace(/ and /,' '); m.querySelector(`[data-sv="${b.dataset.mic}"]`).value = t; }; rec.start(); }); };

/* ===================== ROLE WALK — small confusions found by opening every screen as every role, phone and desktop ===================== */
const STUDIO_VIEWS = ['sday','sboard','sdraw','sfile','studio'];
/* 1. Studio borrowed the current job silently, so Jobs came back on a different project. Studio keeps its own current project and gives the other one back. */
let studioPrev = null;
ensureStudioProject = function(){ if (!roomsOf(S.id).length && !designEst(S)){ const p = studioProjects().find(x => x.id===DB.studioCurrent) || studioProjects()[0]; if (p){ if (!studioPrev) studioPrev = S.id; setCurrent(p.id); } } if (roomsOf(S.id).length || designEst(S)) DB.studioCurrent = S.id; };
const renderBase_rw = render;
render = function(){ if (!STUDIO_VIEWS.includes(view) && studioPrev){ const back = studioPrev; studioPrev = null; if (DB.projects.some(p=>p.id===back)) setCurrent(back); } renderBase_rw(); };
/* 2. the clock card belongs to people who clock in; the brief sits under the button, not above it */
const renderTimeBase_rw = renderTime;
renderTime = function(){ renderTimeBase_rw(); const u = currentUser(); const emp = DB.employees.find(e => e.id===u?.employeeId); const card = $('#clock-card'); if (card && !emp && !['crew','driver','foreman'].includes(role())) card.style.display = 'none'; else if (card) card.style.display = ''; const v = $('#v-time'); const jv = v?.querySelector('#jv'); if (jv && card && ['crew','driver','foreman'].includes(role()) && jv.compareDocumentPosition(card) & Node.DOCUMENT_POSITION_FOLLOWING) card.after(jv); };
/* 3. Home: two buttons both said "Classic" */
const renderHomeBase_rw = renderHome;
renderHome = function(){ renderHomeBase_rw(); const b = $('#home-classic'); if (b) b.textContent = 'Dashboard view'; const seg = document.querySelector('#theme-seg [data-theme="classic"]'); if (seg) seg.textContent = 'Color'; };
