/* ===================== TODAY — this job or every job ===================== */
/* Today has always been one project. "All jobs" keeps the same page — look-ahead, needs attention, changes — and merges every active job into it, each item tagged with its job. Tapping an item opens it in its own job. */
let dashAll = (() => { try { return localStorage.getItem('dashAll')==='1'; } catch(e){ return false; } })();
const shortName = p => (p.project.name||'').replace(/ — design$/,'').replace(/\s+—.*$/,'').split(',')[0].slice(0, 22);
function dashAllRender(td){ const cur = S.id; const merged = {}; const atts = []; const K = {jobs:0, late:0, urgent:0, matsRisk:0, matsOpen:0, gatesRisk:0, gatesOpen:0}; const logs = [];
  DB.projects.forEach(p => { if (!p.tasks.length && !p.materials.length && !p.decisions.length) return; setCurrent(p.id); const {cpm, projEnd} = computeCPM(); const att = attention(); K.jobs++; const sc = scDate(cpm, projEnd); const delta = p.project.target ? signedWork(p.project.target, sc) : 0; if (delta > 0) K.late++; K.urgent += att.filter(a=>a.sev===3).length; K.matsOpen += p.materials.filter(m => m.status!=='on-site').length; K.matsRisk += p.materials.filter(m => matState(m).sev>=2).length; K.gatesOpen += p.inspections.filter(i => i.status!=='passed').length + p.decisions.filter(d=>d.status==='open').length; K.gatesRisk += p.inspections.filter(i => inspState(i).sev>=2).length + p.decisions.filter(d => decState(d).sev>=2).length;
    att.forEach(a => atts.push(Object.assign({}, a, {p}))); const days = []; let d = td; while (days.length < laDays){ const dow = parse(d).getDay(); if (dow !== 0 && dow !== 6) days.push(d); d = iso(addDays(d,1)); } laDayItems(days).forEach(x => { (merged[x.day] = merged[x.day]||[]).push(...x.items.map(it => Object.assign(it, {pid:p.id, n:`${shortName(p)} · ${it.n}`}))); });
    const since = new Date(Date.now() - 36*3600*1000).toISOString(); p.log.filter(l => l.ts && l.ts > since).forEach(l => logs.push(Object.assign({}, l, {p}))); });
  setCurrent(cur);
  const dayItems = Object.keys(merged).sort().map(day => ({day, items:merged[day]})); const days = []; let d = td; while (days.length < laDays){ const dow = parse(d).getDay(); if (dow !== 0 && dow !== 6) days.push(d); d = iso(addDays(d,1)); } days.forEach(day => { if (!merged[day]) dayItems.push({day, items:[]}); }); dayItems.sort((a,b)=>a.day.localeCompare(b.day));
  $('#kpis').innerHTML = `<div class="kpi ${K.late?'warn':'good'}"><b>${K.jobs - K.late}<span style="font-size:14px;color:var(--ink-3)"> / ${K.jobs}</span></b><span>projects on target</span></div><div class="kpi ${K.urgent?'warn':'good'}"><b>${K.urgent}</b><span>urgent items across all projects</span></div><div class="kpi ${K.matsRisk?'warn':''}"><b>${K.matsRisk}<span style="font-size:14px;color:var(--ink-3)"> / ${K.matsOpen}</span></b><span>materials at risk / not yet on site</span></div><div class="kpi ${K.gatesRisk?'warn':''}"><b>${K.gatesRisk}<span style="font-size:14px;color:var(--ink-3)"> / ${K.gatesOpen}</span></b><span>decisions &amp; inspections to act on / open</span></div>`;
  $('#la-range').textContent = `${fmtL(days[0])} – ${fmtL(days[days.length-1])} · all projects`; $('#lookahead').innerHTML = lookaheadHtml(dayItems, td);
  atts.sort((a,b) => (b.sev - a.sev) || (a.when||'').localeCompare(b.when||''));
  $('#attn-count').textContent = atts.length ? `${atts.filter(a=>a.sev===3).length} urgent · ${atts.length} total · ${K.jobs} jobs` : '';
  $('#attn').innerHTML = atts.length ? atts.map(a => `<div class="attn-item sev${a.sev}" data-go="${a.go.join(':')}" data-proj="${a.p.id}"><div class="when">${fmt(a.when)}</div><div><div class="t"><span class="muted">${esc(shortName(a.p))} · </span>${esc(a.t)}</div><div class="why">${esc(a.why)}</div><div class="act">${esc(a.act)}</div></div><div><span class="pill ${sevPill(a.sev)}">${a.sev===3?'Urgent':a.sev===2?'This week':'Watch'}</span></div></div>`).join('') : '<div class="empty">Nothing is slipping on any project.</div>';
  logs.sort((a,b) => b.ts.localeCompare(a.ts)); $('#chg-count').textContent = logs.length ? `${logs.length} change${logs.length>1?'s':''}` : ''; $('#changes').innerHTML = logs.length ? logs.slice(0,14).map(l => `<div class="chg"><span>${esc(l.t)}</span><span class="muted">${esc(shortName(l.p))} · </span>${esc(l.msg)}</div>`).join('') : '<div class="muted">No changes in the last day on any project.</div>';
  $('#ahead').innerHTML = '<p class="muted" style="margin:0">Pull-forward opportunities are per project — pick one to see them.</p>'; }
const renderDashBase_all = renderDash;
renderDash = function(att, cpm, projEnd){ renderDashBase_all(att, cpm, projEnd); if (dashAll) dashAllRender(today()); };
/* a tap on another job's item opens that job first */
document.addEventListener('click', e => { const el = e.target.closest('[data-proj][data-go]'); if (!el || !el.dataset.proj || el.dataset.proj===S.id) return; setCurrent(el.dataset.proj); }, true);
/* the page title says which */
const renderBase_dall = render;
render = function(){ renderBase_dall(); const sub = document.querySelector('#subnav [data-sub="dash"]'); if (sub) sub.firstChild.textContent = dashAll ? 'Today · all projects' : 'Today'; const ps = $('#pswitch'); if (ps){ ps.querySelector('option[value="__all"]')?.remove(); if (view==='dash'){ const o = document.createElement('option'); o.value = '__all'; o.textContent = 'All projects'; ps.prepend(o); if (dashAll) ps.value = '__all'; } } };

/* ===================== TODAY ON A PHONE — the same page, folded ===================== */
/* Phone rule: show today and tomorrow open, fold the rest of the days to one line each, never list more than a handful of anything without a "more" you chose to tap. */
function foldList(container, keep, label){ if (!container) return; const kids = [...container.children].filter(el => !el.classList.contains('fold-more') && !el.classList.contains('fold-btn')); if (kids.length <= keep + 1) return; const more = document.createElement('div'); more.className = 'fold-more'; more.hidden = true; kids.slice(keep).forEach(el => more.appendChild(el)); const btn = document.createElement('button'); btn.className = 'btn sm fold-btn'; btn.textContent = `Show ${kids.length - keep} more ${label}`; btn.onclick = () => { more.hidden = !more.hidden; btn.textContent = more.hidden ? `Show ${kids.length - keep} more ${label}` : 'Show less'; }; container.appendChild(more); container.appendChild(btn); }
function dashCompact(){ if (!isMobile()) return; const v = $('#v-dash'); if (!v) return;
  /* look-ahead: fold every day after tomorrow to a one-line header with a count; long days show four and a "more" */
  let dayIdx = 0; v.querySelectorAll('.la-day').forEach(day => { const items = [...day.querySelectorAll('.la-item')]; if (day.querySelector('.la-empty')) return; const n = items.length; const idx = dayIdx++; const hd = day.querySelector('.d'); if (idx >= 2){ day.classList.add('la-fold'); const cnt = document.createElement('span'); cnt.className = 'la-cnt'; cnt.textContent = `${n} item${n===1?'':'s'} ›`; hd.appendChild(cnt); hd.onclick = () => { day.classList.toggle('la-fold'); cnt.textContent = day.classList.contains('la-fold') ? `${n} item${n===1?'':'s'} ›` : 'hide'; }; }
    if (n > 5){ const more = document.createElement('div'); more.className = 'fold-more'; more.hidden = true; items.slice(4).forEach(el => more.appendChild(el)); const btn = document.createElement('button'); btn.className = 'btn sm fold-btn'; btn.textContent = `+ ${n-4} more`; btn.onclick = e => { e.stopPropagation(); more.hidden = !more.hidden; btn.textContent = more.hidden ? `+ ${n-4} more` : 'less'; }; day.appendChild(more); day.appendChild(btn); } });
  /* header chrome: no legend, no hint */ v.querySelectorAll('.la-legend').forEach(l => l.style.display = 'none');
  foldList($('#attn'), 6, 'items'); foldList($('#changes'), 4, 'changes'); }
const renderDashBase_cmp = renderDash;
renderDash = function(att, cpm, projEnd){ renderDashBase_cmp(att, cpm, projEnd); try { dashCompact(); } catch(e){ console.warn('compact', e); } };

/* ===================== DASHBOARD — a module of its own: widgets you arrange, per person, published per role ===================== */
/* Brief is the assistant's page; Dashboard is yours. Every widget is a view of the same data the reports use — and a saved search can become a widget, so anything you customize can land here. */
const homeRoot = () => $(view==='dashboard' ? '#dash-body' : '#home-body');
const DASH_GROUPS = {
  'Accounting':[['cashblock','Cash & 13 weeks'],['kpi','Key performance indicators'],['meter','KPI meter'],['trend','Trend graph'],['scorecard','KPI scorecard'],['chart','P&L chart'],['monthcompare','This month vs last'],['ar','Receivables aging'],['apdue','Bills coming due']],
  'Projects':[['jobcards','Project health'],['todayall','Today · all projects'],['decisions','Decisions & gates'],['deliveries','Deliveries this week'],['buyboard','Buy board']],
  'Studio':[['studio','Design hours vs proposal'],['filings','Filings'],['measure','Dimensions & drawings'],['promises','Promises']],
  'People':[['people','Who is on site · hours'],['needsme','Needs me'],['reminders','Reminders'],['analyst','Analyst brief']],
  'Your own':[['search','Saved search (list)'],['snapshot','Saved search (chart)'],['shortcuts','Shortcuts']] };
PORTLETS.jobcards = 'Projects'; Object.assign(PORTLETS, {ar:'Receivables aging', apdue:'Bills coming due', todayall:'Today · all projects', decisions:'Decisions & gates', deliveries:'Deliveries this week', studio:'Design hours vs proposal', filings:'Filings', measure:'Dimensions & drawings', promises:'Promises', people:'Who is on site · hours'});
const WIDE_TYPES = new Set(['chart','scorecard','trend','todayall','jobcards']);
const dashRow = (k, v, cls) => `<div class="h4kv"><span>${k}</span><b class="${cls||''}">${v}</b></div>`;
const dashList = (rows, empty) => rows.length ? `<div class="rem">${rows.join('')}</div>` : `<div class="muted small">${empty}</div>`;
const dashItem = (n, label, go, sev) => `<div class="rem-row ${sev||''}" data-remgo='${esc(JSON.stringify(go||{view:'home'}))}'><b>${n}</b><span>${label}</span></div>`;
function ptAR(){ const td = today(); const open = DB.clients.flatMap(c => clientFin(c).open.map(o => Object.assign(o, {c}))); const b = {cur:0, d30:0, d60:0, d90:0}; open.forEach(o => { if (o.age <= 0) b.cur += o.bal; else if (o.age <= 30) b.d30 += o.bal; else if (o.age <= 60) b.d60 += o.bal; else b.d90 += o.bal; }); const tot = open.reduce((a,o)=>a+o.bal,0); const top = open.filter(o=>o.age>0).sort((a,b)=>b.bal-a.bal).slice(0,4);
  return `<div class="dash-buckets">${[['Current',b.cur,''],['1–30',b.d30,'warn'],['31–60',b.d60,'warn'],['60+',b.d90,'bad']].map(([k,v,c]) => `<div class="${c}"><span>${k}</span><b>${money(v)}</b><i style="width:${tot?Math.round(v/tot*100):0}%"></i></div>`).join('')}</div>${dashRow('Outstanding', money(tot))}${top.length ? dashList(top.map(o => dashItem(money(o.bal), `${esc(o.c.name)} · ${esc(o.x.number)} · ${o.age}d overdue`, {view:'clients'}, o.age>30?'bad':'warn')), '') : '<div class="small muted" style="margin-top:6px">Nothing overdue.</div>'}`; }
function ptAPDue(){ const td = today(); const bills = DB.bills.filter(b => !billIsPaid(b) && !['void','rejected'].includes(b.status)); const bk = {over:0, w1:0, w2:0, later:0}; bills.forEach(b => { const d = b.due ? dayDiff(td, b.due) : 99; const t = billTotal(b); if (d < 0) bk.over += t; else if (d <= 7) bk.w1 += t; else if (d <= 14) bk.w2 += t; else bk.later += t; }); const tot = bills.reduce((a,b)=>a+billTotal(b),0); const soon = bills.filter(b => b.due && dayDiff(td, b.due) <= 7).sort((a,b)=>(a.due||'').localeCompare(b.due||'')).slice(0,5);
  return `<div class="dash-buckets">${[['Past due',bk.over,'bad'],['7 days',bk.w1,'warn'],['14 days',bk.w2,''],['Later',bk.later,'']].map(([k,v,c]) => `<div class="${c}"><span>${k}</span><b>${money(v)}</b><i style="width:${tot?Math.round(v/tot*100):0}%"></i></div>`).join('')}</div>${dashRow('Open payables', money(tot))}${dashList(soon.map(b => dashItem(money(billTotal(b)), `${esc(b.vendor)} · ${esc(b.number||'')} · due ${fmt(b.due)} · ${esc(b.status)}`, {view:'ap'}, dayDiff(td,b.due)<0?'bad':'')), 'Nothing due within 7 days.')}`; }
function ptTodayAll(){ const td = today(); const cur = S.id; const out = []; DB.projects.forEach(p => { if (!p.tasks.length && !p.materials.length) return; setCurrent(p.id); const items = laDayItems([td, iso(addDays(td,1))]); items.forEach(x => x.items.forEach(it => out.push({day:x.day, it, p}))); }); setCurrent(cur); const rows = out.slice(0, 12).map(({day, it, p}) => `<div class="rem-row ${it.k==='late'?'bad':it.k==='insp'?'info':''}" data-go="${it.go.join(':')}" data-proj="${p.id}"><b>${day===td?'Today':'Tmrw'}</b><span><span class="muted">${esc(shortName(p))} · ${esc(it.h)} · </span>${esc(it.n)}</span></div>`); return dashList(rows, 'Nothing scheduled today or tomorrow on any project.') + (out.length > 12 ? `<div class="small muted" style="margin-top:6px">+ ${out.length-12} more on Today · all projects</div>` : ''); }
function ptDecisions(){ const td = today(); const rows = DB.projects.flatMap(p => p.decisions.filter(d => d.status==='open').map(d => ({p, d, due:d.due||decDue(d)}))).sort((a,b)=>(a.due||'9').localeCompare(b.due||'9')).slice(0, 8); return dashList(rows.map(({p,d,due}) => dashItem(due ? fmt(due) : '—', `${esc(shortName(p))} · ${esc(d.name)}${d.gate?` <span class="pill warn">gate · ${esc(d.gate)}</span>`:''} · ${esc(d.owner||'')}`, {view:'dec', project:p.id}, due && due < td ? 'bad' : '')), 'No open decisions.'); }
function ptDeliveries(){ const td = today(); const rows = []; DB.pos.filter(po => ['issued','partial'].includes(po.status) && po.expected && dayDiff(td, po.expected) <= 7).forEach(po => rows.push({d:po.expected, label:`${esc(po.vendor)} · ${esc(po.number)} · ${esc(DB.projects.find(p=>p.id===po.projectId)?.project.name||'')}`, go:{view:'recv'}, sev: dayDiff(td, po.expected) < 0 ? 'bad':''})); DB.projects.forEach(p => p.materials.filter(m => m.eta && m.status!=='on-site' && dayDiff(td, m.eta) <= 7).forEach(m => rows.push({d:m.eta, label:`${esc(m.name)} · ${esc(shortName(p))}`, go:{view:'mat', project:p.id}, sev: dayDiff(td, m.eta) < 0 ? 'bad' : ''}))); rows.sort((a,b)=>a.d.localeCompare(b.d)); return dashList(rows.slice(0,8).map(r => dashItem(fmt(r.d), r.label, r.go, r.sev)), 'Nothing expected within 7 days.'); }
function ptStudio(){ const projs = studioProjects(); const u = currentUser(); const emp = DB.employees.find(e=>e.id===u?.employeeId); const mine = role()==='designer' && emp; const rows = projs.map(p => { const ph = phaseHours(p); const R = retainerLeft(p); const est = ph.reduce((a,x)=>a+x.est,0), used = ph.reduce((a,x)=>a+x.used,0); const cur = ph.find(x=>x.left>0 && x.used>0) || ph[0]; return {p, est, used, R, cur}; }); return `<table class="t dash-t"><thead><tr><th>Project</th><th>Phase</th><th class="money">Hours</th><th class="money">Retainer</th></tr></thead><tbody>${rows.map(r => `<tr data-remgo='${esc(JSON.stringify({view:'sboard', project:r.p.id}))}' style="cursor:pointer"><td><b>${esc(shortName(r.p))}</b></td><td>${r.cur?esc(phaseShort(r.cur.line.item)):'—'}</td><td class="money ${r.used>r.est?'bad':''}">${r.used} / ${r.est}</td><td class="money ${r.R&&r.R.hours<=20?'bad':''}">${r.R?r.R.hours+' hrs':'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No design projects.</td></tr>'}</tbody></table>`; }
function ptFilings(){ const td = today(); const rows = DB.studio.filings.filter(f => f.status!=='approved').map(f => ({f, p:DB.projects.find(p=>p.id===f.projectId)})).sort((a,b) => (a.f.status==='submitted'?0:1) - (b.f.status==='submitted'?0:1)); return dashList(rows.slice(0,8).map(({f,p}) => dashItem(f.submittedOn && !f.approvedOn ? `${dayDiff(f.submittedOn, td)}d` : '·', `${esc(shortName(p))} · ${esc(f.name)} · <span class="pill ${FILING_STATUS[f.status][1]}">${FILING_STATUS[f.status][0]}</span>${f.rounds>2?' · round '+f.rounds+' billable':''}`, {view:'sfile', project:p.id}, f.status==='objections'?'bad':'')), 'No filings in progress.'); }
function ptMeasure(){ const rows = []; studioProjects().forEach(p => { const rooms = roomsOf(p.id); const unv = rooms.filter(r=>roomProv(r)===0).length; const stale = sheetsOf(p.id).filter(s=>s.stale && s.status==='current').length; if (unv) rows.push(dashItem(unv, `rooms on listing dimensions · ${esc(shortName(p))}`, {view:'sboard', project:p.id}, 'warn')); if (stale) rows.push(dashItem(stale, `sheets carry a changed dimension · ${esc(shortName(p))}`, {view:'sdraw', project:p.id}, 'bad')); }); return dashList(rows, 'Every room measured, every sheet current.'); }
function ptPromises(){ const td = today(); const rows = DB.studio.promises.filter(x=>x.status==='open').sort((a,b)=>(a.due||'9').localeCompare(b.due||'9')).slice(0,8); return dashList(rows.map(x => dashItem(fmt(x.due), `${x.dir==='us'?'We owe':'Client owes'} · ${esc(x.owner||'')} · ${esc(x.text)} · ${esc(shortName(DB.projects.find(p=>p.id===x.projectId)||{project:{name:''}}))}`, {view:'sboard', project:x.projectId}, x.due && x.due < td ? 'bad' : '')), 'Nothing promised and open.'); }
function ptPeople(){ const td = today(); const open = DB.time.filter(t => t.status==='open' || (t.date===td && t.in && !t.out)); const mon = iso(addDays(td, -((parse(td).getDay()+6)%7))); const wk = {}; DB.time.filter(t => t.date >= mon && t.date <= td).forEach(t => { wk[t.empId] = (wk[t.empId]||0) + hoursOf(t); }); const sub = DB.time.filter(t=>t.status==='submitted').length; return `${dashRow('On site now', open.length ? open.map(t => esc(DB.employees.find(e=>e.id===t.empId)?.name||'')).join(', ') : 'nobody clocked in')}${dashRow('Time sheets to approve', sub, sub?'warn':'')}<div class="small muted" style="margin:8px 0 4px">Hours this week</div>${dashList(Object.entries(wk).sort((a,b)=>b[1]-a[1]).map(([id,h]) => dashItem(r2(h), `${esc(DB.employees.find(e=>e.id===id)?.name||id)} · ${esc(DB.employees.find(e=>e.id===id)?.role||'')}`, {view:'time'})), 'No hours logged this week.')}`; }
const renderPortletBase_dm = renderPortlet;
renderPortlet = function(p){ switch (p.type){ case 'ar': return ptAR(); case 'apdue': return ptAPDue(); case 'todayall': return ptTodayAll(); case 'decisions': return ptDecisions(); case 'deliveries': return ptDeliveries(); case 'studio': return ptStudio(); case 'filings': return ptFilings(); case 'measure': return ptMeasure(); case 'promises': return ptPromises(); case 'people': return ptPeople(); } return renderPortletBase_dm(p); };
/* defaults per role */
ROLE_HOME.owner = {layout:3, portlets:[{type:'needsme'}, {type:'cashblock'}, {type:'ar'}, {type:'jobcards', cfg:{w:2}}, {type:'apdue'}, {type:'monthcompare'}, {type:'studio'}, {type:'people'}, {type:'chart', cfg:{period:'6m', w:2}}, {type:'buyboard'}]};
ROLE_HOME.pm = {layout:3, portlets:[{type:'needsme'}, {type:'jobcards', cfg:{w:2}}, {type:'todayall', cfg:{w:2}}, {type:'decisions'}, {type:'deliveries'}, {type:'buyboard'}, {type:'kpi', cfg:{kpis:['backlog','committed','billsPending','hours','cosApproved'], range:'tm', cmp:'prev', hl:{}}}]};
ROLE_HOME.coord = {layout:3, portlets:[{type:'needsme'}, {type:'buyboard', cfg:{w:2}}, {type:'deliveries'}, {type:'search', cfg:{ds:'pos', group:'vendor', title:'Open POs by vendor'}}, {type:'people'}, {type:'apdue'}]};
ROLE_HOME.design_mgr = {layout:3, portlets:[{type:'studio', cfg:{w:2}}, {type:'promises'}, {type:'filings'}, {type:'measure'}, {type:'people'}, {type:'decisions', cfg:{w:2}}, {type:'reminders'}]};
ROLE_HOME.designer = {layout:2, portlets:[{type:'studio'}, {type:'promises'}, {type:'measure'}, {type:'decisions'}]};
/* per person, falling back to what the owner published for the role, then the role default */
homeDef = function(){ DB.dashboards = DB.dashboards||{}; const r = role(); const key = DB.deviceUser ? 'u:'+DB.deviceUser : r; if (!DB.dashboards[key]){ const base = (DB.published||{})[r] || DB.dashboards[r] || ROLE_HOME[r] || ROLE_HOME.pm; DB.dashboards[key] = JSON.parse(JSON.stringify(base)); DB.dashboards[key].portlets.forEach(p => { p.id = uid('pt'); p.cfg = p.cfg||{}; }); } return DB.dashboards[key]; };
/* the view */
NAV_GROUPS.splice(1, 0, {id:'dashboard', n:'Dashboard', views:['dashboard']});
NAV_LABELS.dashboard = 'Dashboard'; NAV_ICON.dashboard = '<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="5" rx="1.5"/><rect x="13" y="10" width="8" height="11" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/>';
const dashRoles = () => ['owner','pm','coord','design_mgr','designer'].forEach(r => { if (ROLE_VIEWS[r] && !ROLE_VIEWS[r].includes('dashboard')) ROLE_VIEWS[r].push('dashboard'); }); dashRoles(); const studioInitBase_dm = studioInit; studioInit = function(){ studioInitBase_dm(); dashRoles(); };
function renderDashboardView(){ const root = $('#dash-body'); if (!root) return; renderHomeBase_h4();
  const bar = root.querySelector('.home-bar'); if (bar){ const h2 = bar.querySelector('h2'); if (h2) h2.textContent = 'Dashboard'; const sub = bar.querySelector('.small.muted'); if (sub) sub.textContent = `${ROLE_NAMES[role()]||role()} · ${homeDef().portlets.length} widgets · yours on this device`; bar.querySelector('#home-brief')?.remove(); bar.querySelector('#theme-seg')?.remove(); const edit = bar.querySelector('#home-edit'); if (edit) edit.textContent = homeEdit ? 'Done' : 'Customize';
    /* grouped add menu */ const add = bar.querySelector('#home-add'); if (add){ add.innerHTML = `<option value="">Add widget…</option>` + Object.entries(DASH_GROUPS).map(([g, items]) => `<optgroup label="${g}">${items.map(([k,l]) => `<option value="${k}">${l}</option>`).join('')}</optgroup>`).join(''); } const reset = bar.querySelector('#home-reset'); if (reset) reset.textContent = 'Reset to default'; }
  /* widths */ const H = homeDef(); root.querySelectorAll('.portlet').forEach(el => { const p = H.portlets.find(x=>x.id===el.dataset.pt); if (!p) return; const w = p.cfg?.w || (WIDE_TYPES.has(p.type) ? 2 : 1); el.classList.remove('wide'); el.classList.add('w'+Math.min(w, H.layout||3)); if (homeEdit){ const hd = el.querySelector('.portlet-hd'); if (hd && !hd.querySelector('[data-ptw]')){ const b = document.createElement('button'); b.className = 'btn sm'; b.dataset.ptw = p.id; b.title = 'Width'; b.textContent = `${w}×`; b.onclick = () => { p.cfg = p.cfg||{}; p.cfg.w = (w % (H.layout||3)) + 1; save(); render(); }; hd.appendChild(b); } } });
  root.querySelectorAll('[data-remgo]').forEach(el => { const prev = el.onclick; el.onclick = () => { const go = JSON.parse(el.dataset.remgo); if (go.project) setCurrent(go.project); if (prev) return prev(); view = go.view; render(); window.scrollTo(0,0); }; }); }
const renderBase_dm = render;
render = function(){ renderBase_dm(); if (view==='dashboard') renderDashboardView(); const hc = $('#home-classic'); if (hc) hc.style.display = 'none'; };

/* ===================== DASHBOARD VIEWS — one dashboard, five lenses: Procurement · Projects · Financials · Studio · Billing & Accounting, plus your own ===================== */
/* Each view is a preset of the widgets that person would want first. Every view is still yours to customize; the preset is only the starting point, and Reset brings it back. */
const DASH_VIEWS = [['mine','My dashboard'],['procurement','Procurement'],['projects','Projects'],['financials','Financials'],['studio','Studio'],['billing','Billing & Accounting']];
let dashView = (() => { try { return localStorage.getItem('dashView') || 'mine'; } catch(e){ return 'mine'; } })();
const DASH_PRESETS = {
  procurement:{layout:3, portlets:[{type:'buyboard', cfg:{w:2}}, {type:'poapprove'}, {type:'deliveries'}, {type:'vendors'}, {type:'apdue'}, {type:'search', cfg:{ds:'pos', group:'vendor', title:'Open POs by vendor', w:2}}, {type:'measure'}]},
  projects:{layout:3, portlets:[{type:'jobcards', cfg:{w:2}}, {type:'todayall'}, {type:'decisions'}, {type:'deliveries'}, {type:'people'}, {type:'scorecard', cfg:{preset:'projects', cols:'m3', w:3}}]},
  financials:{layout:3, portlets:[{type:'cashblock'}, {type:'kpi', cfg:{kpis:['income','profit','netPct','availableCash','clientFunds','ar','arOver','ap','backlog'], range:'tm', cmp:'prev', hl:{netPct:{op:'<',v:15}, arOver:{op:'>',v:0}}, w:2}}, {type:'chart', cfg:{period:'6m', w:2}}, {type:'monthcompare'}, {type:'ar'}, {type:'apdue'}, {type:'meter', cfg:{k:'grossPct', range:'tq', min:0, max:60, low:25, high:40}}, {type:'trend', cfg:{months:6, w:3}}]},
  studio:{layout:3, portlets:[{type:'studio', cfg:{w:2}}, {type:'promises'}, {type:'filings'}, {type:'measure'}, {type:'decisions'}, {type:'people'}, {type:'reminders'}]},
  billing:{layout:3, portlets:[{type:'billing', cfg:{w:2}}, {type:'ar'}, {type:'unbilled'}, {type:'books'}, {type:'apdue'}, {type:'monthcompare'}, {type:'needsme'}]} };
Object.assign(PORTLETS, {poapprove:'Purchase orders to approve', vendors:'Vendor compliance', billing:'Billing status', unbilled:'Unbilled work', books:'Books & close'});
DASH_GROUPS['Accounting'].push(['books','Books & close']); DASH_GROUPS['Projects'].push(['poapprove','Purchase orders to approve'], ['vendors','Vendor compliance']); DASH_GROUPS['Accounting'].push(['billing','Billing status'], ['unbilled','Unbilled work']);
function ptPOApprove(){ const rows = DB.pos.filter(po => ['approval','draft'].includes(po.status)).sort((a,b)=>(a.status==='approval'?0:1)-(b.status==='approval'?0:1)); return dashList(rows.slice(0,8).map(po => dashItem(money(poTotal(po).total), `${esc(po.number)} · ${esc(po.vendor)} · ${esc(DB.projects.find(p=>p.id===po.projectId)?.project.name||'')} · <span class="pill ${po.status==='approval'?'warn':'neutral'}">${po.status==='approval'?'Awaiting approval':'Draft'}</span>`, {view:'po', po:po.id}, po.status==='approval'?'warn':'')), 'Nothing waiting for approval.'); }
function ptVendors(){ const rows = DB.vendors.map(v => ({v, f:vendorState(v)})).filter(x => x.f.length).sort((a,b) => b.f.filter(f=>f.lvl==='bad').length - a.f.filter(f=>f.lvl==='bad').length); return dashList(rows.slice(0,8).map(({v,f}) => dashItem(f.some(x=>x.lvl==='bad') ? 'Hold' : 'Watch', `${esc(v.name)} · ${f.map(x=>esc(x.m)).join(' · ')}`, {view:'vendors'}, f.some(x=>x.lvl==='bad')?'bad':'warn')), 'Every vendor is clean — insurance, W-9, license.'); }
function ptBilling(){ const td = today(); const inv = DB.clients.flatMap(c => c.invoices.map(i => ({c, i}))); const draft = inv.filter(x=>x.i.status==='draft'), sent = inv.filter(x=>x.i.status==='sent'); const open = DB.clients.flatMap(c => clientFin(c).open.map(o => Object.assign(o,{c}))); const over = open.filter(o=>o.age>0); const tot = a => money(a.reduce((s,x)=>s+docTotal(x.i).total,0)); const ready = DB.clients.flatMap(c => c.changeOrders.filter(x=>x.status==='approved').map(x=>({c,x})));
  return `<div class="dash-buckets"><div><span>Draft</span><b>${tot(draft)}</b><i style="width:${draft.length?40:0}%"></i></div><div><span>Sent · unpaid</span><b>${tot(sent)}</b><i style="width:${sent.length?60:0}%"></i></div><div class="${over.length?'bad':''}"><span>Overdue</span><b>${money(over.reduce((s,o)=>s+o.bal,0))}</b><i style="width:${over.length?100:0}%"></i></div><div class="warn"><span>COs to bill</span><b>${ready.length}</b><i style="width:${ready.length?50:0}%"></i></div></div>${dashList([...draft.slice(0,4).map(({c,i}) => dashItem(money(docTotal(i).total), `Draft · ${esc(i.number)} · ${esc(c.name)} · ${esc(i.title||'')}`, {view:'clients'}, '')), ...over.slice(0,4).map(o => dashItem(money(o.bal), `Overdue ${o.age}d · ${esc(o.x.number)} · ${esc(o.c.name)}`, {view:'clients'}, 'bad')), ...ready.slice(0,3).map(({c,x}) => dashItem(money(docTotal(x).total), `Approved CO to bill · ${esc(x.number)} · ${esc(c.name)}`, {view:'clients'}, 'warn'))], 'Nothing in draft, nothing overdue, no approved change orders waiting.')}`; }
function ptUnbilled(){ const rows = []; DB.clients.forEach(c => c.estimates.filter(e => e.template==='design' && ['converted','billed'].includes(e.status)).forEach(e => { const h = designHoursUnbilled(c, e); const hrs = r2(h.reduce((a,t)=>a+hoursOf(t),0)); if (hrs) rows.push(dashItem(`${hrs} hrs`, `Design hours banked, not billed · ${esc(c.name)} · ${esc(e.number)}`, {view:'clients'}, 'warn')); })); DB.projects.forEach(p => { const J = jobFin(p); if (J.earned > J.billed + 1) rows.push(dashItem(money(r2(J.earned - J.billed)), `Earned ahead of billing · ${esc(shortName(p))} · earned ${money(J.earned)} vs billed ${money(J.billed)}`, {view:'costs', project:p.id}, '')); }); return dashList(rows.slice(0,8), 'Everything earned is billed.'); }
function ptBooks(){ const uncat = DB.txns.filter(t => !t.cat || t.cat==='uncat' || t.status==='new').length; const props = proposals().length; const verify = DB.bills.filter(b => billIsPaid(b) && b.status!=='verified').length; const m = today().slice(0,7); const cl = closeChecklist(m); const open = cl.filter(x=>!x.ok); return `${dashRow('Bank transactions to categorize', uncat, uncat?'warn':'')}${dashRow('Matches to confirm', props, props?'warn':'')}${dashRow('Paid bills to verify', verify, verify?'warn':'')}<div class="small muted" style="margin:8px 0 4px">Close checklist · ${m}</div>${dashList(open.slice(0,6).map(x => dashItem(x.n, esc(x.label), x.go, 'warn')), 'The month is ready to close.')}`; }
const renderPortletBase_dv = renderPortlet;
renderPortlet = function(p){ switch (p.type){ case 'poapprove': return ptPOApprove(); case 'vendors': return ptVendors(); case 'billing': return ptBilling(); case 'unbilled': return ptUnbilled(); case 'books': return ptBooks(); } return renderPortletBase_dv(p); };
/* layouts are per person per view; "My dashboard" keeps the role default, the others start from their preset */
const homeDefBase_dv = homeDef;
homeDef = function(){ if (view!=='dashboard' || dashView==='mine') return homeDefBase_dv(); DB.dashboards = DB.dashboards||{}; const key = `u:${DB.deviceUser||'x'}:${dashView}`; if (!DB.dashboards[key]){ const base = DASH_PRESETS[dashView] || DASH_PRESETS.projects; DB.dashboards[key] = JSON.parse(JSON.stringify(base)); DB.dashboards[key].portlets.forEach(p => { p.id = uid('pt'); p.cfg = p.cfg||{}; }); } return DB.dashboards[key]; };
const renderDashboardViewBase_dv = renderDashboardView;
renderDashboardView = function(){ try { if (!localStorage.getItem('dashView')){ dashView = ({coord:'procurement', pm:'projects', designer:'studio', design_mgr:'studio'})[role()] || 'mine'; localStorage.setItem('dashView', dashView); } } catch(e){} renderDashboardViewBase_dv(); const root = $('#dash-body'); const bar = root?.querySelector('.home-bar'); if (!bar) return; const vs = DASH_VIEWS.filter(([k]) => k!=='studio' || ['owner','pm','design_mgr','designer'].includes(role()));
  const seg = document.createElement('div'); seg.className = 'seg sm dash-views'; seg.innerHTML = vs.map(([k,n]) => `<button class="${dashView===k?'on':''}" data-dv="${k}">${n}</button>`).join(''); bar.after(seg); seg.querySelectorAll('[data-dv]').forEach(b => b.onclick = () => { dashView = b.dataset.dv; try { localStorage.setItem('dashView', dashView); } catch(e){} homeEdit = false; render(); });
  const h2 = bar.querySelector('h2'); if (h2) h2.textContent = dashView==='mine' ? 'Dashboard' : `Dashboard · ${DASH_VIEWS.find(([k])=>k===dashView)[1]}`; const reset = bar.querySelector('#home-reset'); if (reset && dashView!=='mine'){ reset.textContent = 'Reset this view'; reset.onclick = () => { if (!confirm('Reset this view to its preset?')) return; delete DB.dashboards[`u:${DB.deviceUser||'x'}:${dashView}`]; save(); render(); }; } const pub = bar.querySelector('#home-publish'); if (pub && dashView!=='mine') pub.style.display = 'none'; };

/* ===================== DASHBOARD × PANEL — what the CEO, CFO, procurement, construction and studio leads said they need first ===================== */
/* Built from five panel memos (CEO, construction CFO, purchasing + project executive, studio principal). Signals first, lists second. Every widget is a formula over data the system already holds; thresholds are sized for a 15-person design-build. */
const spark = (vals, w=160, h=28, cls='') => { if (!vals.length) return ''; const mn = Math.min(0, ...vals), mx = Math.max(...vals, 1); const pts = vals.map((v,i) => `${(i/(vals.length-1||1)*w).toFixed(1)},${(h - (v-mn)/(mx-mn||1)*h).toFixed(1)}`).join(' '); const zero = h - (0-mn)/(mx-mn||1)*h; return `<svg class="spark ${cls}" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><line x1="0" y1="${zero}" x2="${w}" y2="${zero}" class="z"/><polyline points="${pts}"/></svg>`; };
const tile = (n, label, cls) => `<div class="dx-tile ${cls||''}"><b>${n}</b><span>${label}</span></div>`;
const bullet = (pct, target, cls) => `<div class="dx-bullet"><i style="width:${Math.max(0, Math.min(100, pct))}%" class="${cls||''}"></i><u style="left:${Math.max(0, Math.min(100, target))}%"></u></div>`;
const activeJobs = () => DB.projects.map(p => ({p, J:jobFin(p)})).filter(x => x.J.contract > 0);
const trail90 = () => [iso(addDays(today(), -90)), today()];
const monthlyRunRate = () => { const P = companyPL(trail90()); return r2(P.income/3); };
/* ---------- CEO / Financials ---------- */
function ptRunway(){ const B = companyBalance(); const F = cashForecast(); const lowW = F.weeks.reduce((m,w) => w.balance < m.balance ? w : m, F.weeks[0]); const out = F.weeks.reduce((a,w)=>a+w.outflow,0)/Math.max(1,F.weeks.length)/7; const days = out > 0 ? Math.max(0, Math.round(B.trulyOurs/out)) : null; const cls = (B.trulyOurs < 0 || F.low < 0) ? 'bad' : (days!=null && days < 60) ? 'warn' : 'ok';
  return `<div class="dx-tiles">${tile(money(B.trulyOurs), 'safe to spend · truly ours', cls)}${tile(days==null?'—':days+' d', 'days of runway at current burn', cls)}${tile(money(F.low), `13-week low · week of ${lowW?fmt(lowW.start):'—'}`, F.low<0?'bad':'')}</div>${spark(F.weeks.map(w=>w.balance), 300, 34, cls)}<div class="small muted">Truly ours = bank + undeposited − client funds held − cards − unpaid bills − payroll due. Red under 30 days or a negative low; amber under 60.</div>`; }
function ptWIP(){ const rows = activeJobs().map(({p,J}) => ({p, J, ou:r2(J.billed - J.earned)})).sort((a,b) => b.ou - a.ou); const tot = r2(rows.reduce((a,r)=>a+r.ou,0)); const B = companyBalance(); const worst = rows.filter(r => r.J.contract && Math.abs(r.ou) > 0.15*Math.max(1, r.J.contract - r.J.earned));
  return `<div class="dx-tiles">${tile(money(tot), tot>0?'billed ahead of work (a liability)':'earned ahead of billing (unbilled)', tot > B.trulyOurs && tot > 0 ? 'bad' : worst.length ? 'warn' : 'ok')}</div><table class="t dash-t"><thead><tr><th>Project</th><th class="money">Earned</th><th class="money">Billed</th><th class="money">Over / (under)</th></tr></thead><tbody>${rows.map(r => `<tr data-remgo='${esc(JSON.stringify({view:'costs', project:r.p.id}))}' style="cursor:pointer"><td><b>${esc(shortName(r.p))}</b></td><td class="money">${money(r.J.earned)}</td><td class="money">${money(r.J.billed)}</td><td class="money ${r.ou>0?'warn':r.ou<0?'bad':''}">${r.ou<0?'('+money(-r.ou)+')':money(r.ou)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No contracts.</td></tr>'}</tbody></table><div class="small muted">Over-billed = client money for work not done yet; under-billed = your money sitting in the job. Amber over 15% of remaining contract; red if the firm total exceeds truly-ours cash.</div>`; }
function ptMarginFc(){ const rows = activeJobs().map(({p,J}) => ({p, J, delta:r2(J.estGPPct - J.plannedGPPct), d$:r2(J.estGP - J.plannedGP)})).sort((a,b) => a.delta - b.delta); return `<div class="rem">${rows.map(r => `<div class="rem-row ${r.delta <= -6 || r.d$ <= -25000 ? 'bad' : r.delta <= -3 ? 'warn' : ''}" data-remgo='${esc(JSON.stringify({view:'costs', project:r.p.id}))}'><b>${r.J.estGPPct}%</b><span><b>${esc(shortName(r.p))}</b> · bid ${r.J.plannedGPPct}% → forecast ${r.J.estGPPct}% (${r.d$>=0?'+':''}${money(r.d$)}) · ${Math.round(r.J.pct*100)}% complete${bullet(r.J.estGPPct, r.J.plannedGPPct, r.delta < -3 ? 'bad' : 'ok')}</span></div>`).join('')||'<div class="muted small">No contracts.</div>'}</div><div class="small muted">Forecast at completion = cost to date + committed + estimate to complete. Amber 3 points under bid, red 6 or $25k.</div>`; }
function ptCOPipe(){ const td = today(); const all = DB.clients.flatMap(c => c.changeOrders.map(x => ({c, x, t:docTotal(x).total, age: x.date ? dayDiff(x.date, td) : 0}))); const st = k => all.filter(o => o.x.status===k); const unbilled = all.filter(o => o.x.status==='approved'); const sum = a => money(a.reduce((s,o)=>s+o.t,0)); const stale = st('sent').filter(o => o.age > 14 && o.t > 10000);
  return `<div class="dx-funnel">${[['draft','Identified / draft'],['sent','Sent · unsigned'],['approved','Approved · unbilled'],['billed','Billed']].map(([k,l]) => `<div class="${k==='sent'&&stale.length?'bad':k==='approved'&&unbilled.length?'warn':''}"><span>${l}</span><b>${sum(st(k))}</b><i>${st(k).length}</i></div>`).join('')}</div>${dashList([...st('sent').sort((a,b)=>b.t-a.t).slice(0,4).map(o => dashItem(money(o.t), `Unsigned ${o.age}d · ${esc(o.x.number)} · ${esc(o.c.name)} · ${esc(o.x.title||'')}`, {view:'clients'}, o.age>14?'bad':'warn')), ...unbilled.slice(0,3).map(o => dashItem(money(o.t), `Approved, not billed · ${esc(o.x.number)} · ${esc(o.c.name)}`, {view:'clients'}, 'warn'))], 'No change orders waiting on a signature or an invoice.')}<div class="small muted">Free work is where townhouse margin dies: red when a CO over $10k has been unsigned more than 14 days.</div>`; }
function ptBlockers(){ const cur = S.id; const rows = []; DB.projects.forEach(p => { if (!p.tasks.length) return; setCurrent(p.id); attention().filter(a => a.sev >= 2 && ['mat','dec','insp'].includes(a.go[0])).forEach(a => rows.push({p, a})); }); setCurrent(cur); rows.sort((a,b) => (b.a.sev - a.a.sev) || (a.a.when||'').localeCompare(b.a.when||'')); const lbl = {mat:'Material', dec:'Decision', insp:'Inspection'}; return dashList(rows.slice(0,8).map(({p,a}) => `<div class="rem-row ${a.sev===3?'bad':'warn'}" data-go="${a.go.join(':')}" data-proj="${p.id}"><b>${fmt(a.when)}</b><span><span class="muted">${esc(shortName(p))} · ${lbl[a.go[0]]} · </span>${esc(a.t)} <span class="muted">— ${esc(a.why)}</span></span></div>`), 'Nothing is holding a critical-path task.'); }
function ptBacklog(){ const jobs = activeJobs(); const backlog = r2(jobs.reduce((a,x)=>a+x.J.backlog,0)); const run = monthlyRunRate(); const months = run > 0 ? r2(backlog/run) : null; const td = today(); const out = DB.clients.flatMap(c => c.estimates.filter(e => e.status==='sent').map(e => ({c, e, age:dayDiff(e.date, td), t:docTotal(e).total}))); const stale = out.filter(o => o.age > 14); return `<div class="dx-tiles">${tile(months==null?'—':months+' mo', 'backlog coverage', months!=null && months < 3 ? 'bad' : months!=null && months < 5 ? 'warn' : 'ok')}${tile(money(backlog), 'remaining contract on signed work')}${tile(out.length, `proposals out · ${money(out.reduce((a,o)=>a+o.t,0))}`, stale.length?'warn':'')}</div>${dashList(stale.slice(0,4).map(o => dashItem(money(o.t), `${o.age}d without an answer · ${esc(o.e.number)} · ${esc(o.c.name)}`, {view:'clients'}, 'warn')), 'No proposal has waited more than two weeks.')}<div class="small muted">Backlog ÷ trailing-3-month revenue run-rate (${money(run)}/mo). Red under 3 months, amber under 5.</div>`; }
function ptRetainage(){ const jobs = activeJobs(); const rec = r2(jobs.reduce((a,x)=>a+(x.J.retHeld||0),0)); const pay = r2(jobs.reduce((a,x)=>a+(x.J.retWithheld||0),0)); const B = companyBalance(); const due = jobs.filter(x => x.J.pct >= 0.95 && (x.J.retHeld||0) > 0); return `<div class="dx-tiles">${tile(money(rec), 'retainage receivable · held by clients', rec > 0.5*Math.max(1,B.trulyOurs) ? 'warn' : '')}${tile(money(pay), 'retainage payable · held on subs')}</div>${dashList(due.map(x => dashItem(money(x.J.retHeld), `${esc(shortName(x.p))} · ${Math.round(x.J.pct*100)}% complete — release invoice?`, {view:'clients'}, 'warn')), 'No release-eligible retainage sitting.')}`; }
function ptDSO(){ const td = today(); const R = trail90(); const bill = DB.clients.flatMap(c=>c.invoices).filter(i => !['void','draft'].includes(i.status) && within(i.date, R)).reduce((a,i)=>a+docTotal(i).total,0); const ar = DB.clients.flatMap(c => clientFin(c).open).reduce((a,o)=>a+o.bal,0); const dso = bill ? Math.round(ar/(bill/90)) : null; const top = DB.clients.map(c => ({c, over:clientFin(c).open.filter(o=>o.age>0).reduce((a,o)=>a+o.bal,0)})).filter(x=>x.over>0).sort((a,b)=>b.over-a.over).slice(0,3); return `<div class="dx-tiles">${tile(dso==null?'—':dso+' d', 'DSO · days sales outstanding', dso>45?'bad':dso>30?'warn':'ok')}${tile(money(ar), 'receivables open')}</div>${dashList(top.map(x => dashItem(money(x.over), `${esc(x.c.name)} · overdue`, {view:'clients'}, 'bad')), 'Nothing overdue.')}<div class="small muted">Progress draws on 30-day terms should turn faster than 30 days. Amber over 30, red over 45.</div>`; }
function ptCashGap(){ const R = trail90(); const keep = DB.company.basis; DB.company.basis = 'accrual'; const A = companyPL(R); DB.company.basis = 'cash'; const C = companyPL(R); DB.company.basis = keep; const gap = r2(A.net - C.net); const pct = A.income ? Math.round(Math.abs(gap)/A.income*100) : 0; return `<div class="dx-tiles">${tile(money(A.net), 'accrual net · trailing 3 mo')}${tile(money(C.net), 'cash net · trailing 3 mo')}${tile((gap>=0?'+':'')+money(gap), 'gap · accrual − cash', pct > 10 ? 'warn' : '')}</div><div class="small muted">Accrual is what you earned; cash is what actually moved. A gap over 10% of revenue means one of them is lying to you — usually deposits.</div>`; }
function ptOverhead(){ const R = ohCurrent(); const m = R.months||[]; return `<div class="dx-tiles">${tile(`${Math.round((R.design?.rate||0)*100)}%`, 'design overhead rate · trailing 3 mo')}${tile(`${Math.round((R.construction?.rate||0)*100)}%`, 'construction overhead rate')}${tile(money(R.mtd?.pool?.total||0), 'overhead this month to date')}</div>${spark(m.map(x=>x.pool||0), 300, 30)}<div class="small muted">${esc(R.basis||'')}. The rate is what every job hour must carry; a rising pool with flat hours is the slow bleed.</div>`; }
function ptIntercompany(){ const rows = icUnbilled(); const tot = r2(rows.reduce((a,o)=>a+o.amount,0)); return `<div class="dx-tiles">${tile(money(tot), 'subsidiary hours not yet billed to the GC', tot ? 'warn' : 'ok')}</div>${dashList(rows.slice(0,5).map(o => dashItem(money(o.amount), `${esc(o.entity?.name||o.ent)} → ${esc(shortName(o.p))} · ${o.hours} hrs`, {view:'reports', tab:'financials'}, 'warn')), 'Intercompany is settled.')}`; }
/* ---------- Billing & Accounting ---------- */
function ptBillable(){ const rows = []; activeJobs().forEach(({p,J}) => { const under = r2(J.earned - J.billed); if (under > 500) rows.push({n:under, l:`Earned, not yet billed · ${esc(shortName(p))}`, go:{view:'clients'}, sev:'warn'}); }); DB.clients.forEach(c => { c.changeOrders.filter(x=>x.status==='approved').forEach(x => rows.push({n:docTotal(x).total, l:`Approved CO · ${esc(x.number)} · ${esc(c.name)}`, go:{view:'clients'}, sev:'warn'})); c.estimates.filter(e => e.template==='design' && ['converted','billed'].includes(e.status)).forEach(e => { const h = designHoursUnbilled(c, e); const hrs = r2(h.reduce((a,t)=>a+hoursOf(t),0)); const rate = +(e.lines.find(l=>l.unit==='hr')?.rate||designRate()); if (hrs) rows.push({n:r2(hrs*rate), l:`${hrs} design hrs banked · ${esc(c.name)}`, go:{view:'clients'}, sev:''}); }); }); DB.studio.filings.forEach(f => { const p = DB.projects.find(x=>x.id===f.projectId); const due = (f.status!=='not-started' && !f.billed.start) ? .5 : (['submitted','objections','approved'].includes(f.status) && !f.billed.submit) ? .25 : (f.status==='approved' && !f.billed.approve) ? .25 : 0; if (due) rows.push({n:r2(f.fee*due), l:`Filing milestone reached · ${esc(f.name)} · ${esc(shortName(p))}`, go:{view:'sfile', project:p.id}, sev:'warn'}); }); rows.sort((a,b)=>b.n-a.n); const tot = r2(rows.reduce((a,r)=>a+r.n,0)); const run = monthlyRunRate(); return `<div class="dx-tiles">${tile(money(tot), 'billable now', run && tot > 0.1*run ? 'bad' : run && tot > 0.05*run ? 'warn' : 'ok')}</div>${dashList(rows.slice(0,8).map(r => dashItem(money(r.n), r.l, r.go, r.sev)), 'Everything earned is on an invoice.')}<div class="small muted">Earned-not-billed + approved COs + banked design hours + filing milestones. Amber over 5% of monthly revenue, red over 10%.</div>`; }
function ptClientFunds(){ const by = {}; clientFundsLedger().forEach(r => { const k = r.p ? r.p.id : 'x'; const o = by[k] = by[k]||{p:r.p, held:0, toBuy:0, floated:0}; o.held += r.reserved||0; o.toBuy += r.remainingToBuy||0; o.floated += r.floated||0; }); const rows = Object.values(by).filter(o=>o.p).sort((a,b)=>b.held-a.held); const tot = r2(rows.reduce((a,o)=>a+o.held,0)); const fl = r2(rows.reduce((a,o)=>a+o.floated,0)); return `<div class="dx-tiles">${tile(money(tot), 'client purchase funds held')}${tile(money(fl), 'floated · our cash covering client purchases', fl>0?'bad':'ok')}</div><table class="t dash-t"><thead><tr><th>Project</th><th class="money">Held</th><th class="money">Still to buy</th><th class="money">Floated</th></tr></thead><tbody>${rows.map(o => `<tr data-remgo='${esc(JSON.stringify({view:'reports', tab:'funds'}))}' style="cursor:pointer"><td><b>${esc(shortName(o.p))}</b></td><td class="money">${money(o.held)}</td><td class="money">${money(o.toBuy)}</td><td class="money ${o.floated>0?'bad':''}">${o.floated?money(o.floated):'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No client funds held.</td></tr>'}</tbody></table><div class="small muted">Must tie to the cash forecast's "client funds". Red the moment we have spent more of a client's money than they gave us.</div>`; }
function ptInvPipe(){ const td = today(); const inv = DB.clients.flatMap(c => c.invoices.map(i => ({c, i, t:docTotal(i).total, age:i.date?dayDiff(i.date, td):0}))); const draft = inv.filter(x=>x.i.status==='draft'); const open = DB.clients.flatMap(c => clientFin(c).open.map(o => Object.assign(o,{c}))); const b = k => open.filter(o => k==='due7' ? (o.age<=0 && o.age>=-7) : k==='b15' ? (o.age>0&&o.age<=15) : k==='b30' ? (o.age>15&&o.age<=30) : k==='b60' ? (o.age>30&&o.age<=60) : o.age>60); const sum = a => a.reduce((s,x)=>s+(x.bal??x.t),0); return `<div class="dx-funnel six">${[['Draft',draft,draft.some(x=>x.age>5)?'warn':''],['Due ≤7d',b('due7'),''],['1–15',b('b15'),'warn'],['16–30',b('b30'),'warn'],['31–60',b('b60'),'bad'],['60+',b('b90'),'bad']].map(([l,a,c]) => `<div class="${a.length?c:''}"><span>${l}</span><b>${money(sum(a))}</b><i>${a.length}</i></div>`).join('')}</div>${dashList(draft.filter(x=>x.age>5).slice(0,4).map(x => dashItem(money(x.t), `Draft ${x.age}d · ${esc(x.i.number)} · ${esc(x.c.name)}`, {view:'clients'}, 'warn')), 'No draft has been sitting more than 5 days.')}`; }
function ptRetReg(){ const rows = activeJobs().filter(x => (x.J.retHeld||0) > 0 || (x.J.retWithheld||0) > 0).map(x => ({x, ready: x.J.pct >= 0.95 && x.p.inspections.every(i => i.status==='passed') && !x.p.issues.some(i => i.status!=='closed')})); return `<table class="t dash-t"><thead><tr><th>Project</th><th class="money">Held by client</th><th class="money">Held on subs</th><th>Release</th></tr></thead><tbody>${rows.map(({x,ready}) => `<tr><td><b>${esc(shortName(x.p))}</b></td><td class="money">${money(x.J.retHeld||0)}</td><td class="money">${money(x.J.retWithheld||0)}</td><td>${ready?'<span class="pill warn">Eligible — invoice it</span>':`<span class="small muted">${Math.round(x.J.pct*100)}% · ${x.p.inspections.filter(i=>i.status!=='passed').length} inspections open</span>`}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No retainage in play.</td></tr>'}</tbody></table>`; }
function ptAPDPO(){ const td = today(); const R = trail90(); const cost = companyPL(R).cogsT||0; const ap = DB.bills.filter(b => !billIsPaid(b) && !['void','rejected'].includes(b.status)); const apT = ap.reduce((a,b)=>a+billTotal(b),0); const dpo = cost ? Math.round(apT/(cost/90)) : null; const exposure = ap.filter(b => b.projectId && DB.clients.some(c => clientFin(c).open.some(o => o.age > 0 && o.x.projectId===b.projectId))); const nc = ap.filter(b => { const v = DB.vendors.find(x=>x.name===b.vendor); return v && vendorState(v).some(f=>f.lvl==='bad'); }); return `<div class="dx-tiles">${tile(dpo==null?'—':dpo+' d', 'DPO · days payables outstanding', dpo>40?'warn':'')}${tile(money(exposure.reduce((a,b)=>a+billTotal(b),0)), 'sub bills on jobs where the client is overdue', exposure.length?'warn':'ok')}${tile(nc.length, 'bills queued to non-compliant vendors', nc.length?'bad':'ok')}</div>${ptAPDue()}`; }
function ptCodeVar(){ const jobs = activeJobs(); const codes = {}; jobs.forEach(({J}) => (J.byCode||[]).forEach(r => { codes[r.code] = (codes[r.code]||0) + (r.budget||0); })); const top = Object.entries(codes).sort((a,b)=>b[1]-a[1]).slice(0,7).map(x=>x[0]); const name = c => (typeof COST_CODES!=='undefined' && COST_CODES.find(x=>x.code===c)?.name) || c; return `<div class="tw"><table class="t dash-t dx-heat"><thead><tr><th>Project</th>${top.map(c => `<th title="${esc(name(c))}">${c}</th>`).join('')}</tr></thead><tbody>${jobs.map(({p,J}) => `<tr><td><b>${esc(shortName(p))}</b></td>${top.map(c => { const r = (J.byCode||[]).find(x=>x.code===c); if (!r || !r.budget) return '<td class="muted">·</td>'; const fc = (r.actual||0) + (r.committed||0); const v = Math.round((fc - r.budget)/r.budget*100); return `<td class="${v>10?'bad':v>0?'warn':'ok'}" title="${esc(name(c))}: budget ${money(r.budget)} · forecast ${money(fc)}">${v>0?'+':''}${v}%</td>`; }).join('')}</tr>`).join('')}</tbody></table></div><div class="small muted">Forecast (actual + committed) vs budget by cost code. Red over +10%.</div>`; }
/* ---------- Procurement ---------- */
function ptLongLead(){ const td = today(); const cur = S.id; const rows = []; DB.projects.forEach(p => { if (!p.materials.length) return; setCurrent(p.id); p.materials.filter(m => m.status!=='on-site').forEach(m => { const {needBy, orderBy} = matDates(m); if (!needBy) return; const ordered = ['ordered','shipped'].includes(m.status); const arrive = ordered ? (m.eta || needBy) : iso(addDays(td, +(m.lead||0))); const fl = dayDiff(arrive, needBy); rows.push({p, m, needBy, orderBy, fl, ordered}); }); }); setCurrent(cur); rows.sort((a,b)=>a.fl-b.fl); const neg = rows.filter(r=>r.fl<0).length; return `<div class="dx-tiles">${tile(neg, 'items with negative float', neg?'bad':'ok')}${tile(rows.filter(r=>r.fl>=0&&r.fl<10).length, 'under 10 working days of float', rows.some(r=>r.fl>=0&&r.fl<10)?'warn':'')}</div>${dashList(rows.slice(0,8).map(r => `<div class="rem-row ${r.fl<0?'bad':r.fl<10?'warn':''}" data-go="mat:${r.m.id}" data-proj="${r.p.id}"><b>${r.fl}d</b><span><span class="muted">${esc(shortName(r.p))} · </span>${esc(r.m.name)} <span class="muted">· ${r.ordered?`ETA ${fmt(r.m.eta||'')}`:`not ordered · ${r.m.lead||0}d lead`} · need ${fmt(r.needBy)}${r.m.vendor?` · ${esc(r.m.vendor)}`:''}</span></span></div>`), 'Every material has float.')}<div class="small muted">Float = need-by − (ETA if ordered, else today + lead time). Landmark windows and millwork live here.</div>`; }
function ptUnpriced(){ const by = {}; clientFundsLedger().forEach(r => { if (!r.p || r.kind==='labor') return; const f = lineFin(r.key); if (!f) return; if (!f.committed && !f.actual){ const o = by[r.p.id] = by[r.p.id]||{p:r.p, unpriced:0, budget:0}; o.unpriced += f.budget||0; } const o2 = by[r.p.id] = by[r.p.id]||{p:r.p, unpriced:0, budget:0}; o2.budget += f.budget||0; }); const rows = Object.values(by).map(o => Object.assign(o, {J:jobFin(o.p), pct: o.budget ? Math.round(o.unpriced/o.budget*100) : 0})).sort((a,b)=>b.unpriced-a.unpriced); const tot = r2(rows.reduce((a,o)=>a+o.unpriced,0)); return `<div class="dx-tiles">${tile(money(tot), 'budget with no PO, no bill, no cost yet', rows.some(o => o.J.pct > .3 && o.pct > 25) ? 'bad' : rows.some(o=>o.pct>15)?'warn':'ok')}</div>${dashList(rows.slice(0,6).map(o => dashItem(money(o.unpriced), `${esc(shortName(o.p))} · ${o.pct}% of budget unpriced · ${Math.round(o.J.pct*100)}% complete`, {view:'costs', project:o.p.id}, o.J.pct > .3 && o.pct > 25 ? 'bad' : o.pct > 15 ? 'warn' : '')), 'Every budget line is priced.')}<div class="small muted">Allowances that never got priced are found at month four. Red over 25% unpriced on a job past 30% complete.</div>`; }
function ptBuyout(){ const rows = activeJobs().map(({p,J}) => ({p, J, cov: J.budget ? Math.round((J.actual + J.committed)/J.budget*100) : 0, done: Math.round(J.pct*100)})); return `<div class="rem">${rows.map(r => `<div class="rem-row ${r.cov < r.done - 20 ? 'bad' : r.cov < r.done - 10 ? 'warn' : ''}" data-remgo='${esc(JSON.stringify({view:'costs', project:r.p.id}))}'><b>${r.cov}%</b><span><b>${esc(shortName(r.p))}</b> · ${r.cov}% of budget committed vs ${r.done}% complete${bullet(r.cov, r.done, r.cov < r.done - 10 ? 'bad' : 'ok')}</span></div>`).join('')||'<div class="muted small">No contracts.</div>'}</div><div class="small muted">Committed = POs + bills + labor. Coverage should lead completion; red when it trails by 20 points.</div>`; }
function ptPOVar(){ const rows = DB.pos.filter(po => !['draft','approval'].includes(po.status)).map(po => ({po, t:poTotal(po).total, b:poBilled(po)})).map(x => Object.assign(x, {v:r2(x.b - x.t)})).filter(x => x.v > 0).sort((a,b)=>b.v-a.v); const noPO = DB.bills.filter(b => !b.poId && b.projectId && !['void','rejected'].includes(b.status)); const noT = noPO.reduce((a,b)=>a+billTotal(b),0); return `<div class="dx-tiles">${tile(money(rows.reduce((a,x)=>a+x.v,0)), 'billed above PO', rows.some(x=>x.v>2500)?'bad':rows.length?'warn':'ok')}${tile(money(noT), `bills with no PO · ${noPO.length}`, noPO.length?'warn':'ok')}</div>${dashList([...rows.slice(0,4).map(x => dashItem('+'+money(x.v), `${esc(x.po.number)} · ${esc(x.po.vendor)} · PO ${money(x.t)}, billed ${money(x.b)}`, {view:'po', po:x.po.id}, x.v>2500?'bad':'warn')), ...noPO.slice(0,3).map(b => dashItem(money(billTotal(b)), `No PO · ${esc(b.vendor)} · ${esc(b.number||'')}`, {view:'ap'}, 'warn'))], 'Every bill matches its order.')}`; }
function ptOrderBy14(){ const td = today(); const cur = S.id; const rows = []; DB.projects.forEach(p => { if (!p.materials.length) return; setCurrent(p.id); p.materials.filter(m => !['ordered','shipped','on-site'].includes(m.status)).forEach(m => { const {orderBy} = matDates(m); if (!orderBy) return; const d = dayDiff(td, orderBy); if (d > 14) return; const blocks = []; const dec = p.decisions.find(x => x.status==='open' && x.kind==='mat' && x.ref===m.id); if (dec) blocks.push('decision: '+dec.name); if (m.ffeId){ const f = DB.studio.ffe.find(x=>x.id===m.ffeId); if (f && f.status==='proposed') blocks.push('selection not approved'); } if (m.roomId && DB.studio.sheets.some(s => s.projectId===p.id && s.rooms.includes(m.roomId) && s.stale && s.status==='current')) blocks.push('drawing stale'); if (!m.vendor) blocks.push('no vendor'); rows.push({p, m, d, blocks}); }); }); setCurrent(cur); rows.sort((a,b)=>a.d-b.d); return dashList(rows.slice(0,8).map(r => `<div class="rem-row ${r.d<=5 && r.blocks.length ? 'bad' : r.blocks.length ? 'warn' : ''}" data-go="mat:${r.m.id}" data-proj="${r.p.id}"><b>${r.d<0?'late':r.d+'d'}</b><span><span class="muted">${esc(shortName(r.p))} · </span>${esc(r.m.name)}${r.blocks.length?` <span class="bad">— blocked by ${esc(r.blocks.join(', '))}</span>`:''}</span></div>`), 'Nothing to order in the next 14 days.'); }
function ptVendorsActive(){ const open = new Set(DB.pos.filter(po => ['issued','partial','approval'].includes(po.status)).map(po => po.vendor)); const rows = DB.vendors.filter(v => open.has(v.name)).map(v => ({v, f:vendorState(v)})).filter(x => x.f.length); return dashList(rows.map(({v,f}) => dashItem(f.some(x=>x.lvl==='bad')?'Hold':'Watch', `${esc(v.name)} · ${f.map(x=>esc(x.m)).join(' · ')}`, {view:'vendors'}, f.some(x=>x.lvl==='bad')?'bad':'warn')), `Every vendor with an open order is clean (${open.size} active).`); }
/* ---------- Projects ---------- */
function ptSchedVar(){ const cur = S.id; const rows = DB.projects.filter(p => p.tasks.length).map(p => { setCurrent(p.id); const h = projectHealth(p); const att = attention().filter(a => a.sev===3); const drv = att[0]; return {p, h, drv}; }); setCurrent(cur); rows.sort((a,b) => b.h.late - a.h.late); return `<table class="t dash-t"><thead><tr><th>Project</th><th class="money">Variance</th><th>Finish</th><th>Driver</th></tr></thead><tbody>${rows.map(r => `<tr data-remgo='${esc(JSON.stringify({view:'dash', project:r.p.id}))}' style="cursor:pointer"><td><b>${esc(shortName(r.p))}</b></td><td class="money ${r.h.late>10?'bad':r.h.late>=5?'warn':r.h.late>0?'':'ok'}">${r.h.late>0?'+'+r.h.late+'d':r.h.late<0?r.h.late+'d':'on'}</td><td>${fmt(r.h.sc)}</td><td class="small">${r.drv ? `${esc(r.drv.t)} <span class="muted">— ${esc(r.drv.why)}</span>` : '<span class="muted">nothing urgent</span>'}</td></tr>`).join('')}</tbody></table><div class="small muted">Forecast finish from the task network vs target; driver = the urgent item on the critical path. Amber 5–10 days, red over 10.</div>`; }
function ptEVTriple(){ const rows = activeJobs().map(({p,J}) => ({p, work:Math.round(J.pct*100), billed: J.contract ? Math.round(J.billed/J.contract*100) : 0, cost: J.eac ? Math.round(J.actual/J.eac*100) : 0})); return `<div class="dx-ev">${rows.map(r => `<div data-remgo='${esc(JSON.stringify({view:'costs', project:r.p.id}))}' class="${r.cost > r.work + 8 || r.billed < r.work - 10 ? 'bad' : r.cost > r.work + 4 || r.billed < r.work - 5 ? 'warn' : ''}"><b>${esc(shortName(r.p))}</b>${[['Work',r.work,'w'],['Billed',r.billed,'b'],['Cost',r.cost,'c']].map(([l,v,k]) => `<div class="ev"><span>${l}</span><div class="bar"><i class="${k}" style="width:${Math.min(100,v)}%"></i></div><em>${v}%</em></div>`).join('')}</div>`).join('')||'<div class="muted small">No contracts.</div>'}</div><div class="small muted">Cost ahead of work by 8 points = a hidden overrun; billed behind work by 10 = your money in the job.</div>`; }
function ptInspections(){ const td = today(); const rows = []; let passed = 0, total = 0; DB.projects.forEach(p => { p.inspections.forEach(i => { if (i.date && dayDiff(i.date, td) <= 90 && dayDiff(i.date, td) >= 0 && ['passed','failed'].includes(i.status)){ total++; if (i.status==='passed') passed++; } if (i.status!=='passed' && i.date && dayDiff(td, i.date) <= 14) rows.push({p, i, d:dayDiff(td, i.date)}); if (i.status==='failed' && !i.reinspect) rows.push({p, i, d:-99}); }); p.permits.forEach(pm => { if (pm.status==='active' && pm.expires && dayDiff(td, pm.expires) <= 30) rows.push({p, pm, d:dayDiff(td, pm.expires)}); }); }); rows.sort((a,b)=>a.d-b.d); const rate = total ? Math.round(passed/total*100) : null; return `<div class="dx-tiles">${tile(rate==null?'—':rate+'%', `inspection pass rate · 90 days (${total})`, rate!=null && rate < 80 ? 'bad' : rate!=null && rate < 90 ? 'warn' : 'ok')}</div>${dashList(rows.slice(0,8).map(r => r.pm ? dashItem(fmt(r.pm.expires), `Permit expires · ${esc(r.pm.agency)} ${esc(r.pm.name)} · ${esc(shortName(r.p))}`, {view:'insp', project:r.p.id}, r.d<=7?'bad':'warn') : dashItem(r.d===-99?'Failed':fmt(r.i.date), `${esc(r.i.agency)} · ${esc(r.i.name)} · ${esc(shortName(r.p))}${r.d===-99?' — no re-inspection scheduled':''}`, {view:'insp', project:r.p.id}, r.d===-99?'bad':'')), 'No inspections in 14 days, no permits expiring.')}`; }
function ptCrew(){ const td = today(); const mon = iso(addDays(td, -((parse(td).getDay()+6)%7))); const rows = activeJobs().map(({p,J}) => { const wk = DB.time.filter(t => t.projectId===p.id && t.date >= mon && t.date <= td); const hrs = r2(wk.reduce((a,t)=>a+hoursOf(t),0)); const cost = r2(wk.reduce((a,t)=>a+hoursOf(t)*laborRate(DB.employees.find(e=>e.id===t.empId)||{}),0)); const lab = (J.byCode||[]).find(r => /labor|payroll/i.test(r.code+' '+(r.name||''))); return {p, hrs, cost, laborCost:J.laborCost||0, budget: lab?.budget||0}; }); const un = DB.time.filter(t => t.status==='submitted' && dayDiff(t.date, td) > 3).length; return `<div class="dx-tiles">${tile(r2(rows.reduce((a,r)=>a+r.hrs,0)), 'crew hours this week')}${tile(un, 'time sheets waiting over 3 days', un?'warn':'ok')}</div><table class="t dash-t"><thead><tr><th>Project</th><th class="money">Hrs · wk</th><th class="money">Labor · wk</th><th class="money">Labor to date</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${esc(shortName(r.p))}</b></td><td class="money">${r.hrs}</td><td class="money">${money(r.cost)}</td><td class="money">${money(r.laborCost)}</td></tr>`).join('')}</tbody></table>`; }
function ptCloseout(){ const rows = activeJobs().filter(x => x.J.pct >= 0.85).map(({p,J}) => ({p, J, punch:p.issues.filter(i=>i.status!=='closed').length, insp:p.inspections.filter(i=>i.status!=='passed').length})); return rows.length ? `<table class="t dash-t"><thead><tr><th>Project</th><th class="money">Done</th><th class="money">Punch</th><th class="money">Inspections</th><th class="money">Retainage</th></tr></thead><tbody>${rows.map(r => `<tr data-remgo='${esc(JSON.stringify({view:'close', project:r.p.id}))}' style="cursor:pointer"><td><b>${esc(shortName(r.p))}</b></td><td class="money">${Math.round(r.J.pct*100)}%</td><td class="money ${r.punch?'warn':''}">${r.punch}</td><td class="money ${r.insp?'warn':''}">${r.insp}</td><td class="money">${money(r.J.retHeld||0)}</td></tr>`).join('')}</tbody></table>` : '<div class="muted small">No project is past 85% — nothing in close-out.</div>'; }
/* ---------- Studio ---------- */
const studioRate = p => +(designEst(p)?.lines.find(l=>l.unit==='hr')?.rate || designRate());
function ptRetainerRunway(){ const td = today(); const rows = studioProjects().map(p => { const R = retainerLeft(p); if (!R) return null; const emps = DB.employees.filter(isDesignStaff).map(e=>e.id); const wk = DB.time.filter(t => t.projectId===p.id && emps.includes(t.empId) && dayDiff(t.date, td) <= 28 && dayDiff(t.date, td) >= 0).reduce((a,t)=>a+hoursOf(t),0)/4; const weeks = wk > 0 ? r2(R.hours/wk) : null; return {p, R, wk:r2(wk), weeks}; }).filter(Boolean).sort((a,b)=>(a.weeks??99)-(b.weeks??99)); return `<div class="rem">${rows.map(r => `<div class="rem-row ${r.weeks!=null && r.weeks < 2 ? 'bad' : r.weeks!=null && r.weeks < 4 ? 'warn' : ''}" data-remgo='${esc(JSON.stringify({view:'sboard', project:r.p.id}))}'><b>${r.weeks==null?'—':r.weeks+' wk'}</b><span><b>${esc(shortName(r.p))}</b> · ${r.R.hours} hrs left (${money(r.R.dollars)}) · burning ${r.wk} hrs/wk${r.weeks!=null?bullet(Math.min(100, r.weeks/8*100), 50, r.weeks<4?'bad':'ok'):''}</span></div>`).join('')||'<div class="muted small">No hourly retainers.</div>'}</div><div class="small muted">Runway = retainer hours left ÷ trailing-4-week burn. Red under 2 weeks (warn the client now), amber under 4.</div>`; }
function ptPhaseBurn(){ const rows = []; studioProjects().forEach(p => { const rooms = roomsOf(p.id); const prog = {sd: rooms.length ? Math.round(rooms.filter(r=>r.phase!=='sd').length/rooms.length*100) : null, dd: rooms.length ? Math.round(rooms.filter(r=>['cd','done'].includes(r.phase)).length/rooms.length*100) : null, cd: rooms.length ? Math.round(rooms.filter(r=>r.phase==='done').length/rooms.length*100) : null}; phaseHours(p).forEach(x => { if (!x.est) return; const burn = Math.round(x.used/x.est*100); const k = /schematic|concept/i.test(x.line.item) ? 'sd' : /development/i.test(x.line.item) ? 'dd' : /construction doc/i.test(x.line.item) ? 'cd' : null; const pr = k ? prog[k] : null; if (!burn && !pr) return; rows.push({p, x, burn, pr}); }); }); rows.sort((a,b) => (b.burn - (b.pr??b.burn)) - (a.burn - (a.pr??a.burn))); return `<div class="dx-pb">${rows.slice(0,8).map(r => `<div class="${r.burn > 100 || (r.pr!=null && r.burn > r.pr + 20) ? 'bad' : (r.pr!=null && r.burn > r.pr + 10) ? 'warn' : ''}"><span><b>${esc(shortName(r.p))}</b> · ${esc(phaseShort(r.x.line.item))}</span><div class="pair"><div class="bar"><i style="width:${Math.min(100,r.burn)}%"></i></div><em>${r.burn}% of hours</em></div>${r.pr!=null?`<div class="pair"><div class="bar"><i class="p" style="width:${r.pr}%"></i></div><em>${r.pr}% of rooms through</em></div>`:''}</div>`).join('')||'<div class="muted small">No phases in progress.</div>'}</div><div class="small muted">Hours burned vs rooms moved past the phase. Red when burn leads progress by 20 points — the leak is in that phase, not the project.</div>`; }
function ptRealization(){ const emps = DB.employees.filter(isDesignStaff).map(e=>e.id); const rows = studioProjects().map(p => { const c = DB.clients.find(x=>x.id===p.clientId); const est = designEst(p); const hrs = DB.time.filter(t => t.projectId===p.id && emps.includes(t.empId)).reduce((a,t)=>a+hoursOf(t),0); const fees = c && est ? designBilled(c, est) : 0; const rate = studioRate(p); const eff = hrs ? r2(fees/hrs) : 0; const real = hrs ? Math.round(fees/(hrs*rate)*100) : 0; return {p, hrs:r2(hrs), fees, rate, eff, real}; }); const H = rows.reduce((a,r)=>a+r.hrs,0), F = rows.reduce((a,r)=>a+r.fees,0); const rate = rows[0]?.rate||designRate(); const eff = H ? r2(F/H) : 0; return `<div class="dx-tiles">${tile(H?Math.round(F/(H*rate)*100)+'%':'—', 'studio realization · fees ÷ (hours × bill rate)', H && F/(H*rate) < .75 ? 'bad' : H && F/(H*rate) < .85 ? 'warn' : 'ok')}${tile(money(eff)+'/hr', `effective rate vs $${rate} bill rate`, eff < rate*.65 ? 'bad' : eff < rate*.8 ? 'warn' : 'ok')}</div><table class="t dash-t"><thead><tr><th>Project</th><th class="money">Hours</th><th class="money">Fees billed</th><th class="money">Eff. rate</th><th class="money">Real.</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${esc(shortName(r.p))}</b></td><td class="money">${r.hrs}</td><td class="money">${money(r.fees)}</td><td class="money">${money(r.eff)}</td><td class="money ${r.real<75?'bad':r.real<85?'warn':''}">${r.real}%</td></tr>`).join('')}</tbody></table><div class="small muted">This is the CEO's studio number: it turns hours into whether the studio covers its burden. Billing lag shows here first — bill banked hours and it recovers.</div>`; }
const FILING_TYPICAL = {lpc:45, altco:30, alt2:25, demo:20, frame:20};
function ptFilingsX(){ const td = today(); const rows = DB.studio.filings.filter(f => f.status!=='approved' && f.status!=='not-started').map(f => { const p = DB.projects.find(x=>x.id===f.projectId); const days = f.submittedOn ? dayDiff(f.submittedOn, td) : (f.startedOn ? dayDiff(f.startedOn, td) : 0); const typ = FILING_TYPICAL[f.key]||30; const court = f.status==='submitted' ? 'agency' : 'us'; return {f, p, days, typ, court, ratio: days/typ}; }).sort((a,b)=>b.ratio-a.ratio); const unbilled = DB.studio.filings.filter(f => (f.status!=='not-started' && !f.billed.start) || (['submitted','objections','approved'].includes(f.status) && !f.billed.submit) || (f.status==='approved' && !f.billed.approve)); return `${dashList(rows.map(r => `<div class="rem-row ${r.ratio > 1.5 || (r.court==='us' && r.days > 5) ? 'bad' : r.ratio > 1 ? 'warn' : ''}" data-remgo='${esc(JSON.stringify({view:'sfile', project:r.p.id}))}'><b>${r.days}d</b><span><b>${esc(r.f.name)}</b> · ${esc(shortName(r.p))} · <span class="pill ${FILING_STATUS[r.f.status][1]}">${FILING_STATUS[r.f.status][0]}</span> · ball with <b>${r.court}</b> · typical ${r.typ}d${r.f.rounds?` · round ${r.f.rounds}`:''}<div class="dx-bullet"><i style="width:${Math.min(100, r.ratio*50)}%" class="${r.ratio>1?'bad':'ok'}"></i><u style="left:50%"></u></div></span></div>`), 'No filings in review.')}${unbilled.length?`<div class="small warn" style="margin-top:6px">${unbilled.length} filing milestone${unbilled.length===1?'':'s'} reached and not invoiced — see Billable now.</div>`:''}<div class="small muted">Days vs our typical for that agency (LPC staff-level ≈45, DOB plan exam ≈25). Red past 1.5× typical, or in our court more than 5 days.</div>`; }
function ptDecisionLat(){ const td = today(); const open = []; const lat = {}; DB.projects.forEach(p => { const c = DB.clients.find(x=>x.id===p.clientId); p.decisions.forEach(d => { if (d.status==='made' && d.madeOn && d.date){ const k = c?.name||'—'; (lat[k] = lat[k]||[]).push(dayDiff(d.date, d.madeOn)); } if (d.status==='open'){ const due = d.due || decDue(d); open.push({p, c, d, due, days: d.date ? dayDiff(d.date, td) : null, gate: due ? dayDiff(td, due) : null}); } }); }); const med = a => { const s = a.slice().sort((x,y)=>x-y); return s.length ? s[Math.floor(s.length/2)] : null; }; open.sort((a,b)=>(a.gate??99)-(b.gate??99)); return `${dashList(open.slice(0,8).map(o => { const m = o.c && lat[o.c.name] ? med(lat[o.c.name]) : null; const cls = (o.gate!=null && o.gate <= 5) || (o.days!=null && o.days > 14) ? 'bad' : (o.gate!=null && o.gate <= 10) || (o.days!=null && o.days > 7) ? 'warn' : ''; return dashItem(o.gate==null?'—':o.gate<0?'late':o.gate+'d', `${esc(shortName(o.p))} · ${esc(o.d.name)}${o.d.gate?` <span class="pill warn">gate · ${esc(o.d.gate)}</span>`:''} · ${esc(o.d.owner||'')}${o.days!=null?` · open ${o.days}d`:''}${m!=null?` · this client usually takes ${m}d`:''}`, {view:'dec', project:o.p.id}, cls); }), 'Nothing open.')}<div class="small muted">Days to the gate the decision holds, next to how long this client usually takes. The evidence for the "we need this by Friday" conversation.</div>`; }
function ptDeliverables(){ const td = today(); const emps = new Set(DB.employees.map(e=>e.name)); const rows = []; studioProjects().forEach(p => { p.tasks.filter(t => t.status!=='done' && (t.track||'')==='design' && t.end && dayDiff(td, t.end) <= 14).forEach(t => rows.push({p, d:t.end, who:t.assignee||'', text:t.name, ext: t.assignee && !emps.has(t.assignee), stale: false})); DB.studio.meetings.filter(m => m.projectId===p.id && m.intake==='proposed').forEach(m => rows.push({p, d:m.date, who:'you', text:`Confirm ${DB.studio.intake[m.id]?.items.filter(i=>i.status==='proposed').length||0} proposals · ${m.title}`, ext:false})); }); DB.studio.promises.filter(x => x.status==='open' && x.dir==='us' && x.due && dayDiff(td, x.due) <= 14).forEach(x => rows.push({p:DB.projects.find(p=>p.id===x.projectId), d:x.due, who:x.owner||'', text:x.text, ext:false})); rows.sort((a,b)=>(a.d||'').localeCompare(b.d||'')); return dashList(rows.slice(0,10).map(r => `<div class="rem-row ${dayDiff(td, r.d) < 0 ? 'bad' : dayDiff(td, r.d) <= 3 ? 'warn' : ''}" data-remgo='${esc(JSON.stringify({view:'sboard', project:r.p?.id}))}'><b>${fmt(r.d)}</b><span><span class="muted">${esc(shortName(r.p||{project:{name:''}}))} · ${r.ext?'<span class="pill info">consultant</span> ':''}${esc(r.who)} · </span>${esc(r.text)}</span></div>`), 'Nothing due in the next 14 days.'); }
function ptHoursPeople(){ const td = today(); const mon = iso(addDays(td, -((parse(td).getDay()+6)%7))); const days = []; for (let i = 1; days.length < 10; i++){ const d = iso(addDays(td, -i)); if (![0,6].includes(parse(d).getDay())) days.push(d); } const rows = DB.employees.filter(isDesignStaff).map(e => { const wk = DB.time.filter(t => t.empId===e.id && t.date >= mon && t.date <= td); const h = r2(wk.reduce((a,t)=>a+hoursOf(t),0)); const bill = r2(wk.filter(t=>t.projectId).reduce((a,t)=>a+hoursOf(t),0)); const un = days.filter(d => !DB.time.some(t => t.empId===e.id && t.date===d)).length; return {e, h, bill, un, util: Math.round(h/40*100)}; }); return `<div class="dx-people">${rows.map(r => `<div class="${r.un>=2 || r.util < 55 || r.util > 95 ? 'bad' : r.un===1 || r.util < 65 ? 'warn' : ''}"><b>${esc(r.e.name)}</b><div class="bar"><i style="width:${Math.min(100,r.util)}%"></i><i class="b" style="width:${Math.min(100, Math.round(r.bill/40*100))}%"></i></div><span>${r.h} hrs this week · ${r.bill} on projects${r.un?` · <em>${r.un} unlogged day${r.un===1?'':'s'}</em>`:''}</span></div>`).join('')}</div><div class="small muted">Against a 40-hour week; dark = on projects. Unlogged days in the last 10 working days are the realization leak.</div>`; }
function ptRework(){ const rows = studioProjects().map(p => { const ch = DB.studio.changes.filter(c => c.projectId===p.id); let re = 0; ch.forEach(c => { re += DB.time.filter(t => t.projectId===p.id && t.date >= c.at && dayDiff(c.at, t.date) <= 10 && /re-?draw|revise|rework|update|re-?issue/i.test(t.notes||'')).reduce((a,t)=>a+hoursOf(t),0); }); const total = DB.time.filter(t => t.projectId===p.id).reduce((a,t)=>a+hoursOf(t),0); const unv = roomsOf(p.id).filter(r => roomProv(r)===0 && r.phase!=='sd').length; return {p, re:r2(re), pct: total ? Math.round(re/total*100) : 0, ch:ch.length, unv}; }); return dashList(rows.map(r => dashItem(r.re+' h', `${esc(shortName(r.p))} · rework after ${r.ch} dimension change${r.ch===1?'':'s'} · ${r.pct}% of hours${r.unv?` · <b class="bad">${r.unv} rooms past SD still unverified</b>`:''}`, {view:'sdraw', project:r.p.id}, r.unv || r.pct > 8 ? 'bad' : r.pct > 4 ? 'warn' : '')), 'No design projects.'); }
function ptCadence(){ const td = today(); const rows = studioProjects().map(p => { const deck = sheetsOf(p.id).filter(s=>s.set==='deck' && s.issuedOn).map(s=>s.issuedOn).sort().pop(); const mt = DB.studio.meetings.filter(m=>m.projectId===p.id).map(m=>m.date).sort().pop(); const tr = DB.studio.transmittals.filter(t=>t.projectId===p.id).map(t=>t.date).sort().pop(); const touch = [deck, mt].filter(Boolean).sort().pop(); const dT = touch ? Math.max(0, dayDiff(touch, td)) : null; const dI = tr ? Math.max(0, dayDiff(tr, td)) : null; return {p, dT, dI}; }); return dashList(rows.map(r => dashItem(r.dT==null?'—':r.dT+'d', `${esc(shortName(r.p))} · since last client touchpoint${r.dI!=null?` · ${r.dI}d since last set issued`:''}`, {view:'sboard', project:r.p.id}, r.dT!=null && r.dT > 21 ? 'bad' : r.dT!=null && r.dT > 14 ? 'warn' : '')), 'No design projects.'); }
function ptFFE(){ const rows = DB.studio.ffe; const by = {}; FFE_STATUS.forEach(s => by[s] = rows.filter(f=>f.status===s).length); const td = today(); const late = rows.filter(f => f.materialId).map(f => { const p = DB.projects.find(x=>x.id===f.projectId); const m = p?.materials.find(x=>x.id===f.materialId); return {f, p, m}; }).filter(x => x.m && !['ordered','shipped','on-site'].includes(x.m.status)); return `<div class="dx-funnel five">${FFE_STATUS.map(s => `<div><span>${s}</span><b>${by[s]}</b></div>`).join('')}</div>${dashList(late.slice(0,5).map(x => dashItem('approved', `${esc(x.f.item)} · ${esc(shortName(x.p))} — not ordered yet`, {view:'mat', project:x.p.id}, 'warn')), 'Every approved selection is ordered.')}`; }
