  if (p.kind==='received'){ if (p.matId){ fReceiveQuiet('mat', p.matId, p.staged); } else { toast('Which material? Use Site → Deliveries'); return false; } return true; }
  if (p.kind==='subok'){ const s = DB.field.subs.find(x=>x.id===p.subId); if (!s) return false; s.status = 'confirmed'; s.at = fNow(); log(`${s.vendor} confirmed for ${fmt(s.date)} (by phone)`, 'field', by); return true; }
  if (p.kind==='noshow'){ const s = DB.field.subs.find(x=>x.id===p.subId); if (s){ s.status = 'noshow'; s.at = fNow(); } fSend({type:'noshow', title:p.title, taskId:s?.taskId || p.taskId || '', to:p.to, dueBy:p.dueBy||td, note:s?`Lead: ${s.lead} ${s.phone}`:''}); return true; }
  if (p.kind==='punch'){ DB.field.punch.push({id:uid('fp'), projectId:S.id, room:p.taskId?task(p.taskId)?.name:'', item:p.title, assignee:'', status:'open', by, at:fNow(), photos:fShots.slice()}); toast('On the punch list'); return true; }
  if (p.kind==='taskdone'){ const t = task(p.taskId); if (!t) return false; t.status = 'done'; t.actualEnd = td; log(`${t.name} finished (foreman)`, 'field', by); toast(`${t.name} — done`); return true; }
  if (p.kind==='taskstart'){ const t = task(p.taskId); if (!t) return false; t.status = 'in-progress'; t.actualStart = t.actualStart||td; log(`${t.name} started (foreman)`, 'field', by); toast(`${t.name} — started`); return true; }
  if (p.kind==='log'){ const rec = DB.field.logs.find(l => l.projectId===S.id && l.date===td) || (() => { const r = {id:uid('fl'), projectId:S.id, date:td, by, weather:'', temp:'', crew:[], subs:[], deliveries:[], done:[], notes:'', photos:[], status:'draft'}; DB.field.logs.push(r); return r; })(); rec.notes = (rec.notes ? rec.notes + ' ' : '') + p.title; toast('Added to today\'s log'); return true; }
  if (p.kind==='insp'){ const i = p.inspId ? S.inspections.find(x=>x.id===p.inspId) : null; if (i && p.result==='passed'){ i.status='passed'; i.resultOn = td; log(`${i.name}: PASSED`, 'field', by); fSend({type:'insp', title:`${i.name} passed${i.gates?` — clear to start ${task(i.gates)?.name||''}`:''}`, dueBy:td, note:p.title}); return true; } if (i && p.result==='failed'){ i.status='failed'; i.resultOn = td; log(`${i.name}: FAILED — ${p.title}`, 'field', by); fSend({type:'insp', title:`${i.name} FAILED — ${p.title}`, note:'Need the fix scoped and a re-inspection booked.', taskId:i.gates||''}); return true; } if (i && p.result==='ready'){ i.readyOn = td; i.readyBy = by; } fSend({type:'insp', title:p.title, taskId:i?.gates||p.taskId||'', to:p.to, dueBy:p.dueBy}); return true; }
