  const mic = m.querySelector('#fmic'); if (SR){ mic.onclick = () => { if (fRec){ try { fRec.stop(); } catch(e){} return; } const r = new SR(); fRec = r; r.lang = 'en-US'; r.interimResults = true; r.continuous = true; const base = ta.value ? ta.value.trim() + ' ' : ''; mic.classList.add('on'); mic.querySelector('span').textContent = 'Listening… tap to stop'; r.onresult = e => { let fin = '', inter = ''; for (let i=0;i<e.results.length;i++){ const s = e.results[i][0].transcript; if (e.results[i].isFinal) fin += s + ' '; else inter += s; } ta.value = (base + fin + inter).replace(/\s+/g,' '); refresh(); }; r.onend = () => { fRec = null; mic.classList.remove('on'); mic.querySelector('span').textContent = 'Tap and talk'; refresh(); }; r.onerror = ev => { fRec = null; mic.classList.remove('on'); mic.querySelector('span').textContent = ev.error==='not-allowed' ? 'Mic blocked — allow it in Settings, or type' : 'Tap and talk'; }; try { r.start(); } catch(e){ fRec = null; } }; }
