function fForYouHtml(){ const items = fForYou(); if (!items.length) return ''; return `<div class="card f-card f-you"><div class="hd"><h3>For you</h3><span class="small muted">${items.length}</span></div>${items.map(i => `<div class="f-row ${i.sev===3?'bad':i.sev===2?'ok':''}"><div class="grow"><b>${esc(i.t)}</b>${i.s?`<span class="small">${esc(i.s)}</span>`:''}</div><button class="btn sm ${i.sev>=2?'primary':''}" data-fack="${i.k}:${i.id}">Got it</button></div>`).join('')}</div>`; }
function fWireForYou(root){ root.querySelectorAll('[data-fack]').forEach(b => b.onclick = () => { const [k,id] = b.dataset.fack.split(':'); if (k==='answer'){ const r = DB.field.raises.find(x=>x.id===id); r.status = 'closed'; r.closedAt = fNow(); if (r.type==='rfi'){ const is = S.issues.find(i => i.raiseId===r.id); if (is) is.status = 'closed'; } log(`Field has it: ${r.title}`, 'field', fWho()); } else if (k==='note'){ const n = DB.field.notes.find(x=>x.id===id); n.ack = fNow(); } else { DB.field.acks = DB.field.acks||[]; DB.field.acks.push(k+':'+id); } save(); render(); }); }
function fMsgForeman(projectId){ mbModal('Message the foreman', `<div class="f"><label>What kind</label><select data-f="kind"><option value="plan">Plan change</option><option value="delivery">Delivery update</option><option value="decision">Decision made</option><option value="sheet">Drawing revised</option><option value="note">Message</option></select></div><div class="f"><label>Say it plainly — this lands at the top of his Today</label><div class="row" style="gap:6px;align-items:flex-start"><textarea data-f="text" rows="3" class="grow" placeholder="e.g. Tile delivery moved to Thursday. Board the garden kitchen tomorrow instead."></textarea>${fVoiceBtn('text')}</div></div>`, {submit:'Send', onSubmit: f => { if (!f.text){ toast('Write the message'); return false; } DB.field.notes = DB.field.notes||[]; DB.field.notes.push({id:uid('fn'), projectId:projectId||S.id, kind:f.kind, text:f.text, by:currentUser()?.name||DB.me, at:fNow(), ack:''}); save(); render(); toast('Sent to the foreman'); }}); const mm = $('#mbm'); if (mm) fWireVoice(mm); }
// ---------- answered by phone ----------
function fPhoneAnswer(id){ const r = DB.field.raises.find(x=>x.id===id); const who = fPerson(r.to); mbModal(`Talked to ${who?who.name.split(' ')[0]:'them'}`, `<p class="small muted" style="margin:0 0 8px"><b>${esc(r.title)}</b></p><div class="f"><label>What they said</label><div class="row" style="gap:6px;align-items:flex-start"><textarea data-f="a" rows="3" class="grow" placeholder="e.g. Go ahead, he's writing the CO"></textarea>${fVoiceBtn('a')}</div></div>${r.type==='extra'?`<div class="f"><label>Decision</label><select data-f="dec"><option value="extra">Proceed as an extra</option><option value="nocharge">Do it, no charge</option><option value="hold">Hold</option></select></div>`:''}<label class="small" style="display:flex;gap:6px;align-items:center"><input type="checkbox" data-f="open"> No answer yet — just log the call</label>`, {submit:'Save', onSubmit: f => { r.calls = r.calls||[]; r.calls.push({at:fNow(), by:fWho(), note:f.a}); if (f.open){ log(`Called ${who?who.name:r.to} about: ${r.title} — ${f.a||'no answer yet'}`, 'field', fWho()); save(); render(); return; } if (!f.a){ toast('What did they say?'); return false; } r.status = 'answered'; r.answer = f.a; r.decision = f.dec||''; r.answeredBy = `${who?who.name:r.to} (by phone, logged by ${fWho()})`; r.answeredAt = fNow(); r.viaPhone = true; r.escalated = false; if (r.type==='rfi'){ const is = S.issues.find(i => i.raiseId===r.id); if (is){ is.status = 'answered'; is.notes = `${is.notes} — Answer (phone): ${f.a}`; } } if (r.type==='extra' && (f.dec||'extra')==='extra'){ S.actions = S.actions||[]; S.actions.push({id:uid('a'), title:`Write change order: ${r.title}`, assignee:who?who.name:'', due:iso(addDays(today(),2)), status:'open', src:'field', raiseId:r.id}); } log(`${F_TYPES[r.type].n} answered by phone (${who?who.name:r.to}): ${f.a}`, 'field', fWho()); save(); render(); }}); const mm = $('#mbm'); if (mm) fWireVoice(mm); }
// ---------- room answers ----------
function fRooms(){ const st = DB.studio?.rooms ? roomsOf(S.id) : []; if (st.length) return st.map(r => ({id:r.id, name:r.name, floor:r.floor, studio:r})); return (S.takeoff?.rooms||[]).map((r,i) => ({id:'tk'+i, name:r.name, floor:r.floor})); }
