/* ---------- analysis — Chen's spreadsheet, native ---------- */
function procAnalysisModal(){
  const all = selItems();
  const byCat = {};
  all.forEach(i => { const c = i.category || 'Other'; const b = byCat[c] = byCat[c] || {n: 0, budget: 0, actual: 0, open: 0}; b.n++; b.budget += selLineCost(i); if (selActual(i)) b.actual += selActual(i); if (SEL_OPEN.includes(i.stage)) b.open += selLineCost(i); });
  const byFM = {};
  all.forEach(i => { const f = i.fm || '—'; const b = byFM[f] = byFM[f] || {n: 0, budget: 0, actual: 0, open: 0}; b.n++; b.budget += selLineCost(i); if (selActual(i)) b.actual += selActual(i); if (SEL_OPEN.includes(i.stage)) b.open += selLineCost(i); });
  const vel = all.map(selDaysToOrder).filter(n => n != null);
  const median = vel.length ? vel.sort((a, b) => a - b)[Math.floor(vel.length / 2)] : null;
  const bought = all.filter(i => selActual(i));
  const saved = bought.reduce((a, i) => a + selSaved(i), 0);
  const budg = bought.reduce((a, i) => a + selLineCost(i), 0);
  const row = ([k, b]) => `<tr><td>${esc(k)}</td><td class="num">${b.n}</td><td class="money">${money(b.budget)}</td><td class="money">${b.actual ? money(b.actual) : '—'}</td><td class="money ${b.actual && b.budget - b.actual > 0 ? 'ok' : ''}">${b.actual ? money(b.budget - b.actual) : '—'}</td><td class="money">${money(b.open)}</td></tr>`;

  mbModal('Procurement analysis', `
    <div class="sel-stats" style="margin:0 0 12px">
      <div class="sel-stat"><b>${money(all.reduce((a, i) => a + selLineCost(i), 0))}</b><span>budgeted across the board</span></div>
      <div class="sel-stat ${saved > 0 ? 'ok' : ''}"><b>${money(saved)}</b><span>saved on what is bought</span></div>
      <div class="sel-stat"><b>${budg ? Math.round(saved / budg * 100) : 0}%</b><span>under budget on those items</span></div>
      <div class="sel-stat"><b>${median == null ? '—' : median + 'd'}</b><span>median days, selected to ordered</span></div>
      <div class="sel-stat"><b>${money(all.filter(i => SEL_OPEN.includes(i.stage)).reduce((a, i) => a + selLineCost(i), 0))}</b><span>remaining to purchase</span></div>
    </div>
    <h4 style="margin:0 0 6px">By category</h4>
    <table class="t"><thead><tr><th>Category</th><th class="num">Items</th><th class="money">Budget</th><th class="money">Actual</th><th class="money">Saved</th><th class="money">Remaining</th></tr></thead>
    <tbody>${Object.entries(byCat).sort((a, b) => b[1].budget - a[1].budget).map(row).join('')}</tbody></table>
    <h4 style="margin:14px 0 6px">By FM group</h4>
    <table class="t"><thead><tr><th>FM</th><th class="num">Items</th><th class="money">Budget</th><th class="money">Actual</th><th class="money">Saved</th><th class="money">Remaining</th></tr></thead>
    <tbody>${Object.entries(byFM).sort((a, b) => String(a[0]).localeCompare(String(b[0]))).map(row).join('')}</tbody></table>
    <p class="small muted" style="margin:12px 0 0">Days selected-to-ordered is the buying speed metric — it says how long a decision sits before anyone acts on it, which is the number that quietly costs the schedule.</p>`,
    {submit: null});
  procWide(900);
}

/* ===================== VENDOR PERFORMANCE =====================
   A lead time read off a vendor's own page is a marketing number. The useful number is how long
   Ferguson actually took, the last six times, on this kind of item — and that is sitting in the
   record already, because every item carries the day it was ordered and the day it landed.

   So the buy date is driven by what happens, not by what is claimed. When the observed median and
   the quoted figure disagree, the observed one wins and the item says so.

   The same history answers the question that should come before sourcing rather than after: who is
   actually cheapest on door hardware, across every project, not just this one. */

const selOrderedItems = () => DB.sel.items.filter(i => i.dates?.ordered);
const median = a => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); return s.length % 2 ? s[(s.length - 1) / 2] : Math.round((s[s.length / 2 - 1] + s[s.length / 2]) / 2); };

// Ordered → landed at the office. The only lead time that is a fact rather than a claim.
function selActualLead(it){
  const o = it.dates?.ordered, r = it.dates?.office;
  return o && r ? dayDiff(o, r) : null;
}

function selVendorStats(){
  const out = {};
  for (const it of selOrderedItems()){
    const v = it.vendor || 'Unassigned';
    const V = out[v] = out[v] || {vendor: v, items: 0, spend: 0, leads: [], quoted: [], onTime: 0, onTimeOf: 0, budget: 0, actual: 0, priced: 0, receipts: 0, clean: 0, cats: {}, makes: {}};
    const cat = it.category || 'Other';
    const C = V.cats[cat] = V.cats[cat] || {cat, items: 0, leads: [], budget: 0, actual: 0, priced: 0, receipts: 0, clean: 0};
    const mk = it.manufacturer || '';
    const M = mk ? (V.makes[mk] = V.makes[mk] || {make: mk, items: 0, leads: []}) : null;
    V.items++; C.items++; if (M) M.items++;
    if (it.receipt){ V.receipts++; C.receipts++; if (it.receipt.condition === 'ok'){ V.clean++; C.clean++; } }
    const lead = selActualLead(it);
    if (lead != null && lead >= 0 && lead < 400){ V.leads.push(lead); C.leads.push(lead); if (M) M.leads.push(lead); if (it.quotedLead) V.quoted.push(+it.quotedLead); }
    const need = it.needOnSite || selNeedOnSite(it);
    if (need && it.dates?.office){ V.onTimeOf++; if (it.dates.office <= need) V.onTime++; }
    const a = selActual(it);
    if (a){ const b = selLineCost(it); V.budget += b; V.actual += a; V.priced++; C.budget += b; C.actual += a; C.priced++; V.spend += a; }
    else V.spend += selLineCost(it);
  }
  for (const V of Object.values(out)){
    V.lead = median(V.leads);
    V.leadN = V.leads.length;
    V.quotedLead = median(V.quoted);
    V.drift = V.lead != null && V.quotedLead != null ? V.lead - V.quotedLead : null;
    V.onTimePct = V.onTimeOf ? Math.round(V.onTime / V.onTimeOf * 100) : null;
    V.intactPct = V.receipts ? Math.round(V.clean / V.receipts * 100) : null;
    V.openClaims = claimsOpen().filter(c => c.vendor === V.vendor).length;
    const closed = selClaims().filter(c => c.vendor === V.vendor && c.resolvedAt);
    V.claimDays = median(closed.map(c => dayDiff(c.raisedAt, c.resolvedAt)).filter(n => n >= 0));
    V.claimsRaised = selClaims().filter(c => c.vendor === V.vendor).length;
    for (const M of Object.values(V.makes)){ M.lead = median(M.leads); M.leadN = M.leads.length; }
    V.savedPct = V.budget ? Math.round((V.budget - V.actual) / V.budget * 100) : null;
    V.saved = r2(V.budget - V.actual);
    for (const C of Object.values(V.cats)){
      C.lead = median(C.leads); C.leadN = C.leads.length;
      C.intactPct = C.receipts ? Math.round(C.clean / C.receipts * 100) : null;
      C.savedPct = C.budget ? Math.round((C.budget - C.actual) / C.budget * 100) : null;
      C.saved = r2(C.budget - C.actual);
    }
  }
  return out;
}

// The lead time to plan against — and the asymmetry matters.
//
// History can tell you a vendor is slower than they claim. It cannot tell you that THIS item is faster
// than they claim: a vendor's median is a coarse number, and a 56-day made-to-order shower set does not
// become a 43-day item because Ferguson's typical order is 43 days. So the observed figure only ever
// pushes the buy date earlier, never later. Plan against the worse of the two.
const SEL_LEAD_MIN_N = 3;
// Most specific evidence first. Manufacturer beats category: a Waterworks order is slow whether it is a
// faucet or a shower set, and the same vendor's stock items are not. Category is the fallback for a
// manufacturer we have not bought before.
function selLeadFor(vendor, category, manufacturer, quoted){
  const q = +quoted || 0;
  const V = selVendorStats()[vendor];
  let obs = null, n = 0, scope = vendor || '';
  if (V){
    const M = manufacturer ? V.makes[manufacturer] : null;
    const C = V.cats[category];
    if (M && M.leadN >= SEL_LEAD_MIN_N){ obs = M.lead; n = M.leadN; scope = `${vendor} · ${manufacturer}`; }
    else if (C && C.leadN >= SEL_LEAD_MIN_N){ obs = C.lead; n = C.leadN; scope = `${vendor} · ${category}`; }
    else if (V.leadN >= SEL_LEAD_MIN_N){ obs = V.lead; n = V.leadN; }
  }
  if (obs != null && obs > q) return {days: obs, basis: 'observed', n, scope, quoted: q};
  return {days: q, basis: 'quoted', n, scope, quoted: q, observed: obs};
}
// Cached per render pass — selVendorStats walks every item and selOrderBy is called per row.
let _leadCache = null, _leadCacheAt = 0;
function selEffLead(it){
  if (!_leadCache || Date.now() - _leadCacheAt > 1500){ _leadCache = {}; _leadCacheAt = Date.now(); }
  const k = `${it.vendor}|${it.category}|${it.manufacturer}|${it.leadDays}`;
  if (!(k in _leadCache)) _leadCache[k] = selLeadFor(it.vendor, it.category, it.manufacturer, +it.leadDays || 0);
  return _leadCache[k];
}

// Who is actually cheapest on door hardware — across every project, before the sourcing starts.
function selCategoryLeaders(){
  const stats = selVendorStats();
  const byCat = {};
  for (const V of Object.values(stats)){
    for (const C of Object.values(V.cats)){
      if (!C.priced) continue;
      (byCat[C.cat] = byCat[C.cat] || []).push({vendor: V.vendor, items: C.priced, savedPct: C.savedPct, saved: C.saved, budget: C.budget, lead: C.lead, leadN: C.leadN, intactPct: V.intactPct, receipts: V.receipts});
    }
  }
  for (const k of Object.keys(byCat)) byCat[k].sort((a, b) => (b.savedPct ?? -99) - (a.savedPct ?? -99) || b.items - a.items);
  return byCat;
}

function procVendorModal(){
  const stats = selVendorStats();
  const rows = Object.values(stats).sort((a, b) => b.spend - a.spend);
  const cats = selCategoryLeaders();
  const drift = rows.filter(v => v.drift != null && v.drift >= 5);
  mbModal('Vendor performance', `
    <p class="small muted" style="margin:0 0 10px">Every figure here comes from the record: the day an order was placed, the day the box landed, and what the receipt said against what was budgeted. A lead time on a vendor's website is a marketing number; this is the one the board plans against once there are ${SEL_LEAD_MIN_N} orders to go on.</p>
    ${drift.length ? `<div class="note warn" style="margin-bottom:10px"><b>Quoting short:</b> ${drift.map(v => `${esc(v.vendor)} says ${v.quotedLead} days and takes ${v.lead}`).join('; ')}. The board plans against the longer figure. History only ever moves a buy date earlier — it can prove a vendor slow, never fast.</div>` : ''}
    ${(() => { const bad = rows.filter(v => v.intactPct != null && v.intactPct < 90 && v.receipts >= 3); return bad.length ? `<div class="note bad" style="margin-bottom:10px"><b>Arriving damaged:</b> ${bad.map(v => `${esc(v.vendor)} — ${100 - v.intactPct}% of ${v.receipts} receipts had something wrong`).join('; ')}. A vendor a few percent cheaper who damages one in four is not cheaper.</div>` : ''; })()}
    <table class="t"><thead><tr><th>Vendor</th><th class="num">Items</th><th class="money">Spend</th><th class="num">Lead — actual</th><th class="num">Quoted</th><th class="num">On time</th><th class="num">Intact</th><th class="money">Against budget</th></tr></thead><tbody>
      ${rows.map(v => `<tr>
        <td><b>${esc(v.vendor)}</b><div class="small muted">${esc(Object.values(v.cats).sort((a, b) => b.items - a.items).slice(0, 2).map(c => c.cat).join(', '))}</div>${v.claimDays != null ? `<div class="small muted">claims close in ${v.claimDays}d</div>` : ''}</td>
        <td class="num">${v.items}</td>
        <td class="money">${money(v.spend)}</td>
        <td class="num">${v.lead != null ? `<b>${v.lead}d</b><div class="small muted">n=${v.leadN}</div>` : '<span class="muted">—</span>'}</td>
        <td class="num ${v.drift != null && v.drift >= 5 ? 'bad' : ''}">${v.quotedLead != null ? `${v.quotedLead}d${v.drift ? `<div class="small ${v.drift > 0 ? 'bad' : 'ok'}">${v.drift > 0 ? '+' : ''}${v.drift}d</div>` : ''}` : '<span class="muted">—</span>'}</td>
        <td class="num ${v.onTimePct != null && v.onTimePct < 70 ? 'bad' : ''}">${v.onTimePct != null ? v.onTimePct + '%' : '<span class="muted">—</span>'}</td>
        <td class="num ${v.intactPct != null && v.intactPct < 90 ? 'bad' : ''}">${v.intactPct != null ? `${v.intactPct}%<div class="small muted">${v.receipts} received${v.openClaims ? ` · <b class="bad">${v.openClaims} open</b>` : ''}</div>` : '<span class="muted">—</span>'}</td>
        <td class="money ${v.savedPct > 0 ? 'ok' : v.savedPct < 0 ? 'bad' : ''}">${v.savedPct != null ? `${Math.abs(v.savedPct)}% ${v.savedPct > 0 ? 'under' : v.savedPct < 0 ? 'over' : 'on'}<div class="small muted">${money(Math.abs(v.saved))} on ${v.priced}</div>` : '<span class="muted">—</span>'}</td>
      </tr>`).join('') || '<tr><td colspan="7" class="empty">No orders with dates yet.</td></tr>'}
    </tbody></table>

    ${(() => {
      const mk = [];
      for (const v of rows) for (const M of Object.values(v.makes || {})) if (M.leadN >= SEL_LEAD_MIN_N) mk.push({vendor: v.vendor, ...M, vLead: v.lead});
      if (!mk.length) return '';
      return `<h4 style="margin:16px 0 6px">By manufacturer, through each vendor</h4>
      <p class="small muted" style="margin:0 0 8px">A made-to-order line is slow whether it is a faucet or a shower set, and the same vendor's stock is not. Where there are ${SEL_LEAD_MIN_N} orders of a manufacturer through a vendor, that is the figure the board plans against — it beats the category average.</p>
      <table class="t"><thead><tr><th>Vendor</th><th>Manufacturer</th><th class="num">Orders</th><th class="num">Lead</th><th class="num">Vs their own average</th></tr></thead><tbody>
      ${mk.sort((a, b) => b.lead - a.lead).map(x => `<tr><td>${esc(x.vendor)}</td><td><b>${esc(x.make)}</b></td><td class="num">${x.leadN}</td><td class="num"><b>${x.lead}d</b></td>
        <td class="num ${x.vLead != null && x.lead - x.vLead >= 7 ? 'bad' : ''}">${x.vLead != null ? `${x.lead - x.vLead > 0 ? '+' : ''}${x.lead - x.vLead}d` : '—'}</td></tr>`).join('')}
      </tbody></table>`;
    })()}

    <h4 style="margin:16px 0 6px">Who to ask first, by category</h4>
    <p class="small muted" style="margin:0 0 8px">Ranked by how far under budget they land, across every project. This is the question worth answering before the sourcing rather than after it.</p>
    ${Object.keys(cats).length ? `<table class="t"><thead><tr><th>Category</th><th>Ask first</th><th class="num">Under budget</th><th class="num">Lead</th><th class="num">Intact</th><th>Then</th></tr></thead><tbody>
      ${Object.entries(cats).sort((a, b) => b[1][0].budget - a[1][0].budget).map(([cat, list]) => `<tr>
        <td>${esc(cat)}</td>
        <td><b>${esc(list[0].vendor)}</b><div class="small muted">${list[0].items} item${list[0].items === 1 ? '' : 's'}</div></td>
        <td class="num ${list[0].savedPct > 0 ? 'ok' : ''}">${list[0].savedPct != null ? `${Math.abs(list[0].savedPct)}% ${list[0].savedPct >= 0 ? 'under' : 'over'}` : '—'}</td>
        <td class="num">${list[0].lead != null ? list[0].lead + 'd' : '—'}</td>
        <td class="num ${list[0].intactPct != null && list[0].intactPct < 90 ? 'bad' : ''}">${list[0].intactPct != null ? list[0].intactPct + '%' : '—'}</td>
        <td class="small muted">${esc(list.slice(1, 3).map(x => `${x.vendor}${x.savedPct != null ? ` (${Math.abs(x.savedPct)}% ${x.savedPct >= 0 ? 'under' : 'over'})` : ''}`).join(', ') || '—')}</td>
      </tr>`).join('')}
    </tbody></table>` : '<p class="small muted">Nothing bought with an actual cost against it yet.</p>'}
    <p class="small muted" style="margin:12px 0 0">Under-budget percentages compare the receipt — goods, shipping and tax — against what the item was budgeted at. A vendor with one lucky order is not a pattern; the item count is there so you can see which is which. Read the intact column beside the price: a saving that arrives chipped costs a re-order and four weeks.</p>`,
    {submit: null});
  procWide(1040);
}

/* ===================== CLIPPER ACCESS =====================
   The extension needs to prove it is one of ours. A token is issued here, shown once, and stored as a
   hash — so this screen can list who has one and revoke it, and nobody can read a colleague's token back
   out of the database. Showing it once is the point: a token you can look up later is a token that leaks.
   Each one is bound to the person it was issued to, so a clip arrives with a name on it. */
const CLIP_TOKEN_LEN = 32;
function clipToken(){
  const a = new Uint8Array(CLIP_TOKEN_LEN);
  (window.crypto || {}).getRandomValues ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); });
  return 'sdc_' + [...a].map(b => b.toString(36).padStart(2, '0')).join('').slice(0, 40);
}
// Not a password hash and does not need to be — the token is 40 random characters, so there is nothing
// to brute-force back. This exists so the stored row is not itself a working credential.
async function clipHash(t){
  try {
    const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(t));
    return [...new Uint8Array(d)].map(b => b.toString(16).padStart(2, '0')).join('');
  } catch (e){ let h = 0; for (const c of t) h = (h * 31 + c.charCodeAt(0)) | 0; return 'x' + (h >>> 0).toString(16); }
}
function clipTokens(){ DB.company.clipTokens = DB.company.clipTokens || []; return DB.company.clipTokens; }

function clipAccessModal(){
  const list = clipTokens();
  const endpoint = (window.SDP_CONFIG?.aiUrl || '').replace(/\/ai$/, '/clip') || `${location.origin}/api/clip`;
  mbModal('Clipper access', `
    <p class="small muted" style="margin:0 0 10px">One token per person. It is shown once, here, and stored only as a hash — a token anyone can look up later is a token that leaks. Clips arrive with the holder's name on them, so a bad capture can be traced to a person rather than to "the clipper".</p>
    <div class="f"><label>Board address for the extension</label><input id="clip-endpoint" value="${esc(endpoint)}" readonly></div>
    ${list.length ? `<table class="t" style="margin-top:10px"><thead><tr><th>Who</th><th>Issued</th><th>Last used</th><th></th></tr></thead><tbody>
      ${list.map(t => `<tr class="${t.revoked ? 'muted' : ''}"><td><b>${esc(t.name)}</b><div class="small muted">${esc(t.hint || '')}</div></td><td class="small">${fmt(t.at)}</td><td class="small">${t.usedAt ? fmt(t.usedAt) : '<span class="muted">never</span>'}</td>
        <td class="nowrap">${t.revoked ? '<span class="pill neutral">Revoked</span>' : `<button class="btn sm ghost" data-revoke="${t.id}">Revoke</button>`}</td></tr>`).join('')}
    </tbody></table>` : '<p class="small muted" style="margin-top:10px">No tokens issued yet.</p>'}
    <div class="grid2" style="margin-top:12px">
      <div class="f"><label>Issue a token to</label><select data-f="who">${DB.users.filter(u => !String(u.role).startsWith('mb_')).map(u => `<option value="${esc(u.name)}">${esc(u.name)} — ${esc(ROLE_NAMES[u.role] || u.role)}</option>`).join('')}</select></div>
      <div class="f"><label>&nbsp;</label><button class="btn primary" id="clip-issue" style="width:100%">Issue</button></div>
    </div>
    <div id="clip-new"></div>`, {submit: null});

  const m = document.getElementById('mbm'); if (!m) return;
  m.querySelectorAll('[data-revoke]').forEach(b => b.onclick = () => {
    const t = clipTokens().find(x => x.id === b.dataset.revoke); if (!t) return;
    t.revoked = today(); audit('clip-token', t.id, 'revoked', null, {name: t.name});
    log(`Clipper token revoked — ${t.name}`); save(); mbCloseModal(); clipAccessModal();
  });
  m.querySelector('#clip-issue').onclick = async () => {
    const who = m.querySelector('[data-f="who"]').value;
    const tok = clipToken();
    const rec = {id: uid('ct'), name: who, at: today(), hash: await clipHash(tok), hint: `…${tok.slice(-6)}`, by: currentUser()?.name || DB.me || '', usedAt: '', revoked: ''};
    clipTokens().push(rec);
    audit('clip-token', rec.id, 'issued', null, {name: who});
    log(`Clipper token issued to ${who}`);
    if (window.Cloud && Cloud.on() && Cloud.saveClipToken) Cloud.saveClipToken(rec).catch(() => {});
    save();
    m.querySelector('#clip-new').innerHTML = `<div class="note" style="margin-top:12px"><b>${esc(who)}'s token — copy it now</b>
      <div class="clip-tok"><code id="clip-tok">${esc(tok)}</code><button class="btn sm" id="clip-copy">Copy</button></div>
      <div class="small muted" style="margin-top:6px">Paste it into the extension: right-click the icon → Options, with the board address above. It will not be shown again — issue a new one if it is lost.</div></div>`;
    m.querySelector('#clip-copy').onclick = () => { navigator.clipboard?.writeText(tok); toast('Copied'); };
  };
}

/* ===================== THE PICKUP RUN — Gabriel's screen =====================
   Alan, 00:56:23: "driver details for Gabriel — okay, tomorrow you need to pick these things up from the
   office, and he can check it off from his app." It is a list of tagged boxes, ordered by the day the wall
   needs them, and it is generated rather than written: an item is on it because it is at the office and
   the schedule says the site wants it. Checking a box moves the item to the site and stamps the date, so
   the buyer's board and the driver's list are the same record — nobody reconciles anything. */
const PICKUP_HORIZON = 10;                                     // days of site dates worth loading a van for

function pickupList(){
  const out = [];
  for (const p of DB.projects){
    for (const it of DB.sel.items){
      if (it.projectId !== p.id || it.stage !== 'office') continue;
      if (selHeld(it)) continue;                                   // under claim; it is not going anywhere
      const need = selNeedOnSite(it);
      const days = need ? dayDiff(today(), need) : 999;
      if (days > PICKUP_HORIZON) continue;
      out.push({p, it, need, days});
    }
  }
  return out.sort((a, b) => a.days - b.days || String(a.it.tag).localeCompare(String(b.it.tag)));
}

function renderPickup(){
  const card = document.getElementById('pickup-card');
  if (!card) return;
  const list = pickupList();
  if (!list.length){ card.innerHTML = `<div class="hd"><h3>Office pickups</h3></div><p class="small muted" style="padding:0 0 4px">Nothing at the office is wanted on site in the next ${PICKUP_HORIZON} days.</p>`; return; }
  const byProj = {};
  list.forEach(x => (byProj[x.p.id] = byProj[x.p.id] || {p: x.p, rows: []}).rows.push(x));
  const late = list.filter(x => x.days < 0).length;
  card.innerHTML = `
    <div class="hd"><h3>Office pickups</h3><span class="small muted">${list.length} box${list.length === 1 ? '' : 'es'} · ${Object.keys(byProj).length} stop${Object.keys(byProj).length === 1 ? '' : 's'}${late ? ` · <b class="bad">${late} already wanted on site</b>` : ''}</span></div>
    ${Object.values(byProj).map(({p, rows}) => `
      <div class="pick-stop">
        <div class="pick-hd"><b>${esc(p.project.name)}</b><span class="small muted">${esc(p.project.addr || '')}</span></div>
        ${rows.map(({it, need, days}) => `
          <label class="pick-row ${days < 0 ? 'late' : ''}">
            <input type="checkbox" data-pickup="${it.id}">
            <span class="pick-tag">${esc(it.tag || '—')}</span>
            <span class="pick-what"><b>${esc(it.name)}</b><span class="small muted">${[it.room, `${selQty(it)} ${SEL_UNIT_LABEL[it.unit] || it.unit}`, it.finish].filter(Boolean).map(esc).join(' · ')}</span></span>
            <span class="pick-when ${days < 0 ? 'bad' : days <= 2 ? 'warn' : ''}">${need ? (days < 0 ? `wanted ${-days}d ago` : days === 0 ? 'today' : days === 1 ? 'tomorrow' : `in ${days} days`) : 'no date'}</span>
          </label>`).join('')}
      </div>`).join('')}
    <p class="small muted" style="margin:10px 0 0">Ticking a box marks it delivered to the site and stamps today's date on the buyer's board. Nothing else to tell anyone.</p>`;
  card.querySelectorAll('[data-pickup]').forEach(cb => cb.onchange = () => {
    const it = selItem(cb.dataset.pickup); if (!it) return;
    selReceive(it, 'site');
    log(`${it.name}${it.tag ? ` (${it.tag})` : ''} taken to site`, 'manual', currentUser()?.name || DB.me || '');
    renderPickup(); if (view === 'proc') renderProc();
    toast(`${it.tag || it.name} → site`);
  });
}

/* ===================== hooks ===================== */
/* Selections, procurement and the two reports are all per-project, but the Purchasing group was never
   marked as one — so the project picker in the sub-bar was hidden and there was no way to change job
   from inside the module. Marking it fixes it everywhere in Purchasing at once, rather than bolting a
   second project dropdown onto one screen. */
(() => { const g = NAV_GROUPS.find(x => x.id === 'buy'); if (!g) return; g.views.unshift('sel', 'proc'); g.proj = true; })();
Object.assign(NAV_LABELS, {sel: 'Selections', proc: 'Procurement'});

const remindersBase_sel = reminders;
reminders = function(){
  const out = remindersBase_sel();
  try {
    if (!DB.sel) return out;
    const mine = selItems();
    const late = mine.filter(i => selLate(i) > 0);
    if (late.length) out.push({n: late.length, label: `past the order-by date — ${late.slice(0, 2).map(i => i.name).join(', ')}${late.length > 2 ? '…' : ''}`, go: {view: 'proc'}, sev: 'bad'});
    const red = mine.filter(selBlocked);
    if (red.length) out.push({n: red.length, label: 'selections with an unresolved red flag — the record and the vendor page disagree', go: {view: 'sel'}, sev: 'bad'});
    const soon = mine.filter(i => { const l = selLate(i); return l <= 0 && l > -7 && SEL_OPEN.includes(i.stage); });
    if (soon.length) out.push({n: soon.length, label: 'to order this week to hold the schedule', go: {view: 'proc'}, sev: 'warn'});
    const pick = pickupList();
    if (pick.length && ['owner', 'pm', 'coord', 'driver'].includes(role())) out.push({n: pick.length, label: `at the office and wanted on site within ${PICKUP_HORIZON} days — on the pickup run`, go: {view: 'route'}, sev: pick.some(x => x.days < 0) ? 'bad' : ''});
    const cl = claimsOpen();
    if (cl.length){
      const stale = cl.filter(c => dayDiff(c.raisedAt, today()) > 7);
      out.push({n: cl.length, label: `open vendor claim${cl.length === 1 ? '' : 's'} — damaged, short or wrong on arrival${stale.length ? `, ${stale.length} over a week old` : ''}`, go: {view: 'proc'}, sev: stale.length ? 'bad' : 'warn'});
    }
    const untagged = mine.filter(i => i.stage === 'office' && !i.tag);
    if (untagged.length) out.push({n: untagged.length, label: 'at the office without a tag — the site cannot be told what to look for', go: {view: 'proc'}, sev: 'warn'});
  } catch (e){}
  return out;
};

