/* ===================== RETURNS — money out, until it is money back =====================
   The failure Alan described is not a filing failure. It is that "the project problem is solved" and
   "the money came back" are two different events, and the system only ever recorded the first. The
   replacement arrives, the wall closes, everyone moves on, and a box sits in the office until the
   vendor's window shuts and the money is simply gone. Worse: to keep the job moving we buy the
   replacement BEFORE the return goes back, so the same item is paid for twice and nothing anywhere
   says so.

   So a return here is not a task with a tick box. It is an amount of the firm's money sitting in
   someone else's hands, with a deadline attached, and it stays on the books until a credit or a
   refund lands and is matched to a transaction. Four rules follow from that:

     1. A return is created the moment the reason exists, not when someone gets round to it. Damaged,
        wrong item, over-ordered, client changed their mind — each of those opens one automatically.
     2. The deadline is the vendor's return window measured from the day it was received, not from the
        day someone noticed. That is the number that actually expires.
     3. Shipping it back does not close it. Only money closes it — a credit, a refund, or a written-off
        decision with a name against it.
     4. Buying a replacement first is allowed and normal, and it is linked, so the double spend is a
        figure on the screen rather than a surprise in the job costs.
*/

const RET_REASONS = [
  ['damaged',     'Damaged on arrival',      'The vendor owes us; photograph it before it moves.'],
  ['wrong-item',  'Wrong item sent',         'Their error — full credit, and they usually pay the freight back.'],
  ['wrong-order', 'We ordered the wrong one', 'Our error — expect a restocking fee and check the window carefully.'],
  ['over-ordered', 'Over-ordered',           'Common on tile and trim. Whole boxes usually go back; opened ones usually do not.'],
  ['not-needed',  'No longer needed',        'Scope changed after it was bought.'],
  ['client-change', 'Client changed the selection', 'If it is our error the firm eats it; if it is a change order the client does.'],
];
const RET_REASON = Object.fromEntries(RET_REASONS.map(([k, l, why]) => [k, {k, label: l, why}]));

/* The pipeline. Note where the money is: it is out from the moment the return exists and it does not
   come back at "shipped". Only the last three states are money-neutral. */
const RET_STATES = [
  ['raise',     'RMA to request',    'out',  'Nothing has been asked of the vendor yet. This is where returns die.'],
  ['authorised', 'RMA in hand',      'out',  'Authorised. The clock is the return window, not the RMA.'],
  ['toship',    'Boxed, to go out',  'out',  'Sitting in the office. It goes out on the next run.'],
  ['shipped',   'Shipped back',      'out',  'On its way. Shipping it back is not getting paid.'],
  ['received',  'Vendor has it',     'out',  'They have it. Now chase the credit.'],
  ['credited',  'Credited',          'back', 'Credit issued. Match it to a statement line.'],
  ['refunded',  'Refunded',          'back', 'Money back on the card or in the account.'],
  ['written',   'Written off',       'lost', 'A decision, with a name and a reason against it.'],
];
const RET_STATE = Object.fromEntries(RET_STATES.map(([k, l, money, why]) => [k, {k, label: l, money, why}]));
const RET_OPEN = RET_STATES.filter(s => s[2] === 'out').map(s => s[0]);
const RET_DONE = ['credited', 'refunded', 'written'];

const RET_DEFAULT_WINDOW = 30;
const RET_WARN_DAYS = 7;                                   // start pushing
const RET_URGENT_DAYS = 3;                                 // it goes red

const RET_CFG = {window: RET_DEFAULT_WINDOW, restockPct: 20, chaseDays: 10};
// Read through a helper: this module is spliced into a file that loads long before DB exists.
const retCfg = () => (typeof DB !== 'undefined' && DB && DB.company && DB.company.returns) || RET_CFG;
function retInit(){
  DB.sel = DB.sel || {};
  DB.sel.returns = DB.sel.returns || [];
  DB.company.returns = Object.assign({}, RET_CFG, DB.company.returns || {});
  // Vendors differ, and the difference is the whole deadline.
  const pol = {'Ferguson': [30, 25], 'Build.com': [30, 0], 'House of Antique Hardware': [60, 15], 'Bedrosians': [30, 25], 'Circa Lighting': [30, 20], 'Diamond Appliances': [14, 25]};
  for (const [name, [w, rp]] of Object.entries(pol)){
    let v = DB.vendors.find(x => x.name === name);
    if (!v){ v = {id: uid('v'), name, trade: '', insuranceExp: '', bankChangedAt: ''}; DB.vendors.push(v); }
    if (v.returnWindow == null) v.returnWindow = w;
    if (v.restockPct == null) v.restockPct = rp;
  }
  try { retSeed(); } catch (e){ console.warn('returns seed', e); }
}

/* ---------- vendor policy ---------- */
function retVendor(name){
  const v = DB.vendors.find(x => x.name === name) || {};
  return {
    window: +v.returnWindow || retCfg().window,
    restockPct: v.restockPct != null ? +v.restockPct : retCfg().restockPct,
    returnsTo: v.returnsTo || '',
    name,
  };
}
const retList = () => (DB.sel.returns = DB.sel.returns || []);
const retOpen = () => retList().filter(r => RET_OPEN.includes(r.status));
const retFor = itemId => retList().filter(r => r.itemId === itemId);

/* ---------- the deadline that actually expires ---------- */
const retDaysLeft = r => r.returnBy ? dayDiff(today(), r.returnBy) : null;
function retRisk(r){
  if (!RET_OPEN.includes(r.status)) return {lvl: 0, label: '', cls: ''};
  const d = retDaysLeft(r);
  if (d == null) return {lvl: 1, label: 'no return-by date', cls: 'warn'};
  if (d < 0) return {lvl: 3, label: `window closed ${-d}d ago`, cls: 'bad'};
  if (d <= RET_URGENT_DAYS) return {lvl: 3, label: `${d}d left`, cls: 'bad'};
  if (d <= RET_WARN_DAYS) return {lvl: 2, label: `${d}d left`, cls: 'warn'};
  return {lvl: 0, label: `${d}d left`, cls: ''};
}
// Shipped back and still nothing? That is the other place money disappears.
function retChase(r){
  if (!['shipped', 'received'].includes(r.status)) return 0;
  const since = r.receivedAt || r.shippedAt;
  return since ? dayDiff(since, today()) : 0;
}

/* ---------- money ---------- */
const retValue = r => r2((+r.qty || 0) * (+r.unitCost || 0));
const retExpected = r => r2(retValue(r) * (1 - (+r.restockPct || 0) / 100) + (+r.freightBack ? -(+r.freightBack) : 0));
const retRecovered = r => r2(+r.recovered || 0);
const retShortfall = r => RET_DONE.includes(r.status) ? r2(retValue(r) - retRecovered(r)) : 0;
// Everything the firm is currently owed, or has quietly lost.
function retExposure(projectId){
  const rows = retList().filter(r => !projectId || r.projectId === projectId);
  const open = rows.filter(r => RET_OPEN.includes(r.status));
  const lost = rows.filter(r => r.status === 'written');
  const shortfalls = rows.filter(r => RET_DONE.includes(r.status)).reduce((a, r) => a + retShortfall(r), 0);
  return {
    open: open.length,
    outstanding: r2(open.reduce((a, r) => a + retExpected(r), 0)),
    expired: open.filter(r => retRisk(r).lvl === 3 && (retDaysLeft(r) ?? 0) < 0),
    closing: open.filter(r => { const d = retDaysLeft(r); return d != null && d >= 0 && d <= RET_WARN_DAYS; }),
    unshipped: open.filter(r => ['raise', 'authorised', 'toship'].includes(r.status)),
    awaitingCredit: open.filter(r => ['shipped', 'received'].includes(r.status)),
    writtenOff: r2(lost.reduce((a, r) => a + retValue(r), 0)),
    shortfall: r2(shortfalls),
    doubleSpent: r2(open.filter(r => r.replacementItemId).reduce((a, r) => a + retValue(r), 0)),
  };
}

/* ---------- creating one ---------- */
function retRaise(it, o){
  o = o || {};
  const pol = retVendor(it.vendor);
  const received = it.dates?.office || today();
  const r = {
    id: uid('rt'), itemId: it.id, projectId: it.projectId,
    vendor: it.vendor || '', manufacturer: it.manufacturer || '', sku: it.sku || '', name: it.name || '',
    reason: o.reason || 'damaged',
    qty: o.qty != null ? +o.qty : selQty(it),
    unitCost: o.unitCost != null ? +o.unitCost : selCost(it),
    raisedAt: today(), by: currentUser()?.name || DB.me || '',
    receivedOn: received,
    window: o.window != null ? +o.window : pol.window,
    returnBy: addDays(received, o.window != null ? +o.window : pol.window),
    restockPct: o.restockPct != null ? +o.restockPct : (['damaged', 'wrong-item'].includes(o.reason) ? 0 : pol.restockPct),
    freightBack: 0,
    expect: o.expect || (['damaged', 'wrong-item'].includes(o.reason) ? 'replacement' : 'refund'),
    status: 'raise', rma: '', rmaAt: '', shippedAt: '', carrier: '', tracking: '', receivedAt: '',
    location: it.tag ? `Office · ${it.tag}` : 'Office',
    recovered: 0, recoveredAt: '', txnRef: '',
    replacementItemId: o.replacementItemId || '', claimId: o.claimId || '',
    owner: o.owner || currentUser()?.name || DB.me || '',
    note: o.note || '', writeOff: null,
    history: [{at: today(), status: 'raise', by: currentUser()?.name || DB.me || '', note: o.note || ''}],
  };
  r.returnBy = iso(r.returnBy);
  retList().unshift(r);
  audit('sel-return', r.id, 'raised', null, {item: r.name, vendor: r.vendor, value: retValue(r), returnBy: r.returnBy});
  log(`Return raised — ${r.name} to ${r.vendor || 'vendor'}, ${money(retValue(r))}, window closes ${fmt(r.returnBy)}`);
  save();
  return r;
}
function retSet(r, status, o){
  o = o || {};
  const was = r.status;
  r.status = status;
  ['rma', 'carrier', 'tracking', 'txnRef', 'owner', 'location'].forEach(k => { if (o[k] !== undefined && o[k] !== '') r[k] = o[k]; });
  if (o.recovered !== undefined && o.recovered !== '') r.recovered = +o.recovered || 0;
  if (o.restockPct !== undefined && o.restockPct !== '') r.restockPct = +o.restockPct;
  if (status === 'authorised' && !r.rmaAt) r.rmaAt = today();
  if (status === 'shipped' && !r.shippedAt) r.shippedAt = today();
  if (status === 'received' && !r.receivedAt) r.receivedAt = today();
  if (['credited', 'refunded'].includes(status) && !r.recoveredAt) r.recoveredAt = today();
  r.history.push({at: today(), status, by: currentUser()?.name || DB.me || '', note: o.note || ''});
  audit('sel-return', r.id, status, {status: was}, o);
  if (['credited', 'refunded'].includes(status)) log(`Return recovered — ${r.name}, ${money(retRecovered(r))} from ${r.vendor}${retShortfall(r) > 0 ? ` (${money(retShortfall(r))} short of what we paid)` : ''}`);
  save();
}
function retWriteOff(r, why, amount){
  r.writeOff = {at: today(), by: currentUser()?.name || DB.me || '', why, amount: amount != null ? +amount : retValue(r)};
  retSet(r, 'written', {note: why});
  log(`Return written off — ${r.name}, ${money(r.writeOff.amount)} lost. ${why}`);
}

/* ---------- the buy-ahead link ----------
   "We had to buy it again to keep the job moving." Fine — but the new item is created FROM the return,
   so the two are joined and the double spend is a number rather than a discovery in the job costs. */
function retBuyReplacement(r){
  const orig = selItem(r.itemId);
  if (!orig) return null;
  const it = selNew({
    projectId: orig.projectId, room: orig.room, name: orig.name, desc: orig.desc,
    qty: r.qty, unit: orig.unit, cost: orig.cost, markupPct: orig.markupPct,
    vendor: orig.vendor, manufacturer: orig.manufacturer, sku: orig.sku, finish: orig.finish, dims: orig.dims,
    url: orig.url, img: orig.img, leadDays: orig.leadDays, needOnSite: orig.needOnSite,
    taskId: orig.taskId, when: orig.when, fm: orig.fm, category: orig.category,
    clip: orig.clip, stage: 'appr', replacesReturnId: r.id,
    notes: `Bought to keep the job moving while ${r.name} goes back to ${r.vendor}. The original is return ${r.id}.`,
  });
  r.replacementItemId = it.id;
  r.history.push({at: today(), status: r.status, by: currentUser()?.name || DB.me || '', note: 'Replacement bought ahead of the credit.'});
  audit('sel-return', r.id, 'replacement-bought', null, {itemId: it.id});
  log(`Replacement bought ahead of the credit — ${it.name}. ${money(retValue(r))} is now paid twice until ${r.vendor} credits us.`);
  save();
  return it;
}

/* ---------- automation: returns are created by events, not by remembering ---------- */
// A claim that is not going to be replaced in place needs the thing to physically go back.
const selRaiseClaimBase_ret = typeof selRaiseClaim === 'function' ? selRaiseClaim : null;
if (selRaiseClaimBase_ret){
  selRaiseClaim = function(it, kind, o){
    const c = selRaiseClaimBase_ret(it, kind, o);
    if (['damaged', 'wrong'].includes(kind) && !retFor(it.id).some(r => RET_OPEN.includes(r.status))){
      retRaise(it, {reason: kind === 'wrong' ? 'wrong-item' : 'damaged', qty: c.qty || selQty(it), claimId: c.id,
                    note: `Opened from the ${SEL_COND[kind].label.toLowerCase()} claim on arrival.`});
    }
    return c;
  };
}

/* ---------- checks on the item ---------- */
const selVerifyLocalBase_ret = selVerifyLocal;
selVerifyLocal = function(it){
  const raised = selVerifyLocalBase_ret(it);
  try {
    for (const r of retFor(it.id)){
      if (RET_OPEN.includes(r.status)){
        const risk = retRisk(r);
        const d = retDaysLeft(r);
        raised.push(selCheck(it, risk.lvl >= 3 ? 3 : 2, 'return',
          d != null && d < 0 ? `Return window closed — ${money(retValue(r))} at risk` : `To go back to ${r.vendor} — ${money(retValue(r))}, ${risk.label}`,
          `${RET_REASON[r.reason].label}. ${RET_STATE[r.status].why}${r.replacementItemId ? ' A replacement was already bought, so this amount is currently paid twice.' : ''}`,
          `return:${r.id}`));
      }
    }
    (it.checks || []).forEach(c => {
      if (c.field === 'return' && String(c.key).startsWith('return:')){
        const r = retList().find(x => x.id === c.key.slice(7));
        if (!r || !RET_OPEN.includes(r.status)) c.cleared = true;
      }
    });
    if (it.replacesReturnId){
      const r = retList().find(x => x.id === it.replacesReturnId);
      if (r && RET_OPEN.includes(r.status))
        raised.push(selCheck(it, 1, 'return', `Replaces an item still owed back to ${r.vendor}`,
          `${money(retValue(r))} is paid twice until that return is credited. It is ${RET_STATE[r.status].label.toLowerCase()}.`, `replaces:${r.id}`));
    }
  } catch (e){}
  return raised;
};

/* ---------- seed: the four shapes this exists to stop ---------- */
function retSeed(){
  if (DB.__retSeeded || !DB.sel || !DB.sel.items || !DB.sel.items.length) return;
  DB.__retSeeded = 1;
  const byName = n => DB.sel.items.find(i => (i.name || '').includes(n));
  const mk = (o) => { const r = Object.assign({
    id: uid('rt'), raisedAt: o.receivedOn, by: 'Chen', freightBack: 0, rma: '', rmaAt: '', shippedAt: '', carrier: '', tracking: '',
    receivedAt: '', recovered: 0, recoveredAt: '', txnRef: '', replacementItemId: '', claimId: '', owner: 'Chen', writeOff: null,
    location: 'Office', history: [{at: o.receivedOn, status: 'raise', by: 'Chen', note: o.note || ''}],
  }, o); r.returnBy = iso(addDays(r.receivedOn, r.window)); retList().push(r); return r; };

  // 1. The one that sat in the office until the window shut. This is the whole complaint.
  const a = byName('Zellige');
  if (a) mk({itemId: a.id, projectId: a.projectId, vendor: 'Bedrosians', manufacturer: 'Zellige', sku: '', name: '38 sq ft over-ordered zellige',
    reason: 'over-ordered', qty: 38, unitCost: 14.5, receivedOn: iso(addDays(today(), -74)), window: 30, restockPct: 25,
    expect: 'refund', status: 'raise', note: 'Four boxes never opened. Nobody asked for an RMA.'});

  // 2. The one where we bought it again to keep moving, and the first one is still ours.
  const b2 = byName('Widespread lavatory faucet');
  if (b2){
    const r = mk({itemId: b2.id, projectId: b2.projectId, vendor: 'Ferguson', manufacturer: 'Waterworks', sku: 'RGLS02-CH', name: 'Lavatory faucet — chrome sent, brass ordered',
      reason: 'wrong-item', qty: 2, unitCost: 940, receivedOn: iso(addDays(today(), -19)), window: 30, restockPct: 0,
      expect: 'refund', status: 'authorised', rma: 'RMA-44812', rmaAt: iso(addDays(today(), -12)),
      note: 'Their picking error. Brass re-ordered the same day so the bath could close.'});
    r.history.push({at: r.rmaAt, status: 'authorised', by: 'Chen', note: 'Dana issued the RMA and a prepaid label.'});
    const rep = DB.sel.items.find(i => i.sku === 'RGLS02-WB');
    if (rep){ r.replacementItemId = rep.id; rep.replacesReturnId = r.id; }
  }

  // 3. Gone back weeks ago; the credit never appeared. The second place money vanishes.
  const c = byName('Brass cabinet cup pulls');
  if (c) mk({itemId: c.id, projectId: c.projectId, vendor: 'House of Antique Hardware', manufacturer: 'HAH', sku: '', name: '8 surplus cup pulls',
    reason: 'over-ordered', qty: 8, unitCost: 18.5, receivedOn: iso(addDays(today(), -46)), window: 60, restockPct: 15,
    expect: 'credit', status: 'shipped', rma: 'HAH-7712', rmaAt: iso(addDays(today(), -31)), shippedAt: iso(addDays(today(), -27)),
    carrier: 'UPS', tracking: '1Z44R8110399', note: 'Sent back four weeks ago. No credit on the statement yet.'});

  // 4. One that closed properly — and still came back short, because restocking is a real cost.
  const d = byName('Porcelain field tile');
  if (d) mk({itemId: d.id, projectId: d.projectId, vendor: 'Bedrosians', manufacturer: 'Bedrosians', sku: '', name: '24 sq ft surplus porcelain',
    reason: 'over-ordered', qty: 24, unitCost: 9.4, receivedOn: iso(addDays(today(), -88)), window: 30, restockPct: 25,
    expect: 'credit', status: 'credited', rma: 'BD-2214', shippedAt: iso(addDays(today(), -70)), receivedAt: iso(addDays(today(), -64)),
    recovered: 169.2, recoveredAt: iso(addDays(today(), -55)), txnRef: 'CM-8841', note: 'Credited less 25% restocking.'});

  // The board should open already showing what is owed back, not wait for someone to press Verify.
  const touched = new Set(retList().map(r => r.itemId).concat(DB.sel.items.filter(i => i.replacesReturnId).map(i => i.id)));
  touched.forEach(id => { const it = selItem(id); if (it) try { selVerifyLocal(it); } catch (e){} });
}

/* ===================== the returns screen ===================== */
// Returns default to every project. The money is the firm's, not the job's, and a box in the office
// belongs to whoever is standing next to it — filtering it to the project someone happens to have open
// is how it stops being anybody's problem.
let retFilter = 'open', retSort = 'urgency', retAllProjects = true;

function retRows(){
  let rows = retList().filter(r => retAllProjects || r.projectId === S.id);
  if (retFilter === 'open') rows = rows.filter(r => RET_OPEN.includes(r.status));
  else if (retFilter === 'risk') rows = rows.filter(r => RET_OPEN.includes(r.status) && retRisk(r).lvl >= 2);
  else if (retFilter === 'office') rows = rows.filter(r => ['raise', 'authorised', 'toship'].includes(r.status));
  else if (retFilter === 'chase') rows = rows.filter(r => ['shipped', 'received'].includes(r.status));
  else if (retFilter === 'done') rows = rows.filter(r => RET_DONE.includes(r.status));
  const key = r => retSort === 'value' ? -retValue(r) : retSort === 'vendor' ? r.vendor : (retDaysLeft(r) ?? 9999);
  return rows.sort((a, b) => { const x = key(a), y = key(b); return typeof x === 'number' ? x - y : String(x).localeCompare(String(y)); });
}

function retModal(){
  const E = retExposure(retAllProjects ? null : S.id);
  const proj = id => (DB.projects.find(p => p.id === id) || {project: {}}).project.name || '';
  const rows = retRows();
  const nextAction = r => ({
    raise: 'Ask the vendor for an RMA',
    authorised: 'Box it and put it on the next run',
    toship: 'Goes out on the next run',
    shipped: 'Chase the credit',
    received: 'Chase the credit',
  })[r.status] || '';

  mbModal('Returns', `
    <p class="small muted" style="margin:0 0 10px">A return is money of ours sitting in someone else's hands with a deadline on it. Shipping it back does not close it — only a credit, a refund, or a written-off decision with a name against it does.</p>

    <div class="sel-stats" style="margin:0 0 12px">
      <div class="sel-stat ${E.outstanding ? 'warn' : ''}"><b>${money(E.outstanding)}</b><span>owed back to us${E.open ? ` · ${E.open} open` : ''}</span></div>
      <div class="sel-stat ${E.expired.length ? 'bad' : ''}"><b>${E.expired.length}</b><span>past the return window</span></div>
      <div class="sel-stat ${E.closing.length ? 'warn' : ''}"><b>${E.closing.length}</b><span>window closes within ${RET_WARN_DAYS} days</span></div>
      <div class="sel-stat ${E.doubleSpent ? 'bad' : ''}"><b>${money(E.doubleSpent)}</b><span>paid twice — replacement bought first</span></div>
      <div class="sel-stat ${E.writtenOff ? 'bad' : ''}"><b>${money(E.writtenOff + E.shortfall)}</b><span>never came back</span></div>
    </div>

    ${E.expired.length ? `<div class="note bad" style="margin-bottom:10px"><b>${E.expired.length} return${E.expired.length === 1 ? ' is' : 's are'} past the vendor's window.</b> ${esc(E.expired.slice(0, 3).map(r => `${r.name} — ${r.vendor}, ${money(retValue(r))}`).join('; '))}. Call them anyway: a window is a policy, not a law, and vendors bend it for a firm that buys. If they will not, write it off deliberately so it lands in the job cost rather than vanishing.</div>` : ''}
    ${E.unshipped.length ? `<div class="note warn" style="margin-bottom:10px"><b>${E.unshipped.length} box${E.unshipped.length === 1 ? '' : 'es'} still in the office</b> — ${money(E.unshipped.reduce((a, r) => a + retValue(r), 0))}. They go out on the next run; the driver's sheet lists them.</div>` : ''}
    ${E.awaitingCredit.filter(r => retChase(r) > retCfg().chaseDays).length ? `<div class="note warn" style="margin-bottom:10px"><b>Sent back and still not credited:</b> ${esc(E.awaitingCredit.filter(r => retChase(r) > retCfg().chaseDays).map(r => `${r.vendor} — ${money(retExpected(r))}, ${retChase(r)} days`).join('; '))}.</div>` : ''}

    <div class="proc-bar ret-bar" style="margin-bottom:8px">
      <div class="proc-filters">${[['open', 'Open'], ['risk', 'At risk'], ['office', 'In the office'], ['chase', 'Awaiting credit'], ['done', 'Closed'], ['all', 'Everything']].map(([k, l]) => `<button class="${retFilter === k ? 'on' : ''}" data-rf="${k}">${l}</button>`).join('')}</div>
      <select id="ret-sort"><option value="urgency" ${retSort === 'urgency' ? 'selected' : ''}>By deadline</option><option value="value" ${retSort === 'value' ? 'selected' : ''}>By value</option><option value="vendor" ${retSort === 'vendor' ? 'selected' : ''}>By vendor</option></select>
      <label class="sel-toggle"><input type="checkbox" id="ret-all" ${retAllProjects ? 'checked' : ''}> Every project</label>
      <span class="small muted">${retAllProjects ? 'showing every job' : esc(S.project.name) + ' only'}</span>
    </div>

    <div class="proc-wrap"><table class="t ret-t">
      <thead><tr><th>Item</th><th>Where it is</th><th>Why</th><th class="money">Value</th><th class="money">Expect back</th><th>Window</th><th>State</th><th>Next</th><th></th></tr></thead>
      <tbody>${rows.map(r => { const risk = retRisk(r); const it = selItem(r.itemId); return `<tr class="${risk.lvl >= 3 ? 'proc-late' : ''}">
        <td><b>${esc(r.name)}</b><div class="small muted">${esc(r.vendor)}${r.sku ? ` · ${esc(r.sku)}` : ''} · ${r.qty} ${it ? SEL_UNIT_LABEL[it.unit] || it.unit : ''}</div>${retAllProjects ? `<div class="small muted">${esc(proj(r.projectId))}</div>` : ''}${r.replacementItemId ? '<div class="small bad">replacement already bought</div>' : ''}</td>
        <td class="small">${esc(r.location || '—')}${r.tracking ? `<div class="small muted">${esc(r.carrier)} ${esc(r.tracking)}</div>` : ''}</td>
        <td class="small">${esc(RET_REASON[r.reason].label)}</td>
        <td class="money">${money(retValue(r))}</td>
        <td class="money">${money(retExpected(r))}${r.restockPct ? `<div class="small muted">${r.restockPct}% restock</div>` : ''}</td>
        <td class="small ${risk.cls}">${r.returnBy ? fmt(r.returnBy) : '—'}${risk.label ? `<div class="small ${risk.cls}">${esc(risk.label)}</div>` : ''}</td>
        <td class="small">${esc(RET_STATE[r.status].label)}${RET_DONE.includes(r.status) ? `<div class="small ${retShortfall(r) > 0 ? 'bad' : 'ok'}">${retRecovered(r) ? money(retRecovered(r)) + ' back' : ''}${retShortfall(r) > 0 ? ` · ${money(retShortfall(r))} short` : ''}</div>` : ''}${['shipped', 'received'].includes(r.status) && retChase(r) ? `<div class="small ${retChase(r) > retCfg().chaseDays ? 'bad' : 'muted'}">${retChase(r)}d</div>` : ''}</td>
        <td class="small muted">${esc(nextAction(r))}</td>
        <td class="nowrap"><button class="btn sm" data-ret="${r.id}">Open</button></td>
      </tr>`; }).join('') || '<tr><td colspan="9" class="empty">Nothing here.</td></tr>'}</tbody>
    </table></div>
    <p class="small muted" style="margin:10px 0 0">The return window runs from the day it was received, not the day someone noticed — that is the date that actually expires. Restocking is assumed at the vendor's rate, and at zero when the fault was theirs.</p>`,
    {submit: null});
  procWide(1120);
  const m = document.getElementById('mbm'); if (!m) return;
  m.querySelectorAll('[data-rf]').forEach(b => b.onclick = () => { retFilter = b.dataset.rf; mbCloseModal(); retModal(); });
  m.querySelector('#ret-sort').onchange = e => { retSort = e.target.value; mbCloseModal(); retModal(); };
  m.querySelector('#ret-all').onchange = e => { retAllProjects = e.target.checked; mbCloseModal(); retModal(); };
  m.querySelectorAll('[data-ret]').forEach(b => b.onclick = () => { const r = retList().find(x => x.id === b.dataset.ret); mbCloseModal(); retOne(r); });
}

function retOne(r){
  if (!r) return;
  const it = selItem(r.itemId);
  const risk = retRisk(r);
  const rep = r.replacementItemId ? selItem(r.replacementItemId) : null;
  mbModal(`Return — ${esc(r.name)}`, `
    <div class="ret-head">
      <div><span class="muted small">Value out</span><b>${money(retValue(r))}</b></div>
      <div><span class="muted small">Expect back</span><b>${money(retExpected(r))}</b></div>
      <div><span class="muted small">Window closes</span><b class="${risk.cls}">${r.returnBy ? fmt(r.returnBy) : '—'}</b><span class="small ${risk.cls}">${esc(risk.label)}</span></div>
      <div><span class="muted small">Owner</span><b>${esc(r.owner || '—')}</b></div>
    </div>
    <p class="small muted" style="margin:10px 0">${esc(RET_REASON[r.reason].label)} — ${esc(RET_REASON[r.reason].why)} Received ${fmt(r.receivedOn)}, ${r.window}-day window at ${esc(r.vendor)}.${r.note ? ' ' + esc(r.note) : ''}</p>
    ${rep ? `<div class="note bad"><b>${money(retValue(r))} is paid twice right now.</b> ${esc(rep.name)} was bought to keep the job moving. That stops the moment this is credited.</div>`
          : RET_OPEN.includes(r.status) && it && SEL_OPEN.includes(it.stage) === false ? `<div class="note"><b>Need it on site before the credit comes?</b> Buy the replacement from here and the two stay joined, so the double spend shows as a number instead of turning up in the job costs.</div>` : ''}

    <ul class="sel-findings" style="margin:10px 0">${r.history.map(h => `<li class="info"><b>${esc(RET_STATE[h.status] ? RET_STATE[h.status].label : h.status)}</b> <span class="small muted">${fmt(h.at)} · ${esc(h.by)}</span>${h.note ? `<div class="small muted">${esc(h.note)}</div>` : ''}</li>`).join('')}</ul>

    <div class="f"><label>Move it to</label><select data-f="status">${RET_STATES.map(([k, l, mo]) => `<option value="${k}" ${r.status === k ? 'selected' : ''}>${l}${mo === 'back' ? ' — money back' : mo === 'lost' ? ' — money lost' : ''}</option>`).join('')}</select></div>
    <div class="grid2">
      <div class="f"><label>RMA / authorisation</label><input data-f="rma" value="${esc(r.rma)}" placeholder="RMA-44812"></div>
      <div class="f"><label>Where it is</label><input data-f="location" value="${esc(r.location)}" placeholder="Office · shelf 3"></div>
    </div>
    <div class="grid2">
      <div class="f"><label>Carrier back</label><input data-f="carrier" value="${esc(r.carrier)}" placeholder="UPS · vendor's label"></div>
      <div class="f"><label>Tracking</label><input data-f="tracking" value="${esc(r.tracking)}"></div>
    </div>
    <div class="grid3">
      <div class="f"><label>Restocking %</label><input data-f="restockPct" type="number" step="1" value="${r.restockPct}"></div>
      <div class="f"><label>Amount recovered</label><input data-f="recovered" type="number" step="0.01" value="${r.recovered || ''}"></div>
      <div class="f"><label>Credit / refund reference</label><input data-f="txnRef" value="${esc(r.txnRef)}" placeholder="CM-8841 · card ••4412"></div>
    </div>
    <div class="f"><label>Note</label><textarea data-f="note" rows="2" placeholder="Dana issued RMA-44812, prepaid label emailed. Credit on the next statement."></textarea></div>

    <div class="sel-drawer-acts">
      ${!rep && it ? `<button class="btn" data-act="rebuy">Buy a replacement now</button>` : ''}
      ${RET_OPEN.includes(r.status) ? `<button class="btn" data-act="writeoff">Write it off</button>` : ''}
      ${it ? `<button class="btn" data-act="item">Open the item</button>` : ''}
    </div>
    <p class="small muted" style="margin:10px 0 0">Marking it credited or refunded is what closes it, and the amount is compared against what we paid — the difference is a real cost and lands on the vendor's record.</p>`,
    {submit: 'Update the return', onSubmit: f => {
      retSet(r, f.status, f);
      if (it) selVerifyLocal(it);
      renderProc();
      const back = ['credited', 'refunded'].includes(f.status);
      toast(back ? (retShortfall(r) > 0 ? `Closed — ${money(retRecovered(r))} back, ${money(retShortfall(r))} short of what we paid` : `Closed — ${money(retRecovered(r))} back`) : 'Return updated');
    }});
  procWide(760);
  const m = document.getElementById('mbm'); if (!m) return;
  m.querySelectorAll('[data-act]').forEach(b => b.onclick = () => {
    const a = b.dataset.act;
    if (a === 'rebuy'){ const nb = retBuyReplacement(r); mbCloseModal(); renderProc(); if (nb) selOpenItem(nb.id); toast(`${money(retValue(r))} now paid twice until ${r.vendor} credits us — it is on the returns screen`); return; }
    if (a === 'item'){ mbCloseModal(); selOpenItem(r.itemId); return; }
    if (a === 'writeoff'){ mbCloseModal(); retWriteOffModal(r); return; }
  });
}

function retWriteOffModal(r){
  mbModal('Write off a return', `
    <p class="small muted" style="margin:0 0 10px">Writing it off is a decision, not a drift. ${money(retValue(r))} lands on ${esc(selProject(selItem(r.itemId) || {projectId: r.projectId}).project.name)} as a cost, with your name and your reason against it, and it counts against ${esc(r.vendor)} on their record.</p>
    <div class="f"><label>Why is the money not coming back?</label><textarea data-f="why" rows="3" placeholder="Window closed in June; Bedrosians will not take opened boxes and would not make an exception. 22 sq ft of zellige, kept for the next job."></textarea></div>
    <div class="f"><label>Amount to write off</label><input data-f="amount" type="number" step="0.01" value="${retValue(r)}"></div>`,
    {submit: 'Write it off', onSubmit: f => {
      if (!f.why || f.why.length < 12){ toast('A sentence, so the next person knows'); return false; }
      retWriteOff(r, f.why, f.amount);
      const it = selItem(r.itemId); if (it) selVerifyLocal(it);
      renderProc(); toast(`${money(f.amount)} written off`);
    }});
}

/* ---------- the outbound half of the driver's run ---------- */
const renderPickupBase_ret = typeof renderPickup === 'function' ? renderPickup : null;
if (renderPickupBase_ret){
  renderPickup = function(){
    renderPickupBase_ret();
    const card = document.getElementById('pickup-card');
    if (!card) return;
    const out = retList().filter(r => ['authorised', 'toship'].includes(r.status));
    if (!out.length) return;
    const val = out.reduce((a, r) => a + retValue(r), 0);
    card.insertAdjacentHTML('beforeend', `
      <div class="pick-stop pick-out">
        <div class="pick-hd"><b>Going back</b><span class="small muted">${out.length} box${out.length === 1 ? '' : 'es'} · ${money(val)} of ours until they are gone</span></div>
        ${out.map(r => { const risk = retRisk(r); return `<label class="pick-row ${risk.lvl >= 3 ? 'late' : ''}">
          <input type="checkbox" data-shipped="${r.id}">
          <span class="pick-tag">${esc((r.location || '').split('·').pop().trim() || '—')}</span>
          <span class="pick-what"><b>${esc(r.name)}</b><span class="small muted">back to ${esc(r.vendor)}${r.rma ? ` · ${esc(r.rma)}` : ' · no RMA yet'} · ${money(retValue(r))}</span></span>
          <span class="pick-when ${risk.cls}">${esc(risk.label || '')}</span></label>`; }).join('')}
        <p class="small muted" style="margin:6px 0 0">Ticking one marks it shipped back. It is still our money until the credit lands.</p>
      </div>`);
    card.querySelectorAll('[data-shipped]').forEach(cb => cb.onchange = () => {
      const r = retList().find(x => x.id === cb.dataset.shipped); if (!r) return;
      if (!r.rma){ toast(`${r.vendor} has not given an RMA — most vendors refuse a return without one`); cb.checked = false; return; }
      retSet(r, 'shipped', {note: 'Handed over on the run.'});
      renderPickup(); if (view === 'proc') renderProc();
      toast(`${r.name} on its way back — ${money(retExpected(r))} to chase`);
    });
  };
}

/* ---------- the brief ---------- */
const remindersBase_ret = reminders;
reminders = function(){
  const out = remindersBase_ret();
  try {
    const E = retExposure(null);
    if (E.expired.length) out.push({n: E.expired.length, label: `return${E.expired.length === 1 ? '' : 's'} past the vendor's window — ${money(E.expired.reduce((a, r) => a + retValue(r), 0))} at risk`, go: {view: 'proc'}, sev: 'bad'});
    if (E.closing.length) out.push({n: E.closing.length, label: `return window${E.closing.length === 1 ? '' : 's'} closing within ${RET_WARN_DAYS} days — ${money(E.closing.reduce((a, r) => a + retValue(r), 0))}`, go: {view: 'proc'}, sev: 'warn'});
    const stale = E.awaitingCredit.filter(r => retChase(r) > retCfg().chaseDays);
    if (stale.length) out.push({n: stale.length, label: `sent back and still not credited — ${money(stale.reduce((a, r) => a + retExpected(r), 0))}`, go: {view: 'proc'}, sev: 'warn'});
    if (E.unshipped.length) out.push({n: E.unshipped.length, label: `return${E.unshipped.length === 1 ? '' : 's'} sitting in the office — ${money(E.unshipped.reduce((a, r) => a + retValue(r), 0))} not moving`, go: {view: 'route'}, sev: E.unshipped.some(r => retRisk(r).lvl >= 2) ? 'bad' : 'warn'});
    if (E.doubleSpent) out.push({n: 1, label: `${money(E.doubleSpent)} paid twice — replacements bought before the credit came back`, go: {view: 'proc'}, sev: 'warn'});
  } catch (e){}
  return out;
};

/* ---------- vendor scorecard: do they actually pay us back? ---------- */
const selVendorStatsBase_ret = selVendorStats;
selVendorStats = function(){
  const stats = selVendorStatsBase_ret();
  for (const r of retList()){
    const V = stats[r.vendor] = stats[r.vendor] || {vendor: r.vendor, items: 0, spend: 0, leads: [], quoted: [], onTime: 0, onTimeOf: 0,
      budget: 0, actual: 0, priced: 0, receipts: 0, clean: 0, cats: {}, makes: {}, lead: null, leadN: 0, quotedLead: null, drift: null,
      onTimePct: null, intactPct: null, savedPct: null, saved: 0, openClaims: 0, claimDays: null, claimsRaised: 0};
    V.returns = (V.returns || 0) + 1;
    if (RET_DONE.includes(r.status)){
      V.retClosed = (V.retClosed || 0) + 1;
      V.retPaid = r2((V.retPaid || 0) + retValue(r));
      V.retBack = r2((V.retBack || 0) + retRecovered(r));
      if (r.recoveredAt) (V.retDays = V.retDays || []).push(dayDiff(r.raisedAt, r.recoveredAt));
    } else V.retOpenValue = r2((V.retOpenValue || 0) + retValue(r));
  }
  for (const V of Object.values(stats)){
    V.recoveryPct = V.retPaid ? Math.round((V.retBack / V.retPaid) * 100) : null;
    V.creditDays = V.retDays && V.retDays.length ? V.retDays.slice().sort((a, b) => a - b)[Math.floor(V.retDays.length / 2)] : null;
  }
  return stats;
};

