/* ---------- hooks ---------- */
// Banking should not show a vendor credit as an ordinary uncategorised deposit.
if (typeof txnState === 'function'){
  const txnStateBase_rm = txnState;
  txnState = function(t){
    const st = txnStateBase_rm(t);
    try {
      if (t.amt > 0 && !t.retId && (t.cat === 'uncat' || !t.cat)){
        if (rmProposals().some(p => p.t.id === t.id)) return {sev: 2, msg: 'Looks like a vendor credit — confirm it against a return'};
        if (rmOrphans().some(x => x.id === t.id)) return {sev: 1, msg: 'Money in from a vendor with no return behind it'};
      }
      if (t.retId && t.cat === 'refund') return {sev: 0};
    } catch (e){}
    return st;
  };
}

const remindersBase_rm = reminders;
reminders = function(){
  const out = remindersBase_rm();
  try {
    const p = rmProposals();
    if (p.length) out.push({n: p.length, label: `credit${p.length === 1 ? '' : 's'} landed against a return — confirm to close ${money(p.reduce((a, x) => a + (+x.t.amt || 0), 0))}`, go: {view: 'proc'}, sev: ''});
    const o = rmOrphans();
    if (o.length) out.push({n: o.length, label: `money in from a vendor with no return behind it — ${money(o.reduce((a, t) => a + (+t.amt || 0), 0))}`, go: {view: 'bank'}, sev: 'warn'});
  } catch (e){}
  return out;
};

const retModalBase_rm = retModal;
retModal = function(){
  retModalBase_rm();
  const m = document.getElementById('mbm'); if (!m) return;
  const p = rmProposals();
  const bd = m.querySelector('.mbm-bd'); if (!bd) return;
  bd.insertAdjacentHTML('afterbegin', p.length
    ? `<div class="note ok" style="margin-bottom:10px"><b>${p.length} credit${p.length === 1 ? ' has' : 's have'} landed</b> — ${money(p.reduce((a, x) => a + (+x.t.amt || 0), 0))} matched to returns and waiting on you. <button class="btn sm" id="rm-open" style="margin-left:6px">Confirm them</button></div>`
    : '');
  m.querySelector('#rm-open')?.addEventListener('click', () => { mbCloseModal(); rmModal(); });
};

const renderProcBase_rm = renderProc;
renderProc = function(){
  renderProcBase_rm();
  const acts = document.querySelector('#proc-body .ph .acts');
  if (!acts || document.getElementById('proc-credits')) return;
  const p = rmProposals();
  if (!p.length) return;
  const b = document.createElement('button');
  b.className = 'btn primary';
  b.id = 'proc-credits';
  b.textContent = `Credits to confirm · ${p.length}`;
  b.onclick = () => rmModal();
  acts.insertBefore(b, acts.firstChild);
};

/* ---------- seed: the money actually arrives ---------- */
function rmSeed(){
  if (DB.__rmSeeded || !DB.sel || !DB.sel.returns || !DB.sel.returns.length) return;
  DB.__rmSeeded = 1;
  const card = (DB.accounts || []).find(a => a.type === 'card') || (DB.accounts || [])[0];
  if (!card) return;
  const T = (id, date, desc, amt, x) => DB.txns.push(Object.assign({id, date, acct: card.id, desc, amt, cat: 'uncat', projectId: '', code: '', vendor: '', memo: '', receipt: '', status: 'new', actor: '', source: 'seed', line: ''}, x || {}));

  // The credit for the pulls that went back a month ago, sitting unnoticed on the card statement.
  const hah = DB.sel.returns.find(r => r.vendor === 'House of Antique Hardware' && r.status === 'shipped');
  if (hah) T('tcr1', iso(addDays(today(), -3)), 'HOUSE OF ANTIQUE HDW CREDIT', retExpected(hah));

  // And one nobody was expecting: Bedrosians finally credited something from a previous job.
  T('tcr2', iso(addDays(today(), -9)), 'BEDROSIANS TILE CREDIT MEMO', 214.5);
}

if (typeof retInit === 'function'){
  const retInitBase_rm = retInit;
  retInit = function(){ retInitBase_rm(); try { rmSeed(); } catch (e){ console.warn('credit seed', e); } };
}



/*<<podoc.js>>*/
/* ===================== THE PURCHASE ORDER IS THE SCREEN =====================
   Alan: "Why is this so complicated? I want to select items and then have it take me to a PO that I can
   edit before submitting."

   Right. Every question the run used to ask in a dialog — which vendor is this actually coming from,
   what is it really costing, should this one be on its own order, is any of this billed yet — is a
   field on the purchase order. Asking them beforehand meant answering them blind, in a modal, before
   the document existed; and once answered they could not be revisited without cancelling and starting
   again.

   So the run makes the drafts and opens the first one, and everything below lives on the document:

     · the other drafts from the same run, so moving between them is one click
     · a line can be moved to another vendor — it leaves this order and joins (or starts) theirs
     · a line can be pulled onto an order of its own
     · what the firm is carrying, if this was bought before it was billed, with the reason recorded

   Nothing is committed to a vendor until Issue PO, which is the button that was always there.
*/

const poSiblings = (po) => {
  const run = (DB.sel.runs || []).find(r => (r.poIds || []).includes(po.id));
  return run ? (run.poIds || []).map(id => DB.pos.find(p => p.id === id)).filter(Boolean) : [po];
};

// What this order is carrying that nobody has been billed for yet.
function poFunding(po){
  if (typeof selFunding !== 'function') return null;
  const items = (po.lines || []).map(l => l.selId && selItem(l.selId)).filter(Boolean);
  if (!items.length) return null;
  const c = fundCheck(items);
  return c.rows.length ? c : null;
}

/* ---------- moving a line to another vendor ----------
   The vendor on a selection is where the designer found it. This is where it is actually being bought,
   which is often decided at this moment and for a better price. Moving the line moves the money, the
   item record and the estimate link with it — one order per vendor is the rule, so the line has to
   land on that vendor's document rather than change this one's name. */
function poMoveLine(po, lineId, vendor){
  vendor = String(vendor || '').trim();
  const l = (po.lines || []).find(x => x.id === lineId);
  if (!l || !vendor || vendor === po.vendor) return;
  if (po.status !== 'draft'){ toast('This order has been issued — cancel it or raise a new one'); return; }

  let target = DB.pos.find(p => p.status === 'draft' && p.projectId === po.projectId
    && String(p.vendor).toLowerCase() === vendor.toLowerCase() && p.id !== po.id);
  const fresh = !target;
  if (!target){
    target = Object.assign({}, po, {
      id: uid('po'), number: selPONumber(po.fm || '', po.projectId), vendor, lines: [],
      matchedTxns: [], date: today(), status: 'draft',
    });
    DB.pos.push(target);
    const run = (DB.sel.runs || []).find(r => (r.poIds || []).includes(po.id));
    if (run) run.poIds.push(target.id);
  }
  po.lines = po.lines.filter(x => x.id !== lineId);
  target.lines.push(l);
  if (l.selId){ const it = selItem(l.selId); if (it){ it.vendor = vendor; it.poId = target.id;
    audit('sel-item', it.id, 'vendor-changed', {vendor: po.vendor}, {vendor, via: 'purchase order'}); } }
  if (typeof ensureVendor === 'function') ensureVendor(vendor);
  log(`${l.item} moved from ${po.number} to ${target.number} — buying from ${vendor}`);
  audit('po', po.id, 'line-moved', {vendor: po.vendor}, {to: target.number, vendor});
  const empty = !po.lines.length;
  if (empty){ DB.pos = DB.pos.filter(p => p.id !== po.id); poOpen = target.id; }
  save(); render();
  toast(`${l.item} → ${target.number}${fresh ? ` (new order for ${vendor})` : ''}${empty ? `; ${po.number} was empty and has gone` : ''}`);
}

// One line, its own document — for the thing that needs its own terms, deposit or delivery.
function poSplitLine(po, lineId){
  const l = (po.lines || []).find(x => x.id === lineId);
  if (!l || (po.lines || []).length < 2) return;
  if (po.status !== 'draft'){ toast('This order has been issued'); return; }
  const target = Object.assign({}, po, {
    id: uid('po'), number: selPONumber(po.fm || '', po.projectId), lines: [l], matchedTxns: [], status: 'draft',
  });
  DB.pos.push(target);
  const run = (DB.sel.runs || []).find(r => (r.poIds || []).includes(po.id));
  if (run) run.poIds.push(target.id);
  po.lines = po.lines.filter(x => x.id !== lineId);
  if (l.selId){ const it = selItem(l.selId); if (it) it.poId = target.id; }
  audit('po', po.id, 'line-split', null, {to: target.number, item: l.item});
  log(`${l.item} pulled onto its own order ${target.number}`);
  save(); poOpen = target.id; render();
  toast(`${l.item} is on ${target.number} of its own`);
}

/* ---------- the strip, the banner, and the per-line controls ---------- */
if (typeof renderPODoc === 'function'){
  const renderPODocBase_pd = renderPODoc;
  renderPODoc = function(po){
    let h = renderPODocBase_pd(po);
    const sibs = poSiblings(po).filter(p => p.status === 'draft');
    const ed = po.status === 'draft';

    if (sibs.length > 1){
      h = `<div class="po-run no-print"><span class="small muted">This buy run made ${sibs.length} drafts</span>
        ${sibs.map(p => `<button class="${p.id === po.id ? 'on' : ''}" data-pogo="${p.id}">${esc(p.number)} · ${esc(p.vendor)} <span class="muted">${money(poTotal(p).total)}</span></button>`).join('')}
        <span class="grow"></span><span class="small muted">Each issues on its own.</span></div>` + h;
    }

    const f = ed ? poFunding(po) : null;
    if (f){
      // anchored before the line table: the meta block is rewritten by an earlier override, so matching
      // on it silently did nothing — a replace that finds nothing is the quietest bug there is.
      h = h.replace('<table class="lines"', `<div class="note warn no-print" style="margin:0 0 10px">
        <b>${money(f.exposure)}</b> of this order is not covered by money collected from the client${f.unbillable.length ? ` — ${f.unbillable.length} item${f.unbillable.length === 1 ? '' : 's'} on no approved estimate line` : ''}.
        Long-lead buying gets ahead of billing all the time; it is a decision to lend the job money, so it is recorded when this issues.
        <div class="f" style="margin-top:8px"><label>Why buy now</label><input data-p="fundNote" value="${esc(po.fundNote || '')}" placeholder="e.g. 42-day lead; FM12 invoices Friday"></div></div><table class="lines"`);
    }

    // per-line: move to another vendor, or pull onto its own order
    if (ed && (po.lines || []).length){
      const vendors = [...new Set([...DB.vendors.map(v => v.name), ...DB.sel.items.map(i => i.vendor)].filter(Boolean))].sort();
      (po.lines || []).forEach(l => {
        const a = h.indexOf(`<tr data-line="${l.id}">`); if (a < 0) return;
        const b = h.indexOf('</tr>', a);
        const row = h.slice(a, b) +
          `<td class="po-move no-print"><select data-pomove="${l.id}" title="Buy this line from someone else — it moves to their order">
            <option value="">${esc(po.vendor)}</option>
            ${vendors.filter(v => v !== po.vendor).map(v => `<option value="${esc(v)}">→ ${esc(v)}</option>`).join('')}
            <option value="__new">→ someone else…</option>
          </select>${(po.lines || []).length > 1 ? `<button class="fm-mini" data-posplit="${l.id}" title="Put this line on a purchase order of its own">⧉</button>` : ''}</td>`;
        h = h.slice(0, a) + row + h.slice(b);
      });
      h = h.replace('<th style="width:70px">Received</th>', '<th style="width:70px">Received</th><th class="no-print po-move" style="width:118px">Buy from</th>');
    }
    return h;
  };
}

if (typeof wirePODoc === 'function'){
  const wirePODocBase_pd = wirePODoc;
  wirePODoc = function(po){
    wirePODocBase_pd(po);
    document.querySelectorAll('[data-pogo]').forEach(b => b.onclick = () => { poOpen = b.dataset.pogo; render(); });
    document.querySelectorAll('[data-pomove]').forEach(sel => sel.onchange = () => {
      const id = sel.dataset.pomove;
      let v = sel.value;
      if (!v) return;
      if (v === '__new'){
        v = prompt('Buying this line from which vendor?', '');
        if (!v){ sel.value = ''; return; }
      }
      poMoveLine(po, id, v);
    });
    document.querySelectorAll('[data-posplit]').forEach(b => b.onclick = () => poSplitLine(po, b.dataset.posplit));
    const note = document.querySelector('[data-p="fundNote"]');
    if (note) note.addEventListener('change', () => {
      po.fundNote = note.value; po.fundedBy = 'firm'; po.fundedAt = today();
      po.fundedByWho = currentUser()?.name || DB.me || '';
      save(); toast('Recorded on the order');
    });
  };
}
/*<</podoc.js>>*/

/*<<fund.js>>*/
/* ===================== BUYING AHEAD OF THE BILL =====================
   Alan's question, and it is the right one: what happens when Chen buys something that has not been
   invoiced yet?

   Two answers, and the app was giving neither.

   The first is that it is often correct. A 56-day shower set on a job that closes in November has to
   be bought before anyone bills for it, or it does not arrive. Procurement is not doing anything wrong
   by getting ahead of billing; the firm is simply lending the job money, and that is a decision, not
   an accident. So this does not block the purchase. It names it, prices it, and puts it somewhere a
   person will see it.

   The second is the hole underneath: a purchase order raised from the selections board carried no link
   back to the estimate line it belonged to (`line: ''`). Without that link the spend never reached job
   costing, the margin on the line, or the funds ledger — so "have we billed for this?" had no answer
   to give. Attaching the line is most of the fix; the warning is the visible part of it.

   The states, in the order money actually moves:
     not billable  — no approved estimate line covers this item at all. The riskiest, because nobody
                     has agreed to pay for it. Usually means a selection was never put on a proposal.
     approved      — a client-approved line exists, but no invoice has gone out yet.
     invoiced      — billed, not paid. The client owes us; we are out of pocket until they pay.
     collected     — the money is in. Buying this is spending the client's money, which is the point.
*/

const FUND_STATES = [
  ['collected',   'Client money', 'ok',   'Billed and paid. Buying this spends money already collected.'],
  ['invoiced',    'Invoiced',     '',     'Billed, not yet paid. The firm is out of pocket until it lands.'],
  ['approved',    'Approved only','warn', 'The client approved the line but has not been invoiced for it.'],
  ['not-billable','Not on a bill','bad',  'No approved estimate line covers this item. Nobody has agreed to pay for it.'],
];
const FUND_STATE = Object.fromEntries(FUND_STATES.map(([k, label, cls, why]) => [k, {k, label, cls, why}]));

/* The link that was missing. A finish-materials estimate line carries the selId of the board item it
   came from, so the item can find its own line — and once it can, everything downstream works. */
function selEstLine(it){
  if (!it) return null;
  for (const c of DB.clients){
    for (const d of c.estimates){
      if (d.status === 'void' || d.status === 'rejected') continue;
      const l = (d.lines || []).find(x => x.selId === it.id);
      if (l) return {key: `estimate:${d.id}:${l.id}`, doc: d, line: l, client: c};
    }
  }
  return null;
}

/* What the money behind one item looks like. Costs a lineFin() call, so it is cached for a render
   pass the way selEffLead is. */
let _fundCache = null, _fundCacheAt = 0;
function selFunding(it){
  if (!_fundCache || Date.now() - _fundCacheAt > 1500){ _fundCache = {}; _fundCacheAt = Date.now(); }
  if (it.id in _fundCache) return _fundCache[it.id];
  const out = (_fundCache[it.id] = fundingOf(it));
  return out;
}
function fundingOf(it){
  const ref = selEstLine(it);
  const cost = selActual(it) || selLineCost(it);
  if (!ref) return {state: 'not-billable', key: '', doc: null, cost, billed: 0, collected: 0, exposure: cost};
  const approved = ['approved', 'converted', 'sent', 'billed'].includes(ref.doc.status);
  const f = (typeof lineFin === 'function') ? lineFin(ref.key) : null;
  const billed = f ? f.billed : 0;
  const collected = f ? f.collected : 0;
  const state = !approved ? 'not-billable' : collected > 0 ? 'collected' : billed > 0 ? 'invoiced' : 'approved';
  // What the firm has out of pocket on this item: what it cost, less what has actually been collected
  // against the line it sits on. Never negative — a well-funded line is not a credit.
  const exposure = Math.max(0, r2(cost - collected));
  return {state, key: ref.key, doc: ref.doc, line: ref.line, cost, billed, collected, exposure};
}

/* ---------- the fail-safe ----------
   It runs where the money leaves: at the buy run. Nothing is blocked. What happens is that the person
   raising the order is told, in money, what the firm is about to lend the job — and the answer is
   recorded on the purchase order, so the question "why did we pay for this before billing it?" has an
   answer three months later. */
function fundCheck(items){
  const rows = items.map(it => ({it, f: selFunding(it)})).filter(r => ['not-billable', 'approved', 'invoiced'].includes(r.f.state));
  const by = k => rows.filter(r => r.f.state === k);
  return {
    rows,
    unbillable: by('not-billable'),
    approvedOnly: by('approved'),
    invoiced: by('invoiced'),
    ahead: rows.filter(r => r.f.state !== 'invoiced'),          // not yet billed at all
    exposure: r2(rows.reduce((a, r) => a + r.f.exposure, 0)),
  };
}

/* ---------- and it is caught even when nobody was looking ----------
   The gate covers buying through the app. Money also leaves by someone using the company card in a
   showroom, and the item turns up already bought. So the same question is asked of the record itself,
   and the answer shows on the board next to every other thing that is wrong with an item. */
function fundVerify(it){
  if (typeof selCheck !== 'function') return;
  const f = selFunding(it);
  const bought = !SEL_OPEN.includes(it.stage) || it.poId;
  if (!bought) return;
  if (f.state === 'not-billable')
    selCheck(it, 3, 'funding', 'Bought, and not on any approved estimate line',
      'Nobody has agreed to pay for this. Either it belongs on a proposal that was never sent, or it should not have been bought. It is money out with nothing behind it.', 'fund:not-billable');
  else if (f.state === 'approved')
    selCheck(it, 2, 'funding', 'Bought before it was invoiced',
      `${money(f.exposure)} the firm is carrying on this item. The line is approved — invoicing it is usually the whole answer.`, 'fund:unbilled');
}
/*<</fund.js>>*/

/*<<costlines.js>>*/
/* ===================== COST BY LINE — rough, labour, subs, finish =====================
   Alan: "when we are matching transactions to line items on estimates, invoices, WIPs — it's either
   rough materials, labor, subs, finish material. I want to see a report that shows it per line item."

   The app already knew what a line had cost. What it did not know was what KIND of cost it was, which
   is the number that tells you whether a job is going wrong and where. A line that is 40% over on subs
   is a scope problem; the same line 40% over on finish materials is a selections problem; over on
   labour is a productivity problem. One "actual" figure hides all three.

   Nothing new is typed to get this. Every cost already arrives attached to something that says what it
   is — a bill has a category, a transaction has a category, a purchase order raised from the
   selections board carries the item ids it was raised for. Rough and finish materials are told apart
   by that last one: a material cost that came through the selections board is finish, and a material
   cost that did not is rough. That is exactly the distinction the firm makes out loud.
*/

const CL_CLASSES = [
  ['rough',  'Rough materials', 'Lumber, board, wire, pipe, fasteners — bought against the construction estimate.'],
  ['labor',  'Labour',          'Our own crew, from payroll.'],
  ['subs',   'Subcontractors',  'Trades billing us against this line.'],
  ['finish', 'Finish materials','Anything specified on the selections board — fixtures, tile, lighting, hardware, appliances.'],
  ['other',  'Other',           'Equipment, disposal, permits, design — real job cost, none of the four.'],
];
const CL_CLASS = Object.fromEntries(CL_CLASSES.map(([k, l, why]) => [k, {k, label: l, why}]));
const CL_KEYS = CL_CLASSES.map(c => c[0]);

/* ---------- what kind of cost is this ----------
   The only judgement in the file, so it lives in one function and is tested on its own. */
const clPOof = id => DB.pos.find(p => p.id === id);
const clIsFinishPO = po => !!po && (po.lines || []).some(l => l.selId);
function clClassify(src, ctx){
  const cat = String(src.cat || '').toLowerCase();
  if (cat === 'labor' || cat === 'payroll-oh') return 'labor';
  if (cat === 'subs') return 'subs';
  if (['equipment', 'disposal', 'permits', 'design'].includes(cat)) return 'other';
  if (cat === 'materials'){
    // Finish if it came through the selections board — by its purchase order, or because the estimate
    // line it is attached to is a finish-materials line to begin with.
    if (clIsFinishPO(clPOof(src.poId))) return 'finish';
    if (src.txnId && DB.pos.some(p => clIsFinishPO(p) && (p.matchedTxns || []).includes(src.txnId))) return 'finish';
    if (ctx && ctx.finishLine) return 'finish';
    return 'rough';
  }
  return 'other';
}

/* Every cost document sitting against one line, each with a class. Bills first, then transactions that
   did not come in through a bill, which is the same rule lineFin uses so the two cannot disagree. */
function clCosts(key, ctx){
  const bills = DB.bills.filter(b => b.line === key && !['void', 'rejected'].includes(b.status));
  const out = bills.map(b => ({kind: 'bill', id: b.id, date: b.date, vendor: b.vendor || '', ref: b.number || '',
                               amount: r2(billTotal(b)), cls: clClassify({cat: b.cat, poId: b.poId}, ctx), doc: b}));
  DB.txns.filter(t => t.line === key && !t.billId).forEach(t => {
    out.push({kind: 'txn', id: t.id, date: t.date, vendor: t.vendor || '', ref: t.desc || '',
              amount: r2(-(+t.amt || 0)), cls: clClassify({cat: t.cat, txnId: t.id}, ctx), doc: t});
  });
  return out.sort((a, b) => String(a.date).localeCompare(String(b.date)));
}

/* ---------- a row is a line of a contract ---------- */
const ohAvailable = () => typeof burdenOf === 'function' && typeof burdened === 'function';
const ohShown = () => ohAvailable() && burdened();

function clRows(){
  const ohOn = ohShown();
  const jobs = clScope === 'all' ? DB.projects
    : clScope === 'client' ? DB.projects.filter(p => p.clientId === (DB.projects.find(x => x.id === S.id)?.clientId))
    : DB.projects.filter(p => p.id === S.id);
  const rows = [];
  for (const p of jobs){
    for (const o of lineOptions(p.id)){
      const f = lineFin(o.key); if (!f) continue;
      const finishLine = o.doc.template === 'materials' || !!o.line.selId;
      const costs = clCosts(o.key, {finishLine});
      const by = Object.fromEntries(CL_KEYS.map(k => [k, 0]));
      costs.forEach(c => { by[c.cls] = r2(by[c.cls] + c.amount); });
      const actual = r2(CL_KEYS.reduce((a, k) => a + by[k], 0));
      const price = f.price, budget = f.budget;
      const committedCost = f.committed;
      rows.push({
        key: o.key, doc: o.doc, line: o.line, project: p, projectName: p.project.name,
        client: (DB.clients.find(c => c.id === p.clientId)?.name || '—'),
        number: o.doc.number, item: o.line.item || o.line.desc || 'Untitled line',
        code: (o.line.code || (typeof codeForLine === 'function' ? codeForLine(o.line) : '99')),
        price, budget, billed: f.billed, collected: f.collected, committed: f.committed,
        actual, ...by, costs,
        /* Two profits, because they answer different questions. Profit now is price against what has
           actually been spent — true today, and flattering, because the bills that have not arrived are
           not in it. At completion is price against the greater of the budget and what is spent plus
           what is already committed on open purchase orders: the number that says how this line ends
           if nothing else changes. A line looks healthy on the first and sick on the second when the
           POs are out and the invoices have not landed, which is most of the time. */
        profitNow: r2(price - actual),
        profitNowPct: price ? Math.round((price - actual) / price * 100) : null,
        atCost: r2(Math.max(budget, actual + committedCost)),
        profitFinal: r2(price - Math.max(budget, actual + committedCost)),
        profitFinalPct: price ? Math.round((price - Math.max(budget, actual + committedCost)) / price * 100) : null,
        /* Overhead is not a cost of this line; it is the firm's cost of being able to do the line at
           all, spread over the work by the rate the app already computes from the last three months.
           So it is never mixed into gross profit — it sits in its own column, behind the same firm-wide
           Gross / After overhead switch the rest of the app uses. One definition of overhead, not two. */
        overhead: ohOn ? (typeof burdenOf === 'function' ? burdenOf(Math.max(budget, actual + committedCost), String(o.line.code || (typeof codeForLine === 'function' ? codeForLine(o.line) : '99'))) : 0) : 0,
        margin: r2(price - Math.max(actual, budget)),
        marginPct: price ? Math.round((price - Math.max(actual, budget)) / price * 100) : null,
        variance: budget ? r2(budget - actual) : null,
        dominant: CL_KEYS.filter(k => by[k]).sort((a, b) => by[b] - by[a])[0] || '',
      });
    }
  }
  rows.forEach(r => {
    r.net = r2(r.profitFinal - (r.overhead || 0));
    r.netPct = r.price ? Math.round(r.net / r.price * 100) : null;
  });
  return rows;
}

const CL_COLS = [
  ['client',   'Client',    'text'],
  ['project',  'Project',   'text'],
  ['number',   'Document',  'text'],
  ['item',     'Line',      'text'],
  ['code',     'Code',      'text'],
  ['price',    'Value',     'money'],
  ['budget',   'Budget',    'money'],
  ['rough',    'Rough',     'money'],
  ['labor',    'Labour',    'money'],
  ['subs',     'Subs',      'money'],
  ['finish',   'Finish',    'money'],
  ['other',    'Other',     'money'],
  ['actual',   'Actual',    'money'],
  ['committed','Committed', 'money'],
  ['variance', 'vs budget', 'money'],
  ['profitNow','Profit now','money'],
  ['profitNowPct','%',      'pct'],
  ['profitFinal','At completion','money'],
  ['profitFinalPct','%',    'pct'],
  ['overhead', 'Overhead',  'money'],
  ['net',      'Net',       'money'],
  ['netPct',   'Net %',     'pct'],
];
let clScope = 'project', clSort = 'price', clDir = -1, clQ = '', clClass = 'all', clCode = 'all', clOnlyOver = false;

function clCols(){
  const drop = new Set();
  if (clScope === 'project'){ drop.add('client'); drop.add('project'); }
  if (clScope === 'client') drop.add('client');
  if (!ohShown()){ drop.add('overhead'); drop.add('net'); drop.add('netPct'); }
  return CL_COLS.filter(c => !drop.has(c[0]));
}
const clValue = (r, k) => k === 'project' ? r.projectName : r[k];

function clFiltered(){
  let rows = clRows();
  if (clClass !== 'all') rows = rows.filter(r => (r[clClass] || 0) > 0);
  if (clCode !== 'all') rows = rows.filter(r => r.code === clCode);
  if (clOnlyOver) rows = rows.filter(r => r.variance != null && r.variance < 0);
  if (clQ.trim()){
    const q = clQ.trim().toLowerCase();
    rows = rows.filter(r => [r.item, r.number, r.projectName, r.client, r.code].join(' ').toLowerCase().includes(q));
  }
  const type = Object.fromEntries(CL_COLS.map(c => [c[0], c[2]]));
  const t = type[clSort] || 'text';
  return rows.sort((a, b) => {
    const x = clValue(a, clSort), y = clValue(b, clSort);
    if (x == null && y == null) return 0;
    if (x == null) return 1;
    if (y == null) return -1;
    const c = ['money', 'pct', 'num'].includes(t) ? (+x || 0) - (+y || 0)
            : String(x).localeCompare(String(y), undefined, {numeric: true});
    return c * clDir;
  });
}

function clTotals(rows){
  const t = {lines: rows.length};
  ['price', 'budget', 'actual', 'committed', 'billed', 'collected', 'profitNow', 'profitFinal', 'overhead', 'net', ...CL_KEYS].forEach(k =>
    t[k] = r2(rows.reduce((a, r) => a + (+r[k] || 0), 0)));
  t.profitNowPct = t.price ? Math.round(t.profitNow / t.price * 100) : null;
  t.profitFinalPct = t.price ? Math.round(t.profitFinal / t.price * 100) : null;
  t.netPct = t.price ? Math.round(t.net / t.price * 100) : null;
  t.variance = r2(t.budget - t.actual);
  t.margin = r2(t.price - Math.max(t.actual, t.budget));
  t.marginPct = t.price ? Math.round(t.margin / t.price * 100) : null;
  t.over = rows.filter(r => r.variance != null && r.variance < 0);
  t.overAmt = r2(t.over.reduce((a, r) => a + r.variance, 0));
  return t;
}

function clCell(r, k){
  const v = clValue(r, k);
  if (CL_KEYS.includes(k))
    return `<td class="money ${v ? 'cl-' + k : 'muted'}" ${v ? `title="${esc(CL_CLASS[k].why)}"` : ''}>${v ? money(v) : '—'}</td>`;
  switch (k){
    case 'item':      return `<td><b>${esc(r.item)}</b>${r.costs.length ? `<div class="sub">${r.costs.length} cost${r.costs.length === 1 ? '' : 's'}</div>` : ''}</td>`;
    case 'code':      return `<td class="sub" title="${esc((COST_CODES.find(c => c[0] === r.code) || [,''])[1] || '')}">${esc(r.code)}</td>`;
    case 'variance':  return `<td class="money ${v == null ? '' : v < 0 ? 'an-over' : 'an-under'}">${v == null ? '<span class="muted">—</span>' : money(v)}</td>`;
    case 'marginPct': case 'profitNowPct': case 'profitFinalPct': case 'netPct':
      return `<td class="money pct-cell ${v == null ? '' : v < 0 ? 'an-over' : v < (DB.company.minMargin || 20) ? 'cl-thin' : ''}">${v == null ? '<span class="muted">—</span>' : v + '%'}</td>`;
    case 'profitNow': case 'profitFinal': case 'net':
      return `<td class="money ${v < 0 ? 'an-over' : ''}" ${k === 'profitFinal' ? `title="Price less the greater of budget and (spent + committed) — where this line lands if nothing else changes"` : k === 'net' ? 'title="At completion, less this line\'s share of overhead"' : 'title="Price less what has actually been spent so far"'}>${money(v || 0)}</td>`;
    case 'overhead': return `<td class="money muted" title="This line's share of the firm's overhead, at the rate computed from the last three months">${v ? money(v) : '—'}</td>`;
    case 'price': case 'budget': case 'actual': case 'committed':
      return `<td class="money">${v ? money(v) : '<span class="muted">—</span>'}</td>`;
    default:          return `<td>${esc(v ?? '')}</td>`;
  }
}

function renderCostLines(){
  const root = $('#proc-body'); if (!root) return;
  const rows = clFiltered();
  const t = clTotals(rows);
  const all = clRows();
  const cols = clCols();
  const bar = (k) => { const v = t[k]; return `<div class="cl-bar-seg cl-${k}" style="flex:${Math.max(v, 0)}" title="${CL_CLASS[k].label} · ${money(v)}"></div>`; };
  const spent = CL_KEYS.reduce((a, k) => a + t[k], 0);

  root.innerHTML = `
  ${procTabsHtml()}
  <div class="ph"><div><h2>Cost by line — ${esc(clScope === 'all' ? 'every project' : clScope === 'client' ? (DB.clients.find(c => c.id === DB.projects.find(p => p.id === S.id)?.clientId)?.name || 'this client') : S.project.name)}</h2>
    <p class="lead">Every contract line with what it has actually cost, split the way the firm talks about cost: rough materials, labour, subs, finish materials. Nothing is typed to produce this — a material cost that came through the selections board is finish, one that did not is rough.</p></div>
    <div class="acts"><button class="btn" id="cl-csv">Export to Excel</button></div></div>

  <div class="sel-stats">
    <div class="sel-stat"><b>${money(t.price)}</b><span>contract value on these lines</span></div>
    <div class="sel-stat"><b>${money(t.actual)}</b><span>spent</span></div>
    <div class="sel-stat"><b>${money(t.committed)}</b><span>committed on open POs</span></div>
    <div class="sel-stat"><b>${money(t.profitNow)}</b><span>profit now · ${t.profitNowPct == null ? '—' : t.profitNowPct + '%'}</span></div>
    <div class="sel-stat ${t.profitFinalPct != null && t.profitFinalPct < (DB.company.minMargin || 20) ? 'bad' : ''}"><b>${money(t.profitFinal)}</b><span>at completion · ${t.profitFinalPct == null ? '—' : t.profitFinalPct + '%'}</span></div>
    ${ohShown() ? `<div class="sel-stat ${t.net < 0 ? 'bad' : ''}"><b>${money(t.net)}</b><span>net after ${money(t.overhead)} overhead · ${t.netPct == null ? '—' : t.netPct + '%'}</span></div>` : ''}
  </div>

  ${spent ? `<div class="cl-bar">${CL_KEYS.filter(k => t[k]).map(bar).join('')}</div>
  <div class="cl-key">${CL_KEYS.filter(k => t[k]).map(k => `<span><i class="cl-${k}"></i>${CL_CLASS[k].label} <b>${money(t[k])}</b> <span class="muted">${Math.round(t[k] / spent * 100)}%</span></span>`).join('')}</div>` : ''}

  ${t.over.length ? `<p class="note bad" style="margin:10px 0 0"><b>${t.over.length} line${t.over.length === 1 ? '' : 's'} over budget</b> — ${money(Math.abs(t.overAmt))} between them. Sort by <b>vs budget</b> to see the worst, and open a row to see which kind of cost did it.</p>` : ''}

  <div class="proc-bar an-lens">
    <span class="small muted">Show</span>
    <select id="cl-scope">${AN_SCOPES.map(([k, l]) => `<option value="${k}" ${clScope === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <select id="cl-class"><option value="all">Any kind of cost</option>${CL_CLASSES.map(([k, l]) => `<option value="${k}" ${clClass === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <select id="cl-code"><option value="all">Any cost code</option>${[...new Set(all.map(r => r.code))].sort().map(c => `<option value="${esc(c)}" ${clCode === c ? 'selected' : ''}>${esc(c)} ${esc((COST_CODES.find(x => x[0] === c) || [,''])[1] || '')}</option>`).join('')}</select>
    <label class="cl-chk"><input type="checkbox" id="cl-over" ${clOnlyOver ? 'checked' : ''}><span>over budget only</span></label>
    ${ohAvailable() ? burdenToggleHtml() : ''}
    <input id="cl-q" placeholder="Search line, document, job…" value="${esc(clQ)}" style="max-width:220px">
    <span class="grow"></span><span class="small muted">${all.length} line${all.length === 1 ? '' : 's'}</span>
  </div>

  <div class="proc-wrap"><table class="t an cl">
    <thead><tr>${cols.map(([k, l, ty]) => `<th class="${['money', 'pct'].includes(ty) ? 'money' : ''} ${clSort === k ? 'sorted' : ''}" data-clsort="${k}">${l}${clSort === k ? (clDir > 0 ? ' ↑' : ' ↓') : ''}</th>`).join('')}</tr></thead>
    <tbody>${rows.map(r => `<tr data-clrow="${esc(r.key)}">${cols.map(([k]) => clCell(r, k)).join('')}</tr>`).join('') || `<tr><td colspan="${cols.length}" class="empty">Nothing matches those filters.</td></tr>`}</tbody>
    <tfoot><tr><td colspan="${cols.findIndex(c => c[0] === 'price')}">${rows.length} line${rows.length === 1 ? '' : 's'}</td>
      ${cols.slice(cols.findIndex(c => c[0] === 'price')).map(([k]) => k === 'marginPct'
        ? `<td class="money">${t.marginPct == null ? '' : t.marginPct + '%'}</td>`
        : `<td class="money ${k === 'variance' && t.variance < 0 ? 'an-over' : ''}">${money(t[k] || 0)}</td>`).join('')}</tr></tfoot>
  </table></div>
  <p class="small muted" style="margin:8px 0 0">Actual is bills plus card and bank transactions matched to the line, counted once. Committed is what is on purchase orders that have been issued and not yet billed. <b>Profit now</b> is price less what has actually been spent — true today, and flattering, because the bills that have not arrived are not in it. <b>At completion</b> is price less the greater of the budget and spent-plus-committed: where the line lands if nothing else changes. ${ohShown() ? 'Overhead is this line\'s share of the firm\'s cost of being able to do the work at all, at the rate computed from the last three months, and is never mixed into gross profit.' : 'Switch to <b>After overhead</b> to add each line\'s share of the firm\'s overhead and the net beneath it.'}</p>`;

  wireCostLines(root);
}

// One line, opened: every bill and transaction behind it, and which kind of cost each one is.
function clRowModal(r){
  const by = Object.fromEntries(CL_KEYS.map(k => [k, r.costs.filter(c => c.cls === k)]));
  mbModal(`${esc(r.number)} · ${esc(r.item)}`, `
    <div class="sel-stats" style="margin:0 0 10px">
      <div class="sel-stat"><b>${money(r.price)}</b><span>value</span></div>
      <div class="sel-stat"><b>${money(r.budget)}</b><span>budget</span></div>
      <div class="sel-stat ${r.variance != null && r.variance < 0 ? 'bad' : ''}"><b>${money(r.actual)}</b><span>spent${r.variance != null ? ` · ${r.variance < 0 ? money(Math.abs(r.variance)) + ' over' : money(r.variance) + ' under'}` : ''}</span></div>
    </div>
    ${r.costs.length ? CL_KEYS.filter(k => by[k].length).map(k => `
      <h4 style="margin:12px 0 4px">${CL_CLASS[k].label} <span class="muted" style="font-weight:400">· ${money(r2(by[k].reduce((a, c) => a + c.amount, 0)))}</span></h4>
      <table class="t"><tbody>${by[k].map(c => `<tr><td class="num">${fmt(c.date)}</td><td>${esc(c.vendor || '')}</td>
        <td class="sub">${esc(String(c.ref).slice(0, 46))}</td><td class="sub">${c.kind === 'bill' ? 'bill' : 'card / bank'}</td>
        <td class="money">${money(c.amount)}</td></tr>`).join('')}</tbody></table>`).join('')
      : '<div class="empty">Nothing has been matched to this line yet.</div>'}
    <p class="small muted" style="margin:12px 0 0">A material cost is <b>finish</b> when it came through the selections board — its purchase order carries the board items it was raised for — and <b>rough</b> otherwise. Change what a transaction is categorised as in Banking and this follows.</p>`,
    {submit: null});
  procWide(820);
}

function clCsv(){
  const rows = clFiltered(), cols = clCols();
  const q = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const head = cols.map(c => c[1]);
  const body = rows.map(r => cols.map(c => clValue(r, c[0])).map(q).join(','));
  const t = clTotals(rows);
  body.push(cols.map(c => ['price', 'budget', 'actual', 'committed', 'variance', ...CL_KEYS].includes(c[0]) ? t[c[0]]
    : c[0] === 'marginPct' ? (t.marginPct ?? '') : c[0] === 'item' ? 'TOTAL' : '').map(q).join(','));
  return [head.map(q).join(','), ...body].join('\r\n');
}

function wireCostLines(root){
  const go = () => renderCostLines();
  root.querySelectorAll('[data-clsort]').forEach(th => th.onclick = () => {
    const k = th.dataset.clsort;
    if (clSort === k) clDir *= -1; else { clSort = k; clDir = ['price', 'budget', 'actual', 'committed', 'variance', 'marginPct', ...CL_KEYS].includes(k) ? -1 : 1; }
    go();
  });
  root.querySelector('#cl-scope').onchange = e => { clScope = e.target.value; go(); };
  root.querySelector('#cl-class').onchange = e => { clClass = e.target.value; go(); };
  root.querySelector('#cl-code').onchange = e => { clCode = e.target.value; go(); };
  root.querySelector('#cl-over').onchange = e => { clOnlyOver = e.target.checked; go(); };
  const q = root.querySelector('#cl-q');
  q.oninput = () => { clQ = q.value; const at = q.selectionStart; go(); const n = document.getElementById('cl-q'); if (n){ n.focus(); n.setSelectionRange(at, at); } };
  wireProcTabs(root);
  root.querySelector('#cl-csv').onclick = () => {
    const csv = clCsv();
    mbModal('Export to Excel', `<p class="small muted" style="margin:0 0 10px">${clFiltered().length} lines, the columns on screen, with a TOTAL row.</p>
      <div class="row" style="gap:8px"><button class="btn primary" id="cl-dl">Download</button><button class="btn" id="cl-copy">Copy to the clipboard</button></div>
      <textarea id="cl-csv-text" readonly style="width:100%;height:120px;margin-top:10px;font-family:ui-monospace,Menlo,monospace;font-size:11px">${esc(csv)}</textarea>`, {submit: null});
    const m = document.getElementById('mbm'); if (!m) return;
    const name = `cost-by-line-${today()}.csv`;
    m.querySelector('#cl-dl').onclick = () => { try { const a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob(['﻿' + csv], {type: 'text/csv;charset=utf-8'})); a.download = name;
      document.body.appendChild(a); a.click(); a.remove(); toast('Exported'); } catch (e){ toast('This copy cannot save files — copy it instead'); } };
    m.querySelector('#cl-copy').onclick = async () => { const ta = m.querySelector('#cl-csv-text');
      try { await navigator.clipboard.writeText(csv); toast('Copied'); } catch (e){ ta.focus(); ta.select(); toast('Press Ctrl-C / Cmd-C'); } };
  };
  root.querySelectorAll('[data-clrow]').forEach(tr => tr.onclick = () => {
    const r = clRows().find(x => x.key === tr.dataset.clrow); if (r) clRowModal(r);
  });
}

/* ---------- where it lives ----------
   A third pane of Procurement, alongside the buy board and the analysis report. Same skeleton, same
   habits: a scope, filters, every column sorting, a row that opens what is behind it, an export. */
if (typeof renderProc === 'function'){
  const renderProcBase_cl = renderProc;
  renderProc = function(){ if (procPane === 'cost' && view === 'proc') return renderCostLines(); return renderProcBase_cl(); };
}
/*<</costlines.js>>*/

/*<<analysis.js>>*/
/* ===================== THE ANALYSIS REPORT =====================
   Chen's sheet, made out of records instead of typing. 313 Convent: 202 rows, 27 FM packages, 91
   vendors, kept by hand in Google Sheets and cross-referenced to Houzz by re-keying the FM number.

   The sheet is a good report. Its problem is that it is a copy: every figure in it was typed in a
   second time, so it drifts from the thing it describes, and when the range at the top stopped being
   extended nobody noticed. Reading 313 Convent as it stands:

     · the totals block says $401,796.61 budgeted and $333,015.72 spent, and calls the difference
       $70,806.19 — but those two numbers differ by $68,780.89. The savings cell is $2,025.30 adrift
       from its own two inputs.
     · the purchased rows in the sheet add to $846,262.52 budgeted and $702,769.61 spent. The totals
       block is reading about half the sheet, because the sum ranges stopped where FM12 used to end.
     · 76 of the 202 lines came in OVER budget, −$16,154 between them. "17.62% saved" says nothing
       about that, and over-budget is the number a buyer needs to see.
     · markup is not 10% on all of them: windows carry 35%, the millwork 67.8%, the stained glass 20%.
     · the category column holds 37 distinct labels for about fifteen real categories — "Tile" and
       "Tile FM", "Hardware" and "Door Hardware - FM", "Stone", "Stone FM" and "Srone".

   None of that is Chen being careless. It is what a spreadsheet does over two years. So this report
   derives every figure from the item records, totals whatever is actually on screen, shows overruns
   as loudly as savings, and normalises the category before it counts it.
*/

/* ---------- categories, said once ----------
   The suffix a package number leaves behind ("Tile FM", "Doors - FM") is not a different category. */
const AN_CAT_FIX = {
  'srone': 'Tile & stone', 'stone': 'Tile & stone', 'tile': 'Tile & stone', 'pavers': 'Tile & stone', 'hardscape': 'Tile & stone',
  'hardware': 'Hardware', 'door hardware': 'Hardware', 'accessories and hardware': 'Hardware', 'accessory & hardware': 'Hardware',
  'light fixture': 'Lighting fixture', 'lighting': 'Lighting fixture', 'light fixtures': 'Lighting fixture', 'electric': 'Electrical',
  'bathroom fixture': 'Bath fixture', 'bathroom fixtures': 'Bath fixture', 'plumbing': 'Plumbing fixture', 'plumbing fixture': 'Plumbing fixture',
  'floor': 'Flooring', 'flooring': 'Flooring', 'doors': 'Doors', 'door': 'Doors', 'window': 'Windows', 'windows': 'Windows',
  'millwork': 'Millwork', 'lumber': 'Millwork', 'trim & molding': 'Millwork', 'ceiling': 'Millwork',
  'appliances': 'Appliance', 'appliance': 'Appliance', 'glass': 'Glass', 'paint': 'Paint',
  'hvac': 'HVAC', 'hvac & ventilation': 'HVAC', 'design items': 'Design items',
};
function anCat(raw){
  const s = String(raw || '').toLowerCase().replace(/[\s-]*fm\s*$/i, '').replace(/\s+/g, ' ').trim();
  if (!s) return 'Uncategorised';
  return AN_CAT_FIX[s] || (SEL_CATS.includes(raw) ? raw : (s[0].toUpperCase() + s.slice(1)));
}

/* ---------- a row ----------
   Chen's row is not an item, it is a package: "FM1 - 1.Accessories and Hardware", Build.com. That is
   one FM group at one vendor — which is exactly one purchase order, which is exactly the thing a bank
   transaction has to match. So the report groups the same way the money does. */
const AN_STATUS = {purchased: 'Purchased', partial: 'Partial', pending: 'Pending'};
const anOrdered = it => !SEL_OPEN.includes(it.stage);
const anMU = it => 1 + ((it.markupPct == null ? 10 : +it.markupPct) / 100);

const anProject = pid => DB.projects.find(p => p.id === pid);
const anProjName = pid => anProject(pid)?.project?.name || '—';
const anClientOf = pid => { const p = anProject(pid); return p ? (DB.clients.find(c => c.id === p.clientId)?.name || '—') : '—'; };
const anPOof = it => DB.pos.find(p => p.id === it.poId);

// Which items the report is looking at, at the width it has been set to.
function anScopeItems(){
  if (anScope === 'all') return DB.sel.items.slice();
  if (anScope === 'client'){
    const cid = anProject(S.id)?.clientId;
    const ids = new Set(DB.projects.filter(p => p.clientId === cid).map(p => p.id));
    return DB.sel.items.filter(i => ids.has(i.projectId));
  }
  return selItems();
}

// The grain. Every one of these is the same items counted a different way — the one-record-many-lenses
// rule, which is why the totals never depend on which lens is chosen.
const AN_GRAIN = {
  po:      it => `${it.fm || '—'}|${it.vendor || 'No vendor'}${anScope === 'project' ? '' : '|' + it.projectId}`,
  ponum:   it => anPOof(it)?.id || `unordered|${it.vendor || 'No vendor'}|${it.projectId}`,
  fm:      it => `${it.fm || '—'}${anScope === 'project' ? '' : '|' + it.projectId}`,
  vendor:  it => it.vendor || 'No vendor',
  cat:     it => anCat(it.category),
  project: it => it.projectId,
  client:  it => anProject(it.projectId)?.clientId || '—',
};

function anRows(pid){
  const items = pid ? selItems(pid) : anScopeItems();
  const grain = AN_GRAIN[anGroup] || AN_GRAIN.po;
  const groups = {};
  for (const it of items){
    const key = grain(it);
    (groups[key] = groups[key] || {fm: it.fm || '—', vendor: it.vendor || 'No vendor', items: []}).items.push(it);
  }
  const seq = {};
  const rows = Object.values(groups).map(g => {
    const its = g.items;
    const ord = its.filter(anOrdered).length;
    const back = its.filter(i => (DB.sel.returns || []).some(r => r.itemId === i.id && r.status !== 'closed'));
    const price = r2(its.reduce((a, i) => a + selLineCost(i), 0));
    const withMU = r2(its.reduce((a, i) => a + selLineCost(i) * anMU(i), 0));
    const priced = its.filter(i => selActual(i));
    const final = priced.length ? r2(priced.reduce((a, i) => a + selActual(i), 0)) : null;
    // Savings compares like with like: what those same lines were budgeted at, not the whole group.
    const against = priced.length ? r2(priced.reduce((a, i) => a + selLineCost(i), 0)) : 0;
    const dates = f => its.map(i => i.dates?.[f]).filter(Boolean).sort()[0] || '';
    const cats = {};
    its.forEach(i => { const c = anCat(i.category); cats[c] = (cats[c] || 0) + selLineCost(i); });
    const cat = Object.entries(cats).sort((a, b) => b[1] - a[1])[0]?.[0] || 'Uncategorised';
    // A return is not a status, it is a thing happening to some of the items. One box going back does
    // not make a nine-item vendor group "Returned" — it makes it a purchased group with one on its way
    // back, and the money is tracked separately either way.
    const status = ord === 0 ? 'pending' : ord < its.length ? 'partial' : 'purchased';
    const pids = [...new Set(its.map(i => i.projectId))];
    const po = anPOof(its[0]);
    const vendors = [...new Set(its.map(i => i.vendor || 'No vendor'))];
    const fms = [...new Set(its.map(i => i.fm || '—'))];
    const desc =
      anGroup === 'ponum'   ? (po ? `${po.number} · ${po.vendor}` : `Not yet ordered · ${vendors[0]}`) :
      anGroup === 'vendor'  ? g.vendor :
      anGroup === 'cat'     ? cat :
      anGroup === 'project' ? anProjName(pids[0]) :
      anGroup === 'client'  ? anClientOf(pids[0]) :
      anGroup === 'fm'      ? `${fms[0]} — ${its.length} item${its.length === 1 ? '' : 's'}` :
      its.length === 1 ? its[0].name : `${cat} — ${its.length} items`;
    return {
      key: grain(its[0]), fm: fms.length === 1 ? fms[0] : `${fms.length} FMs`,
      vendor: vendors.length === 1 ? vendors[0] : `${vendors.length} vendors`,
      project: pids.length === 1 ? anProjName(pids[0]) : `${pids.length} projects`,
      client: [...new Set(pids.map(anClientOf))].length === 1 ? anClientOf(pids[0]) : 'Several',
      projectIds: pids, po: po && its.every(i => i.poId === po.id) ? po.number : (anGroup === 'ponum' && po ? po.number : ''),
      items: its, n: its.length, cat, status, desc, back: back.length,
      created: dates('created'), ordered: dates('ordered'),
      price, withMU, final, against,
      saved: final == null ? null : r2(against - final),
      savedPct: final == null || !against ? null : Math.round((against - final) / against * 1000) / 10,
      open: r2(its.filter(i => SEL_OPEN.includes(i.stage)).reduce((a, i) => a + selLineCost(i), 0)),
      /* Who is paying for this, right now. The worst state in the group wins, because a package that is
         nine-tenths collected and one-tenth on nobody's estimate is a package with a problem in it. */
      ...(() => {
        if (typeof selFunding !== 'function') return {funding: '', exposure: 0};
        const fs = its.map(selFunding);
        const order = ['not-billable', 'approved', 'invoiced', 'collected'];
        const worst = order.find(k => fs.some(f => f.state === k)) || 'collected';
        const bought = its.filter(i => !SEL_OPEN.includes(i.stage) || i.poId);
        return {funding: worst, fundingLabel: FUND_STATE[worst]?.label || '',
                exposure: r2(bought.reduce((a, i) => a + selFunding(i).exposure, 0))};
      })(),
    };
  });
  // The Code column is the position inside the FM, the way Chen writes it: FM1 - 1, FM1 - 2.
  rows.sort((a, b) => String(a.fm).localeCompare(String(b.fm), undefined, {numeric: true}) || String(a.vendor).localeCompare(String(b.vendor)));
  rows.forEach(r => { seq[r.fm] = (seq[r.fm] || 0) + 1; r.code = anGroup === 'po' ? seq[r.fm] : ''; r.label = anGroup === 'po' ? `${r.fm} - ${r.code}. ${r.desc}` : r.desc; });
  return rows;
}

/* ---------- the totals ----------
   Computed from the rows on screen, every time. A total that cannot disagree with the list above it
   is the whole reason for building this rather than maintaining the sheet. */
function anTotals(rows){
  const t = {
    lines: rows.length,
    clientValue: r2(rows.reduce((a, r) => a + r.withMU, 0)),
    budget: r2(rows.reduce((a, r) => a + r.price, 0)),
    boughtBudget: r2(rows.reduce((a, r) => a + r.against, 0)),
    spent: r2(rows.reduce((a, r) => a + (r.final || 0), 0)),
    remaining: r2(rows.reduce((a, r) => a + r.open, 0)),
    over: rows.filter(r => r.saved != null && r.saved < 0),
    under: rows.filter(r => r.saved != null && r.saved > 0),
    fronted: r2(rows.reduce((a, r) => a + (r.exposure || 0), 0)),
    unbillable: rows.filter(r => r.funding === 'not-billable'),
  };
  t.saved = r2(t.boughtBudget - t.spent);
  t.savedPct = t.boughtBudget ? Math.round(t.saved / t.boughtBudget * 1000) / 10 : null;
  t.overAmt = r2(t.over.reduce((a, r) => a + r.saved, 0));
  t.mu = t.budget ? Math.round(t.clientValue / t.budget * 100) / 100 : null;
  return t;
}

/* ---------- the screen ---------- */
const AN_COLS_ALL = [
  ['client',   'Client',      'text'],
  ['project',  'Project',     'text'],
  ['fm',       'FM',          'text'],
  ['po',       'PO',          'text'],
  ['code',     'Code',        'num'],
  ['desc',     'Description', 'text'],
  ['cat',      'Category',    'text'],
  ['status',   'Status',      'text'],
  ['created',  'Created',     'date'],
  ['ordered',  'Ordered',     'date'],
  ['vendor',   'Vendor',      'text'],
  ['price',    'Price',       'money'],
  ['withMU',   'With markup', 'money'],
  ['final',    'Final',       'money'],
  ['saved',    '$ saved',     'money'],
  ['savedPct', '% saved',     'pct'],
  ['days',     'Days to order','num'],
  ['funding',  'Funded by',   'text'],
  ['exposure', 'Firm is out', 'money'],
];
/* A column that says the same thing on every row is noise. Client and Project appear only when the
   report is wider than one job; Code only where it means something; PO only once one exists. */
function anCols(){
  const drop = new Set();
  if (anScope === 'project') { drop.add('client'); drop.add('project'); }
  if (anScope === 'client') drop.add('client');
  if (anGroup === 'client') drop.add('project');
  if (anGroup !== 'po') drop.add('code');
  if (anGroup === 'vendor' || anGroup === 'cat' || anGroup === 'client' || anGroup === 'project') drop.add('fm');
  if (anGroup === 'vendor' || anGroup === 'cat' || anGroup === 'client') drop.add('vendor');
  // A job's "category" is whichever one it spends most on, which tells nobody anything.
  if (anGroup === 'project' || anGroup === 'client' || anGroup === 'cat') drop.add('cat');
  const rows = anRows();
  if (!rows.some(r => r.po)) drop.add('po');
  return AN_COLS_ALL.filter(c => !drop.has(c[0]));
}
let anSort = 'fm', anDir = 1, anFM = 'all', anVendor = 'all', anCatF = 'all', anStatus = 'all', anQ = '';
/* Procurement is not done one job at a time. Chen buys across every live project at once — the same
   vendor, the same order, three addresses — so the report reads at whatever width the question needs,
   and groups by whatever the question is about. The rows change grain; the arithmetic does not. */
let anFunding = 'all';     // all · ahead (bought and not yet billed) · not-billable
let anScope = 'project';   // project · client · all
let anGroup = 'po';        // the FM package at one vendor, which is one purchase order
const AN_SCOPES = [['project', 'This project'], ['client', 'This client'], ['all', 'Every project']];
const AN_GROUPS = [
  ['po',      'FM package × vendor', 'One purchase order — what a bank line has to match.'],
  ['ponum',   'Purchase order',      'Grouped by the PO actually raised, so what is on order is one row.'],
  ['fm',      'FM package',          'The invoice the client sees.'],
  ['vendor',  'Vendor',              'Everything we are buying from one house, across jobs.'],
  ['cat',     'Category',            'Where the money goes: tile, lighting, hardware.'],
  ['project', 'Project',             'One row a job.'],
  ['client',  'Client',              'One row a client, across their jobs.'],
];
const anSel = new Set();   // selected row keys — packages, not items

const anDays = r => (r.created && r.ordered) ? Math.round((Date.parse(r.ordered) - Date.parse(r.created)) / 86400000) : null;
function anValue(r, k){
  if (k === 'days') return anDays(r);
  if (k === 'status') return AN_STATUS[r.status];
  if (k === 'funding') return r.fundingLabel || '';
  return r[k];
}
function anFiltered(pid){
  let rows = anRows(pid);
  if (anFM !== 'all') rows = rows.filter(r => r.fm === anFM);
  if (anVendor !== 'all') rows = rows.filter(r => r.vendor === anVendor);
  if (anCatF !== 'all') rows = rows.filter(r => r.cat === anCatF);
  if (anStatus !== 'all') rows = rows.filter(r => r.status === anStatus);
  if (anFunding === 'ahead') rows = rows.filter(r => r.exposure > 0);
  else if (anFunding !== 'all') rows = rows.filter(r => r.funding === anFunding);
  if (anQ.trim()){
    const q = anQ.trim().toLowerCase();
    rows = rows.filter(r => [r.label, r.vendor, r.cat, r.fm].join(' ').toLowerCase().includes(q)
      || r.items.some(i => [i.name, i.sku, i.tag].filter(Boolean).join(' ').toLowerCase().includes(q)));
  }
  const type = Object.fromEntries(AN_COLS_ALL.map(c => [c[0], c[2]]));
  const t = type[anSort] || 'text';
  return rows.sort((a, b) => {
    const x = anValue(a, anSort), y = anValue(b, anSort);
    if (x == null && y == null) return 0;
    if (x == null) return 1;                 // empties sit at the bottom whichever way it is sorted
    if (y == null) return -1;
    const c = ['money', 'num', 'pct'].includes(t) ? (+x || 0) - (+y || 0)
            : t === 'date' ? String(x).localeCompare(String(y))
            : String(x).localeCompare(String(y), undefined, {numeric: true});
    return c * anDir;
  });
}

const anMoney = v => v == null ? '<span class="muted">—</span>' : money(v);
function anCell(r, k){
  const v = anValue(r, k);
  switch (k){
    case 'desc':   return `<td><b>${esc(r.desc)}</b>${r.n > 1 ? `<div class="sub">${r.n} items</div>` : ''}</td>`;
    case 'status': return `<td><span class="pill ${r.status === 'purchased' ? 'ok' : r.status === 'pending' ? 'warn' : ''}">${AN_STATUS[r.status]}</span>${r.back ? `<span class="pill bad" style="margin-left:4px" title="${r.back} item${r.back === 1 ? '' : 's'} going back to the vendor">${r.back} back</span>` : ''}</td>`;
    case 'created': case 'ordered': return `<td class="num">${v ? fmt(v) : '<span class="muted">—</span>'}</td>`;
    case 'price': case 'withMU': case 'final': return `<td class="money">${anMoney(v)}</td>`;
    case 'saved':  return `<td class="money ${v == null ? '' : v < 0 ? 'an-over' : 'an-under'}">${anMoney(v)}</td>`;
    case 'savedPct': return `<td class="money ${v == null ? '' : v < 0 ? 'an-over' : 'an-under'}">${v == null ? '<span class="muted">—</span>' : v + '%'}</td>`;
    case 'days':   return `<td class="num">${v == null ? '<span class="muted">—</span>' : v + 'd'}</td>`;
    case 'code':   return `<td class="num sub">${r.code}</td>`;
    case 'po':     return `<td class="sub">${esc(r.po || '')}</td>`;
    case 'funding': { const s = FUND_STATE[r.funding]; return `<td>${s ? `<span class="pill ${s.cls}" title="${esc(s.why)}">${esc(s.label)}</span>` : ''}</td>`; }
    case 'exposure': return `<td class="money ${v ? 'an-over' : ''}" title="What the firm has out of pocket on this row — what it cost, less what has been collected against the line it sits on">${v ? money(v) : '<span class="muted">—</span>'}</td>`;
    case 'client': case 'project': return `<td>${esc(v ?? '')}</td>`;
    default:       return `<td>${esc(v ?? '')}</td>`;
  }
}

/* ===================== ACTING FROM THE REPORT =====================
   A report you can only read sends the buyer somewhere else to do the work, and the somewhere else is
   where the second copy of the truth gets born. This is the screen Chen has open while he buys, so the
   things he does while buying happen here: put a package on a purchase order, mark it ordered, receive
   it, say what it actually cost, send something back.

   Everything acts on the ITEMS behind the selected rows, because a package is a grouping and an item is
   the record. And every action goes through the same function the item screens use — selPORun,
   selReceive, retRaise — so there is one rule per action, not two.  */

// The selection is kept across filter changes, because ticking twelve rows and then narrowing the view
// should not throw eleven of them away. But acting on rows you cannot see is the way to a nasty
// surprise, so the bar says how many are off screen.
const anPicked = () => anRows().filter(r => anSel.has(r.key));
const anHidden = () => { const shown = new Set(anFiltered().map(r => r.key)); return anPicked().filter(r => !shown.has(r.key)); };
const anPickedItems = () => anPicked().flatMap(r => r.items);

function anBar(){
  const rows = anPicked();
  if (!rows.length) return '';
  const its = anPickedItems();
  // "Still to buy" and "not yet on a purchase order" are different things: an item sits in an open
  // stage until the vendor confirms, but it is not buyable again once a PO carries it.
  const onLivePO = i => i.poId && DB.pos.some(p => p.id === i.poId && p.status !== 'cancelled');
  const buyable = its.filter(i => SEL_OPEN.includes(i.stage) && !onLivePO(i));
  const blocked = buyable.filter(selBlocked);
  const value = r2(its.reduce((a, i) => a + selLineCost(i), 0));
  return `<div class="an-bar">
    <b>${rows.length} package${rows.length === 1 ? '' : 's'}</b><span class="muted">${its.length} item${its.length === 1 ? '' : 's'} · ${money(value)}</span>
    ${anHidden().length ? `<span class="pill warn" title="Ticked earlier, then filtered out of view. Anything you do here includes them.">${anHidden().length} not shown</span>` : ''}
    <span class="grow"></span>
    ${(() => {
      const clean = buyable.filter(i => !selBlocked(i));
      const jobs = [...new Set(clean.map(i => i.projectId))].length;
      const why = !buyable.length ? (its.some(onLivePO) ? 'Everything selected is already on a purchase order' : 'Everything selected has already been ordered — a purchase order is raised before the order, not after')
        : !clean.length ? `${blocked.length === 1 ? 'The one item' : `All ${blocked.length} items`} still to buy here ${blocked.length === 1 ? 'has' : 'have'} an unresolved red check. Clear or override it on the board first.`
        : `${clean.length} item${clean.length === 1 ? '' : 's'} → ${new Set(clean.map(i => i.vendor || 'Unassigned vendor')).size} purchase order${new Set(clean.map(i => i.vendor || 'Unassigned vendor')).size === 1 ? '' : 's'}${jobs > 1 ? `, across ${jobs} jobs` : ''}${blocked.length ? `. ${blocked.length} red-flagged will be left behind.` : ''}`;
      return `<button class="btn sm primary" data-anact="po" ${clean.length ? '' : 'disabled'} title="${esc(why)}">Purchase order${clean.length && clean.length !== its.length ? ` · ${clean.length}` : ''}</button>`;
    })()}
    <button class="btn sm" data-anact="ordered">Mark ordered</button>
    <button class="btn sm" data-anact="office">Received at the office</button>
    <button class="btn sm" data-anact="site">Delivered to site</button>
    <button class="btn sm" data-anact="cost">What it cost…</button>
    <button class="btn sm ghost" data-anact="clear">Clear</button>
    ${blocked.length ? `<span class="pill bad" title="An unresolved red check means the record and the vendor page disagree about what the item is">${blocked.length} red-flagged</span>` : ''}
  </div>`;
}

// Forward only, and never past a step that has to be done by a person looking at the box.
const AN_FWD = {ordered: 'ord', office: 'office', site: 'site'};
function anAdvance(kind){
  const its = anPickedItems();
  const target = AN_FWD[kind];
  const already = its.filter(i => SEL_ORDER.indexOf(i.stage) >= SEL_ORDER.indexOf(target));
  const todo = its.filter(i => SEL_ORDER.indexOf(i.stage) < SEL_ORDER.indexOf(target));
  if (!todo.length){ toast(`Nothing to move — all ${its.length} are already there or past it`); return; }
  // Ordered → at the office is an ordinary jump: not everything gets a shipped state, and asking every
  // time trains people to click through the question. The one worth stopping for is marking something
  // received that was never ordered, because that means a record somewhere is wrong.
  const never = todo.filter(i => SEL_ORDER.indexOf(i.stage) < SEL_ORDER.indexOf('ord') && kind !== 'ordered');
  if (never.length && !confirm(`${never.length} of these have not been ordered yet. Mark them "${SEL_STAGE[target].label}" anyway?`)) return;
  let held = 0;
  for (const it of todo){
    if (kind === 'ordered'){ it.dates = it.dates || {}; it.stage = 'ord'; it.dates.ordered = it.dates.ordered || today(); }
    else if (selReceive(it, kind === 'office' ? 'office' : 'site', {}) === false) held++;
    audit('sel-item', it.id, `stage-${target}`, null, {from: it.stage, via: 'analysis'});
  }
  log(`${todo.length - held} item${todo.length - held === 1 ? '' : 's'} moved to ${SEL_STAGE[target].label.toLowerCase()} from the analysis report`);
  save(); renderAnalysis();
  toast(`${todo.length - held} moved${already.length ? `, ${already.length} were already past it` : ''}${held ? `, ${held} held by a claim` : ''}`);
}

/* The one edit that matters most on this screen: what it actually cost. Every figure in the Final,
   $ saved and % saved columns comes from here, and Chen was typing it into a spreadsheet. Cost,
   shipping and tax separately, because "fully baked in" is his phrase for the sum of the three. */
function anCostModal(){
  const its = anPickedItems();
  if (!its.length) return;
  mbModal('What it cost', `
    <p class="small muted" style="margin:0 0 10px">The landed price — cost, shipping and tax — against what each line was budgeted at. Leave a row blank and it stays uncounted rather than counting as nothing saved.</p>
    <table class="t"><thead><tr><th>Item</th><th>Vendor</th><th class="money">Budget</th><th style="width:92px">Cost</th><th style="width:78px">Shipping</th><th style="width:72px">Tax</th><th class="money">Difference</th></tr></thead>
    <tbody>${its.map(i => { const a = selActual(i);
      return `<tr data-cost="${i.id}"><td>${esc(i.name)}${i.sku ? `<div class="sub">${esc(i.sku)}</div>` : ''}</td><td class="sub">${esc(i.vendor || '')}</td>
        <td class="money">${money(selLineCost(i))}</td>
        <td><input class="num" type="number" step="0.01" data-cf="cost" value="${i.actual ? (+i.actual.cost || '') : ''}" placeholder="${r2(selLineCost(i))}"></td>
        <td><input class="num" type="number" step="0.01" data-cf="shipping" value="${i.actual ? (+i.actual.shipping || '') : ''}"></td>
        <td><input class="num" type="number" step="0.01" data-cf="tax" value="${i.actual ? (+i.actual.tax || '') : ''}"></td>
        <td class="money an-diff">${a ? money(r2(selLineCost(i) - a)) : '<span class="muted">—</span>'}</td></tr>`; }).join('')}
    </tbody></table>`,
    {submit: 'Save what they cost', onSubmit: () => {
      let n = 0;
      document.querySelectorAll('#mbm tr[data-cost]').forEach(tr => {
        const it = selItem(tr.dataset.cost); if (!it) return;
        const g = f => { const v = tr.querySelector(`[data-cf="${f}"]`).value; return v === '' ? null : +v || 0; };
        const cost = g('cost');
        if (cost == null){ return; }
        it.actual = {cost, shipping: g('shipping') || 0, tax: g('tax') || 0};
        audit('sel-item', it.id, 'actual-recorded', null, it.actual);
        n++;
      });
      if (!n){ toast('Nothing entered'); return false; }
      log(`Landed cost recorded on ${n} item${n === 1 ? '' : 's'}`);
      save(); renderAnalysis();
      toast(`${n} priced — the savings columns follow`);
    }});
  procWide(880);
  // The difference updates as it is typed, so a number that looks wrong is caught before it is saved.
  const m2 = document.getElementById('mbm'); if (!m2) return;
  m2.querySelectorAll('tr[data-cost]').forEach(tr => {
    const it = selItem(tr.dataset.cost);
    const paint = () => {
      const g = f => +tr.querySelector(`[data-cf="${f}"]`).value || 0;
      const a = r2(g('cost') + g('shipping') + g('tax'));
      const cell = tr.querySelector('.an-diff');
      if (!a){ cell.innerHTML = '<span class="muted">—</span>'; cell.className = 'money an-diff'; return; }
      const d = r2(selLineCost(it) - a);
      cell.textContent = money(d);
      cell.className = 'money an-diff ' + (d < 0 ? 'an-over' : 'an-under');
    };
    tr.querySelectorAll('[data-cf]').forEach(inp => inp.addEventListener('input', paint));
  });
}

/* What did not get bought, and why. A toast that says "3 left behind" and then vanishes is how items
   get forgotten for a fortnight. */
function anSkippedModal(items, next){
  mbModal('Left off the purchase orders', `
    <p class="small muted" style="margin:0 0 10px">These have an unresolved red check — the record and the vendor's page disagree about what the item is. Everything else went on a purchase order.</p>
    <table class="t"><thead><tr><th>Item</th><th>Vendor</th><th>What disagrees</th></tr></thead>
    <tbody>${items.map(i => `<tr><td><b>${esc(i.name)}</b><div class="sub">${esc(i.sku || '')}</div></td><td class="sub">${esc(i.vendor || '')}</td>
      <td>${(selOpenChecks(i) || []).filter(c => c.sev >= 3).map(c => `<div>${esc(c.msg)}</div>`).join('') || '<span class="muted">—</span>'}</td></tr>`).join('')}
    </tbody></table>
    <p class="small muted" style="margin:10px 0 0">Open each one on the selections board to clear it or override it, then buy them.</p>`,
    next ? {submit: 'Continue', onSubmit: () => setTimeout(next, 30)} : {submit: null});
  procWide(760);
}

function anAct(kind){
  if (kind === 'clear'){ anSel.clear(); renderAnalysis(); return; }
  if (kind === 'cost') return anCostModal();
  if (kind === 'po'){
    const live = i => i.poId && DB.pos.some(p => p.id === i.poId && p.status !== 'cancelled');
    const picked = anPickedItems().filter(i => SEL_OPEN.includes(i.stage) && !live(i));
    if (!picked.length){ toast('Everything selected is already on a purchase order, or already ordered'); return; }
    // One purchase order per job per FM per vendor — selPORun groups it, because that grouping is the
    // rule (a PO has to match one payment on one job), not a preference of this screen.
    /* No pre-flight questions. Selecting things and pressing this makes the drafts and puts you on the
       first one — everything that used to be asked in a dialog is a field on the document, which is
       where it belongs and where it can still be changed after the fact. */
    const made = selPORun(picked.map(i => i.id), {split: 'vendor'});
    if (!made) return;                       // it says why — a red check on everything picked
    const jobs = new Set(made.map(p => p.projectId)).size;
    anSel.clear(); renderAnalysis();
    const left = (made.skipped || []).length;
    toast(`${made.length} draft purchase order${made.length === 1 ? '' : 's'}${jobs > 1 ? ` across ${jobs} jobs` : ''}${left ? ` · ${left} left behind on a red check` : ''}`);
    setTimeout(() => poAfterRun(made), 40);
    return;
  }
  anAdvance(kind);
}

function renderAnalysis(){
  const root = $('#proc-body'); if (!root) return;
  const rows = anFiltered();
  const t = anTotals(rows);
  const all = anRows();
  const cols = anCols();
  const grain = AN_GROUPS.find(g => g[0] === anGroup) || AN_GROUPS[0];
  const stat = (v, l, cls) => `<div class="sel-stat ${cls || ''}"><b>${v}</b><span>${l}</span></div>`;

  root.innerHTML = `
  ${procTabsHtml()}
  <div class="ph"><div><h2>Analysis — ${esc(anScope === 'all' ? 'every project' : anScope === 'client' ? (anClientOf(S.id) || 'this client') : S.project.name)}</h2>
    <p class="lead">${esc(grain[2])} Every figure is read from the item records, and the totals are of the rows below — change the width, the grouping or a filter and they move with it.</p></div>
    <div class="acts">
      <button class="btn" id="an-csv">Export to Excel</button>
      <button class="btn" id="an-board">Buy board</button>
    </div></div>

  <div class="sel-stats">
    ${stat(money(t.clientValue), 'billed to the client', '')}
    ${stat(money(t.budget), 'budgeted to buy', '')}
    ${stat(money(t.spent), 'actually spent', '')}
    ${stat(money(t.saved), t.savedPct == null ? 'against budget' : `${t.savedPct}% against the ${money(t.boughtBudget)} bought so far`, t.saved > 0 ? 'ok' : t.saved < 0 ? 'bad' : '')}
    ${stat(money(t.fronted), 'the firm is carrying', t.fronted ? 'warn' : '')}
    ${stat(money(t.remaining), 'left to purchase', '')}
    ${stat(t.mu == null ? '—' : t.mu.toFixed(2), 'average markup', '')}
  </div>
  ${t.unbillable.length ? `<p class="note bad" style="margin:10px 0 0"><b>${t.unbillable.length} row${t.unbillable.length === 1 ? '' : 's'} sit on no approved estimate line</b> — nobody has agreed to pay for them. Either the selection never made it onto a proposal, or it should not have been bought. Filter by <b>Not on a bill</b> to see them.</p>` : ''}
  ${t.over.length ? `<p class="note bad" style="margin:10px 0 0"><b>${t.over.length} of ${t.over.length + t.under.length} priced lines came in over budget</b> — ${money(Math.abs(t.overAmt))} between them, against ${money(t.under.reduce((a, r) => a + r.saved, 0))} saved on the rest. A single "under budget" figure hides this; sort by <b>$ saved</b> to see the worst first.</p>` : ''}

  ${anBar()}

  <div class="proc-bar an-lens">
    <span class="small muted">Show</span>
    <select id="an-scope" title="How wide the report reads">${AN_SCOPES.map(([k, l]) => `<option value="${k}" ${anScope === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <span class="small muted">grouped by</span>
    <select id="an-group" title="What each row stands for">${AN_GROUPS.map(([k, l]) => `<option value="${k}" ${anGroup === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <span class="grow"></span>
    <span class="small muted">${all.length} row${all.length === 1 ? '' : 's'} · ${all.reduce((a, r) => a + r.n, 0)} items</span>
  </div>

  <div class="proc-bar">
    <select id="an-fm"><option value="all">All FM packages</option>${[...new Set(all.map(r => r.fm))].sort((a, b) => String(a).localeCompare(String(b), undefined, {numeric: true})).map(f => `<option value="${esc(f)}" ${anFM === f ? 'selected' : ''}>${esc(f)}</option>`).join('')}</select>
    <select id="an-vendor"><option value="all">All vendors</option>${[...new Set(all.map(r => r.vendor))].sort().map(v => `<option value="${esc(v)}" ${anVendor === v ? 'selected' : ''}>${esc(v)}</option>`).join('')}</select>
    <select id="an-cat"><option value="all">All categories</option>${[...new Set(all.map(r => r.cat))].sort().map(c => `<option value="${esc(c)}" ${anCatF === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select>
    <select id="an-fund"><option value="all">Any funding</option><option value="ahead" ${anFunding === 'ahead' ? 'selected' : ''}>Bought ahead of the money</option>${FUND_STATES.map(([k, l]) => `<option value="${k}" ${anFunding === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <select id="an-status"><option value="all">Any status</option>${Object.entries(AN_STATUS).map(([k, l]) => `<option value="${k}" ${anStatus === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
    <input id="an-q" placeholder="Search package, vendor, item, SKU…" value="${esc(anQ)}">
  </div>

  <div class="proc-wrap"><table class="t an">
    <thead><tr><th class="an-cb"><input type="checkbox" id="an-all" ${rows.length && rows.every(r => anSel.has(r.key)) ? 'checked' : ''} title="Select every row shown"></th>${cols.map(([k, l, ty]) => `<th class="${['money', 'pct'].includes(ty) ? 'money' : ty === 'num' ? 'num' : ''} ${anSort === k ? 'sorted' : ''}" data-asort="${k}">${l}${anSort === k ? (anDir > 0 ? ' ↑' : ' ↓') : ''}</th>`).join('')}</tr></thead>
    <tbody>${rows.map(r => `<tr data-anrow="${esc(r.key)}" class="${anSel.has(r.key) ? 'on' : ''}"><td class="an-cb"><input type="checkbox" data-ancb="${esc(r.key)}" ${anSel.has(r.key) ? 'checked' : ''}></td>${cols.map(([k]) => anCell(r, k)).join('')}</tr>`).join('') || `<tr><td colspan="${cols.length + 1}" class="empty">Nothing matches those filters.</td></tr>`}</tbody>
    <tfoot><tr><td colspan="${cols.findIndex(c => c[0] === 'price') + 1}">${rows.length} line${rows.length === 1 ? '' : 's'}${rows.length !== all.length ? ` of ${all.length}` : ''}</td>
      <td class="money">${money(t.budget)}</td><td class="money">${money(t.clientValue)}</td><td class="money">${money(t.spent)}</td>
      <td class="money ${t.saved < 0 ? 'an-over' : 'an-under'}">${money(t.saved)}</td>
      <td class="money ${t.saved < 0 ? 'an-over' : 'an-under'}">${t.savedPct == null ? '' : t.savedPct + '%'}</td><td></td></tr></tfoot>
  </table></div>
  <p class="small muted" style="margin:8px 0 0">Savings compares each line against what those same items were budgeted at — not against the whole package — so a part-bought package cannot show a saving it has not made yet. Days to order is the gap between the day an item was specified and the day it was bought.</p>`;

  wireAnalysis(root);
}

function anCsvText(){
  const rows = anFiltered();
  const cols = anCols();
  const q = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const head = [...cols.map(c => c[1]), 'Items'];
  const cell = (r, k) => k === 'status' ? AN_STATUS[r.status] : anValue(r, k);
  const body = rows.map(r => [...cols.map(c => cell(r, c[0])), r.n].map(q).join(','));
  const t = anTotals(rows);
  const totals = cols.map(c => c[0] === 'price' ? t.budget : c[0] === 'withMU' ? t.clientValue
    : c[0] === 'final' ? t.spent : c[0] === 'saved' ? t.saved : c[0] === 'savedPct' ? (t.savedPct ?? '')
    : c[0] === 'desc' ? 'TOTAL' : '');
  body.push([...totals, ''].map(q).join(','));
  return [head.map(q).join(','), ...body].join('\r\n');
}
const anCsv = anCsvText;   // the old name, for anything already calling it

/* Two ways out, because one of them is often not available: a hosted copy of this app runs in a frame
   that is not allowed to start a download, and a saved file that never arrives is worse than no button.
   So the dialog offers the file and the clipboard, and says which one to reach for. */
function anExportModal(){
  const csv = anCsvText();
  const rows = anFiltered().length;
  const name = `${(S.project.name || 'project').replace(/[^A-Za-z0-9]+/g, '-')}-analysis-${today()}.csv`;
  mbModal('Export to Excel', `
    <p class="small muted" style="margin:0 0 10px">${rows} line${rows === 1 ? '' : 's'} — the columns on screen, plus a TOTAL row so the file adds up on its own. Opens straight into Excel or Sheets.</p>
    <div class="row" style="gap:8px"><button class="btn primary" id="an-dl">Download ${esc(name)}</button><button class="btn" id="an-copy">Copy to the clipboard</button></div>
    <p class="small muted" style="margin:10px 0 0">If nothing downloads — some hosted copies of this app are not allowed to save files — copy it and paste into a blank sheet.</p>
    <textarea id="an-csv-text" readonly style="width:100%;height:120px;margin-top:10px;font-family:ui-monospace,Menlo,monospace;font-size:11px">${esc(csv)}</textarea>`,
    {submit: null});
  const m = document.getElementById('mbm'); if (!m) return csv;
  m.querySelector('#an-dl').onclick = () => {
    try {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob(['\ufeff' + csv], {type: 'text/csv;charset=utf-8'}));
      a.download = name; document.body.appendChild(a); a.click(); a.remove();
      toast(`${rows} lines exported`);
    } catch (e){ toast('This copy of the app cannot save files — copy it instead'); }
  };
  m.querySelector('#an-copy').onclick = async () => {
    const ta = m.querySelector('#an-csv-text');
    try { await navigator.clipboard.writeText(csv); toast('Copied — paste into a blank sheet'); }
    catch (e){ ta.focus(); ta.select(); toast('Press Ctrl-C / Cmd-C to copy'); }
  };
  return csv;
}

function wireAnalysis(root){
  const go = () => renderAnalysis();
  root.querySelectorAll('[data-asort]').forEach(th => th.onclick = () => {
    const k = th.dataset.asort;
    if (anSort === k) anDir *= -1; else { anSort = k; anDir = ['price', 'withMU', 'final', 'saved', 'savedPct', 'days'].includes(k) ? -1 : 1; }
    go();
  });
  root.querySelector('#an-scope').onchange = e => { anScope = e.target.value; anSel.clear(); go(); };
  root.querySelector('#an-group').onchange = e => { anGroup = e.target.value; anSel.clear(); if (anSort === 'code' || anSort === 'po') anSort = 'fm'; go(); };
  root.querySelector('#an-fm').onchange = e => { anFM = e.target.value; go(); };
  root.querySelector('#an-vendor').onchange = e => { anVendor = e.target.value; go(); };
  root.querySelector('#an-cat').onchange = e => { anCatF = e.target.value; go(); };
  root.querySelector('#an-status').onchange = e => { anStatus = e.target.value; go(); };
  root.querySelector('#an-fund').onchange = e => { anFunding = e.target.value; go(); };
  const q = root.querySelector('#an-q');
  q.oninput = () => { anQ = q.value; const at = q.selectionStart; go(); const n = document.getElementById('an-q'); if (n){ n.focus(); n.setSelectionRange(at, at); } };
  root.querySelector('#an-csv').onclick = () => anExportModal();
  wireProcTabs(root);
  root.querySelector('#an-board').onclick = () => { procPane = 'board'; renderProc(); };
  root.querySelector('#an-all').onchange = e => {
    const shown = anFiltered().map(r => r.key);
    if (e.target.checked) shown.forEach(k => anSel.add(k)); else shown.forEach(k => anSel.delete(k));
    go();
  };
  root.querySelectorAll('[data-ancb]').forEach(cb => cb.onclick = e => {
    e.stopPropagation();
    const k = cb.dataset.ancb;
    if (cb.checked) anSel.add(k); else anSel.delete(k);
    go();
  });
  root.querySelectorAll('[data-anact]').forEach(b => b.onclick = () => anAct(b.dataset.anact));
  root.querySelectorAll('[data-anrow]').forEach(tr => tr.onclick = (e) => {
    if (e.target.closest('.an-cb')) return;
    const row = anRows().find(r => r.key === tr.dataset.anrow); if (!row) return;
    anRowModal(row);
  });
}

// What is behind one line of the report — because the first question anyone asks a total is "which
// items?", and the second is "can I fix that one from here".
function anRowModal(r){
  const draw = () => {
    mbModal(`${esc(r.fm)} · ${esc(r.vendor)}`, `
      <table class="t"><thead><tr><th>Item</th><th>SKU</th><th>Stage</th><th class="num">Qty</th><th class="money">Budget</th><th class="money">Actual</th><th class="money">Difference</th><th></th></tr></thead>
      <tbody>${r.items.map(i => { const a = selActual(i), b = selLineCost(i); const d = a ? r2(b - a) : null;
        const back = (DB.sel.returns || []).find(x => x.itemId === i.id && x.status !== 'closed');
        return `<tr><td>${esc(i.name)}</td><td class="sub">${esc(i.sku || '')}</td>
          <td><span class="pill ${SEL_STAGE[i.stage]?.cls || ''}">${esc(SEL_STAGE[i.stage]?.label || i.stage)}</span></td>
          <td class="num">${selQty(i)}</td><td class="money">${money(b)}</td><td class="money">${a ? money(a) : '<span class="muted">—</span>'}</td>
          <td class="money ${d == null ? '' : d < 0 ? 'an-over' : 'an-under'}">${d == null ? '<span class="muted">—</span>' : money(d)}</td>
          <td style="white-space:nowrap">${back ? `<span class="pill warn" title="${esc(RET_REASON[back.reason]?.label || back.reason)}">going back</span>`
            : `<button class="btn sm ghost" data-anret="${i.id}" title="Send this item back to the vendor">Return…</button>`}
            <button class="btn sm ghost" data-anitem="${i.id}" title="Open the item">Open</button></td></tr>`; }).join('')}
      </tbody></table>
      <p class="small muted" style="margin:10px 0 0">Actual is what was paid including shipping and tax — the number Chen calls fully baked in. A line with no actual yet is not counted as a saving.</p>`,
      {submit: null});
    procWide(940);
    const m2 = document.getElementById('mbm'); if (!m2) return;
    m2.querySelectorAll('[data-anret]').forEach(b => b.onclick = () => anReturnModal(selItem(b.dataset.anret), draw));
    m2.querySelectorAll('[data-anitem]').forEach(b => b.onclick = () => {
      const it = selItem(b.dataset.anitem); if (!it) return;
      mbCloseModal();
      if (it.projectId !== S.id) setCurrent(it.projectId);
      setView('sel'); render();
      setTimeout(() => { if (typeof selOpenItem === 'function') selOpenItem(it.id); }, 60);
    });
  };
  draw();
}

/* A return raised from here rather than from the board, because this is the screen where someone
   notices that a line cost more than it should have — which is often the moment they remember the
   box in the office that never went back. */
function anReturnModal(it, back){
  if (!it) return;
  if (typeof retRaise !== 'function'){ toast('Returns are not available in this copy'); return; }
  mbModal(`Send back — ${esc(it.name)}`, `
    <div class="grid2">
      <div class="f"><label>Why</label><select data-f="reason">${RET_REASONS.map(([k, l]) => `<option value="${k}">${esc(l)}</option>`).join('')}</select></div>
      <div class="f"><label>How many of the ${selQty(it)}</label><input class="num" type="number" step="any" data-f="qty" value="${selQty(it)}"></div>
    </div>
    <div class="f"><label>Note</label><input data-f="note" placeholder="What is wrong with it, or why it is going back"></div>
    <p class="small muted" style="margin:8px 0 0" id="an-ret-why">${esc(RET_REASONS[0][2])}</p>
    <p class="small muted" style="margin:8px 0 0">The return window and any restocking fee come from what we know about ${esc(it.vendor || 'this vendor')}. It becomes money owed to us and is chased until a credit lands on the statement.</p>`,
    {submit: 'Raise the return', onSubmit: f => {
      const r = retRaise(it, {reason: f.reason, qty: +f.qty || selQty(it), note: f.note || ''});
      audit('sel-item', it.id, 'return-raised', null, {reason: f.reason, via: 'analysis'});
      log(`Return raised on ${it.name} — ${RET_REASON[f.reason]?.label || f.reason}`);
      save();
      toast(`${it.name} is going back${r && r.returnBy ? ` — window closes ${fmt(r.returnBy)}` : ''}`);
      setTimeout(() => { if (typeof back === 'function') back(); renderAnalysis(); }, 30);
    }});
  const m3 = document.getElementById('mbm'); if (!m3) return;
  const sel = m3.querySelector('[data-f="reason"]'), why = m3.querySelector('#an-ret-why');
  sel.onchange = () => { why.textContent = RET_REASON[sel.value]?.why || ''; };
}

/* ---------- where it lives ----------
   A report is a screen, not a dialog. Chen said of the Houzz preview "I never clicked on it" after a
   year of use; a modal behind a button is where features go to be undiscovered. This is a pane of
   Procurement with a way back to the board. */
let procPane = 'board';

/* Three panes, one strip. Before this the panes were entered through buttons that sat among the
   actions — so once you were on the report there was nothing saying where you were or what else
   existed, and the way back was a button on the far side of the screen. Navigation and actions are
   different things and should not share a row. */
const PROC_PANES = [
  ['board',    'Buy board',    'What has to be ordered, and when'],
  ['analysis', 'Analysis',     "Chen's report: budget, spend, savings by package"],
  ['cost',     'Cost by line', 'Every contract line by rough, labour, subs and finish'],
];
const procTabsHtml = () => `<div class="ctabs proc-panes no-print">${PROC_PANES.map(([k, l, why]) =>
  `<button class="${procPane === k ? 'on' : ''}" data-ppane="${k}" title="${esc(why)}">${l}</button>`).join('')}</div>`;
function wireProcTabs(root){
  (root || document).querySelectorAll('[data-ppane]').forEach(b => b.onclick = () => {
    if (procPane === b.dataset.ppane) return;
    procPane = b.dataset.ppane; renderProc();
  });
}
if (typeof renderProc === 'function'){
  const renderProcBase_an = renderProc;
  renderProc = function(){
    if (procPane === 'analysis' && view === 'proc') return renderAnalysis();
    const out = renderProcBase_an();
    const root = document.getElementById('proc-body');
    if (root && !root.querySelector('.proc-panes')){
      root.insertAdjacentHTML('afterbegin', procTabsHtml());
      wireProcTabs(root);
    }
    return out;
  };
}
/*<</analysis.js>>*/

/*<<dnd.js>>*/
/* ===================== DRAG TO REORDER =====================
   An estimate is read in the order the lines sit in, and that order is a judgement: the kitchen first
   because that is what the client cares about, the long-lead items at the top because that is what has
   to be bought. Up-and-down buttons make you click eleven times to move one line eleven places.

   One helper, three grids — the finish-materials sheet, the plain lines table, and the construction
   estimate, where a sub-item travels with the line it belongs to. Pointer events rather than HTML5
   drag-and-drop, because the same code then works on a tablet on site.

   Two rules that matter more than the animation:
     · Dragging is disabled while the sheet is sorted by a column. What you see is not the document
       order then, so a drop would move a line somewhere nobody pointed at.
     · The handle is a real button. Focus it and the arrow keys move the line, which is faster than
       dragging for one step and is the only way to do this without a mouse.
*/

// A grip, drawn rather than typed: two columns of dots, the convention everywhere this gesture exists.
const DND_GRIP = '<svg viewBox="0 0 10 16" width="10" height="16" aria-hidden="true"><g fill="currentColor"><circle cx="3" cy="4" r="1.15"/><circle cx="7" cy="4" r="1.15"/><circle cx="3" cy="8" r="1.15"/><circle cx="7" cy="8" r="1.15"/><circle cx="3" cy="12" r="1.15"/><circle cx="7" cy="12" r="1.15"/></g></svg>';
const dndGrip = (id, label) => `<button class="dnd-grip" data-grip="${id}" tabindex="0" title="Drag to move${label ? ` ${label}` : ''}, or use the arrow keys" aria-label="Reorder${label ? ` ${label}` : ''}">${DND_GRIP}</button>`;
const dndLocked = why => `<span class="dnd-grip off" title="${esc(why)}" aria-hidden="true">${DND_GRIP}</span>`;

/* root      — the element containing the rows
   rowSel    — CSS for a row, e.g. 'tr[data-fmline]' or '.ct-row'
   idOf      — row element → the line id it stands for
   blockOf   — id → the ids that must move with it (a parent takes its sub-items). Default: itself.
   onOrder   — called with the new full order of ids, once, on drop or key press. */
function dndRows(root, {rowSel, idOf, blockOf, onOrder}){
  if (!root) return;
  const rows = () => [...root.querySelectorAll(rowSel)];
  const ids = () => rows().map(idOf);
  const block = id => (blockOf ? blockOf(id) : [id]);

  // Move a whole block to sit before `beforeId` (or last, when null), and hand back the new order.
  const reorder = (id, beforeId) => {
    const b = block(id);
    const rest = ids().filter(x => !b.includes(x));
    const at = beforeId == null ? rest.length : rest.indexOf(beforeId);
    if (at < 0) return null;
    return [...rest.slice(0, at), ...b, ...rest.slice(at)];
  };

  root.querySelectorAll('[data-grip]').forEach(grip => {
    const id = grip.dataset.grip;

    grip.addEventListener('keydown', e => {
      const dir = e.key === 'ArrowUp' ? -1 : e.key === 'ArrowDown' ? 1 : 0;
      if (!dir) return;
      e.preventDefault();
      const order = ids();
      const b = block(id);
      const rest = order.filter(x => !b.includes(x));
      const first = order.indexOf(b[0]);
      // Step over the whole block that sits next to us, not one row of it.
      const anchor = dir < 0 ? order[first - 1] : order[first + b.length];
      if (anchor == null) return;                      // already at the top or the bottom
      const anchorBlock = block(anchor);
      const target = dir < 0 ? anchorBlock[0] : anchorBlock[anchorBlock.length - 1];
      const at = rest.indexOf(target);
      if (at < 0) return;
      const next = dir < 0 ? [...rest.slice(0, at), ...b, ...rest.slice(at)]
                           : [...rest.slice(0, at + 1), ...b, ...rest.slice(at + 1)];
      onOrder(next, id);
    });

    grip.addEventListener('pointerdown', e => {
      if (e.button != null && e.button !== 0) return;
      e.preventDefault();
      const start = rows().find(r => idOf(r) === id); if (!start) return;
      const moving = block(id).map(x => rows().find(r => idOf(r) === x)).filter(Boolean);
      moving.forEach(r => r.classList.add('dnd-moving'));
      root.classList.add('dnd-on');
      grip.setPointerCapture(e.pointerId);
      let dropBefore = undefined;   // undefined = unchanged, null = the end

      const paint = ev => {
        const others = rows().filter(r => !moving.includes(r));
        root.querySelectorAll('.dnd-over,.dnd-over-end').forEach(r => r.classList.remove('dnd-over', 'dnd-over-end'));
        let before = null;
        for (const r of others){
          const box = r.getBoundingClientRect();
          if (ev.clientY < box.top + box.height / 2){ before = idOf(r); break; }
        }
        dropBefore = before;
        if (before != null) others.find(r => idOf(r) === before)?.classList.add('dnd-over');
        else others[others.length - 1]?.classList.add('dnd-over-end');
      };
      const stop = () => {
        grip.removeEventListener('pointermove', paint);
        grip.removeEventListener('pointerup', done);
        grip.removeEventListener('pointercancel', cancel);
        moving.forEach(r => r.classList.remove('dnd-moving'));
        root.classList.remove('dnd-on');
        root.querySelectorAll('.dnd-over,.dnd-over-end').forEach(r => r.classList.remove('dnd-over', 'dnd-over-end'));
      };
      const done = () => {
        stop();
        if (dropBefore === undefined) return;      // a click, not a drag
        const next = reorder(id, dropBefore);
        if (next) onOrder(next, id);
      };
      const cancel = () => stop();
      grip.addEventListener('pointermove', paint);
      grip.addEventListener('pointerup', done);
      grip.addEventListener('pointercancel', cancel);
    });
  });
}

// Put the document's lines into the order the ids describe. Anything the caller did not mention keeps
// its place at the end, so a stale id can never silently drop a line off an estimate.
function dndApply(d, order){
  const by = Object.fromEntries(d.lines.map(l => [l.id, l]));
  const out = order.map(id => by[id]).filter(Boolean);
  d.lines.forEach(l => { if (!out.includes(l)) out.push(l); });
  d.lines = out;
}
/*<</dnd.js>>*/

/*<<fmcols.js>>*/
/* ===================== FINISH-MATERIALS ESTIMATE — the columns =====================
   From the 8 Sep walkthrough, where Chen and Alan went left to right across the Houzz proposal grid.
   What they were looking at is a spreadsheet whose columns happen to be a contract: some of them the
   client sees and signs, some of them are ours. Houzz gets two things right — you can turn columns on
   and off, and you can invent your own (Chen's office tag, "121-4") — and one thing wrong: the columns
   are decoration on a line, so the same faucet is typed into the proposal, the PO and the tracker.

   So the model here is a column REGISTRY. Every column declares its type, whether the client sees it,
   and where its value comes from. A line is just data; the grid, the client preview and the printed
   PDF are three readings of the same registry. Turning a column off cannot lose the value behind it,
   and marking a column client-visible is the only thing that decides what gets printed.

   The registry is also what lets a selection become an estimate line without anyone retyping it: both
   sides speak the same field names.
*/

const FM_UNITS = ['ea', 'pc', 'set', 'pr', 'sf', 'lf', 'sy', 'box', 'roll', 'gal', 'hr', 'day', 'ls'];
const FM_UNIT_LABEL = {ea: 'each', pc: 'pieces', set: 'set', pr: 'pair', sf: 'sq ft', lf: 'lin ft', sy: 'sq yd',
                       box: 'boxes', roll: 'rolls', gal: 'gallons', hr: 'hours', day: 'days', ls: 'flat rate'};

/* key, label, type, width, {client, def, help} — client:true means the client sees it and it prints. */
const FM_COLS = [
  ['img',          'Image',            'img',    46,  {client: true,  def: true,  help: 'What the client is looking at. Nothing else in a proposal does as much work.'}],
  ['item',         'Item',             'text',   190, {client: true,  def: true,  lock: true}],
  ['desc',         'Description',      'text',   200, {client: true,  def: true}],
  ['sku',          'SKU',              'text',   106, {client: false, def: true,  help: 'A description is not an identity. Two things that look the same are told apart by this.'}],
  ['manufacturer', 'Manufacturer',     'text',   112, {client: true,  def: false}],
  ['room',         'Room',             'room',   118, {client: true,  def: true,  help: 'Chen calls it location. Sorting by it is how a proposal becomes a buy list.'}],
  ['finish',       'Colour / finish',  'text',   116, {client: true,  def: true}],
  ['dims',         'Dimensions',       'text',   106, {client: true,  def: true}],
  ['qty',          'Qty',              'num',    58,  {client: true,  def: true}],
  ['unit',         'Unit',             'unit',   78,  {client: true,  def: true}],
  ['cost',         'Unit cost',        'money',  88,  {client: false, def: true,  help: 'What we pay. Never printed.'}],
  ['markupPct',    'Markup %',         'pct',    72,  {client: false, def: true,  help: 'Unit price is cost plus this. Edit either one and the other follows.'}],
  ['rate',         'Unit price',       'money',  92,  {client: true,  def: true}],
  ['amount',       'Amount',           'calc',   96,  {client: true,  def: true,  lock: true}],
  ['shipping',     'Shipping',         'money',  80,  {client: true,  def: false}],
  ['shipMarkupPct','Shipping markup',  'pct',    72,  {client: false, def: false}],
  ['taxable',      'Tax',              'check',  42,  {client: true,  def: true}],
  ['vendor',       'Vendor',           'text',   112, {client: false, def: true}],
  ['url',          'Link',             'link',   64,  {client: false, def: true,  help: 'The vendor page this was specified from — the most important column on the screen, in Chen’s words, and the one Houzz buries.'}],
  ['leadDays',     'Lead',             'days',   62,  {client: false, def: true,  help: 'Sortable, so the long poles get bought first.'}],
  ['needOnSite',   'On site by',       'date',   96,  {client: false, def: false}],
  ['tag',          'Office tag',       'text',   82,  {client: false, def: false, help: 'The code on the box in the office, so the site can be told what to look for.'}],
  ['cat',          'Category',         'text',   110, {client: false, def: false}],
];
const FM_COL = Object.fromEntries(FM_COLS.map(([k, label, type, w, o]) => [k, {k, label, type, w, ...o}]));

const FM_CUSTOM_TYPES = [['text', 'Text'], ['num', 'Number'], ['money', 'Money'], ['check', 'Checkbox'],
                         ['select', 'Single select'], ['date', 'Date'], ['days', 'Duration (days)'], ['link', 'Link']];

/* ---------- what this document shows ----------
   Defaults live on the company so a firm decides its house layout once; a document may override, so a
   one-off proposal can show a column without changing everybody else's. */
function fmInit(){
  DB.company.fmCols = DB.company.fmCols || FM_COLS.filter(c => c[4].def).map(c => c[0]);
  DB.company.fmClient = DB.company.fmClient || FM_COLS.filter(c => c[4].client).map(c => c[0]);
  DB.company.fmCustom = DB.company.fmCustom || [];
}
const fmCustom = () => (DB.company.fmCustom = DB.company.fmCustom || []);
const fmDef = k => FM_COL[k] || fmCustom().find(c => c.k === k);
function fmCols(d){
  fmInit();
  const keys = (d && d.cols && d.cols.length) ? d.cols : DB.company.fmCols;
  return keys.map(fmDef).filter(Boolean);
}
function fmIsClient(d, k){
  const c = fmDef(k);
  if (!c) return false;
  const list = (d && d.clientCols) || DB.company.fmClient;
  return list.includes(k);
}
/* Chen widens and narrows columns as he works — a name column that fits and a price column that does
   not is the difference between reading the sheet and fighting it. A width set on the document stays
   with the document; set with nothing open, it becomes the house default. */
function fmWidth(d, k){
  const col = fmDef(k); if (!col) return 100;
  return ((d && d.colW && d.colW[k]) ?? (DB.company.fmW || {})[k] ?? col.w);
}
function fmSetWidth(d, k, px){
  px = Math.max(38, Math.min(460, Math.round(px)));
  d.colW = d.colW || {}; d.colW[k] = px;
}
const fmSetCols = (d, keys) => { if (d.cols || keys.join() !== DB.company.fmCols.join()) d.cols = keys; else DB.company.fmCols = keys; };

/* ---------- values ----------
   Unit price and unit cost are two ends of the same fact. Typing either should move the other, because
   a buyer thinks in cost and a client reads price, and making someone maintain both is how they drift. */
/* Whole dollars are right for a total and wrong for a unit price: tile at $6.60 a square foot is not
   tile at $7 a square foot, and a client who multiplies it out will find the difference. */
const fmMoney = n => { const v = +n || 0; return Number.isInteger(v) ? money(v) : (v < 0 ? '−$' : '$') + Math.abs(v).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}); };
const fmMarkup = l => l.markupPct == null ? (DB.company.fmMarkup ?? 0) : +l.markupPct;
function fmSetField(d, l, k, v){
  const c = fmDef(k);
  if (!c) return;
  if (c.type === 'check'){ l[k] = !!v; return; }
  if (['num', 'money', 'pct', 'days'].includes(c.type)) v = v === '' ? '' : +v || 0;
  l[k] = v;
  if (k === 'cost' || k === 'markupPct') l.rate = r2((+l.cost || 0) * (1 + fmMarkup(l) / 100));
  else if (k === 'rate' && +l.cost) l.markupPct = r2(((+l.rate || 0) / (+l.cost) - 1) * 100);
}
function fmValue(d, l, k){
  if (k === 'amount') return lineAmount(l, d);
  return l[k];
}

/* ---------- images ----------
   A picture belongs on the line, not in an attachment nobody opens. Three ways in, because the three
   ways it actually arrives are: the clipper already has one, someone has a file, someone has a link. */
const fmImgSrc = l => {
  const v = l.img || '';
  if (!v) return '';
  if (v.startsWith('blob:')) return blobCache[v.slice(5)] || '';
  return v;
};
async function fmAttachImage(d, l, file){
  const dataUrl = await new Promise((res, rej) => { const fr = new FileReader(); fr.onload = () => res(fr.result); fr.onerror = rej; fr.readAsDataURL(file); });
  const small = await fmShrink(dataUrl, 640);
  const id = uid('im');
  await putBlob(id, small);
  l.img = 'blob:' + id;
  save();
}
// A proposal with forty photographs at full resolution is a proposal nobody can open. 640px is plenty
// for a thumbnail and for the printed sheet.
function fmShrink(dataUrl, max){
  return new Promise(res => {
    const img = new Image();
    img.onload = () => {
      const s = Math.min(1, max / Math.max(img.width, img.height));
      if (s >= 1) return res(dataUrl);
      const cv = document.createElement('canvas');
      cv.width = Math.round(img.width * s); cv.height = Math.round(img.height * s);
      cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
      try { res(cv.toDataURL('image/jpeg', 0.82)); } catch (e){ res(dataUrl); }
    };
    img.onerror = () => res(dataUrl);
    img.src = dataUrl;
  });
}

/* ---------- the grid ---------- */
let fmSort = '', fmDir = 1, fmPreview = false;
function fmOrdered(d){
  if (!fmSort) return d.lines;
  const c = fmDef(fmSort);
  const val = l => { const v = fmValue(d, l, fmSort); return c && ['num', 'money', 'pct', 'days', 'calc'].includes(c.type) ? (+v || 0) : String(v ?? '').toLowerCase(); };
  return [...d.lines].sort((a, b) => { const x = val(a), y = val(b); return (typeof x === 'number' ? x - y : x.localeCompare(y)) * fmDir; });
}

function fmCell(d, l, c, editable, extra){
  const ro = editable ? '' : 'readonly';
  const cls = (s) => `${s || ''}${extra && extra.cls ? ' ' + extra.cls : ''}`;
  const sty = extra && extra.style ? ` style="${extra.style}"` : '';
  // A sheet nobody can type into should not look like a form. Read-only — a sent document, or the
  // client's own view — renders as text, which is also what prints properly.
  if (!editable && c.type !== 'img'){
    const v0 = fmValue(d, l, c.k);
    if (c.type === 'check') return `<td class="${cls('')}" style="text-align:center${extra && extra.style ? ';' + extra.style : ''}">${v0 ? '<span class="fm-tick">✓</span>' : ''}</td>`;
    if (c.type === 'link') return `<td class="${cls('fm-link')}"${sty}>${v0 ? `<a href="${esc(v0)}" target="_blank" rel="noopener">open</a>` : ''}</td>`;
    if (['money', 'calc'].includes(c.type)) return `<td class="${cls('amt')}"${sty}>${v0 === '' || v0 == null ? '' : fmMoney(v0)}</td>`;
    if (c.type === 'pct') return `<td class="${cls('amt')}"${sty}>${v0 === '' || v0 == null ? '' : r2(v0) + '%'}</td>`;
    if (c.type === 'days') return `<td class="${cls('amt')}"${sty}>${v0 ? v0 + ' d' : ''}</td>`;
    if (c.type === 'num') return `<td class="${cls('amt')}"${sty} style="font-weight:400">${v0 ?? ''}</td>`;
    if (c.type === 'unit') return `<td class="${cls('')}"${sty}>${esc(FM_UNIT_LABEL[v0] || v0 || '')}</td>`;
    if (c.type === 'date') return `<td class="${cls('')}"${sty}>${v0 ? fmt(v0) : ''}</td>`;
    return `<td class="${cls('')}"${sty}>${esc(v0 ?? '')}</td>`;
  }
  const v = fmValue(d, l, c.k);
  switch (c.type){
    case 'img': {
      const src = fmImgSrc(l);
      return `<td class="${cls('fm-img')}"${sty}>${src ? `<img src="${esc(src)}" alt="" loading="lazy" data-fmimg="${l.id}">`
        : `<button class="fm-noimg" data-fmimg="${l.id}" title="Add a picture">+</button>`}</td>`;
    }
    case 'calc':  return `<td class="${cls('amt')}"${sty}>${fmMoney(v)}</td>`;
    case 'check': return `<td class="${cls('')}" style="text-align:center${extra && extra.style ? ';' + extra.style : ''}"><input type="checkbox" data-fmf="${c.k}" ${v ? 'checked' : ''} ${editable ? '' : 'disabled'} style="width:auto"></td>`;
    case 'link':  return `<td class="${cls('fm-link')}"${sty}>${v ? `<a href="${esc(v)}" target="_blank" rel="noopener" title="${esc(v)}">open</a>` : ''}${editable ? `<button class="fm-mini" data-fmlink="${l.id}" title="${v ? 'Change the link' : 'Add a link'}">${v ? '✎' : '+'}</button>` : ''}</td>`;
    case 'room':  return `<td class="${cls('')}"${sty}><input data-fmf="room" list="fm-rooms" value="${esc(v || '')}" ${ro} placeholder="Room"></td>`;
    case 'unit':  return `<td class="${cls('')}"${sty}><select data-fmf="unit" ${editable ? '' : 'disabled'}>${FM_UNITS.map(u => `<option value="${u}" ${v === u ? 'selected' : ''}>${FM_UNIT_LABEL[u]}</option>`).join('')}</select></td>`;
    case 'select':return `<td class="${cls('')}"${sty}><select data-fmf="${c.k}" ${editable ? '' : 'disabled'}><option value=""></option>${(c.options || []).map(o => `<option value="${esc(o)}" ${v === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select></td>`;
    case 'date':  return `<td class="${cls('')}"${sty}><input type="date" data-fmf="${c.k}" value="${esc(v || '')}" ${ro}></td>`;
    case 'days':  return `<td class="${cls('')}"${sty}><input class="num" type="number" step="1" data-fmf="${c.k}" value="${v ?? ''}" ${ro} placeholder="d"></td>`;
    case 'num':   return `<td class="${cls('')}"${sty}><input class="num" type="number" step="any" data-fmf="${c.k}" value="${v ?? ''}" ${ro}></td>`;
    case 'money': return `<td class="${cls('')}"${sty}><input class="num" type="number" step="0.01" data-fmf="${c.k}" value="${v ?? ''}" ${ro}></td>`;
    case 'pct':   return `<td class="${cls('')}"${sty}><input class="num" type="number" step="0.1" data-fmf="${c.k}" value="${v ?? ''}" ${ro}></td>`;
    default:      return `<td class="${cls('')}"${sty}><input data-fmf="${c.k}" value="${esc(v ?? '')}" ${ro}></td>`;
  }
}

function fmLinesHtml(c, d, editable, kind){
  fmInit();
  // Preview is not a second renderer. It is the same grid with the client's columns and nothing else —
  // which is the point of marking a column client-visible in the first place, and the only honest way
  // to answer "what will they actually see".
  if (fmPreview) editable = false;
  const cols = fmCols(d).filter(col => !fmPreview || fmIsClient(d, col.k));
  const rooms = [...new Set(d.lines.map(l => l.room).filter(Boolean).concat(roomNamesFor(d)))].sort();
  // The first columns stay put while the sheet scrolls right, so a price four columns over still has a
  // name attached to it. Only the picture and the item earn that; everything else scrolls.
  const stick = {}; let off = 0;
  for (const col of cols){ if (col.k !== 'img' && col.k !== 'item') break; stick[col.k] = off; off += fmWidth(d, col.k); }
  const extraFor = (col) => ({cls: (fmIsClient(d, col.k) ? '' : 'int') + (col.k in stick ? ' fm-stick' : ''),
                              style: col.k in stick ? `left:${stick[col.k]}px` : ''});
  const totalCost = d.lines.reduce((a, l) => a + (+l.cost || 0) * (+l.qty || 0), 0);
  const sub = docTotal(d).sub;
  const bar = `<div class="row no-doc-print" style="gap:8px;align-items:center;margin-bottom:6px">
    <button class="btn sm ${fmPreview ? 'primary' : ''}" id="fm-preview">${fmPreview ? 'Back to editing' : 'Preview as the client'}</button>
    ${fmPreview ? `<span class="small muted">${cols.length} of ${fmCols(d).length} columns — this is the sheet they sign.</span>` : ''}</div>`;
  return bar + `<datalist id="fm-rooms">${rooms.map(r => `<option value="${esc(r)}">`).join('')}</datalist>
  <div class="fm-wrap"><table class="lines fm">
    <thead><tr>${editable ? `<th class="fm-grip" title="Drag a line by its handle to change the order"></th>` : ''}${cols.map(col => `<th class="${fmIsClient(d, col.k) ? '' : 'int'}${fmSort === col.k ? ' sorted' : ''}${col.k in stick ? ' fm-stick' : ''}" style="width:${fmWidth(d, col.k)}px${col.k in stick ? `;left:${stick[col.k]}px` : ''}" title="${esc(col.help || col.label)}${fmIsClient(d, col.k) ? '' : ' · internal, never printed'}"><span class="fm-h" data-fmsort="${col.k}">${col.type === 'img' ? '<svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.3"><rect x="1.5" y="2.5" width="13" height="11" rx="1.5"/><circle cx="5.5" cy="6.5" r="1.2"/><path d="M2 11l3.5-3 3 2.5L11 8l3 3"/></svg>' : esc(col.label)}${fmSort === col.k ? (fmDir > 0 ? ' ↑' : ' ↓') : ''}</span><span class="fm-rz" data-fmrz="${col.k}" title="Drag to widen"></span></th>`).join('')}<th style="width:26px"></th></tr></thead>
    <tbody>${fmOrdered(d).map(l => `<tr data-fmline="${l.id}">${editable ? `<td class="fm-grip">${fmSort ? dndLocked('Sorted by a column — clear the sort to move lines by hand') : dndGrip(l.id, esc(l.item || 'this line'))}</td>` : ''}${cols.map(col => fmCell(d, l, col, editable, extraFor(col))).join('')}<td>${editable ? `<span class="rm" data-rmline="${l.id}" title="Remove line">✕</span>` : ''}</td></tr>`).join('')}</tbody>
  </table></div>
  ${kind !== 'invoice' && !fmPreview ? `<div class="small muted no-doc-print" style="margin:2px 0 8px">Shaded columns are ours — cost, markup, vendor, SKU, the link, lead time — and never print. Budget ${money(totalCost)} · margin ${sub ? Math.round((sub - totalCost) / sub * 100) : 0}%.</div>` : ''}
  ${editable && !fmPreview ? `<div class="row no-doc-print" style="gap:8px">
    <button class="btn sm" data-addline>+ Add line</button>
    <button class="btn sm" id="fm-from-sel">Add from selections…</button>
    <button class="btn sm" id="fm-cols">Columns…</button>
    ${fmSort ? `<button class="btn sm ghost" id="fm-unsort">Clear sort</button><button class="btn sm" id="fm-applysort">Keep this order</button><span class="small muted">Sorted by ${esc(fmDef(fmSort)?.label || fmSort)} — lines cannot be dragged while a sort is on.</span>` : `<span class="small muted">Drag a line by its handle to reorder it.</span>`}
  </div>` : ''}`;
}
// Rooms already known to this job, so the column is a real list rather than free text everyone spells differently.
function roomNamesFor(d){
  const out = [];
  try {
    const p = DB.projects.find(x => x.id === d.projectId);
    if (p && typeof roomsOf === 'function') roomsOf(p.id).forEach(r => out.push(r.name));
    if (typeof selItems === 'function' && p) selItems(p.id).forEach(i => { if (i.room) out.push(i.room); });
  } catch (e){}
  return out;
}

/* ---------- the column chooser ---------- */
function fmColsModal(c, d){
  const on = fmCols(d).map(x => x.k);
  const all = [...FM_COLS.map(x => x[0]), ...fmCustom().map(x => x.k)];
  const off = all.filter(k => !on.includes(k));
  const row = (k, shown, i) => {
    const col = fmDef(k);
    const client = fmIsClient(d, k);
    return `<li data-ck="${k}" class="${shown ? '' : 'off'}">
      <label class="fm-ck"><input type="checkbox" data-fmon="${k}" ${shown ? 'checked' : ''} ${col.lock ? 'disabled' : ''}> <b>${esc(col.label)}</b></label>
      <label class="fm-ck small" title="Client-visible columns are the only ones that print"><input type="checkbox" data-fmclient="${k}" ${client ? 'checked' : ''}> client sees it</label>
      <span class="small muted">${esc(col.help || (col.custom ? 'Custom column' : ''))}</span>
      ${shown ? `<span class="fm-ord"><button data-fmmv="${k}:-1" title="Up">↑</button><button data-fmmv="${k}:1" title="Down">↓</button></span>` : ''}
      ${col.custom ? `<button class="fm-mini" data-fmdel="${k}" title="Delete this column">✕</button>` : ''}
    </li>`;
  };
  mbModal('Columns', `
    <p class="small muted" style="margin:0 0 10px">A column being off does not lose what is behind it — turn it back on and the values are still there. <b>Client sees it</b> is the only thing that decides what prints: everything else is ours and shades yellow on screen.</p>
    <ul class="fm-cols">${on.map((k, i) => row(k, true, i)).join('')}</ul>
    ${off.length ? `<h4 style="margin:14px 0 6px">Not shown</h4><ul class="fm-cols">${off.map(k => row(k, false)).join('')}</ul>` : ''}
    ${(d.colW && Object.keys(d.colW).length) ? `<p class="small" style="margin:10px 0 0"><button class="btn sm ghost" id="fm-wreset">Reset column widths</button></p>` : ''}
    <h4 style="margin:14px 0 6px">Your own column</h4>
    <p class="small muted" style="margin:0 0 8px">Chen keeps the office tag this way — the code written on the box, so the site can be told what to look for. Anything you add here is sortable and reportable like the rest.</p>
    <div class="fm-3">
      <div class="f"><label>Name</label><input data-f="cname" placeholder="Office tag"></div>
      <div class="f"><label>Type</label><select data-f="ctype">${FM_CUSTOM_TYPES.map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select></div>
      <div class="f"><label>Choices, if a select</label><input data-f="copts" placeholder="Ordered, Received, On site"></div>
    </div>`,
    {submit: 'Add the column', onSubmit: f => {
      if (!f.cname) return;
      const k = 'x_' + f.cname.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
      // A second column called Office tag is how a firm ends up with the tag in two places and the
      // right one in neither. If the name is already taken, turn that column on instead of making a twin.
      const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
      const dup = [...FM_COLS.map(x => FM_COL[x[0]]), ...fmCustom()].find(col => norm(col.label) === norm(f.cname));
      if (dup){
        if (fmCols(d).some(x => x.k === dup.k)){ toast(`${dup.label} is already on the sheet`); return false; }
        fmSetCols(d, [...fmCols(d).map(x => x.k), dup.k]);
        save(); render();
        toast(`${dup.label} already exists — turned it on`);
        return;
      }
      fmCustom().push({k, label: f.cname, type: f.ctype || 'text', w: f.ctype === 'check' ? 46 : 110, custom: true,
                       client: false, options: (f.copts || '').split(',').map(s => s.trim()).filter(Boolean)});
      fmSetCols(d, [...fmCols(d).map(x => x.k), k]);
      audit('doc-cols', d.id, 'custom-column-added', null, {name: f.cname, type: f.ctype});
      save(); render();
      toast(`${f.cname} added`);
    }});
  procWide(820);
  const m = document.getElementById('mbm'); if (!m) return;
  const refresh = () => { save(); mbCloseModal(); render(); fmColsModal(c, d); };
  m.querySelector('#fm-wreset')?.addEventListener('click', () => { delete d.colW; refresh(); });
  m.querySelectorAll('[data-fmon]').forEach(cb => cb.onchange = () => {
    const k = cb.dataset.fmon;
    const keys = fmCols(d).map(x => x.k);
    fmSetCols(d, cb.checked ? [...keys, k] : keys.filter(x => x !== k));
    refresh();
  });
  m.querySelectorAll('[data-fmclient]').forEach(cb => cb.onchange = () => {
    const k = cb.dataset.fmclient;
    const list = ((d.clientCols || DB.company.fmClient) || []).slice();
    const next = cb.checked ? [...new Set([...list, k])] : list.filter(x => x !== k);
    if (d.clientCols || next.join() !== DB.company.fmClient.join()) d.clientCols = next; else DB.company.fmClient = next;
    refresh();
  });
  m.querySelectorAll('[data-fmmv]').forEach(b => b.onclick = () => {
    const [k, dir] = b.dataset.fmmv.split(':');
    const keys = fmCols(d).map(x => x.k);
    const i = keys.indexOf(k), j = i + (+dir);
    if (j < 0 || j >= keys.length) return;
    keys.splice(j, 0, keys.splice(i, 1)[0]);
    fmSetCols(d, keys);
    refresh();
  });
  m.querySelectorAll('[data-fmdel]').forEach(b => b.onclick = () => {
    const k = b.dataset.fmdel;
    DB.company.fmCustom = fmCustom().filter(x => x.k !== k);
    fmSetCols(d, fmCols(d).map(x => x.k).filter(x => x !== k));
    refresh();
  });
}

/* ---------- pulling the selections in ----------
   The whole reason the columns exist. Maya clipped it, the board verified it, and the estimate line is
   the same record read a different way — so nobody retypes a SKU into a proposal. */
function fmFromSelections(c, d){
  if (typeof selItems !== 'function'){ toast('The selections board is not available here'); return; }
  const already = new Set(d.lines.map(l => l.selId).filter(Boolean));
  const items = selItems(d.projectId).filter(i => !already.has(i.id));
  if (!items.length){ toast('Every selection on this job is already on the estimate'); return; }
  const byRoom = {};
  items.forEach(i => (byRoom[i.room || 'Unassigned'] = byRoom[i.room || 'Unassigned'] || []).push(i));
  mbModal('Add from selections', `
    <p class="small muted" style="margin:0 0 10px">These come across whole — image, SKU, finish, dimensions, vendor, cost and lead time — and stay joined to the board, so a price or a finish that changes there is not silently different here.</p>
    ${Object.entries(byRoom).map(([room, list]) => `<h4 style="margin:12px 0 6px">${esc(room)}</h4>
      <table class="t"><thead><tr><th style="width:26px"></th><th style="width:44px"></th><th>Item</th><th>Finish</th><th class="num">Qty</th><th class="money">Unit cost</th><th>Flags</th></tr></thead><tbody>
      ${list.map(i => `<tr><td><input type="checkbox" data-pick="${i.id}" ${selBlocked(i) ? '' : 'checked'}></td>
        <td>${i.img ? `<img class="fm-thumb" src="${esc(i.img)}" alt="">` : ''}</td>
        <td><b>${esc(i.name)}</b><div class="small muted">${[i.sku, i.vendor].filter(Boolean).map(esc).join(' · ')}</div></td>
        <td class="small">${esc(i.finish || '')}</td><td class="num">${selQty(i)} ${esc(i.unit)}</td><td class="money">${money(selCost(i))}</td>
        <td>${selBlocked(i) ? '<span class="pill bad">red flag</span>' : selOpenChecks(i).length ? `<span class="pill warn">${selOpenChecks(i).length}</span>` : '<span class="pill ok">·</span>'}</td></tr>`).join('')}
      </tbody></table>`).join('')}
    <p class="small muted" style="margin:10px 0 0">Anything with an unresolved red flag is unticked — the record and the vendor page disagree about what it is, and that is not a thing to put in front of a client.</p>`,
    {submit: 'Add them', onSubmit: () => {
      const ids = [...document.querySelectorAll('#mbm [data-pick]:checked')].map(x => x.dataset.pick);
      if (!ids.length) return false;
      let n = 0;
      for (const id of ids){
        const i = selItem(id); if (!i) continue;
        const markup = i.markupPct == null ? 10 : +i.markupPct;
        d.lines.push({
          id: uid('l'), selId: i.id, item: i.name, desc: i.desc || '',
          qty: selQty(i), unit: FM_UNITS.includes(i.unit) ? i.unit : 'ea',
          cost: selCost(i), markupPct: markup, rate: r2(selCost(i) * (1 + markup / 100)),
          taxable: i.taxable !== false, shipping: +i.shipping || 0, shipMarkupPct: +i.shipMarkupPct || 0,
          img: i.img || '', sku: i.sku || '', manufacturer: i.manufacturer || '', room: i.room || '',
          finish: i.finish || '', dims: i.dims || '', vendor: i.vendor || '', url: i.url || '',
          leadDays: +i.leadDays || '', needOnSite: (typeof selNeedOnSite === 'function' ? selNeedOnSite(i) : i.needOnSite) || '',
          tag: i.tag || '', cat: i.category || '', cost_: undefined,
        });
        n++;
      }
      log(`${n} selection${n === 1 ? '' : 's'} added to ${d.number || 'the estimate'}`);
      save(); render();
      toast(`${n} added — image, SKU, finish and lead came with them`);
    }});
  procWide(900);
}

/* ---------- wiring ---------- */
function fmWire(c, d, root, rerender){
  root.querySelectorAll('tr[data-fmline]').forEach(tr => {
    const l = d.lines.find(x => x.id === tr.dataset.fmline); if (!l) return;
    tr.querySelectorAll('[data-fmf]').forEach(inp => inp.addEventListener('change', e => {
      fmSetField(d, l, e.target.dataset.fmf, e.target.type === 'checkbox' ? e.target.checked : e.target.value);
      save(); rerender();
    }));
  });
  root.querySelectorAll('[data-fmsort]').forEach(h => h.onclick = () => {
    const k = h.dataset.fmsort;
    if (fmSort === k) fmDir *= -1; else { fmSort = k; fmDir = 1; }
    rerender();
  });
  root.querySelectorAll('[data-fmrz]').forEach(gr => gr.addEventListener('pointerdown', e => {
    e.preventDefault(); e.stopPropagation();
    const th = gr.closest('th'), k = gr.dataset.fmrz, x0 = e.clientX, w0 = th.getBoundingClientRect().width;
    gr.setPointerCapture(e.pointerId);
    const move = ev => { const w = Math.max(38, Math.min(460, w0 + ev.clientX - x0)); th.style.width = w + 'px'; };
    const up = ev => {
      gr.removeEventListener('pointermove', move); gr.removeEventListener('pointerup', up);
      fmSetWidth(d, k, w0 + ev.clientX - x0); save();
    };
    gr.addEventListener('pointermove', move); gr.addEventListener('pointerup', up);
  }));
  root.querySelector('#fm-preview')?.addEventListener('click', () => { fmPreview = !fmPreview; rerender(); });
  root.querySelector('#fm-unsort')?.addEventListener('click', () => { fmSort = ''; rerender(); });
  // Sorting is a view; this is the button that makes the view the document. Chen sorts by room to read
  // it, then wants the proposal to print that way — without it he would drag twenty lines by hand.
  root.querySelector('#fm-applysort')?.addEventListener('click', () => {
    const label = fmDef(fmSort)?.label || fmSort;
    dndApply(d, fmOrdered(d).map(l => l.id));
    fmSort = '';
    audit('doc-lines', d.id, 'reordered', null, {by: label});
    save(); rerender();
    toast(`Lines are now in ${label} order`);
  });
  if (!fmSort) dndRows(root.querySelector('table.lines.fm'), {
    rowSel: 'tr[data-fmline]',
    idOf: tr => tr.dataset.fmline,
    onOrder: order => { dndApply(d, order); save(); rerender(); },
  });
  root.querySelector('#fm-cols')?.addEventListener('click', () => fmColsModal(c, d));
  root.querySelector('#fm-from-sel')?.addEventListener('click', () => fmFromSelections(c, d));
  root.querySelectorAll('[data-fmimg]').forEach(el => el.onclick = () => fmImageModal(d, d.lines.find(x => x.id === el.dataset.fmimg)));
  root.querySelectorAll('[data-fmlink]').forEach(el => el.onclick = () => {
    const l = d.lines.find(x => x.id === el.dataset.fmlink); if (!l) return;
    mbModal('Website link', `<div class="f"><label>Where this was specified from</label><input data-f="url" value="${esc(l.url || '')}" placeholder="https://…"></div>
      <p class="small muted" style="margin:8px 0 0">Internal. It is what procurement checks the item against before buying it.</p>`,
      {submit: 'Save', onSubmit: f => { l.url = f.url; save(); rerender(); }});
  });
}

function fmImageModal(d, l){
  if (!l) return;
  const src = fmImgSrc(l);
  const sel = l.selId && typeof selItem === 'function' ? selItem(l.selId) : null;
  mbModal(`Picture — ${esc(l.item || 'item')}`, `
    <div class="fm-imgbox">${src ? `<img src="${esc(src)}" alt="">` : '<span class="muted small">No picture yet</span>'}</div>
    <div class="f"><label>From a link</label><input data-f="url" value="${(l.img || '').startsWith('blob:') ? '' : esc(l.img || '')}" placeholder="https://…/faucet.jpg"></div>
    <div class="f"><label>Or a file</label><input type="file" accept="image/*" id="fm-file"></div>
    ${sel && sel.img && sel.img !== l.img ? `<button class="btn sm" id="fm-fromsel" style="margin-top:6px">Use the picture from the selections board</button>` : ''}
    <p class="small muted" style="margin:10px 0 0">Pictures are resized to 640px before they are stored, so a proposal with forty of them still opens. The client sees them on the printed sheet when the Image column is client-visible.</p>`,
    {submit: 'Save', onSubmit: f => { if (f.url !== undefined && f.url !== '' ) { l.img = f.url; } save(); render(); }});
  const m = document.getElementById('mbm'); if (!m) return;
  m.querySelector('#fm-file')?.addEventListener('change', async e => {
    const file = e.target.files && e.target.files[0]; if (!file) return;
    await fmAttachImage(d, l, file);
    mbCloseModal(); render(); toast('Picture added');
  });
  m.querySelector('#fm-fromsel')?.addEventListener('click', () => { l.img = sel.img; save(); mbCloseModal(); render(); toast('Picture taken from the board'); });
}

/* ---------- hooks ----------
   The registry is loaded on boot so a document opened cold already knows its columns. The renderer and
   the wiring are patched in app.js itself rather than wrapped here: a materials estimate is a first-class
   template, not a decoration on the generic grid. */
if (typeof finishBoot === 'function'){
  const finishBootBase_fm = finishBoot;
  finishBoot = function(){ try { fmInit(); } catch (e){ console.warn('fm cols', e); } finishBootBase_fm(); };
}
/*<</fmcols.js>>*/



/*<<spend.js>>*/
/* ===================== WHERE THE MONEY STARTS =====================
   From the 9 Sep review with Jeanette. The whole hour is one problem seen from six angles: by the time
   a dollar reaches the ledger, everything anyone needed to know about it has been lost, and Jeanette
   spends her days reconstructing it.

     · the feed says "Apple" nine times and breaks nothing down, so she opens Chase in a second window
       and clicks "see order details" on each charge
     · Gabriel photographs receipts into her email, so she searches a folder by date or by amount
     · one Quality Building receipt is Douglas fir for the window frames AND masks for the crew, so she
       splits it by hand and types the real answer into a memo field where no report can reach it
     · the cost code is "just numbers" copied into that memo
     · nothing ties to a line on an estimate — Alan: "it needs to match it to an actual line item."
       Jeanette: "never has."
     · so a $2,200 washer and dryer gets billed at $1,648.98, and the only reason anyone knows is that
       Jeanette found it. Alan: "who says that there aren't more that aren't caught?"

   The answer is not better categorising. It is that categorising should not be happening at the bank at
   all. Every one of those facts existed at the moment of the purchase — the person standing at the
   counter knew the job, the line, and what it was for. This file makes that moment the record.

   A SPEND RECORD is created where money is committed: a purchase order, a receipt photographed at the
   counter, a crew member's hours, a bill against a PO. It carries, from birth:

       job · estimate line · cost code · cost class · who · evidence · authorisation

   The bank transaction then has one job, and it is not data entry: find the spend record it settles.
   Everything the transaction needs, it inherits. What cannot find a spend record is money that left
   with nobody's name on it, and that is a finding rather than a chore.

   Nothing here posts on its own. Machine proposes, person confirms — the rule the rest of the app
   already follows, and the reason the numbers can be believed.
*/

const SPEND_KINDS = {
  field:     'Bought in the field',
  po:        'Against a purchase order',
  bill:      'Vendor bill',
  reimburse: 'To reimburse',
};
const SPEND_STATES = [
  ['draft',    'Draft',     '',     'Being written. Nothing has been claimed yet.'],
  ['submitted','To approve','warn', 'Waiting on the project manager or the owner.'],
  ['approved', 'Approved',  'ok',   'Approved to pay and to bill. Waiting for the money to move.'],
  ['settled',  'Settled',   'ok',   'Matched to the transaction that paid it.'],
  ['rejected', 'Rejected',  'bad',  'Sent back with a reason.'],
];
const SPEND_STATE = Object.fromEntries(SPEND_STATES.map(([k, l, c, w]) => [k, {k, label: l, cls: c, why: w}]));

/* The crew works in Spanish. Alan, 00:24:36: "it needs to be able to understand Spanish." Labels are
   the cheap half of that; the hard half is that what a person says about a receipt has to survive into
   the record, so the note is kept verbatim in whatever language it was written and never translated
   away from the original. */
const SP_ES = {
  'Amount': 'Importe', 'Vendor': 'Proveedor', 'Job': 'Obra', 'What is it for': 'Para qué es',
  'Add a split': 'Agregar división', 'Receipt': 'Recibo', 'Submit': 'Enviar', 'Line': 'Partida',
  'Cost code': 'Código de costo', 'Reimburse me': 'Reembolsarme', 'Photo': 'Foto', 'Note': 'Nota',
};
let spLang = 'en';
const T = s => spLang === 'es' ? (SP_ES[s] || s) : s;

function spInit(){
  DB.spend = DB.spend || [];
  DB.spend.forEach(s => { s.lines = s.lines || []; });
}
const spAll = () => (DB.spend || []);
const spTotal = s => r2((s.lines || []).reduce((a, l) => a + (+l.amount || 0), 0));
const spFor = pid => spAll().filter(s => s.projectId === pid);
const spOpen = () => spAll().filter(s => ['submitted', 'approved'].includes(s.status));

/* ---------- born ---------- */
function spNew(o){
  spInit();
  const s = Object.assign({
    id: uid('sp'), at: nowStamp(), date: today(), by: currentUser()?.name || DB.me || '',
    kind: 'field', projectId: S.id, vendor: '', lines: [], note: '', lang: spLang,
    receipt: '', cardLast4: '', reimburse: false, status: 'draft', poId: '', txnId: '',
  }, o || {});
  DB.spend.push(s);
  audit('spend', s.id, 'created', null, {kind: s.kind, by: s.by});
  return s;
}
function spSubmit(s){
  if (!spTotal(s)){ toast('Put an amount on it first'); return false; }
  if (!s.lines.every(l => l.key || l.code)){ toast('Every part needs a line or a cost code'); return false; }
  s.status = 'submitted'; s.submittedAt = today();
  audit('spend', s.id, 'submitted', null, {total: spTotal(s)});
  log(`${s.by} submitted ${money(spTotal(s))} at ${s.vendor || 'a vendor'}${s.reimburse ? ' — to reimburse' : ''}`);
  save();
  return true;
}
function spApprove(s, ok, why){
  s.status = ok ? 'approved' : 'rejected';
  s.approvedBy = currentUser()?.name || DB.me || '';
  s.approvedAt = today();
  s.rejectNote = ok ? '' : (why || '');
  audit('spend', s.id, ok ? 'approved' : 'rejected', null, {by: s.approvedBy, why: why || ''});
  log(`${money(spTotal(s))} at ${s.vendor || 'a vendor'} ${ok ? 'approved' : 'sent back'} by ${s.approvedBy}${why ? ' — ' + why : ''}`);
  save();
}

/* ---------- the class of a cost, decided once, at the source ----------
   The same four words the firm already uses, and the same rule the cost report uses: a material bought
   through the selections board is finish, one bought at a counter is rough. Here the person knows which
   they are holding, so they are asked once rather than guessed at later. */
const SP_CLASSES = [
  ['rough',  'Rough materials', 'Lumber, board, wire, pipe, fasteners, safety.'],
  ['finish', 'Finish materials','Anything specified on the selections board.'],
  ['labor',  'Labour',          'Our own crew.'],
  ['subs',   'Subcontractor',   'A trade billing us.'],
  ['other',  'Other',           'Equipment, disposal, permits, fees.'],
];
const spClassOf = l => l.cls || 'rough';

/* ---------- what a line on a spend record points at ---------- */
function spLineOptions(pid){
  const out = (typeof lineOptions === 'function' ? lineOptions(pid || S.id) : []);
  return out.map(o => ({key: o.key, label: o.label, code: (o.line.code || (typeof codeForLine === 'function' ? codeForLine(o.line) : '99'))}));
}

/* ===================== THE BANK'S ONE JOB =====================
   Not "what is this?" but "which spend record does this settle?". A transaction that finds one inherits
   the job, the line, the cost code, the class, the receipt and the person — none of which it could have
   worked out on its own, and all of which somebody already knew at the counter. */
const SP_WINDOW = 12;                      // days between the purchase and the statement
function spScore(s, t){
  if (s.txnId || !['approved', 'submitted'].includes(s.status)) return null;
  const amt = Math.abs(+t.amt || 0), tot = spTotal(s);
  if (!tot || !amt) return null;
  const reasons = [];
  let score = 0;
  if (Math.abs(amt - tot) < 0.01){ score += 55; reasons.push({code: 'amount-exact'}); }
  else if (tot && Math.abs(amt - tot) / tot <= 0.02){ score += 34; reasons.push({code: 'amount-near'}); }
  else return null;                        // a spend record is a known amount; near is as loose as it gets
  const v = String(s.vendor || '').toLowerCase(), d = String(t.desc || '').toLowerCase();
  const tv = String(t.vendor || '').toLowerCase();
  if (v && tv && v === tv){ score += 35; reasons.push({code: 'vendor-tagged'}); }
  else if (v && v.split(/\s+/).some(w => w.length >= 4 && d.includes(w))){ score += 28; reasons.push({code: 'vendor-token'}); }
  const gap = Math.round((Date.parse(t.date) - Date.parse(s.date)) / 86400000);
  if (gap < -1) return null;               // the card cannot be charged before the thing was bought
  if (gap <= SP_WINDOW){ score += 12; reasons.push({code: 'in-window', gap}); }
  else { score -= 10; reasons.push({code: 'late', gap}); }
  if (s.cardLast4 && String(t.acct || '').includes(s.cardLast4)){ score += 10; reasons.push({code: 'same-card'}); }
  return {score, reasons};
}
const SP_MIN = 70;

// One transaction settles one spend record and one spend record is settled once.
function spProposals(){
  spInit();
  const money = DB.txns.filter(t => (+t.amt || 0) < 0 && !t.spendId && !t.billId);
  const pairs = [];
  for (const s of spAll())
    for (const t of money){
      const r = spScore(s, t);
      if (r && r.score >= SP_MIN) pairs.push({spendId: s.id, txnId: t.id, s, t, ...r});
    }
  pairs.sort((a, b) => b.score - a.score);
  const us = new Set(), ut = new Set(), out = [];
  for (const p of pairs){
    if (us.has(p.spendId) || ut.has(p.txnId)) continue;
    us.add(p.spendId); ut.add(p.txnId); out.push(p);
  }
  return out;
}

/* Confirming is where the ledger gets its facts — all of them at once, none of them typed. */
function spSettle(s, t){
  t.spendId = s.id;
  t.projectId = s.projectId;
  t.vendor = t.vendor || s.vendor;
  t.actor = s.by;
  const first = (s.lines || [])[0] || {};
  t.line = first.key || t.line || '';
  t.code = first.code || t.code || '';
  t.cat = spClassOf(first) === 'labor' ? 'labor' : spClassOf(first) === 'subs' ? 'subs'
        : spClassOf(first) === 'other' ? 'equipment' : 'materials';
  t.spendClass = spClassOf(first);
  t.receipt = s.receipt || t.receipt || '';
  t.status = 'categorized';
  t.memo = [t.memo, s.note].filter(Boolean).join(' · ');
  if ((s.lines || []).length > 1){
    // A receipt covering framing and masks is two costs. Splitting it here is what stops the answer
    // from ending up in a memo field where no report can reach it.
    t.split = s.lines.map(l => ({amount: -Math.abs(+l.amount || 0), line: l.key || '', code: l.code || '',
                                 cls: l.cls || 'rough', note: l.note || ''}));
  }
  s.status = 'settled'; s.txnId = t.id; s.settledAt = today();
  audit('spend', s.id, 'settled', null, {txn: t.id, amount: spTotal(s)});
  save();
}

/* ===================== WHAT IT COST vs WHAT WE BILLED =====================
   Jeanette's list for Patricia, found by reading. The washer and dryer billed at $1,648.98 that cost
   $2,200; the hamper pull-out nobody billed; the second trash pull-out; the hood; the free valve. Every
   one of them is the same shape — cost landed on a line, and the client was never asked for it — and
   every one of them is computable the moment cost and billing share a line key.

   This does not decide anything. It hands a person the list Jeanette builds by hand. */
function spUnbilled(pid){
  const out = [];
  const jobs = pid ? [DB.projects.find(p => p.id === pid)].filter(Boolean) : DB.projects;
  for (const p of jobs){
    for (const o of (typeof lineOptions === 'function' ? lineOptions(p.id) : [])){
      const f = lineFin(o.key); if (!f) continue;
      const cost = f.actual, billed = f.billed, price = f.price;
      // Room left on the line: what the client agreed to, less what has been billed against it.
      const room = r2(price - billed);
      if (cost > billed + 0.5){
        out.push({kind: cost > price + 0.5 ? 'over-contract' : 'unbilled',
                  project: p, key: o.key, doc: o.doc, line: o.line, label: o.label,
                  cost, billed, price, gap: r2(cost - billed), room});
      }
    }
  }
  // Money that landed on no line at all — it cannot be billed because nobody knows what it belongs to.
  DB.txns.filter(t => (+t.amt || 0) < 0 && t.projectId && !t.line && !['transfer', 'cc-payment', 'owner', 'loan'].includes(t.cat))
    .forEach(t => {
      const p = DB.projects.find(x => x.id === t.projectId); if (!p) return;
      if (pid && p.id !== pid) return;
      out.push({kind: 'no-line', project: p, txn: t, cost: r2(-t.amt), billed: 0, price: 0, gap: r2(-t.amt),
                label: t.desc || t.vendor || 'Uncategorised job cost'});
    });
  return out.sort((a, b) => b.gap - a.gap);
}

/* Money out with nobody's name on it. Not everything qualifies: the insurance premium and the office
   rent are real costs that no field receipt will ever explain, and flagging them would bury the ones
   that matter. What counts is money that looks like JOB cost — a trade category, or a job attached, or
   nothing decided at all — with no purchase order, no bill and no captured receipt behind it. The $316
   Amazon charge in the meeting is exactly this shape. */
const SP_JOB_CATS = ['materials', 'subs', 'labor', 'equipment', 'disposal', 'permits', 'design'];
function spOrphans(){
  const claimed = new Set(spProposals().map(p => p.txnId));
  return DB.txns.filter(t => {
    if ((+t.amt || 0) >= 0 || t.spendId || t.billId || t.poId) return false;
    if (claimed.has(t.id)) return false;
    if (t.cat === 'uncat') return true;                    // nobody has said what it is
    if (!SP_JOB_CATS.includes(t.cat)) return false;        // overhead is not a field receipt
    return !t.line;                                        // job cost that reaches no line
  }).sort((a, b) => String(b.date).localeCompare(String(a.date)));
}

/* ===================== CAPTURE, AT THE COUNTER =====================
   The whole design rests on this screen being faster than photographing a receipt into somebody's
   email. Amount, who, what job, what it is for — and the split, because the receipt in the meeting was
   framing timber and safety masks on one piece of paper. */
function spCaptureModal(o){
  spInit();
  const s = o && o.spend ? o.spend : spNew(o || {});
  const draw = () => {
    const opts = spLineOptions(s.projectId);
    const jobs = DB.projects.map(p => `<option value="${p.id}" ${s.projectId === p.id ? 'selected' : ''}>${esc(p.project.name)}</option>`).join('');
    const lineRow = (l, i) => `<tr data-spl="${l.id}">
      <td><input class="num" type="number" step="0.01" data-slf="amount" value="${l.amount ?? ''}" placeholder="0.00"></td>
      <td><select data-slf="key"><option value="">— ${esc(T('Line'))} —</option>${opts.map(x => `<option value="${esc(x.key)}" ${l.key === x.key ? 'selected' : ''}>${esc(x.label)}</option>`).join('')}</select></td>
      <td><select data-slf="cls">${SP_CLASSES.map(([k, lab]) => `<option value="${k}" ${spClassOf(l) === k ? 'selected' : ''}>${lab}</option>`).join('')}</select></td>
      <td><select data-slf="code"><option value="">—</option>${COST_CODES.map(c => `<option value="${c[0]}" ${l.code === c[0] ? 'selected' : ''}>${c[0]} ${esc(c[1])}</option>`).join('')}</select></td>
      <td><input data-slf="note" value="${esc(l.note || '')}" placeholder="${esc(T('Note'))}"></td>
      <td>${(s.lines.length > 1 && s.status === 'draft') ? `<span class="rm" data-slrm="${l.id}">✕</span>` : ''}</td></tr>`;

    mbModal(`${esc(T('What is it for'))}${s.vendor ? ' — ' + esc(s.vendor) : ''}`, `
      <div class="row" style="gap:6px;margin:0 0 10px"><span class="small muted">${esc(T('Photo'))} · ${esc(T('Receipt'))}</span><span class="grow"></span>
        <div class="seg sm"><button class="${spLang === 'en' ? 'on' : ''}" data-splang="en">EN</button><button class="${spLang === 'es' ? 'on' : ''}" data-splang="es">ES</button></div></div>
      <div class="grid3">
        <div class="f"><label>${esc(T('Vendor'))}</label><input data-sf="vendor" value="${esc(s.vendor)}" list="sp-vendors" placeholder="Home Depot"></div>
        <div class="f"><label>${esc(T('Job'))}</label><select data-sf="projectId">${jobs}</select></div>
        <div class="f"><label>Date</label><input type="date" data-sf="date" value="${s.date}"></div>
      </div>
      <datalist id="sp-vendors">${[...new Set(DB.vendors.map(v => v.name).filter(Boolean))].sort().map(v => `<option value="${esc(v)}">`).join('')}</datalist>

      <div class="sp-shot">${s.receipt ? `<img src="${esc(spImg(s))}" alt="">` : `<span class="muted small">${esc(T('Receipt'))} — photograph it here and it never has to live in anyone's email</span>`}
        <input type="file" accept="image/*" capture="environment" id="sp-file"></div>

      <table class="t sp-lines"><thead><tr><th style="width:92px">${esc(T('Amount'))}</th><th>${esc(T('Line'))}</th><th style="width:130px">Class</th><th style="width:150px">${esc(T('Cost code'))}</th><th>${esc(T('Note'))}</th><th></th></tr></thead>
      <tbody>${s.lines.map(lineRow).join('') || ''}</tbody></table>
      <div class="row" style="gap:8px;margin-top:6px"><button class="btn sm" id="sp-add">+ ${esc(T('Add a split'))}</button>
        <span class="small muted">One receipt, more than one thing on it — split it here and each part reaches its own line.</span>
        <span class="grow"></span><b>${money(spTotal(s))}</b></div>

      <div class="f" style="margin-top:10px"><label>${esc(T('Note'))}</label><input data-sf="note" value="${esc(s.note || '')}" placeholder="${spLang === 'es' ? 'Marcos de las ventanas del frente' : 'Framing for the front windows'}"></div>
      <label class="cl-chk" style="margin-top:8px"><input type="checkbox" data-sf="reimburse" ${s.reimburse ? 'checked' : ''}><span>${esc(T('Reimburse me'))} — pay it back on the next payroll rather than matching a card</span></label>
      <p class="small muted" style="margin:10px 0 0">Nothing here is a category to be worked out later. It is what you know standing at the counter, and it is what the transaction will inherit when it clears.</p>`,
      {submit: s.status === 'draft' ? esc(T('Submit')) : 'Save', onSubmit: () => {
        if (s.status === 'draft'){ if (!spSubmit(s)) return false; }
        else save();
        render();
        toast(s.status === 'submitted' ? `${money(spTotal(s))} sent for approval` : 'Saved');
      }});
    procWide(980);

    const m = document.getElementById('mbm'); if (!m) return;
    const redraw = () => { mbCloseModal(); draw(); };
    m.querySelectorAll('[data-splang]').forEach(b => b.onclick = () => { spLang = b.dataset.splang; redraw(); });
    m.querySelectorAll('[data-sf]').forEach(inp => inp.addEventListener('change', () => {
      const f = inp.dataset.sf;
      s[f] = inp.type === 'checkbox' ? inp.checked : inp.value;
      if (f === 'projectId') redraw(); else save();
    }));
    m.querySelectorAll('tr[data-spl]').forEach(tr => {
      const l = s.lines.find(x => x.id === tr.dataset.spl); if (!l) return;
      tr.querySelectorAll('[data-slf]').forEach(inp => inp.addEventListener('change', () => {
        const f = inp.dataset.slf;
        l[f] = f === 'amount' ? (+inp.value || 0) : inp.value;
        // choosing the line fills the cost code from it, because the line already knows
        if (f === 'key' && l.key){ const o = spLineOptions(s.projectId).find(x => x.key === l.key); if (o && !l.code) l.code = o.code; }
        save(); redraw();
      }));
    });
    m.querySelectorAll('[data-slrm]').forEach(x => x.onclick = () => { s.lines = s.lines.filter(l => l.id !== x.dataset.slrm); save(); redraw(); });
    m.querySelector('#sp-add').onclick = () => { s.lines.push({id: uid('sl'), amount: '', key: '', code: '', cls: 'rough', note: ''}); save(); redraw(); };
    m.querySelector('#sp-file')?.addEventListener('change', async e => {
      const file = e.target.files && e.target.files[0]; if (!file) return;
      await spAttach(s, file); redraw(); toast('Receipt on the record');
    });
  };
  if (!s.lines.length) s.lines.push({id: uid('sl'), amount: '', key: '', code: '', cls: 'rough', note: ''});
  draw();
  return s;
}

const spImg = s => { const v = s.receipt || ''; return v.startsWith('blob:') ? (blobCache[v.slice(5)] || '') : v; };
async function spAttach(s, file){
  const dataUrl = await new Promise((res, rej) => { const fr = new FileReader(); fr.onload = () => res(fr.result); fr.onerror = rej; fr.readAsDataURL(file); });
  const small = typeof fmShrink === 'function' ? await fmShrink(dataUrl, 1100) : dataUrl;
  const id = uid('rc'); await putBlob(id, small);
  s.receipt = 'blob:' + id;
  audit('spend', s.id, 'receipt-attached', null, {});
  save();
}

/* ===================== THE SCREEN JEANETTE OPENS =====================
   Three questions, in the order the money moves: what needs approving, what has cleared the bank that
   we can now settle, and what has cost us money nobody has billed for. */
let spTab = 'approve', spProj = 'all';
const SP_TABS = [['approve', 'To approve'], ['match', 'Money to settle'], ['unbilled', 'Cost not billed'], ['all', 'Everything']];

function renderSpend(){
  const root = $('#spend-body') || $('#vf-body'); if (!root) return;
  spInit();
  const pid = spProj === 'all' ? null : spProj;
  const queue = spAll().filter(s => s.status === 'submitted' && (!pid || s.projectId === pid));
  const props = spProposals().filter(p => !pid || p.s.projectId === pid);
  const orph = spOrphans();
  const un = spUnbilled(pid);
  const unTotal = r2(un.reduce((a, r) => a + r.gap, 0));

  const stat = (v, l, cls) => `<div class="sel-stat ${cls || ''}"><b>${v}</b><span>${l}</span></div>`;
  root.innerHTML = `
  <div class="ph"><div><h2>Spend</h2>
    <p class="lead">Every dollar starts where it is spent, not at the bank. A receipt captured at the counter already knows the job, the line and what it is for — so the transaction that clears a week later has one job, which is to find the record it settles.</p></div>
    <div class="acts"><button class="btn primary" id="sp-new">Capture a receipt</button></div></div>

  <div class="sel-stats">
    ${stat(queue.length, 'waiting on approval', queue.length ? 'warn' : '')}
    ${stat(props.length, 'transactions that match a record', '')}
    ${stat(orph.length, 'left the bank with no record behind it', orph.length ? 'bad' : '')}
    ${stat(money(unTotal), 'cost the client has not been billed for', unTotal ? 'bad' : '')}
    ${stat(money(r2(spAll().filter(s => s.reimburse && s.status === 'approved').reduce((a, s) => a + spTotal(s), 0))), 'to reimburse on the next payroll', '')}
  </div>

  <div class="proc-bar an-lens">
    <div class="ctabs" style="margin:0">${SP_TABS.map(([k, l]) => `<button class="${spTab === k ? 'on' : ''}" data-sptab="${k}">${l}${k === 'approve' && queue.length ? `<span class="n">${queue.length}</span>` : ''}${k === 'unbilled' && un.length ? `<span class="n">${un.length}</span>` : ''}</button>`).join('')}</div>
    <span class="grow"></span>
    <select id="sp-proj"><option value="all">Every project</option>${DB.projects.map(p => `<option value="${p.id}" ${spProj === p.id ? 'selected' : ''}>${esc(p.project.name)}</option>`).join('')}</select>
  </div>
  <div id="sp-pane">${spPane({queue, props, orph, un, pid})}</div>`;
  wireSpend(root);
}

function spPane({queue, props, orph, un}){
  if (spTab === 'approve') return spQueueHtml(queue);
  if (spTab === 'match') return spMatchHtml(props, orph);
  if (spTab === 'unbilled') return spUnbilledHtml(un);
  return spAllHtml();
}

const spLineLabel = l => {
  if (!l.key) return l.code ? `${l.code} ${(COST_CODES.find(c => c[0] === l.code) || [, ''])[1]}` : '<span class="muted">no line</span>';
  const ref = typeof findLine === 'function' ? findLine(l.key) : null;
  return ref ? `${esc(ref.doc.number)} · ${esc(ref.line.item || ref.line.desc || '')}` : '<span class="muted">line not found</span>';
};

function spQueueHtml(rows){
  if (!rows.length) return '<div class="empty">Nothing waiting. Anything captured in the field lands here for a yes or a no.</div>';
  return `<div class="proc-wrap"><table class="t an"><thead><tr><th>Captured</th><th>Who</th><th>Vendor</th><th>Job</th><th>What it is for</th><th class="money">Amount</th><th>Receipt</th><th></th></tr></thead>
  <tbody>${rows.map(s => `<tr data-spopen="${s.id}">
    <td class="num">${fmt(s.date)}</td><td>${esc(s.by)}</td><td>${esc(s.vendor || '')}</td>
    <td class="sub">${esc(DB.projects.find(p => p.id === s.projectId)?.project?.name || '')}</td>
    <td>${s.lines.map(l => `<div class="small">${money(l.amount)} · ${spLineLabel(l)}${l.note ? ` <span class="muted">${esc(l.note)}</span>` : ''}</div>`).join('')}${s.reimburse ? '<span class="pill warn">reimburse</span>' : ''}</td>
    <td class="money">${money(spTotal(s))}</td>
    <td>${s.receipt ? `<img class="fm-thumb" src="${esc(spImg(s))}" alt="">` : '<span class="muted small">none</span>'}</td>
    <td style="white-space:nowrap"><button class="btn sm primary" data-spok="${s.id}">Approve</button><button class="btn sm ghost" data-spno="${s.id}">Send back</button></td></tr>`).join('')}
  </tbody></table></div>
  <p class="small muted" style="margin:8px 0 0">Approving is what makes it payable and billable. Everything on the row was entered by the person who spent the money, at the moment they spent it.</p>`;
}

function spMatchHtml(props, orph){
  return `${props.length ? `<h4 style="margin:0 0 6px">${props.length} transaction${props.length === 1 ? '' : 's'} match a record</h4>
  <div class="proc-wrap"><table class="t an"><thead><tr><th>Cleared</th><th>On the statement</th><th class="money">Amount</th><th>Settles</th><th>Job · line</th><th>Why</th><th></th></tr></thead>
  <tbody>${props.map(p => `<tr><td class="num">${fmt(p.t.date)}</td><td class="sub">${esc(String(p.t.desc || '').slice(0, 40))}</td>
    <td class="money">${money(Math.abs(p.t.amt))}</td>
    <td>${esc(p.s.vendor || '')} <span class="muted small">${esc(p.s.by)} · ${fmt(p.s.date)}</span></td>
    <td class="small">${p.s.lines.map(l => spLineLabel(l)).join('<br>')}</td>
    <td class="small muted">${p.reasons.map(r => r.code).join(' · ')}</td>
    <td><button class="btn sm primary" data-spset="${p.s.id}:${p.t.id}">Settle</button></td></tr>`).join('')}
  </tbody></table></div>` : '<div class="empty">Nothing to settle. Every record that has cleared is matched.</div>'}
  ${orph.length ? `<h4 style="margin:16px 0 6px">${orph.length} left the bank with no record behind it</h4>
  <p class="small muted" style="margin:0 0 6px">Money out that no purchase order, bill or captured receipt explains. This is the list that used to be worked out by opening the bank in a second window.</p>
  <div class="proc-wrap"><table class="t an"><thead><tr><th>Cleared</th><th>On the statement</th><th class="money">Amount</th><th>Job</th><th></th></tr></thead>
  <tbody>${orph.slice(0, 40).map(t => `<tr><td class="num">${fmt(t.date)}</td><td>${esc(String(t.desc || '').slice(0, 52))}</td>
    <td class="money">${money(Math.abs(t.amt))}</td><td class="sub">${esc(DB.projects.find(p => p.id === t.projectId)?.project?.name || '<span class="muted">—</span>')}</td>
    <td><button class="btn sm" data-spclaim="${t.id}">Write the record</button></td></tr>`).join('')}
  </tbody></table></div>` : ''}`;
}

function spUnbilledHtml(rows){
  if (!rows.length) return '<div class="empty">Every cost on every line has been billed. That is rarer than it sounds.</div>';
  const K = {unbilled: ['warn', 'Cost above what has been billed'], 'over-contract': ['bad', 'Cost above the contract value of the line'], 'no-line': ['bad', 'Job cost on no line at all']};
  return `<p class="small muted" style="margin:0 0 8px">The list Jeanette builds by reading. A cost has landed on a line and the client has not been asked for it — the $2,200 washer and dryer billed at $1,648.98, the hamper pull-out nobody billed, the second trash pull-out. Sorted by what is at stake.</p>
  <div class="proc-wrap"><table class="t an"><thead><tr><th>Job</th><th>Line</th><th></th><th class="money">Cost</th><th class="money">Billed</th><th class="money">Not billed</th><th class="money">Contract</th></tr></thead>
  <tbody>${rows.slice(0, 60).map(r => `<tr>
    <td class="sub">${esc(r.project.project.name)}</td>
    <td><b>${esc(r.line ? (r.line.item || r.line.desc || r.label) : r.label)}</b>${r.doc ? `<div class="sub">${esc(r.doc.number)}</div>` : ''}</td>
    <td><span class="pill ${K[r.kind][0]}" title="${esc(K[r.kind][1])}">${r.kind === 'no-line' ? 'no line' : r.kind === 'over-contract' ? 'over contract' : 'not billed'}</span></td>
    <td class="money">${money(r.cost)}</td><td class="money">${money(r.billed)}</td>
    <td class="money an-over">${money(r.gap)}</td>
    <td class="money">${r.price ? money(r.price) : '<span class="muted">—</span>'}</td></tr>`).join('')}
  </tbody></table></div>
  <p class="small muted" style="margin:8px 0 0">"Over contract" is the one to look at first: the line cost more than the client ever agreed to pay for it, so billing it needs a change order rather than a progress invoice.</p>`;
}

function spAllHtml(){
  const rows = spAll().filter(s => spProj === 'all' || s.projectId === spProj).slice().reverse();
  if (!rows.length) return '<div class="empty">No spend records yet.</div>';
  return `<div class="proc-wrap"><table class="t an"><thead><tr><th>Date</th><th>Who</th><th>Vendor</th><th>Job</th><th class="money">Amount</th><th>State</th><th>Settled by</th></tr></thead>
  <tbody>${rows.map(s => { const st = SPEND_STATE[s.status] || {};
    const t = s.txnId && DB.txns.find(x => x.id === s.txnId);
    return `<tr data-spopen="${s.id}"><td class="num">${fmt(s.date)}</td><td>${esc(s.by)}</td><td>${esc(s.vendor || '')}</td>
      <td class="sub">${esc(DB.projects.find(p => p.id === s.projectId)?.project?.name || '')}</td>
      <td class="money">${money(spTotal(s))}</td>
      <td><span class="pill ${st.cls || ''}" title="${esc(st.why || '')}">${esc(st.label || s.status)}</span></td>
      <td class="sub">${t ? esc(String(t.desc || '').slice(0, 30)) : ''}</td></tr>`; }).join('')}
  </tbody></table></div>`;
}

function wireSpend(root){
  const go = () => renderSpend();
  root.querySelectorAll('[data-sptab]').forEach(b => b.onclick = () => { spTab = b.dataset.sptab; go(); });
  root.querySelector('#sp-proj').onchange = e => { spProj = e.target.value; go(); };
  root.querySelector('#sp-new').onclick = () => spCaptureModal({projectId: spProj === 'all' ? S.id : spProj});
  root.querySelectorAll('[data-spok]').forEach(b => b.onclick = e => { e.stopPropagation();
    spApprove(spAll().find(s => s.id === b.dataset.spok), true); go(); toast('Approved'); });
  root.querySelectorAll('[data-spno]').forEach(b => b.onclick = e => { e.stopPropagation();
    const s = spAll().find(x => x.id === b.dataset.spno);
    mbModal('Send it back', `<div class="f"><label>What is wrong with it</label><input data-f="why" placeholder="Which job is this for?"></div>`,
      {submit: 'Send back', onSubmit: f => { spApprove(s, false, f.why); go(); }}); });
  root.querySelectorAll('[data-spset]').forEach(b => b.onclick = () => {
    const [sid, tid] = b.dataset.spset.split(':');
    const s = spAll().find(x => x.id === sid), t = DB.txns.find(x => x.id === tid);
    if (s && t){ spSettle(s, t); go(); toast(`${money(spTotal(s))} settled — the line, the code and the receipt went with it`); }
  });
  root.querySelectorAll('[data-spclaim]').forEach(b => b.onclick = () => {
    const t = DB.txns.find(x => x.id === b.dataset.spclaim); if (!t) return;
    // Writing the record after the fact: the same form, opened with what the statement already knows.
    const s = spCaptureModal({projectId: t.projectId || S.id, vendor: t.vendor || String(t.desc || '').slice(0, 28), date: t.date, kind: 'field'});
    s.lines[0].amount = r2(Math.abs(t.amt));
    s._claim = t.id;
  });
  root.querySelectorAll('[data-spopen]').forEach(tr => tr.onclick = () => {
    const s = spAll().find(x => x.id === tr.dataset.spopen); if (s) spCaptureModal({spend: s});
  });
}

/* ---------- where it lives ----------
   Its own screen under Money, because it is where the money is decided rather than where it is
   reconciled — and reachable from the field app, which is the point of it. */
(() => {
  const host = document.querySelector('.main') || document.body;
  if (!document.getElementById('v-spend')){
    const sec = document.createElement('section');
    sec.className = 'view'; sec.id = 'v-spend';
    sec.innerHTML = '<div id="spend-body"></div>';
    (document.querySelector('#v-bank')?.parentElement || host).appendChild(sec);
  }
  if (typeof ROLE_VIEWS === 'object') Object.keys(ROLE_VIEWS).forEach(r => {
    if (['owner', 'pm', 'admin', 'bookkeeper', 'ceo', 'cfo'].some(x => r.toLowerCase().includes(x)) || ROLE_VIEWS[r].includes('bank'))
      if (!ROLE_VIEWS[r].includes('spend')) ROLE_VIEWS[r].push('spend');
  });
  if (typeof NAV_GROUPS !== 'undefined'){
    const g = NAV_GROUPS.find(x => x.id === 'money');
    if (g && !g.views.includes('spend')) g.views.unshift('spend');
    if (typeof NAV_LABELS === 'object') NAV_LABELS.spend = 'Spend';
  }
})();

if (typeof render === 'function'){
  const renderBase_sp = render;
  render = function(){ renderBase_sp(); if (view === 'spend') renderSpend(); };
}
if (typeof finishBoot === 'function'){
  const finishBootBase_sp = finishBoot;
  finishBoot = function(){ try { spInit(); spSeed(); } catch (e){ console.warn('spend init', e); } finishBootBase_sp(); };
}

/* A day of Gabriel's receipts, so the screen has something true to show: the Quality Building slip that
   is timber for the window frames and masks for the crew on one piece of paper, and an Amazon charge
   nobody can explain. */
/* A drawn stand-in for the photograph Gabriel would take, so the record is complete end to end without
   fetching anything. The real one is a camera capture on a phone. */
function spPaperReceipt(vendor, lines, total){
  const rows = lines.map((l, i) => `<text x="14" y="${86 + i * 18}" font-size="10" fill="#333">${l[0]}</text><text x="196" y="${86 + i * 18}" font-size="10" text-anchor="end" fill="#333">${l[1]}</text>`).join('');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="220" height="${120 + lines.length * 18}" viewBox="0 0 220 ${120 + lines.length * 18}">
    <rect width="220" height="${120 + lines.length * 18}" fill="#fffdf8" stroke="#e6e0d4"/>
    <text x="110" y="26" font-size="12" text-anchor="middle" font-weight="600" fill="#222">${vendor}</text>
    <text x="110" y="42" font-size="9" text-anchor="middle" fill="#888">BROOKLYN NY · SALE</text>
    <line x1="12" y1="56" x2="208" y2="56" stroke="#ddd"/>${rows}
    <line x1="12" y1="${74 + lines.length * 18}" x2="208" y2="${74 + lines.length * 18}" stroke="#ddd"/>
    <text x="14" y="${92 + lines.length * 18}" font-size="11" font-weight="600" fill="#222">TOTAL</text>
    <text x="196" y="${92 + lines.length * 18}" font-size="11" text-anchor="end" font-weight="600" fill="#222">${total}</text></svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

function spSeed(){
  if (DB.__spSeed || !DB.projects.length) return;
  DB.__spSeed = 1;
  const p = DB.projects.find(x => x.id === 'p121') || DB.projects[0];
  const opts = spLineOptions(p.id);
  const find = re => (opts.find(o => re.test(o.label)) || {});
  const win = find(/window/i), gen = find(/general|condition|supervis/i), tile = find(/tile/i);
  const S1 = spNew({projectId: p.id, vendor: 'Quality Building Supply', by: 'Gabriel', date: iso(addDays(today(), -4)),
    note: 'Marcos de las ventanas del frente · masks for the crew', lang: 'es', kind: 'field', cardLast4: '3949'});
  S1.lines = [
    {id: uid('sl'), amount: 238.44, key: win.key || '', code: win.code || '04', cls: 'rough', note: 'Douglas fir — front window frames'},
    {id: uid('sl'), amount: 61.20, key: gen.key || '', code: gen.code || '01', cls: 'rough', note: 'N95 masks — worker protection'},
  ];
  S1.receipt = spPaperReceipt('QUALITY BUILDING SUPPLY',
    [['DOUGLAS FIR 2X6 KD', '238.44'], ['N95 RESPIRATOR 10PK', '61.20']], '299.64');
  S1.status = 'submitted'; S1.submittedAt = S1.date;
  const S2 = spNew({projectId: p.id, vendor: 'Dakota Hardware', by: 'Gabriel', date: iso(addDays(today(), -2)),
    note: 'Blades and fixings', kind: 'field', reimburse: true});
  S2.lines = [{id: uid('sl'), amount: 96.74, key: gen.key || '', code: gen.code || '01', cls: 'rough', note: ''}];
  S2.receipt = spPaperReceipt('DAKOTA HARDWARE', [['BLADES / FIXINGS', '96.74']], '96.74');
  S2.status = 'submitted'; S2.submittedAt = S2.date;
  const S3 = spNew({projectId: p.id, vendor: 'Nemo Tile', by: 'Chen', date: iso(addDays(today(), -6)), kind: 'field', cardLast4: '3949'});
  S3.lines = [{id: uid('sl'), amount: 4250, key: tile.key || '', code: tile.code || '08', cls: 'rough', note: 'Bathroom floor tile'}];
  S3.receipt = spPaperReceipt('NEMO TILE SUPPLY', [['PORCELAIN 12X24 · 340SF', '4,250.00']], '4,250.00');
  S3.status = 'approved'; S3.approvedBy = 'Alan'; S3.approvedAt = S3.date;
  // the card charge that settles Gabriel's Quality Building receipt, a week behind the purchase
  const C = DB.accounts.find(a => a.type === 'card');
  if (C && !DB.txns.some(t => t.id === 'tsp0'))
    DB.txns.push({id: 'tsp0', date: iso(addDays(today(), -1)), acct: C.id, desc: 'QUALITY BLDG SUPPLY 118',
      amt: -r2(spTotal(S1)), cat: 'uncat', projectId: '', code: '', vendor: '', memo: '', receipt: '', status: 'new'});
  // and the charge with nobody's name on it
  const A = DB.accounts.find(a => a.type === 'card') || DB.accounts[0];
  if (A && !DB.txns.some(t => t.id === 'tsp1'))
    DB.txns.push({id: 'tsp1', date: iso(addDays(today(), -3)), acct: A.id, desc: 'AMAZON MKTPLACE US*R41K2',
      amt: -316.18, cat: 'uncat', projectId: '', code: '', vendor: '', memo: '', receipt: '', status: 'new'});
  save();
}
/*<</spend.js>>*/

/*<<labor.js>>*/
/* ===================== HOURS THAT REACH A LINE =====================
   The second half of the 9 Sep review, and the half that eats Jeanette's week.

   Today a crew member's day is typed three times. Once by them; once by Jeanette into QuickBooks Time
   against a project and a class; and a third time into a bill she makes by COPYING last week's and
   editing every field — "I'll put in patch and repair, but it's not materials, it's labor... and then
   I'll put in 121 State Street... eight hours... 25 × 8 is 200... and then Patricia's name again so we
   know it's accurate... and then the class will be construction" (00:38:54). Per person. Per task.

   Alan: "we want it to go into the line item that they're working on. It's got to match the line item.
   That's the most important thing." (00:34:40)

   The crew already logs job + cost code per split. What was missing is the line, so labour never landed
   anywhere a margin could see it. This adds it — and where the person is working on a scheduled task
   that already belongs to a line, it is filled in rather than asked for.

   And the mismatch Alan caught at 00:33:34 — QuickBooks Time saying "painting prep" when the system
   only has "painting" — cannot happen when the thing they pick IS the line.
*/

/* ---------- resolving the line for an hour ----------
   Three ways, in descending order of confidence: the person said so; the task they are on belongs to
   one; or exactly one line on the job carries that cost code. The third is a suggestion, never a
   silent assignment — a guess that writes itself into the ledger is how the ledger stops being true. */
function labLineFor(w, projectId){
  if (w && w.line) return {key: w.line, how: 'stated'};
  if (w && w.taskId){
    const p = DB.projects.find(x => x.id === projectId);
    const t = p && (p.tasks || []).find(x => x.id === w.taskId);
    if (t && t.lineRef) return {key: t.lineRef, how: 'task'};
  }
  const opts = typeof lineOptions === 'function' ? lineOptions(projectId) : [];
  const code = w && w.code;
  if (code){
    const hits = opts.filter(o => String(o.line.code || (typeof codeForLine === 'function' ? codeForLine(o.line) : '')) === String(code));
    if (hits.length === 1) return {key: hits[0].key, how: 'code'};
    if (hits.length > 1) return {key: '', how: 'ambiguous', hits: hits.length};
  }
  return {key: '', how: 'none'};
}

const labRate = empId => (DB.employees.find(e => e.id === empId)?.rate) || 0;
const labBurden = empId => (DB.employees.find(e => e.id === empId)?.burden) || 0;

/* Every approved hour, as cost, against the line it belongs to. This is the shape payroll needs and the
   shape the cost report needs, and they are the same shape, which is the point. */
function labCosts(o){
  o = o || {};
  const entries = DB.time.filter(t => t.status === 'approved' && !t.payrollId
    && (!o.projectId || t.projectId === o.projectId));
  const out = [];
  for (const t of entries){
    const splits = (t.work && t.work.length) ? t.work : [{projectId: t.projectId, code: t.code, hours: hoursOf(t), taskId: t.taskId || '', line: t.line || ''}];
    for (const w of splits){
      const pid = w.projectId || t.projectId;
      if (!pid) continue;
      const L = labLineFor(w, pid);
      const hours = r2(+w.hours || 0);
      if (!hours) continue;
      out.push({entry: t, work: w, empId: t.empId, name: DB.employees.find(e => e.id === t.empId)?.name || '',
                date: t.date, projectId: pid, code: w.code || t.code || '', hours,
                rate: labRate(t.empId), amount: r2(hours * labRate(t.empId)),
                line: L.key, how: L.how, hits: L.hits || 0});
    }
  }
  return out.sort((a, b) => String(a.date).localeCompare(String(b.date)) || a.name.localeCompare(b.name));
}

const labGrouped = rows => {
  const g = {};
  rows.forEach(r => { const k = `${r.projectId}|${r.line || 'none'}|${r.empId}`;
    const x = (g[k] = g[k] || {projectId: r.projectId, line: r.line, empId: r.empId, name: r.name, hours: 0, amount: 0, rows: []});
    x.hours = r2(x.hours + r.hours); x.amount = r2(x.amount + r.amount); x.rows.push(r); });
  return Object.values(g);
};

/* ---------- the run ----------
   One button: approved hours become labour cost on their lines, approved reimbursements are paid back
   in the same run, and the existing payroll build does the money. Alan, 00:37:21: "you click run
   payroll. You've categorised everything. Boom." */
function labReimbursements(){
  return (typeof spAll === 'function' ? spAll() : []).filter(s => s.reimburse && s.status === 'approved' && !s.payrollId);
}

function labRun(){
  const rows = labCosts();
  if (!rows.length && !labReimbursements().length){ toast('No approved hours or reimbursements waiting'); return null; }
  const missing = rows.filter(r => !r.line);
  const doIt = () => {
    /* Labour becomes a spend record per person per line — the same object a receipt makes, so it
       reaches job costing, the margin on the line and the cost report by the same road. */
    const made = [];
    labGrouped(rows.filter(r => r.line)).forEach(g => {
      const s = spNew({projectId: g.projectId, kind: 'field', vendor: g.name, by: g.name,
                       date: today(), note: `${g.hours} h @ ${money(labRate(g.empId))}`});
      s.kind = 'labor';
      s.lines = [{id: uid('sl'), amount: g.amount, key: g.line, cls: 'labor',
                  code: (typeof findLine === 'function' ? (findLine(g.line)?.line.code || '') : ''),
                  note: `${g.hours} h`}];
      s.status = 'approved'; s.approvedBy = currentUser()?.name || DB.me || ''; s.approvedAt = today();
      made.push(s);
    });
    const reim = labReimbursements();
    const runs = (typeof payrollFromTime === 'function') ? payrollFromTime() : null;
    const runId = (DB.payroll || []).slice(-1)[0]?.id || '';
    made.forEach(s => { s.payrollId = runId; s.status = 'settled'; s.settledAt = today(); });
    reim.forEach(s => { s.payrollId = runId; s.status = 'settled'; s.settledAt = today();
      audit('spend', s.id, 'reimbursed', null, {payroll: runId}); });
    const labour = r2(made.reduce((a, s) => a + spTotal(s), 0));
    const back = r2(reim.reduce((a, s) => a + spTotal(s), 0));
    log(`Payroll run — ${money(labour)} of labour across ${new Set(made.map(s => s.lines[0].key)).size} lines${back ? `, ${money(back)} reimbursed` : ''}`);
    audit('payroll', runId, 'labour-costed', null, {lines: made.length, labour, reimbursed: back});
    save(); render();
    toast(`${money(labour)} of labour landed on its lines${back ? ` · ${money(back)} reimbursed` : ''}`);
    return {made, reim, runs};
  };

  if (missing.length){
    // Hours that reach no line are the only thing worth stopping for — they are the ones that would
    // otherwise land as a project-level lump nobody can bill or measure.
    mbModal('Some hours reach no line', `
      <p class="small muted" style="margin:0 0 10px">${missing.length} of ${rows.length} splits do not say which line they belong to, so ${money(r2(missing.reduce((a, r) => a + r.amount, 0)))} of labour would land on the job as a lump. Set them on the timesheet, or run anyway and they stay project-level.</p>
      <table class="t"><thead><tr><th>Date</th><th>Who</th><th>Job</th><th>Cost code</th><th class="num">Hours</th><th>Why not</th></tr></thead>
      <tbody>${missing.slice(0, 20).map(r => `<tr><td class="num">${fmt(r.date)}</td><td>${esc(r.name)}</td>
        <td class="sub">${esc(DB.projects.find(p => p.id === r.projectId)?.project?.name || '')}</td>
        <td class="sub">${esc(r.code || '—')}</td><td class="num">${r.hours}</td>
        <td class="small muted">${r.how === 'ambiguous' ? `${r.hits} lines carry that code` : 'no line, no task, no code'}</td></tr>`).join('')}
      </tbody></table>`,
      {submit: 'Run anyway', onSubmit: () => { doIt(); }});
    procWide(760);
    return null;
  }
  return doIt();
}

/* ---------- the screen ---------- */
function labPaneHtml(){
  const rows = labCosts();
  const groups = labGrouped(rows);
  const reim = labReimbursements();
  const labour = r2(rows.reduce((a, r) => a + r.amount, 0));
  const missing = rows.filter(r => !r.line);
  const line = k => { const ref = k && typeof findLine === 'function' ? findLine(k) : null;
    return ref ? `${esc(ref.doc.number)} · ${esc(ref.line.item || ref.line.desc || '')}` : '<span class="an-over">no line</span>'; };
  return `
  <div class="sel-stats" style="margin-bottom:10px">
    <div class="sel-stat"><b>${r2(rows.reduce((a, r) => a + r.hours, 0))}</b><span>approved hours waiting</span></div>
    <div class="sel-stat"><b>${money(labour)}</b><span>of labour, at their rates</span></div>
    <div class="sel-stat ${missing.length ? 'bad' : ''}"><b>${missing.length}</b><span>splits that reach no line</span></div>
    <div class="sel-stat"><b>${money(r2(reim.reduce((a, s) => a + spTotal(s), 0)))}</b><span>to reimburse in the same run</span></div>
  </div>
  ${groups.length ? `<div class="proc-wrap"><table class="t an"><thead><tr><th>Who</th><th>Job</th><th>Goes to</th><th class="num">Hours</th><th class="money">Rate</th><th class="money">Cost</th><th>How the line was found</th></tr></thead>
  <tbody>${groups.map(g => `<tr><td><b>${esc(g.name)}</b></td>
    <td class="sub">${esc(DB.projects.find(p => p.id === g.projectId)?.project?.name || '')}</td>
    <td>${g.line ? line(g.line) : `<select data-labset="${esc(g.rows.map(r => r.entry.id + ':' + (r.entry.work || []).indexOf(r.work)).join(','))}" class="lab-pick">
      <option value="">— which line —</option>${(typeof lineOptions === 'function' ? lineOptions(g.projectId) : []).map(o => `<option value="${esc(o.key)}">${esc(o.label)}</option>`).join('') || '<option value="" disabled>this job has no contract lines</option>'}</select>`}</td>
    <td class="num">${g.hours}</td><td class="money">${money(labRate(g.empId))}</td>
    <td class="money">${money(g.amount)}</td>
    <td class="small muted">${[...new Set(g.rows.map(r => r.how))].map(h => ({stated: 'they said so', task: 'from the task', code: 'only line with that code', ambiguous: 'more than one line has that code', none: '—'}[h] || h)).join(' · ')}</td></tr>`).join('')}
  </tbody></table></div>` : '<div class="empty">No approved hours waiting. Hours land here once a supervisor has approved the day.</div>'}
  ${reim.length ? `<h4 style="margin:14px 0 6px">Riding along with the run</h4>
  <table class="t"><tbody>${reim.map(s => `<tr><td>${esc(s.by)}</td><td>${esc(s.vendor || '')}</td>
    <td class="sub">${esc(DB.projects.find(p => p.id === s.projectId)?.project?.name || '')}</td>
    <td class="money">${money(spTotal(s))}</td></tr>`).join('')}</tbody></table>` : ''}
  <div class="row" style="gap:8px;margin-top:12px"><button class="btn primary" id="lab-run">Run payroll</button>
    <span class="small muted">Approved hours become labour on their lines, reimbursements are paid back in the same run, and the bills are built. One press.</span></div>`;
}

/* ---------- it lives on the Spend screen, as the fifth question ----------
   Where the money starts, in the order it moves: capture, approve, settle, bill, pay. Payroll is the
   last of those and belongs beside the others, not in a different part of the building. */
if (typeof SP_TABS !== 'undefined'){
  SP_TABS.push(['payroll', 'Hours & payroll']);
}
if (typeof spPane === 'function'){
  const spPaneBase_lab = spPane;
  spPane = function(ctx){ return spTab === 'payroll' ? labPaneHtml() : spPaneBase_lab(ctx); };
}
if (typeof wireSpend === 'function'){
  const wireSpendBase_lab = wireSpend;
  wireSpend = function(root){
    wireSpendBase_lab(root);
    root.querySelector('#lab-run')?.addEventListener('click', () => { labRun(); renderSpend(); });
    /* Setting the line here writes it back to the hours themselves, so the answer is given once and the
       timesheet, the payroll run and the margin all agree from then on. */
    root.querySelectorAll('[data-labset]').forEach(sel => sel.onchange = () => {
      if (!sel.value) return;
      let n = 0;
      sel.dataset.labset.split(',').forEach(ref => {
        const [tid, i] = ref.split(':');
        const t = DB.time.find(x => x.id === tid); if (!t) return;
        const w = (t.work || [])[+i];
        if (w){ w.line = sel.value; n++; } else { t.line = sel.value; n++; }
      });
      const ref = typeof findLine === 'function' ? findLine(sel.value) : null;
      audit('time', 'bulk', 'line-set', null, {splits: n, line: sel.value});
      log(`${n} time split${n === 1 ? '' : 's'} pointed at ${ref ? ref.line.item || ref.line.desc : sel.value}`);
      save(); renderSpend();
      toast(`${n} split${n === 1 ? '' : 's'} now land on that line`);
    });
  };
}

/* ---------- the timesheet learns about lines ----------
   One more control on the day the crew already fills in. It is defaulted, not demanded: where the job
   has exactly one line carrying that cost code, that is the line, and the person is only interrupted
   when the answer is genuinely unknown. */
if (typeof renderDaySheet === 'function'){
  const renderDaySheetBase_lab = renderDaySheet;
  renderDaySheet = function(emp){
    renderDaySheetBase_lab(emp);
    const card = document.getElementById('day-card');
    if (!card || card.style.display === 'none') return;
    const td = today();
    const mine = DB.time.filter(t => t.empId === emp.id && !t.payrollId && t.status !== 'approved');
    const e = mine.find(t => t.date === td) || mine.slice(-1)[0];
    if (!e || !(e.work || []).length) return;
    const locked = e.status === 'approved';
    card.querySelectorAll('.work').forEach((row, i) => {
      const w = e.work[i]; if (!w || row.querySelector('[data-wl]')) return;
      const pid = w.projectId || e.projectId;
      const opts = typeof lineOptions === 'function' ? lineOptions(pid) : [];
      const L = labLineFor(w, pid);
      const sel = document.createElement('select');
      sel.dataset.wl = i;
      sel.disabled = locked;
      sel.title = 'Which line of the estimate this hour belongs to — what makes it show up in the margin';
      sel.innerHTML = `<option value="">${L.key ? '↳ ' + (L.how === 'task' ? 'from the task' : 'only line with that code') : 'Which line…'}</option>` +
        opts.map(o => `<option value="${esc(o.key)}" ${w.line === o.key ? 'selected' : ''}>${esc(o.label)}</option>`).join('');
      sel.addEventListener('change', () => { w.line = sel.value; save(); render(); });
      row.insertBefore(sel, row.querySelector('input') || null);
    });
  };
}
/*<</labor.js>>*/


/*<<receipt.js>>*/
/* ===================== READING THE PAPER =====================
   The receipt in a crew member's pocket is the most information-dense document in the business, and
   it is the only one nobody reads. It carries the vendor, the date, the card, and — the part that
   matters — a printed list of exactly what was bought, line by line, at the price paid.

   One trip to Quality Building is Douglas fir for the window frames, a box of screws, and a bag of
   N95s for the crew. Three cost codes, two classes, one piece of paper. Today that becomes a single
   $412.60 charge against "materials", and the only person who could have split it is standing at the
   counter with a phone.

   And it is written on. The driver rings the total, circles it, writes "121 State — front windows"
   across the top and "$118 office" beside the masks. That handwriting is the field's answer to the
   question accounting will ask three weeks later. It should be read — but it must never be believed
   over the print.

   THE RULE, and it is the whole reason this can be trusted:

     Handwriting CHOOSES among what the printed receipt already says. It never overrides it.

   Ink that agrees with the print raises confidence and fills the answer in. Ink that disagrees with
   the print is a finding for a person, and the print stands. Ink about something the print is silent
   on — a room, a job, a set of initials — is a proposal, never a posting.

   And one more, which keeps the job cost honest: THE SPLITS ALWAYS SUM TO THE PAPER. What the reader
   could not classify is carried as an explicit unclassified remainder, visible on the record. A cost
   we could not name is a finding; a cost that quietly went missing is a lie. */

/* ---------- what a line on a hardware receipt is ----------
   LINE_KW maps the words on an estimate to a cost code. It is no use here: an estimate says
   "Framing & rough carpentry", a receipt says "2X4-104 5/8 STUD SPF". This is the counter's
   vocabulary — what the words on the paper mean in the trades this firm actually runs.

   Order matters: the first match wins, so the specific sits above the general. "TILE SAW" is
   equipment, not tile, which is why it appears before "tile". */
const RC_VOCAB = [
  // rentals, tools and equipment — before the trades, because a "tile saw" is not tile
  [/\b(rental|rent(ed)?\s|day\s*rate|scaffold\s*rent)/i,        'other',  '01', 'a rental'],
  [/\b(saw|drill|blade|bit set|hammer|level|ladder|tool|torpedo|sawzall|impact driver)\b/i, 'other', '01', 'a tool'],
  [/\b(dumpster|dump fee|disposal|debris|haul[- ]?away|tipping)/i,'other', '02', 'disposal'],
  // general conditions — the crew's own consumables, not the building
  [/\b(n95|respirator|mask|glove|glasses|goggle|hard ?hat|vest|ear ?plug|first aid|knee ?pad)/i, 'other', '01', 'crew safety'],
  [/\b(broom|dust ?pan|contractor bag|trash bag|shop ?vac|rag|towel|cleaner|degreaser)/i, 'other', '01', 'site clean-up'],
  [/\b(zip ?wall|poly|plastic sheet|ram ?board|floor protect|masking|drop ?cloth|red ?rosin)/i, 'other', '01', 'protection'],
  [/\b(porta|portable toilet|water cooler|coffee|lunch|snack)/i, 'other', '01', 'site services'],
  // demolition
  [/\b(pry ?bar|demo bar|sledge|chipping|wrecking)/i,            'rough', '02', 'demolition'],
  // framing & rough carpentry
  [/\b(2\s*x\s*\d|4\s*x\s*4|stud|spf|doug(las)? ?fir|df\b|lvl|glulam|joist|rafter|header|sill plate|blocking)/i, 'rough', '03', 'framing lumber'],
  [/\b(plywood|ply\b|osb|cdx|subfloor|advantech|sheathing|furring|strapping)/i, 'rough', '03', 'sheet goods'],
  [/\b(screw|nail|fastener|lag|anchor|bracket|joist hanger|simpson|construction adhesive|liquid nails)/i, 'rough', '03', 'fasteners'],
  // windows, doors & exterior envelope
  [/\b(flashing|house ?wrap|tyvek|sill pan|weather ?strip|caulk.*(window|exterior)|lintel|brick|mortar|pointing|parge)/i, 'rough', '04', 'exterior'],
  // plumbing
  [/\b(pex|copper (pipe|tube)|cpvc|abs|pvc (pipe|fitting)|p-?trap|shark ?bite|solder|flux|ball valve|shut ?off|escutcheon|supply line|wax ring|closet flange)/i, 'rough', '05', 'plumbing rough'],
  // electrical
  [/\b(romex|nm-?b|thhn|wire|conduit|emt|breaker|panel|gfci|afci|receptacle|outlet|switch|device box|old work box|wire ?nut|wago|junction)/i, 'rough', '06', 'electrical rough'],
  // insulation, drywall & taping
  [/\b(insulation|rockwool|mineral wool|batt|foam board|spray foam|great stuff|vapor)/i, 'rough', '07', 'insulation'],
  [/\b(drywall|sheetrock|gyp|green ?board|durock|cement board|corner bead|joint compound|mud|tape|setting compound|durabond)/i, 'rough', '07', 'drywall'],
  // tile & waterproofing
  [/\b(thin ?set|thinset|grout|kerdi|redgard|schluter|membrane|backer|spacer|wedi)/i, 'rough', '08', 'tile setting'],
  [/\b(tile|mosaic|porcelain|marble|slab)/i,                     'finish','08', 'tile'],
  // flooring
  [/\b(underlayment|hardwood|white oak|engineered|luxury vinyl|lvp|stair nose|reducer|transition|floor finish|polyurethane|bona)/i, 'finish','09', 'flooring'],
  // millwork & counters
  [/\b(cabinet|millwork|counter ?top|quartz|butcher ?block|shelf|shelving|melamine|edge ?band)/i, 'finish','10', 'millwork'],
  // finish carpentry, doors & hardware
  [/\b(base ?board|casing|crown|moulding|molding|trim|jamb|door slab|hinge|door knob|lever|pull|knob|latch|astragal)/i, 'finish','11', 'finish carpentry'],
  // paint & restoration
  [/\b(primer|paint|benjamin|sherwin|farrow|spackle|sand ?paper|roller|brush|tray|painters tape|frog ?tape|stain|shellac)/i, 'rough', '12', 'paint'],
  // fixtures & appliances
  [/\b(faucet|sink|toilet|vanity|tub|shower ?head|valve trim|light|fixture|sconce|pendant|led|bulb|fan|range|hood|dishwasher|refrigerator|washer|dryer)/i, 'finish','13', 'fixtures'],
  // permits & fees
  [/\b(permit|filing fee|inspection|expedit|dob\b|landmark)/i,   'other', '14', 'permits & fees'],
  // delivery is not a thing, it is a charge that belongs to whatever it carried
  [/\b(delivery|freight|shipping|fuel surcharge|handling)/i,     'rough', '',   'delivery'],
];
/* A receipt line, read. `cls` and `code` are proposals with the word that produced them attached, so
   a person correcting one can see why it was wrong. Nothing here posts. */
function rcClassify(desc){
  const t = String(desc || '');
  for (const [re, cls, code, why] of RC_VOCAB){ const m = t.match(re); if (m) return {cls, code, why, word: m[0]}; }
  return {cls: 'rough', code: '', why: 'nothing on the line said what it was', word: ''};
}
/* Delivery, freight and fuel are not their own cost — they belong to what they carried. When the rest
   of the receipt agrees on a code, the charge follows it rather than sitting in 99. */
function rcCarry(lines){
  const votes = {};
  lines.forEach(l => { if (l.code && l.why !== 'delivery') votes[l.code] = (votes[l.code] || 0) + (+l.amount || 0); });
  const top = Object.entries(votes).sort((a, b) => b[1] - a[1])[0];
  lines.forEach(l => { if (l.why === 'delivery' && !l.code && top){ l.code = top[0]; l.why = 'delivery, coded with what it carried'; } });
  return lines;
}

/* ---------- the rules reader ----------
   Runs with no network. Hardware receipts are printed by a handful of point-of-sale systems and they
   are more regular than they look: a SKU, a description, then either "QTY @ PRICE" on the same line or
   on the one below, then the extended amount right-aligned. */
const RC_MONEY = /(-?\$?\s?(?:\d{1,3}(?:,\d{3})+|\d+)\.\d{2})\s*[A-Z]?$/;
const rcNum = s => +String(s || '').replace(/[$,\s]/g, '') || 0;
function rcParseText(text){
  const raw = String(text || '').split(/\r?\n/).map(l => l.replace(/\s+$/, '')).filter(l => l.trim());
  const read = {vendor: '', date: '', card: '', subtotal: 0, tax: 0, total: 0, lines: [], ink: [], source: 'read from the text on the receipt'};
  if (!raw.length) return read;

  // The vendor is the first line that is not an address, a phone number or a store number.
  read.vendor = (raw.find(l => /[A-Za-z]{3}/.test(l) && !/^\d|store|#\d|\(\d{3}\)|\d{3}-\d{4}|^\s*\d+\s+\w+\s+(st|ave|rd|blvd)/i.test(l)) || '').trim().slice(0, 60);

  const dm = raw.join('\n').match(/\b(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})\b/);
  if (dm){ const y = dm[3].length === 2 ? '20' + dm[3] : dm[3]; read.date = `${y}-${String(dm[1]).padStart(2, '0')}-${String(dm[2]).padStart(2, '0')}`; }
  read.card = (raw.join('\n').match(/(?:x{2,}|\*{2,}|ending\s+in\s*)(\d{4})\b/i) || [])[1] || '';

  const totOf = re => { const l = raw.find(x => re.test(x)); const m = l && l.match(RC_MONEY); return m ? rcNum(m[1]) : 0; };
  read.subtotal = totOf(/\bsub ?total\b/i);
  read.tax      = totOf(/\b(sales )?tax\b/i);
  read.total    = totOf(/\b(grand )?total\b(?!.*sub)/i) || totOf(/\bamount (due|paid)\b/i);

  const skipRe = /\b(sub ?total|tax|total|change|cash|visa|master|amex|debit|credit|auth|approval|balance|tender|thank you|return policy|store|cashier|reg #|survey)\b/i;
  for (let i = 0; i < raw.length; i++){
    const l = raw[i];
    if (skipRe.test(l)) continue;
    const m = l.match(RC_MONEY); if (!m) continue;
    const amount = rcNum(m[1]); if (!amount) continue;
    let body = l.slice(0, l.length - m[0].length).trim();
    const sku = (body.match(/^(\d{6,}|[A-Z0-9]{3,}-[A-Z0-9-]{3,})\s+/) || [])[1] || '';
    if (sku) body = body.slice(sku.length).trim();

    /* "3 @ 12.48", either trailing the description or on the line below.
       Not "x". A hardware receipt is full of 2X6, 4X8 and 1/2IN, and reading "2X6-12" as two at six
       dollars mangles the price AND eats the words that say what it is. The multiplication sign only
       counts when it is spaced and followed by a price with cents. */
    let qty = 1, unit = 0;
    const QAT = /(\d+(?:\.\d+)?)\s*(?:ea\s*)?@\s*\$?(\d+(?:\.\d+)?)/i;
    const QX  = /(\d+(?:\.\d+)?)\s+x\s+\$?(\d+\.\d{2})\b/i;
    const q1 = body.match(QAT) || body.match(QX);
    const q2 = !q1 && raw[i + 1] && (raw[i + 1].match(new RegExp('^\\s*' + QAT.source, 'i')) || raw[i + 1].match(new RegExp('^\\s*' + QX.source, 'i')));
    const q = q1 || q2;
    if (q){ qty = +q[1] || 1; unit = +q[2] || 0; if (q1) body = body.replace(q1[0], '').trim(); }
    else { unit = amount; }
    // the quantity column repeats at the head of the description; drop it once, and only if it agrees
    const lead = body.match(/^(\d+(?:\.\d+)?)\s+(?=\S)/);
    if (lead && Math.abs(+lead[1] - qty) < 0.001) body = body.slice(lead[0].length);
    body = body.replace(/[\s.\-]+$/, '').trim();
    if (!body) continue;
    read.lines.push({id: uid('rl'), n: read.lines.length + 1, sku, desc: body, qty, unit, amount});
  }
  if (!read.total && read.lines.length) read.total = r2(read.lines.reduce((a, l) => a + l.amount, 0) + read.tax);
  read.lines.forEach(l => Object.assign(l, rcClassify(`${l.sku} ${l.desc}`)));
  rcCarry(read.lines);
  return read;
}

/* ---------- the vision reader ----------
   Two jobs in one pass, kept separate in the reply so they can be compared rather than blended: what
   the receipt PRINTS, and what somebody WROTE ON IT. Blending them is exactly the failure to avoid —
   a model that quietly "corrects" a printed price to match a handwritten one has destroyed the only
   independent check we have. */
const RC_PROMPT = `You are reading a photograph of a paper receipt from a construction supplier.

Return ONLY JSON, no prose, in exactly this shape:
{"vendor":"","date":"YYYY-MM-DD","card":"last4 or empty","subtotal":0,"tax":0,"total":0,
 "lines":[{"sku":"","desc":"","qty":1,"unit":0,"amount":0,"conf":0.0}],
 "ink":[{"text":"","where":"top|beside a line|bottom|margin","nearLine":0,"conf":0.0}]}

Rules you must follow:
- "lines" is ONLY what the receipt PRINTS. Copy the printed description verbatim, abbreviations and all.
- "ink" is ONLY what a person wrote by hand on the paper - pen, marker, circles, arrows. Transcribe it
  literally. Do NOT clean it up, expand abbreviations, or guess at a word you cannot read: put the part
  you can read and set conf low.
- NEVER let handwriting change a printed number. If ink says 412.60 and the print says 421.60, report
  the print as 421.60 and the ink as "412.60". Reporting the disagreement is the point.
- If a handwritten note sits beside a particular printed line, set nearLine to that line's 1-based index.
- conf is 0 to 1: how sure you are you read those characters correctly.
- Omit nothing because it looks unimportant. A line you skip becomes a cost nobody can account for.`;

async function rcAskVision(dataUrl){
  const m = String(dataUrl || '').match(/^data:(image\/[a-z+]+);base64,(.+)$/i);
  if (!m) return {err: 'the receipt is not an image we can send'};
  try {
    const r = await fetch(aiEndpoint(), {method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({model: 'claude-sonnet-4-6', max_tokens: 2000, messages: [{role: 'user', content: [
        {type: 'image', source: {type: 'base64', media_type: m[1], data: m[2]}},
        {type: 'text', text: RC_PROMPT}]}]})});
    if (!r.ok) return {err: `the reader answered ${r.status}`};
    const data = await r.json();
    if (data.error) return {err: data.error.message || 'the reader refused'};
    const txt = (data.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
    const j = safeJSON(txt);
    if (!j || !Array.isArray(j.lines)) return {err: 'the reader did not answer in a shape we can use'};
    return {read: j};
  } catch (e){ return {err: e.message || 'the reader could not be reached'}; }
}

/* Normalise either reader into one record. */
function rcNormalise(j, source){
  const read = {vendor: j.vendor || '', date: j.date || '', card: j.card || '', subtotal: +j.subtotal || 0,
                tax: +j.tax || 0, total: +j.total || 0, source, at: nowStamp(),
                lines: (j.lines || []).map((l, i) => Object.assign({
                  id: uid('rl'), n: i + 1, sku: l.sku || '', desc: l.desc || '', qty: +l.qty || 1,
                  unit: +l.unit || 0, amount: r2(+l.amount || 0), conf: l.conf == null ? 1 : +l.conf,
                }, rcClassify(`${l.sku || ''} ${l.desc || ''}`))),
                ink: (j.ink || []).map(k => ({id: uid('ik'), text: String(k.text || '').trim(),
                  where: k.where || '', nearLine: +k.nearLine || 0, conf: k.conf == null ? 1 : +k.conf}))};
  rcCarry(read.lines);
  if (!read.total && read.lines.length) read.total = r2(read.lines.reduce((a, l) => a + l.amount, 0) + read.tax);
  return read;
}

/* The one entry point. Vision if it can be reached, rules if it cannot, and the record says which —
   because a number read by a model and a number read by a regex do not deserve the same trust. */
async function rcRead(s){
  const img = typeof spImg === 'function' ? spImg(s) : (s.receipt || '');
  // Only a real photograph goes to the reader. A drawn stand-in is an SVG, which is markup rather
  // than pixels: sending it would be asking a vision model to read our own HTML back to us.
  if (img && /^data:image\/(png|jpe?g|webp|gif);base64,/i.test(img)){
    const {read, err} = await rcAskVision(img);
    if (read) return rcNormalise(read, 'read from the photograph');
    if (s.receiptText) return Object.assign(rcParseText(s.receiptText), {note: err});
    return {err: err, lines: [], ink: []};
  }
  if (s.receiptText) return rcParseText(s.receiptText);
  return {err: 'there is no receipt on this record yet', lines: [], ink: []};
}

/* ---------- does it add up ----------
   The gate. Lines + tax must equal the printed total. When they do not, the difference is not hidden
   and it is not dropped: it is carried as an unclassified remainder so the job still bears the whole
   cost, and it is shown as a finding so somebody looks at the paper. */
function rcMath(read){
  const lines = r2((read.lines || []).reduce((a, l) => a + (+l.amount || 0), 0));
  const sub = read.subtotal || lines;
  const tax = +read.tax || 0;
  const total = +read.total || r2(sub + tax);
  const gap = r2(total - r2(lines + tax));
  const notes = [];
  if (read.subtotal && Math.abs(r2(read.subtotal - lines)) > 0.02)
    notes.push(`the lines add to ${money2(lines)} but the receipt's own subtotal says ${money2(read.subtotal)}`);
  if (Math.abs(gap) > 0.02)
    notes.push(gap > 0 ? `${money2(gap)} of the total is not on any line we could read`
                       : `the lines add to ${money2(-gap)} more than the total`);
  return {lines, sub, tax, total, gap, ok: Math.abs(gap) <= 0.02, notes};
}
const money2 = n => '$' + (Math.round((+n || 0) * 100) / 100).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});

/* ---------- reading the handwriting against the print ----------
   Every note gets a state, and the states are the whole point:

     confirms   the print says the same thing. Use it, and say why we are sure.
     conflicts  the print says otherwise. The PRINT STANDS and a person is told.
     proposes   the print is silent (a room, a job, initials). Offered, never applied on its own.
     unclear    we could not read it well enough to check. Shown as unreadable, with the crop.

   A note about a job the record is not on is called out hardest, because a receipt costed to the
   wrong job is worse than one costed to nothing: it is wrong in two places and looks right in both. */
function rcInk(read, s){
  const m = rcMath(read);
  const proj = DB.projects.find(p => p.id === (s && s.projectId));
  const opts = typeof spLineOptions === 'function' ? spLineOptions(s && s.projectId) : [];
  const out = [];

  (read.ink || []).forEach(k => {
    const t = (k.text || '').trim(); if (!t) return;
    const low = t.toLowerCase();
    const add = o => out.push(Object.assign({id: k.id, text: t, conf: k.conf, where: k.where, nearLine: k.nearLine}, o));

    if (k.conf != null && k.conf < 0.45){
      add({kind: 'unclear', state: 'unclear', says: 'not legible enough to check',
           detail: 'Left as written. Nothing is filled in from a word we could not read.'});
      return;
    }

    // an amount
    const amt = (t.match(/\$?\s?((?:\d{1,3}(?:,\d{3})+|\d+)\.\d{2})\b/) || [])[1];
    if (amt){
      const v = rcNum(amt);
      const line = (read.lines || []).find(l => Math.abs(l.amount - v) < 0.02);
      const run  = rcSubsetTo(read.lines || [], v);
      if (m.sub && Math.abs(v - m.sub) < 0.02 && Math.abs(m.sub - m.total) > 0.02)
        add({kind: 'amount', state: 'confirms', says: `the subtotal, ${money2(v)}`,
             detail: 'The written figure is the receipt before tax. Every printed line is accounted for.'});
      else if (Math.abs(v - m.total) < 0.02)
        add({kind: 'amount', state: 'confirms', says: `the total, ${money2(v)}`,
             detail: 'The written total matches the printed total. The photograph is of the whole receipt, not a page of it.'});
      else if (line)
        add({kind: 'amount', state: 'confirms', says: `${money2(v)} — line ${line.n}, ${line.desc}`, line: line.id,
             detail: 'A written amount that lands exactly on a printed line is the field telling us where to split.'});
      else if (run)
        add({kind: 'amount', state: 'confirms', says: `${money2(v)} — lines ${run.map(l => l.n).join(', ')}`, lines: run.map(l => l.id),
             detail: 'These printed lines add to the written amount. That is the split the crew intended.'});
      else
        add({kind: 'amount', state: 'conflicts', says: `${money2(v)} — nothing printed adds to it`,
             detail: `The printed total is ${money2(m.total)} and no line or run of lines makes ${money2(v)}. The print stands; somebody should look at the paper.`});
      return;
    }

    // a cost code, written as a bare number or "code 3"
    const cc = (t.match(/\bcode\s*#?\s*(\d{1,2})\b/i) || t.match(/^#?\s*(0\d|1[0-4])\s*$/) || [])[1];
    if (cc){
      const code = String(cc).padStart(2, '0');
      const known = COST_CODES.find(c => c[0] === code);
      const printed = [...new Set((read.lines || []).map(l => l.code).filter(Boolean))];
      if (!known) add({kind: 'code', state: 'conflicts', says: `cost code ${code}, which we do not use`, detail: 'Left off. A code that is not on the schedule is a mis-read or a mis-write.'});
      else if (printed.includes(code)) add({kind: 'code', state: 'confirms', says: `cost code ${code} — ${known[1]}`, code,
             detail: 'What was bought agrees with the code that was written. Applied to the lines it covers.'});
      else add({kind: 'code', state: 'conflicts', says: `cost code ${code} — ${known[1]}`, code,
             detail: `Nothing printed on this receipt reads as ${known[1]}${printed.length ? ` — it reads as ${printed.map(c => (COST_CODES.find(x => x[0] === c) || [,c])[1]).join(' and ')}` : ''}. The print stands.`});
      return;
    }

    // a job — by name, by address, or by client surname
    const hit = DB.projects.find(p => {
      const n = (p.project?.name || '').toLowerCase(), a = (p.project?.address || '').toLowerCase();
      const cl = (typeof clientOf === 'function' ? clientOf(p)?.name : '') || '';
      const num = (a.match(/^\d+/) || n.match(/^\d+/) || [])[0];
      return (n && low.includes(n.slice(0, 12))) || (num && low.includes(num) && /\d/.test(low))
          || (cl && low.includes(cl.split(' ').pop().toLowerCase()));
    });
    if (hit){
      if (proj && hit.id === proj.id)
        add({kind: 'job', state: 'confirms', says: `the job — ${hit.project.name}`,
             detail: 'The job written on the paper is the job on this record.'});
      else
        add({kind: 'job', state: 'conflicts', says: `the job — ${hit.project.name}`, projectId: hit.id, hard: true,
             detail: `This record is on ${proj ? proj.project.name : 'no job'}. A receipt costed to the wrong job is wrong twice and looks right both times. Somebody decides this one.`});
      return;
    }

    // a room or an area — the print cannot confirm it, but the estimate can offer a line
    const near = opts.filter(o => { const w = low.split(/[^a-z]+/).filter(x => x.length > 3);
                                    return w.some(x => o.label.toLowerCase().includes(x)); });
    if (near.length === 1)
      add({kind: 'line', state: 'proposes', says: `the line — ${near[0].label}`, key: near[0].key,
           detail: 'The receipt does not say which line; the estimate has one that matches what was written. Yours to accept.'});
    else if (near.length > 1)
      add({kind: 'line', state: 'proposes', says: `${near.length} lines match those words`, keys: near.map(o => o.key),
           detail: 'More than one line could be meant. Pick one rather than letting it be guessed.'});
    // a person
    else if (/^[A-Z][a-z]+$|^[A-Z]{2,3}$/.test(t) && t.length <= 12){
      const who = (DB.employees || []).find(e => (e.name || '').toLowerCase().startsWith(low) ||
                    (e.name || '').split(' ').map(x => x[0]).join('').toLowerCase() === low);
      add({kind: 'who', state: who ? 'confirms' : 'proposes', says: who ? `who bought it — ${who.name}` : `initials — ${t}`,
           who: who ? who.name : '', detail: who ? 'Matches somebody on the crew.' : 'Not a name we hold. Kept on the record as written.'});
    }
    else
      add({kind: 'note', state: 'proposes', says: t,
           detail: 'Kept verbatim on the record, in the language it was written in. Nothing is inferred from it.'});
  });
  return out;
}
/* The smallest run of printed lines that adds to a written amount — how a hand-written split is
   confirmed against the paper. Small subsets only; a "match" found among twenty lines is arithmetic
   coincidence, not evidence. */
function rcSubsetTo(lines, target){
  const ls = lines.slice(0, 14);
  for (let size = 2; size <= Math.min(4, ls.length); size++){
    const idx = [];
    const walk = (start, left) => {
      if (!left){ const sum = r2(idx.reduce((a, i) => a + ls[i].amount, 0));
                  return Math.abs(sum - target) < 0.02 ? idx.map(i => ls[i]) : null; }
      for (let i = start; i <= ls.length - left; i++){ idx.push(i); const r = walk(i + 1, left - 1); if (r) return r; idx.pop(); }
      return null;
    };
    const r = walk(0, size); if (r) return r;
  }
  return null;
}

/* ---------- from a reading to a record ----------
   Printed lines become splits on the spend record — one per line, or grouped by cost code when the
   receipt is long, because eleven splits on a $60 receipt is data entry by another name. The
   unclassified remainder rides along so the total ties to the paper. */
function rcApply(s, read, opts){
  opts = opts || {};
  const keep = (read.lines || []).filter(l => !opts.drop || !opts.drop.includes(l.id));
  /* Struck off is not gone. A line somebody decided is not a cost to this job was still on the paper
     and still on the card, so it stays in the remainder: the record's total has to equal the charge
     or settlement will never find it, and a job cost that quietly shrinks is the failure this whole
     module exists to end. */
  const struck = r2((read.lines || []).filter(l => opts.drop && opts.drop.includes(l.id)).reduce((a, l) => a + l.amount, 0));
  const m = rcMath(Object.assign({}, read, {lines: keep}));
  const group = opts.group !== false && keep.length > 6;
  const rows = [];
  if (group){
    const by = {};
    keep.forEach(l => { const k = `${l.cls}|${l.code}`; (by[k] = by[k] || []).push(l); });
    Object.values(by).forEach(g => rows.push({
      amount: r2(g.reduce((a, l) => a + l.amount, 0)), cls: g[0].cls, code: g[0].code,
      note: `${g.length} item${g.length === 1 ? '' : 's'} — ${g.slice(0, 3).map(l => l.desc).join(', ')}${g.length > 3 ? '…' : ''}`,
      from: g.map(l => l.id),
    }));
  } else keep.forEach(l => rows.push({
    amount: l.amount, cls: l.cls, code: l.code,
    note: [l.qty > 1 ? `${l.qty} × ${money2(l.unit)}` : '', l.desc].filter(Boolean).join(' · '), from: [l.id],
  }));

  // tax rides with the largest split rather than becoming a cost of its own
  if (m.tax > 0.02 && rows.length){
    const big = rows.reduce((a, b) => (b.amount > a.amount ? b : a));
    big.amount = r2(big.amount + m.tax); big.note += ` (incl. ${money2(m.tax)} tax)`;
  }
  if (Math.abs(m.gap) > 0.02) rows.push({
    amount: m.gap, cls: 'other', code: '',
    note: struck > 0.02
      ? `On the receipt but not costed here${Math.abs(m.gap - struck) > 0.02 ? ', plus what could not be read' : ''} — needs a pair of eyes`
      : 'On the receipt but not on a line we could read — needs a pair of eyes',
    unclassified: true, from: [],
  });

  const keyFor = opts.keys || {};
  s.lines = rows.map(r => ({id: uid('sl'), amount: r.amount, key: keyFor[r.code] || opts.key || '',
                            code: r.code, cls: r.cls, note: r.note, from: r.from, unclassified: !!r.unclassified}));
  if (read.vendor && !s.vendor) s.vendor = read.vendor;
  if (read.date && read.date !== s.date) s.dateOnPaper = read.date;
  if (read.card && !s.cardLast4) s.cardLast4 = read.card;
  s.read = {source: read.source, at: read.at || nowStamp(), total: m.total, tax: m.tax, gap: m.gap,
            lines: read.lines, ink: read.ink, by: currentUser()?.name || DB.me || ''};
  audit('spend', s.id, 'receipt-read', null, {source: read.source, lines: (read.lines || []).length,
        ink: (read.ink || []).length, gap: m.gap});
  save();
  return s;
}

/* ===================== THE SCREEN =====================
   The paper on the left, what we made of it on the right. Every proposal says where it came from, and
   the two things a person must actually decide — a conflict, and an unclassified remainder — are the
   only things shouting. */
const RC_STATE = {confirms: ['ok', 'confirmed'], conflicts: ['bad', 'conflict'],
                  proposes: ['info', 'not on the receipt'], unclear: ['neutral', 'unreadable']};
/* What a person has to decide comes first. A conflict is a decision, a proposal is an offer, a
   confirmation is only reassurance, and something we could not read is a footnote. Leaving them in
   the order they happened to be written puts the one thing that matters fourth down the page. */
const RC_ORDER = {conflicts: 0, proposes: 1, confirms: 2, unclear: 3};
const rcSortInk = ink => ink.slice().sort((a, b) => (RC_ORDER[a.state] ?? 9) - (RC_ORDER[b.state] ?? 9)
                                                 || (b.hard ? 1 : 0) - (a.hard ? 1 : 0));

function rcReviewModal(s, read){
  const ink = rcSortInk(rcInk(read, s));
  const opts = typeof spLineOptions === 'function' ? spLineOptions(s.projectId) : [];
  let group = (read.lines || []).length > 6;
  const drop = new Set();

  const draw = () => {
    const keep = (read.lines || []).filter(l => !drop.has(l.id));
    const kept = r2(keep.reduce((a, l) => a + l.amount, 0));
    /* Struck-off lines change the arithmetic, so the arithmetic is redone against what is left. It
       was computed once when the dialog opened, which meant striking a $85 delivery off still showed
       "the lines add up to the paper" — the one sentence on this screen that must never be wrong. */
    const m = rcMath(Object.assign({}, read, {lines: keep}));
    const hard = ink.filter(k => k.state === 'conflicts');

    const lineRow = l => `<tr class="${drop.has(l.id) ? 'off' : ''}" data-rcl="${l.id}">
      <td class="n">${l.n}</td>
      <td><div>${esc(l.desc)}</div>${l.sku ? `<div class="small muted">SKU ${esc(l.sku)}</div>` : ''}
          ${l.conf < 0.7 ? `<div class="small warn">read with low confidence — check it against the photo</div>` : ''}</td>
      <td class="n">${l.qty > 1 ? `${l.qty} × ${money2(l.unit)}` : ''}</td>
      <td class="n"><b>${money2(l.amount)}</b></td>
      <td><select data-rcf="cls">${SP_CLASSES.map(([k, lab]) => `<option value="${k}" ${l.cls === k ? 'selected' : ''}>${lab}</option>`).join('')}</select></td>
      <td><select data-rcf="code"><option value="">—</option>${COST_CODES.map(c => `<option value="${c[0]}" ${l.code === c[0] ? 'selected' : ''}>${c[0]} ${esc(c[1])}</option>`).join('')}</select>
          <div class="small muted">${esc(l.why || '')}</div></td>
      <td><span class="rm" data-rcdrop="${l.id}" title="not a cost — take it off">${drop.has(l.id) ? '↺' : '✕'}</span></td></tr>`;

    const inkRow = k => { const [cls, what] = RC_STATE[k.state] || RC_STATE.proposes;
      return `<div class="rc-ink ${k.state}">
        <div class="row" style="gap:8px;align-items:baseline">
          <span class="pill ${cls}">${esc(what)}</span>
          <b>“${esc(k.text)}”</b>${k.where ? `<span class="small muted">${esc(k.where)}</span>` : ''}
          <span class="grow"></span>${k.conf != null && k.conf < 1 ? `<span class="small muted">${Math.round(k.conf * 100)}% sure of the characters</span>` : ''}
        </div>
        <div class="small">${esc(k.says)}</div>
        <div class="small muted">${esc(k.detail)}</div>
        ${k.state === 'proposes' && (k.key || k.who) ? `<button class="btn sm" data-rctake="${k.id}">Use it</button>` : ''}
        ${k.state === 'conflicts' && k.projectId ? `<button class="btn sm" data-rcjob="${k.projectId}">Move this receipt to ${esc((DB.projects.find(p => p.id === k.projectId)?.project.name) || '')}</button>` : ''}
      </div>`; };

    mbModal(`What the receipt says${read.vendor ? ' — ' + esc(read.vendor) : ''}`, `
      <div class="rc-wrap">
        <div class="rc-paper">
          ${s.receipt ? `<img src="${esc(spImg(s))}" alt="the receipt">` : `<div class="muted small">no photograph on this record</div>`}
          <div class="small muted" style="margin-top:6px">${esc(read.source || 'read')}${read.card ? ` · card ending ${esc(read.card)}` : ''}${read.date ? ` · dated ${esc(read.date)}` : ''}</div>
        </div>
        <div class="rc-side">
          <div class="rc-sum ${m.ok ? '' : 'bad'}">
            <div><span>${keep.length} line${keep.length === 1 ? '' : 's'}</span><b>${money2(kept)}</b></div>
            ${m.tax ? `<div><span>tax</span><b>${money2(m.tax)}</b></div>` : ''}
            <div><span>printed total</span><b>${money2(m.total)}</b></div>
            ${m.ok ? `<div class="ok small">the lines add up to the paper</div>`
                   : `<div class="bad small">${esc(m.notes.join('; '))} — it will be carried as unclassified so the job still bears it</div>`}
          </div>
          ${hard.length ? `<div class="rc-hard"><b>${hard.length} thing${hard.length === 1 ? '' : 's'} written on this receipt disagree${hard.length === 1 ? 's' : ''} with what is printed on it.</b>
            <div class="small">The print stands. These are yours to decide.</div></div>` : ''}
          <h4>Written on the paper</h4>
          ${ink.length ? ink.map(inkRow).join('') : `<p class="small muted">Nothing handwritten was found.</p>`}
          <h4>Where it lands</h4>
          <label class="cl-chk"><input type="checkbox" id="rc-group" ${group ? 'checked' : ''}><span>Group the splits by cost code — ${(read.lines || []).length} printed lines becomes ${new Set(keep.map(l => `${l.cls}|${l.code}`)).size}</span></label>
          <div class="f" style="margin-top:8px"><label>Put every split on this estimate line, unless one says otherwise</label>
            <select id="rc-key"><option value="">— decide per split later —</option>${opts.map(o => `<option value="${esc(o.key)}">${esc(o.label)}</option>`).join('')}</select></div>
        </div>
      </div>
      <table class="t rc-lines"><thead><tr><th style="width:34px">#</th><th>What the receipt printed</th><th style="width:96px">Qty</th><th style="width:92px">Amount</th><th style="width:158px">Class</th><th style="width:190px">Cost code</th><th style="width:30px"></th></tr></thead>
        <tbody>${(read.lines || []).map(lineRow).join('') || `<tr><td colspan="7" class="muted small">No printed lines were read. Check the photograph is sharp and the whole receipt is in frame.</td></tr>`}</tbody></table>
      <p class="small muted" style="margin:10px 0 0">Handwriting chooses among what the receipt already says; it never overrides it. Nothing here posts until you submit it.</p>`,
      {submit: 'Put it on the record', wide: true, onSubmit: () => {
        rcApply(s, read, {group: document.getElementById('rc-group')?.checked,
                          key: document.getElementById('rc-key')?.value || '',
                          drop: [...drop]});
        // a note the field wrote, kept verbatim, in whatever language it was written in
        const notes = ink.filter(k => k.kind === 'note' || k.kind === 'who').map(k => k.text);
        if (notes.length) s.note = [s.note, ...notes].filter(Boolean).join(' · ');
        save(); render();
        toast(`${s.lines.length} split${s.lines.length === 1 ? '' : 's'} from the receipt`);
        if (typeof spCaptureModal === 'function') setTimeout(() => spCaptureModal({spend: s}), 60);
      }});
    if (typeof procWide === 'function') procWide(1120);

    const el = document.getElementById('mbm'); if (!el) return;
    const redraw = () => { mbCloseModal(); draw(); };
    el.querySelectorAll('[data-rcdrop]').forEach(x => x.onclick = () => {
      const id = x.dataset.rcdrop; drop.has(id) ? drop.delete(id) : drop.add(id); redraw(); });
    el.querySelectorAll('tr[data-rcl]').forEach(tr => {
      const l = (read.lines || []).find(x => x.id === tr.dataset.rcl); if (!l) return;
      tr.querySelectorAll('[data-rcf]').forEach(inp => inp.addEventListener('change', () => {
        l[inp.dataset.rcf] = inp.value; l.why = 'you set it'; redraw(); }));
    });
    el.querySelector('#rc-group')?.addEventListener('change', e => { group = e.target.checked; });
    el.querySelectorAll('[data-rctake]').forEach(b => b.onclick = () => {
      const k = ink.find(x => x.id === b.dataset.rctake); if (!k) return;
      if (k.key){ const sel = el.querySelector('#rc-key'); if (sel){ sel.value = k.key; } }
      if (k.who) s.by = k.who;
      toast('Taken from the handwriting'); redraw();
    });
    el.querySelectorAll('[data-rcjob]').forEach(b => b.onclick = () => {
      s.projectId = b.dataset.rcjob; save();
      audit('spend', s.id, 'job-changed-from-ink', null, {to: s.projectId});
      toast('Moved. The lines on offer are this job\'s now.'); redraw();
    });
  };
  draw();
}

/* ---------- the button that starts it ---------- */
async function rcRun(s){
  toast('Reading the receipt…');
  const read = await rcRead(s);
  if (read.err){ toast(read.err); return; }
  if (!(read.lines || []).length && !(read.ink || []).length){ toast('Nothing legible came off that photograph'); return; }
  mbCloseModal();
  rcReviewModal(s, read);
}

/* Hang it off the capture form: a receipt on the record grows a "Read it" button, and a record whose
   receipt has already been read says so, with the source, because how a number arrived is part of
   whether it can be trusted. */
if (typeof spCaptureModal === 'function'){
  const spCaptureBase_rc = spCaptureModal;
  spCaptureModal = function(o){
    const s = spCaptureBase_rc(o);
    setTimeout(() => {
      const m = document.getElementById('mbm'); if (!m || !s) return;
      const shot = m.querySelector('.sp-shot'); if (!shot || shot.querySelector('.rc-go')) return;
      const bar = document.createElement('div');
      bar.className = 'rc-go';
      bar.innerHTML = s.read
        ? `<span class="pill info">read</span><span class="small muted">${esc(s.read.source)} · ${(s.read.lines || []).length} printed lines · ${(s.read.ink || []).length} handwritten note${(s.read.ink || []).length === 1 ? '' : 's'}${Math.abs(s.read.gap || 0) > 0.02 ? ` · ${money2(s.read.gap)} unclassified` : ''}</span><span class="grow"></span><button class="btn sm" id="rc-again">Read it again</button>`
        : `<span class="small muted">A photograph of a receipt is a list of what was bought, at the price paid. Read it and every line lands on its own cost code.</span><span class="grow"></span><button class="btn sm primary" id="rc-go" ${s.receipt ? '' : 'disabled'}>Read the receipt</button>`;
      shot.parentNode.insertBefore(bar, shot.nextSibling);
      bar.querySelector('#rc-go')?.addEventListener('click', () => rcRun(s));
      bar.querySelector('#rc-again')?.addEventListener('click', () => rcRun(s));
    }, 0);
    return s;
  };
}

/* ---------- a piece of paper to look at ----------
   A drawn stand-in for the photograph Gabriel takes, with the ink on it, so the whole path — printed
   lines, handwriting, the disagreement between them — is visible offline. The real one is a camera
   capture, and `rcRead` sends that to the reader instead of parsing text. */
function rcPaper(o){
  const W = 300, top = 96, lh = 20, n = o.lines.length;
  const foot = top + n * lh + 8;
  const H = foot + 96;
  const esx = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const rows = o.lines.map((l, i) => {
    const y = top + i * lh;
    return `<text x="16" y="${y}" font-family="monospace" font-size="9" fill="#3a3a3a">${esx(l[0])}</text>`
         + (l[2] ? `<text x="16" y="${y + 9}" font-family="monospace" font-size="8" fill="#8a8a8a">${esx(l[2])}</text>` : '')
         + `<text x="284" y="${y}" font-family="monospace" font-size="9" text-anchor="end" fill="#3a3a3a">${esx(l[1])}</text>`;
  }).join('');
  const ink = (o.ink || []).map(k => {
    const t = esx(k.t);
    if (k.circle) return `<g><ellipse cx="${k.x}" cy="${k.y - 3}" rx="${k.rx || 46}" ry="12" fill="none" stroke="#1c4fd8" stroke-width="1.6" opacity=".8" transform="rotate(${k.r || -3} ${k.x} ${k.y})"/></g>`;
    return `<text x="${k.x}" y="${k.y}" font-family="'Segoe Script','Bradley Hand','Comic Sans MS',cursive" font-size="${k.s || 12}" fill="#1c4fd8" opacity="${k.o || .92}" transform="rotate(${k.r || -4} ${k.x} ${k.y})">${t}</text>`;
  }).join('');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
    <rect width="${W}" height="${H}" fill="#fffdf7" stroke="#e3ddd0"/>
    <text x="${W / 2}" y="28" font-family="monospace" font-size="12" text-anchor="middle" font-weight="700" fill="#222">${esx(o.vendor)}</text>
    <text x="${W / 2}" y="42" font-family="monospace" font-size="8" text-anchor="middle" fill="#999">${esx(o.sub || 'BROOKLYN NY')}</text>
    <text x="16" y="60" font-family="monospace" font-size="8" fill="#999">${esx(o.date || '')}</text>
    <text x="284" y="60" font-family="monospace" font-size="8" text-anchor="end" fill="#999">${esx(o.card ? 'CARD XXXX' + o.card : '')}</text>
    <line x1="14" y1="72" x2="286" y2="72" stroke="#e0dacd"/>
    <text x="16" y="86" font-family="monospace" font-size="8" fill="#aaa">QTY  DESCRIPTION</text>
    ${rows}
    <line x1="14" y1="${foot}" x2="286" y2="${foot}" stroke="#e0dacd"/>
    <text x="200" y="${foot + 16}" font-family="monospace" font-size="9" text-anchor="end" fill="#666">SUBTOTAL</text><text x="284" y="${foot + 16}" font-family="monospace" font-size="9" text-anchor="end" fill="#3a3a3a">${esx(o.subtotal)}</text>
    <text x="200" y="${foot + 30}" font-family="monospace" font-size="9" text-anchor="end" fill="#666">TAX</text><text x="284" y="${foot + 30}" font-family="monospace" font-size="9" text-anchor="end" fill="#3a3a3a">${esx(o.tax)}</text>
    <text x="200" y="${foot + 48}" font-family="monospace" font-size="11" text-anchor="end" font-weight="700" fill="#111">TOTAL</text><text x="284" y="${foot + 48}" font-family="monospace" font-size="11" text-anchor="end" font-weight="700" fill="#111">${esx(o.total)}</text>
    ${ink}</svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

/* One trip, seven things, four cost codes and two classes — the receipt the whole module exists for,
   with the crew's pen on it, including one number written wrong. */
const RC_SEED_LINES = [
  ['4    DOUGLAS FIR 2X6-12 KD', '154.44', '4 @ 38.61'],
  ['12   2X4-104 STUD SPF',      '84.00',  '12 @ 7.00'],
  ['3    CDX PLYWOOD 3/4 4X8',   '187.20', '3 @ 62.40'],
  ['1    ROMEX 12-2 NM-B 250FT', '118.44', ''],
  ['2    PEX-A 1/2IN 100FT',     '83.00',  '2 @ 41.50'],
  ['2    N95 RESPIRATOR 10PK',   '61.20',  '2 @ 30.60'],
  ['1    CONTRACTOR BAGS 42GAL', '24.98',  ''],
  ['1    DELIVERY - JOBSITE',    '85.00',  ''],
];
const RC_SEED_TEXT = `QUALITY BUILDING SUPPLY
418 3RD AVE BROOKLYN NY 11215
(718) 555-0140   STORE #118
09/05/2026  14:22  REG 3

4 DOUGLAS FIR 2X6-12 KD   4 @ 38.61      154.44
12 2X4-104 STUD SPF       12 @ 7.00       84.00
3 CDX PLYWOOD 3/4 4X8     3 @ 62.40      187.20
1 ROMEX 12-2 NM-B 250FT                  118.44
2 PEX-A 1/2IN 100FT       2 @ 41.50       83.00
2 N95 RESPIRATOR 10PK     2 @ 30.60       61.20
1 CONTRACTOR BAGS 42GAL                   24.98
1 DELIVERY - JOBSITE                      85.00
SUBTOTAL                                 798.26
TAX                                       70.85
TOTAL                                    869.11
VISA XXXX3949  AUTH 004182
THANK YOU`;

function rcSeed(){
  if (DB.__rcSeed || !DB.projects || !DB.projects.length) return;
  DB.__rcSeed = 1;
  if (typeof spNew !== 'function') return;
  const p = DB.projects.find(x => x.id === 'p121') || DB.projects[0];
  const foot = 96 + RC_SEED_LINES.length * 20 + 8;
  const s = spNew({projectId: p.id, vendor: '', by: 'Gabriel', date: iso(addDays(today(), -3)),
                   kind: 'field', status: 'draft', note: ''});
  s.receiptText = RC_SEED_TEXT;
  s.receipt = rcPaper({
    vendor: 'QUALITY BUILDING SUPPLY', sub: '418 3RD AVE BROOKLYN NY', date: '09/05/2026 14:22',
    card: '3949', lines: RC_SEED_LINES, subtotal: '798.26', tax: '70.85', total: '869.11',
    ink: [
      {t: 'Locke - front windows', x: 30, y: 20, s: 13, r: -5},
      {t: '$118.44 elec', x: 150, y: 172, s: 11, r: -3},
      {t: '86.18 office', x: 150, y: 216, s: 11, r: -3},
      {t: '795.26', x: 96, y: foot + 16, s: 12, r: -4},
      {t: 'code 06', x: 20, y: foot + 34, s: 11, r: -3},
      {t: 'Gbrl', x: 26, y: foot + 62, s: 12, r: -6, o: .55},
      {circle: true, x: 258, y: foot + 48, rx: 40, r: -3},
    ],
  });
  s.lines = [];
  audit('spend', s.id, 'receipt-attached', null, {seed: 1});
  save();
}
if (typeof spSeed === 'function'){
  const spSeedBase_rc = spSeed;
  spSeed = function(){ spSeedBase_rc(); try { rcSeed(); } catch (e){} };
}
