/*<<recon.js>>*/
/* ===================== RECONCILING TO THE STATEMENT =====================
   00:14:29. Some transactions never download, so Jeanette re-pulls the whole month as a file every
   single day. That is a person doing a computer's job, badly, forever — and it still does not answer
   the question she is actually asking, which is *have I got everything?*

   Downloading again cannot answer it. The feed is the only thing being compared to the feed. The
   statement is the independent number, and the arithmetic is a hundred years old:

       opening balance  +/- everything that moved  =  closing balance

   If our transactions do not produce the bank's closing balance, we are missing some. The difference
   says how much and how many, and it says it in one number instead of a morning.

   The second thing this gives, which the firm does not have at all: **a date the books are true up
   to.** Every account carries the last period that reconciled, and anything after that line is
   provisional. Being able to say "the books are reconciled through August" is the difference between
   numbers and opinions, and it is the whole of what "credibility" means in accounting. */

function rxInit(){
  DB.statements = DB.statements || [];
  DB.statements.forEach(s => { s.charges = +s.charges || 0; s.credits = +s.credits || 0; });
}
const rxAll = () => (DB.statements || []);
const rxFor = acctId => rxAll().filter(s => s.acctId === acctId).sort((a, b) => String(b.period).localeCompare(a.period));

/* Everything the feed holds for one account in one calendar month, split the way a statement splits
   it: money out and money in. A card statement calls those charges and payments; a bank statement
   calls them debits and credits. Same arithmetic either way. */
function rxOurs(acctId, period){
  const txns = (DB.txns || []).filter(t => t.acct === acctId && String(t.date || '').startsWith(period));
  const out = r2(txns.filter(t => t.amt < 0).reduce((a, t) => a + Math.abs(t.amt), 0));
  const inn = r2(txns.filter(t => t.amt > 0).reduce((a, t) => a + t.amt, 0));
  return {txns, charges: out, credits: inn, count: txns.length};
}

/* The reconciliation itself. `gap` is the money the statement accounts for and our records do not —
   positive means we are SHORT, which is the direction that matters, because a cost we never saw is a
   job that looks more profitable than it is. */
function rxCheck(st){
  const ours = rxOurs(st.acctId, st.period);
  const acct = (DB.accounts || []).find(a => a.id === st.acctId) || {};
  const card = acct.type === 'card';

  // what the statement says moved, and what ours says moved
  const stNet = r2((+st.charges || 0) - (+st.credits || 0));
  const ourNet = r2(ours.charges - ours.credits);
  const gap = r2(stNet - ourNet);

  // and the same thing from the balances, which is the check on the check
  const byBal = (st.opening === '' || st.opening == null || st.closing === '' || st.closing == null) ? null
    : r2(card ? (+st.opening) + stNet - (+st.closing) : (+st.opening) - stNet - (+st.closing));

  const notes = [];
  if (Math.abs(gap) > 0.02)
    notes.push(gap > 0
      ? `the statement accounts for ${money2(gap)} our records do not — that is cost the jobs have not been charged`
      : `our records hold ${money2(-gap)} the statement does not — a double import, the wrong account, or the wrong month`);
  if (st.count && ours.count !== +st.count)
    notes.push(`${st.count} lines on the statement against ${ours.count} in the feed — ${Math.abs(+st.count - ours.count)} ${ours.count < +st.count ? 'missing' : 'extra'}`);
  if (byBal != null && Math.abs(byBal) > 0.02)
    notes.push(`the statement's own opening and closing balances do not agree with its totals by ${money2(Math.abs(byBal))} — check the figures that were entered`);

  return {ours, gap, byBal, card, ok: Math.abs(gap) <= 0.02 && (!st.count || ours.count === +st.count), notes,
          stCharges: +st.charges || 0, stCredits: +st.credits || 0};
}

/* Where the missing ones probably are. Not a guess at the transactions themselves — we do not have
   them — but the days the feed is silent on inside a period it should be busy in. A bank feed that
   drops a batch drops a day, not a transaction. */
function rxSilentDays(acctId, period){
  const days = {};
  (DB.txns || []).filter(t => t.acct === acctId && String(t.date || '').startsWith(period))
    .forEach(t => { days[t.date] = (days[t.date] || 0) + 1; });
  const [y, m] = period.split('-').map(Number);
  const last = new Date(y, m, 0).getDate();
  const end = period === today().slice(0, 7) ? +today().slice(8, 10) : last;
  const out = [];
  for (let d = 1; d <= end; d++){
    const iso_ = `${period}-${String(d).padStart(2, '0')}`;
    const wd = new Date(y, m - 1, d).getDay();
    if (!days[iso_] && wd !== 0 && wd !== 6) out.push(iso_);
  }
  return out;
}

/* The line the books are true up to. An account is reconciled through the last unbroken run of
   reconciled months — a gap in the middle stops it, because a reconciled September behind an
   unreconciled August proves nothing about August. */
function rxThrough(acctId){
  const done = rxFor(acctId).filter(s => s.status === 'reconciled').map(s => s.period).sort();
  if (!done.length) return '';
  let run = done[done.length - 1];
  for (let i = done.length - 1; i > 0; i--){
    const [y, m] = done[i].split('-').map(Number);
    const prev = m === 1 ? `${y - 1}-12` : `${y}-${String(m - 1).padStart(2, '0')}`;
    if (done[i - 1] !== prev) break;
    run = done[i - 1];
  }
  return done[done.length - 1] && run ? done[done.length - 1] : '';
}
function rxBooksThrough(){
  const accts = (DB.accounts || []);
  const each = accts.map(a => ({acct: a, through: rxThrough(a.id)}));
  const any = each.filter(x => x.through);
  if (any.length < accts.length) return {through: '', each, why: `${accts.length - any.length} account${accts.length - any.length === 1 ? ' has' : 's have'} never been reconciled`};
  const oldest = any.map(x => x.through).sort()[0];
  return {through: oldest, each, why: `every account is reconciled through ${oldest}`};
}
const rxMonthName = p => { const [y, m] = String(p || '').split('-'); return m ? `${['January','February','March','April','May','June','July','August','September','October','November','December'][+m - 1]} ${y}` : p; };

/* ---------- entering one ----------
   Four numbers off the front page of the statement. Not a file to import and not a screen to scrape:
   the whole point is that this is the INDEPENDENT record, so it is typed from the paper. */
function rxModal(st){
  rxInit();
  const accts = DB.accounts || [];
  const s = st || {id: uid('st'), acctId: (accts[0] || {}).id, period: (() => { const d = new Date(); d.setMonth(d.getMonth() - 1); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`; })(),
                   opening: '', closing: '', charges: '', credits: '', count: '', note: '', status: 'open'};
  const draw = () => {
    const acct = accts.find(a => a.id === s.acctId) || {};
    const card = acct.type === 'card';
    const chk = (s.charges !== '' || s.credits !== '') ? rxCheck(s) : null;
    mbModal(st ? `${esc(acct.name || 'Statement')} — ${esc(rxMonthName(s.period))}` : 'Reconcile a statement', `
      <div class="grid3">
        <div class="f"><label>Account</label><select data-f="acctId">${accts.map(a => `<option value="${a.id}" ${s.acctId === a.id ? 'selected' : ''}>${esc(a.name)}${a.last4 ? ' ····' + a.last4 : ''}</option>`).join('')}</select></div>
        <div class="f"><label>Statement month</label><input type="month" data-f="period" value="${esc(s.period)}"></div>
        <div class="f"><label>Lines on the statement</label><input type="number" data-f="count" value="${s.count}" placeholder="optional"></div>
        <div class="f"><label>Opening balance</label><input type="number" step="0.01" data-f="opening" value="${s.opening}"></div>
        <div class="f"><label>${card ? 'Charges' : 'Money out'}</label><input type="number" step="0.01" data-f="charges" value="${s.charges}"></div>
        <div class="f"><label>${card ? 'Payments & credits' : 'Money in'}</label><input type="number" step="0.01" data-f="credits" value="${s.credits}"></div>
        <div class="f"><label>Closing balance</label><input type="number" step="0.01" data-f="closing" value="${s.closing}"></div>
        <div class="f" style="grid-column:span 2"><label>Note</label><input data-f="note" value="${esc(s.note || '')}" placeholder="Statement dated 9/2, downloaded as PDF"></div>
      </div>
      ${chk ? `<div class="rx-out ${chk.ok ? 'ok' : 'bad'}">
        <div class="rx-cmp">
          <div><span>The statement says</span><b>${money2(chk.stCharges)} out · ${money2(chk.stCredits)} in${s.count ? ` · ${s.count} lines` : ''}</b></div>
          <div><span>Our records hold</span><b>${money2(chk.ours.charges)} out · ${money2(chk.ours.credits)} in · ${chk.ours.count} lines</b></div>
        </div>
        ${chk.ok ? `<div class="ok"><b>It reconciles.</b> Every dollar on the statement is in the books, and every line in the books is on the statement.</div>`
                 : `<div class="bad"><b>${money2(Math.abs(chk.gap))} apart.</b> ${esc(chk.notes.join('. '))}.</div>
                    ${chk.gap > 0 ? `<div class="small">Days in ${esc(rxMonthName(s.period))} the feed is silent on: ${rxSilentDays(s.acctId, s.period).map(d => d.slice(8)).join(', ') || 'none — so the missing lines are on days that did download'}</div>` : ''}`}
      </div>` : ''}
      <p class="small muted" style="margin:10px 0 0">Four numbers off the front page. The statement is worth typing precisely because it is the one record we did not produce — checking the feed against the feed proves nothing.</p>`,
      {submit: 'Save', wide: true,
       onSubmit: f => {
         Object.assign(s, f);
         ['opening', 'closing', 'charges', 'credits'].forEach(k => { if (s[k] !== '') s[k] = +s[k]; });
         if (!st) DB.statements.push(s);
         audit('statement', s.id, st ? 'updated' : 'entered', null, {acct: s.acctId, period: s.period, gap: rxCheck(s).gap});
         save(); renderSpend(); toast('Statement saved');
       }});
    if (typeof procWide === 'function') procWide(900);
    const m = document.getElementById('mbm'); if (!m) return;
    /* Closing the month is a different act from saving the numbers, so it is a different button, and
       it only exists once the numbers actually tie. A "reconciled" flag you can set on a month that
       does not balance is worse than no flag at all. */
    if (chk && chk.ok && s.status !== 'reconciled'){
      const ft = m.querySelector('.mbm-ft');
      if (ft) ft.insertAdjacentHTML('afterbegin', `<button class="btn primary" id="rx-done">Mark ${esc(rxMonthName(s.period))} reconciled</button>`);
    }
    m.querySelectorAll('[data-f]').forEach(inp => inp.addEventListener('change', () => {
      s[inp.dataset.f] = ['opening', 'closing', 'charges', 'credits'].includes(inp.dataset.f) && inp.value !== '' ? +inp.value : inp.value;
      mbCloseModal(); draw();
    }));
    m.querySelector('#rx-done')?.addEventListener('click', () => {
      if (!st) DB.statements.push(s);
      s.status = 'reconciled'; s.reconciledBy = currentUser()?.name || DB.me || ''; s.reconciledAt = today();
      audit('statement', s.id, 'reconciled', null, {acct: s.acctId, period: s.period, by: s.reconciledBy});
      log(`${rxMonthName(s.period)} reconciled on ${(DB.accounts.find(a => a.id === s.acctId) || {}).name} by ${s.reconciledBy}`);
      save(); mbCloseModal(); renderSpend();
      toast(`${rxMonthName(s.period)} is closed — the books are true to that line`);
    });
  };
  draw();
}

/* ---------- the screen ---------- */
function rxPaneHtml(){
  rxInit();
  const books = rxBooksThrough();
  const open = rxAll().filter(s => s.status !== 'reconciled');
  const gaps = open.map(s => ({s, chk: rxCheck(s)})).filter(x => !x.chk.ok);
  const short = r2(gaps.reduce((a, x) => a + Math.max(0, x.chk.gap), 0));
  const stat = (v, s, cls) => `<div class="sel-stat"><b class="${cls || ''}">${v}</b><span>${s}</span></div>`;

  const row = st => {
    const chk = rxCheck(st), a = (DB.accounts || []).find(x => x.id === st.acctId) || {};
    return `<tr data-rxopen="${st.id}">
      <td><b>${esc(a.name || 'account')}</b><div class="small muted">${esc(rxMonthName(st.period))}</div></td>
      <td class="n">${money2(chk.stCharges)}<div class="small muted">${st.count ? st.count + ' lines' : ''}</div></td>
      <td class="n">${money2(chk.ours.charges)}<div class="small muted">${chk.ours.count} lines</div></td>
      <td>${chk.ok
        ? `<span class="pill ok">reconciles</span>`
        : `<span class="pill bad">${money2(Math.abs(chk.gap))} apart</span><div class="small">${esc(chk.notes[0] || '')}</div>`}</td>
      <td>${st.status === 'reconciled'
        ? `<span class="small ok">closed by ${esc(st.reconciledBy || '')} ${esc(st.reconciledAt || '')}</span>`
        : `<span class="small muted">open</span>`}</td></tr>`;
  };

  const acctRow = x => `<tr>
    <td><b>${esc(x.acct.name)}</b>${x.acct.last4 ? ` <span class="small muted">····${esc(x.acct.last4)}</span>` : ''}</td>
    <td>${x.through ? `<span class="ok">through ${esc(rxMonthName(x.through))}</span>` : '<span class="bad">never reconciled</span>'}</td>
    <td class="n">${(() => { const p = rxFor(x.acct.id)[0]; return p ? esc(rxMonthName(p.period)) : '—'; })()}</td></tr>`;

  return `
  <div class="sel-stats">
    ${stat(books.through ? rxMonthName(books.through) : '—', 'the books are true through', books.through ? 'ok' : 'bad')}
    ${stat(open.length, `statement${open.length === 1 ? '' : 's'} still open`)}
    ${stat(gaps.length ? money2(short) : '$0', 'the bank accounts for and we do not', short ? 'bad' : 'ok')}
    ${stat(rxAll().filter(s => s.status === 'reconciled').length, 'months closed')}
  </div>

  <div class="rx-line ${books.through ? '' : 'bad'}">
    <b>${books.through ? `Reconciled through ${esc(rxMonthName(books.through))}.` : 'Nothing has been reconciled yet.'}</b>
    <span class="small">${esc(books.why)}. Everything after that line is provisional — which is a fact worth being able to state, not an admission.</span>
  </div>

  <div class="row" style="gap:8px;margin:14px 0 8px"><h3 style="margin:0">Statements</h3>
    <span class="small muted">Four numbers off the front page, against what the feed brought in.</span>
    <span class="grow"></span><button class="btn sm primary" id="rx-add">Reconcile a month</button></div>
  <table class="t"><thead><tr><th>Account</th><th style="width:150px">The statement</th><th style="width:150px">Our records</th><th>Does it tie</th><th style="width:200px"></th></tr></thead>
    <tbody>${rxAll().sort((a, b) => String(b.period).localeCompare(a.period)).map(row).join('')
      || `<tr><td colspan="5" class="muted small">No statements entered. Until one is, "have we got everything?" can only be answered by downloading the month again and hoping.</td></tr>`}</tbody></table>

  <h3 style="margin:18px 0 8px">Where each account stands</h3>
  <table class="t"><thead><tr><th>Account</th><th style="width:260px">Reconciled</th><th style="width:180px">Last statement entered</th></tr></thead>
    <tbody>${books.each.map(acctRow).join('')}</tbody></table>`;
}
function rxWire(root){
  root.querySelector('#rx-add')?.addEventListener('click', () => rxModal(null));
  root.querySelectorAll('[data-rxopen]').forEach(tr => tr.addEventListener('click', () => {
    const st = rxAll().find(s => s.id === tr.dataset.rxopen); if (st) rxModal(st);
  }));
}

if (typeof SP_TABS !== 'undefined') SP_TABS.push(['recon', 'Reconciled through']);
if (typeof spPane === 'function'){
  const spPaneBase_rx = spPane;
  spPane = function(ctx){ return spTab === 'recon' ? rxPaneHtml() : spPaneBase_rx(ctx); };
}
if (typeof wireSpend === 'function'){
  const wireSpendBase_rx = wireSpend;
  wireSpend = function(root){ wireSpendBase_rx(root); if (spTab === 'recon') try { rxWire(root); } catch (e){ console.error('recon', e); } };
}

/* Two months on the main card account: one that ties, and one where the feed is $1,284 short — which
   is the shape of the problem being described at 00:14:29, seen from the statement instead of from
   the download. */
function rxSeed(){
  if (DB.__rxSeed) return; DB.__rxSeed = 1;
  rxInit();
  const card = (DB.accounts || []).find(a => a.type === 'card'); if (!card) return;
  const per = p => { const d = new Date(); d.setMonth(d.getMonth() - p); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`; };
  const mk = (period, extra) => {
    const o = rxOurs(card.id, period);
    const s = {id: uid('st'), acctId: card.id, period, opening: 0, closing: 0,
               charges: r2(o.charges + (extra || 0)), credits: o.credits,
               count: o.count + (extra ? 2 : 0), note: 'Entered from the PDF statement', status: extra ? 'open' : 'reconciled'};
    s.closing = r2(s.opening + s.charges - s.credits);
    if (!extra){ s.reconciledBy = 'Jeanette'; s.reconciledAt = iso(addDays(today(), -20)); }
    DB.statements.push(s);
  };
  mk(per(2), 0);
  mk(per(1), 1284.36);
  save();
}
/* Seeded last of everything, deliberately. A statement is a fixed record of a month that has already
   happened; deriving one from a transaction list that later grows produces a "reconciliation" whose
   difference moves on its own, which is the one thing a reconciliation may never do. */
if (typeof spSeed === 'function'){
  const spSeedBase_rx = spSeed;
  spSeed = function(){ spSeedBase_rx(); try { rxSeed(); } catch (e){} };
}
