/*<<route.js>>*/
/* ===================== WHO HAS TO SAY YES =====================
   Today every payment goes to one person, because `ceoAbove` is 0 and always has been. That is not an
   approval policy, it is the absence of one: the owner signs off a $40 box of screws with the same
   attention as a $38,000 millwork deposit, which means neither gets any.

   Now that a charge knows its amount, its job, its cost class, its vendor, its purchase order and —
   since the card register — the person who spent it, approval can be a rule the firm decides once
   rather than a habit somebody performs daily.

   Two things this is for, and they are different:

     THRESHOLD    small things stop bothering the owner, so the large ones get read.
     CONTROL      some things go to the owner no matter how small, because size is not the risk.

   The controls are the point. A bill with no purchase order behind it is somebody buying without
   asking. A vendor's first invoice is a vendor nobody has checked. **And a vendor whose bank details
   changed last week is the single most common way construction firms are defrauded** — the field is
   already on the vendor record in this database and nothing has ever read it. */

const RT_ROLES = [['coord', 'Coordinator'], ['pm', 'Project manager'], ['owner', 'Owner']];
const RT_RANK = {coord: 1, pm: 2, owner: 3};
const RT_DEFAULT = {
  ladder: [[500, 'coord'], [5000, 'pm'], [Infinity, 'owner']],
  controls: {noPO: true, newVendor: true, bankChanged: 60, overPO: true, noLine: false, weekend: false},
  selfApprove: false,
};
const rtCfg = () => { DB.company.routing = Object.assign({}, RT_DEFAULT, DB.company.routing || {}); return DB.company.routing; };

/* What a thing being approved actually is, whatever table it lives in. */
function rtSubject(o){
  if (!o) return null;
  if (o.lines && o.number !== undefined && o.vendor !== undefined && !o.kind)
    return {kind: 'bill', amount: billTotal(o), vendor: o.vendor, poId: o.poId, projectId: o.projectId,
            createdBy: o.createdBy, lines: o.lines, date: o.date, ref: o};
  if (o.kind && o.lines)          // a spend record
    return {kind: 'spend', amount: spTotal(o), vendor: o.vendor, poId: o.poId, projectId: o.projectId,
            createdBy: o.by, lines: o.lines, date: o.date, ref: o};
  if (o.total !== undefined && o.runId !== undefined)
    return {kind: 'payroll', amount: +o.total || 0, vendor: '', poId: '', projectId: '',
            createdBy: o.createdBy, lines: [], date: o.date, ref: o};
  return {kind: 'other', amount: +o.amount || +o.total || 0, vendor: o.vendor || '', poId: o.poId || '',
          projectId: o.projectId || '', createdBy: o.createdBy || '', lines: o.lines || [], date: o.date, ref: o};
}

/* The answer: who must approve, in order, and — the part that makes it usable — WHY each of them.
   An approval screen that says "needs the owner" teaches nothing. One that says "needs the owner:
   Window Works changed its bank details 12 days ago" is the control doing its job. */
function rtFor(o){
  const cfg = rtCfg(), s = rtSubject(o);
  if (!s) return {need: ['owner'], why: [], top: 'owner'};
  const why = [];

  let byAmount = 'owner';
  for (const [cap, r] of cfg.ladder){ if (s.amount < cap){ byAmount = r; break; } }
  why.push({role: byAmount, kind: 'amount',
            msg: `${money(s.amount)} — ${byAmount === 'coord' ? 'inside the coordinator\'s limit' : byAmount === 'pm' ? 'the project manager signs to ' + money(cfg.ladder[1][0]) : 'above ' + money(cfg.ladder[1][0]) + ', so the owner sees it'}`});

  const c = cfg.controls;
  if (c.noPO && s.kind === 'bill' && !s.poId)
    why.push({role: 'owner', kind: 'no-po', msg: 'No purchase order behind it — somebody bought without asking'});

  const vend = (DB.vendors || []).find(v => v.name && s.vendor && v.name.toLowerCase() === String(s.vendor).toLowerCase());
  if (c.newVendor && s.vendor){
    const prior = (DB.bills || []).filter(b => b.id !== (s.ref && s.ref.id) && b.vendor && b.vendor.toLowerCase() === String(s.vendor).toLowerCase()
                                          && ['paid', 'approved', 'verified'].includes(b.status));
    if (!prior.length) why.push({role: 'owner', kind: 'new-vendor', msg: `First payment to ${s.vendor} — nobody has been paid under this name before`});
  }
  if (c.bankChanged && vend && vend.bankChangedAt){
    const days = Math.round((new Date(s.date || today()) - new Date(vend.bankChangedAt)) / 86400000);
    if (days >= 0 && days <= c.bankChanged)
      why.push({role: 'owner', kind: 'bank-changed', hard: true,
                msg: `${vend.name} changed its bank details ${days} day${days === 1 ? '' : 's'} ago — confirm by phone on a number you already had, not one on the invoice`});
  }
  if (c.overPO && s.poId){
    const po = (DB.pos || []).find(p => p.id === s.poId);
    if (po){
      const t = poTotal(po).total;
      const others = (DB.bills || []).filter(b => b.poId === po.id && b.status !== 'void' && b.id !== (s.ref && s.ref.id));
      const sofar = r2(others.reduce((a, b) => a + billTotal(b), 0) + s.amount);
      if (sofar > t + 1) why.push({role: 'owner', kind: 'over-po', msg: `Takes ${po.number} to ${money(sofar)} on a ${money(t)} order`});
    }
  }
  if (c.noLine && (s.lines || []).length && !s.lines.some(l => l.line || l.key))
    why.push({role: 'pm', kind: 'no-line', msg: 'Not tied to a line on any estimate, so it cannot reach a job'});

  const top = why.reduce((a, w) => RT_RANK[w.role] > RT_RANK[a] ? w.role : a, 'coord');

  /* Who actually has to sign. Two rules, and the second is the one that makes the first work.

     Approval is a LADDER: everything from the bottom rung up to whichever reason reaches highest, so
     a $38,000 deposit collects the coordinator, the PM and the owner rather than jumping to the owner
     alone — which is how the firm's own recorded approvals already read.

     And THE RUNG YOU SIT ON IS SATISFIED BY YOUR RAISING IT. The coordinator who enters a $120 bill
     has not approved it, and cannot: nobody approves their own. Without this the small payments the
     ladder was built to stop escalating would deadlock on a rung only their author occupies, and the
     policy would be quietly abandoned within a week. So the chain starts one rung above whoever
     raised it, and something above them always has to say yes. */
  const raiser = rtRoleOf(s.createdBy);
  const all = RT_ROLES.map(r => r[0]);
  let need = all.filter(r => RT_RANK[r] <= RT_RANK[top] && RT_RANK[r] > RT_RANK[raiser]);
  if (!need.length) need = all.filter(r => RT_RANK[r] === RT_RANK[raiser] + 1);
  if (!need.length) need = ['owner'];
  return {need, why, top, byAmount, raiser, amount: s.amount, subject: s};
}
/* The role a person holds, from the user list the firm already keeps. Anybody unknown is treated as a
   coordinator, which is the cautious answer: it means the approval must come from above them. */
function rtRoleOf(name){
  if (!name) return 'coord';
  const u = (DB.users || []).find(x => (x.name || '').toLowerCase() === String(name).toLowerCase());
  const r = u && u.role;
  return RT_RANK[r] ? r : 'coord';
}

/* Where a thing has got to, and whose turn it is. Read from the approvals already recorded on it,
   so nothing new has to be stored and old records still answer. */
function rtStep(o){
  const r = rtFor(o), s = rtSubject(o);
  const done = new Set(((o.approvals) || []).filter(a => /approv|recommend/i.test(a.action || '')).map(a => a.role));
  const next = r.need.find(role_ => !done.has(role_));
  return Object.assign(r, {done: [...done], next: next || '', complete: !next});
}
/* Segregation of duties, which the firm already half-has: the person who raised it cannot be the
   person who approves it. Here that rule is stated rather than implied, and it applies at every rung
   rather than only at the owner's. */
function rtCan(o, who, roleOf){
  const st = rtStep(o), s = rtSubject(o);
  const me = String(who || currentUser()?.name || DB.me || '').toLowerCase();
  const myRole = roleOf || role();
  if (st.complete) return {ok: false, why: 'it has every approval it needs'};
  if (st.next !== myRole) return {ok: false, why: `it is with the ${(RT_ROLES.find(r => r[0] === st.next) || [, st.next])[1].toLowerCase()}`};
  if (!rtCfg().selfApprove && s.createdBy && me && String(s.createdBy).toLowerCase() === me)
    return {ok: false, why: 'you raised it — somebody else approves it'};
  return {ok: true, why: ''};
}
function rtApprove(o, note){
  const can = rtCan(o); if (!can.ok){ toast(can.why); return false; }
  const st = rtStep(o);
  o.approvals = [...(o.approvals || []), {t: nowStamp(), by: currentUser()?.name || DB.me || '', role: st.next,
    action: st.next === 'owner' ? 'approved for payment by Owner' : st.next === 'pm' ? 'recommended by PM' : 'approved by coordinator',
    note: note || ''}];
  const after = rtStep(o);
  if (after.complete) o.status = 'approved';
  else if (st.next === 'pm') o.status = 'pm-approved';
  audit(o.number !== undefined ? 'bill' : 'spend', o.id, 'approved-step', null, {role: st.next, complete: after.complete});
  save();
  return true;
}

/* ---------- the policy, and the screen ---------- */
function rtPolicyModal(){
  const cfg = rtCfg();
  const c = cfg.controls;
  mbModal('Who has to say yes', `
    <p class="small muted" style="margin:0 0 10px">Two separate things. The ladder is about size. The controls are about risk, and they send a payment to the owner however small it is.</p>
    <h4 style="margin:0 0 6px">The ladder</h4>
    <div class="grid3">
      <div class="f"><label>The coordinator signs up to</label><input type="number" step="50" data-f="l0" value="${cfg.ladder[0][0]}"></div>
      <div class="f"><label>The project manager up to</label><input type="number" step="500" data-f="l1" value="${cfg.ladder[1][0]}"></div>
      <div class="f"><label>Above that</label><input value="The owner" disabled></div>
    </div>
    <h4 style="margin:14px 0 6px">The controls</h4>
    <label class="cl-chk"><input type="checkbox" data-f="noPO" ${c.noPO ? 'checked' : ''}><span><b>No purchase order behind it.</b> Somebody bought without asking.</span></label>
    <label class="cl-chk"><input type="checkbox" data-f="newVendor" ${c.newVendor ? 'checked' : ''}><span><b>The first payment to a vendor.</b> Nobody has been paid under this name before.</span></label>
    <label class="cl-chk"><input type="checkbox" data-f="bankChanged" ${c.bankChanged ? 'checked' : ''}><span><b>The vendor changed its bank details recently.</b> This is how construction firms are defrauded, and the date is already on the vendor record.</span></label>
    <label class="cl-chk"><input type="checkbox" data-f="overPO" ${c.overPO ? 'checked' : ''}><span><b>It takes a purchase order over what was ordered.</b> That is a change order, not an approval.</span></label>
    <label class="cl-chk"><input type="checkbox" data-f="noLine" ${c.noLine ? 'checked' : ''}><span><b>It is not tied to a line on any estimate.</b> The cost cannot reach a job.</span></label>
    <h4 style="margin:14px 0 6px">And one rule that is not negotiable by default</h4>
    <label class="cl-chk"><input type="checkbox" data-f="selfApprove" ${cfg.selfApprove ? 'checked' : ''}><span>Allow somebody to approve what they raised themselves. <span class="muted">Off. Turning it on removes the only separation of duties the firm has.</span></span></label>`,
    {submit: 'Save the policy', wide: true, onSubmit: f => {
      cfg.ladder = [[+f.l0 || 0, 'coord'], [+f.l1 || 0, 'pm'], [Infinity, 'owner']];
      cfg.controls = {noPO: f.noPO, newVendor: f.newVendor, bankChanged: f.bankChanged ? (c.bankChanged || 60) : 0,
                      overPO: f.overPO, noLine: f.noLine, weekend: false};
      cfg.selfApprove = f.selfApprove;
      audit('company', 'routing', 'policy-changed', null, {ladder: [f.l0, f.l1], controls: cfg.controls});
      save(); renderSpend(); toast('Policy saved — it applies to everything waiting');
    }});
  if (typeof procWide === 'function') procWide(760);
}

const rtWaiting = () => (DB.bills || []).filter(b => ['draft', 'submitted', 'pm-approved'].includes(b.status))
  .concat((DB.spend || []).filter(s => s.status === 'submitted'));

function rtPaneHtml(){
  const cfg = rtCfg();
  const rows = rtWaiting().map(o => ({o, st: rtStep(o), s: rtSubject(o)}))
    .sort((a, b) => (b.st.why.some(w => w.hard) ? 1 : 0) - (a.st.why.some(w => w.hard) ? 1 : 0) || b.s.amount - a.s.amount);
  const mine = rows.filter(r => rtCan(r.o).ok);
  const hard = rows.filter(r => r.st.why.some(w => w.hard));
  const stat = (v, s, cls) => `<div class="sel-stat"><b class="${cls || ''}">${v}</b><span>${s}</span></div>`;
  const roleName = k => (RT_ROLES.find(r => r[0] === k) || [, k])[1];

  const row = ({o, st, s}) => `<tr>
    <td><b>${esc(s.vendor || (s.kind === 'payroll' ? 'Payroll' : 'Spend'))}</b>
        <div class="small muted">${esc(o.number || o.note || '')} · raised by ${esc(s.createdBy || '—')}</div></td>
    <td class="n"><b>${money(s.amount)}</b></td>
    <td>${st.why.map(w => `<div class="small ${w.hard ? 'bad' : w.kind === 'amount' ? 'muted' : 'warn'}">${w.kind === 'amount' ? '' : `<b>${esc(roleName(w.role))}:</b> `}${esc(w.msg)}</div>`).join('')}</td>
    <td>${st.complete ? '<span class="pill ok">fully approved</span>'
        : `<span class="pill ${st.next === 'owner' ? 'warn' : 'info'}">with the ${esc(roleName(st.next).toLowerCase())}</span>
           <div class="small muted">${st.need.map(n => (st.done.includes(n) ? '✓ ' : '') + roleName(n)).join(' → ')}</div>`}</td>
    <td>${rtCan(o).ok ? `<button class="btn sm primary" data-rtok="${o.id}">Approve</button>`
        : `<span class="small muted">${esc(rtCan(o).why)}</span>`}</td></tr>`;

  return `
  <div class="sel-stats">
    ${stat(rows.length, 'waiting on somebody')}
    ${stat(mine.length, 'waiting on you', mine.length ? 'warn' : '')}
    ${stat(hard.length, 'stopped by a control, not by size', hard.length ? 'bad' : 'ok')}
    ${stat(money(cfg.ladder[1][0]), 'above which the owner sees it')}
  </div>
  ${hard.length ? `<div class="cd-flags"><b>${hard.length} payment${hard.length === 1 ? '' : 's'} held by a control</b>
    ${hard.map(r => `<div class="small">${esc(r.s.vendor)} ${money(r.s.amount)} — ${esc(r.st.why.find(w => w.hard).msg)}</div>`).join('')}</div>` : ''}

  <div class="row" style="gap:8px;margin:12px 0 8px"><h3 style="margin:0">Waiting for a yes</h3>
    <span class="small muted">The ladder is about size; the controls are about risk and ignore size entirely.</span>
    <span class="grow"></span><button class="btn sm" id="rt-policy">The policy</button></div>
  <table class="t"><thead><tr><th>What</th><th style="width:110px">Amount</th><th>Why it needs who it needs</th><th style="width:200px">Where it is</th><th style="width:150px"></th></tr></thead>
    <tbody>${rows.map(row).join('') || `<tr><td colspan="5" class="muted small">Nothing waiting.</td></tr>`}</tbody></table>
  <p class="small muted" style="margin:10px 0 0">Nobody approves what they raised themselves. That is the only separation of duties the firm has, and it is on by default.</p>`;
}
function rtWire(root){
  root.querySelector('#rt-policy')?.addEventListener('click', () => rtPolicyModal());
  root.querySelectorAll('[data-rtok]').forEach(b => b.onclick = () => {
    const o = rtWaiting().find(x => x.id === b.dataset.rtok); if (!o) return;
    const st = rtStep(o), hard = st.why.find(w => w.hard);
    if (hard){
      mbModal('Before you approve this', `<p class="bad"><b>${esc(hard.msg)}</b></p>
        <p class="small muted">Approving is not the problem; approving without checking is. Say what you did, and it goes on the record beside the payment.</p>
        <div class="f"><label>What you checked</label><input data-f="note" placeholder="Called Marco on the number from the 2024 contract — details confirmed"></div>`,
        {submit: 'I checked it — approve', onSubmit: f => {
          if (!f.note){ toast('Say what you checked'); return false; }
          if (rtApprove(o, f.note)){ renderSpend(); toast('Approved, with what you checked on the record'); }
        }});
      return;
    }
    if (rtApprove(o)) { renderSpend(); toast(rtStep(o).complete ? 'Fully approved' : `Passed to the ${(RT_ROLES.find(r => r[0] === rtStep(o).next) || [, ''])[1].toLowerCase()}`); }
  });
}

if (typeof SP_TABS !== 'undefined') SP_TABS.push(['route', 'Who has to say yes']);
if (typeof spPane === 'function'){
  const spPaneBase_rt = spPane;
  spPane = function(ctx){ return spTab === 'route' ? rtPaneHtml() : spPaneBase_rt(ctx); };
}
if (typeof wireSpend === 'function'){
  const wireSpendBase_rt = wireSpend;
  wireSpend = function(root){ wireSpendBase_rt(root); if (spTab === 'route') try { rtWire(root); } catch (e){ console.error('route', e); } };
}
/*<</route.js>>*/

/*<<terms.js>>*/
/* ===================== WHAT THE TERMS ARE WORTH =====================
   "2/10 net 30" is printed on half the invoices this firm receives and has never been read by anything.
   It means: pay within ten days and take 2% off, otherwise the whole amount is due in thirty.

   Two percent for paying twenty days early is not a discount, it is a return. Twenty days is a
   fifty-fifth of a year, so 2% over that period annualises to about 37% — better than any use the
   firm has for that cash, and it is available on the calendar, for free, by paying a bill on Thursday
   instead of the following month. Missing it is not neutral. It is a 37% cost of borrowing from a
   vendor who was offering to lend for nothing.

   The other half of the same calendar is the one the firm already feels: what is late, what is nearly
   late, and what a payment run on any given day would actually cost. Both come from one field nobody
   has ever parsed, and the bill ingest now reads it off the invoice automatically. */

/* 2/10 NET 30 · 2%10 NET 30 · 1.5/15 n45 · NET 30 · DUE ON RECEIPT · COD */
function tmParse(text){
  const t = String(text || '').toUpperCase().replace(/\s+/g, ' ').trim();
  if (!t) return null;
  if (/DUE ON RECEIPT|^COD\b|CASH ON DELIVERY/.test(t)) return {disc: 0, discDays: 0, net: 0, label: 'due on receipt'};
  const d = t.match(/(\d+(?:\.\d+)?)\s*[%\/]\s*(\d+)/);
  const n = t.match(/(?:NET|N)\s*[- ]?\s*(\d+)/);
  if (!d && !n) return null;
  return {disc: d ? +d[1] : 0, discDays: d ? +d[2] : 0, net: n ? +n[1] : (d ? +d[2] : 0),
          label: t.slice(0, 24)};
}
/* The number that makes it a decision rather than a nicety. Paying `net - discDays` days early to
   save `disc`% is an annual rate, and it is almost always enormous. */
function tmAnnual(tm){
  if (!tm || !tm.disc || tm.net <= tm.discDays) return 0;
  const days = tm.net - tm.discDays;
  return Math.round((tm.disc / (100 - tm.disc)) * (365 / days) * 100);
}
const tmOf = bill => tmParse((bill.terms || '') || ((bill.notes || '').match(/terms\s+([^·]+)/i) || [])[1] || '')
  || (bill.due && bill.date ? {disc: 0, discDays: 0, net: Math.max(0, Math.round((new Date(bill.due) - new Date(bill.date)) / 86400000)), label: 'from the dates'} : null);

/* One bill, on the calendar. */
function tmRow(b){
  const tm = tmOf(b); if (!tm) return null;
  const amt = billTotal(b);
  const base = b.date || today();
  const discBy = tm.disc ? iso(addDays(base, tm.discDays)) : '';
  const dueBy = b.due || iso(addDays(base, tm.net));
  const daysToDisc = discBy ? Math.round((new Date(discBy) - new Date(today())) / 86400000) : null;
  const daysToDue = Math.round((new Date(dueBy) - new Date(today())) / 86400000);
  const save = tm.disc ? r2(amt * tm.disc / 100) : 0;
  return {bill: b, tm, amt, discBy, dueBy, daysToDisc, daysToDue, save, annual: tmAnnual(tm),
          state: daysToDue < 0 ? 'late' : (daysToDisc != null && daysToDisc >= 0) ? 'discount'
               : daysToDue <= 7 ? 'soon' : 'later',
          missed: !!(tm.disc && daysToDisc != null && daysToDisc < 0 && !['paid'].includes(b.status))};
}
const TM_PAYABLE = ['approved', 'pm-approved', 'submitted'];
function tmRows(){
  return (DB.bills || []).filter(b => b.status !== 'void' && b.status !== 'paid')
    .map(tmRow).filter(Boolean)
    .sort((a, b) => (b.save - a.save) || (a.dueBy || '').localeCompare(b.dueBy || ''));
}
/* What a run on a given day costs, and what it saves. The reason to look at a date rather than a list:
   paying everything whose discount expires this week is one transfer, not eleven decisions. */
function tmRun(by){
  const day = by || iso(addDays(today(), 3));
  const take = tmRows().filter(r => r.discBy && r.discBy >= today() && r.discBy <= day && TM_PAYABLE.includes(r.bill.status));
  const must = tmRows().filter(r => !take.includes(r) && r.dueBy <= day && TM_PAYABLE.includes(r.bill.status));
  return {day, take, must,
          cost: r2(take.reduce((a, r) => a + r.amt - r.save, 0) + must.reduce((a, r) => a + r.amt, 0)),
          save: r2(take.reduce((a, r) => a + r.save, 0))};
}
/* What has already been given away. Not a scold — a number, because the only way anybody believes
   this is worth doing is seeing what a year of not doing it came to. */
function tmForgone(){
  const paid = (DB.bills || []).filter(b => b.status === 'paid' && b.paidAt);
  let n = 0, amt = 0;
  paid.forEach(b => { const tm = tmOf(b); if (!tm || !tm.disc) return;
    const by = iso(addDays(b.date || today(), tm.discDays));
    if (b.paidAt > by){ n++; amt = r2(amt + billTotal(b) * tm.disc / 100); } });
  return {n, amt};
}

function tmPaneHtml(){
  const rows = tmRows();
  const run = tmRun();
  const late = rows.filter(r => r.state === 'late');
  const disc = rows.filter(r => r.state === 'discount');
  const missed = rows.filter(r => r.missed);
  const gone = tmForgone();
  const stat = (v, s, cls) => `<div class="sel-stat"><b class="${cls || ''}">${v}</b><span>${s}</span></div>`;
  const when = n => n == null ? '' : n < 0 ? `${-n} day${-n === 1 ? '' : 's'} ago` : n === 0 ? 'today' : `in ${n} day${n === 1 ? '' : 's'}`;

  const row = r => `<tr>
    <td><b>${esc(r.bill.vendor)}</b> <span class="small muted">${esc(r.bill.number || '')}</span>
        <div class="small muted">${esc(r.tm.label)}${r.bill.poId ? ' · ' + esc((DB.pos.find(p => p.id === r.bill.poId) || {}).number || '') : ''}</div></td>
    <td class="n"><b>${money(r.amt)}</b></td>
    <td>${r.tm.disc
      ? `<b class="${r.state === 'discount' ? 'ok' : r.missed ? 'bad' : ''}">${money(r.save)}</b>
         <div class="small ${r.state === 'discount' ? '' : 'muted'}">${r.missed ? `the window closed ${when(r.daysToDisc)}` : `pay by ${esc(r.discBy)} — ${when(r.daysToDisc)}`}</div>`
      : '<span class="muted small">no discount offered</span>'}</td>
    <td>${r.tm.disc ? `<span class="small ${r.annual >= 15 ? 'ok' : 'muted'}">${r.annual}% a year</span>` : ''}</td>
    <td><span class="pill ${r.state === 'late' ? 'bad' : r.state === 'discount' ? 'ok' : r.state === 'soon' ? 'warn' : 'neutral'}">${r.state === 'late' ? `${-r.daysToDue} days late` : when(r.daysToDue)}</span>
        <div class="small muted">due ${esc(r.dueBy)}</div></td>
    <td>${esc(r.bill.status)}</td></tr>`;

  return `
  <div class="sel-stats">
    ${stat(disc.length ? money(r2(disc.reduce((a, r) => a + r.save, 0))) : '$0', 'still available by paying early', disc.length ? 'ok' : '')}
    ${stat(missed.length ? money(r2(missed.reduce((a, r) => a + r.save, 0))) : '$0', `given away on ${missed.length} unpaid bill${missed.length === 1 ? '' : 's'}`, missed.length ? 'bad' : '')}
    ${stat(late.length, `already late${late.length ? ' — ' + money(r2(late.reduce((a, r) => a + r.amt, 0))) : ''}`, late.length ? 'bad' : 'ok')}
    ${stat(gone.n ? money(gone.amt) : '$0', `handed back on ${gone.n} bill${gone.n === 1 ? '' : 's'} already paid`, gone.amt ? 'warn' : '')}
  </div>

  ${run.take.length ? `<div class="tm-run">
    <b>Pay ${run.take.length === 1 ? 'this one' : `these ${run.take.length}`} by ${esc(run.day)} and keep ${money(run.save)}.</b>
    <div class="small">${run.take.map(r => `${esc(r.bill.vendor)} ${money(r.amt)} → ${money(r2(r.amt - r.save))}`).join(' · ')}</div>
    <div class="small muted">One transfer. ${money(r2(run.cost))} leaves${run.must.length ? `, including ${run.must.length} that ${run.must.length === 1 ? 'is' : 'are'} simply due` : ''}.</div>
  </div>` : ''}

  <div class="row" style="gap:8px;margin:14px 0 8px"><h3 style="margin:0">Terms</h3>
    <span class="small muted">Two percent for paying twenty days early is a 37% annual return, available on the calendar, for nothing.</span></div>
  <table class="t"><thead><tr><th>Bill</th><th style="width:110px">Amount</th><th style="width:210px">If we pay early</th><th style="width:110px">Worth</th><th style="width:170px">Due</th><th style="width:120px">Where it is</th></tr></thead>
    <tbody>${rows.map(row).join('') || `<tr><td colspan="6" class="muted small">Nothing outstanding. Terms are read off the invoice when a bill is brought in, and from the dates when the invoice does not print them.</td></tr>`}</tbody></table>
  <p class="small muted" style="margin:10px 0 0">A discount is only real if the bill is approved in time to pay it — which is why the window is shown against where the bill actually is, not against the calendar alone.</p>`;
}

if (typeof SP_TABS !== 'undefined') SP_TABS.push(['terms', 'Terms & early payment']);
if (typeof spPane === 'function'){
  const spPaneBase_tm = spPane;
  spPane = function(ctx){ return spTab === 'terms' ? tmPaneHtml() : spPaneBase_tm(ctx); };
}

/* The ingest already reads "TERMS: NET 30" off the invoice; keep it as a field rather than burying it
   in a note, so it can be parsed rather than searched. */
if (typeof biToBill === 'function'){
  const biToBillBase_tm = biToBill;
  biToBill = function(inv, po, findings){
    const b = biToBillBase_tm(inv, po, findings);
    if (inv && inv.terms) b.terms = inv.terms;
    return b;
  };
}
/* Terms on the vendors the firm already deals with, so the calendar has something true to show. */
function tmSeed(){
  if (DB.__tmSeed) return; DB.__tmSeed = 1;
  const set = (name, terms) => { const v = (DB.vendors || []).find(x => (x.name || '').toLowerCase().includes(name)); if (v) v.terms = terms;
    (DB.bills || []).forEach(b => { if ((b.vendor || '').toLowerCase().includes(name) && !b.terms) b.terms = terms; }); };
  set('nemo', '2/10 NET 30');
  set('window', 'NET 14');
  set('carlos', '1.5/15 NET 45');
  set('alberto', 'NET 30');
  save();
}
if (typeof spSeed === 'function'){
  const spSeedBase_tm = spSeed;
  spSeed = function(){ spSeedBase_tm(); try { tmSeed(); } catch (e){} };
}
/*<</terms.js>>*/

/*<<spnav.js>>*/
/* ===================== ONE SCREEN, THREE JOBS =====================
   The money screen started with four tabs and now has ten, in a row that wraps. That is not a nav, it
   is a list of everything that got built, and it makes the person scan ten things to find the one they
   came for. The tabs are also not peers: some are today's work, some are where a cost is born, and
   some are policy that is set once and read occasionally.

   So they are grouped by what somebody is actually doing when they open this screen:

     THE DAY      what needs approving, what has cleared, what has not been billed on
     WHERE IT STARTS  the four places a cost is created — hours, cards, receipts, vendor bills
     CONTROLS     the rules and the reconciliation, which are read rather than worked

   A group is chosen first and its tabs are shown underneath. Two short rows instead of one long one,
   and the group you are in tells you what kind of question you are asking. */
const SP_GROUPS = [
  ['day',   'The day',          ['approve', 'match', 'unbilled', 'all']],
  ['start', 'Where cost starts',['payroll', 'cards', 'inbills']],
  ['ctrl',  'Controls',         ['route', 'terms', 'recon']],
];
const spGroupOf = tab => (SP_GROUPS.find(g => g[2].includes(tab)) || SP_GROUPS[0])[0];
let spGroup = 'day';

/* Counts belong on the group as well as the tab, or a person in one group never learns that something
   is waiting in another. */
function spGroupCount(key){
  const g = SP_GROUPS.find(x => x[0] === key); if (!g) return 0;
  let n = 0;
  if (g[2].includes('approve')) n += (DB.spend || []).filter(s => s.status === 'submitted').length;
  if (g[2].includes('inbills')) n += (typeof biPending === 'function' ? biPending().length : 0);
  if (g[2].includes('route')) n += (typeof rtWaiting === 'function'
    ? rtWaiting().filter(o => { try { return rtCan(o).ok; } catch (e){ return false; } }).length : 0);
  return n;
}
function spTabCount(k){
  try {
    if (k === 'approve') return (DB.spend || []).filter(s => s.status === 'submitted').length;
    if (k === 'unbilled') return (typeof spUnbilled === 'function' && S ? spUnbilled(S.id).length : 0);
    if (k === 'inbills') return (typeof biPending === 'function' ? biPending().length : 0);
    if (k === 'route') return (typeof rtWaiting === 'function' ? rtWaiting().filter(o => rtCan(o).ok).length : 0);
    if (k === 'cards') return (typeof cdUnassigned === 'function' ? cdUnassigned().length : 0);
    if (k === 'terms') return (typeof tmRows === 'function' ? tmRows().filter(r => r.state === 'discount' || r.state === 'late').length : 0);
    if (k === 'recon') return (typeof rxAll === 'function' ? rxAll().filter(s => s.status !== 'reconciled').length : 0);
  } catch (e){}
  return 0;
}

function spNavHtml(){
  const label = k => (SP_TABS.find(t => t[0] === k) || [, k])[1];
  const grp = SP_GROUPS.find(g => g[0] === spGroup) || SP_GROUPS[0];
  return `<div class="sp-nav">
    <div class="sp-groups">${SP_GROUPS.map(([k, l]) => { const n = spGroupCount(k);
      return `<button class="${spGroup === k ? 'on' : ''}" data-spgrp="${k}">${esc(l)}${n ? `<span class="n">${n}</span>` : ''}</button>`; }).join('')}</div>
    <div class="ctabs sp-sub" style="margin:0">${grp[2].filter(k => SP_TABS.some(t => t[0] === k)).map(k => { const n = spTabCount(k);
      return `<button class="${spTab === k ? 'on' : ''}" data-sptab="${k}">${esc(label(k))}${n ? `<span class="n">${n}</span>` : ''}</button>`; }).join('')}</div>
  </div>`;
}

/* Swap the one long row for the two short ones, wherever renderSpend put it. Anchoring on the markup
   rather than rewriting renderSpend keeps every tab that gets added later working without this file
   knowing about it. */
if (typeof renderSpend === 'function'){
  const renderSpendBase_nav = renderSpend;
  renderSpend = function(){
    if (spGroupOf(spTab) !== spGroup) spGroup = spGroupOf(spTab);
    renderSpendBase_nav();
    const root = (typeof $ === 'function' && ($('#spend-body') || $('#vf-body'))) || null;
    if (!root) return;
    const old = root.querySelector('.ctabs:not(.sp-sub)');
    if (old && !root.querySelector('.sp-nav')){
      old.insertAdjacentHTML('beforebegin', spNavHtml());
      old.remove();
      root.querySelectorAll('[data-spgrp]').forEach(b => b.onclick = () => {
        const g = SP_GROUPS.find(x => x[0] === b.dataset.spgrp); if (!g) return;
        spGroup = g[0];
        // land on the tab in that group that has something waiting, else its first
        spTab = g[2].find(k => SP_TABS.some(t => t[0] === k) && spTabCount(k)) || g[2].find(k => SP_TABS.some(t => t[0] === k)) || spTab;
        renderSpend();
      });
      root.querySelectorAll('.sp-sub [data-sptab]').forEach(b => b.onclick = () => { spTab = b.dataset.sptab; renderSpend(); });
    }
  };
}
/*<</spnav.js>>*/

/*<<progress.js>>*/
/* ===================== BILLING WHAT HAS ACTUALLY LANDED =====================
   A progress invoice is a percentage per line that somebody types, once a month, from memory. The
   schedule of values, the retainage, the G702 summary — all of that already works. What is missing is
   the only hard part: deciding the number.

   On the Locke job that produced $13,970 of façade work spent against $19,530 billed on $33,500 of
   cost. Nobody was lying. They estimated the percentage and moved on.

   THE CORRECTION THAT MAKES THIS SAFE: cost is not progress.

   Sixty percent of a line's budget spent might mean sixty percent complete, or it might mean the line
   is badly over and half finished. Billing off cost would quietly convert an overrun into an invoice
   to the client, which is worse than under-billing — it is the thing that gets a contractor sued. So:

     the SCHEDULE drives the number where the work is trackable — tasks done, tasks running
     DELIVERIES drive it for lines that are a material rather than a labour operation
     COST is the cross-check, and only ever a fallback, and it says so on its face

   Where cost and completion diverge, that IS the finding. Cost ahead of progress means the line is
   going over and the time to know is now. Progress ahead of billing means work done and not invoiced.

   And nothing is billed by this screen. It proposes a percentage per line, with what it read, and a
   person accepts it onto a draft invoice they still have to send. */

const PG_BASIS = {
  schedule:  ['the schedule',        'tasks on this trade, done and running'],
  delivered: ['what was delivered',  'received against the purchase orders on this line'],
  cost:      ['cost, as a fallback', 'no schedule or delivery evidence — cost is a guide, not progress'],
  none:      ['nothing to go on',    'no tasks, no deliveries and no cost on this line yet'],
};
const pgCfg = () => { DB.company.progress = Object.assign({stored: false, diverge: 15, ahead: 5}, DB.company.progress || {}); return DB.company.progress; };

/* ---------- the schedule ----------
   A task carries a trade, and a trade maps to a cost code the app already computes. So a contract line
   coded 04 is served by the window tasks, and their state is the honest measure of that line.
   A finished task counts fully; a running one counts by how far through its own dates it is, which is
   closer to true than the fifty percent everyone defaults to and never revisits. */
function pgTaskPct(p, code){
  if (!p || !code) return null;
  const mine = (p.tasks || []).filter(t => t.type !== 'milestone' && (
    t.lineRef ? false : (typeof codeForTrade === 'function' && t.trade && codeForTrade(t.trade) === code)));
  if (!mine.length) return null;
  const span = t => Math.max(1, Math.round((new Date(t.end || t.start) - new Date(t.start)) / 86400000) + 1);
  const share = t => {
    if (t.status === 'done') return 1;
    if (t.status !== 'in-progress') return 0;
    const s = new Date(t.actualStart || t.start), e = new Date(t.end || t.start);
    const n = new Date(today());
    if (n <= s) return 0.05;
    const f = (n - s) / Math.max(86400000, e - s);
    return Math.max(0.05, Math.min(0.95, f));       // never 0 and never 100 while it is still running
  };
  const days = mine.reduce((a, t) => a + span(t), 0);
  const doneDays = mine.reduce((a, t) => a + span(t) * share(t), 0);
  return {pct: r2(doneDays / days * 100), n: mine.length,
          done: mine.filter(t => t.status === 'done').length,
          running: mine.filter(t => t.status === 'in-progress').length};
}
/* Tasks tied to a line directly, when anybody has done that — always better than the trade guess. */
function pgTaskPctByRef(p, key){
  const mine = (p.tasks || []).filter(t => t.lineRef === key);
  if (!mine.length) return null;
  const span = t => Math.max(1, Math.round((new Date(t.end || t.start) - new Date(t.start)) / 86400000) + 1);
  const days = mine.reduce((a, t) => a + span(t), 0);
  const doneDays = mine.reduce((a, t) => a + span(t) * (t.status === 'done' ? 1 : t.status === 'in-progress' ? 0.5 : 0), 0);
  return {pct: r2(doneDays / days * 100), n: mine.length, done: mine.filter(t => t.status === 'done').length,
          running: mine.filter(t => t.status === 'in-progress').length, exact: true};
}

/* ---------- what turned up ----------
   Ordered, received, and — the distinction that matters on a pay application — what is on site and not
   yet in the building. G703 keeps materials presently stored in its own column for exactly this reason:
   under most contracts they are billable, under some they are not, and either way they are not
   progress. */
function pgDelivered(key){
  const pos = (DB.pos || []).filter(po => !['cancelled', 'draft'].includes(po.status) && (po.lines || []).some(l => l.line === key));
  let ordered = 0, received = 0;
  pos.forEach(po => (po.lines || []).filter(l => l.line === key).forEach(l => {
    const q = +l.qty || 0, price = +l.price || 0;
    ordered = r2(ordered + q * price);
    received = r2(received + Math.min(q, +l.received || 0) * price);
  }));
  return {ordered, received, pct: ordered ? r2(received / ordered * 100) : null, pos: pos.length};
}

/* ---------- one line of the contract, with everything known about it ---------- */
function pgEvidence(c, p, sv){
  const key = sv.lineRef || '';
  const fin = key && typeof lineFin === 'function' ? lineFin(key) : null;
  const ref = key && typeof findLine === 'function' ? findLine(key) : null;
  const line = ref ? ref.line : null;
  const code = line ? (line.code || (typeof codeForLine === 'function' ? codeForLine(line) : '')) : '';
  const scheduled = +sv.scheduled || 0;
  const billedPct = r2(sovBilled(c, sv.id));
  const cost = fin ? fin.actual : 0;
  const budget = fin ? fin.budget : 0;
  const committed = fin ? fin.committed : 0;
  const hours = (typeof labCosts === 'function' ? labCosts().filter(r => r.line === key) : []);
  const del = key ? pgDelivered(key) : {ordered: 0, received: 0, pct: null, pos: 0};
  const sched = key ? (pgTaskPctByRef(p, key) || pgTaskPct(p, code)) : null;
  const isMaterial = !!(line && (line.selId || (ref && ref.doc.template === 'materials')));
  return {sv, key, line, code, scheduled, billedPct, cost, budget, committed, del, sched, isMaterial,
          hours: r2(hours.reduce((a, r) => a + (+r.hours || 0), 0)),
          costPct: budget ? r2(Math.min(200, cost / budget * 100)) : null,
          fin};
}

/* ---------- the proposal ----------
   Percent complete TO DATE, not this period — the pay application does that subtraction itself, and
   getting the two confused is how a line gets billed twice. */
function pgProposal(ev){
  const cfg = pgCfg();
  let pct = null, basis = 'none', extra = '', stale = false;

  /* A schedule that says nothing has started on a trade the firm has already spent money on is not
     evidence that nothing has started. It is evidence that nobody has updated the tasks. Reading it as
     a hard zero produced fifteen "the evidence disagrees" findings on the seeded job — a control that
     fires on every line is one nobody reads, which is the failure this whole approach is meant to
     avoid. So a silent schedule with cost behind it is treated as ABSENT evidence, and the absence is
     itself the finding. */
  stale = !!(ev.sched && ev.sched.n && ev.sched.pct === 0 && ev.cost > 0);

  if (ev.sched && ev.sched.n && !stale){ pct = ev.sched.pct; basis = 'schedule';
    extra = `${ev.sched.done} of ${ev.sched.n} task${ev.sched.n === 1 ? '' : 's'} done${ev.sched.running ? `, ${ev.sched.running} running` : ''}`; }
  else if (ev.isMaterial && ev.del.pct != null){ pct = ev.del.pct; basis = 'delivered';
    extra = `${money(ev.del.received)} received of ${money(ev.del.ordered)} ordered`; }
  else if (ev.costPct != null && ev.cost > 0){ pct = Math.min(100, ev.costPct); basis = 'cost';
    extra = `${money(ev.cost)} spent against a ${money(ev.budget)} budget`; }
  else if (ev.del.received > 0){ pct = ev.del.pct; basis = 'delivered';
    extra = `${money(ev.del.received)} received of ${money(ev.del.ordered)} ordered`; }

  /* Materials on site and not in the building. Only counted when the contract allows billing for
     stored materials, and shown separately either way, because it is not progress. */
  let stored = 0;
  if (ev.del.received > 0 && pct != null){
    const installedValue = r2(ev.scheduled * pct / 100);
    stored = r2(Math.max(0, ev.del.received - Math.max(0, installedValue - (ev.cost - ev.del.received))));
    stored = r2(Math.min(stored, ev.del.received));
  }
  const storedPct = (cfg.stored && ev.scheduled && stored > 0) ? r2(Math.min(100 - (pct || 0), stored / ev.scheduled * 100)) : 0;

  const propose = pct == null ? null : r2(Math.min(100, pct + storedPct));
  return {pct: propose, own: pct, basis, extra, stored, storedPct, stale,
          label: PG_BASIS[basis][0], why: PG_BASIS[basis][1],
          period: propose == null ? null : r2(Math.max(0, propose - ev.billedPct))};
}

/* ---------- what the divergence says ---------- */
function pgFindings(ev, pr){
  const cfg = pgCfg(), f = [];
  const add = (sev, kind, msg) => f.push({sev, kind, msg});

  if (pr.pct == null && ev.cost > 0)
    add('warn', 'blind', `${money(ev.cost)} has landed on this line and there is nothing to measure progress by — no tasks on the trade, no purchase order receipts`);

  if (ev.cost > 0 && ev.billedPct === 0)
    add('bad', 'never-billed', `${money(ev.cost)} spent and nothing billed on this line yet`);

  if (pr.stale)
    add('warn', 'stale', `Nothing on this trade is marked started, but ${money(ev.cost)} has landed on the line — the tasks are behind the work, so the schedule cannot be used to measure it`);

  /* Over budget is simply true and worth saying whatever the basis. Over budget RELATIVE TO THE WORK
     DONE is a much stronger claim, and it is only made where the work is actually known — a cost
     overrun cannot be inferred from cost alone, and a stale schedule cannot be used to infer it
     either. */
  if (ev.budget && ev.cost > ev.budget * 1.02)
    add('bad', 'over-budget', `${money(ev.cost)} spent against a ${money(ev.budget)} budget — ${money(r2(ev.cost - ev.budget))} over, before anything still committed`);

  if (pr.pct != null && ev.costPct != null && !pr.stale && (pr.basis === 'schedule' || pr.basis === 'delivered')){
    const gap = r2(ev.costPct - pr.own);
    if (gap > cfg.diverge && ev.cost <= ev.budget * 1.02)
      add('bad', 'over', `${ev.costPct}% of the budget spent against ${pr.own}% of the work done — this line is heading over by about ${money(r2(ev.budget * gap / 100))}`);
    else if (gap < -cfg.diverge)
      add('info', 'under', `${pr.own}% done on ${ev.costPct}% of the budget — this line is running under, so far`);
  }

  /* Billed ahead of the work is a serious thing to say to a person about their own invoice, so it is
     only said where the work is genuinely known. Cost cannot prove it — front-loading a schedule of
     values is normal and legal — and a stale schedule certainly cannot. */
  if (pr.pct != null && !pr.stale && !ev.lumpBilled && (pr.basis === 'schedule' || pr.basis === 'delivered')
      && ev.billedPct > pr.pct + cfg.ahead)
    add('bad', 'over-billed', `Already billed ${ev.billedPct}% against ${pr.pct}% complete — billing further would take it further ahead of the work`);

  if (pr.storedPct)
    add('info', 'stored', `${money(pr.stored)} of it is material on site and not yet installed — billable here because the contract allows stored materials, and shown separately on the application`);
  else if (pr.stored > 0)
    add('info', 'stored-off', `${money(pr.stored)} of material is on site and not installed — not included, because stored materials are switched off for this contract`);

  if (pr.pct != null && pr.period === 0 && ev.billedPct > 0)
    add('info', 'nothing', 'Nothing new to bill on this line since the last application');

  if (pr.pct === 100 && ev.committed > 0)
    add('warn', 'committed', `Proposed at 100% with ${money(ev.committed)} still committed on open purchase orders — check the line is really finished`);

  return f;
}

/* ---------- every line of one job ---------- */
function pgRows(projectId){
  const p = DB.projects.find(x => x.id === (projectId || S.id)); if (!p) return [];
  const c = DB.clients.find(x => x.id === p.clientId); if (!c) return [];
  const svs = (c.sov || []).filter(sv => sv.projectId == null || sv.projectId === p.id)
    .sort((a, b) => (a.order || 0) - (b.order || 0));
  const evs = svs.map(sv => pgEvidence(c, p, sv));

  /* Has this contract ever been billed line by line, or as one percentage across everything? If every
     line carries the identical percentage, the answer is a lump — somebody billed "52% of the job" and
     the schedule of values inherited it. In that case "billed 51.67% against 0% complete" is true of
     every line and means nothing about any of them, so it is said once about the contract instead of
     eleven times about its lines. Eleven copies of a true sentence is still a screen nobody reads.
     Judged per source, because a base contract billed as a lump and a change order billed separately
     are two different billing histories sitting in one schedule of values — testing them together
     misses the lump entirely, which is what a first pass at this did. */
  let lump = null;
  const bySource = {};
  evs.forEach(e => { const k = e.sv.source || 'Contract'; (bySource[k] = bySource[k] || []).push(e); });
  Object.entries(bySource).forEach(([src, list]) => {
    const billed = list.filter(e => e.billedPct > 0);
    const pcts = [...new Set(billed.map(e => e.billedPct))];
    if (pcts.length === 1 && billed.length >= 3){
      billed.forEach(e => { e.lumpBilled = true; });
      if (!lump || billed.length > lump.n) lump = {pct: pcts[0], n: billed.length, source: src};
    }
  });

  const rows = svs.map((sv, i) => { const ev = evs[i]; const pr = pgProposal(ev);
                                    return {c, p, sv, ev, pr, findings: pgFindings(ev, pr)}; });
  rows.lump = lump;
  return rows;
}
const pgTotals = rows => ({
  scheduled: r2(rows.reduce((a, r) => a + r.ev.scheduled, 0)),
  billed: r2(rows.reduce((a, r) => a + r.ev.scheduled * r.ev.billedPct / 100, 0)),
  propose: r2(rows.reduce((a, r) => a + (r.pr.period ? r.ev.scheduled * r.pr.period / 100 : 0), 0)),
  cost: r2(rows.reduce((a, r) => a + r.ev.cost, 0)),
  unbilled: r2(rows.reduce((a, r) => a + Math.max(0, r.ev.cost - r.ev.scheduled * r.ev.billedPct / 100), 0)),
});

/* ---------- onto a draft ----------
   The existing pay application does the rest: retainage, previous applications, the deposit, the G702
   summary and the print. This only fills in the one column nobody could compute. */
function pgDraft(projectId){
  const p = DB.projects.find(x => x.id === (projectId || S.id)); if (!p) return null;
  const c = DB.clients.find(x => x.id === p.clientId); if (!c) return null;
  let inv = (c.invoices || []).find(i => i.mode === 'sov' && i.status === 'draft' && (i.projectId || '') === (p.id || ''));
  if (!inv){
    const d = (c.estimates || []).find(e => ['converted', 'billed'].includes(e.status) && (e.projectId || '') === (p.id || ''));
    if (!d || typeof ctProgressInvoice !== 'function') return null;
    inv = ctProgressInvoice(c, d);
    inv.projectId = p.id;
  }
  return {c, p, inv};
}
function pgApply(projectId, only){
  const d = pgDraft(projectId); if (!d){ toast('No contract on this job to bill against'); return null; }
  const rows = pgRows(projectId);
  let n = 0, amt = 0;
  rows.forEach(r => {
    if (only && !only.includes(r.sv.id)) return;
    if (r.pr.period == null || r.pr.period <= 0) return;
    const l = (d.inv.lines || []).find(x => x.sovId === r.sv.id); if (!l) return;
    const room = r2(100 - (+l.prevPct || 0));
    l.pct = r2(Math.min(r.pr.period, room));
    l.desc = l.desc || r.pr.extra;
    n++; amt = r2(amt + r.ev.scheduled * l.pct / 100);
    audit('invoice', d.inv.id, 'progress-proposed', null,
          {line: r.sv.desc, pct: l.pct, basis: r.pr.basis, why: r.pr.extra});
  });
  save();
  return {inv: d.inv, client: d.c, n, amt};
}

/* ---------- the screen ---------- */
function pgPaneHtml(){
  const p = DB.projects.find(x => x.id === (spProj === 'all' ? S.id : spProj)) || S;
  const rows = pgRows(p.id);
  const T = pgTotals(rows);
  const cfg = pgCfg();
  const flags = rows.flatMap(r => r.findings.filter(f => f.sev === 'bad').map(f => [r, f]));
  const stat = (v, s, cls) => `<div class="sel-stat"><b class="${cls || ''}">${v}</b><span>${s}</span></div>`;

  const row = ({sv, ev, pr, findings}) => `<tr data-pgrow="${sv.id}">
    <td><b>${esc(sv.desc)}</b><div class="small muted">${esc(sv.source || '')}${ev.code ? ' · ' + esc(ev.code) : ''}</div></td>
    <td class="n">${money(ev.scheduled)}</td>
    <td class="n">${ev.billedPct}%<div class="small muted">${money(r2(ev.scheduled * ev.billedPct / 100))}</div></td>
    <td>${pr.pct == null
      ? '<span class="muted small">nothing to measure it by</span>'
      : `<b class="${pr.basis === 'cost' ? 'warn' : ''}">${pr.pct}%</b>
         <div class="small muted">${esc(pr.label)} — ${esc(pr.extra)}</div>`}</td>
    <td class="n">${pr.period ? `<b>${money(r2(ev.scheduled * pr.period / 100))}</b><div class="small muted">${pr.period}% this period</div>` : '<span class="muted">—</span>'}</td>
    <td>${ev.cost ? `${money(ev.cost)}${ev.costPct != null ? `<div class="small muted">${ev.costPct}% of budget</div>` : ''}` : '<span class="muted small">—</span>'}</td>
    <td>${findings.map(f => `<div class="small ${f.sev === 'bad' ? 'bad' : f.sev === 'warn' ? 'warn' : 'muted'}">${esc(f.msg)}</div>`).join('') || ''}</td></tr>`;

  return `
  <div class="sel-stats">
    ${stat(money(T.propose), 'this application would bill', T.propose ? 'ok' : '')}
    ${stat(money(T.unbilled), 'cost above what has been billed on those lines', T.unbilled ? 'bad' : 'ok')}
    ${stat(`${T.scheduled ? Math.round(T.billed / T.scheduled * 100) : 0}%`, `billed to date of ${money(T.scheduled)}`)}
    ${stat(flags.length, `line${flags.length === 1 ? '' : 's'} to look at first`, flags.length ? 'bad' : 'ok')}
  </div>

  <div class="pg-rule">
    <b>Cost is not progress.</b>
    <span class="small">Sixty percent of a budget spent can mean sixty percent complete or a line running badly over. So the schedule drives the number where the work is trackable, deliveries drive it for material lines, and cost is only ever a fallback — and where the two disagree, that is the finding rather than the invoice.</span>
  </div>

  ${rows.lump ? `<div class="pg-lump"><b>${rows.lump.source === 'Contract' ? 'This contract has' : esc(rows.lump.source) + ' has'} been billed as one percentage, not line by line.</b>
    <span class="small">${rows.lump.n} lines carry the same ${rows.lump.pct}%, so "billed against complete" is true of every line and says nothing about any of them. From this application on, each line bills on its own evidence — and the comparison starts meaning something.</span></div>` : ''}
  ${flags.length ? `<div class="cd-flags"><b>${flags.length} line${flags.length === 1 ? '' : 's'} to look at before this goes to the client</b>
    ${flags.slice(0, 6).map(([r, f]) => `<div class="small">${esc(r.sv.desc)} — ${esc(f.msg)}</div>`).join('')}</div>` : ''}

  <div class="row" style="gap:8px;margin:14px 0 8px"><h3 style="margin:0">${esc(p.project ? p.project.name : 'This job')} — ready to bill</h3>
    <span class="grow"></span>
    <label class="cl-chk" style="margin:0"><input type="checkbox" id="pg-stored" ${cfg.stored ? 'checked' : ''}><span class="small">Contract allows billing stored materials</span></label>
    <button class="btn sm primary" id="pg-apply" ${T.propose ? '' : 'disabled'}>Put ${money(T.propose)} on a draft</button></div>

  <table class="t"><thead><tr><th>Line</th><th style="width:110px">Scheduled</th><th style="width:110px">Billed</th>
    <th style="width:240px">Complete, and how we know</th><th style="width:130px">This period</th>
    <th style="width:120px">Cost landed</th><th>What the evidence says</th></tr></thead>
    <tbody>${rows.map(row).join('') || `<tr><td colspan="7" class="muted small">No schedule of values on this job. Convert an approved estimate and every line appears here with what has landed on it.</td></tr>`}</tbody></table>
  <p class="small muted" style="margin:10px 0 0">Percentages are complete-to-date; the pay application works out this period, the retainage, the previous applications and the deposit as it already does. Nothing here is sent — it fills a draft you still have to look at.</p>`;
}
function pgWire(root){
  root.querySelector('#pg-stored')?.addEventListener('change', e => {
    pgCfg().stored = e.target.checked;
    audit('company', 'progress', 'stored-materials', null, {on: e.target.checked});
    save(); renderSpend();
  });
  root.querySelector('#pg-apply')?.addEventListener('click', () => {
    const pid = (spProj === 'all' ? S.id : spProj);
    const rows = pgRows(pid);
    const bad = rows.filter(r => r.findings.some(f => f.sev === 'bad'));
    const go = () => {
      const out = pgApply(pid);
      if (!out) return;
      renderSpend();
      toast(`${out.n} line${out.n === 1 ? '' : 's'} filled — ${money(out.amt)} on ${out.inv.number || 'a draft'}. Nothing is sent.`);
    };
    if (!bad.length){ go(); return; }
    mbModal('Before this goes on a draft', `
      <p class="small">${bad.length} line${bad.length === 1 ? '' : 's'} where what we spent and what we have done do not agree. The proposal still uses the work, not the cost — but these are worth a look first.</p>
      <table class="t"><thead><tr><th>Line</th><th>What the evidence says</th></tr></thead><tbody>
      ${bad.map(r => `<tr><td><b>${esc(r.sv.desc)}</b></td><td>${r.findings.filter(f => f.sev === 'bad').map(f => `<div class="small">${esc(f.msg)}</div>`).join('')}</td></tr>`).join('')}
      </tbody></table>
      <p class="small muted" style="margin:8px 0 0">A line running over is a margin problem, not a billing one — billing more of it does not fix it and does put the invoice ahead of the work.</p>`,
      {submit: 'Fill the draft anyway', wide: true, onSubmit: go});
    if (typeof procWide === 'function') procWide(820);
  });
  root.querySelectorAll('[data-pgrow]').forEach(tr => tr.addEventListener('click', () => {
    const pid = (spProj === 'all' ? S.id : spProj);
    const r = pgRows(pid).find(x => x.sv.id === tr.dataset.pgrow); if (!r) return;
    const ev = r.ev, pr = r.pr;
    mbModal(esc(r.sv.desc), `
      <div class="pg-ev">
        <div><span>Scheduled value</span><b>${money(ev.scheduled)}</b></div>
        <div><span>Billed to date</span><b>${ev.billedPct}% · ${money(r2(ev.scheduled * ev.billedPct / 100))}</b></div>
        <div><span>Cost landed</span><b>${money(ev.cost)}${ev.budget ? ` of ${money(ev.budget)} budgeted` : ''}</b></div>
        <div><span>Still committed on orders</span><b>${money(ev.committed)}</b></div>
        <div><span>Hours booked</span><b>${ev.hours || 0}</b></div>
        <div><span>Delivered</span><b>${ev.del.pos ? `${money(ev.del.received)} of ${money(ev.del.ordered)} on ${ev.del.pos} order${ev.del.pos === 1 ? '' : 's'}` : 'nothing ordered on this line'}</b></div>
        <div><span>Schedule</span><b>${ev.sched ? `${ev.sched.pct}% — ${ev.sched.done} of ${ev.sched.n} done${ev.sched.running ? `, ${ev.sched.running} running` : ''}` : 'no tasks on this trade'}</b></div>
      </div>
      <div class="pg-prop">
        ${pr.pct == null ? '<b>Nothing to propose.</b><div class="small">There is no schedule, no delivery and no cost on this line to measure it by. A number typed here would be a guess wearing a percentage sign.</div>'
        : `<b>${pr.pct}% complete to date — from ${esc(pr.label)}.</b>
           <div class="small">${esc(pr.extra)}. ${esc(pr.why)}.</div>
           <div class="small muted">That is ${pr.period}% this period, ${money(r2(ev.scheduled * (pr.period || 0) / 100))}.</div>`}
      </div>
      ${r.findings.length ? `<h4 style="margin:12px 0 6px">What the evidence says</h4>
        ${r.findings.map(f => `<div class="rc-ink ${f.sev === 'bad' ? 'conflicts' : f.sev === 'warn' ? 'proposes' : 'unclear'}"><div class="small">${esc(f.msg)}</div></div>`).join('')}` : ''}`,
      {submit: null});
    if (typeof procWide === 'function') procWide(760);
  }));
}

if (typeof SP_TABS !== 'undefined') SP_TABS.push(['billing', 'Ready to bill']);
if (typeof SP_GROUPS !== 'undefined'){ const g = SP_GROUPS.find(x => x[0] === 'day'); if (g && !g[2].includes('billing')) g[2].push('billing'); }
if (typeof spPane === 'function'){
  const spPaneBase_pg = spPane;
  spPane = function(ctx){ return spTab === 'billing' ? pgPaneHtml() : spPaneBase_pg(ctx); };
}
if (typeof wireSpend === 'function'){
  const wireSpendBase_pg = wireSpend;
  wireSpend = function(root){ wireSpendBase_pg(root); if (spTab === 'billing') try { pgWire(root); } catch (e){ console.error('progress', e); } };
}
/*<</progress.js>>*/

/*<<dsn.js>>*/
/* ===================== THE HOURS THE CLIENT AGREED TO =====================
   Alan, to the 140 Prospect clients: *"sometimes just saying something as simple as 'Yeah, I'd love to
   see what that looks like' could be 30 hours in an architect or designer's time that you guys are
   paying to see that."*

   He is right, and the firm still runs 40 hours past the number before anyone says a word. By then
   there are only bad options: bill the client for work they never agreed to, or eat it. The design
   team did nothing wrong — nobody told them where the line was, and the person who could have told
   them was reading a timesheet a fortnight later.

   TWO CEILINGS, AND THEY ARE NOT THE SAME THING.

     HOURS PAID FOR    money actually collected on the design contract, divided by the rate.
                       Going past it means the studio is working unfunded. It is a CASH problem and
                       the answer is an invoice.
     HOURS AGREED      the hours in the signed proposal. Going past it means the studio is working
                       outside what the client authorised. It is a SCOPE problem and the answer is
                       the client's signature, not an invoice.

   A firm that tracks only the first bills for work nobody approved. One that tracks only the second
   works for months on money that never arrived. So both are carried, both are warned on, and the two
   warnings say different things to different people.

   AND THE WARNING HAS TO LAND WHERE THE HOUR IS SPENT. A report nobody opens is how this happens now.
   Every path that logs design time goes through `logHours`, so that is where the guard sits: the
   designer is told what is left BEFORE the entry is written, not after. */

const DS_LIMITS = () => Object.assign({warnPct: 80, actPct: 90, minHours: 20, hardStop: true},
                                      (DB.company && DB.company.designLimits) || {});

const dsEst = p => (typeof designEst === 'function' ? designEst(p) : null);
const dsRate = est => +((est && (est.lines || []).find(l => l.unit === 'hr') || {}).rate)
                    || (typeof designRate === 'function' ? designRate() : 175);
const dsHourLines = est => ((est && est.lines) || []).filter(l => l.unit === 'hr');
const dsAgreedHours = est => r2(dsHourLines(est).reduce((a, l) => a + (+l.qty || 0), 0));

/* Money in, and money merely asked for. The difference matters: a retainer that has been invoiced and
   not paid buys nothing, and a studio that treats it as funded is working on a promise. */
function dsMoney(c, p, est){
  if (!c || !est) return {collected: 0, invoiced: 0};
  const mine = (c.invoices || []).filter(i => i.status !== 'void' &&
    ((i.projectId || '') === (p.id || '') || i.retainerOf === est.id || i.fromDoc === est.id || i.depositOf === est.id));
  const invoiced = r2(mine.reduce((a, i) => a + (typeof docTotal === 'function' ? docTotal(i).total : 0), 0));
  const collected = r2(mine.reduce((a, i) => a + (typeof invoicePaid === 'function' ? invoicePaid(c, i) : 0), 0));
  return {collected, invoiced, unpaid: r2(invoiced - collected), n: mine.length};
}
/* Hours burned. Design staff only — a labourer's hours on the same job are construction cost, not the
   client's design block, and mixing them would eat the block twice as fast as it really goes. */
function dsBurned(p, est){
  const staff = (DB.employees || []).filter(e => typeof isDesignStaff === 'function' ? isDesignStaff(e) : (+e.billRate || 0) > 0).map(e => e.id);
  const rows = (DB.time || []).filter(t => t.projectId === p.id && staff.includes(t.empId));
  const h = t => (typeof hoursOf === 'function' ? hoursOf(t) : 0);
  return {hours: r2(rows.reduce((a, t) => a + h(t), 0)), rows,
          unapproved: r2(rows.filter(t => t.status !== 'approved').reduce((a, t) => a + h(t), 0))};
}
/* How fast it is going. Four weeks, because a fortnight is noise on a studio and a quarter is history. */
function dsBurnRate(p){
  const staff = (DB.employees || []).filter(e => typeof isDesignStaff === 'function' ? isDesignStaff(e) : (+e.billRate || 0) > 0).map(e => e.id);
  const from = iso(addDays(today(), -28));
  const h = t => (typeof hoursOf === 'function' ? hoursOf(t) : 0);
  const hrs = (DB.time || []).filter(t => t.projectId === p.id && staff.includes(t.empId) && t.date >= from)
                             .reduce((a, t) => a + h(t), 0);
  return r2(hrs / 4);                                   // hours a week
}

const DS_STATE = {
  ok:            ['ok',      'inside both ceilings'],
  'watch-paid':  ['warn',    'approaching the hours paid for'],
  'over-paid':   ['bad',     'past the hours paid for'],
  'watch-agreed':['warn',    'approaching the hours agreed'],
  'over-agreed': ['bad',     'past the hours agreed'],
  unfunded:      ['bad',     'no hours paid for at all'],
};

function dsStatus(p){
  const est = dsEst(p); if (!est) return null;
  const c = DB.clients.find(x => x.id === p.clientId); if (!c) return null;
  const rate = dsRate(est), lim = DS_LIMITS();
  const agreed = dsAgreedHours(est);
  const M = dsMoney(c, p, est);
  const paidHours = rate ? r2(M.collected / rate) : 0;
  const B = dsBurned(p, est);
  const burned = B.hours;
  const leftPaid = r2(paidHours - burned);
  const leftAgreed = r2(agreed - burned);
  const week = dsBurnRate(p);
  const runway = h => (week > 0 && h > 0) ? Math.round(h / week * 7) : (h <= 0 ? 0 : null);
  const runwayWord = d => d == null ? '' : d <= 0 ? 'gone' : d === 1 ? 'about a day' : `about ${d} days`;

  const near = (left, total) => total > 0 && (left <= lim.minHours || burned / total * 100 >= lim.warnPct);
  let state = 'ok';
  /* Nothing paid for at all is the worst case, not an exempt one. The first pass gated every paid-hours
     rule on `paidHours > 0`, which meant a job where the client had paid nothing and the studio had
     already worked hours reported as fine — the precise situation this module exists to catch, passed
     over because the divisor was zero. */
  if (paidHours <= 0 && burned > 0) state = 'unfunded';
  else if (agreed > 0 && leftAgreed <= 0) state = 'over-agreed';
  else if (paidHours > 0 && leftPaid <= 0) state = 'over-paid';
  else if (agreed > 0 && near(leftAgreed, agreed)) state = 'watch-agreed';
  else if (paidHours > 0 && near(leftPaid, paidHours)) state = 'watch-paid';

  return {p, c, est, rate, agreed, paidHours, burned, leftPaid, leftAgreed, week, M,
          unapproved: B.unapproved,
          runwayPaid: runway(leftPaid), runwayAgreed: runway(leftAgreed), runwayWord,
          pctPaid: paidHours ? Math.round(burned / paidHours * 100) : null,
          pctAgreed: agreed ? Math.round(burned / agreed * 100) : null,
          binding: (agreed > 0 && paidHours > 0) ? (leftAgreed <= leftPaid ? 'agreed' : 'paid')
                 : agreed > 0 ? 'agreed' : 'paid',
          state, lim};
}
const dsAll = () => (typeof studioProjects === 'function' ? studioProjects() : DB.projects)
  .map(dsStatus).filter(Boolean).sort((a, b) => (Math.min(a.leftPaid, a.leftAgreed)) - (Math.min(b.leftPaid, b.leftAgreed)));

/* What to say, to whom. The two ceilings do not produce the same sentence, and they are not the same
   person's problem: an invoice is the billing team's, a signature is the project lead's. */
function dsChecks(st){
  const out = [], lim = st.lim;
  const push = (sev, who, kind, msg, act) => out.push({sev, who, kind, msg, act});

  if (st.agreed > 0 && st.leftAgreed <= 0)
    push('bad', 'lead', 'over-agreed',
      `${r2(-st.leftAgreed)} hours past the ${st.agreed} the client agreed to. Every hour from here is work nobody authorised — that is a conversation and a signature, not an invoice.`,
      'authorise');
  else if (st.agreed > 0 && (st.leftAgreed <= lim.minHours || st.pctAgreed >= lim.warnPct))
    push('warn', 'lead', 'watch-agreed',
      `${st.leftAgreed} of ${st.agreed} agreed hours left${st.runwayAgreed != null ? ` — ${st.runwayWord(st.runwayAgreed)} at ${st.week} hours a week` : ''}. Tell the client now, while it is a choice rather than a bill.`,
      'authorise');

  if (st.paidHours <= 0 && st.burned > 0)
    push('bad', 'billing', 'unfunded',
      `${st.burned} hours worked and not one of them paid for${st.M.unpaid > 0.5 ? ` — ${money(st.M.unpaid)} is invoiced and uncollected` : ' — nothing has even been invoiced'}. The proposal says the client pays for hours in advance; this job is not on that footing.`,
      st.M.unpaid > 0.5 ? 'chase' : 'topup');
  else if (st.paidHours > 0 && st.leftPaid <= 0)
    push('bad', 'billing', 'over-paid',
      `${r2(-st.leftPaid)} hours beyond what has been paid for — ${money(r2(-st.leftPaid * st.rate))} of studio time carried by us.`,
      'topup');
  else if (st.paidHours > 0 && (st.leftPaid <= lim.minHours || st.pctPaid >= lim.warnPct))
    push('warn', 'billing', 'watch-paid',
      `${st.leftPaid} of ${st.paidHours} paid hours left${st.runwayPaid != null ? ` — ${st.runwayWord(st.runwayPaid)} at this pace` : ''}. Invoice the next block before the studio runs onto our own money.`,
      'topup');

  if (st.M.unpaid > 0.5)
    push('warn', 'billing', 'unpaid',
      `${money(st.M.unpaid)} invoiced and not collected — that is ${r2(st.M.unpaid / st.rate)} hours the studio may think it has and does not.`,
      'chase');

  if (st.unapproved > 0)
    push('info', 'lead', 'unapproved',
      `${st.unapproved} hours logged and not yet approved — they count against the block here, but they are not billable until somebody signs them off.`);

  if (!st.agreed)
    push('warn', 'lead', 'no-agreement',
      'This proposal has no hours on it, so there is no ceiling to warn against. Put the agreed hours on the design line and the guard starts working.');

  return out;
}

/* ---------- the guard, at the moment the hour is logged ----------
   Not a report. The designer is about to write down four hours; this is where they find out that
   three are left. */
function dsGuard(projectId, hours){
  const p = DB.projects.find(x => x.id === projectId); if (!p) return {ok: true};
  const st = dsStatus(p); if (!st) return {ok: true};
  const after = r2(st.burned + (+hours || 0));
  const lim = st.lim;
  const overAgreed = st.agreed > 0 && after > st.agreed;
  const overPaid = st.paidHours > 0 && after > st.paidHours;
  /* An unfunded job is a management decision, not the designer's. Blocking every entry on it would
     teach people to force past the guard within a day, and a guard everybody forces is worse than no
     guard at all. So it tells them, loudly, and shows the job as unfunded to the two people who can
     actually do something about it. */
  if (st.paidHours <= 0 && st.agreed > 0 && after <= st.agreed)
    return {ok: true, st, after,
            note: `${st.p.project.name}: no hours have been paid for on this job yet — ${after} worked`};
  if (!overAgreed && !overPaid){
    const leftAfter = Math.min(st.agreed ? r2(st.agreed - after) : Infinity, st.paidHours ? r2(st.paidHours - after) : Infinity);
    if (leftAfter !== Infinity && leftAfter <= lim.minHours)
      return {ok: true, note: `${leftAfter} hours left after this one${st.runwayPaid != null ? '' : ''}`, st, after};
    return {ok: true, st, after};
  }
  return {ok: false, st, after, overAgreed, overPaid,
          level: overAgreed ? 'agreed' : 'paid',
          crossing: overAgreed ? r2(after - st.agreed) : r2(after - st.paidHours)};
}

if (typeof logHours === 'function'){
  const logHoursBase_ds = logHours;
  logHours = function(projectId, hours, phaseIdx, note, date, force){
    const g = dsGuard(projectId, hours);
    if (g.ok){
      const e = logHoursBase_ds(projectId, hours, phaseIdx, note, date);
      if (e && g.note) toast(g.note);
      return e;
    }
    if (force){
      const e = logHoursBase_ds(projectId, hours, phaseIdx, note, date);
      if (e){
        e.beyond = g.level; e.beyondWhy = force === true ? '' : String(force);
        audit('time', e.id, 'logged-beyond-' + g.level, null, {hours, why: e.beyondWhy, projectId});
        log(`${hours} h logged on ${g.st.p.project.name} beyond the hours ${g.level === 'agreed' ? 'agreed' : 'paid for'} — ${e.beyondWhy || 'no reason given'}`);
        save();
      }
      return e;
    }
    dsCrossModal(g, {projectId, hours, phaseIdx, note, date});
    return null;
  };
}

function dsCrossModal(g, args){
  const st = g.st;
  const agreed = g.level === 'agreed';
  mbModal(agreed ? 'This goes past what the client agreed to' : 'This goes past the hours that have been paid for', `
    <div class="ds-cross ${agreed ? 'hard' : ''}">
      <b>${esc(st.p.project.name)} — ${st.burned} hours logged${agreed ? ` against ${st.agreed} agreed` : ` against ${st.paidHours} paid for`}.</b>
      <div>Logging ${args.hours} more takes it to ${g.after}, which is ${r2(g.crossing)} hour${r2(g.crossing) === 1 ? '' : 's'} over.</div>
    </div>
    <p class="small">${agreed
      ? `Hours past the agreement are work the client has not authorised. Billing for them later is exactly how a client ends up paying for something they never said yes to — and how we end up eating it when they refuse. The right move is a short conversation now, before the hour is spent.`
      : `The work is inside the agreement, but the money for it has not arrived. Every hour past here is the studio running on our own cash until the next block is invoiced and paid.`}</p>
    <div class="f"><label>If you are logging it anyway, say why</label>
      <input data-f="why" placeholder="${agreed ? 'e.g. Cambri asked for the third kitchen option on Friday — Alan approving' : 'e.g. Retainer top-up invoiced 9/8, wire in flight'}"></div>
    <p class="small muted" style="margin:8px 0 0">The hour is recorded either way — hiding it helps nobody. What is recorded with it is that somebody knew, and why.</p>`,
    {submit: 'Log it and record why', cancel: 'Do not log it', wide: true,
     onSubmit: f => {
       if (!f.why){ toast('Say why — that sentence is the whole point'); return false; }
       logHours(args.projectId, args.hours, args.phaseIdx, args.note, args.date, f.why);
       render();
       toast(`Logged, and flagged as beyond the hours ${agreed ? 'agreed' : 'paid for'}`);
     }});
  if (typeof procWide === 'function') procWide(720);
  const m = document.getElementById('mbm'); if (!m) return;
  const ft = m.querySelector('.mbm-ft');
  if (ft) ft.insertAdjacentHTML('afterbegin',
    `<button class="btn" id="ds-ask">${agreed ? 'Ask the client to authorise more hours' : 'Invoice the next block'}</button>`);
  m.querySelector('#ds-ask')?.addEventListener('click', () => { mbCloseModal(); agreed ? dsAuthoriseModal(st) : dsTopUpModal(st); });
}

/* ---------- the two answers ---------- */
function dsTopUpModal(st){
  const suggest = Math.max(20, Math.ceil(Math.max(st.week * 4, r2(-st.leftPaid) + 20) / 5) * 5);
  mbModal(`More hours — ${esc(st.p.project.name)}`, `
    <p class="small muted" style="margin:0 0 10px">An invoice for the next block of hours, at the studio rate on the proposal. This is the cash side: the work is already inside what the client agreed to.</p>
    <div class="grid3">
      <div class="f"><label>Hours</label><input type="number" step="5" data-f="hours" value="${suggest}"></div>
      <div class="f"><label>Rate</label><input type="number" step="5" data-f="rate" value="${st.rate}"></div>
      <div class="f"><label>Due</label><input type="date" data-f="due" value="${iso(addDays(today(), 7))}"></div>
    </div>
    <div class="ds-mini">
      <div><span>Burned</span><b>${st.burned} h</b></div>
      <div><span>Paid for</span><b>${st.paidHours} h</b></div>
      <div><span>Agreed</span><b>${st.agreed || '—'} h</b></div>
      <div><span>At this pace</span><b>${st.week} h a week</b></div>
    </div>
    <p class="small muted" style="margin:8px 0 0">Enough to cover about four weeks at the current pace, and to clear anything already run past. It lands as a draft.</p>`,
    {submit: 'Draft the invoice', wide: true, onSubmit: f => {
      const hours = +f.hours || 0, rate = +f.rate || st.rate;
      if (!hours){ toast('How many hours?'); return false; }
      if (st.agreed && r2(st.burned + hours) > st.agreed)
        toast(`Note: ${st.agreed} hours were agreed — this block runs past that, so it needs the client's authorisation too`);
      const inv = typeof newDoc === 'function' ? newDoc(st.c, 'invoice', {mode: 'items'}) : null;
      if (!inv){ toast('Could not open an invoice'); return false; }
      inv.template = 'design'; inv.projectId = st.p.id; inv.retainerOf = st.est.id;
      inv.title = `Design hours — next ${hours} hours`;
      inv.due = f.due; inv.terms = 'Paid in advance of the hours being worked';
      inv.lines = [{id: uid('l'), item: 'Design services — hours in advance', qty: hours, unit: 'hr', rate,
                    desc: `${hours} hours at ${money(rate)} · ${st.burned} of ${st.paidHours} previously funded hours used`, taxable: false}];
      if (typeof docMark === 'function') docMark(inv);
      audit('invoice', inv.id, 'hours-topup-drafted', null, {project: st.p.id, hours, rate});
      save(); render();
      toast(`${hours} hours drafted — ${money(r2(hours * rate))}. It is a draft; nothing is sent.`);
    }});
  if (typeof procWide === 'function') procWide(720);
}
function dsAuthoriseModal(st){
  const over = r2(Math.max(0, -st.leftAgreed));
  const suggest = Math.max(20, Math.ceil((over + st.week * 4) / 5) * 5);
  mbModal(`More hours than agreed — ${esc(st.p.project.name)}`, `
    <p class="small">The proposal agreed <b>${st.agreed} hours</b>. ${over ? `${over} have already been worked past that.` : `${st.leftAgreed} are left.`}
    Hours beyond the agreement are not ours to bill until the client says yes to them, so this is a change to the proposal rather than an invoice.</p>
    <div class="grid3">
      <div class="f"><label>Additional hours</label><input type="number" step="5" data-f="hours" value="${suggest}"></div>
      <div class="f"><label>Rate</label><input type="number" step="5" data-f="rate" value="${st.rate}"></div>
    </div>
    <div class="f"><label>What they are for</label>
      <input data-f="what" placeholder="Third kitchen option, angled-tub study, roof-stair options"></div>
    <p class="small muted" style="margin:8px 0 0">This drafts a change order against the design proposal. Send it, get it back signed, and the ceiling moves — in that order.</p>`,
    {submit: 'Draft the change order', wide: true, onSubmit: f => {
      const hours = +f.hours || 0, rate = +f.rate || st.rate;
      if (!hours){ toast('How many hours?'); return false; }
      const co = typeof newDoc === 'function' ? newDoc(st.c, 'co', {}) : null;
      if (!co){ toast('Could not open a change order'); return false; }
      co.template = 'design'; co.projectId = st.p.id;
      co.title = `Additional design hours${f.what ? ' — ' + f.what : ''}`;
      co.lines = [{id: uid('l'), item: 'Additional design services', qty: hours, unit: 'hr', rate,
                   desc: f.what || `${hours} additional hours beyond the ${st.agreed} in the proposal`, taxable: false}];
      if (typeof docMark === 'function') docMark(co);
      audit('co', co.id, 'design-hours-requested', null, {project: st.p.id, hours, over});
      log(`${hours} additional design hours drafted for ${st.c.name} — ${st.p.project.name}`);
      save(); render();
      toast(`Change order drafted. The ceiling moves when it comes back signed, not before.`);
    }});
  if (typeof procWide === 'function') procWide(720);
}

/* ---------- the screen the billing team keeps open ---------- */
function dsPaneHtml(){
  const rows = dsAll();
  const lim = DS_LIMITS();
  const bad = rows.filter(r => r.state.startsWith('over') || r.state === 'unfunded');
  const watch = rows.filter(r => r.state.startsWith('watch'));
  const exposure = r2(rows.reduce((a, r) => a + Math.max(0, -r.leftPaid) * r.rate, 0));
  const stat = (v, s, cls) => `<div class="sel-stat"><b class="${cls || ''}">${v}</b><span>${s}</span></div>`;
  const bar = (used, total, cls) => { const pct = total ? Math.min(100, Math.round(used / total * 100)) : 0;
    return `<div class="ds-bar ${cls || ''}"><i style="width:${pct}%"></i></div>`; };

  const row = st => `<tr data-dsrow="${st.p.id}">
    <td><b>${esc(st.p.project.name)}</b><div class="small muted">${esc(st.c.name)} · ${money(st.rate)}/hr</div></td>
    <td class="n">${st.burned} h${st.unapproved ? `<div class="small muted">${st.unapproved} unapproved</div>` : ''}</td>
    <td>${st.paidHours ? `${st.leftPaid} left of ${st.paidHours}${bar(st.burned, st.paidHours, st.leftPaid <= 0 ? 'bad' : st.leftPaid <= lim.minHours ? 'warn' : '')}
         <div class="small ${st.leftPaid <= 0 ? 'bad' : 'muted'}">${st.runwayPaid != null ? (st.leftPaid > 0 ? `${st.runwayWord(st.runwayPaid)} at ${st.week} h/wk` : `${money(r2(-st.leftPaid * st.rate))} of our own money`) : 'no hours logged lately'}</div>`
       : '<span class="muted small">nothing collected yet</span>'}</td>
    <td>${st.agreed ? `${st.leftAgreed} left of ${st.agreed}${bar(st.burned, st.agreed, st.leftAgreed <= 0 ? 'bad' : st.leftAgreed <= lim.minHours ? 'warn' : '')}
         <div class="small ${st.leftAgreed <= 0 ? 'bad' : 'muted'}">${st.leftAgreed <= 0 ? 'unauthorised — needs the client' : st.runwayAgreed != null ? st.runwayWord(st.runwayAgreed) : ''}</div>`
       : '<span class="muted small">no hours on the proposal</span>'}</td>
    <td><span class="pill ${DS_STATE[st.state][0]}">${DS_STATE[st.state][1]}</span>
        ${st.binding ? `<div class="small muted">the binding ceiling is the hours ${st.binding === 'agreed' ? 'agreed' : 'paid for'}</div>` : ''}</td>
    <td>${st.leftAgreed <= lim.minHours && st.agreed ? `<button class="btn sm ${st.leftAgreed <= 0 ? 'primary' : ''}" data-dsauth="${st.p.id}">Ask the client</button>` : ''}
        ${st.paidHours && st.leftPaid <= lim.minHours ? `<button class="btn sm ${st.leftPaid <= 0 ? 'primary' : ''}" data-dstop="${st.p.id}">Invoice hours</button>` : ''}</td></tr>`;

  return `
  <div class="sel-stats">
    ${stat(bad.length, 'past a ceiling or unfunded', bad.length ? 'bad' : 'ok')}
    ${stat(watch.length, 'approaching one', watch.length ? 'warn' : '')}
    ${stat(exposure ? money(exposure) : '$0', 'studio time carried on our own money', exposure ? 'bad' : 'ok')}
    ${stat(`${lim.minHours} h · ${lim.warnPct}%`, 'warn at whichever comes first')}
  </div>

  <div class="pg-rule">
    <b>Two ceilings, and they are different problems.</b>
    <span class="small">Hours <b>paid for</b> is cash — running past it means the studio is working on our money, and the answer is an invoice. Hours <b>agreed</b> is scope — running past it means working on something the client never authorised, and the answer is their signature. Billing for the second is how a client ends up paying for something they never said yes to.</span>
  </div>

  ${bad.length || watch.length ? `<div class="cd-flags"><b>What somebody needs to do today</b>
    ${[...bad, ...watch].flatMap(st => dsChecks(st).filter(k => k.sev !== 'info').map(k =>
      `<div class="small ${k.sev === 'bad' ? 'bad' : ''}"><b>${esc(st.p.project.name)}</b> · ${k.who === 'billing' ? 'billing' : 'project lead'} — ${esc(k.msg)}</div>`)).join('')}</div>` : ''}

  <div class="row" style="gap:8px;margin:14px 0 8px"><h3 style="margin:0">Design hours</h3>
    <span class="small muted">Hours land here as the designers log them, and the guard runs before the entry is written, not after.</span>
    <span class="grow"></span><button class="btn sm" id="ds-policy">When to warn</button></div>
  <table class="t"><thead><tr><th>Job</th><th style="width:100px">Burned</th><th style="width:210px">Paid for</th><th style="width:210px">Agreed</th><th style="width:190px">Where it stands</th><th style="width:190px"></th></tr></thead>
    <tbody>${rows.map(row).join('') || `<tr><td colspan="6" class="muted small">No design proposals with hours on them yet.</td></tr>`}</tbody></table>
  <p class="small muted" style="margin:10px 0 0">Hours logged but not yet approved count against the block here — they have been spent whether or not anybody has signed them off.</p>`;
}
function dsWire(root){
  root.querySelectorAll('[data-dstop]').forEach(b => b.onclick = e => { e.stopPropagation();
    const st = dsStatus(DB.projects.find(x => x.id === b.dataset.dstop)); if (st) dsTopUpModal(st); });
  root.querySelectorAll('[data-dsauth]').forEach(b => b.onclick = e => { e.stopPropagation();
    const st = dsStatus(DB.projects.find(x => x.id === b.dataset.dsauth)); if (st) dsAuthoriseModal(st); });
  root.querySelectorAll('[data-dsrow]').forEach(tr => tr.addEventListener('click', ev => {
    if (ev.target.closest('button')) return;
    const st = dsStatus(DB.projects.find(x => x.id === tr.dataset.dsrow)); if (!st) return;
    const ks = dsChecks(st);
    mbModal(esc(st.p.project.name), `
      <div class="ds-mini">
        <div><span>Burned</span><b>${st.burned} h</b></div>
        <div><span>Paid for</span><b>${st.paidHours} h</b></div>
        <div><span>Agreed</span><b>${st.agreed || '—'} h</b></div>
        <div><span>Pace</span><b>${st.week} h a week</b></div>
        <div><span>Collected</span><b>${money(st.M.collected)}</b></div>
        <div><span>Invoiced, not collected</span><b>${money(st.M.unpaid)}</b></div>
      </div>
      ${ks.length ? ks.map(k => `<div class="rc-ink ${k.sev === 'bad' ? 'conflicts' : k.sev === 'warn' ? 'proposes' : 'unclear'}">
        <div class="small"><b>${k.who === 'billing' ? 'Billing' : 'Project lead'}</b> — ${esc(k.msg)}</div></div>`).join('')
        : '<p class="small muted">Inside both ceilings, with room to spare.</p>'}`, {submit: null});
    if (typeof procWide === 'function') procWide(720);
  }));
  root.querySelector('#ds-policy')?.addEventListener('click', () => {
    const lim = DS_LIMITS();
    mbModal('When to warn', `
      <p class="small muted" style="margin:0 0 10px">Whichever comes first — a percentage is right on a big block and useless on a small one, and a fixed number of hours is the reverse.</p>
      <div class="grid3">
        <div class="f"><label>Warn at</label><input type="number" data-f="warnPct" value="${lim.warnPct}"><span class="small muted">% burned</span></div>
        <div class="f"><label>or when fewer than</label><input type="number" data-f="minHours" value="${lim.minHours}"><span class="small muted">hours are left</span></div>
        <div class="f"><label>Act at</label><input type="number" data-f="actPct" value="${lim.actPct}"><span class="small muted">% burned</span></div>
      </div>`,
      {submit: 'Save', onSubmit: f => {
        DB.company.designLimits = {warnPct: +f.warnPct || 80, actPct: +f.actPct || 90, minHours: +f.minHours || 20, hardStop: true};
        audit('company', 'designLimits', 'changed', null, DB.company.designLimits);
        save(); renderSpend(); toast('Saved — it applies to every design job');
      }});
  });
}

if (typeof SP_TABS !== 'undefined') SP_TABS.push(['dhours', 'Design hours']);
if (typeof SP_GROUPS !== 'undefined'){ const g = SP_GROUPS.find(x => x[0] === 'day'); if (g && !g[2].includes('dhours')) g[2].push('dhours'); }
if (typeof spPane === 'function'){
  const spPaneBase_ds = spPane;
  spPane = function(ctx){ return spTab === 'dhours' ? dsPaneHtml() : spPaneBase_ds(ctx); };
}
if (typeof wireSpend === 'function'){
  const wireSpendBase_ds = wireSpend;
  wireSpend = function(root){ wireSpendBase_ds(root); if (spTab === 'dhours') try { dsWire(root); } catch (e){ console.error('design hours', e); } };
}
if (typeof spTabCount === 'function'){
  const spTabCountBase_ds = spTabCount;
  spTabCount = function(k){ if (k === 'dhours'){ try { return dsAll().filter(s => s.state !== 'ok').length; } catch (e){ return 0; } } return spTabCountBase_ds(k); };
}

/* ---------- and it reaches the people who are not looking at that screen ----------
   The designer sees it at the moment of logging. The billing team sees it on their own screen. Anybody
   else sees it here, which is the list the firm already reads every morning. */
if (typeof reminders === 'function'){
  const remindersBase_ds = reminders;
  reminders = function(){
    const out = remindersBase_ds();
    try {
      const rows = dsAll();
      const overAgreed = rows.filter(r => r.state === 'over-agreed');
      const overPaid = rows.filter(r => r.state === 'over-paid');
      const watch = rows.filter(r => r.state.startsWith('watch'));
      if (overAgreed.length) out.push({n: overAgreed.length, sev: 'bad',
        label: `design job${overAgreed.length === 1 ? '' : 's'} past the hours the client agreed to — ${overAgreed.map(r => r.p.project.name).join(', ')}`,
        go: {view: 'spend'}});
      if (overPaid.length) out.push({n: overPaid.length, sev: 'bad',
        label: `design job${overPaid.length === 1 ? '' : 's'} running on our own money — ${money(r2(overPaid.reduce((a, r) => a + -r.leftPaid * r.rate, 0)))} of studio time unfunded`,
        go: {view: 'spend'}});
      if (watch.length) out.push({n: watch.length, sev: 'warn',
        label: `design job${watch.length === 1 ? '' : 's'} approaching a ceiling — tell the client while it is still a choice`,
        go: {view: 'spend'}});
    } catch (e){}
    return out;
  };
}

/* The designer's own screen carries it too, above the log box, so the number is in front of them
   before they type an hour into it rather than after. */
if (typeof renderSDay === 'function'){
  const renderSDayBase_ds = renderSDay;
  renderSDay = function(){
    renderSDayBase_ds();
    try {
      const root = document.querySelector('#sday-body') || document.querySelector('#studio-body') || document.body;
      const box = root.querySelector('#st-addgo')?.closest('.card') || root.querySelector('.card');
      if (!box || box.querySelector('.ds-banner')) return;
      const rows = dsAll().filter(s => s.state !== 'ok');
      if (!rows.length) return;
      box.insertAdjacentHTML('afterbegin', `<div class="ds-banner">${rows.map(st => {
        const k = dsChecks(st).find(x => x.sev !== 'info');
        return `<div class="${st.state.startsWith('over') ? 'bad' : 'warn'}"><b>${esc(st.p.project.name)}</b> — ${esc(k ? k.msg : '')}</div>`;
      }).join('')}</div>`);
    } catch (e){}
  };
}
/*<</dsn.js>>*/

/*<<filing.js>>*/
/* ===================== THE OTHER HALF OF THE PROPOSAL =====================
   A design proposal has two halves and they behave nothing alike. Design is a block of HOURS, paid in
   advance and burned down. Filings are FIXED PRICES, and they are billed against milestones that the
   agencies decide, not us.

   On 140 Prospect that is $111,000 across five filings — Alteration-CO $45,000, LPC rear windows
   $27,000, ALT-2 $15,000, demolition $12,000, framing $12,000 — and the stages are:

       50%  deposit, up front
       30%  on submission
       10%  on approval
       10%  on sign-off

   Nothing has ever tracked whether those stages were billed as they were hit. The app already knows
   when a filing was submitted and when it was approved — it is on the filing record, with dates. So
   the money is not a judgement call: **a stage the agency has already granted us is a stage that is
   billable today, and the only reason it goes uninvoiced is that nobody was looking.**

   This is the design-hours guard pointed the other way. That one stops the firm spending past what was
   agreed. This one stops it leaving money on the table it has already earned. */

const FIL_STAGES = [
  ['deposit',   'Deposit',    50, 'up front, before the work starts'],
  ['submitted', 'Submitted',  30, 'the application is in'],
  ['approval',  'Approved',   10, 'the agency has approved it'],
  ['signoff',   'Signed off', 10, 'closed out — the letter or the CO'],
];
const filPct = k => (FIL_STAGES.find(s => s[0] === k) || [, , 0])[2];

function filInit(){
  if (!DB.studio || !DB.studio.filings) return;
  DB.studio.filings.forEach(f => {
    const b = f.billed || {};
    /* The record shipped with three flags under older names and no sign-off at all. Carry them across
       rather than dropping what was already marked billed. */
    f.billed = {deposit: !!(b.deposit ?? b.start), submitted: !!(b.submitted ?? b.submit),
                approval: !!(b.approval ?? b.approve), signoff: !!b.signoff};
    if (f.signedOffOn === undefined) f.signedOffOn = '';
  });
}
const filAll = pid => { filInit(); return ((DB.studio && DB.studio.filings) || []).filter(f => !pid || f.projectId === pid); };

/* When a stage becomes ours to bill.

   THE DEPOSIT IS DUE AT SIGNING, NOT WHEN THE FILING STARTS. The first build of this gated it on the
   filing being in prep, which is backwards: 50% up front is what FUNDS starting it. On 140 Prospect the
   retainer and half the filings were invoiced the Tuesday after the kickoff, weeks before anything
   reached an agency. So the deposit turns on the proposal being accepted — which is the same event the
   client signed — and the other three turn on dates the agency has already put on the record. */
const filAccepted = f => {
  const p = DB.projects.find(x => x.id === f.projectId);
  const est = p && typeof designEst === 'function' ? designEst(p) : null;
  return !!est && ['approved', 'converted', 'billed'].includes(est.status);
};
function filEarned(f){
  return {
    deposit:   filAccepted(f) || !!f.startedOn || ['in-prep', 'submitted', 'objections', 'approved'].includes(f.status),
    submitted: !!(f.submittedOn || ['submitted', 'objections', 'approved'].includes(f.status)),
    approval:  !!(f.approvedOn || f.status === 'approved'),
    signoff:   !!f.signedOffOn,
  };
}
function filRow(f){
  const earned = filEarned(f), fee = +f.fee || 0;
  const ahead = f.ahead || {};
  const stages = FIL_STAGES.map(([k, label, pct, why]) => ({
    k, label, pct, why, amount: r2(fee * pct / 100),
    earned: earned[k], billed: !!(f.billed || {})[k], ahead: !!ahead[k],
    due: earned[k] && !(f.billed || {})[k],
    on: k === 'submitted' ? f.submittedOn : k === 'approval' ? f.approvedOn : k === 'signoff' ? f.signedOffOn : (filAccepted(f) ? 'at signing' : f.startedOn),
  }));
  const due = stages.filter(s => s.due);
  const billedAmt = r2(stages.filter(s => s.billed).reduce((a, s) => a + s.amount, 0));
  const earnedAmt = r2(stages.filter(s => s.earned).reduce((a, s) => a + s.amount, 0));
  return {f, fee, stages, due,
          billedAmt, dueAmt: r2(due.reduce((a, s) => a + s.amount, 0)), earnedAmt,
          /* Money taken for work not yet performed. It is legitimate — it is what the contract says —
             but it is the firm holding the client's money against a promise, and a firm that cannot
             see that number cannot answer for it. */
          unearned: r2(Math.max(0, billedAmt - earnedAmt)),
          canBillAhead: stages.filter(s => !s.earned && !s.billed),
          project: DB.projects.find(p => p.id === f.projectId)};
}
const filRows = pid => filAll(pid).map(filRow).sort((a, b) => b.dueAmt - a.dueAmt || b.fee - a.fee);
const filDue = pid => filRows(pid).filter(r => r.dueAmt > 0);

/* ---------- one invoice, every stage that is due ----------
   Five filings hitting stages on their own schedules is not five invoices. It is one invoice with a
   line per stage, which is also how the client reads their own proposal. */
/* `picks` is a list of "filingId:stage" when billing has chosen exactly what goes on the document —
   which is how a stage gets pulled forward. Without it, everything earned and unbilled goes on. */
function filInvoice(pid, keys, picks){
  const all = filRows(pid);
  const want = picks ? new Set(picks) : null;
  const rows = (want ? all : filDue(pid).filter(r => !keys || keys.includes(r.f.id)))
    .map(r => want ? Object.assign({}, r, {due: r.stages.filter(s => !s.billed && want.has(r.f.id + ':' + s.k))}) : r)
    .filter(r => r.due.length);
  if (!rows.length){ toast('Nothing selected'); return null; }
  const p = DB.projects.find(x => x.id === (pid || S.id));
  const c = DB.clients.find(x => x.id === (p && p.clientId));
  if (!c){ toast('No client on this job'); return null; }
  const inv = typeof newDoc === 'function' ? newDoc(c, 'invoice', {mode: 'items'}) : null;
  if (!inv) return null;
  inv.template = 'design'; inv.projectId = p.id;
  inv.title = `Filings — ${rows.reduce((a, r) => a + r.due.length, 0)} stage${rows.reduce((a, r) => a + r.due.length, 0) === 1 ? '' : 's'} due`;
  inv.terms = 'Net 15';
  inv.lines = rows.flatMap(r => r.due.map(s => ({
    id: uid('l'), item: `${r.f.name} — ${s.label.toLowerCase()}`,
    desc: `${s.pct}% of ${money(r.fee)}${s.on ? ` · ${s.label.toLowerCase()} ${s.on}` : ''}`,
    qty: 1, unit: 'ls', rate: s.amount, taxable: false, filingId: r.f.id, filingStage: s.k,
    ahead: !s.earned})));
  if (typeof docMark === 'function') docMark(inv);
  rows.forEach(r => r.due.forEach(s => {
    r.f.billed[s.k] = true;
    if (!s.earned){ r.f.ahead = r.f.ahead || {}; r.f.ahead[s.k] = true;
      audit('filing', r.f.id, 'billed-ahead', null, {stage: s.k, amount: s.amount}); }
  }));
  audit('invoice', inv.id, 'filing-stages-billed', null,
        {project: p.id, stages: inv.lines.length, total: r2(inv.lines.reduce((a, l) => a + l.rate, 0))});
  log(`${inv.lines.length} filing stage${inv.lines.length === 1 ? '' : 's'} invoiced on ${p.project.name} — ${money(r2(inv.lines.reduce((a, l) => a + l.rate, 0)))}`);
  save();
  return inv;
}

/* ---------- the section ---------- */
function filPaneHtml(pid){
  const rows = filRows(pid);
  if (!rows.length) return '';
  const fee = r2(rows.reduce((a, r) => a + r.fee, 0));
  const billed = r2(rows.reduce((a, r) => a + r.billedAmt, 0));
  const due = r2(rows.reduce((a, r) => a + r.dueAmt, 0));

  const unearned = r2(rows.reduce((a, r) => a + r.unearned, 0));
  const chip = (r, s) => `<span class="fil-st ${s.billed ? (s.ahead ? 'aheadb' : 'done') : s.due ? 'due' : s.earned ? 'earned' : ''}"
      title="${esc(s.why)}${s.on ? ' — ' + esc(s.on) : ''}">${s.pct}% ${esc(s.label)}${s.billed ? (s.ahead ? ' ✓ ahead' : ' ✓') : s.due ? ' · due' : ''}</span>`;

  const row = r => `<tr>
    <td><b>${esc(r.f.name)}</b><div class="small muted">${esc((r.project && r.project.project.name) || '')} · ${esc(r.f.status)}</div></td>
    <td class="n">${money(r.fee)}</td>
    <td><div class="fil-stages">${r.stages.map(s => chip(r, s)).join('')}</div></td>
    <td class="n">${money(r.billedAmt)}<div class="small muted">of ${money(r.earnedAmt)} earned</div></td>
    <td class="n">${r.dueAmt ? `<b class="bad">${money(r.dueAmt)}</b>` : '<span class="muted">—</span>'}</td></tr>`;

  return `
  <h3 style="margin:22px 0 4px">Filings</h3>
  <p class="small muted" style="margin:0 0 8px">Fixed prices, billed against milestones the agencies decide.
    ${FIL_STAGES.map(([, l, p]) => `${p}% ${l.toLowerCase()}`).join(' · ')}.
    A stage the agency has already granted is billable today; the only reason it goes uninvoiced is that nobody was looking.</p>
  ${unearned ? `<div class="dp-note"><div><b>${money(unearned)} invoiced ahead of the work.</b> That is the contract — half up front is what funds starting — but it is the client's money held against a promise. It clears itself as each filing is submitted and approved.</div></div>` : ''}
  ${due ? `<div class="cd-flags"><b>${money(due)} of filing work is earned and not invoiced</b>
    ${rows.filter(r => r.dueAmt).map(r => `<div class="small">${esc(r.f.name)} — ${r.due.map(s => `${s.label.toLowerCase()}${s.on ? ' ' + s.on : ''} (${money(s.amount)})`).join(', ')}</div>`).join('')}
    <button class="btn sm primary" id="fil-bill" style="margin-top:8px">Invoice ${money(due)} on one document</button></div>`
    : `<div class="row" style="margin:8px 0"><span class="small muted">Nothing is earned and unbilled.</span><span class="grow"></span><button class="btn sm" id="fil-bill">Bill a stage early</button></div>`}
  <table class="t"><thead><tr><th>Filing</th><th style="width:110px">Fee</th><th style="width:400px">Stages</th><th style="width:130px">Invoiced</th><th style="width:110px">Due now</th></tr></thead>
    <tbody>${rows.map(row).join('')}
      <tr style="font-weight:600"><td>Total</td><td class="n">${money(fee)}</td><td></td><td class="n">${money(billed)}</td><td class="n">${due ? money(due) : '—'}</td></tr></tbody></table>`;
}
function filWire(root, pid){
  root.querySelector('#fil-bill')?.addEventListener('click', () => {
    const rows = filRows(pid).filter(r => r.stages.some(s => !s.billed));
    if (!rows.length){ toast('Every stage on every filing has been invoiced'); return; }
    /* Every unbilled stage, not only the earned ones. What is earned is ticked; what is not is offered
       with the consequence written next to it, because billing for a stage before it happens is a
       legitimate thing this contract does and a promise the firm then owes. */
    const line = (r, s) => `<tr class="${s.earned ? '' : 'fil-ahead'}">
      <td><input type="checkbox" data-filp="${esc(r.f.id + ':' + s.k)}" data-amt="${s.amount}" ${s.earned ? 'checked' : ''}></td>
      <td>${esc(r.f.name)}</td>
      <td>${s.pct}% · ${esc(s.label.toLowerCase())}</td>
      <td>${s.earned ? `<span class="small ok">earned${s.on ? ' · ' + esc(String(s.on)) : ''}</span>`
                     : `<span class="small warn">not yet — billing this is money taken against a promise</span>`}</td>
      <td class="n">${money(s.amount)}</td></tr>`;
    mbModal('What goes on this invoice', `
      <p class="small muted" style="margin:0 0 8px">One document, a line per stage. Everything the agency has already granted is ticked. Anything below it can be pulled forward — half up front is what the contract says, and it is what funds starting the work.</p>
      <table class="t"><thead><tr><th></th><th>Filing</th><th>Stage</th><th>Where it stands</th><th style="width:110px">Amount</th></tr></thead><tbody>
      ${rows.map(r => r.stages.filter(s => !s.billed).map(s => line(r, s)).join('')).join('')}
      </tbody></table>
      <div class="row" style="margin-top:10px"><button class="btn sm" id="fil-half">Tick every deposit</button>
        <span class="grow"></span><b id="fil-tot"></b></div>
      <p class="small muted" style="margin:8px 0 0">Anything invoiced before it is earned is marked as such on the filing, so the firm can always say how much of the client's money is being held against work not yet done.</p>`,
      {submit: 'Draft it', wide: true, onSubmit: () => {
        const picks = [...document.querySelectorAll('[data-filp]:checked')].map(x => x.dataset.filp);
        if (!picks.length){ toast('Nothing ticked'); return false; }
        const inv = filInvoice(pid, null, picks);
        if (inv){ render(); toast(`${inv.lines.length} stage${inv.lines.length === 1 ? '' : 's'} drafted — ${money(r2(inv.lines.reduce((a, l) => a + l.rate, 0)))}`); }
      }});
    if (typeof procWide === 'function') procWide(880);
    const m = document.getElementById('mbm'); if (!m) return;
    const tot = () => { const n = [...m.querySelectorAll('[data-filp]:checked')].reduce((a, x) => a + (+x.dataset.amt || 0), 0);
      const el = m.querySelector('#fil-tot'); if (el) el.textContent = money(r2(n)); };
    m.querySelectorAll('[data-filp]').forEach(x => x.addEventListener('change', tot));
    m.querySelector('#fil-half')?.addEventListener('click', () => {
      m.querySelectorAll('[data-filp]').forEach(x => { if (x.dataset.filp.endsWith(':deposit')) x.checked = true; }); tot(); });
    tot();
  });
}

/* It reaches the morning list too — an approved filing whose 10% was never invoiced is money the firm
   has already earned and is quietly lending to the client. */
if (typeof reminders === 'function'){
  const remindersBase_fil = reminders;
  reminders = function(){
    const out = remindersBase_fil();
    try {
      const rows = filDue();
      const amt = r2(rows.reduce((a, r) => a + r.dueAmt, 0));
      if (amt) out.push({n: rows.reduce((a, r) => a + r.due.length, 0), sev: 'warn',
        label: `filing stages earned and not invoiced — ${money(amt)}`, go: {view: 'spend'}});
    } catch (e){}
    return out;
  };
}
/*<</filing.js>>*/

/*<<dphase.js>>*/
/* ===================== HOURS AGAINST THE LINE THEY WERE SPENT ON =====================
   Alan: *"The hours should go against each phase. When the designer enters their hours for the day it
   should match the line items on the proposal. We should get alerts by phase but it doesn't mean we
   need to act on it if the design team thinks we will be under the total estimated hours."*

   That last sentence is the whole design of this, and it is easy to get wrong. A phase over its
   estimate is INFORMATION. The job over its total is a PROBLEM. Design development running 12 hours
   past its 210 while the job still has 140 hours in hand is a studio spending its budget in a
   different order than it guessed — which is normal, and stopping work over it would be absurd.

   So: **the phase warns, the job stops.** And a phase warning is never shown alone — it is shown with
   where the job stands, because that is the sentence that lets somebody decide not to act:

       "Design development is 12 hours past its 210. The job is still 140 under its 404."

   The other case Alan named is the one that actually costs money: *"Clients will bring things up like
   the stairs to the roof which was not initially scoped, and as long as we notify the client that it
   will take them over the hours we estimated, that is fine."* Work that is not on the proposal at all
   has no phase to go against, so the log asks for that explicitly rather than quietly filing it under
   whatever phase is open — and the moment it is logged, it offers the notification. The 50–60 hours of
   roof-stair study never becomes a surprise, because it was named as out of scope on the day it
   started. */

const dpLines = est => ((est && est.lines) || []).filter(l => l.unit === 'hr');
const DP_NONE = '__unscoped';

/* Hours land on a phase by the line the designer chose. Older entries carry an index into the hour
   lines instead, so both are read — a record written before this existed is still worth counting. */
function dpUsed(p, est){
  const staff = (DB.employees || []).filter(e => typeof isDesignStaff === 'function' ? isDesignStaff(e) : (+e.billRate || 0) > 0).map(e => e.id);
  const lines = dpLines(est);
  const h = t => (typeof hoursOf === 'function' ? hoursOf(t) : 0);
  const by = {}; lines.forEach(l => by[l.id] = 0);
  by[DP_NONE] = 0;
  (DB.time || []).filter(t => t.projectId === p.id && staff.includes(t.empId)).forEach(t => {
    let key = t.phaseLine && (by[t.phaseLine] !== undefined || t.phaseLine === DP_NONE) ? t.phaseLine : null;
    if (!key && t.outOfScope) key = DP_NONE;
    if (!key && t.phase != null && lines[t.phase]) key = lines[t.phase].id;
    if (!key) key = lines.length ? lines[0].id : DP_NONE;
    by[key] = r2((by[key] || 0) + h(t));
  });
  return by;
}
function dpRows(p){
  const est = typeof designEst === 'function' ? designEst(p) : null; if (!est) return [];
  const by = dpUsed(p, est);
  const lim = typeof DS_LIMITS === 'function' ? DS_LIMITS() : {warnPct: 80, minHours: 20};
  return dpLines(est).map(l => {
    const agreed = +l.qty || 0, used = r2(by[l.id] || 0), left = r2(agreed - used);
    const pct = agreed ? Math.round(used / agreed * 100) : null;
    const state = agreed <= 0 ? 'none' : left < 0 ? 'over'
      : (left <= lim.minHours || pct >= lim.warnPct) ? 'watch' : 'ok';
    return {line: l, id: l.id, name: l.item || l.desc || 'Phase', agreed, used, left, pct, state,
            rate: +l.rate || 0};
  });
}
const dpUnscoped = p => { const est = typeof designEst === 'function' ? designEst(p) : null;
  return est ? r2(dpUsed(p, est)[DP_NONE] || 0) : 0; };

/* The sentence. A phase over its estimate on a job that is still comfortably inside its total is a
   note; the same phase on a job with nothing left is the beginning of a conversation. */
function dpVerdict(p){
  const st = typeof dsStatus === 'function' ? dsStatus(p) : null;
  const rows = dpRows(p);
  const over = rows.filter(r => r.state === 'over');
  const watch = rows.filter(r => r.state === 'watch');
  const unscoped = dpUnscoped(p);
  const out = [];
  if (over.length && st){
    const jobLeft = st.leftAgreed;
    out.push({sev: jobLeft > 0 ? 'info' : 'bad', kind: 'phase-over',
      msg: `${over.map(r => `${r.name} is ${r2(-r.left)} hours past its ${r.agreed}`).join('; ')}. ` +
           (jobLeft > 0
             ? `The job is still ${jobLeft} hours under its ${st.agreed}, so this may be nothing more than the work happening in a different order than we guessed.`
             : `And the job has nothing left — ${r2(-jobLeft)} hours past its ${st.agreed}. This one is not a note.`)});
  }
  if (watch.length)
    out.push({sev: 'info', kind: 'phase-watch',
      msg: `${watch.map(r => `${r.name} has ${r.left} of ${r.agreed} left`).join('; ')}.`});
  if (unscoped > 0)
    out.push({sev: 'warn', kind: 'unscoped',
      msg: `${unscoped} hours logged as not on the proposal${st ? ` — ${money(r2(unscoped * st.rate))} at the studio rate` : ''}. The client agreed to none of these; they need to know before it becomes a bill.`});
  return out;
}

/* ---------- the log, against a line of the proposal ---------- */
function dpOptions(p){
  const est = typeof designEst === 'function' ? designEst(p) : null;
  const rows = dpRows(p);
  return {est, rows, has: !!est};
}
function dpSelectHtml(p, sel){
  const {rows, has} = dpOptions(p);
  if (!has) return '';
  return `<select id="st-addphase" title="Which line of the proposal">
    ${rows.map(r => `<option value="${esc(r.id)}" ${sel === r.id ? 'selected' : ''}>${esc(r.name)}${r.agreed ? ` — ${r.left} of ${r.agreed} left` : ''}</option>`).join('')}
    <option value="${DP_NONE}" ${sel === DP_NONE ? 'selected' : ''}>Not on the proposal</option>
  </select>`;
}

/* The guard, extended. The job total still stops the entry; a phase only ever speaks. */
if (typeof dsGuard === 'function'){
  const dsGuardBase_dp = dsGuard;
  dsGuard = function(projectId, hours, phaseLine){
    const g = dsGuardBase_dp(projectId, hours);
    try {
      const p = DB.projects.find(x => x.id === projectId);
      if (!p || !phaseLine) return g;
      if (phaseLine === DP_NONE){
        g.unscoped = true;
        g.note = `${hours} h logged as not on the proposal — the client has agreed to none of it`;
        return g;
      }
      const r = dpRows(p).find(x => x.id === phaseLine);
      if (!r || !r.agreed) return g;
      const after = r2(r.used + (+hours || 0));
      if (after > r.agreed){
        const st = typeof dsStatus === 'function' ? dsStatus(p) : null;
        const jobLeft = st ? r2(st.agreed - (st.burned + (+hours || 0))) : null;
        g.phase = {name: r.name, agreed: r.agreed, after, over: r2(after - r.agreed), jobLeft};
        g.note = `${r.name} is now ${r2(after - r.agreed)} hours past its ${r.agreed}` +
                 (jobLeft != null ? (jobLeft > 0 ? ` — the job still has ${jobLeft} of ${st.agreed}` : ` — and the job is out of hours`) : '');
      }
    } catch (e){}
    return g;
  };
}
/* Carry the chosen line onto the entry, so tomorrow's report does not have to guess. */
if (typeof logHours === 'function'){
  const logHoursBase_dp = logHours;
  logHours = function(projectId, hours, phaseIdx, note, date, force, phaseLine){
    const e = logHoursBase_dp(projectId, hours, phaseIdx, note, date, force);
    if (e && phaseLine){
      e.phaseLine = phaseLine;
      if (phaseLine === DP_NONE){
        e.outOfScope = true;
        audit('time', e.id, 'logged-out-of-scope', null, {projectId, hours});
      }
      save();
    }
    return e;
  };
}

/* ---------- the designer's own screen ----------
   The phase select sits next to the hours box, and the option itself carries what is left, so the
   number is in front of them at the moment they choose the line rather than in a report afterwards. */
if (typeof renderSDay === 'function'){
  const renderSDayBase_dp = renderSDay;
  renderSDay = function(){
    renderSDayBase_dp();
    try {
      const root = document.querySelector('#sday-body') || document.querySelector('#studio-body') || document.body;
      const hrs = root.querySelector('#st-addh'); const go = root.querySelector('#st-addgo');
      const proj = root.querySelector('#st-addp');
      if (!hrs || !go || !proj || root.querySelector('#st-addphase')) return;
      const draw = () => {
        const p = DB.projects.find(x => x.id === proj.value);
        const old = root.querySelector('#st-addphase'); if (old) old.remove();
        const html = p ? dpSelectHtml(p) : '';
        if (html) hrs.insertAdjacentHTML('afterend', html);
      };
      draw();
      proj.addEventListener('change', draw);
      /* Take the click before the base handler: the base picks a phase by guessing which one is open,
         and the whole point is that the person doing the work says which line it was. */
      const fresh = go.cloneNode(true); go.parentNode.replaceChild(fresh, go);
      fresh.addEventListener('click', () => {
        const h = +hrs.value; if (!h){ toast('How many hours?'); return; }
        const pid = proj.value;
        const sel = root.querySelector('#st-addphase');
        const phaseLine = sel ? sel.value : '';
        const p = DB.projects.find(x => x.id === pid);
        const est = p && typeof designEst === 'function' ? designEst(p) : null;
        const idx = est && phaseLine && phaseLine !== DP_NONE
          ? Math.max(0, dpLines(est).findIndex(l => l.id === phaseLine)) : 0;
        const noteEl = root.querySelector('#st-addn');
        const e = logHours(pid, h, idx, (noteEl && noteEl.value) || 'Design', today(), false, phaseLine);
        if (e){
          const g = dsGuard(pid, 0, phaseLine);
          if (g && g.unscoped) dpUnscopedModal(p, h, e);
          else if (g && g.phase) toast(g.note);
          else toast(`${h} h logged`);
          hrs.value = ''; if (noteEl) noteEl.value = '';
          renderSDay();
        }
      });
    } catch (e){}
  };
}

/* Work nobody agreed to, named on the day it happens. */
function dpUnscopedModal(p, hours, entry){
  const st = typeof dsStatus === 'function' ? dsStatus(p) : null;
  const un = dpUnscoped(p);
  mbModal('This is not on the proposal', `
    <div class="ds-cross">
      <b>${hours} hours on ${esc(p.project.name)}, against no line of the proposal.</b>
      <div>${un} hours in total now sit outside the agreed scope${st ? ` — ${money(r2(un * st.rate))} at ${money(st.rate)} an hour` : ''}.</div>
    </div>
    <p class="small">This is the roof-stair case: the client asks for something that was never scoped, the studio does it, and the conversation happens when the invoice arrives. It does not have to. Telling them today, while it is a choice, costs one email — and the hours are fine as long as they know.</p>
    <div class="f"><label>What was it for</label><input data-f="what" value="${esc(entry && entry.notes || '')}" placeholder="Roof-stair options — Cambri asked on the 5th"></div>
    <p class="small muted" style="margin:8px 0 0">The hours stay logged either way. What changes is whether the client hears about them now or at the end.</p>`,
    {submit: 'Note it and carry on', wide: true, onSubmit: f => {
      if (entry){ entry.notes = f.what || entry.notes; save(); }
      toast('Logged as outside the proposal');
    }});
  if (typeof procWide === 'function') procWide(720);
  const m = document.getElementById('mbm'); if (!m) return;
  const ft = m.querySelector('.mbm-ft');
  if (ft) ft.insertAdjacentHTML('afterbegin', `<button class="btn primary" id="dp-tell">Draft the client's authorisation now</button>`);
  m.querySelector('#dp-tell')?.addEventListener('click', () => {
    mbCloseModal();
    if (st && typeof dsAuthoriseModal === 'function') dsAuthoriseModal(st);
  });
}

/* ---------- the phases, on the billing screen ---------- */
function dpPaneHtml(p){
  const rows = dpRows(p); if (!rows.length) return '';
  const v = dpVerdict(p);
  const un = dpUnscoped(p);
  const bar = r => { const pct = r.agreed ? Math.min(100, Math.round(r.used / r.agreed * 100)) : 0;
    return `<div class="ds-bar ${r.state === 'over' ? 'bad' : r.state === 'watch' ? 'warn' : ''}"><i style="width:${pct}%"></i></div>`; };
  const row = r => `<tr>
    <td><b>${esc(r.name)}</b></td>
    <td class="n">${r.agreed} h</td>
    <td class="n">${r.used} h</td>
    <td>${r.left < 0 ? `<b class="${r.state === 'over' ? 'warn' : ''}">${r2(-r.left)} over</b>` : `${r.left} left`}${bar(r)}</td>
    <td class="n">${r.pct == null ? '' : r.pct + '%'}</td></tr>`;
  return `
  <h3 style="margin:22px 0 4px">By phase — ${esc(p.project.name)}</h3>
  <p class="small muted" style="margin:0 0 8px">Hours go against the line of the proposal they were spent on. <b>The phase warns; the job stops.</b> A phase running past its estimate on a job that is still inside its total is the work happening in a different order than we guessed, not a problem.</p>
  ${v.length ? `<div class="dp-note">${v.map(x => `<div class="${x.sev === 'bad' ? 'bad' : x.sev === 'warn' ? 'warn' : ''}">${esc(x.msg)}</div>`).join('')}</div>` : ''}
  <table class="t"><thead><tr><th>Phase</th><th style="width:90px">Agreed</th><th style="width:90px">Used</th><th style="width:220px">Left</th><th style="width:70px"></th></tr></thead>
    <tbody>${rows.map(row).join('')}
    ${un ? `<tr><td><b>Not on the proposal</b><div class="small muted">nobody agreed to these</div></td><td class="n">—</td><td class="n">${un} h</td><td><span class="warn small">needs the client's word</span></td><td></td></tr>` : ''}
    </tbody></table>`;
}

/* Both halves of the proposal on one screen, because that is how the document reads. */
if (typeof SP_TABS !== 'undefined'){ const t = SP_TABS.find(x => x[0] === 'dhours'); if (t) t[1] = 'Design & filings'; }
if (typeof dsPaneHtml === 'function'){
  const dsPaneBase_dp = dsPaneHtml;
  dsPaneHtml = function(){
    const p = DB.projects.find(x => x.id === (spProj === 'all' ? S.id : spProj)) || S;
    let out = dsPaneBase_dp();
    try {
      const rows = (typeof dsAll === 'function' ? dsAll() : []);
      const pick = rows.find(r => r.p.id === p.id) || rows[0];
      if (pick) out += dpPaneHtml(pick.p);
      if (typeof filPaneHtml === 'function') out += filPaneHtml(pick ? pick.p.id : p.id);
    } catch (e){}
    return out;
  };
}
if (typeof dsWire === 'function'){
  const dsWireBase_dp = dsWire;
  dsWire = function(root){
    dsWireBase_dp(root);
    try {
      const rows = (typeof dsAll === 'function' ? dsAll() : []);
      const p = DB.projects.find(x => x.id === (spProj === 'all' ? S.id : spProj)) || S;
      const pick = rows.find(r => r.p.id === p.id) || rows[0];
      if (typeof filWire === 'function') filWire(root, pick ? pick.p.id : p.id);
    } catch (e){}
  };
}
/*<</dphase.js>>*/

/*<<deposit.js>>*/
/* ===================== THE DEPOSIT, THE DAY IT IS SIGNED =====================
   Alan: *"We usually take the deposit as soon as the contract has been signed."*

   The two halves of a design proposal are billed on different clocks after that day — hours are drawn
   down as they are worked, filings are billed as the agencies grant each stage — but on the day itself
   there is only one thing to do: raise half the contract, on one document, and send it.

   The app could already do that in two places and neither of them was the day of signing: the design
   half through a retainer or a milestone invoice, the filings half through their deposit stage. So
   billing had to know both, in the right order, and remember which half had already been touched.

   THE RULE THAT KEEPS IT SAFE: half of everything signed, LESS ANYTHING ALREADY INVOICED AGAINST IT.
   140 Prospect has a $24,000 retainer already out. A blunt "50% of $191,800" would ask the client for
   $95,900 and quietly bill that retainer twice. What is actually outstanding to reach half is $16,400
   on the design and $55,500 on the filings — and that is what the invoice says. */

const DEP_PCT = () => +((DB.company && DB.company.depositPct) || 50);

function depPlan(p, pct){
  const est = typeof designEst === 'function' ? designEst(p) : null; if (!est) return null;
  const c = DB.clients.find(x => x.id === p.clientId); if (!c) return null;
  pct = pct == null ? DEP_PCT() : +pct;

  const hrLines = (est.lines || []).filter(l => l.unit === 'hr');
  const feeLines = (est.lines || []).filter(l => l.unit !== 'hr');
  const amt = l => (typeof lineAmount === 'function' ? lineAmount(l, est) : (+l.qty || 0) * (+l.rate || 0));
  const designFee = r2(hrLines.reduce((a, l) => a + amt(l), 0));
  const filingFee = r2(feeLines.reduce((a, l) => a + amt(l), 0));

  /* What each half has already been asked for. Filing invoicing is tracked stage by stage on the
     filing record, so that half is exact; everything else invoiced on the job belongs to the design
     half, which is the cautious way round — it can only make us ask for less. */
  const filRowsHere = typeof filRows === 'function' ? filRows(p.id) : [];
  const filingInvoiced = r2(filRowsHere.reduce((a, r) => a + r.billedAmt, 0));
  const projInvoiced = r2((c.invoices || []).filter(i => i.status !== 'void' && (i.projectId || '') === (p.id || ''))
    .reduce((a, i) => a + (typeof docTotal === 'function' ? docTotal(i).total : 0), 0));
  const designInvoiced = r2(Math.max(0, projInvoiced - filingInvoiced));

  const designTarget = r2(designFee * pct / 100);
  const filingTarget = r2(filingFee * pct / 100);
  const designDue = r2(Math.max(0, designTarget - designInvoiced));
  const filingDue = r2(Math.max(0, filingTarget - filingInvoiced));

  const rate = typeof dsRate === 'function' ? dsRate(est) : 0;
  const stages = filRowsHere.map(r => ({r, stage: r.stages.find(s => s.k === 'deposit')}))
    .filter(x => x.stage && !x.stage.billed);

  return {p, c, est, pct, designFee, filingFee, contract: r2(designFee + filingFee),
          designInvoiced, filingInvoiced, designTarget, filingTarget, designDue, filingDue,
          total: r2(designDue + filingDue), rate,
          buysHours: rate ? r2(designDue / rate) : 0, stages,
          retainer: +est.retainer || 0};
}

function depInvoice(p, opts){
  opts = opts || {};
  const plan = depPlan(p, opts.pct); if (!plan) return null;
  const design = opts.design !== false ? plan.designDue : 0;
  const doFilings = opts.filings !== false;
  const lines = [];
  if (design > 0) lines.push({id: uid('l'), item: `Design services — ${plan.pct}% at signing`,
    desc: `${plan.pct}% of ${money(plan.designFee)}${plan.designInvoiced ? ` less ${money(plan.designInvoiced)} already invoiced` : ''} · funds about ${plan.buysHours} hours at ${money(plan.rate)}`,
    qty: 1, unit: 'ls', rate: design, taxable: false, depositHalf: 'design'});
  if (doFilings) plan.stages.forEach(({r, stage}) => lines.push({
    id: uid('l'), item: `${r.f.name} — ${stage.pct}% deposit`,
    desc: `${stage.pct}% of ${money(r.fee)} · due at signing`,
    qty: 1, unit: 'ls', rate: stage.amount, taxable: false,
    filingId: r.f.id, filingStage: 'deposit', depositHalf: 'filings'}));
  if (!lines.length){ toast('Nothing outstanding to reach the deposit'); return null; }

  const inv = typeof newDoc === 'function' ? newDoc(plan.c, 'invoice', {mode: 'items'}) : null;
  if (!inv) return null;
  inv.template = 'design'; inv.projectId = p.id; inv.retainerOf = plan.est.id;
  inv.title = `Deposit at signing — ${plan.pct}% of the contract`;
  inv.terms = 'Due on signing';
  inv.due = today();
  inv.lines = lines;
  if (typeof docMark === 'function') docMark(inv);
  /* Mark the filing deposits billed here rather than leaving them to be raised a second time on the
     filings screen. One action, both ledgers straight. */
  if (doFilings) plan.stages.forEach(({r, stage}) => {
    r.f.billed = r.f.billed || {}; r.f.billed.deposit = true;
    if (!stage.earned){ r.f.ahead = r.f.ahead || {}; r.f.ahead.deposit = true; }
  });
  audit('invoice', inv.id, 'deposit-at-signing', null,
        {project: p.id, pct: plan.pct, design, filings: r2(lines.filter(l => l.depositHalf === 'filings').reduce((a, l) => a + l.rate, 0))});
  log(`Deposit at signing drafted for ${plan.c.name} — ${money(r2(lines.reduce((a, l) => a + l.rate, 0)))}`);
  save();
  return inv;
}

function depModal(p){
  const draw = (pct) => {
    const d = depPlan(p, pct); if (!d){ toast('No signed design proposal on this job'); return; }
    const row = (label, fee, target, done, due, extra) => `<tr>
      <td><b>${esc(label)}</b>${extra ? `<div class="small muted">${extra}</div>` : ''}</td>
      <td class="n">${money(fee)}</td>
      <td class="n">${money(target)}</td>
      <td class="n">${done ? money(done) : '<span class="muted">—</span>'}</td>
      <td class="n">${due ? `<b>${money(due)}</b>` : '<span class="muted">—</span>'}</td></tr>`;
    mbModal(`Deposit at signing — ${esc(p.project.name)}`, `
      <p class="small muted" style="margin:0 0 10px">Half the contract, on one document, the day it is signed. Anything already invoiced against either half is taken off first, so a retainer that is already out is never billed twice.</p>
      <div class="row" style="gap:8px;align-items:center;margin-bottom:10px">
        <label class="small">Deposit</label>
        <input type="number" id="dep-pct" min="0" max="100" step="5" value="${d.pct}" style="width:70px">
        <span class="small muted">% of the contract</span>
        <span class="grow"></span>
        <label class="cl-chk" style="margin:0"><input type="checkbox" id="dep-design" checked><span class="small">Design</span></label>
        <label class="cl-chk" style="margin:0"><input type="checkbox" id="dep-filings" checked><span class="small">Filings</span></label>
      </div>
      <table class="t"><thead><tr><th>Half</th><th style="width:110px">Contract</th><th style="width:110px">${d.pct}% of it</th><th style="width:120px">Already invoiced</th><th style="width:110px">Due now</th></tr></thead><tbody>
        ${row('Design — hours', d.designFee, d.designTarget, d.designInvoiced, d.designDue,
              d.designDue ? `funds about ${d.buysHours} hours at ${money(d.rate)}${d.retainer ? ` · the proposal names a ${money(d.retainer)} retainer` : ''}` : 'already covered')}
        ${row('Filings — fixed', d.filingFee, d.filingTarget, d.filingInvoiced, d.filingDue,
              d.stages.length ? `${d.stages.length} filing${d.stages.length === 1 ? '' : 's'} · the deposit on each` : 'already covered')}
        <tr style="font-weight:600"><td>Total</td><td class="n">${money(d.contract)}</td><td class="n">${money(r2(d.designTarget + d.filingTarget))}</td><td class="n">${money(r2(d.designInvoiced + d.filingInvoiced))}</td><td class="n">${money(d.total)}</td></tr>
      </tbody></table>
      <p class="small muted" style="margin:10px 0 0">Signing is what earns the deposit, so none of this counts as invoiced ahead. It is still money taken before the work is done: the remaining ${100 - d.pct}% of each filing follows its own milestones — 30% on submission, 10% on approval, 10% at sign-off — and the filings screen tracks each one.</p>`,
      {submit: `Draft ${money(d.total)}`, wide: true, onSubmit: () => {
        const inv = depInvoice(p, {pct: +document.getElementById('dep-pct').value,
          design: document.getElementById('dep-design').checked,
          filings: document.getElementById('dep-filings').checked});
        if (!inv) return false;
        render();
        toast(`Deposit drafted — ${money(r2(inv.lines.reduce((a, l) => a + l.rate, 0)))} on ${inv.number || 'a draft'}`);
      }});
    if (typeof procWide === 'function') procWide(880);
    const m = document.getElementById('mbm'); if (!m) return;
    m.querySelector('#dep-pct')?.addEventListener('change', e => { mbCloseModal(); draw(+e.target.value); });
  };
  draw();
}

/* On the screen, next to the two halves it covers. */
if (typeof dsPaneHtml === 'function'){
  const dsPaneBase_dep = dsPaneHtml;
  dsPaneHtml = function(){
    let out = dsPaneBase_dep();
    try {
      const rows = (typeof dsAll === 'function' ? dsAll() : []);
      const p = DB.projects.find(x => x.id === (spProj === 'all' ? S.id : spProj)) || S;
      const pick = (rows.find(r => r.p.id === p.id) || rows[0]);
      if (!pick) return out;
      const d = depPlan(pick.p);
      if (d && d.total > 0)
        out += `<div class="dep-bar">
          <div><b>${money(d.total)} of the deposit has not been invoiced.</b>
          <span class="small">${d.pct}% of a ${money(d.contract)} contract is ${money(r2(d.designTarget + d.filingTarget))}; ${money(r2(d.designInvoiced + d.filingInvoiced))} has gone out. The rest is due the day it was signed.</span></div>
          <span class="grow"></span><button class="btn sm primary" id="dep-go">Draft the deposit</button></div>`;
    } catch (e){}
    return out;
  };
}
if (typeof dsWire === 'function'){
  const dsWireBase_dep = dsWire;
  dsWire = function(root){
    dsWireBase_dep(root);
    root.querySelector('#dep-go')?.addEventListener('click', () => {
      const rows = (typeof dsAll === 'function' ? dsAll() : []);
      const p = DB.projects.find(x => x.id === (spProj === 'all' ? S.id : spProj)) || S;
      const pick = (rows.find(r => r.p.id === p.id) || rows[0]);
      if (pick) depModal(pick.p);
    });
  };
}
