/* ---------- 5. heading = tab; the crumb says the same word; body carries the role ---------- */

const IA_OLD_TITLES = {port:'Company overview', bank:'Banking & transactions', ap:'Bills & payroll', verify:'Verification', time:'Time & crew', inv:'Inventory & tools', proc:'Procurement', sday:'My day', sboard:'Project board', po:'Purchasing', client:'Project overview', insp:'Inspections & permits', field:'Field & plans', chat:'Project chat', proj:'Settings & log', recv:'Deliveries'};
const IA_H2_SKIP = new Set(['home','dashboard','sboard','client','sday']);
