  { const g0 = typeof navGroupOf === 'function' ? navGroupOf(view) : null; document.body.dataset.scope = (g0 && ['home','clients','billing','money','reports'].includes(g0.id)) || (view === 'proj' && typeof settingsMode !== 'undefined' && settingsMode === 'company') ? 'firm' : 'project'; }
