/* ---------- 4. the billing worklist ---------- */

function iaBillQueueHtml(){
  const td = today();
  const drafts = [], unpaid = [];
  DB.clients.forEach(c => c.invoices.forEach(i => {
    if (billClient && c.id !== billClient) return;
    const t = docTotal(i); const st = invoiceStatus(c, i);
    if (i.status === 'draft') drafts.push({c, i, t});
    else if (!['paid','void'].includes(i.status)){ const bal = r2(t.total - invoicePaid(c, i)); if (bal > 0.005) unpaid.push({c, i, t, bal, age: i.due ? dayDiff(i.due, td) : 0, st}); }
  }));
  unpaid.sort((a,b) => b.age - a.age);
  const undep = typeof undepositedReceipts === 'function' ? undepositedReceipts().filter(x => !billClient || x.c.id === billClient) : [];
  const sug = typeof billingSuggestions === 'function' ? billingSuggestions().filter(s => !billClient || s.c.id === billClient) : [];
  const row = (n, title, sub, go, act) => `<div class="h4r" ${go ? `data-billgo='${esc(JSON.stringify(go))}'` : ''}><span class="h4r-n">${n}</span><span class="grow">${title}${sub ? ` <span class="small muted">· ${sub}</span>` : ''}</span>${act ? `<em class="small">${act} ›</em>` : ''}</div>`;
  const card = (title, body, empty) => `<div class="card"><div class="hd"><h3>${title}</h3></div>${body || `<div class="muted small">${empty}</div>`}</div>`;
  return `<div class="bq">
    ${card('Ready to bill', sug.slice(0, 8).map(s => row(money(s.amount), esc(s.title), esc(s.p?.project.name || ''), {suggest:{clientId:s.c.id, docId:s.d.id, act:s.act}}, 'Draft')).join(''), 'Nothing has earned an invoice since the last one.')}
    ${card('Drafts to send', drafts.map(d => row(money(d.t.total), `${esc(d.i.number)} · ${esc(d.c.name)}`, esc(d.i.title || ''), {doc:{clientId:d.c.id, kind:'invoice', id:d.i.id}}, 'Open')).join(''), 'No drafts waiting.')}
    ${card('Sent, not paid', unpaid.slice(0, 10).map(u => row(money(u.bal), `${esc(u.i.number)} · ${esc(u.c.name)}`, u.age > 0 ? `<b class="bad">${u.age} d past due</b>` : u.i.due ? `due ${fmt(u.i.due)}` : '', {doc:{clientId:u.c.id, kind:'invoice', id:u.i.id}}, 'Open')).join(''), 'Everything sent has been paid.')}
    ${card('Recorded, not yet in the bank', undep.map(x => row(money(x.py.amount), `${esc(x.c.name)} · ${fmt(x.py.date)}`, esc(x.py.method || ''), {view:'bank'}, 'Banking')).join(''), 'Every recorded payment has been seen in the bank.')}
  </div>`;
}
const renderBillingBase_p2 = renderBilling;
renderBilling = function(){
  renderBillingBase_p2();
  const root = document.getElementById('billing-body'); if (!root || billTab !== 'billable' || docOpen) return;
  const tabs = root.querySelector('.ctabs'); if (!tabs) return;
  tabs.insertAdjacentHTML('afterend', iaBillQueueHtml());
  root.querySelectorAll('[data-billgo]').forEach(el => el.onclick = () => {
    let go; try { go = JSON.parse(el.dataset.billgo); } catch(e){ return; }
    if (go.doc){ clientOpen = go.doc.clientId; docOpen = {kind:go.doc.kind, id:go.doc.id}; billTab = 'invoices'; render(); return; }
    if (go.view){ setView(go.view); return; }
    if (go.suggest){ const {clientId, docId, act} = go.suggest; const c = DB.clients.find(x => x.id === clientId); const d = c && findDoc(c, 'estimate', docId); if (!c || !d) return; clientOpen = clientId; Promise.resolve(docAction(c, d, act)).then(() => { save(); render(); }); }
  });
};

/* ---------- the PO page is the purchase orders ---------- */
