/*<<pass2b.js>>*/
/* ---------- pass 2b: the foreman and the studio director ----------
   - A material request defaulted its cost line to whatever task the foreman was clocked into. An
     insulation request went to demolition without anyone choosing it. The line is now chosen, never assumed.
   - "Arriving today" — subs and deliveries — sat below seven sub cards on the Site tab. It is the first
     thing on Today, and it says so when nothing is coming.
   - The Studio table summed a project's phases, so Schematic at 41.5 of 40 hours read as fine until the
     project was opened. The hours cell now carries the worst phase.                                    */

/* ---------- 1. the request names its line ---------- */
if (typeof mbModal === 'function' && typeof f3MaterialSheet === 'function'){
  const mbModalBase_p2b = mbModal;
  mbModal = function(title, body, opts){
    if (title === 'Materials or a tool' && typeof body === 'string' && /data-f="task"/.test(body)){
      body = body
        .replace(/<select data-f="task">/, '<select data-f="task"><option value="" selected>Choose the work it is for…</option>')
        .replace(/ selected(?=[^>]*>[^<]*<\/option>)(?![^<]*Choose the work)/g, '')
        .replace('<option value="">Not for a particular task</option>', '<option value="none">Not for a particular task</option>');
      const onSubmit = opts && opts.onSubmit;
      if (onSubmit) opts = Object.assign({}, opts, {onSubmit: f => {
        if (!f.task){ toast('Pick the work it is for — that is what puts the cost on the right line'); return false; }
        if (f.task === 'none') f.task = '';
        return onSubmit(f);
      }});
    }
    return mbModalBase_p2b(title, body, opts);
  };
}

/* ---------- 2. arriving today, at the top of Today ---------- */
function f3ArrivingHtml(){
  const td = today();
  const subs = ((DB.field && DB.field.subs) || []).filter(s => s.projectId === S.id && s.date === td);
  const pos = (DB.pos || []).filter(po => po.projectId === S.id && !['cancelled','draft','received'].includes(po.status) && (po.expected || po.needBy) === td);
  const rows = [
    ...subs.map(s => `<div class="f3-row ${s.status === 'noshow' ? 'late' : ''}"><div><span class="k">Sub</span><b>${esc(s.vendor || s.lead || 'Sub')}</b><div class="small muted">${esc(s.trade || '')}${s.status ? ' · ' + ({noshow:'no-show', onsite:'on site', confirmed:'confirmed', unconfirmed:'not confirmed'}[s.status] || esc(s.status)) : ''}</div></div></div>`),
    ...pos.map(po => `<div class="f3-row"><div><span class="k">Delivery</span><b>${esc(po.vendor || 'Vendor')}</b><div class="small muted">${esc(po.number)} · ${(po.lines || []).length} line${(po.lines || []).length === 1 ? '' : 's'}</div></div></div>`),
  ];
  return `<div class="card f-card f3-arriving"><div class="hd"><h3>Arriving today</h3><span class="small muted">${rows.length ? `${rows.length} coming` : ''}</span></div>${rows.length ? rows.join('') : '<div class="small muted">Nothing is scheduled to arrive today.</div>'}</div>`;
}
if (typeof fRenderToday === 'function'){
  const fRenderTodayBase_p2b = fRenderToday;
  fRenderToday = function(){
    fRenderTodayBase_p2b();
    const root = document.querySelector('#ftoday-body'); if (!root || root.querySelector('.f3-arriving')) return;
    const now = root.querySelector('.f-nowcard');
    if (now) now.insertAdjacentHTML('afterend', f3ArrivingHtml()); else root.insertAdjacentHTML('afterbegin', f3ArrivingHtml());
  };
}

/* ---------- 3. the Studio table shows the worst phase ---------- */
function stWorstPhase(pid){
  if (typeof dpRows !== 'function') return null;
  const p = DB.projects.find(x => x.id === pid); if (!p) return null;
  let rows; try { rows = dpRows(p) || []; } catch(e){ return null; }
  let worst = null;
  rows.forEach(r => { if (!r.agreed) return; const pct = r.used / r.agreed; if (!worst || pct > worst.pct) worst = {name: r.name, used: r.used, agreed: r.agreed, pct}; });
  return worst;
}
if (typeof renderStudio === 'function'){
  const renderStudioBase_p2b = renderStudio;
  renderStudio = function(){
    renderStudioBase_p2b();
    const root = document.querySelector('#studio-body'); if (!root) return;
    root.querySelectorAll('tr[data-goproj]').forEach(tr => {
      const pid = tr.dataset.goproj; const w = stWorstPhase(pid); if (!w || w.pct < 0.8) return;
      const cell = [...tr.querySelectorAll('td')].find(td => /\d+(\.\d+)?\s*\/\s*\d+/.test(td.textContent)); if (!cell || cell.querySelector('.st-worst')) return;
      cell.insertAdjacentHTML('beforeend', `<div class="small st-worst ${w.pct >= 1 ? 'bad' : 'warn'}">${esc(w.name)} ${Math.round(w.used*10)/10}/${w.agreed}${w.pct >= 1 ? ' — over' : ''}</div>`);
    });
  };
}
/*<</pass2b.js>>*/

/*<<pass3.js>>*/
/* ---------- pass 3 (part): a reconciliation that can fail, and one cash number ----------
   - Reconcile pre-filled the statement balance with our own book balance and pre-ticked every line, so
     the difference was zero by construction. A reconciliation that cannot fail is not a reconciliation.
     The balance is now typed from the statement, nothing is ticked until a person ticks it.
   - The Banking tiles showed the bank feed's figure while every other screen showed the book. Both are
     real; they are different questions. The tile now says which is which and what the gap is.         */

if (typeof mbModal === 'function' && typeof reconcileDialog === 'function'){
  const mbModalBase_p3 = mbModal;
  mbModal = function(title, body, opts){
    if (typeof title === 'string' && /^Reconcile /.test(title) && typeof body === 'string' && /id="rc-bal"/.test(body)){
      body = body
        .replace(/(id="rc-bal") value="[^"]*"/, '$1 value="" placeholder="From the statement"')
        .replace(/(data-rc="[^"]*") checked/g, '$1')
        .replace(/Enter the statement's ending balance and date, tick what is on the statement\./, "Type the ending balance from the statement itself, then tick each line the statement shows.");
      const onSubmit = opts && opts.onSubmit;
      if (onSubmit) opts = Object.assign({}, opts, {onSubmit: f => {
        const el = document.getElementById('rc-bal');
        if (!el || el.value.trim() === ''){ toast('Type the ending balance from the statement'); return false; }
        return onSubmit(f);
      }});
    }
    return mbModalBase_p3(title, body, opts);
  };
}

if (typeof renderBank === 'function' && typeof acctBook === 'function'){
  const renderBankBase_p3 = renderBank;
  renderBank = function(){
    renderBankBase_p3();
    document.querySelectorAll('#v-bank .acct[data-acct]').forEach(el => {
      const a = (DB.accounts || []).find(x => x.id === el.dataset.acct); if (!a || el.querySelector('.acct-feed')) return;
      const book = r2(acctBook(a)); const feed = +a.balance || 0; const gap = r2(book - feed);
      const b = el.querySelector('b'); if (!b) return;
      b.textContent = money(book); b.style.color = book < 0 ? 'var(--bad)' : '';
      b.insertAdjacentHTML('afterend', `<div class="s acct-feed">book · bank feed ${money(feed)}${a.asOf ? ' as of ' + fmt(a.asOf) : ''}${Math.abs(gap) > 0.005 ? ` · <b class="${Math.abs(gap) > 1000 ? 'warn' : ''}" style="font-size:inherit">${money(gap)} not yet cleared</b>` : ' · ties'}</div>`);
    });
  };
}
/*<</pass3.js>>*/

/*<<pass3b.js>>*/
/* ---------- pass 3b: one progress engine ----------
   The client record's "New progress invoice" pre-filled every line's percent complete from cost to date
   against budget — "cost is progress", the one rule the system is built to refuse. progress.js already
   proposes each line from evidence (the schedule where the work is trackable, deliveries for material
   lines, cost only as a fallback and labelled as such). The pre-fill now comes from there, and a line
   with no evidence is left blank rather than guessed.                                                */

if (typeof progressPrefill === 'function' && typeof pgRows === 'function'){
  progressPrefill = function(c, inv, pctJob){
    const p = DB.projects.find(x => x.id === inv.projectId) || DB.projects.find(x => x.clientId === c.id);
    let rows = []; try { rows = p ? pgRows(p.id) || [] : []; } catch(e){ rows = []; }
    const byLine = {}; rows.forEach(r => { if (r.sv && r.sv.id) byLine[r.sv.id] = r; });
    const basisWord = {schedule:'schedule', delivered:'deliveries', cost:'cost (fallback)', none:'no evidence'};
    let blank = 0, fallback = 0;
    inv.lines.forEach(l => {
      const r = byLine[l.sovId]; const pr = r && r.pr;
      const toDate = pr && pr.pct != null ? pr.pct : null;
      if (toDate == null){ l.pct = 0; l.suggested = false; l.basis = 'none'; blank++; return; }
      l.pct = Math.max(0, r2(toDate - (+l.prevPct || 0))); l.suggested = true; l.basis = pr.basis; if (pr.basis === 'cost') fallback++;
      if (pr.stale) l.basis += ' (schedule stale)';
    });
    inv.title = `Progress billing — work through ${fmtL(today())}`;
    const notes = [`Percentages proposed from evidence per line — ${Object.values(basisWord).slice(0,2).join(' or ')}; cost only where nothing else speaks, and labelled.`];
    if (fallback) notes.push(`${fallback} line${fallback === 1 ? '' : 's'} fell back to cost — check ${fallback === 1 ? 'it' : 'them'} before sending.`);
    if (blank) notes.push(`${blank} line${blank === 1 ? ' has' : 's have'} no evidence and ${blank === 1 ? 'is' : 'are'} left at 0% — fill in what you know.`);
    inv.memo = (inv.memo ? inv.memo + '\n' : '') + notes.join(' ');
  };
}

/* pgApply proposes onto a draft; a draft the pre-fill just filled would read as already proposed.
   Clear the draft's own period first so the engine proposes against what was actually billed. */
if (typeof pgApply === 'function' && typeof pgDraft === 'function'){
  const pgApplyBase_p3b = pgApply;
  pgApply = function(projectId, only){
    const d = pgDraft(projectId);
    if (d && d.inv && Array.isArray(d.inv.lines)) d.inv.lines.forEach(l => { if (!only || only.includes(l.sovId)) l.pct = 0; });
    return pgApplyBase_p3b(projectId, only);
  };
}
/*<</pass3b.js>>*/

/*<<pass3c.js>>*/
/* ---------- pass 3c: every exception has an owner ----------
   The verification list said what was wrong and not who had to act. The rule is the one the approval
   ladder already uses: a serious flag (banking changed, nothing approved behind the charge) is the
   owner's; a card charge with no receipt belongs to whoever holds the card; the rest is the
   controller's to clear or correct. The row carries the owner, the age, and a Respond button that
   opens the same drawer the row always opened. */

function vfOwnerOf(t, v){
  const ex = (v && v.ex) || [];
  const bad = ex.some(e => e.lvl === 'bad');
  const receipt = ex.some(e => /receipt/i.test(e.m || ''));
  if (receipt && typeof cdFor === 'function'){ const {card} = cdFor(t); const h = card && typeof cdHolder === 'function' ? cdHolder(card) : null; if (h && h.name && !/^shared/i.test(h.name)) return h.name; }
  if (bad) return 'Owner';
  return 'Controller';
}
const renderVerifyBase_p3c = renderVerify;
renderVerify = function(){
  const all = DB.txns.filter(t => t.amt < 0); const ver = all.filter(t=>t.verified).length; const exc = openExceptions(); const bad = exc.filter(t => t.verification.ex.some(e=>e.lvl==='bad')).length; const unchecked = all.filter(t=>!t.verification && t.status!=='reconciled').length;
  $('#vf-kpis').innerHTML = `<div class="kpi ${bad?'warn':''}"><b>${exc.length}</b><span>open exceptions · ${bad} serious</span></div><div class="kpi good"><b>${ver}</b><span>verified against approved items</span></div><div class="kpi ${unchecked?'warn':''}"><b>${unchecked}</b><span>cleared transactions not yet checked</span></div><div class="kpi"><b>${money(exc.reduce((a,t)=>a-t.amt,0))}</b><span>value in exception</span></div>`;
  $('#vf-status').textContent = DB.lastVerify ? `Last run ${fmtL(DB.lastVerify.slice(0,10))}` : 'Never run — press Run verification';
  const rows = all.filter(t => vfFilter==='all' || (vfFilter==='open' ? (exc.includes(t)) : t.verified)).map(t => { const v = t.verification||{ex:[]}; const worst = v.ex.some(e=>e.lvl==='bad') ? 3 : v.ex.length ? 2 : 0; return {id:t.id, data:{t, v, worst}, sev:worst, edit:'vtxn:'+t.id, title:v.ex.map(e=>e.m).join(' · ')}; });
  const cols = [
    {key:'date', label:'Cleared', type:'date', w:'76px', get:d => d.t.date},
    {key:'acct', label:'Account', w:'110px', get:d => { const a = DB.accounts.find(x=>x.id===d.t.acct); return a ? `${a.name.split(' ')[0]} ${a.last4}` : '—'; }},
    {key:'desc', label:'Transaction', cls:'name', w:'26%', get:d => ({text:d.t.desc, html:`${esc(d.t.desc)}${d.t.vendor?`<span class="sub">${esc(d.t.vendor)}</span>`:''}`})},
    {key:'amt', label:'Amount', type:'money', w:'96px', get:d => -d.t.amt},
    {key:'match', label:'Matched to', w:'170px', get:d => d.v.matched==='bill' ? `Bill ${esc(DB.bills.find(b=>b.id===d.t.billId)?.number||'')} · approved` : d.v.matched==='payroll' ? 'Approved payroll run' : d.v.matched==='po' ? `PO ${esc(DB.pos.find(p=>p.id===d.t.poId)?.number||'')}` : d.v.matched==='non-operating' ? 'Transfer / non-operating' : d.v.matched==='standing' ? 'Recurring overhead (standing approval)' : (DB.accounts.find(x=>x.id===d.t.acct)?.type==='card' ? 'Card charge' : '—')},
    {key:'status', label:'Status', type:'status', w:'110px', get:d => ({text: d.t.verified ? 'verified' : d.t.ownerCleared ? 'cleared' : d.v.ex?.length ? (d.worst===3?'exception':'review') : (d.t.verification?'ok':'unchecked'), cls: d.t.verified||d.t.ownerCleared ? 'ok' : d.worst===3 ? 'bad' : d.worst===2 ? 'warn' : 'neutral', sort:-d.worst})},
    {key:'owner', label:'Owner', w:'110px', get:d => vfOwnerOf(d.t, d.v)},
    {key:'age', label:'Age', type:'num', w:'64px', get:d => d.t.verified || d.t.ownerCleared ? '' : (dayDiff(d.t.date, today()) + ' d')},
    {key:'why', label:'Flags', cls:'dim', get:d => d.v.ex?.map(e=>e.m).join(' · ')||''},
    {key:'act', label:'', w:'96px', get:d => ({text:'', html: d.t.verified || d.t.ownerCleared ? '' : `<button class="btn sm" data-vfrespond="${d.t.id}">Respond</button>`})},
  ];
  $('#vf-table').innerHTML = grid({id:'verify', cols, rows, defaultSort:'status', empty: vfFilter==='open' ? 'No open exceptions.' : 'Nothing here.'});
  document.querySelectorAll('#vf-table [data-vfrespond]').forEach(b => b.onclick = e => { e.stopPropagation(); openVerifyTxn(b.dataset.vfrespond); });
  const own = {}; exc.forEach(t => { const o = vfOwnerOf(t, t.verification || {ex:[]}); own[o] = (own[o] || 0) + 1; });
  const st = $('#vf-status'); if (st && exc.length) st.textContent += ' · open by owner: ' + Object.entries(own).map(([k,n]) => `${k} ${n}`).join(' · ');
};
/*<</pass3c.js>>*/

/*<<pass4a.js>>*/
/* ---------- pass 4a: each thing in one place ----------
   - Spend › The day carried two money-in panes (Ready to bill, Design & filings) after Billing existed.
     They are Billing's now; Spend keeps what the firm pays and what it has not yet billed for.
   - Spend › Controls (approval routing, terms, reconciled-through) sat under a receipts screen. They are
     controls — their state changes when a person acts — and they join Verification under Accounting › Controls.
   - Reports carried a "CEO dashboard" that repeated the Brief's numbers, and Client funds, which has
     actions and now lives in Billing. Both leave Reports.                                              */

/* ---------- Spend keeps money-out ---------- */
if (typeof SP_GROUPS !== 'undefined'){
  const day = SP_GROUPS.find(g => g[0] === 'day');
  if (day) day[2] = day[2].filter(t => !['billing','dhours'].includes(t));
  const i = SP_GROUPS.findIndex(g => g[0] === 'ctrl'); if (i >= 0) SP_GROUPS.splice(i, 1);
  if (typeof spTab !== 'undefined' && ['billing','dhours','route','terms','recon'].includes(spTab)) spTab = 'approve';
}

/* ---------- Controls: verification, approvals, terms, reconciliation ---------- */
let ctlTab = 'verify';
const CTL_TABS = [['verify','Verification'],['route','Approvals'],['terms','Terms & Early Payment'],['recon','Reconciled Through']];
const renderVerifyBase_p4a = renderVerify;
renderVerify = function(){
  renderVerifyBase_p4a();
  const v = document.getElementById('v-verify'); if (!v) return;
  let sw = v.querySelector('#ctl-tabs');
  if (!sw){ sw = document.createElement('div'); sw.id = 'ctl-tabs'; sw.className = 'ctabs'; const ph = v.querySelector('.ph'); (ph || v).after(sw); }
  sw.innerHTML = CTL_TABS.map(([k,n]) => `<button class="${ctlTab === k ? 'on' : ''}" data-ctltab="${k}">${n}</button>`).join('');
  sw.querySelectorAll('[data-ctltab]').forEach(b => b.onclick = () => { ctlTab = b.dataset.ctltab; render(); });
  let host = v.querySelector('#ctl-pane'); if (!host){ host = document.createElement('div'); host.id = 'ctl-pane'; sw.after(host); }
  const own = [...v.children].filter(el => el !== sw && el !== host && !el.classList.contains('ph'));
  const isV = ctlTab === 'verify';
  own.forEach(el => el.style.display = isV ? '' : 'none');
  const acts = v.querySelector('.ph .acts'); if (acts) acts.style.display = isV ? '' : 'none';
  if (isV){ host.innerHTML = ''; return; }
  host.innerHTML = ctlTab === 'route' ? (typeof rtPaneHtml === 'function' ? rtPaneHtml() : '') : ctlTab === 'terms' ? (typeof tmPaneHtml === 'function' ? tmPaneHtml() : '') : (typeof rxPaneHtml === 'function' ? rxPaneHtml() : '');
  if (ctlTab === 'route' && typeof rtWire === 'function') rtWire(host);
  if (ctlTab === 'recon' && typeof rxWire === 'function') rxWire(host);
  if (ctlTab === 'terms' && typeof tmWire === 'function') tmWire(host);
};
/* the old deep links into Spend › Controls land on the Controls view */
if (typeof setView === 'function'){
  const setViewBase_p4a = setView;
  setView = function(v){ if (v === 'spend' && typeof spTab !== 'undefined' && ['route','terms','recon'].includes(spTab)){ ctlTab = spTab; spTab = 'approve'; v = 'verify'; } return setViewBase_p4a(v); };
}

/* ---------- Reports: read-only, and nothing that lives elsewhere ---------- */
if (typeof REP_GROUPS !== 'undefined'){
  const fin = REP_GROUPS.find(g => g.id === 'fin'); if (fin) fin.tabs = fin.tabs.filter(([k]) => k !== 'dash');
  const cash = REP_GROUPS.find(g => g.id === 'cash'); if (cash) cash.tabs = cash.tabs.filter(([k]) => k !== 'funds');
  if (typeof repTab !== 'undefined' && repTab === 'dash') repTab = 'company';
}
const renderReportsGuard_p4a = typeof renderReports === 'function' ? renderReports : null;
if (renderReportsGuard_p4a){ renderReports = function(){ if (repTab === 'dash') repTab = 'company'; if (repTab === 'funds'){ repTab = 'company'; if ((ROLE_VIEWS[role()]||[]).includes('billing')){ billTab = 'funds'; view = 'billing'; return render(); } } return renderReportsGuard_p4a.apply(this, arguments); }; }
/*<</pass4a.js>>*/

/*<<pass4b.js>>*/
/* ---------- pass 4b: the firm's settings are not a project's ----------
   Project Settings held the user roster, legal entities, approval rules, the company block, data export,
   the assistant's permissions and the backlog — thirteen sections, one scroll, three Save buttons for
   three different records. A project's settings are the project's. The rest is the firm's, reached from
   the rail footer as Settings, and shown without a project's name over it.                         */

let settingsMode = 'project';
IA_LABELS.proj = 'Project Settings';
const renderProjBase_p4b = renderProj;
renderProj = function(){
  renderProjBase_p4b();
  const v = document.getElementById('v-proj'); if (!v) return;
  const grid = v.querySelector('.grid2'); if (!grid) return;
  const projCard = grid.children[0], firmCol = grid.children[1];
  const company = settingsMode === 'company';
  if (projCard) projCard.style.display = company ? 'none' : '';
  if (firmCol) firmCol.style.display = company ? '' : 'none';
  grid.style.gridTemplateColumns = '1fr';
  let bar = v.querySelector('#settings-bar');
  if (!bar){ bar = document.createElement('div'); bar.id = 'settings-bar'; bar.className = 'ph'; grid.before(bar); }
  bar.innerHTML = company
    ? `<div><h2 data-ia-keep="1">Settings</h2><p class="lead">Users, entities, approval rules, the company block, the library, appearance, data.</p></div><div class="acts"><button class="btn" id="settings-toproj">Project Settings ›</button></div>`
    : `<div><h2 data-ia-keep="1">Project Settings</h2><p class="lead">Dates, address, client, entity, holidays and site hours for this project.</p></div><div class="acts"><button class="btn" id="settings-tofirm">Company Settings ›</button></div>`;
  const a = bar.querySelector('#settings-toproj'); if (a) a.onclick = () => { settingsMode = 'project'; setView('proj'); };
  const b = bar.querySelector('#settings-tofirm'); if (b) b.onclick = () => { settingsMode = 'company'; setView('proj'); };
  /* the view's own heading, if it drew one, gives way to the bar */
  const own = v.querySelector(':scope > .ph:not(#settings-bar)'); if (own) own.style.display = 'none';
  const crumbs = document.getElementById('crumbs'); if (crumbs && company) crumbs.innerHTML = '<b>Settings</b>';
  document.body.dataset.scope = company ? 'firm' : document.body.dataset.scope;
};
/* a Settings entry in the rail footer, for anyone who may edit the firm */
function iaSettingsButton(){
  const foot = document.querySelector('.rail .foot'); if (!foot || document.getElementById('rail-settings')) return;
  const b = document.createElement('button'); b.className = 'btn sm'; b.id = 'rail-settings'; b.textContent = 'Settings'; b.style.cssText = 'margin-bottom:8px;width:100%';
  b.onclick = () => { settingsMode = 'company'; setView('proj'); };
  foot.prepend(b);
}
const renderNavBase_p4b = renderNav;
renderNav = function(){ renderNavBase_p4b(); const r = role(); const may = ['owner','pm','controller'].includes(r) && (ROLE_VIEWS[r]||[]).includes('proj'); const b = document.getElementById('rail-settings'); if (may) iaSettingsButton(); else if (b) b.remove(); };
/* the sub-tab is the project's; leaving the project group resets the mode */
const setViewBase_p4b = setView;
setView = function(v){ if (v !== 'proj') settingsMode = 'project'; return setViewBase_p4b(v); };
/*<</pass4b.js>>*/

/*<<pass4c.js>>*/
/* ---------- pass 4c: three dashboards, each widget once ----------
   Six presets carried 41 widgets; margin-at-completion sat on three of them, WIP on three, and nine
   others on two. Nobody knew which tab held the number. Now there are three views beside "My
   dashboard": Owner (the firm's money and risk), Projects (the work), Studio (design and filings).
   Every widget lives on exactly one of them. Customize still lets a person build their own. */

const IA_DASH_VIEWS = [['mine','My Dashboard'],['owner','Owner'],['projects','Projects'],['studio','Studio']];
const P4 = (list, layout=3) => ({layout, portlets:list.map(x => typeof x==='string' ? {type:x} : {type:x[0], cfg:{w:x[1]}})});
const IA_DASH_PRESETS = {
  owner:    P4(['runway','wip','marginfc','dso','copipe','backlog','retainage','clientfunds',['invpipe',2],'billable','apdpo','vendorsactive',['kpi',2],['chart',2],'cashgap','overhead','intercompany','codevar','retreg','books','unbilled','monthcompare','analyst']),
  projects: P4([['schedvar',2],'blockers',['todayall',2],'decisionlat',['evtriple',2],'inspections','deliveries','crew','closeout',['longlead',2],'orderby14','unpriced','povar','buyout','poapprove','vendors','ar','apdue',['jobcards',2],'people',['scorecard',3]]),
  studio:   P4([['studio',2],'phaseburn','realization','retrunway','filingsx','deliverables','hourspeople','rework','cadence','measure','promises','filings','ffe','decisions','reminders']),
};
(function iaDashboards(){
  if (typeof DASH_VIEWS === 'undefined' || typeof DASH_PRESETS === 'undefined') return;
  DASH_VIEWS.splice(0, DASH_VIEWS.length, ...IA_DASH_VIEWS.map(x => [...x]));
  Object.keys(DASH_PRESETS).forEach(k => delete DASH_PRESETS[k]);
  Object.assign(DASH_PRESETS, JSON.parse(JSON.stringify(IA_DASH_PRESETS)));
  if (typeof DASH_ROLE_VIEWS !== 'undefined'){
    Object.keys(DASH_ROLE_VIEWS).forEach(k => delete DASH_ROLE_VIEWS[k]);
    Object.assign(DASH_ROLE_VIEWS, {owner:['mine','owner','projects','studio'], pm:['mine','projects','studio','owner'], coord:['mine','projects'], design_mgr:['mine','studio','projects'], designer:['mine','studio'],
                                    billing:['mine','owner','projects'], controller:['mine','owner','projects']});
  }
  if (typeof DASH_ROLE_PRESETS !== 'undefined'){
    Object.keys(DASH_ROLE_PRESETS).forEach(r => { const keep = DASH_ROLE_PRESETS[r].mine; DASH_ROLE_PRESETS[r] = keep ? {mine: keep} : {}; });
  }
})();
/* a layout built from an old preset is rebuilt once from the new one */
if (typeof homeDef === 'function'){
  const homeDefBase_p4c = homeDef;
  homeDef = function(){
    if (view === 'dashboard' && typeof dashView !== 'undefined' && dashView !== 'mine' && !IA_DASH_PRESETS[dashView]) dashView = 'mine';
    const H = homeDefBase_p4c();
    if (view === 'dashboard' && typeof dashView !== 'undefined' && dashView !== 'mine' && H && H.v !== 6){
      const key = `u:${DB.deviceUser || 'x'}:${dashView}`;
      const N = JSON.parse(JSON.stringify(IA_DASH_PRESETS[dashView])); N.portlets.forEach(p => { p.id = uid('pt'); p.cfg = p.cfg || {}; }); N.v = 6;
      DB.dashboards = DB.dashboards || {}; DB.dashboards[key] = N; return N;
    }
    return H;
  };
}
/*<</pass4c.js>>*/

/*<<pass4d.js>>*/
/* ---------- pass 4d: one clock ----------
   today() read the current project's "as of" date, so a job with one set to 3 September and a design
   project with none showed two different days on the same screen — and the Studio listed "hours not
   logged" for dates that had not happened. The as-of date is the firm's. Set it once, every project
   reads it; clear it, every project reads the real day. */
function iaOneClock(){
  if (typeof DB === 'undefined' || !DB || !Array.isArray(DB.projects)) return;
  if (DB.company && DB.company.asOf === undefined){
    const first = DB.projects.find(p => p.project && p.project.today);
    DB.company.asOf = first ? first.project.today : '';
  }
  const asOf = (DB.company && DB.company.asOf) || '';
  DB.projects.forEach(p => { if (p.project && (p.project.today || '') !== asOf) p.project.today = asOf; });
}
const renderBase_p4d = render;
render = function(){ iaOneClock(); return renderBase_p4d(); };
/* the setting lives with the firm: Settings › Company */
const renderProjBase_p4d = renderProj;
renderProj = function(){
  renderProjBase_p4d();
  const v = document.getElementById('v-proj'); if (!v || v.querySelector('#asof-card')) return;
  const col = v.querySelector('.grid2') && v.querySelector('.grid2').children[1]; if (!col) return;
  const card = document.createElement('div'); card.className = 'card'; card.id = 'asof-card'; card.style.marginBottom = '14px';
  card.innerHTML = `<h3>The firm's clock</h3><p class="small muted">Every screen reads one "as of" date. Leave it blank for today.</p><div class="f" style="max-width:220px"><label>As of</label><input type="date" id="asof-date" value="${esc((DB.company && DB.company.asOf) || '')}"></div>`;
  col.prepend(card);
  card.querySelector('#asof-date').addEventListener('change', e => { DB.company.asOf = e.target.value || ''; iaOneClock(); save(); render(); toast(DB.company.asOf ? `Every screen now reads as of ${fmtL(DB.company.asOf)}` : 'Every screen now reads today'); });
};
/*<</pass4d.js>>*/

/*<<crm.js>>*/
/* ---------- pass 5a: the CRM record set ----------
   The guide asks for client name, phone, email, and the building: condo, co-op or townhouse — and for a
   condo or co-op, the managing company or agent and the superintendent. A client can own two addresses,
   so the building is a record of its own, not a string on the client. Contacts get a typed role, so
   Billing knows who pays, Decisions knows who decides, and Purchasing knows who lets the delivery in.
   Leads come before clients: a prospect is no longer a $0 client with a draft estimate.              */

const CRM_BUILDING = ['', 'Townhouse', 'Condo', 'Co-op', 'Single-family', 'Multi-family', 'Commercial'];
const CRM_ROLES = ['Owner — decisions', 'Owner — payments', "Owner's rep", 'Architect of record', 'Attorney', 'Managing agent', 'Superintendent', 'Tenant', 'Other'];
const CRM_STAGES = [['inquiry','Inquiry'],['site-visit','Site visit'],['proposal','Proposal out'],['won','Won'],['lost','Lost']];
const CRM_SCOPES = ['Design', 'Filings', 'Construction', 'Finish materials', 'Design-build'];
const crmNeedsBuilding = t => /condo|co-op/i.test(t || '');

function crmInit(){
  if (typeof DB === 'undefined' || !DB) return;
  DB.leads = DB.leads || [];
  (DB.clients || []).forEach(c => {
    if (!Array.isArray(c.properties)) c.properties = [];
    const looksLikeAddr = a => /^\s*\d+\s+\S/.test(a || '');   /* a unit description is not a building */
    const addrs = [c.propertyAddr, ...DB.projects.filter(p => p.clientId === c.id).map(p => p.project && p.project.addr).filter(looksLikeAddr)].filter(Boolean);
    addrs.forEach(a => { if (!c.properties.some(p => (p.addr || '').toLowerCase() === a.toLowerCase())) c.properties.push({id: uid('pr'), addr: a, buildingType: '', mgmtCompany: '', mgmtAgent: '', mgmtPhone: '', mgmtEmail: '', superName: '', superPhone: '', notes: ''}); });
  });
}
const crmBuildingOf = c => { const p = (c.properties || []).find(x => x.buildingType); return p ? p.buildingType : ''; };

/* ---------- the property editor, in the same drawer ---------- */
const openClientEditorBase_crm = openClientEditor;
openClientEditor = function(kind, id){
  if (kind !== 'property'){
    openClientEditorBase_crm(kind, id);
    if (kind === 'contact'){ const inp = document.getElementById('e-role'); if (inp && inp.tagName === 'INPUT'){
      const cur = inp.value; const sel = document.createElement('select'); sel.id = 'e-role';
      const opts = CRM_ROLES.includes(cur) || !cur ? CRM_ROLES : [cur, ...CRM_ROLES];
      sel.innerHTML = opts.map(r => `<option ${r === cur ? 'selected' : ''}>${esc(r)}</option>`).join('');
      inp.replaceWith(sel);
      sel.insertAdjacentHTML('afterend', '<div class="small muted" style="margin-top:4px">Billing writes to the payer, Decisions chases the decider, deliveries call the super.</div>');
    } }
    return;
  }
  const c = DB.clients.find(x => x.id === clientOpen); if (!c) return; crmInit();
  const x = id ? c.properties.find(q => q.id === id) : {addr:'', buildingType:'', mgmtCompany:'', mgmtAgent:'', mgmtPhone:'', mgmtEmail:'', superName:'', superPhone:'', notes:''};
  editing = {kind:'client-property', id}; document.getElementById('scrim').classList.add('on'); document.getElementById('drawer').classList.add('on'); document.getElementById('ai').classList.remove('on');
  document.getElementById('d-title').textContent = id ? 'Edit building' : 'New building'; document.getElementById('d-delete').style.display = id ? '' : 'none';
  const b = document.getElementById('d-body');
  b.innerHTML = `<div class="f"><label>Address</label><input id="e-addr" value="${esc(x.addr)}" placeholder="121 State St, Brooklyn"></div>
    <div class="f"><label>Building</label><select id="e-btype">${CRM_BUILDING.map(t => `<option value="${t}" ${x.buildingType === t ? 'selected' : ''}>${t || '— choose —'}</option>`).join('')}</select></div>
    <div id="e-bldg" style="display:${crmNeedsBuilding(x.buildingType) ? '' : 'none'}">
      <div class="f2"><div class="f"><label>Managing company</label><input id="e-mgmtco" value="${esc(x.mgmtCompany)}"></div><div class="f"><label>Managing agent</label><input id="e-mgmt" value="${esc(x.mgmtAgent)}"></div></div>
      <div class="f2"><div class="f"><label>Agent phone</label><input id="e-mgmtph" value="${esc(x.mgmtPhone)}"></div><div class="f"><label>Agent email</label><input id="e-mgmtem" value="${esc(x.mgmtEmail)}"></div></div>
      <div class="f2"><div class="f"><label>Superintendent</label><input id="e-super" value="${esc(x.superName)}"></div><div class="f"><label>Super phone</label><input id="e-superph" value="${esc(x.superPhone)}"></div></div>
      <div class="note">A condo or co-op needs the alteration agreement, the board's work hours and the elevator rules before the first delivery — put them in the notes until they have a home of their own.</div>
    </div>
    <div class="f"><label>Notes</label><textarea id="e-bnotes" rows="3">${esc(x.notes || '')}</textarea></div>`;
  b.querySelector('#e-btype').addEventListener('change', e => { b.querySelector('#e-bldg').style.display = crmNeedsBuilding(e.target.value) ? '' : 'none'; });
  editing.collect = () => ({id: id || uid('pr'), addr: b.querySelector('#e-addr').value.trim(), buildingType: b.querySelector('#e-btype').value, mgmtCompany: b.querySelector('#e-mgmtco').value.trim(), mgmtAgent: b.querySelector('#e-mgmt').value.trim(), mgmtPhone: b.querySelector('#e-mgmtph').value.trim(), mgmtEmail: b.querySelector('#e-mgmtem').value.trim(), superName: b.querySelector('#e-super').value.trim(), superPhone: b.querySelector('#e-superph').value.trim(), notes: b.querySelector('#e-bnotes').value});
};
const saveClientEditorBase_crm = saveClientEditor;
saveClientEditor = function(){
  if (editing && editing.kind === 'client-property'){
    const c = DB.clients.find(x => x.id === clientOpen); if (!c) return; crmInit();
    const o = editing.collect(); if (!o.addr){ toast('An address, at least'); return; }
    if (crmNeedsBuilding(o.buildingType) && !o.superName && !o.mgmtAgent && !o.mgmtCompany) toast('A condo or co-op with no agent and no super — the first delivery will find out');
    const i = c.properties.findIndex(p => p.id === o.id); if (i >= 0) Object.assign(c.properties[i], o); else c.properties.push(o);
    if (!c.propertyAddr) c.propertyAddr = o.addr;
    c.activity.push({t: nowStamp(), by: (S.project && S.project.userName) || '', text: `Building ${editing.id ? 'updated' : 'added'} — ${o.addr}${o.buildingType ? ' · ' + o.buildingType : ''}`});
    closeEditor(); save(); render(); return;
  }
  return saveClientEditorBase_crm();
};

/* ---------- the Overview shows the buildings ---------- */
function crmPropertiesCard(c){
  const rows = (c.properties || []).map(p => `<div class="cl-row"><div><b>${esc(p.addr)}</b>${p.buildingType ? ` <span class="pill neutral">${esc(p.buildingType)}</span>` : ' <span class="pill warn">building type not set</span>'}
      <div class="small muted">${crmNeedsBuilding(p.buildingType) ? [p.mgmtCompany || p.mgmtAgent ? `Agent ${esc([p.mgmtAgent, p.mgmtCompany].filter(Boolean).join(', '))}${p.mgmtPhone ? ' · ' + esc(p.mgmtPhone) : ''}` : '<span class="bad">no managing agent</span>', p.superName ? `Super ${esc(p.superName)}${p.superPhone ? ' · ' + esc(p.superPhone) : ''}` : '<span class="bad">no super</span>'].join(' · ') : (p.notes ? esc(p.notes.slice(0, 80)) : '')}</div></div>
      <button class="btn sm ghost" data-cedit="property:${p.id}">Edit</button></div>`).join('');
  return `<div class="card" style="margin-bottom:14px"><div class="row" style="margin-bottom:6px"><h3 style="margin:0">Buildings</h3><span class="grow"></span><button class="btn sm" data-cedit="property:">Add</button></div>${rows || '<div class="muted small">No building on file yet.</div>'}</div>`;
}
const renderClientsBase_crm = renderClients;
renderClients = function(){
  crmInit();
  renderClientsBase_crm();
  if (!clientOpen || clientTab !== 'overview') return;
  const rec = document.getElementById('client-record'); if (!rec || rec.querySelector('#crm-props')) return;
  const c = DB.clients.find(x => x.id === clientOpen); if (!c) return;
  const grid = rec.querySelector('.grid2'); if (!grid || !grid.children[1]) return;
  const host = document.createElement('div'); host.id = 'crm-props'; host.innerHTML = crmPropertiesCard(c);
  grid.children[1].prepend(host.firstElementChild);
  rec.querySelectorAll('[data-cedit^="property:"]').forEach(b => b.onclick = () => openClientEditor('property', b.dataset.cedit.split(':')[1] || null));
  /* the old free-text property and billing lines give way to the record */
  const old = [...rec.querySelectorAll('.card .small b')].find(b => b.textContent.trim() === 'Property');
  if (old){ let n = old.nextSibling; while (n && !(n.nodeType === 1 && n.tagName === 'B')){ const nx = n.nextSibling; n.remove(); n = nx; } old.remove(); }
};

/* ---------- leads ---------- */
let crmTab = 'clients';
function crmLeadsHtml(){
  const rows = (DB.leads || []).filter(l => l.stage !== 'won' && l.stage !== 'lost').sort((a, b) => String(a.nextDue || '9').localeCompare(String(b.nextDue || '9')));
  const done = (DB.leads || []).filter(l => l.stage === 'won' || l.stage === 'lost').length;
  const stage = k => (CRM_STAGES.find(s => s[0] === k) || [k, k])[1];
  const td = today();
  return `<div class="ph"><div><h2 data-ia-keep="1">Leads</h2><p class="lead">Before a contract, a lead. Won turns it into a client with the estimate already started.</p></div><div class="acts"><button class="btn primary" id="btn-newlead">New Lead</button></div></div>
    ${rows.length ? `<div class="tw"><table class="t"><thead><tr><th>Lead</th><th>Property</th><th>Scope</th><th>Stage</th><th>Source</th><th>Next step</th><th>Due</th><th></th></tr></thead><tbody>${rows.map(l => `<tr><td><b>${esc(l.name)}</b><div class="small muted">${esc(l.phone || '')}${l.phone && l.email ? ' · ' : ''}${esc(l.email || '')}</div></td><td>${esc(l.addr || '')}</td><td>${esc(l.scope || '')}</td><td><span class="pill ${l.stage === 'proposal' ? 'info' : 'neutral'}">${stage(l.stage)}</span></td><td class="dim">${esc(l.source || '')}</td><td>${esc(l.next || '')}</td><td class="${l.nextDue && l.nextDue < td ? 'bad' : ''}">${l.nextDue ? fmt(l.nextDue) : '—'}</td><td><button class="btn sm" data-lead-edit="${l.id}">Edit</button> <button class="btn sm" data-lead-won="${l.id}">Won</button> <button class="btn sm ghost" data-lead-lost="${l.id}">Lost</button></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">No open leads. <button class="btn" id="btn-newlead2">Add the first</button></div>'}
    ${done ? `<p class="small muted" style="margin-top:8px">${done} closed lead${done === 1 ? '' : 's'} kept for the record.</p>` : ''}`;
}
function crmLeadSheet(id){
  const l = id ? DB.leads.find(x => x.id === id) : {name:'', phone:'', email:'', addr:'', buildingType:'', scope:'Design-build', stage:'inquiry', source:'', next:'', nextDue:'', notes:''};
  mbModal(id ? 'Edit lead' : 'New lead', `
    <div class="f2"><div class="f"><label>Name</label><input data-f="name" value="${esc(l.name)}"></div><div class="f"><label>Phone</label><input data-f="phone" value="${esc(l.phone)}"></div></div>
    <div class="f2"><div class="f"><label>Email</label><input data-f="email" value="${esc(l.email)}"></div><div class="f"><label>Source</label><input data-f="source" value="${esc(l.source)}" placeholder="Referral, Houzz, walk-by…"></div></div>
    <div class="f2"><div class="f"><label>Property</label><input data-f="addr" value="${esc(l.addr)}"></div><div class="f"><label>Building</label><select data-f="buildingType">${CRM_BUILDING.map(t => `<option value="${t}" ${l.buildingType === t ? 'selected' : ''}>${t || '— choose —'}</option>`).join('')}</select></div></div>
    <div class="f2"><div class="f"><label>Scope</label><select data-f="scope">${CRM_SCOPES.map(s => `<option ${l.scope === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><div class="f"><label>Stage</label><select data-f="stage">${CRM_STAGES.filter(s => !['won','lost'].includes(s[0])).map(([k, n]) => `<option value="${k}" ${l.stage === k ? 'selected' : ''}>${n}</option>`).join('')}</select></div></div>
    <div class="f2"><div class="f"><label>Next step</label><input data-f="next" value="${esc(l.next)}" placeholder="Site visit, send proposal…"></div><div class="f"><label>Due</label><input type="date" data-f="nextDue" value="${esc(l.nextDue)}"></div></div>
    <div class="f"><label>Notes</label><textarea data-f="notes" rows="2">${esc(l.notes)}</textarea></div>`,
    {submit: id ? 'Save' : 'Add lead', onSubmit: f => { if (!f.name){ toast('A name, at least'); return false; }
      const o = Object.assign(id ? l : {id: uid('ld'), created: today()}, f); if (!id) DB.leads.push(o); save(); render(); }});
}
function crmLeadWon(id){
  const l = DB.leads.find(x => x.id === id); if (!l) return;
  const c = blankClient(l.name); c.type = 'Residential owner'; c.propertyAddr = l.addr || ''; c.billingAddr = c.propertyAddr; c.notes = l.notes || '';
  if (l.email || l.phone) c.contacts.push({id: uid('ct'), name: l.name, email: l.email || '', phone: l.phone || '', role: 'Owner — decisions', primary: true});
  c.properties = l.addr ? [{id: uid('pr'), addr: l.addr, buildingType: l.buildingType || '', mgmtCompany: '', mgmtAgent: '', mgmtPhone: '', mgmtEmail: '', superName: '', superPhone: '', notes: ''}] : [];
  DB.clients.push(c); l.stage = 'won'; l.wonAt = today(); l.clientId = c.id;
  c.activity.push({t: nowStamp(), by: (S.project && S.project.userName) || '', text: `Won from lead — ${l.scope || ''}${l.source ? ' · ' + l.source : ''}`});
  clientOpen = c.id; clientTab = 'overview'; crmTab = 'clients'; save(); render(); toast(`${c.name} is a client — start the estimate from the record`);
}
const renderClientsBase_crm2 = renderClients;
renderClients = function(){
  renderClientsBase_crm2();
  if (clientOpen) return;
  const list = document.getElementById('clients-list'); if (!list) return;
  const open = (DB.leads || []).filter(l => !['won','lost'].includes(l.stage)).length;
  const sw = `<div class="ctabs" id="crm-tabs"><button class="${crmTab === 'clients' ? 'on' : ''}" data-crmtab="clients">Clients<span class="n">${DB.clients.filter(c => !/owned property/i.test(c.type || '')).length}</span></button><button class="${crmTab === 'leads' ? 'on' : ''}" data-crmtab="leads">Leads${open ? `<span class="n">${open}</span>` : ''}</button></div>`;
  if (crmTab === 'leads') list.innerHTML = sw + crmLeadsHtml(); else list.insertAdjacentHTML('afterbegin', sw);
  list.querySelectorAll('[data-crmtab]').forEach(b => b.onclick = () => { crmTab = b.dataset.crmtab; render(); });
  list.querySelectorAll('#btn-newlead, #btn-newlead2').forEach(b => b.onclick = () => crmLeadSheet(null));
  list.querySelectorAll('[data-lead-edit]').forEach(b => b.onclick = () => crmLeadSheet(b.dataset.leadEdit));
  list.querySelectorAll('[data-lead-won]').forEach(b => b.onclick = () => crmLeadWon(b.dataset.leadWon));
  list.querySelectorAll('[data-lead-lost]').forEach(b => b.onclick = () => { const l = DB.leads.find(x => x.id === b.dataset.leadLost); if (!l) return; const why = prompt('Lost — why? (a sentence, so the next one goes better)'); if (why == null) return; l.stage = 'lost'; l.lostWhy = why; l.lostAt = today(); save(); render(); });
};
/*<</crm.js>>*/

/*<<pass6.js>>*/
/* ---------- pass 6: the worst screens, by layout ----------
   From the IA reviewer's ten: All Projects was one card per client per project with a cash chart above
   it — three tiles a card, "New project for X" repeated per client, and no way it survives forty jobs.
   The Buy Board's header carried three buttons that were tabs one row up. Costs flagged twelve of
   sixteen lines with one project-level fact.                                                        */

/* ---------- 1. All Projects is a table ---------- */
const renderPortfolioBase_p6 = renderPortfolio;
renderPortfolio = function(){
  renderPortfolioBase_p6();
  const host = document.getElementById('port-cards'); if (!host) return;
  const cash = document.getElementById('cash-card'); if (cash) cash.style.display = 'none';   /* the Dashboard owns cash */
  const rows = DB.projects.map(p => { const h = projectHealth(p); const J = (typeof jobFin === 'function') ? jobFin(p) : {}; const c = DB.clients.find(x => x.id === p.clientId); return {p, h, J, c}; });
  const grade = h => h.tasks ? ({g:'ok', a:'info', o:'warn', r:'bad'}[h.health.grade] || 'neutral') : 'neutral';
  host.classList.remove('port');
  host.innerHTML = grid({id:'portfolio', cols:[
    {key:'name', label:'Project', cls:'name', w:'22%', get:r => r.p.project.name},
    {key:'client', label:'Client', get:r => r.c ? r.c.name : '—'},
    {key:'health', label:'Health', type:'status', w:'96px', get:r => ({text: r.h.tasks ? String(r.h.health.score) : 'no schedule', cls: grade(r.h), sort: r.h.tasks ? r.h.health.score : -1})},
    {key:'done', label:'Done', type:'num', w:'72px', get:r => r.h.tasks ? r.h.pct + '%' : ''},
    {key:'urgent', label:'Urgent', type:'num', w:'72px', get:r => r.h.urgent || ''},
    {key:'finish', label:'Completion', type:'date', w:'104px', get:r => r.h.tasks ? r.h.sc : ''},
    {key:'late', label:'vs Target', w:'110px', get:r => r.h.tasks && r.p.project.target ? (r.h.late > 0 ? `${r.h.late} d late` : r.h.late < 0 ? `${-r.h.late} d early` : 'on target') : ''},
    {key:'contract', label:'Contract', type:'money', w:'110px', get:r => r.J.contract || ''},
    {key:'billed', label:'Billed', type:'money', w:'100px', get:r => r.J.billed || ''},
    {key:'out', label:'Outstanding', type:'money', w:'110px', get:r => r.J.outstanding || ''},
    {key:'next', label:'Next', get:r => r.h.next && r.h.next[0] ? `${fmt(r.h.next[0].d)} ${r.h.next[0].n}` : ''},
  ], rows: rows.map(r => ({id:r.p.id, data:r, edit:'openproj:'+r.p.id, sev: r.h.tasks && r.h.health.score < 45 ? 2 : 0, title: (r.h.health.why||[]).join(' · ')})), defaultSort:'health', dir:'asc', empty:'No projects yet.'});
  const lead = document.querySelector('#v-port .ph .lead'); if (lead) lead.textContent = 'Every job, ranked by how much attention it needs today. Open one for its Today.';
};
document.addEventListener('click', e => {
  const tr = e.target.closest('#v-port tr[data-edit^="openproj:"]'); if (!tr || e.target.closest('button,a')) return;
  e.stopPropagation(); e.preventDefault(); setCurrent(tr.dataset.edit.split(':')[1]); save(); setView('dash');
}, true);

/* ---------- 2. the Buy Board header keeps its own actions ---------- */
const renderProcBase_p6 = renderProc;
renderProc = function(){
  renderProcBase_p6();
  ['#proc-vendors', '#proc-recv'].forEach(s => { const b = document.querySelector('#proc-body ' + s); if (b) b.remove(); });
  const h2 = document.querySelector('#proc-body .ph h2'); if (h2 && /^Procurement/.test(h2.textContent)) h2.textContent = 'Buy Board';
};

/* ---------- 3. one project-level flag, not twelve line flags ---------- */
/* "billed ahead of cost" on a line means nothing when the whole contract was billed as one
   percentage — every line carries the same number. The project tile says it once. */
const lineFinBase_p6 = lineFin;
const p6LumpCache = {};
function p6IsLump(c){
  const k = c.id; if (p6LumpCache[k] && p6LumpCache[k].t === render.__tick) return p6LumpCache[k].v;
  const live = c.invoices.filter(i => i.mode === 'sov' && !['void','draft'].includes(i.status));
  const count = {}; let n = 0;
  (c.sov || []).forEach(sv => { const p = live.flatMap(i => i.lines).filter(l => l.sovId === sv.id).reduce((a,l) => a + (+l.pct || 0), 0); if (p > 0){ const k = Math.round(p * 100); count[k] = (count[k] || 0) + 1; n++; } });
  const top = Math.max(0, ...Object.values(count));
  const v = n >= 4 && top / n >= 0.8;                    /* four-fifths of the billed lines share one figure: it was billed as a whole */
  p6LumpCache[k] = {t: render.__tick, v}; return v;
}
lineFin = function(key){
  const f = lineFinBase_p6(key); if (!f || !f.client || !Array.isArray(f.flags)) return f;
  if (f.flags.includes('billed ahead of cost') && p6IsLump(f.client)){ f.flags = f.flags.filter(x => x !== 'billed ahead of cost'); f.lumpBilled = true; }
  return f;
};
const renderBase_p6 = render;
render = function(){ render.__tick = (render.__tick || 0) + 1; return renderBase_p6(); };

/* the Costs table computes its own flags in lineProfit(); the same rule applies there */
if (typeof lineProfit === 'function'){
  const lineProfitBase_p6 = lineProfit;
  lineProfit = function(p){
    const rows = lineProfitBase_p6(p);
    const c = DB.clients.find(x => x.id === p.clientId);
    if (!c || !Array.isArray(rows) || !p6IsLump(c)) return rows;
    rows.forEach(r => { if (Array.isArray(r.flags)){ const n = r.flags.length; r.flags = r.flags.filter(f => !/^billed \d+% vs \d+% complete$/.test(f)); if (r.flags.length !== n) r.lumpBilled = true; } });
    rows.lumpBilled = true;
    return rows;
  };
}
/* and the table says it once, above the rows */
const renderCostsBase_p6 = typeof renderCosts === 'function' ? renderCosts : null;
if (renderCostsBase_p6){
  renderCosts = function(){
    renderCostsBase_p6();
    const v = document.getElementById('v-costs'); if (!v || v.querySelector('#p6-lump')) return;
    const c = DB.clients.find(x => x.id === S.clientId); if (!c || !p6IsLump(c)) return;
    const tbl = v.querySelector('table'); if (!tbl) return;
    tbl.insertAdjacentHTML('beforebegin', `<p class="note" id="p6-lump" style="margin-bottom:10px"><b>Billed as one percentage so far, not line by line</b> — the per-line billed figures say nothing yet; the over- or under-billing sits in the tile above. Each line bills on its own evidence from the next application.</p>`);
  };
}
/*<</pass6.js>>*/

/*<<pass7.js>>*/
/* ---------- pass 7: one sheet for a material request; a hold on what the office has not seen ----------
   The foreman's request began in a sheet and finished on a different screen — the Requests composer,
   with kits, "did you forget" and a re-parsed list — one UI seam in the most common thing he does.
   The list is now the second step of the same sheet: lines he can fix, a send button, the receipt.
   The Requests screen stays for status. And the driver's store run listed items procurement had not
   acknowledged, so he was told to buy what nobody had approved; those now carry a hold.           */

/* ---------- 1. the second step of the sheet ---------- */
function f3ReviewSheet(f){
  const td = today();
  let lines = (typeof parseLocal === 'function' ? parseLocal(f.text || '') : []).map(l => Object.assign({qty: 1, unit: 'ea'}, l));
  if (!lines.length && (f.text || '').trim()) lines = [{what: f.text.trim(), qty: 1, unit: 'ea', invId: ''}];
  const tk = f.task && typeof task === 'function' ? task(f.task) : null;
  const sug = (typeof buildSuggestions === 'function' ? buildSuggestions(lines, f.task) : []).slice(0, 4);
  const draw = () => {
    const rows = lines.map((l, i) => { const c = typeof qtyCheck === 'function' ? qtyCheck(l.what, l.qty, l.unit) : null; const inv = l.invId ? DB.inventory.find(x => x.id === l.invId) : null;
      return `<div class="lineedit" data-i="${i}"><input type="number" step="any" data-lf="qty" value="${l.qty}"><input data-lf="unit" value="${esc(l.unit || 'ea')}"><input data-lf="what" value="${esc(l.what)}"><button class="rm" data-rm="${i}" aria-label="Remove">–</button></div>
        ${inv ? `<div class="small muted" style="margin:-2px 0 6px 2px">In stock: ${esc(inv.name)} at ${esc(typeof locName === 'function' ? locName(inv.loc) : '')}</div>` : ''}${c && c.level !== 'ok' ? `<div class="small ${c.level === 'bad' ? 'bad' : 'warn'}" style="margin:-2px 0 6px 2px">${esc(c.text)}</div>` : ''}`; }).join('');
    mbModal('Check the list', `
      <div class="small muted" style="margin-bottom:8px">${tk ? `For <b>${esc(tk.name)}</b>` : 'Not for a particular task'} · needed ${fmtL(f.when || addWork(td, 1))}${f.urgent ? ' · <b class="bad">urgent</b>' : ''}</div>
      <div id="f3-lines">${rows || '<div class="muted small">Nothing yet — add a line.</div>'}</div>
      <div class="row" style="margin-top:6px"><button class="btn sm" id="f3-addline">Add a line</button></div>
      ${sug.length ? `<div class="forgot"><b>Did you forget?</b><div class="chips">${sug.map((s, i) => `<button class="chip" data-sug="${i}">${esc(s.what || s.name || String(s))}</button>`).join('')}</div></div>` : ''}`,
      {submit: `Send ${lines.length ? lines.length + ' line' + (lines.length === 1 ? '' : 's') : ''}`, wide: true, onSubmit: () => {
        if (!lines.length){ toast('Nothing to send yet'); return false; }
        const emp = typeof myEmp === 'function' ? myEmp() : null; const by = (emp && emp.name) || DB.me || 'Crew';
        const slot = (typeof TIME_WINDOWS !== 'undefined' && TIME_WINDOWS[f.slot]) || 'Any time';
        const r = addRequest({items: lines.map(l => Object.assign({}, l, {qty: +l.qty || 1})), neededBy: f.when || addWork(td, 1), timeWindow: slot, taskId: f.task || '', urgency: f.urgent ? 'urgent' : 'normal', note: ''}, by);
        if (!r){ toast('Nothing to send'); return false; }
        r.viaSheet = true;
        if (r.urgency === 'urgent' && typeof notify === 'function') notify('Urgent field request', `${typeof reqLabel === 'function' ? reqLabel(r) : 'Request'} — ${S.project.name}`);
        save(); render();
        if (typeof frqReceipt === 'function') setTimeout(() => frqReceipt(r), 60);
      }});
    const m = document.getElementById('mbm'); if (!m) return;
    m.querySelectorAll('[data-lf]').forEach(inp => inp.addEventListener('change', () => { const i = +inp.closest('[data-i]').dataset.i; const k = inp.dataset.lf; lines[i][k] = k === 'qty' ? (+inp.value || 1) : inp.value; if (k === 'what' && typeof invFind === 'function'){ const inv = invFind(inp.value); lines[i].invId = inv ? inv.id : ''; } }));
    m.querySelectorAll('[data-rm]').forEach(b => b.onclick = () => { lines.splice(+b.dataset.rm, 1); draw(); });
    const add = m.querySelector('#f3-addline'); if (add) add.onclick = () => { lines.push({what: '', qty: 1, unit: 'ea', invId: ''}); draw(); setTimeout(() => { const last = m.querySelector('[data-i]:last-of-type [data-lf="what"]'); if (last) last.focus(); }, 30); };
    m.querySelectorAll('[data-sug]').forEach(b => b.onclick = () => { const s = sug[+b.dataset.sug]; lines.push({what: s.what || s.name || String(s), qty: s.qty || 1, unit: s.unit || 'ea', invId: s.invId || ''}); draw(); });
  };
  draw();
  if (typeof procWide === 'function') procWide(560);
}
if (typeof mbModal === 'function'){
  const mbModalBase_p7 = mbModal;
  mbModal = function(title, body, opts){
    if (title === 'Materials or a tool' && opts && opts.onSubmit){
      const base = opts.onSubmit;
      opts = Object.assign({}, opts, {submit: 'Next — check the list', onSubmit: f => {
        /* the checks upstream (a line chosen, something typed) still run; the handoff to another screen does not */
        if (!f.task){ toast('Pick the work it is for — that is what puts the cost on the right line'); return false; }
        if (!String(f.text || '').trim()){ toast('Say what you need'); return false; }
        if (f.task === 'none') f.task = '';
        setTimeout(() => f3ReviewSheet(f), 40);
        return true;
      }});
    }
    return mbModalBase_p7(title, body, opts);
  };
}

/* ---------- 2. the driver's hold ---------- */
/* a request nobody at the office has acknowledged is not a thing to buy yet: the store list showed it
   with a small "not acked" pill and a live checkbox. The checkbox is now disabled and the line says why. */
const p7Unacked = r => r && r.status === 'new' && !r.ackAt;
function p7HoldStoreList(){
  const unacked = DB.projects.flatMap(p => (p.requests || []).filter(p7Unacked)).flatMap(r => (typeof reqItems === 'function' ? reqItems(r) : (r.items || [{what: r.what}])).map(i => (i.what || '').toLowerCase()).filter(Boolean));
  document.querySelectorAll('.shopitem').forEach(el => {
    if (el.querySelector('.p7-hold')) return;
    const pill = [...el.querySelectorAll('.pill')].find(x => /not acked/i.test(x.textContent));
    const txt = el.textContent.toLowerCase();
    if (!pill && !unacked.some(w => w && txt.includes(w))) return;
    const cb = el.querySelector('input[type=checkbox][data-buy]'); if (cb){ cb.disabled = true; cb.checked = false; }
    el.classList.add('p7-held');
    if (pill){ pill.className = 'pill bad'; pill.textContent = 'hold'; }
    const s = el.querySelector('.s'); (s || el).insertAdjacentHTML('beforeend', `<div class="small p7-hold"><b class="bad">Hold</b> — the office has not acknowledged this. Do not buy it until they do.</div>`);
  });
  const n = document.querySelectorAll('.shopitem.p7-held').length; const shop = document.querySelector('.shop');
  if (n && shop && !document.querySelector('#p7-holdnote')) shop.insertAdjacentHTML('afterbegin', `<div class="note warn" id="p7-holdnote"><b>${n} line${n === 1 ? '' : 's'} on hold</b> — not yet acknowledged by the office. They stay on the list so you can see them; they are not yours to buy yet.</div>`);
}
const renderBase_p7 = render;
render = function(){ renderBase_p7(); if (['route','time','req'].includes(view)) p7HoldStoreList(); };
/*<</pass7.js>>*/

/*<<alt.js>>*/
/* ---------- the alteration agreement ----------
   A co-op or condo hands the client a contract with the building, and the job has to obey it: the hours
   work may happen, the days it may not, whether a wet room may sit over a dry one, the elevator, the
   insurance the building demands of every sub, a deposit, a deadline with a daily penalty behind it.
   Those facts used to live in a PDF in somebody's inbox; the schedule, the foreman and the driver found
   them out the hard way.

   The agreement lives on the BUILDING (a client who does a second job there already has the rules).
   It moves through two stages, because the document changes: the managing agent's draft comes in, the
   reader proposes its terms as fields, a person marks each accept / negotiate / reject with a note —
   that is the redline — and the markup goes back. When the executed copy arrives, the accepted terms
   go live and start governing every project at that address. Nothing governs until a person confirms
   it; a clause the reader cannot find stays blank and says so.                                        */

const ALT_STAGES = [['none','No agreement'],['received','Received — reading'],['redlined','Redlined — with the agent'],['executed','Executed — governing']];
const ALT_TERMS = [
  ['workHours',  'Work hours',            'When work may happen',                                  'schedule'],
  ['workDays',   'Work days',             'Which days',                                            'schedule'],
  ['blackout',   'Building blackout dates','Days the building forbids work (holidays and its own)', 'schedule'],
  ['noise',      'Noisy work window',     'Demolition, drilling, hammering',                       'schedule'],
  ['wetOverDry', 'Wet over dry',          'A wet room may not sit over a dry one below',           'design'],
  ['elevator',   'Elevator',              'Reservation, protection, hours',                        'deliveries'],
  ['coi',        'Insurance',             'Limits and additional insureds every sub must carry',   'vendors'],
  ['deposit',    'Building deposit',      'Refundable, held by the building',                      'billing'],
  ['fees',       'Fees',                  'Application, architect review, non-refundable',         'billing'],
  ['deadline',   'Completion deadline',   'Days allowed from start, and the penalty per day after', 'schedule'],
];
const ALT_POS = [['accept','Accept'],['negotiate','Negotiate'],['reject','Reject']];

function altOf(prop){ if (!prop.alteration) prop.alteration = {stage:'none', text:'', file:'', receivedAt:'', executedAt:'', terms:{}, positions:{}, history:[]}; return prop.alteration; }
const altAddrKey = a => (a || '').toLowerCase().replace(/\b(street)\b/g, 'st').replace(/\b(avenue)\b/g, 'ave').replace(/\b(place)\b/g, 'pl').replace(/\b(road)\b/g, 'rd').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').slice(0, 3).join(' ');
function altProjectsFor(prop){
  const k = altAddrKey(prop.addr); const owner = DB.clients.find(c => (c.properties || []).some(p => p.id === prop.id));
  const streetLike = a => /^\s*\d+\s+\S/.test(a || '');
  return DB.projects.filter(p => {
    if (p.propertyId === prop.id) return true;
    if (k && altAddrKey(p.project && p.project.addr) === k) return true;
    /* a project whose "address" is a unit description belongs to its client's building — the only one, or the first */
    if (owner && p.clientId === owner.id && !streetLike(p.project && p.project.addr)){ const real = (owner.properties || []).filter(x => streetLike(x.addr)); return real.length ? real[0].id === prop.id : (owner.properties || [])[0] && owner.properties[0].id === prop.id; }
    return false; });
}

/* ---------- reading the paper, offline first ---------- */
const ALT_DAYS = {sunday:0, monday:1, tuesday:2, wednesday:3, thursday:4, friday:5, saturday:6, sun:0, mon:1, tue:2, tues:2, wed:3, thu:4, thur:4, thurs:4, fri:5, sat:6};
function altHour(s){ const m = /(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?/i.exec(s || ''); if (!m) return ''; let h = +m[1]; const mm = m[2] || '00'; const ap = (m[3] || '').toLowerCase().replace(/\./g, ''); if (ap === 'pm' && h < 12) h += 12; if (ap === 'am' && h === 12) h = 0; if (!ap && h <= 7) h += 12; return `${String(h).padStart(2, '0')}:${mm}`; }
function altMoney(s){ const m = /\$\s?([\d,]+(?:\.\d{2})?)/.exec(s || ''); return m ? +m[1].replace(/,/g, '') : null; }
function altNormalise(text){
  return (text || '')
    .replace(/[‘’‚]/g, "'").replace(/[“”„]/g, '"').replace(/[{]/g, '(').replace(/[}]/g, ')')
    .replace(/(\d)\s*:\s*(\d{2})/g, '$1:$2')                       /* OCR: "9: 00" */
    .replace(/\b([AP])\s*\.\s*M\b\.?/gi, (m, x) => x.toUpperCase() + 'M')  /* "A. M." → "AM" */
    .replace(/\$\s+(\d)/g, '$$$1')                                  /* "$ 500" */
    .replace(/\s+/g, ' ');
}
const ALT_TIME = '(\\d{1,2}(?::\\d{2})?\\s*(?:am|pm|a\\.m\\.|p\\.m\\.)?)';
function altParse(text){
  const t = altNormalise(text);
  const out = {}; const grab = (re) => { const m = re.exec(t); return m ? {m, src: t.slice(Math.max(0, m.index - 40), m.index + m[0].length + 60).trim()} : null; };
  const sentences = t.split(/(?<=[.;])\s+/);
  let g;
  /* hours */
  g = grab(new RegExp('(?:between(?: the hours of)?|from)\\s+' + ALT_TIME + '\\s+(?:and|to|until|-|–)\\s+' + ALT_TIME, 'i'));
  if (g) out.workHours = {value: `${altHour(g.m[1])}–${altHour(g.m[2])}`, start: altHour(g.m[1]), end: altHour(g.m[2]), src: g.src};
  /* days */
  g = grab(/(mondays?|tuesdays?|wednesdays?|thursdays?|fridays?|saturdays?|sundays?|mon|tue|wed|thu|fri|sat|sun)\.?\s+(?:through|thru|to|-|–)\s+(mondays?|tuesdays?|wednesdays?|thursdays?|fridays?|saturdays?|sundays?|mon|tue|wed|thu|fri|sat|sun)/i);
  if (g){ const a = ALT_DAYS[g.m[1].toLowerCase().replace(/s$/, '')], b = ALT_DAYS[g.m[2].toLowerCase().replace(/s$/, '')]; const days = []; for (let d = a; ; d = (d + 1) % 7){ days.push(d); if (d === b || days.length > 7) break; } out.workDays = {value: `${g.m[1].replace(/s$/, '')}–${g.m[2].replace(/s$/, '')}`, days, src: g.src}; }
  else if (/weekdays only|monday.{0,20}friday/i.test(t)) out.workDays = {value: 'Weekdays', days: [1,2,3,4,5], src: 'weekdays'};
  /* blackout: only dates that sit in a sentence about not working */
  { const ctx = sentences.filter(x => /(no work|not be performed|not permitted|prohibited|shall not perform|no construction|excluding holidays|weekends or holidays|legal holidays)/i.test(x));
    const hol = ctx.some(x => /holiday/i.test(x)); const wk = ctx.some(x => /weekend/i.test(x));
    const dre = /((?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?\s+\d{1,2})(?:\s*[-–]\s*((?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?\s+)?(\d{1,2}))?(?:,?\s*(\d{4}))?/ig;
    const dates = []; ctx.forEach(x => { let d; while ((d = dre.exec(x))){ if (d[4] && +d[4] < +today().slice(0, 4) - 1) continue; dates.push(d[3] ? `${d[1]}–${(d[2] || '').trim() ? d[2].trim() + ' ' : ''}${d[3]}` : d[1]); } });
    if (hol || dates.length) out.blackout = {value: [hol ? 'Building holidays' : '', wk ? 'Weekends' : '', ...dates.slice(0, 8)].filter(Boolean).join(' · '), holidays: hol, weekends: wk, dates: dates.slice(0, 8), src: (ctx.find(x => /holiday|weekend/i.test(x)) || ctx[0] || '').slice(0, 160)}; }
  /* noise */
  g = grab(new RegExp('(?:noisy|noise|demolition|hammer|drill|jackhammer)[^.]{0,120}?(?:between|from)\\s+' + ALT_TIME + '\\s+(?:and|to|until|-|–)\\s+' + ALT_TIME, 'i'));
  if (g) out.noise = {value: `${altHour(g.m[1])}–${altHour(g.m[2])}`, start: altHour(g.m[1]), end: altHour(g.m[2]), src: g.src};
  else { g = grab(new RegExp('(?:noisy|noise)[^.]{0,160}?(?:not|no)[^.]{0,60}?(?:before|prior to)\\s+' + ALT_TIME, 'i'));
    if (g){ const end = out.workHours ? out.workHours.end : ''; out.noise = {value: `${altHour(g.m[1])}${end ? '–' + end : ' onward'}`, start: altHour(g.m[1]), end, src: g.src}; } }
  /* wet over dry */
  { const i = t.search(/wet[\s-]*(?:over|above)[\s-]*dry/i); if (i >= 0){ const win = t.slice(Math.max(0, i - 200), i + 300); out.wetOverDry = {value: /not permitted|prohibited|shall not|may not|\bno\b/i.test(win) ? 'Not permitted' : 'Restricted — see clause', src: t.slice(Math.max(0, i - 12), i + 150).trim()}; } }
  /* elevator: sentences where the elevator is the subject, not an aside in a list */
  { const sents = sentences.filter(x => /elevator/i.test(x) && !/\([^)]*elevator[^)]*\)/i.test(x) && /(service elevator|reserv|schedul|book|superintendent|direct|protect|pad|hours|only)/i.test(x));
    if (sents.length){ const w = sents.join(' ');
      out.elevator = {value: [/service elevator/i.test(w) ? 'Service elevator only' : '', /reserv|schedul|book/i.test(w) ? 'Reservation required' : '', /superintendent[^.]{0,40}direct|as the superintendent/i.test(w) ? 'Times set by the super' : '', /protect|pad/i.test(w) ? 'Protection required' : '', (() => { const h = new RegExp(ALT_TIME + '\\s+(?:and|to|until|-|–)\\s+' + ALT_TIME, 'i').exec(w); return h ? `${altHour(h[1])}–${altHour(h[2])}` : ''; })(), (() => { const n = /(\d{1,3})\s*hours?\s+(?:in advance|notice|prior)/i.exec(w); return n ? `${n[1]} h notice` : ''; })()].filter(Boolean).join(' · ') || 'See clause', src: w.slice(0, 160)}; } }
  /* insurance: the first limit after each heading, however far the boilerplate pushes it */
  { const after = (re, span) => { const m = re.exec(t); if (!m) return null; const win = t.slice(m.index, m.index + span); const d = /\$\s?([\d,]{7,})/.exec(win); return d ? {amt: +d[1].replace(/,/g, ''), src: (m[0] + ' … ' + d[0]).slice(0, 120)} : null; };
    const gl = after(/(?:commercial general liability|general liability|CGL)/i, 1800); const um = after(/(?:umbrella|excess liability)/i, 900); const ai = /additional(?: named)? insured/i.test(t);
    if (gl || um || ai) out.coi = {value: [gl ? `GL ${money(gl.amt)}` : '', um ? `Umbrella ${money(um.amt)}` : '', ai ? 'Additional insureds named' : ''].filter(Boolean).join(' · '), gl: gl ? gl.amt : null, umbrella: um ? um.amt : null, additionalInsured: ai, src: (gl || um || {src: 'additional insured'}).src}; }
  /* deposit: either order */
  g = grab(/(?:security )?deposit[^.]{0,80}?\$[\d,]+(?:\.\d{2})?/i) || grab(/\$[\d,]+(?:\.\d{2})?[^.]{0,100}?(?:security )?deposit/i);
  if (g) out.deposit = {value: money(altMoney(g.m[0])), amount: altMoney(g.m[0]), src: g.src};
  /* fees: a dollar figure and the word fee in the same breath */
  { const fees = []; const seen = new Set();
    const re1 = /((?:application|processing|review|architect|engineer|filing|administrative|non-?refundable|alteration)[^.$]{0,60}?fee)[^.$]{0,40}?\$([\d,]+(?:\.\d{2})?)/ig; let m;
    while ((m = re1.exec(t))){ const amt = +m[2].replace(/,/g, ''); const k = m[1].toLowerCase().replace(/\s+/g, ' '); if (!seen.has(k + amt)){ seen.add(k + amt); fees.push({label: m[1].trim(), amount: amt}); } }
    const re2 = /\$([\d,]+(?:\.\d{2})?)[^.$]{0,60}?(?:as an?|representing(?: an?)?|for the)\s+((?:[a-z]+\s+){0,3}fee)/ig;
    while ((m = re2.exec(t))){ const amt = +m[1].replace(/,/g, ''); const k = m[2].toLowerCase().replace(/\s+/g, ' '); if (!seen.has(k + amt) && !/deposit/i.test(m[0])){ seen.add(k + amt); fees.push({label: m[2].trim(), amount: amt}); } }
    if (fees.length) out.fees = {value: fees.map(f => `${f.label} ${money(f.amount)}`).join(' · '), items: fees, src: fees[0].label}; }
  /* deadline and the penalty behind it */
  { const days = grab(/(?:completed?|complete|finish(?:ed)?)[^.]{0,80}?within\s+(\d{2,3})\s+(?:calendar |business |working )?days/i) || grab(/(\d{2,3})\s+(?:calendar |business |working )?days\s+(?:after|from|following)\s+(?:the )?(?:commencement|start)/i) || grab(/(\d{2,3})\s+(?:calendar |business |working )?days[^.]{0,60}?(?:to complete|completion)/i);
    const pen = grab(/\$([\d,]+)\s*(?:per|a|each|for each)\s+(?:calendar |business )?day/i);
    if (days || pen) out.deadline = {value: [days ? `${days.m[1]} days` : '', pen ? `${money(+pen.m[1].replace(/,/g, ''))}/day after` : ''].filter(Boolean).join(' · '), days: days ? +days.m[1] : null, penaltyPerDay: pen ? +pen.m[1].replace(/,/g, '') : null, src: (days || pen).src}; }
  return out;
}
async function altRead(prop){
  const A = altOf(prop); const local = altParse(A.text); let live = null;
  if (typeof ai === 'function' && typeof aiReady === 'function' && aiReady() && (A.text || '').length > 200){
    try { const r = await ai(`Read this alteration agreement and return JSON only with any of these keys you can find, each {"value": short human summary, "src": the clause's words}: workHours, workDays, blackout, noise, wetOverDry, elevator, coi, deposit, fees, deadline. Omit a key you cannot find. Never guess.\n\n${A.text.slice(0, 12000)}`, 900, 20000);
      if (r && !String(r).startsWith('__ERR')){ const j = safeJSON(r); if (j && typeof j === 'object') live = j; } } catch(e){ live = null; }
  }
  const terms = Object.assign({}, live || {}, local);      /* the deterministic reader wins where both speak; the model fills the rest */
  ALT_TERMS.forEach(([k]) => { if (!terms[k]) terms[k] = null; });
  A.terms = terms; A.readAt = today(); A.readBy = live ? 'assistant + reader' : 'reader';
  if (A.stage === 'none') A.stage = 'received';
  return terms;
}

/* ---------- the sheet ---------- */
function altSheet(clientId, propId){
  const c = DB.clients.find(x => x.id === clientId); const prop = c && (c.properties || []).find(p => p.id === propId); if (!prop) return;
  const A = altOf(prop);
  const draw = () => {
    const st = ALT_STAGES.find(s => s[0] === A.stage) || ALT_STAGES[0];
    const rows = ALT_TERMS.map(([k, n, why, who]) => { const term = A.terms[k]; const pos = A.positions[k] || {state: '', note: ''};
      return `<tr data-term="${k}"><td><b>${n}</b><div class="small muted">${why} · <em>${who}</em></div></td>
        <td>${term ? `<div>${esc(term.value || '')}</div><div class="small muted" title="${esc(term.src || '')}">${esc((term.src || '').slice(0, 90))}${(term.src || '').length > 90 ? '…' : ''}</div>` : '<span class="muted">Not found in the text — say it if you know it</span>'}<div><input class="alt-manual" data-manual="${k}" placeholder="${term ? 'Override…' : 'Type the term'}" value="${esc(pos.manual || '')}" style="margin-top:4px;height:28px;width:100%"></div></td>
        <td><div class="seg sm">${ALT_POS.map(([p, l]) => `<button class="${pos.state === p ? 'on' : ''}" data-pos="${k}:${p}">${l}</button>`).join('')}</div><input data-note="${k}" placeholder="Our note to the agent" value="${esc(pos.note || '')}" style="margin-top:4px;height:28px;width:100%"></td></tr>`; }).join('');
    const decided = ALT_TERMS.filter(([k]) => (A.positions[k] || {}).state).length; const known = ALT_TERMS.filter(([k]) => A.terms[k] || (A.positions[k] || {}).manual).length;
    const projs = altProjectsFor(prop);
    mbModal(`Alteration agreement — ${esc(prop.addr)}`, `
      <div class="steps">${ALT_STAGES.map(([k, l]) => `<span class="${A.stage === k ? 'on' : ALT_STAGES.findIndex(s => s[0] === k) < ALT_STAGES.findIndex(s => s[0] === A.stage) ? 'done' : ''}">${l}</span>`).join('')}</div>
      ${A.stage === 'executed' ? `<div class="note" style="margin-bottom:10px"><b>Executed ${fmtL(A.executedAt)}.</b> The accepted terms govern ${projs.length ? projs.map(p => esc(p.project.name)).join(', ') : 'every project at this address'}.${(A.terms.deposit || A.terms.fees) ? ` <button class="btn sm" id="alt-fees" style="margin-left:8px">Put the deposit and fees on the estimate</button>` : ''}</div>` : ''}
      <div class="f"><label>The agent's draft (paste the text; a scanned PDF must be typed or OCR'd first — nothing is guessed from a picture)</label><textarea id="alt-text" rows="5" placeholder="Paste the alteration agreement here…">${esc(A.text || '')}</textarea></div>
      <div class="row" style="margin-bottom:10px"><button class="btn" id="alt-read">Read it</button><span class="small muted">${A.readAt ? `Read ${fmtL(A.readAt)} by the ${A.readBy} · ${known} of ${ALT_TERMS.length} terms found` : 'Not read yet'}</span><span class="grow"></span><span class="small muted">${decided} of ${ALT_TERMS.length} positions taken</span></div>
      <div class="tw"><table class="t"><thead><tr><th style="width:24%">Term</th><th>What the draft says</th><th style="width:30%">Our position</th></tr></thead><tbody>${rows}</tbody></table></div>
      ${A.history.length ? `<div class="small muted" style="margin-top:8px">${A.history.slice(-4).map(h => `${fmt(h.at)} ${esc(h.what)}`).join(' · ')}</div>` : ''}`,
      {submit: 'Save', wide: true, onSubmit: () => { altCollect(prop); save(); render(); }});
    const m = document.getElementById('mbm'); if (!m) return;
    if (typeof procWide === 'function') procWide(920);
    const ft = m.querySelector('.mbm-ft');
    if (ft && !ft.querySelector('#alt-redline')){
      const b1 = document.createElement('button'); b1.className = 'btn'; b1.id = 'alt-redline'; b1.textContent = 'Send the redline'; b1.title = 'Mark the draft as redlined and with the agent';
      b1.onclick = () => { altCollect(prop); if (!decided){ toast('Take a position on at least one term first'); return; } A.stage = 'redlined'; A.history.push({at: today(), what: `redline sent · ${decided} positions`}); save(); mbCloseModal(); render(); toast('Redline recorded — waiting on the agent'); };
      const b2 = document.createElement('button'); b2.className = 'btn primary'; b2.id = 'alt-exec'; b2.textContent = 'Executed — apply the terms';
      b2.onclick = () => { altCollect(prop); const open = ALT_TERMS.filter(([k]) => (A.terms[k] || (A.positions[k] || {}).manual) && (A.positions[k] || {}).state === 'negotiate'); if (open.length && !confirm(`${open.length} term${open.length === 1 ? ' is' : 's are'} still marked "negotiate": ${open.map(x => x[1]).join(', ')}. Apply the agreement as it stands?`)) return; altExecute(prop); mbCloseModal(); render(); };
      ft.prepend(b2); ft.prepend(b1);
    }
    const fb = m.querySelector('#alt-fees'); if (fb) fb.onclick = () => { const n = altFeesToEstimate(c, prop); toast(n ? `${n} reimbursable line${n === 1 ? '' : 's'} added to the estimate` : 'Already on the estimate, or no open estimate to put them on'); if (n){ save(); } };
    m.querySelector('#alt-read').onclick = async () => { A.text = m.querySelector('#alt-text').value; if (!A.text.trim()){ toast('Paste the agreement first'); return; } const b = m.querySelector('#alt-read'); b.disabled = true; b.textContent = 'Reading…'; await altRead(prop); A.history.push({at: today(), what: 'read'}); save(); mbCloseModal(); altSheet(clientId, propId); };
    m.querySelectorAll('[data-pos]').forEach(b => b.onclick = () => { const [k, p] = b.dataset.pos.split(':'); A.positions[k] = Object.assign(A.positions[k] || {}, {state: p}); altCollect(prop); mbCloseModal(); altSheet(clientId, propId); });
  };
  draw();
}
function altCollect(prop){ const A = altOf(prop); const m = document.getElementById('mbm'); if (!m) return; const ta = m.querySelector('#alt-text'); if (ta) A.text = ta.value; m.querySelectorAll('[data-note]').forEach(i => { A.positions[i.dataset.note] = Object.assign(A.positions[i.dataset.note] || {}, {note: i.value}); }); m.querySelectorAll('[data-manual]').forEach(i => { A.positions[i.dataset.manual] = Object.assign(A.positions[i.dataset.manual] || {}, {manual: i.value.trim()}); }); }

/* ---------- executed: the accepted terms govern ---------- */
function altRules(prop){
  const A = prop.alteration; if (!A || A.stage !== 'executed') return null;
  const R = {}; ALT_TERMS.forEach(([k]) => { const pos = A.positions[k] || {}; if (pos.state === 'reject') return; const t = A.terms[k]; const manual = pos.manual; if (!t && !manual) return; R[k] = Object.assign({}, t || {}, manual ? {value: manual, manual: true} : {}); });
  return R;
}
function altExecute(prop){
  const A = altOf(prop); A.stage = 'executed'; A.executedAt = today(); A.history.push({at: today(), what: 'executed — terms applied'});
  const R = altRules(prop) || {};
  altProjectsFor(prop).forEach(p => {
    p.project.buildingRules = {propertyId: prop.id, addr: prop.addr, rules: R, since: today()};
    if (R.workHours && R.workHours.start && R.workHours.end){ const h = Object.assign({days:[1,2,3,4,5], start:'07:30', end:'16:30', lunch:30}, p.project.hours || {}); h.start = R.workHours.start; h.end = R.workHours.end; if (R.workDays && R.workDays.days) h.days = R.workDays.days; p.project.hours = h; }
    else if (R.workDays && R.workDays.days){ const h = Object.assign({days:[1,2,3,4,5], start:'07:30', end:'16:30', lunch:30}, p.project.hours || {}); h.days = R.workDays.days; p.project.hours = h; }
    if (R.blackout && (R.blackout.dates || []).length){ const yr = today().slice(0, 4); const lines = (p.project.holidays || '').split('\n').filter(Boolean);
      R.blackout.dates.forEach(d => { altExpandDates(d, yr).forEach(iso_ => { if (iso_ && !lines.some(l => l.startsWith(iso_))) lines.push(`${iso_} building — ${d}`); }); }); p.project.holidays = lines.join('\n'); }
    if (R.deadline && R.deadline.days){ const start = (p.tasks || []).map(t => t.start).filter(Boolean).sort()[0] || today(); p.project.buildingDeadline = iso(addDays(start, R.deadline.days)); }
    log(`Alteration agreement executed for ${prop.addr} — building rules now govern`, 'building', (S.project && S.project.userName) || '');
  });
  toast('The building\'s terms now govern the schedule, the site and the deliveries');
}
/* "December 15–January 3" is every day between, across the year end; a single date is itself */
function altExpandDates(d, yr){
  const parts = String(d).split(/\s*[–-]\s*/); if (parts.length < 2) return [altIsoDate(d, yr)].filter(Boolean);
  const a = altIsoDate(parts[0], yr); let bTxt = parts[1]; if (!/[a-z]/i.test(bTxt)) bTxt = parts[0].replace(/\d{1,2}(?:,?\s*\d{4})?\s*$/, '') + ' ' + bTxt;   /* "15–20" keeps the month */
  let b = altIsoDate(bTxt, yr); if (!a || !b) return [a, b].filter(Boolean);
  if (b < a) b = altIsoDate(bTxt, String(+yr + 1));
  const out = []; for (let x = parse(a); iso(x) <= b && out.length < 60; x.setDate(x.getDate() + 1)) out.push(iso(x));
  return out;
}
function altIsoDate(s, yr){ const m = /^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:\s*[-–]\s*\d{1,2})?(?:,?\s*(\d{4}))?/i.exec(s || ''); if (!m) return ''; const mo = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(m[1].toLowerCase().slice(0, 3)) + 1; return `${m[3] || yr}-${String(mo).padStart(2, '0')}-${String(+m[2]).padStart(2, '0')}`; }
function altRulesFor(p){ return (p || S).project && (p || S).project.buildingRules ? (p || S).project.buildingRules : null; }
function altRulesText(p){
  const B = altRulesFor(p); if (!B) return []; const R = B.rules || {}; const out = [];
  if (R.workHours) out.push(`Work ${R.workHours.value}${R.workDays ? ' · ' + R.workDays.value : ''}`); else if (R.workDays) out.push(`Work ${R.workDays.value}`);
  if (R.noise) out.push(`Noisy work only ${R.noise.value}`);
  if (R.blackout) out.push(`No work: ${R.blackout.value}`);
  if (R.elevator) out.push(`Elevator: ${R.elevator.value}`);
  if (R.wetOverDry) out.push(`Wet over dry: ${R.wetOverDry.value}`);
  if (R.coi) out.push(`Subs carry ${R.coi.value}`);
  if ((p || S).project.buildingDeadline) out.push(`Building deadline ${fmtL((p || S).project.buildingDeadline)}${R.deadline && R.deadline.penaltyPerDay ? ` · ${money(R.deadline.penaltyPerDay)}/day after` : ''}`);
  return out;
}

/* the terms, on the building card itself — the draft's terms with our position while it is being redlined, the rules once executed */
function altTermsListHtml(prop){
  const A = prop.alteration; if (!A || A.stage === 'none') return '';
  const label = {workHours:'Hours', workDays:'Days', blackout:'No work', noise:'Noisy work', wetOverDry:'Wet over dry', elevator:'Elevator', coi:'Insurance', deposit:'Deposit', fees:'Fees', deadline:'Deadline'};
  const rows = ALT_TERMS.map(([k]) => { const pos = A.positions[k] || {}; const t = A.terms[k]; const v = pos.manual || (t && t.value); if (!v) return ''; if (A.stage === 'executed' && pos.state === 'reject') return '';
    const mark = A.stage === 'executed' ? '' : pos.state === 'accept' ? '<span class="pill ok">accept</span>' : pos.state === 'negotiate' ? '<span class="pill warn">negotiate</span>' : pos.state === 'reject' ? '<span class="pill bad">reject</span>' : '<span class="pill neutral">open</span>';
    return `<div class="alt-term"><span class="k">${label[k]}</span><span class="v">${esc(v)}</span>${mark}</div>`; }).filter(Boolean).join('');
  const missing = ALT_TERMS.filter(([k]) => !A.terms[k] && !(A.positions[k] || {}).manual).map(([k]) => label[k]);
  return `<div class="alt-terms">${rows || '<div class="small muted">Nothing read yet.</div>'}${missing.length && A.stage !== 'executed' ? `<div class="small muted" style="margin-top:4px">Not in the draft: ${missing.join(', ')}</div>` : ''}</div>`;
}

/* ---------- where it shows ---------- */
