/* reminders: a delivery on a day the building forbids, a deadline the schedule misses, a sub under the building's insurance */
const remindersBase_alt = reminders;
reminders = function(){
  const out = remindersBase_alt();
  DB.projects.forEach(p => { const B = altRulesFor(p); if (!B) return; const R = B.rules || {};
    const hol = new Set((p.project.holidays || '').split('\n').map(l => l.trim().split(/\s+/)[0]).filter(Boolean)); const days = (p.project.hours && p.project.hours.days) || [1,2,3,4,5];
    const bad = DB.pos.filter(po => po.projectId === p.id && !['cancelled','received','draft'].includes(po.status) && po.expected && (hol.has(po.expected) || !days.includes(parse(po.expected).getDay())));
    if (bad.length) out.push({n: bad.length, label: `deliver${bad.length === 1 ? 'y' : 'ies'} expected on a day the building forbids · ${p.project.name} · ${bad.map(x => x.number).join(', ')}`, go: {view: 'po'}, sev: 'warn'});
    if (p.project.buildingDeadline && p.tasks && p.tasks.length){ const h = projectHealth(p); const end = h && h.sc ? h.sc : '';
      if (end && end > p.project.buildingDeadline){ const late = dayDiff(p.project.buildingDeadline, end); out.push({n: late, label: `days past the building's deadline on the current schedule · ${p.project.name}${R.deadline && R.deadline.penaltyPerDay ? ` · ${money(late * R.deadline.penaltyPerDay)} in penalties` : ''}`, go: {view: 'sched', proj: p.id}, sev: 'bad'}); } }
    if (R.coi){ const vs = [...new Set(DB.pos.filter(po => po.projectId === p.id && !['cancelled','draft'].includes(po.status)).map(po => po.vendor))]; const weak = vs.filter(v => { const r = DB.vendors.find(x => x.name === v); return r && (!r.insuranceExp || r.insuranceExp < today()); });
      if (weak.length) out.push({n: weak.length, label: `vendor${weak.length === 1 ? '' : 's'} on ${p.project.name} without current insurance — the building requires ${R.coi.value}`, go: {view: 'vendors'}, sev: 'warn'}); }
  });
  return out;
};
/* billing: the building's deposit and fees are reimbursables on the client's estimate */
function altFeesToEstimate(c, prop){
  const R = altRules(prop); if (!R) return 0; const est = (c.estimates || []).filter(e => ['draft','sent'].includes(e.status)).slice(-1)[0] || (c.estimates || []).slice(-1)[0]; if (!est) return 0;
  let n = 0; const add = (item, amt) => { if (!amt || est.lines.some(l => l.item === item)) return; est.lines.push({id: uid('l'), item, desc: `Per the alteration agreement — ${prop.addr}`, qty: 1, unit: 'ls', rate: amt, cost: amt, markupPct: 0, taxable: false, cat: 'reimbursable'}); n++; };
  if (R.deposit && R.deposit.amount) add('Building deposit (refundable)', R.deposit.amount);
  (R.fees && R.fees.items || []).forEach(f => add(`Building fee — ${f.label}`, f.amount));
  return n;
}

/* ---------- the demo shows one: 121 State Street as a co-op with the agent's draft received and read ---------- */
const ALT_DEMO_TEXT = `ALTERATION AGREEMENT — 200 East 66th Street Owners Corp.\n3. Hours of Work. All work shall be performed between 9:00 a.m. and 4:30 p.m., Monday through Friday. No work is permitted on Saturdays, Sundays, or legal holidays, nor on December 24, December 31 or the week of July 4.\n4. Noisy work, including demolition, drilling and hammering, shall be confined to the hours between 10:00 a.m. and 3:00 p.m.\n5. Wet over dry. No bathroom, kitchen or other wet area shall be located over a dry area of the apartment below. Such wet-over-dry installations are not permitted.\n6. Elevator. The service elevator must be reserved with the superintendent at least 48 hours in advance and padded/protected; deliveries only between 9:00 a.m. and 3:00 p.m.\n7. Insurance. Contractor and each subcontractor shall carry Commercial General Liability insurance of not less than $2,000,000 per occurrence and an Umbrella policy of $5,000,000, naming the Corporation and the Managing Agent as additional insureds.\n8. Security deposit of $10,000.00 shall be delivered to the Managing Agent prior to commencement. A non-refundable processing fee of $750 and an architect review fee of $1,500 are payable with the application.\n9. Completion. The work shall be completed within 120 days of commencement. Shareholder shall pay $250 per day for each day thereafter.`;
function altSeed(){
  if (typeof DB === 'undefined' || !DB || !Array.isArray(DB.clients)) return;
  if (DB.company && DB.company.altSeeded) return;
  const c = DB.clients.find(x => /Klein/.test(x.name)); if (!c) return;
  if (typeof crmInit === 'function') crmInit();
  const p = (c.properties || []).find(x => /121 State/i.test(x.addr)); if (!p) return;
  if (!p.buildingType){ p.buildingType = 'Co-op'; p.mgmtCompany = 'Halstead Management'; p.mgmtAgent = 'R. Torres'; p.mgmtPhone = '(212) 555-0140'; p.mgmtEmail = 'rtorres@example.com'; p.superName = 'Luis'; p.superPhone = '(212) 555-0101'; }
  const A = altOf(p); if (A.stage === 'none' && !A.text){ A.text = ALT_DEMO_TEXT; A.terms = altParse(A.text); ALT_TERMS.forEach(([k]) => { if (!A.terms[k]) A.terms[k] = null; }); A.readAt = today(); A.readBy = 'reader'; A.stage = 'received'; A.receivedAt = today(); A.history.push({at: today(), what: 'received from the managing agent'}, {at: today(), what: 'read'}); }
  DB.company.altSeeded = true;
}
const renderBase_alt = render;
render = function(){ altSeed(); return renderBase_alt(); };
