/*<<brief2.js>>*/
/* ---------- the brief, by role ----------
   One brief was served to five roles with the name swapped: the coordinator was told about bank
   matches she cannot confirm and design fees she does not bill; the controller was told which job
   needed attention on site. A brief is the answer to a person's first three questions of the day,
   and the questions differ by desk. Each role now gets its own facts, its own sentences and its own
   cards — and nothing on it that the role has no screen to act on. The Ask box stays; it answers
   from the same facts.                                                                            */

const b2Row = (n, title, sub, go, act) => `<div class="h4r" ${go ? `data-h4go='${esc(JSON.stringify(go))}'` : ''}><span class="h4r-n ${n && String(n).startsWith('!') ? 'bad' : ''}">${esc(String(n || '·').replace(/^!/, ''))}</span><span class="grow">${title}${sub ? ` <span class="small muted">· ${sub}</span>` : ''}</span>${act ? `<em class="small">${act} ›</em>` : ''}</div>`;
const b2More = (n, shown) => n > shown ? `<div class="small muted" style="padding:6px 0">+ ${n - shown} more</div>` : '';
const b2Empty = s => `<div class="muted small">${s}</div>`;
const b2Plural = (n, one, many) => `${n} ${n === 1 ? one : (many || one + 's')}`;

/* ---------- facts each desk needs ---------- */
function b2Facts(F){
  const td = today(); const in7 = iso(addDays(td, 7)); const X = {};
  /* approvals by rung */
  X.billsPM = DB.bills.filter(b => b.status === 'submitted'); X.billsOwner = DB.bills.filter(b => b.status === 'pm-approved');
  X.posPending = F.posPending; X.cosToSign = DB.clients.flatMap(c => c.changeOrders.filter(x => x.status === 'sent').map(x => ({c, x})));
  X.timeWaiting = DB.time.filter(t => t.status === 'submitted');
  /* exceptions by owner */
  const exc = typeof openExceptions === 'function' ? openExceptions() : []; X.excOwner = exc.filter(t => typeof vfOwnerOf === 'function' && vfOwnerOf(t, t.verification || {ex: []}) === 'Owner'); X.excCtl = exc.filter(t => typeof vfOwnerOf === 'function' && vfOwnerOf(t, t.verification || {ex: []}) !== 'Owner'); X.exc = exc;
  /* the field */
  X.field = DB.projects.flatMap(p => (p.issues || []).filter(i => issueState(i).sev >= 2 && i.status !== 'answered' && i.status !== 'closed').map(i => ({p, i})));
  X.decOver = DB.projects.flatMap(p => { const keep = S; S = p; applyHolidays(); const r = (p.decisions || []).filter(d => d.status === 'open' && decState(d).sev >= 2).map(d => ({p, d, st: decState(d), due: decDue(d)})); S = keep; applyHolidays(); return r; });
  X.noShows = ((DB.field && DB.field.subs) || []).filter(s => s.status === 'noshow' && s.date >= iso(addDays(td, -3))).map(s => ({s, p: DB.projects.find(p => p.id === s.projectId)}));
  X.insp = F.inspections;
  /* jobs at risk and margin */
  X.risk = F.jobs.filter(j => j.score < 65 || j.late > 0);
  X.margin = F.jobs.filter(j => j.J && j.J.contract).map(j => ({j, plan: j.J.plannedGPPct || 0, est: j.J.estGPPct || 0, fade: r2((j.J.estGPPct || 0) - (j.J.plannedGPPct || 0))})).filter(x => x.fade <= -3).sort((a, b) => a.fade - b.fade);
  /* purchasing */
  X.buy = typeof buyList === 'function' ? buyList('') : []; X.buyLate = X.buy.filter(r => r.sev === 3); X.buyWeek = X.buy.filter(r => r.sev === 2);
  X.unacked = DB.projects.flatMap(p => (p.requests || []).filter(r => r.status === 'new' && !r.ackAt).map(r => ({p, r})));
  X.arriving = DB.pos.filter(po => !['cancelled','draft','received'].includes(po.status) && po.expected && po.expected >= td && po.expected <= in7).map(po => ({po, p: DB.projects.find(p => p.id === po.projectId)}));
  X.returns = (typeof retList === 'function' ? retList() : []).filter(r => typeof RET_OPEN !== 'undefined' && RET_OPEN.includes(r.status));
  X.vendorsWeak = [...new Set(DB.pos.filter(po => !['cancelled','draft','received'].includes(po.status)).map(po => po.vendor))].map(v => DB.vendors.find(x => x.name === v)).filter(v => v && (!v.insuranceExp || v.insuranceExp < td));
  X.billsVsPO = DB.bills.filter(b => ['submitted','pm-approved'].includes(b.status) && b.poId).map(b => { const po = DB.pos.find(p => p.id === b.poId); const gap = po ? r2(billTotal(b) - poTotal(po).total) : 0; return {b, po, gap}; }).filter(x => x.po && Math.abs(x.gap) > 1);
  /* billing */
  X.ready = typeof billingSuggestions === 'function' ? billingSuggestions() : [];
  X.drafts = DB.clients.flatMap(c => c.invoices.filter(i => i.status === 'draft').map(i => ({c, i, t: docTotal(i)})));
  X.unpaid = DB.clients.flatMap(c => c.invoices.filter(i => !['paid','void','draft'].includes(i.status)).map(i => ({c, i, bal: r2(docTotal(i).total - invoicePaid(c, i)), age: i.due ? dayDiff(i.due, td) : 0})).filter(x => x.bal > 0.005)).sort((a, b) => b.age - a.age);
  X.undep = typeof undepositedReceipts === 'function' ? undepositedReceipts() : [];
  X.retHeld = r2(DB.clients.reduce((a, c) => a + (clientFin(c).retHeld || 0), 0));
  /* controls */
  X.books = typeof rxBooksThrough === 'function' ? rxBooksThrough() : null;
  X.feedGap = (DB.accounts || []).filter(a => a.type === 'bank').map(a => ({a, gap: r2(acctBook(a) - (+a.balance || 0))})).filter(x => Math.abs(x.gap) > 0.5);
  X.payrollDue = (DB.payroll || []).filter(r => r.payDate && r.payDate <= in7 && !['paid','verified','void'].includes(r.status));
  X.dueWeek = F.dueWeek;
  return X;
}

/* ---------- sentences ---------- */
const briefSentencesBase_b2 = briefSentences;
briefSentences = function(F, r){
  if (!['owner','pm','coord','billing','controller'].includes(r)) return briefSentencesBase_b2(F, r);
  const X = b2Facts(F); const name = (currentUser()?.name || '').split(' ')[0]; const hour = new Date().getHours(); const hi = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  const dayName = new Date(F.td + 'T12:00:00').toLocaleDateString('en-US', {weekday: 'long', month: 'long', day: 'numeric'});
  const out = [`${hi}, ${name || 'there'}. ${dayName}.`]; const b = F.B;
  const cash = () => b.trulyOurs < 0 ? `Cash is ${moneyK(b.cash)}, but after client funds and what we owe we are ${moneyK(-b.trulyOurs)} short — collect before spending.` : `Cash is ${moneyK(b.cash)}, ${moneyK(b.trulyOurs)} truly ours; the 13-week low is ${moneyK(F.low)}${F.lowWeek ? ` (week of ${fmt(F.lowWeek.start)})` : ''}.`;
  if (r === 'owner'){
    const n = X.billsOwner.length + X.posPending.length + X.excOwner.length;
    out.push(n ? `${b2Plural(n, 'thing is', 'things are')} yours to decide: ${[X.billsOwner.length ? b2Plural(X.billsOwner.length, 'bill') + ' for payment' : '', X.posPending.length ? b2Plural(X.posPending.length, 'PO') + ' over your threshold' : '', X.excOwner.length ? b2Plural(X.excOwner.length, 'bank exception') : ''].filter(Boolean).join(', ')}.` : 'Nothing is waiting on your signature.');
    out.push(cash());
    out.push(X.risk.length ? `${X.risk.map(j => j.name).slice(0, 2).join(' and ')} ${X.risk.length === 1 ? 'needs' : 'need'} attention — ${X.risk[0].late > 0 ? `${X.risk[0].name} is ${X.risk[0].late} working days behind` : `${X.risk[0].name}: ${(X.risk[0].h.health && X.risk[0].h.health.why && X.risk[0].h.health.why[0]) || X.risk[0].urgent + ' urgent items'}`}.` : `All ${F.jobs.length} jobs are on target.`);
    if (X.margin.length) out.push(`Margin is fading on ${X.margin[0].j.name}: ${X.margin[0].est}% at completion against ${X.margin[0].plan}% bid.`);
    if (F.arOver) out.push(`${moneyK(F.arOver)} is overdue from clients.`); else if (X.ready.length) out.push(`${b2Plural(X.ready.length, 'invoice')} could go out today — ${money(X.ready.reduce((a, s) => a + (s.amount || 0), 0))}.`);
  }
  if (r === 'pm'){
    const blocks = X.field.length + X.decOver.length + X.noShows.length;
    out.push(blocks ? `${b2Plural(blocks, 'thing is', 'things are')} blocking the field: ${[X.field.length ? b2Plural(X.field.length, 'question') + ' from the foreman' : '', X.decOver.length ? b2Plural(X.decOver.length, 'overdue decision') : '', X.noShows.length ? b2Plural(X.noShows.length, 'sub no-show') : ''].filter(Boolean).join(', ')}.` : 'Nothing is blocking the field this morning.');
    if (X.risk.length) out.push(`${X.risk[0].name}: ${X.risk[0].late > 0 ? `${X.risk[0].late} working days behind target` : `${X.risk[0].urgent} urgent items`}${X.risk[0].next ? `; next: ${String(X.risk[0].next.n).replace(/^(Starts|Finishes|Due):\s*/i, '')} ${fmt(X.risk[0].next.d)}` : ''}.`);
    if (X.insp.length) out.push(`${b2Plural(X.insp.length, 'inspection')} this week — first ${X.insp[0].i.name || X.insp[0].i.type || 'inspection'} on ${fmt(X.insp[0].i.date)}.`);
    const mine = X.billsPM.length + X.timeWaiting.length; if (mine) out.push(`${[X.billsPM.length ? b2Plural(X.billsPM.length, 'bill') + ' to review' : '', X.timeWaiting.length ? b2Plural(X.timeWaiting.length, 'time sheet') + ' to approve' : ''].filter(Boolean).join(' and ')}.`);
    const prog = X.ready.filter(s => s.kind === 'progress'); if (prog.length) out.push(`${prog[0].p.project.name} has earned a progress bill — ${money(prog[0].amount)}.`);
  }
  if (r === 'coord'){
    out.push(X.buyLate.length || X.buyWeek.length ? `Buy: ${X.buyLate.length ? b2Plural(X.buyLate.length, 'item') + ' past order-by' : ''}${X.buyLate.length && X.buyWeek.length ? ', ' : ''}${X.buyWeek.length ? b2Plural(X.buyWeek.length, 'item') + ' to order this week' : ''}.` : 'The buy board is clear.');
    if (X.unacked.length) out.push(`${b2Plural(X.unacked.length, 'field request')} ${X.unacked.length === 1 ? 'is' : 'are'} waiting for you to acknowledge — the foreman is watching the clock.`);
    if (X.arriving.length) out.push(`${b2Plural(X.arriving.length, 'delivery', 'deliveries')} due this week; first ${X.arriving[0].po.vendor} ${fmt(X.arriving[0].po.expected)}.`);
    if (X.vendorsWeak.length) out.push(`${X.vendorsWeak.map(v => v.name).slice(0, 2).join(' and ')} ${X.vendorsWeak.length === 1 ? 'has' : 'have'} no current insurance — no new PO until it lands.`);
    if (X.returns.length) out.push(`${b2Plural(X.returns.length, 'return')} still waiting on a credit.`);
    if (X.billsVsPO.length) out.push(`${b2Plural(X.billsVsPO.length, 'vendor bill')} ${X.billsVsPO.length === 1 ? 'does' : 'do'} not match its PO — ${X.billsVsPO[0].b.vendor} is ${money(Math.abs(X.billsVsPO[0].gap))} ${X.billsVsPO[0].gap > 0 ? 'over' : 'under'}.`);
  }
  if (r === 'billing'){
    out.push(X.ready.length ? `${b2Plural(X.ready.length, 'invoice')} ready to go out — ${money(X.ready.reduce((a, s) => a + (s.amount || 0), 0))} earned and not yet billed.` : 'Nothing new has earned an invoice since the last one.');
    if (X.drafts.length) out.push(`${b2Plural(X.drafts.length, 'draft')} waiting to be sent — ${money(X.drafts.reduce((a, d) => a + d.t.total, 0))}.`);
    const over = X.unpaid.filter(x => x.age > 0); out.push(over.length ? `${money(over.reduce((a, x) => a + x.bal, 0))} is past due across ${b2Plural(over.length, 'invoice')}; oldest is ${over[0].c.name}, ${over[0].age} days.` : `${money(X.unpaid.reduce((a, x) => a + x.bal, 0))} is out with clients, none past due.`);
    if (X.undep.length) out.push(`${b2Plural(X.undep.length, 'payment')} recorded but not yet seen in the bank.`);
    if (X.cosToSign.length) out.push(`${b2Plural(X.cosToSign.length, 'change order')} sent and unsigned — ${money(X.cosToSign.reduce((a, x) => a + docTotal(x.x).total, 0))} not yet in the contract.`);
  }
  if (r === 'controller'){
    const bt = X.books; out.push(bt && bt.through ? `The books are reconciled through ${fmtL(bt.through)}.` : `The books are not reconciled through any date — ${bt ? bt.why : 'no statement on file'}.`);
    if (X.feedGap.length) out.push(`${X.feedGap.map(x => `${x.a.name} is ${money(Math.abs(x.gap))} ${x.gap > 0 ? 'ahead of' : 'behind'} the bank feed`).join('; ')}.`);
    out.push(!DB.lastVerify ? 'Verification has not been run — run it and the exceptions will be listed with their owners.' : X.exc.length ? `${b2Plural(X.exc.length, 'exception')} open — ${X.excOwner.length} for the owner, ${X.excCtl.length} yours.` : 'No open exceptions.');
    out.push(`${b2Plural(X.dueWeek.length, 'bill')} due in seven days, ${money(X.dueWeek.reduce((a, b) => a + billTotal(b), 0))}${X.payrollDue.length ? `; ${b2Plural(X.payrollDue.length, 'payroll run')} to pay` : ''}.`);
    out.push(cash());
  }
  return out.filter(Boolean);
};

/* ---------- cards ---------- */
const h4HomeBase_b2 = h4Home;
h4Home = function(F){
  const r = role(); if (!['owner','pm','coord','billing','controller'].includes(r)) return h4HomeBase_b2(F);
  const X = b2Facts(F); const cards = [];
  const moneyCard = () => `<div class="h4kv"><span>Safe to spend</span><b class="${F.B.trulyOurs < 0 ? 'bad' : ''}">${money(F.B.trulyOurs)}</b></div><div class="h4kv"><span>Cash on the books</span><b>${money(F.B.cash)}</b></div><div class="h4kv"><span>Receivables</span><b>${money(F.arTotal)}</b><i class="${F.arOver ? 'bad' : ''}">${F.arOver ? money(F.arOver) + ' overdue' : 'none overdue'}</i></div><div class="h4kv"><span>Payables</span><b>${money(F.B.ap)}</b><i>${money(X.dueWeek.reduce((a, b) => a + billTotal(b), 0))} due in 7 days</i></div><div class="h4kv"><span>13-week low</span><b class="${F.low < 0 ? 'bad' : ''}">${money(F.low)}</b><i>${F.lowWeek ? 'week of ' + fmt(F.lowWeek.start) : ''}</i></div>`;
  const why = j => j.late > 0 ? `${j.late} d behind` : j.score < 65 ? ((j.h.health && j.h.health.why && j.h.health.why[0]) || `${j.urgent} urgent`) : 'on target';
  const nextOf = j => j.next ? ` · ${esc(String(j.next.n).replace(/^(Starts|Finishes|Due):\s*/i, ''))} ${fmt(j.next.d)}` : '';
  const jobsCard = (list) => list.map(j => `<div class="h4r" data-h4go='${esc(JSON.stringify({view: 'dash', proj: j.p.id}))}'><span class="h4dot ${j.score >= 70 ? 'ok' : j.score >= 45 ? 'warn' : 'bad'}"></span><span class="grow"><b>${esc(j.name)}</b><span class="small muted"> · ${esc(why(j))}${nextOf(j)}</span></span><span class="small muted">${j.J && j.J.contract ? Math.round((j.J.pct || 0) * 100) + '%' : ''}</span></div>`).join('');

  if (r === 'owner'){
    const sign = [...X.billsOwner.map(b => b2Row(money(billTotal(b)), `Approve bill ${esc(b.number || '')} · ${esc(b.vendor)}`, 'PM has reviewed', {view: 'ap', billId: b.id}, 'Decide')),
                  ...X.posPending.map(po => b2Row(money(poTotal(po).total), `PO ${esc(po.number)} · ${esc(po.vendor)}`, 'over your threshold', {view: 'po', po: po.id}, 'Approve')),
                  ...X.excOwner.slice(0, 3).map(t => b2Row('!' + money(-t.amt), esc(t.desc), (t.verification.ex[0] || {}).m || 'exception', {view: 'verify'}, 'Respond'))];
    cards.push(h4Card('Yours to decide', sign.join('') || b2Empty('Nothing is waiting on your signature.'), {view: 'verify'}, sign.length ? `All ${sign.length}` : ''));
    cards.push(h4Card('Accounting', moneyCard(), {view: 'dashboard'}));
    const risk = X.risk.length ? jobsCard(X.risk) : jobsCard(F.jobs.slice(0, 4));
    cards.push(h4Card(X.risk.length ? 'Jobs at risk' : 'Jobs', risk + (X.margin.length ? X.margin.slice(0, 3).map(x => b2Row('!' + x.fade + ' pts', `${esc(x.j.name)} margin fading`, `${x.est}% at completion vs ${x.plan}% bid`, {view: 'costs', proj: x.j.p.id}, 'Costs')).join('') : ''), {view: 'port'}));
    const inRows = [...F.overdue.slice(0, 3).map(x => b2Row('!' + money(x.o.bal), `${esc(x.c.name)} · ${esc(x.o.x.number)}`, `due ${fmt(x.o.x.due)}`, {view: 'billing'}, 'Chase')), ...X.ready.slice(0, 3).map(s => b2Row(money(s.amount), esc(s.title), '', {view: 'billing'}, 'Bill'))];
    cards.push(h4Card('Money in', inRows.join('') || b2Empty('Nothing overdue, nothing waiting to be billed.'), {view: 'billing'}));
  }
  if (r === 'pm'){
    const blk = [...X.field.slice(0, 4).map(x => b2Row('!' + (x.i.since ? '' : ''), `${esc(x.i.title || x.i.text || 'Field question')}`, `${esc(x.p.project.name)} · ${esc(x.i.by || 'foreman')}`, {view: 'field', proj: x.p.id}, 'Answer')),
                 ...X.decOver.slice(0, 4).map(x => b2Row('!' + fmt(x.due), esc(x.d.name), `${esc(x.p.project.name)} · owed by ${esc(x.d.owner || '—')} · ${esc(x.st.msg || '')}`, {view: 'dec', proj: x.p.id}, 'Chase')),
                 ...X.noShows.map(x => b2Row('!' + fmt(x.s.date), `${esc(x.s.vendor || x.s.lead || 'Sub')} did not show`, esc(x.p ? x.p.project.name : ''), x.p ? {view: 'field', proj: x.p.id} : null, 'Call'))];
    cards.push(h4Card('Blocking this week', blk.join('') || b2Empty('Nothing is blocking the field.'), {view: 'field'}));
    cards.push(h4Card('Jobs', jobsCard(F.jobs.slice(0, 6)), {view: 'port'}));
    const site = [...X.insp.slice(0, 3).map(x => b2Row(fmt(x.i.date), esc(x.i.name || x.i.type || 'Inspection'), esc(x.p.project.name), {view: 'insp', proj: x.p.id})), ...X.arriving.slice(0, 3).map(x => b2Row(fmt(x.po.expected), `${esc(x.po.vendor)} · ${esc(x.po.number)}`, esc(x.p ? x.p.project.name : ''), {view: 'recv'}))];
    cards.push(h4Card('This week on site', site.join('') || b2Empty('No inspections or deliveries scheduled.'), {view: 'sched'}));
    const mine = [...X.billsPM.slice(0, 3).map(b => b2Row(money(billTotal(b)), `Review bill ${esc(b.number || '')} · ${esc(b.vendor)}`, '', {view: 'ap', billId: b.id}, 'Review')), X.timeWaiting.length ? b2Row(X.timeWaiting.length, 'time sheets to approve', '', {view: 'time'}, 'Approve') : '', ...X.ready.filter(s => s.kind === 'progress').slice(0, 2).map(s => b2Row(money(s.amount), esc(s.title), '', {view: 'billing'}, 'Draft'))];
    cards.push(h4Card('Mine to approve', mine.join('') || b2Empty('Nothing waiting on you.'), {view: 'ap'}));
  }
  if (r === 'coord'){
    const buy = [...X.buyLate.slice(0, 5).map(x => b2Row('!' + fmt(x.orderBy), esc(x.name), `${esc(x.p.project.name)} · ${esc(x.why || '')}`, {view: 'proc'}, 'Buy')), ...X.buyWeek.slice(0, 4).map(x => b2Row(fmt(x.orderBy), esc(x.name), esc(x.p.project.name), {view: 'proc'}, 'Buy'))];
    cards.push(h4Card('Buy', buy.join('') || b2Empty('The buy board is clear.'), {view: 'proc'}, `${X.buy.length} open`));
    const req = X.unacked.map(x => b2Row('!' + fmt(x.r.neededBy), esc(typeof reqLabel === 'function' ? reqLabel(x.r) : x.r.what), `${esc(x.p.project.name)} · ${esc(x.r.by || '')}`, {view: 'req'}, 'Acknowledge'));
    cards.push(h4Card('Field requests to acknowledge', req.join('') || b2Empty('Every request has been acknowledged.'), {view: 'req'}));
    const arr = [...X.arriving.slice(0, 4).map(x => b2Row(fmt(x.po.expected), `${esc(x.po.vendor)} · ${esc(x.po.number)}`, esc(x.p ? x.p.project.name : ''), {view: 'recv'})), ...X.returns.slice(0, 3).map(rt => b2Row(typeof retExpected === 'function' ? money(retExpected(rt)) : '·', `Return · ${esc(rt.vendor || '')}`, esc(rt.reason || ''), {view: 'recv'}, 'Chase credit'))];
    cards.push(h4Card('Arriving and going back', arr.join('') || b2Empty('Nothing due this week, nothing waiting on a credit.'), {view: 'recv'}));
    const vend = [...X.vendorsWeak.slice(0, 3).map(v => b2Row('!COI', esc(v.name), v.insuranceExp ? `insurance expired ${fmt(v.insuranceExp)}` : 'no insurance on file', {view: 'vendors'}, 'Chase')), ...X.billsVsPO.slice(0, 3).map(x => b2Row('!' + money(Math.abs(x.gap)), `${esc(x.b.vendor)} bill ${x.gap > 0 ? 'over' : 'under'} PO ${esc(x.po.number)}`, '', {view: 'ap', billId: x.b.id}, 'Check'))];
    cards.push(h4Card('Vendors', vend.join('') || b2Empty('Insurance current, bills match their POs.'), {view: 'vendors'}));
  }
  if (r === 'billing'){
    cards.push(h4Card('Ready to bill', X.ready.slice(0, 6).map(s => b2Row(money(s.amount), esc(s.title), esc(s.p ? s.p.project.name : ''), {view: 'billing'}, 'Draft')).join('') || b2Empty('Nothing has earned an invoice since the last one.'), {view: 'billing'}));
    cards.push(h4Card('Drafts to send', X.drafts.slice(0, 6).map(d => b2Row(money(d.t.total), `${esc(d.i.number)} · ${esc(d.c.name)}`, esc(d.i.title || ''), {view: 'billing'}, 'Open')).join('') || b2Empty('No drafts waiting.'), {view: 'billing'}));
    cards.push(h4Card('Sent, not paid', X.unpaid.slice(0, 6).map(u => b2Row((u.age > 0 ? '!' : '') + money(u.bal), `${esc(u.i.number)} · ${esc(u.c.name)}`, u.age > 0 ? `${u.age} d past due` : u.i.due ? `due ${fmt(u.i.due)}` : '', {view: 'billing'}, 'Open')).join('') || b2Empty('Everything sent has been paid.'), {view: 'billing'}));
    const rest = [...X.undep.map(x => b2Row(money(x.py.amount), `${esc(x.c.name)} · recorded ${fmt(x.py.date)}`, 'not yet in the bank', {view: 'bank'}, 'Banking')), ...X.cosToSign.slice(0, 3).map(x => b2Row(money(docTotal(x.x).total), `${esc(x.x.number)} · ${esc(x.c.name)}`, 'change order sent, unsigned', {view: 'billing'}, 'Open')), X.retHeld ? b2Row(money(X.retHeld), 'retainage held by clients', '', {view: 'billing'}) : ''];
    cards.push(h4Card('Deposits, change orders, retainage', rest.join('') || b2Empty('Nothing outstanding here.'), {view: 'billing'}));
  }
  if (r === 'controller'){
    const bt = X.books; const acc = (DB.accounts || []).map(a => { const th = typeof rxThrough === 'function' ? rxThrough(a.id) : ''; const g = X.feedGap.find(x => x.a.id === a.id); return b2Row(th ? fmt(th) : '!—', esc(a.name), th ? 'reconciled through' : 'never reconciled', {view: 'verify'}, 'Reconcile') + (g ? b2Row('!' + money(Math.abs(g.gap)), `${esc(a.name)} book vs feed`, g.gap > 0 ? 'book ahead of the bank' : 'bank ahead of the book', {view: 'bank'}) : ''); });
    cards.push(h4Card('The books', acc.join(''), {view: 'verify'}, bt && bt.through ? `Through ${fmt(bt.through)}` : 'Not reconciled'));
    const exc = [...X.excCtl.slice(0, 5).map(t => b2Row('!' + money(-t.amt), esc(t.desc), (t.verification.ex[0] || {}).m || '', {view: 'verify'}, 'Respond')), X.excOwner.length ? b2Row(X.excOwner.length, 'exceptions waiting on the owner', '', {view: 'verify'}) : ''];
    cards.push(h4Card('Exceptions', exc.join('') || b2Empty(DB.lastVerify ? 'No open exceptions.' : 'Verification has not been run yet.'), {view: 'verify'}, DB.lastVerify ? '' : 'Run it'));
    const pay = [...X.dueWeek.slice(0, 5).map(b => b2Row(money(billTotal(b)), `${esc(b.vendor)} · ${esc(b.number || '')}`, `due ${fmt(b.due)}${b.status !== 'approved' && b.status !== 'paid' ? ' · ' + esc(b.status) : ''}`, {view: 'ap', billId: b.id}, 'Open')), ...X.payrollDue.map(rn => b2Row(money(rn.total || 0), `Payroll ${esc(rn.from || '')}–${esc(rn.to || '')}`, `pay ${fmt(rn.payDate)}`, {view: 'time'}, 'Run'))];
    cards.push(h4Card('Going out this week', pay.join('') || b2Empty('Nothing due in seven days.'), {view: 'ap'}));
    cards.push(h4Card('Accounting', moneyCard(), {view: 'dashboard'}));
  }
  return `<div class="home4">${cards.join('')}</div>`;
};
/* the rows use the same router the brief already has, plus the bill opener from pass 2 */
document.addEventListener('click', e => { const el = e.target.closest('#v-home [data-h4go]'); if (!el) return; let go; try { go = JSON.parse(el.dataset.h4go); } catch(err){ return; } if (go && go.billId){ e.stopPropagation(); e.preventDefault(); iaOpenBillAfter = go.billId; view = 'ap'; render(); } }, true);

/* ---------- the Ask box, by role ----------
   The placeholder asked everyone "can we pay Carlos today?" and the offline answer to "what's on my
   plate" was the owner's week. Each desk now gets its own suggested questions and its own answer to
   the plate question; the assistant, when connected, still answers anything from the same facts. */
const B2_ASK = {
  owner:      ['What is mine to sign today?', 'How is cash?', 'Which job is bleeding?', 'What could we invoice today?'],
  pm:         ["What's blocking the field?", 'Which decisions are overdue and who owes them?', "What's on site this week?", 'What do I need to approve?'],
  coord:      ['What must be ordered this week?', 'Which requests have I not acknowledged?', "What's arriving this week?", 'Which vendors have no insurance?'],
  billing:    ['What can I invoice today?', 'What is past due?', 'Which drafts have not been sent?', 'Which change orders are unsigned?'],
  controller: ['Through what date are the books reconciled?', 'What goes out this week?', 'What exceptions are open?', 'How is cash, truly?'],
};
function b2Plate(r, F){
  const X = b2Facts(F); const L = [];
  if (r === 'owner'){ if (X.billsOwner.length) L.push(`Sign: ${X.billsOwner.map(b => `${b.vendor} ${money(billTotal(b))}`).join(', ')}`); if (X.posPending.length) L.push(`POs over your threshold: ${X.posPending.map(po => `${po.number} ${po.vendor} ${money(poTotal(po).total)}`).join(', ')}`); if (X.excOwner.length) L.push(`Bank exceptions for you: ${X.excOwner.length}`); L.push(`Cash ${money(F.B.cash)}, safe to spend ${money(F.B.trulyOurs)}, 13-week low ${money(F.low)}`); if (X.risk.length) L.push(`Jobs at risk: ${X.risk.map(j => `${j.name} (${j.late > 0 ? j.late + 'd behind' : 'health ' + j.score})`).join(', ')}`); if (X.margin.length) L.push(`Margin fading: ${X.margin.map(x => `${x.j.name} ${x.est}% vs ${x.plan}% bid`).join(', ')}`); if (F.arOver) L.push(`Overdue from clients: ${money(F.arOver)}`); }
  if (r === 'pm'){ if (X.field.length) L.push(`Field questions: ${X.field.map(x => `${x.i.title || x.i.text || 'question'} (${x.p.project.name})`).join('; ')}`); if (X.decOver.length) L.push(`Overdue decisions: ${X.decOver.map(x => `${x.d.name} — ${x.d.owner || '?'} (${x.p.project.name})`).join('; ')}`); if (X.noShows.length) L.push(`No-shows: ${X.noShows.map(x => x.s.vendor || x.s.lead).join(', ')}`); if (X.insp.length) L.push(`Inspections: ${X.insp.map(x => `${x.i.name || x.i.type} ${fmt(x.i.date)}`).join(', ')}`); if (X.billsPM.length) L.push(`Bills to review: ${X.billsPM.map(b => `${b.vendor} ${money(billTotal(b))}`).join(', ')}`); if (X.timeWaiting.length) L.push(`${X.timeWaiting.length} time sheets to approve`); }
  if (r === 'coord'){ if (X.buyLate.length) L.push(`Past order-by: ${X.buyLate.map(x => `${x.name} (${x.p.project.name})`).join('; ')}`); if (X.buyWeek.length) L.push(`Order this week: ${X.buyWeek.slice(0, 8).map(x => x.name).join(', ')}${X.buyWeek.length > 8 ? '…' : ''}`); if (X.unacked.length) L.push(`Acknowledge: ${X.unacked.map(x => `${typeof reqLabel === 'function' ? reqLabel(x.r) : x.r.what} (${x.p.project.name})`).join('; ')}`); if (X.arriving.length) L.push(`Arriving: ${X.arriving.map(x => `${x.po.vendor} ${fmt(x.po.expected)}`).join(', ')}`); if (X.vendorsWeak.length) L.push(`No current insurance: ${X.vendorsWeak.map(v => v.name).join(', ')}`); if (X.returns.length) L.push(`${X.returns.length} returns waiting on a credit`); }
  if (r === 'billing'){ if (X.ready.length) L.push(`Ready to bill: ${X.ready.map(s => `${s.title} (${money(s.amount)})`).join('; ')}`); if (X.drafts.length) L.push(`Drafts: ${X.drafts.map(d => `${d.i.number} ${d.c.name} ${money(d.t.total)}`).join(', ')}`); const over = X.unpaid.filter(x => x.age > 0); L.push(over.length ? `Past due: ${over.map(x => `${x.c.name} ${x.i.number} ${money(x.bal)} ${x.age}d`).join(', ')}` : `Nothing past due; ${money(X.unpaid.reduce((a, x) => a + x.bal, 0))} out`); if (X.undep.length) L.push(`Recorded, not in bank: ${X.undep.map(x => `${x.c.name} ${money(x.py.amount)}`).join(', ')}`); if (X.cosToSign.length) L.push(`Unsigned change orders: ${X.cosToSign.map(x => `${x.x.number} ${x.c.name}`).join(', ')}`); }
  if (r === 'controller'){ L.push(X.books && X.books.through ? `Reconciled through ${fmtL(X.books.through)}` : `Not reconciled — ${X.books ? X.books.why : 'no statement on file'}`); if (X.feedGap.length) L.push(`Book vs feed: ${X.feedGap.map(x => `${x.a.name} ${money(x.gap)}`).join(', ')}`); L.push(!DB.lastVerify ? 'Verification not run yet' : `${X.exc.length} exceptions open (${X.excOwner.length} owner, ${X.excCtl.length} controller)`); if (X.dueWeek.length) L.push(`Due in 7 days: ${X.dueWeek.map(b => `${b.vendor} ${money(billTotal(b))} ${fmt(b.due)}`).join(', ')}`); if (X.payrollDue.length) L.push(`Payroll to pay: ${X.payrollDue.map(rn => `${rn.from}–${rn.to} ${money(rn.total || 0)}`).join(', ')}`); L.push(`Cash ${money(F.B.cash)}, truly ours ${money(F.B.trulyOurs)}`); }
  return L.join('\n');
}
const jvLocalAnswerBase_b2 = jvLocalAnswer;
jvLocalAnswer = function(q, f){
  const r = role(); const s = q.toLowerCase();
  if (['owner','pm','coord','billing','controller'].includes(r)){
    const F = briefFacts(); const X = b2Facts(F);
    if (/plate|attention|focus|priorit|what should i|to do|todo|this week|today|mine to sign|sign today|approve/.test(s) && !/due|owe|cash|deliver|arriv|order|invoice|reconcil/.test(s)) return b2Plate(r, F);
    if (/block/.test(s)) return b2Plate('pm', F) || 'Nothing is blocking the field.';
    if (/order|buy/.test(s)) return [X.buyLate.length ? `Past order-by: ${X.buyLate.map(x => x.name).join(', ')}` : '', X.buyWeek.length ? `This week: ${X.buyWeek.map(x => x.name).join(', ')}` : ''].filter(Boolean).join('\n') || 'The buy board is clear.';
    if (/acknowledg|request/.test(s)) return X.unacked.length ? X.unacked.map(x => `${typeof reqLabel === 'function' ? reqLabel(x.r) : x.r.what} — ${x.p.project.name}, needed ${fmt(x.r.neededBy)}`).join('\n') : 'Every request has been acknowledged.';
    if (/insur|coi|vendor/.test(s)) return X.vendorsWeak.length ? `No current insurance: ${X.vendorsWeak.map(v => `${v.name}${v.insuranceExp ? ' (expired ' + fmt(v.insuranceExp) + ')' : ''}`).join(', ')}` : 'Every active vendor has current insurance on file.';
    if (/invoice|bill (them|it|today)|ready to bill/.test(s)) return X.ready.length ? X.ready.map(x => `${x.title} — ${money(x.amount)}`).join('\n') : 'Nothing has earned an invoice since the last one.';
    if (/draft/.test(s)) return X.drafts.length ? X.drafts.map(d => `${d.i.number} ${d.c.name} ${money(d.t.total)}`).join('\n') : 'No drafts waiting.';
    if (/past due|overdue|unpaid/.test(s)){ const over = X.unpaid.filter(x => x.age > 0); return over.length ? over.map(x => `${x.c.name} ${x.i.number} ${money(x.bal)} — ${x.age} days past due`).join('\n') : `Nothing past due; ${money(X.unpaid.reduce((a, x) => a + x.bal, 0))} out with clients.`; }
    if (/change order|unsigned/.test(s)) return X.cosToSign.length ? X.cosToSign.map(x => `${x.x.number} ${x.c.name} ${money(docTotal(x.x).total)}`).join('\n') : 'No change orders waiting on a signature.';
    if (/reconcil|books/.test(s)) return X.books && X.books.through ? `The books are reconciled through ${fmtL(X.books.through)}.` : `The books are not reconciled through any date — ${X.books ? X.books.why : 'no statement on file'}.`;
    if (/exception/.test(s)) return !DB.lastVerify ? 'Verification has not been run yet.' : X.exc.length ? X.exc.slice(0, 8).map(t => `${t.desc} ${money(-t.amt)} — ${(t.verification.ex[0] || {}).m || ''} (${typeof vfOwnerOf === 'function' ? vfOwnerOf(t, t.verification) : ''})`).join('\n') : 'No open exceptions.';
    if (/goes out|going out|due.*(week|7|seven)|owe/.test(s)) return X.dueWeek.length ? X.dueWeek.map(b => `${b.vendor} ${money(billTotal(b))} due ${fmt(b.due)}`).join('\n') + (X.payrollDue.length ? `\nPayroll: ${X.payrollDue.map(rn => money(rn.total || 0)).join(', ')}` : '') : 'Nothing due to vendors within 7 days.';
    if (/sign/.test(s)) return b2Plate('owner', F);
  }
  return jvLocalAnswerBase_b2(q, f);
};
const renderHomeBase_b2 = renderHome;
renderHome = function(){
  renderHomeBase_b2();
  const r = role(); const q = document.getElementById('jv-q'); const asks = B2_ASK[r]; if (!q || !asks) return;
  q.placeholder = `Ask — "${asks[0]}", "${asks[1]}"`;
  const ask = q.closest('.jv-ask'); if (!ask || ask.parentElement.querySelector('.jv-chips')) return;
  ask.insertAdjacentHTML('afterend', `<div class="chips jv-chips">${asks.map(a => `<button class="chip" data-jvchip="${esc(a)}">${esc(a)}</button>`).join('')}</div>`);
  ask.parentElement.querySelectorAll('[data-jvchip]').forEach(b => b.onclick = () => { q.value = b.dataset.jvchip; const go = document.getElementById('jv-go'); if (go) go.click(); });
};
