  if (d.ack){ requestAction(d.ack.pid, d.ack.rid, 'ack'); save(); render(); toast('Acknowledged — the foreman can see it, the driver can buy it'); return; }
  if (d.note){ const n = eaNotes().find(x => x.id === d.note); if (n){ n.done = true; n.doneAt = today(); save(); render(); } return; }
  if (d.chase){ if (d.chase === 'coi' && d.vendor){ const v = DB.vendors.find(x => x.name === d.vendor); if (v) eaNudge({kind: 'coi', t: `${v.name} — certificate of insurance`, vendor: v, msg: `Hi — we need a current certificate of insurance for ${v.name} before the next payment or purchase order can go out${v.insuranceExp ? ' (the one on file expired ' + fmtL(v.insuranceExp) + ')' : ''}. Could you send it over today? Thanks.`}); return; }
    const item = (window.__eaChase || [])[d.idx]; if (item) eaNudge(item); return; }
  if (d.suggest){ const c = DB.clients.find(x => x.id === d.suggest.clientId); const doc = c && findDoc(c, 'estimate', d.suggest.docId); if (!c || !doc) return; clientOpen = c.id; Promise.resolve(docAction(c, doc, d.suggest.act)).then(() => { save(); render(); }); return; }
  if (d.doc){ clientOpen = d.doc.clientId; docOpen = {kind: d.doc.kind, id: d.doc.id}; billTab = 'invoices'; view = 'billing'; render(); return; }
  if (d.billId){ iaOpenBillAfter = d.billId; view = 'ap'; render(); return; }
  if (d.ctl && typeof ctlTab !== 'undefined') ctlTab = d.ctl;
