/*<<comm.js>>*/
/* ---------- COMMUNICATIONS (comm.js) — the firm's mail, texts and calls become records ----------
   One Communications record per message (email, text, call transcript or call log, chat). Every record
   is routed to the person it came from (client, vendor, employee, or a new lead), the project it is
   about, and the document it answers. A reader proposes what the message means — a bill, a quote, a
   client decision, a deposit on its way, an alteration agreement, a permit event, a call to return, a
   meeting, an escalation — and a person applies it. Nothing writes itself. The live connection
   (Gmail watch, the firm's SMS number, call recording) lands in the hosted app; here the same records
   arrive by import, so the reader is proven on real traffic before a connector exists. */

const CM_STAFF = () => (DB.users || []).map(u => (u.contact || '').toLowerCase()).filter(e => e.includes('@'));
const CM_STAFF_DOMAINS = ['smartdesign.nyc', 'smartdesignbuild.com', 'mercerandbond.com'];
const CM_CATS = {bill:'Vendor bill', quote:'Quote', lead:'New lead', decision:'Client decision', deposit:'Payment on its way', alteration:'Alteration agreement', permit:'Permit / DOB', call:'Call to return', meeting:'Meeting', escalation:'Escalation', question:'Needs your answer', ar:'Invoice sent', delivery:'Delivery', coi:'Insurance / W-9', onboarding:'New client', note:'Note'};
const CM_ICON = {email:'<path d="M3 6h18v12H3z"/><path d="M3 7l9 6 9-6"/>', call:'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>', sms:'<path d="M4 5h16v11H8l-4 4z"/>', chat:'<path d="M4 5h16v11H8l-4 4z"/><path d="M8 9h8M8 12h5"/>'};

function cmInit(){ DB.comms = DB.comms || []; return DB.comms; }
const cmIsStaff = e => { e = (e || '').toLowerCase(); return CM_STAFF_DOMAINS.some(d => e.endsWith('@' + d)) || CM_STAFF().includes(e); };
const cmEmail = s => { const m = (s || '').match(/<([^>]+)>/); return (m ? m[1] : s || '').trim().toLowerCase(); };
const cmName = s => { const m = (s || '').match(/^\s*"?([^"<]+?)"?\s*</); if (m) return m[1].trim(); const e = cmEmail(s); const seen = (DB && DB.comms || []).find(x => x.from && (x.from.email || '').toLowerCase() === e && x.from.name && !/@/.test(x.from.name)); if (seen) return seen.from.name; return e.split('@')[0].replace(/\d+$/, '').replace(/[._]/g, ' ').replace(/\b\w/g, c => c.toUpperCase()); };
const cmMoney = t => { const m = (t || '').match(/\$\s?([\d,]+(?:\.\d{2})?)/g); if (!m) return 0; return Math.max(...m.map(x => +x.replace(/[^\d.]/g, ''))); };
/* the part of an email the person wrote, not the quoted history under it */
function cmOwnText(t){ t = (t || '').replace(/\r/g, ''); const cut = [/\nOn .{0,120}wrote:\s*\n/, /\n-{3,}\s*Forwarded message\s*-{3,}/i, /\nFrom: .{0,120}\nSent: /, /\n>\s/]; let i = t.length; cut.forEach(r => { const m = t.match(r); if (m && m.index < i) i = m.index; }); return t.slice(0, i).replace(/\n{3,}/g, '\n\n').trim(); }
const cmAddrRx = /\b(\d{1,5})\s+((?:East|West|North|South|E\.?|W\.?|N\.?|S\.?)\s+)?(\d{1,3}(?:st|nd|rd|th)?|[A-Za-z]+(?:\s[A-Za-z]+)?)\s+(Street|St\.?|Avenue|Ave\.?|Place|Pl\.?|Road|Rd\.?|Boulevard|Blvd\.?|Lane|Ln\.?|Court|Ct\.?)\b/gi;
const cmAddrRx2 = /\b(\d{1,5})\s+(East|West|E\.?|W\.?)\s+(\d{1,3}(?:st|nd|rd|th))\b(?!\s+(?:Street|St\b|Avenue|Ave\b))/gi;
const cmTitle = a => a.replace(/\s+/g, ' ').toLowerCase().replace(/\b([a-z])(\w*)/g, (m, c, r) => c.toUpperCase() + r).replace(/\b(\d+)(St|Nd|Rd|Th)\b/g, (m, n, o) => n + o.toLowerCase()).replace(/\b(E|W|N|S)\b/g, m => m.toUpperCase());
/* the firm's own address and anything under a signature line never count as "what this is about" */
function cmAddrs(t, subject){
  const firm = ((DB.company || {}).addr || '') + ' 31 Belvidere'; const firmKeys = cmAddrs.firmKeys || (cmAddrs.firmKeys = (firm.match(/\d{1,5}\s+[A-Za-z]+/g) || []).map(x => x.toLowerCase()));
  const body = (t || '').split(/\n--\s*\n|\n(?:Best|Thanks|Thank you|Regards|Sincerely),?\s*\n|\nVisit Smart Design/i)[0];
  const scan = src => { const out = []; let m; cmAddrRx.lastIndex = 0; while ((m = cmAddrRx.exec(src || ''))){ if (!/^(next|last|this|the|a|of|and|to|in|on|at|for|with|by|from|or|per)$/i.test(m[3])) out.push(cmTitle(m[0])); } cmAddrRx2.lastIndex = 0; while ((m = cmAddrRx2.exec(src || ''))) out.push(cmTitle(m[0])); return out; };
  const all = [...scan(subject || ''), ...scan(body)].filter(a => !firmKeys.some(k => a.toLowerCase().startsWith(k)));
  return [...new Set(all)];
}
const cmAddrKey = a => (a || '').toLowerCase().replace(/\b(east|e\.?)\b/, 'e').replace(/\b(west|w\.?)\b/, 'w').replace(/\b(street|st\.?)\b/, 'st').replace(/\b(avenue|ave\.?)\b/, 'ave').replace(/\b(place|pl\.?)\b/, 'pl').replace(/(\d)(st|nd|rd|th)\b/, '$1').replace(/[^a-z0-9]/g, '');

/* ---------- routing: who is this from, what is it about ---------- */
function cmRoute(c){
  const from = cmEmail(c.from && c.from.email || c.from); const fromName = (c.from && c.from.name) || cmName(c.from);
  const r = {clientId:'', vendorId:'', employee:'', projectId:'', addr:'', leadName:'', leadEmail:''};
  if (cmIsStaff(from)) r.employee = fromName;
  const cl = (DB.clients || []).find(cl => (cl.contacts || []).some(k => (k.email || '').toLowerCase() === from) || (cl.email || '').toLowerCase() === from || (from && (cl.name || '').toLowerCase().split(/\s|&/).filter(w => w.length > 3).some(w => from.includes(w))));
  if (cl) r.clientId = cl.id;
  const v = (DB.vendors || []).find(v => (v.email || '').toLowerCase() === from || (from.split('@')[1] || '').split('.')[0].length > 3 && (v.name || '').toLowerCase().replace(/[^a-z]/g, '').includes((from.split('@')[1] || '').split('.')[0].replace(/[^a-z]/g, '')));
  if (v && !cl) r.vendorId = v.id;
  const addrs = cmAddrs(cmOwnText(c.text), c.subject || ''); r.addr = addrs[0] || '';
  const keyOf = a => cmAddrKey(a);
  const proj = (DB.projects || []).find(p => addrs.some(a => keyOf(p.project.addr || '').startsWith(keyOf(a).slice(0, 8)) || keyOf(p.project.name || '').startsWith(keyOf(a).slice(0, 8))));
  if (proj) r.projectId = proj.id; else if (cl){ const p1 = (DB.projects || []).filter(p => p.clientId === cl.id); if (p1.length === 1) r.projectId = p1[0].id; }
  const known = !r.employee && (DB.comms || []).some(x => x.id !== c.id && cmIsStaff(cmEmail(x.from && x.from.email || x.from)) && [...(x.to || []), ...(x.cc || [])].map(cmEmail).includes(from));
  if (known) r.contact = fromName;
  if (!r.clientId && !r.vendorId && !r.employee && !known && !/noreply|no-reply|notification|donotreply|newsletter|billing@|accounts@|statements?@/.test(from)){ r.leadName = fromName; r.leadEmail = from; }
  if (r.employee){ const outs = [...(c.to || []), ...(c.cc || [])].filter(e => !cmIsStaff(cmEmail(e))); if (outs.length) r.counterpart = cmName(outs[0]); }
  /* to / cc can name the client when a staff member writes out */
  if (r.employee && !r.clientId){ const outs = [...(c.to || []), ...(c.cc || [])].map(cmEmail).filter(e => !cmIsStaff(e)); const cl2 = (DB.clients || []).find(cl => (cl.contacts || []).some(k => outs.includes((k.email || '').toLowerCase())) || outs.includes((cl.email || '').toLowerCase())); if (cl2) r.clientId = cl2.id; }
  return r;
}

/* ---------- the reader: what does this message mean ---------- */
function cmRead(c){
  const own = cmOwnText(c.text); const all = `${c.subject || ''}\n${own}`; const low = all.toLowerCase(); const R = c.route || cmRoute(c);
  const P = []; const push = (kind, summary, o) => P.push(Object.assign({id:uid('cp'), kind, summary, on:true}, o || {}));
  const amt = cmMoney(own); const att = (c.attachments || []).map(a => a.name.toLowerCase());
  const who = R.clientId ? (DB.clients.find(x => x.id === R.clientId) || {}).name : R.vendorId ? (DB.vendors.find(x => x.id === R.vendorId) || {}).name : (R.employee && R.counterpart) || R.leadName || R.contact || (c.from && c.from.name) || cmName(c.from);
  const proj = R.projectId ? DB.projects.find(p => p.id === R.projectId) : null; const where = proj ? proj.project.name : (R.addr || '');
  /* 1. a call log from the answering service */
  if (c.channel === 'call' || /posh assist/i.test(c.subject || '') || /caller'?s full name/i.test(own)){
    c.channel = 'call';
    const name = (own.match(/Caller'?s Full Name\s*:?\s*([^\n:]+?)(?:\s*Phone|\n|$)/i) || [])[1] || who; const phone = (own.match(/Phone Number\s*:?\s*([+\d() \-.]{7,})/i) || [])[1] || '';
    const re = (own.match(/Regarding\s*:?\s*([^\n]+?)(?:\s*Transfer Result|\n|$)/i) || [])[1] || (c.text.match(/Regarding\s*([^.]+\.)/i) || [])[1] || '';
    const transferred = /Transfer Result\s*:?\s*Transferred/i.test(own) && !/Not Transferred/i.test(own.replace(/Reason Not Transferred/i, ''));
    const forWho = (re.match(/speak (?:to|with)\s+([A-Z][a-z]+(?:\s[A-Z][a-z]+)?)/) || [])[1] || '';
    push('call', `${name.trim()} called${re ? ' — ' + re.trim() : ''}${transferred ? ' (transferred)' : ' (not reached)'}`, {name:name.trim(), phone:phone.trim(), regarding:re.trim(), forWho, task:!transferred ? `Call back ${name.trim()}${phone ? ' ' + phone.trim() : ''}${re ? ' — ' + re.trim() : ''}` : ''});
    return P;
  }
  /* 2. escalation — read this first, it changes the day */
  if (/unconscionable|are you kidding|costing us|unacceptable|extremely disappointed|this is ridiculous|with all due respect/i.test(own) && !R.employee){ push('escalation', `${who} is escalating${where ? ' on ' + where : ''}: "${own.replace(/\s+/g, ' ').slice(0, 140)}…"`, {task:`Call ${who} today${where ? ' about ' + where : ''} — escalation in writing`, owner:'owner'}); }
  /* 3. alteration agreement arriving */
  if (att.some(a => /alteration|work agreement|decorative|light work/.test(a)) || /alteration agreement/i.test(all)){
    const files = (c.attachments || []).filter(a => /alteration|agreement/i.test(a.name)).map(a => a.name);
    const coi = /\bcoi\b|certificate of insurance/i.test(all); const scope = /scope of work/i.test(all);
    push('alteration', `Alteration agreement${files.length > 1 ? 's' : ''} for ${where || 'the building'}${files.length ? ': ' + files.join(', ') : ''}${coi ? ' · the building also wants a COI' : ''}${scope ? ' and a detailed scope of work' : ''}`, {addr:R.addr, files, coi, scope, task:coi ? `Send COI to the managing agent for ${where || R.addr}` : ''});
  }
  /* 4. permits and DOB */
  const permits = [...new Set((all.match(/\b(?:B\d{8}(?:-I\d(?:-EL)?)?|SR\d{9}|[BME]\d{8})\b/g) || []))];
  if (/dob now|\bdob\b|permit|supersede|inspection|attestation/i.test(all) && (permits.length || /supersede|attestation|work complete/i.test(all))){
    const owner = /owner'?s attestation/i.test(own); const stillOpen = /still open|not closed|remains open|is open|sitting open/i.test(own); const sup = /supersede/i.test(own); const done = !stillOpen && !sup && /has been updated to complete|status.*complete|closed out|is complete/i.test(own);
    push('permit', `${where || 'Permit'}: ${permits.length ? permits.join(', ') + ' · ' : ''}${owner ? "DOB needs the owner's attestation on the supersede" : sup ? 'the permit is being superseded in DOB NOW' : done ? 'DOB shows the job complete' : stillOpen ? 'a permit is still open' : 'permit activity'}`, {permits, task:owner ? `Get the owner's attestation signed in DOB NOW${permits.length ? ' (' + permits[permits.length - 1] + ')' : ''}` : (stillOpen ? `Close the open permit${permits.length ? ' ' + permits[0] : ''} at ${where || R.addr}` : '')});
  }
  /* 5. money: a vendor's bill or statement to us */
  if (!R.employee && !R.clientId && amt && /invoice|statement|balance|amount due|past due|payment/i.test(all) && !/deposit.*sent|money (just )?sent/i.test(low)){
    const num = (all.match(/#\s?(\d{4,})|invoice\s*(?:no\.?|number)\s*[:#]?\s*([A-Z0-9-]*\d[A-Z0-9-]*)/i) || []).slice(1).find(Boolean) || '';
    const due = (all.match(/due\s+([A-Z][a-z]+ \d{1,2},? \d{4})/i) || [])[1] || '';
    const ent = (DB.entities || []).find(e => low.includes((e.name || '').toLowerCase().replace(/ llc$/, '')));
    push('bill', `${who} says ${money(amt)} is owed${ent ? ' by ' + ent.name : ''}${num ? ' · #' + num : ''}${due ? ' · due ' + due : ''}${/past due/i.test(all) ? ' · past due' : ''}`, {vendor:who, amount:amt, number:num, due, entityId:ent ? ent.id : ''});
  }
  /* 6. money: our invoice or deposit request going out */
  if (R.employee && (R.clientId || R.counterpart) && amt && /invoice|progress billing|deposit request|please send the .*deposit|retainer/i.test(all) && !/money (just )?sent/i.test(low)){
    push('ar', `We ${/deposit/i.test(all) ? 'asked ' + who + ' for a ' + money(amt) + ' deposit' : 'billed ' + who + ' ' + money(amt) + (/progress/i.test(all) ? ' as a progress bill' : '')}${where ? ' on ' + where : ''}`, {amount:amt, clientId:R.clientId, counterpart:R.counterpart, deposit:/deposit/i.test(all)});
  }
  /* 7. money on its way from a client */
  if (!R.employee && /money (just )?sent|wire (was |has been )?sent|payment (was |has been )?sent|sent the (deposit|payment|wire)|just paid/i.test(low)){
    const prior = (c.text.match(/\$\s?([\d,]+\.\d{2})/g) || []).map(x => +x.replace(/[^\d.]/g, '')); const expect = prior.length ? prior[0] : amt;
    push('deposit', `${who} says the money is sent${expect ? ' — ' + money(expect) : ''}${where ? ' for ' + where : ''}; watch the feed`, {amount:expect, clientId:R.clientId, task:`Confirm ${expect ? money(expect) + ' ' : ''}from ${who} arrived and record the payment`});
  }
  /* 8. a quote or estimate we sent, or one a vendor sent us */
  if (/quote|estimate|proposal/i.test(all) && att.some(a => /estimate|quote|proposal/.test(a))){
    if (R.employee) push('quote', `Our ${att.find(a => /estimate/.test(a)) ? 'estimate' : 'quote'} went to ${who}${where ? ' for ' + where : ''}${amt ? ' — ' + money(amt) : ''}`, {out:true, clientId:R.clientId, amount:amt});
    else push('quote', `${who} sent a quote${where ? ' for ' + where : ''}${amt ? ' — ' + money(amt) : ''}`, {out:false, vendorId:R.vendorId, amount:amt, task:`Review ${who}'s quote${where ? ' for ' + where : ''}`});
  }
  /* 9. a new lead: someone we do not know, writing about a place and an estimate */
  if (R.leadName && !R.clientId && !P.some(p => p.kind === 'deposit') && /estimate|renovat|apartment|\bapt\b|townhouse|brownstone|kitchen|bathroom|next steps|proposal/i.test(low) && !/unsubscribe|partner|roadshow|our (product|service)|we help|would you be open/i.test(low)){
    const when = (own.match(/\b(?:on\s+)?(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b[^.\n]{0,40}?(\d{1,2}(?::\d{2})?\s?(?:am|pm))?/i) || []);
    push('lead', `${R.leadName} is a new lead${R.addr ? ' at ' + R.addr : ''}${/estimate/i.test(low) ? ' — wants an estimate' : ''}${when[0] ? ' · meeting ' + when[0].trim() : ''}`, {name:R.leadName, email:R.leadEmail, addr:R.addr, next:/estimate/i.test(low) ? 'Send estimate' : 'Follow up', when:when[0] ? when[0].trim() : ''});
  }
  /* 10. insurance and tax paperwork */
  if (att.some(a => /\bcoi\b|certificate|w-?9/.test(a)) && !R.employee && (R.vendorId || !R.clientId)){ push('coi', `${who} sent ${att.find(a => /w-?9/.test(a)) ? 'a W-9' : 'a certificate of insurance'}`, {vendorId:R.vendorId, w9:att.some(a => /w-?9/.test(a))}); }
  /* 11. a meeting being set */
  const mt = own.match(/\b(?:meet|see you|call)\b[^.\n]{0,60}?\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|tomorrow)\b[^.\n]{0,30}?(\d{1,2}(?::\d{2})?\s?(?:am|pm)?)/i);
  if (mt && !P.some(p => p.kind === 'lead' && p.when)) push('meeting', `${who}: ${mt[0].trim()}`, {when:mt[0].trim(), task:`${mt[0].trim()} — ${who}${where ? ' · ' + where : ''}`});
  /* 12. a staff question that needs the owner's answer */
  if (R.employee && /\?/.test(own) && /would you like|should i|do you want|confirm|which|or\b/i.test(own) && (c.to || []).map(cmEmail).some(e => /^alan@/.test(e))){
    const q = (own.match(/[^.\n]*\?/) || [own.slice(0, 120)])[0].trim(); push('question', `${R.employee} needs an answer: ${q}`, {question:q, task:`Answer ${R.employee}: ${q}`, owner:'owner'});
  }
  /* 13. a client decision or approval */
  if (R.clientId && !R.employee && /approved?|go ahead|we choose|we'd like|let's go with|looks good|confirmed/i.test(low) && !P.some(p => p.kind === 'deposit')){ push('decision', `${who} approved or chose something${where ? ' on ' + where : ''}: "${own.replace(/\s+/g, ' ').slice(0, 120)}"`, {clientId:R.clientId}); }
  /* 14. new client welcomed */
  if (R.employee && /welcome/i.test(c.subject || '') && /new client/i.test(low)){ const nm = (own.match(/Hi\s+([A-Z][a-z]+)/) || [])[1] || ''; push('onboarding', `${R.employee} welcomed a new client${nm ? ' — ' + nm : ''}${R.addr ? ' at ' + R.addr : ''}`, {name:nm, addr:R.addr, email:[...(c.to || [])].map(cmEmail).find(e => !cmIsStaff(e)) || ''}); }
  /* 15. delivery */
  if (/delivered|out for delivery|tracking number|shipment/i.test(low) && !R.employee) push('delivery', `${who}: ${(own.match(/[^.\n]*(delivered|out for delivery)[^.\n]*/i) || [own.slice(0, 100)])[0].trim()}`, {});
  if (!P.length) push('note', `${who}${where ? ' · ' + where : ''}: ${own.replace(/\s+/g, ' ').slice(0, 140)}`, {});
  return P;
}
const cmSummary = c => (c.proposals || []).map(p => p.summary).join(' · ');

/* ---------- applying: each proposal becomes the record it names ---------- */
function cmTask(name, projectId, owner){
  const p = projectId ? DB.projects.find(x => x.id === projectId) : null;
  if (p){ p.tasks = p.tasks || []; const t = {id:uid('t'), name, trade:'close', owner:owner || 'PM', status:'planned', type:'task', deps:[], notes:'From a message', start:today(), end:today(), fromComm:true}; p.tasks.push(t); return t; }
  return typeof eaAddNote === 'function' ? eaAddNote(name, today()) : null;
}
function cmActivity(clientId, text){ const c = DB.clients.find(x => x.id === clientId); if (!c) return; c.activity = c.activity || []; c.activity.push({t:nowStamp(), by:'reader', text}); }
function cmApply(c, p){
  const R = c.route || cmRoute(c); const by = (currentUser() || {}).name || role(); let did = '';
  if (p.kind === 'call'){ if (p.task) cmTask(p.task, R.projectId, p.forWho || 'PM'); if (R.clientId) cmActivity(R.clientId, `Call: ${p.summary}`); did = p.task ? 'call-back task' : 'logged'; }
  else if (p.kind === 'escalation'){ cmTask(p.task, R.projectId, 'Owner'); if (R.clientId) cmActivity(R.clientId, `Escalation: ${p.summary}`); const pr = R.projectId && DB.projects.find(x => x.id === R.projectId); if (pr){ pr.project.flag = pr.project.flag || ''; pr.project.flag = `Client escalation ${fmt(today())}: ${p.summary.slice(0, 120)}`; } did = 'task for the Owner today'; }
  else if (p.kind === 'alteration'){
    const cl = R.clientId ? DB.clients.find(x => x.id === R.clientId) : null; let prop = null;
    if (cl){ cl.properties = cl.properties || []; prop = cl.properties.find(q => cmAddrKey(q.addr) === cmAddrKey(p.addr)) || cl.properties[0]; if (!prop && p.addr){ prop = {id:uid('pr'), addr:p.addr, buildingType:'Co-op', mgmtCompany:'', mgmtAgent:'', mgmtPhone:'', mgmtEmail:'', superName:'', superPhone:'', notes:''}; cl.properties.push(prop); } }
    if (prop && typeof altOf === 'function'){ const a = altOf(prop); if (a.stage === 'none'){ a.stage = 'received'; a.receivedAt = today(); } a.file = (p.files || []).join(', ') || a.file; a.history = a.history || []; a.history.push({t:nowStamp(), by, text:`Received by email: ${(p.files || []).join(', ') || 'agreement'}`}); did = 'agreement received on the building'; }
    if (p.task) cmTask(p.task, R.projectId, 'PM'); if (!did) did = 'task';
  }
  else if (p.kind === 'permit'){ if (p.task) cmTask(p.task, R.projectId, 'PM'); const pr = R.projectId && DB.projects.find(x => x.id === R.projectId); if (pr){ pr.permitNotes = pr.permitNotes || []; pr.permitNotes.push({t:nowStamp(), text:p.summary, permits:p.permits}); } if (R.clientId) cmActivity(R.clientId, p.summary); did = p.task ? 'permit task' : 'permit note'; }
  else if (p.kind === 'bill'){ DB.bills = DB.bills || []; const b = {id:uid('b'), vendor:p.vendor, number:p.number || '', date:(c.date || '').slice(0, 10) || today(), due:p.due ? iso(new Date(p.due)) : '', entityId:p.entityId || entDefault(), projectId:'', cat:'office', code:'', line:'', lines:[{id:uid('l'), desc:c.subject || 'Statement', amount:p.amount}], payMethod:'ACH', status:'submitted', approvals:[{t:nowStamp(), by, role:role(), action:'read from email'}], createdBy:'reader', commId:c.id}; DB.bills.push(b); if (!DB.vendors.some(v => v.name.toLowerCase() === (p.vendor || '').toLowerCase())) DB.vendors.push({id:uid('v'), name:p.vendor, trade:'', w9:false, insuranceExp:''}); did = `bill ${money(p.amount)} submitted for approval`; }
  else if (p.kind === 'ar'){ if (p.clientId) cmActivity(p.clientId, `${p.deposit ? 'Deposit request' : 'Invoice'} for ${money(p.amount)} sent by ${R.employee || 'us'} — ${c.subject || ''}`); else cmTask(`Watch for ${money(p.amount)} from ${p.counterpart || 'the client'} — ${c.subject || ''}`, '', 'Controller'); did = p.clientId ? 'logged on the client' : 'watching for the money'; }
  else if (p.kind === 'deposit'){ if (p.task) cmTask(p.task, '', 'Controller'); if (p.clientId) cmActivity(p.clientId, p.summary); DB.expected = DB.expected || []; DB.expected.push({id:uid('ex'), amount:p.amount, clientId:p.clientId || '', from:c.from && (c.from.name || c.from.email) || '', said:(c.date || '').slice(0, 10), commId:c.id}); did = 'watching the feed for it'; }
  else if (p.kind === 'quote'){ if (p.out && p.clientId) cmActivity(p.clientId, p.summary); if (!p.out){ cmTask(p.task, R.projectId, 'PM'); const v = p.vendorId && DB.vendors.find(x => x.id === p.vendorId); if (v){ v.notes = (v.notes ? v.notes + '\n' : '') + `${fmt(today())}: ${p.summary}`; } } did = p.out ? 'logged on the client' : 'review task'; }
  else if (p.kind === 'lead'){ DB.leads = DB.leads || []; if (!DB.leads.some(l => (l.email || '').toLowerCase() === (p.email || '').toLowerCase() && p.email)){ DB.leads.push({id:uid('ld'), created:today(), name:p.name, phone:'', email:p.email, addr:p.addr, buildingType:'', scope:'Design-build', stage:'inquiry', source:'Email', next:p.next, nextDue:'', notes:`${c.subject || ''}${p.when ? ' · ' + p.when : ''}`, commId:c.id}); } if (p.when) cmTask(`${p.when} — ${p.name}${p.addr ? ' · ' + p.addr : ''}`, '', 'Owner'); did = 'lead created'; }
  else if (p.kind === 'coi'){ const v = p.vendorId && DB.vendors.find(x => x.id === p.vendorId); if (v){ if (p.w9) v.w9 = true; else v.coiReceivedAt = today(); } did = v ? (p.w9 ? 'W-9 on file' : 'COI noted — set the expiry on the vendor') : 'noted'; }
  else if (p.kind === 'meeting'){ cmTask(p.task, R.projectId, 'Owner'); did = 'on the list'; }
  else if (p.kind === 'question'){ cmTask(p.task, R.projectId, 'Owner'); did = 'question for the Owner'; }
  else if (p.kind === 'decision'){ cmActivity(p.clientId, `Client wrote: ${cmOwnText(c.text).replace(/\s+/g, ' ').slice(0, 200)}`); did = 'logged as a client decision'; }
  else if (p.kind === 'onboarding'){ if (p.name && !DB.clients.some(cl => (cl.name || '').toLowerCase().includes(p.name.toLowerCase()))){ const cl = typeof blankClient === 'function' ? blankClient(p.name) : {id:uid('cl'), name:p.name, contacts:[], activity:[], invoices:[], estimates:[], changeOrders:[], sov:[], payments:[], docs:[]}; cl.propertyAddr = p.addr || ''; cl.contacts = [{id:uid('k'), name:p.name, email:p.email || '', role:'Client'}]; cl.entityId = entDefault(); DB.clients.push(cl); did = 'client created'; } else did = 'client already on file'; }
  else if (p.kind === 'delivery'){ if (R.projectId) cmTask(`Check delivery: ${p.summary.slice(0, 80)}`, R.projectId, 'Foreman'); did = 'noted'; }
  else { if (R.clientId) cmActivity(R.clientId, p.summary); else if (R.vendorId){ const v = DB.vendors.find(x => x.id === R.vendorId); if (v) v.notes = (v.notes ? v.notes + '\n' : '') + `${fmt(today())}: ${p.summary}`; } did = 'noted'; }
  p.applied = did; p.appliedAt = new Date().toISOString(); p.by = by;
  try { audit('comm', c.id, 'apply-' + p.kind, '', did, ''); } catch(e){}
  return did;
}

/* ---------- import: the shape a connector delivers ---------- */
function cmImport(list){
  cmInit(); let n = 0;
  (list || []).forEach(m => {
    const id = m.msgId || m.id; if (id && DB.comms.some(c => c.msgId === id)) return;
    const c = {id:uid('cm'), msgId:id || '', threadId:m.threadId || '', channel:m.channel || 'email', direction:m.direction || (cmIsStaff(cmEmail(m.from && m.from.email || m.from)) ? 'out' : 'in'), from:typeof m.from === 'string' ? {name:cmName(m.from), email:cmEmail(m.from)} : (m.from || {}), to:m.to || [], cc:m.cc || [], date:m.date || new Date().toISOString(), subject:m.subject || '', text:m.text || '', attachments:m.attachments || [], source:m.source || 'import', status:'new', proposals:[], links:m.links || []};
    c.route = cmRoute(c); c.proposals = cmRead(c); c.status = c.proposals.length ? 'proposed' : 'read'; DB.comms.push(c); n++;
  });
  if (n){ cmReroute(); try { audit('comm', 'import', 'read', '', `${n} messages`, ''); } catch(e){} save(); }
  return n;
}
function cmReroute(){ cmInit(); DB.comms.forEach(c => { if (c.status === 'applied' || c.status === 'ignored' || c.routeLocked) return; c.route = cmRoute(c); const keep = c.proposals.filter(p => p.applied); c.proposals = keep.concat(cmRead(c).filter(p => !keep.some(k => k.kind === p.kind))); }); }

/* ---------- the screen: Home › Messages ---------- */
let cmFilter = 'open', cmOpen = '';
function cmPartyChips(c){
  const R = c.route || {}; const chips = [];
  if (R.clientId){ const cl = DB.clients.find(x => x.id === R.clientId); if (cl) chips.push(`<span class="pill info" data-cmgo="client:${cl.id}">${esc(cl.name)}</span>`); }
  if (R.vendorId){ const v = DB.vendors.find(x => x.id === R.vendorId); if (v) chips.push(`<span class="pill neutral">${esc(v.name)}</span>`); }
  if (R.employee) chips.push(`<span class="pill neutral">${esc(R.employee)}</span>`);
  if (R.leadName && !R.clientId) chips.push(`<span class="pill warn">new: ${esc(R.leadName)}</span>`);
  if (R.projectId){ const p = DB.projects.find(x => x.id === R.projectId); if (p) chips.push(`<span class="pill ok" data-cmgo="project:${p.id}">${esc(p.project.name)}</span>`); } else if (R.addr) chips.push(`<span class="pill neutral">${esc(R.addr)}</span>`);
  return chips.join(' ');
}
function renderComms(){
  const host = $('#comms-body'); if (!host) return; cmInit();
  let L = DB.comms.slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const open = L.filter(c => c.proposals.some(p => !p.applied && p.on !== false) && c.status !== 'ignored');
  if (cmFilter === 'open') L = open; else if (cmFilter === 'calls') L = L.filter(c => c.channel === 'call'); else if (cmFilter === 'applied') L = L.filter(c => c.status === 'applied' || c.proposals.some(p => p.applied));
  const counts = {open:open.length, all:DB.comms.length, calls:DB.comms.filter(c => c.channel === 'call').length, applied:DB.comms.filter(c => c.proposals.some(p => p.applied)).length};
  const seg = [['open','Needs a decision'],['all','Everything'],['calls','Calls'],['applied','Applied']];
  host.innerHTML = `<div class="row wrap" style="gap:8px;align-items:center;margin-bottom:10px"><div class="ctabs" style="margin:0;border:0">${seg.map(s => `<button class="${cmFilter === s[0] ? 'on' : ''}" data-cmf="${s[0]}">${s[1]}${counts[s[0]] ? ` <span class="n">${counts[s[0]]}</span>` : ''}</button>`).join('')}</div><span class="grow"></span>${open.length ? `<button class="btn sm primary" id="cm-applyall">Apply everything I'm sure of</button>` : ''}<label class="btn sm">Import mail<input type="file" id="cm-file" accept=".json" hidden></label><button class="btn sm" id="cm-paste">Paste a message</button></div>
    ${DB.comms.length ? '' : `<div class="empty">Nothing has come in yet. When the mailbox, the firm's number and the call line are connected, every message lands here already routed to its person, project and document, with what it means proposed underneath. Until then, import a mail export or paste a message.</div>`}
    ${L.map(c => { const P = c.proposals || []; const pend = P.filter(p => !p.applied); const isOpen = cmOpen === c.id;
      return `<div class="card cm-row ${c.status}" data-cmid="${c.id}"><div class="row" style="gap:10px;align-items:flex-start"><svg class="cm-ic" viewBox="0 0 24 24">${CM_ICON[c.channel] || CM_ICON.email}</svg><div class="grow" style="min-width:0"><div class="row wrap" style="gap:6px;align-items:baseline"><b>${esc(c.from.name || c.from.email || '')}</b><span class="small muted">${c.direction === 'out' ? '→ ' + esc((c.to || []).map(cmName).join(', ')) : ''}</span><span class="small muted">${(c.date || '').slice(0, 10)}</span>${(c.attachments || []).length ? `<span class="small muted">· ${c.attachments.length} attachment${c.attachments.length > 1 ? 's' : ''}</span>` : ''}</div><div class="cm-subj">${esc(c.subject || '(no subject)')}</div><div class="row wrap" style="gap:4px;margin-top:4px">${cmPartyChips(c)}</div>
        ${P.length ? `<div class="cm-props">${P.map(p => `<div class="cm-prop ${p.applied ? 'done' : ''}"><span class="cat ${p.kind}">${CM_CATS[p.kind] || p.kind}</span><span class="grow">${esc(p.summary)}${p.applied ? ` <span class="small muted">· ${esc(p.applied)}${p.by ? ' · ' + esc(p.by) : ''}</span>` : ''}</span>${p.applied ? '' : `<button class="btn sm primary" data-cmapply="${c.id}|${p.id}">Apply</button><button class="btn sm ghost" data-cmskip="${c.id}|${p.id}">Not this</button>`}</div>`).join('')}</div>` : ''}
        <div class="cm-text ${isOpen ? '' : 'clip'}" data-cmtoggle="${c.id}">${esc(cmOwnText(c.text) || c.text || '')}</div></div></div></div>`; }).join('')}`;
  cmWire(host);
}
function cmWire(host){
  host.querySelectorAll('[data-cmf]').forEach(b => b.onclick = () => { cmFilter = b.dataset.cmf; renderComms(); });
  host.querySelectorAll('[data-cmtoggle]').forEach(d => d.onclick = () => { cmOpen = cmOpen === d.dataset.cmtoggle ? '' : d.dataset.cmtoggle; renderComms(); });
  host.querySelectorAll('[data-cmapply]').forEach(b => b.onclick = () => { const [cid, pid] = b.dataset.cmapply.split('|'); const c = DB.comms.find(x => x.id === cid); const p = c && c.proposals.find(x => x.id === pid); if (!p) return; const did = cmApply(c, p); if (c.proposals.every(x => x.applied || x.on === false)) c.status = 'applied'; save(); render(); toast(did); });
  host.querySelectorAll('[data-cmskip]').forEach(b => b.onclick = () => { const [cid, pid] = b.dataset.cmskip.split('|'); const c = DB.comms.find(x => x.id === cid); const p = c && c.proposals.find(x => x.id === pid); if (!p) return; p.on = false; p.applied = 'set aside'; p.by = (currentUser() || {}).name || role(); if (c.proposals.every(x => x.applied)) c.status = 'applied'; save(); renderComms(); });
  host.querySelectorAll('[data-cmgo]').forEach(s => s.onclick = e => { e.stopPropagation(); const [k, id] = s.dataset.cmgo.split(':'); if (k === 'client'){ clientOpen = id; view = 'clients'; render(); } else { if (typeof setCurrent === 'function') setCurrent(id); view = 'dash'; render(); } });
  const all = host.querySelector('#cm-applyall'); if (all) all.onclick = () => { let n = 0; window.__cmBulk = true; try { DB.comms.forEach(c => c.proposals.forEach(p => { if (p.applied || p.on === false) return; if (['escalation','bill','question'].includes(p.kind)) return; cmApply(c, p); n++; })); DB.comms.forEach(c => { if (c.proposals.length && c.proposals.every(p => p.applied)) c.status = 'applied'; }); } finally { window.__cmBulk = false; } save(); render(); toast(`Applied ${n} — bills, escalations and questions for you are left for your hand; tasks went to the PM, reassign from the task`); };
  const f = host.querySelector('#cm-file'); if (f) f.onchange = () => { const file = f.files[0]; if (!file) return; const rd = new FileReader(); rd.onload = () => { try { const j = JSON.parse(rd.result); const n = cmImport(Array.isArray(j) ? j : (j.messages || [])); render(); toast(`${n} message${n === 1 ? '' : 's'} read`); } catch(e){ toast('That file is not a mail export'); } }; rd.readAsText(file); };
  const pb = host.querySelector('#cm-paste'); if (pb) pb.onclick = () => mbModal('Paste a message', `${mbF('From', mbIn('from', '', 'name <email>'))}${mbF('Subject', mbIn('subject', '', ''))}<div class="f"><label>Message</label><textarea data-f="text" rows="8" placeholder="Paste the email or text here"></textarea></div>`, {submit:'Read it', onSubmit:f2 => { if (!f2.text){ toast('Paste something'); return false; } cmImport([{from:f2.from, subject:f2.subject, text:f2.text, date:new Date().toISOString(), channel:/^\+?\d[\d\s()-]{6,}$/.test(f2.from) ? 'sms' : 'email'}]); render(); }});
}

/* ---------- the assistant knows what came in ---------- */
if (typeof eaToday === 'function'){
  const eaTodayBase_cm = eaToday;
  eaToday = function(r, F, X){ const out = eaTodayBase_cm(r, F, X); if (r !== 'owner' && r !== 'pm') return out; cmInit();
    const open = DB.comms.filter(c => c.proposals.some(p => !p.applied && p.on !== false)); if (!open.length) return out;
    const esc1 = open.filter(c => c.proposals.some(p => p.kind === 'escalation' && !p.applied)); const calls = open.filter(c => c.channel === 'call');
    const item = {n:open.length, t:`${esc1.length ? `${esc1[0].from.name || 'A client'} escalated in writing — I'd call before anything else. ` : ''}${open.length} message${open.length > 1 ? 's' : ''} read and routed${calls.length ? `, ${calls.length} call${calls.length > 1 ? 's' : ''} to return` : ''}; what each means is waiting for your yes.`, go:{view:'comms'}, act:'Review'};
    /* a known client escalating comes before everything; otherwise the mail sits second, after the money */
    if (esc1.some(c => c.route && c.route.clientId)) out.unshift(item); else out.splice(Math.min(1, out.length), 0, item);
    return out; };
}

/* ---------- where it lives ---------- */
(() => {
  if (!document.getElementById('v-comms')){ const sec = document.createElement('section'); sec.className = 'view'; sec.id = 'v-comms'; sec.innerHTML = '<div class="ph"><div><h2>Messages</h2><div class="lead">Mail, texts and calls, routed to the person, the project and the document — with what each one means proposed underneath.</div></div></div><div id="comms-body"></div>'; (document.querySelector('#v-home')?.parentElement || document.querySelector('.main') || document.body).appendChild(sec); }
  if (typeof ROLE_VIEWS === 'object') ['owner','pm','controller','billing','design_mgr'].forEach(r => { if (ROLE_VIEWS[r] && !ROLE_VIEWS[r].includes('comms')) ROLE_VIEWS[r].push('comms'); });
  if (typeof IA_GROUPS !== 'undefined'){ const g = IA_GROUPS.find(x => x.id === 'home'); if (g && !g.views.includes('comms')) g.views.push('comms'); }
  if (typeof IA_LABELS !== 'undefined') IA_LABELS.comms = 'Messages';
  if (typeof NAV_GROUPS !== 'undefined'){ const g = NAV_GROUPS.find(x => x.id === 'home'); if (g && !g.views.includes('comms')) g.views.push('comms'); if (typeof NAV_LABELS === 'object') NAV_LABELS.comms = 'Messages'; }
  if (typeof IA_H2_SKIP !== 'undefined' && IA_H2_SKIP.add) IA_H2_SKIP.add('comms');
})();
if (typeof render === 'function'){ const renderBase_cm = render; render = function(){ renderBase_cm(); if (view === 'comms') renderComms(); }; }

