/*<<comm2.js>>*/
/* ---------- COMMUNICATIONS II (comm2.js) — from a message to the record, by hand or by proposal ----------
   On every message: make a task and assign it, log a note, create a client or a lead, and file the message
   and its attachments where they belong — the client's record (activity the team sees, documents), the
   building's agreement, the vendor's bill or COI, the project's photos. Proposals for tasks, leads and clients
   open an editor first, so what lands is what you meant. */

const CM_ASSIGNEES = () => (DB.users || []).filter(u => !['driver','crew'].includes(u.role)).map(u => u.name);
const cmClientOpts = sel => `<option value="">— none —</option>` + (DB.clients || []).map(c => `<option value="${c.id}" ${c.id === sel ? 'selected' : ''}>${esc(c.name)}</option>`).join('');
const cmProjOpts = sel => `<option value="">— firm-wide —</option>` + (DB.projects || []).map(p => `<option value="${p.id}" ${p.id === sel ? 'selected' : ''}>${esc(p.project.name)}</option>`).join('');
const cmUserOpts = sel => CM_ASSIGNEES().map(n => `<option ${n === sel ? 'selected' : ''}>${esc(n)}</option>`).join('');
function cmAfter(c, text){ c.filed = c.filed || []; c.filed.push({t:nowStamp(), by:(currentUser() || {}).name || role(), text}); }

/* ---------- tasks: assigned, dated, on the right project ---------- */
function cmTaskDialog(c, p){
  const R = c.route || cmRoute(c); const seed = (p && p.task) || `Follow up: ${c.subject || cmOwnText(c.text).slice(0, 60)}`;
  const guess = (p && p.owner === 'owner') ? 'Owner' : (p && p.forWho) || (R.projectId ? 'Alan' : 'Owner');
  const due = (() => { const d = new Date(today() + 'T12:00:00'); d.setDate(d.getDate() + ((p && (p.kind === 'escalation' || p.kind === 'call')) ? 0 : 2)); return iso(d); })();
  mbModal('Task from this message', `${mbF('Task', mbIn('name', seed, ''))}<div class="grid2">${mbF('Assign to', `<select data-f="owner">${cmUserOpts(guess)}</select>`)}${mbF('Due', mbIn('due', due, '', 'date'))}</div>${mbF('Project', `<select data-f="projectId">${cmProjOpts(R.projectId)}</select>`)}${mbF('Note for whoever picks it up', `<textarea data-f="notes" rows="3">${esc((c.subject ? c.subject + ' — ' : '') + cmOwnText(c.text).replace(/\s+/g, ' ').slice(0, 240))}</textarea>`)}`,
    {submit:'Create task', onSubmit:f => { if (!f.name){ toast('Name the task'); return false; }
      const t = cmTaskFull(f.name, f.projectId, f.owner, f.due, f.notes, c.id);
      if (p){ p.applied = `task for ${f.owner}${f.due ? ', due ' + fmt(f.due) : ''}`; p.appliedAt = new Date().toISOString(); p.by = (currentUser() || {}).name || role(); }
      cmAfter(c, `Task for ${f.owner}: ${f.name}`); if (c.proposals.length && c.proposals.every(x => x.applied)) c.status = 'applied';
      save(); render(); toast(`Task for ${f.owner}`); }});
}
function cmTaskFull(name, projectId, owner, due, notes, commId){
  const p = projectId ? DB.projects.find(x => x.id === projectId) : null;
  if (p){ p.tasks = p.tasks || []; const t = {id:uid('t'), name, trade:'close', owner:owner || 'PM', status:'planned', type:'task', deps:[], notes:notes || '', start:today(), end:due || today(), fromComm:commId || true}; p.tasks.push(t); try { audit('task', t.id, 'from-message', '', name, owner); } catch(e){} return t; }
  const n = typeof eaAddNote === 'function' ? eaAddNote(`${owner ? owner + ': ' : ''}${name}`, due || today()) : null; if (n) n.commId = commId; return n;
}

/* ---------- notes: logged where the team looks ---------- */
function cmNoteDialog(c){
  const R = c.route || cmRoute(c);
  mbModal('Log a note', `${mbF('Note', `<textarea data-f="text" rows="4">${esc(cmSummary(c) || cmOwnText(c.text).replace(/\s+/g, ' ').slice(0, 300))}</textarea>`)}<div class="grid2">${mbF('On the client', `<select data-f="clientId">${cmClientOpts(R.clientId)}</select>`)}${mbF('On the project', `<select data-f="projectId">${cmProjOpts(R.projectId)}</select>`)}</div>`,
    {submit:'Log it', onSubmit:f => { if (!f.text){ toast('Say something'); return false; } const by = (currentUser() || {}).name || role(); let where = [];
      if (f.clientId){ cmActivity(f.clientId, f.text); where.push((DB.clients.find(x => x.id === f.clientId) || {}).name); }
      if (f.projectId){ const p = DB.projects.find(x => x.id === f.projectId); if (p){ p.notesLog = p.notesLog || []; p.notesLog.push({t:nowStamp(), by, text:f.text, commId:c.id}); try { const keep = S; S = p; log(`Note from a message: ${f.text.slice(0, 120)}`, 'mail', by); S = keep; } catch(e){} where.push(p.project.name); } }
      if (!where.length && typeof eaAddNote === 'function'){ eaAddNote(f.text, ''); where.push('your notes'); }
      cmAfter(c, `Note logged on ${where.join(' and ')}`); save(); render(); toast(`Logged on ${where.join(' and ')}`); }});
}

/* ---------- people: a lead or a client, prefilled from the message ---------- */
function cmPersonDialog(c, p, asClient){
  const R = c.route || cmRoute(c); const name = (p && p.name) || R.leadName || R.contact || (c.from && c.from.name) || ''; const email = (p && p.email) || R.leadEmail || (c.from && c.from.email) || '';
  const phone = ((c.text || '').match(/(?:\+1[\s-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/) || [''])[0];
  const addr = (p && p.addr) || R.addr || '';
  if (asClient){
    mbModal('New client from this message', `<div class="grid2">${mbF('Name', mbIn('name', name, ''))}${mbF('Company', mbIn('company', '', 'optional'))}</div><div class="grid2">${mbF('Email', mbIn('email', email, ''))}${mbF('Phone', mbIn('phone', phone, ''))}</div><div class="grid2">${mbF('Property', mbIn('addr', addr, 'street address'))}${mbF('Building', mbSel('buildingType', (typeof CRM_BUILDING !== 'undefined' ? CRM_BUILDING : ['', 'Townhouse', 'Condo', 'Co-op']).map(t => [t, t || '— choose —']), ''))}</div>${mbF('Entity', `<select data-f="entityId">${entOpts(entDefault())}</select>`)}<p class="small muted">The message and its attachments are filed on the new record, so the team sees where this came from.</p>`,
      {submit:'Create client', onSubmit:f => { if (!f.name){ toast('A name'); return false; }
        const cl = typeof blankClient === 'function' ? blankClient(f.name) : {id:uid('cl'), name:f.name, contacts:[], activity:[], docs:[], invoices:[], estimates:[], changeOrders:[], sov:[], payments:[]};
        cl.company = f.company || ''; cl.propertyAddr = f.addr || ''; cl.entityId = f.entityId || entDefault(); cl.contacts = [{id:uid('k'), name:f.name, email:f.email || '', phone:f.phone || '', role:'Client'}];
        if (f.addr){ cl.properties = [{id:uid('pr'), addr:f.addr, buildingType:f.buildingType || '', mgmtCompany:'', mgmtAgent:'', mgmtPhone:'', mgmtEmail:'', superName:'', superPhone:'', notes:''}]; }
        DB.clients.push(cl); c.route.clientId = cl.id; c.route.leadName = ''; cmFileToClient(c, cl.id);
        if (p){ p.applied = 'client created'; p.appliedAt = new Date().toISOString(); p.by = (currentUser() || {}).name || role(); }
        (DB.leads || []).forEach(l => { if (l.email && l.email.toLowerCase() === (f.email || '').toLowerCase()) l.stage = 'won'; });
        save(); render(); toast(`${f.name} is a client`); }});
    return;
  }
  const when = (p && p.when) || '';
  mbModal('New lead from this message', `<div class="grid2">${mbF('Name', mbIn('name', name, ''))}${mbF('Email', mbIn('email', email, ''))}</div><div class="grid2">${mbF('Phone', mbIn('phone', phone, ''))}${mbF('Property', mbIn('addr', addr, ''))}</div><div class="grid2">${mbF('Building', mbSel('buildingType', (typeof CRM_BUILDING !== 'undefined' ? CRM_BUILDING : ['', 'Townhouse', 'Condo', 'Co-op']).map(t => [t, t || '— choose —']), ''))}${mbF('Scope', mbSel('scope', typeof CRM_SCOPES !== 'undefined' ? CRM_SCOPES : ['Design-build'], 'Design-build'))}</div><div class="grid2">${mbF('Next step', mbIn('next', (p && p.next) || (when ? 'Meet ' + when : 'Follow up'), ''))}${mbF('Due', mbIn('nextDue', '', '', 'date'))}</div>${mbF('Notes', `<textarea data-f="notes" rows="2">${esc((c.subject || '') + (when ? ' · ' + when : ''))}</textarea>`)}`,
    {submit:'Add lead', onSubmit:f => { if (!f.name){ toast('A name'); return false; } DB.leads = DB.leads || [];
      const l = {id:uid('ld'), created:today(), name:f.name, phone:f.phone, email:f.email, addr:f.addr, buildingType:f.buildingType, scope:f.scope, stage:'inquiry', source:'Email', next:f.next, nextDue:f.nextDue, notes:f.notes, commId:c.id, attachments:(c.attachments || []).map(a => a.name)};
      DB.leads.push(l); if (p){ p.applied = 'lead created'; p.appliedAt = new Date().toISOString(); p.by = (currentUser() || {}).name || role(); }
      if (f.next && f.nextDue) cmTaskFull(`${f.next} — ${f.name}${f.addr ? ' · ' + f.addr : ''}`, '', 'Owner', f.nextDue, '', c.id);
      cmAfter(c, `Lead: ${f.name}`); save(); render(); toast(`${f.name} is a lead`); }});
}

/* ---------- filing: the message and its attachments, each to its place ---------- */
function cmPlaceFor(c, a){
  const n = (a.name || '').toLowerCase(); const R = c.route || {}; const isImg = /\.(jpe?g|png|heic|gif)$/.test(n) || /^image\//.test(a.type || '');
  if (/alteration|work agreement|decorative|light work/.test(n)) return {kind:'agreement', label:'the building\'s alteration agreement'};
  if (/\bcoi\b|certificate|insurance/.test(n)) return {kind:'coi', label:'the vendor\'s insurance'};
  if (/w-?9/.test(n)) return {kind:'w9', label:'the vendor\'s W-9'};
  if (/invoice|statement|bill|receipt/.test(n) && !cmIsStaff(c.from && c.from.email)) return {kind:'bill', label:'the bill'};
  if (/estimate|quote|proposal/.test(n)) return {kind:'estimate', label:cmIsStaff(c.from && c.from.email) ? 'the client\'s documents (our estimate)' : 'the vendor\'s quotes'};
  if (/scan|signed|contract|agreement/.test(n) || isImg && /scan|signed/.test((c.subject || '').toLowerCase())) return {kind:'contract', label:'the client\'s documents (signed)'};
  if (isImg) return {kind:'photo', label:R.projectId ? 'the project\'s photos' : 'the client\'s documents'};
  if (/plan|drawing|\.dwg|\.rvt|set/.test(n)) return {kind:'plan', label:'the project\'s drawings'};
  return {kind:'doc', label:R.clientId || R.leadName ? 'the client\'s documents' : 'documents'};
}
async function cmFileAttachment(c, a){
  const R = c.route || cmRoute(c); const place = cmPlaceFor(c, a); const by = (currentUser() || {}).name || role();
  const cl = R.clientId ? DB.clients.find(x => x.id === R.clientId) : null; const pr = R.projectId ? DB.projects.find(x => x.id === R.projectId) : null; const v = R.vendorId ? DB.vendors.find(x => x.id === R.vendorId) : null;
  const fid = uid('f'); let persisted = false;
  if (a.data && typeof putBlob === 'function'){ try { persisted = await putBlob(fid, a.data); } catch(e){} }
  const rec = {id:fid, name:a.name, type:a.type || '', date:(c.date || '').slice(0, 10) || today(), by, source:'email', commId:c.id, from:c.from && (c.from.name || c.from.email), persisted, pending:!persisted};
  let where = '';
  if (place.kind === 'agreement' && cl){ cl.properties = cl.properties || []; let prop = cl.properties.find(q => R.addr && cmAddrKey(q.addr) === cmAddrKey(R.addr)) || cl.properties[0]; if (!prop){ prop = {id:uid('pr'), addr:R.addr || cl.propertyAddr || '', buildingType:'Co-op', mgmtCompany:'', mgmtAgent:'', mgmtPhone:'', mgmtEmail:'', superName:'', superPhone:'', notes:''}; cl.properties.push(prop); } const alt = altOf(prop); alt.file = a.name; alt.fileId = fid; if (alt.stage === 'none'){ alt.stage = 'received'; alt.receivedAt = today(); } cl.docs.push(Object.assign({}, rec, {type:'Alteration agreement'})); where = `${prop.addr || 'the building'} — alteration agreement`; }
  else if ((place.kind === 'coi' || place.kind === 'w9') && v){ v.docs = v.docs || []; v.docs.push(Object.assign({}, rec, {type:place.kind === 'w9' ? 'W-9' : 'COI'})); if (place.kind === 'w9') v.w9 = true; where = `${v.name} — ${place.kind === 'w9' ? 'W-9' : 'COI'}`; }
  else if (place.kind === 'bill'){ const b = (DB.bills || []).find(x => x.commId === c.id); if (b){ b.fileId = fid; b.file = a.name; where = `bill ${b.number || b.id}`; } else if (v){ v.docs = v.docs || []; v.docs.push(Object.assign({}, rec, {type:'Invoice'})); where = `${v.name} — invoices`; } else if (cl){ cl.docs.push(Object.assign({}, rec, {type:'Document'})); where = `${cl.name} — documents`; } }
  else if (place.kind === 'photo' && pr){ pr.files = pr.files || []; pr.files.push({id:fid, name:a.name, type:a.type || 'image/jpeg', size:a.size || 0, cat:'photo', date:rec.date, by, link:{kind:'comm', id:c.id}, notes:`From ${rec.from}: ${c.subject || ''}`, shareClient:false, ai:null, persisted, pending:!persisted}); where = `${pr.project.name} — photos`; }
  else if (place.kind === 'plan' && pr){ pr.files = pr.files || []; pr.files.push({id:fid, name:a.name, type:a.type || '', size:a.size || 0, cat:'drawing', date:rec.date, by, link:{kind:'comm', id:c.id}, notes:`From ${rec.from}`, shareClient:false, ai:null, persisted, pending:!persisted}); where = `${pr.project.name} — drawings`; }
  else if (cl){ cl.docs.push(Object.assign({}, rec, {type:place.kind === 'contract' ? 'Signed document' : place.kind === 'estimate' ? 'Estimate' : 'Email attachment'})); where = `${cl.name} — documents`; }
  else if (v){ v.docs = v.docs || []; v.docs.push(Object.assign({}, rec, {type:place.kind === 'estimate' ? 'Quote' : 'Document'})); where = `${v.name} — documents`; }
  else if (pr){ pr.files = pr.files || []; pr.files.push({id:fid, name:a.name, type:a.type || '', size:a.size || 0, cat:'doc', date:rec.date, by, link:{kind:'comm', id:c.id}, notes:`From ${rec.from}`, shareClient:false, ai:null, persisted, pending:!persisted}); where = `${pr.project.name} — documents`; }
  else { DB.unfiled = DB.unfiled || []; DB.unfiled.push(rec); where = 'unfiled (no client, vendor or project on this message yet)'; }
  a.filedTo = where; a.fileId = fid; return where;
}
async function cmFileAll(c){ const out = []; for (const a of (c.attachments || [])){ if (a.filedTo) continue; out.push(await cmFileAttachment(c, a)); } if (out.length) cmAfter(c, `Filed ${out.length} attachment${out.length > 1 ? 's' : ''}: ${[...new Set(out)].join('; ')}`); return out; }
/* the message itself goes on the client's record: the team reads it there */
function cmFileToClient(c, clientId){
  const cl = DB.clients.find(x => x.id === clientId); if (!cl) return;
  c.route = c.route || cmRoute(c); c.route.clientId = cl.id;
  const em = c.from && c.from.email; if (em && !cmIsStaff(em) && !(cl.contacts || []).some(k => (k.email || '').toLowerCase() === em.toLowerCase())){ const k = (cl.contacts || []).find(x => !x.email && x.name && (c.from.name || '').toLowerCase().includes(x.name.toLowerCase().split(' ')[0])); if (k) k.email = em; else if (!(cl.contacts || []).length || (c.from.name && !(cl.contacts || []).some(x => x.name === c.from.name))) { cl.contacts = cl.contacts || []; cl.contacts.push({id:uid('k'), name:c.from.name || em, email:em, role:'Contact'}); } }
  cl.activity = cl.activity || []; if (!cl.activity.some(x => x.commId === c.id)) cl.activity.push({t:nowStamp(), by:'mail', text:`${c.channel === 'call' ? 'Call' : c.direction === 'out' ? 'We wrote' : 'They wrote'}: ${c.subject || ''} — ${cmSummary(c) || cmOwnText(c.text).replace(/\s+/g, ' ').slice(0, 160)}`, commId:c.id});
  cmAfter(c, `Filed on ${cl.name}`); cmFileAll(c).then(() => { save(); if (view === 'comms') renderComms(); });
}

/* ---------- proposals that edit before they apply ---------- */
const cmApplyBase_2 = cmApply;
cmApply = function(c, p){
  if (window.__cmBulk) return cmApplyBase_2(c, p);
  if (p.kind === 'call' || p.kind === 'escalation' || p.kind === 'question' || p.kind === 'meeting' || (p.kind === 'permit' && p.task) || (p.kind === 'quote' && !p.out) || p.kind === 'deposit'){
    if (p.kind === 'deposit'){ const did = cmApplyBase_2(c, p); return did; }
    cmTaskDialog(c, p); return 'Choose who and when';
  }
  if (p.kind === 'lead'){ cmPersonDialog(c, p, false); return 'Check the lead and add it'; }
  if (p.kind === 'onboarding'){ if (p.name && DB.clients.some(cl => (cl.name || '').toLowerCase().includes(p.name.toLowerCase()))) return cmApplyBase_2(c, p); cmPersonDialog(c, p, true); return 'Check the client and create it'; }
  const did = cmApplyBase_2(c, p);
  /* anything applied on a known client is filed there, attachments included */
  const R = c.route || {}; if (R.clientId && !(c.filed || []).some(f => /^Filed on/.test(f.text))) cmFileToClient(c, R.clientId); else if ((c.attachments || []).some(a => !a.filedTo)) cmFileAll(c).then(() => { save(); if (view === 'comms') renderComms(); });
  return did;
};

/* ---------- the row gets its own actions ---------- */
const renderCommsBase_2 = renderComms;
renderComms = function(){
  renderCommsBase_2(); const host = $('#comms-body'); if (!host) return;
  host.querySelectorAll('.cm-row').forEach(row => {
    const c = DB.comms.find(x => x.id === row.dataset.cmid); if (!c || row.querySelector('.cm-acts')) return; const R = c.route || {};
    const acts = document.createElement('div'); acts.className = 'cm-acts row wrap';
    const cl = R.clientId && DB.clients.find(x => x.id === R.clientId); const filed = (c.filed || []).some(f => /^Filed on/.test(f.text));
    acts.innerHTML = `<button class="btn sm" data-cma="task">Task</button><button class="btn sm" data-cma="note">Note</button>${cl ? (filed ? `<span class="small muted">Filed on ${esc(cl.name)} — the team sees it there</span>` : `<button class="btn sm" data-cma="file">File on ${esc(cl.name)}</button>`) : `<button class="btn sm" data-cma="fileto">File on a client…</button><button class="btn sm" data-cma="client">New client</button><button class="btn sm" data-cma="lead">New lead</button>`}${(c.attachments || []).length ? `<span class="small muted">· ${(c.attachments || []).map(a => `${esc(a.name)}${a.filedTo ? ' → ' + esc(a.filedTo) : ''}`).join(', ')}</span>` : ''}${(c.filed || []).filter(f => !/^Filed on/.test(f.text)).map(f => `<span class="small muted">· ${esc(f.text)}</span>`).join('')}`;
    const text = row.querySelector('.cm-text'); (text || row).before(acts);
    acts.querySelectorAll('[data-cma]').forEach(b => b.onclick = e => { e.stopPropagation(); const k = b.dataset.cma;
      if (k === 'task') cmTaskDialog(c); else if (k === 'note') cmNoteDialog(c); else if (k === 'client') cmPersonDialog(c, null, true); else if (k === 'lead') cmPersonDialog(c, null, false);
      else if (k === 'file'){ cmFileToClient(c, R.clientId); save(); renderComms(); toast(`Filed on ${cl.name}`); }
      else if (k === 'fileto') mbModal('File on a client', mbF('Client', `<select data-f="clientId">${cmClientOpts('')}</select>`) + `<p class="small muted">The message goes on the client's activity and its attachments into their documents (agreements onto the building, bills onto the bill).</p>`, {submit:'File it', onSubmit:f => { if (!f.clientId){ toast('Choose the client'); return false; } cmFileToClient(c, f.clientId); save(); renderComms(); }}); });
  });
};

/* ---------- the client's record shows its mail ---------- */
if (typeof renderClients === 'function'){
  const renderClientsBase_cm = renderClients;
  renderClients = function(){
    renderClientsBase_cm(); if (clientTab !== 'comms' || !clientOpen) return; const rec = $('#client-record'); if (!rec) return;
    const c = DB.clients.find(x => x.id === clientOpen); if (!c) return; cmInit();
    const emails = (c.contacts || []).map(k => (k.email || '').toLowerCase()).filter(Boolean);
    const mine = DB.comms.filter(m => (m.route && m.route.clientId === c.id) || emails.includes((m.from && m.from.email || '').toLowerCase()) || [...(m.to || []), ...(m.cc || [])].map(cmEmail).some(e => emails.includes(e))).sort((x, y) => (y.date || '').localeCompare(x.date || ''));
    const card = document.createElement('div'); card.className = 'card'; card.style.marginBottom = '12px';
    card.innerHTML = `<div class="hd"><h3>Mail, texts and calls</h3><span class="small muted">${mine.length} on this client · what each meant and what was done about it</span></div>${mine.length ? mine.slice(0, 40).map(m => `<div class="cm-mini"><div class="row wrap" style="gap:6px;align-items:baseline"><svg class="cm-ic" viewBox="0 0 24 24">${CM_ICON[m.channel] || CM_ICON.email}</svg><b>${esc(m.from.name || m.from.email || '')}</b>${m.direction === 'out' ? `<span class="small muted">→ ${esc((m.to || []).map(cmName).join(', '))}</span>` : ''}<span class="small muted">${(m.date || '').slice(0, 10)}</span><span class="grow"></span><a href="#" class="small" data-cmopen="${m.id}">Open in Messages</a></div><div class="cm-subj">${esc(m.subject || '')}</div>${(m.proposals || []).length ? `<div class="small">${m.proposals.map(p => `<span class="cat ${p.kind}">${CM_CATS[p.kind] || p.kind}</span> ${esc(p.summary)}${p.applied ? ` <span class="muted">· ${esc(p.applied)}</span>` : ' <span class="muted">· waiting</span>'}`).join('<br>')}</div>` : ''}${(m.attachments || []).length ? `<div class="small muted">${m.attachments.map(a => `${esc(a.name)}${a.filedTo ? ' → ' + esc(a.filedTo) : ''}`).join(' · ')}</div>` : ''}</div>`).join('') : '<div class="small muted">Nothing yet. Mail from this client\'s contacts, and anything filed here from Messages, collects on this tab.</div>'}`;
    const body = rec.querySelector('.ctabs'); if (body) body.after(card); else rec.append(card); const old = card.nextElementSibling; if (old && /No messages from or to/.test(old.textContent)) old.remove();
    card.querySelectorAll('[data-cmopen]').forEach(x => x.onclick = e => { e.preventDefault(); cmOpen = x.dataset.cmopen; cmFilter = 'all'; view = 'comms'; render(); });
  };
}
/*<</comm2.js>>*/

/*<<mywork.js>>*/
/* ---------- MY WORK (mywork.js) — every task, note and lead in one place ----------
   Tasks live on projects, reminders on the firm's notes, leads in the CRM. From Home › My Work the Owner
   and the office see all of them together: mine or everyone's, open or done, with where each came from
   (a message, the assistant, a hand) and one click to finish or to open the source. */

let mwWho = 'me', mwShow = 'open';
function mwMe(){ const u = typeof currentUser === 'function' ? currentUser() : null; return (u && u.name) || ''; }
function mwOwnerMatch(owner, me){ if (!me) return true; const o = (owner || '').toLowerCase(), m = me.toLowerCase(); if (!o) return false; if (o === m) return true; if (m === 'owner' && /^(owner|ceo|alan)$/.test(o)) return true; return o.split(/\s|\//)[0] === m.split(/\s|\//)[0]; }
function mwItems(){
  const out = []; const me = mwMe();
  const people = typeof CM_ASSIGNEES === 'function' ? CM_ASSIGNEES() : [];
  (DB.projects || []).forEach(p => (p.tasks || []).forEach(t => { if (t.type === 'milestone') return; if (!t.fromComm && !people.some(n => mwOwnerMatch(t.owner, n))) return; /* the schedule stays on the schedule; a person's to-do is a to-do */ out.push({kind:'task', id:t.id, projectId:p.id, project:p.project.name, text:t.name, owner:t.owner || '', due:t.end || t.start || '', done:t.status === 'done', from:t.fromComm ? 'message' : t.notes && /assistant/i.test(t.notes) ? 'assistant' : '', notes:t.notes || '', commId:typeof t.fromComm === 'string' ? t.fromComm : ''}); }));
  if (typeof eaNotes === 'function') eaNotes().forEach(n => { const m = (n.text || '').match(/^([A-Z][\w .]{1,30}?):\s(.+)$/); out.push({kind:'note', id:n.id, project:'', text:m ? m[2] : n.text, owner:m ? m[1] : (n.by || 'Owner'), due:n.due || '', done:!!n.done, from:n.commId ? 'message' : 'assistant', commId:n.commId || ''}); });
  (DB.leads || []).forEach(l => { if (['won','lost'].includes(l.stage)) return; out.push({kind:'lead', id:l.id, project:'', text:`${l.next || 'Follow up'} — ${l.name}${l.addr ? ' · ' + l.addr : ''}`, owner:'Owner', due:l.nextDue || '', done:false, from:l.commId ? 'message' : '', commId:l.commId || ''}); });
  return out.filter(i => (mwShow === 'all' || !i.done) && (mwWho === 'all' || mwOwnerMatch(i.owner, me))).sort((a, b) => (a.done - b.done) || ((a.due || '9999').localeCompare(b.due || '9999')));
}
function renderMyWork(){
  const host = $('#mywork-body'); if (!host) return; const items = mwItems(); const td = today(); const me = mwMe();
  const late = items.filter(i => !i.done && i.due && i.due < td).length; const tdy = items.filter(i => !i.done && i.due === td).length;
  host.innerHTML = `<div class="row wrap" style="gap:8px;align-items:center;margin-bottom:10px"><div class="seg"><button class="${mwWho==='me'?'on':''}" data-mww="me">Mine</button><button class="${mwWho==='all'?'on':''}" data-mww="all">Everyone</button></div><div class="seg"><button class="${mwShow==='open'?'on':''}" data-mws="open">Open</button><button class="${mwShow==='all'?'on':''}" data-mws="all">With done</button></div><span class="small muted">${items.length} item${items.length===1?'':'s'}${late ? ` · <b style="color:var(--bad)">${late} late</b>` : ''}${tdy ? ` · ${tdy} due today` : ''}</span><span class="grow"></span><button class="btn sm" id="mw-add">New task</button></div>
  ${items.length ? `<div class="tw"><table class="t"><thead><tr><th>Due</th><th>What</th><th>Who</th><th>Where</th><th>From</th><th></th></tr></thead><tbody>${items.map(i => `<tr class="${i.done ? 'mw-done' : (i.due && i.due < td ? 'mw-late' : '')}"><td class="small ${i.due && i.due < td && !i.done ? 'bad' : ''}">${i.due ? fmt(i.due) : '<span class="muted">—</span>'}</td><td>${esc(i.text)}${i.notes ? `<div class="small muted">${esc(i.notes.slice(0, 120))}</div>` : ''}</td><td class="small">${esc(i.owner || '—')}</td><td class="small">${i.projectId ? `<a href="#" data-mwproj="${i.projectId}">${esc(i.project)}</a>` : i.kind === 'lead' ? '<a href="#" data-mwleads>Leads</a>' : '<span class="muted">firm</span>'}</td><td class="small muted">${i.from === 'message' ? `<a href="#" data-mwcomm="${esc(i.commId)}">a message</a>` : i.from === 'assistant' ? 'the assistant' : i.kind === 'lead' ? 'CRM' : ''}</td><td>${i.done ? '<span class="pill ok">done</span>' : i.kind === 'lead' ? `<button class="btn sm" data-mwlead="${i.id}">Open</button>` : `<button class="btn sm" data-mwdone="${i.kind}|${i.id}|${i.projectId||''}">Done</button>`}</td></tr>`).join('')}</tbody></table></div>` : `<div class="empty">Nothing ${mwWho === 'me' ? 'assigned to you' : 'open'}${mwShow === 'open' ? '' : ' or done'}. Tasks made from messages, reminders you gave the assistant and leads with a next step all show here.</div>`}`;
  host.querySelectorAll('[data-mww]').forEach(b => b.onclick = () => { mwWho = b.dataset.mww; renderMyWork(); });
  host.querySelectorAll('[data-mws]').forEach(b => b.onclick = () => { mwShow = b.dataset.mws; renderMyWork(); });
  host.querySelectorAll('[data-mwdone]').forEach(b => b.onclick = () => { const [kind, id, pid] = b.dataset.mwdone.split('|'); if (kind === 'task'){ const p = DB.projects.find(x => x.id === pid); const t = p && p.tasks.find(x => x.id === id); if (t){ t.status = 'done'; t.actualEnd = today(); } } else if (kind === 'note'){ const n = eaNotes().find(x => x.id === id); if (n) n.done = true; } save(); renderMyWork(); toast('Done'); });
  host.querySelectorAll('[data-mwproj]').forEach(a => a.onclick = e => { e.preventDefault(); if (typeof setCurrent === 'function') setCurrent(a.dataset.mwproj); view = 'tasks'; render(); });
  host.querySelectorAll('[data-mwleads]').forEach(a => a.onclick = e => { e.preventDefault(); clientOpen = null; view = 'leads'; render(); });
  host.querySelectorAll('[data-mwlead]').forEach(b => b.onclick = () => { if (typeof crmLeadSheet === 'function') crmLeadSheet(b.dataset.mwlead); });
  host.querySelectorAll('[data-mwcomm]').forEach(a => a.onclick = e => { e.preventDefault(); cmOpen = a.dataset.mwcomm; cmFilter = 'all'; view = 'comms'; render(); });
  const add = host.querySelector('#mw-add'); if (add) add.onclick = () => mbModal('New task', `${mbF('Task', mbIn('name', '', ''))}<div class="grid2">${mbF('Assign to', `<select data-f="owner">${cmUserOpts(me || 'Owner')}</select>`)}${mbF('Due', mbIn('due', today(), '', 'date'))}</div>${mbF('Project', `<select data-f="projectId">${cmProjOpts('')}</select>`)}`, {submit:'Create', onSubmit:f => { if (!f.name){ toast('Name it'); return false; } cmTaskFull(f.name, f.projectId, f.owner, f.due, '', ''); save(); renderMyWork(); }});
}
(() => {
  if (!document.getElementById('v-work')){ const sec = document.createElement('section'); sec.className = 'view'; sec.id = 'v-work'; sec.innerHTML = '<div class="ph"><div><h2>My Work</h2><div class="lead">Every task, reminder and lead with a next step — yours or everyone\'s — with where it came from.</div></div></div><div id="mywork-body"></div>'; (document.querySelector('#v-home')?.parentElement || document.querySelector('.main') || document.body).appendChild(sec); }
  if (typeof ROLE_VIEWS === 'object') ['owner','pm','coord','controller','billing','design_mgr','designer'].forEach(r => { if (ROLE_VIEWS[r] && !ROLE_VIEWS[r].includes('work')) ROLE_VIEWS[r].push('work'); });
  const put = (G, L) => { if (typeof G === 'undefined') return; const g = G.find(x => x.id === 'home'); if (g && !g.views.includes('work')){ const i = g.views.indexOf('comms'); g.views.splice(i > -1 ? i : g.views.length, 0, 'work'); } if (L) L.work = 'My Work'; };
  put(typeof IA_GROUPS !== 'undefined' ? IA_GROUPS : undefined, typeof IA_LABELS !== 'undefined' ? IA_LABELS : null);
  put(typeof NAV_GROUPS !== 'undefined' ? NAV_GROUPS : undefined, typeof NAV_LABELS !== 'undefined' ? NAV_LABELS : null);
  if (typeof IA_H2_SKIP !== 'undefined' && IA_H2_SKIP.add) IA_H2_SKIP.add('work');
})();
if (typeof render === 'function'){ const renderBase_mw = render; render = function(){ renderBase_mw(); if (view === 'work') renderMyWork(); }; }
/* the assistant's "Review" for messages, and a task from Messages, both point here when the item is firm-wide */
