/*<<funnel.js>>*/
/* ---------- LEADS & FUNNEL (funnel.js) — the pipeline before a contract ----------
   Leads were a tab inside Clients with no picture of the whole. Now Clients › Leads is its own screen: a stage
   strip (inquiry → site visit → proposal out → won / lost) with counts and estimated value, win rate, how long
   a lead takes, and every lead with one click to move it along, win it (a client is created with the estimate
   ready to start) or lose it (with the reason kept). Leads made from messages link back to the message. */

let fnStage = 'open', fnShow = 'open';
const FN_OPEN = ['inquiry','site-visit','proposal'];
function fnStageName(k){ return (CRM_STAGES.find(s => s[0] === k) || [k, k])[1]; }
function fnNext(k){ const i = FN_OPEN.indexOf(k); return i > -1 && i < FN_OPEN.length - 1 ? FN_OPEN[i + 1] : ''; }
function fnDays(a, b){ if (!a) return 0; return Math.max(0, Math.round((new Date((b || today()) + 'T00:00:00') - new Date(String(a).slice(0, 10) + 'T00:00:00')) / 864e5)); }
function fnLeads(){ return (DB.leads || []).map(l => { if (!l.stage) l.stage = 'inquiry'; if (!l.history) l.history = [{stage:l.stage, at:l.created || today()}]; return l; }); }
function fnMove(id, stage, why){
  const l = (DB.leads || []).find(x => x.id === id); if (!l || l.stage === stage) return;
  if (stage === 'won'){ (l.history = l.history || []).push({stage:'won', at:today()}); view = 'clients'; crmLeadWon(id); return; }
  l.history = l.history || []; l.history.push({stage, at:today(), by:(typeof currentUser === 'function' && currentUser() || {}).name || ''});
  l.stage = stage; if (stage === 'lost'){ l.lostWhy = why || ''; l.lostAt = today(); }
  save(); render(); toast(stage === 'lost' ? 'Lost — kept for the record' : `${l.name} → ${fnStageName(stage)}`);
}
function fnStats(){
  const L = fnLeads(); const td = today(); const since = new Date(td + 'T00:00:00'); since.setDate(since.getDate() - 90); const s90 = since.toISOString().slice(0, 10);
  const by = {}; CRM_STAGES.forEach(([k]) => by[k] = {n:0, value:0}); L.forEach(l => { const b = by[l.stage] || (by[l.stage] = {n:0, value:0}); b.n++; b.value += +l.value || 0; });
  const won = L.filter(l => l.stage === 'won'), lost = L.filter(l => l.stage === 'lost');
  const won90 = won.filter(l => (l.wonAt || '') >= s90).length, lost90 = lost.filter(l => (l.lostAt || '') >= s90).length;
  const open = L.filter(l => FN_OPEN.includes(l.stage));
  const days = won.map(l => fnDays(l.created, l.wonAt)).filter(d => d > 0).sort((a, b) => a - b);
  const stale = open.filter(l => !l.nextDue || l.nextDue < td).length;
  return {by, open:open.length, openValue:open.reduce((a, l) => a + (+l.value || 0), 0), winRate:(won90 + lost90) ? won90 / (won90 + lost90) : null, won90, lost90, median:days.length ? days[Math.floor(days.length / 2)] : null, stale, fromMail:open.filter(l => l.commId).length};
}
function fnStripHtml(){
  const st = fnStats();
  const box = (k, n) => { const b = st.by[k] || {n:0, value:0}; const on = fnStage === k; return `<button class="fn-box ${on ? 'on' : ''} fn-${k}" data-fnstage="${k}"><div class="fn-n">${b.n}</div><div class="fn-l">${esc(n)}</div><div class="fn-v small muted">${b.value ? moneyK(b.value) : '—'}</div></button>`; };
  return `<div class="fn-strip">${box('inquiry', 'Inquiry')}<span class="fn-arrow">→</span>${box('site-visit', 'Site visit')}<span class="fn-arrow">→</span>${box('proposal', 'Proposal out')}<span class="fn-arrow">→</span>${box('won', 'Won')}<span class="fn-gap"></span>${box('lost', 'Lost')}</div>
  <div class="fn-stats small muted">${st.open} open · ${st.openValue ? moneyK(st.openValue) + ' in the pipeline · ' : ''}${st.winRate == null ? 'no wins or losses in the last 90 days' : `win rate ${Math.round(st.winRate * 100)}% over 90 days (${st.won90} won, ${st.lost90} lost)`}${st.median ? ` · a won lead takes ${st.median} day${st.median === 1 ? '' : 's'}` : ''}${st.stale ? ` · <b style="color:var(--bad)">${st.stale} with no next step or overdue</b>` : ''}${st.fromMail ? ` · ${st.fromMail} from messages` : ''}</div>`;
}
function fnRowsHtml(){
  const td = today(); let L = fnLeads();
  L = fnStage === 'open' ? L.filter(l => FN_OPEN.includes(l.stage)) : fnStage === 'all' ? L : L.filter(l => l.stage === fnStage);
  const order = Object.fromEntries(CRM_STAGES.map(([k], i) => [k, i]));
  L.sort((a, b) => (order[a.stage] - order[b.stage]) || String(a.nextDue || '9').localeCompare(String(b.nextDue || '9')));
  if (!L.length) return `<div class="empty">${fnStage === 'open' ? 'No open leads. A lead comes from a message (Home › Messages › New lead), a call, or the New lead button.' : 'Nothing at this stage.'}</div>`;
  return `<div class="tw"><table class="t" id="fn-table"><thead><tr><th>Lead</th><th>Property</th><th>Scope</th><th>Stage</th><th>Source</th><th class="r">Est. value</th><th>Next step</th><th>Due</th><th>Age</th><th></th></tr></thead><tbody>${L.map(l => { const nx = fnNext(l.stage); const closed = !FN_OPEN.includes(l.stage); return `<tr class="${closed ? 'fn-closed' : ''}" data-fnrow="${l.id}"><td><b>${esc(l.name)}</b><div class="small muted">${esc(l.phone || '')}${l.phone && l.email ? ' · ' : ''}${esc(l.email || '')}</div></td><td>${esc(l.addr || '')}${l.buildingType ? `<div class="small muted">${esc(l.buildingType)}</div>` : ''}</td><td class="small">${esc(l.scope || '')}</td><td><span class="pill ${l.stage === 'won' ? 'ok' : l.stage === 'lost' ? 'bad' : l.stage === 'proposal' ? 'info' : 'neutral'}">${fnStageName(l.stage)}</span>${l.stage === 'lost' && l.lostWhy ? `<div class="small muted">${esc(l.lostWhy)}</div>` : ''}</td><td class="small">${l.commId ? `<a href="#" data-fncomm="${esc(l.commId)}">${esc(l.source || 'a message')}</a>` : esc(l.source || '')}</td><td class="r">${l.value ? money(l.value) : '<span class="muted">—</span>'}</td><td class="small">${esc(l.next || '')}</td><td class="small ${!closed && l.nextDue && l.nextDue < td ? 'bad' : ''}">${l.nextDue ? fmt(l.nextDue) : (closed ? '' : '<span class="muted">—</span>')}</td><td class="small muted">${closed ? fnDays(l.created, l.wonAt || l.lostAt) + 'd' : fnDays(l.created) + 'd'}</td><td class="fn-acts">${closed ? (l.stage === 'won' && l.clientId ? `<button class="btn sm" data-fnclient="${l.clientId}">Client</button>` : `<button class="btn sm ghost" data-fnreopen="${l.id}">Reopen</button>`) : `${nx ? `<button class="btn sm" data-fnadv="${l.id}|${nx}">→ ${fnStageName(nx)}</button> ` : ''}<button class="btn sm" data-lead-won="${l.id}">Won</button> <button class="btn sm ghost" data-lead-lost="${l.id}">Lost</button> `}<button class="btn sm ghost" data-lead-edit="${l.id}">Edit</button></td></tr>`; }).join('')}</tbody></table></div>`;
}
function fnWire(host){
  host.querySelectorAll('[data-fnstage]').forEach(b => b.onclick = () => { fnStage = fnStage === b.dataset.fnstage ? 'open' : b.dataset.fnstage; renderLeads(); });
  host.querySelectorAll('[data-fnall]').forEach(b => b.onclick = () => { fnStage = b.dataset.fnall; renderLeads(); });
  host.querySelectorAll('#btn-newlead, #btn-newlead2').forEach(b => b.onclick = () => crmLeadSheet(null));
  host.querySelectorAll('[data-lead-edit]').forEach(b => b.onclick = () => crmLeadSheet(b.dataset.leadEdit));
  host.querySelectorAll('[data-lead-won]').forEach(b => b.onclick = () => fnMove(b.dataset.leadWon, 'won'));
  host.querySelectorAll('[data-lead-lost]').forEach(b => b.onclick = () => { const l = DB.leads.find(x => x.id === b.dataset.leadLost); if (!l) return; mbModal(`Lost — ${esc(l.name)}`, mbF('Why (a sentence, so the next one goes better)', mbIn('why', l.lostWhy || '', 'Went with another builder, budget, timing…')), {submit:'Mark lost', onSubmit:f => fnMove(l.id, 'lost', f.why)}); });
  host.querySelectorAll('[data-fnadv]').forEach(b => b.onclick = () => { const [id, st] = b.dataset.fnadv.split('|'); fnMove(id, st); });
  host.querySelectorAll('[data-fnreopen]').forEach(b => b.onclick = () => { const l = DB.leads.find(x => x.id === b.dataset.fnreopen); if (!l) return; const back = (l.history || []).filter(h => FN_OPEN.includes(h.stage)).pop(); l.stage = back ? back.stage : 'inquiry'; delete l.lostAt; (l.history = l.history || []).push({stage:l.stage, at:today(), reopened:true}); save(); render(); });
  host.querySelectorAll('[data-fnclient]').forEach(b => b.onclick = () => { clientOpen = b.dataset.fnclient; clientTab = 'overview'; crmTab = 'clients'; view = 'clients'; render(); });
  host.querySelectorAll('[data-fncomm]').forEach(a => a.onclick = e => { e.preventDefault(); cmOpen = a.dataset.fncomm; cmFilter = 'all'; view = 'comms'; render(); });
}
function renderLeads(){
  const host = $('#leads-body'); if (!host) return;
  host.innerHTML = `${fnStripHtml()}<div class="row wrap" style="gap:8px;align-items:center;margin:12px 0 8px"><div class="seg"><button class="${fnStage === 'open' ? 'on' : ''}" data-fnall="open">Open</button><button class="${fnStage === 'all' ? 'on' : ''}" data-fnall="all">Everything</button></div>${fnStage !== 'open' && fnStage !== 'all' ? `<span class="small muted">showing ${esc(fnStageName(fnStage))} — click the box again for all open</span>` : ''}<span class="grow"></span><button class="btn primary" id="btn-newlead">New lead</button></div>${fnRowsHtml()}`;
  fnWire(host);
}
/* the lead sheet learns an estimated value and a source list */
crmLeadSheet = function(id){
  const l = id ? DB.leads.find(x => x.id === id) : {name:'', phone:'', email:'', addr:'', buildingType:'', scope:'Design-build', stage:'inquiry', source:'', next:'', nextDue:'', notes:'', value:''};
  if (!l) return;
  const src = ['Referral','Email','Call','Website','Houzz','Instagram','Walk-by','Repeat client','Architect','Broker'];
  mbModal(id ? 'Edit lead' : 'New lead', `
    <div class="f2"><div class="f"><label>Name</label><input data-f="name" value="${esc(l.name)}"></div><div class="f"><label>Phone</label><input data-f="phone" value="${esc(l.phone || '')}"></div></div>
    <div class="f2"><div class="f"><label>Email</label><input data-f="email" value="${esc(l.email || '')}"></div><div class="f"><label>Source</label><input data-f="source" list="fn-src" value="${esc(l.source || '')}" placeholder="Referral, Houzz, walk-by…"><datalist id="fn-src">${src.map(s => `<option value="${s}">`).join('')}</datalist></div></div>
    <div class="f2"><div class="f"><label>Property</label><input data-f="addr" value="${esc(l.addr || '')}"></div><div class="f"><label>Building</label><select data-f="buildingType">${CRM_BUILDING.map(t => `<option value="${t}" ${l.buildingType === t ? 'selected' : ''}>${t || '— choose —'}</option>`).join('')}</select></div></div>
    <div class="f2"><div class="f"><label>Scope</label><select data-f="scope">${CRM_SCOPES.map(s => `<option ${l.scope === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><div class="f"><label>Stage</label><select data-f="stage">${CRM_STAGES.filter(s => FN_OPEN.includes(s[0])).map(([k, n]) => `<option value="${k}" ${l.stage === k ? 'selected' : ''}>${n}</option>`).join('')}</select></div></div>
    <div class="f2"><div class="f"><label>Estimated value</label><input data-f="value" type="number" step="1000" value="${l.value || ''}" placeholder="What the job is likely worth"></div><div class="f"><label>Due</label><input type="date" data-f="nextDue" value="${esc(l.nextDue || '')}"></div></div>
    <div class="f"><label>Next step</label><input data-f="next" value="${esc(l.next || '')}" placeholder="Site visit, send proposal…"></div>
    <div class="f"><label>Notes</label><textarea data-f="notes" rows="2">${esc(l.notes || '')}</textarea></div>`,
    {submit:id ? 'Save' : 'Add lead', onSubmit:f => { if (!f.name){ toast('A name, at least'); return false; }
      f.value = +f.value || 0; const was = l.stage;
      const o = Object.assign(id ? l : {id:uid('ld'), created:today(), history:[]}, f); if (!id) DB.leads.push(o);
      if (!o.history || !o.history.length) o.history = [{stage:o.stage, at:o.created}]; else if (was !== o.stage) o.history.push({stage:o.stage, at:today()});
      save(); render(); }});
};
/* Clients › Leads is now this screen; the old tab points here */
(() => {
  if (!document.getElementById('v-leads')){ const sec = document.createElement('section'); sec.className = 'view'; sec.id = 'v-leads'; sec.innerHTML = '<div class="ph"><div><h2>Leads</h2><div class="lead">Before a contract, a lead. The funnel from the first call to a signed client, with what each stage is worth.</div></div></div><div id="leads-body"></div>'; (document.querySelector('#v-clients')?.parentElement || document.querySelector('.main') || document.body).appendChild(sec); }
  if (typeof ROLE_VIEWS === 'object') ['owner','pm','coord','billing','design_mgr'].forEach(r => { if (ROLE_VIEWS[r] && !ROLE_VIEWS[r].includes('leads')) ROLE_VIEWS[r].push('leads'); });
  const put = (G, L) => { if (typeof G === 'undefined') return; const g = G.find(x => x.id === 'clients'); if (g && !g.views.includes('leads')) g.views.push('leads'); if (L) L.leads = 'Leads'; };
  put(typeof IA_GROUPS !== 'undefined' ? IA_GROUPS : undefined, typeof IA_LABELS !== 'undefined' ? IA_LABELS : null);
  put(typeof NAV_GROUPS !== 'undefined' ? NAV_GROUPS : undefined, typeof NAV_LABELS !== 'undefined' ? NAV_LABELS : null);
})();
if (typeof render === 'function'){ const renderBase_fn = render; render = function(){ if (view === 'clients' && crmTab === 'leads'){ crmTab = 'clients'; view = 'leads'; } renderBase_fn(); if (view === 'leads') renderLeads(); }; }
{ const rcBase_fn = renderClients; renderClients = function(){ rcBase_fn(); const t = document.querySelector('#crm-tabs [data-crmtab="leads"]'); if (t) t.onclick = () => { view = 'leads'; render(); }; }; }
/* demo pipeline (invented names) so the funnel has a shape on first sight */
function fnSeed(){
  if (!DB || DB.__fnSeed || !(DB.projects || []).some(p => p.id === 'p121')) return; DB.__fnSeed = 1; DB.leads = DB.leads || []; if (DB.leads.length) return;
  const td = today(); const d = n => { const x = new Date(td + 'T00:00:00'); x.setDate(x.getDate() - n); return x.toISOString().slice(0, 10); };
  const mk = (o, age, stage, extra) => Object.assign({id:uid('ld'), created:d(age), stage, history:[{stage:'inquiry', at:d(age)}], scope:'Design-build', buildingType:'Co-op', phone:'', email:'', next:'', nextDue:''}, o, extra || {});
  DB.leads.push(
    mk({name:'Priya Raman', addr:'240 W 98th St 7B', source:'Referral', value:185000, next:'Site visit', nextDue:d(-3), email:'priya.r@example.com'}, 6, 'inquiry'),
    mk({name:'Daniel Okafor', addr:'11 Riverside Dr 4A', source:'Website', value:95000, next:'Call back about timing', nextDue:d(2), phone:'+1 917 555 0188'}, 12, 'inquiry'),
    mk({name:'The Lindqvists', addr:'145 Hicks St', buildingType:'Townhouse', source:'Architect', value:420000, next:'Walk the house with the architect', nextDue:d(-1)}, 20, 'site-visit', {history:[{stage:'inquiry', at:d(20)},{stage:'site-visit', at:d(9)}]}),
    mk({name:'Marcus Bell', addr:'77 Bleecker St 3F', buildingType:'Condo', source:'Houzz', value:140000, next:'Follow up on the proposal', nextDue:d(-6)}, 34, 'proposal', {history:[{stage:'inquiry', at:d(34)},{stage:'site-visit', at:d(25)},{stage:'proposal', at:d(14)}]}),
    mk({name:'Ana Petrova', addr:'30 E 85th St 12C', source:'Repeat client', value:260000, next:'Answer the board questions', nextDue:d(1)}, 41, 'proposal', {history:[{stage:'inquiry', at:d(41)},{stage:'site-visit', at:d(30)},{stage:'proposal', at:d(8)}]}),
    mk({name:'Owen Marsh', addr:'52 Clark St 2R', source:'Referral', value:110000}, 70, 'lost', {lostAt:d(31), lostWhy:'Went with a contractor the board already knew', history:[{stage:'inquiry', at:d(70)},{stage:'site-visit', at:d(58)},{stage:'proposal', at:d(46)},{stage:'lost', at:d(31)}]}),
    mk({name:'Grace Whitfield', addr:'8 Gramercy Park N 5', source:'Instagram', value:75000}, 95, 'lost', {lostAt:d(80), lostWhy:'Budget was half the estimate', history:[{stage:'inquiry', at:d(95)},{stage:'lost', at:d(80)}]}),
    mk({name:'Tom & Lily Nakamura', addr:'200 E 66th St 9G', source:'Broker', value:210000}, 88, 'won', {wonAt:d(40), history:[{stage:'inquiry', at:d(88)},{stage:'site-visit', at:d(75)},{stage:'proposal', at:d(60)},{stage:'won', at:d(40)}]})
  );
}
if (typeof finishBoot === 'function'){ const finishBootBase_fn = finishBoot; finishBoot = function(){ const r = finishBootBase_fn.apply(this, arguments); try { fnSeed(); } catch(e){ console.warn('funnel seed', e); } return r; }; }
