  mbModal(`Tax appetite and fit — ${esc(i.name)}`, `<p class="small muted">The HTC filter. A federal credit needs federal liability to absorb 4% of QRE a year for five years; a passive individual usually cannot use it and is a cash investor.</p><div class="grid2">${mbF('Entity type', mbSel('entity', [['', '—'],['individual','Individual'],['corporate','C corporation'],['bank','Bank / insurer'],['passthrough','LLC / partnership'],['ira','IRA'],['trust','Trust']], t.entity || ''))}${mbF('Federal tax liability (yearly, estimate)', mbIn('fedLiability', t.fedLiability || '', '', 'number'))}</div><div class="grid2">${mbF('Passive income to shelter?', mbSel('passive', [['', '—'],['yes','Yes'],['no','No']], t.passive || ''))}${mbF('New York liability?', mbSel('ny', [['', '—'],['yes','Yes'],['no','No']], t.ny || ''))}</div><div class="grid2">${mbF('Class', mbSel('class', [['', 'Decide from the answers'],['credit','Credit investor'],['cash','Cash investor'],['both','Both']], t.class || ''))}${mbF('Time horizon (years)', mbIn('horizon', t.horizon || '', '5 minimum', 'number'))}</div><div class="grid2">${mbF('Comfortable check', mbIn('checkLow', t.checkLow || '', '', 'number'))}${mbF('Stops being comfortable', mbIn('checkHigh', t.checkHigh || '', '', 'number'))}</div><div class="grid2">${mbF('Illiquid investments before?', mbSel('experience', [['', '—'],['yes','Yes'],['no','No — first time']], t.experience || ''))}${mbF('Fit', mbSel('fit', [['', '—'],['good','A partner'],['ok','Fine'],['poor','Wants guarantees or a special deal']], t.fit || ''))}</div>${mbF('Who else decides (CPA, spouse, committee) — names, comma separated', mbIn('deciders', (i.deciders || []).map(d => d.name).join(', '), ''))}`,
    {submit:'Save', onSubmit:f => { const d = f.deciders; delete f.deciders; i.tax = Object.assign({}, t, f); i.deciders = d.split(',').map(s => s.trim()).filter(Boolean).map(n => (i.deciders || []).find(x => x.name === n) || {id:uid('dc'), name:n, met:false}); save(); render(); }});
