function cpAccredDialog(i){ const a = i.accred || {}; mbModal(`Accreditation — ${esc(i.name)}`, `${mbF('Method', mbSel('method', CP_VERIFY, a.method || ''))}<div class="grid2">${mbF('Verified on', mbIn('at', a.at || '', '', 'date'))}${mbF('Document', mbIn('doc', a.doc || '', 'CPA letter 2026-08-14.pdf'))}</div>${mbF('', `<label class="chk"><input type="checkbox" data-f="minRep" ${a.minRep ? 'checked' : ''}> Written representation that the minimum investment is not financed by a third party ($200k / $1M safe harbour)</label>`)}`, {submit:'Save', onSubmit:f => { i.accred = Object.assign({}, a, f); save(); render(); }}); }
function cpAddToRaise(i){ const R = (DB.raises || []).filter(r => r.status !== 'closed' && !(r.pipeline || []).some(p => p.investorId === i.id)); if (!R.length){ toast('Already on every open raise'); return; } mbModal(`Put ${esc(i.name)} on a raise`, `${mbF('Raise', mbSel('raiseId', R.map(r => [r.id, r.name]), R[0].id))}<div class="grid2">${mbF('Stage', mbSel('stage', CP_STAGES.filter(s => CP_OPEN.includes(s[0])), 'target'))}${mbF('Amount (indication)', mbIn('amount', i.tax && i.tax.checkLow || '', '250k, 1.5M'))}</div>`, {submit:'Add', onSubmit:f => { const r = cpRaise(f.raiseId); if (!r) return false; if (cpClass(i) === 'cash' && r.kind === 'credit' && !confirm('This is a cash investor and the raise is credit equity — they cannot use the credit. Add anyway?')) return false; const g = cpSolicitGate(r, i, f.stage); if (g === false) return false; r.pipeline.push({id:uid('pl'), investorId:i.id, stage:f.stage, amount:cpAmount(f.amount), since:today(), history:[{stage:f.stage, at:today()}], solicitationNote:typeof g === 'string' ? g : ''}); save(); render(); }}); }
function cpSolicitGate(r, i, stage){ const ex = (r.compliance || {}).exemption || '506b'; const idx = CP_OPEN.indexOf(stage); if (ex === '506b' && i && idx >= CP_OPEN.indexOf('deck') && !cpRelationship(i)){ if (!confirm(`${i.name}: no substantive pre-existing relationship on the record (two real conversations — calls, meetings or site walks). Under 506(b) a deck or a data room before the relationship is general solicitation. Go ahead anyway?`)) return false; return 'deck or data room before the relationship was established'; } return true; }
function cpAmount(v){ const s = String(v || '').trim().toLowerCase().replace(/[$,\s]/g, ''); const m = s.match(/^([0-9.]+)(k|m)?$/); if (!m) return 0; return Math.round(+m[1] * (m[2] === 'm' ? 1e6 : m[2] === 'k' ? 1e3 : 1)); }
function cpMove(r, p, stage, extra){
  const i = cpInv(p.investorId); const ex = (r.compliance || {}).exemption || '506b'; const td = today(); extra = extra || {};
  if (['deck','room'].includes(stage) && !p.solicitationNote && !extra.force){ const g = cpSolicitGate(r, i, stage); if (g === false) return; if (typeof g === 'string') p.solicitationNote = g; }
  if (['soft','committed','subscribed'].includes(stage) && !(+p.amount) && !extra.amount){ mbModal('Amount', `${mbF(`How much (minimum ${cpK(+r.min || 0)})`, mbIn('amount', '', '250k, 1.5M'))}`, {submit:'Set', onSubmit:f => { const a = cpAmount(f.amount); if (!a){ toast('A number'); return false; } if (+r.min && a < +r.min && !confirm(`Below the minimum of ${cpK(+r.min)}. Allow it?`)) return false; p.amount = a; cpMove(r, p, stage, Object.assign({}, extra, {amount:a})); }}); return; }
  if (stage === 'subscribed' && i){ const A = cpAccredStatus(i, ex, +p.amount || 0); if (ex === '506c' && !A.ok){ toast(`Accreditation: ${A.text}`); return; } if (!extra.force && !confirm(`${i.name} subscribed for ${cpK(+p.amount || 0)} — the accepted subscription is the sale; the Form D clock starts today if this is the first. Confirm?`)) return; }
  if (stage === 'funded' && !extra.force && !confirm(`Wire received from ${i ? i.name : 'the partner'} for ${cpK(+p.amount || 0)}?`)) return;
  p.history = p.history || []; p.history.push({stage, at:td, from:p.stage}); const from = p.stage; p.stage = stage; p.since = td;
  if (stage === 'passed'){ p.lostCode = extra.code || 'other'; p.lostWhy = extra.why || ''; }
  if (stage === 'subscribed'){ p.subSignedAt = td; r.compliance = r.compliance || {}; if (!r.compliance.firstSale) r.compliance.firstSale = td; if (i){ i.next = 'Confirm the wire'; i.nextDue = iso(addDays(td, 7)); } }
  if (stage === 'funded'){ p.fundedAt = td; p.wireAt = td; p.wireAmount = +p.amount || 0; if (i){ i.next = 'Welcome letter and wire confirmation'; i.nextDue = iso(addDays(td, 2)); } }
  if (i && ['deck','room','subscribed','funded'].includes(stage)) i.touches.push({id:uid('tc'), at:td, channel:stage === 'deck' ? 'deck' : stage === 'room' ? 'room' : 'email', direction:'out', note:stage === 'deck' ? `${r.name}: deck sent` : stage === 'room' ? `${r.name}: data room opened` : stage === 'subscribed' ? `${r.name}: subscription documents signed and accepted (${cpK(+p.amount || 0)})` : `${r.name}: wire received (${cpK(+p.amount || 0)})`, by:(currentUser() || {}).name || ''});
  save(); render(); toast(`${i ? i.name : 'Partner'} → ${cpStageName(stage)}`);
}
function cpBack(r, p){ const seq = CP_OPEN.concat(['funded']); const prev = seq[Math.max(0, seq.indexOf(p.stage) - 1)] || 'target'; if (!confirm(`Move ${(cpInv(p.investorId) || {}).name || 'the partner'} back to ${cpStageName(prev)}?`)) return; if (p.stage === 'funded'){ delete p.fundedAt; delete p.wireAt; } if (p.stage === 'subscribed'){ delete p.subSignedAt; const others = (r.pipeline || []).filter(x => x !== p && x.subSignedAt).map(x => x.subSignedAt).sort(); if (r.compliance) r.compliance.firstSale = others[0] || ''; } (p.history = p.history || []).push({stage:prev, at:today(), from:p.stage, back:true}); p.stage = prev; p.since = today(); save(); render(); }
