  const sec = (title, lead, rows) => { const R = rows.filter(([a, b]) => hit(a + ' ' + b)); return R.length ? `<div class="card"><h3>${title}</h3><div class="small muted" style="margin-bottom:8px">${lead}</div>${R.map(([a, b]) => `<div class="sl-pb"><b>${esc(a)}</b>${b ? `<div class="small">${esc(b)}</div>` : ''}</div>`).join('')}</div>` : ''; };
