  const inp = host.querySelector('#cp-pbq'); if (inp) inp.oninput = () => { cpPbQ = inp.value; const pos = inp.selectionStart; renderCapPlaybook(); const i2 = host.querySelector('#cp-pbq'); if (i2){ i2.focus(); i2.setSelectionRange(pos, pos); } };
