  if (cpNumTab === 'raise') body = `<div class="card"><h3>From the list to the wire</h3><div class="sl-funnel">${N.funnel.map(s => `<div class="sl-fstep"><b>${s.n}</b><div>${esc(s.name)}</div><div class="small muted">${s.conv != null ? s.conv + '% of the stage before' : 'everyone on a raise'}</div></div>`).join('')}</div><div class="small" style="margin-top:8px">First conversation to commitment: <b>${N.firstToCommit != null ? N.firstToCommit + '%' : '—'}</b> (benchmark 10–20% for a fund) · soft circle to signed: <b>${N.softToSigned != null ? N.softToSigned + '%' : '—'}</b> · re-up rate: <b>${N.reup != null ? N.reup + '%' : '—'}</b> · K-1s late: <b>${N.k1Late}</b> of ${N.k1N}</div><h3 style="margin-top:12px">Concentration</h3>${N.conc.length ? `<table class="t"><tbody>${N.conc.map(({r, S}) => `<tr><td>${esc(r.name)}</td><td class="small">anchor ${Math.round(S.anchor * 100)}% · coverage ${S.coverage.toFixed(1)}x · ${S.nFunded} funded</td></tr>`).join('')}</tbody></table>` : '<div class="small muted">—</div>'}</div>`;
