const HB_DEFAULT_STAGES = [{id:'inquiry', label:'Inquiry', prob:10}, {id:'qualified', label:'Qualified', prob:25}, {id:'site-visit', label:'Site visit', prob:40}, {id:'design', label:'Design agreement', prob:60, required:['amount']}, {id:'proposal', label:'Proposal out', prob:80, required:['amount','closedate']}, {id:'won', label:'Closed won', prob:100, won:true}, {id:'lost', label:'Closed lost', prob:0, lost:true, required:['closed_lost_reason']}];
function hbInit(){
  DB.hub = DB.hub || {}; const H = DB.hub;
  H.contacts = H.contacts || []; H.companies = H.companies || []; H.tasks = H.tasks || []; H.queues = H.queues || []; H.sequences = H.sequences || []; H.enrollments = H.enrollments || []; H.playbooks = H.playbooks || []; H.forecast = H.forecast || {submissions:[], goals:{}}; H.products = H.products || []; H.views = H.views || {}; H.customProps = H.customProps || {deal:[], contact:[], company:[]}; H.hidden = H.hidden || {deal:[], contact:[], company:[]}; H.about = H.about || {}; H.boardCard = H.boardCard || ['amount','closedate','hubspot_owner_id','hs_priority']; H.assocLabels = H.assocLabels || {}; H.calls = H.calls || [];
  if (!H.pipeline){ H.pipeline = {label:'Sales Pipeline', stages:JSON.parse(JSON.stringify(HB_DEFAULT_STAGES))}; }
  (DB.leads || []).forEach(l => { l.props = l.props || {}; if (!l.closedate) l.closedate = l.stage === 'won' ? (l.wonAt || l.created) : l.stage === 'lost' ? (l.lostAt || l.created) : hbEndOfMonth(iso(addDays(today(), 30))); if (!l.owner) l.owner = 'Owner'; if (!l.dealtype) l.dealtype = 'New Business'; if (!l.forecastCategory) l.forecastCategory = l.stage === 'won' ? 'Closed won' : l.stage === 'lost' ? 'Not forecasted' : ['proposal'].includes(l.stage) ? 'Commit' : ['design','site-visit'].includes(l.stage) ? 'Best case' : 'Pipeline'; l.contactIds = l.contactIds || []; l.companyIds = l.companyIds || []; l.notes_ = l.notes_ || []; });
  H.contacts.forEach(c => { c.props = c.props || {}; c.dealIds = c.dealIds || []; c.touches = c.touches || []; }); H.companies.forEach(c => { c.props = c.props || {}; c.contactIds = c.contactIds || []; c.dealIds = c.dealIds || []; c.touches = c.touches || []; });
  ['deal','contact','company'].forEach(o => { if (!H.views[o]) H.views[o] = [{id:'all', name:`All ${HB_OBJ[o].label.toLowerCase()}`, filters:[], columns:null, locked:true}, {id:'mine', name:`My ${HB_OBJ[o].label.toLowerCase()}`, filters:[{prop:'hubspot_owner_id', op:'eq', value:'__me__'}], columns:null, locked:true}]; });
}
function hbEndOfMonth(d){ const x = new Date(String(d).slice(0, 10) + 'T00:00:00'); x.setMonth(x.getMonth() + 1, 0); return iso(x); }
const hbStages = () => DB.hub.pipeline.stages; const hbStage = id => hbStages().find(s => s.id === id) || {id, label:id, prob:0};
const hbUsers = () => (DB.users || []).filter(u => !['crew','driver','client'].includes(u.role)).map(u => u.name);
const hbMe = () => (typeof currentUser === 'function' && currentUser() || {}).name || 'Owner';
const hbFmtMoney = v => v == null || v === '' ? '' : money(+v || 0);
const hbFmtDate = d => { if (!d) return ''; const s = String(d).slice(0, 10); const y = s.slice(0, 4); return y === String(today()).slice(0, 4) ? fmt(s) : `${fmt(s)}/${y.slice(2)}`; };
const hbRel = d => { if (!d) return ''; const n = Math.round((new Date(today() + 'T00:00:00') - new Date(String(d).slice(0, 10) + 'T00:00:00')) / 864e5); return n === 0 ? 'today' : n === 1 ? 'yesterday' : n > 1 ? `${n} days ago` : n === -1 ? 'tomorrow' : `in ${-n} days`; };
