function hbView_(obj){ return DB.hub.views[obj].find(v => v.id === hbView[obj]) || DB.hub.views[obj][0]; }
function hbColumns(obj){ return hbCols[obj] || hbView_(obj).columns || HB_DEFAULT_COLS[obj]; }
const HB_OPS = [['eq','is equal to'],['ne','is not equal to'],['contains','contains'],['gt','is greater than'],['lt','is less than'],['known','is known'],['unknown','is unknown'],['after','is after'],['before','is before']];
function hbMatch(obj, r, f){ let v = hbGet(obj, r, f.prop); let want = f.value; if (want === '__me__') want = hbMe(); if (Array.isArray(v)) v = v.join(', '); const s = String(v ?? '').toLowerCase(), w = String(want ?? '').toLowerCase(); if (typeof v === 'boolean'){ v = v ? 'true' : ''; } switch (f.op){ case 'eq': return String(v ?? '').toLowerCase() === w; case 'ne': return s !== w; case 'contains': return s.includes(w); case 'gt': return +v > +want; case 'lt': return +v < +want; case 'known': return v !== '' && v != null; case 'unknown': return v === '' || v == null; case 'after': return String(v).slice(0, 10) > want; case 'before': return String(v).slice(0, 10) < want; default: return true; } }
function hbDateWindow(k){ const td = today(); const d = n => iso(addDays(td, n)); if (k === 'today') return [td, td]; if (k === 'yesterday') return [d(-1), d(-1)]; if (k === 'week') return [d(-7), td]; if (k === 'month') return [d(-30), td]; if (k === 'quarter') return [d(-90), td]; if (k === 'thismonth') return [td.slice(0, 7) + '-01', hbEndOfMonth(td)]; if (k === 'nextmonth'){ const x = new Date(td + 'T00:00:00'); x.setMonth(x.getMonth() + 1, 1); return [iso(x), hbEndOfMonth(iso(x))]; } if (k === 'thisquarter'){ const x = new Date(td + 'T00:00:00'); const q = Math.floor(x.getMonth() / 3) * 3; return [iso(new Date(x.getFullYear(), q, 1)), iso(new Date(x.getFullYear(), q + 3, 0))]; } return null; }
function hbRows(obj){ const view = hbView_(obj); let R = HB_OBJ[obj].store().slice(); const q = (hbQ[obj] || '').toLowerCase(); const filters = (view.filters || []).concat(hbAdv[obj] || []); R = R.filter(r => filters.every(f => hbMatch(obj, r, f))); Object.entries(hbQuick[obj] || {}).forEach(([prop, val]) => { if (!val) return; const p = hbProp(obj, prop); if (p && p.type === 'date'){ const w = hbDateWindow(val); if (w) R = R.filter(r => { const v = String(hbGet(obj, r, prop) || '').slice(0, 10); return v && v >= w[0] && v <= w[1]; }); } else R = R.filter(r => String(hbGet(obj, r, prop)) === val); }); if (q) R = R.filter(r => JSON.stringify(obj === 'deal' ? [r.name, r.addr, r.email, r.phone] : obj === 'contact' ? [r.first, r.last, r.email, r.phone, r.companyName] : [r.name, r.domain, r.city]).toLowerCase().includes(q)); const [sp, dir] = hbSort[obj]; R.sort((a, b) => { const va = hbGet(obj, a, sp), vb = hbGet(obj, b, sp); const n = typeof va === 'number' || typeof vb === 'number' ? (+va || 0) - (+vb || 0) : String(va ?? '').localeCompare(String(vb ?? '')); return n * dir; }); return R; }
function hbIndexHtml(obj){
  const H = DB.hub; const views = H.views[obj]; const all = HB_OBJ[obj].store(); const R = hbRows(obj); const cols = hbColumns(obj); const total = R.length; const pages = Math.max(1, Math.ceil(total / hbPageSize)); if (hbPage[obj] > pages) hbPage[obj] = pages; const page = R.slice((hbPage[obj] - 1) * hbPageSize, hbPage[obj] * hbPageSize); const [sp, dir] = hbSort[obj]; const adv = (hbAdv[obj] || []).length; const filtered = adv || Object.values(hbQuick[obj] || {}).some(Boolean) || hbQ[obj];
  const quick = HB_QUICK[obj].map(n => { const p = hbProp(obj, n); const val = (hbQuick[obj] || {})[n] || ''; let opts; if (p.type === 'date') opts = [['', 'All'],['today','Today'],['yesterday','Yesterday'],['week','Last 7 days'],['month','Last 30 days'],['quarter','Last 90 days'],['thismonth','This month'],['nextmonth','Next month'],['thisquarter','This quarter']]; else if (p.type === 'user') opts = [['', 'All']].concat(hbUsers().map(u => [u, u])); else opts = [['', 'All']].concat((p.options || []).filter(Boolean).map(o => [o, o])); return `<div class="hb-pill ${val ? 'on' : ''}"><label>${esc(p.label)}</label><select data-hbquick="${n}">${opts.map(([k, l]) => `<option value="${esc(k)}" ${k === val ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></div>`; }).join('');
  const bulk = hbSel.size ? `<div class="hb-bulk"><b>${hbSel.size} selected</b><button class="hb-btn sm" data-hbbulk="assign">Assign</button><button class="hb-btn sm" data-hbbulk="edit">Edit</button>${obj === 'contact' ? '<button class="hb-btn sm" data-hbbulk="sequence">Enroll in sequence</button>' : ''}<button class="hb-btn sm" data-hbbulk="tasks">Create tasks</button><button class="hb-btn sm" data-hbbulk="export">Export</button><button class="hb-btn sm danger" data-hbbulk="delete">Delete</button><a href="#" data-hbbulk="all" class="small">Select all ${total} records</a></div>` : '';
  const filterbar = `<div class="hb-filterbar">${obj === 'deal' ? `<div class="hb-modes"><button class="${hbMode.deal === 'table' ? 'on' : ''}" data-hbmode="table" title="Table">☰</button><button class="${hbMode.deal === 'board' ? 'on' : ''}" data-hbmode="board" title="Board">▥</button></div><div class="hb-pill"><label>Pipeline</label><select><option>${esc(H.pipeline.label)}</option></select></div>` : ''}${quick}<button class="hb-btn link sm" id="hb-more">+ More</button><button class="hb-btn link sm" id="hb-advanced">Advanced filters${adv ? ` (${adv})` : ''}</button>${filtered ? '<button class="hb-btn link sm" id="hb-clear">Clear all</button>' : ''}<span class="grow"></span><input class="hb-search" id="hb-q" placeholder="Search ${obj === 'deal' ? 'name, property, email' : obj === 'contact' ? 'name, phone, email' : 'name, domain'}…" value="${esc(hbQ[obj] || '')}">${hbMode[obj] === 'table' || obj !== 'deal' ? '<button class="hb-btn sm" id="hb-editcols">Edit columns</button>' : '<button class="hb-btn sm" id="hb-boardopts">Board options</button>'}<button class="hb-btn sm" id="hb-export">Export</button></div>`;
  const table = `<div class="hb-tablewrap"><table class="hb-table"><thead><tr><th class="hb-chk"><input type="checkbox" id="hb-selall" ${page.length && page.every(r => hbSel.has(r.id)) ? 'checked' : ''}></th>${cols.map(n => { const p = hbProp(obj, n) || {label:n}; return `<th class="${sp === n ? (dir > 0 ? 'sort-asc' : 'sort-desc') : ''}"><span data-hbsort="${n}">${esc(p.label)}</span><button class="hb-colmenu" data-hbcolmenu="${n}">⋮</button></th>`; }).join('')}</tr></thead><tbody>${page.map(r => `<tr class="${hbSel.has(r.id) ? 'sel' : ''}"><td class="hb-chk"><input type="checkbox" data-hbsel="${r.id}" ${hbSel.has(r.id) ? 'checked' : ''}></td>${cols.map((n, i) => `<td class="${i === 0 ? 'hb-name' : ''}">${i === 0 ? `<a href="#" data-hbopen="${r.id}">${hbDisplay(obj, r, n) || esc(hbName(obj, r)) || '—'}</a><button class="hb-preview" data-hbpreview="${r.id}">Preview</button>` : `<span class="hb-cell" data-hbcell="${r.id}|${n}">${hbDisplay(obj, r, n) || '<span class="muted">—</span>'}</span>`}</td>`).join('')}</tr>`).join('') || `<tr><td colspan="${cols.length + 1}"><div class="hb-empty"><div class="hb-empty-art"></div><b>No ${HB_OBJ[obj].label.toLowerCase()} match these filters.</b><div class="small muted">Adjust the filters, or create your first ${HB_OBJ[obj].one.toLowerCase()}.</div><button class="hb-btn primary" data-hbcreate="${obj}">Create ${HB_OBJ[obj].one.toLowerCase()}</button></div></td></tr>`}</tbody></table></div><div class="hb-pager"><button class="hb-btn sm" data-hbpage="prev" ${hbPage[obj] <= 1 ? 'disabled' : ''}>‹ Prev</button>${Array.from({length:pages}, (_, i) => `<button class="hb-btn sm ${i + 1 === hbPage[obj] ? 'on' : ''}" data-hbpage="${i + 1}">${i + 1}</button>`).slice(Math.max(0, hbPage[obj] - 3), hbPage[obj] + 2).join('')}<button class="hb-btn sm" data-hbpage="next" ${hbPage[obj] >= pages ? 'disabled' : ''}>Next ›</button><span class="grow"></span><select id="hb-pagesize">${[25, 50, 100].map(n => `<option ${n === hbPageSize ? 'selected' : ''}>${n} per page</option>`).join('')}</select></div>`;
  return `<div class="hb-page"><div class="hb-head"><div><h1>${esc(HB_OBJ[obj].label)}</h1><div class="small muted">${total.toLocaleString()} record${total === 1 ? '' : 's'}</div></div><div class="hb-head-acts"><div class="hb-dd"><button class="hb-btn" id="hb-actions">Actions ▾</button><div class="hb-menu" id="hb-actions-menu"><a href="#" data-hbact="props">Edit properties</a><a href="#" data-hbact="views">Manage views</a><a href="#" data-hbact="export">Export</a><a href="#" data-hbact="import">Import</a></div></div><button class="hb-btn" data-hbact="import">Import</button><button class="hb-btn primary" data-hbcreate="${obj}">Create ${HB_OBJ[obj].one.toLowerCase()}</button></div></div>
  <div class="hb-views">${views.map(v => `<button class="hb-viewtab ${hbView[obj] === v.id ? 'on' : ''}" data-hbview="${v.id}">${esc(v.name)}${hbView[obj] === v.id ? `<span class="hb-viewmenu" data-hbviewmenu="${v.id}">▾</span>` : ''}</button>`).join('')}<button class="hb-viewtab add" id="hb-addview">+ Add view</button><span class="grow"></span><a href="#" class="small" id="hb-allviews">All views</a></div>
  ${bulk || filterbar}${obj === 'deal' && hbMode.deal === 'board' ? hbBoardHtml(R) : table}</div>`;
}
function hbBoardHtml(R){ const H = DB.hub; const st = hbStages(); const cardProps = H.boardCard; const td = today(); return `<div class="hb-board">${st.filter(s => !H.hideEmpty || R.some(l => l.stage === s.id)).map(s => { const L = R.filter(l => l.stage === s.id); const tot = L.reduce((a, l) => a + (+l.value || 0), 0); const w = tot * s.prob / 100; return `<div class="hb-col ${s.won ? 'won' : s.lost ? 'lost' : ''}" data-hbstagecol="${s.id}"><div class="hb-col-hd"><div class="hb-col-title"><b>${esc(s.label)}</b><span class="hb-count">${L.length}</span></div><div class="small muted">Total: ${money(tot)}${!s.won && !s.lost ? ` · Weighted: ${money(w)}` : ''}</div></div><div class="hb-col-body">${L.map(l => { const last = hbGet('deal', l, 'notes_last_updated'); const stale = last && Math.round((new Date(td + 'T00:00:00') - new Date(last + 'T00:00:00')) / 864e5) >= 14; return `<div class="hb-card ${l.priority === 'High' ? 'pri-high' : l.priority === 'Medium' ? 'pri-med' : ''}" draggable="true" data-hbcard="${l.id}"><a href="#" class="hb-card-name" data-hbopen="${l.id}">${esc(l.name)}</a>${cardProps.map(n => { const v = hbDisplay('deal', l, n); if (!v) return ''; const p = hbProp('deal', n); if (n === 'hubspot_owner_id') return ''; if (n === 'hs_priority') return ''; return `<div class="small">${n === 'amount' ? `<b>${v}</b>` : `<span class="muted">${esc(p.label)}:</span> ${v}`}</div>`; }).join('')}<div class="hb-card-ft"><span class="hb-avatar" title="${esc(l.owner || '')}">${esc((l.owner || 'O').split(' ').map(x => x[0]).join('').slice(0, 2).toUpperCase())}</span>${l.priority ? `<span class="hb-flag ${l.priority.toLowerCase()}" title="Priority: ${l.priority}">⚑</span>` : ''}<span class="small muted grow">${last ? 'Last activity ' + hbRel(last) : 'No activity'}</span>${stale ? '<span class="hb-stale" title="No activity in 14 days">●</span>' : ''}</div></div>`; }).join('') || '<div class="hb-col-empty small muted">Drag a deal here</div>'}</div></div>`; }).join('')}</div>`; }
function hbEditColumnsModal(obj){ const cols = hbColumns(obj).slice(); const all = hbProps(obj); mbModal('Edit columns', `<div class="hb-cols"><div><input class="q" id="hb-colq" placeholder="Search properties" style="width:100%;margin-bottom:6px"><div class="hb-collist" id="hb-collist">${all.map(p => `<label class="chk"><input type="checkbox" data-col="${p.name}" ${cols.includes(p.name) ? 'checked' : ''}> ${esc(p.label)} <span class="small muted">${esc(p.group)}</span></label>`).join('')}</div></div><div><div class="small muted" style="margin-bottom:6px">Selected columns (drag to reorder)</div><div class="hb-selcols" id="hb-selcols">${cols.map(n => `<div class="hb-selcol" draggable="true" data-sel="${n}">⋮⋮ ${esc((hbProp(obj, n) || {label:n}).label)}</div>`).join('')}</div></div></div>`, {submit:'Apply', onSubmit:() => { const picked = [...document.querySelectorAll('#hb-selcols [data-sel]')].map(x => x.dataset.sel); if (!picked.length){ toast('Pick at least one column'); return false; } hbCols[obj] = picked; const v = hbView_(obj); if (!v.locked) v.columns = picked; save(); render(); }}); const list = document.getElementById('hb-collist'), selBox = document.getElementById('hb-selcols'); const sync = () => { const on = [...list.querySelectorAll('input:checked')].map(i => i.dataset.col); const cur = [...selBox.querySelectorAll('[data-sel]')].map(x => x.dataset.sel); on.filter(n => !cur.includes(n)).forEach(n => selBox.insertAdjacentHTML('beforeend', `<div class="hb-selcol" draggable="true" data-sel="${n}">⋮⋮ ${esc((hbProp(obj, n) || {label:n}).label)}</div>`)); cur.filter(n => !on.includes(n)).forEach(n => selBox.querySelector(`[data-sel="${n}"]`)?.remove()); wire(); }; list.onchange = sync; document.getElementById('hb-colq').oninput = e => { const q = e.target.value.toLowerCase(); list.querySelectorAll('label').forEach(l => l.style.display = l.textContent.toLowerCase().includes(q) ? '' : 'none'); }; let drag = null; const wire = () => selBox.querySelectorAll('[data-sel]').forEach(el => { el.ondragstart = () => { drag = el; }; el.ondragover = e => e.preventDefault(); el.ondrop = e => { e.preventDefault(); if (drag && drag !== el) selBox.insertBefore(drag, el); }; }); wire(); }
function hbAdvancedPanel(obj){ const F = (hbAdv[obj] || []).slice(); const props = hbProps(obj); const valCtl = f => { const p = hbProp(obj, f.prop) || {}; if (p.type === 'stage') return `<select data-af="value">${hbStages().map(s => `<option value="${s.id}" ${f.value === s.id ? 'selected' : ''}>${esc(s.label)}</option>`).join('')}</select>`; if (p.type === 'user') return `<select data-af="value">${hbUsers().map(u => `<option ${f.value === u ? 'selected' : ''}>${esc(u)}</option>`).join('')}</select>`; if (p.type === 'select' || p.type === 'multi') return `<select data-af="value">${(p.options || []).filter(Boolean).map(o => `<option ${f.value === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select>`; if (p.type === 'bool') return `<select data-af="value"><option value="true">Yes</option><option value="">No</option></select>`; return `<input data-af="value" type="${p.type === 'date' ? 'date' : p.type === 'number' || p.type === 'money' ? 'number' : 'text'}" value="${esc(f.value || '')}" placeholder="Value">`; }; const row = (f, i) => `<div class="hb-advrow" data-i="${i}"><select data-af="prop">${props.map(p => `<option value="${p.name}" ${f.prop === p.name ? 'selected' : ''}>${esc(p.label)}</option>`).join('')}</select><select data-af="op">${HB_OPS.map(([k, n]) => `<option value="${k}" ${f.op === k ? 'selected' : ''}>${n}</option>`).join('')}</select>${valCtl(f)}<button class="hb-btn link sm" data-afdel="${i}">✕</button></div>`; hbPanel('Advanced filters', `<div class="small muted" style="margin-bottom:8px">All filters must match (AND). Property → operator → value.</div><div id="hb-advrows">${F.map(row).join('')}</div><button class="hb-btn link sm" id="hb-advadd">+ Add filter</button>`, {submit:'Apply', onSubmit:() => { const rows = [...document.querySelectorAll('#hb-advrows .hb-advrow')].map(r => ({prop:r.querySelector('[data-af=prop]').value, op:r.querySelector('[data-af=op]').value, value:r.querySelector('[data-af=value]').value.trim()})); hbAdv[obj] = rows; hbPage[obj] = 1; render(); }}); const box = document.getElementById('hb-advrows'); const wireDel = () => { box.querySelectorAll('[data-afdel]').forEach(b => b.onclick = () => b.closest('.hb-advrow').remove()); box.querySelectorAll('[data-af=prop]').forEach(s => s.onchange = () => { const r = s.closest('.hb-advrow'); const html = row({prop:s.value, op:r.querySelector('[data-af=op]').value, value:''}, 0); r.outerHTML = html; wireDel(); }); }; wireDel(); document.getElementById('hb-advadd').onclick = () => { box.insertAdjacentHTML('beforeend', row({prop:props[0].name, op:'eq', value:''}, box.children.length)); wireDel(); }; }
function hbWireIndex(host, obj){
  host.querySelectorAll('[data-hbview]').forEach(b => b.onclick = e => { if (e.target.dataset.hbviewmenu) return; hbView[obj] = b.dataset.hbview; hbCols[obj] = null; hbPage[obj] = 1; hbSel.clear(); render(); });
  host.querySelectorAll('[data-hbviewmenu]').forEach(s => s.onclick = async e => { e.stopPropagation(); const v = hbView_(obj); const k = await hbDropdown(s, (v.locked ? [['clone','Clone'],['save','Save view']] : [['rename','Rename'],['clone','Clone'],['default','Set as default'],['save','Save view'],['share','Manage sharing'],['delete','Delete view']])); if (!k) return; { if (k === 'rename'){ const n = prompt('View name', v.name); if (n) v.name = n; } if (k === 'clone'){ const nv = {id:uid('vw'), name:v.name + ' (copy)', filters:(v.filters || []).concat(hbAdv[obj] || []), columns:hbColumns(obj).slice()}; DB.hub.views[obj].push(nv); hbView[obj] = nv.id; } if (k === 'default'){ DB.hub.views[obj].unshift(...DB.hub.views[obj].splice(DB.hub.views[obj].indexOf(v), 1)); } if (k === 'save'){ if (v.locked){ toast('Clone the view first — the default views are fixed'); } else { v.filters = (v.filters || []).concat(hbAdv[obj] || []); hbAdv[obj] = []; v.columns = hbColumns(obj).slice(); } } if (k === 'delete'){ DB.hub.views[obj] = DB.hub.views[obj].filter(x => x !== v); hbView[obj] = 'all'; } if (k === 'share') hbToast('Shared with everyone on the team'); save(); render(); } });
  const addv = host.querySelector('#hb-addview'); if (addv) addv.onclick = () => mbModal('Create view', `${mbF('Name', mbIn('name', '', ''))}<p class="small muted">The current filters and columns are saved to the new view.</p>`, {submit:'Create', onSubmit:f => { if (!f.name) return false; const nv = {id:uid('vw'), name:f.name, filters:(hbAdv[obj] || []).slice(), columns:hbColumns(obj).slice()}; DB.hub.views[obj].push(nv); hbView[obj] = nv.id; hbAdv[obj] = []; save(); render(); }});
  const allv = host.querySelector('#hb-allviews'); if (allv) allv.onclick = e => { e.preventDefault(); mbModal('All views', `<table class="t"><tbody>${DB.hub.views[obj].map(v => `<tr><td>${esc(v.name)}</td><td class="small muted">${(v.filters || []).length} filter${(v.filters || []).length === 1 ? '' : 's'}</td><td><button class="btn sm" data-govw="${v.id}">Open</button></td></tr>`).join('')}</tbody></table>`, {submit:null}); document.querySelectorAll('[data-govw]').forEach(b => b.onclick = () => { hbView[obj] = b.dataset.govw; mbCloseModal(); render(); }); };
  host.querySelectorAll('[data-hbmode]').forEach(b => b.onclick = () => { hbMode.deal = b.dataset.hbmode; render(); });
  host.querySelectorAll('[data-hbquick]').forEach(s => s.onchange = () => { hbQuick[obj] = hbQuick[obj] || {}; hbQuick[obj][s.dataset.hbquick] = s.value; hbPage[obj] = 1; render(); });
  const more = host.querySelector('#hb-more'); if (more) more.onclick = async () => { const props = hbProps(obj).filter(p => !HB_QUICK[obj].includes(p.name) && ['select','user','date','stage'].includes(p.type)); const k = await hbDropdown(more, props.map(p => [p.name, p.label])); if (k && !HB_QUICK[obj].includes(k)){ HB_QUICK[obj].push(k); render(); } };
  const advb = host.querySelector('#hb-advanced'); if (advb) advb.onclick = () => hbAdvancedPanel(obj);
  const clr = host.querySelector('#hb-clear'); if (clr) clr.onclick = () => { hbAdv[obj] = []; hbQuick[obj] = {}; hbQ[obj] = ''; render(); };
  const q = host.querySelector('#hb-q'); if (q){ q.oninput = () => { hbQ[obj] = q.value; hbPage[obj] = 1; const pos = q.selectionStart; render(); const q2 = document.getElementById('hb-q'); if (q2){ q2.focus(); q2.setSelectionRange(pos, pos); } }; }
  const ec = host.querySelector('#hb-editcols'); if (ec) ec.onclick = () => hbEditColumnsModal(obj);
  const bo = host.querySelector('#hb-boardopts'); if (bo) bo.onclick = async () => { const k = await hbDropdown(bo, [['cards','Edit cards'],['sort','Sort by amount'],['sortdate','Sort by close date'],['hide',DB.hub.hideEmpty ? 'Show empty stages' : 'Hide empty stages']]); if (!k) return; if (k === 'sort'){ hbSort.deal = ['amount', -1]; render(); return; } if (k === 'sortdate'){ hbSort.deal = ['closedate', 1]; render(); return; } if (k === 'hide'){ DB.hub.hideEmpty = !DB.hub.hideEmpty; save(); render(); return; } const props = hbProps('deal').filter(p => !['dealname','pipeline','dealstage'].includes(p.name)); mbModal('Board card properties', `<p class="small muted">Up to four properties show on every card.</p>${[0, 1, 2, 3].map(i => mbF(`Property ${i + 1}`, `<select data-f="p${i}"><option value="">—</option>${props.map(p => `<option value="${p.name}" ${DB.hub.boardCard[i] === p.name ? 'selected' : ''}>${esc(p.label)}</option>`).join('')}</select>`)).join('')}`, {submit:'Save', onSubmit:f => { DB.hub.boardCard = [f.p0, f.p1, f.p2, f.p3].filter(Boolean); save(); render(); }}); };
  host.querySelectorAll('#hb-export, [data-hbact="export"], [data-hbbulk="export"]').forEach(b => b.onclick = e => { e.preventDefault(); const rows = hbSel.size ? hbRows(obj).filter(r => hbSel.has(r.id)) : hbRows(obj); const cols = hbColumns(obj); const csv = [cols.map(n => (hbProp(obj, n) || {label:n}).label).join(',')].concat(rows.map(r => cols.map(n => `"${String(hbDisplay(obj, r, n)).replace(/<[^>]+>/g, '').replace(/"/g, '""')}"`).join(','))).join('\n'); const a = document.createElement('a'); a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv); a.download = `${obj}s.csv`; a.click(); hbToast('Export started'); });
  const act = host.querySelector('#hb-actions'); if (act) act.onclick = () => host.querySelector('#hb-actions-menu').classList.toggle('open');
  host.querySelectorAll('[data-hbact="props"]').forEach(a => a.onclick = e => { e.preventDefault(); view = 'hbsettings'; hbSetTab = 'properties'; hbSetObj = obj; render(); });
  host.querySelectorAll('[data-hbact="views"]').forEach(a => a.onclick = e => { e.preventDefault(); host.querySelector('#hb-allviews').click(); });
  host.querySelectorAll('[data-hbact="import"]').forEach(a => a.onclick = e => { e.preventDefault(); mbModal('Import', `<p class="small">Paste CSV with a header row. Columns are matched to property labels (${hbColumns(obj).map(n => (hbProp(obj, n) || {label:n}).label).slice(0, 4).join(', ')}…).</p><textarea data-f="csv" rows="8" style="width:100%"></textarea>`, {submit:'Import', onSubmit:f => { const lines = f.csv.split(/\r?\n/).filter(Boolean); if (lines.length < 2) return false; const hdr = lines[0].split(',').map(s => s.trim().replace(/^"|"$/g, '')); const props = hbProps(obj); let n = 0; lines.slice(1).forEach(ln => { const cells = ln.match(/("([^"]|"")*"|[^,]*)(,|$)/g).map(s => s.replace(/,$/, '').replace(/^"|"$/g, '').replace(/""/g, '"')); const rec = {}; hdr.forEach((h, i) => { const p = props.find(x => x.label.toLowerCase() === h.toLowerCase() || x.name === h); if (p) rec[p.name] = cells[i] || ''; }); if (obj === 'deal' && rec.dealname){ hbNewDeal(rec); n++; } else if (obj === 'contact' && (rec.firstname || rec.email)){ const c = hbNewContact({}); Object.entries(rec).forEach(([k, v]) => hbSet('contact', c, k, v)); n++; } else if (obj === 'company' && rec.name){ const c = hbNewCompany({}); Object.entries(rec).forEach(([k, v]) => hbSet('company', c, k, v)); n++; } }); save(); render(); hbToast(`${n} record${n === 1 ? '' : 's'} imported`); }}); });
  host.querySelectorAll('[data-hbcreate]').forEach(b => b.onclick = () => hbCreatePanel(b.dataset.hbcreate));
  host.querySelectorAll('[data-hbopen]').forEach(a => a.onclick = e => { e.preventDefault(); hbOpen(obj, a.dataset.hbopen); });
  host.querySelectorAll('[data-hbpreview]').forEach(b => b.onclick = e => { e.stopPropagation(); hbPreviewPanel(obj, b.dataset.hbpreview); });
  host.querySelectorAll('[data-hbsort]').forEach(s => s.onclick = () => { const n = s.dataset.hbsort; hbSort[obj] = [n, hbSort[obj][0] === n ? -hbSort[obj][1] : 1]; render(); });
  host.querySelectorAll('[data-hbcolmenu]').forEach(b => b.onclick = async e => { e.stopPropagation(); const n = b.dataset.hbcolmenu; const k = await hbDropdown(b, [['asc','Sort ascending'],['desc','Sort descending'],['filter','Filter by this column'],['left','Move left'],['right','Move right'],['remove','Remove column']]); if (!k) return; { const cols = hbColumns(obj).slice(); const i = cols.indexOf(n); if (k === 'asc') hbSort[obj] = [n, 1]; if (k === 'desc') hbSort[obj] = [n, -1]; if (k === 'filter'){ hbAdv[obj] = (hbAdv[obj] || []).concat([{prop:n, op:'known', value:''}]); } if (k === 'left' && i > 0){ cols.splice(i - 1, 0, cols.splice(i, 1)[0]); hbCols[obj] = cols; } if (k === 'right' && i < cols.length - 1){ cols.splice(i + 1, 0, cols.splice(i, 1)[0]); hbCols[obj] = cols; } if (k === 'remove' && cols.length > 1){ cols.splice(i, 1); hbCols[obj] = cols; } render(); } });
  host.querySelectorAll('[data-hbsel]').forEach(c => c.onchange = () => { if (c.checked) hbSel.add(c.dataset.hbsel); else hbSel.delete(c.dataset.hbsel); render(); });
  const sa = host.querySelector('#hb-selall'); if (sa) sa.onchange = () => { const R = hbRows(obj).slice((hbPage[obj] - 1) * hbPageSize, hbPage[obj] * hbPageSize); R.forEach(r => sa.checked ? hbSel.add(r.id) : hbSel.delete(r.id)); render(); };
  host.querySelectorAll('[data-hbbulk]').forEach(b => b.onclick = e => { e.preventDefault(); const k = b.dataset.hbbulk; const ids = [...hbSel]; const recs = HB_OBJ[obj].store().filter(r => ids.includes(r.id)); if (k === 'all'){ hbRows(obj).forEach(r => hbSel.add(r.id)); render(); } if (k === 'assign') mbModal(`Assign ${ids.length} record${ids.length === 1 ? '' : 's'}`, mbF('Owner', mbSel('owner', hbUsers(), hbMe())), {submit:'Assign', onSubmit:f => { recs.forEach(r => hbSet(obj, r, 'hubspot_owner_id', f.owner)); hbSel.clear(); save(); render(); }}); if (k === 'edit'){ const props = hbProps(obj).filter(p => !p.ro && p.type !== 'stage'); mbModal(`Edit ${ids.length} record${ids.length === 1 ? '' : 's'}`, `${mbF('Property to update', `<select data-f="prop">${props.map(p => `<option value="${p.name}">${esc(p.label)}</option>`).join('')}</select>`)}${mbF('New value', mbIn('value', '', ''))}`, {submit:'Update', onSubmit:f => { recs.forEach(r => hbSet(obj, r, f.prop, f.value)); hbSel.clear(); save(); render(); }}); } if (k === 'tasks') hbTaskPanel({title:'', assoc:recs.map(r => ({obj, id:r.id}))}, () => { hbSel.clear(); render(); }); if (k === 'sequence' && typeof hbEnrollModal === 'function') hbEnrollModal(recs.map(r => r.id)); if (k === 'delete') mbModal(`Delete ${ids.length} record${ids.length === 1 ? '' : 's'}?`, `<p class="small">Type <b>${ids.length}</b> to confirm. Deleted records can be restored for 90 days.</p>${mbIn('n', '', '')}`, {submit:'Delete', onSubmit:f => { if (f.n !== String(ids.length)) return false; if (obj === 'deal') DB.leads = DB.leads.filter(r => !ids.includes(r.id)); else DB.hub[obj === 'contact' ? 'contacts' : 'companies'] = HB_OBJ[obj].store().filter(r => !ids.includes(r.id)); hbSel.clear(); save(); render(); }}); });
  host.querySelectorAll('[data-hbpage]').forEach(b => b.onclick = () => { const k = b.dataset.hbpage; hbPage[obj] = k === 'prev' ? hbPage[obj] - 1 : k === 'next' ? hbPage[obj] + 1 : +k; render(); });
  const ps = host.querySelector('#hb-pagesize'); if (ps) ps.onchange = () => { hbPageSize = parseInt(ps.value); hbPage[obj] = 1; render(); };
  host.querySelectorAll('[data-hbcell]').forEach(c => c.ondblclick = () => { const [id, n] = c.dataset.hbcell.split('|'); const r = HB_OBJ[obj].store().find(x => x.id === id); const p = hbProp(obj, n); if (!r || !p || p.ro) return; mbModal(`Edit ${esc(p.label)}`, hbFieldHtml(obj, r, n), {submit:'Save', onSubmit:f => { hbSet(obj, r, n, f[n]); save(); render(); hbToast('Changes saved'); }}); });
  /* board */
  let dragId = null; host.querySelectorAll('[data-hbcard]').forEach(c => { c.ondragstart = e => { dragId = c.dataset.hbcard; c.classList.add('dragging'); }; c.ondragend = () => c.classList.remove('dragging'); }); host.querySelectorAll('[data-hbstagecol]').forEach(col => { col.ondragover = e => { e.preventDefault(); col.classList.add('over'); }; col.ondragleave = () => col.classList.remove('over'); col.ondrop = e => { e.preventDefault(); col.classList.remove('over'); const l = DB.leads.find(x => x.id === dragId); if (l) hbMoveStage(l, col.dataset.hbstagecol); }; });
  host.querySelectorAll('[data-hbcard]').forEach(c => c.onclick = e => { if (e.target.closest('a')) return; hbPreviewPanel('deal', c.dataset.hbcard); });
}
function hbDropdown(anchor, items){ document.querySelectorAll('.hb-menu.float').forEach(m => m.remove()); const m = document.createElement('div'); m.className = 'hb-menu float open'; m.innerHTML = items.map(([k, n]) => `<a href="#" data-dd="${k}">${esc(n)}</a>`).join(''); document.body.appendChild(m); const r = anchor.getBoundingClientRect(); m.style.position = 'fixed'; m.style.top = (r.bottom + 4) + 'px'; m.style.left = Math.min(r.left, window.innerWidth - 240) + 'px'; m.style.right = 'auto'; return new Promise(res => { m.querySelectorAll('[data-dd]').forEach(a => a.onclick = e => { e.preventDefault(); m.remove(); res(a.dataset.dd); }); setTimeout(() => document.addEventListener('click', function h(e){ if (!m.contains(e.target)){ m.remove(); document.removeEventListener('click', h); res(null); } }), 0); }); }
/* ---------- preview panel ---------- */
function hbPreviewPanel(obj, id){ const r = HB_OBJ[obj].store().find(x => x.id === id); if (!r) return; const about = (DB.hub.about[obj] || HB_ABOUT[obj]).slice(0, 8); const A = hbActivities(obj, r).slice(0, 5); hbPanel(`<span class="small muted">${esc(HB_OBJ[obj].one)}</span><br>${esc(hbName(obj, r))}`, `<div class="hb-actrow">${['Note','Email','Call','Task','Meeting'].map(a => `<button class="hb-act" data-hbpa="${a.toLowerCase()}"><i></i>${a}</button>`).join('')}</div><div class="hb-card-sec"><h4>About this ${HB_OBJ[obj].one.toLowerCase()}</h4>${about.map(n => `<div class="hb-prop"><label>${esc((hbProp(obj, n) || {label:n}).label)}</label><div>${hbDisplay(obj, r, n) || '<span class="muted">—</span>'}</div></div>`).join('')}</div>${obj === 'deal' ? `<div class="hb-card-sec"><h4>Contacts (${hbContactsOf(r).length})</h4>${hbContactsOf(r).map(c => `<div class="small">${esc(hbName('contact', c))}${c.email ? ` · ${esc(c.email)}` : ''}</div>`).join('') || '<div class="small muted">None</div>'}</div>` : ''}<div class="hb-card-sec"><h4>Recent activities</h4>${A.map(a => `<div class="small"><b>${esc(a.title)}</b> <span class="muted">${hbFmtDate(a.at)}</span></div>`).join('') || '<div class="small muted">No activity yet</div>'}</div><button class="hb-btn" data-hbfull="${id}">View record</button>`, {footer:false}); const p = document.getElementById('hb-panel'); p.querySelector('[data-hbfull]').onclick = () => { hbClosePanel(); hbOpen(obj, id); }; p.querySelectorAll('[data-hbpa]').forEach(b => b.onclick = () => { hbClosePanel(); hbOpen(obj, id); setTimeout(() => hbAction(obj, r, b.dataset.hbpa), 60); }); }
const HB_ABOUT = {deal:['amount','closedate','dealstage','pipeline','hubspot_owner_id','hs_priority','dealtype','hs_forecast_category','hs_next_step','property_address','building_type','scope','hs_source','description'], contact:['email','phone','jobtitle','company','hubspot_owner_id','lifecyclestage','hs_lead_status','hs_buying_role','city'], company:['domain','industry','type','hubspot_owner_id','lifecyclestage','phone','city','description']};
function hbOpen(obj, id){ hbObj = obj; hbOpenId[obj] = id; hbRecTab = 'overview'; view = obj === 'deal' ? 'hbdeals' : obj === 'contact' ? 'hbcontacts' : 'hbcompanies'; render(); window.scrollTo(0, 0); }
/*<</hub_core.js>>*/

