  const ross = mkC(null, 'Elena Ross', {email:'elena.ross@example.com', jobTitle:'Associate broker', lifecycle:'Other', leadStatus:'Connected', buyingRole:['Broker']}); hbAssociate('contact-company', ross.id, compass.id); const dk = mkC(null, 'David Kahn', {email:'dk@example.com', jobTitle:'Principal', lifecycle:'Other', leadStatus:'Connected', buyingRole:['Architect']}); hbAssociate('contact-company', dk.id, kahn.id); const mo = mkC(null, 'Maria Orsini', {jobTitle:'Managing agent', lifecycle:'Other', leadStatus:'Connected'}); hbAssociate('contact-company', mo.id, orsini.id); const nl = mkC(null, 'Jonah Weiss', {email:'jonah.w@example.com', phone:'+1 646 555 0142', jobTitle:'Homeowner', lifecycle:'Lead', leadStatus:'New', source:'Website / Google', created:d(1)}); const nl2 = mkC(null, 'Rebecca Tran', {email:'r.tran@example.com', jobTitle:'Homeowner', lifecycle:'Lead', leadStatus:'Attempted to contact', source:'Instagram', created:d(5), touches:[{id:uid('tc'), at:d(4), kind:'call', direction:'out', outcome:'Left voicemail', title:'Call — Left voicemail', body:'Left a message about the brownstone on Dean St.', by:'Owner'}]});
  const byName = n => (DB.leads || []).find(l => l.name === n); const T = H.tasks; const push = (t) => T.push(Object.assign({id:uid('tk'), created:td, completed:false, type:'To-do', priority:'', queue:'', assignee:'Owner', time:'08:00', reminder:'At task due time', notes:''}, t));
