  if (ana) ana.priority = 'High'; if (lind) lind.priority = 'High'; if (marcus) marcus.priority = 'Medium'; if (dan) dan.priority = 'Low'; const period = hbPeriod()[2]; H.forecast.goals[`Owner|${period}`] = 900000; if (marcus) marcus.forecastCategory = 'Best case'; if (ana) ana.forecastCategory = 'Commit'; if (lind) lind.forecastCategory = 'Commit'; if (priya) priya.forecastCategory = 'Best case';
