/* the four places each office role goes on a phone; More is the full menu */
const M_TABS = {
  owner:[['home','Brief','brief'],['dash','Today','today'],['mapprove','Approve','approve'],['hbworkspace','Sales','sales']],
  pm:[['home','Brief','brief'],['dash','Today','today'],['field','Field','field'],['mapprove','Approve','approve']],
  coord:[['home','Brief','brief'],['dash','Today','today'],['req','Requests','req'],['proc','Buy','buy']],
  billing:[['home','Brief','brief'],['billing','Billing','billing'],['mapprove','Approve','approve'],['clients','Clients','sales']],
  controller:[['home','Brief','brief'],['billing','Billing','billing'],['mapprove','Approve','approve'],['bank','Banking','money']],
  design_mgr:[['sday','My Day','today'],['studio','Studio','studio'],['sdraw','Drawings','draw'],['mapprove','Approve','approve']],
  designer:[['sday','My Day','today'],['sboard','Board','studio'],['sdraw','Drawings','draw'],['sfile','Filings','billing']],
};
const mRole = () => (typeof role === 'function' ? role() : DB.role);
const mOffice = () => mOn() && M_OFFICE.includes(mRole()) && !document.body.classList.contains('ws-mb');

/* ---------- Approvals: one view, every yes/no that waits on this person ---------- */
if (typeof ROLE_VIEWS !== 'undefined'){ ['owner','pm','billing','controller','design_mgr','coord'].forEach(r => { if (ROLE_VIEWS[r] && !ROLE_VIEWS[r].includes('mapprove')) ROLE_VIEWS[r].push('mapprove'); }); }
if (typeof IA_GROUPS !== 'undefined'){ const g = IA_GROUPS.find(x => x.id === 'home'); if (g && !g.views.includes('mapprove')) g.views.push('mapprove'); }
if (typeof NAV_GROUPS !== 'undefined'){ const g = NAV_GROUPS.find(x => x.id === 'home'); if (g && !g.views.includes('mapprove')) g.views.push('mapprove'); }
if (typeof IA_LABELS !== 'undefined') IA_LABELS.mapprove = 'Approvals';
if (typeof NAV_LABELS !== 'undefined') NAV_LABELS.mapprove = 'Approvals';
(function(){ const main = document.querySelector('.main'); if (main && !document.getElementById('v-mapprove')){ const s = document.createElement('section'); s.className = 'view'; s.id = 'v-mapprove'; main.appendChild(s); } })();

function mApprovals(){
  const r = mRole(); const out = [];
  const owner = typeof isOwner === 'function' && isOwner();
  /* vendor bills */
  (DB.bills || []).filter(b => ['submitted','pm-approved'].includes(b.status)).forEach(b => {
    const tot = billTotal(b); const fl = typeof billFlags === 'function' ? billFlags(b) : [];
    const mine = (b.status === 'pm-approved' && owner) || (b.status === 'submitted' && (r === 'pm' || owner));
    if (!mine) return;
    let act = b.status === 'submitted' && !owner ? 'pmok' : (b.status === 'submitted' && typeof needsOwner === 'function' && needsOwner(tot) && owner ? 'pmok' : 'approve');
    const vb = (DB.vendors || []).find(x => (x.name || '').toLowerCase() === (b.vendor || '').toLowerCase());
    const blocked = vb && vb.bankPending ? 'Vendor bank change awaiting your verification — resolve under Vendors first' : (typeof canApprove === 'function' && act === 'approve' && !canApprove(b)) ? 'Separation of duties: a second person must approve this one' : '';
    if (blocked) act = null;
    const comp = typeof complianceIssues === 'function' ? complianceIssues(b).filter(x => x.lvl === 'block').map(x => x.m) : [];
    if (comp.length && !owner) act = null;
    out.push({kind:'bill', id:b.id, comp, sev: blocked || comp.length ? 'bad' : fl.length ? 'warn' : '', n:money(tot), title:`${b.vendor} · bill ${b.number || ''}`, detail:[blocked, act === 'pmok' ? 'First review — your recommendation goes to the Owner, who releases the payment' : '', comp.length ? `Compliance block${comp.length > 1 ? 's' : ''}: ${comp.join('; ')}${owner ? ' — approving asks for your override reason' : ''}` : '', b.status === 'pm-approved' ? 'PM has reviewed' : 'Awaiting review', (() => { const rest = fl.filter(f => !comp.some(c => String(f).replace(/\s+/g, ' ').trim() === String(c).replace(/\s+/g, ' ').trim())); return rest.length ? `${rest.length} control flag${rest.length > 1 ? 's' : ''}: ${rest.join('; ')}` : ''; })(), b.due ? `due ${fmtL ? fmtL(b.due) : b.due}` : ''].filter(Boolean).join(' · '),
      yes: !act ? 'Open' : act === 'pmok' ? 'Recommend' : 'Approve', no:'Reject', open: blocked && vb && vb.bankPending ? {view:'vendors'} : {view:'ap', billId:b.id}, act});
  });
  /* hours */
  if (owner || r === 'pm' || r === 'controller'){ const by = (typeof currentUser === 'function' && currentUser()?.name) || DB.me || ''; (DB.time || []).filter(t => t.status === 'submitted').forEach(t => { const nm = typeof empName === 'function' ? empName(t.empId) : t.empId; if (nm && by && nm.toLowerCase() === by.toLowerCase()) return; const p = DB.projects.find(x => x.id === t.projectId); const fl = typeof timeFlags === 'function' ? timeFlags(t) : []; out.push({kind:'time', id:t.id, sev: fl.length ? 'warn' : '', n:`${(typeof hoursOf === 'function' ? hoursOf(t) : t.hours || 0).toFixed(1)} h`, title:`${nm} · ${t.date || ''}`, detail:[p ? p.project.name : '', fl.join('; ')].filter(Boolean).join(' · '), yes:'Approve', no:'Reject', open:{view:'time'}}); }); }
  /* questions from the site addressed to me */
  if (typeof fForMe === 'function'){ try { fForMe().filter(x => x.status !== 'answered').forEach(x => { const p = DB.projects.find(y => y.id === x.projectId); out.push({kind:'raise', id:x.id, sev: x.escalated || x.type === 'incident' ? 'bad' : 'warn', n: x.dueBy ? `by ${x.dueBy.slice(5)}` : 'site', title: x.title || x.type, detail:[p ? p.project.name : '', x.by || '', x.note || ''].filter(Boolean).join(' · '), yes:'Answer', open:{view:'field', project:x.projectId}}); }); } catch(e){} }
  /* decisions we owe */
  DB.projects.forEach(p => (p.decisions || []).filter(d => d.status === 'open' && /smartdesign|owner|pm|design/i.test(d.owner || '')).forEach(d => out.push({kind:'dec', id:d.id, sev: d.due && d.due < today() ? 'bad' : '', n: d.due ? d.due.slice(5) : '', title:d.name, detail:`${p.project.name}${d.gate ? ' · holds ' + d.gate : ''} · ${d.owner}`, yes:'Open', open:{view:'dec', project:p.id}})));
  /* client documents sitting with us as drafts are not approvals; requests are the coordinator's */
  if (r === 'coord' || owner){ DB.projects.forEach(p => (p.requests || []).filter(q => q.status === 'new').forEach(q => out.push({kind:'req', id:q.id, sev: q.urgent ? 'bad' : '', n:q.neededBy ? String(q.neededBy).slice(5) : '', title:(typeof reqLabel === 'function' ? reqLabel(q) : q.what) || 'Field request', detail:`${p.project.name}${q.by ? ' · ' + q.by : ''} · not acknowledged`, yes:'Acknowledge', open:{view:'req', project:p.id}}))); }
  const rank = s => s === 'bad' ? 0 : s === 'warn' ? 1 : 2;
  return out.sort((a, b) => rank(a.sev) - rank(b.sev));
}
function mGo(go){ if (!go) return; if (go.project && typeof setCurrent === 'function') setCurrent(go.project); if (go.billId) { if (typeof iaOpenBillAfter !== 'undefined') iaOpenBillAfter = go.billId; } view = go.view; render(); window.scrollTo(0, 0); }
function renderMApprove(){
  const v = document.getElementById('v-mapprove'); if (!v) return;
  const items = mApprovals();
  let rest = []; try { rest = needsMe().filter(x => !/Approve bill|vendor bills to approve|hours|time entries/i.test(x.title || '')); } catch(e){}
  const card = it => `<div class="m-appr ${it.sev}" data-mk="${it.kind}" data-mid="${it.id}"><div class="m-appr-t"><b>${esc(it.title)}</b><span class="m-appr-n">${esc(it.n || '')}</span></div>${it.detail ? `<div class="m-appr-d">${esc(it.detail)}</div>` : ''}<div class="m-appr-a">${it.act ? `<button class="btn primary" data-myes>${it.yes}</button><button class="btn danger" data-mno>${it.no}</button><button class="btn ghost" data-mopen>Open</button>` : it.kind === 'time' ? `<button class="btn primary" data-myes>Approve</button><button class="btn danger" data-mno>Reject</button>` : `<button class="btn primary" data-mopen>${it.yes}</button>`}</div></div>`;
  v.innerHTML = `<div class="ph"><div><h2>Approvals</h2><div class="lead">Every yes or no that is waiting on you — bills, hours, questions from the site, decisions we owe. Approve here; open the record when you need the detail.</div></div></div>
    ${items.length ? `<div class="m-appr-list">${items.map(card).join('')}</div>` : '<div class="empty">Nothing is waiting on you.</div>'}
    ${rest.length ? `<h3 style="margin:18px 0 8px">Also on your list</h3><div class="rem nm">${rest.slice(0, 12).map(x => `<div class="rem-row ${x.sev}" data-remgo='${esc(JSON.stringify(x.go || {view:'home'}))}'><b>${esc(String(x.n || '·'))}</b><span><b>${esc(x.title)}</b>${x.detail ? `<br><span class="small muted">${x.detail}</span>` : ''}</span><em class="nm-act">${x.action || 'Open'} ›</em></div>`).join('')}</div>` : ''}`;
  const crumbs = document.getElementById('crumbs'); if (crumbs) crumbs.innerHTML = '<b>Approvals</b>';
  v.querySelectorAll('.m-appr').forEach(el => {
    const it = items.find(x => x.kind === el.dataset.mk && String(x.id) === el.dataset.mid); if (!it) return;
    const yes = el.querySelector('[data-myes]'), no = el.querySelector('[data-mno]'), op = el.querySelector('[data-mopen]');
    if (op) op.onclick = () => mGo(it.open);
    if (it.kind === 'bill'){ const b = DB.bills.find(x => x.id === it.id); const keep = S; const p = DB.projects.find(x => x.id === b.projectId); const runBill = why => { if (p) S = p; const P = window.prompt; if (why) window.prompt = () => why; try { billAction(b, it.act); } catch(e){ console.warn(e); toast('Could not approve: ' + (e.message || e)); } finally { window.prompt = P; } S = keep; render(); };
      if (yes) yes.onclick = () => { if (it.act === 'approve' && it.comp && it.comp.length){ mbModal(`Override — ${esc(b.vendor)}`, `<div class="note warn">${it.comp.map(esc).join('<br>')}</div><div class="f" style="margin-top:10px"><label>Owner override — reason</label><input data-f="why" placeholder="e.g. COI renewal received by email, filing tomorrow" enterkeyhint="done"></div>`, {submit:'Approve anyway', onSubmit: v => { if (!v.why) return false; runBill(v.why); }}); } else runBill(''); }; if (no) no.onclick = () => { if (p) S = p; try { billAction(b, 'reject'); } catch(e){ console.warn(e); } S = keep; render(); }; }
    if (it.kind === 'time'){ const t = DB.time.find(x => x.id === it.id); const keep = S; const p = DB.projects.find(x => x.id === t.projectId); const run = a => { if (p) S = p; try { timeAction(t, a); } catch(e){ console.warn(e); } S = keep; render(); }; if (yes) yes.onclick = () => run('approve'); if (no) no.onclick = () => run('reject'); }
  });
  v.querySelectorAll('[data-remgo]').forEach(el => el.onclick = () => { let go; try { go = JSON.parse(el.dataset.remgo); } catch(e){ return; } mGo(go); });
}
function mApproveCount(){ try { return mApprovals().length; } catch(e){ return 0; } }

/* ---------- bottom tabs for office roles ---------- */
function mRenderTabs(){
  let tb = document.getElementById('mtabs');
  if (!mOffice()){ if (tb) tb.remove(); document.body.classList.remove('m-on'); return; }
  if (!tb){ tb = document.createElement('nav'); tb.id = 'mtabs'; tb.className = 'mtabs no-print'; document.body.appendChild(tb); }
  document.body.classList.add('m-on');
  { const rv = ROLE_VIEWS[mRole()]; if (rv && !rv.includes('mapprove') && ['owner','pm','billing','controller','design_mgr','coord'].includes(mRole())) rv.push('mapprove'); }
  const tabs = (M_TABS[mRole()] || M_TABS.owner).filter(([v]) => (ROLE_VIEWS[mRole()] || []).includes(v) || v === 'mapprove');
  const nAppr = mApproveCount();
  const cur = view;
  const onTab = v => v === cur || (v === 'hbworkspace' && /^hb/.test(cur)) || (v === 'dash' && ['sched','tasks'].includes(cur));
  tb.innerHTML = tabs.map(([v, l, i]) => `<button data-mv="${v}" class="${onTab(v) ? 'on' : ''}">${M_ICON[i]}<span>${l}</span>${v === 'mapprove' && nAppr ? `<i class="n">${nAppr}</i>` : ''}</button>`).join('') + `<button data-mv="__more">${M_ICON.more}<span>More</span></button>`;
  tb.querySelectorAll('button').forEach(b => b.onclick = () => { const v = b.dataset.mv; if (v === '__more'){ document.querySelector('.rail')?.classList.add('open'); document.getElementById('railscrim')?.classList.add('on'); return; } if (v === 'dash' && typeof dashAll !== 'undefined' && !S) return; view = v; render(); window.scrollTo(0, 0); });
}

/* ---------- tables become cards ---------- */
function mCardTables(root){
  if (!mOn()) return;
  root.querySelectorAll('table.dg-t, table.t, table.hb-table, table.tbl, table.rep-t').forEach(t => {
    if (t.classList.contains('m-cards') || t.classList.contains('lines') || t.classList.contains('to') || t.closest('.m-keep, .gantt-wrap, .docwrap, .prev')) return;
    const ths = [...(t.tHead ? t.tHead.rows[0]?.cells || [] : [])];
    if (ths.length < 4) return;
    const labels = ths.map(th => th.textContent.replace(/[↑↓⋮▾▴]/g, '').trim());
    [...t.tBodies].forEach(tb => [...tb.rows].forEach(tr => { if (tr.classList.contains('grp') || tr.classList.contains('sec') || tr.cells.length < 2) { tr.classList.add('m-row-flat'); return; }
      const cells = [...tr.cells]; cells.forEach((td, i) => { if (!td.dataset.l && labels[i]) td.dataset.l = labels[i]; });
      const c0 = cells[0]; if (c0 && c0.querySelector('input[type=checkbox]') && !c0.textContent.trim() && cells[1]){ c0.classList.add('m-selcell'); cells[1].classList.add('m-title'); } else if (c0) c0.classList.add('m-title');
      if (cells.length > 5 && !tr.querySelector('.m-more')){
        /* keep: the name, money, a status pill, the first date, anything with a button; fold the rest */
        let kept = 0, dates = 0; const keep = cells.map((td, i) => { if (i === 0 || td.classList.contains('sel') || td.classList.contains('m-title')) return true; if ((td.dataset.l || '').toLowerCase() === 'health') return false; const isMoney = td.classList.contains('money') || /^\s*[-−]?\$/.test(td.textContent); if (td.querySelector('button, .btn, select, input, a')) return true; const isPill = !!td.querySelector('.pill'); const isDate = td.classList.contains('date') || /^\s*\d{1,2}\/\d{1,2}(\/\d{2,4})?\s*$/.test(td.textContent); if (isMoney || isPill) { kept++; return kept <= 3; } if (isDate && dates === 0){ dates++; kept++; return true; } return false; });
        /* a list with no money or status still shows its first few facts */
        let shown = keep.filter((k, i) => k && i > 0).length; keep.forEach((k, i) => { if (!k && i > 0 && shown < 3 && cells[i].textContent.trim() && cells[i].textContent.trim() !== '—'){ keep[i] = true; shown++; } });
        const hidden = cells.filter((td, i) => !keep[i] && td.textContent.trim()); if (hidden.length){ hidden.forEach(td => td.classList.add('m-hide')); const more = document.createElement('td'); more.className = 'm-more'; more.innerHTML = `<button type="button">+ ${hidden.length} more</button>`; more.querySelector('button').onclick = e => { e.stopPropagation(); const o = tr.classList.toggle('m-open'); more.querySelector('button').textContent = o ? 'Less' : `+ ${hidden.length} more`; }; more.onclick = e => e.stopPropagation(); tr.appendChild(more); }
      } }));
    t.classList.add('m-cards');
  });
}
/* phone numbers dial, emails mail, addresses navigate */
const M_PHONE = /(\(\d{3}\)\s?\d{3}[-.\s]\d{4}|\b\d{3}[-.]\d{3}[-.]\d{4}\b|\+1[\s-]?\d{3}[\s-]?\d{3}[\s-]?\d{4})/g, M_MAIL = /[\w.+-]+@[\w-]+\.[\w.-]+/g;
function mLinkify(root){
  if (!mOn()) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode: n => { const p = n.parentElement; if (!p || p.closest('a, button, input, textarea, select, script, style, .gantt, svg, [contenteditable]')) return NodeFilter.FILTER_REJECT; return (M_PHONE.test(n.nodeValue) || M_MAIL.test(n.nodeValue)) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP; }});
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n => { const html = esc(n.nodeValue).replace(M_MAIL, m => `<a href="mailto:${m}" class="m-link">${m}</a>`).replace(M_PHONE, m => `<a href="tel:${m.replace(/[^\d+]/g, '')}" class="m-link">${m}</a>`); const span = document.createElement('span'); span.innerHTML = html; n.replaceWith(span); });
}
function mRouteLinks(root){
  if (!mOn() || view !== 'route' || typeof planDriverDay !== 'function') return;
  let plan; try { plan = planDriverDay((typeof myEmpUser === 'function' && myEmpUser()?.name) || DB.me); } catch(e){ return; }
  const stops = root.querySelectorAll('.stop'); if (!plan || !plan.stops || !stops.length) return;
  stops.forEach((el, i) => { const s = plan.stops[i]; if (!s || el.querySelector('.m-nav')) return; const g = s.geo || {}; const q = g.lat && g.lng ? `${g.lat},${g.lng}` : encodeURIComponent(s.name || ''); const a = document.createElement('a'); a.className = 'btn sm m-nav'; a.href = `https://maps.apple.com/?daddr=${q}`; a.target = '_blank'; a.rel = 'noopener'; a.textContent = 'Navigate'; const body = el.children[1]; if (body) body.appendChild(a); });
}
/* keyboard-aware inputs */
function mInputs(root){
  if (!mOn()) return;
  root.querySelectorAll('input[type=number]:not([inputmode])').forEach(i => i.setAttribute('inputmode', 'decimal'));
  root.querySelectorAll('input.q:not([enterkeyhint]), input[placeholder^="Search"]:not([enterkeyhint])').forEach(i => { i.setAttribute('enterkeyhint', 'search'); i.setAttribute('autocorrect', 'off'); i.setAttribute('autocapitalize', 'none'); });
  root.querySelectorAll('input[type=tel]:not([autocomplete])').forEach(i => i.setAttribute('autocomplete', 'tel'));
  root.querySelectorAll('input[type=email]:not([autocomplete])').forEach(i => { i.setAttribute('autocomplete', 'email'); i.setAttribute('autocapitalize', 'none'); });
  root.querySelectorAll('input[type=date]:not([enterkeyhint])').forEach(i => i.setAttribute('enterkeyhint', 'done'));
}
/* the active sub-tab is always in view */
function mSubnav(){ if (!mOn()) return; const on = document.querySelector('#subnav .sub-tabs button.on'); if (on && on.scrollIntoView) try { on.scrollIntoView({inline:'center', block:'nearest'}); } catch(e){}
  document.querySelectorAll('#subnav .sub-tabs').forEach(t => { const upd = () => t.classList.toggle('m-more-right', t.scrollWidth - t.clientWidth - t.scrollLeft > 6); upd(); if (!t.dataset.mScroll){ t.dataset.mScroll = '1'; t.addEventListener('scroll', upd, {passive:true}); } }); }
/* no signal: say so once, and say that nothing is lost */
function mNet(){ let bar = document.getElementById('m-offline'); if (navigator.onLine){ if (bar) bar.remove(); return; } if (bar) return; bar = document.createElement('div'); bar.id = 'm-offline'; bar.className = 'm-offline'; bar.textContent = 'No signal — everything you do is saved on this phone and syncs when you are back.'; document.body.appendChild(bar); }
window.addEventListener('online', mNet); window.addEventListener('offline', mNet);

/* ---------- quick capture ---------- */
function mSheet(title, items){
  if (typeof mbCloseModal === 'function') mbCloseModal();
  const m = document.createElement('div'); m.className = 'mbm m-sheet'; m.id = 'mbm';
  m.innerHTML = `<div class="mbm-box"><div class="mbm-hd"><h3>${esc(title)}</h3><button class="mbm-x" aria-label="Close">✕</button></div><div class="m-sheet-list">${items.map(([k, l, i, s]) => `<button data-ms="${k}">${M_ICON[i] || ''}<span><b>${esc(l)}</b>${s ? `<small>${esc(s)}</small>` : ''}</span></button>`).join('')}</div></div>`;
  document.body.appendChild(m);
  const close = () => m.remove();
  m.querySelector('.mbm-x').onclick = close; m.addEventListener('click', e => { if (e.target === m) close(); });
  return new Promise(res => m.querySelectorAll('[data-ms]').forEach(b => b.onclick = () => { close(); res(b.dataset.ms); }));
}
function mReadPhoto(cb, facing){ const inp = document.createElement('input'); inp.type = 'file'; inp.accept = 'image/*'; if (facing) inp.setAttribute('capture', facing); inp.onchange = () => { const f = inp.files && inp.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => cb(rd.result, f); rd.readAsDataURL(f); }; inp.click(); }
function mSavePhoto(dataUrl, f, note){
  if (!S) return; const id = uid('f'); const rec = {id, name: f?.name || `photo-${today()}.jpg`, type: f?.type || 'image/jpeg', size: f?.size || Math.round(dataUrl.length * 0.75), cat:'photo', date:today(), by:(typeof currentUser === 'function' && currentUser()?.name) || DB.me || '', link:null, notes:note || '', shareClient:false, ai:null, persisted:false, uploadedAt:new Date().toISOString(), dataUrl};
  S.files.push(rec); try { if (typeof putBlob === 'function') putBlob(id, dataUrl).then(ok => { rec.persisted = ok; }); } catch(e){}
  log(`Photo added from the phone${note ? ': ' + note : ''}`); save(); toast(`Photo saved to ${S.project.name} · Documents`);
}
async function mQuick(){
  const r = mRole(); const proj = S ? S.project.name : 'no project selected';
  const items = [['photo','Photo to the project', 'camera', proj], ['receipt','Receipt', 'receipt', 'reads the merchant, total and job'], ['note','Note to the project log', 'note', proj], ['task','Task', 'task', 'for someone, with a due date'], ['decision','Decision needed', 'decision', 'what blocks what']];
  if (/^hb/.test(view) || ['owner','pm','coord'].includes(r)) items.push(['call','Log a call', 'call', 'on a deal or a project']);
  items.push(['ask','Ask the assistant', 'ask', '']);
  const k = await mSheet('Capture', items); if (!k) return;
  if (k === 'ask'){ if (typeof openAI === 'function') openAI(); return; }
  if (k === 'photo'){ if (!S){ toast('Pick a project first'); return; } mReadPhoto((d, f) => mbModal('Photo note', `<div class="f"><label>What is this?</label><input data-f="note" placeholder="e.g. 3rd floor bath — rough plumbing done" enterkeyhint="done"></div><img src="${d}" style="width:100%;border-radius:8px;max-height:40vh;object-fit:cover">`, {submit:'Save photo', onSubmit: v => { mSavePhoto(d, f, v.note); render(); }}), 'environment'); return; }
  if (k === 'receipt'){ if (typeof spCaptureModal === 'function') spCaptureModal({projectId: S ? S.id : null}); else toast('Receipts live under Money › Spend'); return; }
  if (k === 'note'){ if (!S){ toast('Pick a project first'); return; } mbModal('Note to the log', `<div class="f"><label>${esc(proj)}</label><textarea data-f="msg" rows="4" placeholder="What happened, in one or two lines"></textarea></div>`, {submit:'Add to log', onSubmit: v => { if (!v.msg) return false; log(v.msg, 'manual'); save(); toast('Logged'); render(); }}); return; }
  if (k === 'task'){ if (!S){ toast('Pick a project first'); return; } const people = (DB.users || []).map(u => u.name); mbModal('New task', `<div class="f"><label>Task</label><input data-f="title" placeholder="Call Nemo about the tile ETA" enterkeyhint="next"></div><div class="f2"><div class="f"><label>For</label><select data-f="assignee">${people.map(n => `<option>${esc(n)}</option>`).join('')}</select></div><div class="f"><label>Due</label><input type="date" data-f="due" value="${today()}"></div></div><div class="f"><label>Priority</label><select data-f="pri"><option value="med">Medium</option><option value="high">High</option><option value="low">Low</option></select></div>`, {submit:'Add task', onSubmit: v => { if (!v.title) return false; S.actions = S.actions || []; S.actions.push({id:uid('a'), title:v.title, assignee:v.assignee, due:v.due, priority:v.pri, status:'todo', link:null, notes:'', source:null, createdAt:today(), completedAt:''}); log(`Task added: ${v.title} → ${v.assignee}`); save(); toast('Task added'); render(); }}); return; }
  if (k === 'decision'){ if (!S){ toast('Pick a project first'); return; } mbModal('Decision needed', `<div class="f"><label>What has to be decided</label><input data-f="name" placeholder="2nd fl bath — tile or stone floor?" enterkeyhint="next"></div><div class="f2"><div class="f"><label>Who decides</label><select data-f="owner"><option>Client</option><option>SmartDesign</option><option>Architect / designer</option></select></div><div class="f"><label>By</label><input type="date" data-f="due" value="${typeof iso === 'function' && typeof addDays === 'function' ? iso(addDays(new Date(today()), 7)) : today()}"></div></div><div class="f"><label>What it holds up</label><input data-f="gate" placeholder="Tile order · 3rd floor bath"></div>`, {submit:'Add decision', onSubmit: v => { if (!v.name) return false; S.decisions = S.decisions || []; S.decisions.push({id:uid('dc'), name:v.name, owner:v.owner, due:v.due, status:'open', gate:v.gate, kind:'design'}); log(`Decision needed: ${v.name} (${v.owner})`); save(); toast('Decision added'); render(); }}); return; }
  if (k === 'call'){ mLogCallDialog(); return; }
}
function mLogCallDialog(name){
  const hb = /^hb/.test(view) && typeof hbObj !== 'undefined' && hbOpenId && hbOpenId[hbObj];
  if (hb){ const list = hbObj === 'deal' ? DB.leads : hbObj === 'contact' ? DB.hub.contacts : DB.hub.companies; const rec = (list || []).find(x => x.id === hbOpenId[hbObj]); if (rec && typeof hbAction === 'function'){ hbAction(hbObj, rec, 'call'); return; } }
  const deals = (DB.leads || []).filter(l => !['won','lost'].includes(l.stage));
  mbModal(`Log a call${name ? ' with ' + esc(name) : ''}`, `<div class="f"><label>About</label><select data-f="about">${S ? `<option value="p:${S.id}">${esc(S.project.name)} (project log)</option>` : ''}${deals.map(l => `<option value="d:${l.id}">${esc(l.name)} (deal)</option>`).join('')}</select></div><div class="f"><label>What was said</label><textarea data-f="msg" rows="4" placeholder="Outcome, what they need, what happens next"></textarea></div><div class="f"><label>Next step (date)</label><input type="date" data-f="next"></div>`, {submit:'Log call', onSubmit: v => {
    if (!v.msg) return false; const [k, id] = (v.about || '').split(':');
    if (k === 'd'){ const l = DB.leads.find(x => x.id === id); if (l){ (l.touches = l.touches || []).push({id:uid('tc'), at:today(), channel:'call', direction:'out', note:v.msg, value:'', objection:'', by:(typeof currentUser === 'function' && currentUser()?.name) || DB.me || ''}); if (v.next){ l.next = 'Follow up on the call'; l.nextDue = v.next; } } }
    else { const keep = S; const p = DB.projects.find(x => x.id === id); if (p) S = p; log(`Call${name ? ' with ' + name : ''}: ${v.msg}${v.next ? ' · next ' + v.next : ''}`); S = keep; }
    save(); toast('Call logged'); render(); }});
}

/* ---------- after a call: offer to log it (HubSpot's post-call prompt) ---------- */
let mPendingCall = null;
document.addEventListener('click', e => { const a = e.target.closest('a[href^="tel:"]'); if (!a || !mOn()) return; mPendingCall = {name:(a.textContent || '').replace(/^Call\s+/i, '').trim(), at:Date.now(), view, hbObj: typeof hbObj !== 'undefined' ? hbObj : null, hbId: typeof hbOpenId !== 'undefined' && typeof hbObj !== 'undefined' ? hbOpenId[hbObj] : null}; }, true);
document.addEventListener('visibilitychange', () => { if (document.visibilityState !== 'visible' || !mPendingCall) return; const c = mPendingCall; mPendingCall = null; if (Date.now() - c.at < 8000) return; const bar = document.createElement('div'); bar.className = 'm-callbar'; bar.innerHTML = `<span>Log the call${c.name ? ' with <b>' + esc(c.name) + '</b>' : ''}?</span><button class="btn primary" id="m-call-yes">Log call</button><button class="btn ghost" id="m-call-no">Not now</button>`; document.body.appendChild(bar); bar.querySelector('#m-call-no').onclick = () => bar.remove(); bar.querySelector('#m-call-yes').onclick = () => { bar.remove(); mLogCallDialog(c.name); }; setTimeout(() => bar.remove(), 60000); });

/* ---------- add to home screen nudge (iOS Safari only) ---------- */
function mHomeNudge(){ const rail = document.querySelector('.rail .foot'); if (!rail || rail.querySelector('.m-a2hs')) return; const ios = /iphone|ipad/i.test(navigator.userAgent); const standalone = window.navigator.standalone === true || window.matchMedia('(display-mode: standalone)').matches; let off = false; try { off = localStorage.getItem('m-a2hs') === '1'; } catch(e){} if (!ios || standalone || off || !mOn()) return; const d = document.createElement('div'); d.className = 'm-a2hs'; d.innerHTML = `<b>Put it on your home screen</b><span>Share → Add to Home Screen. Full screen, one tap, no address bar.</span><button class="btn sm">Got it</button>`; d.querySelector('button').onclick = () => { try { localStorage.setItem('m-a2hs', '1'); } catch(e){} d.remove(); }; rail.prepend(d); }

/* ---------- wiring ---------- */
if (typeof render === 'function'){
  const renderBase_m = render;
  render = function(){
    renderBase_m.apply(this, arguments);
    if (view === 'mapprove'){ try { renderMApprove(); } catch(e){ console.error('approvals', e); } document.querySelectorAll('.view').forEach(e => e.classList.toggle('on', e.id === 'v-mapprove')); }
    try { mRenderTabs(); } catch(e){ console.warn('mtabs', e); }
    const fab = document.getElementById('fab');
    if (fab){ if (mOffice()){ fab.classList.add('m-fab'); fab.innerHTML = M_ICON.plus; fab.setAttribute('aria-label', 'Capture'); fab.onclick = () => mQuick(); } else if (fab.classList.contains('m-fab')){ fab.classList.remove('m-fab'); fab.textContent = 'Assistant'; fab.onclick = () => openAI(); } }
    const on = document.querySelector('.view.on'); if (on){ mCardTables(on); mInputs(on); mLinkify(on); mRouteLinks(on); }
    mSubnav(); mHomeNudge(); mNet();
  };
}
if (mOn() && typeof hbMode !== 'undefined') hbMode.deal = 'table';
let mResizeT = null; window.addEventListener('resize', () => { clearTimeout(mResizeT); mResizeT = setTimeout(() => { try { render(); } catch(e){} }, 150); });
/* a modal opened on a phone is a bottom sheet with a keyboard-aware footer */
if (typeof mbModal === 'function'){ const mbModalBase_m = mbModal; mbModal = function(){ const m = mbModalBase_m.apply(this, arguments); if (m && mOn()) mInputs(m); return m; }; }
