(function(){ const ps = document.getElementById('pswitch'); if (ps) ps.addEventListener('change', e => { if (!(typeof mOn === 'function' && mOn())) return; if (e.target.value === '__all' && view !== 'dash'){ e.stopImmediatePropagation(); setView('port'); } }, true); })();
/* on a phone Today starts across all projects until a project is chosen */
