/* ---------- where each strip lives ---------- */
Object.assign(TL_HOST, {mbinv:'#cpinv-body .sl-kpis', mbraise:'#cpraise-body .kpis', mbcapnum:'#cpnum-body .kpis', mbown:'#mb-own .rep-kpis', client:'#cl-kpis', sday:'#sday-body', sboard:'#sboard-body', sdraw:'#sdraw-body', sfile:'#sfile-body'});
