/*<<topbar.js>>*/
/* ---------- The top bar, and the project header under it (2026-09-13) ----------
   The persistent bar is chrome: who you are looking at (breadcrumb / project), search, New, the
   assistant, and one honest state — the pinned workspace date. Nothing about a particular project
   lives up there any more. The project's dates move to a page-level band on project screens only
   (Procore's Project Home, Salesforce's highlights panel), with at most four chips, and the design
   and permit dates only on the screens they govern. A client sees the company, the project, and a
   way to reach a person — no search, no keyboard hints, no internal targets, no "as of". */

const TB_PROJECT_VIEWS = ['sched','tasks','dec','insp','field','mat','files','costs','inbox','chat','proj','po','recv','time','sboard','sdraw','sfile'];
const TB_CROSS = ['studio','sday','proc','sel','port','vendors','inv','req','route'];
function tbRealToday(){ const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
function tbIsClient(){ return role() === 'client'; }
function tbIsField(){ return document.body.classList.contains('crewmode') || ['foreman','driver','crew'].includes(role()); }
function tbIsMB(){ return document.body.classList.contains('ws-mb'); }

/* the New menu on a desktop: the same capture actions the phone's + offers */
function tbNewMenu(btn){
  const old = document.getElementById('tb-newmenu'); if (old){ old.remove(); return; }
  if (typeof mQuick !== 'function' || typeof mSheet !== 'function'){ return; }
  const base = mSheet;
  mSheet = (title, items) => new Promise(res => {
    const m = document.createElement('div'); m.id = 'tb-newmenu'; m.className = 'tb-menu';
    m.innerHTML = items.filter(([k]) => k !== 'ask').map(([k, l, i, s]) => `<button data-k="${k}"><b>${esc(l)}</b>${s ? `<small>${esc(s)}</small>` : ''}</button>`).join('');
    btn.after(m);
    const close = v => { m.remove(); document.removeEventListener('click', away, true); res(v); };
    const away = e => { if (!m.contains(e.target) && e.target !== btn) close(null); };
    setTimeout(() => document.addEventListener('click', away, true), 0);
    m.querySelectorAll('[data-k]').forEach(b => b.onclick = () => close(b.dataset.k));
  });
  try { mQuick(); } finally { mSheet = base; }
}

/* one date, said once: on target / ahead / past */
function tbVs(vLong, tgt, warn){ try { const y = (S && S.project.target ? S.project.target : today()).slice(0, 4); const m = tgt.match(/^(\d+)\/(\d+)$/); const d = new Date(`${vLong.replace(/^\w+, /, '')} ${y}`); if (m && !isNaN(d)){ const tg = new Date(+y, +m[1] - 1, +m[2]); const diff = Math.round((d - tg) / 86400000); if (diff === 0) return 'on target'; if (diff < 0) return `${-diff} day${diff === -1 ? '' : 's'} ahead of the ${tgt} target`; return `${diff} day${diff === 1 ? '' : 's'} past the ${tgt} target`; } } catch(e){} return warn ? `past the ${tgt} target` : `on the ${tgt} target`; }
/* the project band */
function tbBand(){
  let band = document.getElementById('projhdr');
  const sub = document.getElementById('subnav');
  if (!band){ band = document.createElement('div'); band.id = 'projhdr'; band.className = 'projhdr no-print'; (sub || document.querySelector('header.topbar')).after(band); }
  const projectScreen = TB_PROJECT_VIEWS.includes(view) && !tbIsClient() && !tbIsField() && !tbIsMB() && S && (S.tasks.length || (typeof designEst === 'function' && designEst(S)));
  if (!projectScreen){ band.hidden = true; return; }
  const fin = document.getElementById('st-finish'), fl = document.getElementById('st-float'); if (!fin || !fl){ band.hidden = true; return; }
  const read = el => { const b = el.querySelector('b'); const s = el.querySelector('span'); const parts = (s ? s.textContent : '').split(' · ').map(x => x.trim()).filter(Boolean); return {v: b ? b.textContent.trim() : '—', label: parts[0] || '', rest: parts.slice(1), warn: el.classList.contains('warn')}; };
  const F = read(fin), L = read(fl); const design = typeof isDesignProject === 'function' && isDesignProject(S); const studioView = ['sboard','sdraw','sfile'].includes(view);
  const chips = [];
  const cap = s => s ? s[0].toUpperCase() + s.slice(1) : s;
  if (design){
    chips.push({k:cap(F.label) || 'Current Phase', v:F.v, s:F.rest.join(' · '), tone:F.warn ? 'warn' : ''});
    chips.push({k:cap(L.label) || 'Next Deliverable', v:L.v, s:L.rest.join(' · '), tone:L.warn ? 'warn' : ''});
  } else {
    const target = (F.rest.find(x => /^target/.test(x)) || '').replace('target ', ''); const designEnd = (F.rest.find(x => /^design/.test(x)) || '').replace('design ', ''); const permits = (F.rest.find(x => /^permits/.test(x)) || '').replace('permits ', '');
    const days = L.rest.find(x => /working days/.test(x)); const outTarget = (L.rest.find(x => /^target/.test(x)) || '').replace('target ', '');
    chips.push({k:'Finish', v:F.v, s: target ? tbVs(F.v, target, F.warn) : 'substantial completion', tone:F.warn ? 'bad' : ''});
    if (studioView){ if (designEnd) chips.push({k:'Design', v:designEnd, s:'design track ends'}); if (permits) chips.push({k:'Permits', v:permits, s:'permit track ends'}); }
    else chips.push({k:'Crew Out', v:L.v, s: outTarget ? tbVs(L.v, outTarget, L.warn) : 'last day on site', tone:L.warn ? 'warn' : ''});
    if (days) chips.push({k:'Working Days Left', v:days.replace(/ working days.*/, ''), s:'to substantial completion'});
    if (!studioView && view === 'insp' && permits) chips.push({k:'Permits', v:permits, s:'permit track ends'});
    if (!studioView && ['sched','tasks','dec','mat'].includes(view) && designEnd) chips.push({k:'Design', v:designEnd, s:'design track ends'});
  }
  band.hidden = false;
  band.innerHTML = chips.slice(0, 4).map(c => `<span class="pj-chip ${c.tone || ''}"><span class="k">${esc(c.k)}</span><b>${esc(c.v)}</b>${c.s ? `<small>${esc(c.s)}</small>` : ''}</span>`).join('');
}

/* the bar itself */
function tbRender(){
  const bar = document.querySelector('header.topbar'); if (!bar) return;
  const client = tbIsClient(), field = tbIsField(), mb = tbIsMB();
  const search = document.getElementById('btn-search'); const fab = document.getElementById('fab'); const crumbs = document.getElementById('crumbs');
  /* search: a word, not a sentence; the shortcut hint only where there is room (CSS) */
  if (search){ const sp = search.querySelector('span'); if (sp) sp.textContent = 'Search'; search.style.display = client ? 'none' : ''; }
  if (fab && client) fab.style.display = 'none';
  /* New */
  let nb = document.getElementById('tb-new');
  if (!nb && search){ nb = document.createElement('button'); nb.id = 'tb-new'; nb.className = 'btn tb-new no-print'; nb.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg><span>New</span>'; nb.onclick = () => tbNewMenu(nb); search.after(nb); }
  if (nb) nb.style.display = (client || field || mb || (typeof mOn === 'function' && mOn())) ? 'none' : '';
  /* the pinned date */
  let pin = document.getElementById('tb-pin');
  if (!pin){ pin = document.createElement('span'); pin.id = 'tb-pin'; pin.className = 'tb-pin no-print'; bar.appendChild(pin); }
  const td = today(); const real = tbRealToday(); const pinned = td !== real;
  const mobile = typeof mOn === 'function' && mOn();
  if (pinned && !client && !field){ pin.hidden = false; pin.innerHTML = mobile ? esc(fmtL(td).replace(/^\w+, /, '')) : `<b>Demo date</b> ${esc(fmtL(td))}`; pin.title = `The workspace clock is pinned to ${fmtL(td)} for this demo. The real date is ${fmtL(real)}. Change it under Settings › Project.`; }
  else pin.hidden = true;
  /* client: company · project · a person */
  let msg = document.getElementById('tb-msg');
  if (client){
    if (crumbs && S && !crumbs.querySelector('input,select')) crumbs.innerHTML = `<span class="tb-co">SmartDesign</span><span class="tb-sep">›</span><b>${esc(typeof tcase === 'function' ? tcase(S.project.name) : S.project.name)}</b>`;
    if (!msg){ msg = document.createElement('button'); msg.id = 'tb-msg'; msg.className = 'btn tb-msg no-print'; msg.innerHTML = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a8 8 0 0 1-11.6 7.2L4 21l1.8-5.4A8 8 0 1 1 21 12z"/></svg><span>Message SmartDesign</span>'; msg.onclick = () => { if ((ROLE_VIEWS.client || []).includes('chat')){ view = 'chat'; render(); window.scrollTo(0, 0); } }; bar.appendChild(msg); }
    msg.style.display = (ROLE_VIEWS.client || []).includes('chat') && view !== 'chat' ? '' : 'none';
  } else if (msg) msg.style.display = 'none';
  if (!client && !mb && crumbs && TB_CROSS.includes(view) && !crumbs.querySelector('input,select')){ const b = crumbs.querySelector('b'); if (b) crumbs.innerHTML = `<b>${b.innerHTML}</b>`; }
  if (field && crumbs && !crumbs.querySelector('input,select')){ const cp = crumbs.querySelector('.crumb-proj a[data-crumb-client]'); if (cp){ let n = cp.nextSibling; while (n && (n.nodeType === 3 || (n.tagName === 'SPAN' && n.textContent.trim() === '›'))){ const x = n; n = n.nextSibling; x.remove(); if (x.nodeType !== 3) break; } cp.remove(); } }
  document.body.classList.toggle('tb-client', client);
  tbBand();
}
if (typeof render === 'function'){ const renderBase_tb = render; render = function(){ renderBase_tb.apply(this, arguments); try { tbRender(); } catch(e){ console.error('topbar', e); } }; }
/*<</topbar.js>>*/

/*<<meetings.js>>*/
/* ---------- Meetings: the notes Gemini writes become the record, the tasks, the decisions — and the lesson (2026-09-13) ----------
   Google Meet's "Take notes for me" mails a summary, suggested next steps and a link to a notes Doc that
   also holds the decisions, the details with timestamps and the transcript. Copper files the link and
   stops; HubSpot sends its own bot. Here the notes are read: the meeting is matched to a project and a
   client, every next step becomes a proposed task (owner, date), decisions land on the decision log,
   the summary lands on the client's record and the project log, dates mentioned for materials become
   ETA proposals — each proposed, then approved, edited or skipped, with per-kind auto-apply the owner
   can switch on. Across meetings the module keeps score: steps carried from meeting to meeting, who
   the team waits on, what took longer than estimated and why — and drafts the changes to the ERP that
   would fix it. A change goes live only when the owner approves it. */

function mtInit(){ DB.meetings = DB.meetings || []; DB.changes = DB.changes || []; DB.company = DB.company || {}; DB.company.meetAuto = DB.company.meetAuto || {log:true, note:true, task:false, update:false, decision:false, event:false, eta:false, rule:false}; return DB.meetings; }
const MT_STEP = /^\s*\[([^\]]+)\]\s*([^:]{2,80}):\s*(.+)$/;
const mtNorm = s => String(s || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const mtWords = s => new Set(mtNorm(s).split(' ').map(w => w.length > 4 ? w.replace(/(ies|es|s)$/, m => m === 'ies' ? 'y' : '') : w).filter(w => w.length > 2 && !/^(the|and|for|with|from|that|this|will|our|your|about|into|all|are|was|were|has|have|had|not|but|they|them|then|than|when|what|which|who|how|per|via|any|its|new|get|got|send|ask|make|meet|review|update|confirm|finalize|create|check)$/.test(w)));
function mtSim(a, b){ const A = mtWords(a), B = mtWords(b); if (!A.size || !B.size) return 0; let n = 0; A.forEach(w => { if (B.has(w)) n++; }); return n / Math.min(A.size, B.size); }
function mtIsNotes(c){ const s = (c.subject || '').replace(/^(fwd?|re):\s*/i, '').trim(); return /^notes:/i.test(s) && /(suggested next steps|notes from|summary)/i.test(c.text || ''); }

/* ---------- reading the email ---------- */
function mtParseEmail(c){
  const raw = String(c.text || '').replace(/\r/g, '');
  const m = {title:'', date:(c.date || '').slice(0, 10), summary:'', sections:[], steps:[], decisions:[], details:[], transcript:'', docUrl:'', attendees:[]};
  const t = (c.subject || '').match(/notes:\s*[“"]?([^”"]+?)[”"]?\s*(?:[A-Z][a-z]{2} \d{1,2}, \d{4}.*)?$/i); m.title = t ? t[1].trim() : (c.subject || 'Meeting').replace(/^(fwd?|re):\s*/i, '');
  const dm = (c.subject || '').match(/([A-Z][a-z]{2}) (\d{1,2}), (\d{4})/); if (dm){ const d = new Date(`${dm[1]} ${dm[2]} ${dm[3]}`); if (!isNaN(d)) m.date = iso(d); }
  const link = (c.links || []).find(l => /docs\.google\.com\/document\/d\//.test(l)) || (raw.match(/https:\/\/docs\.google\.com\/document\/d\/[A-Za-z0-9_-]+[^\s)]*/) || [])[0]; if (link) m.docUrl = link;
  /* body: the part after the forwarded header, if any */
  let body = raw; const fi = body.search(/Notes from\s+[“"]/); if (fi > -1) body = body.slice(fi);
  const lines = body.split('\n').map(l => l.trim());
  let mode = ''; let cur = null;
  for (const l of lines){
    if (!l){ continue; }
    if (/^Summary$/i.test(l)){ mode = 'summary'; continue; }
    if (/^Suggested next steps$/i.test(l)){ mode = 'steps'; continue; }
    if (/^(We['’]ve updated the Decisions|Meeting records|Is the Next Steps|Google LLC|You have received this email|Not Useful|Open meeting notes|The content was auto-generated|These notes have been sent)/i.test(l)){ if (/^(Meeting records|Google LLC|Is the Next)/i.test(l)) mode = 'end'; continue; }
    if (mode === 'summary'){ if (!m.summary){ m.summary = l; continue; } if (l.length < 70 && !/[.!?]$/.test(l) && /^[A-Z0-9]/.test(l) && !/^\d+\s*(am|pm)\b/i.test(l)){ cur = {h:l, text:''}; m.sections.push(cur); } else if (cur){ cur.text += (cur.text ? ' ' : '') + l; } else { m.summary += ' ' + l; } continue; }
    if (mode === 'steps'){ const s = l.match(MT_STEP); const last = m.steps[m.steps.length - 1]; if (s){ m.steps.push({owner:s[1].trim(), title:s[2].trim(), detail:s[3].trim()}); } else if (last && !/[.!?]$/.test(last.detail)){ last.detail += ' ' + l; /* a wrapped line */ } else { const u = l.match(/^([A-Z][A-Za-z ,'’&-]{2,80}):\s*(.+)$/); if (u) m.steps.push({owner:'', title:u[1].trim(), detail:u[2].trim()}); else if (last) last.detail += ' ' + l; } continue; }
  }
  m.attendees = mtAttendees(c, m);
  return m;
}
function mtAttendees(c, m){ const names = []; (m.steps || []).forEach(s => { if (!s.owner || /^the (group|team)$/i.test(s.owner)) return; const n = mtPerson(s.owner) || s.owner; if (!names.some(x => mtNorm(x) === mtNorm(n))) names.push(n); }); return names; }

/* ---------- reading the notes Doc (pasted or fetched as text/markdown) ---------- */
function mtParseDoc(md, m){
  const s = String(md || '').replace(/\r/g, '').replace(/\\\[/g, '[').replace(/\\\]/g, ']');
  const sec = (name, deep) => { const r = new RegExp(`###?\\s*\\**${name}\\**\\s*\\n([\\s\\S]*?)(?=\\n${deep ? '(?:#|###)' : '#{1,3}'}\\s|$)`, 'i'); const x = s.match(r); return x ? x[1].trim() : ''; };
  const strip = t => t.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').replace(/\*\*/g, '').replace(/\*/g, '');
  const sum = sec('Summary'); if (sum){ const ls = strip(sum).split('\n').map(l => l.trim()).filter(Boolean); m.summary = m.summary || ls[0] || ''; const secs = []; let cur = null; ls.slice(1).forEach(l => { if (l.length < 70 && !/[.!?]$/.test(l)){ cur = {h:l, text:''}; secs.push(cur); } else if (cur) cur.text += (cur.text ? ' ' : '') + l; }); m.sections = m.sections || []; secs.forEach(s => { if (!m.sections.some(x => mtNorm(x.h) === mtNorm(s.h))) m.sections.push(s); }); }
  const dec = sec('Decisions', true); if (dec){ m.decisions = []; let status = 'aligned'; strip(dec).split('\n').map(l => l.trim()).filter(Boolean).forEach(l => { const h = l.match(/^#{0,3}\s*(Aligned|Needs further discussion|Disagreed|Shelved)\s*$/i); if (h){ status = h[1].toLowerCase().replace(/ /g, '-'); return; } if (/^(We|Let us know|Helpful|Not helpful)/i.test(l)) return; const b = l.replace(/^[-•]\s*/, ''); if (b.length > 8) m.decisions.push({text:b, status}); }); }
  /* the bold heading of each decision is its name; keep it before the markdown is stripped */
  if (dec){ const heads = [...dec.matchAll(/^\s*[-•]\s*\*\*([^*]+)\*\*\s*(.*)$/gm)].map(x => ({name:x[1].trim(), body:x[2].trim()})); m.decisions.forEach(d => { const h = heads.find(x => d.text.startsWith(x.name)); if (h){ d.name = h.name; d.text = h.body || d.text; } }); }
  const ns = sec('Next steps'); if (ns){ const steps = []; strip(ns).split('\n').map(l => l.trim().replace(/^[-•]\s*/, '').trim()).filter(Boolean).forEach(l => { const x = l.match(MT_STEP); if (x) steps.push({owner:x[1].trim(), title:x[2].trim(), detail:x[3].trim()}); else { const u = l.match(/^([A-Z][^:]{2,80}):\s*(.+)$/); if (u) steps.push({owner:'', title:u[1].trim(), detail:u[2].trim()}); } }); m.steps = m.steps || []; steps.forEach(s => { if (!m.steps.some(x => mtSim(x.title + ' ' + x.detail, s.title + ' ' + s.detail) >= 0.6)) m.steps.push(s); }); }
  const det = sec('Details'); if (det){ m.details = []; det.split('\n').map(l => l.trim()).filter(l => /^[-•]\s*\*\*/.test(l) || /^[-•]\s*[A-Z]/.test(l)).forEach(l => { const ts = (l.match(/(\d{2}:\d{2}:\d{2})/) || [])[1] || ''; const h = (l.match(/\*\*([^*]+)\*\*/) || [])[1] || ''; const text = strip(l.replace(/^[-•]\s*/, '')).replace(/\(?\d{2}:\d{2}:\d{2}\)?/g, '').replace(/\(\s*\)/g, '').replace(/\s+([.,;])/g, '$1').replace(/\s{2,}/g, ' ').trim(); m.details.push({h:h.replace(/:$/, ''), text:h ? text.replace(h, '').replace(/^:\s*/, '').trim() : text, ts}); }); }
  const ti = s.search(/#\s*\**[^\n]*Transcript\**/i); if (ti > -1){ const tr = s.slice(ti); m.transcript = strip(tr.replace(/^#.*$/gm, l => l.replace(/[#*]/g, '').trim())).replace(/\n{3,}/g, '\n\n').trim(); }
  const inv = s.match(/Invited\s+([^\n]+)/); if (inv){ const names = [...inv[1].matchAll(/\[([^\]]+)\]/g)].map(x => mtPerson(x[1]) || x[1]); if (names.length) m.attendees = names.filter((n, i, a) => a.findIndex(x => mtNorm(x) === mtNorm(n)) === i); }
  m.docRead = true; return m;
}

/* ---------- who and where ---------- */
function mtMatchProject(m){ const hay = mtNorm([m.title, m.summary, ...(m.sections || []).map(x => x.h + ' ' + x.text)].join(' ')); let best = null, bs = 0;
  DB.projects.forEach(p => { const keys = [p.project.name, p.project.tag, ...String(p.project.keywords || '').split(/[,\n]/)].map(mtNorm).filter(k => k.length > 3); let score = 0; keys.forEach(k => { if (hay.includes(k)) score += k.length > 8 ? 3 : 2; }); const nm = p.project.name.match(/^(\d+)\s+([a-z]+)/i); if (nm && new RegExp(`\\b${nm[1]}\\s+${mtNorm(nm[2])}`).test(mtNorm(m.title))) score += 2; if (score > bs){ bs = score; best = p; } });
  return bs >= 2 ? best : null; }
function mtMatchClient(m, p){ if (p && p.clientId) return DB.clients.find(c => c.id === p.clientId) || null; const hay = ' ' + mtNorm(m.title + ' ' + m.summary) + ' '; const generic = /^(family|residence|residences|group|llc|inc|the|and|home|house|estate|trust|partners)$/; return DB.clients.find(c => mtNorm(c.name).split(' ').some(w => w.length > 3 && !generic.test(w) && hay.includes(' ' + w + ' '))) || null; }
function mtStaff(){ return (DB.users || []).filter(u => u.role !== 'client' && !/^mb_/.test(u.role || '')).map(u => u.name).concat((DB.employees || []).map(e => e.name)).filter((n, i, a) => a.findIndex(x => mtNorm(x) === mtNorm(n)) === i); }
function mtPerson(name){ const n = mtNorm(name); if (!n || /^the (group|team)$/.test(n)) return ''; const first = n.split(' ')[0]; const staff = mtStaff(); return staff.find(x => mtNorm(x) === n) || staff.find(x => mtNorm(x).split(' ')[0] === first) || ''; }

/* ---------- dates in words ---------- */
const MT_DOW = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const MT_MON = ['january','february','march','april','may','june','july','august','september','october','november','december'];
function mtDateWhy(text, base){ const t = String(text || '').toLowerCase(); const b = parse(base || today()); const out = (d, why) => ({date:iso(d), why});
  const lastOf = (y, mi) => new Date(y, mi + 1, 0);
  let x;
  if ((x = t.match(/\b(\d+|a|an|one|two|three|four|five|six)\s+(day|week|month)s?\s+from\s+(today|now|monday|tuesday|wednesday|thursday|friday)\b/))){ const n = /^\d+$/.test(x[1]) ? +x[1] : ({a:1, an:1, one:1, two:2, three:3, four:4, five:5, six:6})[x[1]]; let from = new Date(b); if (!/today|now/.test(x[3])){ const want = MT_DOW.indexOf(x[3]); let delta = (want - from.getDay() + 7) % 7; if (delta === 0) delta = 7; from.setDate(from.getDate() + delta); } const d = x[2] === 'day' ? addDays(from, n) : x[2] === 'week' ? addDays(from, 7 * n) : new Date(from.getFullYear(), from.getMonth() + n, from.getDate()); return out(d, x[0]); }
  if ((x = t.match(/\bin\s+(\d+|a|an|one|two|three|four|five|six)\s+(day|week|month)s?\b/))){ const n = /^\d+$/.test(x[1]) ? +x[1] : ({a:1, an:1, one:1, two:2, three:3, four:4, five:5, six:6})[x[1]]; const d = x[2] === 'day' ? addDays(b, n) : x[2] === 'week' ? addDays(b, 7 * n) : new Date(b.getFullYear(), b.getMonth() + n, b.getDate()); return out(d, x[0]); }
  if ((x = t.match(/\b(early|mid|late|end of|beginning of)[- ](jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*/))){ const mi = MT_MON.findIndex(m => m.startsWith(x[2].slice(0, 3))); let d = new Date(b.getFullYear(), mi, x[1] === 'early' || x[1] === 'beginning of' ? 5 : x[1] === 'mid' ? 15 : x[1] === 'late' ? 25 : 1); if (x[1] === 'end of') d = lastOf(b.getFullYear(), mi); if (d < b) d.setFullYear(d.getFullYear() + 1); return out(d, x[0]); }
  if ((x = t.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})\b/))){ const mi = MT_MON.findIndex(m => m.startsWith(x[1].slice(0, 3))); const d = new Date(b.getFullYear(), mi, +x[2]); if (d < b) d.setFullYear(d.getFullYear() + 1); return out(d, x[0]); }
  if ((x = t.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/))){ const y = x[3] ? (+x[3] < 100 ? 2000 + +x[3] : +x[3]) : b.getFullYear(); return out(new Date(y, +x[1] - 1, +x[2]), x[0]); }
  if ((x = t.match(/\b(?:by |on |before )?the (\d{1,2})(?:st|nd|rd|th)\b/))){ let d = new Date(b.getFullYear(), b.getMonth(), +x[1]); if (d < b) d = new Date(b.getFullYear(), b.getMonth() + 1, +x[1]); return out(d, x[0]); }
  if ((x = t.match(/\bweek of (?:the )?(\d{1,2})(?:st|nd|rd|th)\b/))){ let d = new Date(b.getFullYear(), b.getMonth(), +x[1]); if (d < b) d = new Date(b.getFullYear(), b.getMonth() + 1, +x[1]); return out(d, x[0]); }
  if ((x = t.match(/\b(end of (?:the )?month|month[- ]end)\b/))) return out(lastOf(b.getFullYear(), b.getMonth()), x[0]);
  if ((x = t.match(/\bnext month\b/))) return out(new Date(b.getFullYear(), b.getMonth() + 1, 1), x[0]);
  if ((x = t.match(/\b(today|eod|end of (?:the )?day|asap|right away|this morning|this afternoon)\b/))) return out(b, x[0]);
  if ((x = t.match(/\btomorrow\b/))) return out(addDays(b, 1), x[0]);
  if ((x = t.match(/\bnext week\b/))) return out(addDays(b, 7), x[0]);
  if ((x = t.match(/\b(end of (?:the |this )?week|this week|eow)\b/))){ const d = new Date(b); d.setDate(d.getDate() + ((5 - d.getDay() + 7) % 7 || 7)); return out(d, x[0]); }
  if ((x = t.match(/\b(next\s+)?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b/))){ const want = MT_DOW.indexOf(x[2]); const d = new Date(b); let delta = (want - d.getDay() + 7) % 7; if (delta === 0) delta = 7; if (x[1] && delta < 7) delta += 7; d.setDate(d.getDate() + delta); return out(d, x[0]); }
  return null;
}
function mtDate(text, base){ const r = mtDateWhy(text, base); return r ? r.date : ''; }
function mtTime(text){ const x = String(text || '').match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i); if (!x) return ''; let h = +x[1] % 12; if (x[3].toLowerCase() === 'pm') h += 12; return `${String(h).padStart(2, '0')}:${x[2] || '00'}`; }

/* ---------- from notes to proposals ---------- */
function mtPropose(m){ const p = m.projectId ? DB.projects.find(x => x.id === m.projectId) : null; const c = m.clientId ? DB.clients.find(x => x.id === m.clientId) : null; const P = []; const td = m.date || today();
  const add = o => { o.id = o.id || uid('mp'); o.status = o.status || 'proposed'; P.push(o); };
  if (!p){ if (c) add({kind:'note', title:`Note on ${c.name}'s record`, detail:m.summary, apply:{clientId:c.id}}); return P; }
  /* the record itself */
  add({kind:'log', title:`Log the meeting on ${p.project.name}`, detail:m.summary, apply:{projectId:p.id}});
  if (c) add({kind:'note', title:`Note on ${c.name}'s record`, detail:m.summary, apply:{clientId:c.id}});
  /* next steps → tasks (new, or an update to one that exists); a date only when the notes give one */
  (m.steps || []).forEach((s, i) => {
    const owner = mtPerson(s.owner); const when = mtDateWhy(s.detail, td) || mtDateWhy(s.title, td); const due = when ? when.date : ''; const why = when ? when.why : ''; const time = mtTime(s.detail);
    const isMeeting = /\b(meet|meeting|call|sit down|walk-?through)\b/i.test(s.title + ' ' + s.detail) && (due || time);
    const dateLine = due ? `${fmtL(due)}${time ? ' ' + time.replace(/^(\d{2}):(\d{2})$/, (a, h, mm) => `${(+h % 12) || 12}:${mm} ${+h >= 12 ? 'PM' : 'AM'}`) : ''} (“${why}”)` : 'no date in the notes';
    if (isMeeting){ add({kind:'event', title:`${s.title}${due ? ' — ' + fmtL(due) : ''}`, detail:`${s.detail} · ${dateLine}`, step:i, apply:{projectId:p.id, title:s.title, due, time, owner, why}}); return; }
    const existing = (p.actions || []).find(a => a.status !== 'done' && mtSim(a.title, s.title + ' ' + s.detail) >= 0.6);
    if (existing) add({kind:'update', title:`Update “${existing.title}”`, detail:`${owner ? owner + ' · ' : ''}${dateLine} · ${s.detail}`, step:i, apply:{projectId:p.id, actionId:existing.id, due, owner, note:s.detail, why}});
    else add({kind:'task', title:`${s.title} → ${owner || 'Unassigned'}`, detail:`${s.detail} · ${dateLine}`, step:i, noDate:!due, apply:{projectId:p.id, title:s.title, notes:s.detail, assignee:owner, due, why}});
    /* waiting on someone outside the team */
    const w = s.detail.match(/\b(?:ask|from|with|waiting on|follow up with|confirm with)\s+([A-Z][a-z]+)\b/); if (w && !mtPerson(w[1])) s.waitsOn = w[1]; else s.waitsOn = '';
  });
  /* decisions → the decision log */
  (m.decisions || []).forEach(d => { const name = (d.name || d.text.split(/\s[—–-]\s|:\s|\.\s/)[0]).slice(0, 90); const open = p.decisions.find(x => x.status === 'open' && mtSim(x.name, name + ' ' + d.text) >= 0.5);
    if (d.status === 'aligned'){ if (open) add({kind:'decision', title:`Mark “${open.name}” decided`, detail:d.text, apply:{projectId:p.id, decisionId:open.id, made:true, name:open.name, note:d.text}}); else add({kind:'decision', title:`Record the decision: ${name}`, detail:d.text, apply:{projectId:p.id, name, made:true, note:d.text}}); }
    else add({kind:'decision', title:`Open decision: ${name}`, detail:`${d.status.replace(/-/g, ' ')} — ${d.text}`, apply:{projectId:p.id, name, made:false, note:d.text, due:iso(addWork(td, +(p.project.decBuf || 3), false))}}); });
  /* details that move a date on a material */
  (m.details || []).forEach(d => { const when = mtDateWhy(d.text, td); if (!when) return; const mat = p.materials.find(x => x.status !== 'on-site' && mtSim(x.name, d.h + ' ' + d.text) >= 0.5); if (mat) add({kind:'eta', title:`${mat.name}: expected ${fmtL(when.date)}`, detail:`${d.text} (“${when.why}”)`, apply:{projectId:p.id, materialId:mat.id, eta:when.date}}); });
  /* rules the team stated for itself — every sentence that reads like one */
  [...(m.sections || []).map(x => x.text), ...(m.details || []).map(x => x.text)].forEach(text => { [...String(text).matchAll(/([^.]*\b(?:require|must|protocol|rule|going forward|from now on|always|before (?:any|conducting|starting))\b[^.]*\.)/gi)].forEach(r => { const rule = r[1].trim(); if (!P.some(x => x.kind === 'rule' && x.apply.rule === rule)) add({kind:'rule', title:'A rule the team set for itself', detail:rule, apply:{rule}}); }); });
  return P;
}

/* ---------- applying an approved proposal ---------- */
function mtApply(m, pr){ const A = pr.apply || {}; const by = (typeof currentUser === 'function' && currentUser() || {}).name || ''; const src = `Meeting · ${m.title} · ${fmtL(m.date)}`; const p = A.projectId ? DB.projects.find(x => x.id === A.projectId) : null;
  const inProject = fn => { if (!p) return fn(); const keep = S; S = p; try { return fn(); } finally { S = keep; } };
  if (pr.kind === 'log' && p) inProject(() => log(`Meeting — ${m.title}: ${m.summary}`, 'meeting', by));
  if (pr.kind === 'note'){ const c = DB.clients.find(x => x.id === A.clientId); if (c){ if (Array.isArray(c.notes)) c.notes.unshift({id:uid('n'), at:today(), by, text:`${src}\n${m.summary}`}); else c.notes = `${fmtL(m.date)} — ${m.title}: ${m.summary}\n` + (c.notes || ''); } }
  if (pr.kind === 'task' && p){ p.actions = p.actions || []; p.actions.push({id:uid('a'), title:A.title, assignee:A.assignee || '', due:A.due, priority:'med', status:'todo', link:null, notes:A.notes || '', source:{kind:'meeting', id:m.id, label:src}, createdAt:today(), completedAt:''}); }
  if (pr.kind === 'update' && p){ const a = (p.actions || []).find(x => x.id === A.actionId); if (a){ if (A.due) a.due = A.due; if (A.owner) a.assignee = A.owner; a.notes = [a.notes, `${src}: ${A.note}`].filter(Boolean).join('\n'); } }
  if (pr.kind === 'event' && p){ p.actions = p.actions || []; p.actions.push({id:uid('a'), title:`Meeting: ${A.title}${A.time ? ' at ' + A.time.replace(/^(\d{2}):(\d{2})$/, (a, h, mm) => `${(+h % 12) || 12}:${mm} ${+h >= 12 ? 'PM' : 'AM'}`) : ''}`, assignee:A.owner || '', due:A.due, time:A.time || '', priority:'med', status:'todo', link:null, notes:pr.detail, source:{kind:'meeting', id:m.id, label:src}, createdAt:today(), completedAt:'', meeting:true}); }
  if (pr.kind === 'decision' && p){ if (A.decisionId){ const d = p.decisions.find(x => x.id === A.decisionId); if (d){ d.status = 'made'; d.madeAt = m.date; d.notes = [d.notes, `${src}: ${A.note}`].filter(Boolean).join('\n'); } } else p.decisions.push({id:uid('dc'), name:A.name, owner:A.owner || 'SmartDesign', due:A.made ? m.date : (A.due || iso(addDays(parse(m.date), 7))), status:A.made ? 'made' : 'open', madeAt:A.made ? m.date : '', kind:'general', notes:`${src}: ${A.note}`}); }
  if (pr.kind === 'eta' && p){ const mat = p.materials.find(x => x.id === A.materialId); if (mat){ mat.eta = A.eta; mat.notes = [mat.notes, `${src}: ${pr.detail}`].filter(Boolean).join('\n'); } }
  if (pr.kind === 'rule'){ DB.company.playbook = DB.company.playbook || []; DB.company.playbook.push({id:uid('rl'), text:A.rule, from:src, at:today()}); }
  pr.status = 'applied'; pr.appliedAt = today(); pr.by = by;
}
/* take a log entry or a client note back when the meeting moves to another project or client */
function mtRetract(m, pr){ const A = pr.apply || {}; if (pr.kind === 'log'){ const p = DB.projects.find(x => x.id === A.projectId); if (p && Array.isArray(p.log)){ const i = p.log.findIndex(l => (l.msg || '').startsWith(`Meeting — ${m.title}:`)); if (i > -1) p.log.splice(i, 1); } } if (pr.kind === 'note'){ const c = DB.clients.find(x => x.id === A.clientId); if (c && typeof c.notes === 'string'){ const line = `${fmtL(m.date)} — ${m.title}: ${m.summary}\n`; c.notes = c.notes.replace(line, ''); } } }
function mtAutoApply(m){ const auto = DB.company.meetAuto || {}; m.proposals.forEach(pr => { if (pr.status === 'proposed' && auto[pr.kind]) mtApply(m, pr); }); }

/* ---------- ingest ---------- */
function mtIngest(c){ mtInit(); if (DB.meetings.some(x => x.msgId && x.msgId === (c.msgId || c.id))) return null; const m = mtParseEmail(c); if (!m.steps.length && !m.summary) return null;
  /* the same notes arriving twice — the original and a forward from the host — are one meeting */
  const dup = DB.meetings.find(x => x.date === m.date && mtNorm(x.title) === mtNorm(m.title)); if (dup){ c.meetingId = dup.id; c.status = 'read'; c.proposals = []; if (!dup.docUrl && m.docUrl) dup.docUrl = m.docUrl; return null; }
  const p = mtMatchProject(m); const cl = mtMatchClient(m, p);
  const rec = Object.assign({id:uid('mt'), source:'gemini', msgId:c.msgId || c.id, commId:c.id, projectId:p ? p.id : '', clientId:cl ? cl.id : '', status:'new', createdAt:today(), proposals:[]}, m);
  rec.proposals = mtPropose(rec); mtAutoApply(rec); DB.meetings.push(rec); c.meetingId = rec.id; c.status = 'read'; c.proposals = []; return rec; }
function mtScan(){ mtInit(); let n = 0; (DB.comms || []).forEach(c => { if (!c.meetingId && mtIsNotes(c)){ if (mtIngest(c)) n++; } }); return n; }
function mtReplay(m){ m.proposals.filter(pr => pr.status === 'applied' && ((pr.kind === 'log' && pr.apply.projectId !== m.projectId) || (pr.kind === 'note' && pr.apply.clientId !== m.clientId))).forEach(pr => { mtRetract(m, pr); pr.status = 'moved'; }); m.proposals = m.proposals.filter(pr => pr.status === 'applied' || pr.status === 'skipped'); const fresh = mtPropose(m).filter(pr => !m.proposals.some(a => a.kind === pr.kind && (a.title === pr.title || (a.step != null && a.step === pr.step)))); m.proposals.push(...fresh); mtAutoApply(m); }

/* ---------- what the meetings are telling us ---------- */
function mtLearn(){ mtInit(); const M = DB.meetings.slice().sort((a, b) => (a.date || '').localeCompare(b.date || '')); const td = today(); const out = {carried:[], owners:{}, waits:{}, late:[], decisionsSlow:[], topics:{}, ruleCount:0, n:M.length};
  const seen = []; M.forEach(m => (m.steps || []).forEach(s => { const prev = seen.find(x => mtSim(x.title + ' ' + x.detail, s.title + ' ' + s.detail) >= 0.6); if (prev){ prev.times++; prev.last = m.date; prev.meetings.push(m.title); if (!out.carried.includes(prev)) out.carried.push(prev); } else seen.push({title:s.title, detail:s.detail, owner:mtPerson(s.owner), first:m.date, last:m.date, times:1, meetings:[m.title]}); }));
  M.forEach(m => (m.steps || []).forEach(s => { const o = mtPerson(s.owner) || 'Unassigned'; out.owners[o] = out.owners[o] || {steps:0, done:0, open:0}; out.owners[o].steps++; const p = m.projectId ? DB.projects.find(x => x.id === m.projectId) : null; const a = p ? (p.actions || []).find(x => x.source && x.source.id === m.id && mtSim(x.title, s.title) >= 0.6) : null; if (a){ if (a.status === 'done') out.owners[o].done++; else { out.owners[o].open++; if (a.due && a.due < td) out.late.push({title:a.title, owner:o, due:a.due, meeting:m.title}); } } if (s.waitsOn){ out.waits[s.waitsOn] = (out.waits[s.waitsOn] || 0) + 1; } }));
  M.forEach(m => (m.sections || []).forEach(x => { const k = x.h.replace(/^(optimizing|improving|finalizing|updating)\s+/i, ''); out.topics[k] = (out.topics[k] || 0) + 1; }));
  M.forEach(m => (m.decisions || []).forEach(d => { if (d.status !== 'aligned') out.decisionsSlow.push({text:d.text, status:d.status, meeting:m.title, date:m.date}); }));
  out.ruleCount = (DB.company.playbook || []).length;
  /* why things take longer: the reasons the notes give */
  const why = {}; const RE = [['decision latency', /\b(waiting on (a )?decision|not (yet )?decided|needs? (further )?discussion|finalize .* before|until .* (is )?finalized)\b/i], ['vendor lead time', /\b(lead time|back ?order|cannot be scheduled|can'?t be done next week|weeks? out|mid-[a-z]+|reschedul)/i], ['design change', /\b(redesign|design change|revise the (layout|drawing)|changed the (layout|plan)|new layout)\b/i], ['hidden condition', /\b(existing (damage|condition)|found (that|out)|uncovered|hidden|unexpected)\b/i], ['permits and inspections', /\b(inspection|permit|dob|lpc|examiner|objection)\b/i], ['data and process', /\b(csv|spreadsheet|task list|check-?in process|clean data|import)\b/i]];
  M.forEach(m => { const texts = [...(m.sections || []).map(x => x.text), ...(m.details || []).map(x => x.text), ...(m.steps || []).map(x => x.detail)]; RE.forEach(([k, r]) => texts.forEach(t => { if (r.test(t)){ why[k] = why[k] || {n:0, quotes:[]}; why[k].n++; if (why[k].quotes.length < 3) why[k].quotes.push({t:t.slice(0, 160), m:m.title}); } })); });
  out.why = Object.entries(why).sort((a, b) => b[1].n - a[1].n);
  return out; }

/* the changes the lessons suggest — drafted, never live until approved */
function mtDraftChanges(L){ mtInit(); const drafts = []; const has = t => DB.changes.some(c => c.title === t && c.status !== 'declined');
  const push = (title, why, kind, delta, evidence) => { if (has(title)) return; drafts.push({id:uid('ch'), title, why, kind, delta, evidence:evidence || [], status:'draft', at:today(), by:'The assistant'}); };
  const w = Object.fromEntries(L.why || []);
  if (w['vendor lead time'] && w['vendor lead time'].n >= 1){ const cur = Math.max(...DB.projects.map(p => +p.project.matBuf || 1)); push('Order materials a week earlier', `Vendors could not hold the dates the team assumed in ${w['vendor lead time'].n} meeting note${w['vendor lead time'].n === 1 ? '' : 's'}. A larger buffer between order-by and need-by turns a surprise into a plan — on every project.`, 'setting', {path:'project.matBuf', from:cur, to:cur + 5, label:'Material buffer (working days between order-by and need-by)'}, w['vendor lead time'].quotes); }
  if (w['decision latency'] && w['decision latency'].n >= 1){ const cur = Math.max(...DB.projects.map(p => +p.project.decBuf || 3)); push('Ask for decisions earlier', `Work waited on a decision in ${w['decision latency'].n} note${w['decision latency'].n === 1 ? '' : 's'}. Moving the decision due date further ahead of the task it holds gives the client time to answer before anything slips.`, 'setting', {path:'project.decBuf', from:cur, to:cur + 2, label:'Decision buffer (working days before the task that needs it)'}, w['decision latency'].quotes); }
  if (L.carried.length) push('Carry-overs get a date and a reminder', `${L.carried.length} next step${L.carried.length === 1 ? '' : 's'} came back in a later meeting without being closed. A step with no due date is not a commitment; the ERP should date every step from a meeting and remind the owner the day before.`, 'rule', {path:'company.meetAuto.task', from:!!(DB.company.meetAuto || {}).task, to:true, label:'Create tasks from meeting next steps automatically'}, L.carried.slice(0, 3).map(c => ({t:`${c.title} — ${c.times}× (${c.meetings.slice(0, 2).join(', ')})`, m:''})));
  const waits = Object.entries(L.waits || {}).sort((a, b) => b[1] - a[1]); if (waits.length && waits[0][1] >= 2) push(`Put what ${waits[0][0]} owes on the decision log`, `The team waited on ${waits[0][0]} ${waits[0][1]} times across meetings. Anything owed by someone outside the team belongs on the decision log with a due date, so the wait is visible and chased, not remembered.`, 'rule', {path:'company.meetAuto.decision', from:!!(DB.company.meetAuto || {}).decision, to:true, label:'Record decisions from meetings automatically'}, []);
  if (w['data and process'] && w['data and process'].n >= 2) push('Weekly check-in from the ERP, not a spreadsheet', `The team spent time in ${w['data and process'].n} meetings on CSVs and task lists. The check-in should open on the Today screen with the same task IDs and priorities, so nobody cleans data before a meeting.`, 'code', {path:'brief.weeklyCheckin', from:false, to:true, label:'A weekly check-in page built from the schedule and the meeting steps'}, w['data and process'].quotes);
  if (w['permits and inspections'] && w['permits and inspections'].n >= 2) push('Special inspections list on every permit', `Inspections came up in ${w['permits and inspections'].n} meetings as something still to be asked for. The permit record should carry the required special inspections as a checklist the moment the permit is filed.`, 'code', {path:'permits.specialInspections', from:false, to:true, label:'A special-inspections checklist on the permit record'}, w['permits and inspections'].quotes);
  drafts.forEach(d => DB.changes.push(d)); return drafts; }
function mtChangeApply(ch){ const d = ch.delta || {}; if (ch.kind === 'setting' || ch.kind === 'rule'){ const [root, ...rest] = d.path.split('.'); const set = obj => { for (let i = 0; i < rest.length - 1; i++){ obj[rest[i]] = obj[rest[i]] || {}; obj = obj[rest[i]]; } obj[rest[rest.length - 1]] = d.to; }; if (root === 'project'){ DB.projects.forEach(p => set(p.project)); DB.company.projectDefaults = DB.company.projectDefaults || {}; set(DB.company.projectDefaults); } else if (root === 'company') set(DB.company); else return false; return true; } return true; }

/* ---------- the screen ---------- */
let mtTab = 'meetings', mtOpen = '';
const MT_KIND = {log:'Project Log', note:'Client Note', task:'Task', update:'Task Update', event:'Meeting', decision:'Decision', eta:'Material Date', rule:'Rule'};
const MT_STATUS = {draft:'Draft', approved:'Approved', live:'Live', declined:'Declined'};
function mtCanApprove(){ return ['owner','pm','coord','design_mgr'].includes(role()); }
function mtWaiting(){ mtInit(); return DB.meetings.reduce((a, m) => a + m.proposals.filter(p => p.status === 'proposed').length, 0); }
function renderMeetings(){ const host = document.getElementById('meetings-body'); if (!host) return; mtInit(); mtScan();
  const M = DB.meetings.slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const tabs = [['meetings', 'Meetings'], ['learn', 'What We Are Learning'], ['changes', `Changes${DB.changes.filter(c => c.status === 'draft').length ? ` · ${DB.changes.filter(c => c.status === 'draft').length}` : ''}`], ['settings', 'Settings']];
  let body = '';
  if (mtTab === 'meetings' && mtOpen){ const m = DB.meetings.find(x => x.id === mtOpen); if (m) body = mtMeetingHtml(m); else mtOpen = ''; }
  if (mtTab === 'meetings' && !mtOpen){
    body = `<div class="row" style="margin-bottom:10px;gap:8px;align-items:center"><span class="small muted">Every meeting Gemini took notes for lands here from the Inbox, matched to its project and client, with its next steps proposed as tasks.</span><span class="grow"></span><button class="btn" id="mt-paste">Paste Notes</button><button class="btn primary" id="mt-scan">Read the Inbox</button></div>` +
      grid({id:'meetings', cols:[{key:'date', label:'Date', type:'date', w:'110px', get:r => r.m.date}, {key:'title', label:'Meeting', get:r => ({html:`<span data-mt="${r.m.id}"></span><b>${esc(r.m.title)}</b><div class="small muted">${esc(r.m.summary.slice(0, 110))}${r.m.summary.length > 110 ? '…' : ''}</div>`, text:r.m.title, sort:r.m.title})}, {key:'proj', label:'Project', w:'170px', get:r => r.m.projectId ? (DB.projects.find(p => p.id === r.m.projectId) || {project:{name:''}}).project.name : {html:'<span class="pill warn">Not Matched</span>', text:'', sort:''}}, {key:'who', label:'With', w:'160px', get:r => (r.m.attendees || []).slice(0, 3).join(', ')}, {key:'steps', label:'Next Steps', type:'num', w:'90px', get:r => (r.m.steps || []).length}, {key:'wait', label:'Waiting', type:'num', w:'90px', get:r => r.m.proposals.filter(p => p.status === 'proposed').length}, {key:'st', label:'Status', type:'status', w:'110px', get:r => { const w = r.m.proposals.filter(p => p.status === 'proposed').length; return {text:w ? 'To review' : 'Reviewed', cls:w ? 'warn' : 'ok'}; }}], rows:M.map(m => ({id:m.id, data:{m}, sev:m.proposals.some(p => p.status === 'proposed') ? 2 : 0})), defaultSort:'date', dir:'desc', empty:'No meeting notes yet. Turn on “Take notes for me” in Google Meet and they will land here from the Inbox.'});
  }
  if (mtTab === 'learn') body = mtLearnHtml();
  if (mtTab === 'changes') body = mtChangesHtml();
  if (mtTab === 'settings') body = mtSettingsHtml();
  host.innerHTML = `<div class="ctabs" style="margin-bottom:12px">${tabs.map(([k, n]) => `<button class="${mtTab === k ? 'on' : ''}" data-mttab="${k}">${n}</button>`).join('')}</div>${body}`;
  mtWire(host);
}
function mtMeetingHtml(m){ const p = m.projectId ? DB.projects.find(x => x.id === m.projectId) : null; const c = m.clientId ? DB.clients.find(x => x.id === m.clientId) : null; const waiting = m.proposals.filter(x => x.status === 'proposed');
  const pr = x => `<div class="mt-pr ${x.status}"><div class="mt-pr-k">${MT_KIND[x.kind] || x.kind}</div><div class="mt-pr-b"><b>${esc(x.title)}</b>${x.noDate && x.status === 'proposed' ? ' <span class="pill warn">No Date</span>' : ''}${x.detail ? `<div class="small muted">${esc(x.detail)}</div>` : ''}${x.status === 'applied' ? `<div class="small ok">Applied ${fmtL(x.appliedAt)}${x.by ? ' by ' + esc(x.by) : ''}</div>` : x.status === 'skipped' ? '<div class="small muted">Skipped</div>' : ''}</div>${x.status === 'proposed' && mtCanApprove() ? `<div class="mt-pr-a"><button class="btn sm primary" data-mtok="${x.id}">Approve</button>${['task','event','update','decision'].includes(x.kind) ? `<button class="btn sm" data-mtedit="${x.id}">Edit</button>` : ''}<button class="btn sm ghost" data-mtskip="${x.id}">Skip</button></div>` : ''}</div>`;
  return `<div class="crumb"><a href="#" data-mtback>Meetings</a><span>›</span>${esc(m.title)}</div>
    <div class="ph"><div><h2 data-ia-keep="1">${esc(m.title)}</h2><div class="lead">${fmtL(m.date)}${(m.attendees || []).length ? ' · with ' + esc(m.attendees.join(', ')) : ''}${m.commId ? ` · <a href="#" data-mtmail>the email</a>` : ''}</div></div><div class="acts">${m.docUrl ? `<a class="btn sm" href="${esc(m.docUrl)}" target="_blank" rel="noopener">Open in Google Docs</a>` : ''}${m.docUrl && !m.docRead && window.SDP_CONFIG ? '<button class="btn sm" id="mt-fetch">Fetch the Notes Doc</button>' : ''}<button class="btn sm" id="mt-doc">Paste the Notes Doc</button>${p && typeof openAI === 'function' ? `<button class="btn sm" id="mt-deep">Deep Read With the Assistant</button>` : ''}</div></div>
    <div class="grid2">
      <div>
        <div class="card"><div class="hd"><h3>Where It Belongs</h3></div><div class="f2"><div class="f"><label>Project</label><select id="mt-proj"><option value="">— none —</option>${DB.projects.map(x => `<option value="${x.id}" ${x.id === m.projectId ? 'selected' : ''}>${esc(x.project.name)}</option>`).join('')}</select></div><div class="f"><label>Client</label><select id="mt-client"><option value="">— none —</option>${DB.clients.map(x => `<option value="${x.id}" ${x.id === m.clientId ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select></div></div></div>
        ${mtSinceHtml(m)}
        <div class="card" style="margin-top:10px"><div class="hd"><h3>Summary</h3></div><p style="margin:0 0 8px">${esc(m.summary)}</p>${(m.sections || []).map(s => `<p style="margin:0 0 8px"><b>${esc(s.h)}</b><br>${esc(s.text)}</p>`).join('')}</div>
        ${(m.decisions || []).length ? `<div class="card" style="margin-top:10px"><div class="hd"><h3>Decisions</h3></div>${m.decisions.map(d => `<div class="row" style="gap:8px;align-items:flex-start;margin-bottom:6px"><span class="pill ${d.status === 'aligned' ? 'ok' : 'warn'}">${esc(d.status.replace(/-/g, ' '))}</span><span>${esc(d.text)}</span></div>`).join('')}</div>` : ''}
        <div class="card" style="margin-top:10px"><div class="hd"><h3>Next Steps</h3><span class="small muted">${(m.steps || []).length} from the notes</span></div>${(m.steps || []).map(s => `<div class="st-item"><span class="k">${esc(mtPerson(s.owner) || s.owner)}${s.waitsOn ? ` · waits on ${esc(s.waitsOn)}` : ''}</span><b>${esc(s.title)}</b><span class="small muted">${esc(s.detail)}</span></div>`).join('') || '<div class="small muted">No next steps in the notes.</div>'}</div>
        ${(m.details || []).length ? `<div class="card" style="margin-top:10px"><div class="hd"><h3>Details</h3></div>${m.details.map(d => `<div class="st-item"><span class="k">${d.ts ? esc(d.ts) : ''}</span><b>${esc(d.h)}</b><span class="small muted">${esc(d.text)}</span></div>`).join('')}</div>` : ''}
        ${m.transcript ? `<details class="card" style="margin-top:10px"><summary><b>Transcript</b> <span class="small muted">about ${Math.round(m.transcript.split(/\s+/).length / 130)} minutes of talk</span></summary><pre class="small" style="white-space:pre-wrap;max-height:400px;overflow:auto;margin-top:8px">${esc(m.transcript.slice(0, 60000))}</pre></details>` : ''}
      </div>
      <div>
        <div class="card"><div class="hd"><h3>Proposed From These Notes</h3><span class="grow"></span>${waiting.length && mtCanApprove() ? `<button class="btn sm primary" id="mt-okall">Approve All · ${waiting.length}</button>` : ''}<button class="btn sm ghost" id="mt-redo" title="Read the notes again after changing the project or client">Re-Read</button></div>
          ${!p ? '<div class="note warn" style="margin-bottom:8px"><b>No project matched.</b> Pick the project on the left — next steps, decisions and dates are proposed against it.</div>' : ''}${m.proposals.length ? m.proposals.map(pr).join('') : '<div class="small muted">Nothing to propose from these notes.</div>'}
          <div class="small muted" style="margin-top:8px">Approve puts it on the record with the meeting as its source. Settings decides which kinds apply on their own.</div></div>
      </div>
    </div>`; }
function mtSinceHtml(m){ if (!m.projectId) return ''; const prev = DB.meetings.filter(x => x.id !== m.id && x.projectId === m.projectId && (x.date || '') <= (m.date || '')).sort((a, b) => (b.date || '').localeCompare(a.date || ''))[0]; if (!prev || !(prev.steps || []).length) return ''; const p = DB.projects.find(x => x.id === m.projectId);
  const rows = prev.steps.map(s => { const a = (p.actions || []).find(x => x.source && x.source.id === prev.id && mtSim(x.title, s.title) >= 0.6); const back = (m.steps || []).some(x => mtSim(x.title + ' ' + x.detail, s.title + ' ' + s.detail) >= 0.6); const st = a && a.status === 'done' ? 'closed' : back ? 'came back' : a ? (a.due && a.due < m.date ? 'slipped' : 'open') : 'never became a task'; return {s, st}; });
  const n = k => rows.filter(r => r.st === k).length;
  return `<div class="card" style="margin-top:10px"><div class="hd"><h3>Since ${esc(prev.title)}</h3><span class="small muted">${fmtL(prev.date)} · ${n('closed')} closed · ${n('came back')} came back · ${n('slipped')} slipped</span></div>${rows.map(r => `<div class="st-item ${/came back|slipped/.test(r.st) ? 'late' : ''}"><span class="k">${esc(r.st)}</span><b>${esc(r.s.title)}</b><span class="small muted">${esc(mtPerson(r.s.owner) || r.s.owner || 'unassigned')}</span></div>`).join('')}</div>`; }
function mtLearnHtml(){ const L = mtLearn(); if (!L.n) return '<div class="empty">Nothing to learn from yet — the first meeting notes will start the record.</div>';
  const owners = Object.entries(L.owners).sort((a, b) => b[1].steps - a[1].steps); const waits = Object.entries(L.waits).sort((a, b) => b[1] - a[1]); const topics = Object.entries(L.topics).sort((a, b) => b[1] - a[1]).slice(0, 6);
  const working = []; const notWorking = [];
  owners.forEach(([o, s]) => { if (s.steps >= 2 && s.done / s.steps >= 0.6) working.push(`${o} closes what they take on — ${s.done} of ${s.steps} steps done`); if (s.open >= 3) notWorking.push(`${o} is carrying ${s.open} open steps from meetings`); });
  if (!L.carried.length && L.n >= 2) working.push('No next step has had to be repeated in a later meeting'); if (L.carried.length) notWorking.push(`${L.carried.length} step${L.carried.length === 1 ? '' : 's'} came back in a later meeting without being closed`);
  if (L.late.length) notWorking.push(`${L.late.length} meeting step${L.late.length === 1 ? '' : 's'} past due`);
  if (L.decisionsSlow.length) notWorking.push(`${L.decisionsSlow.length} decision${L.decisionsSlow.length === 1 ? '' : 's'} left the room still open`);
  return `<div class="grid2">
    <div>
      <div class="card"><div class="hd"><h3>What Is Working</h3></div>${working.length ? working.map(x => `<div class="st-item"><b>${esc(x)}</b></div>`).join('') : '<div class="small muted">Nothing to credit yet — this fills in as steps from meetings get closed as tasks.</div>'}</div>
      <div class="card" style="margin-top:10px"><div class="hd"><h3>What Is Not</h3></div>${notWorking.length ? notWorking.map(x => `<div class="st-item late"><b>${esc(x)}</b></div>`).join('') : '<div class="small muted">Nothing repeating, nothing late.</div>'}</div>
      <div class="card" style="margin-top:10px"><div class="hd"><h3>Bottlenecks</h3><span class="small muted">who the team waits on</span></div>${waits.length ? waits.map(([w, n]) => `<div class="st-item"><span class="k">${n}× across meetings</span><b>Waiting on ${esc(w)}</b></div>`).join('') : '<div class="small muted">No one outside the team is named as a wait.</div>'}${L.carried.length ? `<div class="hd" style="margin-top:8px"><h3>Carried From Meeting to Meeting</h3></div>${L.carried.map(c => `<div class="st-item late"><span class="k">${c.times}× · ${esc(c.owner || 'unassigned')} · since ${fmtL(c.first)}</span><b>${esc(c.title)}</b><span class="small muted">${esc(c.meetings.slice(0, 3).join(' · '))}</span></div>`).join('')}` : ''}</div>
    </div>
    <div>
      <div class="card"><div class="hd"><h3>Why Things Take Longer Than Estimated</h3><span class="small muted">the reasons the notes give</span></div>${L.why.length ? L.why.map(([k, v]) => `<div class="st-item"><span class="k">${v.n} mention${v.n === 1 ? '' : 's'}</span><b>${esc(k[0].toUpperCase() + k.slice(1))}</b>${v.quotes.map(q => `<span class="small muted">“${esc(q.t)}” — ${esc(q.m)}</span>`).join('')}</div>`).join('') : '<div class="small muted">The notes do not yet say why anything slipped.</div>'}</div>
      <div class="card" style="margin-top:10px"><div class="hd"><h3>What Gets Talked About</h3></div>${topics.map(([t, n]) => `<div class="row" style="justify-content:space-between"><span>${esc(t)}</span><span class="small muted">${n}×</span></div>`).join('') || '<div class="small muted">—</div>'}</div>
      <div class="card" style="margin-top:10px"><div class="hd"><h3>The Assistant's Read</h3><span class="grow"></span><button class="btn sm" id="mt-ai">${DB.company.meetRead ? 'Read Them Again' : 'Read the Meetings'}</button></div><div class="small" id="mt-ai-out">${DB.company.meetRead ? esc(DB.company.meetRead.text).replace(/\n/g, '<br>') + `<div class="muted" style="margin-top:4px">read ${fmtL(DB.company.meetRead.at)} across ${DB.company.meetRead.n} meetings</div>` : '<span class="muted">With the assistant connected, it reads every meeting — summaries, decisions, details, transcripts — and writes what is working, what is not, the bottlenecks, why things ran long, and what to change.</span>'}</div></div>
      <div class="card" style="margin-top:10px"><div class="hd"><h3>Solutions</h3><span class="grow"></span><button class="btn sm primary" id="mt-draft">Draft the Changes</button></div><div class="small muted">Each lesson becomes a change to the ERP — a buffer, a rule, a screen — drafted under Changes and live only when the owner approves it.</div>${(DB.changes || []).filter(c => c.status !== 'declined').slice(0, 5).map(c => `<div class="st-item"><span class="k">${esc(MT_STATUS[c.status] || c.status)}</span><b>${esc(c.title)}</b></div>`).join('')}</div>
    </div></div>`; }
function mtChangesHtml(){ const C = (DB.changes || []).slice().sort((a, b) => ({draft:0, approved:1, live:2, declined:3}[a.status] - {draft:0, approved:1, live:2, declined:3}[b.status]) || (b.at || '').localeCompare(a.at || '')); const owner = role() === 'owner';
  return `<div class="row" style="margin-bottom:10px"><span class="small muted">Changes the ERP drafted from what the meetings taught it. Nothing here touches the app until the owner approves it and publishes.</span></div>${C.length ? C.map(c => `<div class="card mt-ch ${c.status}" style="margin-bottom:10px"><div class="row" style="align-items:flex-start;gap:12px"><div class="grow"><div class="row" style="gap:8px;align-items:center"><span class="pill ${c.status === 'live' ? 'ok' : c.status === 'draft' ? 'warn' : c.status === 'declined' ? 'neutral' : 'info'}">${esc(MT_STATUS[c.status] || c.status)}</span><b>${esc(c.title)}</b><span class="small muted">${c.kind === 'code' ? 'needs a build' : c.kind === 'setting' ? 'a setting' : 'a rule'} · drafted ${fmtL(c.at)}</span></div><p class="small" style="margin:6px 0">${esc(c.why)}</p>${c.delta && c.delta.label ? `<div class="small"><b>${esc(c.delta.label)}</b>: ${esc(String(c.delta.from))} → <b>${esc(String(c.delta.to))}</b></div>` : ''}${(c.evidence || []).length ? `<div class="small muted" style="margin-top:4px">${c.evidence.map(e => `“${esc(e.t)}${e.t.length >= 160 ? '…' : ''}”${e.m ? ' — ' + esc(e.m) : ''}`).join('<br>')}</div>` : ''}${c.approvedBy ? `<div class="small ok" style="margin-top:4px">${c.status === 'live' ? 'Published' : 'Approved'} by ${esc(c.approvedBy)} ${fmtL(c.approvedAt)}</div>` : ''}</div><div class="acts" style="flex-direction:column;gap:6px">${c.status === 'draft' && owner ? `<button class="btn sm primary" data-chok="${c.id}">${c.kind === 'code' ? 'Approve the Build' : 'Approve and Publish'}</button><button class="btn sm ghost" data-chno="${c.id}">Decline</button>` : ''}${c.status === 'draft' && !owner ? '<span class="small muted">Waiting on the owner</span>' : ''}${c.status === 'approved' && c.kind === 'code' ? '<span class="small muted">Queued for the next build</span>' : ''}</div></div></div>`).join('') : '<div class="empty">No changes drafted yet. Read a few meetings, then draft the changes under What We Are Learning.</div>'}`; }
function mtSettingsHtml(){ const a = DB.company.meetAuto || {}; const rows = [['log', 'Log the meeting on the project'], ['note', 'Note on the client record'], ['task', 'Tasks from next steps'], ['update', 'Updates to tasks that already exist'], ['event', 'Follow-up meetings'], ['decision', 'Decisions on the decision log'], ['eta', 'Material dates'], ['rule', 'Rules the team sets for itself']];
  return `<div class="card"><div class="hd"><h3>What Applies Without Asking</h3><span class="small muted">everything else waits for an approval on the meeting</span></div>${rows.map(([k, n]) => `<label class="row" style="gap:10px;padding:6px 0"><input type="checkbox" data-mtauto="${k}" ${a[k] ? 'checked' : ''} ${mtCanApprove() ? '' : 'disabled'}><span>${n}</span></label>`).join('')}<div class="small muted" style="margin-top:8px">Propose by default; let a kind apply on its own once its proposals have earned it. Tasks and decisions carry the meeting as their source either way.</div></div>
    <div class="card" style="margin-top:10px"><div class="hd"><h3>How the Notes Get Here</h3></div><div class="small">In Google Meet, turn on <b>Take notes for me</b> and set <b>Send notes to: All invited guests</b> (the default, invited guests in your organization, keeps client meetings out of the record). The email from Gemini lands in the Inbox and is read here; the full notes Doc — decisions, details with timestamps, the transcript — is read when it is pasted, or fetched by the hosted app when Drive access is connected.</div></div>`; }
function mtWire(host){
  host.querySelectorAll('[data-mttab]').forEach(b => b.onclick = () => { mtTab = b.dataset.mttab; mtOpen = ''; render(); });
  host.querySelectorAll('[data-mtback]').forEach(a => a.onclick = e => { e.preventDefault(); mtOpen = ''; render(); });
  host.querySelectorAll('[data-mt]').forEach(sp => { const tr = sp.closest('tr'); if (!tr) return; tr.classList.add('click'); tr.onclick = () => { mtOpen = sp.dataset.mt; render(); }; });
  const scan = host.querySelector('#mt-scan'); if (scan) scan.onclick = () => { const n = mtScan(); save(); toast(n ? `${n} meeting${n === 1 ? '' : 's'} read from the Inbox` : 'Nothing new in the Inbox'); render(); };
  const paste = host.querySelector('#mt-paste'); if (paste) paste.onclick = () => mbModal('Paste Meeting Notes', `<div class="f"><label>Title</label><input data-f="title" placeholder="121 State St — schedule review"></div><div class="f"><label>Date</label><input type="date" data-f="date" value="${today()}"></div><div class="f"><label>The notes (the email, or the whole Doc)</label><textarea data-f="text" rows="10" placeholder="Paste the Gemini email or the notes Doc"></textarea></div>`, {submit:'Read', onSubmit:v => { if (!v.text) return false; const fake = {id:uid('cm'), msgId:'paste:' + uid('x'), subject:`Notes: “${v.title || 'Meeting'}” ${fmtL(v.date)}`, date:v.date, text:v.text, links:[]}; let m = mtIngest(fake); if (!m){ m = Object.assign({id:uid('mt'), source:'paste', msgId:fake.msgId, projectId:'', clientId:'', status:'new', createdAt:today(), proposals:[]}, mtParseEmail(fake)); m.title = v.title || m.title; m.date = v.date; DB.meetings.push(m); } if (/#\s*\**[^\n]*(Notes|Transcript)/i.test(v.text) || /###?\s*\**Decisions/i.test(v.text)){ mtParseDoc(v.text, m); const p = mtMatchProject(m); if (p && !m.projectId){ m.projectId = p.id; const c = mtMatchClient(m, p); if (c) m.clientId = c.id; } mtReplay(m); } save(); mtOpen = m.id; render(); }});
  host.querySelectorAll('[data-mtauto]').forEach(cb => cb.onchange = () => { DB.company.meetAuto[cb.dataset.mtauto] = cb.checked; save(); });
  const aiBtn = host.querySelector('#mt-ai'); if (aiBtn) aiBtn.onclick = async () => { if (typeof ai !== 'function'){ toast('The assistant is not connected'); return; } aiBtn.disabled = true; aiBtn.textContent = 'Reading…'; const M = DB.meetings.slice().sort((a, b) => (a.date || '').localeCompare(b.date || '')); const corpus = M.map(m => `## ${m.title} — ${m.date}${m.projectId ? ' — ' + ((DB.projects.find(p => p.id === m.projectId) || {project:{name:''}}).project.name) : ''}\nSummary: ${m.summary}\n${(m.sections || []).map(s => s.h + ': ' + s.text).join('\n')}\nDecisions: ${(m.decisions || []).map(d => `[${d.status}] ${d.text}`).join(' | ') || '—'}\nNext steps: ${(m.steps || []).map(s => `[${s.owner}] ${s.title}: ${s.detail}`).join(' | ')}\nDetails: ${(m.details || []).map(d => d.h + ': ' + d.text).join(' | ') || '—'}${m.transcript ? '\nTranscript (excerpt): ' + m.transcript.slice(0, 6000) : ''}`).join('\n\n').slice(0, 60000); const prompt = `You are the operations lead of a New York design-build firm reading ${M.length} meeting notes taken by Google Meet. Today is ${today()}. Write, in plain prose with short headed paragraphs and no bullet lists: What is working and why. What is not working and why. Bottlenecks (people, vendors, decisions the team keeps waiting on). Why things are taking longer than estimated — name the causes with the evidence from the notes. Then Solutions: five concrete changes to how the team works or to the ERP that would improve productivity and forecasting, each with the reason. Under 450 words. Do not invent facts that are not in the notes.\n\n${corpus}`; try { const out = await ai(prompt, 1500); if (!out || /^__ERR/.test(out)) throw new Error(out || 'no answer'); DB.company.meetRead = {text:out, at:today(), n:M.length}; save(); render(); } catch(e){ toast('The assistant could not read the meetings right now'); aiBtn.disabled = false; aiBtn.textContent = 'Read All the Meetings'; } };
  const draft = host.querySelector('#mt-draft'); if (draft) draft.onclick = () => { const d = mtDraftChanges(mtLearn()); save(); toast(d.length ? `${d.length} change${d.length === 1 ? '' : 's'} drafted` : 'Nothing new to draft'); mtTab = 'changes'; render(); };
  host.querySelectorAll('[data-chok]').forEach(b => b.onclick = () => { const c = DB.changes.find(x => x.id === b.dataset.chok); if (!c) return; const by = (currentUser() || {}).name || 'Owner'; if (c.kind === 'code'){ c.status = 'approved'; } else { mtChangeApply(c); c.status = 'live'; } c.approvedBy = by; c.approvedAt = today(); log(`Change ${c.status}: ${c.title}`, 'change', by); save(); toast(c.status === 'live' ? 'Published' : 'Approved for the next build'); render(); });
  host.querySelectorAll('[data-chno]').forEach(b => b.onclick = () => { const c = DB.changes.find(x => x.id === b.dataset.chno); if (c){ c.status = 'declined'; save(); render(); } });
  const m = mtOpen ? DB.meetings.find(x => x.id === mtOpen) : null; if (!m) return;
  host.querySelectorAll('[data-mtok]').forEach(b => b.onclick = () => { const pr = m.proposals.find(x => x.id === b.dataset.mtok); if (pr){ mtApply(m, pr); save(); toast('Applied'); render(); } });
  host.querySelectorAll('[data-mtskip]').forEach(b => b.onclick = () => { const pr = m.proposals.find(x => x.id === b.dataset.mtskip); if (pr){ pr.status = 'skipped'; save(); render(); } });
  host.querySelectorAll('[data-mtedit]').forEach(b => b.onclick = () => { const pr = m.proposals.find(x => x.id === b.dataset.mtedit); if (!pr) return; const A = pr.apply; const people = ['', ...mtStaff()];
    if (pr.kind === 'decision'){ mbModal('Edit the Decision', `<div class="f"><label>Decision</label><input data-f="name" value="${esc(A.name || '')}"></div><div class="f"><label>What was decided</label><textarea data-f="note" rows="3">${esc(A.note || '')}</textarea></div><div class="f2"><div class="f"><label>Status</label><select data-f="made"><option value="1" ${A.made ? 'selected' : ''}>Decided</option><option value="0" ${!A.made ? 'selected' : ''}>Still open</option></select></div><div class="f"><label>Due, if open</label><input type="date" data-f="due" value="${A.due || ''}"></div></div>`, {submit:'Approve', onSubmit:v => { if (!v.name) return false; A.name = v.name; A.note = v.note; A.made = v.made === '1'; A.due = v.due; pr.title = A.made ? `Record the decision: ${v.name}` : `Open decision: ${v.name}`; pr.detail = v.note; mtApply(m, pr); save(); toast('Applied'); render(); }}); return; }
    const cur = A.assignee || A.owner || ''; mbModal('Edit Before Approving', `<div class="f"><label>${pr.kind === 'event' ? 'Meeting' : 'Task'}</label><input data-f="title" value="${esc(A.title || pr.title)}"></div><div class="f2"><div class="f"><label>For</label><select data-f="assignee">${people.map(n => `<option value="${esc(n)}" ${n === cur ? 'selected' : ''}>${n ? esc(n) : 'Unassigned'}</option>`).join('')}</select></div><div class="f"><label>Due</label><input type="date" data-f="due" value="${A.due || ''}"></div></div>${pr.kind === 'event' ? `<div class="f"><label>Time</label><input type="time" data-f="time" value="${A.time || ''}"></div>` : ''}<div class="f"><label>Project</label><select data-f="projectId">${DB.projects.map(x => `<option value="${x.id}" ${x.id === A.projectId ? 'selected' : ''}>${esc(x.project.name)}</option>`).join('')}</select></div><div class="f"><label>Notes</label><textarea data-f="notes" rows="3">${esc(A.notes || A.note || '')}</textarea></div>`, {submit:'Approve', onSubmit:v => { if (!v.title) return false; A.title = v.title; A.assignee = v.assignee; A.owner = v.assignee; A.due = v.due; if (v.time !== undefined) A.time = v.time; A.projectId = v.projectId; A.notes = v.notes; A.note = v.notes; pr.title = `${v.title} → ${v.assignee || 'Unassigned'}`; pr.noDate = !v.due; mtApply(m, pr); save(); toast('Applied'); render(); }}); });
  host.querySelectorAll('[data-mtmail]').forEach(a => a.onclick = e => { e.preventDefault(); const c = (DB.comms || []).find(x => x.id === m.commId); if (!c) return; if (typeof cmOpen !== 'undefined'){ cmOpen = c.id; cmFilter = 'all'; } view = 'comms'; render(); });
  const all = host.querySelector('#mt-okall'); if (all) all.onclick = () => { m.proposals.filter(x => x.status === 'proposed').forEach(pr => mtApply(m, pr)); save(); toast('All applied'); render(); };
  const redo = host.querySelector('#mt-redo'); if (redo) redo.onclick = () => { mtReplay(m); save(); render(); };
  const ps = host.querySelector('#mt-proj'); if (ps) ps.onchange = () => { m.projectId = ps.value; const p = DB.projects.find(x => x.id === ps.value); const c = p ? mtMatchClient(m, p) : null; if (c) m.clientId = c.id; mtReplay(m); save(); render(); };
  const cs = host.querySelector('#mt-client'); if (cs) cs.onchange = () => { m.clientId = cs.value; mtReplay(m); save(); render(); };
  const doc = host.querySelector('#mt-doc'); if (doc) doc.onclick = () => mbModal('Paste the Notes Doc', `<div class="small muted" style="margin-bottom:8px">Open the Doc from the email, select all, copy, paste here. Decisions, details with timestamps and the transcript are read from it.</div><div class="f"><textarea data-f="text" rows="12"></textarea></div>`, {submit:'Read the Doc', onSubmit:v => { if (!v.text) return false; mtParseDoc(v.text, m); mtReplay(m); save(); toast('Notes Doc read'); render(); }});
  const fetchDoc = host.querySelector('#mt-fetch'); if (fetchDoc) fetchDoc.onclick = async () => { const id = (m.docUrl.match(/\/d\/([A-Za-z0-9_-]+)/) || [])[1]; if (!id) return; fetchDoc.disabled = true; fetchDoc.textContent = 'Fetching…'; try { const base = (window.SDP_CONFIG && window.SDP_CONFIG.aiUrl || '/api/ai').replace(/\/ai$/, ''); const r = await (typeof bnFetch === 'function' ? bnFetch : fetch)(`${base}/meeting-doc?id=${encodeURIComponent(id)}`); const j = await r.json(); if (!r.ok || !j.text) throw new Error(j.error || 'no text'); mtParseDoc(j.text, m); mtReplay(m); save(); toast('Notes Doc read'); render(); } catch(e){ toast('Could not fetch the Doc — paste it instead'); fetchDoc.disabled = false; fetchDoc.textContent = 'Fetch the Notes Doc'; } };
  const deep = host.querySelector('#mt-deep'); if (deep) deep.onclick = () => { const p = DB.projects.find(x => x.id === m.projectId); if (!p) return; setCurrent(p.id); openAI('meeting'); setTimeout(() => { const ta = document.getElementById('mt-text'); const ti = document.getElementById('mt-title'); const dt = document.getElementById('mt-date'); if (ta) ta.value = m.transcript || [m.summary, ...(m.sections || []).map(s => s.h + '\n' + s.text), 'Next steps:', ...(m.steps || []).map(s => `[${s.owner}] ${s.title}: ${s.detail}`)].join('\n\n'); if (ti) ti.value = m.title; if (dt) dt.value = m.date; }, 50); };
}

