/* summaries from the notes */
function lsFill(t, m){ const p = m.projectId ? DB.projects.find(x => x.id === m.projectId) : null; const c = m.clientId ? DB.clients.find(x => x.id === m.clientId) : (p ? DB.clients.find(x => x.id === p.clientId) : null); const steps = (m.steps || []).map(s => `• ${s.title}${s.detail ? ' — ' + s.detail : ''}${s.owner ? ` (${lsStaffName(s.owner) || s.owner})` : ''}`).join('\n') || '• (none recorded)'; const decs = (m.decisions || []).map(d => `• ${d.name ? d.name + ': ' : ''}${d.text}${d.status && d.status !== 'aligned' ? ' — still open' : ''}`).join('\n') || '• (none recorded)'; const waiting = (m.steps || []).filter(s => lsOutside(s.owner)).map(s => `• ${s.owner}: ${s.title}`).join('\n') || '• (nobody outside the team)'; const scope = (m.sections || []).filter(x => /scope|out of scope|not (in|part of) the (proposal|contract)|additional/i.test(x.h + ' ' + x.text)).map(x => `• ${x.h}`).join('\n') || '• (nothing raised)';
  return t.replace(/\{client\}/g, lsFirstName(c)).replace(/\{title\}/g, m.title || '').replace(/\{date\}/g, fmtL(m.date)).replace(/\{project\}/g, p ? p.project.name : '').replace(/\{summary\}/g, m.summary || '').replace(/\{steps\}/g, steps).replace(/\{decisions\}/g, decs).replace(/\{waiting\}/g, waiting).replace(/\{scope\}/g, scope).replace(/\{signature\}/g, (typeof currentUser === 'function' && currentUser() || {}).name || (DB.company || {}).name || 'SmartDesign'); }
function lsSummaryModal(m, kind){ const T = (DB.company.meetTemplates || {})[kind] || ''; const text = lsFill(T, m); mbModal(kind === 'client' ? 'Client summary — for your approval before it goes' : 'Internal summary', `<div class="f"><textarea data-f="text" rows="18" style="font-family:inherit">${esc(text)}</textarea></div><div class="small muted">${kind === 'client' ? 'The rule: drafted within two hours of the meeting, approved by the owner, then sent. Edit here, then copy.' : 'For the team channel or the project log.'}</div>`, {submit:'Copy', onSubmit: v => { try { navigator.clipboard && navigator.clipboard.writeText(v.text); } catch(e){} m.summaries = m.summaries || {}; m.summaries[kind] = {text:v.text, at:today(), by:(typeof currentUser === 'function' && currentUser() || {}).name || ''}; save(); toast('Copied'); }}); }
if (typeof mtMeetingHtml === 'function'){ const mtMeetingHtmlBase_ls = mtMeetingHtml; mtMeetingHtml = function(m){ let h = mtMeetingHtmlBase_ls.apply(this, arguments); try { if (m.projectId){ h = h.replace('<button class="btn sm" id="mt-doc">', `<button class="btn sm" data-lssum="client">Draft the Client Summary</button><button class="btn sm" data-lssum="internal">Internal Summary</button><button class="btn sm" id="mt-doc">`); const docs = lsDocsHtml(m); if (docs) h = h.replace('<div class="grid2">', docs + '<div class="grid2">'); (m.proposals || []).filter(x => x.kind === 'waiting' && x.status === 'proposed').forEach(x => { h = h.replace(`<button class="btn sm primary" data-mtok="${x.id}">Approve</button>`, `<button class="btn sm primary" data-mtok="${x.id}">Approve</button><button class="btn sm" data-lswedit="${x.id}">Edit</button>`); }); } } catch(e){ console.error('lessons meeting', e); } return h; }; }
