/* ---------- F: a finish or fixture decision needs a sample seen on site ---------- */
const LS_FINISH_RE = /\b(paint|colou?r|tile|stone|marble|finish|fixture|stain|fabric|hardware|light(ing)?|faucet|vanity|counter(top)?|floor(ing)?|wood|grout|wallpaper|cabinet|sconce|knob|pull|door|window|sink|tub|shower|molding|moulding|trim|sample)\b/i;
function lsNeedsSample(d){ if (!(DB.company || {}).sampleGate) return false; if (d.sample) return false; return d.kind === 'design' || LS_FINISH_RE.test(d.name || ''); }
document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('[data-decided]'); if (!b || !S) return; const d = S.decisions.find(x => x.id === b.dataset.decided); if (!d || !lsNeedsSample(d)) return; e.preventDefault(); e.stopImmediatePropagation(); lsSampleModal(d, () => b.click()); }, true);
function lsSampleModal(d, then){ const by = (typeof currentUser === 'function' && currentUser() || {}).name || ''; const owner = typeof isOwner === 'function' ? isOwner() : (typeof role === 'function' && role() === 'owner');
  mbModal(`Seen on site? — ${esc(d.name)}`, `<div class="small" style="margin-bottom:8px">A finish or fixture is not decided until the sample has been seen on site. Add the photo, or record who saw it and when.</div><div class="f"><label>Photo of the sample on site</label><input type="file" accept="image/*" capture="environment" id="ls-sample-file"></div><div class="f2"><div class="f"><label>Seen by</label><input data-f="by" value="${esc(by)}"></div><div class="f"><label>On</label><input type="date" data-f="on" value="${today()}"></div></div><div class="f"><label>Where</label><input data-f="where" placeholder="2nd floor bath, on the wall next to the window"></div>${owner ? '<button class="btn sm ghost" id="ls-sample-skip">Mark Decided Without a Sample (Owner)</button>' : '<div class="small muted">Only the owner can mark a finish decided without a sample.</div>'}`, {submit:'Sample Seen — Mark Decided', onSubmit: v => { const f = document.getElementById('ls-sample-file'); const done = photo => { d.sample = {photo:photo || '', by:v.by, on:v.on, where:v.where}; log(`Sample seen on site for "${d.name}" by ${v.by}${v.where ? ' — ' + v.where : ''}`, 'manual'); save(); then && then(); }; if (f && f.files && f.files[0] && f.files[0].size < 2.5e6){ const r = new FileReader(); r.onload = () => done(r.result); r.readAsDataURL(f.files[0]); return; } if (!(f && f.files && f.files[0]) && !(v.by && v.where)){ toast('A photo of the sample, or who saw it and where'); return false; } done(''); }});
  const sk = document.getElementById('ls-sample-skip'); if (sk) sk.onclick = () => { d.sample = {override:true, by, on:today()}; log(`"${d.name}" marked decided without a sample — owner override by ${by}`, 'manual'); save(); mbCloseModal(); then && then(); }; }

/* ---------- G: buy board sorts; vendor lead time; delivery window and cutoff on the PO ---------- */
let lsBuySort = '';
function lsVendorLead(name){ if (!name) return 0; const v = (DB.vendors || []).find(x => x.name.toLowerCase() === String(name).toLowerCase()); return v ? (+v.leadDays || 0) : 0; }
if (typeof buyList === 'function'){ const buyListBase_ls = buyList; buyList = function(scope){ const rows = buyListBase_ls.apply(this, arguments); const td = today();
  rows.forEach(r => { if (r.kind !== 'material' || r.lead || r.ordered || !r.needBy) return; const lead = lsVendorLead(r.vendor); if (!lead) return; r.lead = lead; r.leadFrom = 'vendor'; withProject(r.p, () => { r.orderBy = addWork(r.needBy, -lead, false); }); if (!r.dec){ if (r.orderBy < td){ r.sev = 3; r.why = `order-by ${fmt(r.orderBy)} passed`; } else if (wd(td, r.orderBy) <= 5 && r.sev < 2){ r.sev = 2; r.why = `order by ${fmt(r.orderBy)}`; } } });
  if (lsBuySort){ const k = lsBuySort.replace(/^-/, ''), dir = lsBuySort[0] === '-' ? -1 : 1; const val = r => k === 'lead' ? (r.lead || 0) : k === 'vendor' ? (r.vendor || '') : (r[k] || '9999-99-99'); rows.sort((a, b) => { const x = val(a), y = val(b); return (typeof x === 'number' ? x - y : String(x).localeCompare(String(y))) * dir; }); }
  return rows; }; }
if (typeof renderBuyBoard === 'function'){ const renderBuyBoardBase_ls = renderBuyBoard; renderBuyBoard = function(){ renderBuyBoardBase_ls.apply(this, arguments); const host = document.getElementById('buy-board'); if (!host) return; const map = {'Order by':'orderBy', 'On site by':'needBy', 'Lead':'lead', 'Vendor':'vendor'};
  host.querySelectorAll('table.buy-t thead th').forEach(th => { const k = map[th.textContent.trim()]; if (!k) return; th.classList.add('ls-sort'); const on = lsBuySort.replace(/^-/, '') === k; if (on) th.innerHTML = `${esc(th.textContent)} <span class="ls-arrow">${lsBuySort[0] === '-' ? '↓' : '↑'}</span>`; th.title = 'Sort'; th.onclick = () => { lsBuySort = lsBuySort === k ? '-' + k : lsBuySort === '-' + k ? '' : k; render(); }; });
  host.querySelectorAll('tr.buy-row').forEach(tr => { const cell = tr.children[5]; if (cell && cell.textContent.trim() === '—') cell.innerHTML = '<span class="pill warn" title="No lead time on the item or the vendor — the order-by date cannot be computed">no lead</span>'; });
  const p = host.querySelector('p.small.muted'); if (p && !/vendor's lead/.test(p.textContent)) p.textContent += ` An item with no lead time takes its vendor's lead days (Vendors › Lead days). Click ${[...host.querySelectorAll('th.ls-sort')].map(t => t.textContent.replace(/[↑↓]/g, '').trim()).join(', ').replace(/, ([^,]*)$/, ' or $1')} to sort.`; }; }
/* vendor: lead days */
if (typeof openVendor === 'function'){ const openVendorBase_ls = openVendor; openVendor = function(id){ openVendorBase_ls.apply(this, arguments); const v = id ? DB.vendors.find(x => x.id === id) : {}; const body = document.getElementById('d-body'); const trade = body && body.querySelector('#e-trade'); if (!trade || body.querySelector('#e-lead')) return; const row = trade.closest('.f2'); const div = document.createElement('div'); div.className = 'f2'; div.innerHTML = `<div class="f"><label>Lead days</label><input id="e-lead" type="number" min="0" value="${+v.leadDays || 0}"><span class="hint">Used for any item from this vendor with no lead time of its own.</span></div><div class="f"><label>Delivery window</label><input id="e-window" value="${esc(v.deliveryWindow || '')}" placeholder="8:00 AM – 3:00 PM, no Fridays"></div>`; row.after(div); const collect = editing.collect; editing.collect = () => Object.assign(collect(), {leadDays:+document.getElementById('e-lead').value || 0, deliveryWindow:document.getElementById('e-window').value.trim()}); }; }
/* PO: delivery window and site cutoff, printed on the document the vendor gets */
function lsPoWin(po){ const v = (DB.vendors || []).find(x => x.name.toLowerCase() === String(po.vendor || '').toLowerCase()); const hrs = S && typeof siteHours === 'function' ? siteHours() : null; return {win: po.deliveryWindow || (v && v.deliveryWindow) || '', cutoff: po.siteCutoff || (hrs ? hrs.end : '')}; }
if (typeof renderPODoc === 'function'){ const renderPODocBase_ls = renderPODoc; renderPODoc = function(po){ let h = renderPODocBase_ls.apply(this, arguments); try { const {win, cutoff} = lsPoWin(po); const i = h.indexOf('data-p="shipTo"'); if (i < 0) return h; const j = h.indexOf('</div>', i); if (j < 0) return h; const k = j + 6; h = h.slice(0, k) + `<div class="f"><label>Delivery window · site cutoff</label><div class="row" style="gap:6px"><input data-lsp="deliveryWindow" value="${esc(win)}" placeholder="8:00 AM – 3:00 PM" style="flex:1"><input data-lsp="siteCutoff" type="time" value="${esc(cutoff)}" title="Last time a delivery can be received on site"></div></div>` + h.slice(k); } catch(e){ console.error('lessons po', e); } return h; }; }
if (typeof wirePODoc === 'function'){ const wirePODocBase_ls = wirePODoc; wirePODoc = function(po){ wirePODocBase_ls.apply(this, arguments); document.querySelectorAll('#po-doc [data-lsp]').forEach(i => i.onchange = () => { po[i.dataset.lsp] = i.value; const {win, cutoff} = lsPoWin(po); const line = `Deliver ${win ? 'within ' + win : 'during site hours'}; nothing received after ${cutoff ? cutoff.replace(/^(\d{2}):(\d{2})$/, (a, h, mm) => `${(+h % 12) || 12}:${mm} ${+h >= 12 ? 'PM' : 'AM'}`) : 'the site cutoff'}. Call the site before dispatch.`; const kept = String(po.notes || '').split('\n').filter(l => !/^Deliver .*Call the site before dispatch\.$/.test(l.trim())); po.notes = [...kept, line].filter(Boolean).join('\n'); const n = document.querySelector('#po-doc [data-p="notes"]'); if (n) n.value = po.notes; save(); }); }; }

/* ---------- H: two numbers on the project band ---------- */
function lsUnbilled(p){ try { const w = wipRow(p); return {under:+w.under || 0, pending:+w.pending || 0}; } catch(e){ return {under:0, pending:0}; } }
if (typeof tbBand === 'function'){ const tbBandBase_ls = tbBand; tbBand = function(){ tbBandBase_ls.apply(this, arguments); const band = document.getElementById('projhdr'); if (!band || band.hidden || !S) return; const chip = (k, v, s, tone) => `<span class="pj-chip ls-chip ${tone || ''}"><span class="k">${esc(k)}</span><b>${esc(v)}</b>${s ? `<small>${esc(s)}</small>` : ''}</span>`; let extra = '';
  if (lsIsDesign(S)){ const s = lsScope(S); extra += chip('Scope', s.status === 'confirmed' ? 'Confirmed' : s.status === 'sent' ? 'Sent' : 'Not Sent', s.status === 'confirmed' ? fmtL(s.confirmedOn) : s.status === 'sent' ? `${fmtL(s.sentOn)} · awaiting the client` : 'design hours running on a conversation', s.status === 'confirmed' ? '' : s.status === 'sent' ? 'warn' : 'bad'); }
  const W = lsWaitRows(S); const days = W.reduce((a, r) => a + r.days, 0); const late = W.filter(r => r.late).length; if (W.length){ const who = [...new Set(W.map(r => r.who))]; extra += chip('Waiting', `${days}d`, `on ${who.slice(0, 2).join(', ')}${who.length > 2 ? ` +${who.length - 2}` : ''}${late ? ` · ${late} past escalation` : ''}`, late ? 'bad' : 'warn'); }
  const U = lsUnbilled(S); const K = v => typeof moneyK === 'function' ? moneyK(v) : money(v); if (U.under > 0) extra += chip('Unbilled', K(U.under), `earned, not yet invoiced${U.pending > 0 ? ` · ${K(U.pending)} in COs awaiting approval` : ''}`, 'warn'); else if (U.pending > 0) extra += chip('Pending COs', K(U.pending), 'change orders awaiting the client', '');
  if (extra) band.insertAdjacentHTML('beforeend', extra); }; }

/* ---------- J: the daily review on Spend ---------- */
function lsReviewItems(){ const items = []; const td = today(); const push = (key, n, label, go, amt) => items.push({key, n, label, go, amt});
  try { const o = spOrphans(); push('orph', o.length, 'bank lines with no receipt, bill or payroll behind them', () => { spTab = 'match'; }, o.reduce((a, t) => a + Math.abs(+t.amt || +t.amount || 0), 0)); } catch(e){}
  try { const q = spAll().filter(s => s.status === 'submitted'); push('appr', q.length, 'receipts waiting for approval', () => { spTab = 'approve'; }, q.reduce((a, s) => a + (+s.total || +s.amount || 0), 0)); } catch(e){}
  try { const u = spAll().filter(s => !['rejected','void'].includes(s.status) && (!s.projectId || !s.line)); push('uncost', u.length, 'receipts with no project or estimate line', () => { spTab = 'all'; }, 0); } catch(e){}
  try { const c = typeof cdUnassigned === 'function' ? cdUnassigned(30) : []; push('card', c.length, 'card charges in the last 30 days with no cardholder', () => { spTab = 'cards'; }, c.reduce((a, t) => a + Math.abs(+t.amt || 0), 0)); } catch(e){}
  try { const r = (DB.pos || []).filter(po => ['received','partial'].includes(po.status) && !(DB.bills || []).some(b => b.poId === po.id)); push('pobill', r.length, 'purchase orders received with no vendor bill yet', () => { view = 'bills'; }, 0); } catch(e){}
  try { const t = (DB.time || []).filter(e => e.status === 'submitted' && e.date <= td); push('time', t.length, 'hours submitted, not yet approved', () => { view = 'time'; }, 0); } catch(e){}
  return items; }
function lsReviewHtml(){ const td = today(); DB.company.spReview = DB.company.spReview || {}; const day = DB.company.spReview[td] || (DB.company.spReview[td] = {done:{}}); const items = lsReviewItems(); const open = items.filter(i => i.n && !day.done[i.key]).length; const by = (typeof currentUser === 'function' && currentUser() || {}).name || '';
  return `<div class="card ls-review"><div class="hd"><h3>Today's Review</h3><span class="small muted">${fmtL(td)} · ${open ? `${open} of ${items.length} still to look at` : 'all clear — every count is zero or checked'}</span><span class="grow"></span>${day.doneAt ? `<span class="small ok">Finished ${esc(day.doneAt)}${day.by ? ' by ' + esc(day.by) : ''}</span>` : `<button class="btn sm ${open ? '' : 'primary'}" id="ls-rev-done">Finish the Review</button>`}</div>
    ${items.map(i => `<label class="ls-rev-row ${i.n ? (day.done[i.key] ? 'checked' : 'open') : 'clear'}"><input type="checkbox" data-lsrev="${i.key}" ${day.done[i.key] || !i.n ? 'checked' : ''} ${!i.n ? 'disabled' : ''}><b>${i.n}</b><span>${esc(i.label)}${i.amt ? ` · ${money(i.amt)}` : ''}</span>${i.n ? `<a href="#" data-lsgo="${i.key}">Open ›</a>` : ''}</label>`).join('')}
    <div class="small muted" style="margin-top:6px">The order is the rule: the line with nothing behind it first, then what is waiting on you, then what cannot be costed. Check each once you have looked; the counts refresh on their own.</div></div>`; }
if (typeof renderSpend === 'function'){ const renderSpendBase_ls = renderSpend; renderSpend = function(){ renderSpendBase_ls.apply(this, arguments); const root = document.getElementById('spend-body') || document.getElementById('vf-body'); if (!root || root.querySelector('.ls-review')) return; if (!['owner','pm','coord','controller'].includes(typeof role === 'function' ? role() : 'owner')) return; const d = document.createElement('div'); d.innerHTML = lsReviewHtml(); const card = d.firstElementChild; const ph = root.querySelector('.ph'); const strip = root.querySelector('.tl-strip, [data-tlhost], .kpis'); if (strip && strip.parentElement === root) strip.after(card); else if (ph) ph.after(card); else root.prepend(card);
  const td = today(); const day = DB.company.spReview[td]; card.querySelectorAll('[data-lsrev]').forEach(c => c.onchange = () => { day.done[c.dataset.lsrev] = c.checked; save(); render(); }); card.querySelectorAll('[data-lsgo]').forEach(a => a.onclick = e => { e.preventDefault(); const it = lsReviewItems().find(x => x.key === a.dataset.lsgo); if (it){ it.go(); render(); } }); const fin = card.querySelector('#ls-rev-done'); if (fin) fin.onclick = () => { const left = lsReviewItems().filter(i => i.n && !day.done[i.key]); if (left.length && !confirm(`${left.length} item${left.length === 1 ? '' : 's'} not checked. Finish anyway?`)) return; day.doneAt = new Date().toTimeString().slice(0, 5); day.by = (typeof currentUser === 'function' && currentUser() || {}).name || ''; save(); render(); toast('Review finished'); }; }; }

/* ---------- the register: the Changes tab shows what was approved and built ---------- */
