/* ---------- nav: the assistant's screens are one group, Home is Home again ---------- */
(function pzNav(){ const VIEWS = ['meetings','brain','calendar','obligations']; const svg = '<path d="M4 4h16v16H4z"/><path d="M4 9h16M9 9v11"/>';
  const mk = () => ({id:'office', n:'Office', views:[...VIEWS]});
  if (typeof IA_GROUPS !== 'undefined'){ const h = IA_GROUPS.find(g => g.id === 'home'); if (h) h.views = h.views.filter(v => !VIEWS.includes(v)); if (!IA_GROUPS.some(g => g.id === 'office')) IA_GROUPS.splice(IA_GROUPS.findIndex(g => g.id === 'home') + 1, 0, mk()); if (typeof IA_ICON === 'object') IA_ICON.office = svg; }
  if (typeof NAV_GROUPS !== 'undefined'){ const h = NAV_GROUPS.find(g => g.id === 'home'); if (h) h.views = h.views.filter(v => !VIEWS.includes(v)); if (!NAV_GROUPS.some(g => g.id === 'office')) NAV_GROUPS.splice(NAV_GROUPS.findIndex(g => g.id === 'home') + 1, 0, mk()); if (typeof NAV_ICON === 'object') NAV_ICON.office = svg; } })();

