/*<<brain4.js>>*/
/* ---------- The Brain, part four (2026-09-14, v92) ----------
   Three things a real meeting needs. A team meeting talks about five projects: every paragraph and
   step is matched on its own, the meeting belongs to all of them, each project gets its own log entry
   and its own tasks, and what matches nothing gets a picker per paragraph. A sentence about unbilled
   work or a change order is two tasks — the PM starts the change order, the biller sends the invoice —
   with the document one click away. And when a meeting raises a topic that will move by email
   (insurance, a permit, a claim, a quote, a mold report), the ERP watches the inbox for it: matching
   mail is filed to the project, pinned to the meeting and the task that waits on it, and surfaced to
   whoever owns it. */

/* ---------- A. one meeting, several projects ---------- */
function b4MatchText(text){ if (typeof mtMatchProject !== 'function') return null; const p = mtMatchProject({title:'', summary:text, sections:[]}); if (p) return p; /* a number and a street name anywhere in the text: "206 Lenox", "121 State" */ const hay = mtNorm(text); return DB.projects.find(q => { const nm = q.project.name.match(/^(\d+)\s+([a-z]+)/i); return nm && new RegExp(`\\b${nm[1]}\\s+${mtNorm(nm[2])}\\b`).test(hay); }) || null; }
function b4Split(m){ const secs = m.sections || [], steps = m.steps || [], dets = m.details || []; const by = {}; const put = (pid, k, i) => { if (!pid) return; by[pid] = by[pid] || {id:pid, sections:[], steps:[], details:[]}; by[pid][k].push(i); };
  secs.forEach((s, i) => { const p = b4MatchText(`${s.h} ${s.text}`); if (p) put(p.id, 'sections', i); });
  steps.forEach((s, i) => { const p = b4MatchText(`${s.title} ${s.detail}`) || (() => { /* a step with no project of its own follows the paragraph that shares its words */ const w = new Set(mtWords(s.title + ' ' + s.detail)); let best = null, bn = 0; secs.forEach((x, j) => { const n = [...mtWords(x.h + ' ' + x.text)].filter(y => w.has(y)).length; if (n > bn){ bn = n; best = j; } }); if (best === null || bn < 2) return null; const owner = Object.values(by).find(b => b.sections.includes(best)); return owner ? {id:owner.id} : null; })(); if (p) put(p.id, 'steps', i); });
  dets.forEach((d, i) => { const p = b4MatchText(`${d.h} ${d.text}`); if (p) put(p.id, 'details', i); });
  const list = Object.values(by).sort((a, b) => (b.sections.length + b.steps.length) - (a.sections.length + a.steps.length));
  const unmatched = {sections:secs.map((s, i) => i).filter(i => !list.some(b => b.sections.includes(i))), steps:steps.map((s, i) => i).filter(i => !list.some(b => b.steps.includes(i)))};
  return {list, unmatched}; }
function b4Sub(m, part){ const p = DB.projects.find(x => x.id === part.id); const secs = part.sections.map(i => m.sections[i]); const steps = part.steps.map(i => m.steps[i]); const dets = part.details.map(i => m.details[i]);
  return Object.assign({}, m, {projectId:part.id, clientId:p ? p.clientId : m.clientId, summary:secs.length ? secs.map(s => `${s.h}: ${s.text}`).join(' ') : m.summary, sections:secs, steps, details:dets, decisions:(m.decisions || []).filter(d => { const q = b4MatchText(`${d.name || ''} ${d.text}`); return q ? q.id === part.id : part === (m.split || {}).primary; })}); }
