/* ---------- C. watches: the inbox is watched for what the meeting raised ---------- */
const B4_TOPICS = [['insurance', /\b(insurance|policy|insurer|carrier|adjuster|coverage|claim|binder|certificate of insurance|COI)\b/i], ['permit', /\b(permit|filing|DOB|LPC|expediter|meter number|inspection|inspector|violation)\b/i], ['quote', /\b(quote|quotation|proposal|estimate|bid|pricing)\b/i], ['mold', /\b(mold|remediation|clearance test|air quality)\b/i], ['delivery', /\b(delivery|ETA|lead time|ship date|back ?order)\b/i], ['design', /\b(drawings?|measurements?|design presentation|samples?|selections?)\b/i], ['legal', /\b(contract|agreement|closing|lawyer|attorney|neighbor claim|lien)\b/i]];
const B4_STOP = /^(the|and|for|with|from|that|this|have|will|been|were|they|them|their|about|into|after|before|which|would|could|should|there|where|when|what|also|just|need|needs|still|week|next|last|today|team|group|meeting|project|client|work|done|send|sent|call|email)$/;
function b4Init(){ DB.watches = DB.watches || []; }
function b4WatchFrom(m, text, projectId, extra){ b4Init(); const topic = (B4_TOPICS.find(([k, r]) => r.test(text)) || [])[0]; if (!topic) return null; const words = [...new Set(String(text).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 4 && !B4_STOP.test(w)))].slice(0, 12); const party = (text.match(/\b(?:from|with|by|to)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/) || [])[1] || ''; const key = `${projectId || ''}|${topic}|${party.toLowerCase()}`; if (DB.watches.some(w => w.key === key && w.status === 'open')) return DB.watches.find(w => w.key === key && w.status === 'open');
  const w = Object.assign({id:uid('wt'), key, topic, words, party, projectId:projectId || '', meetingId:m ? m.id : '', label:`${topic[0].toUpperCase() + topic.slice(1)}${party ? ' · ' + party : ''}`, text:String(text).slice(0, 160), owner:'', since:today(), until:iso(addDays(today(), 45)), hits:[], unread:0, status:'open', at:today()}, extra || {}); DB.watches.push(w); return w; }
function b4WatchesFromMeeting(m){ const out = []; const parts = m.split ? m.split.projects : [{id:m.projectId, sections:(m.sections || []).map((s, i) => i), steps:(m.steps || []).map((s, i) => i)}]; parts.forEach(part => { part.sections.forEach(i => { const s = m.sections[i]; if (!s) return; const w = b4WatchFrom(m, `${s.h}. ${s.text}`, part.id); if (w && !out.includes(w)) out.push(w); }); part.steps.forEach(i => { const s = m.steps[i]; if (!s) return; const w = b4WatchFrom(m, `${s.title}. ${s.detail}`, part.id, {owner:typeof mtPerson === 'function' && mtPerson(s.owner) || ''}); if (w && !out.includes(w)) out.push(w); }); }); return out; }
