if (typeof cmImport === 'function'){ const cmImportBase_b4 = cmImport; cmImport = function(list){ const r = cmImportBase_b4.apply(this, arguments); try { const n = b4Sweep(); if (n && typeof toast === 'function' && document.body.dataset.booted) toast(`${n} update${n === 1 ? '' : 's'} on what you are watching`); } catch(e){ console.error('brain4 sweep', e); } return r; }; }
if (typeof finishBoot === 'function'){ const finishBootBase_b4 = finishBoot; finishBoot = function(){ const r = finishBootBase_b4.apply(this, arguments); try { b4Init(); (DB.meetings || []).forEach(m => { if (!m.watches){ m.watches = b4WatchesFromMeeting(m).map(w => w.id); } }); b4Sweep(); save(); } catch(e){ console.error('brain4 boot', e); } return r; }; }
/* what a watch produced, on the meeting, on the task, on Today, and a tab on The Brain */
function b4Open(commId){ const c = (DB.comms || []).find(x => x.id === commId); if (!c) return; if (typeof cmOpen !== 'undefined'){ cmOpen = c.id; cmFilter = 'all'; } view = 'comms'; render(); }
function b4HitsHtml(ws, title){ const hits = ws.flatMap(w => w.hits.map(h => Object.assign({w}, h))).sort((a, b) => b.at.localeCompare(a.at)); if (!ws.length) return ''; return `<div class="card b4-watch" style="margin-top:10px"><div class="hd"><h3>${esc(title || 'Watching the Inbox')}</h3><span class="small muted">${ws.filter(w => w.status === 'open').length} open · ${hits.length} update${hits.length === 1 ? '' : 's'}</span></div><div class="row" style="gap:6px;flex-wrap:wrap;margin-bottom:6px">${ws.map(w => `<span class="pill ${w.status === 'open' ? (w.unread ? 'warn' : 'ok') : ''}" title="${esc(w.text)}">${esc(w.label)}${w.hits.length ? ' · ' + w.hits.length : ''}</span>`).join('')}</div>${hits.length ? hits.slice(0, 8).map(h => `<div class="b4-hit"><span class="k">${fmt(h.at)}</span><a href="#" data-b4open="${h.commId}"><b>${esc(h.subject || '(no subject)')}</b></a><span class="small muted">${esc(h.from)} · ${esc(h.w.label)}</span></div>`).join('') : '<div class="small muted">Nothing has come in yet. Matching mail is filed to the project and pinned here the moment it lands.</div>'}</div>`; }
if (typeof mtMeetingHtml === 'function'){ const mtMeetingHtmlBase_b4c = mtMeetingHtml; mtMeetingHtml = function(m){ let h = mtMeetingHtmlBase_b4c.apply(this, arguments); try { b4Init(); const ws = DB.watches.filter(w => w.meetingId === m.id); if (ws.length){ const card = b4HitsHtml(ws, 'Updates Since the Meeting'); h = h.replace('<div class="grid2">', card + '<div class="grid2">'); } } catch(e){} return h; }; }
if (typeof mtWire === 'function'){ const mtWireBase_b4c = mtWire; mtWire = function(host){ mtWireBase_b4c.apply(this, arguments); host.querySelectorAll('[data-b4open]').forEach(a => a.onclick = e => { e.preventDefault(); b4Open(a.dataset.b4open); }); }; }
if (typeof openActionEditor === 'function'){ const openActionEditorBase_b4c = openActionEditor; openActionEditor = function(id){ openActionEditorBase_b4c.apply(this, arguments); const a = id ? S.actions.find(x => x.id === id) : null; if (!a || !(a.updates || []).length) return; const body = document.getElementById('d-body'); if (!body || body.querySelector('#b4-upd')) return; const div = document.createElement('div'); div.className = 'note'; div.id = 'b4-upd'; div.style.margin = '8px 0'; div.innerHTML = `<b>${a.updates.length} update${a.updates.length === 1 ? '' : 's'} from the inbox</b>${a.updates.slice(-4).reverse().map(u => `<div class="small"><a href="#" data-b4open="${u.commId}">${esc(u.subject || '(no subject)')}</a> · ${fmt(u.at)}</div>`).join('')}`; const notes = body.querySelector('#e-notes'); (notes ? notes.closest('.f') : body).before(div); div.querySelectorAll('[data-b4open]').forEach(x => x.onclick = e => { e.preventDefault(); closeEditor(); b4Open(x.dataset.b4open); }); }; }
/* Today: the updates for whoever owns the item; The Brain: a Watching tab */
if (typeof renderHome === 'function'){ const renderHomeBase_b4 = renderHome; renderHome = function(){ renderHomeBase_b4.apply(this, arguments); try { b4Init(); const root = typeof homeRoot === 'function' ? homeRoot() : null; if (!root || root.querySelector('.b4-today')) return; const me = (typeof currentUser === 'function' && currentUser() || {}).name || ''; const mgr = ['owner','pm'].includes(typeof role === 'function' ? role() : ''); const ws = DB.watches.filter(w => w.status === 'open' && w.unread && (mgr || w.owner === me)); if (!ws.length) return; const hits = ws.flatMap(w => w.hits.map(h => Object.assign({w}, h))).sort((a, b) => b.at.localeCompare(a.at)).slice(0, 5); const card = document.createElement('div'); card.className = 'card b4-today'; card.innerHTML = `<div class="hd"><h3>Updates on What You Are Waiting For</h3><span class="small muted">${hits.length} from the inbox</span><span class="grow"></span><button class="btn sm" data-b4seen>Seen</button></div>${hits.map(h => `<div class="h4r"><span class="h4r-n">${fmt(h.at)}</span><span class="grow"><a href="#" data-b4open="${h.commId}">${esc(h.subject || '(no subject)')}</a> <span class="small muted">· ${esc(h.w.label)}${h.w.projectId ? ' · ' + esc((DB.projects.find(p => p.id === h.w.projectId) || {project:{name:''}}).project.name.replace(/ —.*$/, '')) : ''}</span></span></div>`).join('')}`; const bn = root.querySelector('.bn-today'); (bn || root.querySelector('.home-bar') || root).after(card); card.querySelectorAll('[data-b4open]').forEach(a => a.onclick = e => { e.preventDefault(); b4Open(a.dataset.b4open); }); card.querySelector('[data-b4seen]').onclick = () => { ws.forEach(w => { w.unread = 0; }); save(); render(); }; } catch(e){ console.error('brain4 today', e); } }; }
function b4WatchingHtml(){ b4Init(); const W = DB.watches.slice().sort((a, b) => ({open:0, closed:1, expired:2}[a.status] - {open:0, closed:1, expired:2}[b.status]) || (b.at || '').localeCompare(a.at || '')); return `<div class="small muted" style="margin-bottom:8px">Topics a meeting or a Waiting On task raised that will move by email. Matching mail is filed to the project, pinned to the meeting and the task, and shown to the owner on Today. A watch closes when its task is done or after its window.</div>${W.length ? W.map(w => { const p = DB.projects.find(x => x.id === w.projectId); return `<div class="b4-w ${w.status}"><div class="row" style="gap:8px;align-items:baseline;flex-wrap:wrap"><span class="pill ${w.status === 'open' ? 'ok' : ''}">${w.status[0].toUpperCase() + w.status.slice(1)}</span><b>${esc(w.label)}</b><span class="small muted">${p ? esc(p.project.name.replace(/ —.*$/, '')) + ' · ' : ''}${w.owner ? esc(w.owner) + ' · ' : ''}since ${fmt(w.since)} · until ${fmt(w.until)}${w.meetingId ? ' · from a meeting' : w.taskId ? ' · from a Waiting On task' : ''}</span><span class="grow"></span>${w.status === 'open' ? `<button class="btn sm ghost" data-b4stop="${w.id}">Stop Watching</button>` : ''}</div><div class="small muted">${esc(w.text)}</div>${w.hits.length ? `<div class="small" style="margin-top:4px">${w.hits.slice(-3).reverse().map(h => `<a href="#" data-b4open="${h.commId}">${esc(h.subject || '(no subject)')}</a> · ${fmt(h.at)}`).join('<br>')}</div>` : ''}</div>`; }).join('') : '<div class="empty">Nothing is being watched. A meeting that raises insurance, a permit, a quote or a claim, or a task that waits on someone, starts a watch on its own.</div>'}`; }
if (typeof renderBrain === 'function'){ const renderBrainBase_b4 = renderBrain; renderBrain = function(){ renderBrainBase_b4.apply(this, arguments); const host = document.getElementById('brain-body'); if (!host) return; const seg = host.querySelector('.seg'); if (seg && !seg.querySelector('[data-bntab="watching"]')){ const b = document.createElement('button'); b.dataset.bntab = 'watching'; const n = (DB.watches || []).filter(w => w.status === 'open' && w.unread).length; b.innerHTML = `Watching${n ? ` <span class="pill warn">${n}</span>` : ''}`; b.className = bnTab === 'watching' ? 'on' : ''; b.onclick = () => { bnTab = 'watching'; renderBrain(); }; const pl = seg.querySelector('[data-bntab="plugins"]'); pl ? seg.insertBefore(b, pl) : seg.appendChild(b); } if (bnTab === 'watching'){ if (seg){ while (seg.nextElementSibling) seg.nextElementSibling.remove(); } const d = document.createElement('div'); d.innerHTML = b4WatchingHtml(); host.appendChild(d); host.querySelectorAll('[data-b4stop]').forEach(b => b.onclick = () => { const w = DB.watches.find(x => x.id === b.dataset.b4stop); if (w){ w.status = 'closed'; w.closedAt = today(); save(); renderBrain(); } }); host.querySelectorAll('[data-b4open]').forEach(a => a.onclick = e => { e.preventDefault(); b4Open(a.dataset.b4open); }); } }; }
