  {id:'design-only', label:'Design Only', stages:[{id:'inquiry', label:'Inquiry', prob:10}, {id:'qualified', label:'Qualified', prob:25}, {id:'concept', label:'Concept Meeting', prob:45}, {id:'design', label:'Design Agreement', prob:70, required:['amount']}, {id:'proposal', label:'Proposal Out', prob:85, required:['amount','closedate']}, {id:'won', label:'Closed Won', prob:100, won:true}, {id:'lost', label:'Closed Lost', prob:0, lost:true, required:['closed_lost_reason']}]}
