  H.pipelines.sort((a, b) => { const o = ['design-build','construction-only','design-only']; const ia = o.indexOf(a.id), ib = o.indexOf(b.id); return (ia < 0 ? 9 : ia) - (ib < 0 ? 9 : ib); });
  scSelectPipe(H.pipelineId || H.pipelines[0].id); if (H.pipeline !== H.pipelines.find(p => p.id === H.pipelineId)) scSelectPipe(H.pipelines[0].id);
