  let R = L.filter(l => scTab === 'all' ? !['Unqualified','Junk'].includes(l.leadStatus || 'New') : (l.leadStatus || 'New') === scTab);
  if (scOwner) R = R.filter(l => (l.owner || 'Owner') === scOwner); if (scSource) R = R.filter(l => (l.source || '') === scSource);
