  return `<div class="ph"><div><h2>Leads</h2><div class="lead">${lead}</div></div><div class="acts"><button class="btn" id="sc-inbox">Messages</button><button class="btn primary" id="sc-newlead">New Lead</button></div></div>
  <div class="ctabs" id="sc-tabs">${tabs.map(([k, n, c]) => `<button class="${scTab === k ? 'on' : ''}" data-sctab="${k}">${n}<span class="n">${c || ''}</span></button>`).join('')}</div>
  <div class="row sc-filters"><input class="q" id="sc-q" placeholder="Search name, company, email, property…" value="${esc(scQ)}"><select id="sc-owner"><option value="">All Owners</option>${owners.map(o => `<option ${o === scOwner ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select><select id="sc-source"><option value="">All Sources</option>${sources.map(o => `<option ${o === scSource ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select><span class="grow"></span><span class="small muted">${R.length} lead${R.length === 1 ? '' : 's'}</span></div>
  ${R.length ? `<div class="sc-mlist">${R.map(l => { const st = l.leadStatus || 'New'; const last = scLastTouch(l); const lateRow = l.nextDue && l.nextDue < td; return `<div class="card sc-mcard" data-scrow="${l.id}"><div class="row"><a href="#" data-scopen="${l.id}"><b>${esc(l.name)}</b></a><span class="grow"></span><span class="pill ${SC_PILL[st] || 'neutral'}">${st}</span></div><div class="small muted">${esc(l.addr || '')}${l.buildingType ? ' · ' + esc(l.buildingType) : ''}${l.company ? ' · ' + esc(l.company) : ''}</div><div class="small">${l.email ? esc(l.email) : ''}${l.email && l.phone ? ' · ' : ''}${esc(l.phone || '')}</div><div class="small ${lateRow ? 'bad' : 'muted'}">${l.next ? `${esc(l.next)}${l.nextDue ? ` · ${fmt(l.nextDue)}` : ''}` : 'No next step'} · last touch ${last ? hbRel(last) : '—'}</div><div class="row sc-macts">${['Unqualified','Junk'].includes(st) ? `<button class="btn sm" data-screopen="${l.id}">Reopen</button>` : `<button class="btn sm primary" data-scconvert="${l.id}">Convert</button><button class="btn sm" data-scunq="${l.id}">Unqualify</button>`}</div></div>`; }).join('')}</div><div class="tw sc-leads-wrap"><table class="t sc-leads"><thead><tr><th>Name</th><th>Company</th><th>Contact</th><th>Property</th><th>Source</th><th>Status</th><th>Owner</th><th>Last Touch</th><th>Next Step</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>` : `<div class="empty">${L.length ? 'No leads match.' : 'No leads yet. Add one here, or open a message and choose Add Lead — it lands here with the message attached.'}</div>`}`;
