  const q = host.querySelector('#sc-q'); if (q) q.oninput = () => { scQ = q.value; const pos = q.selectionStart; renderScLeads(); const q2 = host.querySelector('#sc-q'); if (q2){ q2.focus(); q2.setSelectionRange(pos, pos); } };
  const ow = host.querySelector('#sc-owner'); if (ow) ow.onchange = () => { scOwner = ow.value; renderScLeads(); }; const so = host.querySelector('#sc-source'); if (so) so.onchange = () => { scSource = so.value; renderScLeads(); };
  host.querySelector('#sc-newlead').onclick = () => scLeadSheet(null); host.querySelector('#sc-inbox').onclick = () => { view = 'comms'; render(); };
  host.querySelectorAll('[data-scopen]').forEach(a => a.onclick = e => { e.preventDefault(); scOpen(a.dataset.scopen); });
  host.querySelectorAll('[data-scconvert]').forEach(b => b.onclick = () => scConvertDialog(scLead(b.dataset.scconvert)));
  host.querySelectorAll('[data-scunq]').forEach(b => b.onclick = () => scUnqualifyDialog(scLead(b.dataset.scunq), 'Unqualified'));
  host.querySelectorAll('[data-screopen]').forEach(b => b.onclick = () => scSetStatus(scLead(b.dataset.screopen), 'Open'));
